/// ZIP/対応アーカイブ、および本扱いの画像のみフォルダを読むときのページ順。
/// 一覧整理用のソート設定から独立した、Windows に近いファイル名自然順で固定する。
pub(crate) const BOOK_READING_PAGE_ORDER: crate::settings::SortOrder =
    crate::settings::SortOrder::FileName;

/// Full-resolution still images use a complete mip chain for stable minification.
/// Thumbnails, animated frames, masks, and pixel-art filters intentionally keep
/// their existing texture options.
pub(crate) const DISPLAY_IMAGE_TEXTURE_OPTIONS: egui::TextureOptions =
    egui::TextureOptions::LINEAR.with_mipmap_mode(Some(egui::TextureFilter::Linear));

fn settings_boot_problem_source(
    source: crate::settings_db::BootSource,
) -> Option<crate::settings_db::BootSource> {
    matches!(
        source,
        crate::settings_db::BootSource::IncompatibleSettings
            | crate::settings_db::BootSource::FailedFallbackDefault
    )
    .then_some(source)
}

fn folder_media_sort_order(
    fallback: crate::settings::SortOrder,
    is_compiled_book: bool,
    folders_empty: bool,
    media_are_images_only: bool,
    auto_image_folder_book_enabled: bool,
) -> crate::settings::SortOrder {
    if !is_compiled_book && folders_empty && media_are_images_only && auto_image_folder_book_enabled
    {
        BOOK_READING_PAGE_ORDER
    } else {
        fallback
    }
}

/// 一覧中の保持帯の基準位置。フルスクリーン中は凍結した一覧スクロール位置ではなく、
/// 現在ページへ追従する。フィルタ変更などで現在ページが display list にない場合だけ
/// 一覧側の位置へ戻す。
fn thumbnail_retention_anchor_position(
    visible_indices: &[usize],
    grid_visible_first: usize,
    fullscreen_idx: Option<usize>,
) -> usize {
    if visible_indices.is_empty() {
        return 0;
    }
    let grid_visible_first = grid_visible_first.min(visible_indices.len() - 1);
    fullscreen_idx
        .and_then(|idx| visible_indices.binary_search(&idx).ok())
        .unwrap_or(grid_visible_first)
}

/// 指定枚数へ保持帯を縮める。現在位置を必ず含め、従来どおり前方を約 2/3、後方を
/// 約 1/3 優先する。端では余った枠を反対側へ回す。
fn thumbnail_keep_bounds_for_count(
    desired_start: usize,
    desired_end: usize,
    anchor: usize,
    max_items: usize,
) -> (usize, usize) {
    if desired_start >= desired_end {
        return (desired_start, desired_start);
    }
    let anchor = anchor.clamp(desired_start, desired_end - 1);
    let max_items = max_items
        .max(1)
        .min(desired_end.saturating_sub(desired_start));
    let back_capacity = anchor.saturating_sub(desired_start);
    let forward_capacity = desired_end.saturating_sub(anchor);

    let mut back = (max_items / 3).min(back_capacity);
    let mut forward = max_items.saturating_sub(back).min(forward_capacity);
    let mut remaining = max_items.saturating_sub(back + forward);
    let add_back = remaining.min(back_capacity.saturating_sub(back));
    back += add_back;
    remaining -= add_back;
    forward += remaining.min(forward_capacity.saturating_sub(forward));

    (anchor - back, anchor + forward)
}

