#[cfg(windows)]
impl App {
    const EGUI_VIEWPORT_CLASS: &'static str = "Window Class";
    const DETACHED_PHYSICAL_ACTIVATION_MAX_DRAG_PX: i32 = 8;

    fn detached_window_runtime_default_linked(&self) -> bool {
        !self.detached_viewer_independent_active
    }

    fn detached_window_runtime_placement_is_usable(
        placement: crate::settings::DetachedViewerWindowPlacement,
    ) -> bool {
        placement.is_sane()
            && crate::monitor::title_bar_on_some_monitor(placement.x, placement.y, placement.w)
    }

    pub(crate) fn detached_window_runtime_placement(
        &self,
        window_id: u64,
    ) -> Option<crate::settings::DetachedViewerWindowPlacement> {
        self.detached_window_manager
            .placement(window_id)
            .filter(|placement| Self::detached_window_runtime_placement_is_usable(*placement))
    }

    pub(crate) fn set_detached_window_runtime_placement(
        &mut self,
        window_id: u64,
        placement: crate::settings::DetachedViewerWindowPlacement,
        reason: &'static str,
    ) {
        if !Self::detached_window_runtime_placement_is_usable(placement) {
            self.log_detached_image_window_debug(format!(
                "runtime_placement_rejected window_id={window_id} reason={reason} \
                 placement={placement:?}"
            ));
            return;
        }
        let default_linked = self.detached_window_runtime_default_linked();
        let previous =
            self.detached_window_manager
                .set_placement(window_id, placement, default_linked);
        self.log_detached_image_window_debug(format!(
            "runtime_placement window_id={window_id} reason={reason} \
             from={previous:?} to={placement:?}"
        ));
    }

    pub(crate) fn detached_window_seed_placement(
        &self,
        window_id: u64,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        self.detached_window_runtime_placement(window_id)
            .unwrap_or_else(|| self.detached_viewer_window_placement())
    }

    pub(crate) fn ensure_detached_window_runtime_placement(
        &mut self,
        window_id: u64,
        reason: &'static str,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        if let Some(placement) = self.detached_window_runtime_placement(window_id) {
            return placement;
        }
        let seed = self.detached_viewer_window_placement();
        self.set_detached_window_runtime_placement(window_id, seed, reason);
        seed
    }

    pub(crate) fn detached_window_runtime_trim_bbox(
        &self,
        window_id: u64,
        idx: usize,
    ) -> Option<Option<egui::Rect>> {
        let item_key = self.items.get(idx)?.perf_key();
        self.detached_window_manager
            .trim_bbox(window_id, idx, &item_key)
    }

    pub(crate) fn set_detached_window_runtime_trim_bbox(
        &mut self,
        window_id: u64,
        idx: usize,
        bbox: Option<egui::Rect>,
        reason: &'static str,
    ) {
        let Some(item_key) = self.items.get(idx).map(|item| item.perf_key()) else {
            return;
        };
        let bbox_label = Self::format_detached_trim_bbox_for_log(bbox);
        let default_linked = self.detached_window_runtime_default_linked();
        self.detached_window_manager
            .set_trim_bbox(window_id, idx, item_key, bbox, default_linked);
        self.log_detached_image_window_debug(format!(
            "detached_trim_bbox_bake window_id={window_id} idx={idx} bbox={bbox_label} \
             reason={reason}"
        ));
    }

    pub(crate) fn format_detached_trim_bbox_for_log(bbox: Option<egui::Rect>) -> String {
        match bbox {
            Some(rect) => format!(
                "({:.4},{:.4} {:.4}x{:.4})",
                rect.min.x,
                rect.min.y,
                rect.width(),
                rect.height()
            ),
            None => "none".to_string(),
        }
    }

    pub(crate) fn active_detached_runtime_placement(
        &self,
    ) -> Option<crate::settings::DetachedViewerWindowPlacement> {
        self.active_detached_hwnd_window_id()
            .and_then(|window_id| self.detached_window_runtime_placement(window_id))
    }

    pub(crate) fn active_detached_seed_placement(
        &self,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        self.active_detached_runtime_placement()
            .unwrap_or_else(|| self.detached_viewer_window_placement())
    }

    pub(crate) fn active_detached_builder_placement_latch(
        &mut self,
        refresh_latch: bool,
        reason: &'static str,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        let live = self.active_detached_seed_placement();
        let Some(window_id) = self.active_detached_hwnd_window_id() else {
            return live;
        };

        let previous = self
            .detached_window_manager
            .builder_placement_latch(window_id);
        let latch_usable = previous.is_some_and(Self::detached_window_runtime_placement_is_usable);
        let refreshed = refresh_latch || !latch_usable;
        let placement = if refreshed {
            let default_linked = self.detached_window_runtime_default_linked();
            self.detached_window_manager.set_builder_placement_latch(
                window_id,
                live,
                default_linked,
            );
            live
        } else {
            previous.unwrap_or(live)
        };

        if Self::detached_image_window_debug_enabled() {
            self.log_detached_viewport_placement_event(
                reason,
                "builder_placement_latch",
                format!(
                    "window_id={window_id} refresh={refresh_latch} refreshed={refreshed} \
                     previous={previous:?} live={live:?} latched={placement:?}"
                ),
            );
        }
        placement
    }

    pub(crate) fn refresh_detached_builder_placement_latch_for_active_entry(
        &mut self,
        window_id: u64,
        reason: &'static str,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        let live = self.ensure_detached_window_runtime_placement(window_id, reason);
        let default_linked = self.detached_window_runtime_default_linked();
        let previous = self.detached_window_manager.set_builder_placement_latch(
            window_id,
            live,
            default_linked,
        );
        if Self::detached_image_window_debug_enabled() {
            self.log_detached_viewport_placement_event(
                reason,
                "builder_placement_latch_active_entry",
                format!("window_id={window_id} previous={previous:?} live={live:?}"),
            );
        }
        live
    }

    fn detached_window_hwnd_get_raw(&self, window_id: u64) -> Option<u64> {
        self.detached_window_manager.hwnd_raw(window_id)
    }

    fn detached_window_hwnd_alive(&self, window_id: u64) -> Option<u64> {
        self.detached_window_manager.hwnd_alive(window_id)
    }

    fn detached_window_hwnd_is_alive(&self, hwnd: u64) -> bool {
        self.detached_window_manager.hwnd_is_alive(hwnd)
    }

    fn detached_window_hwnd_clear(&mut self, window_id: u64) -> Option<u64> {
        self.detached_window_manager.clear_hwnd(window_id)
    }

    fn detached_window_hwnd_clear_if_dead(&mut self, window_id: u64) -> Option<u64> {
        let cleared = self.detached_window_manager.clear_hwnd_if_dead(window_id);
        if cleared.is_some()
            && let Some(window) = self
                .detached_image_windows
                .iter_mut()
                .find(|window| window.id == window_id)
        {
            // egui が同じ ViewportId の OS window を作り直すときは、旧 HWND へ一度適用済み
            // だった placement も新 HWND へ再適用する必要がある。ParkedLive は通常の
            // parked liveness sweep の対象外なので、HWND ownership 境界で共通に戻す。
            window.initial_placement_applied = false;
        }
        cleared
    }

    fn detached_window_hwnd_set(&mut self, window_id: u64, hwnd: u64) -> Option<u64> {
        let default_linked = self.detached_window_runtime_default_linked();
        self.detached_window_manager
            .set_hwnd(window_id, hwnd, default_linked)
    }

    fn detached_window_registered_hwnds(&self) -> std::collections::HashSet<u64> {
        self.detached_window_manager.registered_hwnds()
    }

    fn select_detached_created_hwnd(
        before: &[crate::dwm_transitions::ThreadWindowSnapshotEntry],
        after: &[crate::dwm_transitions::ThreadWindowSnapshotEntry],
    ) -> DetachedWindowHwndDiff {
        let mut created = after
            .iter()
            .filter(|entry| {
                !entry.is_main
                    && entry.class_name == Self::EGUI_VIEWPORT_CLASS
                    && !before.iter().any(|old| old.hwnd_raw == entry.hwnd_raw)
            })
            .map(|entry| entry.hwnd_raw)
            .collect::<Vec<_>>();
        created.sort_unstable();
        created.dedup();
        match created.as_slice() {
            [hwnd] => DetachedWindowHwndDiff::Created(*hwnd),
            [] => DetachedWindowHwndDiff::NoChange,
            _ => DetachedWindowHwndDiff::Ambiguous(created),
        }
    }

    fn select_detached_unclaimed_hwnd(
        after: &[crate::dwm_transitions::ThreadWindowSnapshotEntry],
        claimed: &std::collections::HashSet<u64>,
    ) -> DetachedWindowHwndDiff {
        let mut unclaimed = after
            .iter()
            .filter(|entry| {
                !entry.is_main
                    && entry.class_name == Self::EGUI_VIEWPORT_CLASS
                    && !claimed.contains(&entry.hwnd_raw)
                    // 可視な実窓だけをフォールバック採用の候補にする。hidden / minimized /
                    // rect 取得不能な stale viewport が「唯一の未登録窓」として誤採用される
                    // と、host resync / focus / close が実際の detached 窓ではなく残骸 HWND
                    // へ向く (review-v2.3.0 hunt P2、BA-1/BA-4)。正規の host は表示直後の
                    // フォールバック経路なので可視のはずで、まだ不可視なら NoChange →
                    // 次フレームの再試行に任せる。created 側 (before/after 差分) は stale 窓
                    // が before に含まれるため元々安全で、生成直後の未表示フレームを
                    // 取りこぼさないようこの条件は付けない。
                    && entry.visible
                    && !entry.iconic
                    && entry.rect_ok
            })
            .map(|entry| entry.hwnd_raw)
            .collect::<Vec<_>>();
        unclaimed.sort_unstable();
        unclaimed.dedup();
        match unclaimed.as_slice() {
            [hwnd] => DetachedWindowHwndDiff::Created(*hwnd),
            [] => DetachedWindowHwndDiff::NoChange,
            _ => DetachedWindowHwndDiff::Ambiguous(unclaimed),
        }
    }

    #[cfg(windows)]
    fn begin_detached_window_hwnd_registration(&mut self, window_id: u64, reason: &'static str) {
        // HWND の欠落は OS host の生成状態であって、メディア session の意味状態ではない。
        // ParkedLive を Opening に落とすと live poll / 新メディア close routing から外れる。
        // Closing も host の再登録だけで復活させない。
        if !matches!(
            self.detached_window_state(window_id),
            Some(DetachedWindowState::ParkedLive | DetachedWindowState::Closing)
        ) {
            self.transition_detached_window_state(window_id, DetachedWindowState::Opening, reason);
        }
    }

    #[cfg(windows)]
    fn detached_window_state_for_show_label(
        &self,
        window_id: u64,
        label: &'static str,
    ) -> DetachedWindowState {
        match self.detached_window_state(window_id) {
            Some(DetachedWindowState::ParkedLive) => DetachedWindowState::ParkedLive,
            Some(DetachedWindowState::Closing) => DetachedWindowState::Closing,
            _ if label == "passive" => DetachedWindowState::Parked,
            _ => DetachedWindowState::Active,
        }
    }

    #[cfg(windows)]
    fn try_resync_detached_video_host_after_registration(&mut self, window_id: u64) {
        // Passive ParkedLive bundle はこの時点では mount されていない。別の active context
        // を見たまま try_resync を呼ぶと、その context を「対象外」と判定して pending を
        // 消費してしまう。owner bundle の poll 中、または active owner の登録時だけ即時試行し、
        // passive owner は次の poll_parked_live_detached_windows まで要求を保持する。
        if self.pending_detached_video_host_resync
            && self.active_detached_hwnd_window_id() == Some(window_id)
        {
            self.pending_detached_video_host_resync = !self.try_resync_detached_video_host();
        }
    }

    #[cfg(windows)]
    fn adopt_unclaimed_detached_window_hwnd_after_show(
        &mut self,
        window_id: u64,
        label: &'static str,
        viewport_id: egui::ViewportId,
        after: &[crate::dwm_transitions::ThreadWindowSnapshotEntry],
        old: Option<u64>,
    ) -> bool {
        let claimed = self.detached_window_registered_hwnds();
        match Self::select_detached_unclaimed_hwnd(after, &claimed) {
            DetachedWindowHwndDiff::Created(hwnd) => {
                self.detached_window_hwnd_set(window_id, hwnd);
                let state = self.detached_window_state_for_show_label(window_id, label);
                self.transition_detached_window_state(window_id, state, "hwnd_adopted_unclaimed");
                self.detached_viewer_host_generation =
                    self.detached_viewer_host_generation.saturating_add(1);
                let old_text = old
                    .map(|hwnd| format!("0x{hwnd:x}"))
                    .unwrap_or_else(|| "none".to_string());
                crate::logger::log(format!(
                    "[detached-viewer] hwnd_adopted_unclaimed hwnd=0x{hwnd:x} \
                     host_generation={} frame={} window_id={window_id} label={label} \
                     viewport={viewport_id:?} old={old_text} new_state=\"{}\"",
                    self.detached_viewer_host_generation,
                    self.frame_counter,
                    Self::win32_hwnd_debug_state(hwnd)
                ));
                self.try_resync_detached_video_host_after_registration(window_id);
                true
            }
            DetachedWindowHwndDiff::NoChange => {
                self.log_detached_image_window_debug(format!(
                    "hwnd_unclaimed_retry label={label} frame={} window_id={window_id} \
                     viewport={viewport_id:?} reason=no_unclaimed old={} \
                     after_count={} claimed_count={} host={}",
                    self.frame_counter,
                    old.map(|hwnd| format!("0x{hwnd:x}"))
                        .unwrap_or_else(|| "none".to_string()),
                    after.len(),
                    claimed.len(),
                    self.detached_viewer_host_debug_state()
                ));
                false
            }
            DetachedWindowHwndDiff::Ambiguous(candidates) => {
                self.log_detached_image_window_debug(format!(
                    "hwnd_unclaimed_retry label={label} frame={} window_id={window_id} \
                     viewport={viewport_id:?} reason=ambiguous candidates={candidates:x?} \
                     old={} after_count={} claimed_count={} host={}",
                    self.frame_counter,
                    old.map(|hwnd| format!("0x{hwnd:x}"))
                        .unwrap_or_else(|| "none".to_string()),
                    after.len(),
                    claimed.len(),
                    self.detached_viewer_host_debug_state()
                ));
                false
            }
        }
    }

    #[cfg(test)]
    pub(crate) fn set_detached_window_live_hwnds_for_test<I>(&mut self, hwnds: I)
    where
        I: IntoIterator<Item = u64>,
    {
        self.detached_window_manager.set_live_hwnds_for_test(hwnds);
    }

    pub(crate) fn transition_detached_window_state(
        &mut self,
        window_id: u64,
        new_state: DetachedWindowState,
        reason: &'static str,
    ) {
        // A passive snapshot that still owns a media player must remain ParkedLive until
        // activation or terminal close. Log only an actual lifecycle transition that violates
        // that invariant; unlike MIV_DETACHED_WINDOW_DEBUG this is intentionally always on so a
        // rare overnight/tray-restore failure survives until the next report without per-frame
        // noise. Resuming/Closing are valid handoff states even while the snapshot is still
        // present for part of the transition.
        let passive_media_owner = self
            .detached_image_windows
            .iter()
            .find(|window| window.id == window_id)
            .and_then(|window| window.paused_bundle.as_deref())
            .filter(|bundle| Self::viewer_context_bundle_contains_video(bundle))
            .map(|bundle| {
                let video_cache_entries = bundle
                    .fs_cache
                    .values()
                    .filter(|entry| matches!(entry, FsCacheEntry::Video { .. }))
                    .count();
                (bundle.fullscreen_idx, video_cache_entries)
            });
        let previous_state = self.detached_window_state(window_id);
        let default_linked = self.detached_window_runtime_default_linked();
        let transition =
            self.detached_window_manager
                .transition_state(window_id, new_state, default_linked);
        if let Some((bundle_fullscreen_idx, video_cache_entries)) = passive_media_owner
            && !matches!(
                new_state,
                DetachedWindowState::ParkedLive
                    | DetachedWindowState::Resuming
                    | DetachedWindowState::Closing
            )
        {
            crate::logger::log(format!(
                "[detached-media-invariant] passive media owner entered non-live state: \
                 window_id={window_id} from={previous_state:?} to={new_state:?} reason={reason} \
                 bundle_fullscreen_idx={bundle_fullscreen_idx:?} \
                 video_cache_entries={video_cache_entries} hwnd=0x{:x}",
                transition.hwnd
            ));
        }
        let entering_active = transition.from != DetachedWindowState::Active
            && transition.to == DetachedWindowState::Active;
        self.log_detached_image_window_debug(format!(
            "state_transition window_id={} from={:?} to={:?} \
             reason={reason} hwnd=0x{:x} linked={}",
            transition.window_id,
            transition.from,
            transition.to,
            transition.hwnd,
            transition.linked
        ));
        if entering_active {
            self.refresh_detached_builder_placement_latch_for_active_entry(
                window_id,
                "state_active_entry",
            );
        }
    }

    pub(crate) fn detached_window_state(&self, window_id: u64) -> Option<DetachedWindowState> {
        self.detached_window_manager.state(window_id)
    }

    pub(crate) fn active_detached_window_id(&self) -> Option<u64> {
        self.active_detached_session
            .map(|session| session.window_id)
    }

    pub(crate) fn active_detached_window_state(&self) -> Option<DetachedWindowState> {
        let window_id = self.active_detached_window_id()?;
        self.detached_window_state(window_id)
    }

    pub(crate) fn active_detached_window_is_closing(&self) -> bool {
        matches!(
            self.active_detached_window_state(),
            Some(DetachedWindowState::Closing)
        )
    }

    pub(crate) fn update_detached_window_runtime_flags(
        &mut self,
        window_id: u64,
        linked: bool,
        reason: &'static str,
    ) {
        let default_linked = self.detached_window_runtime_default_linked();
        let old_linked = self
            .detached_window_manager
            .set_linked(window_id, linked, default_linked);
        if old_linked != linked {
            self.log_detached_image_window_debug(format!(
                "runtime_flags window_id={window_id} linked={old_linked}->{linked} reason={reason}"
            ));
        }
    }

    #[cfg(windows)]
    pub(crate) fn queue_deferred_detached_window_activation(
        &mut self,
        window_id: u64,
        reason: &'static str,
    ) {
        let frame = self.frame_counter;
        let default_linked = self.detached_window_runtime_default_linked();
        let (was_pending, state) = self
            .detached_window_manager
            .queue_deferred_activation(window_id, default_linked);
        self.log_detached_image_window_debug(format!(
            "deferred_activate_queued frame={frame} id={window_id} reason={reason} \
             duplicate={was_pending} state={:?}",
            state
        ));
    }

    #[cfg(windows)]
    fn detached_physical_activation_dragged_too_far(
        start: Option<(i32, i32)>,
        current: Option<(i32, i32)>,
    ) -> bool {
        let (Some((sx, sy)), Some((cx, cy))) = (start, current) else {
            return false;
        };
        let dx = i64::from(cx) - i64::from(sx);
        let dy = i64::from(cy) - i64::from(sy);
        let limit = i64::from(Self::DETACHED_PHYSICAL_ACTIVATION_MAX_DRAG_PX);
        dx.saturating_mul(dx).saturating_add(dy.saturating_mul(dy)) > limit.saturating_mul(limit)
    }

    #[cfg(windows)]
    #[cfg(windows)]
    fn detached_activation_target_full_rect(
        target: DetachedActivationWatchTargetRect,
    ) -> egui::Rect {
        egui::Rect::from_min_max(
            egui::pos2(target.left as f32, target.top as f32),
            egui::pos2(target.right as f32, target.bottom as f32),
        )
    }

    #[cfg(windows)]
    pub(crate) fn detached_activation_close_button_contains(
        target: DetachedActivationWatchTargetRect,
        cursor_pos: Option<(i32, i32)>,
    ) -> bool {
        let Some((x, y)) = cursor_pos else {
            return false;
        };
        let full_rect = Self::detached_activation_target_full_rect(target);
        let rect = match target.close_hit_test {
            DetachedActivationCloseHitTest::ImageBar => {
                crate::ui_fullscreen::detached_image_window_bar_close_button_rect(full_rect)
            }
            DetachedActivationCloseHitTest::MusicChrome => {
                match Self::parked_live_music_close_slot_rect(
                    full_rect,
                    crate::ui_helpers::panel_edge_trigger_px(full_rect.width()),
                ) {
                    Some(rect) => rect,
                    None => return false,
                }
            }
        };
        (x as f32) >= rect.left()
            && (x as f32) < rect.right()
            && (y as f32) >= rect.top()
            && (y as f32) < rect.bottom()
    }

    #[cfg(windows)]
    fn detached_activation_native_close_hit(
        target: DetachedActivationWatchTargetRect,
        sample: DetachedActivationWatchSample,
    ) -> bool {
        sample.native_close_hit_hwnd != 0 && sample.native_close_hit_hwnd == target.hwnd
    }

    #[cfg(windows)]
    fn detached_activation_close_hit(
        target: DetachedActivationWatchTargetRect,
        sample: DetachedActivationWatchSample,
    ) -> bool {
        Self::detached_activation_native_close_hit(target, sample)
            || Self::detached_activation_close_button_contains(target, sample.cursor_pos)
    }

    #[cfg(windows)]
    fn detached_activation_title_bar_contains(
        target: DetachedActivationWatchTargetRect,
        cursor_pos: Option<(i32, i32)>,
    ) -> bool {
        let Some((x, y)) = cursor_pos else {
            return false;
        };
        x >= target.left
            && x < target.right
            && y >= target.top
            && (y as f32) < target.top as f32 + crate::ui_fullscreen::TOP_BAR_HEIGHT
    }

    #[cfg(windows)]
    fn detached_activation_cursor_root_allows_repair(
        targets: &[DetachedActivationWatchTargetRect],
        sample: DetachedActivationWatchSample,
        main_hwnd: u64,
        claimed_hwnds: &[u64],
    ) -> bool {
        sample.cursor_root_hwnd != 0
            && sample.cursor_root_hwnd != main_hwnd
            && !claimed_hwnds.contains(&sample.cursor_root_hwnd)
            && !targets
                .iter()
                .any(|target| target.hwnd == sample.cursor_root_hwnd)
    }

    #[cfg(windows)]
    fn detached_activation_candidate_for_down_edge(
        targets: &[DetachedActivationWatchTargetRect],
        sample: DetachedActivationWatchSample,
        main_hwnd: u64,
        claimed_hwnds: &[u64],
    ) -> Option<DetachedActivationClickCandidate> {
        // 直接ヒットは「OS が報告したクリック先 (cursor_root_hwnd) と一致する target」を
        // 最優先で探す。targets のリスト順は z-order ではないため、矩形あたり判定を
        // リスト先頭から行うと、重なった parked 窓で背面窓が前面窓へのクリックを吸い、
        // hwnd 不一致でクリックが丸ごと棄却される (findings-19 実機バグ: 重なった
        // Page 107 窓がクリック不能)。
        if let Some(target) = Self::detached_activation_target_for_cursor_root(
            targets,
            sample.cursor_pos,
            sample.cursor_root_hwnd,
        ) {
            let intent = if Self::detached_activation_close_hit(target, sample) {
                DetachedActivationClickIntent::Close
            } else {
                if !target.eligible {
                    return None;
                }
                DetachedActivationClickIntent::Activate
            };
            return Some(DetachedActivationClickCandidate {
                window_id: target.window_id,
                hwnd: target.hwnd,
                repair_hwnd: None,
                start_screen_pos: sample.cursor_pos,
                drag_sensitive: Self::detached_activation_title_bar_contains(
                    target,
                    sample.cursor_pos,
                ),
                intent,
                moved_too_far: false,
            });
        }
        let target =
            Self::detached_activation_target_containing_cursor(targets, sample.cursor_pos)?;
        if !Self::detached_activation_cursor_root_allows_repair(
            targets,
            sample,
            main_hwnd,
            claimed_hwnds,
        ) {
            return None;
        }
        let intent = if Self::detached_activation_close_hit(target, sample) {
            DetachedActivationClickIntent::Close
        } else {
            if !target.eligible {
                return None;
            }
            DetachedActivationClickIntent::Activate
        };
        Some(DetachedActivationClickCandidate {
            window_id: target.window_id,
            hwnd: sample.cursor_root_hwnd,
            repair_hwnd: (intent == DetachedActivationClickIntent::Activate)
                .then_some(sample.cursor_root_hwnd),
            start_screen_pos: sample.cursor_pos,
            drag_sensitive: Self::detached_activation_title_bar_contains(target, sample.cursor_pos),
            intent,
            moved_too_far: false,
        })
    }

    #[cfg(windows)]
    fn detached_activation_target_containing_cursor(
        targets: &[DetachedActivationWatchTargetRect],
        cursor_pos: Option<(i32, i32)>,
    ) -> Option<DetachedActivationWatchTargetRect> {
        let (x, y) = cursor_pos?;
        targets.iter().copied().find(|target| {
            x >= target.left && x < target.right && y >= target.top && y < target.bottom
        })
    }

    /// cursor_root_hwnd (OS の WindowFromPoint root) と一致する target を返す。
    /// 矩形あたり判定だけの `detached_activation_target_containing_cursor` と違い、
    /// parked 窓が重なっていても実際にクリックされた窓を一意に特定できる。
    /// 矩形包含も併せて確認するのは、close ボタン / タイトルバー判定が
    /// target の矩形を基準にしているため。hwnd 一致で矩形だけ外れたクリックは、
    /// repair 側も targets 内 hwnd を除外するため結局棄却される (= 従来と同じ保守挙動)。
    #[cfg(windows)]
    fn detached_activation_target_for_cursor_root(
        targets: &[DetachedActivationWatchTargetRect],
        cursor_pos: Option<(i32, i32)>,
        cursor_root_hwnd: u64,
    ) -> Option<DetachedActivationWatchTargetRect> {
        if cursor_root_hwnd == 0 {
            return None;
        }
        let (x, y) = cursor_pos?;
        targets.iter().copied().find(|target| {
            target.hwnd == cursor_root_hwnd
                && x >= target.left
                && x < target.right
                && y >= target.top
                && y < target.bottom
        })
    }

    #[cfg(windows)]
    fn detached_activation_down_rejection_diagnostic(
        targets: &[DetachedActivationWatchTargetRect],
        sample: DetachedActivationWatchSample,
        main_hwnd: u64,
        claimed_hwnds: &[u64],
    ) -> Option<DetachedActivationWatchDiagnostic> {
        let target =
            Self::detached_activation_target_containing_cursor(targets, sample.cursor_pos)?;
        let reason = if !target.eligible {
            "down_ineligible"
        } else if sample.cursor_root_hwnd == 0 {
            "down_no_window_from_point"
        } else if sample.cursor_root_hwnd == main_hwnd {
            "down_main_window"
        } else if claimed_hwnds.contains(&sample.cursor_root_hwnd)
            || targets
                .iter()
                .any(|candidate| candidate.hwnd == sample.cursor_root_hwnd)
        {
            "down_claimed_window"
        } else if sample.cursor_root_hwnd != target.hwnd {
            "down_window_from_point_mismatch"
        } else {
            "down_unknown"
        };
        Some(DetachedActivationWatchDiagnostic {
            reason,
            foreground_hwnd: sample.foreground_hwnd,
            cursor_root_hwnd: sample.cursor_root_hwnd,
            cursor_pos: sample.cursor_pos,
            target_window_id: Some(target.window_id),
            target_hwnd: Some(target.hwnd),
        })
    }

    #[cfg(windows)]
    fn detached_activation_up_rejection_diagnostic(
        reason: &'static str,
        click: DetachedActivationClickCandidate,
        sample: DetachedActivationWatchSample,
    ) -> DetachedActivationWatchDiagnostic {
        DetachedActivationWatchDiagnostic {
            reason,
            foreground_hwnd: sample.foreground_hwnd,
            cursor_root_hwnd: sample.cursor_root_hwnd,
            cursor_pos: sample.cursor_pos,
            target_window_id: Some(click.window_id),
            target_hwnd: Some(click.hwnd),
        }
    }

    #[cfg(all(windows, test))]
    pub(crate) fn detached_activation_watch_step_result(
        state: &mut DetachedActivationWatchState,
        sample: DetachedActivationWatchSample,
        targets: &[DetachedActivationWatchTargetRect],
    ) -> DetachedActivationWatchStepResult {
        Self::detached_activation_watch_step_result_with_context(state, sample, targets, 0, &[])
    }

    #[cfg(windows)]
    pub(crate) fn detached_activation_watch_step_result_with_context(
        state: &mut DetachedActivationWatchState,
        sample: DetachedActivationWatchSample,
        targets: &[DetachedActivationWatchTargetRect],
        main_hwnd: u64,
        claimed_hwnds: &[u64],
    ) -> DetachedActivationWatchStepResult {
        if targets.is_empty() {
            *state = DetachedActivationWatchState::default();
            return DetachedActivationWatchStepResult::default();
        }

        let down_edge = sample.left_button_down && !state.left_button_was_down;
        let up_edge = !sample.left_button_down && state.left_button_was_down;
        let mut diagnostic = None;

        if down_edge {
            state.active_click = Self::detached_activation_candidate_for_down_edge(
                targets,
                sample,
                main_hwnd,
                claimed_hwnds,
            );
            if state.active_click.is_none() {
                diagnostic = Self::detached_activation_down_rejection_diagnostic(
                    targets,
                    sample,
                    main_hwnd,
                    claimed_hwnds,
                );
            }
        } else if sample.left_button_down
            && let Some(click) = state.active_click.as_mut()
            && !click.moved_too_far
            && click.drag_sensitive
            && Self::detached_physical_activation_dragged_too_far(
                click.start_screen_pos,
                sample.cursor_pos,
            )
        {
            click.moved_too_far = true;
        }

        let mut activate = None;
        let mut close = None;
        if up_edge && let Some(click) = state.active_click.take() {
            let target = targets
                .iter()
                .copied()
                .find(|target| target.window_id == click.window_id);
            let target_still_exists = target.is_some();
            let dragged = click.moved_too_far
                || (click.drag_sensitive
                    && Self::detached_physical_activation_dragged_too_far(
                        click.start_screen_pos,
                        sample.cursor_pos,
                    ));
            if !target_still_exists {
                diagnostic = Some(Self::detached_activation_up_rejection_diagnostic(
                    "up_target_gone",
                    click,
                    sample,
                ));
            } else if click.intent == DetachedActivationClickIntent::Close {
                if target.is_some_and(|target| Self::detached_activation_close_hit(target, sample))
                {
                    close = Some(DetachedCloseRequest {
                        window_id: click.window_id,
                    });
                } else {
                    diagnostic = Some(Self::detached_activation_up_rejection_diagnostic(
                        "up_close_outside",
                        click,
                        sample,
                    ));
                }
            } else if dragged {
                diagnostic = Some(Self::detached_activation_up_rejection_diagnostic(
                    "up_dragged",
                    click,
                    sample,
                ));
            } else if sample.foreground_hwnd != click.hwnd {
                diagnostic = Some(Self::detached_activation_up_rejection_diagnostic(
                    "up_foreground_mismatch",
                    click,
                    sample,
                ));
            } else {
                activate = Some(DetachedActivationRequest {
                    window_id: click.window_id,
                    repair_hwnd: click.repair_hwnd,
                });
            }
        }

        state.left_button_was_down = sample.left_button_down;
        DetachedActivationWatchStepResult {
            activation: activate,
            close,
            diagnostic,
        }
    }

    #[cfg(all(windows, test))]
    pub(crate) fn detached_activation_watch_step(
        state: &mut DetachedActivationWatchState,
        sample: DetachedActivationWatchSample,
        targets: &[DetachedActivationWatchTargetRect],
    ) -> Option<u64> {
        Self::detached_activation_watch_step_result(state, sample, targets)
            .activation
            .map(|request| request.window_id)
    }

    #[cfg(windows)]
    fn detached_hwnd_is_unclaimed_egui_viewport_for_window(
        &self,
        window_id: u64,
        hwnd: u64,
    ) -> bool {
        if self.detached_window_hwnd_alive(window_id).is_some() {
            return false;
        }
        if hwnd == 0 {
            return false;
        }
        if !self.detached_window_hwnd_is_alive(hwnd) {
            return false;
        }
        if self
            .detached_window_manager
            .hwnd_claimed_by_other(window_id, hwnd)
            .is_some()
        {
            return false;
        }
        let Some(main_hwnd) = self.main_hwnd else {
            return false;
        };
        let windows = crate::dwm_transitions::thread_window_snapshot(
            windows::Win32::Foundation::HWND(main_hwnd as *mut _),
        );
        self.detached_hwnd_is_unclaimed_egui_viewport_for_window_in_snapshot(
            window_id, hwnd, &windows,
        )
    }

    #[cfg(windows)]
    fn detached_hwnd_is_unclaimed_egui_viewport_for_window_in_snapshot(
        &self,
        window_id: u64,
        hwnd: u64,
        windows: &[crate::dwm_transitions::ThreadWindowSnapshotEntry],
    ) -> bool {
        if self.detached_window_hwnd_alive(window_id).is_some() {
            return false;
        }
        if hwnd == 0 {
            return false;
        }
        if !self.detached_window_hwnd_is_alive(hwnd) {
            return false;
        }
        if self
            .detached_window_manager
            .hwnd_claimed_by_other(window_id, hwnd)
            .is_some()
        {
            return false;
        }
        windows.iter().any(|entry| {
            entry.hwnd_raw == hwnd
                && !entry.is_main
                && entry.class_name == Self::EGUI_VIEWPORT_CLASS
        })
    }

    #[cfg(windows)]
    fn repair_detached_window_hwnd_from_watcher(&mut self, window_id: u64, hwnd: u64) -> bool {
        if !self.detached_hwnd_is_unclaimed_egui_viewport_for_window(window_id, hwnd) {
            return false;
        }
        self.repair_detached_window_hwnd_from_watcher_unchecked(window_id, hwnd)
    }

    #[cfg(windows)]
    fn repair_detached_window_hwnd_from_watcher_unchecked(
        &mut self,
        window_id: u64,
        hwnd: u64,
    ) -> bool {
        let previous = self.detached_window_hwnd_set(window_id, hwnd);
        let state = self.detached_window_state_for_show_label(window_id, "passive");
        self.transition_detached_window_state(window_id, state, "watcher_repair_hwnd");
        self.detached_viewer_host_generation =
            self.detached_viewer_host_generation.saturating_add(1);
        crate::logger::log(format!(
            "[detached-viewer] hwnd_adopted_watcher hwnd=0x{hwnd:x} \
             host_generation={} frame={} window_id={window_id} old={} new_state=\"{}\"",
            self.detached_viewer_host_generation,
            self.frame_counter,
            previous
                .map(|old| format!("0x{old:x}"))
                .unwrap_or_else(|| "none".to_string()),
            Self::win32_hwnd_debug_state(hwnd)
        ));
        self.try_resync_detached_video_host_after_registration(window_id);
        true
    }

    #[cfg(all(windows, test))]
    fn repair_detached_window_hwnd_from_watcher_with_snapshot(
        &mut self,
        window_id: u64,
        hwnd: u64,
        windows: &[crate::dwm_transitions::ThreadWindowSnapshotEntry],
    ) -> bool {
        if !self.detached_hwnd_is_unclaimed_egui_viewport_for_window_in_snapshot(
            window_id, hwnd, windows,
        ) {
            return false;
        }
        self.repair_detached_window_hwnd_from_watcher_unchecked(window_id, hwnd)
    }

    #[cfg(windows)]
    fn deferred_detached_activation_watch_targets(&self) -> Vec<DetachedActivationWatchTarget> {
        self.detached_image_windows
            .iter()
            .filter(|window| window.can_activate())
            .filter_map(|window| {
                let runtime = self.detached_window_manager.runtime(window.id)?;
                if runtime.state != DetachedWindowState::Parked {
                    return None;
                }
                let hwnd = self.detached_window_hwnd_alive_for_window_id(window.id)?;
                let close_hit_test = if self
                    .parked_live_music_window_info_for_window_id(window.id)
                    .is_some()
                {
                    DetachedActivationCloseHitTest::MusicChrome
                } else {
                    DetachedActivationCloseHitTest::ImageBar
                };
                Some(DetachedActivationWatchTarget {
                    window_id: window.id,
                    hwnd,
                    eligible: self.frame_counter >= window.activation_ready_frame,
                    close_hit_test,
                })
            })
            .collect()
    }

    #[cfg(windows)]
    pub(crate) fn refresh_parked_detached_window_hwnd_liveness(&mut self) {
        let ids = self
            .detached_image_windows
            .iter()
            .filter(|window| {
                self.detached_window_state(window.id) == Some(DetachedWindowState::Parked)
            })
            .filter_map(|window| {
                let hwnd = self.detached_window_hwnd_raw_for_window_id(window.id);
                (hwnd != 0 && !self.detached_window_hwnd_is_alive(hwnd))
                    .then_some((window.id, hwnd))
            })
            .collect::<Vec<_>>();
        for (window_id, hwnd) in ids {
            let cleared = self.clear_detached_window_hwnd_for_window_id(window_id);
            self.transition_detached_window_state(
                window_id,
                DetachedWindowState::Opening,
                "parked_hwnd_liveness",
            );
            self.log_detached_image_window_debug(format!(
                "parked_hwnd_liveness_clear window_id={window_id} hwnd=0x{hwnd:x} \
                 cleared={} frame={}",
                cleared.is_some(),
                self.frame_counter
            ));
        }
    }

    #[cfg(windows)]
    pub(crate) fn sync_deferred_detached_activation_watcher(&self, ctx: &egui::Context) {
        self.detached_window_manager
            .update_activation_watch_targets(
                self.deferred_detached_activation_watch_targets(),
                self.main_hwnd
                    .and_then(|hwnd| u64::try_from(hwnd).ok())
                    .unwrap_or(0),
                ctx,
            );
    }

    #[cfg(windows)]
    pub(crate) fn drain_deferred_detached_activation_watcher(&mut self, ctx: &egui::Context) {
        for diagnostic in self.detached_window_manager.drain_watch_diagnostics() {
            let cursor = diagnostic
                .cursor_pos
                .map(|(x, y)| format!("({x},{y})"))
                .unwrap_or_else(|| "none".to_string());
            let target_id = diagnostic
                .target_window_id
                .map(|id| id.to_string())
                .unwrap_or_else(|| "none".to_string());
            let target_hwnd = diagnostic
                .target_hwnd
                .map(|hwnd| format!("0x{hwnd:x}"))
                .unwrap_or_else(|| "none".to_string());
            self.log_detached_image_window_debug(format!(
                "deferred_activate_watcher_rejected reason={} foreground=0x{:x} \
                 cursor_root=0x{:x} cursor={} target_id={} target_hwnd={} frame={}",
                diagnostic.reason,
                diagnostic.foreground_hwnd,
                diagnostic.cursor_root_hwnd,
                cursor,
                target_id,
                target_hwnd,
                self.frame_counter
            ));
        }
        let close_ids = self
            .detached_window_manager
            .drain_close_requests()
            .into_iter()
            .map(|request| request.window_id)
            .collect::<Vec<_>>();
        if !close_ids.is_empty() {
            self.close_detached_image_windows_by_ids(
                ctx,
                &close_ids,
                &close_ids,
                "watcher_passive_close",
                None,
            );
        }
        for request in self.detached_window_manager.drain_activation_requests() {
            let id = request.window_id;
            if let Some(repair_hwnd) = request.repair_hwnd
                && !self.repair_detached_window_hwnd_from_watcher(id, repair_hwnd)
            {
                let known_hwnd = self.detached_window_hwnd_raw_for_window_id(id);
                let known_state = self.detached_window_state(id);
                let claimed_by = self
                    .detached_window_manager
                    .hwnd_claimed_by_other(id, repair_hwnd);
                self.log_detached_image_window_debug(format!(
                    "deferred_activate_watcher_dropped id={id} reason=repair_failed \
                     observed_hwnd=0x{repair_hwnd:x} observed_state=\"{}\" \
                     known_hwnd=0x{known_hwnd:x} known_state={known_state:?} \
                     known_hwnd_state=\"{}\" claimed_by={claimed_by:?} frame={}",
                    Self::win32_hwnd_debug_state(repair_hwnd),
                    Self::win32_hwnd_debug_state(known_hwnd),
                    self.frame_counter
                ));
                continue;
            }
            let can_activate = self.detached_image_windows.iter().any(|window| {
                window.id == id
                    && window.can_activate()
                    && self.detached_window_state(id) == Some(DetachedWindowState::Parked)
            });
            if can_activate {
                self.queue_deferred_detached_window_activation(id, "watcher_left_release");
                ctx.request_repaint();
            } else {
                self.log_detached_image_window_debug(format!(
                    "deferred_activate_watcher_dropped id={id} reason=no_reopen_route \
                     frame={}",
                    self.frame_counter
                ));
            }
        }
    }

    #[cfg(all(windows, test))]
    pub(crate) fn detached_window_deferred_activation_pending(&self, window_id: u64) -> bool {
        self.detached_window_manager
            .deferred_activation_pending(window_id)
    }

    #[cfg(windows)]
    fn take_pending_deferred_detached_window_activation(&mut self) -> Option<u64> {
        self.detached_window_manager
            .take_pending_deferred_activation()
    }

    #[cfg(windows)]
    pub(crate) fn commit_pending_deferred_detached_window_activation(
        &mut self,
        ctx: &egui::Context,
    ) -> bool {
        let Some(id) = self.take_pending_deferred_detached_window_activation() else {
            return false;
        };
        let frame = self.frame_counter;
        self.log_detached_image_window_debug(format!(
            "deferred_activate_commit frame={frame} id={id} before_active_dispatch=true \
             passive_windows={} active_context={}",
            self.detached_image_windows.len(),
            self.active_detached_viewer_context_present()
        ));
        if self.activate_detached_image_window_snapshot(ctx, id) {
            self.log_detached_image_window_debug(format!(
                "deferred_activate_commit_succeeded frame={frame} id={id} \
                 passive_windows={} active_context={} session={:?}",
                self.detached_image_windows.len(),
                self.active_detached_viewer_context_present(),
                self.active_detached_session
            ));
            true
        } else {
            self.log_detached_image_window_debug(format!(
                "deferred_activate_commit_failed frame={frame} id={id} \
                 passive_windows={} active_context={}",
                self.detached_image_windows.len(),
                self.active_detached_viewer_context_present()
            ));
            false
        }
    }

    pub(crate) fn remove_detached_window_runtime(
        &mut self,
        window_id: u64,
        reason: &'static str,
    ) -> Option<DetachedWindowRuntime> {
        self.discard_parked_native_video_pending_for_window(window_id, reason);
        self.cancel_media_navigation_pending_for_owner(Some(window_id), reason);
        let runtime = self.detached_window_manager.remove(window_id);
        if let Some(runtime) = runtime.as_ref() {
            if let Some(placement) = runtime
                .placement
                .filter(|placement| Self::detached_window_runtime_placement_is_usable(*placement))
            {
                self.settings.detached_viewer_window_placement = Some(placement);
                self.log_detached_image_window_debug(format!(
                    "runtime_placement_persisted window_id={} reason={reason} \
                     placement={placement:?}",
                    runtime.window_id
                ));
            }
            if runtime.state != DetachedWindowState::Closing {
                self.log_detached_image_window_debug(format!(
                    "state_transition_unexpected window_id={} \
                     from={:?} to=Removed reason={reason} hwnd=0x{:x} linked={} \
                     placement={:?}",
                    runtime.window_id,
                    runtime.state,
                    runtime.hwnd,
                    runtime.linked,
                    runtime.placement
                ));
            } else {
                self.log_detached_image_window_debug(format!(
                    "state_transition window_id={} from=Closing to=Removed \
                     reason={reason} hwnd=0x{:x} linked={} placement={:?}",
                    runtime.window_id, runtime.hwnd, runtime.linked, runtime.placement
                ));
            }
        }
        runtime
    }
}

#[cfg(windows)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ViewerContextDescriptor {
    Pdf {
        path: PathBuf,
        page_num: Option<u32>,
    },
    Zip {
        path: PathBuf,
        entry_name: Option<String>,
        archive_source_override: Option<PathBuf>,
    },
    /// A directory-backed image book (plain image folder or compiled book root).
    /// Unlike `Image`, this descriptor mounts the directory itself as the reader context.
    BookFolder { path: PathBuf },
    /// 通常画像。parked still の再オープン**フォールバック専用** (findings-19):
    /// 同期スタンプが main の現行 items で解決できないとき、親フォルダを窓内
    /// コンテキストとして読み込んでこの画像を開き直す。グリッドからの open
    /// ルーティング (`detached_viewer_context_descriptor_for_idx`) には使わない。
    Image { path: PathBuf },
}

/// A detached book context is created only after the source ownership is known.
///
/// Grid `Folder` tiles use `ScannedFolder`: the main context owns the asynchronous
/// classification request, and only a confirmed image book crosses into a detached
/// context. Reopen descriptors still use `Descriptor` and perform their own scan.
#[cfg(windows)]
enum DetachedBookContextStart {
    Descriptor(ViewerContextDescriptor),
    ScannedFolder { path: PathBuf, scan: ScannedDir },
}

#[cfg(windows)]
enum DetachedGridItemOpenPlan {
    /// The directory has not been enumerated yet, so it must remain main-owned until
    /// the worker proves that it is an image book.
    FolderCandidate { path: PathBuf },
    /// ZIP/PDF and explicit leaf sources already have an unambiguous detached owner.
    Descriptor(ViewerContextDescriptor),
}

#[cfg(windows)]
struct ActiveDetachedViewerContext {
    bundle: ViewerContextBundle,
}

/// アクティブ detached viewer セッションの再オープン経路の種別 (将来拡張用)。
#[cfg(windows)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum DetachedSource {
    Image,
    Video,
    Audio,
    Book,
}

/// 「この detached 窓を生かす意思」を表す単一の明示状態。
/// 詳細は docs/detached-viewer-keepalive-design.md §3.1 / §3.7。
/// - session が存在し、対応する `DetachedWindowRuntime.state != Closing` の間だけ
///   keep-alive (毎フレーム描画) する。
/// - close は「真にセッションを畳む」明示経路でのみ `closing=true` → teardown 後に `None`。
/// - folder-nav reopen / PDF/ZIP 列挙待ち / context swap では据え置き (close_fullscreen で
///   推測クリアしない)。
#[cfg(windows)]
#[derive(Clone, Copy, Debug)]
pub(crate) struct ActiveDetachedSession {
    pub(crate) window_id: u64,
    pub(crate) source: DetachedSource,
}

#[cfg(windows)]
#[derive(Clone, Debug)]
pub(crate) struct ParkedLiveMusicWindowInfo {
    pub(crate) fs_idx: usize,
    pub(crate) title: String,
    pub(crate) position_secs: f64,
    pub(crate) duration_secs: f64,
    pub(crate) playing: bool,
    pub(crate) video_audio_mode: bool,
    pub(crate) playback_speed: f64,
    pub(crate) volume: f64,
    pub(crate) muted: bool,
    pub(crate) loop_mode: crate::settings::VideoLoopMode,
    pub(crate) continuous_mode: crate::video::VideoContinuousMode,
    pub(crate) row_secs: f64,
    pub(crate) normalize_ui_state: crate::video::normalize_types::NormalizeUiState,
    pub(crate) bookmark_secs: Vec<f64>,
    pub(crate) bookmarks_loaded: bool,
}

/// ブックマーク一覧から viewer を開く直前のグリッド状態。
///
/// 一覧は viewer を閉じたときに DB から非同期で再構築されるため、単なる index では
/// 選択とスクロール位置を復元できない。安定 ID の並びが同じなら pixel offset をそのまま
/// 復元し、並びが変わった場合は `opened_key` を可視範囲へ戻すために保持する。
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct BookmarkViewReturnGridState {
    pub(crate) row_keys: Vec<(u8, i64)>,
    pub(crate) selected_key: Option<(u8, i64)>,
    pub(crate) opened_key: (u8, i64),
    pub(crate) scroll_offset_y: f32,
}

impl BookmarkViewReturnGridState {
    fn capture(
        rows: &[crate::bookmark_browser::BookmarkBrowserRow],
        selected: Option<usize>,
        opened_key: (u8, i64),
        scroll_offset_y: f32,
    ) -> Self {
        Self {
            row_keys: rows
                .iter()
                .map(crate::bookmark_browser::BookmarkBrowserRow::stable_key)
                .collect(),
            selected_key: selected
                .and_then(|idx| rows.get(idx))
                .map(crate::bookmark_browser::BookmarkBrowserRow::stable_key),
            opened_key,
            scroll_offset_y,
        }
    }
}

/// Ownership state for a viewer opened from the bookmark grid.
///
/// The old representation used two independent `Option`s and treated a
/// missing grid snapshot as an implicit "detached" marker. That allowed media
/// and book requests to disagree about which context owned the grid. These
/// variants make every valid transition explicit:
///
/// - `Opening`: the origin context owns the bookmark grid while a viewer is
///   open (embedded or in another context).
/// - `Restoring`: the viewer closed and the next bookmark read-model build
///   should restore the captured grid position.
/// - `Detached`: this mounted viewer context is separate from the origin grid.
#[derive(Clone, Debug, PartialEq)]
pub(crate) enum BookmarkViewState {
    Opening {
        target: crate::bookmark_browser::BookmarkViewReturnTarget,
        grid: BookmarkViewReturnGridState,
    },
    Restoring {
        grid: BookmarkViewReturnGridState,
    },
    Detached {
        target: crate::bookmark_browser::BookmarkViewReturnTarget,
    },
}

impl BookmarkViewState {
    pub(crate) fn target(&self) -> Option<&crate::bookmark_browser::BookmarkViewReturnTarget> {
        match self {
            Self::Opening { target, .. } | Self::Detached { target } => Some(target),
            Self::Restoring { .. } => None,
        }
    }

    fn origin_grid_mut(&mut self) -> Option<&mut BookmarkViewReturnGridState> {
        match self {
            Self::Opening { grid, .. } | Self::Restoring { grid } => Some(grid),
            Self::Detached { .. } => None,
        }
    }
}

/// このプロセスで path-keyed rating DB に適用した最新値。
///
/// DB は main / detached / parked context で共有されるため、idx cache と違ってこの台帳は
/// context bundle に入れない。非同期 XMP hydration は開始時世代と現在世代を比較し、後から
/// 行われたユーザー操作を古い読み取り結果で上書きしない。
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct RatingSessionWrite {
    generation: u64,
    stars: u8,
    explicit_user: bool,
}

#[derive(Default)]
struct MetadataImportRefreshIndex {
    items_generation: u64,
    next_item: usize,
    complete: bool,
    affected: bool,
    collect_legacy_seed_paths: bool,
    items: Vec<metadata_import_refresh::ItemKey>,
    legacy_seed_paths: Vec<PathBuf>,
    current_rating_key: Option<String>,
    folder_pin_paths: Vec<PathBuf>,
    folder_pin_aliases: Vec<(String, String)>,
}

fn metadata_import_context_path_is_affected(
    path: &Path,
    import_root: &Path,
    recursive: bool,
) -> bool {
    let key = crate::path_key::normalize_keep_drive(path);
    let root = crate::path_key::normalize_keep_drive(import_root);
    if key == root {
        return true;
    }
    // import root自身のrating / 代表サムネpinは、親フォルダcontextのroot tileにも現れる。
    if import_root
        .parent()
        .is_some_and(|parent| crate::path_key::normalize_keep_drive(parent) == key)
    {
        return true;
    }
    if recursive {
        return key
            .strip_prefix(&root)
            .is_some_and(|suffix| suffix.starts_with('/'));
    }
    path.parent()
        .is_some_and(|parent| crate::path_key::normalize_keep_drive(parent) == root)
}

struct FolderPinLookupTarget {
    path: PathBuf,
    /// `ZipDir` cellのliteral keyからDB保存先のeffective keyへのalias。
    alias: Option<(String, String)>,
}

