fn run_local_adjust_render(
    key: LocalAdjustResultKey,
    source: Arc<egui::ColorImage>,
    layers: Vec<local_adjust_core::LocalAdjustmentLayer>,
    cancel: Arc<AtomicBool>,
) -> LocalAdjustRenderResult {
    if cancel.load(Ordering::Relaxed) {
        return LocalAdjustRenderResult::Cancelled;
    }
    let [width, height] = source.size;
    let rgba = crate::capture::color_image_to_rgba(&source);
    let src = local_adjust_core::RgbaImageRef {
        width,
        height,
        pixels: &rgba,
    };
    match local_adjust_core::apply_layers_with_progress(src, &layers, Some(&cancel), |_| {}) {
        Ok(out) => {
            if cancel.load(Ordering::Relaxed) {
                return LocalAdjustRenderResult::Cancelled;
            }
            LocalAdjustRenderResult::Ready {
                key,
                image: egui::ColorImage::from_rgba_unmultiplied(
                    [out.width, out.height],
                    &out.pixels,
                ),
            }
        }
        Err(local_adjust_core::LocalAdjustError::Cancelled) => LocalAdjustRenderResult::Cancelled,
        Err(err) => LocalAdjustRenderResult::Failed {
            key,
            error: err.to_string(),
        },
    }
}

enum LocalMaterializeLayers {
    Memory(Vec<local_adjust_core::LocalAdjustmentLayer>),
    Database { path: PathBuf, page_key: String },
}

enum ConcealMaterializeMask {
    Memory {
        bitmap: Vec<bool>,
        shapes: Vec<crate::mask_db::Shape>,
        size: [usize; 2],
    },
    Database {
        path: PathBuf,
        page_key: String,
    },
}

fn emit_edit_materialize_ms(
    kind: &'static str,
    stage: &'static str,
    key: Option<&str>,
    seq: u64,
    t0: std::time::Instant,
) {
    if !crate::perf::is_enabled() {
        return;
    }
    crate::perf::event(
        "edit_materialize",
        kind,
        key,
        seq,
        &[
            ("stage", serde_json::Value::from(stage)),
            (
                "ms",
                serde_json::Value::from(t0.elapsed().as_secs_f64() * 1000.0),
            ),
        ],
    );
}

fn run_local_materialize(
    request: EditMaterializeRequest,
    source: Arc<egui::ColorImage>,
    layers_source: LocalMaterializeLayers,
    cancel: Arc<AtomicBool>,
) -> EditMaterializeResult {
    let perf_key = match &layers_source {
        LocalMaterializeLayers::Database { page_key, .. } => Some(page_key.clone()),
        LocalMaterializeLayers::Memory(_) => None,
    };
    if cancel.load(Ordering::Relaxed) {
        return EditMaterializeResult::Cancelled { request };
    }
    let mut layers = match layers_source {
        LocalMaterializeLayers::Memory(layers) => layers,
        LocalMaterializeLayers::Database { path, page_key } => {
            let db_t0 = std::time::Instant::now();
            let db = match crate::local_adjust_db::LocalAdjustDb::open_readonly(&path) {
                Ok(db) => db,
                Err(err) => {
                    return EditMaterializeResult::Failed {
                        request,
                        error: format!("local adjust DB open failed: {err}"),
                    };
                }
            };
            let json = db.get_layers_json(&page_key);
            emit_edit_materialize_ms(
                "db_read",
                "local",
                Some(&page_key),
                request.input_seq,
                db_t0,
            );
            let Some(json) = json else {
                return EditMaterializeResult::Ready {
                    request,
                    payload: EditMaterializePayload::LocalInactive { layers: Vec::new() },
                };
            };
            if cancel.load(Ordering::Relaxed) {
                return EditMaterializeResult::Cancelled { request };
            }
            let decode_t0 = std::time::Instant::now();
            let parsed =
                serde_json::from_str::<Vec<local_adjust_core::LocalAdjustmentLayer>>(&json);
            emit_edit_materialize_ms(
                "decode",
                "local_json",
                Some(&page_key),
                request.input_seq,
                decode_t0,
            );
            match parsed {
                Ok(layers) => layers,
                Err(err) => {
                    crate::logger::log(format!(
                        "local_adjust: invalid layers_json key={page_key} error={err}"
                    ));
                    return EditMaterializeResult::Ready {
                        request,
                        payload: EditMaterializePayload::LocalInactive { layers: Vec::new() },
                    };
                }
            }
        }
    };
    if cancel.load(Ordering::Relaxed) {
        return EditMaterializeResult::Cancelled { request };
    }

    let [width, height] = source.size;
    let raster_t0 = std::time::Instant::now();
    for layer in &mut layers {
        if cancel.load(Ordering::Relaxed) {
            return EditMaterializeResult::Cancelled { request };
        }
        if !layer.masks_match_dims(width.max(1), height.max(1)) {
            layer.resize_masks_to(width.max(1), height.max(1));
        }
    }
    emit_edit_materialize_ms(
        "raster",
        "local_mask_resize",
        perf_key.as_deref(),
        request.input_seq,
        raster_t0,
    );

    if !layers
        .iter()
        .any(|layer| layer.enabled && layer.opacity > 0.0)
    {
        return EditMaterializeResult::Ready {
            request,
            payload: EditMaterializePayload::LocalInactive { layers },
        };
    }
    let compose_t0 = std::time::Instant::now();
    let rgba = crate::capture::color_image_to_rgba(&source);
    let src = local_adjust_core::RgbaImageRef {
        width,
        height,
        pixels: &rgba,
    };
    let rendered =
        local_adjust_core::apply_layers_with_progress(src, &layers, Some(&cancel), |_| {});
    emit_edit_materialize_ms(
        "compose",
        "local",
        perf_key.as_deref(),
        request.input_seq,
        compose_t0,
    );
    match rendered {
        Ok(out) if !cancel.load(Ordering::Relaxed) => EditMaterializeResult::Ready {
            request,
            payload: EditMaterializePayload::LocalReady {
                layers,
                image: egui::ColorImage::from_rgba_unmultiplied(
                    [out.width, out.height],
                    &out.pixels,
                ),
            },
        },
        Ok(_) | Err(local_adjust_core::LocalAdjustError::Cancelled) => {
            EditMaterializeResult::Cancelled { request }
        }
        Err(err) => EditMaterializeResult::Failed {
            request,
            error: err.to_string(),
        },
    }
}

fn run_conceal_materialize(
    request: EditMaterializeRequest,
    source: Arc<egui::ColorImage>,
    source_kind: &'static str,
    mask_source: ConcealMaterializeMask,
    preset: Option<crate::conceal::ConcealPreset>,
    cancel: Arc<AtomicBool>,
) -> EditMaterializeResult {
    let [w, h] = source.size;
    let perf_key = match &mask_source {
        ConcealMaterializeMask::Database { page_key, .. } => Some(page_key.clone()),
        ConcealMaterializeMask::Memory { .. } => None,
    };
    if cancel.load(Ordering::Relaxed) {
        return EditMaterializeResult::Cancelled { request };
    }
    let loaded = match mask_source {
        ConcealMaterializeMask::Memory {
            mut bitmap,
            mut shapes,
            size: [mw, mh],
        } => {
            if [mw, mh] != [w, h] {
                let decode_t0 = std::time::Instant::now();
                bitmap = crate::mask_db::rescale_mask(&bitmap, mw, mh, w, h);
                let sx = w as f32 / mw.max(1) as f32;
                let sy = h as f32 / mh.max(1) as f32;
                for shape in &mut shapes {
                    shape.scale_xy(sx, sy);
                }
                emit_edit_materialize_ms(
                    "decode",
                    "conceal_memory_rescale",
                    None,
                    request.input_seq,
                    decode_t0,
                );
            }
            Some((bitmap, shapes))
        }
        ConcealMaterializeMask::Database { path, page_key } => {
            let db_t0 = std::time::Instant::now();
            let db = match crate::conceal_db::ConcealDb::open_readonly(&path) {
                Ok(db) => db,
                Err(err) => {
                    return EditMaterializeResult::Failed {
                        request,
                        error: format!("conceal DB open failed: {err}"),
                    };
                }
            };
            let raw = db.get_raw(&page_key);
            emit_edit_materialize_ms(
                "db_read",
                "conceal",
                Some(&page_key),
                request.input_seq,
                db_t0,
            );
            if let Some(raw) = raw {
                let decode_t0 = std::time::Instant::now();
                let decoded =
                    crate::conceal_db::ConcealDb::materialize_raw(raw, w, h, Some(&cancel));
                emit_edit_materialize_ms(
                    "decode",
                    "conceal_deflate_json",
                    Some(&page_key),
                    request.input_seq,
                    decode_t0,
                );
                decoded
            } else {
                None
            }
        }
    };
    if cancel.load(Ordering::Relaxed) {
        return EditMaterializeResult::Cancelled { request };
    }
    let (mut bitmap, shapes) = loaded.unwrap_or_else(|| (vec![false; w * h], Vec::new()));
    if matches!(
        request.kind,
        EditMaterializeKind::Conceal {
            purpose: ConcealMaterializePurpose::EnterMode { .. },
            ..
        }
    ) {
        return EditMaterializeResult::Ready {
            request,
            payload: EditMaterializePayload::ConcealEnter {
                source,
                source_kind,
                mask: bitmap,
                shapes,
            },
        };
    }
    if !bitmap.iter().any(|&bit| bit) && shapes.is_empty() {
        return EditMaterializeResult::Ready {
            request,
            payload: EditMaterializePayload::ConcealDisplayEmpty {
                source,
                source_kind,
            },
        };
    }

    let raster_t0 = std::time::Instant::now();
    if !crate::mask_db::rasterize_shapes_into_cancel(&mut bitmap, &shapes, w, h, &cancel) {
        return EditMaterializeResult::Cancelled { request };
    }
    emit_edit_materialize_ms(
        "raster",
        "conceal",
        perf_key.as_deref(),
        request.input_seq,
        raster_t0,
    );
    if cancel.load(Ordering::Relaxed) {
        return EditMaterializeResult::Cancelled { request };
    }
    let image = if bitmap.iter().any(|&bit| bit) {
        let compose_t0 = std::time::Instant::now();
        let image = crate::conceal_compose::compose_with_preset_cancel(
            &source,
            &bitmap,
            &preset.expect("display conceal request has preset"),
            &cancel,
        );
        emit_edit_materialize_ms(
            "compose",
            "conceal",
            perf_key.as_deref(),
            request.input_seq,
            compose_t0,
        );
        image
    } else {
        None
    };
    if cancel.load(Ordering::Relaxed) {
        return EditMaterializeResult::Cancelled { request };
    }
    EditMaterializeResult::Ready {
        request,
        payload: match image {
            Some(image) => EditMaterializePayload::ConcealDisplayReady {
                image,
                source_kind,
                shape_count: shapes.len(),
            },
            None => EditMaterializePayload::ConcealDisplayEmpty {
                source,
                source_kind,
            },
        },
    }
}

fn edit_materialize_result_request(result: &EditMaterializeResult) -> EditMaterializeRequest {
    match result {
        EditMaterializeResult::Ready { request, .. }
        | EditMaterializeResult::Cancelled { request }
        | EditMaterializeResult::Failed { request, .. } => *request,
    }
}

fn edit_materialize_result_needs_upload(result: &EditMaterializeResult) -> bool {
    matches!(
        result,
        EditMaterializeResult::Ready {
            payload: EditMaterializePayload::LocalReady { .. }
                | EditMaterializePayload::ConcealDisplayReady { .. },
            ..
        }
    )
}

pub(crate) struct ComparePinLoadPending {
    pub(crate) source_idx: usize,
    pub(crate) source_key: String,
}

pub(crate) struct ComparePreparedPair {
    pub(crate) key: u64,
    pub(crate) current_idx: usize,
    pub(crate) pinned_source_idx: usize,
    pub(crate) current_input_size: [usize; 2],
    pub(crate) pinned_input_size: [usize; 2],
    pub(crate) target_size: [usize; 2],
    pub(crate) pixels: ComparePreparedPixels,
    pub(crate) pinned_texture: Option<egui::TextureHandle>,
    pub(crate) current_texture: Option<egui::TextureHandle>,
    pub(crate) diff_texture: Option<egui::TextureHandle>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ComparePrepareOutput {
    ShaderPair,
    PinnedTexture,
    WipeTextures,
    DiffTexture,
}

impl ComparePrepareOutput {
    pub(crate) fn for_mode(mode: CompareViewMode, gpu_compare_available: bool) -> Option<Self> {
        match mode {
            CompareViewMode::Off => None,
            CompareViewMode::PinnedNormal => Some(Self::PinnedTexture),
            CompareViewMode::Wipe { .. } if gpu_compare_available => Some(Self::ShaderPair),
            CompareViewMode::Diff if gpu_compare_available => Some(Self::ShaderPair),
            CompareViewMode::Wipe { .. } => Some(Self::WipeTextures),
            CompareViewMode::Diff => Some(Self::DiffTexture),
        }
    }

    pub(crate) fn label(self) -> &'static str {
        match self {
            Self::ShaderPair => "shader-pair",
            Self::PinnedTexture => "pinned-texture",
            Self::WipeTextures => "wipe-textures",
            Self::DiffTexture => "diff-texture",
        }
    }
}

pub(crate) enum ComparePreparedPixels {
    ShaderPair {
        pinned_rgba: Arc<Vec<u8>>,
        current_rgba: Arc<Vec<u8>>,
    },
    PinnedTexture(Arc<egui::ColorImage>),
    WipeTextures {
        pinned: Arc<egui::ColorImage>,
        current: Arc<egui::ColorImage>,
    },
    DiffTexture(Arc<egui::ColorImage>),
}

impl ComparePreparedPixels {
    pub(crate) fn output(&self) -> ComparePrepareOutput {
        match self {
            Self::ShaderPair { .. } => ComparePrepareOutput::ShaderPair,
            Self::PinnedTexture(_) => ComparePrepareOutput::PinnedTexture,
            Self::WipeTextures { .. } => ComparePrepareOutput::WipeTextures,
            Self::DiffTexture(_) => ComparePrepareOutput::DiffTexture,
        }
    }

    pub(crate) fn allocated_bytes(&self) -> u64 {
        let rgba_bytes = |rgba: &Arc<Vec<u8>>| rgba.capacity() as u64;
        let color_bytes = |pixels: &Arc<egui::ColorImage>| {
            (pixels.pixels.capacity() * std::mem::size_of::<egui::Color32>()) as u64
        };
        match self {
            Self::ShaderPair {
                pinned_rgba,
                current_rgba,
            } => rgba_bytes(pinned_rgba) + rgba_bytes(current_rgba),
            Self::PinnedTexture(pinned) => color_bytes(pinned),
            Self::WipeTextures { pinned, current } => color_bytes(pinned) + color_bytes(current),
            Self::DiffTexture(diff) => color_bytes(diff),
        }
    }

    pub(crate) fn buffer_count(&self) -> usize {
        match self {
            Self::ShaderPair { .. } | Self::WipeTextures { .. } => 2,
            Self::PinnedTexture(_) | Self::DiffTexture(_) => 1,
        }
    }

    pub(crate) fn valid_for_size(&self, size: [usize; 2]) -> bool {
        let Some(expected_pixels) = size[0].checked_mul(size[1]) else {
            return false;
        };
        let Some(expected_rgba) = expected_pixels.checked_mul(4) else {
            return false;
        };
        let rgba_valid = |rgba: &Arc<Vec<u8>>| rgba.len() == expected_rgba;
        let color_valid = |pixels: &Arc<egui::ColorImage>| {
            pixels.size == size && pixels.pixels.len() == expected_pixels
        };
        match self {
            Self::ShaderPair {
                pinned_rgba,
                current_rgba,
            } => rgba_valid(pinned_rgba) && rgba_valid(current_rgba),
            Self::PinnedTexture(pinned) => color_valid(pinned),
            Self::WipeTextures { pinned, current } => color_valid(pinned) && color_valid(current),
            Self::DiffTexture(diff) => color_valid(diff),
        }
    }
}

impl ComparePreparedPair {
    pub(crate) fn allocated_cpu_bytes(&self) -> u64 {
        self.pixels.allocated_bytes()
    }
}

