/// 比較合成の排他的なライフサイクル。
///
/// `WaitingForSource` は PDF の表示解像度更新など、現在ページの最終 source がまだ
/// 確定していない状態を表す。準備中 / 準備済みを別々の `Option` で持たないため、
/// worker 完了前の縮退画像を Ready として描画へ公開できない。
#[derive(Default)]
pub(crate) enum ComparePreparationState {
    #[default]
    Unprepared,
    WaitingForSource(ComparePrepareRequest),
    Preparing(ComparePreparePending),
    /// 入力が失効したが、途中cancel不能なworkerの完了を回収するまで次を直列化する状態。
    Draining(ComparePreparePending),
    Ready(ComparePreparedPair),
}

impl ComparePreparationState {
    pub(crate) fn request(&self) -> Option<ComparePrepareRequest> {
        match self {
            Self::WaitingForSource(request) => Some(*request),
            Self::Preparing(pending) | Self::Draining(pending) => Some(pending.request),
            Self::Ready(pair) => Some(ComparePrepareRequest {
                current_idx: pair.current_idx,
                pinned_source_idx: pair.pinned_source_idx,
                output: pair.pixels.output(),
            }),
            Self::Unprepared => None,
        }
    }

    pub(crate) fn prepared_pair(&self) -> Option<&ComparePreparedPair> {
        match self {
            Self::Ready(pair) => Some(pair),
            _ => None,
        }
    }

    pub(crate) fn prepared_pair_mut(&mut self) -> Option<&mut ComparePreparedPair> {
        match self {
            Self::Ready(pair) => Some(pair),
            _ => None,
        }
    }

    pub(crate) fn is_pending(&self) -> bool {
        matches!(
            self,
            Self::WaitingForSource(_) | Self::Preparing(_) | Self::Draining(_)
        )
    }

    pub(crate) fn invalidate(&mut self) {
        let old = std::mem::take(self);
        *self = match old {
            Self::Preparing(pending) | Self::Draining(pending) => Self::Draining(pending),
            _ => Self::Unprepared,
        };
    }
}

/// 起動オーバーレイ用の `StartupProgressHook` を作る共通ヘルパー。
/// `IndexerManager::new` が各 sub-step の前に呼び、Mutex 内の文字列を更新する。
fn make_progress_hook(progress: Arc<Mutex<String>>) -> crate::indexer_manager::StartupProgressHook {
    Arc::new(move |s: &str| {
        if let Ok(mut p) = progress.lock() {
            *p = s.to_string();
        }
    })
}

#[cfg(windows)]
fn run_vst3_startup_load(
    bridge: std::sync::Arc<crate::video::dsp::DspBridge>,
    plugins: Vec<crate::settings::Vst3PluginEntry>,
    progress: Arc<Mutex<String>>,
    my_gen: u64,
) {
    if let Ok(mut p) = progress.lock() {
        *p = "VST3 プラグインを初期化中…".to_string();
    }
    // T21 (Codex R-VST-001): 後続の chain rebuild が来たら諦める。
    if bridge.is_chain_rebuild_stale(my_gen) {
        crate::logger::log(format!(
            "[VST3 startup] gen={my_gen} stale before enable, skipping"
        ));
        return;
    }
    if let Err(e) = bridge.enable() {
        crate::logger::log(format!("vst3 startup enable failed: {e}"));
        return;
    }
    if plugins.is_empty() {
        return;
    }
    let sample_rate = crate::video::audio::default_output_sample_rate().unwrap_or(48_000);
    let total = plugins.len();
    for (idx, entry) in plugins.into_iter().enumerate() {
        if bridge.is_chain_rebuild_stale(my_gen) {
            crate::logger::log(format!(
                "[VST3 startup] gen={my_gen} stale at plugin {}/{}, dropping remaining",
                idx + 1,
                total
            ));
            return;
        }
        if let Ok(mut p) = progress.lock() {
            *p = format!("VST3 プラグインを初期化中… ({}/{})", idx + 1, total);
        }
        crate::logger::log(format!(
            "[VST3 startup] loading {}/{}: {}",
            idx + 1,
            total,
            entry.path
        ));
        if let Err(e) = bridge.add_plugin(
            &entry.path,
            sample_rate,
            480,
            entry.bypass,
            entry.user_hidden,
            entry.state.as_deref(),
            entry.gui_pos,
            entry.gui_size,
        ) {
            crate::logger::log(format!(
                "vst3 startup add_plugin {} failed: {e} (このプラグインのみスキップ)",
                entry.path
            ));
            if !bridge.is_enabled() {
                crate::logger::log(
                    "[VST3 startup] stopped because the bridge was disabled after a plugin timeout"
                        .to_string(),
                );
                break;
            }
        } else {
            crate::logger::log(format!(
                "[VST3 startup] loaded {}/{}: {}",
                idx + 1,
                total,
                entry.path
            ));
        }
    }
}

/// 名前索引 OFF 遷移時の「supervisor join 完了 → search_index_db クリア」を実行する
/// 共通ヘルパー (T53 + Codex P3 / 2026-05-16)。
///
/// 自由関数として extract する理由: `apply_favorite_name_index_change` の旧コードでは
/// `std::thread::Builder::spawn(closure)` の closure 内に clear ロジックを直書きしていた
/// が、`spawn` は失敗時に closure を実行せずに drop するだけなので、spawn 失敗パスでは
/// clear が永久に走らない不具合があった。channel handoff (= spawn 成功時) と sync 呼び出し
/// (= spawn 失敗時) の両方から本関数を呼ぶ構造に変えることで、どちらの経路でも join → clear
/// の順序を保ったまま、必ず両方が実行される。
fn run_name_index_off_completion(
    handle: crate::name_index_supervisor::NameIndexSupervisorHandle,
    clear_target: Option<(Arc<crate::search_index_db::SearchIndexDb>, PathBuf)>,
) {
    // Drop 内で cancel 再送 + thread.join() が走る (= bulk scan が止まるまで待つ)。
    drop(handle);
    if let Some((db, path)) = clear_target {
        if let Err(e) = db.clear_for_favorite(&path) {
            crate::logger::log(format!(
                "favorites: clear name index for {} failed (post-join): {e}",
                path.display()
            ));
        }
    }
}

/// 非同期で走っている `navigate_folder_with_skip` ワーカーの状態。
pub(crate) struct FolderNavPending {
    /// DFS キャンセル用トークン。連打の累積・モード切替・フォルダ強制切替で立てる。
    cancel: Arc<AtomicBool>,
    /// DFS スレッドからの結果チャネル。
    rx: mpsc::Receiver<FolderNavThreadResult>,
    /// この DFS ステップの方向 (forward=↓, backward=↑)。結果の後処理に使う。
    forward: bool,
    /// この DFS が発火された起点モード。結果の後処理に使う。
    mode: FolderNavMode,
}

/// 1 本の DFS が進行している間に受け付ける追加移動数の上限。
///
/// キーを離した後まで長く移動し続けないよう、最初に実行中の 1 ステップとは別に
/// 保持する追加ステップを前後それぞれ 5 件までに制限する。
const MAX_PENDING_NAV: i32 = 5;

/// 実フォルダを **worker で事前 scan** してから開くための保留状態。
/// folder pane ナビと detached image open が共有し、`purpose` が結果の適用先と対象 leaf を所有する。
/// UI スレッドで `scan_directory` (大/遅/ネットワークフォルダで read_dir が数百 ms〜秒) を
/// 直接走らせないための、`spawn_folder_nav` の DFS pre-scan と同じ方式。
pub(crate) struct FolderPaneOpenPending {
    /// 開く候補 (= 完了後に通常 nav 優先順位で裁定する実ディレクトリ)。
    path: PathBuf,
    /// 旧 pending を上書き/別 nav 勝利時に立てるキャンセルトークン。
    cancel: Arc<AtomicBool>,
    /// scan worker からの結果チャネル。
    rx: mpsc::Receiver<std::io::Result<ScannedDir>>,
    /// scan 完了後に誰が結果を適用するか。detached image open は対象画像まで
    /// この request に内包し、main の仮想一覧や別の deferred field に依存しない。
    purpose: FolderOpenScanPurpose,
}

pub(crate) enum FolderOpenScanPurpose {
    PaneNavigation,
    /// A grid `Folder` requested while always-new mode is active. The main context
    /// owns this request until the completed scan classifies it as either an image
    /// book (detached) or an ordinary mixed folder (main navigation).
    GridFolderCandidate,
    DetachedFolder,
    DetachedImage {
        image_path: PathBuf,
    },
}

/// folder open scan の完了候補。`purpose` に応じて main nav の優先順位で裁定するか、
/// mounted detached bundle 内で対象画像を開く。
pub(crate) struct FolderPaneOpenReady {
    path: PathBuf,
    scan: std::io::Result<ScannedDir>,
    purpose: FolderOpenScanPurpose,
}

#[cfg(windows)]
enum DetachedPhysicalFolderOpenPoll {
    Waiting,
    Applied,
    Failed,
}

/// 親フォルダ上の `ConvertibleArchive` タイル用に、変換済み cache ZIP の対応表を
/// UI スレッド外で解決している状態。
pub(crate) struct ConvertedArchiveCachePathsPending {
    /// 起動時の items 世代。完了時に変わっていれば結果を捨てる。
    generation: u64,
    cancel: Arc<AtomicBool>,
    rx: mpsc::Receiver<ConvertedArchiveCachePathsResult>,
}

impl ConvertedArchiveCachePathsPending {
    fn cancel(&self) {
        self.cancel.store(true, Ordering::Relaxed);
    }
}

impl Drop for ConvertedArchiveCachePathsPending {
    fn drop(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
    }
}

struct ConvertedArchiveCachePathsResult {
    paths: std::collections::HashMap<String, PathBuf>,
    peeked: usize,
    hits: usize,
    elapsed_ms: f64,
    input_seq: u64,
}

/// `poll_folder_nav` がワーカー完了を検知したときに返す情報。
pub(crate) struct FolderNavResult {
    /// DFS が見つけた次フォルダ (None なら DFS が尽きた)。
    pub path: Option<PathBuf>,
    /// `folder_should_stop` をパスしたフォルダ (= 画像/動画/ZIP/PDF あり) か。
    /// `false` のときは skip_limit 尽きまたは DFS 末端でのフォールバック、または
    /// 結果自体が `None` (path も None)。Fullscreen モードの後処理は false なら
    /// 移動を取りやめて境界ヒントを出す。
    pub hit_image_folder: bool,
    /// 起点の方向。
    pub forward: bool,
    /// 起点モード。
    pub mode: FolderNavMode,
    /// この DFS が進行している間に同じモードで受け付けた追加ステップ。
    ///
    /// 一般の `start_loading_items` は別操作によるフォルダ切替で古い burst を流すため、
    /// App 上の accumulator を従来どおり clear する。この値だけは完了した folder-nav
    /// request 自身が所有し、適用成功後に次の DFS へ引き渡す。
    pub queued_steps: i32,
    /// DFS スレッドで事前走査した `path` の中身、または走査失敗。
    /// 失敗を空一覧として `load_folder` へ適用して catalog を削除しない。
    pub scanned: FolderNavScanResult,
}

/// 非同期メタデータ読み込み (フルスクリーン表示対象画像の AI/EXIF/XMP) の状態。
///
/// `open_fullscreen` から起動され、`poll_metadata_load` で結果を受信する。
/// **背景**: XMP リーダーは JPEG/PNG 全体を読むため (`read_tweet_info`)、
/// 20MP 級の写真で UI スレッドが 100ms 級でブロックしていた
/// (AI metadata と EXIF は数 ms だが、XMP が主犯)。
/// 新 fullscreen idx が開かれたら旧 pending を cancel する (連打時は最新のみ処理)。
pub(crate) struct MetadataLoadPending {
    cancel: Arc<AtomicBool>,
    rx: mpsc::Receiver<MetadataLoadResult>,
}

impl MetadataLoadPending {
    pub(crate) fn cancel(&self) {
        self.cancel.store(true, Ordering::Relaxed);
    }
}

/// メタデータ読み込みワーカーの結果。キー (metadata_cache_key の形式) と
/// 4 つのパース結果 (AI metadata / EXIF / XMP xtw / XMP GPano) をまとめて返す。
/// UI 側はそれぞれのキャッシュに投入する。
pub(crate) struct MetadataLoadResult {
    key: String,
    metadata: Option<crate::png_metadata::AiMetadata>,
    exif: Option<crate::exif_reader::ExifInfo>,
    xmp: Option<crate::xmp_reader::XmpTweetInfo>,
    /// XMP GPano パノラマメタデータ。`Some(_)` でも `is_populated()` で空かどうかを判定。
    /// 360 度パノラマビュー機能 (docs/panorama-360-view-plan.md) のシグナル。
    panorama: Option<crate::xmp_reader::XmpPanoramaInfo>,
    /// 外部メタデータサイドカー (同名 JSON/TXT) の右パネル表示用内容 (FS 画像のみ)。
    /// docs/sidecar-metadata-ingest.md §11。
    sidecar: Option<crate::external_metadata::SidecarDisplay>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum LazyColumnState {
    Disabled,
    NotRequested,
    Loading {
        done: usize,
        total: usize,
    },
    /// 現ジョブは完了したが、描画後の可視 + 先読み範囲に次ジョブが必要かを
    /// まだ照合していない走査セッション。ジョブ境界を Ready として公開しない。
    Reconciling {
        done: usize,
        total: usize,
        failed: usize,
    },
    Ready {
        failed: usize,
    },
    Cancelled,
}

impl LazyColumnState {
    pub(crate) fn is_ready(self) -> bool {
        matches!(self, Self::Ready { .. })
    }

    fn is_loading(self) -> bool {
        matches!(self, Self::Loading { .. } | Self::Reconciling { .. })
    }
}

impl Default for LazyColumnState {
    fn default() -> Self {
        Self::Disabled
    }
}

const DETAILS_LAZY_META_STALE_CAP: usize = 50_000;
/// 詳細遅延メタの target 構築を UI thread で 1 frame に進める上限。
///
/// 50 万件の smart folder でも全件 clone + 判定を 1 frame に集中させず、約 1us/item の
/// 実機報告なら 4ms 前後の slice へ抑える。走査 session は cursor を保持し、scroll 時は
/// worker の priority queue だけを更新するため先頭から数え直さない。
const DETAILS_META_TARGET_SCAN_BUDGET_PER_FRAME: usize = 4_096;

#[derive(Clone, Default)]
pub(crate) struct DetailsLazyMeta {
    pub(crate) source_mtime: i64,
    pub(crate) source_size: i64,
    pub(crate) created_at: Option<i64>,
    pub(crate) created_at_failed: bool,
    pub(crate) ai_metadata_checked: bool,
    pub(crate) ai_models: Vec<String>,
    pub(crate) ai_tool: Option<String>,
    pub(crate) page_count: Option<u32>,
    pub(crate) page_count_checked: bool,
    pub(crate) page_count_failed: bool,
    /// PDF のページ数を取得した時点の、保存済みパスワードのプロセス内更新世代。
    /// パスワード自体やそのハッシュは保持しない。
    pub(crate) page_count_pdf_password_revision: Option<u64>,
    pub(crate) image_dims: Option<(u32, u32)>,
    pub(crate) image_dims_failed: bool,
    pub(crate) video_duration_secs: Option<f64>,
    pub(crate) video_dims: Option<(u32, u32)>,
    pub(crate) video_codec: Option<String>,
    pub(crate) video_meta_failed: bool,
}

impl DetailsLazyMeta {
    fn matches_source(&self, source: Option<(i64, i64)>) -> bool {
        let (mtime, size) = source.unwrap_or((0, 0));
        self.source_mtime == mtime && self.source_size == size
    }

    fn apply_patch(&mut self, patch: Self, loaded: DetailsLazyFieldFlags) -> bool {
        let source_changed = !self.matches_source(Some((patch.source_mtime, patch.source_size)));
        if source_changed {
            *self = Self::default();
        }
        self.source_mtime = patch.source_mtime;
        self.source_size = patch.source_size;
        if loaded.created_at {
            self.created_at = patch.created_at;
            self.created_at_failed = patch.created_at_failed;
        }
        if loaded.ai_metadata {
            self.ai_metadata_checked = patch.ai_metadata_checked;
            self.ai_models = patch.ai_models;
            self.ai_tool = patch.ai_tool;
        }
        if loaded.page_count {
            self.page_count = patch.page_count;
            self.page_count_checked = patch.page_count_checked;
            self.page_count_failed = patch.page_count_failed;
            self.page_count_pdf_password_revision = patch.page_count_pdf_password_revision;
        }
        if loaded.image_dims {
            self.image_dims = patch.image_dims;
            self.image_dims_failed = patch.image_dims_failed;
        }
        if loaded.video_meta {
            self.video_duration_secs = patch.video_duration_secs;
            self.video_dims = patch.video_dims;
            self.video_codec = patch.video_codec;
            self.video_meta_failed = patch.video_meta_failed;
        }
        source_changed
    }
}

#[derive(Clone, Copy, Default)]
struct DetailsLazyFieldFlags {
    page_count: bool,
    created_at: bool,
    ai_metadata: bool,
    image_dims: bool,
    video_meta: bool,
}

impl DetailsLazyFieldFlags {
    fn any(self) -> bool {
        self.page_count || self.created_at || self.ai_metadata || self.image_dims || self.video_meta
    }

    fn merge(&mut self, other: Self) {
        self.page_count |= other.page_count;
        self.created_at |= other.created_at;
        self.ai_metadata |= other.ai_metadata;
        self.image_dims |= other.image_dims;
        self.video_meta |= other.video_meta;
    }
}

/// 詳細列の表示文字列が変化した世代。
///
/// best-fit は対象列の世代だけを監視する。全列共通の世代にすると、タグの連続到着中に
/// 動画列まで再走査されるなど、無関係な background load で完了できなくなるため分離する。
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct DetailsCellContentRevisions {
    pub(crate) tags: u64,
    pub(crate) page_count: u64,
    pub(crate) created_at: u64,
    pub(crate) image_dims: u64,
    pub(crate) video_meta: u64,
}

impl DetailsCellContentRevisions {
    fn bump(value: &mut u64) {
        *value = value.wrapping_add(1);
    }

    fn bump_lazy_fields(&mut self, loaded: DetailsLazyFieldFlags) {
        if loaded.page_count {
            Self::bump(&mut self.page_count);
        }
        if loaded.created_at {
            Self::bump(&mut self.created_at);
        }
        if loaded.image_dims {
            Self::bump(&mut self.image_dims);
        }
        if loaded.video_meta {
            Self::bump(&mut self.video_meta);
        }
    }

    fn bump_all_lazy_fields(&mut self) {
        Self::bump(&mut self.page_count);
        Self::bump(&mut self.created_at);
        Self::bump(&mut self.image_dims);
        Self::bump(&mut self.video_meta);
    }
}

struct DetailsMetaPending {
    visible_revision: u64,
    selection_target_key: Option<String>,
    normal_target_keys: HashSet<String>,
    cancel: Arc<AtomicBool>,
    phase: DetailsMetaPendingPhase,
}

enum DetailsMetaPendingPhase {
    Planning(DetailsMetaTargetPlan),
    Loading {
        rx: mpsc::Receiver<DetailsMetaEvent>,
        priority_tx: mpsc::Sender<Vec<DetailsMetaTarget>>,
    },
}

enum DetailsMetaScanOrder {
    Explicit {
        indices: Vec<usize>,
        cursor: usize,
    },
    CurrentGrid {
        cursor: usize,
        len: usize,
        order_revision: u64,
    },
}

impl DetailsMetaScanOrder {
    fn scanned(&self) -> usize {
        match self {
            Self::Explicit { cursor, .. } | Self::CurrentGrid { cursor, .. } => *cursor,
        }
    }

    fn len(&self) -> usize {
        match self {
            Self::Explicit { indices, .. } => indices.len(),
            Self::CurrentGrid { len, .. } => *len,
        }
    }

    fn is_complete(&self) -> bool {
        self.scanned() >= self.len()
    }

    fn is_incremental(&self) -> bool {
        matches!(self, Self::CurrentGrid { .. })
    }
}

struct DetailsMetaTargetPlan {
    generation: u64,
    order: DetailsMetaScanOrder,
    visible_near: HashSet<usize>,
    load_all_page_counts: bool,
    ai_facet_load: bool,
    page_count_config: DetailsPageCountConfig,
    visible_targets: Vec<DetailsMetaTarget>,
    background_targets: Vec<DetailsMetaTarget>,
    cached_done: usize,
    cached_failed: usize,
    total: usize,
    scan_slices: usize,
    scan_started_at: Option<std::time::Instant>,
}

fn details_meta_reprioritize_candidate(
    current_visible: &HashSet<String>,
    normal_target_keys: &HashSet<String>,
) -> bool {
    !current_visible.is_empty()
        && (normal_target_keys.is_empty() || current_visible.is_disjoint(normal_target_keys))
}

fn details_meta_reprioritize_allowed(
    now: std::time::Instant,
    last_scroll_at: Option<std::time::Instant>,
    current_visible: &HashSet<String>,
    normal_target_keys: &HashSet<String>,
) -> bool {
    details_meta_reprioritize_candidate(current_visible, normal_target_keys)
        && matches!(
            decide_prefetch_allowed(now, last_scroll_at, 0),
            PrefetchDecision::Allow { .. }
        )
}

fn details_selection_pending_is_stale(
    target_key: Option<&str>,
    pending_target_key: Option<&str>,
) -> bool {
    target_key.is_none_or(|target_key| pending_target_key != Some(target_key))
}

