/// 非同期お気に入り検索 (Ctrl+S) の状態。
///
/// `search_index_db.search()` は SQLite クエリでインデックス化された名前検索だが、
/// 大規模お気に入りツリーでは 10〜100ms 級のブロックになり得る。さらにその後に
/// 走る `start_loading_items` が数百ms の UI ブロック源になるので、DB 問い合わせ
/// だけでもバックグラウンドに退避する。
pub(crate) struct FavSearchPending {
    cancel: Arc<AtomicBool>,
    rx: mpsc::Receiver<rusqlite::Result<Vec<crate::search_index_db::IndexEntry>>>,
}

/// Runtime-only hash for display pipeline cache keys.
///
/// `DefaultHasher` is intentionally not stable across Rust releases, so these
/// values must never be persisted. They only separate in-process render cache
/// entries while the app is running.
fn runtime_hash_with(f: impl FnOnce(&mut std::collections::hash_map::DefaultHasher)) -> u64 {
    use std::hash::Hasher;
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    f(&mut hasher);
    hasher.finish()
}

fn hash_adjust_color_ai_params(
    params: &crate::adjustment::AdjustParams,
    ai_feature_mode: crate::settings::AiFeatureMode,
) -> u64 {
    use std::hash::Hash;
    runtime_hash_with(|h| {
        params.brightness.to_bits().hash(h);
        params.contrast.to_bits().hash(h);
        params.gamma.to_bits().hash(h);
        params.saturation.to_bits().hash(h);
        params.temperature.to_bits().hash(h);
        params.black_point.hash(h);
        params.white_point.hash(h);
        params.midtone.to_bits().hash(h);
        params.auto_mode.map(|mode| format!("{mode:?}")).hash(h);
        params.upscale_model.hash(h);
        params.denoise_model.hash(h);
        ai_feature_mode.hash(h);
    })
}

fn hash_adjust_final_params(
    params: &crate::adjustment::AdjustParams,
    ai_feature_mode: crate::settings::AiFeatureMode,
    post_filter_bypassed: bool,
) -> u64 {
    use std::hash::Hash;
    runtime_hash_with(|h| {
        hash_adjust_color_ai_params(params, ai_feature_mode).hash(h);
        post_filter_bypassed.hash(h);
        if !post_filter_bypassed {
            format!("{:?}", params.colorize).hash(h);
            format!("{:?}", params.post_filter).hash(h);
            params.creative_lut.id.hash(h);
            params.creative_lut.strength.to_bits().hash(h);
        }
        // 最終表示段スマートシャープ。post_filter バイパス (消しゴム / 隠蔽 / 分析) 中も
        // 色調補正と同様に適用したままにするので、bypassed の条件外で hash する。
        // color_ai hash には含めない (= 強度変更で final AI を再実行させない)。
        params.smart_sharpen.hash(h);
    })
}

/// 検索モード。相互排他と戻り先移譲 (`take_origin_for_search_entry`) 用。
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum SearchMode {
    /// Ctrl+F: ローカルフォルダのメタデータ検索
    LocalMeta,
    /// Ctrl+S: お気に入り配下の名前検索
    Favsearch,
    /// Ctrl+G: お気に入り全体のメタデータ検索
    Global,
    /// Ctrl+T: tags.db 直引きのタグビュー
    TagView,
}

/// 非同期メタデータ検索 (Ctrl+F) の状態。
///
/// 背景: 検索マッチの判定には `png_metadata::build_searchable_from_path` や
/// `xmp_reader::read_tweet_info` など、ファイル I/O を伴う読み取りが必要。
/// フォルダに数百〜数千枚の画像があると UI スレッドで数秒ブロックしていたため、
/// バックグラウンドスレッドで実行して結果を `poll_search` で受け取る構造に変更した。
pub(crate) struct SearchPending {
    /// 検索キャンセル用トークン。新クエリ / 検索バー閉じ / フォルダ切替で立てる。
    cancel: Arc<AtomicBool>,
    /// UI が毎フレーム読む検索進捗。worker は item 完了ごとに更新する。
    progress: Arc<SearchProgressShared>,
    /// ワーカースレッドから結果を受け取るチャネル。
    rx: mpsc::Receiver<SearchThreadResult>,
}

impl SearchPending {
    pub(crate) fn cancel(&self) {
        self.cancel.store(true, Ordering::Relaxed);
    }

    pub(crate) fn progress_snapshot(&self) -> SearchProgressSnapshot {
        self.progress.snapshot()
    }
}

/// Ctrl+F worker の item 単位進捗 snapshot。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SearchProgressSnapshot {
    pub done: usize,
    pub total: usize,
    pub matched: usize,
}

/// Ctrl+F worker から UI へ渡す軽量進捗共有状態。
pub(crate) struct SearchProgressShared {
    total: AtomicUsize,
    done: AtomicUsize,
    matched: AtomicUsize,
}

impl SearchProgressShared {
    fn new(total: usize) -> Self {
        Self {
            total: AtomicUsize::new(total),
            done: AtomicUsize::new(0),
            matched: AtomicUsize::new(0),
        }
    }

    fn mark_item_done(&self, matched: bool) {
        if matched {
            self.matched.fetch_add(1, Ordering::Relaxed);
        }
        self.done.fetch_add(1, Ordering::Relaxed);
    }

    pub(crate) fn snapshot(&self) -> SearchProgressSnapshot {
        let total = self.total.load(Ordering::Relaxed);
        SearchProgressSnapshot {
            done: self.done.load(Ordering::Relaxed).min(total),
            total,
            matched: self.matched.load(Ordering::Relaxed).min(total),
        }
    }
}

/// 検索ワーカースレッドからの結果。
pub(crate) enum SearchThreadResult {
    /// 検索完了。`matches` は該当アイテムの原インデックス集合、
    /// `xmp_additions` はワーカーが新規に読み取った XMP エントリの (key, value) 対で、
    /// UI スレッドで `xmp_cache` にマージする。
    Done {
        matches: std::collections::HashSet<usize>,
        xmp_additions: Vec<(String, Option<crate::xmp_reader::XmpTweetInfo>)>,
    },
}

impl FolderNavMode {
    /// perf ログに載せる短い識別子。variant 名のみでパスなどを含めず、
    /// ユーザーパスが診断ログに混入しないようにする。
    pub fn perf_tag(&self) -> &'static str {
        match self {
            FolderNavMode::Grid => "grid",
            FolderNavMode::SiblingGrid => "grid_sibling",
            FolderNavMode::Fullscreen => "fullscreen",
            FolderNavMode::SiblingFullscreen => "fullscreen_sibling",
            FolderNavMode::Favsearch { .. } => "favsearch",
            FolderNavMode::SmartFolder { .. } => "smart_folder",
            FolderNavMode::SlideshowNext => "slideshow_next",
        }
    }

    pub fn sibling_only(&self) -> bool {
        matches!(
            self,
            FolderNavMode::SiblingGrid | FolderNavMode::SiblingFullscreen
        )
    }

    pub fn history_trigger(&self) -> HistoryTrigger {
        match self {
            FolderNavMode::SlideshowNext => HistoryTrigger::AutoAdvance,
            _ => HistoryTrigger::UserChosen,
        }
    }
}

/// モードの種類と検索スコープを比較する。Favsearch は root / fullscreen が変わったら
/// 旧バーストを混ぜず、pending を張り替える。
fn folder_nav_mode_same_kind(a: &FolderNavMode, b: &FolderNavMode) -> bool {
    match (a, b) {
        (FolderNavMode::Grid, FolderNavMode::Grid)
        | (FolderNavMode::SiblingGrid, FolderNavMode::SiblingGrid)
        | (FolderNavMode::Fullscreen, FolderNavMode::Fullscreen)
        | (FolderNavMode::SiblingFullscreen, FolderNavMode::SiblingFullscreen) => true,
        (
            FolderNavMode::Favsearch {
                root: a_root,
                fullscreen: a_fullscreen,
            },
            FolderNavMode::Favsearch {
                root: b_root,
                fullscreen: b_fullscreen,
            },
        ) => a_root == b_root && a_fullscreen == b_fullscreen,
        (
            FolderNavMode::SmartFolder {
                state: a_state,
                fullscreen: a_fullscreen,
            },
            FolderNavMode::SmartFolder {
                state: b_state,
                fullscreen: b_fullscreen,
            },
        ) => a_state.definition_id == b_state.definition_id && a_fullscreen == b_fullscreen,
        _ => false,
    }
}

fn navigate_smart_folder_scope(
    state: &top_level_grid_view::SmartFolderViewState,
    current: &Path,
    forward: bool,
    tree_opts: crate::folder_tree::FolderTreeOptions,
    skip_limit: usize,
    cancel: &AtomicBool,
) -> Option<FolderNavOutcome> {
    if let Some(entry_root) = state.scoped_entry_root() {
        let outcome = navigate_folder_with_skip(
            current,
            |path| {
                let next = if forward {
                    next_folder_dfs(path, tree_opts)
                } else {
                    prev_folder_dfs(path, tree_opts)
                }?;
                crate::search_index_db::is_under(&next, entry_root).then_some(next)
            },
            |path, cancel| {
                crate::folder_tree::folder_should_stop_with_options(path, cancel, tree_opts)
            },
            skip_limit,
            Some(cancel),
        );
        if outcome.is_some() {
            return outcome;
        }
    }

    if cancel.load(Ordering::Relaxed) {
        return None;
    }
    let path = state.entry_at_offset(forward)?.to_path_buf();
    let hit_image_folder =
        crate::folder_tree::folder_should_stop_with_options(&path, Some(cancel), tree_opts);
    Some(FolderNavOutcome {
        path,
        hit_image_folder,
    })
}

