pub(crate) enum FinalEffectResult {
    Ready {
        pixels: Arc<egui::ColorImage>,
        elapsed_ms: f64,
        timing: FinalEffectTiming,
    },
    Cancelled,
}

#[derive(Clone, Copy, Debug, Default)]
pub(crate) struct FinalEffectTiming {
    adjust_ms: f64,
    sharpen_ms: f64,
    colorize_check_ms: f64,
    colorize_apply_ms: f64,
    creative_lut_ms: f64,
    post_filter_ms: f64,
    colorize_applied: bool,
    colorize_mode: crate::colorize::ColorizeMode,
    tone_method: crate::colorize::ToneDensityMethod,
    tone_radius: f32,
}

struct FinalEffectJob {
    source: Arc<egui::ColorImage>,
    /// AI を使わない先読みでは、色調補正も worker 上で行って UI を止めない。
    adjust_before_effect: Option<crate::adjustment::AdjustParams>,
    smart_sharpen: u8,
    colorize: crate::colorize::ColorizeParams,
    colorize_applicable_override: Option<bool>,
    creative_lut: Option<(crate::creative_lut::SharedCreativeLut, f32)>,
    post_filter: crate::adjustment::PostFilter,
}

/// Build the low-resolution page-turn rendition synchronously on the UI thread.
/// The order is the page-turn contract in display-pipeline §2.5.6:
/// color adjustment -> colorize -> Creative LUT. Content edits, AI, sharpen and
/// post filters stay outside this bounded thumbnail-sized path.
struct PassthroughRenditionPixels {
    /// None means every low-resolution effect was an identity and the catalog
    /// texture can be reused without an extra upload.
    pixels: Option<egui::ColorImage>,
    colorize_applied: bool,
}

fn build_passthrough_rendition_pixels(
    source: &egui::ColorImage,
    params: &crate::adjustment::AdjustParams,
    creative_lut: Option<(crate::creative_lut::SharedCreativeLut, f32)>,
    colorize_applicable_override: Option<bool>,
) -> PassthroughRenditionPixels {
    let mut pixels = if params.is_color_identity() {
        None
    } else {
        Some(crate::adjustment::apply_adjustments_fast(source, params))
    };
    let colorize_source = pixels.as_ref().unwrap_or(source);
    let colorize_applied = final_effect_colorize_applies(
        &params.colorize,
        colorize_applicable_override,
        colorize_source,
    );
    if colorize_applied {
        let cancel = AtomicBool::new(false);
        pixels = crate::colorize::apply_applicable_with_cancel(
            colorize_source,
            &params.colorize,
            &cancel,
        );
    }
    if let Some((lut, strength)) = creative_lut {
        let lut_source = pixels.as_ref().unwrap_or(source);
        pixels = Some(crate::creative_lut::apply_to_color_image(
            lut_source, &lut, strength,
        ));
    }
    PassthroughRenditionPixels {
        pixels,
        colorize_applied,
    }
}

fn final_effect_colorize_applies(
    colorize: &crate::colorize::ColorizeParams,
    applicable_override: Option<bool>,
    source: &egui::ColorImage,
) -> bool {
    match colorize.mode {
        crate::colorize::ColorizeMode::MonochromeOnly => {
            applicable_override.unwrap_or_else(|| crate::colorize::should_apply(source, colorize))
        }
        _ => crate::colorize::should_apply(source, colorize),
    }
}

fn run_final_effect_job(job: FinalEffectJob, cancel: &AtomicBool) -> FinalEffectResult {
    let started = std::time::Instant::now();
    let mut timing = FinalEffectTiming {
        colorize_mode: job.colorize.mode,
        tone_method: job.colorize.tone_method,
        tone_radius: job.colorize.tone_radius,
        ..FinalEffectTiming::default()
    };
    if cancel.load(Ordering::Relaxed) {
        return FinalEffectResult::Cancelled;
    }
    let stage_started = std::time::Instant::now();
    let adjusted = if let Some(params) = job.adjust_before_effect.as_ref() {
        Arc::new(crate::adjustment::apply_adjustments_fast(
            &job.source,
            params,
        ))
    } else {
        job.source
    };
    timing.adjust_ms = stage_started.elapsed().as_secs_f64() * 1000.0;
    if cancel.load(Ordering::Relaxed) {
        return FinalEffectResult::Cancelled;
    }
    let stage_started = std::time::Instant::now();
    let sharpened = if job.smart_sharpen == 0 {
        adjusted
    } else {
        Arc::new(crate::adjustment::apply_final_smart_sharpen(
            &adjusted,
            job.smart_sharpen,
        ))
    };
    timing.sharpen_ms = stage_started.elapsed().as_secs_f64() * 1000.0;
    if cancel.load(Ordering::Relaxed) {
        return FinalEffectResult::Cancelled;
    }
    let stage_started = std::time::Instant::now();
    timing.colorize_applied =
        final_effect_colorize_applies(&job.colorize, job.colorize_applicable_override, &sharpened);
    timing.colorize_check_ms = stage_started.elapsed().as_secs_f64() * 1000.0;
    let stage_started = std::time::Instant::now();
    let colorized = if timing.colorize_applied {
        match crate::colorize::apply_applicable_with_cancel(&sharpened, &job.colorize, cancel) {
            Some(image) => Arc::new(image),
            None => return FinalEffectResult::Cancelled,
        }
    } else {
        sharpened
    };
    timing.colorize_apply_ms = stage_started.elapsed().as_secs_f64() * 1000.0;
    if cancel.load(Ordering::Relaxed) {
        return FinalEffectResult::Cancelled;
    }
    let stage_started = std::time::Instant::now();
    let lut_applied = if let Some((lut, strength)) = job.creative_lut {
        Arc::new(crate::creative_lut::apply_to_color_image(
            &colorized, &lut, strength,
        ))
    } else {
        colorized
    };
    timing.creative_lut_ms = stage_started.elapsed().as_secs_f64() * 1000.0;
    if cancel.load(Ordering::Relaxed) {
        return FinalEffectResult::Cancelled;
    }
    let stage_started = std::time::Instant::now();
    let pixels = if job.post_filter != crate::adjustment::PostFilter::None {
        Arc::new(crate::post_filter::apply(&lut_applied, job.post_filter))
    } else {
        lut_applied
    };
    timing.post_filter_ms = stage_started.elapsed().as_secs_f64() * 1000.0;
    if cancel.load(Ordering::Relaxed) {
        FinalEffectResult::Cancelled
    } else {
        FinalEffectResult::Ready {
            pixels,
            elapsed_ms: started.elapsed().as_secs_f64() * 1000.0,
            timing,
        }
    }
}

/// 見開きから消しゴムに入ったときのコンテキスト。Apply / Cancel で
/// 元の見開き状態 (= `saved_mode` の spread_mode + `pair.0` を中心ページとした
/// 見開き表示) を復元するために保存する。
#[derive(Clone, Copy, Debug)]
pub(crate) struct EraseSpreadCtx {
    pub saved_mode: crate::settings::SpreadMode,
    /// (left_idx, right_idx)。LTR / RTL のいずれでも「画面上の左/右」の意味で固定。
    pub pair: (usize, usize),
}

/// 見開き表示中に補正パネルが編集対象とするページ (画面上の左/右で固定、
/// LTR/RTL は問わない)。Single (単ページ / 表紙単独 / 横長単独) では参照されず、
/// L/R セレクタも UI 上に出ない。`open_fullscreen` (= ページ送り、ペア切替、
/// 初回フルスクリーン) と spread_mode 切替で `Left` にリセットされる。
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub(crate) enum AdjustSpreadTarget {
    #[default]
    Left,
    Right,
}

/// 仮想フォルダ (PDF/ZIP) 進入時の親 catalog への write-back ターゲット。
/// `start_loading_items` で仮想フォルダ用 catalog を開くタイミングで構築し、
/// `poll_thumbnails` の finalize シグナル経路で発火する。
pub(crate) struct VirtualFolderWriteback {
    pub parent_catalog: Arc<crate::catalog::CatalogDb>,
    /// 親 catalog 側の保存キー (例: `pdfthumb:foo.pdf` / `zipthumb:foo.zip`)。
    pub parent_key: String,
    /// 仮想 catalog 側の対応キー (= cache_map の lookup に使う、例: `page_0000`)。
    pub target_key: String,
    /// 監視対象の items 内 idx (= 最初の PdfPage / ZipImage の idx)。
    pub target_idx: usize,
    /// このターゲットが有効な items 世代。`fire_*` で `App::items_generation` と
    /// 一致しなければ無視 + クリア (Codex P2 対策)。
    ///
    /// `start_loading_items` でも仮想 writeback はクリアされるが、
    /// `replace_search_view_items` (Ctrl+G 検索ビュー切替、`global_search_ui.rs`) や
    /// `remove_items_batch` (削除直後の idx 詰め、`app.rs`) は `items_generation` を
    /// 直接 +1 するだけで `start_loading_items` を通らない。この場で書き戻しが発火
    /// すると古い PDF/ZIP の親 catalog に書いてしまうので、このフィールドが
    /// 実質的な唯一のガードになる。
    pub items_gen: u64,
    /// 現フォルダの cache_map 参照。worker がここに WebP データを put 後、
    /// 本構造体経由で親 catalog にミラーする。
    pub cache_map:
        Arc<std::sync::RwLock<std::collections::HashMap<String, crate::catalog::CacheEntry>>>,
    /// 親 catalog の `pdfthumb:` / `zipthumb:` 行に書き込む mtime / size。
    /// PDF/ZIP **ファイル本体**の mtime / size を入れる (親 grid 表示時の値と一致)。
    pub parent_entry_mtime: i64,
    pub parent_entry_size: i64,
}

