    /// VST3 manager は fullscreen viewport 内の操作パネルなので、開いたままでも
    /// W / Enter / 矢印などの動画ショートカットは使えるようにする。
    pub(crate) fn any_modal_dialog_open_for_fullscreen_keys(&self) -> bool {
        self.common_modal_dialog_open()
    }

    #[cfg(all(windows, feature = "test-script"))]
    pub(crate) fn prepare_test_script_run(&mut self) {
        // A fresh isolated data directory normally opens first-run and migration
        // dialogs. Scripted runs cannot dismiss pointer-driven setup UI, and
        // allowing those dialogs to block input would make an unattended smoke
        // test impossible. Suppress startup-only prompts in memory; never save
        // these choices to the isolated profile.
        self.settings.first_setup_completed = true;
        self.show_mouse_nav_migration_prompt = false;
        self.show_whats_new = false;
    }

    pub(crate) fn clear_fullscreen_tag_picker_state(&mut self) {
        self.fullscreen_tag_picker_open = false;
        self.fullscreen_tag_picker_input.clear();
        self.fullscreen_tag_picker_row_key = None;
        self.fullscreen_tag_picker_focus_request = false;
        self.fullscreen_tag_picker_recent_tab = false;
        self.fullscreen_tag_panel_target_key = None;
        self.fullscreen_tag_panel_sticky_tags.clear();
    }

    pub(crate) fn show_mouse_nav_migration_prompt_dialog(&mut self, ctx: &egui::Context) {
        if !self.show_mouse_nav_migration_prompt {
            return;
        }

        let mut open = true;
        let mut choice = None;
        egui::Window::new("マウス戻る/進むボタン")
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .anchor(egui::Align2::CENTER_CENTER, egui::Vec2::ZERO)
            .show(ctx, |ui| {
                ui.set_min_width(420.0);
                ui.label("マウスの戻る/進むボタンの標準動作を選んでください。");
                ui.add_space(6.0);
                ui.label("標準では、ブラウザやエクスプローラーに近いフォルダ履歴の戻る/進むとして使います。");
                ui.label("従来どおり、ツリー順の前/次フォルダ移動として使うこともできます。");
                ui.add_space(6.0);
                ui.small("後で 環境設定 > マウスボタン から変更できます。");
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if ui.button("標準にする").clicked() {
                        choice = Some(
                            crate::ring_shortcut::MouseBackForwardActionId::FolderHistoryPrevNext,
                        );
                    }
                    if ui.button("従来どおり").clicked() {
                        choice =
                            Some(crate::ring_shortcut::MouseBackForwardActionId::TreeFolderPrevNext);
                    }
                });
            });

        if choice.is_none() && !open {
            choice = Some(crate::ring_shortcut::MouseBackForwardActionId::TreeFolderPrevNext);
        }
        if let Some(action) = choice {
            self.settings
                .ring_shortcuts
                .set_mouse_buttons_from_legacy_pair(action);
            self.settings.ring_shortcuts.mouse_back_forward_action =
                crate::ring_shortcut::MouseBackForwardActionId::None;
            self.settings.ring_shortcuts.mouse_nav_prompt_done = true;
            self.settings.save();
            self.show_mouse_nav_migration_prompt = false;
        }
    }

