    #[cfg(windows)]
    fn take_current_viewer_context_bundle(&mut self) -> ViewerContextBundle {
        let mut bundle = ViewerContextBundle::empty();
        self.swap_viewer_context_bundle(&mut bundle);
        bundle
    }

    #[cfg(windows)]
    fn detached_viewer_suppresses_main_history_persistence(&self) -> bool {
        self.detached_viewer_main_history_suppression_depth > 0
    }

    #[cfg(not(windows))]
    fn detached_viewer_suppresses_main_history_persistence(&self) -> bool {
        false
    }

    #[cfg(windows)]
    fn with_detached_viewer_main_history_suppressed<R>(
        &mut self,
        f: impl FnOnce(&mut Self) -> R,
    ) -> R {
        let previous_depth = self.detached_viewer_main_history_suppression_depth;
        self.detached_viewer_main_history_suppression_depth = previous_depth.saturating_add(1);
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| f(self)));
        self.detached_viewer_main_history_suppression_depth = previous_depth;
        match result {
            Ok(value) => value,
            Err(payload) => std::panic::resume_unwind(payload),
        }
    }

    #[cfg(windows)]
    fn with_active_detached_viewer_context<R>(
        &mut self,
        f: impl FnOnce(&mut Self) -> R,
    ) -> Option<R> {
        let mut active = self.active_detached_viewer_context.take()?;
        self.swap_viewer_context_bundle(&mut active.bundle);
        let previous_depth = self.detached_viewer_main_history_suppression_depth;
        self.detached_viewer_main_history_suppression_depth = previous_depth.saturating_add(1);
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| f(self)));
        self.detached_viewer_main_history_suppression_depth = previous_depth;
        self.swap_viewer_context_bundle(&mut active.bundle);
        self.active_detached_viewer_context = Some(active);
        match result {
            Ok(value) => Some(value),
            Err(payload) => std::panic::resume_unwind(payload),
        }
    }

    /// 現在マウント中のコンテキストの thumb 結果チャネル (`self.rx`) を読み捨てる。
    /// グリッドを描かない detached context 用 (review-v2.3.0 P2-9): channel を bundle 化した
    /// ことで、detached context のロードが spawn した worker の結果 (ZIP 内動画サムネ等) は
    /// その context の rx に届くが、poll_thumbnails を回さないため放置するとバッファが
    /// 溜まり続ける。表示予定が無いので捨てる。detached での panorama 高解像度アップグレード
    /// も同 channel 経由だが、これは bundle 化前から detached では機能していない経路
    /// (main mount 中の poll で世代不一致 drop) なので挙動退行にはならない。
    fn drain_thumb_results_discard(&mut self) {
        while self.rx.try_recv().is_ok() {}
    }

    pub(crate) fn effective_folder(&self) -> Option<PathBuf> {
        if self.items_are_drive_list {
            None
        } else {
            self.archive_source_override
                .clone()
                .or_else(|| self.current_folder.clone())
        }
    }

    pub(crate) fn current_location_root(&self) -> Option<PathBuf> {
        location_root_for_path(&self.effective_folder()?)
    }

    pub(crate) fn active_drive_current_dir(&self, letter: char) -> Option<PathBuf> {
        let key = drive_current_key_for_letter(letter)?;
        self.active_quick_folder_workspace()?
            .drive_current_dirs
            .get(&key)
            .cloned()
    }

    /// アイテムの UI 表示用フルパス。変換キャッシュ閲覧中 (`archive_source_override`)
    /// は ZIP 内アイテムのコンテナ部分をユーザー視点の元アーカイブパスへ置き換える。
    #[cfg(test)]
    pub(crate) fn user_facing_display_path(&self, item: &GridItem) -> String {
        if let (Some(src), Some(cur)) = (
            self.archive_source_override.as_ref(),
            self.current_folder.as_ref(),
        ) {
            match item {
                GridItem::ZipImage {
                    zip_path,
                    entry_name,
                } if crate::folder_tree::path_eq(zip_path, cur) => {
                    return format!("{}:{}", src.display(), entry_name);
                }
                GridItem::ZipDir {
                    zip_path,
                    dir_prefix,
                    ..
                } if crate::folder_tree::path_eq(zip_path, cur) => {
                    return format!("{}:{}", src.display(), dir_prefix);
                }
                _ => {}
            }
        }
        item.display_path()
    }

    /// グリッド上の「親へ戻る」操作 (Backspace / Alt+↑ / ツールバー⬆ / Pad B) の
    /// 共通ナビゲーション先を返す。ドライブルートでは親 `Path` が無いので、ドライブ
    /// 一覧へ戻す専用ナビを返す。
    /// 閲覧履歴ビューから開いた本を「親へ戻る」操作で閉じるとき、実ディレクトリではなく
    /// 閲覧履歴ビューへ戻す。本の effective パスにいる間だけ有効 (深い階層では None)。
    pub(crate) fn reading_history_back_nav(&self) -> Option<crate::ui_main::AddressBarNav> {
        // ネスト ZIP の深い階層では本のルート扱いにしない。effective_folder() は深さに
        // 関わらず root ZIP のままなので、zip_nav の深さで明示的に弾く (root に戻ってから
        // 閲覧履歴へ抜ける。docs「深い階層では通常の親へ」と整合させる。Esc 直帰経路も同じ)。
        if self.zip_nav.as_ref().is_some_and(|n| !n.at_root()) {
            return None;
        }
        let from = self.reading_history_return_from.as_ref()?;
        let cur = self.effective_folder()?;
        crate::folder_tree::path_eq(&cur, from)
            .then_some(crate::ui_main::AddressBarNav::ReadingHistory)
    }

    /// 横断ブックマーク一覧から直接開いた本・動画・音声を閉じるときだけ、
    /// 実ファイルの親ではなく一覧へ戻す。ページ identity を直接開く操作なので、
    /// ネスト ZIP 内でも現在のユーザー視点コンテナが一致すれば一覧へ直帰する。
    pub(crate) fn bookmark_view_back_nav(&self) -> Option<crate::ui_main::AddressBarNav> {
        let BookmarkViewState::Opening { target, .. } = self.bookmark_view_state.as_ref()? else {
            return None;
        };
        self.bookmark_target_is_current(target)
            .then_some(crate::ui_main::AddressBarNav::Bookmarks)
    }

    fn bookmark_target_is_current(
        &self,
        target: &crate::bookmark_browser::BookmarkViewReturnTarget,
    ) -> bool {
        let still_at_target = match target {
            crate::bookmark_browser::BookmarkViewReturnTarget::Media(target_path) => self
                .fullscreen_idx
                .and_then(|idx| self.items.get(idx))
                .is_some_and(|item| match item {
                    GridItem::Video(path) | GridItem::Audio(path) => {
                        crate::path_key::eq_keep_drive(path, target_path)
                    }
                    _ => false,
                }),
            crate::bookmark_browser::BookmarkViewReturnTarget::Book(container_path) => self
                .effective_folder()
                .is_some_and(|current| crate::path_key::eq_keep_drive(&current, container_path)),
        };
        still_at_target
    }

    pub(crate) fn clear_bookmark_view_return_state(&mut self) {
        self.bookmark_view_state = None;
    }

    fn reconcile_bookmark_return_target_for_folder_load(&mut self, path: &Path) {
        let should_clear = match self.bookmark_view_state.as_ref() {
            Some(BookmarkViewState::Opening { target, .. }) => {
                !target.matches_loaded_container(path)
            }
            Some(BookmarkViewState::Detached {
                target: target @ crate::bookmark_browser::BookmarkViewReturnTarget::Media(_),
            }) => !target.matches_loaded_container(path),
            // A detached book owns all navigation inside its own context. The origin bookmark
            // grid stays mounted in main even when the reader moves to another page/container.
            Some(BookmarkViewState::Detached {
                target: crate::bookmark_browser::BookmarkViewReturnTarget::Book(_),
            })
            | Some(BookmarkViewState::Restoring { .. })
            | None => false,
        };
        if should_clear {
            self.clear_bookmark_view_return_state();
        }
    }

    fn bookmark_view_close_nav(&mut self) -> Option<crate::ui_main::AddressBarNav> {
        let nav = self.bookmark_view_back_nav();
        if nav.is_none()
            && matches!(
                self.bookmark_view_state,
                Some(BookmarkViewState::Opening { .. })
            )
        {
            self.clear_bookmark_view_return_state();
        }
        nav
    }

    pub(crate) fn bookmark_view_target(
        &self,
    ) -> Option<&crate::bookmark_browser::BookmarkViewReturnTarget> {
        self.bookmark_view_state
            .as_ref()
            .and_then(BookmarkViewState::target)
    }

    fn bookmark_view_begin_restore(&mut self) {
        let Some(state) = self.bookmark_view_state.take() else {
            return;
        };
        self.bookmark_view_state = match state {
            BookmarkViewState::Opening { grid, .. } | BookmarkViewState::Restoring { grid } => {
                Some(BookmarkViewState::Restoring { grid })
            }
            detached @ BookmarkViewState::Detached { .. } => Some(detached),
        };
    }

    fn take_bookmark_restore_grid(&mut self) -> Option<BookmarkViewReturnGridState> {
        match self.bookmark_view_state.take() {
            Some(BookmarkViewState::Restoring { grid }) => Some(grid),
            Some(other) => {
                self.bookmark_view_state = Some(other);
                None
            }
            None => None,
        }
    }

    /// 閲覧履歴ビューの項目を開く直前に、消えたコンテナへ入らないようにする。
    ///
    /// 表示直後に履歴全体を検査すると、外付けドライブやネットワークパスで UI が重くなったり、
    /// 後から件数が変わって行がずれる体験になる。ここではユーザーが実際に開こうとした
    /// 1 件だけを軽く確認する。missing は外付け切断や NAS offline と区別できないため、
    /// 現在のビューにも DB にも破壊的変更を加えない。
    pub(crate) fn guard_reading_history_open(&mut self, idx: usize) -> bool {
        if !self.items_are_reading_history_view {
            return true;
        }
        let Some((path, key)) = self.items.get(idx).and_then(|item| {
            let path = match item {
                GridItem::Video(path) | GridItem::Audio(path) => Some(path.clone()),
                GridItem::Folder(_)
                | GridItem::ZipFile(_)
                | GridItem::PdfFile(_)
                | GridItem::ConvertibleArchive { .. } => {
                    item.container_path().map(|path| path.to_path_buf())
                }
                _ => None,
            }?;
            Some((path, reading_history_key_for_item(item)))
        }) else {
            return true;
        };

        match reading_history_open_path_status(&path) {
            ReadingHistoryOpenPathStatus::Available => true,
            ReadingHistoryOpenPathStatus::Missing => {
                self.show_feedback_toast(
                    "ファイルが見つかりません。閲覧履歴は保持されています".to_string(),
                );
                let _ = key;
                false
            }
            ReadingHistoryOpenPathStatus::Unavailable => {
                self.show_feedback_toast(
                    "ファイルにアクセスできません。外付けドライブが未接続の可能性があります"
                        .to_string(),
                );
                false
            }
        }
    }

    /// グリッドからコンテナを開いたときに、閲覧履歴ビューへの戻り先予約を更新する。
    ///
    /// - 閲覧履歴ビューで本 (コンテナ) を開いた → その本へ戻り先を焼き付ける。
    /// - 閲覧履歴ビュー以外で別のコンテナを開いた → 古い予約を捨てる (別の本/フォルダへ
    ///   出たので、以後 Backspace は閲覧履歴ではなく通常の親フォルダへ向かう)。
    /// - 画像 / ページ等 (非コンテナ) のオープンでは予約を変えない (= 本の中でページを
    ///   読んでいるだけなので戻り先を保持する)。
    pub(crate) fn note_reading_history_open(&mut self, idx: usize) {
        let Some(item) = self.items.get(idx) else {
            return;
        };
        let is_container = matches!(
            item,
            GridItem::Folder(_)
                | GridItem::ZipFile(_)
                | GridItem::PdfFile(_)
                | GridItem::ConvertibleArchive { .. }
        );
        if !is_container {
            return;
        }
        if self.items_are_reading_history_view {
            self.reading_history_return_from = item.container_path().map(|p| p.to_path_buf());
        } else {
            self.reading_history_return_from = None;
        }
    }

    pub(crate) fn grid_parent_nav_target(&self) -> Option<crate::ui_main::AddressBarNav> {
        if let Some(nav) = self.bookmark_view_back_nav() {
            return Some(nav);
        }
        if let Some(nav) = self.reading_history_back_nav() {
            return Some(nav);
        }
        if self.items_are_bookmark_view || self.bookmark_browser_pending.is_some() {
            return self
                .folder_history_back_target()
                .is_some()
                .then_some(crate::ui_main::AddressBarNav::HistoryBack);
        }
        if self.rating_view_parent_nav_available() {
            return Some(crate::ui_main::AddressBarNav::RatingViewBack);
        }
        if let Some(nav) = self.subfolder_expansion_back_nav() {
            return Some(nav);
        }
        if let Some(nav) = self.smart_folder_parent_nav_target() {
            return Some(nav);
        }
        if self.items_are_smart_folder_view {
            return None;
        }
        let cur = self.effective_folder()?;
        if let Some(parent) = cur.parent() {
            Some(crate::ui_main::AddressBarNav::Direct(parent.to_path_buf()))
        } else {
            Some(crate::ui_main::AddressBarNav::DriveList(Some(cur)))
        }
    }

    pub(crate) fn resolve_grid_parent_nav(&mut self) -> Option<crate::ui_main::AddressBarNav> {
        if let Some(nav) = self.bookmark_view_back_nav() {
            return Some(nav);
        }
        if let Some(nav) = self.reading_history_back_nav() {
            return Some(nav);
        }
        if self.items_are_bookmark_view || self.bookmark_browser_pending.is_some() {
            return self
                .folder_history_back_target()
                .is_some()
                .then_some(crate::ui_main::AddressBarNav::HistoryBack);
        }
        if self.rating_view_parent_nav_available() {
            return Some(crate::ui_main::AddressBarNav::RatingViewBack);
        }
        if let Some(nav) = self.subfolder_expansion_back_nav() {
            return Some(nav);
        }
        if let Some(nav) = self.smart_folder_parent_nav_target() {
            if let crate::ui_main::AddressBarNav::Direct(path) = &nav
                && !smart_folder::is_smart_folder_synthetic_path(path)
            {
                self.authorize_smart_folder_session_open(path);
                self.select_after_load = self
                    .effective_folder()
                    .and_then(|current| current.file_name().map(|name| name.to_os_string()))
                    .and_then(|name| name.to_str().map(str::to_string));
            }
            return Some(nav);
        }
        if self.items_are_smart_folder_view {
            return None;
        }
        let cur = self.effective_folder()?;
        let nav = if let Some(parent) = cur.parent() {
            self.select_after_load = cur
                .file_name()
                .and_then(|n| n.to_str())
                .map(|s| s.to_string());
            crate::ui_main::AddressBarNav::Direct(parent.to_path_buf())
        } else {
            crate::ui_main::AddressBarNav::DriveList(Some(cur))
        };
        Some(nav)
    }

    #[cfg(windows)]
    fn close_detached_viewer_for_virtual_page_list_parent_nav(&mut self) {
        let in_virtual_page_list = self
            .current_folder
            .as_deref()
            .is_some_and(crate::folder_tree::is_open_as_container);
        if in_virtual_page_list && self.viewer_session_is_detached() {
            // virtual page list (本の中の親) から detached を閉じる = セッション終了 (§3.7)。
            #[cfg(windows)]
            {
                self.begin_active_detached_session_close("virtual_page_list_parent_nav");
                self.finish_active_detached_session_close("virtual_page_list_parent_nav");
            }
            self.close_fullscreen();
        }
    }

    /// `pending_return_to_parent` (「ページを直接開く」設定 ON の ZIP/PDF、または
    /// 追加設定 ON の画像のみ通常フォルダで Esc/Enter/右クリックから立つ
    /// 「親フォルダ (一覧) へ戻る」予約) を消化したときの
    /// ナビ先を返す。
    ///
    /// **変換アーカイブ対応 (Codex P1)**: 変換済み RAR/7z/LZH 閲覧中は `current_folder` が
    /// キャッシュ ZIP (`%APPDATA%\...\archive_cache\..\book.zip`) を指す。そのまま
    /// `current_folder.parent()` へ戻すとキャッシュフォルダへ飛んでしまうため、ユーザー
    /// 視点の元 `.lzh` / `.7z` を返す `effective_folder()` を基準に親を取る (通常 ZIP/PDF
    /// では `effective_folder() == current_folder` なので挙動不変)。親が取れない
    /// (ドライブ root 等) ときは `None` を返し、呼び出し側が close にフォールバックする。
    pub(crate) fn resolve_return_to_parent_nav(&mut self) -> Option<crate::ui_main::AddressBarNav> {
        if let Some(nav) = self.bookmark_view_back_nav() {
            return Some(nav);
        }
        if let Some(nav) = self.reading_history_back_nav() {
            return Some(nav);
        }
        if self.rating_view_parent_nav_available() {
            return Some(crate::ui_main::AddressBarNav::RatingViewBack);
        }
        if let Some(nav) = self.subfolder_expansion_back_nav() {
            return Some(nav);
        }
        if let Some(nav) = self.smart_folder_parent_nav_target() {
            if let crate::ui_main::AddressBarNav::Direct(path) = &nav
                && !smart_folder::is_smart_folder_synthetic_path(path)
            {
                self.authorize_smart_folder_session_open(path);
            }
            return Some(nav);
        }
        if self.items_are_smart_folder_view {
            return None;
        }
        let cur = self.effective_folder()?;
        let parent = cur.parent()?;
        self.select_after_load = cur
            .file_name()
            .and_then(|n| n.to_str())
            .map(|s| s.to_string());
        Some(crate::ui_main::AddressBarNav::Direct(parent.to_path_buf()))
    }

    pub(crate) fn take_pending_return_to_parent_nav(
        &mut self,
    ) -> Option<crate::ui_main::AddressBarNav> {
        if !std::mem::take(&mut self.pending_return_to_parent) {
            return None;
        }
        if let Some(nav) = self.resolve_return_to_parent_nav() {
            return Some(nav);
        }
        // 親が取れない (ドライブ root 等): 予約は消化済みなので通常 close にフォールバック。
        #[cfg(windows)]
        let detached_video_preserved = self.promote_active_detached_video_for_main_context_change();
        #[cfg(not(windows))]
        let detached_video_preserved = false;
        #[cfg(windows)]
        if !detached_video_preserved {
            self.preserve_active_detached_image_window_for_main_context_change();
        }
        if !detached_video_preserved {
            self.close_fullscreen();
        }
        None
    }

    /// Early-return 経路で `pending_return_to_parent` 由来のナビを消化する。
    ///
    /// 通常は App::update 後段の input_nav 合流点で処理するが、Windows の
    /// in-window 静止画フルスクリーンはグリッド描画を飛ばして return するため、
    /// そこでナビを捨てないよう同じロード処理を先に適用する。
    pub(crate) fn apply_fullscreen_close_nav_immediate(
        &mut self,
        nav: crate::ui_main::AddressBarNav,
    ) -> bool {
        match nav {
            crate::ui_main::AddressBarNav::Direct(path) => {
                self.load_folder_or_convert_archive(path);
                self.clear_pending_folder_nav_steps();
                true
            }
            crate::ui_main::AddressBarNav::DriveList(origin) => {
                self.enter_drive_list_from_navigation(origin);
                true
            }
            crate::ui_main::AddressBarNav::ReadingHistory => {
                self.enter_reading_history();
                true
            }
            crate::ui_main::AddressBarNav::Bookmarks => {
                self.enter_bookmark_view();
                true
            }
            crate::ui_main::AddressBarNav::RatingViewBack => {
                self.rating_view_parent_nav();
                true
            }
            crate::ui_main::AddressBarNav::BooksRoot => {
                self.open_books_root();
                true
            }
            crate::ui_main::AddressBarNav::HistoryBack
            | crate::ui_main::AddressBarNav::HistoryForward => false,
        }
    }

    pub(crate) fn local_search_blocks_parent_nav(&self) -> bool {
        self.show_search_bar
            && (self.search_filter.is_some() || self.search_pending.is_some())
            && self
                .search_filter_origin_folder
                .as_ref()
                .is_some_and(|origin| {
                    self.effective_folder()
                        .as_ref()
                        .is_some_and(|cur| crate::folder_tree::path_eq(cur, origin))
                })
    }

    fn normalize_folder_nav_rating_metadata(
        stack: &[PathBuf],
        rating_view_stars: &mut Vec<Option<u8>>,
        smart_folder_states: &mut Vec<Option<top_level_grid_view::SmartFolderViewState>>,
    ) {
        rating_view_stars.resize(stack.len(), None);
        smart_folder_states.resize(stack.len(), None);
    }

    fn folder_nav_targets_eq(
        left: &Path,
        left_rating_view_stars: Option<u8>,
        left_smart_folder_state: Option<&top_level_grid_view::SmartFolderViewState>,
        right: &Path,
        right_rating_view_stars: Option<u8>,
        right_smart_folder_state: Option<&top_level_grid_view::SmartFolderViewState>,
    ) -> bool {
        if !crate::folder_tree::path_eq(left, right) {
            return false;
        }
        if crate::folder_tree::path_eq(left, &rating_view_synthetic_path()) {
            left_rating_view_stars == right_rating_view_stars
        } else if smart_folder::is_smart_folder_synthetic_path(left) {
            left_smart_folder_state == right_smart_folder_state
        } else {
            true
        }
    }

    fn push_folder_nav_stack(
        stack: &mut Vec<PathBuf>,
        rating_view_stars: &mut Vec<Option<u8>>,
        smart_folder_states: &mut Vec<Option<top_level_grid_view::SmartFolderViewState>>,
        path: PathBuf,
        stars: Option<u8>,
        smart_folder_state: Option<top_level_grid_view::SmartFolderViewState>,
    ) {
        Self::normalize_folder_nav_rating_metadata(stack, rating_view_stars, smart_folder_states);
        if stack.last().is_some_and(|last| {
            Self::folder_nav_targets_eq(
                last,
                rating_view_stars.last().copied().flatten(),
                smart_folder_states.last().and_then(Option::as_ref),
                &path,
                stars,
                smart_folder_state.as_ref(),
            )
        }) {
            if let Some(last) = smart_folder_states.last_mut() {
                *last = smart_folder_state;
            }
            return;
        }
        stack.push(path);
        rating_view_stars.push(stars);
        smart_folder_states.push(smart_folder_state);
        if stack.len() > MAX_FOLDER_NAV_STACK {
            stack.remove(0);
            rating_view_stars.remove(0);
            smart_folder_states.remove(0);
        }
    }

    fn pop_folder_nav_stack(
        stack: &mut Vec<PathBuf>,
        rating_view_stars: &mut Vec<Option<u8>>,
        smart_folder_states: &mut Vec<Option<top_level_grid_view::SmartFolderViewState>>,
    ) -> Option<(
        PathBuf,
        Option<u8>,
        Option<top_level_grid_view::SmartFolderViewState>,
    )> {
        Self::normalize_folder_nav_rating_metadata(stack, rating_view_stars, smart_folder_states);
        let path = stack.pop()?;
        let stars = rating_view_stars.pop().flatten();
        let smart_folder_state = smart_folder_states.pop().flatten();
        Some((path, stars, smart_folder_state))
    }

    fn active_quick_folder_workspace(&self) -> Option<&QuickFolderWorkspace> {
        self.active_quick_folder_slot
            .map(|slot| &self.quick_folder_workspaces[slot.index()])
    }

    fn active_quick_folder_workspace_mut(&mut self) -> Option<&mut QuickFolderWorkspace> {
        self.active_quick_folder_slot
            .map(|slot| &mut self.quick_folder_workspaces[slot.index()])
    }

    fn push_active_folder_nav_back_stack(
        &mut self,
        path: PathBuf,
        stars: Option<u8>,
        smart_folder_state: Option<top_level_grid_view::SmartFolderViewState>,
    ) {
        if let Some(workspace) = self.active_quick_folder_workspace_mut() {
            Self::push_folder_nav_stack(
                &mut workspace.history.back_stack,
                &mut workspace.history.back_rating_view_stars,
                &mut workspace.history.back_smart_folder_states,
                path,
                stars,
                smart_folder_state,
            );
        } else {
            Self::push_folder_nav_stack(
                &mut self.folder_nav_back_stack,
                &mut self.folder_nav_back_rating_view_stars,
                &mut self.folder_nav_back_smart_folder_states,
                path,
                stars,
                smart_folder_state,
            );
        }
    }

    fn clear_active_folder_nav_forward_stack(&mut self) {
        if let Some(workspace) = self.active_quick_folder_workspace_mut() {
            workspace.history.forward_stack.clear();
            workspace.history.forward_rating_view_stars.clear();
            workspace.history.forward_smart_folder_states.clear();
        } else {
            self.folder_nav_forward_stack.clear();
            self.folder_nav_forward_rating_view_stars.clear();
            self.folder_nav_forward_smart_folder_states.clear();
        }
    }

    fn take_active_folder_nav_suppress_record_once(&mut self) -> bool {
        if let Some(workspace) = self.active_quick_folder_workspace_mut() {
            std::mem::take(&mut workspace.history.suppress_record_once)
        } else {
            std::mem::take(&mut self.suppress_folder_nav_record_once)
        }
    }

    pub(crate) fn set_active_folder_nav_suppress_record_once(&mut self, value: bool) {
        if let Some(workspace) = self.active_quick_folder_workspace_mut() {
            workspace.history.suppress_record_once = value;
        } else {
            self.suppress_folder_nav_record_once = value;
        }
    }

    fn sync_quick_folder_settings(&mut self) {
        self.settings.quick_folder_slots =
            std::array::from_fn(|idx| self.quick_folder_workspaces[idx].target.clone());
        self.settings.quick_folder_recent_folders =
            std::array::from_fn(|idx| self.quick_folder_workspaces[idx].recent_folders.clone());
        self.settings.quick_folder_drive_current_dirs =
            std::array::from_fn(|idx| self.quick_folder_workspaces[idx].drive_current_dirs.clone());
        // 後方互換: 旧 `recent_folders` には主スロット A の一覧を残す
        // (旧バージョンへダウングレードしても最近フォルダが空にならないように)。
        self.settings.recent_folders = self.quick_folder_workspaces[QuickFolderSlotId::A.index()]
            .recent_folders
            .clone();
    }

    /// 最近開いたフォルダ MRU へのエントリ追加 (重複除去 + 先頭挿入 + 上限切り詰め)。
    fn push_recent_folder_entry(list: &mut Vec<PathBuf>, path: &Path) {
        list.retain(|p| !crate::folder_tree::path_eq(p, path));
        list.insert(0, path.to_path_buf());
        list.truncate(MAX_RECENT_FOLDERS);
    }

    /// アクティブスロットの最近開いたフォルダ一覧から `path` を取り除く
    /// (変換キャッシュ ZIP のパスを履歴に残さない等)。
    pub(crate) fn forget_recent_folder(&mut self, path: &Path) {
        if let Some(workspace) = self.active_quick_folder_workspace_mut() {
            workspace
                .recent_folders
                .retain(|p| !crate::folder_tree::path_eq(p, path));
        } else {
            self.recent_folders
                .retain(|p| !crate::folder_tree::path_eq(p, path));
        }
    }

    pub(crate) fn quick_folder_target(&self, slot: QuickFolderSlotId) -> Option<&PathBuf> {
        self.quick_folder_workspaces[slot.index()].target.as_ref()
    }

    #[cfg(test)]
    pub(crate) fn current_quick_folder_target(&self) -> Option<PathBuf> {
        if self.items_are_drive_list
            || self.show_search_bar
            || self.search_filter.is_some()
            || self.search_pending.is_some()
            || self.global_search.active
            || self.favsearch.active
            || self.tag_view.active
            || self.items_are_global_search_view
            || self.items_are_tag_view
            || self.items_are_rating_view
            || self.is_snapshot_active()
        {
            return None;
        }
        let target = self.effective_folder()?;
        if is_synthetic_view_path(&target) {
            return None;
        }
        Some(target)
    }

    #[cfg(test)]
    pub(crate) fn set_quick_folder_slot_target(
        &mut self,
        slot: QuickFolderSlotId,
        target: PathBuf,
    ) {
        let workspace = &mut self.quick_folder_workspaces[slot.index()];
        workspace.target = Some(target.clone());
        if let Some(key) = drive_current_key_for_path(&target) {
            workspace.drive_current_dirs.insert(key, target);
        }
        self.active_quick_folder_slot = Some(slot);
        self.sync_quick_folder_settings();
    }

    #[cfg(test)]
    pub(crate) fn clear_quick_folder_slot(&mut self, slot: QuickFolderSlotId) {
        let workspace = &mut self.quick_folder_workspaces[slot.index()];
        workspace.target = None;
        workspace.history = FolderNavHistoryState::default();
        workspace.drive_current_dirs.clear();
        self.sync_quick_folder_settings();
    }

    pub(crate) fn clear_quick_folder_slots(&mut self) {
        for workspace in &mut self.quick_folder_workspaces {
            *workspace = QuickFolderWorkspace::default();
        }
        self.active_quick_folder_slot = Some(QuickFolderSlotId::A);
        self.sync_quick_folder_settings();
    }

    pub(crate) fn activate_quick_folder_slot(
        &mut self,
        slot: QuickFolderSlotId,
    ) -> QuickFolderSwitchTarget {
        let target = self.quick_folder_target(slot).cloned();
        self.cancel_pending_folder_nav();
        self.active_quick_folder_slot = Some(slot);
        match target {
            Some(target) => {
                if !self.items_are_drive_list
                    && self
                        .effective_folder()
                        .is_some_and(|current| crate::folder_tree::path_eq(&current, &target))
                {
                    QuickFolderSwitchTarget::Current
                } else {
                    self.set_active_folder_nav_suppress_record_once(true);
                    QuickFolderSwitchTarget::Folder(target)
                }
            }
            None if self.items_are_drive_list => QuickFolderSwitchTarget::Current,
            None => {
                // A/B 切替自体は履歴に積まない。DriveList の通常入口が行う履歴記録を
                // 新しく active になった空スロット側で 1 回だけ抑止する。
                self.set_active_folder_nav_suppress_record_once(true);
                QuickFolderSwitchTarget::DriveList
            }
        }
    }

    pub(crate) fn update_active_quick_folder_target(&mut self, target: &Path) {
        // 合成ビューは一時的な current_folder marker。A/B の永続ターゲットへ保存しない。
        if is_synthetic_view_path(target) {
            return;
        }
        if let Some(slot) = self.active_quick_folder_slot {
            let workspace = &mut self.quick_folder_workspaces[slot.index()];
            workspace.target = Some(target.to_path_buf());
            if let Some(key) = drive_current_key_for_path(target) {
                workspace
                    .drive_current_dirs
                    .insert(key, target.to_path_buf());
            }
            self.sync_quick_folder_settings();
        }
    }

    /// 明示した移動元 `from` を「戻る」履歴へ積み、「進む」履歴をクリアする。
    /// `record_folder_nav_transition` の自動記録では移動元が正しく取れないケース
    /// (検索から「フォルダに移動」で抜ける等) に、呼び出し側が確定した移動元を渡す。
    pub(crate) fn push_nav_history_entry(&mut self, from: PathBuf) {
        self.push_active_folder_nav_back_stack(from, None, None);
        self.clear_active_folder_nav_forward_stack();
    }

    pub(crate) fn remember_recent_folder(&mut self, path: &Path) {
        // 合成ビューは「履歴▼」の永続 MRU には保存しない。←/→ の session 履歴だけで扱う。
        if is_synthetic_view_path(path) {
            return;
        }
        // 検索 (Ctrl+G / Ctrl+S / Ctrl+T) 中は recent_folders を一切変更しない。
        // record_folder_nav_transition 以外に archive_convert などが直接呼ぶため、
        // recent_folders を汚さないチョークポイントをここに置く。
        if self.global_search.active || self.favsearch.active || self.tag_view.active {
            return;
        }
        // アクティブな A/B スロットごとに最近開いたフォルダ一覧を分離する。
        if let Some(workspace) = self.active_quick_folder_workspace_mut() {
            Self::push_recent_folder_entry(&mut workspace.recent_folders, path);
        } else {
            Self::push_recent_folder_entry(&mut self.recent_folders, path);
        }
        self.sync_quick_folder_settings();
    }

    pub(crate) fn clear_recent_folders(&mut self) {
        for workspace in &mut self.quick_folder_workspaces {
            workspace.recent_folders.clear();
        }
        self.recent_folders.clear();
        self.sync_quick_folder_settings();
    }

    /// `load_folder*` 入口で呼ぶ。現在地から `target` への遷移を履歴に記録する。
    ///
    /// ここで扱う履歴はスクロール復元用の `folder_history` とは別物で、
    /// ユーザーがフォルダバーの ←/→ や履歴メニューで辿るためのもの。
    fn record_folder_nav_transition(&mut self, target: &Path) {
        self.record_folder_nav_transition_with_rating(target, None);
    }

    /// Record a completed transition using an origin whose ownership was transferred from a
    /// transient view (for example smart A -> Ctrl+G results -> smart B). The result grid's
    /// synthetic marker must never become the Back target.
    pub(crate) fn record_folder_nav_transition_from_restore(
        &mut self,
        target: &Path,
        from: &top_level_grid_view::TopLevelGridRestore,
    ) {
        let Some(path) = from.legacy_path() else {
            return;
        };
        let rating_view_stars = from.rating_stars();
        let smart_folder_state = match from {
            top_level_grid_view::TopLevelGridRestore::SmartFolder(state) => Some(state.clone()),
            _ => None,
        };
        self.record_folder_nav_transition_from_current(
            target,
            None,
            self.top_level_grid_view.smart_folder().cloned(),
            Some(path),
            rating_view_stars,
            smart_folder_state,
        );
    }

    fn folder_nav_current_location(&self) -> Option<PathBuf> {
        if let Some(state) = self.top_level_grid_view.smart_folder() {
            Some(smart_folder::smart_folder_synthetic_path(
                state.definition_id,
            ))
        } else if self.items_are_drive_list {
            Some(drive_list_synthetic_path())
        } else {
            self.effective_folder()
        }
    }

    fn folder_nav_rating_view_stars_for_path(&self, path: &Path) -> Option<u8> {
        (crate::folder_tree::path_eq(path, &rating_view_synthetic_path())
            && (1..=5).contains(&self.rating_view_stars))
        .then_some(self.rating_view_stars)
    }

    pub(crate) fn view_return_rating_view_stars_for_path(&self, path: Option<&Path>) -> Option<u8> {
        path.and_then(|path| self.folder_nav_rating_view_stars_for_path(path))
    }

    pub(crate) fn view_return_context_from_parts(
        &self,
        path: Option<PathBuf>,
        subfolder_restore: Option<subfolder_expansion::SubfolderExpansionRestoreState>,
        rating_view_stars: Option<u8>,
    ) -> top_level_grid_view::TopLevelGridRestore {
        top_level_grid_view::TopLevelGridRestore::from_legacy_parts(
            path,
            subfolder_restore,
            rating_view_stars,
            self.top_level_grid_view.smart_folder().cloned(),
        )
    }

    pub(crate) fn current_top_level_restore_snapshot(
        &self,
    ) -> Option<top_level_grid_view::TopLevelGridRestore> {
        use top_level_grid_view::{TopLevelGridRestore, TopLevelGridSurface};

        if let Some(return_to) = self.top_level_grid_view.return_to() {
            return Some(return_to.clone());
        }
        match self.top_level_grid_view.surface() {
            TopLevelGridSurface::SmartFolder(state) => {
                Some(TopLevelGridRestore::SmartFolder(state.clone()))
            }
            TopLevelGridSurface::SubfolderExpansion => {
                Some(TopLevelGridRestore::SubfolderExpansion(
                    subfolder_expansion::SubfolderExpansionRestoreState {
                        root: self.subfolder_expansion_root.clone(),
                        roots: self.subfolder_expansion_roots.clone(),
                        saved_folder: self.subfolder_expansion_saved_folder.clone(),
                        snapshot: self.subfolder_expansion_snapshot.clone(),
                        removed_paths: self.subfolder_expansion_removed_paths.clone(),
                    },
                ))
            }
            TopLevelGridSurface::DriveList => Some(TopLevelGridRestore::DriveList),
            TopLevelGridSurface::ReadingHistory => Some(TopLevelGridRestore::ReadingHistory),
            TopLevelGridSurface::Bookmarks => Some(TopLevelGridRestore::Bookmarks),
            TopLevelGridSurface::Rating { stars } => {
                Some(TopLevelGridRestore::Rating { stars: *stars })
            }
            TopLevelGridSurface::Search(_) | TopLevelGridSurface::Snapshot => None,
            TopLevelGridSurface::Folder => self.folder_nav_current_location().map(|path| {
                self.view_return_context_from_parts(
                    Some(path.clone()),
                    None,
                    self.view_return_rating_view_stars_for_path(Some(&path)),
                )
            }),
        }
    }

    fn record_folder_nav_transition_with_rating(
        &mut self,
        target: &Path,
        target_rating_view_stars: Option<u8>,
    ) {
        let current = self.folder_nav_current_location();
        let current_rating_view_stars = current
            .as_deref()
            .and_then(|path| self.folder_nav_rating_view_stars_for_path(path));
        let current_smart_folder_state = self.top_level_grid_view.smart_folder().cloned();
        self.record_folder_nav_transition_from_current(
            target,
            target_rating_view_stars,
            None,
            current,
            current_rating_view_stars,
            current_smart_folder_state,
        );
    }

    /// スマートフォルダ内で root / scoped current が変わる直前の位置を履歴へ積む。
    /// path は同じ synthetic marker のままなので、`SmartFolderViewState` の差を
    /// 履歴地点の identity として扱う。
    pub(crate) fn record_smart_folder_scope_transition(
        &mut self,
        target_state: &top_level_grid_view::SmartFolderViewState,
    ) {
        let Some(current_state) = self.top_level_grid_view.smart_folder().cloned() else {
            return;
        };
        if current_state == *target_state {
            return;
        }
        let synthetic = smart_folder::smart_folder_synthetic_path(current_state.definition_id);
        self.record_folder_nav_transition_from_current(
            &synthetic,
            None,
            Some(target_state.clone()),
            Some(synthetic.clone()),
            None,
            Some(current_state),
        );
    }

    fn record_folder_nav_transition_from_current(
        &mut self,
        target: &Path,
        target_rating_view_stars: Option<u8>,
        target_smart_folder_state: Option<top_level_grid_view::SmartFolderViewState>,
        current: Option<PathBuf>,
        current_rating_view_stars: Option<u8>,
        current_smart_folder_state: Option<top_level_grid_view::SmartFolderViewState>,
    ) {
        if self.detached_viewer_suppresses_main_history_persistence() {
            self.suppress_nav_record_for_search_restore = false;
            self.set_active_folder_nav_suppress_record_once(false);
            return;
        }
        // 検索 (Ctrl+G / Ctrl+S / Ctrl+T) 中の移動、および検索クローズによる検索前フォルダへの
        // 復帰は履歴 (back/forward/recent) に一切残さない。検索は透明な一時オーバーレイ
        // であり、抜けると検索前の状態に完全復帰する。`suppress_nav_record_for_search_restore`
        // は close_* が active を false にしてから load_folder(saved) を呼ぶ取りこぼしを補う
        // ワンショット (短絡で消費漏れしないよう先に take しておく)。
        let search_restore = std::mem::take(&mut self.suppress_nav_record_for_search_restore);
        if self.global_search.active
            || self.favsearch.active
            || self.tag_view.active
            || search_restore
        {
            // 古いワンショット抑止が次の通常ナビへ漏れないようここで消費しておく。
            self.set_active_folder_nav_suppress_record_once(false);
            return;
        }

        // スマートフォルダ内部の実パスはそのまま履歴へ積まない。scope 遷移は
        // `record_smart_folder_scope_transition` が同じ synthetic path + state metadata の
        // 組として先に記録するため、後続の通常 load 記録はここで重複抑止する。
        if let (Some(current), Some(state)) =
            (current.as_deref(), current_smart_folder_state.as_ref())
        {
            let synthetic = smart_folder::smart_folder_synthetic_path(state.definition_id);
            let current_in_scope = crate::folder_tree::path_eq(current, &synthetic)
                || state.contains_scoped_path(current);
            if current_in_scope && state.contains_scoped_path(target) {
                self.set_active_folder_nav_suppress_record_once(false);
                return;
            }
        }

        let target_rating_view_stars = target_rating_view_stars.filter(|stars| {
            crate::folder_tree::path_eq(target, &rating_view_synthetic_path())
                && (1..=5).contains(stars)
        });
        if current.as_deref().is_some_and(|current| {
            Self::folder_nav_targets_eq(
                current,
                current_rating_view_stars,
                current_smart_folder_state.as_ref(),
                target,
                target_rating_view_stars,
                target_smart_folder_state.as_ref(),
            )
        }) {
            self.update_active_quick_folder_target(target);
            self.set_active_folder_nav_suppress_record_once(false);
            return;
        }

        self.remember_recent_folder(target);

        if self.take_active_folder_nav_suppress_record_once() {
            self.update_active_quick_folder_target(target);
            return;
        }

        let Some(current) = current else {
            self.update_active_quick_folder_target(target);
            return;
        };
        if Self::folder_nav_targets_eq(
            &current,
            current_rating_view_stars,
            current_smart_folder_state.as_ref(),
            target,
            target_rating_view_stars,
            target_smart_folder_state.as_ref(),
        ) {
            self.update_active_quick_folder_target(target);
            return;
        }

        self.push_active_folder_nav_back_stack(
            current,
            current_rating_view_stars,
            current_smart_folder_state,
        );
        self.clear_active_folder_nav_forward_stack();
        self.update_active_quick_folder_target(target);
    }

    pub(crate) fn folder_nav_history_snapshot(&self) -> FolderNavHistorySnapshot {
        FolderNavHistorySnapshot {
            back_stack: self.folder_nav_back_stack.clone(),
            forward_stack: self.folder_nav_forward_stack.clone(),
            back_rating_view_stars: self.folder_nav_back_rating_view_stars.clone(),
            forward_rating_view_stars: self.folder_nav_forward_rating_view_stars.clone(),
            back_smart_folder_states: self.folder_nav_back_smart_folder_states.clone(),
            forward_smart_folder_states: self.folder_nav_forward_smart_folder_states.clone(),
            recent_folders: self.recent_folders.clone(),
            suppress_record_once: self.suppress_folder_nav_record_once,
            pending_rating_view_stars: self.pending_folder_nav_rating_view_stars,
            pending_smart_folder_state: self.pending_folder_nav_smart_folder_state.clone(),
            quick_folder_workspaces: self.quick_folder_workspaces.clone(),
            active_quick_folder_slot: self.active_quick_folder_slot,
            favsearch_nav_stack: self.favsearch.nav_stack.clone(),
            tag_view_nav_stack: self.tag_view.nav_stack.clone(),
            rating_view_nav_stack: self.rating_view_nav_stack.clone(),
            pending_rating_view_zipdir_open: self.pending_rating_view_zipdir_open.clone(),
        }
    }

    pub(crate) fn restore_folder_nav_history(&mut self, snapshot: FolderNavHistorySnapshot) {
        self.folder_nav_back_stack = snapshot.back_stack;
        self.folder_nav_forward_stack = snapshot.forward_stack;
        self.folder_nav_back_rating_view_stars = snapshot.back_rating_view_stars;
        self.folder_nav_forward_rating_view_stars = snapshot.forward_rating_view_stars;
        self.folder_nav_back_smart_folder_states = snapshot.back_smart_folder_states;
        self.folder_nav_forward_smart_folder_states = snapshot.forward_smart_folder_states;
        self.recent_folders = snapshot.recent_folders;
        self.suppress_folder_nav_record_once = snapshot.suppress_record_once;
        self.pending_folder_nav_rating_view_stars = snapshot.pending_rating_view_stars;
        self.pending_folder_nav_smart_folder_state = snapshot.pending_smart_folder_state;
        self.quick_folder_workspaces = snapshot.quick_folder_workspaces;
        self.active_quick_folder_slot = snapshot
            .active_quick_folder_slot
            .or(Some(QuickFolderSlotId::A));
        self.sync_quick_folder_settings();
        self.favsearch.nav_stack = snapshot.favsearch_nav_stack;
        self.tag_view.nav_stack = snapshot.tag_view_nav_stack;
        self.rating_view_nav_stack = snapshot.rating_view_nav_stack;
        self.pending_rating_view_zipdir_open = snapshot.pending_rating_view_zipdir_open;
    }

    pub(crate) fn attach_archive_convert_nav_history_rollback(
        &mut self,
        snapshot: FolderNavHistorySnapshot,
    ) {
        if let Some(state) = self.archive_convert.as_mut() {
            state.nav_history_rollback = Some(snapshot);
        }
    }

    pub(crate) fn clear_archive_convert_nav_history_rollback(&mut self) {
        if let Some(state) = self.archive_convert.as_mut() {
            state.nav_history_rollback = None;
        }
    }

    pub(crate) fn folder_history_back_target(&self) -> Option<&PathBuf> {
        self.active_quick_folder_workspace()
            .and_then(|workspace| workspace.history.back_stack.last())
            .or_else(|| {
                if self.active_quick_folder_slot.is_some() {
                    None
                } else {
                    self.folder_nav_back_stack.last()
                }
            })
    }

    pub(crate) fn folder_history_forward_target(&self) -> Option<&PathBuf> {
        self.active_quick_folder_workspace()
            .and_then(|workspace| workspace.history.forward_stack.last())
            .or_else(|| {
                if self.active_quick_folder_slot.is_some() {
                    None
                } else {
                    self.folder_nav_forward_stack.last()
                }
            })
    }

    pub(crate) fn recent_folder_entries(&self) -> &[PathBuf] {
        // アクティブな A/B スロットの最近開いたフォルダ一覧を返す。
        if let Some(workspace) = self.active_quick_folder_workspace() {
            &workspace.recent_folders
        } else {
            &self.recent_folders
        }
    }

    pub(crate) fn navigate_folder_history_back(&mut self) -> Option<PathBuf> {
        let current = self.folder_nav_current_location();
        let current_rating_view_stars = current
            .as_deref()
            .and_then(|path| self.folder_nav_rating_view_stars_for_path(path));
        let current_smart_folder_state = self.top_level_grid_view.smart_folder().cloned();
        let (target, target_rating_view_stars, target_smart_folder_state) =
            if let Some(workspace) = self.active_quick_folder_workspace_mut() {
                Self::pop_folder_nav_stack(
                    &mut workspace.history.back_stack,
                    &mut workspace.history.back_rating_view_stars,
                    &mut workspace.history.back_smart_folder_states,
                )?
            } else {
                Self::pop_folder_nav_stack(
                    &mut self.folder_nav_back_stack,
                    &mut self.folder_nav_back_rating_view_stars,
                    &mut self.folder_nav_back_smart_folder_states,
                )?
            };
        if let Some(current) = current
            && !Self::folder_nav_targets_eq(
                &current,
                current_rating_view_stars,
                current_smart_folder_state.as_ref(),
                &target,
                target_rating_view_stars,
                target_smart_folder_state.as_ref(),
            )
        {
            if let Some(workspace) = self.active_quick_folder_workspace_mut() {
                Self::push_folder_nav_stack(
                    &mut workspace.history.forward_stack,
                    &mut workspace.history.forward_rating_view_stars,
                    &mut workspace.history.forward_smart_folder_states,
                    current,
                    current_rating_view_stars,
                    current_smart_folder_state,
                );
            } else {
                Self::push_folder_nav_stack(
                    &mut self.folder_nav_forward_stack,
                    &mut self.folder_nav_forward_rating_view_stars,
                    &mut self.folder_nav_forward_smart_folder_states,
                    current,
                    current_rating_view_stars,
                    current_smart_folder_state,
                );
            }
        }
        self.pending_folder_nav_rating_view_stars = target_rating_view_stars;
        self.pending_folder_nav_smart_folder_state = target_smart_folder_state;
        self.set_active_folder_nav_suppress_record_once(true);
        Some(target)
    }

    /// フォルダ履歴が指す合成パスを、実ディレクトリとしてロードせず対応ビューへ戻す。
    ///
    /// `Unavailable` は保持 state が既に無いケース。呼び出し側は履歴 snapshot を戻して
    /// no-op にし、合成パスを `load_folder` へ流してはならない。
    pub(crate) fn dispatch_synthetic_folder_history_target(
        &mut self,
        target: &Path,
    ) -> SyntheticFolderHistoryDispatch {
        let smart_folder_target = smart_folder::is_smart_folder_synthetic_path(target);
        let target_rating_view_stars = self.pending_folder_nav_rating_view_stars.take();
        let target_smart_folder_state = self.pending_folder_nav_smart_folder_state.take();
        let smart_folder_restore_is_scoped =
            target_smart_folder_state.as_ref().is_some_and(|state| {
                matches!(
                    state.position,
                    top_level_grid_view::SmartFolderPosition::Scoped { .. }
                )
            });
        let dispatch = if crate::folder_tree::path_eq(target, &drive_list_synthetic_path()) {
            let origin = self.effective_folder();
            self.enter_drive_list(origin);
            SyntheticFolderHistoryDispatch::Restored
        } else if crate::folder_tree::path_eq(target, &reading_history_synthetic_path()) {
            self.enter_reading_history();
            SyntheticFolderHistoryDispatch::Restored
        } else if crate::folder_tree::path_eq(target, &bookmark_view_synthetic_path()) {
            self.enter_bookmark_view();
            SyntheticFolderHistoryDispatch::Restored
        } else if crate::folder_tree::path_eq(target, &rating_view_synthetic_path()) {
            let stars = target_rating_view_stars.or_else(|| {
                (1..=5)
                    .contains(&self.rating_view_stars)
                    .then_some(self.rating_view_stars)
            });
            if let Some(stars) = stars {
                self.rating_view_nav_stack.clear();
                self.pending_rating_view_zipdir_open = None;
                if self.rating_view_rows_stars == Some(stars) && self.rating_view_pending.is_none()
                {
                    self.install_rating_view_rows();
                } else {
                    self.rating_view_stars = stars;
                    self.rating_view_sort = crate::rating_view::RatingViewSort::default();
                    self.reload_current_rating_view_preserving_sort();
                }
                SyntheticFolderHistoryDispatch::Restored
            } else {
                SyntheticFolderHistoryDispatch::Unavailable
            }
        } else if crate::folder_tree::path_eq(target, &subfolder_expansion_synthetic_path()) {
            let restored = if let Some(state) = self.folder_nav_subfolder_restore.take() {
                self.restore_subfolder_expansion_for_synthetic_path_with_state(target, Some(state))
            } else if self.subfolder_expansion_snapshot.is_some() {
                self.reinstall_subfolder_expansion_snapshot()
            } else if self.subfolder_expansion_root.is_some()
                || self.subfolder_expansion_saved_folder.is_some()
            {
                self.restore_subfolder_expansion_for_synthetic_path(target)
            } else {
                false
            };
            if restored {
                SyntheticFolderHistoryDispatch::Restored
            } else {
                SyntheticFolderHistoryDispatch::Unavailable
            }
        } else if smart_folder_target {
            let restored = if let Some(state) = target_smart_folder_state {
                self.restore_smart_folder_view_state(state);
                true
            } else {
                self.restore_smart_folder_for_synthetic_path(target)
            };
            if restored {
                SyntheticFolderHistoryDispatch::Restored
            } else {
                SyntheticFolderHistoryDispatch::Unavailable
            }
        } else {
            SyntheticFolderHistoryDispatch::NotSynthetic
        };

        if dispatch == SyntheticFolderHistoryDispatch::Restored {
            // 合成ビュー再構築は load_folder を通らないため、navigate_* が立てた
            // suppress ワンショットをここで消費する。ただしスマートフォルダは非同期install
            // が履歴遷移を記録するため、そのinstallまで維持する。snapshot missでopen経路が
            // 一度clearしていても、history dispatchが所有権を立て直す。
            // root / snapshot-miss は非同期 prepare の install が suppress を消費する。
            // scoped state は上の restore 中に実フォルダを同期 load 済みなので、ここで
            // 新しい suppress を残すと次のユーザー操作が履歴に入らなくなる。
            self.set_active_folder_nav_suppress_record_once(
                smart_folder_target && !smart_folder_restore_is_scoped,
            );
        }
        dispatch
    }

    /// お気に入り追加対象として扱える現在地。お気に入りは検索/索引のルートに
    /// なるため、実ディレクトリだけを許可し、ZIP/PDF/変換キャッシュは対象外にする。
    pub(crate) fn current_favorite_target(&self) -> Option<PathBuf> {
        if self.archive_source_override.is_some()
            || self.current_folder_last_mtime.is_none()
            || self.pdf_enumerate_pending.is_some()
            || self.zip_enumerate_pending.is_some()
            || self.show_pdf_password_dialog
            || self.pdf_password_request_pending_in_any_context()
        {
            return None;
        }
        let target = self.current_folder.clone()?;
        if crate::books::path_is_under_or_equal(&target, &self.book_root_path()) {
            return None;
        }
        Some(target)
    }

    pub(crate) fn poll_current_folder_watch(&mut self, ctx: &egui::Context) {
        self.ensure_current_folder_watch(ctx);

        let now = std::time::Instant::now();
        let mut should_check = false;
        let mut repaint_after = None;
        {
            let Some(watch) = self.current_folder_watch.as_mut() else {
                return;
            };

            let mut saw_change = false;
            while let Ok(event) = watch.rx.try_recv() {
                match event {
                    Ok(event) => {
                        if Self::current_folder_watch_event_relevant(&event) {
                            saw_change = true;
                        }
                    }
                    Err(err) => {
                        crate::logger::log(format!("current_folder_watch: notify error: {err}"));
                        saw_change = true;
                    }
                }
            }

            if saw_change {
                let delay = std::time::Duration::from_millis(CURRENT_FOLDER_WATCH_DEBOUNCE_MS);
                watch.debounce_until = Some(now + delay);
                repaint_after = Some(delay);
            } else if let Some(deadline) = watch.debounce_until {
                if now >= deadline {
                    watch.debounce_until = None;
                    should_check = true;
                } else {
                    repaint_after = Some(deadline.saturating_duration_since(now));
                }
            }
        }

        if let Some(delay) = repaint_after {
            ctx.request_repaint_after(delay);
        }
        if should_check {
            self.check_external_folder_changes();
        }
    }

    fn ensure_current_folder_watch(&mut self, ctx: &egui::Context) {
        let target = self.current_favorite_target();
        let Some(folder) = target else {
            self.current_folder_watch = None;
            self.current_folder_watch_failed = None;
            return;
        };

        if self
            .current_folder_watch
            .as_ref()
            .is_some_and(|watch| crate::folder_tree::path_eq(&watch.folder, &folder))
        {
            return;
        }

        self.current_folder_watch = None;
        if self
            .current_folder_watch_failed
            .as_ref()
            .is_some_and(|failed| crate::folder_tree::path_eq(failed, &folder))
        {
            return;
        }
        self.current_folder_watch_failed = None;

        match Self::start_current_folder_watch(ctx, folder.clone()) {
            Ok(watch) => {
                crate::logger::log(format!(
                    "current_folder_watch: watching {}",
                    folder.display()
                ));
                self.current_folder_watch = Some(watch);
            }
            Err(err) => {
                crate::logger::log(format!(
                    "current_folder_watch: failed to watch {}: {err}",
                    folder.display()
                ));
                self.current_folder_watch_failed = Some(folder);
            }
        }
    }

    fn start_current_folder_watch(
        ctx: &egui::Context,
        folder: PathBuf,
    ) -> Result<CurrentFolderWatch, String> {
        use notify::Watcher;

        let (tx, rx) = crossbeam_channel::unbounded::<notify::Result<notify::Event>>();
        let repaint_ctx = ctx.clone();
        let mut watcher = notify::recommended_watcher(move |event| {
            let _ = tx.send(event);
            repaint_ctx.request_repaint();
        })
        .map_err(|e| format!("recommended_watcher failed: {e}"))?;
        watcher
            .watch(&folder, notify::RecursiveMode::NonRecursive)
            .map_err(|e| format!("watch failed: {e}"))?;

        Ok(CurrentFolderWatch {
            folder,
            _watcher: watcher,
            rx,
            debounce_until: None,
        })
    }

    fn current_folder_watch_event_relevant(event: &notify::Event) -> bool {
        !matches!(event.kind, notify::EventKind::Access(_))
    }

    pub(crate) fn navigate_folder_history_forward(&mut self) -> Option<PathBuf> {
        let current = self.folder_nav_current_location();
        let current_rating_view_stars = current
            .as_deref()
            .and_then(|path| self.folder_nav_rating_view_stars_for_path(path));
        let current_smart_folder_state = self.top_level_grid_view.smart_folder().cloned();
        let (target, target_rating_view_stars, target_smart_folder_state) =
            if let Some(workspace) = self.active_quick_folder_workspace_mut() {
                Self::pop_folder_nav_stack(
                    &mut workspace.history.forward_stack,
                    &mut workspace.history.forward_rating_view_stars,
                    &mut workspace.history.forward_smart_folder_states,
                )?
            } else {
                Self::pop_folder_nav_stack(
                    &mut self.folder_nav_forward_stack,
                    &mut self.folder_nav_forward_rating_view_stars,
                    &mut self.folder_nav_forward_smart_folder_states,
                )?
            };
        if let Some(current) = current
            && !Self::folder_nav_targets_eq(
                &current,
                current_rating_view_stars,
                current_smart_folder_state.as_ref(),
                &target,
                target_rating_view_stars,
                target_smart_folder_state.as_ref(),
            )
        {
            if let Some(workspace) = self.active_quick_folder_workspace_mut() {
                Self::push_folder_nav_stack(
                    &mut workspace.history.back_stack,
                    &mut workspace.history.back_rating_view_stars,
                    &mut workspace.history.back_smart_folder_states,
                    current,
                    current_rating_view_stars,
                    current_smart_folder_state,
                );
            } else {
                Self::push_folder_nav_stack(
                    &mut self.folder_nav_back_stack,
                    &mut self.folder_nav_back_rating_view_stars,
                    &mut self.folder_nav_back_smart_folder_states,
                    current,
                    current_rating_view_stars,
                    current_smart_folder_state,
                );
            }
        }
        self.pending_folder_nav_rating_view_stars = target_rating_view_stars;
        self.pending_folder_nav_smart_folder_state = target_smart_folder_state;
        self.set_active_folder_nav_suppress_record_once(true);
        Some(target)
    }

    /// 現在のフォルダを再読み込みする。変換済みアーカイブ閲覧中 (キャッシュ ZIP を
    /// `current_folder` に、元 RAR/7z/LZH を `archive_source_override` に持っている状態)
    /// は再読み込み後も override/address を元 RAR/7z/LZH に戻し、UI コンテキストを維持する。
    ///
    /// 用途: 環境設定 OK 押下時の同名ファイル設定変更・Susie 設定変更など、再読み込みは
    /// 必要だが元アーカイブの文脈を保ちたいケース。
    /// トレイ復帰 / フォーカス復帰時に呼び、現在表示中のフォルダが外部 (ComfyUI 等) で
    /// 変化していれば再ロードする。選択中アイテムはパスで追跡して復元し、再ロード後に
    /// ビューポート外にはみ出していれば次フレームで可視範囲に収める。
    ///
    /// スキップ条件:
    /// - `current_folder` が None
    /// - Ctrl+G 検索中 (別ビューで動いている)
    /// - ZIP / PDF / 検索合成パスなどディレクトリ実体でない (= `current_folder_last_mtime`
    ///   が None のまま)
    /// - mtime が保存値と同じ (= 外部更新なし)
    /// - mtime は変わったが、再走査した内容シグネチャ (path+mtime+size) が一致する
    ///   (Windows Search / ウイルススキャン等が触っただけ → ちらつき抑止)
    ///
    /// 再ロードは `load_folder_with_scan` に走らせた `scan` を渡して再 read_dir を避ける。
    /// UI スレッドでの syscall は `metadata()` + 1 回の `read_dir` のみ。
    pub(crate) fn check_external_folder_changes(&mut self) {
        if self.global_search.active || self.tag_view.active {
            return;
        }
        // 削除進行中はフォーカス復帰による自動再読み込みを抑止する。削除自身が
        // フォルダ mtime を更新するので素通しすると load_folder が走り、items が
        // 差し替わって poll_delete_pending が generation 不一致で結果適用をスキップ、
        // 加えて未完了ファイルに対するサムネ/AI 先読みが発生して「読み込み失敗」が
        // 出る。削除完了ダイアログが閉じてから次のフレームで再検知される。
        if self.delete_pending.is_some() {
            return;
        }
        let Some(folder) = self.current_folder.clone() else {
            return;
        };
        let Some(prev_mtime) = self.current_folder_last_mtime else {
            return;
        };
        let Ok(meta) = folder.metadata() else {
            return;
        };
        if !meta.is_dir() {
            return;
        }
        let Ok(new_mtime) = meta.modified() else {
            return;
        };
        if new_mtime == prev_mtime {
            return;
        }
        // mtime が変わっていても、フォルダ内容 (paths + mtimes + sizes) が同一なら
        // items 差し替えをスキップして画面ちらつきを防ぐ。Windows Search や
        // ウイルススキャン等が触っただけで mtime が更新されるケースを救済する。
        let Ok(scan) = scan_directory_with_settings(&folder, &self.settings) else {
            // 一時的なネットワーク切断や権限エラーを「空フォルダへの変更」として扱わない。
            return;
        };
        let new_sig = signature_from_scan(&scan);
        if self.current_folder_signature == Some(new_sig) {
            self.current_folder_last_mtime = Some(new_mtime);
            return;
        }
        self.clear_retained_final_ai_cache(&format!(
            "external_folder_change folder={}",
            folder.display()
        ));
        self.clear_retained_pdf_page_cache(&format!(
            "external_folder_change folder={}",
            folder.display()
        ));
        // 選択中アイテムのパスを保存 (非選択 / パス取れないアイテムは None)。
        let selected_path: Option<PathBuf> = self
            .selected
            .and_then(|idx| self.items.get(idx))
            .and_then(|item| match item {
                GridItem::Folder(p)
                | GridItem::Image(p)
                | GridItem::Video(p)
                | GridItem::ZipFile(p)
                | GridItem::PdfFile(p) => Some(p.clone()),
                GridItem::ConvertibleArchive { path, .. } => Some(path.clone()),
                _ => None,
            });
        crate::logger::log(format!(
            "auto-refresh: folder content changed ({}), reloading",
            folder.display()
        ));
        // 既に走らせた scan を pre_scan として渡し、UI スレッドで再 read_dir しない。
        self.load_folder_with_scan(folder, Some(scan));
        // 再ロード後に選択パスを探し、見つかればそこにカーソルを戻してスクロール依頼。
        // 見つからない (消えた) / そもそも未選択ならスクロール位置は触らない。
        if let Some(path) = selected_path {
            let new_idx = self.items.iter().position(|it| {
                matches!(it,
                    GridItem::Folder(p)
                    | GridItem::Image(p)
                    | GridItem::Video(p)
                    | GridItem::ZipFile(p)
                    | GridItem::PdfFile(p) if p == &path)
                    || matches!(it, GridItem::ConvertibleArchive { path: p, .. } if p == &path)
            });
            if let Some(idx) = new_idx {
                self.selected = Some(idx);
                self.scroll_to_selected = true;
            }
        }
    }

    pub(crate) fn reload_current_folder_preserving_override(&mut self) {
        let Some(folder) = self.current_folder.clone() else {
            return;
        };
        if self.restore_smart_folder_for_synthetic_path(&folder) {
            return;
        }
        if self.restore_subfolder_expansion_for_synthetic_path(&folder) {
            return;
        }
        self.select_after_load = self
            .selected
            .and_then(|index| self.items.get(index))
            .map(|item| item.name().into_owned());
        let saved_override = self.archive_source_override.clone();
        self.load_folder(folder);
        if let Some(src) = saved_override {
            self.address = src.to_string_lossy().to_string();
            self.archive_source_override = Some(src);
        }
    }

    /// ソート順変更後の再表示。現在のビュー種別を保ったまま並べ替える。
    ///
    /// - **ネスト ZIP ツリー閲覧中**: 現在の階層を保ったまま新ソートで再 materialize。
    ///   `load_folder(zip_path)` で開き直すと ZIP のルートへ飛んでしまうため
    ///   (ユーザー報告: ソート変更で階層がリセットされる)。
    /// - **Ctrl+G 検索結果ビュー**: 検索結果の並べ替えに反映 (実フォルダを再ロードしない)。
    /// - **通常フォルダ**: スクロール履歴を捨てて先頭から再ロード。
    pub(crate) fn apply_sort_change_reload(&mut self) {
        if self.zip_nav.is_some() {
            self.zip_nav_show_current_level();
            return;
        }
        if self.global_search.active && self.items_are_global_search_view {
            self.rebuild_items_from_global_search();
            return;
        }
        if self.tag_view.active && self.items_are_tag_view {
            self.execute_tag_view();
            return;
        }
        if self.items_are_rating_view {
            if matches!(
                self.rating_view_sort,
                crate::rating_view::RatingViewSort::Normal(_)
            ) {
                self.rating_view_sort =
                    crate::rating_view::RatingViewSort::Normal(self.settings.sort_order);
            }
            self.install_rating_view_rows();
            return;
        }
        if self.items_are_bookmark_view {
            if matches!(
                self.bookmark_view_sort,
                crate::bookmark_browser::BookmarkViewSort::Normal(_)
            ) {
                self.bookmark_view_sort =
                    crate::bookmark_browser::BookmarkViewSort::Normal(self.settings.sort_order);
            }
            self.install_bookmark_view_rows();
            return;
        }
        if self.reprepare_current_smart_folder_for_sort() {
            return;
        }
        if let Some(root) = self
            .subfolder_expansion_pending
            .as_ref()
            .map(|pending| pending.root.clone())
        {
            self.subfolder_expansion_roots = self
                .subfolder_expansion_pending
                .as_ref()
                .map(|pending| pending.roots.clone())
                .unwrap_or_else(|| vec![root.clone()]);
            self.subfolder_expansion_root = Some(root.clone());
            self.subfolder_expansion_saved_folder = Some(root);
            return;
        }
        if self.items_are_subfolder_expansion_view {
            if self.reinstall_subfolder_expansion_snapshot() {
                return;
            }
            if let Some(root) = self.subfolder_expansion_root.clone() {
                let roots = if self.subfolder_expansion_roots.is_empty() {
                    vec![root.clone()]
                } else {
                    self.subfolder_expansion_roots.clone()
                };
                self.start_subfolder_expansion_scan_roots(root, roots);
            }
            return;
        }
        if let Some(path) = self.current_folder.clone() {
            self.folder_history.remove(&path);
            self.load_folder(path);
        }
    }

    /// 見開き設定 (`spread_db`) のコンテナキー。
    ///
    /// ネスト ZIP ツリー閲覧中は **`zip_path` + 現在の実効 prefix** を合成パスにして、
    /// **本 (= 内側 ZIP / サブフォルダ) ごとに独立**して見開き向き / 表紙有無 / 連結方向を
    /// 記憶する (ユーザー要望)。`spread_db` は path 文字列を PRIMARY KEY にするだけなので、
    /// 実在しない合成パス (`C:\x.zip\01_inner\chapterA.zip`) でも一意キーとして機能する
    /// (ZIP 自身のキー `C:\x.zip` とも衝突しない)。通常フォルダ / 単純 ZIP は従来どおり
    /// `current_folder`。
    pub(crate) fn spread_container_key(&self) -> Option<PathBuf> {
        if let Some(nav) = self.zip_nav.as_ref() {
            let mut p = nav.tree.zip_path.clone();
            for seg in nav.current() {
                p.push(seg);
            }
            Some(p)
        } else {
            self.current_folder.clone()
        }
    }

    /// 代表サムネピン (`folder_thumb_pins`) のコンテナキー。見開きキーとは
    /// **ルート表示の扱いだけ** 異なる。
    ///
    /// ネスト ZIP ツリー閲覧中:
    /// - **ルート表示 (`at_root`)**: 通常 ZIP は `zip_path` そのもの。変換キャッシュ ZIP
    ///   では `archive_source_override` (= 元 RAR/7z/LZH) を使う。ルート本の代表 =
    ///   親フォルダの ZipFile / ConvertibleArchive セルが引くキーであり、単一ラッパー
    ///   ZIP (開いた時点で collapse 済み) で `spread_container_key`
    ///   (= `zip_path\vol01`) を使うと、ピンしても親セルに反映
    ///   されず、v1.2.x のフラット UI で付けた既存ピン (key=`zip_path`) も解除不能に
    ///   なる (レビュー P2)。
    /// - **本の中 (スタック深さ ≥ 2)**: 同じ root + 実効 prefix 合成パス。親階層の
    ///   ZipDir セル側は `refresh_folder_pin_map` が実効 prefix で alias 登録するので一致する。
    ///
    /// 通常フォルダは `current_folder`。
    pub(crate) fn pin_container_key(&self) -> Option<PathBuf> {
        if let Some(nav) = self.zip_nav.as_ref() {
            let root = zip_pin_root_path(
                &nav.tree.zip_path,
                self.archive_source_override.as_deref(),
                self.current_folder.as_deref(),
            );
            if nav.at_root() {
                return Some(root.to_path_buf());
            }
            let mut p = root.to_path_buf();
            for seg in nav.current() {
                p.push(seg);
            }
            return Some(p);
        }
        self.current_folder.clone()
    }

    /// 指定キーの見開きモード / 連結方式 / 綴じ方向を `spread_db` から読み込んで
    /// `self.spread_mode` / `reading_flow` / `reading_direction` に適用する。
    /// 未登録なら呼び出し元が型で指定した既定値。旧 `SpreadMode::Vertical` は
    /// 「単ページ + 縦連結」に読み替え。
    ///
    /// `start_loading_items` (フォルダ / 初回 ZIP open) と、ネスト ZIP の階層切替
    /// (`zip_nav_show_current_level` / finalize 後) の両方から呼び、本ごとに設定を復元する。
    pub(crate) fn apply_spread_for_key(
        &mut self,
        key: &std::path::Path,
        defaults: SpreadRestoreDefaults,
    ) {
        self.apply_spread_for_key_with_fallback(key, None, defaults);
    }

    /// `apply_spread_for_key` の fallback キー付き版。`key` に保存が無い項目を
    /// `fallback` キーから読む。ネスト ZIP の本キー (`zip_path\book`) に未保存のとき
    /// `zip_path` (= v1.2.x フラット時代の保存先 / ZIP 全体の既定) へフォールバックする
    /// ことで、旧バージョンで保存した単一ラッパー ZIP の見開き設定が collapse 後の
    /// キーでも生き、ZIP 全体の設定を各本が継承する。本ごとに変更した時点で本キーの
    /// 行が書かれ、以降は本キーが勝つ (レビュー P2)。
    pub(crate) fn apply_spread_for_key_with_fallback(
        &mut self,
        key: &std::path::Path,
        fallback: Option<&std::path::Path>,
        defaults: SpreadRestoreDefaults,
    ) {
        let db = self.spread_db.as_ref();
        let stored_spread = db
            .and_then(|db| db.get(key))
            .or_else(|| fallback.and_then(|fb| db.and_then(|db| db.get(fb))))
            .unwrap_or(defaults.spread_mode);
        self.reading_flow = db
            .and_then(|db| db.get_flow(key))
            .or_else(|| fallback.and_then(|fb| db.and_then(|db| db.get_flow(fb))))
            .unwrap_or(defaults.reading_flow);
        self.reading_direction = db
            .and_then(|db| db.get_direction(key))
            .or_else(|| fallback.and_then(|fb| db.and_then(|db| db.get_direction(fb))))
            .unwrap_or(defaults.reading_direction);
        if stored_spread == crate::settings::SpreadMode::Vertical {
            self.spread_mode = crate::settings::SpreadMode::Single;
            self.reading_flow = crate::settings::ReadingFlow::Vertical;
        } else {
            self.spread_mode = stored_spread;
        }
        self.spread_shift_anchor_idx = None;
        if self.spread_mode.is_rtl() {
            self.reading_direction = crate::settings::ReadingDirection::Rtl;
        } else if matches!(
            self.spread_mode,
            crate::settings::SpreadMode::Ltr | crate::settings::SpreadMode::LtrCover
        ) {
            self.reading_direction = crate::settings::ReadingDirection::Ltr;
        }
    }

    pub(crate) fn apply_view_trim_for_key(&mut self, key: &std::path::Path) {
        self.apply_view_trim_for_key_with_fallback(key, None);
    }

    pub(crate) fn apply_view_trim_for_key_with_fallback(
        &mut self,
        key: &std::path::Path,
        fallback: Option<&std::path::Path>,
    ) {
        let state = self
            .view_trim_db
            .as_ref()
            .and_then(|db| db.get_book_state(key))
            .or_else(|| {
                fallback.and_then(|fb| {
                    self.view_trim_db
                        .as_ref()
                        .and_then(|db| db.get_book_state(fb))
                })
            })
            .unwrap_or_default();
        self.view_trim_apply_mode = match state.apply_mode {
            crate::view_trim::ViewTrimApplyMode::Page => crate::view_trim::ViewTrimApplyMode::None,
            mode => mode,
        };
        self.view_trim_book_settings = state.book_settings;
        self.view_trim_page_apply_root_idx = None;
        self.view_trim_page_spread_separate = self.view_trim_book_settings.spread_separate;

        let legacy_margin_fit = matches!(
            self.settings.fullscreen_fit_mode,
            crate::settings::FullscreenFitMode::MarginFit
        ) || self.settings.margin_fit_enabled;
        if legacy_margin_fit {
            self.settings.fullscreen_fit_mode = crate::settings::FullscreenFitMode::Page;
            self.settings.margin_fit_enabled = false;
            if matches!(
                self.view_trim_apply_mode,
                crate::view_trim::ViewTrimApplyMode::None
            ) {
                self.view_trim_apply_mode = crate::view_trim::ViewTrimApplyMode::Auto;
            }
            self.settings.save();
            if let Some(db) = &self.view_trim_db {
                let migrated = crate::view_trim::ViewTrimBookState {
                    apply_mode: self.view_trim_apply_mode,
                    book_settings: self.view_trim_book_settings,
                };
                if let Err(err) = db.set_book_state(key, migrated) {
                    crate::logger::log(format!(
                        "view_trim: failed to migrate legacy margin fit for book: {err}"
                    ));
                }
            }
        }
    }

    pub(crate) fn persist_current_view_trim_book_state(&self) {
        let (Some(db), Some(key)) = (&self.view_trim_db, self.spread_container_key()) else {
            return;
        };
        let state = crate::view_trim::ViewTrimBookState {
            apply_mode: match self.view_trim_apply_mode {
                crate::view_trim::ViewTrimApplyMode::Page => {
                    crate::view_trim::ViewTrimApplyMode::None
                }
                mode => mode,
            },
            book_settings: self.view_trim_book_settings,
        };
        if let Err(err) = db.set_book_state(&key, state) {
            crate::logger::log(format!("view_trim: failed to save book state: {err}"));
        }
    }

    pub(crate) fn persist_view_trim_page_override(
        &mut self,
        idx: usize,
        page_override: crate::view_trim::ViewTrimPageOverride,
    ) {
        let (Some(db), Some(key)) = (&self.view_trim_db, self.page_path_key(idx)) else {
            return;
        };
        if let Err(err) = db.set_page_override(&key, page_override) {
            crate::logger::log(format!(
                "view_trim: failed to save page override idx={idx}: {err}"
            ));
        }
        self.invalidate_smart_folder_resort_metadata();
    }

    pub(crate) fn remove_view_trim_page_override(&mut self, idx: usize) {
        let (Some(db), Some(key)) = (&self.view_trim_db, self.page_path_key(idx)) else {
            return;
        };
        if let Err(err) = db.remove_page_override(&key) {
            crate::logger::log(format!(
                "view_trim: failed to remove page override idx={idx}: {err}"
            ));
        }
        self.invalidate_smart_folder_resort_metadata();
    }

    pub(crate) fn hydrate_view_trim_page_overrides_for_current_items(&mut self) {
        self.view_trim_page_overrides.clear();
        let Some(db) = &self.view_trim_db else {
            return;
        };
        // current_folder / source_path は WSL 形式やライブラリエイリアスのままでも、
        // GridItem 内の PDF / ZIP 実体パスは Windows の実パスへ解決済みの場合がある。
        // コンテナ prefix で検索すると、その2つの名前空間が異なる本では保存済みの
        // page_path を拾えない。永続化も表示も page_path_key を正本にしているため、
        // 再水和も現在 items の exact key だけを同じ境界で列挙して取得する。
        let page_keys = (0..self.items.len())
            .filter_map(|idx| self.page_path_key(idx).map(|key| (idx, key)))
            .collect::<Vec<_>>();
        let page_key_refs = page_keys
            .iter()
            .map(|(_, key)| key.as_str())
            .collect::<Vec<_>>();
        let page_map = db.load_page_overrides_many(&page_key_refs);
        if page_map.is_empty() {
            return;
        }
        for (idx, key) in page_keys {
            if let Some(page_override) = page_map.get(&key) {
                self.view_trim_page_overrides.insert(idx, *page_override);
            }
        }
    }

    /// 通常の (事前スキャンなしの) フォルダロード。`scan_directory` を UI スレッドで
    /// 同期実行する。初期化 / 履歴復元 / 直接パス指定など、Ctrl+↑↓ 連打以外の
    /// すべての呼び出しが通る。
    pub fn load_folder(&mut self, path: PathBuf) {
        self.load_folder_with_scan(path, None);
    }

    /// メニュー / BS / 場所アクションからドライブ一覧を開き、直前の場所を ← 履歴へ積む。
    pub(crate) fn enter_drive_list_from_navigation(&mut self, origin: Option<PathBuf>) {
        self.record_folder_nav_transition(&drive_list_synthetic_path());
        self.enter_drive_list(origin);
    }

    /// ドライブ一覧本体を構築する。履歴 dispatch からも呼ぶため、ここでは履歴を記録しない。
    pub(crate) fn enter_drive_list(&mut self, origin: Option<PathBuf>) {
        crate::logger::log("=== enter_drive_list ===");
        // ドライブ一覧へ移るので in-flight のフォルダペイン open scan は破棄する。
        self.cancel_folder_pane_open();
        self.gamepad_location_picker = None;
        // 閲覧履歴の戻り先予約はここで捨てる (本コンテキストを抜けた)。
        self.reading_history_return_from = None;
        self.clear_bookmark_view_return_state();

        if let Some(cur) = self.current_folder.clone() {
            let leaving_search_view = self.items_are_global_search_view
                || self.items_are_tag_view
                || self.items_are_reading_history_view
                || self.items_are_bookmark_view
                || self.items_are_rating_view
                || is_synthetic_view_path(&cur);
            if !leaving_search_view && !self.items_are_drive_list {
                self.folder_history
                    .insert(cur, (self.scroll_offset_y, self.selected));
            }
        }

        #[cfg(windows)]
        let detached_video_preserved = self.promote_active_detached_video_for_main_context_change();
        #[cfg(not(windows))]
        let detached_video_preserved = false;
        #[cfg(windows)]
        if !detached_video_preserved {
            self.preserve_active_detached_image_window_for_main_context_change();
        }
        if !detached_video_preserved {
            self.close_fullscreen();
        }
        if let Some(pending) = self.folder_nav_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        self.clear_pending_folder_nav_steps();
        self.bump_full_context_for_load();
        // ドライブ一覧は start_loading_items を通らない経路。残った ZIP ツリーナビ状態を
        // 破棄しないと、BS / gamepad-back が zip_nav_back() を先に拾って drive-list marker の
        // まま旧 ZIP 階層を復活させてしまう (Codex P2)。ネスト ZIP バイト列キャッシュも破棄。
        self.zip_nav = None;
        // ファイル名スタックも同様に解除 (SLI を通らない経路なので明示的に)。
        self.stack_mode_requested = false;
        self.stack_view = None;
        self.stack_showing_flat = false;
        self.cancel_stack_script_pending();
        if self.items_are_subfolder_expansion_view {
            let synthetic = subfolder_expansion_synthetic_path();
            self.folder_nav_subfolder_restore =
                self.take_subfolder_expansion_restore_for_synthetic_path(Some(&synthetic));
        }
        self.cancel_subfolder_expansion_pending();
        self.clear_subfolder_expansion_view_state();
        self.cancel_smart_folder_pending();
        self.clear_smart_folder_view_state();
        if let Some(pending) = self.rating_view_pending.take() {
            pending.cancel();
        }
        crate::zip_loader::clear_nested_cache();

        let (tx, rx) = mpsc::channel();
        self.tx = tx.clone();
        self.rx = rx;

        self.current_folder = Some(drive_list_synthetic_path());
        self.current_folder_last_mtime = None;
        self.current_folder_signature = None;
        self.current_folder_rating_cache = None;
        self.archive_source_override = None;
        self.address.clear();
        self.settings.last_folder = Some(drive_list_last_folder_sentinel());
        self.selected = None;
        self.scroll_offset_y = 0.0;
        self.scroll_to_selected = false;
        self.pending_grid_scroll = None;
        self.scroll_hint.store(0, Ordering::Relaxed);
        self.search_filter = None;
        self.search_filter_origin_folder = None;
        self.search_query.clear();
        self.show_search_bar = false;
        self.checked.clear();
        self.requested.clear();
        self.pending_finalize.clear();
        self.texture_backlog.clear();
        self.keep_range = (0, 0);
        self.keep_set.clear();
        self.keep_start_shared.store(0, Ordering::Relaxed);
        self.keep_end_shared.store(0, Ordering::Relaxed);
        self.visible_end_shared.store(0, Ordering::Relaxed);
        self.metadata_cache.clear();
        self.exif_cache.clear();
        self.xmp_cache.clear();
        self.xmp_panorama_info.clear();
        self.clear_tags_cache();
        self.rotation_cache.clear();
        self.rating_cache.clear();
        self.reset_folder_rating_counts();
        self.adjustment_cache.clear();
        self.thumb_pixels.clear();
        self.passthrough_rendition_cache.clear();
        self.thumb_edit_preview_layers.clear();
        self.thumb_adjust_tex.clear();
        self.fs_cache.clear();
        self.fs_lanczos_cache.clear();
        self.fs_upload_backlog.clear();
        self.fs_pending.clear();
        self.input_generation.clear();
        self.clear_all_final_pipeline_caches();
        self.clear_color_filter_for_new_items();
        self.current_color_cache_map = None;
        self.current_color_catalog = None;

        if let Some(pending) = self.search_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        if let Some(pending) = self.metadata_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        self.pdf_enumerate_pending = None;
        self.zip_enumerate_pending = None;
        self.fs_nav_after_pdf_enumerate = None;
        self.virtual_folder_writeback = None;
        self.pdf_prefetch_grace_until = None;

        let items: Vec<GridItem> = crate::known_folders::available_drives()
            .into_iter()
            .map(GridItem::Folder)
            .collect();
        let image_metas = vec![None; items.len()];
        self.install_new_items(items, image_metas);
        self.items_are_drive_list = true;
        self.top_level_grid_view
            .replace_surface(top_level_grid_view::TopLevelGridSurface::DriveList);

        for idx in 0..self.items.len() {
            let has_pin = match &self.items[idx] {
                GridItem::Folder(path) => {
                    let key = crate::path_key::normalize_keep_drive(path);
                    self.folder_pin_map.contains_key(&key)
                }
                _ => false,
            };
            if !has_pin {
                self.thumbnails[idx] = ThumbnailState::Failed;
            }
        }

        self.rebuild_visible_indices();
        if let Some(origin) = origin {
            self.selected = self.items.iter().position(|item| {
                matches!(item, GridItem::Folder(path) if crate::folder_tree::path_eq(path, &origin))
            });
            if self.selected.is_some() {
                self.scroll_to_selected = true;
            }
        }
        if self.selected.is_none() {
            self.selected = self.visible_indices.first().copied();
        }

        if self.folder_pin_map.is_empty() {
            self.reload_queue = None;
            self.heavy_io_queue = None;
            return;
        }

        let catalog_arc = self.get_or_open_catalog(&drive_list_catalog_path());
        let cache_map: Arc<
            std::sync::RwLock<std::collections::HashMap<String, crate::catalog::CacheEntry>>,
        > = Arc::new(std::sync::RwLock::new(
            catalog_arc
                .as_ref()
                .and_then(|catalog| catalog.load_all().ok())
                .unwrap_or_default(),
        ));
        self.current_color_cache_map = Some(Arc::clone(&cache_map));
        self.current_color_catalog = catalog_arc.clone();
        self.seed_drive_list_pin_thumbs_from_catalog(&cache_map, catalog_arc.as_ref());
        self.cache_gen_total = 0;
        self.cache_gen_done = Arc::new(AtomicUsize::new(0));
        let reload_queue: Arc<NotifyQueue> = Arc::new((Mutex::new(Vec::new()), Condvar::new()));
        let heavy_io_queue: Arc<NotifyQueue> = Arc::new((Mutex::new(Vec::new()), Condvar::new()));
        self.reload_queue = Some(Arc::clone(&reload_queue));
        self.heavy_io_queue = Some(Arc::clone(&heavy_io_queue));
        let cancel = Arc::clone(&self.cancel_token);
        self.spawn_thumbnail_workers(
            &tx,
            cancel,
            reload_queue,
            heavy_io_queue,
            cache_map,
            catalog_arc,
            self.folder_thumb_pin_db.clone(),
        );
    }

    pub(crate) fn load_folder_or_convert_archive(&mut self, path: PathBuf) -> FolderOpenOutcome {
        self.load_folder_or_convert_archive_with_auto_fullscreen(path, false)
    }

    fn load_folder_nav_target(
        &mut self,
        path: PathBuf,
        pre_scan: Option<ScannedDir>,
    ) -> FolderOpenOutcome {
        if path.is_file() && crate::folder_tree::is_convertible_archive_path(&path) {
            self.load_folder_or_convert_archive(path)
        } else {
            self.load_folder_with_scan(path, pre_scan);
            FolderOpenOutcome::Loaded
        }
    }

    /// 通常のフォルダ / ZIP / PDF はそのまま開き、変換対応アーカイブ (RAR/7z/LZH)
    /// は有効なキャッシュがあれば元パス表示を維持したまま開く。未変換なら既存の
    /// 変換確認ダイアログを出す。
    ///
    /// `auto_fullscreen` は起動引数 / SendTo / 既存インスタンス転送など、
    /// ユーザーが本ファイルまたは画像フォルダを直接開いた経路だけ true にする。
    /// 履歴復元やアドレスバー移動は従来どおり false で呼ぶ。
    pub(crate) fn load_folder_or_convert_archive_with_auto_fullscreen(
        &mut self,
        path: PathBuf,
        auto_fullscreen: bool,
    ) -> FolderOpenOutcome {
        self.load_folder_or_convert_archive_with_auto_fullscreen_owned(
            path,
            auto_fullscreen,
            OpenRequestOwner::Navigation,
        )
    }

    pub(crate) fn load_folder_or_convert_archive_with_auto_fullscreen_owned(
        &mut self,
        path: PathBuf,
        auto_fullscreen: bool,
        owner: OpenRequestOwner,
    ) -> FolderOpenOutcome {
        // Claim the visible-open lifecycle before dispatching by container type. In particular,
        // archive B must replace an in-flight archive A before request_* observes the old state.
        if !self.claim_open_request_owner(&path, &owner) {
            return FolderOpenOutcome::Ignored;
        }
        let format = path
            .extension()
            .and_then(|e| e.to_str())
            .and_then(crate::archive_converter::ArchiveFormat::from_extension);
        if path.is_file()
            && let Some(format) = format
        {
            if self.settings.archive_file_handling_ignores_convertible() {
                self.pending_auto_fs_open = false;
                self.show_feedback_toast(
                    "設定により RAR / 7z / LZH アーカイブを無視しています".into(),
                );
                return FolderOpenOutcome::Ignored;
            }
            if format == crate::archive_converter::ArchiveFormat::Rar {
                let fallback_cached_zip = self.try_archive_cache_lookup(&path);
                return if self.request_rar_open_owned(
                    path,
                    auto_fullscreen,
                    fallback_cached_zip,
                    owner,
                ) {
                    FolderOpenOutcome::ConversionDialogOpened
                } else {
                    FolderOpenOutcome::Ignored
                };
            }
            if let Some(cached) = self.try_archive_cache_lookup(&path) {
                if self
                    .effective_folder()
                    .is_some_and(|cur| crate::folder_tree::path_eq(&cur, &path))
                {
                    self.set_active_folder_nav_suppress_record_once(true);
                }
                // ★固定 ガード等でブロックされたら Ignored を返し、後続の drill 進行に
                // 流さない (Codex P1)。
                return if self.open_archive_via_cache_owned(path, cached, auto_fullscreen, owner) {
                    FolderOpenOutcome::Loaded
                } else {
                    FolderOpenOutcome::Ignored
                };
            } else {
                return if self.request_archive_convert_owned(path, format, auto_fullscreen, owner) {
                    FolderOpenOutcome::ConversionDialogOpened
                } else {
                    FolderOpenOutcome::Ignored
                };
            }
        }
        if auto_fullscreen && path.is_file() && crate::folder_tree::is_virtual_folder(&path) {
            self.pending_auto_fs_open = true;
        } else if auto_fullscreen
            && path.is_dir()
            && self.settings.auto_fullscreen_image_folders_enabled()
        {
            self.pending_auto_fs_open = true;
        }
        self.load_folder_with_scan_claimed(path, None, owner);
        FolderOpenOutcome::Loaded
    }

    /// 事前スキャン済みディレクトリを受け取れる load_folder の本体。
    /// Ctrl+↑↓ の DFS スレッドが `scan_directory` を済ませている場合、
    /// `pre_scan=Some(...)` を渡すことで UI スレッドの read_dir (= 最大 179ms)
    /// をスキップできる。`path` が ZIP/PDF ファイルのときは仮想フォルダとして
    /// 別ルートに入るため `pre_scan` は無視される (None 相当で委譲)。
    pub fn load_folder_with_scan(&mut self, path: PathBuf, pre_scan: Option<ScannedDir>) {
        self.load_folder_with_scan_owned(path, pre_scan, OpenRequestOwner::Navigation);
    }

    pub(crate) fn load_folder_with_scan_owned(
        &mut self,
        path: PathBuf,
        pre_scan: Option<ScannedDir>,
        owner: OpenRequestOwner,
    ) {
        if !self.claim_open_request_owner(&path, &owner) {
            return;
        }
        self.load_folder_with_scan_claimed(path, pre_scan, owner);
    }

    /// Acquire the right to perform a visible load before any format-specific dispatch.
    ///
    /// This is intentionally idempotent: the container dispatcher enforces the boundary before
    /// archive recognition, while direct folder loaders enforce it for callers that bypass that
    /// dispatcher. Same-folder reloads remain exempt in
    /// `cancel_archive_convert_for_navigation_to`.
    fn claim_open_request_owner(&mut self, path: &Path, owner: &OpenRequestOwner) -> bool {
        match owner {
            OpenRequestOwner::Navigation => {
                if self.navigation_scope.is_detached_physical() {
                    // Archive conversion, unresolved startup opens, and bookmark
                    // opens are App-global main requests. A detached context can
                    // own its load without cancelling any of them.
                    return true;
                }
                // A direct navigation owns the next visible location. If an earlier startup,
                // activation, or bookmark path is still resolving, dispose that request before
                // the worker can overwrite this navigation with a late completion.
                self.cancel_archive_convert_for_navigation_to(path, "normal_navigation");
                self.cancel_unresolved_open_for_navigation();
                self.cancel_conflicting_bookmark_open_for_navigation(path);
                true
            }
            OpenRequestOwner::Bookmark(bookmark_owner) => {
                if !self.bookmark_open_owner_is_current(bookmark_owner) {
                    crate::logger::log(format!(
                        "[bookmark-open] reject stale visible load id={} path={}",
                        bookmark_owner.request_id.0,
                        path.display()
                    ));
                    self.pending_auto_fs_open = false;
                    return false;
                }
                true
            }
        }
    }

    fn load_folder_with_scan_claimed(
        &mut self,
        path: PathBuf,
        pre_scan: Option<ScannedDir>,
        owner: OpenRequestOwner,
    ) {
        let detached_physical = self.navigation_scope.is_detached_physical();
        if !detached_physical && !smart_folder::is_smart_folder_synthetic_path(&path) {
            let preserve_smart_folder_session = self.preserve_smart_folder_session_for_load(&path);
            if self.smart_folder_pending.is_some()
                || self.smart_folder_prepare_pending.is_some()
                || self.smart_folder_confirm_pending.is_some()
            {
                self.cancel_smart_folder_pending();
            }
            if !preserve_smart_folder_session
                && (self.items_are_smart_folder_view
                    || self.top_level_grid_view.smart_folder().is_some())
            {
                self.clear_smart_folder_view_state();
            }
        }
        // 別経路の load が走ったら、この bundle の in-flight folder open scan は stale なので
        // 破棄する。poll_folder_pane_open は pending を take してから適用するため、自分自身の
        // 完了結果を pre-scan 付きで load する場合は no-op。
        self.cancel_folder_pane_open();
        if !detached_physical {
            if self.restore_smart_folder_for_synthetic_path(&path) {
                self.suppress_nav_record_for_search_restore = false;
                return;
            }
            if self.restore_subfolder_expansion_for_synthetic_path(&path) {
                self.suppress_nav_record_for_search_restore = false;
                return;
            }
            self.reconcile_smart_folder_scoped_real_folder_load(&path);
        }
        if matches!(
            self.top_level_grid_view.surface(),
            top_level_grid_view::TopLevelGridSurface::DriveList
                | top_level_grid_view::TopLevelGridSurface::ReadingHistory
                | top_level_grid_view::TopLevelGridSurface::Bookmarks
        ) {
            self.top_level_grid_view
                .replace_surface(top_level_grid_view::TopLevelGridSurface::Folder);
        }
        // 閲覧履歴から開いた本以外の実フォルダへ明示ナビで出たら、戻り先予約を捨てる
        // (アドレスバー / 履歴戻る / フォルダナビ等。予約した本そのものを開き直す場合は維持)。
        if self
            .reading_history_return_from
            .as_ref()
            .is_some_and(|from| !crate::folder_tree::path_eq(from, &path))
        {
            self.reading_history_return_from = None;
        }
        if !detached_physical && matches!(owner, OpenRequestOwner::Navigation) {
            self.reconcile_bookmark_return_target_for_folder_load(&path);
        }
        // ★固定 (Snapshot Lock) 中は **範囲外** フォルダへの移動を block する (= §4.4)。
        // 範囲内 (= snapshot 内 entry またはその下の階層) は自由に navigate 可能
        // (§4.4 「captured folder の中の child folder」)。判定は `snapshot_owner_entry`
        // で path 完全一致または prefix 一致を見る。
        // snapshot_internal_nav は snapshot_load_and_open 経由の forced bypass (= 既知
        // safe path のみ)、ここの owner_entry チェックは UI 経由 click を扱う。
        if !detached_physical
            && self.is_snapshot_active()
            && !self.snapshot_internal_nav
            && self.snapshot_owner_entry(&path).is_none()
        {
            // 範囲外で load がブロックされると、開く直前に立てた自動フルスクリーン予約を
            // load_zip_as_folder が消化できず stale 化する (Codex P3: ★固定中に範囲外の
            // 変換アーカイブ/ZIP/PDF を開こうとしたケース)。ここで明示的にクリアして、
            // 次の正当な open が誤ってフルスクリーンになるのを防ぐ。
            self.pending_auto_fs_open = false;
            self.show_feedback_toast(
                "スナップショット中は範囲外のフォルダに移動できません (★固定を解除してください)"
                    .into(),
            );
            return;
        }
        // perf: UI スレッドをブロックする load_folder 全体の wall time を計測する。
        // Ctrl+↑↓ 連打時の引っかかりの主要因がここに集まる想定。
        let lf_t0 = std::time::Instant::now();
        let lf_seq = self.input_seq;
        let pre_scanned = pre_scan.is_some();
        // path.display().to_string() のアロケーションを perf-log 有効時に限定する
        // (通常起動では空文字のまま放置する)。
        let lf_path_disp: String = if crate::perf::is_enabled() {
            path.display().to_string()
        } else {
            String::new()
        };
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "load_folder_begin",
                None,
                lf_seq,
                &[
                    ("path", serde_json::Value::from(lf_path_disp.clone())),
                    ("pre_scanned", serde_json::Value::from(pre_scanned)),
                ],
            );
        }
        let folder_changes = self
            .current_folder
            .as_ref()
            .map(|current| !crate::folder_tree::path_eq(current, &path))
            .unwrap_or(true);
        if folder_changes {
            // ファイル名スタックは「現在フォルダに束縛されたビューモード」なので、別フォルダへ
            // ナビゲートしたら自動解除する (plan §3.5)。同一フォルダ再読込 (ソート変更・外部更新・
            // メンバーグリッドからの戻り) では folder_changes=false なので維持される。
            self.stack_mode_requested = false;
            if !detached_physical {
                self.clear_archive_convert_nav_history_rollback();
            }
            // **review #11/#13 対応**: 前フォルダ向けの catch-up / neighbor-prefetch
            // ジョブをまとめてキャンセル & queue から破棄する。これにより:
            //   - 未処理 job が即 drop され、握っていた `Arc<CatalogDb>` が解放される
            //     (catalog_cache LRU が実際に Connection を close できるようになる)
            //   - 進行中の render_page / enumerate_pages が cancel flag を読んで
            //     Interrupted で抜け、PDF worker Normal 枠を即解放する
            //   - 新フォルダ向けの enqueue は新しい cancel flag で焼き付くので、
            //     混ざらない
            if !detached_physical {
                crate::thumb_loader::bump_catchup_epoch();
                // PDF render pool の context epoch も bump し、前フォルダの page-grid
                // render ジョブを stale prune する。`load_pdf_as_folder` の async enumerate
                // 待ちの間も保護されるよう、`start_loading_items` (= helper 経由) より早い
                // load_folder の入口で先に bump する (二重 bump は fetch_add で別 epoch
                // になるだけで無害)。
                let _ = crate::pdf_loader::bump_render_context_epoch();
            }
        }
        self.record_folder_nav_transition(&path);
        // パスが .zip / .cbz / .pdf ファイルなら仮想フォルダとして開く
        if path.is_file() {
            let ext = path
                .extension()
                .and_then(|e| e.to_str())
                .map(|e| e.to_ascii_lowercase())
                .unwrap_or_default();
            if crate::folder_tree::is_zip_extension(&ext) {
                self.load_zip_as_folder(path);
                if crate::perf::is_enabled() {
                    crate::perf::event(
                        "nav",
                        "load_folder_end",
                        None,
                        lf_seq,
                        &[
                            (
                                "ms",
                                serde_json::Value::from(lf_t0.elapsed().as_secs_f64() * 1000.0),
                            ),
                            ("kind", serde_json::Value::from("zip")),
                            ("path", serde_json::Value::from(lf_path_disp)),
                        ],
                    );
                }
                return;
            }
            if ext == "pdf" {
                self.load_pdf_as_folder(path);
                if crate::perf::is_enabled() {
                    crate::perf::event(
                        "nav",
                        "load_folder_end",
                        None,
                        lf_seq,
                        &[
                            (
                                "ms",
                                serde_json::Value::from(lf_t0.elapsed().as_secs_f64() * 1000.0),
                            ),
                            ("kind", serde_json::Value::from("pdf")),
                            ("path", serde_json::Value::from(lf_path_disp)),
                        ],
                    );
                }
                return;
            }
        }

        crate::logger::log(format!("=== load_folder: {} ===", path.display()));

        // フォルダ移動でメタ操作の Undo/Redo スタックを破棄する (移動先で過去の
        // レーティング操作を巻き戻すと UX が混乱するため)。
        if !detached_physical {
            self.clear_meta_undo();
        }

        // 外側の ZIP/PDF/フォルダを切り替えたので、ネスト ZIP バイト列キャッシュを破棄する。
        // これで古い外側アーカイブのバイト列が RAM に居残るのを防ぐ。
        crate::zip_loader::clear_nested_cache();
        // ZIP を出るのでツリーナビ状態も破棄 (start_loading_items でも消えるが、
        // enumerate pending 窓中の stale 参照を防ぐため早期にクリア)。
        self.zip_nav = None;

        // ── ディレクトリ走査（画像はメタデータも収集）────────────────
        // pre_scan が与えられていれば DFS スレッドで既に走査済み (UI 非ブロック)。
        // 無ければ UI スレッドで scan_directory を呼ぶ (従来挙動)。
        let scan_t0 = std::time::Instant::now();
        let scan = match pre_scan {
            Some(scan) => scan,
            None => match scan_directory_with_settings(&path, &self.settings) {
                Ok(scan) => scan,
                Err(error) => {
                    crate::logger::log(format!(
                        "load_folder scan failed path={} error={error}",
                        path.display()
                    ));
                    self.pending_auto_fs_open = false;
                    self.release_fs_nav_lock();
                    self.show_feedback_toast("フォルダを読み取れませんでした".to_string());
                    return;
                }
            },
        };
        // Keep the image-book boundary independent from the caller and from the eventual
        // detached/main owner. Grid Folder preflight uses this same predicate before it
        // commits a context, preventing the two load paths from drifting apart.
        let scanned_folder_is_image_book = self.scanned_folder_is_image_book(&path, &scan);
        // フォーカス復帰時の差分判定用シグネチャ。scan を消費する前に計算しておき、
        // `start_loading_items` に引数として渡す。
        let folder_signature = signature_from_scan(&scan);
        let mut omitted_entries = scan.omitted;
        let (mut folders, mut folder_metas): (Vec<GridItem>, Vec<Option<(i64, i64)>>) =
            scan.folders.into_iter().unzip();
        let mut all_media = scan.all_media;
        let is_book_page_folder =
            crate::books::is_direct_book_folder(&self.book_root_path(), &path);
        if is_book_page_folder {
            // 本の中は「番号付き画像だけ」が正本。ユーザーが手動で ZIP/PDF/フォルダ/動画/音声を
            // 混ぜてもページとして扱わず、通常フォルダ閲覧のコンテナブロックも出さない。
            folders.clear();
            folder_metas.clear();
            all_media
                .retain(|(_, kind, _, _)| *kind == crate::app::folder_scan::ScanMediaKind::Image);
        }

        let scan_ms = scan_t0.elapsed().as_secs_f64() * 1000.0;
        let scan_folders = folders.len();
        let scan_media = all_media.len();
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "lf_scan",
                None,
                lf_seq,
                &[
                    ("ms", serde_json::Value::from(scan_ms)),
                    ("folders", serde_json::Value::from(scan_folders)),
                    ("media", serde_json::Value::from(scan_media)),
                    ("pre_scanned", serde_json::Value::from(pre_scanned)),
                ],
            );
        }

        let sort_t0 = std::time::Instant::now();
        let folder_sort = self.book_sort_order_for_path(&path);
        let media_sort = folder_media_sort_order(
            folder_sort,
            is_book_page_folder,
            folders.is_empty(),
            all_media
                .iter()
                .all(|(_, kind, _, _)| *kind == crate::app::folder_scan::ScanMediaKind::Image),
            self.settings.auto_fullscreen_image_folders_enabled(),
        );
        // folders (Folder / ZipFile / PdfFile / ConvertibleArchive) も sort_order に
        // 従って並べる (Explorer / Finder と同じ慣習で 2 段構成は維持)。
        crate::grid_item::sort_folder_block(&mut folders, &mut folder_metas, folder_sort);
        let mut keyed_media: Vec<_> = all_media
            .into_iter()
            .map(|entry| {
                let name = entry.0.file_name().and_then(|n| n.to_str()).unwrap_or("");
                let key = media_sort.name_key(name);
                (entry, key)
            })
            .collect();
        keyed_media.sort_by(|(a, ak), (b, bk)| media_sort.compare_name_keys(ak, a.2, bk, b.2));
        all_media = keyed_media.into_iter().map(|(entry, _)| entry).collect();
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "lf_sort",
                None,
                lf_seq,
                &[(
                    "ms",
                    serde_json::Value::from(sort_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // ── 同名ファイルフィルタ ─────────────────────────────────────
        let dup_t0 = std::time::Instant::now();
        self.video_thumb_overrides.clear();
        omitted_entries.same_name =
            self.apply_duplicate_filters(&mut folders, &mut folder_metas, &mut all_media);
        if !detached_physical
            && matches!(
                self.top_level_grid_view.surface(),
                top_level_grid_view::TopLevelGridSurface::Folder
            )
        {
            // main の通常フォルダだけがこの常設チップの対象。サブ展開・スマートフォルダ・
            // 検索結果は後追い範囲なので、同じ filter を共有していてもここへ公開しない。
            self.normal_folder_omitted_entries = Some(NormalFolderOmittedEntries {
                folder: path.clone(),
                counts: omitted_entries,
            });
        }
        if omitted_entries != folder_scan::OmittedFolderEntryCounts::default() {
            // チップが出ない / 数が合わないという報告を、推測でなくログで切り分けるための 1 行。
            // 走査済みの値を書くだけで追加の I/O は無い。
            crate::logger::log(format!(
                "omitted entries: same_name={} hidden={} unsupported={} system={} chip={} \
                 published={} surface={:?}",
                omitted_entries.same_name,
                omitted_entries.hidden,
                omitted_entries.unsupported,
                omitted_entries.system,
                omitted_entries.primary_count(),
                !detached_physical,
                self.top_level_grid_view.surface(),
            ));
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "lf_dup_filter",
                None,
                lf_seq,
                &[(
                    "ms",
                    serde_json::Value::from(dup_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // items を一度全カテゴリへ materialize し、共通 helper で設定された表示行へ配置する。
        let mut items: Vec<GridItem> = folders;
        let mut image_metas: Vec<Option<(i64, i64)>> = folder_metas;

        for (p, media_kind, mtime, file_size) in &all_media {
            match media_kind {
                crate::app::folder_scan::ScanMediaKind::Video => {
                    items.push(GridItem::Video(p.clone()));
                    image_metas.push(Some((*mtime, *file_size)));
                }
                crate::app::folder_scan::ScanMediaKind::Audio => {
                    // 音声はフルスクリーンで音楽ビューを開く。サムネは固定の音楽アイコン
                    // (波形サムネは生成しないので video_items のようなサムネ要求は不要)。
                    items.push(GridItem::Audio(p.clone()));
                    image_metas.push(Some((*mtime, *file_size)));
                }
                crate::app::folder_scan::ScanMediaKind::Image => {
                    items.push(GridItem::Image(p.clone()));
                    image_metas.push(Some((*mtime, *file_size)));
                }
            }
        }
        crate::grid_item::arrange_grid_items(
            &mut items,
            &mut image_metas,
            &self.settings.grid_display_order,
            Some(media_sort),
        );
        let video_items = crate::filename_stack_ui::stack_video_items(&items, &image_metas);
        let auto_open_image_folder = if std::mem::take(&mut self.pending_auto_fs_open) {
            self.settings.auto_fullscreen_image_folders_enabled() && scanned_folder_is_image_book
        } else {
            false
        };

        // 画像ファイル名集合 (カタログ掃除用キー)。pinned 形式 (`{base}#pin:{source_id}`)
        // も含めることで、`delete_missing` がピン由来の cache 行を巻き添えで消さない
        // (Codex Phase B P2 指摘)。pin DB lookup は load_folder 1 回あたり 1 度だけ実行。
        let pin_map_for_existing: std::collections::HashMap<
            String,
            crate::folder_thumb_pins::FolderPinSource,
        > = if let Some(db) = self.folder_thumb_pin_db.as_ref() {
            let containers: Vec<&std::path::Path> = items
                .iter()
                .filter_map(|it| match it {
                    GridItem::Folder(p) | GridItem::ZipFile(p) | GridItem::PdfFile(p) => {
                        Some(p.as_path())
                    }
                    GridItem::ConvertibleArchive { path, .. } => Some(path.as_path()),
                    _ => None,
                })
                .collect();
            if containers.is_empty() {
                std::collections::HashMap::new()
            } else {
                db.lookup_many(containers)
            }
        } else {
            std::collections::HashMap::new()
        };
        let existing_keys: std::collections::HashSet<String> = items
            .iter()
            .zip(image_metas.iter())
            .flat_map(|(it, meta)| {
                folder_thumb_existing_keys_for(
                    it,
                    *meta,
                    &pin_map_for_existing,
                    self.folder_thumb_pin_db.as_deref(),
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                    use_full_path_cache_keys_for_folder(&path),
                )
            })
            .collect();

        // 訪問時自動索引化は廃止。「名前」フル索引化 ON のお気に入りのみ
        // name_bulk_indexer 経由で全走査する (検索結果が閲覧履歴に依らないように)。

        // ファイル名スタック: スタックモード ON のときは、グループ分けを **常にスクリプト
        // (ワーカー)** で行う。
        // - 「分類ルールをスクリプトで行う」OFF → 内蔵既定スクリプト (DEFAULT_SCRIPT、
        //   mXD/末尾連番/先頭連番/連写のカスケード)。
        // - ON → ユーザーの stack_rules.rhai (無ければ内蔵既定)。
        // どちらも UI スレッドでは走らせない (重くなり得る) ので通常フォルダを先に表示し、
        // 完了後 poll_stack_script が集約ビューへ差し替える。組み込み separator ルールは
        // スクリプト失敗時のフォールバックのみ (旧「OFF=末尾連番だけ」の同期パスは廃止)。
        // existing_keys は **変換前の全 items** から集めてあり (= 全メンバーのサムネキャッシュ
        // キーを保持するので delete_missing が非代表メンバーを巻き添えで消さない)、ワーカー完了時に
        // start_loading_items へ渡すため消費前に複製しておく。
        let stack_on = self.stack_mode_requested;
        let stack_async_prep = if stack_on {
            // スクリプト本文の読み込み (ファイル I/O) はワーカー側で行うので、ここでは
            // 「スクリプトを使うか」のフラグだけを渡す (UI スレッドの同期 read_to_string 回避)。
            let script_enabled = self.settings.stack_script_enabled;
            let (passthrough, passthrough_metas, media) =
                crate::filename_stack_ui::extract_stack_parts(&items, &image_metas);
            Some((
                script_enabled,
                self.settings.stack_separator,
                passthrough,
                passthrough_metas,
                media,
                existing_keys.clone(),
                path.clone(),
            ))
        } else {
            None
        };
        self.stack_active_rule = None;
        self.stack_script_error = None;

        let items_len = items.len();
        self.start_loading_items(
            path,
            items,
            image_metas,
            existing_keys,
            video_items,
            Some(folder_signature),
        );
        if let Some((
            script_enabled,
            separator,
            passthrough,
            passthrough_metas,
            media,
            stack_existing,
            stack_folder,
        )) = stack_async_prep
        {
            // start_loading_items が stack_mode_requested / stack_script_pending をリセットした
            // 後で、通常フォルダ表示のままワーカーへグループ分けを投げる。
            self.stack_mode_requested = true;
            self.spawn_stack_script_worker(
                stack_folder,
                passthrough,
                passthrough_metas,
                media,
                separator,
                folder_sort,
                stack_existing,
                Some(folder_signature),
                script_enabled,
                false,
            );
        }

        if auto_open_image_folder {
            let mut new_idx = if self.settings.book_open_resume.resumes() {
                self.resume_page_for_container()
            } else {
                None
            };
            if new_idx.is_none() {
                new_idx = self.find_fullscreen_nav_target_filtered(false);
            }
            if let Some(new_idx) = new_idx {
                #[cfg(windows)]
                {
                    // `pending_auto_fs_open` はグリッド/外部からの明示的なフォルダ open に
                    // 由来する one-shot。画像のみ通常フォルダは列挙後にここで初めて
                    // open_fullscreen するため、ZIP/PDF の DeferredFsReopen と同様に
                    // grid-origin の意図を復元してから開く。これを省くと always-new
                    // detached で「継続ナビ」扱いになり、直前 active 窓を再利用してしまう。
                    self.fs_open_intent_from_grid = true;
                }
                self.open_fullscreen(new_idx, crate::app::HistoryTrigger::UserChosen);
                self.selected = Some(new_idx);
                self.scroll_to_selected = true;
                self.update_last_selected_image();
            }
        }

        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "load_folder_end",
                None,
                lf_seq,
                &[
                    (
                        "ms",
                        serde_json::Value::from(lf_t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                    ("kind", serde_json::Value::from("folder")),
                    ("path", serde_json::Value::from(lf_path_disp)),
                    ("items", serde_json::Value::from(items_len)),
                ],
            );
        }
        if !detached_physical {
            self.update_smart_folder_scoped_address();
        }
    }

    /// 名前索引フラグ (`auto_index_structure`) の OFF→ON / ON→OFF 遷移を即時反映する。
    /// 呼び出し側はすでに `settings.favorites[*].auto_index_structure` を更新した後に呼ぶ。
    ///
    /// - false → true: 既存 supervisor があれば先に drop、新規 supervisor を spawn。
    ///   supervisor が初期バルクを走らせ、その後 notify-rs で差分追従する。
    /// - true → false: supervisor を drop し、`search_index_db` をクリア。
    ///   **順序重要**: supervisor の drop (cancel + join) を先に完了させないと、
    ///   in-flight upsert が clear_for_favorite 後に走って索引を復活させる race が
    ///   発生する。
    pub(crate) fn apply_favorite_name_index_change(
        &mut self,
        fav_id: uuid::Uuid,
        fav_path: &std::path::Path,
        new_on: bool,
    ) {
        // 既存 supervisor があれば drop (OFF 遷移だけでなく ON→ON でも念のため:
        // path 変更等で spawn し直すシナリオ)。
        // `drop(handle)` は `thread.join()` を待つため、bulk scan 進行中は UI が
        // 数百 ms ブロックする。signal_stop で cancel は立ててから、実際の join は
        // バックグラウンドスレッドに逃がす。spawn 失敗時は closure が現スレッドで drop
        // されるので同期 join にフォールバックする (UI ブロックするが整合性は保たれる)。
        //
        // T53 (Codex R-SEARCH-002 / 2026-05-16): OFF 遷移の `clear_for_favorite` は
        // **必ず supervisor の join 完了後**に走らせる。旧コードは joiner スレッドを
        // spawn した直後に UI スレッドで clear を呼んでいたため、supervisor の最後の
        // upsert が DB mutex 待ち中に clear が走り、その後 upsert が完了して OFF 後の
        // 索引にゴーストレコードを残す race があった。new_on=false 経路では clear を
        // joiner closure 内に移し、join 完了後 (= in-flight upsert 全消化後) に走らせる。
        let existing_handle = self.name_index_supervisors.remove(&fav_id);
        let clear_target = if !new_on {
            self.search_index_db
                .as_ref()
                .map(|db| (Arc::clone(db), fav_path.to_path_buf()))
        } else {
            None
        };
        if let Some(handle) = existing_handle {
            handle.signal_stop();
            // T53 + Codex post-merge P3 (2026-05-16): spawn 失敗時に closure 内のロジック
            // が走らない問題を回避する。`std::thread::Builder::spawn` は失敗時 closure を
            // **実行せずに drop** するだけなので、closure 内に `clear_for_favorite` を入れて
            // しまうと spawn 失敗時に索引クリアが永久に行われない (= 低頻度だが OFF 後にも
            // 行が残る)。
            //
            // mpsc 経由でハンドル + clear_target を background worker に手渡しする構造に
            // すれば、spawn 成功時は worker が同じ処理を行い、spawn 失敗時は handle と
            // clear_target が外側に残るので main thread で同期実行できる。**どちらの経路
            // でも join → clear の順序は保たれる**。
            let (tx, rx) = mpsc::channel::<(
                crate::name_index_supervisor::NameIndexSupervisorHandle,
                Option<(
                    Arc<crate::search_index_db::SearchIndexDb>,
                    std::path::PathBuf,
                )>,
            )>();
            let spawn_result = std::thread::Builder::new()
                .name(format!("name-index-joiner-{}", fav_id.as_simple()))
                .spawn(move || {
                    if let Ok((handle, target)) = rx.recv() {
                        run_name_index_off_completion(handle, target);
                    }
                });
            match spawn_result {
                Ok(_) => {
                    // worker が rx.recv で待機中。ここで handle + clear_target を譲渡。
                    let _ = tx.send((handle, clear_target));
                }
                Err(e) => {
                    crate::logger::log(format!(
                        "name-index-joiner spawn failed, sync join instead: {e}"
                    ));
                    drop(tx); // rx もすでに drop 済 (closure dropped by failed spawn)
                    run_name_index_off_completion(handle, clear_target);
                }
            }
        } else if let Some((db, path)) = clear_target {
            // 既存 supervisor が居なかった場合 (= 既に OFF だが clear を念のため呼ぶ
            // / 起動直後の冪等処理) はそのまま同期 clear。
            if let Err(e) = db.clear_for_favorite(&path) {
                crate::logger::log(format!(
                    "favorites: clear name index for {} failed: {e}",
                    path.display()
                ));
            }
        }

        let Some(db) = self.search_index_db.as_ref() else {
            return;
        };
        if new_on {
            crate::logger::log(format!(
                "favorites: spawning name index supervisor for {}",
                fav_path.display()
            ));
            let handle = crate::name_index_supervisor::spawn(
                fav_id,
                fav_path.to_path_buf(),
                Arc::clone(db),
                vec![self.settings.books_root_path()],
                Some(Arc::clone(&self.activity_gate)),
            );
            self.name_index_supervisors.insert(fav_id, handle);
        }
    }

    /// 起動時 IndexerManager 初期化をバックグラウンドスレッドで開始する。
    /// 1 度しか走らせない。
    pub(crate) fn kick_off_startup_init(&mut self) {
        if self.startup_init.is_some() || self.startup_done {
            return;
        }
        #[cfg(windows)]
        self.kick_off_vst3_startup_load();
        let favorites = self.settings.favorites.clone();
        let speed = self.settings.indexer_speed_profile;
        let excluded_roots = vec![self.settings.books_root_path()];
        let activity_gate = Arc::clone(&self.activity_gate);
        let progress = Arc::clone(&self.startup_progress);
        let (tx, rx) = mpsc::channel();
        let started_at = std::time::Instant::now();
        let hook = make_progress_hook(Arc::clone(&progress));
        let spawn_result = std::thread::Builder::new()
            .name("startup-init".to_string())
            .spawn({
                let hook = Arc::clone(&hook);
                move || {
                    let t = std::time::Instant::now();
                    let mgr = crate::indexer_manager::IndexerManager::new(
                        &favorites,
                        speed,
                        activity_gate,
                        excluded_roots,
                        Some(hook),
                    );
                    crate::perf::emit_ms("startup", "indexer_manager_new", 0, t);
                    let _ = tx.send(mgr);
                }
            });
        if let Err(e) = spawn_result {
            // フォールバック: スレッド起動に失敗したら同期で実行する
            // (スレッド数制限の極端な環境向け保険)。
            crate::logger::log(format!(
                "startup-init spawn failed: {e} — running synchronously"
            ));
            self.indexer_manager = crate::indexer_manager::IndexerManager::new(
                &self.settings.favorites,
                self.settings.indexer_speed_profile,
                Arc::clone(&self.activity_gate),
                vec![self.settings.books_root_path()],
                Some(hook),
            );
            self.startup_done = true;
            self.housekeeping_armed = true;
            return;
        }
        self.startup_init = Some(StartupInitPending { rx, started_at });
    }

    /// 起動直後の VST3 bridge enable + チェーン自動ロードを UI とは独立に開始する。
    #[cfg(windows)]
    pub(crate) fn kick_off_vst3_startup_load(&mut self) {
        if self.vst3_init_kicked || !self.settings.vst3_enabled {
            return;
        }
        self.vst3_init_kicked = true;
        let plugins = self.settings.vst3_plugins.clone();
        if plugins.is_empty() {
            crate::logger::log("[VST3 startup] skipped: no configured plugins");
            return;
        }

        let bridge = self.dsp_bridge.clone();
        let progress = Arc::new(Mutex::new("VST3 プラグインを初期化中…".to_string()));
        let worker_progress = Arc::clone(&progress);
        let (tx, rx) = mpsc::channel();
        let started_at = std::time::Instant::now();
        // T21 (Codex R-VST-001): 起動 load と chain rebuild の interleave 防止。
        // 起動 load も世代を取り、後続 rebuild が来たら諦める。
        let my_gen = bridge.bump_chain_rebuild_gen();
        let spawn_result = std::thread::Builder::new()
            .name("vst3-startup-load".to_string())
            .spawn(move || {
                run_vst3_startup_load(bridge, plugins, worker_progress, my_gen);
                let _ = tx.send(());
            });
        match spawn_result {
            Ok(_) => {
                crate::logger::log("[VST3 startup] background load started");
                self.vst3_startup_load = Some(Vst3StartupLoadPending {
                    rx,
                    progress,
                    started_at,
                });
            }
            Err(e) => {
                crate::logger::log(format!("[VST3 startup] background load spawn failed: {e}"));
            }
        }
    }

    #[cfg(windows)]
    fn take_mounted_deferred_vst3_media_open(&mut self) -> Option<usize> {
        let idx = self.vst3_deferred_media_open.take()?;
        (self.fullscreen_idx == Some(idx)
            && matches!(
                self.items.get(idx),
                Some(GridItem::Video(_) | GridItem::Audio(_))
            )
            && !self.fs_cache.contains_key(&idx))
        .then_some(idx)
    }

    #[cfg(windows)]
    fn consume_deferred_vst3_media_open_in_all_contexts(
        &mut self,
        mut consume: impl FnMut(&mut Self, usize),
    ) {
        if let Some(idx) = self.take_mounted_deferred_vst3_media_open() {
            consume(self, idx);
        }

        let active_has_pending = self
            .active_detached_viewer_context
            .as_ref()
            .is_some_and(|active| active.bundle.vst3_deferred_media_open.is_some());
        if active_has_pending && let Some(mut active) = self.active_detached_viewer_context.take() {
            self.swap_viewer_context_bundle(&mut active.bundle);
            if let Some(idx) = self.take_mounted_deferred_vst3_media_open() {
                consume(self, idx);
            }
            self.swap_viewer_context_bundle(&mut active.bundle);
            self.active_detached_viewer_context = Some(active);
        }

        self.consume_deferred_vst3_media_open_in_parked_contexts(&mut consume);
    }

    #[cfg(windows)]
    fn consume_deferred_vst3_media_open_in_parked_contexts(
        &mut self,
        consume: &mut impl FnMut(&mut Self, usize),
    ) {
        let ids: Vec<u64> = self
            .detached_image_windows
            .iter()
            .filter(|window| {
                window
                    .paused_bundle
                    .as_deref()
                    .is_some_and(|bundle| bundle.vst3_deferred_media_open.is_some())
            })
            .map(|window| window.id)
            .collect();
        for id in ids {
            let Some(pos) = self
                .detached_image_windows
                .iter()
                .position(|window| window.id == id)
            else {
                continue;
            };
            let Some(mut bundle) = self.detached_image_windows[pos].paused_bundle.take() else {
                continue;
            };
            self.swap_viewer_context_bundle(&mut bundle);
            let saved_input_window_id = self.native_video_parked_live_input_window_id;
            self.native_video_parked_live_input_window_id = Some(id);
            if let Some(idx) = self.take_mounted_deferred_vst3_media_open() {
                consume(self, idx);
            }
            self.native_video_parked_live_input_window_id = saved_input_window_id;
            self.swap_viewer_context_bundle(&mut bundle);
            if let Some(window) = self
                .detached_image_windows
                .iter_mut()
                .find(|window| window.id == id)
            {
                window.paused_bundle = Some(bundle);
            }
        }
    }

    #[cfg(windows)]
    pub(crate) fn resume_deferred_vst3_media_open(&mut self, ctx: &egui::Context) {
        // mounted main だけでなく promote 済み active / ParkedLive bundle も同じ ownership
        // seam で mount し、各 context 自身の pending を消費する。
        // (review-v2.3.0 追補 BA-7: vst3 deferred)
        self.consume_deferred_vst3_media_open_in_all_contexts(|app, idx| {
            crate::logger::log(format!(
                "[VST3 startup] deferred media open resumes idx={idx}"
            ));
            app.start_fs_load(idx);
            ctx.request_repaint();
        });
    }

    #[cfg(windows)]
    pub(crate) fn poll_vst3_startup_load(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.vst3_startup_load.as_ref() else {
            return;
        };
        match pending.try_recv() {
            Ok(()) => {
                crate::logger::log(format!(
                    "[VST3 startup] background load completed in {:.0} ms",
                    pending.elapsed_ms()
                ));
                self.vst3_startup_load = None;
                self.resume_deferred_vst3_media_open(ctx);
            }
            Err(mpsc::TryRecvError::Empty) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(200));
            }
            Err(mpsc::TryRecvError::Disconnected) => {
                crate::logger::log("[VST3 startup] background load worker disconnected");
                self.vst3_startup_load = None;
                self.resume_deferred_vst3_media_open(ctx);
            }
        }
    }

    pub fn configure_play_test(&mut self, config: PlayTestConfig) {
        crate::logger::log(format!(
            "[play-test] configured path={} duration_ms={} mute={} start_secs={:?} skip_vst3={}",
            config.path.display(),
            config.duration.as_millis(),
            config.mute,
            config.start_secs,
            config.skip_vst3
        ));
        if config.skip_vst3 {
            self.settings.vst3_enabled = false;
            self.vst3_init_kicked = true;
            crate::logger::log("[play-test] VST3 startup skipped for playback benchmark");
        }
        self.play_test = Some(PlayTestState::new(config));
    }

    pub(crate) fn poll_play_test(&mut self, ctx: &egui::Context) {
        if self.play_test.as_ref().is_none_or(|s| s.close_sent) {
            return;
        }
        if !self.startup_done {
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
            return;
        }

        if self
            .play_test
            .as_ref()
            .and_then(|s| s.launched_idx)
            .is_none()
        {
            let Some(config) = self.play_test.as_ref().map(|s| s.config.clone()) else {
                return;
            };
            if let Some(parent) = config.path.parent().map(PathBuf::from) {
                if self.current_folder.as_deref() != Some(parent.as_path()) {
                    crate::logger::log(format!(
                        "[play-test] loading parent folder before launch path={} parent={}",
                        config.path.display(),
                        parent.display()
                    ));
                    self.load_folder(parent);
                    ctx.request_repaint_after(std::time::Duration::from_millis(50));
                    return;
                }
            }
            let target_key = crate::adjustment_db::normalize_path(&config.path);
            let idx = self
                .items
                .iter()
                .enumerate()
                .find_map(|(idx, item)| match item {
                    GridItem::Video(path)
                        if crate::adjustment_db::normalize_path(path) == target_key =>
                    {
                        Some(idx)
                    }
                    _ => None,
                })
                .unwrap_or_else(|| {
                    // If the folder view filtered the file out for any reason, keep the
                    // soak test deterministic by injecting a one-off video item after
                    // the parent folder has already been loaded.
                    let idx = self.items.len();
                    self.items.push(GridItem::Video(config.path.clone()));
                    self.image_metas.push(None);
                    self.thumbnails.push(ThumbnailState::Pending);
                    self.bump_items_generation();
                    self.invalidate_facet_name_cache();
                    self.visible_indices.push(idx);
                    idx
                });
            self.selected = Some(idx);
            self.fs_open_intent_from_grid = true;
            self.open_fullscreen(idx, crate::app::HistoryTrigger::UserChosen);
            if let Some(state) = self.play_test.as_mut() {
                state.launched_idx = Some(idx);
            }
            crate::logger::log(format!(
                "[play-test] launched idx={} path={}",
                idx,
                config.path.display()
            ));
            if crate::perf::is_enabled() {
                crate::perf::event(
                    "play_test",
                    "launched",
                    Some(&config.path.display().to_string()),
                    0,
                    &[
                        ("idx", serde_json::Value::from(idx as i64)),
                        (
                            "duration_ms",
                            serde_json::Value::from(config.duration.as_secs_f64() * 1000.0),
                        ),
                        ("mute", serde_json::Value::from(config.mute)),
                    ],
                );
            }
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
            return;
        }

        let Some(idx) = self.play_test.as_ref().and_then(|s| s.launched_idx) else {
            return;
        };
        let video_snapshot = match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Video { player, .. }) => Some((
                player.is_playing(),
                player.pending_frames(),
                player.engine_state_code(),
                player.position(),
                player.duration(),
            )),
            _ => None,
        };

        if let Some((is_playing, pending_frames, state_code, pos, dur)) = video_snapshot {
            if self
                .play_test
                .as_ref()
                .and_then(|s| s.playback_started_at)
                .is_none()
                && (is_playing || pending_frames > 0)
            {
                let now = std::time::Instant::now();
                if let Some(state) = self.play_test.as_mut() {
                    state.playback_started_at = Some(now);
                }
                crate::logger::log(format!(
                    "[play-test] playback started idx={idx} state={state_code} pending={pending_frames} pos={pos:.3}"
                ));
                if crate::perf::is_enabled() {
                    crate::perf::event(
                        "play_test",
                        "playback_started",
                        None,
                        0,
                        &[
                            ("idx", serde_json::Value::from(idx as i64)),
                            ("state", serde_json::Value::from(state_code as i64)),
                            (
                                "pending_frames",
                                serde_json::Value::from(pending_frames as i64),
                            ),
                            ("pos", serde_json::Value::from(pos)),
                            ("duration", serde_json::Value::from(dur)),
                        ],
                    );
                }
            }
        }

        let Some(started_at) = self.play_test.as_ref().and_then(|s| s.playback_started_at) else {
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
            return;
        };
        let duration = self
            .play_test
            .as_ref()
            .map(|s| s.config.duration)
            .unwrap_or_else(|| std::time::Duration::from_secs(30));
        if started_at.elapsed() >= duration {
            let final_snapshot = match self.fs_cache.get(&idx) {
                Some(FsCacheEntry::Video { player, .. }) => Some((
                    player.position(),
                    player.duration(),
                    player.pending_frames(),
                    player.engine_state_code(),
                )),
                _ => None,
            };
            if let Some((pos, dur, pending, state_code)) = final_snapshot {
                crate::logger::log(format!(
                    "[play-test] completed idx={idx} pos={pos:.3} duration={dur:.3} pending={pending} state={state_code}"
                ));
                if crate::perf::is_enabled() {
                    crate::perf::event(
                        "play_test",
                        "completed",
                        None,
                        0,
                        &[
                            ("idx", serde_json::Value::from(idx as i64)),
                            ("pos", serde_json::Value::from(pos)),
                            ("duration", serde_json::Value::from(dur)),
                            ("pending_frames", serde_json::Value::from(pending as i64)),
                            ("state", serde_json::Value::from(state_code as i64)),
                        ],
                    );
                }
            }
            crate::perf::flush();
            if let Some(state) = self.play_test.as_mut() {
                state.close_sent = true;
            }
            std::process::exit(0);
        } else {
            ctx.request_repaint_after(std::time::Duration::from_millis(200));
        }
    }

    #[cfg(windows)]
    pub(crate) fn vst3_startup_load_pending(&self) -> bool {
        self.vst3_startup_load.is_some()
    }

    #[cfg(windows)]
    pub(crate) fn vst3_startup_progress_text(&self) -> String {
        self.vst3_startup_load
            .as_ref()
            .map(|p| p.progress_text())
            .unwrap_or_else(|| "VST3 プラグインを初期化中…".to_string())
    }

    /// 起動 init の完了を確認する。完了していれば `indexer_manager` に注入し
    /// `startup_init = None`、`startup_done = true` に遷移する。
    /// `housekeeping_armed=true` の間、毎フレーム supervisor の idle 状態を見て、
    /// 全 supervisor が初回 scan を完了して idle になったら一度だけ spawn する。
    /// これにより VACUUM が初回 ingest と Mutex を取り合わないようにする。
    pub(crate) fn poll_housekeeping_arm(&mut self) {
        if !self.housekeeping_armed {
            return;
        }
        let Some(mgr) = self.indexer_manager.as_ref() else {
            // indexer 初期化失敗時はそもそも housekeeping も走らせない
            self.housekeeping_armed = false;
            return;
        };
        if mgr.all_supervisors_idle() {
            mgr.spawn_housekeeping(&crate::data_dir::get());
            self.housekeeping_armed = false;
        }
    }

    pub(crate) fn poll_startup_init(&mut self) {
        let Some(pending) = &self.startup_init else {
            return;
        };
        match pending.try_recv() {
            Ok(mgr) => {
                crate::logger::log(format!(
                    "startup: IndexerManager init completed in {:.0} ms",
                    pending.elapsed_ms()
                ));
                self.indexer_manager = mgr;
                self.startup_init = None;
                self.startup_done = true;
                self.housekeeping_armed = true;
                if let Ok(mut p) = self.startup_progress.lock() {
                    *p = "起動完了".to_string();
                }
            }
            Err(mpsc::TryRecvError::Empty) => {}
            Err(mpsc::TryRecvError::Disconnected) => {
                // bg スレッドが panic 等で落ちた: 検索機能なしで継続させる。
                crate::logger::log("startup: init thread disconnected unexpectedly");
                self.indexer_manager = None;
                self.startup_init = None;
                self.startup_done = true;
            }
        }
    }

    /// auto / manual の更新チェックを spawn する。
    ///
    /// - `manual=true`: ユーザー操作 (環境設定の「今すぐ確認」)。`update_check_enabled`
    ///   を無視して常に実行、結果ダイアログも常に開く
    /// - `manual=false`: 起動 5 秒後 + 24 時間ごとの auto。`update_check_enabled=false`
    ///   なら no-op、結果は新バージョン検知時のみバッジで通知
    ///
    /// 既に spawn 中 (rx が残っている) なら多重起動を防ぐため no-op。
    pub(crate) fn kick_update_check(&mut self, manual: bool) {
        if self.update_check_pending.is_some() {
            return;
        }
        if !manual && !self.settings.update_check_enabled {
            return;
        }
        self.update_check_last_spawn = Some(std::time::Instant::now());
        match crate::update_check::spawn_check(env!("CARGO_PKG_VERSION")) {
            Ok(rx) => {
                self.update_check_pending = Some(UpdateCheckPending { rx, manual });
            }
            Err(e) => {
                // スレッド起動自体の失敗。auto なら silent fail (ログのみ)、
                // manual ならユーザーが押した結果なのでエラーダイアログを出す。
                crate::logger::log(format!("update_check: spawn failed: {e}"));
                if manual {
                    self.update_check_error = Some(e);
                    self.show_update_dialog = true;
                }
            }
        }
    }

    /// 起動完了後の初回 + 24 時間ごとの auto kick。`App::update` の毎フレーム冒頭で呼ばれる。
    pub(crate) fn maybe_auto_update_check(&mut self) {
        if !self.settings.update_check_enabled {
            return;
        }
        if !self.startup_done {
            return; // 起動中はネットワークを走らせない
        }
        const PERIODIC: std::time::Duration = std::time::Duration::from_secs(24 * 3600);
        let due = match self.update_check_last_spawn {
            None => true, // 起動完了直後の初回
            Some(t) => t.elapsed() >= PERIODIC,
        };
        if due {
            self.kick_update_check(false);
        }
    }

    /// `update_check_pending` を非ブロッキング poll する。結果が来ていれば
    /// `update_info` に反映し、manual のときは結果ダイアログを開く。auto かつ
    /// 「新バージョンあり」のときはバッジで気付かせるだけ (ダイアログは開かない)。
    pub(crate) fn poll_update_check(&mut self) {
        let Some(pending) = self.update_check_pending.as_ref() else {
            return;
        };
        let result = match pending.rx.try_recv() {
            Ok(r) => Some(r),
            Err(std::sync::mpsc::TryRecvError::Empty) => return,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                // worker が送信前に panic した等の異常終了。manual ならユーザー操作が
                // 黙って終わらないようエラーダイアログを出す (auto は silent + log)。
                let was_manual = pending.manual;
                crate::logger::log(
                    "update_check: worker channel disconnected before sending result",
                );
                self.update_check_pending = None;
                if was_manual {
                    self.update_check_error =
                        Some("更新チェックの内部エラー (スレッド異常終了)".to_string());
                    self.show_update_dialog = true;
                }
                return;
            }
        };
        let pending = self.update_check_pending.take().unwrap();
        match result.unwrap() {
            Ok(info) => {
                let is_newer = info.is_newer;
                let tag = info.latest_tag.clone();
                // auto かつ更新確認 OFF の場合: spawn と結果到着の間で OFF に切り替わった
                // ケース。バッジを出さない契約を守るため、結果は破棄する (manual は常に
                // 結果を保持してダイアログで見せる)。
                if !pending.manual && !self.settings.update_check_enabled {
                    crate::logger::log(format!(
                        "update_check: dropping auto result ({tag}); user disabled checks"
                    ));
                    return;
                }
                self.update_info = Some(info);
                self.update_check_error = None;
                if pending.manual {
                    self.show_update_dialog = true;
                } else if is_newer {
                    crate::logger::log(format!("update_check: newer version found ({tag})"));
                }
            }
            Err(e) => {
                crate::logger::log(format!("update_check: failed: {e}"));
                if pending.manual {
                    // 既知の update_info はクリアしない (バッジを消さない)。
                    // 失敗ダイアログでは update_check_error を見て分岐する。
                    self.update_check_error = Some(e);
                    self.show_update_dialog = true;
                }
            }
        }
    }

    /// 通知バッジを表示すべきか (新バージョンあり、かつユーザーが skip していない)。
    /// `update_check_enabled=false` の間は結果を持っていてもバッジは出さない (OFF=
    /// 「通知も止める」と読める方が自然なため)。
    pub(crate) fn should_show_update_badge(&self) -> bool {
        if !self.settings.update_check_enabled {
            return false;
        }
        let Some(ref info) = self.update_info else {
            return false;
        };
        if !info.is_newer {
            return false;
        }
        match &self.settings.update_check_dismissed_version {
            Some(d) => d != &info.latest_tag,
            None => true,
        }
    }

    pub(crate) fn render_startup_overlay(&self, ctx: &egui::Context) {
        let progress_text = self
            .startup_progress
            .lock()
            .map(|s| s.clone())
            .unwrap_or_else(|_| "起動中…".to_string());
        // 背景全面に半透明の幕を引いてから中央に文字を出す。
        egui::CentralPanel::default()
            .frame(egui::Frame::NONE.fill(ctx.style().visuals.panel_fill))
            .show(ctx, |ui| {
                let rect = ui.available_rect_before_wrap();
                ui.painter().rect_filled(
                    rect,
                    egui::CornerRadius::ZERO,
                    ctx.style().visuals.panel_fill,
                );
                ui.scope_builder(
                    egui::UiBuilder::new().max_rect(rect).layout(
                        egui::Layout::centered_and_justified(egui::Direction::TopDown),
                    ),
                    |ui| {
                        ui.vertical_centered(|ui| {
                            ui.add_space(rect.height() * 0.3);
                            ui.spinner();
                            ui.add_space(12.0);
                            ui.label(egui::RichText::new("起動中…").size(20.0).strong());
                            ui.add_space(8.0);
                            ui.label(
                                egui::RichText::new(progress_text)
                                    .size(14.0)
                                    .color(ui.visuals().weak_text_color()),
                            );
                        });
                    },
                );
            });
    }

    /// 起動中の入力イベントを消費する (× ボタン以外)。Loading 終了後に
    /// 残ったキー入力が再生されてしまうのを防ぐため、events を空にする。
    /// `ViewportEvent::Close` だけは eframe 側で別経路を通るので影響しない。
    pub(crate) fn consume_input_during_startup(&self, ctx: &egui::Context) {
        ctx.input_mut(|i| {
            i.events.retain(|e| {
                // window 関連 (フォーカス・サイズ変更等) は通したい。Key/Mouse/Text のみ捨てる。
                !matches!(
                    e,
                    egui::Event::Key { .. }
                        | egui::Event::Text(_)
                        | egui::Event::PointerButton { .. }
                        | egui::Event::PointerMoved(_)
                        | egui::Event::MouseWheel { .. }
                        | egui::Event::Touch { .. }
                        | egui::Event::Ime(_)
                )
            });
        });
    }

    /// 起動時に `auto_index_structure = true` のお気に入りごとに name index supervisor を
    /// spawn する。`indexer_manager.sync_with_favorites` のメタ側の挙動に対応する。
    /// 呼び出しは `App` 構築後 (settings が load 済みで search_index_db が開いている状態) に
    /// 1 回だけ。
    pub(crate) fn spawn_initial_name_index_supervisors(&mut self) {
        let Some(db) = self.search_index_db.as_ref().cloned() else {
            return;
        };
        for fav in &self.settings.favorites {
            if !fav.auto_index_structure {
                continue;
            }
            if self.name_index_supervisors.contains_key(&fav.id) {
                continue;
            }
            crate::logger::log(format!(
                "startup: spawning name index supervisor for {}",
                fav.path.display()
            ));
            let handle = crate::name_index_supervisor::spawn(
                fav.id,
                fav.path.clone(),
                Arc::clone(&db),
                vec![self.settings.books_root_path()],
                Some(Arc::clone(&self.activity_gate)),
            );
            self.name_index_supervisors.insert(fav.id, handle);
        }
    }

    /// タイトルバーの「(インデックス更新中)」表示用。
    /// 名前索引 / メタ索引のいずれかが `in_full_scan=true` を返しているなら true。
    /// notify-rs の watcher で待機中 (監視中) は false。
    pub(crate) fn any_indexer_in_full_scan(&self) -> bool {
        // 名前索引
        for h in self.name_index_supervisors.values() {
            if h.snapshot_stats().in_full_scan {
                return true;
            }
        }
        // メタ索引
        if let Some(mgr) = self.indexer_manager.as_ref() {
            for v in mgr.all_stats() {
                if v.stats.in_full_scan {
                    return true;
                }
            }
        }
        false
    }

    // name_index_supervisors は HashMap の Drop で各 handle が個別に cancel + join
    // される。名前索引は SQLite ベースで Tantivy writer のような共有リソースが
    // 無いため、1 体ずつ drop してもデッドロックしない (メタ側の writer 共有とは違う)。

    /// メタデータ索引フラグ (`auto_index_metadata`) の OFF→ON / ON→OFF 遷移を即時反映する。
    /// 呼び出し側はすでに `settings.favorites[*].auto_index_metadata` を更新した後に呼ぶ。
    ///
    /// - false → true: 呼び出し側で `sync_with_favorites` を呼べば supervisor が spawn される
    /// - true → false: 当 favorite の fts_meta 行を tombstone 化 → `sync_with_favorites` で
    ///   supervisor を停止
    pub(crate) fn apply_favorite_meta_index_change(&mut self, fav_id: uuid::Uuid, new_on: bool) {
        if !new_on {
            if let Some(mgr) = self.indexer_manager.as_ref() {
                mgr.purge_favorite_metadata(fav_id);
            }
        }
        // spawn/stop は sync_with_favorites 側
        if let Some(mgr) = self.indexer_manager.as_mut() {
            mgr.sync_with_favorites(&self.settings.favorites);
        }
    }

    /// お気に入り検索バーを開く (メニューや Ctrl+S から呼ばれる)。
    /// 他の検索バー (Ctrl+F / Ctrl+G) が開いていれば閉じて相互排他を保つ。
    pub(crate) fn open_favsearch(&mut self) {
        let fallback_origin = self.current_folder.clone();
        let transferred_origin = self.take_origin_for_search_entry(SearchMode::Favsearch);
        self.favsearch.active = true;
        self.favsearch.focus_request = true;
        self.favsearch.nav_stack.clear();
        self.favsearch.results_paths.clear();
        // 検索モードに入る際、現在のフォルダを保存して戻れるようにする
        if let Some(origin) = transferred_origin {
            self.favsearch.saved_folder = origin.legacy_path().or(fallback_origin);
            self.favsearch_subfolder_restore = origin.subfolder_restore();
        } else if self.favsearch.saved_folder.is_none() {
            self.favsearch.saved_folder = fallback_origin;
            self.favsearch_subfolder_restore = None;
        }
    }

    /// タグビュー (Ctrl+T) を開く。
    pub(crate) fn open_tag_view(&mut self) {
        self.open_tag_view_with_query(None, true);
    }

    pub(crate) fn open_tag_view_for_tag(&mut self, tag_name: &str) {
        let query = crate::tags_db::format_display_tag(tag_name);
        if query.is_empty() {
            return;
        }
        if self.viewer_session_blocks_main_window() {
            self.close_fullscreen();
        }
        self.open_tag_view_with_query(Some(query), false);
    }

    fn open_tag_view_with_query(&mut self, query: Option<String>, focus_request: bool) {
        if self.tag_view.active {
            if let Some(query) = query {
                self.tag_view.query = query;
                self.tag_view.last_executed.clear();
                self.execute_tag_view();
            }
            if focus_request {
                self.tag_view.focus_request = true;
            }
            return;
        }
        let fallback_origin = self.current_folder.clone();
        let transferred_origin = self.take_origin_for_search_entry(SearchMode::TagView);
        self.tag_view.active = true;
        self.tag_view.focus_request = focus_request;
        if let Some(origin) = transferred_origin {
            self.tag_view.saved_folder = origin.legacy_path().or(fallback_origin);
            self.tag_view_subfolder_restore = origin.subfolder_restore();
        } else {
            self.tag_view.saved_folder = fallback_origin;
            self.tag_view_subfolder_restore = None;
        }
        if let Some(query) = query {
            self.tag_view.query = query;
            self.tag_view.last_executed.clear();
        }
        self.execute_tag_view();
    }

    pub(crate) fn toggle_tag_view(&mut self) {
        if self.tag_view.active {
            self.close_tag_view();
        } else {
            self.open_tag_view();
        }
    }

    /// Ctrl+F のローカルメタデータ検索バーを開く。
    /// 他の検索バーが開いていれば閉じる (相互排他)。
    pub(crate) fn open_local_metadata_search(&mut self) {
        let transferred_origin = self.take_origin_for_search_entry(SearchMode::LocalMeta);
        let restore_smart_folder = transferred_origin.as_ref().is_some_and(|origin| {
            origin
                .legacy_path()
                .as_deref()
                .is_some_and(smart_folder::is_smart_folder_synthetic_path)
        });
        if let Some(origin) = transferred_origin {
            self.restore_view_return_context(origin);
            if restore_smart_folder {
                // Keep the pending smart restore as the owner of the grid.  Its install boundary
                // will run the query typed while the worker is active against the final indices.
                self.smart_folder_local_search_reapply = Some(String::new());
            }
        }
        // スタック集約計算待ち (通常フォルダ表示中) に Ctrl+F が来たら、検索を優先する。
        // 放置するとワーカー完了時の `apply_stack_script_result` → `start_loading_items` が
        // `search_filter` / `search_query` をクリアし、入力した検索が消えてしまう
        // (= スタック ON 直後の短い窓で踏める race)。ワーカーをキャンセルしスタック意図も
        // 解除して、現在表示中の通常フォルダに対する検索を成立させる。集約完了後は
        // `stack_mode_available()` が検索中はトグルを禁止するので、ここで先回りして解除する。
        if self.stack_script_pending.is_some() {
            self.cancel_stack_script_pending();
            self.stack_mode_requested = false;
        }
        self.show_search_bar = true;
        self.search_focus_request = true;
    }

    /// 新しい検索へ入る前に、既存の最上位一時ビューが所有する本来の戻り先を取得する。
    ///
    /// 既存検索や検索由来Snapshotを通常closeすると、smart/subfolderの非同期復元を開始して
    /// 直後に次の検索がcancelする競合になる。ここでは表示を復元せず`TopLevelGridRestore`だけを
    /// 次の所有者へ移譲する。Ctrl+Fは一覧内filterなので、呼び出し側がcontextを復元してから
    /// 最終一覧へqueryを再適用する。
    pub(crate) fn take_origin_for_search_entry(
        &mut self,
        keep: SearchMode,
    ) -> Option<top_level_grid_view::TopLevelGridRestore> {
        let current_restore = self.current_top_level_restore_snapshot();
        let mut transferred = self.dismiss_snapshot_without_restore();
        if !matches!(keep, SearchMode::LocalMeta) && self.show_search_bar {
            self.show_search_bar = false;
            self.search_query.clear();
            self.search_filter = None;
            self.search_filter_origin_folder = None;
            self.search_has_focus = false;
            self.search_tag_bridge.clear();
            self.cancel_search_pending();
            self.rebuild_visible_indices();
        }
        if !matches!(keep, SearchMode::Favsearch) && self.favsearch.active {
            transferred = Some(self.dismiss_favsearch_without_restore());
        }
        if !matches!(keep, SearchMode::Global) && self.global_search.active {
            transferred = Some(self.dismiss_global_search_without_restore());
        }
        if !matches!(keep, SearchMode::TagView) && self.tag_view.active {
            transferred = Some(self.dismiss_tag_view_without_restore());
        }
        // A pending smart-folder worker may still own the pre-search origin while the previous
        // result grid remains visible. Its context is more authoritative than that synthetic path.
        if let Some(origin) = self.take_smart_folder_origin_for_search_entry() {
            transferred = Some(origin);
        }
        self.cancel_pending_folder_nav();
        if matches!(keep, SearchMode::LocalMeta) {
            return transferred;
        }
        let origin = transferred.or(current_restore);
        let search = match keep {
            SearchMode::Favsearch => top_level_grid_view::TopLevelSearchView::Favorite,
            SearchMode::Global => top_level_grid_view::TopLevelSearchView::Global,
            SearchMode::TagView => top_level_grid_view::TopLevelSearchView::Tag,
            SearchMode::LocalMeta => unreachable!(),
        };
        self.top_level_grid_view.begin(
            top_level_grid_view::TopLevelGridSurface::Search(search),
            origin.clone(),
        );
        origin
    }

    /// お気に入り検索バーを閉じて、元のフォルダに戻る。
    pub(crate) fn close_favsearch(&mut self) {
        let return_context = self.dismiss_favsearch_without_restore();
        self.restore_view_return_context(return_context);
    }

    /// Ctrl+S の状態だけを終了し、元ビューの再構築は行わず戻り先の所有権を返す。
    /// 別の最上位ビューへ直行するとき、復元 worker を起動直後にキャンセルする競合を防ぐ。
    pub(crate) fn dismiss_favsearch_without_restore(
        &mut self,
    ) -> top_level_grid_view::TopLevelGridRestore {
        self.cancel_pending_folder_nav();
        self.favsearch.active = false;
        self.favsearch.has_focus = false;
        self.favsearch.query.clear();
        self.favsearch.last_executed.clear();
        self.favsearch.nav_stack.clear();
        self.favsearch.results_paths.clear();
        if let Some(pending) = self.favsearch_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        let path = self.favsearch.saved_folder.take();
        let rating_view_stars = self.view_return_rating_view_stars_for_path(path.as_deref());
        let subfolder_restore = self.favsearch_subfolder_restore.take();
        let fallback =
            self.view_return_context_from_parts(path, subfolder_restore, rating_view_stars);
        self.top_level_grid_view
            .take_return_to()
            .unwrap_or(fallback)
    }

    pub(crate) fn restore_view_return_context(
        &mut self,
        context: top_level_grid_view::TopLevelGridRestore,
    ) {
        use top_level_grid_view::TopLevelGridRestore;

        let (saved, rating_view_stars) = match context {
            TopLevelGridRestore::SmartFolder(state) => {
                self.restore_smart_folder_view_state(state);
                return;
            }
            TopLevelGridRestore::SubfolderExpansion(state) => {
                self.suppress_nav_record_for_search_restore = true;
                let restored = self.restore_subfolder_expansion_for_synthetic_path_with_state(
                    &subfolder_expansion_synthetic_path(),
                    Some(state),
                );
                self.suppress_nav_record_for_search_restore = false;
                if !restored {
                    self.set_active_folder_nav_suppress_record_once(false);
                }
                return;
            }
            TopLevelGridRestore::Unavailable => return,
            TopLevelGridRestore::Folder(path) => {
                self.top_level_grid_view
                    .replace_surface(top_level_grid_view::TopLevelGridSurface::Folder);
                (path, None)
            }
            TopLevelGridRestore::DriveList => (drive_list_synthetic_path(), None),
            TopLevelGridRestore::ReadingHistory => (reading_history_synthetic_path(), None),
            TopLevelGridRestore::Bookmarks => (bookmark_view_synthetic_path(), None),
            TopLevelGridRestore::Rating { stars } => (rating_view_synthetic_path(), Some(stars)),
        };
        self.suppress_nav_record_for_search_restore = true;

        let smart_target = smart_folder::is_smart_folder_synthetic_path(&saved);
        self.pending_folder_nav_rating_view_stars = rating_view_stars;
        match self.dispatch_synthetic_folder_history_target(&saved) {
            SyntheticFolderHistoryDispatch::Restored if smart_target => {
                // Until async prepare installs the smart grid, the previous search result may
                // remain visible. Keep the actual restore target as the worker-owned origin so
                // another search entered in this window cannot inherit that stale synthetic path.
                self.smart_folder_open_origin =
                    Some(self.view_return_context_from_parts(Some(saved), None, None));
                // snapshot miss may route through `open_smart_folder`, whose normal cancel boundary
                // clears stale suppression. This restore owns it, so re-arm until async install.
                self.suppress_nav_record_for_search_restore = true;
            }
            SyntheticFolderHistoryDispatch::Restored => {
                // Drive list / reading history / rating view restoration does not call the real
                // folder loader, so consume the one-shot explicitly at this ownership boundary.
                self.suppress_nav_record_for_search_restore = false;
                self.set_active_folder_nav_suppress_record_once(false);
            }
            SyntheticFolderHistoryDispatch::NotSynthetic => self.load_folder(saved),
            SyntheticFolderHistoryDispatch::Unavailable => {
                // Never hand a recognized but unavailable synthetic path to `load_folder`.
                self.suppress_nav_record_for_search_restore = false;
                self.set_active_folder_nav_suppress_record_once(false);
            }
        }
    }

    /// タグビューを閉じて、開く前のフォルダに戻る。
    pub(crate) fn close_tag_view(&mut self) {
        if !self.tag_view.active {
            return;
        }
        let return_context = self.dismiss_tag_view_without_restore();
        self.restore_view_return_context(return_context);
    }

    pub(crate) fn dismiss_tag_view_without_restore(
        &mut self,
    ) -> top_level_grid_view::TopLevelGridRestore {
        self.cancel_pending_folder_nav();
        if let Some(pending) = self.tag_view_pending.take() {
            pending.cancel();
        }
        self.tag_view.active = false;
        self.tag_view.has_focus = false;
        self.tag_view.query.clear();
        self.tag_view.last_executed.clear();
        self.tag_view.last_executed_kind_filter = self.tag_view.kind_filter;
        self.tag_view.nav_stack.clear();
        self.tag_view.summaries.clear();
        self.tag_view.result_count = 0;
        self.tag_view.truncated = false;
        self.tag_view.reject_message = None;
        self.items_are_tag_view = false;
        let path = self.tag_view.saved_folder.take();
        let rating_view_stars = self.view_return_rating_view_stars_for_path(path.as_deref());
        let subfolder_restore = self.tag_view_subfolder_restore.take();
        let fallback =
            self.view_return_context_from_parts(path, subfolder_restore, rating_view_stars);
        self.top_level_grid_view
            .take_return_to()
            .unwrap_or(fallback)
    }

    pub(crate) fn record_tag_view_nav_open(&mut self, path: &Path) {
        if !self.tag_view.active {
            return;
        }
        if self
            .tag_view
            .nav_stack
            .last()
            .is_some_and(|last| crate::folder_tree::path_eq(last, path))
        {
            return;
        }
        self.tag_view.nav_stack.push(path.to_path_buf());
        if self.tag_view.nav_stack.len() > MAX_FOLDER_NAV_STACK {
            self.tag_view.nav_stack.remove(0);
        }
    }

    pub(crate) fn tag_view_back(&mut self) {
        if self.zip_nav_back() {
            return;
        }
        if self.tag_view.nav_stack.is_empty() {
            return;
        }
        let popped = self.tag_view.nav_stack.pop();
        self.cancel_pending_folder_nav();
        if let Some(popped_path) = popped
            && let Some(name) = popped_path.file_name().and_then(|n| n.to_str())
        {
            self.select_after_load = Some(name.to_string());
        }
        if let Some(top) = self.tag_view.nav_stack.last().cloned() {
            let _ = self.load_folder_or_convert_archive(top);
            self.update_tag_view_address();
        } else {
            self.execute_tag_view();
        }
    }

    pub(crate) fn update_tag_view_address(&mut self) {
        if !self.tag_view.active {
            return;
        }
        let query = self.tag_view.last_executed.trim();
        if self.tag_view.nav_stack.is_empty() {
            self.address = if query.is_empty() {
                "タグビュー".to_string()
            } else {
                format!("タグビュー: {query}")
            };
            return;
        }
        let trail: Vec<String> = self
            .tag_view
            .nav_stack
            .iter()
            .filter_map(|p| p.file_name().and_then(|n| n.to_str()).map(str::to_string))
            .collect();
        let base = if query.is_empty() {
            "タグビュー".to_string()
        } else {
            format!("タグビュー: {query}")
        };
        if trail.is_empty() {
            self.address = base;
        } else {
            self.address = format!("{base} > {}", trail.join(" > "));
        }
    }

    pub(crate) fn execute_tag_view(&mut self) {
        self.tag_view.last_executed = self.tag_view.query.clone();
        self.tag_view.last_executed_kind_filter = self.tag_view.kind_filter;
        self.tag_view.reject_message = None;
        self.tag_view.truncated = false;
        self.tag_view.result_count = 0;
        self.tag_view.nav_stack.clear();
        if let Some(pending) = self.tag_view_pending.take() {
            pending.cancel();
        }
        let data_dir = crate::data_dir::get();
        let query = self.tag_view.query.clone();
        let kind_filter = self.tag_view.kind_filter;
        self.tag_view_pending = Some(crate::tag_view::spawn_tag_view_search(
            data_dir,
            query,
            kind_filter,
        ));
    }

    pub(crate) fn poll_tag_view(&mut self) {
        let Some(pending) = self.tag_view_pending.as_ref() else {
            return;
        };
        match pending.try_recv() {
            Ok(Ok(result)) => {
                self.tag_view_pending = None;
                if result.query == self.tag_view.last_executed
                    && result.kind_filter == self.tag_view.last_executed_kind_filter
                {
                    self.apply_tag_view_result(result);
                }
            }
            Ok(Err(msg)) => {
                self.tag_view_pending = None;
                self.tag_view.reject_message = Some(msg);
            }
            Err(mpsc::TryRecvError::Empty) => {}
            Err(mpsc::TryRecvError::Disconnected) => {
                self.tag_view_pending = None;
            }
        }
    }

    fn apply_tag_view_result(&mut self, result: crate::tag_view::TagViewResult) {
        self.tag_view.summaries = result.summaries;
        self.tag_view.truncated = result.truncated;
        self.tag_view.result_count = result.entries.len();

        if result.query.trim().is_empty() {
            if self.items_are_tag_view {
                if let Some(saved) = self.tag_view.saved_folder.clone() {
                    let restore_state = self.tag_view_subfolder_restore.take();
                    self.suppress_nav_record_for_search_restore = true;
                    if self.restore_subfolder_expansion_for_synthetic_path_with_state(
                        &saved,
                        restore_state,
                    ) {
                        self.suppress_nav_record_for_search_restore = false;
                    } else {
                        self.load_folder(saved);
                    }
                }
            }
            return;
        }

        let mut items: Vec<GridItem> = Vec::with_capacity(result.entries.len());
        let mut image_metas: Vec<Option<(i64, i64)>> = Vec::with_capacity(result.entries.len());
        let mut video_items: Vec<(usize, PathBuf, u64)> = Vec::new();
        for entry in result.entries {
            let idx = items.len();
            let item = match entry.kind {
                crate::tag_view::TagViewItemKind::Folder => GridItem::Folder(entry.path.clone()),
                crate::tag_view::TagViewItemKind::Image => GridItem::Image(entry.path.clone()),
                crate::tag_view::TagViewItemKind::Video => GridItem::Video(entry.path.clone()),
                crate::tag_view::TagViewItemKind::Audio => GridItem::Audio(entry.path.clone()),
                crate::tag_view::TagViewItemKind::ZipFile => GridItem::ZipFile(entry.path.clone()),
                crate::tag_view::TagViewItemKind::PdfFile => GridItem::PdfFile(entry.path.clone()),
                crate::tag_view::TagViewItemKind::Archive(format) => GridItem::ConvertibleArchive {
                    path: entry.path.clone(),
                    format,
                },
            };
            if matches!(item, GridItem::Video(_)) {
                video_items.push((idx, entry.path.clone(), entry.file_size.max(0) as u64));
            }
            image_metas.push(Some((entry.mtime, entry.file_size)));
            items.push(item);
        }

        let pin_map_for_existing: std::collections::HashMap<
            String,
            crate::folder_thumb_pins::FolderPinSource,
        > = if let Some(db) = self.folder_thumb_pin_db.as_ref() {
            let containers: Vec<&std::path::Path> = items
                .iter()
                .filter_map(|it| match it {
                    GridItem::Folder(p) | GridItem::ZipFile(p) | GridItem::PdfFile(p) => {
                        Some(p.as_path())
                    }
                    GridItem::ConvertibleArchive { path, .. } => Some(path.as_path()),
                    _ => None,
                })
                .collect();
            if containers.is_empty() {
                std::collections::HashMap::new()
            } else {
                db.lookup_many(containers)
            }
        } else {
            std::collections::HashMap::new()
        };
        let existing_keys: std::collections::HashSet<String> = items
            .iter()
            .zip(image_metas.iter())
            .flat_map(|(it, meta)| {
                folder_thumb_existing_keys_for(
                    it,
                    *meta,
                    &pin_map_for_existing,
                    self.folder_thumb_pin_db.as_deref(),
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                    true,
                )
            })
            .collect();
        let saved_folder = self.tag_view.saved_folder.clone();
        if let Some(restore_state) =
            self.take_subfolder_expansion_restore_for_synthetic_path(saved_folder.as_deref())
        {
            self.tag_view_subfolder_restore = Some(restore_state);
        }
        self.start_loading_items(
            search_results_synthetic_path(),
            items,
            image_metas,
            existing_keys,
            video_items,
            None,
        );
        self.items_are_tag_view = true;
        self.address = format!("タグビュー: {}", self.tag_view.query.trim());
    }

    /// 検索コンテキスト中の Ctrl+↑↓ ナビゲーション。
    ///
    /// 振る舞い:
    /// 1. 現在のスタック先頭 (検索結果から入ったフォルダ) を「サブツリールート」とし、
    ///    そのサブツリー内では通常の DFS (next_folder_dfs / prev_folder_dfs) で移動する。
    /// 2. DFS の結果がサブツリー外に出る場合、検索結果リスト内の前後アイテムへジャンプする
    ///    (`favsearch_navigate_sibling`)。
    ///
    /// サブツリー内の移動はスタックに push するので、BS で元の位置に戻れる。
    ///
    /// 実装上: `navigate_folder_with_skip` は DFS + `read_dir` で UI スレッドを
    /// ブロックし得るので、`start_folder_nav` に投げて非同期実行する。結果は
    /// `apply_folder_nav_result` が `FolderNavMode::Favsearch` ブランチで
    /// 受け取り、sibling fallback も含めた後処理を行う。
    pub(crate) fn favsearch_ctrl_nav(&mut self, forward: bool) {
        if self.favsearch.nav_stack.is_empty() {
            // 検索結果リスト上ではなにもしない
            return;
        }
        let root = self.favsearch.nav_stack[0].clone();
        let Some(current) = self.favsearch.nav_stack.last().cloned() else {
            return;
        };
        self.start_folder_nav(
            current,
            forward,
            FolderNavMode::Favsearch {
                root,
                fullscreen: false,
            },
        );
    }

    fn favsearch_sibling_path(&self, delta: isize) -> Option<PathBuf> {
        let results = &self.favsearch.results_paths;
        if results.is_empty() {
            return None;
        }
        let cur_root = match self.favsearch.nav_stack.first() {
            Some(p) => p.clone(),
            None => return None, // 検索結果リスト上では何もしない
        };
        let idx = match results.iter().position(|p| p == &cur_root) {
            Some(i) => i,
            None => {
                // 現在 root が結果リストに見つからない (データ更新等)。素直に先頭へ。
                0
            }
        };
        let next_idx = idx as isize + delta;
        if next_idx < 0 || next_idx >= results.len() as isize {
            return None; // 端で止める
        }
        Some(results[next_idx as usize].clone())
    }

    fn clear_pending_folder_nav_steps(&mut self) {
        self.pending_folder_nav_steps = 0;
        self.pending_folder_nav_mode = FolderNavMode::Grid;
    }

    /// 検索結果の前後アイテムへ移動する (Ctrl+↑↓ 用、`delta` は +1 / -1)。
    /// スタックがある場合は root (nav_stack[0]) を基準に検索結果内を前後する。
    /// 移動後は新しい root 1 つだけのスタックになる。
    pub(crate) fn favsearch_navigate_sibling(&mut self, delta: isize) -> bool {
        let Some(next_path) = self.favsearch_sibling_path(delta) else {
            return false;
        };
        self.clear_pending_folder_nav_steps();
        self.favsearch.nav_stack = vec![next_path.clone()];
        self.load_folder(next_path);
        self.update_favsearch_address();
        true
    }

    /// BS が押されたときの検索コンテキスト内の「戻る」処理。
    /// スタックを 1 段ポップし、空になれば検索結果リストへ戻る。
    /// 抜けてきた子フォルダ/ファイル名は `select_after_load` に渡し、
    /// 戻り先で該当アイテムがカーソル選択されるようにする。
    pub(crate) fn favsearch_back(&mut self) {
        if self.favsearch.nav_stack.is_empty() {
            // 検索結果リスト上では BS は何もしない (ファイルシステム遡りを禁止)
            return;
        }
        let popped = self.favsearch.nav_stack.pop();
        self.cancel_pending_folder_nav();
        if let Some(popped_path) = popped {
            if let Some(name) = popped_path.file_name().and_then(|n| n.to_str()) {
                self.select_after_load = Some(name.to_string());
            }
        }
        if let Some(top) = self.favsearch.nav_stack.last().cloned() {
            self.load_folder(top);
            self.update_favsearch_address();
        } else {
            // スタックが空になった = 検索結果リストに戻る。
            self.execute_favsearch();
        }
    }

    /// アドレスバー表示を検索コンテキストに応じて更新する。
    /// 現在地を包含するお気に入りフォルダを特定し、その配下の相対パスを表示する
    /// (例: "🔍 検索結果: "query" > Photos > 2024 > Vacation")。
    pub(crate) fn update_favsearch_address(&mut self) {
        if !self.favsearch.active {
            return;
        }
        let query = self.favsearch.last_executed.clone();
        let count = self.favsearch.results_paths.len();
        if self.favsearch.nav_stack.is_empty() {
            self.address = format!("🔍 検索結果: \"{}\"  ({} 件)", query, count);
            return;
        }
        // 現在地 = スタックの末尾 (深い場所)
        let current = self.favsearch.nav_stack.last().cloned().unwrap();
        // 包含するお気に入り根を探し、その直下からの相対パスを元のケースで組み立てる
        let segments: Vec<String> =
            match self.find_nearest_favorite(&current).map(|f| f.path.clone()) {
                Some(root) => {
                    let root_name = root
                        .file_name()
                        .and_then(|n| n.to_str())
                        .map(str::to_string);
                    let rel_components = current.components().skip(root.components().count());
                    root_name
                        .into_iter()
                        .chain(rel_components.map(|c| c.as_os_str().to_string_lossy().to_string()))
                        .collect()
                }
                None => current
                    .file_name()
                    .and_then(|n| n.to_str())
                    .map(|s| vec![s.to_string()])
                    .unwrap_or_default(),
            };
        self.address = format!("🔍 検索結果: \"{}\" > {}", query, segments.join(" > "));
    }

    /// 現在のクエリで検索を実行し、結果をグリッドに反映する。
    /// お気に入り検索 (Ctrl+S) をバックグラウンドスレッドで開始する。
    /// SQLite FTS クエリは通常数 ms だが、インデックスが大きいと数十〜数百 ms に
    /// 達し UI を止め得る。結果は `poll_favsearch` で受信する。
    pub(crate) fn execute_favsearch(&mut self) {
        self.favsearch.last_executed = self.favsearch.query.clone();
        let query = self.favsearch.query.trim().to_string();
        self.favsearch.nav_stack.clear();

        // 既存 in-flight をキャンセル
        if let Some(pending) = self.favsearch_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }

        // 空クエリ: 空結果で即座に start_loading_items (待ち時間なし)
        if query.is_empty() {
            self.apply_favsearch_results(Vec::new());
            return;
        }

        let Some(db) = self.search_index_db.clone() else {
            return;
        };
        // §19.7: favorite_filter で単一お気に入りに絞り込む。
        // Codex P2 #3: 選択中 favorite が auto_index_structure=false になった / 削除された場合、
        // UI との食い違いを防ぐため filter を None に倒して UI も「すべて」に戻す。
        if let Some(id) = self.favsearch.favorite_filter {
            let still_valid = self
                .settings
                .favorite_by_id(id)
                .is_some_and(|f| f.auto_index_structure);
            if !still_valid {
                self.favsearch.favorite_filter = None;
            }
        }
        let fav_roots: Vec<PathBuf> = match self.favsearch.favorite_filter {
            Some(id) => self
                .settings
                .favorite_by_id(id)
                .map(|f| vec![f.path.clone()])
                .unwrap_or_default(),
            None => self
                .settings
                .favorites
                .iter()
                .map(|f| f.path.clone())
                .collect(),
        };

        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_w = Arc::clone(&cancel);
        let (tx, rx) = mpsc::channel();

        let mode: crate::search_query::MatchMode = self.favsearch.or_mode.into();
        let kind_filter = self.favsearch.kind_filter;
        std::thread::Builder::new()
            .name("favsearch-db".to_string())
            .spawn(move || {
                if cancel_w.load(Ordering::Relaxed) {
                    return;
                }
                let result = db.search(&query, &fav_roots, kind_filter, mode);
                // キャンセル後の送信は無意味なので捨てる (UI 側 pending も None に戻っている)
                if cancel_w.load(Ordering::Relaxed) {
                    return;
                }
                let _ = tx.send(result);
            })
            .ok();

        self.favsearch_pending = Some(FavSearchPending { cancel, rx });
    }

    /// お気に入り検索の結果をポーリングする。
    pub(crate) fn poll_favsearch(&mut self) {
        let Some(pending) = self.favsearch_pending.as_ref() else {
            return;
        };
        match pending.rx.try_recv() {
            Ok(Ok(results)) => {
                self.favsearch_pending = None;
                self.apply_favsearch_results(results);
            }
            Ok(Err(e)) => {
                crate::logger::log(format!("favsearch query failed: {e}"));
                self.favsearch_pending = None;
            }
            Err(mpsc::TryRecvError::Empty) => {}
            Err(mpsc::TryRecvError::Disconnected) => {
                self.favsearch_pending = None;
            }
        }
    }

    /// SQLite 検索結果を `start_loading_items` に流し込む共通処理。
    fn apply_favsearch_results(&mut self, results: Vec<crate::search_index_db::IndexEntry>) {
        let mut items: Vec<GridItem> = Vec::with_capacity(results.len());
        let mut image_metas: Vec<Option<(i64, i64)>> = Vec::with_capacity(results.len());
        let mut video_items: Vec<(usize, PathBuf, u64)> = Vec::new();
        for e in &results {
            let item = match e.kind {
                crate::search_index_db::IndexKind::Folder => GridItem::Folder(e.path.clone()),
                crate::search_index_db::IndexKind::ZipFile => GridItem::ZipFile(e.path.clone()),
                crate::search_index_db::IndexKind::PdfFile => GridItem::PdfFile(e.path.clone()),
                crate::search_index_db::IndexKind::VideoFile => GridItem::Video(e.path.clone()),
            };
            let idx = items.len();
            if matches!(item, GridItem::Video(_)) {
                image_metas.push(Some((e.mtime, 0)));
                video_items.push((idx, e.path.clone(), 0));
            } else {
                image_metas.push(Some((e.mtime, 0)));
            }
            items.push(item);
        }
        self.favsearch.results_paths = results.iter().map(|e| e.path.clone()).collect();

        let synthetic = search_results_synthetic_path();
        // pinned 形式の cache 行も保護対象に入れる (Codex Phase B P2 指摘、load_folder と同様)。
        let pin_map_for_existing: std::collections::HashMap<
            String,
            crate::folder_thumb_pins::FolderPinSource,
        > = if let Some(db) = self.folder_thumb_pin_db.as_ref() {
            let containers: Vec<&std::path::Path> = items
                .iter()
                .filter_map(|it| match it {
                    GridItem::Folder(p) | GridItem::ZipFile(p) | GridItem::PdfFile(p) => {
                        Some(p.as_path())
                    }
                    _ => None,
                })
                .collect();
            if containers.is_empty() {
                std::collections::HashMap::new()
            } else {
                db.lookup_many(containers)
            }
        } else {
            std::collections::HashMap::new()
        };
        let existing_keys: std::collections::HashSet<String> = items
            .iter()
            .zip(image_metas.iter())
            .flat_map(|(it, meta)| {
                folder_thumb_existing_keys_for(
                    it,
                    *meta,
                    &pin_map_for_existing,
                    self.folder_thumb_pin_db.as_deref(),
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                    // T54 follow-on: 検索結果は full-path ベース (= 異なる親フォルダの
                    // 同名コンテナが共存しうるので basename だと衝突する)
                    true,
                )
            })
            .collect();
        let saved_folder = self.favsearch.saved_folder.clone();
        if let Some(restore_state) =
            self.take_subfolder_expansion_restore_for_synthetic_path(saved_folder.as_deref())
        {
            self.favsearch_subfolder_restore = Some(restore_state);
        }
        self.start_loading_items(
            synthetic,
            items,
            image_metas,
            existing_keys,
            video_items,
            None,
        );
        self.update_favsearch_address();
    }

    /// メニュー操作で閲覧履歴を開く。
    ///
    /// 履歴 ←/→ からの復元は `dispatch_synthetic_folder_history_target` が
    /// `enter_reading_history` を直接呼ぶ。ここでだけ遷移を記録することで、メニュー起動時の
    /// 直前フォルダは back stack に残しつつ、履歴復元時の二重記録を避ける。
    pub(crate) fn enter_reading_history_from_menu(&mut self) {
        self.record_folder_nav_transition(&reading_history_synthetic_path());
        self.enter_reading_history();
    }

    /// 閲覧履歴ビューを開く。
    pub(crate) fn enter_reading_history(&mut self) {
        crate::logger::log("=== enter_reading_history ===");
        // いま閲覧履歴ビューにいるので、戻り先予約は消費済み扱いにする。
        self.reading_history_return_from = None;
        self.clear_bookmark_view_return_state();
        self.gamepad_location_picker = None;
        if self.global_search.active {
            self.global_search.saved_folder = None;
            self.close_global_search();
        }
        if self.favsearch.active {
            self.favsearch.saved_folder = None;
            self.close_favsearch();
        }
        if self.tag_view.active {
            self.tag_view.saved_folder = None;
            self.close_tag_view();
        }
        if self.show_search_bar {
            self.show_search_bar = false;
            self.search_query.clear();
            self.search_filter = None;
            self.search_filter_origin_folder = None;
            self.search_has_focus = false;
            self.search_tag_bridge.clear();
            self.cancel_search_pending();
        }

        let limit = self
            .settings
            .reading_history_limit
            .clamp(1, crate::reading_history_db::READING_HISTORY_LIMIT_MAX);
        let entries = match self
            .reading_history_db
            .as_ref()
            .map(|db| db.list_recent(limit))
        {
            Some(Ok(entries)) => entries,
            Some(Err(e)) => {
                crate::logger::log(format!("reading-history: list failed: {e}"));
                self.show_feedback_toast("[閲覧履歴を読み込めませんでした]".to_string());
                Vec::new()
            }
            None => {
                self.show_feedback_toast("[閲覧履歴 DB を開けません]".to_string());
                Vec::new()
            }
        };

        self.install_reading_history_entries(entries);
    }

    fn install_reading_history_entries(
        &mut self,
        entries: Vec<crate::reading_history_db::ReadingHistoryEntry>,
    ) {
        let ReadingHistoryLoadInputs {
            items,
            image_metas,
            video_items,
            rows,
        } = reading_history_load_inputs(entries);

        let pin_map_for_existing: std::collections::HashMap<
            String,
            crate::folder_thumb_pins::FolderPinSource,
        > = if let Some(db) = self.folder_thumb_pin_db.as_ref() {
            let containers: Vec<&std::path::Path> =
                items.iter().filter_map(GridItem::container_path).collect();
            if containers.is_empty() {
                std::collections::HashMap::new()
            } else {
                db.lookup_many(containers)
            }
        } else {
            std::collections::HashMap::new()
        };
        let existing_keys: std::collections::HashSet<String> = items
            .iter()
            .zip(image_metas.iter())
            .flat_map(|(it, meta)| {
                folder_thumb_existing_keys_for(
                    it,
                    *meta,
                    &pin_map_for_existing,
                    self.folder_thumb_pin_db.as_deref(),
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                    true,
                )
            })
            .collect();

        self.start_loading_items(
            reading_history_synthetic_path(),
            items,
            image_metas,
            existing_keys,
            video_items,
            None,
        );
        self.items_are_reading_history_view = true;
        self.top_level_grid_view
            .replace_surface(top_level_grid_view::TopLevelGridSurface::ReadingHistory);
        self.reading_history_rows = rows;
        self.address = "閲覧履歴".to_string();
        self.rebuild_visible_indices();
        if self.selected.is_none()
            && let Some(&idx) = self.visible_indices.first()
        {
            self.selected = Some(idx);
            self.scroll_to_selected = true;
        }
    }

    /// メニュー操作でレーティング一覧を開く。
    ///
    /// 非同期 build 完了後の `install_rating_view_rows` が current_folder を合成パスへ
    /// 切り替える前に、直前フォルダを back stack へ記録する。
    pub(crate) fn enter_rating_view_from_menu(&mut self, stars: u8) {
        let stars = stars.clamp(1, 5);
        self.record_folder_nav_transition_with_rating(&rating_view_synthetic_path(), Some(stars));
        self.enter_rating_view(stars);
    }

    /// ★N が付いたアイテム / コンテナをフラットに並べるレーティング一覧ビューを開く。
    pub(crate) fn enter_rating_view(&mut self, stars: u8) {
        let stars = stars.clamp(1, 5);
        crate::logger::log(format!("=== enter_rating_view stars={stars} ==="));
        self.gamepad_location_picker = None;
        if let Some(pending) = self.rating_view_pending.take() {
            pending.cancel();
        }
        self.rating_view_stars = stars;
        self.rating_view_sort = crate::rating_view::RatingViewSort::default();
        self.rating_view_rows.clear();
        self.rating_view_rows_stars = None;
        self.rating_view_skipped = 0;
        self.rating_view_nav_stack.clear();
        self.pending_rating_view_zipdir_open = None;
        if !self.items_are_rating_view {
            self.rating_view_saved_folder = self.current_folder.clone();
            self.rating_view_subfolder_restore = None;
        }

        if self.global_search.active {
            self.global_search.saved_folder = None;
            self.close_global_search();
        }
        if self.favsearch.active {
            self.favsearch.saved_folder = None;
            self.close_favsearch();
        }
        if self.tag_view.active {
            self.tag_view.saved_folder = None;
            self.close_tag_view();
        }
        if self.show_search_bar {
            self.show_search_bar = false;
            self.search_query.clear();
            self.search_filter = None;
            self.search_filter_origin_folder = None;
            self.search_has_focus = false;
            self.search_tag_bridge.clear();
            self.cancel_search_pending();
        }

        self.address = format!(
            "{} レーティング一覧を読み込み中…",
            "★".repeat(stars as usize)
        );
        self.rating_view_pending = Some(crate::rating_view::spawn_rating_view_build(
            crate::rating_db::RatingDb::db_path(),
            stars,
        ));
    }

    pub(crate) fn close_rating_view(&mut self) {
        if let Some(pending) = self.rating_view_pending.take() {
            pending.cancel();
        }
        self.rating_view_rows.clear();
        self.rating_view_rows_stars = None;
        self.rating_view_skipped = 0;
        self.rating_view_nav_stack.clear();
        self.pending_rating_view_zipdir_open = None;
        self.items_are_rating_view = false;
        let restore_state = self.rating_view_subfolder_restore.take();
        if let Some(saved) = self.rating_view_saved_folder.take() {
            self.suppress_nav_record_for_search_restore = true;
            if crate::folder_tree::path_eq(&saved, &drive_list_synthetic_path()) {
                self.suppress_nav_record_for_search_restore = false;
                self.enter_drive_list(None);
            } else if self
                .restore_subfolder_expansion_for_synthetic_path_with_state(&saved, restore_state)
            {
                self.suppress_nav_record_for_search_restore = false;
            } else {
                self.load_folder(saved);
            }
        }
    }

    pub(crate) fn rating_view_nav_context_active(&self) -> bool {
        self.items_are_rating_view || !self.rating_view_nav_stack.is_empty()
    }

    pub(crate) fn rating_view_parent_nav_available(&self) -> bool {
        self.rating_view_nav_context_active() || self.rating_view_pending.is_some()
    }

    pub(crate) fn record_rating_view_nav_open(&mut self, path: &Path) {
        if !self.rating_view_nav_context_active() || is_synthetic_view_path(path) {
            return;
        }
        if self
            .rating_view_nav_stack
            .last()
            .is_some_and(|last| crate::folder_tree::path_eq(last, path))
        {
            return;
        }
        self.rating_view_nav_stack.push(path.to_path_buf());
        if self.rating_view_nav_stack.len() > MAX_FOLDER_NAV_STACK {
            self.rating_view_nav_stack.remove(0);
        }
    }

    pub(crate) fn rating_view_parent_nav(&mut self) {
        if !self.rating_view_nav_stack.is_empty() {
            self.rating_view_back();
            return;
        }
        if self.items_are_rating_view || self.rating_view_pending.is_some() {
            self.close_rating_view();
        }
    }

    pub(crate) fn rating_view_back(&mut self) {
        if self.zip_nav_back() {
            return;
        }
        if self.rating_view_nav_stack.is_empty() {
            return;
        }
        let popped = self.rating_view_nav_stack.pop();
        self.cancel_pending_folder_nav();
        self.pending_rating_view_zipdir_open = None;
        if let Some(popped_path) = popped.as_ref()
            && let Some(name) = popped_path.file_name().and_then(|n| n.to_str())
        {
            self.select_after_load = Some(name.to_string());
        }
        if let Some(top) = self.rating_view_nav_stack.last().cloned() {
            let _ = self.load_folder_or_convert_archive(top);
        } else {
            self.install_rating_view_rows();
            if let Some(popped_path) = popped.as_ref() {
                self.select_rating_view_row_for_opened_path(popped_path);
            }
        }
    }

    fn select_rating_view_row_for_opened_path(&mut self, path: &Path) {
        for idx in self.visible_indices.iter().copied() {
            let Some(item) = self.items.get(idx) else {
                continue;
            };
            let matches_path = item
                .container_path()
                .is_some_and(|candidate| crate::folder_tree::path_eq(candidate, path))
                || matches!(
                    item,
                    GridItem::ZipDir { zip_path, .. }
                        if crate::folder_tree::path_eq(zip_path, path)
                );
            if matches_path {
                self.selected = Some(idx);
                self.scroll_to_selected = true;
                return;
            }
        }
    }

    pub(crate) fn poll_rating_view(&mut self) {
        let Some(pending) = self.rating_view_pending.as_ref() else {
            return;
        };
        match pending.rx.try_recv() {
            Ok(Ok(result)) => {
                self.rating_view_pending = None;
                if result.stars == self.rating_view_stars {
                    self.apply_rating_view_result(result);
                }
            }
            Ok(Err(msg)) => {
                self.rating_view_pending = None;
                crate::logger::log(format!("rating-view: build failed: {msg}"));
                self.show_feedback_toast("[レーティング一覧を読み込めませんでした]".to_string());
            }
            Err(mpsc::TryRecvError::Empty) => {}
            Err(mpsc::TryRecvError::Disconnected) => {
                self.rating_view_pending = None;
            }
        }
    }

    fn apply_rating_view_result(&mut self, result: crate::rating_view::RatingViewBuildResult) {
        self.rating_view_rows_stars = Some(result.stars);
        self.rating_view_rows = result.rows;
        self.rating_view_skipped = result.skipped;
        self.install_rating_view_rows();
        if self.rating_view_skipped > 0 {
            self.show_feedback_toast(format!(
                "見つからない項目を {} 件除外しました",
                self.rating_view_skipped
            ));
        }
    }

    pub(crate) fn set_rating_view_sort(&mut self, sort: crate::rating_view::RatingViewSort) {
        self.rating_view_sort = sort;
        if self.items_are_rating_view {
            self.install_rating_view_rows();
        }
    }

    pub(crate) fn refresh_rating_view_after_rating_changes(&mut self, changes: &[(String, u8)]) {
        if changes.is_empty() {
            self.rebuild_visible_indices();
            return;
        }
        let view_stars = self.rating_view_stars;
        let now_ms = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .ok()
            .map(|d| d.as_millis().min(i64::MAX as u128) as i64);
        let changed: std::collections::HashMap<&str, u8> = changes
            .iter()
            .map(|(key, stars)| (key.as_str(), *stars))
            .collect();
        self.rating_view_rows.retain_mut(|row| {
            let Some(&new_stars) = changed.get(row.key.as_str()) else {
                return true;
            };
            if new_stars == view_stars && new_stars > 0 {
                if let Some(ts) = now_ms {
                    row.rated_at_ms = Some(ts);
                }
                true
            } else {
                false
            }
        });
        let existing: std::collections::HashSet<&str> = self
            .rating_view_rows
            .iter()
            .map(|row| row.key.as_str())
            .collect();
        let restore_keys: Vec<String> = changes
            .iter()
            .filter(|(key, stars)| {
                *stars == view_stars && *stars > 0 && !existing.contains(key.as_str())
            })
            .map(|(key, _)| key.clone())
            .collect();
        drop(existing);
        if !restore_keys.is_empty() {
            self.reload_current_rating_view_preserving_sort();
            return;
        }
        self.install_rating_view_rows();
    }

    pub(crate) fn reload_current_rating_view_preserving_sort(&mut self) {
        let stars = self.rating_view_stars.clamp(1, 5);
        if let Some(pending) = self.rating_view_pending.take() {
            pending.cancel();
        }
        self.rating_view_stars = stars;
        self.rating_view_rows.clear();
        self.rating_view_rows_stars = None;
        self.rating_view_skipped = 0;
        self.address = format!(
            "{} レーティング一覧を読み込み中…",
            "★".repeat(stars as usize)
        );
        self.rating_view_pending = Some(crate::rating_view::spawn_rating_view_build(
            crate::rating_db::RatingDb::db_path(),
            stars,
        ));
    }

    pub(crate) fn reload_open_metadata_views_after_cleanup(&mut self) {
        if self.items_are_rating_view {
            self.reload_current_rating_view_preserving_sort();
        }
        if self.tag_view.on_results_grid() {
            self.tag_view.last_executed.clear();
            self.execute_tag_view();
        }
    }

    fn install_rating_view_rows(&mut self) {
        let previous_selected = self.selected;
        let previous_selected_key = previous_selected.and_then(|idx| self.rating_path_key(idx));
        crate::rating_view::sort_rows(&mut self.rating_view_rows, self.rating_view_sort);
        let mut items: Vec<GridItem> = self
            .rating_view_rows
            .iter()
            .map(|row| row.item.clone())
            .collect();
        let mut image_metas: Vec<Option<(i64, i64)>> = self
            .rating_view_rows
            .iter()
            .map(|row| row.image_meta)
            .collect();
        // ★設定時刻順を含む rating view 固有の行内順序は維持し、カテゴリ行だけを共通
        // helper で組み替える。Normal sort も直前の sort_rows で既に確定済み。
        crate::grid_item::arrange_grid_items(
            &mut items,
            &mut image_metas,
            &self.settings.grid_display_order,
            None,
        );
        let mut rows_by_item: std::collections::HashMap<
            String,
            std::collections::VecDeque<crate::rating_view::RatingViewRow>,
        > = std::collections::HashMap::new();
        for row in self.rating_view_rows.drain(..) {
            rows_by_item
                .entry(row.item.perf_key())
                .or_default()
                .push_back(row);
        }
        self.rating_view_rows = items
            .iter()
            .map(|item| {
                rows_by_item
                    .get_mut(&item.perf_key())
                    .and_then(std::collections::VecDeque::pop_front)
                    .expect("arranged rating item must retain its source row")
            })
            .collect();
        let video_items: Vec<(usize, PathBuf, u64)> = items
            .iter()
            .enumerate()
            .filter_map(|(idx, item)| match item {
                GridItem::Video(path) => {
                    let size = image_metas
                        .get(idx)
                        .and_then(|m| *m)
                        .map(|(_, size)| size.max(0) as u64)
                        .unwrap_or(0);
                    Some((idx, path.clone(), size))
                }
                _ => None,
            })
            .collect();
        let pin_map_for_existing: std::collections::HashMap<
            String,
            crate::folder_thumb_pins::FolderPinSource,
        > = if let Some(db) = self.folder_thumb_pin_db.as_ref() {
            let containers: Vec<&std::path::Path> =
                items.iter().filter_map(GridItem::container_path).collect();
            if containers.is_empty() {
                std::collections::HashMap::new()
            } else {
                db.lookup_many(containers)
            }
        } else {
            std::collections::HashMap::new()
        };
        let existing_keys: std::collections::HashSet<String> = items
            .iter()
            .zip(image_metas.iter())
            .flat_map(|(it, meta)| {
                folder_thumb_existing_keys_for(
                    it,
                    *meta,
                    &pin_map_for_existing,
                    self.folder_thumb_pin_db.as_deref(),
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                    true,
                )
            })
            .collect();

        let saved_folder = self.rating_view_saved_folder.clone();
        if let Some(restore_state) =
            self.take_subfolder_expansion_restore_for_synthetic_path(saved_folder.as_deref())
        {
            self.rating_view_subfolder_restore = Some(restore_state);
        }
        self.start_loading_items(
            rating_view_synthetic_path(),
            items,
            image_metas,
            existing_keys,
            video_items,
            None,
        );
        self.items_are_rating_view = true;
        self.top_level_grid_view.replace_surface(
            top_level_grid_view::TopLevelGridSurface::Rating {
                stars: self.rating_view_stars,
            },
        );
        self.address = format!(
            "{} レーティング一覧",
            "★".repeat(self.rating_view_stars as usize)
        );
        self.rebuild_visible_indices();
        let selected = previous_selected_key
            .as_deref()
            .and_then(|key| self.rating_view_rows.iter().position(|row| row.key == key))
            .filter(|idx| self.visible_indices.contains(idx))
            .or_else(|| {
                previous_selected.and_then(|idx| {
                    self.visible_indices
                        .iter()
                        .copied()
                        .find(|&visible| visible >= idx)
                        .or_else(|| self.visible_indices.last().copied())
                })
            })
            .or_else(|| self.visible_indices.first().copied());
        if let Some(idx) = selected {
            self.selected = Some(idx);
            self.scroll_to_selected = true;
        }
    }

    /// 閲覧履歴ビューから 1 件削除する。
    pub(crate) fn remove_reading_history_entry_for_idx(&mut self, idx: usize) {
        let Some(key) = self.items.get(idx).and_then(reading_history_key_for_item) else {
            return;
        };
        let result = match self.reading_history_db.as_ref() {
            Some(db) => db.remove_key(&key).map_err(|e| e.to_string()),
            None => Err("閲覧履歴 DB を開けません".to_string()),
        };
        match result {
            Ok(()) => {
                self.show_feedback_toast("[閲覧履歴から削除しました]".to_string());
                self.enter_reading_history();
            }
            Err(err) => {
                crate::logger::log(format!("reading-history: remove failed: {err}"));
                self.show_feedback_toast("[閲覧履歴の削除に失敗しました]".to_string());
            }
        }
    }

    /// `path` を包含する最も近いお気に入り (パスが最長一致するもの) を返す。
    /// ZIP/PDF を開いている最中に呼ぶと ZIP/PDF 本体のパスで判定されるので、
    /// 仮想フォルダ内ページにもお気に入り標準が適用される。
    /// 入れ子 (例: `C:\pics` と `C:\pics\AI` が両方登録済み) のときは深い方を優先。
    pub(crate) fn find_nearest_favorite(
        &self,
        path: &std::path::Path,
    ) -> Option<&crate::settings::FavoriteEntry> {
        let mut best: Option<&crate::settings::FavoriteEntry> = None;
        let mut best_len = 0usize;
        for fav in &self.settings.favorites {
            if !crate::search_index_db::is_under(path, &fav.path) {
                continue;
            }
            let len = fav.path.as_os_str().len();
            if best.is_none() || len > best_len {
                best = Some(fav);
                best_len = len;
            }
        }
        best
    }

    /// タスク 3: ZIP ファイルを仮想フォルダとして開く (非同期)。
    ///
    /// ネスト ZIP の中央ディレクトリ列挙は数秒かかるため worker に逃がす。
    /// UI 側は即座に「読み込み中…」を表示し、BS / Ctrl+↑↓ で中断可能。
    /// 結果は `poll_zip_enumerate` が受け取り `start_loading_items` を呼ぶ。
    pub fn load_zip_as_folder(&mut self, zip_path: PathBuf) {
        crate::logger::log(format!(
            "=== load_zip_as_folder: {} ===",
            zip_path.display()
        ));

        #[cfg(windows)]
        {
            // ZIP は列挙待ちで items を先に clear するため、完了後の start_loading_items では
            // unbundled メディアを判定できない。still preserve / close より先に退避する。
            // cache-hit / 入れ子 ZIP の再帰入口でも二度目は fullscreen_idx=None で no-op。
            // (review-v2.3.0 追補6: R2-P2-2 ZIP media promote)
            let detached_media_preserved =
                self.promote_active_detached_video_for_main_context_change();
            if !detached_media_preserved
                && self.should_preserve_active_detached_image_window_for_main_context_change()
            {
                self.preserve_active_detached_image_window_for_main_context_change();
                self.close_fullscreen();
            }
        }

        // 入れ子に RAR/7z/LZH を含み、過去に「展開キャッシュ」へ変換済みの ZIP は、
        // キャッシュ ZIP へ振り替えて開く (RAR 等のキャッシュヒット経路と同じ、v1.3.0)。
        // キャッシュ ZIP 自身を開く内側の再帰呼び出しでは lookup が miss するので
        // 無限再帰にはならない。lookup は mtime+size 検証付き (元 ZIP が更新されたら
        // miss して通常経路 → 列挙で再検出 → 再変換提案)。
        if !crate::rar_loader::is_rar_path(&zip_path)
            && !self.settings.archive_file_handling_ignores_convertible()
            && let Some(cached) = self.try_archive_cache_lookup(&zip_path)
            && !crate::folder_tree::path_eq(&cached, &zip_path)
        {
            crate::logger::log(format!(
                "  zip: converted-archive cache hit -> {}",
                cached.display()
            ));
            if self.open_archive_via_cache(zip_path.clone(), cached, false) {
                return;
            }
            // ★固定の範囲外ガード等で振り替えがブロックされた場合は通常の ZIP 経路へ
            // 落とす (元 ZIP のツリー表示は従来どおり可能、非 ZIP の中身だけ見えない)。
        }

        // 旧 ZIP / PDF pending を Drop (cancel 自動伝搬)。
        // fs_nav_after_pdf_enumerate も一緒に捨てないと、後続の別 PDF で古い方向で
        // fullscreen が勝手に開いてしまう (Codex P2)。
        self.zip_enumerate_pending = None;
        self.pdf_enumerate_pending = None;
        self.fs_nav_after_pdf_enumerate = None;
        // 自動 1 ページ目フルスクリーン (環境設定 ON で grid から ZIP を開いた) の予約を、
        // enumerate 完了で先頭ページを開く既存 deferred 機構へ載せ替える。
        if std::mem::take(&mut self.pending_auto_fs_open) {
            self.fs_nav_after_pdf_enumerate = Some(DeferredFsReopen {
                history_trigger: crate::app::HistoryTrigger::UserChosen,
                resume_slideshow: false,
                target: DeferredFsTarget::None,
                // 「ZIP/PDF × 一覧から開く」: 続きから / 先頭から を設定で切替。
                resume_to_last_page: self.settings.book_open_resume.resumes(),
                from_explicit_open: true,
                preserve_after_password_prompt: true,
            });
        }

        // 旧サムネイルワーカーを即キャンセル (pending 完了後に start_loading_items でも
        // 再度 cancel されるが、先に止めておくことで worker キューの渋滞を防ぐ)。
        self.cancel_token.store(true, Ordering::Relaxed);
        self.wake_all_workers();

        // ネスト ZIP キャッシュのクリアは **UI スレッドで** 行う。worker 内で行うと、
        // 複数 ZIP を連打したときに旧 worker の遅れた clear が新 worker の populate を
        // 上書き消去するレースが起きる。ここで同期実行すれば load_zip_as_folder 呼び出し
        // の直列順で確実にクリアされる (clear 自体は軽量: NESTED_CACHE.clear())。
        crate::zip_loader::clear_nested_cache();
        // 旧 ZIP のツリーナビ状態を破棄 (新ツリーは finalize_zip_enumerate が設定)。
        // enumerate pending 窓中に stale nav を参照しないよう早期クリア。
        self.zip_nav = None;

        // UI 即応: items をクリアして grid が「読み込み中…」を出せる状態にし、
        // address / current_folder を zip_path にして breadcrumb と BS (parent) を正しく動かす。
        // catalog / sidecar / worker spawn などの重い設定は poll_zip_enumerate の
        // start_loading_items で行う (二重にやらない)。
        self.items.clear();
        self.thumbnails.clear();
        self.image_metas.clear();
        self.invalidate_facet_name_cache();
        self.visible_indices.clear();
        self.details_order.clear();
        self.details_tag_prewarm_indices.clear();
        if let Some(pending) = self.details_meta_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        self.details_image_dims_state = LazyColumnState::Disabled;
        self.selected = None;
        self.grid_click_selection_anchor = None;
        self.scroll_offset_y = 0.0;
        self.pending_grid_scroll = None;
        // 変換キャッシュの override は「current_folder == そのキャッシュ ZIP」の間だけ
        // 有効なペア。**別の ZIP へ遷移するならここで同期的に破棄する** (キャッシュ経由で
        // 開く経路は open_archive_via_cache / 変換完了 pending_nav が load 後に再設定する)。
        // ここで消さないと、下で current_folder を新 ZIP に書き換える → async 列挙完了時の
        // start_loading_items では previous_folder == source_path となり preserve 判定が
        // 常に真 → stale override が残留する。その結果 effective_folder() が古い元
        // アーカイブを指し続け、Ctrl+↑↓ の脱出 DFS が毎回「古いアーカイブの次 = 同じ隣の
        // ZIP」へ着地して、押しっぱなしで同じ ZIP を再走破し続けるループになる (実機報告)。
        if !self
            .current_folder
            .as_ref()
            .is_some_and(|cur| crate::folder_tree::path_eq(cur, &zip_path))
        {
            self.archive_source_override = None;
        }
        self.current_folder = Some(zip_path.clone());
        self.current_folder_rating_cache = None;
        self.current_folder_last_mtime = None;
        self.current_folder_signature = None;
        self.address = zip_path.to_string_lossy().to_string();
        self.update_global_search_address();
        // items_generation はここでは進めない。PDF と同じく、async enumerate 完了後に
        // start_loading_items 内 install_new_items が bump する。ここで進めると
        // poll_fs_nav_lock が「新 items 投入」と誤認して fs_holdover_tex を premature に
        // クリアし、ZIP enumerate 完了前に黒画面遷移してしまう (Codex 指摘)。
        // 代わりに「ZIP 投入直後の repaint」は tail repaint reasons に
        // zip_enumerate_pending を含めることで担保する。

        // worker spawn
        let cancel = Arc::new(AtomicBool::new(false));
        let (tx, rx) = mpsc::channel();
        let path_w = zip_path.clone();
        let cancel_w = Arc::clone(&cancel);
        let spawn_result = std::thread::Builder::new()
            .name("zip-enumerate".into())
            .spawn(move || {
                if cancel_w.load(Ordering::Relaxed) {
                    return;
                }
                let result = crate::zip_loader::enumerate_image_entries_detailed(&path_w)
                    .map_err(|e| e.to_string());
                if let Ok(enumeration) = &result {
                    // CP932 デコード対応で entry_name が変わった ZIP のリリース済み
                    // per-page キー (★/補正/注釈等) を、結果を UI へ返す**前**に移行する。
                    // ここで済ませると開いた直後のレーティング読み出しが必ず新キーに当たる。
                    crate::zip_key_migration::migrate_if_needed(
                        &path_w,
                        &enumeration.legacy_renames,
                    );
                }
                let _ = tx.send(result);
            });

        if let Err(e) = spawn_result {
            // リソース枯渇等でスレッド spawn に失敗した場合は panic せず、UI スレッドで
            // 同期的に enumerate してそのまま start_loading_items に流す
            // (PDF 側と揃えた fallback)。UI は多少詰まるが「アプリが落ちる」よりは遥かにマシ。
            crate::logger::log(format!(
                "zip-enumerate: spawn failed ({e}), falling back to synchronous enumerate"
            ));
            drop(rx);
            let result = crate::zip_loader::enumerate_image_entries_detailed(&zip_path)
                .map_err(|e| e.to_string());
            self.finalize_zip_enumerate(zip_path, result);
            return;
        }

        self.zip_enumerate_pending = Some(ZipEnumeratePending {
            zip_path,
            cancel,
            rx,
        });
    }

    /// `zip_enumerate_pending` の結果を毎フレーム polling する。
    /// 完了時に group/sort + items 構築を行い `start_loading_items` に流す。
    pub(crate) fn poll_zip_enumerate(&mut self) {
        let Some(pending) = self.zip_enumerate_pending.as_ref() else {
            return;
        };
        // 新しい load_folder 等で cancel が立った (実質 Drop 直前) 場合は結果を適用しない
        if pending.cancel.load(Ordering::Relaxed) {
            self.zip_enumerate_pending = None;
            // cancel された pending ではフルスクリーン復帰は不成立。defer フラグを
            // 放置すると grid 抑止 / holdover 維持が永続化するので明示的に破棄する
            // (PDF 側 cancel ガードと対称)。
            self.fs_nav_after_pdf_enumerate = None;
            self.release_fs_nav_lock();
            return;
        }
        let result = match pending.rx.try_recv() {
            Ok(r) => r,
            Err(mpsc::TryRecvError::Empty) => return,
            Err(mpsc::TryRecvError::Disconnected) => {
                crate::logger::log("zip enumerate: worker disconnected");
                let zip_path = pending.zip_path.clone();
                self.zip_enumerate_pending = None;
                // ワーカー切断ではフルスクリーン復帰が起きない: defer フラグを破棄。
                self.fs_nav_after_pdf_enumerate = None;
                self.release_fs_nav_lock();
                self.start_loading_items(
                    zip_path,
                    Vec::new(),
                    Vec::new(),
                    std::collections::HashSet::new(),
                    Vec::new(),
                    None,
                );
                return;
            }
        };
        let zip_path = pending.zip_path.clone();
        self.zip_enumerate_pending = None;
        self.finalize_zip_enumerate(zip_path, result);
    }

    /// enumerate 結果 → group/sort → `start_loading_items`。
    /// async (poll_zip_enumerate) と sync fallback (spawn 失敗時) の両方から呼ぶ。
    fn finalize_zip_enumerate(
        &mut self,
        zip_path: PathBuf,
        result: Result<crate::zip_loader::ZipEnumeration, String>,
    ) {
        let sort = BOOK_READING_PAGE_ORDER;
        let enumeration = match result {
            Ok(e) => e,
            Err(e) => {
                crate::logger::log(format!("  zip enumerate failed: {e}"));
                // 失敗時はフルスクリーンを開き直さないので defer フラグを破棄する
                // (line 6142 の `.take()` には到達しない早期 return パス)。
                self.fs_nav_after_pdf_enumerate = None;
                self.release_fs_nav_lock();
                self.start_loading_items(
                    zip_path,
                    Vec::new(),
                    Vec::new(),
                    std::collections::HashSet::new(),
                    Vec::new(),
                    None,
                );
                return;
            }
        };
        let has_foreign_archives = enumeration.has_foreign_archives;
        let entries = enumeration.entries;
        crate::logger::log(format!(
            "  zip: {} image entries (foreign archives: {has_foreign_archives})",
            entries.len()
        ));

        // ネスト ZIP ツリーナビ (v1.3.0、docs/nested-zip-tree-plan.md Strategy A)。
        // フラット展開 + 章区切りセルをやめ、entry_name の '/' 区切りでツリーを構築し、
        // ルート階層 (冗長ラッパーは自動降下) だけを materialize して表示する。これで
        // 内側 ZIP / サブフォルダが「入れるコンテナ」になり、見開きペアリングが本ごとに
        // リセットされる (= 平坦な並びの偶奇で複数本を 1 冊に連結してしまう問題の根治)。
        // ツリー構築は純ロジック (I/O なし) なので 1100 エントリでも数 ms。
        let tree = std::sync::Arc::new(crate::zip_tree::ZipTree::build(zip_path.clone(), entries));
        // existing_keys は **全階層** のキー (全 leaf entry_name + 全 dir の zipdir:) を
        // 集める。ルート階層しか materialize しないので、これがないと深い階層の
        // サムネが delete_missing で stale 削除されて再生成ループになる (Codex P2)。
        let mut existing_keys: std::collections::HashSet<String> =
            tree.all_cache_keys().into_iter().collect();
        // 本ごとピン (Model B) の代表サムネは zipdir:{prefix}#pin:{entry} キーで保存される。
        // base の zipdir:{prefix} しか existing に無いと delete_missing が pinned 行を毎回
        // 消して再生成になる (Codex P2)。pinned cache key も存続キーに含める。
        // - DB キーは「set 側 = nav スタックの実効 prefix」なので、literal prefix を
        //   `collapse_redundant` で実効 prefix に解決してから引く (単一ラッパー本の
        //   set/lookup キー不一致の根治、レビュー P2)。cache key 側は literal のまま
        //   (= `make_load_request` の `zipdir_cache_key(dir_prefix)` と一致させる)。
        // - lookup は `lookup_many` 1 回に束ねる。per-dir の逐次 SQLite lookup は UI
        //   スレッドで dirs 数に比例してブロックする (レビュー P3)。
        if let Some(pin_db) = self.folder_thumb_pin_db.as_ref() {
            // 変換キャッシュ ZIP では pin DB キーの root が元アーカイブ
            // (`zip_pin_root_path`) になる。ここを cache ZIP root のまま引くと
            // 変換アーカイブ内の本ピンだけ existing_keys に乗らず、delete_missing が
            // pinned 行を毎回 prune して再生成ループになる (set/lookup 側との対称性)。
            let pin_root = zip_pin_root_path(
                &tree.zip_path,
                self.archive_source_override.as_deref(),
                self.current_folder.as_deref(),
            )
            .to_path_buf();
            let dir_keys: Vec<(String, PathBuf)> = existing_keys
                .iter()
                .filter_map(|k| k.strip_prefix("zipdir:").map(|p| p.to_string()))
                .map(|prefix| {
                    let segs: Vec<String> = prefix
                        .split('/')
                        .filter(|s| !s.is_empty())
                        .map(|s| s.to_string())
                        .collect();
                    let effective = tree.collapse_redundant(&segs);
                    let book_key = book_container_key_from_segs(&pin_root, &effective);
                    (prefix, book_key)
                })
                .collect();
            let pin_map = pin_db.lookup_many(dir_keys.iter().map(|(_, k)| k.clone()));
            let pinned: Vec<String> = dir_keys
                .iter()
                .filter_map(|(prefix, book_key)| {
                    let norm = crate::path_key::normalize_keep_drive(book_key);
                    match pin_map.get(&norm) {
                        Some(crate::folder_thumb_pins::FolderPinSource::ZipEntry {
                            zip_rel,
                            entry,
                        }) if zip_rel.is_empty() => Some(format!(
                            "{}{}{}",
                            crate::grid_item::zipdir_cache_key(prefix),
                            crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                            entry
                        )),
                        Some(
                            source @ crate::folder_thumb_pins::FolderPinSource::ZipDir {
                                zip_rel,
                                ..
                            },
                        ) if zip_rel.is_empty() => resolve_pin_target_cascaded(
                            book_key,
                            source,
                            Some(pin_db.as_ref()),
                            self.settings.folder_thumb_depth as usize,
                        )
                        .map(|resolved| {
                            format!(
                                "{}{}{}",
                                crate::grid_item::zipdir_cache_key(prefix),
                                crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                                resolved.source_id,
                            )
                        }),
                        _ => None,
                    }
                })
                .collect();
            existing_keys.extend(pinned);
        }
        let nav = crate::zip_tree::ZipNavState::new(tree);
        let (mut items, mut image_metas) = nav.materialize_current(sort);
        crate::grid_item::arrange_grid_items(
            &mut items,
            &mut image_metas,
            &self.settings.grid_display_order,
            Some(sort),
        );

        self.start_loading_items(
            zip_path.clone(),
            items,
            image_metas,
            existing_keys,
            Vec::new(),
            None,
        );
        // start_loading_items が zip_nav を None にした後で、新しいツリーナビを設定する。
        self.zip_nav = Some(nav);
        // アドレス欄をパンくず表示に更新 (単一ラッパー ZIP は collapse 済み実効 prefix を反映)。
        self.update_zip_nav_address();
        // ルート本の見開き設定を本ごとのキー (zip_path + 実効 prefix) で読み直す。
        // start_loading_items は zip_path キーで読んだので、ここで上書きする。
        // 本キーに未保存の項目は zip_path キーへフォールバック (v1.2.x 保存分の互換)。
        if let Some(key) = self.spread_container_key() {
            let fb = self.zip_nav.as_ref().map(|nav| nav.tree.zip_path.clone());
            let defaults = SpreadRestoreDefaults::for_book(&self.settings);
            self.apply_spread_for_key_with_fallback(&key, fb.as_deref(), defaults);
            self.apply_view_trim_for_key_with_fallback(&key, fb.as_deref());
        }
        self.enter_pending_rating_view_zipdir_after_open(&zip_path);

        // 列挙で非 ZIP アーカイブ (RAR/7z/LZH) を検出した場合の変換提案の段取り。
        // 自動フルスクリーン予約 (deferred) と同フレームでぶつかると、提案ダイアログが
        // メインビューポート側に出てフルスクリーンビューポートの裏に隠れる (Codex P2):
        // - 読書中の流入 (fs_nav lock 保持 = Ctrl+↑↓ / スライドショー / ★固定ナビ):
        //   フルスクリーン継続を優先して今回は提案しない (グリッドから開き直すと出る)
        // - グリッドからの自動フルスクリーン予約 (lock なし): FS 予約を取り下げて提案を
        //   出し、変換完了後の自動フルスクリーンへ引き継ぐ (ConvertState.auto_fullscreen)
        let offer_foreign = has_foreign_archives
            && self
                .zip_nav
                .as_ref()
                .is_some_and(|nav| self.zip_foreign_offer_applicable(&nav.tree.zip_path));
        let mut offer_now = offer_foreign;
        let mut offer_auto_fs = false;
        if offer_foreign && self.fs_nav_after_pdf_enumerate.is_some() {
            if self.fs_nav_is_locked() {
                offer_now = false;
            } else {
                self.fs_nav_after_pdf_enumerate = None;
                offer_auto_fs = true;
            }
        }

        // Ctrl+↑↓ フォルダナビから fullscreen で ZIP に遷移してきた場合、items が
        // 揃った今 fullscreen を開き直す (Codex P1: PDF と同じ処理を ZIP にも適用)。
        if let Some(deferred) = self.fs_nav_after_pdf_enumerate.take() {
            self.open_deferred_fullscreen_after_enumerate(deferred);
        }

        // 列挙で非 ZIP アーカイブ (RAR/7z/LZH) を検出した場合、入れ子を展開した
        // 閲覧用キャッシュへの変換を提案する (v1.3.0)。ツリー表示は既に出ている
        // (非 ZIP の中身だけが見えない) ので、キャンセルしてもそのまま閲覧できる。
        if offer_now {
            let zip_path = self.zip_nav.as_ref().map(|nav| nav.tree.zip_path.clone());
            if let Some(zip_path) = zip_path {
                self.offer_zip_foreign_archive_conversion(&zip_path, offer_auto_fs);
            }
        }
    }

    /// `offer_zip_foreign_archive_conversion` を出してよい状況か (ループ / 多重防止)。
    /// - キャッシュ ZIP 自身では提案しない (変換出力は非 ZIP アーカイブのファイル
    ///   エントリを含まないので通常 flag 自体立たないが、手作りの類似 ZIP への防御)
    /// - RAR 等の変換キャッシュを開いている最中 (`archive_source_override`) も同様
    /// - 既に別の変換ダイアログが動作中なら出さない
    /// - ★固定 (snapshot) 中も出さない: キャッシュ ZIP は snapshot 範囲外なので
    ///   振り替え (`load_folder`) が範囲外ガードでブロックされ、自動フルスクリーン
    ///   予約だけ消える中途半端な状態になる (Codex R2 P3)。固定解除後に開き直せば
    ///   通常どおり提案される。
    fn zip_foreign_offer_applicable(&self, zip_path: &Path) -> bool {
        !crate::archive_cache::is_under_cache_root(zip_path)
            && self.archive_source_override.is_none()
            && self.archive_convert.is_none()
            && self.batch_convert.is_none()
            && !self.is_snapshot_active()
            && !self.settings.archive_file_handling_ignores_convertible()
    }

    /// ZIP 列挙で非 ZIP アーカイブ (RAR/7z/LZH) を検出したときの「入れ子を展開した
    /// 閲覧用キャッシュへの変換」提案 (v1.3.0)。`ArchiveFormat::Zip` で既存の変換
    /// ダイアログ (`request_archive_convert`) に乗せる。変換完了後はキャッシュ ZIP を
    /// `archive_source_override` 付きで開く (RAR 等と同じ pending_nav 経路)。
    /// `auto_fullscreen` はグリッドの自動フルスクリーン予約を取り下げて提案に
    /// 置き換えた場合に true (変換完了後に 1 ページ目を自動フルスクリーン表示)。
    fn offer_zip_foreign_archive_conversion(&mut self, zip_path: &Path, auto_fullscreen: bool) {
        if !self.zip_foreign_offer_applicable(zip_path) {
            return;
        }
        // 既にキャッシュがある (開いている間に別経路で変換が完了した等) なら
        // ダイアログを出さずそのまま振り替える。
        if let Some(cached) = self.try_archive_cache_lookup(zip_path) {
            let _ = self.open_archive_via_cache(zip_path.to_path_buf(), cached, auto_fullscreen);
            return;
        }
        let _ = self.request_archive_convert(
            zip_path.to_path_buf(),
            crate::archive_converter::ArchiveFormat::Zip,
            auto_fullscreen,
        );
    }

    /// 現在の `zip_nav` 階層を materialize して grid に表示する (軽量経路、Phase 3)。
    ///
    /// `start_loading_items` を通さない: catalog / worker は同一コンテナ (外側 ZIP) で
    /// 再構築不要、かつ階層内移動でフォルダ履歴 / last_folder を汚さないため。
    /// Ctrl+G の `replace_search_view_items` と同様に `install_new_items` +
    /// `invalidate_idx_state_and_queues` で idx 状態と in-flight キューを破棄し、
    /// サムネは永続ワーカー + 毎フレーム reconcile が Pending を拾って再ロードする。
    /// `zip_nav` 自体は維持される (= ナビ継続)。
    fn zip_nav_show_current_level(&mut self) {
        let sort = BOOK_READING_PAGE_ORDER;
        let display_order = self.settings.grid_display_order.clone();
        let (items, metas, zip_path) = {
            let Some(nav) = self.zip_nav.as_ref() else {
                return;
            };
            let (mut items, mut metas) = nav.materialize_current(sort);
            crate::grid_item::arrange_grid_items(
                &mut items,
                &mut metas,
                &display_order,
                Some(sort),
            );
            (items, metas, nav.tree.zip_path.clone())
        };
        // 旧レベルの in-flight 検索 / 詳細メタ pending を停止 (idx が付け替わるので無意味)。
        if let Some(pending) = self.search_pending.take() {
            pending.cancel();
        }
        if let Some(pending) = self.metadata_pending.take() {
            pending.cancel();
        }
        // Loaded 済みサムネを content key で確保しておき、install 後に新 idx へ転送する
        // (Ctrl+G `replace_search_view_items` の thumb_reuse_key と同じ発想、レビュー P3)。
        // enter/back は新旧レベルの item が交わらないため実質 no-op だが、**同一階層の
        // 再 materialize (ソート変更 / ピン dirty 再表示)** では同じ item が並び替わる
        // だけなので、全 Pending リセットによる一瞬のプレースホルダフラッシュを防げる。
        // key の構成は `zip_level_thumb_reuse_key` 参照 (ZipDir は representative 込み:
        // ソート変更で代表が変わったセルは意図的にキー不一致 → 新代表で読み直す、Codex P2)。
        // 補正対象の source pixels も同じ key で移す (Ctrl+G と同様、補正済み tex は再生成)。
        let preserved: std::collections::HashMap<String, crate::grid_item::ThumbnailState> = self
            .items
            .iter()
            .zip(self.thumbnails.iter())
            .filter_map(|(it, st)| match st {
                crate::grid_item::ThumbnailState::Loaded { .. } => {
                    zip_level_thumb_reuse_key(it).map(|k| (k, st.clone()))
                }
                _ => None,
            })
            .collect();
        let preserved_thumb_pixels: std::collections::HashMap<String, Arc<egui::ColorImage>> = self
            .items
            .iter()
            .enumerate()
            .filter_map(|(i, it)| {
                self.thumb_pixels
                    .get(&i)
                    .cloned()
                    .and_then(|pixels| zip_level_thumb_reuse_key(it).map(|k| (k, pixels)))
            })
            .collect();
        let preserved_thumb_layers: std::collections::HashMap<
            String,
            Arc<Vec<crate::edit_preview_cache::CachedAnnotationLayer>>,
        > = self
            .items
            .iter()
            .enumerate()
            .filter_map(|(i, it)| {
                self.thumb_edit_preview_layers
                    .get(&i)
                    .cloned()
                    .and_then(|layers| zip_level_thumb_reuse_key(it).map(|key| (key, layers)))
            })
            .collect();
        // A pinned Folder/ZIP/PDF representative can inherit the edit-preview identity of its
        // resolved child page.  `install_new_items` clears the idx-keyed map, so preserve that
        // identity with the same content key as the Loaded thumbnail.  Without this, a later
        // edit notification cannot find and invalidate the reused parent thumbnail.
        let preserved_thumb_preview_keys: std::collections::HashMap<String, String> = self
            .items
            .iter()
            .enumerate()
            .filter_map(|(i, it)| {
                self.thumb_edit_preview_keys
                    .get(&i)
                    .cloned()
                    .and_then(|preview_key| {
                        zip_level_thumb_reuse_key(it).map(|reuse_key| (reuse_key, preview_key))
                    })
            })
            .collect();
        // items / image_metas / thumbnails 差し替え + items_generation bump。
        self.install_new_items(items, metas);
        // idx ベース状態 + in-flight キューを破棄 (replace_search_view_items / snapshot と同じ)。
        self.invalidate_idx_state_and_queues();
        if self.color_filter.enabled {
            self.color_filter.applied_scope_signature = None;
            self.color_filter.confirmation = None;
            self.color_filter.confirmed_large_scan_scope = None;
            self.color_filter_scope_refresh_pending = true;
        }
        // ZIP 内の階層ごとに Shift+F のコンテナ★キーが変わるため、アドレスバー★の
        // メモ化値も階層切替ごとに捨てる。
        self.current_folder_rating_cache = None;
        // 確保しておいた Loaded サムネを新 idx に転送 (invalidate の後 = thumb_pixels が
        // clear された後)。Loaded のままなら upload backlog に乗らず同一フレームで前回の
        // テクスチャが見え続けるのでちらつかない。
        if !preserved.is_empty() {
            for i in 0..self.items.len() {
                let Some(key) = zip_level_thumb_reuse_key(&self.items[i]) else {
                    continue;
                };
                if let Some(state) = preserved.get(&key) {
                    self.thumbnails[i] = state.clone();
                    if let Some(preview_key) = preserved_thumb_preview_keys.get(&key) {
                        self.thumb_edit_preview_keys.insert(i, preview_key.clone());
                    }
                    if is_thumb_adjust_target(Some(&self.items[i])) {
                        if let Some(pixels) = preserved_thumb_pixels.get(&key) {
                            self.thumb_pixels.insert(i, Arc::clone(pixels));
                        }
                        if let Some(layers) = preserved_thumb_layers.get(&key) {
                            self.thumb_edit_preview_layers.insert(i, Arc::clone(layers));
                        }
                    }
                }
            }
        }
        // idx-keyed ページ編集状態 (補正 / ローカル調整 / 最終段 crop / 消しゴム / 隠蔽) を
        // clear して、新レベルの entry に対し DB から再 hydrate する。entry_name キーで引くので
        // 階層が変わっても各ページの保存済み補正・マスクが正しく載り、旧 idx の編集が別 entry に
        // 漏れない (Codex P1)。invalidate はこれらを意図的に触らないので明示的に呼ぶ必要がある。
        self.rehydrate_page_edit_state_for_current_items(&zip_path);
        self.local_adjust_generation.clear();
        self.local_adjust_cache.clear();
        // path-keyed メタキャッシュは新レベルの別 entry 用にリセット。
        self.metadata_cache.clear();
        self.exif_cache.clear();
        self.xmp_cache.clear();
        self.clear_tags_cache();
        // Ctrl+F フィルタの残留を解除 (旧レベルの entry 向けなので新レベルでは無効)。
        self.search_filter = None;
        self.search_query.clear();
        self.selected = None;
        self.scroll_offset_y = 0.0;
        self.scroll_to_selected = false;
        self.pending_grid_scroll = None;
        self.scroll_hint
            .store(0, std::sync::atomic::Ordering::Relaxed);
        // レーティングフィルタ有効時、rebuild_visible_indices が item ごとに get_rating で
        // SQLite を引くと UI スレッドが詰まる。start_loading_items と同じく事前に
        // バッチ prewarm しておく (Codex P3 perf parity)。
        self.prewarm_rating_cache();
        // facet filter は visible_indices の構築に直接効くため、ZIP 階層で anchor 外へ
        // 戻った場合は再構築前に親条件を復元しておく。
        self.maybe_restore_facet_filter_after_zip_level_change();
        // ★ visible_indices を再構築。これがないと旧レベルの stale index が
        // update_keep_range_and_requests で thumbnails[i] を範囲外参照して panic する (Codex P1)。
        self.rebuild_visible_indices();
        // tag prewarm worker は invalidate で cancel 済み → 新レベル向けに再起動。
        self.prewarm_grid_tags();
        // アドレス欄を「元 ZIP パス > ZIP 内パス」のパンくず表示に更新。
        self.update_zip_nav_address();
        // 入った本 (= 現在の階層) の見開き設定を本ごとのキーで読み直す。これで BS 戻り /
        // Ctrl+↓ 等どの経路で本を切り替えても、その本の見開き向き / 連結方向が一貫して
        // 復元される (ユーザー要望: 本ごとに独立記憶)。本キーに未保存の項目は zip_path
        // キーへフォールバック (v1.2.x 保存分の互換 + ZIP 全体設定の継承)。
        if let Some(key) = self.spread_container_key() {
            let fb = self.zip_nav.as_ref().map(|nav| nav.tree.zip_path.clone());
            let defaults = SpreadRestoreDefaults::for_book(&self.settings);
            self.apply_spread_for_key_with_fallback(&key, fb.as_deref(), defaults);
            self.apply_view_trim_for_key_with_fallback(&key, fb.as_deref());
        }
        // ★付きの本を開いて一時解除したフィルタを、本より上の階層へ戻ったら復元する
        // (実フォルダの maybe_restore_rating_filter_if_out_of_scope に相当)。
        self.maybe_restore_rating_filter_after_zip_level_change();
    }

    /// アドレス欄をネスト ZIP ツリーナビのパンくず表示にする。
    /// `元 ZIP のフルパス > seg1 > seg2 …` (ルート階層なら ZIP パスのみ)。
    /// 検索ドリルの breadcrumb (`update_global_search_address`) と同じ " > " 区切り表記。
    /// `self.address` は nav イベント時のみ更新され毎フレーム再計算されないので、
    /// ここで設定したパンくずは次のフォルダ遷移まで保持される。
    pub(crate) fn update_zip_nav_address(&mut self) {
        let addr = {
            let Some(nav) = self.zip_nav.as_ref() else {
                return;
            };
            // 変換キャッシュ ZIP (RAR/7z/LZH/CBR/CB7) を開いている場合、表示根はユーザー視点の
            // 元アーカイブパス (archive_source_override) にする。nav.tree.zip_path は内部の
            // キャッシュ ZIP 実体なので、そのまま出すとユーザーに見せるべきでないパスが漏れる
            // (Codex P2)。通常 ZIP は override 無しなので zip_path をそのまま使う。
            let root = self
                .archive_source_override
                .as_ref()
                .unwrap_or(&nav.tree.zip_path);
            let zip = root.display().to_string();
            let segs = nav.current();
            if segs.is_empty() {
                zip
            } else {
                format!("{zip} > {}", segs.join(" > "))
            }
        };
        self.address = addr;
    }

    /// レーティング一覧に復元された ZipDir セルを開く。
    /// 一覧ビューには `zip_nav` が無いので、外側 ZIP / 変換アーカイブを通常経路で開き、
    /// 列挙完了後に `dir_prefix` へ入る。
    pub(crate) fn open_rating_view_zipdir(&mut self, zip_path: PathBuf, dir_prefix: String) {
        if dir_prefix.is_empty() {
            return;
        }
        let rollback = self
            .rating_view_nav_context_active()
            .then(|| self.folder_nav_history_snapshot());
        self.record_rating_view_nav_open(&zip_path);
        self.pending_rating_view_zipdir_open = Some(PendingRatingViewZipDirOpen {
            source_path: zip_path.clone(),
            dir_prefix,
        });
        match self.load_folder_or_convert_archive(zip_path) {
            FolderOpenOutcome::Ignored => {
                self.pending_rating_view_zipdir_open = None;
                if let Some(snapshot) = rollback {
                    self.restore_folder_nav_history(snapshot);
                }
            }
            FolderOpenOutcome::ConversionDialogOpened => {
                if let Some(snapshot) = rollback {
                    self.attach_archive_convert_nav_history_rollback(snapshot);
                }
            }
            FolderOpenOutcome::Loaded => {}
        }
    }

    fn enter_pending_rating_view_zipdir_after_open(&mut self, loaded_zip_path: &Path) -> bool {
        let Some(pending) = self.pending_rating_view_zipdir_open.take() else {
            return false;
        };
        let source_matches_loaded =
            crate::folder_tree::path_eq(&pending.source_path, loaded_zip_path);
        let source_matches_override = self
            .archive_source_override
            .as_ref()
            .is_some_and(|source| crate::folder_tree::path_eq(source, &pending.source_path));
        if !source_matches_loaded && !source_matches_override {
            crate::logger::log(format!(
                "rating-view zipdir open dropped: pending={} loaded={}",
                pending.source_path.display(),
                loaded_zip_path.display()
            ));
            return false;
        }
        let Some(nav) = self.zip_nav.as_mut() else {
            self.pending_rating_view_zipdir_open = Some(pending);
            return false;
        };
        nav.enter(&pending.dir_prefix);
        self.zip_nav_show_current_level();
        true
    }

    /// `ZipDir` セルへ降りる (Enter / ダブルクリック / ゲームパッド accept)。
    /// `dir_prefix` は `GridItem::ZipDir.dir_prefix` (ルートからの絶対パス、末尾 '/')。
    pub(crate) fn zip_nav_enter(&mut self, dir_prefix: &str) {
        let Some(nav) = self.zip_nav.as_mut() else {
            return;
        };
        nav.enter(dir_prefix);
        self.zip_nav_show_current_level();
    }

    /// ZIP 階層を 1 段戻る。戻れたら `true`、ルート (スタック底) なら `false`
    /// (= 呼び出し側が ZIP を抜けて実フォルダ親へ遷移する)。
    ///
    /// 戻った後、出てきた本の ZipDir セルを選択して「どの本から出たか」を示す
    /// (BS で実フォルダ親へ抜けたとき `select_after_load` が ZIP を選ぶのと同じ慣習、
    /// レビュー P3)。collapse で深く降りていた本でも、セルの literal prefix は
    /// 出てきた実効 prefix の先頭部分に一致するので前方一致で探せる。
    pub(crate) fn zip_nav_back(&mut self) -> bool {
        let left = {
            let Some(nav) = self.zip_nav.as_mut() else {
                return false;
            };
            let left: Vec<String> = nav.current().to_vec();
            if !nav.back() {
                return false;
            }
            left
        };
        self.zip_nav_show_current_level();
        let target = self.items.iter().position(|it| match it {
            GridItem::ZipDir { dir_prefix, .. } => {
                let segs: Vec<&str> = dir_prefix.split('/').filter(|s| !s.is_empty()).collect();
                !segs.is_empty()
                    && segs.len() <= left.len()
                    && segs.iter().zip(left.iter()).all(|(a, b)| *a == b.as_str())
            }
            _ => false,
        });
        if let Some(idx) = target {
            self.selected = Some(idx);
            self.scroll_to_selected = true;
        }
        true
    }

    /// Ctrl+↑↓ をネスト ZIP ツリーの DFS 前順ナビとして処理する (#4 改)。
    ///
    /// 実フォルダの Ctrl+↑↓ と同じ規則 (次 = 最初の子 → 次の兄弟 → 祖先の次の兄弟、
    /// 前 = 前の兄弟の最後の子孫 → 親) を ZIP 内ツリーに適用する。ルート表示でも
    /// 子の本があれば降りる (実機 3 巡目フィードバック: 旧仕様はルートで子を素通りして
    /// 次の実 ZIP へスキップ + 本の中から ZIP を抜けられなかった)。
    ///
    /// 戻り値 `true` = 消費した (= 通常のフォルダ DFS ナビへ流さない)。ツリーの端
    /// (forward=最後のノードの後 / backward=ルートの前) では `false` を返し、呼び出し側が
    /// 従来どおり ZIP を抜けて実フォルダの DFS ナビへ続く (= ZIP の中身を実フォルダ
    /// ツリーの一部として通過できる)。
    pub(crate) fn zip_nav_handle_ctrl_updown(&mut self, forward: bool) -> bool {
        if self.zip_nav.is_none() {
            return false;
        }
        let sort = BOOK_READING_PAGE_ORDER;
        let moved = self
            .zip_nav
            .as_mut()
            .map(|n| n.dfs_step(forward, sort))
            .unwrap_or(false);
        if moved {
            self.zip_nav_show_current_level();
            true
        } else {
            false
        }
    }

    /// フルスクリーン中の Ctrl+↑↓ DFS ナビ (#4 改)。**直下画像を持つ**次/前のノード
    /// (= 読めるページがある階層) まで DFS 前順で進み、その先頭画像をフルスクリーンで
    /// 開く。子コンテナだけの分岐ノードは読書中の停止点として意味が無いのでスキップする
    /// (グリッド側 `zip_nav_handle_ctrl_updown` は全ノードに停止する — 実フォルダの
    /// グリッド Ctrl+↑↓ が画像なしフォルダにも止まるのと同じ非対称)。
    /// ツリーの端に達したら nav 状態を変えず `false` (= 呼び出し側が ZIP を抜けて
    /// 次/前の実フォルダへ。スライドショー next-folder の分岐にも使う)。
    ///
    /// ⚠ holdover キャプチャ (`capture_fs_nav_holdover`) は **移動が確定してから**行う。
    /// holdover は `fs_nav_locked_gen = items_generation` を立て、`poll_fs_nav_lock` は
    /// items_generation が進むまで解除しない。端で移動しないのに先に capture すると items が
    /// 変わらず lock が永久に残り、以降のフルスクリーン Ctrl+↑↓ が無視される (Codex P1)。
    /// 探索は clone した nav 上で行い items は触らないので、着地確定後
    /// `zip_nav_show_current_level` の前に capture すれば旧ページの holdover を正しく取れる。
    pub(crate) fn zip_nav_dfs_fullscreen(&mut self, fs_idx: usize, forward: bool) -> bool {
        let sort = BOOK_READING_PAGE_ORDER;
        let Some(nav) = self.zip_nav.as_ref() else {
            return false;
        };
        // 直下画像のあるノードまで clone 上で DFS 探索し、見つかったときだけ本体へ
        // 書き戻す (端に達したケースで途中まで進んだ状態が残らないように)。
        // dfs_step は前順を強制前進するのでループは必ず有限で終わる。
        let mut probe = nav.clone();
        let landed = loop {
            if !probe.dfs_step(forward, sort) {
                break false; // ツリーの端: ZIP を抜ける (呼び出し側で実フォルダ nav へ)
            }
            let has_images = probe
                .tree
                .node_at(probe.current())
                .is_some_and(|n| !n.images.is_empty());
            if has_images {
                break true;
            }
        };
        if !landed {
            return false;
        }
        self.zip_nav = Some(probe);
        // 移動確定 → holdover を取ってから items を差し替える。
        self.capture_fs_nav_holdover(fs_idx);
        // 新しい本のページに差し替え + その本の見開き設定を適用。
        self.zip_nav_show_current_level();
        // 新しい本の先頭画像をフルスクリーンで開く (Ctrl+↑↓ 慣習: 常に先頭着地)。
        if let Some(new_idx) = self.find_fullscreen_nav_target_filtered(true) {
            self.open_fullscreen(new_idx, crate::app::HistoryTrigger::UserChosen);
            self.selected = Some(new_idx);
            self.scroll_to_selected = true;
            self.update_last_selected_image();
        } else {
            // 直下画像はあるがレーティングフィルタで全 hidden のケース。
            // open_fullscreen に到達しないまま放置すると、
            // ① 旧 fs_idx が新 items の範囲外なら poll_fs_nav_lock の解除条件
            //    (thumbnails[idx] Loaded / fs_cache) に永遠に達せず holdover lock が
            //    残留して以降の Ctrl+↑↓ が全部無視される、
            // ② 範囲内なら ZipDir セルをフルスクリーン表示してしまう (レビュー P1)。
            // lock を明示解放してフルスクリーンを閉じ、グリッドにこの階層を見せる
            // (= グリッド側 Ctrl+↓ でこの階層へ移動したときと同じ着地)。
            self.release_fs_nav_lock();
            self.slideshow_playing = false;
            self.slideshow_anchor_idx = None;
            self.continuous_reading_scroll_transition = None;
            self.slideshow_scroll_range_cache = None;
            self.close_fullscreen();
        }
        true
    }

    /// PDF ファイルを仮想フォルダとして開く (非同期)。
    ///
    /// ワーカーにページ列挙リクエストを送り、即座に return する。
    /// 結果は `poll_pdf_enumerate` が次フレーム以降にポーリングして処理する。
    /// パスワード付き PDF の場合はダイアログで入力を求める。
    pub fn load_pdf_as_folder(&mut self, pdf_path: PathBuf) {
        crate::logger::log(format!(
            "=== load_pdf_as_folder: {} ===",
            pdf_path.display()
        ));

        #[cfg(windows)]
        if self.should_preserve_active_detached_image_window_for_main_context_change() {
            self.preserve_active_detached_image_window_for_main_context_change();
            self.close_fullscreen();
        }

        // PDF を開く際、直前に ZIP を見ていた可能性があるためネスト ZIP キャッシュを破棄する。
        crate::zip_loader::clear_nested_cache();
        // ZIP を出るのでツリーナビ状態も破棄。
        self.zip_nav = None;

        // 旧サムネイルワーカーを即座にキャンセルして PDF ワーカーキューの渋滞を防ぐ。
        // start_loading_items は enumerate 完了後に呼ばれるため、ここで先行キャンセルする。
        self.cancel_token.store(true, Ordering::Relaxed);
        self.wake_all_workers();

        // 旧 pending を drop すると `PdfEnumerateHandle::Drop` が cancel を立て、
        // pool dispatcher は pop 時に IPC 前で古いジョブを捨てる。
        // ZIP 側 pending も一緒に捨てる (ZIP → PDF 遷移時の取り残し防止、Codex P2)。
        self.pdf_enumerate_pending = None;
        self.zip_enumerate_pending = None;
        // 直前の cache-hit の placeholder 情報はクリア (= 新規 nav の出発点)。
        self.pdf_placeholder_count = None;
        // 自動 1 ページ目フルスクリーン (環境設定 ON で grid から PDF を開いた) の予約を、
        // enumerate 完了で先頭ページを開く既存 deferred 機構へ載せ替える。folder-nav は
        // pending_auto_fs_open=false なのでここでは触らない (reopen が後段で set する)。
        if std::mem::take(&mut self.pending_auto_fs_open) {
            self.fs_nav_after_pdf_enumerate = Some(DeferredFsReopen {
                history_trigger: crate::app::HistoryTrigger::UserChosen,
                resume_slideshow: false,
                target: DeferredFsTarget::None,
                // 「ZIP/PDF × 一覧から開く」: 続きから / 先頭から を設定で切替。
                resume_to_last_page: self.settings.book_open_resume.resumes(),
                from_explicit_open: true,
                preserve_after_password_prompt: true,
            });
        }

        // ── パスワード確認 ──
        // **`saved_password`** = この PDF 固有の保存パスワード (`pdf_passwords` 経由)。
        // **`password`** = enumerate に渡す実値 (saved_password 優先、無ければ
        // session-level の `pdf_current_password` フォールバック)。
        // メタキャッシュの placeholder gate には `saved_password.is_some()` を使う
        // こと (= Codex P1 対策。session password の居座りで他 PDF の保護を bypass
        // しないため)。
        let saved_password: Option<String> = self.pdf_passwords.get(&pdf_path);
        let password: Option<String> = saved_password
            .clone()
            .or_else(|| self.pdf_current_password.clone());

        // パスワードチェックも非同期化したいが、ダイアログ表示のフローが複雑になるため
        // ここでは簡易判定: 保存済みパスワードがなければ非同期で check_password を含めて
        // enumerate を試みる。パスワードエラーは結果受信時にハンドルする。

        // ── 隣接 PDF の ±1 を items から先に取り出す (Codex P2 round 1 対応) ──
        // 次の `try_apply_pdf_meta_cache` が cache hit すると start_loading_items で
        // `self.items` が PDF ページに置き換わるため、PdfFile の隣接探索は **その前**
        // に済ませる必要がある。pre-fetch 自体の kick は文中の最後 (placeholder 適用 +
        // pending セット完了後) にまとめて行う。
        let neighbor_pdf_paths = self.collect_neighbor_pdf_paths(&pdf_path);

        // ── PDF メタキャッシュ (v1.0.0) lookup ──
        // 過去に enumerate or サムネ render に成功した PDF はページ数が catalog DB に
        // 永続化されている。mtime/file_size 一致なら即座に N セルの placeholder grid に
        // 遷移して「キビキビ動く」体感を実現する (= PDFium 開封の 100ms〜1.3s を裏に隠す)。
        // 検証 enumerate は並行して必ず走らせ、結果を `poll_pdf_enumerate` で照合する。
        let placeholder_built = self.try_apply_pdf_meta_cache(&pdf_path, saved_password.is_some());

        // ── 非同期でページ列挙をリクエスト (検証 + cache 更新) ──
        let handle = crate::pdf_loader::enumerate_pages_async(&pdf_path, password.as_deref());
        self.pdf_enumerate_pending = Some((pdf_path.clone(), password, handle));
        if placeholder_built.is_some() {
            // 検証用に覚えておく: 一致なら grid 再構築 skip、不一致なら再構築する。
            self.pdf_placeholder_count = placeholder_built;
        }

        // アドレスバーを即座に更新 (ローディング中であることを示す)
        self.address = pdf_path.to_string_lossy().to_string();
        // Ctrl+G 絞り込みビュー中なら生の PDF パスを「🌐 アイテム検索: "query" > scansnap >
        // ファイル名.pdf」のブレッドクラム形式で上書きし直す (2026-04 ユーザー報告)。
        // no-op: Ctrl+G 非アクティブ / Aggregated 時は何もしない。
        self.update_global_search_address();

        // PDFium による PDF オープン + ページ列挙はファイル固有 (cold disk + 構造解析)
        // で 100ms〜1.3s 程度かかる。その間、グリッドは親フォルダのままで動かないため
        // 「Enter は効いたのか?」とユーザーが不安になる。左下に「読み込み中」バッジを
        // 出すのは `render_container_enumerate_overlay` ([ui_main.rs])。既存「先読み N/M」
        // と同じ場所 (LEFT_BOTTOM) なので、ユーザーの目線パターンに合う。

        // ── 隣接 PDF の pre-fetch (v1.0.0、Ctrl+↑↓ ナビ最適化) ──
        // 上で `collect_neighbor_pdf_paths` で先に親 items から拾った ±1 の PdfFile に
        // ついて、background で render_page を kick して page_count + WebP サムネ +
        // OS cache を温める。ユーザーが Ctrl+↑↓ で次々と PDF を渡り歩くケースで
        // 「次の PDF も cache hit 経路で瞬時化」する効果。
        if !neighbor_pdf_paths.is_empty() {
            self.spawn_neighbor_pdf_prefetch_tasks(neighbor_pdf_paths);
        }
    }

    /// `self.items` が親フォルダの内容を持つ時点で呼ばれ、現在位置 (`current_pdf`) の
    /// ±1 にある `PdfFile` を集めて返す。順序は parent → next。`current_pdf` が
    /// 見つからない (= 検索結果ビュー等から開いた) 場合は空 Vec。
    fn collect_neighbor_pdf_paths(&self, current_pdf: &Path) -> Vec<PathBuf> {
        let mut out = Vec::new();
        let idx = self.items.iter().position(|item| match item {
            GridItem::PdfFile(p) => crate::folder_tree::path_eq(p, current_pdf),
            _ => false,
        });
        let Some(idx) = idx else {
            return out;
        };
        if idx > 0 {
            if let Some(GridItem::PdfFile(p)) = self.items.get(idx - 1) {
                out.push(p.clone());
            }
        }
        if let Some(GridItem::PdfFile(p)) = self.items.get(idx + 1) {
            out.push(p.clone());
        }
        out
    }

    /// 隣接 PDF prefetch ジョブを enqueue する (background worker queue 経由)。
    ///
    /// **Codex P3 round 2 対応**: 親 catalog の取得は LRU **hit のみ** で済ませる。
    /// `get_or_open_catalog` を使うと UI スレッドで cold `CatalogDb::open` (30-150ms)
    /// が走り得る。検索結果 / FavSearch のように隣接 PDF が複数フォルダから集まる
    /// 場合は最大 2 回 × cold open で UI が固まり、Enter 直後の体感を削る。warm catalog
    /// のみで prefetch を走らせ、cold な隣接は skip (= ユーザーが実際に Enter したとき
    /// 通常経路で populate されるので機能不整合なし)。
    ///
    /// **Codex P2-1 round 1 対応**: 各 neighbor の親ごとに catalog を取り直す。
    /// 検索結果のように複数フォルダ由来の neighbor がいるケースで、別フォルダの PDF
    /// メタ/`pdfthumb:` を誤った catalog DB に書き込む事故を防ぐ。
    fn spawn_neighbor_pdf_prefetch_tasks(&mut self, neighbor_paths: Vec<PathBuf>) {
        let thumb_px = self.settings.thumb_px;
        let thumb_quality = self.settings.thumb_quality;
        for neighbor in neighbor_paths {
            let Some(parent) = neighbor.parent().map(|p| p.to_path_buf()) else {
                continue;
            };
            // **warm hit のみ** 使う。`HashMap::get` で cold open を発火させない。
            // hit すれば LRU 順序の更新だけのためにあえて `get_or_open_catalog` を呼ばず、
            // 直接 cache から Arc::clone する。
            let Some(parent_catalog) = self.catalog_cache.get(&parent).cloned() else {
                continue;
            };
            crate::thumb_loader::spawn_pdf_neighbor_prefetch(
                neighbor,
                parent_catalog,
                thumb_px,
                thumb_quality,
            );
        }
    }

    fn open_deferred_fullscreen_after_enumerate(
        &mut self,
        deferred: DeferredFsReopen,
    ) -> DeferredFsOpenOutcome {
        // ★固定 navigation の Preferred target は従来どおり miss 時に読書位置 / 先頭へ
        // fallback する。一方、detached の明示 leaf open は Required で、対象が列挙結果に
        // 無ければ別ページを開かず terminal close へ進める。
        let mut new_idx = match &deferred.target {
            DeferredFsTarget::None => None,
            DeferredFsTarget::Preferred(target) => self.resolve_snapshot_target_idx(target),
            DeferredFsTarget::Required(target) => {
                let resolved = self.resolve_snapshot_target_idx(target);
                if resolved.is_none() {
                    crate::logger::log(format!("detached deferred target missing: {target:?}"));
                    return DeferredFsOpenOutcome::RequiredTargetMissing;
                }
                resolved
            }
        };
        // grid から本を開いた場合は保存済み読書位置 (続きから) を優先。
        if new_idx.is_none() && deferred.resume_to_last_page {
            new_idx = self.resume_page_for_container();
        }
        if new_idx.is_none() {
            new_idx = self.find_fullscreen_nav_target_filtered(!deferred.resume_slideshow);
        }
        if let Some(new_idx) = new_idx {
            if deferred.from_explicit_open {
                self.fs_open_intent_from_grid = true;
            }
            self.open_fullscreen(new_idx, deferred.history_trigger);
            self.selected = Some(new_idx);
            self.scroll_to_selected = true;
            self.update_last_selected_image();
            if deferred.resume_slideshow {
                self.slideshow_playing = true;
                self.schedule_next_slideshow_from_now();
            }
            DeferredFsOpenOutcome::Opened
        } else {
            DeferredFsOpenOutcome::NoPlayableItem
        }
    }

    /// PDF メタキャッシュ (catalog DB の `pdf_meta` テーブル) を引いて、ヒットすれば
    /// 即座に N セルの placeholder `PdfPage` GridItem を構築して `start_loading_items`
    /// で表示する (= Enter→ページ一覧の体感を瞬時にする)。
    ///
    /// 戻り値: 表示した placeholder の page_count。cache miss / 利用不可なら `None`。
    /// 呼び出し側は `self.pdf_placeholder_count` に保管し、`poll_pdf_enumerate` で
    /// 実 enumerate の結果と照合する (一致なら再構築 skip、不一致なら通常経路で再構築)。
    ///
    /// `has_password` は呼び出し側で計算済みの「保存パスワードがあるか」フラグ。
    /// cache が `password_required=1` のとき、保存パスワードが無い状態で placeholder を
    /// 立てると後で正しくレンダできないので skip する (Codex P1 対応)。
    fn try_apply_pdf_meta_cache(
        &mut self,
        pdf_path: &Path,
        has_saved_password: bool,
    ) -> Option<u32> {
        let filename = pdf_path.file_name()?.to_str()?.to_string();
        let parent = pdf_path.parent()?.to_path_buf();

        // stat は同期 I/O だが ~1ms。catalog open より軽量。
        let meta = std::fs::metadata(pdf_path).ok()?;
        let mtime = meta
            .modified()
            .ok()
            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|d| d.as_secs() as i64)?;
        let file_size = meta.len();

        // 親フォルダの catalog DB を **warm hit 経由のみ** で取得する (review #6 対応)。
        // ここは UI スレッドの「Enter→placeholder 即表示」hot path なので、
        // cold open (PRAGMA + schema init で 5-150ms) を絶対に走らせない。
        // warm miss なら placeholder は出さず通常 enumerate (async) に任せる。
        // 一度 catalog が warm-up された後の 2 回目以降の Enter で初めて
        // placeholder が出る、という degraded UX で許容する。
        let (page_count, password_required) = {
            let catalog = self.peek_warm_catalog(&parent)?;
            catalog
                .get_pdf_meta(&filename, mtime, file_size as i64)
                .ok()??
        };

        // パスワード保護下で開かれたキャッシュは、`pdf_passwords` の **この PDF 固有の**
        // 保存パスワードがある場合だけ trust する (Codex P1 対応: 他 PDF の session
        // パスワードで保護 PDF の placeholder を出すと bypass になる)。
        // **review #10 対応**: negative cache (page_count=0, password_required=true)
        // のときも先にここで弾く。先に page_count==0 を見ると negative cache が miss
        // 扱いになって `maybe_spawn_pdf_meta_catchup` が永久に re-enqueue してしまう。
        if password_required && !has_saved_password {
            crate::logger::log(format!(
                "  pdf meta cache: skip placeholder for password-protected {filename} (no saved password)"
            ));
            return None;
        }

        if page_count == 0 {
            return None;
        }

        // ── placeholder grid 構築 ──
        let mut items: Vec<GridItem> = Vec::with_capacity(page_count as usize);
        let mut image_metas: Vec<Option<(i64, i64)>> = Vec::with_capacity(page_count as usize);
        let mut existing_keys: std::collections::HashSet<String> =
            std::collections::HashSet::with_capacity(page_count as usize);
        for i in 0..page_count {
            items.push(GridItem::PdfPage {
                pdf_path: pdf_path.to_path_buf(),
                page_num: i,
                content_type: None, // 実際の render 時に解析
            });
            image_metas.push(Some((mtime, file_size as i64)));
            existing_keys.insert(crate::grid_item::pdf_page_cache_key(i));
        }

        crate::logger::log(format!(
            "  pdf meta cache hit: {filename} page_count={page_count} (instant placeholder)"
        ));

        self.start_loading_items(
            pdf_path.to_path_buf(),
            items,
            image_metas,
            existing_keys,
            Vec::new(),
            None,
        );

        Some(page_count)
    }

    /// PDF ページ列挙の非同期応答をポーリングする。
    /// 毎フレーム `update()` から呼び出す。
    pub(crate) fn poll_pdf_enumerate(&mut self) {
        let Some((ref pdf_path, _, ref handle)) = self.pdf_enumerate_pending else {
            return;
        };

        // Generation guard: cancel が立っている pending の結果は破棄する。
        // load_pdf_as_folder は旧 pending を置き換える (= Drop で cancel) ため通常は
        // ここに None で到達するが、将来 pending を cancel 後に再利用する経路が
        // 追加されても古い結果を適用しないための念押し。
        if handle.cancel.load(Ordering::Relaxed) {
            self.pdf_enumerate_pending = None;
            // cancel された pending では deferred fullscreen reopen も不成立。
            // 放置すると `shortcuts_blocked_by_text_input` / `embedded_fs_pending` /
            // `poll_fs_nav_lock` の defer 経路がフラグを見て永続的に grid を抑止する
            // (= UI フリーズに見える)。明示的に破棄する。
            self.fs_nav_after_pdf_enumerate = None;
            self.release_fs_nav_lock();
            return;
        }

        let result = match handle.rx.try_recv() {
            Ok(r) => r,
            Err(mpsc::TryRecvError::Empty) => return, // まだ結果が来ていない
            Err(mpsc::TryRecvError::Disconnected) => {
                // ワーカーが切断 (通常起きない)
                crate::logger::log("  pdf enumerate: worker disconnected");
                let path = pdf_path.clone();
                self.pdf_enumerate_pending = None;
                self.fs_nav_after_pdf_enumerate = None;
                self.pdf_placeholder_count = None;
                self.start_loading_items(
                    path,
                    Vec::new(),
                    Vec::new(),
                    std::collections::HashSet::new(),
                    Vec::new(),
                    None,
                );
                return;
            }
        };

        let (pdf_path, password, _handle) = self.pdf_enumerate_pending.take().unwrap();

        // cancel 経由の Interrupted は late-arriving な stale 結果なので適用しない
        // (pool dispatcher が cancel を見て IPC 前に Err で返してくるパス)
        if let Err(ref e) = result {
            if e.kind() == std::io::ErrorKind::Interrupted {
                crate::logger::log(format!(
                    "  pdf enumerate: cancelled result dropped for {}",
                    pdf_path.display()
                ));
                // cancel 経路でもフルスクリーン復帰はもう起きないので defer フラグを破棄する。
                // 残すと grid 抑止 / holdover 維持が永続化して UI フリーズに見える。
                self.fs_nav_after_pdf_enumerate = None;
                self.release_fs_nav_lock();
                return;
            }
        }

        match result {
            Ok(pages) => {
                let actual_count = pages.len() as u32;
                crate::logger::log(format!("  pdf: {actual_count} pages"));
                self.pdf_current_password = password.clone();

                // ── パスワード保存 (placeholder hit/miss 共通の tail 処理) ──
                // パスワードダイアログで「保存する」を ON にして OK した場合、
                // enumerate 成功時点で DPAPI に保存する。
                //
                // **pdf_meta の書き込みより先**に実行 (Codex P1 follow-up 対応):
                // 後だと、ダイアログ入力直後の retry で `pdf_passwords` に新パスワードが
                // 入る前に password_required=false で書かれてしまい、次回起動時に
                // cache hit & placeholder 表示でページ数が露出する。
                if let Some((save_path, pw)) = self.pdf_password_pending_save.take() {
                    if save_path == pdf_path {
                        self.pdf_passwords.set(&save_path, &pw);
                        self.pdf_passwords.save();
                        self.invalidate_details_pdf_page_count(&save_path);
                    }
                }

                // ── PDF メタキャッシュ (v1.0.0) への書き込み ──
                // 確定 page_count を親フォルダ catalog DB に保存。`password_required`
                // 列の決定ルール (Codex P1/P2 follow-up 対応):
                //
                //   1. **保存パスワード有 (この PDF 固有、上の pending_save 消化済み含む)**
                //      → `set_pdf_meta` で true 書く (saved password が必要だった = 確信)
                //   2. **password=None で enumerate 成功**
                //      → `set_pdf_meta` で false 書く (パスワード不要 = 確信)
                //   3. **password=Some だが保存パスワード無し (= session-level の暫定 pw、
                //      もしくはダイアログ入力で「保存しない」を選んだ未確定パスワード)**
                //      → `set_pdf_meta_thumb` (**UPDATE only**) で書く。**新規行は作らない**。
                //      新規行を false で作ると、保護 PDF を保存なしパスワードで開いた
                //      ケースが永久に「非保護」記録されて次回 placeholder で page 数が
                //      露出する bypass になる。次回 enumerate で確信値が取れた時に
                //      新規行が初めて作成される。
                let saved_pw_now = self.pdf_passwords.get(&pdf_path).is_some();
                let session_only = password.is_some() && !saved_pw_now;
                if let (Some(parent), Some(filename), Some(page0)) = (
                    pdf_path.parent().map(|p| p.to_path_buf()),
                    pdf_path
                        .file_name()
                        .and_then(|n| n.to_str())
                        .map(|s| s.to_string()),
                    pages.first(),
                ) {
                    let page0_mtime = page0.mtime;
                    let page0_size = page0.file_size as i64;
                    // 親フォルダ catalog は LRU 経由で取得 (Codex P2)
                    if let Some(cat) = self.get_or_open_catalog(&parent) {
                        let result = if session_only {
                            cat.set_pdf_meta_thumb(&filename, page0_mtime, page0_size, actual_count)
                        } else {
                            cat.set_pdf_meta(
                                &filename,
                                page0_mtime,
                                page0_size,
                                actual_count,
                                saved_pw_now,
                            )
                        };
                        if let Err(e) = result {
                            crate::logger::log(format!(
                                "  pdf meta cache: set failed for {filename}: {e}"
                            ));
                        }
                    }
                }

                // ── placeholder grid との照合 (Codex P1-2 対応) ──
                // cache hit で N セル placeholder を立てていた場合、実 enumerate の
                // page_count と一致するか確認。完全一致なら grid 再構築は skip して
                // Ctrl+↑↓ deferred fullscreen 等の tail 処理だけ実行する。
                let placeholder_count = self.pdf_placeholder_count.take();
                let need_rebuild = match placeholder_count {
                    Some(n) if n == actual_count => {
                        crate::logger::log(format!(
                            "  pdf meta cache verified: count={actual_count} (no grid rebuild)"
                        ));
                        false
                    }
                    Some(n) => {
                        crate::logger::log(format!(
                            "  pdf meta cache mismatch: cached={n} actual={actual_count} for {} (rebuilding grid)",
                            pdf_path.display()
                        ));
                        true
                    }
                    None => true, // cache miss / placeholder 未作成
                };

                if need_rebuild {
                    let mut items: Vec<GridItem> = Vec::new();
                    let mut image_metas: Vec<Option<(i64, i64)>> = Vec::new();
                    let mut existing_keys: std::collections::HashSet<String> =
                        std::collections::HashSet::new();

                    for page in &pages {
                        let key = crate::grid_item::pdf_page_cache_key(page.page_num);
                        existing_keys.insert(key);
                        items.push(GridItem::PdfPage {
                            pdf_path: pdf_path.clone(),
                            page_num: page.page_num,
                            content_type: None, // render 時に解析
                        });
                        image_metas.push(Some((page.mtime, page.file_size as i64)));
                    }

                    self.start_loading_items(
                        pdf_path.clone(),
                        items,
                        image_metas,
                        existing_keys,
                        Vec::new(),
                        None,
                    );
                }

                // Ctrl+↑↓ フォルダナビから遷移してきた場合はここで fullscreen を開き直す。
                // placeholder hit/miss 問わず必ず実行する (Codex P1-2)。
                if let Some(deferred) = self.fs_nav_after_pdf_enumerate.take() {
                    self.open_deferred_fullscreen_after_enumerate(deferred);
                }
            }
            Err(e) => {
                let err_msg = format!("{e}");
                // パスワードエラーかどうかを判定 (エラーメッセージに "Password" が含まれる)
                if err_msg.contains("Password") || err_msg.contains("password") {
                    // 誤ったパスワードを DPAPI/セッションキャッシュに保存していた場合は破棄し、
                    // ユーザーに再入力してもらう。DPAPI も破棄しないと、次の load_pdf_as_folder が
                    // また stale を拾って無限ループになる。
                    self.pdf_password_pending_save = None;
                    if password.is_some() {
                        self.pdf_current_password = None;
                        self.pdf_passwords.remove(&pdf_path);
                        self.pdf_passwords.save();
                        self.invalidate_details_pdf_page_count(&pdf_path);
                    }
                    self.prepare_deferred_reopen_for_pdf_password_prompt();
                    // PDF メタキャッシュで placeholder grid を立てていた場合、レンダ
                    // できない N セルがそのまま残るので空に戻す (Codex P1 対応)。
                    // 空に戻すと render_grid の中央表示が「表示するファイルがありません」
                    // になりつつ、パスワードダイアログがその上に出る。
                    if self.pdf_placeholder_count.take().is_some() {
                        self.start_loading_items(
                            pdf_path.clone(),
                            Vec::new(),
                            Vec::new(),
                            std::collections::HashSet::new(),
                            Vec::new(),
                            None,
                        );
                    }
                    self.pdf_password_request = Some(PdfPasswordRequest { path: pdf_path });
                    self.show_pdf_password_dialog = true;
                    self.pdf_password_input.clear();
                    // password が渡されていた = 入力済みのパスワードが誤っていた
                    self.pdf_password_error = if password.is_some() {
                        Some("パスワードが正しくありません".to_string())
                    } else {
                        None
                    };
                    self.pdf_password_save = false;
                    return;
                }
                // その他の失敗: deferred 意図と placeholder count をクリアして
                // グリッド表示にフォールバック
                self.fs_nav_after_pdf_enumerate = None;
                self.pdf_placeholder_count = None;
                crate::logger::log(format!("  pdf enumerate failed: {e}"));
                self.start_loading_items(
                    pdf_path,
                    Vec::new(),
                    Vec::new(),
                    std::collections::HashSet::new(),
                    Vec::new(),
                    None,
                );
            }
        }
    }

    fn prepare_deferred_reopen_for_pdf_password_prompt(&mut self) {
        let preserve_reopen = self
            .fs_nav_after_pdf_enumerate
            .as_ref()
            .is_some_and(|deferred| deferred.preserve_after_password_prompt);
        if !preserve_reopen {
            // Ctrl+↑↓ 由来の deferred fullscreen 意図は破棄する
            // (パスワード入力後に再び fullscreen にしたければユーザーが手動で開く)。
            self.fs_nav_after_pdf_enumerate = None;
        }
        // パスワード保護 PDF + placeholder 無しの場合、`load_pdf_as_folder`
        // 経路では `items_generation` が進んでいないため、`poll_fs_nav_lock`
        // が `items_generation <= locked_gen` で永久にロック解除しない
        // (= holdover が居座る)。明示オープン由来の reopen は残す場合でも、
        // パスワード入力中の nav lock はここで解放する。
        self.release_fs_nav_lock();
    }

    pub(crate) fn pdf_password_dialog_path(&self) -> Option<PathBuf> {
        #[cfg(windows)]
        if let Some(path) = self
            .active_detached_viewer_context
            .as_ref()
            .and_then(|active| active.bundle.pdf_password_request.as_ref())
            .map(|request| request.path.clone())
        {
            return Some(path);
        }
        self.pdf_password_request
            .as_ref()
            .map(|request| request.path.clone())
    }

    pub(crate) fn pdf_password_request_pending_in_any_context(&self) -> bool {
        if self.pdf_password_request.is_some() {
            return true;
        }
        #[cfg(windows)]
        {
            return self
                .active_detached_viewer_context
                .as_ref()
                .is_some_and(|active| active.bundle.pdf_password_request.is_some());
        }
        #[cfg(not(windows))]
        false
    }

    fn retry_pdf_password_request_in_mounted_context(
        &mut self,
        password: String,
        save: bool,
    ) -> bool {
        let Some(request) = self.pdf_password_request.take() else {
            return false;
        };
        self.pdf_current_password = Some(password.clone());
        self.pdf_password_pending_save = save.then(|| (request.path.clone(), password));
        self.load_pdf_as_folder(request.path);
        true
    }

    pub(crate) fn retry_pdf_password_dialog_request(
        &mut self,
        password: String,
        save: bool,
    ) -> bool {
        #[cfg(windows)]
        if self
            .active_detached_viewer_context
            .as_ref()
            .is_some_and(|active| active.bundle.pdf_password_request.is_some())
        {
            return self
                .with_active_detached_viewer_context(|app| {
                    app.retry_pdf_password_request_in_mounted_context(password, save)
                })
                .unwrap_or(false);
        }
        self.retry_pdf_password_request_in_mounted_context(password, save)
    }

    fn cancel_pdf_password_request_in_mounted_context(&mut self) -> bool {
        if self.pdf_password_request.take().is_none() {
            return false;
        }
        self.pdf_password_pending_save = None;
        self.fs_nav_after_pdf_enumerate = None;
        self.release_fs_nav_lock();
        self.restore_rating_filter_suppression();
        true
    }

    pub(crate) fn cancel_pdf_password_dialog_request(&mut self) -> bool {
        #[cfg(windows)]
        if self
            .active_detached_viewer_context
            .as_ref()
            .is_some_and(|active| active.bundle.pdf_password_request.is_some())
        {
            return self
                .with_active_detached_viewer_context(|app| {
                    app.cancel_pdf_password_request_in_mounted_context()
                })
                .unwrap_or(false);
        }
        self.cancel_pdf_password_request_in_mounted_context()
    }

    /// load_folder と load_zip_as_folder の共通処理。
    /// PDF / ZIP を仮想フォルダとして開いた直後の seed + write-back ターゲット設定 +
    /// PDFium prefetch grace 設定をまとめて行う。
    ///
    /// 背景:
    /// - 親フォルダのグリッド表示中に PdfFile/ZipFile のサムネは
    ///   親 catalog の `pdfthumb:foo.pdf` / `zipthumb:foo.zip` キーに保存される。
    /// - 仮想 catalog (PDF/ZIP path で別 SQLite) は別で `page_0000` / 最初の
    ///   エントリ name キーを使う。
    /// - 二つの catalog は独立しているので、毎回同じ画像を 2 回生成していた
    ///   (PDF は PDFium 経由 200-500ms)。
    ///
    /// この関数は 3 つの方向で対策する:
    /// 1. **seed**: 親 catalog にエントリがあれば仮想 catalog にコピー (= 再生成回避)。
    ///    既に grid を経由していたケースは即時ヒット。
    /// 2. **writeback ターゲット設定**: 仮想 catalog 側で worker が page_0000 を
    ///    完成させた後、`poll_thumbnails` の finalize で親 catalog にもミラー書き込み。
    ///    grid を経由しないルート (= Ctrl+↑↓ で直接 PDF を開く流れ) では、初回の
    ///    PDFium レンダリングコストは取り戻せないが、2 回目以降の同じフォルダ進入で
    ///    seed 経路がヒットするようになる。
    /// 3. **prefetch grace**: PDF を開いた直後 100ms は prefetch を抑止して、
    ///    Ctrl+↑↓ 連打の最中に PDFium プールが「破棄される予定の prefetch render」
    ///    で詰まらないようにする。ユーザーがその場で停止したらそこから prefetch 開始。
    fn setup_virtual_folder_seed_and_writeback(
        &mut self,
        source_path: &Path,
        target_db: &crate::catalog::CatalogDb,
        cache_map: &Arc<
            std::sync::RwLock<std::collections::HashMap<String, crate::catalog::CacheEntry>>,
        >,
    ) {
        let ext = source_path
            .extension()
            .and_then(|e| e.to_str())
            .map(|s| s.to_ascii_lowercase());
        let (parent_prefix, target_key, target_idx, is_pdf) = match ext.as_deref() {
            Some("pdf") => {
                // 最初の PdfPage の idx (通常 0)。
                let Some(target_idx) = self
                    .items
                    .iter()
                    .position(|it| matches!(it, GridItem::PdfPage { page_num: 0, .. }))
                else {
                    return;
                };
                (
                    crate::thumb_loader::CACHE_KEY_PDF,
                    crate::grid_item::pdf_page_cache_key(0),
                    target_idx,
                    true,
                )
            }
            Some("zip") | Some("cbz") => {
                let Some((target_idx, entry_name)) =
                    self.items.iter().enumerate().find_map(|(i, it)| match it {
                        GridItem::ZipImage { entry_name, .. } => Some((i, entry_name.clone())),
                        _ => None,
                    })
                else {
                    return;
                };
                (
                    crate::thumb_loader::CACHE_KEY_ZIP,
                    entry_name,
                    target_idx,
                    false,
                )
            }
            _ => return,
        };

        // PDF/ZIP 開いた直後の prefetch 抑制 (= worker thrash 防止) を仕掛ける。
        // PDF だけに適用 (ZIP は decode が軽いので大した負荷にならない)。
        if is_pdf {
            self.pdf_prefetch_grace_until =
                Some(std::time::Instant::now() + std::time::Duration::from_millis(100));
        }

        let Some(parent) = source_path.parent() else {
            return;
        };
        let Some(fname) = source_path.file_name().and_then(|n| n.to_str()) else {
            return;
        };
        let parent_key = format!("{parent_prefix}{fname}");
        let Some(parent_db) = self.get_or_open_catalog(parent) else {
            return;
        };

        // ── seed 経路 ──────────────────────────────────────────────
        // 仮想 catalog 側に既にあれば何もしない (再 seed 不要)。
        let already_in_virtual = cache_map
            .read()
            .map(|m| m.contains_key(&target_key))
            .unwrap_or(false);
        let parent_entry = if !already_in_virtual {
            parent_db.load_one(&parent_key).ok().flatten()
        } else {
            None
        };
        if let Some(entry) = parent_entry {
            // ヘッダのみで寸法を取り、target_db に書き込み。
            // バイト列が壊れていた (= save_thumb_bytes が false 返却) ケースでは
            // cache_map にも入れない — 入れるとサムネ表示時にデコード失敗で
            // `Failed` 状態に陥る (Codex P2)。
            // SQLite I/O エラーは Ok(false) と区別してログに残す (= 静かに丸めると
            // disk full / lock 競合の調査が困難になるため)。
            let saved = match target_db.save_thumb_bytes(
                &target_key,
                entry.mtime,
                entry.file_size,
                entry.source_dims,
                &entry.jpeg_data,
            ) {
                Ok(b) => b,
                Err(e) => {
                    crate::logger::log(format!(
                        "seed virtual folder: save_thumb_bytes failed for {target_key}: {e}"
                    ));
                    false
                }
            };
            if saved {
                if let Ok(mut m) = cache_map.write() {
                    m.insert(target_key.clone(), entry);
                }
                crate::perf::event("nav", "virtual_seed_hit", Some(&parent_key), 0, &[]);
            } else {
                crate::perf::event("nav", "virtual_seed_undecodable", Some(&parent_key), 0, &[]);
            }
        } else if !already_in_virtual {
            crate::perf::event("nav", "virtual_seed_miss", Some(&parent_key), 0, &[]);
        }

        // ── writeback ターゲット設定 ──────────────────────────────
        // 親エントリの mtime / size を取得 (= PDF/ZIP ファイル本体のメタ)。
        let (entry_mtime, entry_size) = match std::fs::metadata(source_path) {
            Ok(m) => {
                let mt = crate::ui_helpers::mtime_secs(&m);
                let sz = m.len() as i64;
                (mt, sz)
            }
            Err(_) => (0, 0),
        };
        self.virtual_folder_writeback = Some(VirtualFolderWriteback {
            parent_catalog: parent_db,
            parent_key,
            target_key,
            target_idx,
            items_gen: self.items_generation,
            cache_map: Arc::clone(cache_map),
            parent_entry_mtime: entry_mtime,
            parent_entry_size: entry_size,
        });
    }

    /// `poll_thumbnails` の finalize シグナル経路から呼ばれ、
    /// `virtual_folder_writeback` の対象 idx が完成していたら親 catalog にミラー書き込みする。
    /// 一度発火したら writeback を None にして二重書き込みを防ぐ。
    ///
    /// 古い items 世代の writeback が残っていた (= `items_generation` 進行後) 場合は
    /// idx 一致でも発火させずクリアのみする (Codex P2: 別フォルダの親 catalog への
    /// 誤書き込み防止)。
    fn fire_virtual_folder_writeback_if_ready(&mut self, finalized_idx: usize) {
        let Some(wb) = self.virtual_folder_writeback.as_ref() else {
            return;
        };
        if wb.items_gen != self.items_generation {
            self.virtual_folder_writeback = None;
            return;
        }
        if finalized_idx != wb.target_idx {
            return;
        }
        // cache_map から WebP データを取り出す (worker が直前に書き込んでいるはず)。
        // RwLock の read guard を save() 越しに保持しないために clone する
        // (save 中はファイル I/O で blocking、guard 保持は他スレッドの読み書きを止める)。
        // None なら from_cache 経路 (cache hit で finalize 不発) など、worker が
        // cache_map にエントリを残さなかったケース。再発火させても効果がないので
        // 1 回試してクリアする (Codex P2: 失敗で stale 残置を防ぐ)。
        let entry_opt = wb
            .cache_map
            .read()
            .ok()
            .and_then(|m| m.get(&wb.target_key).cloned());
        if let Some(entry) = entry_opt {
            let parent_key = wb.parent_key.clone();
            let _ = wb.parent_catalog.save_thumb_bytes(
                &parent_key,
                wb.parent_entry_mtime,
                wb.parent_entry_size,
                entry.source_dims,
                &entry.jpeg_data,
            );
            crate::perf::event("nav", "virtual_writeback", Some(&parent_key), 0, &[]);
        }
        self.virtual_folder_writeback = None;
    }

    /// `catalog_cache` の全エントリを drop し、SQLite Connection を閉じる。
    /// キャッシュマネージャの「削除」操作 (DeleteOld / DeleteAll / DeleteFolder)
    /// 呼び出し前に必須。Windows では Connection が握っている `.db` ファイルは
    /// `remove_file` で削除できず silent fail するので、削除前に Connection を
    /// 全部畳む必要がある (Codex P3)。LRU が小さいので評価コストは無視可能。
    pub(crate) fn evict_all_catalog_cache(&mut self) {
        self.catalog_cache.clear();
        self.catalog_cache_order.clear();
    }

    /// `catalog_cache` から `Arc<CatalogDb>` を取得し、無ければ open して挿入する。
    /// LRU 最大 16 件、超過時は FIFO で古いものから drop (= SQLite Connection close)。
    /// `start_loading_items` の毎ステップ open を吸収するためのキャッシュ。
    /// open 失敗時は cache に挿入せず None を返す (次回も open を再試行)。
    /// LRU から warm hit だけ返す。miss でも `CatalogDb::open` を発火させない
    /// (review #6 対応)。UI スレッドから placeholder 体感向上のために呼ぶ経路は
    /// この warm-only API を使い、cold open が必要な経路は通常の
    /// `get_or_open_catalog` を別経路 / worker で呼ぶ。
    pub(crate) fn peek_warm_catalog(
        &mut self,
        folder_path: &Path,
    ) -> Option<Arc<crate::catalog::CatalogDb>> {
        if self.catalog_cache.contains_key(folder_path) {
            if let Some(pos) = self
                .catalog_cache_order
                .iter()
                .position(|p| p == folder_path)
            {
                let key = self.catalog_cache_order.remove(pos).unwrap();
                self.catalog_cache_order.push_back(key);
            }
            return self.catalog_cache.get(folder_path).cloned();
        }
        None
    }

    pub(crate) fn get_or_open_catalog(
        &mut self,
        folder_path: &Path,
    ) -> Option<Arc<crate::catalog::CatalogDb>> {
        const MAX_CACHED: usize = 16;
        // hit: LRU 末尾に移動して返す。
        if let Some(arc) = self.peek_warm_catalog(folder_path) {
            return Some(arc);
        }
        // miss: open + insert。失敗時は cache を汚さない。
        let cache_dir = crate::catalog::default_cache_dir();
        let catalog = match crate::catalog::CatalogDb::open(&cache_dir, folder_path) {
            Ok(c) => Arc::new(c),
            Err(e) => {
                crate::logger::log(format!("  catalog open failed: {e}"));
                return None;
            }
        };
        // 容量超過なら最古を evict (Arc が外部で保持されていなければ Connection が close)。
        while self.catalog_cache_order.len() >= MAX_CACHED {
            if let Some(oldest) = self.catalog_cache_order.pop_front() {
                self.catalog_cache.remove(&oldest);
            } else {
                break;
            }
        }
        let key: PathBuf = folder_path.to_path_buf();
        self.catalog_cache.insert(key.clone(), Arc::clone(&catalog));
        self.catalog_cache_order.push_back(key);
        Some(catalog)
    }

    /// Register a catalog opened by a background prepare worker without performing any file or
    /// SQLite I/O on the UI thread.  This mirrors the LRU insertion half of
    /// `get_or_open_catalog` and is used by large aggregate views.
    fn cache_preopened_catalog(
        &mut self,
        folder_path: &Path,
        catalog: Arc<crate::catalog::CatalogDb>,
    ) {
        const MAX_CACHED: usize = 16;
        if let Some(pos) = self
            .catalog_cache_order
            .iter()
            .position(|path| crate::folder_tree::path_eq(path, folder_path))
        {
            self.catalog_cache_order.remove(pos);
        }
        while self.catalog_cache_order.len() >= MAX_CACHED {
            if let Some(oldest) = self.catalog_cache_order.pop_front() {
                self.catalog_cache.remove(&oldest);
            } else {
                break;
            }
        }
        let key = folder_path.to_path_buf();
        self.catalog_cache.insert(key.clone(), catalog);
        self.catalog_cache_order.push_back(key);
    }

    ///
    /// 与えられた `items` / `image_metas` を新しい状態として設定し、
    /// 旧タスクをキャンセル → カタログを開く → 永続ワーカー + 動画スレッドを起動 →
    /// 履歴復元 → last_folder 保存 までを行う。
    pub(crate) fn start_loading_items(
        &mut self,
        source_path: PathBuf,
        items: Vec<GridItem>,
        image_metas: Vec<Option<(i64, i64)>>,
        catalog_existing_keys: std::collections::HashSet<String>,
        video_items: Vec<(usize, PathBuf, u64)>,
        folder_signature: Option<u64>,
    ) {
        self.start_loading_items_inner(
            source_path,
            items,
            image_metas,
            catalog_existing_keys,
            video_items,
            folder_signature,
            None,
        );
    }

    pub(crate) fn start_loading_subfolder_items(
        &mut self,
        source_path: PathBuf,
        items: Vec<GridItem>,
        image_metas: Vec<Option<(i64, i64)>>,
        video_items: Vec<(usize, PathBuf, u64)>,
        metadata: subfolder_expansion::PreparedSubfolderMetadata,
    ) {
        self.start_loading_items_inner(
            source_path,
            items,
            image_metas,
            std::collections::HashSet::new(),
            video_items,
            None,
            Some(metadata),
        );
    }

    fn start_loading_items_inner(
        &mut self,
        source_path: PathBuf,
        items: Vec<GridItem>,
        image_metas: Vec<Option<(i64, i64)>>,
        catalog_existing_keys: std::collections::HashSet<String>,
        video_items: Vec<(usize, PathBuf, u64)>,
        folder_signature: Option<u64>,
        mut prepared_subfolder: Option<subfolder_expansion::PreparedSubfolderMetadata>,
    ) {
        let detached_physical = self.navigation_scope.is_detached_physical();
        let preserve_smart_folder_session = !detached_physical
            && !smart_folder::is_smart_folder_synthetic_path(&source_path)
            && self.preserve_smart_folder_session_for_load(&source_path);
        self.cancel_media_navigation_pending_for_current_context("start_loading_items");
        if !detached_physical {
            self.clear_color_filter_for_new_items();
            self.color_filter_scope_refresh_pending = false;
        }
        self.current_color_cache_map = None;
        self.current_color_catalog = None;

        // ネスト ZIP ツリーナビの単一チョークポイント: 別コンテナ (フォルダ/PDF/別 ZIP/
        // 検索結果) への遷移は必ずここを通るので、旧 zip_nav を破棄する。ZIP を開く
        // 経路 (finalize_zip_enumerate) は start_loading_items の **後**で zip_nav を
        // 再設定するので、ここでクリアしても問題ない。階層内ナビ (enter/back) は
        // install_new_items の軽量経路を使い start_loading_items を通らない (= 維持)。
        self.zip_nav = None;
        // ファイル名スタックは「通常フォルダ表示のときだけ ON」のビューモードなので、
        // 任意のコンテナ遷移 (フォルダ/ZIP/PDF/検索結果/タグ/履歴) でここを通るたびに
        // ビュー実体 (`stack_view`) とユーザー意図 (`stack_mode_requested`) の両方を破棄する。
        // 通常フォルダ読込 (`load_folder_with_scan`) だけが、この呼び出しの **後** で
        // 直前の意図に基づき両方を再設定する (= zip_nav を finalize_zip_enumerate が後で
        // 再設定するのと同じパターン)。これにより Ctrl+G 等 SLI を通る経路でも確実に解除され、
        // 同一フォルダ再読込 (ソート変更・メンバー戻り) では hook が復元する。
        self.stack_view = None;
        self.stack_mode_requested = false;
        self.stack_showing_flat = false;
        // 進行中のスタックスクリプトワーカーも破棄 (旧フォルダ向けの結果を適用しない)。
        self.cancel_stack_script_pending();
        if !detached_physical
            && !crate::folder_tree::path_eq(&source_path, &subfolder_expansion_synthetic_path())
        {
            if self.items_are_subfolder_expansion_view {
                // Search/rating/synthetic views own their dedicated restore state. Taking it again
                // here after their first transfer leaves a root-only duplicate. Real-folder
                // navigation keeps the generic history restore; smart-folder install performs an
                // explicit synthetic-to-synthetic transfer at its ownership boundary.
                if !is_synthetic_view_path(&source_path) {
                    let synthetic = subfolder_expansion_synthetic_path();
                    self.folder_nav_subfolder_restore =
                        self.take_subfolder_expansion_restore_for_synthetic_path(Some(&synthetic));
                }
            }
            self.cancel_subfolder_expansion_pending();
            self.clear_subfolder_expansion_view_state();
        }
        if !detached_physical && !smart_folder::is_smart_folder_synthetic_path(&source_path) {
            if self.smart_folder_pending.is_some()
                || self.smart_folder_prepare_pending.is_some()
                || self.smart_folder_confirm_pending.is_some()
            {
                self.cancel_smart_folder_pending();
            }
            if !preserve_smart_folder_session
                && (self.items_are_smart_folder_view
                    || self.top_level_grid_view.smart_folder().is_some())
            {
                self.clear_smart_folder_view_state();
            }
        }
        if !detached_physical {
            self.gamepad_location_picker = None;
        }
        if !detached_physical
            && !crate::folder_tree::path_eq(&source_path, &rating_view_synthetic_path())
        {
            if let Some(pending) = self.rating_view_pending.take() {
                pending.cancel();
            }
        }
        let previous_folder = self.current_folder.clone();
        let previous_archive_source_override = self.archive_source_override.clone();
        let preserve_archive_source_override = previous_archive_source_override.is_some()
            && previous_folder
                .as_ref()
                .is_some_and(|prev| crate::folder_tree::path_eq(prev, &source_path));

        // 通常フォルダ / ZIP / 検索結果など PDF 以外への遷移では、残存する PDF
        // enumerate pending を無効化する。放置すると遅れて届いた結果を
        // `poll_pdf_enumerate` が適用して現在表示を古い PDF 仮想フォルダに戻す。
        // pending.Drop で自動 cancel されるので take するだけでよい。
        if let Some((pending_path, _, _)) = self.pdf_enumerate_pending.as_ref() {
            if pending_path != &source_path {
                self.pdf_enumerate_pending = None;
                self.fs_nav_after_pdf_enumerate = None;
            }
        }
        // ZIP も同様: 別パスへの遷移 (BS で親フォルダ、Ctrl+↑↓ で兄弟フォルダ等) が起きたら、
        // 途中結果で上書き戻されないよう pending を捨てる (Drop で worker cancel)。
        // 同じ zip_path への `start_loading_items` は poll_zip_enumerate 自身が呼ぶので残す。
        if let Some(pending) = self.zip_enumerate_pending.as_ref() {
            if pending.zip_path != source_path {
                self.zip_enumerate_pending = None;
                // PDF 側 (line 6920) と対称: 別パスへ遷移するなら deferred fullscreen
                // reopen も成立しないので defer フラグを破棄する。残すと
                // `shortcuts_blocked_by_text_input` 経由で grid ショートカットが
                // 永続的に効かなくなる。
                self.fs_nav_after_pdf_enumerate = None;
            }
        }

        // 残存する仮想フォルダ writeback / PDF prefetch grace をリセットする (Codex P2)。
        // 前 items に対して仕掛けた writeback は、次に同じ target_idx (通常 0) の finalize
        // が来た瞬間に「全く違う PDF/ZIP の親 catalog」へ書き込みを発火させてしまう。
        // setup_virtual_folder_seed_and_writeback が新フォルダ用に再設定する場合は
        // それが上書きするので問題ない。
        self.virtual_folder_writeback = None;
        self.pdf_prefetch_grace_until = None;
        // フォルダ切替直後は「直前にスクロールしたのと同じ扱い」で prefetch gate を効かせる。
        // None だと `decide_prefetch_allowed` が「未スクロール → 即 allow」と判定して
        // 初フレームから prefetch が pool に流れる。新コンテキストでも visible を優先したいので
        // `Some(now)` で 100ms idle 待ちを生み出す (= 同 1 フレーム内の Ctrl+↑↓ 多段 nav にも効く)。
        // docs/prefetch-suppression-during-scroll-plan.md 1.3 参照。
        if !detached_physical {
            self.last_prefetch_scroll_at = Some(std::time::Instant::now());
            // **Codex P3-2 (2026-05)**: suppression event の transition tracker も新フォルダで
            // リセット。前フォルダ末で allow 状態のまま終わると、新フォルダ初回の Block 遷移が
            // `start` ではなく次の continue tick まで遅れたり、逆も起きる。新コンテキストでは
            // 「未観測」スタートにして初回 frame で確実に start を emit させる。
            self.prev_prefetch_allowed = None;
            self.last_prefetch_suppressed_emit_at = None;
        }

        // perf: start_loading_items 全体 + 内訳 (sidecar_flush / close_fullscreen /
        // state_reset / prewarm_rating / prewarm_tags / rebuild_visible_indices /
        // adjustment_db / mask_db / catalog_open / catalog_load_all /
        // catalog_delete_missing / spawn_workers / settings_save)。
        // UI スレッドブロックの真犯人を特定するため、区間ごとに ms を記録する。
        let sli_t0 = std::time::Instant::now();
        let sli_seq = self.input_seq;
        let items_len = items.len();
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_begin",
                None,
                sli_seq,
                &[("items", serde_json::Value::from(items_len))],
            );
        }

        // ── サイドカーをフラッシュしてメモリから降ろす ──
        // フォルダ切替前に dirty なサイドカーをディスクに書き出す。メモリ上の表現は
        // 破棄して再読み込みに任せる (長時間稼働時のメモリリーク防止)。
        let sidecar_t0 = std::time::Instant::now();
        if !detached_physical {
            self.flush_all_sidecars();
            self.sidecars.clear();
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_sidecar_flush",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(sidecar_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // ── 履歴保存 + 旧タスクキャンセル + 状態リセット ──
        // 退場ビューが検索結果ビュー (Ctrl+G 合成ビュー / Ctrl+S 結果一覧) のときは
        // folder_history (スクロール位置復元用) へ保存しない。Ctrl+G は current_folder を
        // 検索前フォルダのまま保つため、検索ビューの scroll_offset_y をそのフォルダの
        // スクロール状態として記録すると、後で戻ったとき誤った位置に復元される。
        if !detached_physical && let Some(cur) = self.current_folder.clone() {
            let leaving_search_view = self.items_are_global_search_view
                || self.items_are_tag_view
                || self.items_are_reading_history_view
                || self.items_are_bookmark_view
                || self.items_are_rating_view
                || is_synthetic_view_path(&cur);
            let has_grid_state_to_save =
                !self.items.is_empty() || self.selected.is_some() || self.scroll_offset_y != 0.0;
            if !leaving_search_view && has_grid_state_to_save {
                self.folder_history
                    .insert(cur, (self.scroll_offset_y, self.selected));
            }
        }
        #[cfg(windows)]
        let detached_video_preserved = self.promote_active_detached_video_for_main_context_change();
        #[cfg(not(windows))]
        let detached_video_preserved = false;
        #[cfg(windows)]
        if !detached_video_preserved {
            self.preserve_active_detached_image_window_for_main_context_change();
        }
        if !detached_video_preserved {
            self.close_fullscreen();
        }

        // close_fullscreen_end から sli_prewarm_rating までの区間を 3 つに分割して
        // 計測する (nav cancel / items 割当 / キャッシュ clear)。UI が止まる潜在箇所を
        // 特定できるようにするため。
        let cancel_t0 = std::time::Instant::now();
        // 進行中のフォルダナビゲーションをキャンセル
        // (他の経路でフォルダが変更された場合に不要な結果を破棄する)
        if let Some(pending) = self.folder_nav_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        // モード・累積もリセット (新しい load_folder が走る = 連打バースト中断)
        self.clear_pending_folder_nav_steps();

        self.bump_full_context_for_load();
        crate::logger::log("  cancel_token -> true (old tasks will stop)");
        let cancel = Arc::clone(&self.cancel_token);

        let (tx, rx) = mpsc::channel();
        self.tx = tx.clone();
        self.rx = rx;
        crate::perf::emit_ms("nav", "sli_nav_cancel", sli_seq, cancel_t0);

        let assign_t0 = std::time::Instant::now();
        self.current_folder = Some(source_path.clone());
        self.current_folder_rating_cache = None;
        if !detached_physical {
            self.reset_folder_rating_counts();
        }
        // ★フィルタ suppression scope の判定: anchor の subtree 外に出たら復元する。
        // 判定は current_folder 反映直後に行うため、`effective_folder()` が最新値を返す。
        // RAR/7z/LZH キャッシュ ZIP の async enumerate 完了時は、呼び出し元が設定した
        // archive_source_override がまだ生きているため、ユーザー視点の元アーカイブ
        // パスを基準に判定できる。
        if !detached_physical {
            self.maybe_restore_rating_filter_if_out_of_scope();
        }
        // 外部更新の自動反映で使う mtime。ディレクトリ実体のみ (ZIP / PDF / 検索合成は
        // 仮想フォルダなのでファイル追加イベントの対象外)。metadata 失敗時は None のまま。
        self.current_folder_last_mtime = source_path
            .metadata()
            .ok()
            .filter(|m| m.is_dir())
            .and_then(|m| m.modified().ok());
        // mtime が None の経路 (ZIP / PDF / 検索結果) ではシグネチャも持たない:
        // フォーカス復帰の差分判定は `current_folder_last_mtime` の有無でゲートされるため
        // 副次的にシグネチャ比較も無効化される。
        self.current_folder_signature = self
            .current_folder_last_mtime
            .is_some()
            .then_some(folder_signature)
            .flatten();
        if preserve_archive_source_override {
            if let Some(src) = previous_archive_source_override {
                self.address = src.to_string_lossy().to_string();
                self.archive_source_override = Some(src);
            }
        } else {
            self.address = self
                .book_address_label_for_path(&source_path)
                .unwrap_or_else(|| source_path.to_string_lossy().to_string());
            self.archive_source_override = None;
        }
        // Ctrl+G 絞り込みビュー中はブレッドクラム形式を維持する
        // (2026-04 ユーザー報告: PDF 開くと raw パスに戻ってしまうバグ)。
        // no-op: Ctrl+G 非アクティブ / Aggregated 時は何もしない。
        if !detached_physical {
            self.update_global_search_address();
        }
        self.selected = None;
        self.scroll_offset_y = 0.0;
        self.scroll_to_selected = false;
        self.pending_grid_scroll = None;
        self.scroll_hint.store(0, Ordering::Relaxed);

        // `install_new_items_inner` は view flags と `self.items` を差し替えるため、今回の
        // 読み込みが本かどうかは、確定済みの target source/items から先に決める。
        let page_order_view_kind = PageOrderViewKind::for_loading_source(&source_path);
        let spread_restore_defaults =
            if self.page_order_locked_for_items(&source_path, &items, page_order_view_kind) {
                SpreadRestoreDefaults::for_book(&self.settings)
            } else {
                SpreadRestoreDefaults::NON_BOOK
            };
        let has_prepared_aggregate = prepared_subfolder
            .as_ref()
            .is_some_and(|metadata| metadata.aggregate.is_some());
        self.install_new_items_inner(items, image_metas, !has_prepared_aggregate);
        let mut prepared_aggregate = prepared_subfolder
            .as_mut()
            .and_then(|metadata| metadata.aggregate.take());
        if prepared_aggregate.is_none()
            && let Some(folder_pin_map) = prepared_subfolder
                .as_mut()
                .and_then(|metadata| metadata.folder_pin_map.take())
        {
            self.folder_pin_map = folder_pin_map;
        }
        if let Some(metadata) = prepared_aggregate.as_mut() {
            if let Some(pending) = self.converted_archive_cache_paths_pending.take() {
                pending.cancel();
            }
            self.converted_archive_cache_paths =
                std::mem::take(&mut metadata.converted_archive_cache_paths);
            self.folder_pin_map = std::mem::take(&mut metadata.folder_pin_map);
        }
        // 準備 worker が sparse metadata を完成させているため、未登録キーの同期 DB
        // fallback を止めるフラグを prewarm / visible rebuild より先に立てる。
        if prepared_subfolder.is_some() {
            self.items_are_subfolder_expansion_view = true;
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_items_assign",
                None,
                sli_seq,
                &[
                    (
                        "ms",
                        serde_json::Value::from(assign_t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                    ("items", serde_json::Value::from(self.items.len())),
                ],
            );
        }

        let clear_t0 = std::time::Instant::now();
        let texture_backlog_len = self.texture_backlog.len();
        let fs_upload_backlog_len = self.fs_upload_backlog.len();
        self.requested.clear();
        self.pending_finalize.clear();
        self.texture_backlog.clear();
        self.keep_range = (0, 0);
        self.keep_set.clear();
        self.details_hover_thumb_idx = None;
        self.metadata_cache.clear();
        self.exif_cache.clear();
        self.xmp_cache.clear();
        self.xmp_panorama_info.clear();
        self.clear_tags_cache();
        self.checked.clear();
        self.rotation_cache.clear();
        self.rating_cache.clear();
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_cache_clear",
                None,
                sli_seq,
                &[
                    (
                        "ms",
                        serde_json::Value::from(clear_t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                    (
                        "texture_backlog",
                        serde_json::Value::from(texture_backlog_len),
                    ),
                    (
                        "fs_upload_backlog",
                        serde_json::Value::from(fs_upload_backlog_len),
                    ),
                ],
            );
        }
        // 1 回のクエリで全アイテムのレーティングを引いてキャッシュに載せる。
        // これにより rebuild_visible_indices や draw_cell からの初回 get_rating が
        // SQLite を叩かずに済む (大量フォルダで初フレームが詰まるのを防ぐ)。
        let prewarm_rating_t0 = std::time::Instant::now();
        if let Some(prepared) = prepared_subfolder.as_mut() {
            self.rating_cache = std::mem::take(&mut prepared.rating_cache);
        } else {
            self.prewarm_rating_cache();
        }
        // DB prewarm 後、別 context からこのセッション中に書かれた path の最新値を重ねる。
        // 特に明示クリア (DB 行なし) は DB だけでは区別できないため、global 台帳が正本になる。
        self.sync_current_context_rating_session_writes();
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_prewarm_rating",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(prewarm_rating_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }
        // タグバッジ用も同様に tags.db から一括 prewarm。
        // rating と合算すると tags.db 側の退行が見えないので区間を分けて計測する
        // (cold tags.db + 大フォルダで UI スレッド同期クエリが伸びる潜在箇所)。
        let prewarm_tags_t0 = std::time::Instant::now();
        if let Some(prepared) = prepared_subfolder.as_mut() {
            if let Some(pending) = self.tag_prewarm_pending.take() {
                pending.cancel();
            }
            self.tag_prewarm_queued.clear();
            if let Some(pending) = self.tag_legacy_seed_pending.take() {
                pending.cancel();
            }
            self.replace_tags_cache(std::mem::take(&mut prepared.tags_cache));
            if self.settings.write_rating_to_xmp {
                self.tag_prewarm_pending = Some(crate::tag_prewarm::spawn());
            }
            if self.tags_db.is_some() {
                self.tag_legacy_seed_pending = Some(crate::tag_legacy_seed_worker::spawn(
                    crate::data_dir::get(),
                    std::mem::take(&mut prepared.legacy_paths),
                ));
            }
        } else {
            self.prewarm_grid_tags();
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_prewarm_tags",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(prewarm_tags_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }
        let rebuild_t0 = std::time::Instant::now();
        self.rebuild_visible_indices();
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_rebuild_visible_indices",
                None,
                sli_seq,
                &[
                    (
                        "ms",
                        serde_json::Value::from(rebuild_t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                    (
                        "visible",
                        serde_json::Value::from(self.visible_indices.len()),
                    ),
                ],
            );
        }
        // 表示モード: DB から読み込み、なければ読み込み対象が本のときだけ settings の既定値。
        // 本でないビューは単ページ + ページ単位 + 左→右へ戻す。明示保存値はどちらでも優先する。
        // 旧実装の SpreadMode::Vertical は「単ページ + 縦連結」として解釈する。
        // ZIP の場合はここで一旦 zip_path キーで読むが、finalize_zip_enumerate が zip_nav
        // 設定後に「ルート本のキー (zip_path + 実効 prefix)」で読み直す (本ごと独立記憶)。
        self.apply_spread_for_key(&source_path, spread_restore_defaults);
        self.apply_view_trim_for_key(&source_path);
        self.spread_popup_open = false;
        self.fit_popup_open = false;
        self.slideshow_popup_open = false;
        self.continuous_reading_scroll_transition = None;
        self.slideshow_scroll_range_cache = None;
        self.search_filter = None;
        self.search_filter_origin_folder = None;
        if !detached_physical {
            self.search_query.clear();
            // 非同期検索 in-flight があればキャンセル (フォルダ切替で items が変わるため
            // 検索結果インデックスが意味を失う)
            if let Some(pending) = self.search_pending.take() {
                pending.cancel.store(true, Ordering::Relaxed);
            }
        }
        // メタデータ読み込みも idx ベースなのでフォルダ切替時にキャンセル
        if let Some(pending) = self.metadata_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }

        // 画像補正: ページ個別パラメータを DB から復元
        self.adjustment_cache.clear();
        self.thumb_pixels.clear();
        self.passthrough_rendition_cache.clear();
        self.thumb_edit_preview_layers.clear();
        self.thumb_adjust_tex.clear();
        self.thumb_adjust_was_dragging = false;
        self.thumb_adjust_drag_color_dirty = false;
        self.adjustment_page_params.clear();
        self.adjustment_dragging = false;
        self.adjustment_mode = crate::ui_helpers::MetadataPanelOpenState::Closed;
        self.cache_current_edit_preview_if_ready();
        self.local_adjust_mode = false;
        self.export_crop_mode = false;
        self.export_crop_drag = None;
        self.export_crop_create_drag = None;
        self.export_crop_spread_ctx = None;
        self.local_adjust_page_layers.clear();
        self.local_adjust_pages.clear();
        self.export_crop_page_settings.clear();
        self.export_crop_pages.clear();
        self.local_adjust_selected_layers.clear();
        self.local_adjust_add_layer_dialog_open = false;
        self.local_adjust_change_mask_dialog_open = false;
        self.local_adjust_change_mask_keep_manual_override = true;
        self.local_adjust_effect_picker_dialog_open = false;
        self.local_adjust_effect_query.clear();
        self.local_adjust_show_source = false;
        self.local_adjust_show_mask = true;
        self.local_adjust_preview_to_selected_layer = false;
        self.local_adjust_effect_clipboard = None;
        self.local_adjust_rgb_pick_active = None;
        self.local_adjust_repair_point_pick_active = None;
        self.local_adjust_selective_color_pick_active = false;
        self.local_adjust_effect_position_handles_visible = true;
        self.local_adjust_canvas_drag = None;
        self.local_adjust_mask_brush_stroke = None;
        self.local_adjust_mask_lasso_points.clear();
        self.local_adjust_mask_shape_drag_start = None;
        self.local_adjust_mask_shape_drag_end = None;
        self.local_adjust_selected_shape = None;
        self.local_adjust_shape_drag = None;
        self.local_adjust_canvas_drag_before_layers = None;
        self.local_adjust_shape_drag_before_layers = None;
        self.local_adjust_mask_brush_before_layers = None;
        self.local_adjust_brush_deferred_render = None;
        self.local_adjust_generation.clear();
        self.local_adjust_cache.clear();
        self.edit_result_cache.clear();
        self.clear_all_final_pipeline_caches();
        self.cancel_all_local_adjust_pending();
        self.local_adjust_layer_bypass_cache.clear();
        self.local_adjust_prefix_preview_cache.clear();
        self.local_adjust_lut_pending = None;
        self.local_adjust_segmentation_pending = None;
        self.mask_pages.clear();
        self.erase_mask_generation.clear();
        self.conceal_pages.clear();
        self.conceal_mask_generation.clear();
        self.comic_pages.clear();
        self.erase_result_cache.clear();
        self.input_generation.clear();
        self.edit_result_cache.clear();
        self.clear_all_final_pipeline_caches();
        self.cancel_all_erase_inpaint_pending();
        // 360 度パノラマビュー: フォルダ変更で cache 全体が変わったので世代を一斉 bump
        // (§3.6.2.2)。adjustment_generation / ai_upscale_generation の HashMap
        // 自体はクリアしない (キーが残っていても次フォルダで同 source_key が
        // 出てくることは稀だし、値だけ +1 する分には害もない)。
        self.bump_all_adjustment_generations();
        self.bump_all_ai_generations();

        // ── サイドカー → 中央 DB のインポート ──
        // フォルダ丸ごと移動された場合など、中央 DB に無いエントリがサイドカーにあれば
        // 取り込む。DB にあるエントリは authoritative なので上書きしない。
        // 下の `db.load_page_params` はインポート後に走るので、補填されたエントリも拾える。
        let sidecar_import_t0 = std::time::Instant::now();
        if !has_prepared_aggregate
            && (self.settings.sidecar_backup_enabled || self.settings.tag_sidecar_backup_enabled)
        {
            let sidecar_folder = if source_path.is_dir() {
                source_path.clone()
            } else {
                source_path
                    .parent()
                    .map(|p| p.to_path_buf())
                    .unwrap_or_else(|| source_path.clone())
            };
            self.import_sidecar_to_dbs(&sidecar_folder);
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_sidecar_import",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(sidecar_import_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        let adj_t0 = std::time::Instant::now();
        if let Some(metadata) = prepared_aggregate.as_mut() {
            self.adjustment_page_params = std::mem::take(&mut metadata.adjustment_page_params);
        } else if let Some(db) = &self.adjustment_db {
            let prefix = crate::adjustment_db::normalize_path(&source_path);
            let page_map = db.load_page_params(&prefix);
            if !page_map.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if let Some(params) = page_map.get(&key) {
                            self.adjustment_page_params.insert(idx, params.clone());
                        }
                    }
                }
            }
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_adjustment_db",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(adj_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // 補正レイヤー: グリッドではバッジ判定だけに使うため、巨大な JSON 本体は
        // 読まず、現在 items の page key に対応する行の存在だけを復元する。
        // レイヤー配列はフルスクリーン表示 / 補正レイヤーパネルで遅延ロードする。
        let local_adjust_t0 = std::time::Instant::now();
        if let Some(prepared) = prepared_subfolder.as_mut() {
            self.local_adjust_page_layers.clear();
            self.local_adjust_pages = std::mem::take(&mut prepared.local_adjust_pages);
            self.local_adjust_selected_layers.clear();
        } else {
            self.hydrate_local_adjust_layer_keys_for_current_items();
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_local_adjust_db",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(local_adjust_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // 最後段 crop: ページ単位の crop 設定を DB から復元。
        // サムネイル画像には反映せず、フルスクリーン表示 / コピー / エクスポートの
        // 最終段だけで使う。
        let crop_t0 = std::time::Instant::now();
        if let Some(metadata) = prepared_aggregate.as_mut() {
            self.export_crop_page_settings =
                std::mem::take(&mut metadata.export_crop_page_settings);
            self.export_crop_pages = self.export_crop_page_settings.keys().copied().collect();
        } else if let Some(db) = &self.export_crop_db {
            let prefix = crate::adjustment_db::normalize_path(&source_path);
            let page_map = db.load_by_prefix(&prefix);
            if !page_map.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if let Some(settings) = page_map.get(&key) {
                            self.export_crop_page_settings.insert(idx, *settings);
                            self.export_crop_pages.insert(idx);
                        }
                    }
                }
            }
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_export_crop_db",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(crop_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        let view_trim_t0 = std::time::Instant::now();
        if let Some(metadata) = prepared_aggregate.as_mut() {
            self.view_trim_page_overrides = std::mem::take(&mut metadata.view_trim_page_overrides);
        } else {
            self.hydrate_view_trim_page_overrides_for_current_items();
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_view_trim_db",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(view_trim_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // 消しゴムマスク: フォルダ内でマスクを持つページを列挙
        let mask_t0 = std::time::Instant::now();
        if let Some(metadata) = prepared_aggregate.as_mut() {
            self.mask_pages = std::mem::take(&mut metadata.mask_pages);
            self.conceal_pages = std::mem::take(&mut metadata.conceal_pages);
            self.comic_pages = std::mem::take(&mut metadata.comic_pages);
        } else if let Some(db) = &self.mask_db {
            let prefix = crate::adjustment_db::normalize_path(&source_path);
            let mask_keys = db.load_mask_keys(&prefix);
            if !mask_keys.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if mask_keys.contains(&key) {
                            self.mask_pages.insert(idx);
                        }
                    }
                }
            }
        }

        // 隠蔽加工マスク: バッジ用に「マスクを持つページ」を集合化 (mask_db と同様)
        if prepared_aggregate.is_none()
            && let Some(db) = &self.conceal_db
        {
            let prefix = crate::adjustment_db::normalize_path(&source_path);
            let conceal_keys = db.load_conceal_keys(&prefix);
            if !conceal_keys.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if conceal_keys.contains(&key) {
                            self.conceal_pages.insert(idx);
                        }
                    }
                }
            }
        }

        // テキスト注釈 (comic): バッジ用に「注釈を持つページ」を集合化 (mask_db と同様)。
        if prepared_aggregate.is_none()
            && let Some(db) = &self.comic_db
        {
            let prefix = crate::adjustment_db::normalize_path(&source_path);
            let comic_keys = db.load_comic_keys(&prefix);
            if !comic_keys.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if comic_keys.contains(&key) {
                            self.comic_pages.insert(idx);
                        }
                    }
                }
            }
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_mask_db",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(mask_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }
        // visible_indices はアイテム設定後 (下の行) に再計算される

        // ── カタログを開く + cache_map ロード + 削除掃除 ──
        let catalog_open_t0 = std::time::Instant::now();
        let aggregate_catalog_was_prepared = prepared_aggregate.is_some();
        let prepared_catalog = prepared_aggregate
            .as_mut()
            .and_then(|metadata| metadata.catalog.take());
        let catalog_arc = if let Some(prepared) = prepared_catalog.as_ref() {
            self.cache_preopened_catalog(&source_path, Arc::clone(&prepared.db));
            Some(Arc::clone(&prepared.db))
        } else if aggregate_catalog_was_prepared {
            // The aggregate worker already attempted the open. Never retry failed file/SQLite
            // I/O synchronously on the UI thread; thumbnails can run without a catalog.
            None
        } else {
            self.get_or_open_catalog(&source_path)
        };
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_catalog_open",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(catalog_open_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        let catalog_load_t0 = std::time::Instant::now();
        let shared_prepared_entries = prepared_catalog
            .as_ref()
            .and_then(|prepared| prepared.shared_entries.clone());
        let cache_map: Arc<
            std::sync::RwLock<std::collections::HashMap<String, crate::catalog::CacheEntry>>,
        > = shared_prepared_entries.unwrap_or_else(|| {
            Arc::new(std::sync::RwLock::new(match prepared_catalog {
                Some(prepared) => prepared.entries,
                None => catalog_arc
                    .as_ref()
                    .and_then(|c| c.load_all().ok())
                    .unwrap_or_default(),
            }))
        });
        let catalog_entries = cache_map.read().unwrap().len();
        crate::logger::log(format!("  catalog: {catalog_entries} entries in DB"));
        self.current_color_cache_map = Some(Arc::clone(&cache_map));
        self.current_color_catalog = catalog_arc.clone();

        // PDF / ZIP を仮想フォルダとして開いた場合、親フォルダ catalog の
        // pdfthumb: / zipthumb: 先頭サムネを仮想 catalog の page_0000 / 最初の
        // entry name キーに seed する (PDFium 再レンダリング 200-500ms を回避)。
        // 同時に write-back ターゲットを設定して「仮想 catalog で完成した先頭サムネを
        // 親 catalog にミラー保存」する経路も開く (次回親フォルダ表示時の grid サムネ
        // 生成を省略するため)。
        // `pdf_prefetch_grace_until` も初期化して、仮想フォルダ開いた直後の数十 ms は
        // PDFium ワーカーを現ページ専用に空けておく (Ctrl+↑↓ 連打時の thrash 抑制)。
        if let Some(ref cat) = catalog_arc {
            self.setup_virtual_folder_seed_and_writeback(&source_path, cat, &cache_map);
        }
        // Phase C: フォルダピンの source が Video の場合、video_pins DB の抽出済み
        // WebP を folder の pinned cache key (`folderthumb:auto-v...#pin:{source_id}`) で
        // catalog + cache_map にミラーする。これにより worker は pinned_key で
        // cache_hit して動画フレームをそのまま表示できる (= 動画自身を Shell API で
        // 取り直す経路を踏まない)。`catalog_existing_keys` には既に pinned 形式が
        // 含まれているので、直後の delete_missing がこの seed 行を消すことはない。
        if !aggregate_catalog_was_prepared {
            self.seed_folder_video_pin_thumbs(&cache_map, catalog_arc.as_ref());
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_catalog_load_all",
                None,
                sli_seq,
                &[
                    (
                        "ms",
                        serde_json::Value::from(catalog_load_t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                    ("entries", serde_json::Value::from(catalog_entries)),
                ],
            );
        }

        let catalog_del_t0 = std::time::Instant::now();
        if !is_synthetic_view_path(&source_path) {
            if let Some(ref cat) = catalog_arc {
                if let Err(e) = cat.delete_missing(&catalog_existing_keys) {
                    crate::logger::log(format!("  catalog delete_missing failed: {e}"));
                }
            }
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_catalog_delete_missing",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(catalog_del_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // ── auto_aspect: items 世代リセット + catalog 既存比率の seed ──
        // delete_missing 完了後 / spawn_thumbnail_workers 起動前のこの位置で呼ぶ。
        // この時点で self.items / image_metas / cache_map がすべて確定済み。
        self.reset_and_seed_auto_aspect(&cache_map);

        // ── 進捗カウンタリセット + 共有 display_px 更新 ──
        self.cache_gen_total = 0;
        self.cache_gen_done = Arc::new(AtomicUsize::new(0));

        let initial_display_px = compute_display_px(
            self.last_cell_size,
            self.last_cell_h,
            self.last_pixels_per_point,
        );
        self.display_px_shared
            .store(initial_display_px, Ordering::Relaxed);
        crate::logger::log(format!(
            "  display_px = {initial_display_px}  cache_policy = {}",
            self.settings.cache_policy.label()
        ));

        // ── 永続ワーカー + (必要なら) 動画スレッドを起動 ──
        let spawn_t0 = std::time::Instant::now();
        let reload_queue: Arc<NotifyQueue> = Arc::new((Mutex::new(Vec::new()), Condvar::new()));
        let heavy_io_queue: Arc<NotifyQueue> = Arc::new((Mutex::new(Vec::new()), Condvar::new()));
        self.reload_queue = Some(Arc::clone(&reload_queue));
        self.heavy_io_queue = Some(Arc::clone(&heavy_io_queue));

        self.spawn_thumbnail_workers(
            &tx,
            Arc::clone(&cancel),
            reload_queue,
            heavy_io_queue,
            cache_map,
            catalog_arc,
            self.folder_thumb_pin_db.clone(),
        );
        if !video_items.is_empty() {
            // Phase 8.B': ピン留めフレームを path → WebP の map で snapshot し
            // worker thread に渡す (= grid サムネ最優先で使用される)。
            let pin_blobs: std::collections::HashMap<PathBuf, Vec<u8>> =
                if let Some(prepared) = prepared_subfolder.as_mut() {
                    std::mem::take(&mut prepared.video_pin_blobs)
                } else if let Some(db) = self.video_pin_db.as_ref() {
                    video_items
                        .iter()
                        .filter_map(|(_, p, _)| {
                            db.lookup(p)
                                .filter(|pin| !pin.thumb_webp.is_empty())
                                .map(|pin| (p.clone(), pin.thumb_webp))
                        })
                        .collect()
                } else {
                    std::collections::HashMap::new()
                };
            self.spawn_video_thread(
                tx,
                cancel,
                video_items,
                self.video_thumb_overrides.clone(),
                pin_blobs,
            );
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_spawn_workers",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(spawn_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
        }

        // ── 履歴復元 + last_folder 保存 ──
        // `select_after_load` (BS 戻り / 親フォルダボタン / `favsearch_back`) が指定されている
        // ときは履歴より優先する: 深い階層から BS で戻ったとき、最初にフォルダへ入った位置
        // ではなく「今いる位置」にカーソルを合わせるため。指定アイテムが items に見つから
        // なかった場合 (削除等) のみ履歴へフォールバック。
        let history_state = (!detached_physical)
            .then(|| self.folder_history.get(&source_path).copied())
            .flatten();
        let restored = !detached_physical && self.try_select_after_load();
        if restored && let Some((scroll, _)) = history_state {
            // BS / direct-page close は select_after_load で選択対象を更新するが、
            // 視点は戻り先リストでユーザーが見ていたスクロール位置を先に復元する。
            // scroll_to_selected は残し、対象が範囲外になった場合だけ render_grid で補正する。
            self.scroll_offset_y = scroll;
        }
        if !restored {
            if let Some((scroll, sel)) = history_state {
                self.scroll_offset_y = scroll;
                self.selected = sel;
                if sel.is_some() {
                    self.scroll_to_selected = true;
                }
                // 前回保存時は可視だった sel が、現在のフィルタ状態では非可視かもしれない。
                // `rebuild_visible_indices` 時点では selected が None だったので redirect が
                // 走っておらず、ここで再度 redirect して WYSIWYG 不変条件を保つ (Codex P2)。
                self.redirect_selected_to_visible();
            }
        }
        // 同セッション履歴 (folder_history) に位置が無い (= 再起動後の初回など) かつ
        // select_after_load も無い場合、永続化した読書位置 (book_resume_db) をグリッド選択に
        // 復元する (= 再起動を跨いだ「続きから」)。
        if !restored && history_state.is_none() {
            let resume = self
                .book_resume_db
                .as_ref()
                .and_then(|db| db.get(&source_path))
                .filter(|&p| self.is_readable_page_idx(p));
            if let Some(page) = resume {
                self.selected = Some(page);
                self.scroll_to_selected = true;
                self.redirect_selected_to_visible();
            }
        }
        // A freshly loaded grid must not inherit stale idle-upgrade timing from
        // the previous grid. Scroll history has been restored by this point, so
        // restart the quiet window from the restored position.
        if !detached_physical {
            self.last_scroll_offset_y_tracked = self.scroll_offset_y;
            self.last_scroll_change_time = std::time::Instant::now();
        }
        // 検索結果 / 閲覧履歴 / レーティング一覧用の合成パスは last_folder に記録しない (次回起動時に復元しないため)。
        // active detached viewer の PDF / ZIP ページ文脈も、メイン一覧とは独立した一時 context
        // なので last_folder / quick folder settings へ永続化しない。
        let save_t0 = std::time::Instant::now();
        if !is_synthetic_view_path(&source_path)
            && !self.detached_viewer_suppresses_main_history_persistence()
        {
            // 変換アーカイブ (RAR/CBR/7z/LZH) 閲覧中は source_path (= current_folder) が
            // キャッシュ ZIP (`archive_cache\..\book.zip`) を指す。次回起動で復元すべきは
            // 元アーカイブなので、archive_source_override を反映した effective_folder() を
            // 保存する (通常フォルダ / ネイティブ ZIP/PDF では override が無く source_path と
            // 一致するので挙動不変)。recent_folders は open_archive_via_cache が既に元
            // アーカイブを記録済み。
            self.settings.last_folder = Some(self.effective_folder().unwrap_or(source_path));
            self.sync_quick_folder_settings();
            self.settings.save();
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "sli_settings_save",
                None,
                sli_seq,
                &[(
                    "ms",
                    serde_json::Value::from(save_t0.elapsed().as_secs_f64() * 1000.0),
                )],
            );
            crate::perf::event(
                "nav",
                "sli_end",
                None,
                sli_seq,
                &[
                    (
                        "ms",
                        serde_json::Value::from(sli_t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                    ("items", serde_json::Value::from(items_len)),
                ],
            );
        }
    }

    fn set_items_generation(&mut self, items_generation: u64) {
        self.items_generation = items_generation;
        self.fs_cache.set_items_generation(items_generation);
        self.fs_pending.set_items_generation(items_generation);
        self.fs_early_dims.set_items_generation(items_generation);
        self.fs_upload_backlog
            .set_items_generation(items_generation);
    }

    pub(crate) fn bump_items_generation(&mut self) {
        self.set_items_generation(self.items_generation.wrapping_add(1));
    }

    #[cfg(test)]
    fn fs_generation_state_is_current(&self) -> bool {
        self.fs_cache.current_items_generation() == self.items_generation
            && self.fs_pending.current_items_generation() == self.items_generation
            && self.fs_early_dims.current_items_generation() == self.items_generation
            && self.fs_upload_backlog.current_items_generation() == self.items_generation
    }

    /// items / image_metas / thumbnails を新しい並びで差し替え、items_generation を bump する。
    ///
    /// 世代更新と thumbnails の Pending 初期化を 1 箇所に集約するためのヘルパ。
    /// 呼び出し側 (`start_loading_items` / `replace_search_view_items`) はこの後で
    /// セッションの残り (キャッシュ clear 等) を進める。世代 bump を忘れると、旧
    /// ワーカーの ThumbMsg が新 items の同じ idx に適用されてサムネが化ける race
    /// が起きる。
    pub(crate) fn install_new_items(
        &mut self,
        items: Vec<GridItem>,
        image_metas: Vec<Option<(i64, i64)>>,
    ) {
        self.install_new_items_inner(items, image_metas, true);
    }

    fn install_new_items_inner(
        &mut self,
        items: Vec<GridItem>,
        image_metas: Vec<Option<(i64, i64)>>,
        refresh_container_metadata: bool,
    ) {
        debug_assert_eq!(items.len(), image_metas.len());
        self.persist_pending_view_trim_state();
        self.items = items;
        self.image_metas = image_metas;
        self.thumb_edit_preview_keys.clear();
        self.idle_upgrade_cache_bypass_ineligible.clear();
        self.thumbnails = self
            .items
            .iter()
            .map(|item| match item {
                // 音声は固定の音楽アイコンで描画し、サムネイルをロードしない (D2)。
                // Pending のままだと「読み込み中」に数えられて prefetch 抑制や毎フレーム
                // repaint を誘発する (Codex P2)。初期状態を terminal (= 非ロード・非リクエスト)
                // にして「これ以上ロードしない」と扱わせる。grid_paint の Audio アームは
                // thumb 状態を無視してアイコンを描くので見た目に影響はない。
                GridItem::Audio(_) => ThumbnailState::Failed,
                _ => ThumbnailState::Pending,
            })
            .collect();
        self.bump_items_generation();
        self.invalidate_facet_name_cache();
        // 一覧全体の差し替えでは同じ index が別アイテムを指し得るため、クリック範囲選択の
        // 起点を失効させる。Ctrl+G streaming のように内容 identity で追従できる経路だけ、
        // 呼び出し側が旧 key を保存して新世代へ明示的に再マップする。
        self.grid_click_selection_anchor = None;
        self.view_trim_mode = false;
        self.view_trim_page_apply_root_idx = None;
        self.view_trim_page_spread_separate = self.view_trim_book_settings.spread_separate;
        self.view_trim_page_overrides.clear();
        self.view_trim_dirty_page_overrides.clear();
        self.view_trim_save_pending = false;
        if let Some(pending) = self.details_meta_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        self.details_lazy_visible_revision = self.details_lazy_visible_revision.wrapping_add(1);
        self.ai_model_facet_requested = self.facet_ai_filter_active();
        self.details_image_dims_state =
            if self.details_any_lazy_columns_enabled() || self.ai_model_facet_should_load() {
                LazyColumnState::NotRequested
            } else {
                LazyColumnState::Disabled
            };
        // 既定は「実ビュー」。`replace_search_view_items` (= 合成ビュー経路) は
        // この後で true に上書きする。
        self.items_are_global_search_view = false;
        self.items_are_tag_view = false;
        self.items_are_reading_history_view = false;
        self.items_are_bookmark_view = false;
        self.items_are_rating_view = false;
        self.items_are_subfolder_expansion_view = false;
        self.items_are_smart_folder_view = false;
        self.items_are_drive_list = false;
        self.reading_history_rows.clear();
        // 親コンテナ (Folder/ZipFile/PdfFile/ConvertibleArchive) のピン情報を 1 度の lookup_many で取得し、
        // make_load_request からの per-frame DB ヒットを回避する。pin がレアケースで
        // 大半は empty なので、典型的なフォルダで HashMap は数百 bytes に収まる。
        if refresh_container_metadata {
            self.start_converted_archive_cache_paths_refresh();
            self.refresh_folder_pin_map();
        } else {
            if let Some(pending) = self.converted_archive_cache_paths_pending.take() {
                pending.cancel();
            }
            self.converted_archive_cache_paths.clear();
            self.folder_pin_map.clear();
        }
    }

    /// 現在 items の変換アーカイブについて、有効な変換キャッシュ ZIP を
    /// `make_load_request` から同期参照できる map にまとめる。
    ///
    /// SQLite `peek` と cache ZIP の `exists()` は worker で行い、UI スレッドは
    /// 現在の items から `(path, mtime, size)` を snapshot するだけにする。スクロール中 /
    /// 毎フレームのサムネ要求で archive_cache.db を叩かないための小さなキャッシュ。
    /// 親フォルダ上の `ConvertibleArchive` セルに加え、レーティング一覧に復元された
    /// `ZipDir` が元 RAR/7z/LZH パスを持つケースもここで解決する。
    fn start_converted_archive_cache_paths_refresh(&mut self) {
        if let Some(pending) = self.converted_archive_cache_paths_pending.take() {
            pending.cancel();
        }
        self.converted_archive_cache_paths.clear();
        // サブ展開は Image / Video / Folder / ZipFile / PdfFile だけで、ConvertibleArchive は
        // 取り込まない。数百万件を判定しても必ず空なので synthetic path で即終了する。
        if self.current_folder.as_ref().is_some_and(|folder| {
            crate::folder_tree::path_eq(folder, &subfolder_expansion_synthetic_path())
        }) {
            return;
        }
        let Some(db) = self.archive_cache_db.clone() else {
            return;
        };
        let inputs: Vec<(PathBuf, i64, i64)> = self
            .items
            .iter()
            .enumerate()
            .filter_map(|(idx, item)| {
                let path = match item {
                    GridItem::ConvertibleArchive { path, .. } => path,
                    GridItem::ZipDir { zip_path, .. }
                        if zip_path
                            .extension()
                            .and_then(|ext| ext.to_str())
                            .and_then(crate::archive_converter::ArchiveFormat::from_extension)
                            .is_some() =>
                    {
                        zip_path
                    }
                    _ => return None,
                };
                let (mtime, file_size) = self.image_metas.get(idx).and_then(|m| *m)?;
                Some((path.clone(), mtime, file_size))
            })
            .collect();
        if inputs.is_empty() {
            return;
        }

        let generation = self.items_generation;
        let input_seq = self.input_seq;
        let cancel = Arc::new(AtomicBool::new(false));
        let worker_cancel = Arc::clone(&cancel);
        let (tx, rx) = mpsc::channel();
        let spawn_result = std::thread::Builder::new()
            .name("archive-cache-peek".to_string())
            .spawn(move || {
                let t0 = std::time::Instant::now();
                let mut paths = std::collections::HashMap::new();
                let mut peeked = 0usize;
                let mut hits = 0usize;
                for (path, mtime, file_size) in inputs {
                    if worker_cancel.load(Ordering::Relaxed) {
                        return;
                    }
                    peeked += 1;
                    let mut cache_src = path.clone();
                    let mut cache_mtime = mtime;
                    let mut cache_file_size = file_size;
                    if crate::rar_loader::is_rar_path(&path) {
                        match crate::rar_loader::inspect_for_direct_read(&path) {
                            Ok(inspection)
                                if inspection.decision
                                    == crate::rar_loader::RarDirectReadDecision::Direct =>
                            {
                                hits += 1;
                                paths.insert(
                                    crate::path_key::normalize_keep_drive(&path),
                                    inspection.resolved_path,
                                );
                                continue;
                            }
                            Ok(inspection) => {
                                // A visible subsequent volume represents the same logical book as
                                // its first volume. Cache lookup and thumbnail loading therefore use
                                // the header-resolved first path while the grid cell keeps the exact
                                // file the user can manage via shell operations.
                                cache_src = inspection.resolved_path;
                                if let Ok(metadata) = std::fs::metadata(&cache_src) {
                                    cache_mtime = crate::ui_helpers::mtime_secs(&metadata);
                                    cache_file_size = metadata.len() as i64;
                                }
                            }
                            Err(_) => {}
                        }
                    }
                    // peek = 読み取り専用 lookup。フォルダを表示しただけで全アーカイブに
                    // last_access UPDATE (書き込みトランザクション) を発行しない。
                    if let Some(cached_zip) = db.peek(&cache_src, cache_mtime, cache_file_size) {
                        if worker_cancel.load(Ordering::Relaxed) {
                            return;
                        }
                        hits += 1;
                        paths.insert(crate::path_key::normalize_keep_drive(&path), cached_zip);
                    }
                }
                if !worker_cancel.load(Ordering::Relaxed) {
                    let _ = tx.send(ConvertedArchiveCachePathsResult {
                        paths,
                        peeked,
                        hits,
                        elapsed_ms: t0.elapsed().as_secs_f64() * 1000.0,
                        input_seq,
                    });
                }
            });
        match spawn_result {
            Ok(_) => {
                self.converted_archive_cache_paths_pending =
                    Some(ConvertedArchiveCachePathsPending {
                        generation,
                        cancel,
                        rx,
                    });
            }
            Err(e) => {
                crate::logger::log(format!("archive_cache_peek spawn failed: {e}"));
            }
        }
    }

    fn poll_converted_archive_cache_paths(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.converted_archive_cache_paths_pending.as_ref() else {
            return;
        };
        let result = match pending.rx.try_recv() {
            Ok(result) => result,
            Err(std::sync::mpsc::TryRecvError::Empty) => return,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                self.converted_archive_cache_paths_pending = None;
                return;
            }
        };
        let generation = pending.generation;
        self.converted_archive_cache_paths_pending = None;
        if generation != self.items_generation {
            return;
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "archive_cache_peek",
                None,
                result.input_seq,
                &[
                    ("ms", serde_json::Value::from(result.elapsed_ms)),
                    ("peeked", serde_json::Value::from(result.peeked)),
                    ("hits", serde_json::Value::from(result.hits)),
                    ("async", serde_json::Value::from(true)),
                ],
            );
        }
        let should_rebuild_visible = self.settings.facet_filter.has_rollup_edit_filter();
        self.converted_archive_cache_paths = result.paths;
        if should_rebuild_visible {
            self.rebuild_visible_indices();
        }
        ctx.request_repaint();
    }

    /// Phase C: フォルダピンの source が Video のときに、`video_pins` DB の WebP を
    /// folder の pinned cache key で catalog + cache_map に書き込む。
    ///
    /// これを呼んだ直後、worker は通常の cache_hit 経路 (pinned_key で `cache_map`
    /// を引く) で動画ピンフレームを取り出せる。`apply_folder_thumb_pin` の Video
    /// 分岐は LoadRequest の `cache_key_override` / `mtime` / `file_size` を target
    /// 動画のメタデータで埋めるので、ここで書き込んだ catalog 行と整合する。
    ///
    /// **stale 行の掃除** (Codex Phase C P2 指摘): `video_pins` に行が無い / 空 blob /
    /// 復元失敗のときは、過去に seed されていた pinned cache 行 (= 旧 video pin の
    /// WebP) を catalog + cache_map から **削除** する。これをやらないと、worker が
    /// 旧 WebP で cache_hit してしまい、auto-pick fallback に落ちない。
    ///
    /// **byte 比較** (Codex Phase C P2 指摘): `video_pins.set_pin` は同じ動画 path に
    /// 対して `pin_pts_secs` / `thumb_webp` を上書き更新する。mtime/size だけ見ると
    /// 「内容が変わったか」を判定できないので、`jpeg_data` を直接比較して再 seed する。
    ///
    /// **「動画内 PIN 必須」仕様** (Codex post-merge P2 → ユーザー合意): seed が拾うのは
    /// `video_pins.db` の WebP のみ。一時期 sidecar `image::open` / Shell API 抽出の
    /// fallback も seed に入れたが、UI スレッドで重く動画 pin 付きフォルダ複数 + Shell
    /// 遅延でフォルダ移動が固まったため撤去した。動画を folder pin したいユーザーは
    /// 先にフルスクリーンで `P` キー / HUD でフレームを保存する
    /// (set 側で `try_set_folder_thumb_pin_with_video_guard` がガード)。
    fn seed_folder_video_pin_thumbs(
        &self,
        cache_map: &Arc<
            std::sync::RwLock<std::collections::HashMap<String, crate::catalog::CacheEntry>>,
        >,
        catalog: Option<&Arc<crate::catalog::CatalogDb>>,
    ) {
        if self.folder_pin_map.is_empty() {
            return;
        }
        let Some(video_db) = self.video_pin_db.as_ref() else {
            return;
        };
        let Some(cat) = catalog else {
            return;
        };
        use crate::folder_thumb_pins::ResolvedKind;
        let pin_db = self.folder_thumb_pin_db.as_deref();
        let max_cascade_depth = self.settings.folder_thumb_depth as usize;
        // T54 follow-on (Codex post-merge / 2026-05-16): 検索結果コンテキストでは
        // make_load_request が full-path ベースの cache key を使うので、seed 側も同じ key で
        // WebP を書き込まないと cache hit せず、auto-pick が pinned_key 下に上書きで保存
        // される churn が発生する (= ユーザー視点では「pin したフォルダのサムネが
        // 検索結果上だけ別の画像になる」)。`container_cache_base_key` を経由して
        // 両側で同じキーを共有させる。
        let use_full_path_keys = self.use_full_path_cache_keys();
        let mut seeded = 0u32;
        let mut purged = 0u32;
        for item in &self.items {
            let GridItem::Folder(container_path) = item else {
                continue;
            };
            let container_key = crate::path_key::normalize_keep_drive(container_path);
            let Some(source) = self.folder_pin_map.get(&container_key) else {
                continue;
            };
            // cascade 解決の leaf が Video kind になるケースを対象にする (= Folder→...→Video
            // の入れ子 pin にも対応)。immediate source が Video でも、Folder→Folder→...→Video
            // でも leaf が Video なら同じ seed 処理。
            let lookup = |p: &std::path::Path| pin_db.and_then(|db| db.lookup(p));
            let Some(resolved) = crate::folder_thumb_pins::resolve_pin_target_cascaded_via(
                container_path,
                source,
                lookup,
                max_cascade_depth,
            ) else {
                continue;
            };
            if !matches!(resolved.kind, ResolvedKind::Video) {
                continue;
            }
            let Some(base_key) = container_cache_base_key(
                item,
                use_full_path_keys,
                Some(self.settings.folder_thumb_sort),
                self.settings.folder_thumb_depth,
            ) else {
                continue;
            };
            let pinned_key = format!(
                "{}{}{}",
                base_key,
                crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                resolved.source_id,
            );

            // video_pins.db の WebP (= フルスクリーン HUD でユーザーがピン留めした
            // 特定フレーム) のみを seed する。
            //
            // Codex post-merge P2 対応: sidecar 画像の `image::open` / Shell API 呼び出しは
            // UI スレッドで重く、動画 pin 付きフォルダが複数あると `start_loading_items`
            // (= フォルダ移動) がブロックする。sidecar / Shell fallback は撤去し、
            // 「動画を folder pin するには先にフルスクリーンでフレームを保存する」
            // 仕様にした (set 側で `try_set_folder_thumb_pin_with_video_guard` がガード)。
            // ここに来る時点で video_pins WebP は必ず存在する想定だが、レース
            // (フルスクリーンで unpin した直後など) で空になっていることもあるので
            // `.filter(non-empty)` は残し、空なら下の purge_stale 経路に落とす。
            let webp = video_db
                .lookup(&resolved.abs_path)
                .map(|pin| pin.thumb_webp)
                .filter(|b| !b.is_empty());

            // pinned_key 行を catalog + cache_map から削除する内部 closure。
            // 「seed できない (WebP 無し / 破損 / SQL エラー)」全ケースで共通に使い、
            // 旧 pin の WebP が cache_hit で復活しないようにする (Codex Phase C P3 指摘)。
            // 削除中だけで使うのでローカル変数 + 通常関数として書く方が借用が単純になる。
            let purge_stale = |pinned_key: &str| -> bool {
                let stale_exists = cache_map
                    .read()
                    .ok()
                    .map(|map| map.contains_key(pinned_key))
                    .unwrap_or(false);
                if !stale_exists {
                    return false;
                }
                match cat.delete_one(pinned_key) {
                    Ok(()) => {
                        if let Ok(mut map) = cache_map.write() {
                            map.remove(pinned_key);
                        }
                        true
                    }
                    Err(e) => {
                        crate::logger::log(format!(
                            "folder_thumb_pin video seed purge failed: {e} ({pinned_key})"
                        ));
                        false
                    }
                }
            };

            let Some(webp) = webp else {
                // WebP 無し: 既存 seed (旧 pin の残骸) があれば削除して fallback 経路へ。
                if purge_stale(&pinned_key) {
                    purged += 1;
                }
                continue;
            };

            // 既存 seed が完全一致 (mtime/size + bytes) なら書き直さない (典型ケース)。
            let already_seeded = cache_map
                .read()
                .ok()
                .and_then(|map| {
                    map.get(&pinned_key).map(|entry| {
                        entry.mtime == resolved.mtime
                            && entry.file_size == resolved.file_size
                            && entry.jpeg_data == webp
                    })
                })
                .unwrap_or(false);
            if already_seeded {
                continue;
            }
            match cat.save_thumb_bytes(&pinned_key, resolved.mtime, resolved.file_size, None, &webp)
            {
                Ok(true) => {}
                Ok(false) => {
                    crate::logger::log(format!(
                        "folder_thumb_pin video seed: invalid WebP for {} (purge stale)",
                        resolved.abs_path.display()
                    ));
                    if purge_stale(&pinned_key) {
                        purged += 1;
                    }
                    continue;
                }
                Err(e) => {
                    crate::logger::log(format!(
                        "folder_thumb_pin video seed save failed: {e} ({}) (purge stale)",
                        resolved.abs_path.display()
                    ));
                    if purge_stale(&pinned_key) {
                        purged += 1;
                    }
                    continue;
                }
            }
            if let Ok(mut map) = cache_map.write() {
                map.insert(
                    pinned_key.clone(),
                    crate::catalog::CacheEntry {
                        mtime: resolved.mtime,
                        file_size: resolved.file_size,
                        jpeg_data: webp,
                        source_dims: None,
                    },
                );
            }
            seeded += 1;
        }
        if seeded > 0 || purged > 0 {
            crate::logger::log(format!(
                "folder_thumb_pin: video seed = {seeded}, purged stale = {purged}"
            ));
        }
    }

    fn drive_list_pin_seed_entry(
        &mut self,
        container: &std::path::Path,
        source: &crate::folder_thumb_pins::FolderPinSource,
    ) -> Option<crate::catalog::CacheEntry> {
        use crate::folder_thumb_pins::{FileKind, FolderPinSource};
        match source {
            FolderPinSource::File { rel, kind } => {
                let fname = direct_pin_rel_file_name(rel)?;
                let use_full_path_key = crate::path_key::is_drive_or_share_root(container);
                match kind {
                    FileKind::Image => {
                        let cat = self.get_or_open_catalog(container)?;
                        let key = if use_full_path_key {
                            image_full_path_cache_key(&container.join(rel))
                        } else {
                            fname
                        };
                        cat.load_one(&key).ok().flatten()
                    }
                    FileKind::Video => {
                        let video_path = container.join(rel);
                        let webp = self
                            .video_pin_db
                            .as_ref()
                            .and_then(|db| db.lookup(&video_path))
                            .map(|pin| pin.thumb_webp)
                            .filter(|b| !b.is_empty())?;
                        Some(crate::catalog::CacheEntry {
                            mtime: 0,
                            file_size: 0,
                            jpeg_data: webp,
                            source_dims: None,
                        })
                    }
                    FileKind::ZipFile => {
                        let cat = self.get_or_open_catalog(container)?;
                        let item = GridItem::ZipFile(container.join(rel));
                        let key = container_cache_base_key(&item, use_full_path_key, None, 0)
                            .unwrap_or_else(|| format!("{}{}", CACHE_KEY_ZIP, fname));
                        cat.load_one(&key).ok().flatten()
                    }
                    FileKind::PdfFile => {
                        let cat = self.get_or_open_catalog(container)?;
                        let item = GridItem::PdfFile(container.join(rel));
                        let key = container_cache_base_key(&item, use_full_path_key, None, 0)
                            .unwrap_or_else(|| format!("{}{}", CACHE_KEY_PDF, fname));
                        cat.load_one(&key).ok().flatten()
                    }
                    FileKind::Folder => {
                        let folder_path = container.join(rel);
                        let folder_item = GridItem::Folder(folder_path);
                        let key = container_cache_base_key(
                            &folder_item,
                            use_full_path_key,
                            Some(self.settings.folder_thumb_sort),
                            self.settings.folder_thumb_depth,
                        )?;
                        let cat = self.get_or_open_catalog(container)?;
                        let base_entry = cat.load_one(&key).ok().flatten();
                        let pinned_prefix =
                            format!("{}{}", key, crate::thumb_loader::CACHE_KEY_PIN_SUFFIX);
                        let pinned_entry = cat
                            .load_latest_with_prefix(&pinned_prefix)
                            .ok()
                            .flatten()
                            .map(|(_, entry)| entry);
                        pinned_entry.or(base_entry)
                    }
                }
            }
            FolderPinSource::ZipEntry { zip_rel, entry } => {
                let zip_path = if zip_rel.is_empty() {
                    container.to_path_buf()
                } else {
                    container.join(zip_rel)
                };
                let cat = self.get_or_open_catalog(&zip_path)?;
                cat.load_one(entry).ok().flatten()
            }
            FolderPinSource::ZipDir {
                zip_rel,
                dir_prefix,
            } => {
                let zip_path = if zip_rel.is_empty() {
                    container.to_path_buf()
                } else {
                    container.join(zip_rel)
                };
                let cat = self.get_or_open_catalog(&zip_path)?;
                let key = crate::grid_item::zipdir_cache_key(dir_prefix);
                let base_entry = cat.load_one(&key).ok().flatten();
                let pinned_prefix = format!("{}{}", key, crate::thumb_loader::CACHE_KEY_PIN_SUFFIX);
                let pinned_entry = cat
                    .load_latest_with_prefix(&pinned_prefix)
                    .ok()
                    .flatten()
                    .map(|(_, entry)| entry);
                pinned_entry.or(base_entry)
            }
            FolderPinSource::PdfPage { pdf_rel, page } => {
                let pdf_path = if pdf_rel.is_empty() {
                    container.to_path_buf()
                } else {
                    container.join(pdf_rel)
                };
                let cat = self.get_or_open_catalog(&pdf_path)?;
                cat.load_one(&crate::grid_item::pdf_page_cache_key(*page))
                    .ok()
                    .flatten()
            }
        }
    }

    fn seed_drive_list_pin_thumbs_from_catalog(
        &mut self,
        cache_map: &Arc<
            std::sync::RwLock<std::collections::HashMap<String, crate::catalog::CacheEntry>>,
        >,
        drive_list_catalog: Option<&Arc<crate::catalog::CatalogDb>>,
    ) {
        if self.folder_pin_map.is_empty() {
            return;
        }
        let Some(target_cat) = drive_list_catalog.cloned() else {
            return;
        };
        let mut seeded = 0u32;
        for idx in 0..self.items.len() {
            let Some((container_path, source, base_key)) = self.items.get(idx).and_then(|item| {
                let GridItem::Folder(path) = item else {
                    return None;
                };
                let key = crate::path_key::normalize_keep_drive(path);
                let source = self.folder_pin_map.get(&key)?.clone();
                let base_key = container_cache_base_key(
                    item,
                    true,
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                )?;
                Some((path.clone(), source, base_key))
            }) else {
                continue;
            };
            let prefix = drive_list_pinned_cache_key_prefix(&base_key, &source);
            let Some(entry) = self.drive_list_pin_seed_entry(&container_path, &source) else {
                continue;
            };
            let key = drive_list_pinned_cache_key(&prefix, entry.mtime, entry.file_size);
            let already_cached = cache_map
                .read()
                .ok()
                .and_then(|map| map.get(&key).cloned())
                .is_some_and(|cached| {
                    cached.mtime == entry.mtime
                        && cached.file_size == entry.file_size
                        && cached.jpeg_data == entry.jpeg_data
                });
            if already_cached {
                continue;
            }
            match target_cat.save_thumb_bytes(
                &key,
                entry.mtime,
                entry.file_size,
                entry.source_dims,
                &entry.jpeg_data,
            ) {
                Ok(true) => {
                    if let Ok(mut map) = cache_map.write() {
                        map.insert(key, entry);
                    }
                    seeded += 1;
                }
                Ok(false) => {
                    crate::logger::log(format!(
                        "drive-list pin seed: cached bytes are not decodable ({prefix})"
                    ));
                }
                Err(e) => {
                    crate::logger::log(format!("drive-list pin seed failed: {e} ({prefix})"));
                }
            }
        }
        if seeded > 0 {
            crate::logger::log(format!("drive-list pin seed = {seeded}"));
        }
    }

    /// 通常ロードとmetadata import終端refreshで共用する、item単位のfolder-pin identity。
    ///
    /// `ZipDir`はDB保存先のeffective prefixとcell参照側のliteral prefixが異なり得るため、
    /// lookup pathに加えてaliasも返す。
    fn folder_pin_lookup_target_for_item(&self, item: &GridItem) -> Option<FolderPinLookupTarget> {
        let direct = match item {
            GridItem::Folder(path)
            | GridItem::ZipFile(path)
            | GridItem::PdfFile(path)
            | GridItem::ConvertibleArchive { path, .. } => Some(path.clone()),
            _ => None,
        };
        if let Some(path) = direct {
            return Some(FolderPinLookupTarget { path, alias: None });
        }
        let GridItem::ZipDir {
            zip_path,
            dir_prefix,
            ..
        } = item
        else {
            return None;
        };
        let book_root = zip_pin_root_path(
            zip_path,
            self.archive_source_override.as_deref(),
            self.current_folder.as_deref(),
        );
        let literal = book_container_key(book_root, dir_prefix);
        let effective_key = if let Some(nav) = self.zip_nav.as_ref() {
            let segments = dir_prefix
                .split('/')
                .filter(|segment| !segment.is_empty())
                .map(str::to_owned)
                .collect::<Vec<_>>();
            let effective = nav.tree.collapse_redundant(&segments);
            book_container_key_from_segs(book_root, &effective)
        } else {
            literal.clone()
        };
        let literal_key = crate::path_key::normalize_keep_drive(&literal);
        let effective_key_normalized = crate::path_key::normalize_keep_drive(&effective_key);
        Some(FolderPinLookupTarget {
            path: effective_key,
            alias: (literal_key != effective_key_normalized)
                .then_some((literal_key, effective_key_normalized)),
        })
    }

    /// item以外にfolder-pin mapが必要とするcontext固有identity。
    fn folder_pin_context_lookup_paths(&self) -> Vec<PathBuf> {
        let mut paths = Vec::with_capacity(2);
        // current_folder自身はアドレスバーの📌状態で参照する。
        if let Some(current) = self.current_folder.as_ref()
            && !is_synthetic_view_path(current)
            && !self.items_are_global_search_view
            && !self.items_are_tag_view
        {
            paths.push(current.clone());
        }
        // ZIP本を開いている場合は、現在の本そのもののpin keyも必要。
        if self.zip_nav.is_some()
            && let Some(book_key) = self.pin_container_key()
        {
            paths.push(book_key);
        }
        paths
    }

    fn apply_folder_pin_aliases(
        pins: &mut HashMap<String, crate::folder_thumb_pins::FolderPinSource>,
        aliases: &[(String, String)],
    ) {
        for (literal_key, effective_key) in aliases {
            if let Some(pin) = pins.get(effective_key).cloned() {
                pins.insert(literal_key.clone(), pin);
            }
        }
    }

    /// 現在items中の親コンテナとcontext固有identityをDBから一括取得する。
    fn refresh_folder_pin_map(&mut self) {
        self.folder_pin_map.clear();
        // サブ展開はprepare workerが全対象を照会済み。
        if self.current_folder.as_ref().is_some_and(|folder| {
            crate::folder_tree::path_eq(folder, &subfolder_expansion_synthetic_path())
        }) {
            return;
        }
        let Some(db) = self.folder_thumb_pin_db.as_ref() else {
            return;
        };
        let mut paths = Vec::with_capacity(self.items.len() + 2);
        let mut aliases = Vec::new();
        for item in &self.items {
            if let Some(target) = self.folder_pin_lookup_target_for_item(item) {
                paths.push(target.path);
                if let Some(alias) = target.alias {
                    aliases.push(alias);
                }
            }
        }
        paths.extend(self.folder_pin_context_lookup_paths());
        if paths.is_empty() {
            return;
        }
        self.folder_pin_map = db.lookup_many(paths);
        Self::apply_folder_pin_aliases(&mut self.folder_pin_map, &aliases);
    }

    fn should_force_cache_for_drive_list_pin(&self, item: &GridItem) -> bool {
        let Some(container) = self.current_folder.as_ref() else {
            return false;
        };
        if self.items_are_drive_list || !crate::path_key::is_drive_or_share_root(container) {
            return false;
        }
        let Some(source) = crate::folder_thumb_pins::source_from_grid_item(container, item) else {
            return false;
        };
        if matches!(
            source,
            crate::folder_thumb_pins::FolderPinSource::File {
                kind: crate::folder_thumb_pins::FileKind::Video,
                ..
            }
        ) {
            return false;
        }
        let container_key = crate::path_key::normalize_keep_drive(container);
        self.folder_pin_map
            .get(&container_key)
            .is_some_and(|pinned| pinned == &source)
    }

    /// 指定 container の代表サムネピンを `source` に設定 (上書き) し、再ロード予約を立てる。
    /// UI 側 (アドレスバーの 📌 ボタン / コンテキストメニュー) からの主エントリポイント。
    ///
    /// 戻り値: 書き込みに成功すれば `true`。pin DB 未開 / SQL エラーで失敗時は
    /// `false` でログのみ残す (UI 側はエラー詳細を出さずに「設定できませんでした」を表示)。
    pub(crate) fn set_folder_thumb_pin(
        &mut self,
        container: &std::path::Path,
        source: crate::folder_thumb_pins::FolderPinSource,
    ) -> bool {
        let Some(db) = self.folder_thumb_pin_db.as_ref() else {
            crate::logger::log("folder_thumb_pin: DB not open".to_string());
            return false;
        };
        match db.set(container, &source) {
            Ok(()) => {
                let key = crate::path_key::normalize_keep_drive(container);
                self.folder_pin_map.insert(key, source);
                self.invalidate_smart_folder_resort_metadata();
                self.folder_thumb_pin_dirty = true;
                crate::logger::log(format!("folder_thumb_pin set: {}", container.display()));
                true
            }
            Err(e) => {
                crate::logger::log(format!("folder_thumb_pin set failed: {e}"));
                false
            }
        }
    }

    /// 指定 container の代表サムネピンを解除する (該当行が無くてもエラーにしない)。
    pub(crate) fn remove_folder_thumb_pin(&mut self, container: &std::path::Path) -> bool {
        let Some(db) = self.folder_thumb_pin_db.as_ref() else {
            return false;
        };
        match db.remove(container) {
            Ok(()) => {
                let key = crate::path_key::normalize_keep_drive(container);
                self.folder_pin_map.remove(&key);
                self.invalidate_smart_folder_resort_metadata();
                self.folder_thumb_pin_dirty = true;
                crate::logger::log(format!("folder_thumb_pin removed: {}", container.display()));
                true
            }
            Err(e) => {
                crate::logger::log(format!("folder_thumb_pin remove failed: {e}"));
                false
            }
        }
    }

    /// 指定 container に現在のピン情報があれば返す。UI 側で「同じ画像が pin 済みか」
    /// 判定し、トグル動作のためのボタン表示状態を切り替えるのに使う。
    pub(crate) fn folder_thumb_pin_for(
        &self,
        container: &std::path::Path,
    ) -> Option<&crate::folder_thumb_pins::FolderPinSource> {
        let key = crate::path_key::normalize_keep_drive(container);
        self.folder_pin_map.get(&key)
    }

    /// 選択中アイテムを代表サムネにピンするときの `source`。ネスト ZIP ツリー閲覧中は
    /// ZipImage を ZipEntry、ZipDir を ZipDir source にする。通常フォルダは
    /// `source_from_grid_item(current_folder, item)`。
    /// ピン対象コンテナは `pin_container_key()` (zip 内は本キー、通常は current_folder)。
    /// 📌 ボタン状態 / コンテキストメニュー / グリッドバッジで P キーと同じ判定を共有する。
    pub(crate) fn folder_pin_selected_source(
        &self,
        idx: usize,
    ) -> Option<crate::folder_thumb_pins::FolderPinSource> {
        let item = self.items.get(idx)?;
        if let Some(nav) = self.zip_nav.as_ref() {
            return match item {
                GridItem::ZipImage { entry_name, .. } => {
                    Some(crate::folder_thumb_pins::FolderPinSource::ZipEntry {
                        zip_rel: String::new(),
                        entry: entry_name.clone(),
                    })
                }
                GridItem::ZipDir { dir_prefix, .. } => {
                    let segs = zip_dir_prefix_segments(dir_prefix);
                    let effective = nav.tree.collapse_redundant(&segs);
                    let dir_prefix = zip_dir_prefix_from_segs(&effective);
                    if dir_prefix.is_empty() {
                        None
                    } else {
                        Some(crate::folder_thumb_pins::FolderPinSource::ZipDir {
                            zip_rel: String::new(),
                            dir_prefix,
                        })
                    }
                }
                _ => None,
            };
        }
        let container = self.current_folder.as_ref()?;
        crate::folder_thumb_pins::source_from_grid_item(container, item)
    }

    /// アドレスバー 📌 ボタンの表示状態を算出する (UI 描画から呼ばれる)。
    ///
    /// 返り値:
    /// - `None`: ボタンを描画しない (= 設定 OFF / 検索アグリゲートビュー / current_folder 無し)
    /// - `Some(state)`: 描画する。`state.enabled = false` の場合は disabled + tooltip 表示
    pub(crate) fn compute_folder_pin_button_state(
        &self,
    ) -> Option<crate::ui_main::FolderPinButtonState> {
        if !self.settings.show_address_bar_folder_pin {
            return None;
        }
        // Ctrl+G アグリゲートビュー / Ctrl+T タグ結果では container 概念が無いので隠す
        if self.items_are_global_search_view || self.items_are_tag_view {
            return None;
        }
        // current_folder 未確定 (起動直後 / 合成ビュー) は描画しない
        let container = self.current_folder.as_ref()?;
        if is_synthetic_view_path(container) {
            return None;
        }
        // 変換キャッシュ ZIP の内部を `zip_nav` で見ている場合は、pin_container_key()
        // が元アーカイブパスへ戻すのでピン可能。zip_nav が無い中途半端な override 状態
        // だけは dead pin を避けるため隠す。
        if self.archive_source_override.is_some() && self.zip_nav.is_none() {
            return None;
        }
        // ピン対象コンテナ: ネスト ZIP では本キー (通常 ZIP は zip_path root、
        // 変換キャッシュは元アーカイブ root)、通常は current_folder。
        // P キー (toggle_folder_pin_for_idx) と同じ対象を見て
        // highlight/tooltip を一致させる。
        let pin_container = self
            .pin_container_key()
            .unwrap_or_else(|| container.clone());
        // 既存 pin (もしあれば) を引いておく
        let existing_pin = self.folder_thumb_pin_for(&pin_container).cloned();
        // 空フォルダ (= ピン可能なアイテムが 1 つも無い) で、なおかつ既存 pin も無い場合は
        // ボタン自体を隠す (Codex 最終レビュー P3 指摘: 「空フォルダは対象外」の
        // ドキュメント記述と挙動を揃える)。既存 pin がある場合は「右クリックで解除」を
        // 提供したいので隠さない (= ファイルを全部削除した後でもピンを掃除できる)。
        if self.items.is_empty() && existing_pin.is_none() {
            return None;
        }
        // 選択中アイテムから source を組み立てる (= 「左クリックで何を pin するか」)。
        // ネスト ZIP では本ごとピン (Model B) に合わせた source を使う。
        let selected_source: Option<crate::folder_thumb_pins::FolderPinSource> = self
            .selected
            .and_then(|i| self.folder_pin_selected_source(i));

        let selected_item = self.selected.and_then(|i| self.items.get(i));
        let is_convertible = matches!(selected_item, Some(GridItem::ConvertibleArchive { .. }));

        let matches_current_pin = match (&existing_pin, &selected_source) {
            (Some(a), Some(b)) => a == b,
            _ => false,
        };

        // 描画 + tooltip の決定
        // 1) ConvertibleArchive 選択中: 「変換後に設定可能」で disabled
        // 2) 選択無し / pin 不可: 「項目を選択してください」で disabled
        // 3) 通常: enabled。matches_current_pin で tooltip を分岐
        let (enabled, tooltip) = if is_convertible {
            (
                false,
                "代表サムネ固定: 変換後に設定可能 (アーカイブを ZIP に変換すると指定できます)"
                    .to_string(),
            )
        } else if selected_source.is_none() {
            // 既存 pin があるなら右クリックで解除のみ許可する (= enabled、ただし左クリック toggle は
            // source 無しで no-op)。ボタンとしては enabled で「右クリックで解除」案内を tooltip に。
            if existing_pin.is_some() {
                (
                    true,
                    "代表サムネ固定済み (右クリックで解除 / 左クリックで再設定するにはアイテムを選択)"
                        .to_string(),
                )
            } else {
                (
                    false,
                    "代表サムネ固定: フォルダ内のアイテムを選択してください".to_string(),
                )
            }
        } else if matches_current_pin {
            (
                true,
                "代表サムネ固定中: 左クリック / 右クリックで解除".to_string(),
            )
        } else if existing_pin.is_some() {
            (
                true,
                "選択中のアイテムを代表サムネに変更 (左クリック) / 解除 (右クリック)".to_string(),
            )
        } else {
            (
                true,
                "選択中のアイテムを代表サムネに固定 (左クリック)".to_string(),
            )
        };

        Some(crate::ui_main::FolderPinButtonState {
            enabled,
            tooltip,
            matches_current_pin,
        })
    }

    /// アドレスバー 📌 ボタンの左クリック (toggle) / P キーショートカットのハンドラ。
    /// 指定アイテムが現在の pin と一致 → 解除、不一致 → set。
    ///
    /// **silent no-op 条件** (`compute_folder_pin_button_state` で UI を隠す条件と整合):
    /// - `current_folder` 無し / 検索合成パス
    /// - Ctrl+G アグリゲートビュー (`items_are_global_search_view`)
    /// - Ctrl+T タグビュー (`items_are_tag_view`)
    /// - RAR/7z/LZH 変換キャッシュ ZIP の drill-down だが `zip_nav` が無い中途半端な状態
    /// - 選択無し / 選択アイテムが pin 不能 (ConvertibleArchive / SearchContainer、
    ///   または container を指す `rel=""` ケース)
    ///
    /// **Video pin の set ガード**: pin 対象が動画でかつ `video_pins` DB に有効な WebP
    /// (= フルスクリーン HUD でユーザーがピン留めしたフレーム) が無い場合、トースト
    /// 通知を出して set 自体を拒否する。これをやらないと、worker が auto-pick fallback で
    /// 親フォルダ自身の代表画を pinned_key 下に保存してしまい、ユーザーから見ると
    /// 「動画 pin したのにサムネが変わらない」状態になる (= 効果が無い pin)。
    pub(crate) fn toggle_folder_pin_for_idx(&mut self, idx: usize) {
        // zip_nav がある変換キャッシュ閲覧中は元アーカイブパスへピンできる。
        // zip_nav が無い override 状態だけは dead pin を避ける。
        if self.archive_source_override.is_some() && self.zip_nav.is_none() {
            return;
        }
        // ネスト ZIP ツリー: 現在の本 (= pin_container_key) ごとに代表サムネを記憶する。
        // ZipImage は直接画像、ZipDir は通常フォルダの子フォルダ pin と同じく container
        // source として保存し、表示時に cascade 解決する。
        if self.zip_nav.is_some() {
            let Some(book_key) = self.pin_container_key() else {
                return;
            };
            let Some(source) = self.folder_pin_selected_source(idx) else {
                return;
            };
            if self.folder_thumb_pin_for(&book_key) == Some(&source) {
                self.remove_folder_thumb_pin(&book_key);
                self.show_feedback_toast("この本の代表サムネを解除しました".to_string());
            } else {
                self.set_folder_thumb_pin(&book_key, source);
                self.show_feedback_toast("この本の代表サムネに設定しました".to_string());
            }
            // 設定対象 (本) のセルは親階層にあり現在のビューには無いので、ここでの
            // 再 materialize (= scroll/selected リセット) は不要。dirty を消して
            // 読書位置を保つ。親へ戻ると zip_nav_back の refresh_folder_pin_map が
            // ピンを拾ってセルに反映する。
            self.folder_thumb_pin_dirty = false;
            return;
        }
        let Some(container) = self.current_folder.clone() else {
            return;
        };
        if is_synthetic_view_path(&container) {
            return;
        }
        if self.items_are_global_search_view || self.items_are_tag_view {
            return;
        }
        let Some(item) = self.items.get(idx).cloned() else {
            return;
        };
        let Some(source) = crate::folder_thumb_pins::source_from_grid_item(&container, &item)
        else {
            return;
        };
        let existing = self.folder_thumb_pin_for(&container).cloned();
        if existing.as_ref() == Some(&source) {
            // 解除は無条件で許可 (DB 上の dead pin を掃除できるように)
            self.remove_folder_thumb_pin(&container);
            return;
        }
        self.try_set_folder_thumb_pin_with_video_guard(&container, source);
    }

    /// アドレスバー 📌 ボタンの左クリック (toggle) / グリッド P キーショートカットのハンドラ。
    pub(crate) fn toggle_folder_pin_from_selection(&mut self) {
        let Some(idx) = self.selected else {
            return;
        };
        self.toggle_folder_pin_for_idx(idx);
    }

    /// `set_folder_thumb_pin` の薄いラッパで、**動画 source の場合は video_pins DB に
    /// 有効な WebP が無ければ拒否**する。worker が auto-pick fallback で「親フォルダ自身の
    /// 代表画」を pinned_key に保存してしまう dead pin を防ぐ。
    ///
    /// 戻り値: 実際に pin が設定できれば `true`。拒否時はトーストを出して `false`。
    /// 拒否は **set** にのみ適用される (= remove は別経路から直接呼ぶ)。
    ///
    /// 設計判断 (Codex post-merge P2 → ユーザー合意「動画内 PIN 必須仕様」):
    /// sidecar `image::open` / Shell API 抽出を `seed_folder_video_pin_thumbs` で
    /// 同期実行すると、動画 pin 付きフォルダ複数 + Shell 遅延でフォルダ移動が固まる。
    /// そのため video source は **`video_pins.db` に WebP がある (= フルスクリーンで
    /// フレームを保存済み) 場合のみ** folder pin を許可する。seed は軽い DB→DB
    /// コピーだけになり UI ヒッチが完全に消える。フレーム未保存の動画に 📌 すると
    /// トーストで「フルスクリーンでフレームを保存してください」と案内する。
    fn try_set_folder_thumb_pin_with_video_guard(
        &mut self,
        container: &std::path::Path,
        source: crate::folder_thumb_pins::FolderPinSource,
    ) -> bool {
        if let crate::folder_thumb_pins::FolderPinSource::File {
            kind: crate::folder_thumb_pins::FileKind::Video,
            ..
        } = &source
        {
            let abs = container.join(source.rel());
            let has_webp = self
                .video_pin_db
                .as_ref()
                .and_then(|db| db.lookup(&abs))
                .map(|pin| !pin.thumb_webp.is_empty())
                .unwrap_or(false);
            if !has_webp {
                // 2 行の操作ガイドなので既定 1.2 秒では読み切れない。長め (5 秒) で表示。
                self.show_feedback_toast_with_duration(
                    "動画内でピン留めされた画像がないため、設定できません\n\
                     先にフルスクリーンで動画を開き、HUD のピンボタン (または P キー) で\
                     フレームを保存してください"
                        .to_string(),
                    5.0,
                );
                crate::logger::log(format!(
                    "folder_thumb_pin: video pin rejected (no WebP) for {}",
                    abs.display()
                ));
                return false;
            }
        }
        self.set_folder_thumb_pin(container, source)
    }

    /// 親コンテナの代表サムネピンが書き換わっていたら現フォルダを再ロードして
    /// グリッドに反映する。`close_fullscreen` と `App::update` (= 毎フレーム) の
    /// 両方から呼ばれる。dirty が `close_fullscreen` でしか consume されないと、
    /// グリッドモードで 📌 を押しても次の fullscreen 開閉までグリッドが古いまま
    /// になる (Codex Phase D P2 指摘)。
    pub(crate) fn consume_folder_thumb_pin_dirty(&mut self) {
        if std::mem::take(&mut self.folder_thumb_pin_dirty) {
            // ネスト ZIP ツリー閲覧中は現在の階層を保ったまま再 materialize する。
            // load_folder(zip_path) で開き直すと ZIP のルートに飛んでしまう
            // (ユーザー報告: 内側ファイルを P でピンするとトップ階層にジャンプ)。
            if self.zip_nav.is_some() {
                self.zip_nav_show_current_level();
            } else if let Some(cur) = self.current_folder.clone() {
                self.folder_history.remove(&cur);
                self.load_folder(cur);
            }
        }
    }

    /// 動画ピンの書き換え (P ピン / 解除 / 後追い WebP 補完) があったら現フォルダを
    /// 再ロードしてグリッドサムネに反映する (Phase 8.B')。`close_fullscreen` と
    /// `App::update` (= 毎フレーム、メインビューア非表示時) の両方から呼ばれる。
    /// close_fullscreen だけで consume していると、フル機能モード + メディア別
    /// ウィンドウの P ピンではメイン窓のグリッドが開きっぱなしで反映契機が来ない
    /// (実機 FB 2026-07-10。`consume_folder_thumb_pin_dirty` と同じ構造の修正)。
    ///
    /// 再ロードは「ピンした動画が現在の items に見えているとき」だけ行う。別窓が
    /// メイン表示と無関係なフォルダの動画をピンしたケースで、メイン側のスクロール /
    /// 選択を巻き込む無駄な再ロードを避けるため。ここで dirty を捨てても、その動画の
    /// フォルダを次に開く load_folder が video_pins.db から WebP を snapshot し直す
    /// (`start_loading_items` の pin_blobs) ので反映漏れにはならない。
    pub(crate) fn consume_video_thumb_overrides_dirty(&mut self) {
        if self.video_thumb_overrides_dirty_paths.is_empty() {
            return;
        }
        // P ピン時に thumb worker のフレームがまだ無かった場合 (空 WebP で set_pin →
        // 旧 blob 温存)、後追い補完 (`tick_pending_pin_thumb_refresh`) が DB に正しい
        // フレームを書き込むまで consume を遅らせる。先に再ロードすると「古いフレームの
        // まま」を一度描いてから補完後にもう一度リロードする二度手間になる。pending は
        // 完了 / 10s タイムアウト / 動画切替の全ケースで None に戻るので詰まらない。
        #[cfg(windows)]
        if self.pending_pin_thumb_refresh.is_some() {
            return;
        }
        // 再ロードの最短間隔 (安全網)。マーカーキャッシュ経由の producer が dirty を
        // 再点火し続ける状態 (実機 2026-07-10: persist ↔ 再ロードの自己ループで
        // ~50ms 周期の load_folder 連打、全動画サムネが Pending=黒に固着) に陥っても、
        // 連打にはさせない。dirty は捨てず保持し、間隔経過後の consume で処理する。
        if let Some(t) = self.video_thumb_reload_last_at
            && t.elapsed() < std::time::Duration::from_secs(1)
        {
            return;
        }
        let dirty = std::mem::take(&mut self.video_thumb_overrides_dirty_paths);
        if !self.video_pin_dirty_visible_in_items(&dirty) {
            return;
        }
        self.video_thumb_reload_last_at = Some(std::time::Instant::now());
        if self.items_are_subfolder_expansion_view {
            // 同じ snapshot を再適用して動画ピンの WebP を再取得する。
            if !self.reinstall_subfolder_expansion_snapshot()
                && let Some(root) = self.subfolder_expansion_root.clone()
            {
                let roots = if self.subfolder_expansion_roots.is_empty() {
                    vec![root.clone()]
                } else {
                    self.subfolder_expansion_roots.clone()
                };
                self.start_subfolder_expansion_scan_roots(root, roots);
            }
        } else if self.items_are_smart_folder_view {
            // A resident smart-folder result is frozen for the session. The explicit toolbar /
            // menu / gamepad reopen is the refresh gesture for path-keyed metadata and pins.
        } else if let Some(cur) = self.current_folder.clone()
            && !is_synthetic_view_path(&cur)
        {
            // 現フォルダ + 履歴を温存したまま再ロード。folder pin 側にある zip_nav
            // 分岐 (ルートへ飛ぶ罠の回避) は不要 — ZIP ビューには実ファイル Video
            // セルも動画へ解決される Folder タイルも出ないため、可視性チェックで
            // 必ず手前で return する。
            self.folder_history.remove(&cur);
            self.load_folder(cur);
        }
        // 既知の制限 (bool フラグ時代から同じ): 検索 / タグ等の合成ビューに dirty 動画の
        // Video セルが見えている場合、可視性は true になるがどの再ロード分岐にも入らず
        // サムネは古いまま (従来も close_fullscreen で consume して何もしなかった)。
        // ビューを閉じてフォルダへ戻る load_folder で反映される。
    }

    /// `consume_video_thumb_overrides_dirty` の可視性判定 (App 状態込み)。
    /// items の実ファイル `Video` セル (純関数 `video_pin_dirty_paths_visible`) に加え、
    /// 代表サムネ 📌 の cascade 解決が dirty 動画へ到達する `Folder` タイルも対象にする
    /// (親フォルダ表示中に別窓でピンを付け替えたとき、`seed_folder_video_pin_thumbs` が
    /// 焼いたタイル WebP を再ロードで更新するため。Codex P1)。解決ロジックは seed 側と
    /// 同じ folder_pin_map + cascade。resolve は fs metadata / pin DB lookup を伴うが、
    /// ここへ来るのはピン操作直後の 1 回だけなので負荷は seed (フォルダロード毎) 以下。
    fn video_pin_dirty_visible_in_items(&self, dirty: &std::collections::HashSet<PathBuf>) -> bool {
        if video_pin_dirty_paths_visible(dirty, &self.items) {
            return true;
        }
        if self.folder_pin_map.is_empty() {
            return false;
        }
        let dirty_keys: std::collections::HashSet<String> = dirty
            .iter()
            .map(|p| crate::path_key::normalize_keep_drive(p))
            .collect();
        let pin_db = self.folder_thumb_pin_db.as_deref();
        let max_cascade_depth = self.settings.folder_thumb_depth as usize;
        self.items.iter().any(|item| {
            let GridItem::Folder(container_path) = item else {
                return false;
            };
            let container_key = crate::path_key::normalize_keep_drive(container_path);
            let Some(source) = self.folder_pin_map.get(&container_key) else {
                return false;
            };
            let lookup = |p: &std::path::Path| pin_db.and_then(|db| db.lookup(p));
            let Some(resolved) = crate::folder_thumb_pins::resolve_pin_target_cascaded_via(
                container_path,
                source,
                lookup,
                max_cascade_depth,
            ) else {
                return false;
            };
            matches!(resolved.kind, crate::folder_thumb_pins::ResolvedKind::Video)
                && dirty_keys.contains(&crate::path_key::normalize_keep_drive(&resolved.abs_path))
        })
    }

    /// Ctrl+E エクスポートが現在表示中の実フォルダへ書き出したら、一覧復帰時の
    /// 再読み込み対象として記録する。ZIP / PDF / 検索結果などの仮想ビューでは
    /// 一覧文脈が変わってしまうため、ここでは何もしない。
    pub(crate) fn note_exported_file_for_folder_refresh(&mut self, path: &Path) {
        if self.items_are_global_search_view
            || self.global_search.active
            || self.favsearch.on_results_grid()
            || self.items_are_tag_view
            || self.tag_view.on_results_grid()
        {
            return;
        }
        let Some(parent) = path.parent() else {
            return;
        };
        let Some(cur) = self.current_favorite_target() else {
            return;
        };
        if crate::folder_tree::path_eq(parent, &cur) {
            self.export_folder_refresh_pending = Some(cur);
        }
    }

    /// Ctrl+E で現在フォルダへ保存されたファイルをグリッドへ反映する。
    ///
    /// フルスクリーン中に `load_folder` すると表示が閉じてしまうため、呼び出し側は
    /// `fullscreen_idx.is_none()` のときだけ実行する。
    pub(crate) fn consume_export_folder_refresh_pending(&mut self) {
        // .take() より先にガードを評価する。検索ビュー中やフォルダ未確定の状態で
        // ここを通っても pending を消費せず、後で復帰したときに再読込できるよう
        // 残しておく (Codex review CONFIRMED)。
        if self.export_folder_refresh_pending.is_none() {
            return;
        }
        if self.items_are_global_search_view
            || self.global_search.active
            || self.favsearch.on_results_grid()
            || self.items_are_tag_view
            || self.tag_view.on_results_grid()
        {
            return;
        }
        let Some(cur) = self.current_favorite_target() else {
            return;
        };
        let Some(target) = self.export_folder_refresh_pending.take() else {
            return;
        };
        if crate::folder_tree::path_eq(&cur, &target) {
            crate::logger::log(format!(
                "export: reloading current folder after Ctrl+E save ({})",
                cur.display()
            ));
            self.folder_history.remove(&cur);
            self.load_folder(cur);
        }
    }

    /// アドレスバー 📌 ボタンの右クリック / コンテキストメニューの「解除」ハンドラ。
    pub(crate) fn remove_folder_pin_for_current_container(&mut self) {
        // ネスト ZIP では本キー (pin_container_key: ルート = zip_path / 本の中 = 実効 prefix)
        // のピンを解除する。📌 ボタン状態が本キーを見ているので、右クリック解除も同じ
        // キーにしないとずれる (Codex P2)。
        let in_zip = self.zip_nav.is_some();
        let Some(container) = self.pin_container_key() else {
            return;
        };
        self.remove_folder_thumb_pin(&container);
        // 本の中では対象セルが親階層にあり現ビューに無いので、再 materialize (scroll
        // リセット) は不要。dirty を消して読書位置を保つ。
        if in_zip {
            self.folder_thumb_pin_dirty = false;
        }
    }

    /// コンテキストメニューに「代表サムネに固定 / 解除」エントリ (separator + ボタン)
    /// を**まとめて**追加する。アドレスバー 📌 と同じ動作をメニュー経由でも提供する。
    ///
    /// **separator 込みで描画する**ことに注意 (Codex Phase D P3 指摘: 呼び出し側で
    /// 先に `ui.separator()` を打つと、本関数が早期 return する条件 (アグリゲートビュー
    /// / 変換 drill-down / pin 不能 variant 等) で孤立 separator が残るバグになる)。
    /// 本関数は描画が確定する直前まで separator を打たない。
    ///
    /// 戻り値: メニューを閉じるべきなら `true` (= ピン書き換え操作が走った)。
    /// 描画スキップ / disabled / クリック未発生は `false`。
    pub(crate) fn render_folder_pin_menu_entry(
        &mut self,
        ui: &mut egui::Ui,
        item: &GridItem,
    ) -> bool {
        // 親コンテナ未確定 / Ctrl+G アグリゲートビュー / Ctrl+T タグビュー / 変換キャッシュ drill-down
        // / pin 不能 variant では一切描画しない (separator も打たない)。
        let Some(container) = self.current_folder.clone() else {
            return false;
        };
        if self.items_are_global_search_view || self.items_are_tag_view {
            return false;
        }
        if is_synthetic_view_path(&container) {
            return false;
        }
        // zip_nav がある変換キャッシュ閲覧中は元アーカイブパスへピンできる。
        // zip_nav が無い override 状態だけは dead pin を避ける。
        if self.archive_source_override.is_some() && self.zip_nav.is_none() {
            return false;
        }
        // pin 不能 variant: 描画スキップ
        if matches!(item, GridItem::SearchContainer { .. }) {
            return false;
        }
        // ConvertibleArchive: disabled + tooltip (描画 OK だが返値は常に false)
        if matches!(item, GridItem::ConvertibleArchive { .. }) {
            ui.separator();
            ui.add_enabled(false, egui::Button::new("📌 代表サムネに固定"))
                .on_hover_text("変換後に設定可能 (アーカイブを ZIP に変換すると指定できます)");
            return false;
        }
        // ピン対象コンテナ / source。ネスト ZIP では P キーと同じく本キーへ保存する。
        let (pin_container, source) = if let Some(nav) = self.zip_nav.as_ref() {
            match item {
                GridItem::ZipImage { entry_name, .. } => {
                    let Some(bk) = self.pin_container_key() else {
                        return false;
                    };
                    (
                        bk,
                        crate::folder_thumb_pins::FolderPinSource::ZipEntry {
                            zip_rel: String::new(),
                            entry: entry_name.clone(),
                        },
                    )
                }
                GridItem::ZipDir { dir_prefix, .. } => {
                    let Some(bk) = self.pin_container_key() else {
                        return false;
                    };
                    let segs = zip_dir_prefix_segments(dir_prefix);
                    let effective = nav.tree.collapse_redundant(&segs);
                    let dir_prefix = zip_dir_prefix_from_segs(&effective);
                    if dir_prefix.is_empty() {
                        return false;
                    }
                    (
                        bk,
                        crate::folder_thumb_pins::FolderPinSource::ZipDir {
                            zip_rel: String::new(),
                            dir_prefix,
                        },
                    )
                }
                _ => return false,
            }
        } else {
            let Some(source) = crate::folder_thumb_pins::source_from_grid_item(&container, item)
            else {
                // rel が空 (= container 自身を指している) などの理由で source 取れず → skip
                return false;
            };
            (container.clone(), source)
        };
        let existing = self.folder_thumb_pin_for(&pin_container).cloned();
        let is_current = existing.as_ref() == Some(&source);
        let label = if is_current {
            "📌 代表サムネ固定を解除"
        } else {
            "📌 代表サムネに固定"
        };
        ui.separator();
        if ui.button(label).clicked() {
            let in_zip = self.zip_nav.is_some();
            if is_current {
                self.remove_folder_thumb_pin(&pin_container);
            } else {
                self.try_set_folder_thumb_pin_with_video_guard(&pin_container, source);
            }
            // 本の中では対象セルが親階層にあり現ビューに無いので、再 materialize (scroll
            // リセット) は不要。dirty を消して読書位置を保つ (親へ戻れば refresh が拾う)。
            if in_zip {
                self.folder_thumb_pin_dirty = false;
            }
            return true;
        }
        false
    }

    /// items の idx 参照がまとめて無効になった後に呼ぶ共通クリーンアップ。
    ///
    /// 呼び出し元: `remove_items_batch` (削除完了時の idx シフト) と
    /// `replace_search_view_items` (Ctrl+G 結果差し替え)。事前条件として
    /// 呼び出し側で `items_generation` の bump 済みであること (そうしないと
    /// 旧ワーカーの `ThumbMsg` が新 items の同じ idx に着地してサムネが化ける)。
    ///
    /// クリーンアップ内容:
    /// - requested / pending_finalize / texture_backlog / fs_upload_backlog: idx を含む
    ///   キューイング状態
    /// - keep_range / keep_set / keep_start_shared / keep_end_shared: ワーカーの
    ///   in_range 判定境界。新しい update_keep_range_and_requests が次フレームで
    ///   正しい値を入れ直すまで保守的に 0 にしておく
    /// - idx-keyed HashMap 群 (rotation / rating / adjustment / thumb_pixels / ai_* / fs_*)
    /// - in-flight pending (fs_pending / ai_upscale_pending) のキャンセル
    /// - reload_queue / heavy_io_queue の排水: 旧 idx 向け重い I/O (Folder/ZIP/ZipDir 代表画)
    ///   や PDF レンダ要求が worker スロットを占有し続けるのを防ぐ。次フレームの
    ///   `update_keep_range_and_requests` が新 items に対応した request を再投入する
    ///
    /// items / thumbnails / image_metas / search_filter / selected / checked /
    /// scroll_offset_y / visible_indices / path-keyed キャッシュは呼び出し元の責務。
    pub(crate) fn invalidate_idx_state_and_queues(&mut self) {
        use std::sync::atomic::Ordering;

        self.invalidate_facet_name_cache();
        self.requested.clear();
        // items / thumbnails are replaced by several synthetic-view paths without going
        // through install_new_items.  The memo is idx-keyed, so retaining it would make an
        // unrelated item at the same index permanently ineligible for idle upgrading.
        self.idle_upgrade_cache_bypass_ineligible.clear();
        self.pending_finalize.clear();
        self.texture_backlog.clear();
        self.checked.clear();
        self.keep_range = (0, 0);
        self.keep_set.clear();
        self.details_hover_thumb_idx = None;
        self.keep_start_shared.store(0, Ordering::Relaxed);
        self.keep_end_shared.store(0, Ordering::Relaxed);

        // idx-keyed caches (HashMap<usize, ...>)
        // 注: `adjustment_page_params` / `mask_pages` は DB ロード済みの「ユーザーが付けた」
        // idx-keyed 状態なので、ここでは触らない。削除経路では呼び出し元が idx shift し、
        // 差し替え経路 (Ctrl+G) では呼び出し元が明示的に clear する。
        self.rotation_cache.clear();
        self.page_dims_cache.clear();
        self.rating_cache.clear();
        self.adjustment_cache.clear();
        self.thumb_pixels.clear();
        self.passthrough_rendition_cache.clear();
        self.thumb_edit_preview_layers.clear();
        self.thumb_adjust_tex.clear();
        self.ai_upscale_cache.clear();
        self.ai_upscale_failed.clear();
        self.ai_classify_cache.clear();
        self.input_generation.clear();
        self.erase_mask_generation.clear();
        self.local_adjust_generation.clear();
        self.local_adjust_brush_deferred_render = None;
        self.conceal_mask_generation.clear();
        self.erase_result_cache.clear();
        self.local_adjust_cache.clear();
        self.local_adjust_layer_bypass_cache.clear();
        self.local_adjust_prefix_preview_cache.clear();
        self.edit_result_cache.clear();
        self.clear_all_final_pipeline_caches();
        self.export_crop_mode = false;
        self.export_crop_drag = None;
        self.export_crop_create_drag = None;
        self.export_crop_spread_ctx = None;
        self.cancel_all_local_adjust_pending();
        self.local_adjust_lut_pending = None;
        self.local_adjust_segmentation_pending = None;
        // 360 度パノラマビュー: cache 全体が変わったので世代を一斉 bump (§3.6.2.2)。
        self.bump_all_adjustment_generations();
        self.bump_all_ai_generations();
        self.erase_base_cache.clear();
        self.conceal_base_cache.clear();
        self.conceal_cache.clear();
        self.comic_cache.clear();
        self.cancel_all_comic_bakes();
        self.fs_early_dims.clear();
        self.fs_cache.clear();
        self.fs_lanczos_cache.clear();
        self.fs_margin_bbox_cache.clear();
        self.fs_upload_backlog.clear();

        // in-flight pending (idx-keyed) をキャンセル
        for (cancel, _, _) in self.fs_pending.values() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.fs_pending.clear();
        for (cancel, _) in self.ai_upscale_pending.values() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.ai_upscale_pending.clear();
        self.cancel_all_erase_inpaint_pending();

        // auto_aspect.samples は idx キーなので、items の削除/差替えで idx が
        // 変わると古い比率や消えた item の比率が残る (Codex P3 2026-05)。
        // 削除は稀 + 新規 Loaded ですぐ復旧するので、簡単のため samples と
        // streak を全クリアする。`current` / `switches_done` / `last_switch_at`
        // は同じフォルダ内の継続性として残す (= 差替え経路でも一度確定した
        // 自動比率が消えない)。
        self.auto_aspect.samples.clear();
        self.auto_aspect.streak = None;

        // タグプリウォーム: idx-keyed な queued 集合 + worker handle。worker は旧 idx の
        // 画像パスを参照し続けるので、items 差し替え・削除のどちらでも取り消す。
        // 再 spawn は呼び出し元 (replace_search_view_items / 削除まとめ後) の責務。
        if let Some(pending) = self.tag_prewarm_pending.take() {
            pending.cancel();
        }
        self.tag_prewarm_queued.clear();
        if let Some(pending) = self.tag_legacy_seed_pending.take() {
            pending.cancel();
        }

        // キューに残った旧 idx リクエストを排水。items_gen 差異で最終的には破棄されるが、
        // worker が pop した直後は decode を走らせ始めてしまうので、明示的に捨てる。
        if let Some(ref q) = self.reload_queue {
            if let Ok(mut guard) = q.0.lock() {
                guard.clear();
            }
        }
        if let Some(ref q) = self.heavy_io_queue {
            if let Ok(mut guard) = q.0.lock() {
                guard.clear();
            }
        }
    }

    /// 現在の `items` に対して、idx-keyed なページ編集状態 (画像補正の個別パラメータ /
    /// ローカル調整レイヤー / 最終段 crop / 表示トリム個別設定 / 消しゴムマスク /
    /// 隠蔽マスク) を一旦 clear し、DB から再 hydrate する。
    ///
    /// `load_folder` (= `start_loading_items`) の hydration ブロック (perf イベント
    /// `sli_adjustment_db` / `sli_local_adjust_db` / `sli_export_crop_db` / mask / conceal)
    /// と同じ対象マップを使う。補正レイヤーは `local_adjust_pages` のキー存在だけを
    /// hydrate し、巨大な JSON 本体はフルスクリーン表示側で遅延ロードする。**あちらを
    /// 変えたらこちらも揃えること** (= 同期漏れ防止。snapshot 経路だけ古い hydration を
    /// 引きずると Codex P1 が再発する)。
    ///
    /// 用途: ★固定 (snapshot) の activate / deactivate / list 復帰のように、`load_folder` を
    /// 通さずに `items` を差し替える経路。これらで呼ばないと、差し替え前 idx に紐付いた補正・
    /// マスクが新しい items の別ページに乗る (Codex P1)。補正・マスク等の編集は `set_page_params`
    /// 等が DB に同期保存するので、DB から読み直せば snapshot 中の編集も反映される。
    ///
    /// `prefix_path` は DB prefix クエリに使うフォルダ / ZIP / PDF パス (= snapshot origin)。
    /// 検索 view 由来 snapshot のように prefix が合成 path / cross-folder の場合は DB が空ヒット
    /// になり、マップは空のまま (= 検索 view は元々ページ編集状態を持たない設計と整合)。
    ///
    /// `local_adjust_selected_layers` は DB を持たない UI 選択状態なので clear のみ
    /// (load_folder と同じ。再選択時に 0 始まりで復元される)。
    /// idx-keyed なページ編集状態 (補正の個別パラメータ / ローカル調整レイヤー + 選択 idx /
    /// 最終段 crop / 表示トリム個別設定 / 消しゴムマスク / 隠蔽マスクのバッジ集合) を
    /// 全 clear する。
    ///
    /// `rehydrate_page_edit_state_for_current_items` の clear 段であり、
    /// 「ページ編集 overlay を出さない」べき経路 (= 検索 view 由来 snapshot や
    /// `replace_search_view_items`) からも単独で呼ぶ。**ここに列挙するマップ集合が
    /// idx-keyed ページ編集状態の正準リスト**。新しい idx-keyed ページ編集マップを足したら
    /// ここと `remove_items_batch` の shift 群の両方に追加すること。bundle 外の native pending
    /// (`native_video_source_swap_pending` / `native_video_open_pending` /
    /// `native_video_fast_swap_pending` / `video_tile_swap_pending`) も owner=None の mounted 所有だけ
    /// 同じ shift 群へ追加すること (review-v2.3.0 追補3: 角度A-1)。
    pub(crate) fn clear_page_edit_state(&mut self) {
        self.adjustment_page_params.clear();
        self.local_adjust_page_layers.clear();
        self.local_adjust_pages.clear();
        self.local_adjust_selected_layers.clear();
        self.export_crop_page_settings.clear();
        self.export_crop_pages.clear();
        self.view_trim_page_apply_root_idx = None;
        self.view_trim_page_spread_separate = self.view_trim_book_settings.spread_separate;
        self.persist_pending_view_trim_state();
        self.view_trim_page_overrides.clear();
        self.view_trim_dirty_page_overrides.clear();
        self.mask_pages.clear();
        self.conceal_pages.clear();
        self.comic_pages.clear();
        // 進行中のスタンプ埋め込み worker は別フォルダ/別ページへ移ったので破棄 (R2-6)。
        if let Some(p) = self.stamp_embed_pending.take() {
            p.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
    }

    fn hydrate_local_adjust_layer_keys_for_current_items(&mut self) {
        self.local_adjust_page_layers.clear();
        self.local_adjust_pages.clear();
        self.local_adjust_selected_layers.clear();

        let key_by_idx = (0..self.items.len())
            .filter_map(|idx| self.page_path_key(idx).map(|key| (idx, key)))
            .collect::<Vec<_>>();
        if key_by_idx.is_empty() {
            return;
        }

        let Some(db) = &self.local_adjust_db else {
            return;
        };
        let keys = key_by_idx
            .iter()
            .map(|(_, key)| key.clone())
            .collect::<Vec<_>>();
        let existing = db.load_existing_layer_keys(&keys);
        if existing.is_empty() {
            return;
        }

        for (idx, key) in key_by_idx {
            if existing.contains(&key) {
                self.local_adjust_pages.insert(idx);
            }
        }
    }

    pub(crate) fn load_local_adjust_layers_for_book_snapshot_sync(&mut self, idx: usize) -> bool {
        if self.local_adjust_page_layers.contains_key(&idx) {
            return true;
        }
        if !self.local_adjust_pages.contains(&idx) {
            return false;
        }

        let Some(key) = self.page_path_key(idx) else {
            self.local_adjust_pages.remove(&idx);
            self.local_adjust_selected_layers.remove(&idx);
            return false;
        };
        let Some(layers) = self
            .local_adjust_db
            .as_ref()
            .and_then(|db| db.get_layers(&key))
        else {
            self.local_adjust_pages.remove(&idx);
            self.local_adjust_selected_layers.remove(&idx);
            Self::set_page_key_presence(&mut self.local_adjust_page_keys, &key, false);
            return false;
        };

        let loaded = !layers.is_empty();
        self.set_local_adjust_layers_for_idx_memory_only_inner(idx, layers);
        loaded
    }

    pub(crate) fn rehydrate_page_edit_state_for_current_items(
        &mut self,
        prefix_path: &std::path::Path,
    ) {
        self.clear_page_edit_state();

        let prefix = crate::adjustment_db::normalize_path(prefix_path);

        if let Some(db) = &self.adjustment_db {
            let page_map = db.load_page_params(&prefix);
            if !page_map.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if let Some(params) = page_map.get(&key) {
                            self.adjustment_page_params.insert(idx, params.clone());
                        }
                    }
                }
            }
        }
        self.hydrate_local_adjust_layer_keys_for_current_items();
        if let Some(db) = &self.export_crop_db {
            let page_map = db.load_by_prefix(&prefix);
            if !page_map.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if let Some(settings) = page_map.get(&key) {
                            self.export_crop_page_settings.insert(idx, *settings);
                            self.export_crop_pages.insert(idx);
                        }
                    }
                }
            }
        }
        self.hydrate_view_trim_page_overrides_for_current_items();
        if let Some(db) = &self.mask_db {
            let mask_keys = db.load_mask_keys(&prefix);
            if !mask_keys.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if mask_keys.contains(&key) {
                            self.mask_pages.insert(idx);
                        }
                    }
                }
            }
        }
        if let Some(db) = &self.conceal_db {
            let conceal_keys = db.load_conceal_keys(&prefix);
            if !conceal_keys.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if conceal_keys.contains(&key) {
                            self.conceal_pages.insert(idx);
                        }
                    }
                }
            }
        }
        if let Some(db) = &self.comic_db {
            let comic_keys = db.load_comic_keys(&prefix);
            if !comic_keys.is_empty() {
                for idx in 0..self.items.len() {
                    if let Some(key) = self.page_path_key(idx) {
                        if comic_keys.contains(&key) {
                            self.comic_pages.insert(idx);
                        }
                    }
                }
            }
        }
    }

    /// 複数 idx をまとめて items から取り除く共通ルーチン。
    ///
    /// `sorted_desc_idxs` は降順ソート済み・重複なしの idx 配列を期待する。
    /// 大量削除 (★1 画像数千件一括削除など) で 1 件ずつ処理すると
    /// `adjustment_page_params` の再構築が O(N·M) になってしまうため、
    /// `partition_point` を使った O(K log K) の idx shift で一括処理する。
    ///
    /// 事前条件: `sorted_desc_idxs` は降順・重複なし・すべて `self.items.len()` 未満。
    pub(crate) fn remove_items_batch(&mut self, sorted_desc_idxs: &[usize]) {
        if sorted_desc_idxs.is_empty() {
            return;
        }
        let previous_items_generation = self.items_generation;
        let removed_snapshot_paths: Vec<std::path::PathBuf> = sorted_desc_idxs
            .iter()
            .filter_map(|&i| {
                self.items
                    .get(i)
                    .and_then(GridItem::drag_source_path)
                    .map(std::path::Path::to_path_buf)
            })
            .collect();

        // 各残存 old_idx に対する new_idx を partition_point で O(log K) 算出。
        let mut sorted_asc: Vec<usize> = sorted_desc_idxs.to_vec();
        sorted_asc.sort_unstable();
        let shift = |old: usize| -> Option<usize> {
            let p = sorted_asc.partition_point(|&x| x < old);
            if sorted_asc.get(p) == Some(&old) {
                return None;
            }
            Some(old - p)
        };

        // 再生中の動画/音声 player は明示的に old idx -> new idx へ移して温存する。
        // 新世代への bump より前に owner から取り出し、後段の invalidate 後に刻み直す。
        let preserved_video_entries: Vec<(usize, FsCacheEntry)> = self
            .fs_cache
            .take_values()
            .into_iter()
            .filter(|(_, entry)| matches!(entry, FsCacheEntry::Video { .. }))
            .filter_map(|(i, entry)| shift(i).map(|ni| (ni, entry)))
            .collect();

        // 物理 shift: 降順なので items.remove(i) の再 shift は発生しない。
        for &i in sorted_desc_idxs {
            if i < self.items.len() {
                self.items.remove(i);
            }
            if i < self.thumbnails.len() {
                self.thumbnails.remove(i);
            }
            if i < self.image_metas.len() {
                self.image_metas.remove(i);
            }
        }
        self.bump_items_generation();
        self.remove_paths_from_subfolder_expansion_snapshot(&removed_snapshot_paths);
        self.remove_paths_from_smart_folder_snapshots(&removed_snapshot_paths);

        self.grid_click_selection_anchor = self
            .grid_click_selection_anchor
            .and_then(|anchor| anchor.index_for_generation(previous_items_generation))
            .and_then(shift)
            .map(|index| GridClickSelectionAnchor::new(index, self.items_generation));

        if let Some(ref mut filter) = self.search_filter {
            let new_filter: std::collections::HashSet<usize> =
                filter.iter().filter_map(|&i| shift(i)).collect();
            *filter = new_filter;
        }

        // adjustment_page_params / mask_pages / conceal_pages は DB 復元済みの
        // ユーザ設定なので clear せず idx shift で残存ページの分を保持する。
        self.adjustment_page_params = std::mem::take(&mut self.adjustment_page_params)
            .into_iter()
            .filter_map(|(i, v)| shift(i).map(|ni| (ni, v)))
            .collect();
        self.local_adjust_page_layers = std::mem::take(&mut self.local_adjust_page_layers)
            .into_iter()
            .filter_map(|(i, v)| shift(i).map(|ni| (ni, v)))
            .collect();
        self.local_adjust_pages = self
            .local_adjust_pages
            .iter()
            .filter_map(|&i| shift(i))
            .collect();
        // 選択中レイヤー idx も同じ old→new マッピングで shift する。抜けると削除後に
        // 別ページへ古い選択状態が乗る / 対象ページが選択を失う (Codex P2)。
        // `set_local_adjust_layers_for_idx_memory_only_inner` が
        // local_adjust_page_layers / local_adjust_pages / local_adjust_selected_layers を
        // セットで更新する不変条件に合わせる。値 (選択 layer idx) は削除でそのページの
        // layer 配列が変わらないので基本そのまま有効だが、念のため shift 済みの
        // local_adjust_page_layers の残存数で clamp する。
        self.local_adjust_selected_layers = std::mem::take(&mut self.local_adjust_selected_layers)
            .into_iter()
            .filter_map(|(i, sel)| {
                shift(i).map(|ni| {
                    let cap = self
                        .local_adjust_page_layers
                        .get(&ni)
                        .map(|layers| layers.len().saturating_sub(1))
                        .unwrap_or(0);
                    (ni, sel.min(cap))
                })
            })
            .collect();
        self.export_crop_page_settings = std::mem::take(&mut self.export_crop_page_settings)
            .into_iter()
            .filter_map(|(i, v)| shift(i).map(|ni| (ni, v)))
            .collect();
        self.export_crop_pages = self
            .export_crop_pages
            .iter()
            .filter_map(|&i| shift(i))
            .collect();
        self.view_trim_page_overrides = std::mem::take(&mut self.view_trim_page_overrides)
            .into_iter()
            .filter_map(|(i, v)| shift(i).map(|ni| (ni, v)))
            .collect();
        self.view_trim_dirty_page_overrides = self
            .view_trim_dirty_page_overrides
            .iter()
            .filter_map(|&i| shift(i))
            .collect();
        self.view_trim_page_apply_root_idx = self.view_trim_page_apply_root_idx.and_then(shift);
        if self.view_trim_page_apply_root_idx.is_none() {
            self.view_trim_page_spread_separate = self.view_trim_book_settings.spread_separate;
        }
        self.mask_pages = self.mask_pages.iter().filter_map(|&i| shift(i)).collect();
        self.conceal_pages = self
            .conceal_pages
            .iter()
            .filter_map(|&i| shift(i))
            .collect();
        self.comic_pages = self.comic_pages.iter().filter_map(|&i| shift(i)).collect();
        let shifted_thumb_pixels = std::mem::take(&mut self.thumb_pixels)
            .into_iter()
            .filter_map(|(i, v)| {
                shift(i)
                    .filter(|&ni| {
                        ni < self.items.len() && is_thumb_adjust_target(self.items.get(ni))
                    })
                    .map(|ni| (ni, v))
            })
            .collect();
        let shifted_thumb_layers = std::mem::take(&mut self.thumb_edit_preview_layers)
            .into_iter()
            .filter_map(|(i, layers)| {
                shift(i)
                    .filter(|&ni| {
                        ni < self.items.len() && is_thumb_adjust_target(self.items.get(ni))
                    })
                    .map(|ni| (ni, layers))
            })
            .collect();
        let shifted_thumb_preview_keys = std::mem::take(&mut self.thumb_edit_preview_keys)
            .into_iter()
            .filter_map(|(i, key)| shift(i).map(|ni| (ni, key)))
            .collect();

        // selected の詰め動作: `sel - count(removed idx < sel)` は残存 / 削除どちらの
        // ケースでも「old idx の位置に収まる新 idx」(= 繰り上がった次 item) を返す。
        //   - sel が残存: new_idx = sel - p (shift と同じ)
        //   - sel が削除対象: そのスロットは次の surviving item が詰まるので同じく sel - p
        // 末尾を削除したケース (sel - p が新 len を超える) は後続の `sel >= n` clamp で
        // n-1 にフォールバックする。
        // 例: [a,b,c,d,e,f] で selected=3(d), 削除=[1,3] → p=1, new_sel = 3-1 = 2 = e。
        self.selected = self
            .selected
            .map(|sel| sel - sorted_asc.partition_point(|&x| x < sel));

        // ── フルスクリーン / 音声モードの viewer 状態も shift する (review-v2.3.0 P2-2) ──
        // detached / マルチウィンドウでは「別窓で視聴中にメイン窓グリッドから削除」が一級
        // フローになり、shift しないと視聴中 idx が削除後に別のアイテムを指す (表示のズレ +
        // レーティング等 idx ベース操作の誤適用)。視聴中アイテム自体が削除された場合は
        // selected と同じ「次の残存アイテムが詰まる」規則で送り、全消えなら None
        // (= 既存の `fullscreen_idx.is_none()` クリーンアップ経路がビューポートを閉じる)。
        if let Some(old) = self.fullscreen_idx {
            self.fullscreen_idx = match shift(old) {
                Some(ni) => Some(ni),
                None => {
                    let slid = old - sorted_asc.partition_point(|&x| x < old);
                    fullscreen_neighbor_after_removal(&self.items, slid)
                }
            };
        }
        // 音声モード系の idx-keyed 状態は対象アイテムが残存したときだけ追随し、消えたら畳む
        // (fullscreen_idx と同じ p で shift されるので、残存時は相互一致が保たれる)。
        self.video_audio_mode = self.video_audio_mode.and_then(shift);
        self.video_audio_vst = self.video_audio_vst.take().and_then(|mut s| {
            shift(s.fs_idx).map(|ni| {
                s.fs_idx = ni;
                s
            })
        });
        #[cfg(windows)]
        {
            self.video_audio_exit_pending =
                self.video_audio_exit_pending.take().and_then(|mut p| {
                    shift(p.fs_idx).map(|ni| {
                        p.fs_idx = ni;
                        p
                    })
                });
            if self.video_audio_mode.is_none() {
                self.video_audio_mode_entry_target = None;
            }
        }
        #[cfg(windows)]
        let detached_media_owns_global_indices = self
            .active_detached_viewer_context_contains_video()
            || self.parked_live_media_window_exists();
        #[cfg(not(windows))]
        let detached_media_owns_global_indices = false;
        // active promoted は owner=None、ParkedLive は bundle mount 時だけ global EOF state を使う。
        // いずれも fs_idx は bundle 空間なので、main items の削除では shift しない。
        // メディア窓 1 本規則により、この間に mounted main media の EOF state は併存しない。
        // (review-v2.3.0 追補6: R2-P2-1 media index ownership)
        if !detached_media_owns_global_indices {
            self.video_continuous_last_eof = self
                .video_continuous_last_eof
                .and_then(|(i, serial)| shift(i).map(|ni| (ni, serial)));
        }
        // 音量ノーマライズ / ループ位置の idx-keyed 状態も同様に shift (Codex fix-review P2)。
        self.normalize_ui_states = std::mem::take(&mut self.normalize_ui_states)
            .into_iter()
            .filter_map(|(i, v)| shift(i).map(|ni| (ni, v)))
            .collect();
        self.normalize_auto_scan_suppressed = self
            .normalize_auto_scan_suppressed
            .iter()
            .filter_map(|&i| shift(i))
            .collect();
        self.last_loop_pos = std::mem::take(&mut self.last_loop_pos)
            .into_iter()
            .filter_map(|(i, v)| shift(i).map(|ni| (ni, v)))
            .collect();
        // 進行中の音量スキャンは対象が残存すれば fs_idx を追随させる (完了側は
        // fs_idx + file_path で検証するので、追随しないと無関係アイテムの削除のたびに
        // 完了結果が stale 扱いになり、再生再開 / preroll 解除 / gain 反映が落ちる)。
        // 対象自体が削除されたら worker を cancel して畳む (player も fs_cache から
        // 消えるので preroll suspend の解除は不要)。
        // normalize_state も App-global だが、active promoted / ParkedLive の poll 中は bundle の
        // fs_idx を保持する。path 所有は teardown 側で照合するため main 削除では触らない。
        if !detached_media_owns_global_indices {
            if let Some(mut st) = self.normalize_state.take() {
                match shift(st.fs_idx) {
                    Some(ni) => {
                        st.fs_idx = ni;
                        self.normalize_state = Some(st);
                    }
                    None => {
                        st.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
                    }
                }
            }
        }
        // 音声 VST シェル (プレーン音声の presenter 流用): 対象が残存すれば fs_idx を追随、
        // 対象自体が削除されたら正規手順 (exit_music_vst_shell) で GUI/owner ごと畳む
        // (state だけ落とすと VST GUI が孤児 owner のまま残る)。teardown は下の fs_cache
        // take より前に行うこと (exit が対象 player から native output を外すため、
        // fs_cache に旧 idx の entry が残っている必要がある)。(Codex fix-review2 P2)
        #[cfg(windows)]
        if let Some(cur) = self.music_vst_shell.as_ref().map(|s| s.fs_idx) {
            match shift(cur) {
                Some(ni) => {
                    if let Some(shell) = self.music_vst_shell.as_mut() {
                        shell.fs_idx = ni;
                    }
                }
                None => self.exit_music_vst_shell(),
            }
        }
        // VST3 起動待ちで保留中のメディア open も追随 (再開側が fullscreen_idx 一致を
        // 要求するため、shift しないと保留 open が黙って失われる)。対象削除なら None。
        #[cfg(windows)]
        {
            self.vst3_deferred_media_open = self.vst3_deferred_media_open.and_then(shift);
            // owner=None は mounted と promoted active の二義。active bundle が存在する間は
            // 4 pending の idx 空間も bundle 側なので main items の削除では shift しない。
            // ParkedLive pending は owner=Some(window_id) の既存 gate で別途守られる。
            let shift_ownerless_native_pending =
                !self.active_detached_viewer_context_contains_video();
            // bundle 外の native pending 4 種も、現在 mount 中の context 所有 (owner=None)
            // だけ main items の old→new idx へ追随させる。owner=Some(window_id) は ParkedLive
            // bundle 内 items の idx 空間なので、main grid の削除では絶対に動かさない。
            // (review-v2.3.0 追補3: 角度A-1)
            let discard_source_swap =
                self.native_video_source_swap_pending
                    .as_ref()
                    .is_some_and(|pending| {
                        pending.parked_live_window_id.is_none()
                            && shift_ownerless_native_pending
                            && shift(pending.target_idx).is_none()
                    });
            if discard_source_swap {
                if let Some(pending) = self.native_video_source_swap_pending.take() {
                    // source-swap は presenter を pending.native_output だけで保持するため、
                    // state を単に drop せず close_fullscreen と同じ overlay 後始末を通す。
                    pending.native_output.set_navigation_preview(None);
                    if pending.reason == "tile" {
                        self.video_tile_state = None;
                        self.video_tile_mode_active = false;
                        self.video_tile_reopen_pending = false;
                        self.video_tile_reopen_deadline = None;
                    }
                }
            } else if let Some(pending) = self.native_video_source_swap_pending.as_mut()
                && pending.parked_live_window_id.is_none()
                && shift_ownerless_native_pending
            {
                // from_idx は完了ログ用の provenance で、旧 source 自体が削除されても target
                // が残る限り swap は継続できる。削除スロットへ詰まった位置に collapse する。
                let collapsed_from =
                    pending.from_idx - sorted_asc.partition_point(|&x| x < pending.from_idx);
                pending.from_idx = shift(pending.from_idx)
                    .unwrap_or_else(|| collapsed_from.min(self.items.len().saturating_sub(1)));
                pending.target_idx =
                    shift(pending.target_idx).expect("source-swap target removal handled above");
            }

            let discard_open = self
                .native_video_open_pending
                .as_ref()
                .is_some_and(|pending| {
                    pending.parked_live_window_id.is_none()
                        && shift_ownerless_native_pending
                        && shift(pending.idx).is_none()
                });
            if discard_open {
                self.native_video_open_pending = None;
            } else if let Some(pending) = self.native_video_open_pending.as_mut()
                && pending.parked_live_window_id.is_none()
                && shift_ownerless_native_pending
            {
                pending.idx = shift(pending.idx).expect("native open target removal handled above");
            }

            let discard_fast =
                self.native_video_fast_swap_pending
                    .as_ref()
                    .is_some_and(|pending| {
                        pending.parked_live_window_id.is_none()
                            && shift_ownerless_native_pending
                            && shift(pending.target_idx).is_none()
                    });
            if discard_fast {
                self.native_video_fast_swap_pending = None;
                // deferred delta は fast/tile pending の companion。pending だけ落として残すと
                // 別 context の poll が取り出すため、同時に破棄する (追補3: 角度A-2)。
                self.native_video_deferred_nav_delta = None;
            } else if let Some(pending) = self.native_video_fast_swap_pending.as_mut()
                && pending.parked_live_window_id.is_none()
                && shift_ownerless_native_pending
            {
                pending.target_idx =
                    shift(pending.target_idx).expect("fast-swap target removal handled above");
            }

            let discard_tile = self
                .video_tile_swap_pending
                .as_ref()
                .is_some_and(|pending| {
                    pending.parked_live_window_id.is_none()
                        && shift_ownerless_native_pending
                        && shift(pending.target_idx).is_none()
                });
            if discard_tile {
                self.video_tile_swap_pending = None;
                self.video_tile_state = None;
                self.video_tile_mode_active = false;
                self.video_tile_reopen_pending = false;
                self.video_tile_reopen_deadline = None;
                self.native_video_deferred_nav_delta = None;
            } else if let Some(pending) = self.video_tile_swap_pending.as_mut()
                && pending.parked_live_window_id.is_none()
                && shift_ownerless_native_pending
            {
                pending.target_idx =
                    shift(pending.target_idx).expect("tile-swap target removal handled above");
            }
        }

        self.invalidate_idx_state_and_queues();
        self.fs_cache.extend(preserved_video_entries);
        // Loaded のサムネイル本体は Vec::remove で残るため、補正用 source も同じ
        // idx shift で残す。補正済み TextureHandle は invalidate 後に再生成させる。
        self.thumb_pixels = shifted_thumb_pixels;
        self.thumb_edit_preview_layers = shifted_thumb_layers;
        self.thumb_edit_preview_keys = shifted_thumb_preview_keys;

        let n = self.items.len();
        if n == 0 {
            self.selected = None;
        } else if let Some(sel) = self.selected {
            if sel >= n {
                self.selected = Some(n - 1);
            }
        }

        self.rebuild_visible_indices();

        // auto_aspect: invalidate で samples を全クリアしたが、削除後も残存 thumbnails
        // (= 削除されなかった item の Loaded サムネ) がある。Auto モードならそれらから
        // samples を再構築する (Codex P3 2026-05)。
        if self.settings.thumb_aspect_auto {
            self.rebuild_auto_aspect_samples_from_loaded();
            self.maybe_apply_auto_aspect(false);
        }
    }

    /// 削除 / リネームで消える path を表示・再生中の viewer サーフェス (メイン fullscreen /
    /// active detached / passive・parked detached 窓) を閉じる (review-v2.3.0 角度④ (A)(B)
    /// の最小対応)。
    ///
    /// - **削除は shell 操作の前に呼ぶ**: 再生中 decoder が file handle を掴んだままだと
    ///   ゴミ箱移動が共有違反で失敗し続けるため (B)。削除確認ダイアログ通過後に呼ぶので、
    ///   その後の削除失敗で窓だけ閉じ損になるケースは許容する。
    /// - **リネームは成功後に旧 path で呼ぶ**: parked bundle が旧 path のまま生き残ると、
    ///   再生位置の書き戻しやメタデータ書込が旧名キーへ流れるため (A)。
    /// - フォルダ / ZIP / PDF コンテナは配下 (`<key>/…`) とアーカイブ内エントリ
    ///   (`<key>::…`) のプレフィックス一致でも閉じる。
    /// - bundle に「含まれるだけで表示していない」アイテムは閉じない (再活性化時の
    ///   `resolve_viewer_sync_stamp_idx` が fail-safe に空振る既存動作に任せる)。
    pub(crate) fn release_viewer_surfaces_for_removed_paths(
        &mut self,
        ctx: &egui::Context,
        removed: &[std::path::PathBuf],
        reason: &'static str,
    ) {
        if removed.is_empty() {
            return;
        }
        let matches_key = removed_path_key_matcher(removed);

        // メイン fullscreen は「再生中の VideoPlayer が対象 path を掴んでいる」ときだけ
        // 閉じる (fs_cache clear で player が drop され handle が解放される)。静止画は
        // 閉じない: メイン文脈は削除完了後に `remove_items_batch` が fullscreen_idx を
        // 隣へスライドする既存の再整合を持つので、閲覧継続の UX を維持する
        // (窓を閉じるのは再整合を持たない detached/parked bundle 側だけ)。
        if let Some(idx) = self.fullscreen_idx {
            let player_matches = matches!(
                self.fs_cache.get(&idx),
                Some(FsCacheEntry::Video { player, .. })
                    if matches_key(&crate::adjustment_db::normalize_path(player.path()))
            );
            // player 作成前でも、表示 item 自体が削除対象の media で、かつ VST3/native open
            // 待ちなら handle 取得競合前に同じ close 経路へ入れる。静止画は従来どおり
            // remove_items_batch の隣接再整合へ任せる (review-v2.3.0 追補3: 角度A-3)。
            #[cfg(windows)]
            let deferred_media_matches = self
                .items
                .get(idx)
                .and_then(grid_item_media_path)
                .is_some_and(|item_path| {
                    if !matches_key(&crate::adjustment_db::normalize_path(item_path)) {
                        return false;
                    }
                    let vst_waiting = self.vst3_deferred_media_open == Some(idx);
                    let native_waiting = !self.active_detached_viewer_context_contains_video()
                        && self
                            .native_video_open_pending
                            .as_ref()
                            .is_some_and(|pending| {
                                pending.parked_live_window_id.is_none()
                                    && pending.idx == idx
                                    && crate::folder_tree::path_eq(&pending.path, item_path)
                                    && matches_key(&crate::adjustment_db::normalize_path(
                                        &pending.path,
                                    ))
                            });
                    vst_waiting || native_waiting
                });
            #[cfg(not(windows))]
            let deferred_media_matches = false;
            if player_matches || deferred_media_matches {
                crate::logger::log(format!(
                    "[removed-path] close main fullscreen (playing/deferred media target) \
                     reason={reason} player={player_matches} deferred={deferred_media_matches}"
                ));
                self.close_fullscreen();
            }
        }

        #[cfg(windows)]
        {
            // active detached (live bundle) が対象を表示 / 再生中なら閉じる。
            let active_matches = self
                .active_detached_viewer_context
                .as_ref()
                .is_some_and(|c| viewer_bundle_references_removed(&c.bundle, &matches_key));
            if active_matches {
                crate::logger::log(format!(
                    "[removed-path] close active detached reason={reason}"
                ));
                self.close_current_active_detached_viewer_context(ctx);
            }

            // passive / parked 窓 (parked-live メディア含む)。ctx 不要の close 経路
            // (`close_parked_live_media_windows_for_new_media` と同じ手順) で閉じる。
            let ids: Vec<u64> = self
                .detached_image_windows
                .iter()
                .filter(|w| detached_window_references_removed(w, &matches_key))
                .map(|w| w.id)
                .collect();
            if !ids.is_empty() {
                self.log_detached_image_window_debug(format!(
                    "close_for_removed_path ids={ids:?} reason={reason}"
                ));
                for id in &ids {
                    self.transition_detached_window_state(
                        *id,
                        DetachedWindowState::Closing,
                        reason,
                    );
                    self.detached_image_window_close_pending.push(*id);
                    self.clear_detached_window_hwnd_for_window_id(*id);
                }
                // passive/parked の直接 retain-drop でも共通 teardown seam を通し、最終
                // resume を保存してから rename の path 移行へ渡す (review-v2.3.0 追補3: A-4)。
                self.teardown_paused_media_bundles_for_window_ids(&ids, reason);
                self.detached_image_windows
                    .retain(|window| !ids.contains(&window.id));
                for id in ids {
                    self.remove_detached_window_runtime(id, reason);
                }
                self.prune_deferred_detached_image_window_views();
            }
        }
        #[cfg(not(windows))]
        let _ = ctx;

        // ラウドネス測定 (音量スキャン) ワーカーも App-global で対象ファイルを開いている。
        // parked bundle の close は `cleanup_normalize_state_for_fs_idx` を通らないため、
        // 削除対象をスキャン中なら path 一致で cancel する (Sol 角度④検収 P2 その2。
        // fs_idx は文脈依存なので使わない)。
        if self
            .normalize_state
            .as_ref()
            .is_some_and(|st| matches_key(&crate::adjustment_db::normalize_path(&st.file_path)))
        {
            if let Some(st) = self.normalize_state.take() {
                crate::logger::log(format!(
                    "[removed-path] cancel normalize scan reason={reason}"
                ));
                st.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
            }
        }

        // 音楽解析ワーカーは bundle 所有ではなく App-global で、対象ファイルを FFmpeg decode
        // 用に開いている。窓や player を閉じても解析側の handle は残るため、削除対象が解析中
        // ならここで破棄する (Sol 角度④検収 P2)。解析はキャンセル可 (decode 毎パケット +
        // 解析 bin/FFT 窓単位) なので handle は数 ms で閉じる。窓 close の後に呼ぶこと
        // (現在ビューの teardown 順を既存経路と揃えるため)。
        let current_analysis_matches = self
            .music_analysis_path
            .as_deref()
            .is_some_and(|p| matches_key(&crate::adjustment_db::normalize_path(p)));
        if current_analysis_matches {
            crate::logger::log(format!(
                "[removed-path] clear music view state reason={reason}"
            ));
            self.clear_music_view_state();
        } else if self
            .music_analysis_pending
            .as_ref()
            .is_some_and(|p| matches_key(&crate::adjustment_db::normalize_path(&p.path)))
        {
            // 現在ビューは別ファイルだが、走行中ワーカーが削除対象を開いているケース
            // (連続切替直後など)。ビュー状態には触れず解析だけ止める。
            crate::logger::log(format!(
                "[removed-path] cancel stale music analysis reason={reason}"
            ));
            self.cancel_music_analysis();
        }
    }

    /// 削除 (成功分) / リネーム (旧 path) に対応する動画再生位置の記録を破棄する
    /// (角度④ (A): 消えた path のキーで resume が残る / 書き戻されるのを防ぐ)。
    /// フォルダ / コンテナの削除は配下キーもまとめて落とす。
    pub(crate) fn purge_video_resume_positions_for_removed_paths(
        &mut self,
        removed: &[std::path::PathBuf],
    ) {
        if removed.is_empty() {
            return;
        }
        let matches_key = removed_path_key_matcher(removed);
        self.settings
            .video_resume_positions
            .retain(|key, _| !matches_key(key));
        #[cfg(windows)]
        self.video_resume_thumb_last_request
            .retain(|key, _| !matches_key(key));
    }

    /// delete worker が hard purge 済みの path に合わせて、DB を再読込せず App-global の
    /// presence set / path cache を同じ exact + `/` + `::` 規則で整合させる。
    fn purge_in_memory_metadata_for_removed_paths(
        &mut self,
        removed: &[std::path::PathBuf],
        purged_pdf_password_paths: &[std::path::PathBuf],
    ) {
        let matches_key = removed_path_key_matcher(removed);

        self.rating_cache.clear();
        self.rotation_cache.clear();
        self.current_folder_rating_cache = None;
        self.invalidate_rating_counts_cache();
        self.reset_folder_rating_counts();
        self.retain_tags_cache(|key| !matches_key(key));
        self.rating_session_writes
            .retain(|key, _| !matches_key(key));
        self.folder_pin_map.retain(|key, _| !matches_key(key));
        self.search_drilled_folder_counts
            .retain(|key, _| !matches_key(key));
        self.reading_history_rows.retain(|key, _| !matches_key(key));
        self.rating_view_rows.retain(|row| !matches_key(&row.key));

        for set in [
            &mut self.adjusted_page_keys,
            &mut self.local_adjust_page_keys,
            &mut self.mask_page_keys,
            &mut self.conceal_page_keys,
            &mut self.comic_page_keys,
            &mut self.rotation_page_keys,
        ] {
            set.retain(|key| !matches_key(key));
        }

        if self
            .fullscreen_video_marker_cache
            .as_ref()
            .is_some_and(|cache| matches_key(&crate::adjustment_db::normalize_path(&cache.path)))
        {
            self.fullscreen_video_marker_cache = None;
            self.cancel_fullscreen_video_marker_thumb_decode();
        }
        if self
            .music_bookmarks_loaded_for
            .as_ref()
            .is_some_and(|path| matches_key(&crate::adjustment_db::normalize_path(path)))
        {
            self.music_bookmarks.clear();
            self.music_bookmarks_loaded_for = None;
        }
        if self
            .last_book_resume
            .as_ref()
            .is_some_and(|(path, _)| matches_key(&crate::adjustment_db::normalize_path(path)))
        {
            self.last_book_resume = None;
        }
        if self
            .last_reading_history_touch
            .as_ref()
            .is_some_and(|(key, _)| matches_key(key))
        {
            self.last_reading_history_touch = None;
        }
        if self
            .reading_history_return_from
            .as_ref()
            .is_some_and(|path| matches_key(&crate::adjustment_db::normalize_path(path)))
        {
            self.reading_history_return_from = None;
        }
        self.video_thumb_overrides_dirty_paths
            .retain(|path| !matches_key(&crate::adjustment_db::normalize_path(path)));
        for path in purged_pdf_password_paths {
            self.pdf_passwords.remove(path);
        }
        for path in removed {
            let (Some(parent), Some(file_name)) = (path.parent(), path.file_name()) else {
                continue;
            };
            if let Some(sidecar) = self.sidecars.get_mut(parent) {
                sidecar.purge_deleted_root(&file_name.to_string_lossy().to_lowercase());
            }
        }
        self.sidecars
            .retain(|folder, _| !matches_key(&crate::adjustment_db::normalize_path(folder)));
        self.invalidate_tag_apply_suggestions();
    }

    /// 終端refreshのcompact indexを全viewer contextから破棄する。
    fn clear_metadata_import_refresh_indexes(&mut self) {
        self.metadata_import_refresh_index = None;
        #[cfg(windows)]
        {
            if let Some(mut active) = self.active_detached_viewer_context.take() {
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.metadata_import_refresh_index = None;
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.active_detached_viewer_context = Some(active);
            }
            for index in 0..self.detached_image_windows.len() {
                let Some(mut bundle) = self.detached_image_windows[index].paused_bundle.take()
                else {
                    continue;
                };
                self.swap_viewer_context_bundle(&mut bundle);
                self.metadata_import_refresh_index = None;
                self.swap_viewer_context_bundle(&mut bundle);
                self.detached_image_windows[index].paused_bundle = Some(bundle);
            }
        }
    }

    /// DB更新終端後の表示cache再取得準備を開始する。
    pub(crate) fn begin_metadata_import_terminal_refresh(&mut self) {
        self.clear_metadata_import_refresh_indexes();
    }

    pub(crate) fn advance_metadata_import_terminal_refresh(
        &mut self,
        import_root: &Path,
        recursive: bool,
        collect_legacy_seed_paths: bool,
    ) -> bool {
        const MAX_ITEMS_PER_FRAME: usize = 2_048;
        const MAX_TIME_PER_FRAME: std::time::Duration = std::time::Duration::from_millis(3);

        let deadline = std::time::Instant::now() + MAX_TIME_PER_FRAME;
        let mut remaining = MAX_ITEMS_PER_FRAME;
        let mut complete = self.advance_current_metadata_import_terminal_index(
            import_root,
            recursive,
            collect_legacy_seed_paths,
            &mut remaining,
            deadline,
        );
        #[cfg(windows)]
        {
            if complete
                && remaining > 0
                && std::time::Instant::now() < deadline
                && let Some(mut active) = self.active_detached_viewer_context.take()
            {
                self.swap_viewer_context_bundle(&mut active.bundle);
                complete = self.advance_current_metadata_import_terminal_index(
                    import_root,
                    recursive,
                    collect_legacy_seed_paths,
                    &mut remaining,
                    deadline,
                );
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.active_detached_viewer_context = Some(active);
            }
            if complete {
                for index in 0..self.detached_image_windows.len() {
                    if remaining == 0 || std::time::Instant::now() >= deadline {
                        complete = false;
                        break;
                    }
                    let Some(mut bundle) = self.detached_image_windows[index].paused_bundle.take()
                    else {
                        continue;
                    };
                    self.swap_viewer_context_bundle(&mut bundle);
                    complete = self.advance_current_metadata_import_terminal_index(
                        import_root,
                        recursive,
                        collect_legacy_seed_paths,
                        &mut remaining,
                        deadline,
                    );
                    self.swap_viewer_context_bundle(&mut bundle);
                    self.detached_image_windows[index].paused_bundle = Some(bundle);
                    if !complete {
                        break;
                    }
                }
            }
        }
        complete
    }

    fn advance_current_metadata_import_terminal_index(
        &mut self,
        import_root: &Path,
        recursive: bool,
        collect_legacy_seed_paths: bool,
        remaining: &mut usize,
        deadline: std::time::Instant,
    ) -> bool {
        let restart = self
            .metadata_import_refresh_index
            .as_ref()
            .is_none_or(|index| {
                index.items_generation != self.items_generation
                    || index.collect_legacy_seed_paths != collect_legacy_seed_paths
            });
        if restart {
            let affected = self.current_folder.as_deref().is_some_and(|path| {
                metadata_import_context_path_is_affected(path, import_root, recursive)
            }) || self.archive_source_override.as_deref().is_some_and(|path| {
                metadata_import_context_path_is_affected(path, import_root, recursive)
            });
            let current_rating_key = self
                .current_container_rating_key_and_source()
                .map(|(key, _)| key);
            let folder_pin_paths = affected
                .then(|| self.folder_pin_context_lookup_paths())
                .unwrap_or_default();
            self.metadata_import_refresh_index = Some(MetadataImportRefreshIndex {
                items_generation: self.items_generation,
                current_rating_key,
                affected,
                complete: !affected || self.items.is_empty(),
                collect_legacy_seed_paths,
                folder_pin_paths,
                legacy_seed_paths: Vec::new(),
                ..MetadataImportRefreshIndex::default()
            });
        }

        let mut index = self
            .metadata_import_refresh_index
            .take()
            .expect("terminal metadata refresh index initialized");
        while index.affected
            && index.next_item < self.items.len()
            && *remaining > 0
            && std::time::Instant::now() < deadline
        {
            let item_index = index.next_item;
            let rating_key = self.rating_path_key(item_index);
            let page_key = self.page_path_key(item_index);
            let had_page_state = page_key.as_deref().is_some_and(|key| {
                self.adjusted_page_keys.contains(key)
                    || self.local_adjust_page_keys.contains(key)
                    || self.mask_page_keys.contains(key)
                    || self.conceal_page_keys.contains(key)
                    || self.comic_page_keys.contains(key)
                    || self.rotation_page_keys.contains(key)
            }) || self.adjustment_page_params.contains_key(&item_index)
                || self.local_adjust_pages.contains(&item_index)
                || self.export_crop_page_settings.contains_key(&item_index)
                || self.view_trim_page_overrides.contains_key(&item_index)
                || self.mask_pages.contains(&item_index)
                || self.conceal_pages.contains(&item_index)
                || self.comic_pages.contains(&item_index)
                || self.rotation_cache.contains_key(&item_index);
            let item = &self.items[item_index];
            let tag_key = tag_item_path(item).map(crate::tags_db::item_key_for_path);
            if index.collect_legacy_seed_paths
                && !self.items_are_global_search_view
                && !self.items_are_tag_view
                && !self.idx_is_compiled_book_page(item_index)
                && let GridItem::Image(path) | GridItem::Video(path) = item
            {
                index.legacy_seed_paths.push(path.clone());
            }
            let folder_pin_target = self.folder_pin_lookup_target_for_item(item);
            let container_path = folder_pin_target.as_ref().map(|target| target.path.clone());
            if let Some(target) = folder_pin_target {
                if let Some(alias) = target.alias {
                    index.folder_pin_aliases.push(alias);
                }
            }
            let (video_path, video_size) = if let GridItem::Video(path) = item {
                let size = self
                    .image_metas
                    .get(item_index)
                    .and_then(|metadata| *metadata)
                    .map(|(_, size)| size.max(0) as u64)
                    .unwrap_or(0);
                (Some(path.clone()), size)
            } else {
                (None, 0)
            };

            if rating_key.is_some()
                || tag_key.is_some()
                || page_key.is_some()
                || container_path.is_some()
                || video_path.is_some()
            {
                let key = rating_key
                    .as_ref()
                    .or(tag_key.as_ref())
                    .or(page_key.as_ref())
                    .cloned()
                    .unwrap_or_default();
                let rating = rating_key.as_deref() == Some(key.as_str());
                let tags = tag_key.as_deref() == Some(key.as_str());
                // rating/tagは重なる物理itemでは同じnormalize_path identityを使う。
                debug_assert!(rating_key.is_none() || rating);
                debug_assert!(tag_key.is_none() || tags);
                let (page, alternate_page_key) = match page_key {
                    Some(page_key) if page_key == key => (true, None),
                    Some(page_key) => (false, Some(page_key)),
                    None => (false, None),
                };
                index.items.push(metadata_import_refresh::ItemKey {
                    index: item_index,
                    key,
                    rating,
                    tags,
                    page,
                    had_page_state,
                    alternate_page_key,
                    container_path,
                    video_path,
                    video_size,
                });
            }
            index.next_item += 1;
            *remaining -= 1;
        }
        index.complete = !index.affected
            || (index.items_generation == self.items_generation
                && index.next_item >= self.items.len());
        let complete = index.complete;
        self.metadata_import_refresh_index = Some(index);
        complete
    }

    pub(crate) fn take_metadata_import_refresh_requests(
        &mut self,
    ) -> Vec<metadata_import_refresh::ContextRequest> {
        fn take_current(
            index: &mut Option<MetadataImportRefreshIndex>,
            slot: metadata_import_refresh::ContextSlot,
            spread_container_path: Option<PathBuf>,
            old_folder_pin_keys: std::collections::HashSet<String>,
        ) -> Option<metadata_import_refresh::ContextRequest> {
            let index = index.take()?;
            (index.complete && index.affected).then_some(metadata_import_refresh::ContextRequest {
                slot,
                items_generation: index.items_generation,
                items: index.items,
                legacy_seed_paths: index.legacy_seed_paths,
                current_rating_key: index.current_rating_key,
                spread_container_path,
                old_folder_pin_keys,
                folder_pin_paths: index.folder_pin_paths,
                folder_pin_aliases: index.folder_pin_aliases,
            })
        }

        let mut requests = Vec::new();
        let spread_path = self.spread_container_key();
        let old_folder_pin_keys = self.folder_pin_map.keys().cloned().collect();
        if let Some(request) = take_current(
            &mut self.metadata_import_refresh_index,
            metadata_import_refresh::ContextSlot::Main,
            spread_path,
            old_folder_pin_keys,
        ) {
            requests.push(request);
        }
        #[cfg(windows)]
        {
            if let Some(mut active) = self.active_detached_viewer_context.take() {
                let window_id = self.active_detached_window_id();
                self.swap_viewer_context_bundle(&mut active.bundle);
                let spread_path = self.spread_container_key();
                let old_folder_pin_keys = self.folder_pin_map.keys().cloned().collect();
                if let Some(request) = take_current(
                    &mut self.metadata_import_refresh_index,
                    metadata_import_refresh::ContextSlot::ActiveDetached(window_id),
                    spread_path,
                    old_folder_pin_keys,
                ) {
                    requests.push(request);
                }
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.active_detached_viewer_context = Some(active);
            }
            for window_index in 0..self.detached_image_windows.len() {
                let window_id = self.detached_image_windows[window_index].id;
                let Some(mut bundle) = self.detached_image_windows[window_index]
                    .paused_bundle
                    .take()
                else {
                    continue;
                };
                self.swap_viewer_context_bundle(&mut bundle);
                let spread_path = self.spread_container_key();
                let old_folder_pin_keys = self.folder_pin_map.keys().cloned().collect();
                if let Some(request) = take_current(
                    &mut self.metadata_import_refresh_index,
                    metadata_import_refresh::ContextSlot::PausedDetached {
                        index: window_index,
                        window_id,
                    },
                    spread_path,
                    old_folder_pin_keys,
                ) {
                    requests.push(request);
                }
                self.swap_viewer_context_bundle(&mut bundle);
                self.detached_image_windows[window_index].paused_bundle = Some(bundle);
            }
        }
        requests
    }

    pub(crate) fn abort_metadata_import_terminal_refresh(&mut self) {
        self.clear_metadata_import_refresh_indexes();
    }

    /// 転送開始前に、現在mount中のcontextが持つmetadata writerを静止させる。
    ///
    /// XMP rating prewarmはファイルread結果をUI pollでDBへ反映するため、handleを取消・破棄
    /// すれば以後書込みを生成しない。legacy seedはworker自身がtags.dbへ書くので取消による
    /// 中途半端な打切りはせず、完了結果をcontextへ適用してhandleが消えるまで待つ。
    fn quiesce_current_metadata_transfer_context_writers(&mut self) -> bool {
        if let Some(pending) = self.tag_prewarm_pending.take() {
            pending.cancel();
        }
        self.tag_prewarm_queued.clear();
        self.poll_tag_legacy_seed_results();
        self.tag_legacy_seed_pending.is_some()
    }

    /// main / active detached / paused detachedの全context writerを静止させる。
    /// importでは全contextのdrain後、App-globalなtag write workerの接続解放も待つ。
    /// `Ok(true)`の間はDB writerまたは接続解放ACKを待つため、転送workerを開始しない。
    pub(crate) fn quiesce_metadata_transfer_context_writers(
        &mut self,
        release_tag_db_for_import: bool,
    ) -> Result<bool, String> {
        let mut busy = self.quiesce_current_metadata_transfer_context_writers();
        #[cfg(windows)]
        {
            if let Some(mut active) = self.active_detached_viewer_context.take() {
                self.swap_viewer_context_bundle(&mut active.bundle);
                busy |= self.quiesce_current_metadata_transfer_context_writers();
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.active_detached_viewer_context = Some(active);
            }
            for window_index in 0..self.detached_image_windows.len() {
                let Some(mut bundle) = self.detached_image_windows[window_index]
                    .paused_bundle
                    .take()
                else {
                    continue;
                };
                self.swap_viewer_context_bundle(&mut bundle);
                busy |= self.quiesce_current_metadata_transfer_context_writers();
                self.swap_viewer_context_bundle(&mut bundle);
                self.detached_image_windows[window_index].paused_bundle = Some(bundle);
            }
        }

        if !release_tag_db_for_import {
            return Ok(busy);
        }
        if busy {
            return Ok(true);
        }

        let Some(handle) = self.tag_write_handle.as_ref() else {
            // worker未spawnは、解放対象の接続が存在しないため解放済みと同義。
            self.metadata_transfer_tag_db_release_state = MetadataTransferTagDbReleaseState::Idle;
            return Ok(false);
        };
        if matches!(
            self.metadata_transfer_tag_db_release_state,
            MetadataTransferTagDbReleaseState::Idle
        ) {
            // 先に既存jobを完走させる。要求後に入ったjobはworker側の保留queueへ残り、
            // import終了後のresumeで処理される。
            if handle.is_busy() {
                return Ok(true);
            }
            handle.request_db_release();
            self.metadata_transfer_tag_db_release_state =
                MetadataTransferTagDbReleaseState::Requested {
                    started_at: std::time::Instant::now(),
                };
            return Ok(true);
        }
        if handle.db_released() {
            return Ok(false);
        }
        let MetadataTransferTagDbReleaseState::Requested { started_at } =
            self.metadata_transfer_tag_db_release_state
        else {
            unreachable!("idle release state returned above");
        };
        if started_at.elapsed() >= std::time::Duration::from_secs(5) {
            return Err(
                "タグ書き込みワーカーが5秒以内にtags.dbの接続を解放しなかったため、メタ情報インポートを開始できませんでした"
                    .to_string(),
            );
        }
        Ok(true)
    }

    /// 転送待機で取消したXMP rating readerを、完了・開始失敗・待機キャンセル後に
    /// contextごとへ戻す。legacy seedは安全に完走させているため再生成しない。
    pub(crate) fn resume_metadata_transfer_context_readers(&mut self) {
        if let Some(handle) = self.tag_write_handle.as_ref() {
            handle.resume_db();
        }
        self.metadata_transfer_tag_db_release_state = MetadataTransferTagDbReleaseState::Idle;

        if !self.settings.write_rating_to_xmp {
            return;
        }
        if !self.items.is_empty() && self.tag_prewarm_pending.is_none() {
            self.tag_prewarm_pending = Some(crate::tag_prewarm::spawn());
        }
        #[cfg(windows)]
        {
            if let Some(active) = self.active_detached_viewer_context.as_mut()
                && !active.bundle.items.is_empty()
                && active.bundle.tag_prewarm_pending.is_none()
            {
                active.bundle.tag_prewarm_pending = Some(crate::tag_prewarm::spawn());
            }
            for window in &mut self.detached_image_windows {
                if let Some(bundle) = window.paused_bundle.as_mut()
                    && !bundle.items.is_empty()
                    && bundle.tag_prewarm_pending.is_none()
                {
                    bundle.tag_prewarm_pending = Some(crate::tag_prewarm::spawn());
                }
            }
        }
    }

    pub(crate) fn apply_metadata_import_terminal_refresh(
        &mut self,
        result: metadata_import_refresh::RefreshResult,
        changed: crate::metadata_transfer::ImportChangedSections,
    ) -> (Vec<String>, bool) {
        let stale_before_apply = result.contexts.iter().any(|context| match context.slot {
            metadata_import_refresh::ContextSlot::Main => {
                context.items_generation != self.items_generation
            }
            #[cfg(windows)]
            metadata_import_refresh::ContextSlot::ActiveDetached(expected_window_id) => {
                self.active_detached_window_id() != expected_window_id
                    || self
                        .active_detached_viewer_context
                        .as_ref()
                        .is_some_and(|active| {
                            active.bundle.items_generation != context.items_generation
                        })
            }
            #[cfg(windows)]
            metadata_import_refresh::ContextSlot::PausedDetached {
                index: window_index,
                window_id,
            } => self
                .detached_image_windows
                .get(window_index)
                .is_some_and(|window| {
                    window.id != window_id
                        || window.paused_bundle.as_ref().is_some_and(|bundle| {
                            bundle.items_generation != context.items_generation
                        })
                }),
            #[cfg(not(windows))]
            _ => false,
        });
        if stale_before_apply {
            return (result.errors, true);
        }
        let mut stale_context = false;
        if let Some(snapshot) = result.page_snapshot {
            self.replace_metadata_import_page_state_snapshot(snapshot);
        }
        for context in result.contexts {
            match context.slot {
                metadata_import_refresh::ContextSlot::Main => {
                    stale_context |=
                        !self.apply_current_metadata_import_terminal_result(context, changed);
                }
                #[cfg(windows)]
                metadata_import_refresh::ContextSlot::ActiveDetached(expected_window_id) => {
                    if self.active_detached_window_id() != expected_window_id {
                        stale_context = true;
                    } else if let Some(mut active) = self.active_detached_viewer_context.take() {
                        self.swap_viewer_context_bundle(&mut active.bundle);
                        stale_context |=
                            !self.apply_current_metadata_import_terminal_result(context, changed);
                        self.swap_viewer_context_bundle(&mut active.bundle);
                        self.active_detached_viewer_context = Some(active);
                    }
                }
                #[cfg(windows)]
                metadata_import_refresh::ContextSlot::PausedDetached {
                    index: window_index,
                    window_id,
                } => {
                    if self
                        .detached_image_windows
                        .get(window_index)
                        .is_some_and(|window| window.id != window_id)
                    {
                        stale_context = true;
                        continue;
                    }
                    if let Some(mut bundle) = self
                        .detached_image_windows
                        .get_mut(window_index)
                        .and_then(|window| window.paused_bundle.take())
                    {
                        self.swap_viewer_context_bundle(&mut bundle);
                        stale_context |=
                            !self.apply_current_metadata_import_terminal_result(context, changed);
                        self.swap_viewer_context_bundle(&mut bundle);
                        if let Some(window) = self.detached_image_windows.get_mut(window_index) {
                            window.paused_bundle = Some(bundle);
                        }
                    }
                }
                #[cfg(not(windows))]
                _ => {}
            }
        }

        if changed.ratings {
            self.invalidate_rating_counts_cache();
            self.reset_folder_rating_counts();
            self.schedule_current_smart_folder_metadata_refresh(
                smart_folder::SmartFolderMetadataDependency::Rating,
            );
        }
        if changed.tags {
            self.schedule_current_smart_folder_metadata_refresh(
                smart_folder::SmartFolderMetadataDependency::Tags,
            );
            self.invalidate_tag_apply_suggestions();
        }
        if changed.page_state {
            self.schedule_current_smart_folder_metadata_refresh(
                smart_folder::SmartFolderMetadataDependency::Edits,
            );
        }
        if changed.book_bookmarks || changed.timed_bookmarks {
            self.notify_bookmarks_changed();
        }
        (result.errors, stale_context)
    }

    fn apply_current_metadata_import_terminal_result(
        &mut self,
        mut result: metadata_import_refresh::ContextResult,
        changed: crate::metadata_transfer::ImportChangedSections,
    ) -> bool {
        if result.items_generation != self.items_generation {
            return false;
        }
        let rating_cache_replaced = result.rating_cache.is_some();
        let tags_cache_replaced = result.tags_cache.is_some();
        let legacy_seed_paths = std::mem::take(&mut result.legacy_seed_paths);
        let rebuild_display =
            rating_cache_replaced || tags_cache_replaced || result.page_state.is_some();
        if let Some(ratings) = result.rating_cache.take() {
            self.rating_cache = ratings;
            self.current_folder_rating_cache = result.current_rating;
            self.rating_session_write_seen_generation = self.rating_session_write_generation;
            if let Some(pending) = self.tag_prewarm_pending.take() {
                pending.cancel();
            }
            self.tag_prewarm_queued.clear();
        }
        if let Some(tags) = result.tags_cache.take() {
            self.tags_cache = tags;
            if let Some(pending) = self.tag_prewarm_pending.take() {
                pending.cancel();
            }
            self.tag_prewarm_queued.clear();
            if let Some(pending) = self.tag_legacy_seed_pending.take() {
                pending.cancel();
            }
            DetailsCellContentRevisions::bump(&mut self.details_cell_content_revisions.tags);
        }
        if let Some(page) = result.page_state.take() {
            for index in &page.thumbnail_reset_indices {
                self.evict_thumbnail_for_edit_preview_refresh(*index);
            }
            self.adjustment_page_params = page.adjustment_page_params;
            self.local_adjust_pages = page.local_adjust_pages;
            self.local_adjust_page_layers.clear();
            self.local_adjust_selected_layers.clear();
            self.export_crop_pages = page.export_crop_page_settings.keys().copied().collect();
            self.export_crop_page_settings = page.export_crop_page_settings;
            self.view_trim_page_overrides = page.view_trim_page_overrides;
            self.mask_pages = page.mask_pages;
            self.conceal_pages = page.conceal_pages;
            self.comic_pages = page.comic_pages;
            self.rotation_cache = page.rotation_cache;
            self.adjustment_cache.clear();
            self.thumb_adjust_tex.clear();
            self.erase_result_cache.clear();
            self.local_adjust_cache.clear();
            self.local_adjust_layer_bypass_cache.clear();
            self.local_adjust_prefix_preview_cache.clear();
            self.edit_result_cache.clear();
            self.conceal_base_cache.clear();
            self.conceal_cache.clear();
            self.comic_docs.clear();
            self.cancel_all_local_adjust_pending();
            self.cancel_all_erase_inpaint_pending();
            self.bump_all_adjustment_generations();
            self.clear_all_final_pipeline_caches();
        }
        if let Some(container) = result.container_state.take() {
            let stored_spread = container
                .spread_mode
                .unwrap_or(self.settings.default_spread_mode);
            self.reading_flow = container
                .reading_flow
                .unwrap_or(self.settings.default_reading_flow);
            self.reading_direction = container
                .reading_direction
                .unwrap_or(self.settings.default_reading_direction);
            if stored_spread == crate::settings::SpreadMode::Vertical {
                self.spread_mode = crate::settings::SpreadMode::Single;
                self.reading_flow = crate::settings::ReadingFlow::Vertical;
            } else {
                self.spread_mode = stored_spread;
            }
            if self.spread_mode.is_rtl() {
                self.reading_direction = crate::settings::ReadingDirection::Rtl;
            } else if matches!(
                self.spread_mode,
                crate::settings::SpreadMode::Ltr | crate::settings::SpreadMode::LtrCover
            ) {
                self.reading_direction = crate::settings::ReadingDirection::Ltr;
            }
            self.spread_shift_anchor_idx = None;
            let trim = container.view_trim.unwrap_or_default();
            self.view_trim_apply_mode = match trim.apply_mode {
                crate::view_trim::ViewTrimApplyMode::Page => {
                    crate::view_trim::ViewTrimApplyMode::None
                }
                mode => mode,
            };
            self.view_trim_book_settings = trim.book_settings;
            self.view_trim_page_apply_root_idx = None;
            self.view_trim_page_spread_separate = self.view_trim_book_settings.spread_separate;
        }
        let folder_thumbnails_changed = result
            .folder_pin_reset_indices
            .as_ref()
            .is_some_and(|indices| !indices.is_empty());
        if let Some(folder_pins) = result.folder_pin_map.take() {
            self.folder_pin_map = folder_pins;
        }
        if let Some(indices) = result.folder_pin_reset_indices.take() {
            for index in indices {
                if let Some(thumbnail) = self.thumbnails.get_mut(index) {
                    *thumbnail = ThumbnailState::Pending;
                }
                self.requested.remove(&index);
                self.pending_finalize.remove(&index);
            }
        }
        if let (Some(video_items), Some(pin_blobs)) =
            (result.video_items.take(), result.video_pin_blobs.take())
            && !video_items.is_empty()
        {
            for (index, _, _) in &video_items {
                if let Some(thumbnail) = self.thumbnails.get_mut(*index) {
                    *thumbnail = ThumbnailState::Pending;
                }
                self.requested.remove(index);
                self.pending_finalize.remove(index);
            }
            self.spawn_video_thread(
                self.tx.clone(),
                Arc::clone(&self.cancel_token),
                video_items,
                self.video_thumb_overrides.clone(),
                pin_blobs,
            );
        }
        // folder pin自体、またはそのleafとなるvideo pinの変更時はcontextを一度だけ
        // 再materializeし、catalogへseed済みの代表WebPも更新・削除する。
        if folder_thumbnails_changed {
            self.folder_thumb_pin_dirty = true;
            // dirty flag自体はApp-globalなので、detached/parked bundleをswap backする前に
            // 現在mount中のcontextで消費する。video pinをleafに持つ代表サムネの
            // catalog seed更新・削除も、通常ロードと同じ経路でcontextごとに一度だけ行う。
            self.consume_folder_thumb_pin_dirty();
        }

        if changed.book_bookmarks {
            self.current_book_bookmarks.clear();
            self.current_book_bookmarks_key = None;
            self.current_book_bookmarks_request = None;
            self.clear_book_bookmark_title_edit();
        }
        if changed.timed_bookmarks {
            self.fullscreen_video_marker_cache = None;
            self.cancel_fullscreen_video_marker_thumb_decode();
            self.music_bookmarks.clear();
            self.music_bookmarks_loaded_for = None;
        }
        // 古いDB snapshotの結果を防ぐため上で取消したcontext所有workerを、
        // 完成cacheの適用後に同じcontextへ再生成する。これをmount中に行うことで
        // main / active detached / paused detached がそれぞれ自分のhandleを持つ。
        if (rating_cache_replaced || tags_cache_replaced) && self.settings.write_rating_to_xmp {
            self.tag_prewarm_pending = Some(crate::tag_prewarm::spawn());
        }
        if tags_cache_replaced {
            self.start_tag_legacy_seed(legacy_seed_paths);
        }
        // visible_indices / facet / details order / selectionはViewerContextBundle所有。
        // cacheを適用したcontextをmountしている間に一体で再計算する。
        if rebuild_display {
            self.rebuild_visible_indices_preserving_facet_scope();
        }
        true
    }

    pub(crate) fn replace_metadata_import_page_state_snapshot(
        &mut self,
        snapshot: crate::metadata_transfer::ImportPageStateSnapshot,
    ) {
        self.adjusted_page_keys = snapshot.adjusted;
        self.local_adjust_page_keys = snapshot.local_adjusted;
        self.mask_page_keys = snapshot.masked;
        self.conceal_page_keys = snapshot.concealed;
        self.comic_page_keys = snapshot.comic;
        self.rotation_page_keys = snapshot.rotated;
    }

    /// リネーム移行が使う data_dir (テストでは tempdir に差し替え可能)。
    fn rename_migration_data_dir(&self) -> std::path::PathBuf {
        #[cfg(test)]
        if let Some(dir) = &self.rename_migration_data_dir_override {
            return dir.clone();
        }
        crate::data_dir::get()
    }

    /// ジャーナル (`rename_key_migration::JOURNAL_FILE`) を現在の未完了ジョブ集合
    /// (in-flight + queue + boot_retry) で書き直す。enqueue / 完了 / Disconnected の
    /// 状態変化ごとに呼ぶ。App は完全 snapshot の組み立てだけを担い、filesystem I/O は
    /// latest-value writer が直列実行する (best-effort、失敗はログのみ)。
    fn persist_rename_migration_journal(&mut self) {
        let mut entries: Vec<(std::path::PathBuf, std::path::PathBuf)> = Vec::new();
        if let Some(job) = &self.rename_migration_in_flight {
            entries.push((job.old_path.clone(), job.new_path.clone()));
        }
        entries.extend(self.rename_migration_queue.iter().cloned());
        entries.extend(self.rename_migration_boot_retry.iter().cloned());
        let data_dir = self.rename_migration_data_dir();
        self.rename_migration_journal_writer
            .get_or_insert_with(crate::rename_key_migration::RenameMigrationJournalWriter::spawn)
            .enqueue(data_dir, entries);
    }

    fn flush_rename_migration_journal(&self) {
        if let Some(writer) = self.rename_migration_journal_writer.as_ref() {
            writer.flush();
        }
    }

    /// 前セッションの未完了ジャーナルを読み込んでキューへ積む。最初の enqueue / poll の
    /// 前に必ず 1 回呼ばれる (先に enqueue の persist が走ると回復エントリを上書き
    /// してしまうため、lazy guard で担保する)。移行は冪等なので、クラッシュで途中まで
    /// 走ったジョブを再実行しても安全 (角度⑤ Sol/Terra P1)。
    fn ensure_rename_migration_journal_loaded(&mut self) {
        if self.rename_migration_journal_loaded {
            return;
        }
        self.rename_migration_journal_loaded = true;
        let entries = crate::rename_key_migration::journal_load(&self.rename_migration_data_dir());
        if entries.is_empty() {
            return;
        }
        crate::logger::log(format!(
            "[RENAME-MIG] recovering {} unfinished migration(s) from journal",
            entries.len()
        ));
        self.rename_migration_queue.extend(entries);
    }

    /// 削除に成功した path を**新側**に持つ未実行のリネーム移行を破棄する (角度⑦ P1:
    /// 「A→B を改名 → 移行がタグ書込ゲートで待機中に B を削除」すると、後から走る移行が
    /// 削除済み B のメタデータ行を作り直してしまう)。フォルダ削除は配下 (`<key>/…`) も対象。
    /// 実行中 (in-flight) のジョブは中断できないため対象外: その結末は「削除済み path に
    /// 孤児行が残る」= 通常削除と同じ性質 (mIV は削除時に path-keyed 行を消さない) で許容。
    pub(crate) fn invalidate_rename_migrations_for_removed_paths(
        &mut self,
        removed: &[std::path::PathBuf],
    ) {
        if removed.is_empty() {
            return;
        }
        // ジャーナル未読込のまま journal 書き戻しをすると回復エントリを失うので先に読む。
        self.ensure_rename_migration_journal_loaded();
        let matches_key = removed_path_key_matcher(removed);
        let keep = |new_path: &std::path::Path| {
            !matches_key(&crate::adjustment_db::normalize_path(new_path))
        };
        let before = self.rename_migration_queue.len() + self.rename_migration_boot_retry.len();
        self.rename_migration_queue.retain(|(_, new)| keep(new));
        self.rename_migration_boot_retry
            .retain(|(_, new)| keep(new));
        let after = self.rename_migration_queue.len() + self.rename_migration_boot_retry.len();
        if after != before {
            crate::logger::log(format!(
                "[RENAME-MIG] dropped {} migration(s) targeting deleted path(s)",
                before - after
            ));
            self.persist_rename_migration_journal();
        }
    }

    /// リネーム成功後に path-keyed 永続データの移行ジョブを FIFO キューへ積む
    /// ([`crate::rename_key_migration`]、対象ストアと制限はモジュール doc 参照)。
    /// DB の cold open が UI を止めないよう worker スレッドで実行し、完了は
    /// `poll_rename_migration_pending` が拾って in-memory キャッシュを引き直す。
    /// ジョブはジャーナルにも書かれ、終了 / クラッシュ / トレイ Exit を跨いでも次回起動時に
    /// 再実行される。通常終了は `on_exit`、App drop は writer の Drop が最新 snapshot を flush する。
    pub(crate) fn spawn_rename_key_migration(
        &mut self,
        old_path: std::path::PathBuf,
        new_path: std::path::PathBuf,
    ) {
        self.ensure_rename_migration_journal_loaded();
        self.rename_migration_queue.push_back((old_path, new_path));
        self.persist_rename_migration_journal();
        self.try_start_next_rename_migration();
    }

    /// リネーム移行の開始を遅らせるべき書込 worker が残っているか。
    ///
    /// tags.db はタグ書込 worker が**ジョブ実行時に**キーを解決して書くため、旧 path 宛の
    /// 実行待ちジョブが残ったまま移行すると、移行後に旧キーの行が復活して失われる
    /// (Sol rename-mig P2)。worker が空になるまで移行開始を遅らせれば、残ジョブが先に
    /// 旧キーへ着地し、その後の移行がまとめて新キーへ運ぶので順序が正しくなる。
    ///
    /// 編集 preview も save/delete worker の FIFO が空になるまで待ち、移行後に旧 key 行が
    /// 復活しないようにする。タグ側は `is_busy()` ではなく
    /// **`has_unconsumed_batch()`** を使う: is_busy は
    /// worker の DB 書込完了で false になるが、UI 側の結果消費 (`poll_tag_write_results` の
    /// sidecar ミラー書込) はさらに後のフレーム後半に走るため、is_busy だけだと移行開始後に
    /// 旧 path のサイドカーが書き直される (Sol rename-mig R2 P2)。
    /// ★の書込 worker (ファイル XMP / 動画サイドカー) も同様に待つ (DB は書かず、
    /// sidecar 書込は worker 内で完結するので is_busy で足りる)。本ブックマークは
    /// 専用 service の FIFO へ旧 path の追加が残った後で rename DB を先に動かさないよう、
    /// request の結果を UI が消費し終えるまで待つ。
    pub(crate) fn rename_migration_writers_busy(&self) -> bool {
        let tag_busy = self
            .tag_write_handle
            .as_ref()
            .is_some_and(|h| h.has_unconsumed_batch());
        let rating_busy = self
            .rating_write_handle
            .as_ref()
            .is_some_and(|h| h.is_busy());
        let edit_preview_busy = self
            .edit_preview_cache
            .as_ref()
            .is_some_and(|cache| cache.has_pending_commands());
        tag_busy
            || rating_busy
            || edit_preview_busy
            || !self.book_bookmark_pending_requests.is_empty()
    }

    /// キュー先頭のリネーム移行 worker を起動する (直列 = in-flight が無いときだけ)。
    /// 書込 worker が busy の間は開始せず、`poll_rename_migration_pending` が毎フレーム
    /// 再試行する。
    pub(crate) fn try_start_next_rename_migration(&mut self) {
        if self.rename_migration_in_flight.is_some() || self.rename_migration_queue.is_empty() {
            return;
        }
        if self.rename_migration_writers_busy() {
            return;
        }
        if self.metadata_cleanup_pending.is_some() {
            return;
        }
        if self.delete_purge_retry_pending.is_some() {
            return;
        }
        let Some((old_path, new_path)) = self.rename_migration_queue.pop_front() else {
            return;
        };
        let data_dir = self.rename_migration_data_dir();
        let (tx, rx) = std::sync::mpsc::channel();
        let worker_old = old_path.clone();
        let worker_new = new_path.clone();
        match std::thread::Builder::new()
            .name("rename-key-migration".into())
            .spawn(move || {
                // panic は report 化して返す (Disconnected をプロセス死のみに限定する)。
                // panicked=true の report は poll 側でジャーナルに残し、次回起動で
                // 冪等に再実行する (残ストア未試行のまま消し込まない、Sol 角度⑤検収)。
                let report = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    crate::rename_key_migration::run_at(&data_dir, &worker_old, &worker_new)
                }))
                .unwrap_or_else(|_| {
                    crate::rename_key_migration::RenameMigrationReport {
                        rows: 0,
                        errors: vec!["worker panicked".to_string()],
                        panicked: true,
                    }
                });
                let _ = tx.send(report);
            }) {
            Ok(_) => {
                self.rename_migration_in_flight = Some(RenameMigrationInFlight {
                    old_path,
                    new_path,
                    rx,
                });
            }
            Err(e) => {
                // ジョブを失わない (Terra 角度⑤ P2): 先頭へ戻して次フレームで再試行する。
                // ジャーナルにも残っているので、失敗が続いたまま終了しても次回起動で回復する。
                crate::logger::log(format!("[RENAME-MIG] spawn failed (requeue): {e}"));
                self.rename_migration_queue.push_front((old_path, new_path));
            }
        }
    }

    /// リネーム移行 worker の完了を受信し、移行後の値で in-memory キャッシュを引き直して
    /// キューの次ジョブを開始する。ジャーナル回復もここが起点 (初回呼び出しで読込)。
    pub(crate) fn poll_rename_migration_pending(&mut self, ctx: &egui::Context) {
        self.ensure_rename_migration_journal_loaded();
        // ドラッグ中で繰り延べた main 文脈の再構築を、ドラッグが終わったフレームで実行。
        if self.rename_rehydrate_main_deferred
            && self.adjustment_drag_session.is_none()
            && self.adjustment_standard_drag_session.is_none()
        {
            self.rename_rehydrate_main_deferred = false;
            self.rehydrate_mounted_context_after_rename();
        }
        if let Some(job) = self.rename_migration_in_flight.as_ref() {
            match job.rx.try_recv() {
                Ok(report) => {
                    let job = self
                        .rename_migration_in_flight
                        .take()
                        .expect("guarded above");
                    if report.panicked {
                        // panic = 残ストアを試行しないまま中断した可能性がある。per-store
                        // エラー (全ストア試行済み) と違って消し込まず、ジャーナルに残して
                        // 次回起動で冪等に再実行する (Sol 角度⑤検収)。セッション内での
                        // 再試行はしない (決定的 panic の無限ループ回避)。
                        crate::logger::log("[RENAME-MIG] worker panicked (boot retry)".to_string());
                        self.show_feedback_toast(
                            "名前変更に伴う設定の引き継ぎが中断されました (次回起動時に再実行します)"
                                .to_string(),
                        );
                        self.rename_migration_boot_retry
                            .push((job.old_path, job.new_path));
                        self.persist_rename_migration_journal();
                        self.try_start_next_rename_migration();
                        ctx.request_repaint_after(std::time::Duration::from_millis(100));
                        return;
                    }
                    // report を受信できたジョブはジャーナルから消し込む (per-store エラーは
                    // 通常経路と同じ best-effort = 再試行しない)。
                    self.persist_rename_migration_journal();
                    crate::logger::log(format!(
                        "[RENAME-MIG] done rows={} errors={}",
                        report.rows,
                        report.errors.len()
                    ));
                    for e in report.errors.iter().take(3) {
                        crate::logger::log(format!("[RENAME-MIG] error: {e}"));
                    }
                    if !report.errors.is_empty() {
                        self.show_feedback_toast(format!(
                            "名前変更に伴う設定の引き継ぎに一部失敗しました ({} 件)",
                            report.errors.len()
                        ));
                    }
                    // presence set / resume キーを引き直す。通常経路では rename 成功時に
                    // 書換済みで no-op だが、ジャーナル回復ジョブ (起動後に走る) では
                    // 起動時ロードが旧キーを読んでいるためここでの書換が本番になる。
                    self.rewrite_page_edit_presence_for_rename(&job.old_path, &job.new_path);
                    self.migrate_video_resume_positions_for_renamed_path(
                        &job.old_path,
                        &job.new_path,
                    );
                    let old_rating_key = crate::adjustment_db::normalize_path(&job.old_path);
                    let new_rating_key = crate::adjustment_db::normalize_path(&job.new_path);
                    migrate_key_map_for_rename(
                        &mut self.rating_session_writes,
                        &old_rating_key,
                        &new_rating_key,
                    );
                    // ★ / タグの path-keyed 表示キャッシュはグローバルに引き直す (安全)。
                    self.rating_cache.clear();
                    self.invalidate_rating_counts_cache();
                    self.clear_tags_cache();
                    // rename 直後の folder reload が DB migration より先に完了すると、
                    // 新 key で preview miss した raw thumbnail が Loaded のまま残る。
                    // 移行対象の preview identity を持つセルだけ Evicted に戻し、移行済み
                    // edit_previews 行を通常 worker 経路で読み直す。
                    self.refresh_edit_preview_thumbnails_after_rename(&job.old_path, &job.new_path);
                    // idx キーのページ編集 state は「リネームに関係する文脈」だけ再構築する。
                    // 旧実装の全文脈 clear_page_edit_state は、無関係な画像の編集中ドラッグ値
                    // まで消し、離した瞬間に既存の保存済み補正を削除する実害があった
                    // (角度⑦ P1、Sol/Terra/Luna 一致)。
                    self.rehydrate_contexts_after_rename_migration(&job.old_path, &job.new_path);
                    // 共通リネーム worker は book_bookmarks.db も更新する。現在の本の
                    // 左パネルと横断一覧が旧 identity を保持し続けないよう再読込する。
                    self.invalidate_book_bookmarks_after_path_migration();
                    self.refresh_smart_folders_after_rename();
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    // report が届かないままプロセス内で消息不明 (通常は起きない: panic は
                    // catch して report 化している)。セッション内では再試行せず、ジャーナルに
                    // 残して次回起動で回復させる。
                    let job = self
                        .rename_migration_in_flight
                        .take()
                        .expect("guarded above");
                    crate::logger::log("[RENAME-MIG] worker disconnected".to_string());
                    self.rename_migration_boot_retry
                        .push((job.old_path, job.new_path));
                    self.persist_rename_migration_journal();
                }
            }
        }
        self.try_start_next_rename_migration();
        if self.rename_migration_in_flight.is_some() || !self.rename_migration_queue.is_empty() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
    }

    /// リネーム移行の完了後、影響を受ける文脈 (mounted main / active detached /
    /// parked bundle) の idx キー編集 state と★キャッシュを DB から再構築する
    /// (角度⑦ P1/P2)。無関係な文脈には一切触れない。
    ///
    /// - main: 改名アイテムの親フォルダを表示中 (または改名フォルダ配下) のときだけ。
    ///   補正スライダーのドラッグ中は据え置き、ドラッグ終了後のフレームで実行する
    ///   (ドラッグ値の消失 → 離した時に既存補正が削除される事故を防ぐ、Terra 角度⑦)。
    /// - active/parked bundle: 移行ギャップ中に新 path を開いて旧 DB 状態のまま hydrate
    ///   した bundle は再活性化しても再読込されない (Sol/Terra 角度⑦ P2) ため、
    ///   `poll_parked_live_detached_windows` と同じ swap 手順で一時 mount して再構築する。
    ///   parked bundle は編集中ではないので即時で安全。
    fn rehydrate_contexts_after_rename_migration(
        &mut self,
        old_path: &std::path::Path,
        new_path: &std::path::Path,
    ) {
        let removed = [old_path.to_path_buf(), new_path.to_path_buf()];
        let matches_key = removed_path_key_matcher(&removed);
        let parent_keys: Vec<String> = [old_path.parent(), new_path.parent()]
            .into_iter()
            .flatten()
            .map(crate::adjustment_db::normalize_path)
            .collect();
        let folder_refs = |folder: Option<&std::path::Path>| -> bool {
            folder.is_some_and(|f| {
                let fk = crate::adjustment_db::normalize_path(f);
                matches_key(&fk) || parent_keys.iter().any(|p| *p == fk)
            })
        };
        // 全体検索 / サブ展開などの合成ビューは current_folder が合成 path のため
        // フォルダ照合に掛からない。items にリネーム対象が含まれるかも見る
        // (Sol 角度⑦検収 P2。リネームは稀な操作なので O(items) 走査を許容)。
        let items_ref = |items: &[crate::grid_item::GridItem]| -> bool {
            items.iter().any(|item| {
                item.drag_source_path()
                    .is_some_and(|p| matches_key(&crate::adjustment_db::normalize_path(p)))
            })
        };

        if folder_refs(self.current_folder.as_deref()) || items_ref(&self.items) {
            if self.adjustment_drag_session.is_some()
                || self.adjustment_standard_drag_session.is_some()
            {
                self.rename_rehydrate_main_deferred = true;
            } else {
                self.rehydrate_mounted_context_after_rename();
            }
        }

        #[cfg(windows)]
        {
            let active_matches = self
                .active_detached_viewer_context
                .as_ref()
                .is_some_and(|c| {
                    viewer_bundle_references_removed(&c.bundle, &matches_key)
                        || folder_refs(c.bundle.current_folder.as_deref())
                        || items_ref(&c.bundle.items)
                });
            if active_matches {
                if let Some(ctx_state) = self.active_detached_viewer_context.take() {
                    let mut bundle = ctx_state.bundle;
                    self.swap_viewer_context_bundle(&mut bundle);
                    self.rehydrate_mounted_context_after_rename();
                    self.swap_viewer_context_bundle(&mut bundle);
                    self.active_detached_viewer_context =
                        Some(ActiveDetachedViewerContext { bundle });
                }
            }
            let idxs: Vec<usize> = self
                .detached_image_windows
                .iter()
                .enumerate()
                .filter(|(_, w)| {
                    w.paused_bundle.as_deref().is_some_and(|b| {
                        viewer_bundle_references_removed(b, &matches_key)
                            || folder_refs(b.current_folder.as_deref())
                            || items_ref(&b.items)
                    })
                })
                .map(|(i, _)| i)
                .collect();
            for i in idxs {
                let Some(mut bundle) = self.detached_image_windows[i].paused_bundle.take() else {
                    continue;
                };
                self.swap_viewer_context_bundle(&mut bundle);
                self.rehydrate_mounted_context_after_rename();
                self.swap_viewer_context_bundle(&mut bundle);
                self.detached_image_windows[i].paused_bundle = Some(bundle);
            }
        }
    }

    /// mounted 文脈の per-page 編集 state (idx キー) と★/タグ表示キャッシュを DB から
    /// 再構築する。`rehydrate_page_edit_state_for_current_items` は移行後の DB を読むので
    /// 値は正しくなる。
    fn rehydrate_mounted_context_after_rename(&mut self) {
        let Some(folder) = self.current_folder.clone() else {
            return;
        };
        self.rehydrate_page_edit_state_for_current_items(&folder);
        self.rating_cache.clear();
        self.current_folder_rating_cache = None;
        self.clear_tags_cache();
    }

    /// rename DB migration より先に raw thumbnail が着地した場合の対象限定 refresh。
    ///
    /// `thumb_edit_preview_keys` は直接ページだけでなく、編集 preview を継承する手動 pin
    /// 親セルの canonical page key も保持する。exact / folder prefix / archive entry の
    /// 3 面で旧・新どちらかに属するセルだけを再要求し、通常 catalog 行は触らない。
    fn refresh_edit_preview_thumbnails_after_rename(
        &mut self,
        old_path: &std::path::Path,
        new_path: &std::path::Path,
    ) {
        let matches_key =
            removed_path_key_matcher(&[old_path.to_path_buf(), new_path.to_path_buf()]);
        let affected = self
            .thumb_edit_preview_keys
            .iter()
            .filter_map(|(&idx, key)| matches_key(key).then_some(idx))
            .collect::<Vec<_>>();
        for idx in affected {
            self.evict_thumbnail_for_edit_preview_refresh(idx);
        }
    }

    /// リネームに合わせて、編集済みバッジ用の presence set (起動時に全 DB キーを読み込む
    /// グローバル集合) のキーを in-memory で書き換える。DB 側の移行
    /// (`rename_key_migration`) と同じ exact + `/` + `::` の 3 面規則。
    pub(crate) fn rewrite_page_edit_presence_for_rename(
        &mut self,
        old_path: &std::path::Path,
        new_path: &std::path::Path,
    ) {
        let old_k = crate::adjustment_db::normalize_path(old_path);
        let new_k = crate::adjustment_db::normalize_path(new_path);
        if old_k == new_k {
            return;
        }
        rewrite_key_set_for_rename(&mut self.adjusted_page_keys, &old_k, &new_k);
        rewrite_key_set_for_rename(&mut self.local_adjust_page_keys, &old_k, &new_k);
        rewrite_key_set_for_rename(&mut self.mask_page_keys, &old_k, &new_k);
        rewrite_key_set_for_rename(&mut self.conceal_page_keys, &old_k, &new_k);
        rewrite_key_set_for_rename(&mut self.comic_page_keys, &old_k, &new_k);
    }

    /// リネームに合わせて動画再生位置の in-memory 記録キーを付け替える (DB 側は settings
    /// 保存時に反映される)。削除時の `purge_video_resume_positions_for_removed_paths` と
    /// 対になる移行版。
    pub(crate) fn migrate_video_resume_positions_for_renamed_path(
        &mut self,
        old_path: &std::path::Path,
        new_path: &std::path::Path,
    ) {
        let old_k = crate::adjustment_db::normalize_path(old_path);
        let new_k = crate::adjustment_db::normalize_path(new_path);
        if old_k == new_k {
            return;
        }
        migrate_key_map_for_rename(&mut self.settings.video_resume_positions, &old_k, &new_k);
        #[cfg(windows)]
        migrate_key_map_for_rename(&mut self.video_resume_thumb_last_request, &old_k, &new_k);
    }

    /// 起動時と後続 idle 時に delete purge journal を worker で再実行する。
    /// journal の path は「Shell 削除成功済み」の証跡だが、再作成された同名ファイルの
    /// 新メタを消さないよう、孤児整理と同じ親到達可能 + path 不在の条件も再確認する。
    pub(crate) fn poll_delete_purge_retry(&mut self, ctx: &egui::Context) {
        if let Some(pending) = self.delete_purge_retry_pending.as_ref() {
            match pending.rx.try_recv() {
                Ok(report) => {
                    self.delete_purge_retry_pending = None;
                    crate::logger::log(format!(
                        "[delete-purge] retry done attempted={} purged={} rows={} remaining={} errors={}",
                        report.attempted,
                        report.purged,
                        report.rows,
                        report.remaining,
                        report.errors.len()
                    ));
                    for error in report.errors.iter().take(3) {
                        crate::logger::log(format!("[delete-purge] retry error: {error}"));
                    }
                    self.delete_purge_retry_needed = report.remaining > 0;
                    self.delete_purge_retry_after = self
                        .delete_purge_retry_needed
                        .then(|| std::time::Instant::now() + std::time::Duration::from_secs(10));
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {
                    ctx.request_repaint_after(std::time::Duration::from_millis(100));
                    return;
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    self.delete_purge_retry_pending = None;
                    self.delete_purge_retry_needed = true;
                    self.delete_purge_retry_after =
                        Some(std::time::Instant::now() + std::time::Duration::from_secs(10));
                }
            }
        }
        const DELETE_PURGE_INPUT_IDLE: std::time::Duration = std::time::Duration::from_secs(1);
        if let Some(last_input_at) = self.last_input_at
            && last_input_at.elapsed() < DELETE_PURGE_INPUT_IDLE
        {
            ctx.request_repaint_after(
                DELETE_PURGE_INPUT_IDLE.saturating_sub(last_input_at.elapsed()),
            );
            return;
        }
        if !self.delete_purge_retry_needed
            || self.delete_pending.is_some()
            || self.metadata_cleanup_pending.is_some()
            || self.rename_migration_in_flight.is_some()
            || !self.rename_migration_queue.is_empty()
            || self.rename_migration_writers_busy()
            || self
                .delete_purge_retry_after
                .is_some_and(|retry_at| std::time::Instant::now() < retry_at)
        {
            if let Some(retry_at) = self.delete_purge_retry_after {
                ctx.request_repaint_after(
                    retry_at.saturating_duration_since(std::time::Instant::now()),
                );
            }
            return;
        }
        self.delete_purge_retry_needed = false;
        self.delete_purge_retry_after = None;
        self.delete_purge_retry_pending = Some(crate::metadata_cleanup::spawn_delete_purge_retry(
            self.rename_migration_data_dir(),
        ));
        ctx.request_repaint_after(std::time::Duration::from_millis(100));
    }

    /// 削除ワーカーを spawn し、`delete_pending` に保持する。
    /// 既に実行中の場合は何もしない (UI 側でダイアログ表示中はボタン無効化する前提)。
    /// 対象を表示・再生中の窓は spawn 前に閉じる (decoder handle 解放、上記 (B))。
    pub(crate) fn start_delete_files(
        &mut self,
        ctx: &egui::Context,
        paths: Vec<std::path::PathBuf>,
    ) {
        if paths.is_empty()
            || self.delete_pending.is_some()
            || self.metadata_cleanup_pending.is_some()
            || self.delete_purge_retry_pending.is_some()
        {
            return;
        }
        self.release_viewer_surfaces_for_removed_paths(ctx, &paths, "delete_target_path");
        // 削除中に items を差し替える恐れのある in-flight pending を停止。poll_delete_pending
        // は path で現 items に引き直すので世代一致は厳密には不要だが、余計な再描画・
        // キャッシュ無効化を避けるため事前に静かにしておく。
        if let Some(p) = self.search_pending.take() {
            p.cancel();
        }
        if let Some(p) = self.favsearch_pending.take() {
            p.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        self.global_search.pending = None;
        self.delete_pending = Some(crate::delete_worker::spawn(paths, self.main_hwnd));
    }

    /// 毎フレーム `delete_pending` の進捗メッセージを受信する。
    ///
    /// 進捗バッチを受けるたびに `succeeded` / `failed` / `processed` を更新し、
    /// `DeleteMsg::Done` 受信で items への反映 (成功 path を現在の items から引き直して
    /// `remove_items_batch`) + `prewarm_grid_tags` 再起動 + ダイアログクローズを行う。
    ///
    /// 完了時に `items_generation` が開始時と変わっていれば items への反映をスキップする
    /// (フォルダ切替などで items が入れ替わった場合、ゴミ箱移動済みの path を現在の items
    /// から引こうとしても自然に空振るが、早期 return で無駄処理を省く)。
    pub(crate) fn poll_delete_pending(&mut self) {
        let Some(pending) = self.delete_pending.as_mut() else {
            return;
        };
        let mut done = false;
        let mut canceled = false;
        loop {
            match pending.rx.try_recv() {
                Ok(crate::delete_worker::DeleteMsg::Batch {
                    succeeded,
                    failed,
                    purged_pdf_password_paths,
                    purge_deferred,
                }) => {
                    pending.succeeded.extend(succeeded);
                    pending.failed.extend(failed);
                    pending
                        .purged_pdf_password_paths
                        .extend(purged_pdf_password_paths);
                    pending.purge_deferred |= purge_deferred;
                }
                Ok(crate::delete_worker::DeleteMsg::Done { canceled: c }) => {
                    done = true;
                    canceled = c;
                    break;
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => break,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    done = true;
                    break;
                }
            }
        }

        if !done {
            return;
        }

        let pending = self.delete_pending.take().expect("guarded above");
        let succeeded = pending.succeeded;
        let purged_pdf_password_paths = pending.purged_pdf_password_paths;
        let failed_count = pending.failed.len();
        if pending.purge_deferred {
            self.delete_purge_retry_needed = true;
            self.delete_purge_retry_after = None;
        }

        crate::logger::log(format!(
            "[delete] done: canceled={canceled} succeeded={} failed={failed_count}",
            succeeded.len(),
        ));

        if failed_count > 0 {
            let first = pending
                .failed
                .first()
                .map(|(p, m)| format!("{}: {m}", p.display()));
            crate::logger::log(format!(
                "[delete] first failed = {}",
                first.unwrap_or_default()
            ));
            self.show_feedback_toast(format!("{} 件の削除に失敗しました", failed_count));
        }

        if succeeded.is_empty() {
            return;
        }

        // delete-worker は全 Shell 成功 path を末尾で hard purge してから Done を送る。
        // UI 側は Done 後に disk I/O なしで presence set / cache を同じ path 境界で整合させる。
        self.purge_in_memory_metadata_for_removed_paths(&succeeded, &purged_pdf_password_paths);

        // 消えた path の再生位置記録を破棄する (角度④ (A)。窓のクローズは
        // `start_delete_files` が worker spawn 前に済ませている)。
        self.purge_video_resume_positions_for_removed_paths(&succeeded);
        // 消えた path を新側に持つ未実行のリネーム移行も破棄する (角度⑦ P1)。
        self.invalidate_rename_migrations_for_removed_paths(&succeeded);

        // 成功 path を現在の items から引き直して idx 配列を作る。
        // items が途中で入れ替わっても (Ctrl+G 結果差し替え等) 現 items に残っている分だけ
        // 引き当てられる。items_generation の一致チェックは不要 (空振り最適化のためだけの
        // 早期 return を入れると、Ctrl+G 結果に削除済み path が含まれていたとき反映漏れになる)。
        let success_set: std::collections::HashSet<&std::path::Path> =
            succeeded.iter().map(|p| p.as_path()).collect();
        let mut idxs: Vec<usize> = self
            .items
            .iter()
            .enumerate()
            .filter_map(|(i, item)| {
                let path = item.drag_source_path()?;
                if success_set.contains(path) {
                    Some(i)
                } else {
                    None
                }
            })
            .collect();
        idxs.sort_unstable_by(|a, b| b.cmp(a));
        if idxs.is_empty() {
            return;
        }
        self.remove_items_batch(&idxs);
        self.prewarm_grid_tags();

        // 削除自身がフォルダ mtime を更新しているので、`current_folder_last_mtime` を
        // 新しい値に進めて `check_external_folder_changes` の自動再読込をスキップさせる。
        // これを怠ると次フレームで削除済み path を grid から抜いたのとほぼ同じ結果を
        // `load_folder()` で再計算することになり、数千件削除直後に UI が再度ブロックする。
        // また、stale な `current_folder_signature` (削除前の状態) が残ると後の
        // 外部 mtime 変更時に「内容変化あり」と誤判定して reload が走るので無効化する。
        // 次の reload でフル再走査されてシグネチャが新しく構築される。
        if let Some(folder) = self.current_folder.clone() {
            if let Ok(meta) = folder.metadata() {
                if meta.is_dir() {
                    if let Ok(new_mtime) = meta.modified() {
                        self.current_folder_last_mtime = Some(new_mtime);
                    }
                }
            }
        }
        self.current_folder_signature = None;
    }

    /// 現在のマウスカーソル位置のウィンドウが `hwnd` (= mIV メインウィンドウ) かを返す。
    /// native ドラッグの落下先が mIV 自身かを `SHDoDragDrop` 完了時に判定するのに使う。
    #[cfg(windows)]
    fn cursor_over_window(hwnd: isize) -> bool {
        use windows::Win32::Foundation::{HWND, POINT};
        use windows::Win32::UI::WindowsAndMessaging::{
            GA_ROOT, GetAncestor, GetCursorPos, WindowFromPoint,
        };
        unsafe {
            let mut pt = POINT::default();
            if GetCursorPos(&mut pt).is_err() {
                return false;
            }
            let under = WindowFromPoint(pt);
            if under.0.is_null() {
                return false;
            }
            // 子ウィンドウ上に落ちてもルートで比較する。
            GetAncestor(under, GA_ROOT) == HWND(hwnd as *mut core::ffi::c_void)
        }
    }

    #[cfg(not(windows))]
    fn cursor_over_window(_hwnd: isize) -> bool {
        false
    }

    /// エクスプローラ等から mIV ウィンドウへドロップされたファイルを、現在表示中の
    /// 実フォルダへコピーする (mIV → 外部 のドラッグ送出と対称の受け取り方向)。
    ///
    /// コピー先は `current_favorite_target()` — 実ディレクトリ表示中だけ `Some`。
    /// ただし Ctrl+G / Ctrl+S の検索結果ビューは `current_folder` を直前の実フォルダの
    /// まま残すため、それだけだと「直前のフォルダ」へ誤コピーしてしまう。検索結果
    /// 表示中は明示的に拒否する (Codex P2)。
    ///
    /// **フォルダのドロップ受け取りは v1.1.0 で一旦無効化** — 同名衝突の無確認上書き・
    /// 再帰コピーのデータ破壊リスクのため、Explorer 相当の衝突解決と合わせて将来へ延期。
    /// ドロップされたディレクトリは全て skip し (notice で通知)、ファイルのみコピーする。
    /// 再有効化時の自己再帰ガードは `file_drag::dir_copy_would_recurse` を流用する。
    ///
    /// 完了時のフォルダ再読み込みは `poll_file_drop_pending` が `pending_reload` を立てて行う。
    pub(crate) fn handle_external_file_drop(&mut self, paths: Vec<PathBuf>) {
        if paths.is_empty() {
            return;
        }
        // 検索結果ビュー (Ctrl+G 合成 / Ctrl+S favsearch / Ctrl+T タグビュー) は current_folder が直前の
        // 実フォルダのまま残る。コピー先が曖昧なので拒否する。
        let in_search_view = self.items_are_global_search_view
            || self.favsearch.on_results_grid()
            || self.tag_view.on_results_grid()
            || self.items_are_tag_view;
        let dest = if in_search_view {
            None
        } else {
            self.current_favorite_target()
        };
        let Some(dest) = dest else {
            let msg = if in_search_view {
                "検索結果の表示中はファイルをドロップできません"
            } else if self.current_folder.is_some() {
                "ZIP / PDF を表示中はファイルをドロップできません"
            } else {
                "コピー先のフォルダがありません"
            };
            self.show_feedback_toast(msg.to_string());
            return;
        };
        // **review #7 対応**: ドロップ先との自己再帰判定 (per-path `Path::is_dir` +
        // `fs::canonicalize`×2) は遅いネットワーク共有で 1 path あたり 50-500ms に
        // なるので、UI スレッドから worker へ全部投げる。UI 側は即座に件数 toast を
        // 出して return する。Worker 内で検証 → PowerShell 起動 → 完了待ち の順で
        // 動き、完了を `drop_copy_pending` 経由で `CopyOutcome` 付きで受け取り、
        // 失敗があればトーストで通知する (review #15)。
        let n_total = paths.len();
        let (tx, rx) = std::sync::mpsc::channel::<crate::ui_dialogs::context_menu::CopyOutcome>();
        let dest_for_worker = dest.clone();
        let spawn_result = std::thread::Builder::new()
            .name("file-drop-validate".into())
            .spawn(move || {
                // フォルダのドロップ受け取りは v1.1.0 で一旦無効化 (同名衝突の無確認
                // 上書き・再帰コピーのデータ破壊リスクのため、Explorer 相当の衝突解決と
                // 合わせて将来へ延期)。ディレクトリは skip しファイルのみコピーする。
                let (to_copy, folder_skipped) =
                    crate::file_drag::partition_dropped_paths(paths, |p| p.is_dir());
                if to_copy.is_empty() {
                    crate::logger::log(format!(
                        "file_drop: all {folder_skipped} dropped paths are folders; folder drop is disabled"
                    ));
                    let notice = if folder_skipped > 0 {
                        format!(
                            "フォルダのドロップは現在無効です ({folder_skipped} 件をスキップ)。ファイルのみコピーできます"
                        )
                    } else {
                        "コピー対象がありませんでした".to_string()
                    };
                    let _ = tx.send(crate::ui_dialogs::context_menu::CopyOutcome {
                        attempted: 0,
                        failed: 0,
                        first_errors: Vec::new(),
                        notice: Some(notice),
                    });
                    return;
                }
                if folder_skipped > 0 {
                    crate::logger::log(format!(
                        "file_drop: {folder_skipped} folders skipped (folder drop disabled); copying {} files",
                        to_copy.len()
                    ));
                }
                let to_copy_attempted = to_copy.len();
                let copy_rx = crate::ui_dialogs::context_menu::copy_paths_into_folder(
                    to_copy,
                    &dest_for_worker,
                );
                // copy_paths_into_folder 内 worker から CopyOutcome を受け取って UI へ転送。
                // **Codex P2-1 対応**: Disconnected (= 内側 worker が outcome を送らずに
                // 死んだ) を `CopyOutcome::default()` (= failed=0 の成功扱い) に潰さず、
                // 全件失敗として伝える。実コピーが起きていない可能性が高い局面でも
                // 「成功 N / 失敗 0」と表示されていた旧バグの修正。
                let mut outcome = match copy_rx.recv() {
                    Ok(o) => o,
                    Err(e) => crate::ui_dialogs::context_menu::CopyOutcome::all_failed(
                        to_copy_attempted,
                        format!("copy worker disconnected without sending outcome: {e}"),
                    ),
                };
                // ファイル + フォルダ混在ドロップで、ファイルのコピーは成功したが
                // フォルダを skip した旨も通知する (copy 側 notice が無いときだけ上書き)。
                if folder_skipped > 0 && outcome.notice.is_none() {
                    outcome.notice = Some(format!(
                        "フォルダ {folder_skipped} 件はスキップしました (フォルダのドロップは現在無効です)"
                    ));
                }
                let _ = tx.send(outcome);
            });
        if let Err(e) = spawn_result {
            crate::logger::log(format!("file_drop: failed to spawn validate worker: {e}"));
            self.show_feedback_toast("コピー処理の起動に失敗しました".to_string());
            return;
        }
        self.drop_copy_pending.push(rx);
        self.show_feedback_toast(format!("{n_total} 件の項目をコピーしています…"));
    }

    /// 外部 D&D の copy worker 完了を拾い、完了ごとに `pending_reload` を立てる。
    /// 失敗があればトーストでユーザーに通知する。
    pub(crate) fn poll_file_drop_pending(&mut self) {
        if !self.drop_copy_pending.is_empty() {
            let mut completed: Vec<crate::ui_dialogs::context_menu::CopyOutcome> = Vec::new();
            self.drop_copy_pending.retain(|rx| match rx.try_recv() {
                Ok(outcome) => {
                    completed.push(outcome);
                    false
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => false,
                Err(std::sync::mpsc::TryRecvError::Empty) => true,
            });
            for outcome in completed {
                self.pending_reload = true;
                if outcome.failed > 0 {
                    let attempted = outcome.attempted;
                    let failed = outcome.failed;
                    let succeeded = attempted.saturating_sub(failed);
                    crate::logger::log(format!(
                        "file_drop: copy outcome attempted={attempted} succeeded={succeeded} failed={failed}"
                    ));
                    for err in &outcome.first_errors {
                        crate::logger::log(format!("file_drop: copy error: {err}"));
                    }
                    let summary = outcome.first_errors.first().cloned().unwrap_or_default();
                    let toast = if summary.is_empty() {
                        format!("ファイルコピー: 成功 {succeeded} / 失敗 {failed} (詳細はログ参照)")
                    } else {
                        format!("ファイルコピー: 成功 {succeeded} / 失敗 {failed} — 例: {summary}")
                    };
                    self.show_feedback_toast(toast);
                } else if let Some(notice) = outcome.notice {
                    // **Codex P2-2 対応**: 失敗ではないが通知が必要なケース
                    // (= 全件除外で実コピー未実行 等)。
                    crate::logger::log(format!("file_drop: notice: {notice}"));
                    self.show_feedback_toast(notice);
                }
            }
        }
    }

    pub(crate) fn poll_capture_pending(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.capture_pending.as_ref() else {
            return;
        };
        let result = match pending.rx.try_recv() {
            Ok(result) => result,
            Err(std::sync::mpsc::TryRecvError::Empty) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
                return;
            }
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                Err("キャプチャ保存が中断されました".to_string())
            }
        };
        self.capture_pending = None;
        match result {
            Ok(path) => {
                crate::logger::log(format!("capture saved: {}", path.display()));
                self.show_capture_saved_toast(path);
            }
            Err(err) => {
                crate::logger::log(format!("capture save failed: {err}"));
                self.show_feedback_toast(format!("保存できません: {err}"));
            }
        }
    }

    pub(crate) fn poll_compare_pin_pending(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.compare_pin_pending.as_ref() else {
            return;
        };
        let result = match pending.rx.try_recv() {
            Ok(result) => result,
            Err(std::sync::mpsc::TryRecvError::Empty) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
                return;
            }
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                Err("比較画像の準備が中断されました".to_string())
            }
        };
        let source_idx = pending.source_idx;
        self.compare_pin_pending = None;
        self.compare_pin_load_pending = None;
        match result {
            Ok(result) => {
                let expected = result.width as usize * result.height as usize * 4;
                let indicator_expected =
                    result.indicator_width as usize * result.indicator_height as usize * 4;
                if result.rgba.len() != expected
                    || result.indicator_rgba.len() != indicator_expected
                    || result.indicator_width == 0
                    || result.indicator_height == 0
                {
                    self.show_feedback_toast("比較画像のサイズが不正です".to_string());
                    return;
                }
                let pixels = egui::ColorImage::from_rgba_unmultiplied(
                    [result.width as usize, result.height as usize],
                    &result.rgba,
                );
                let display_name = result.basename;
                let indicator_pixels = egui::ColorImage::from_rgba_unmultiplied(
                    [
                        result.indicator_width as usize,
                        result.indicator_height as usize,
                    ],
                    &result.indicator_rgba,
                );
                self.pinned_compare_slot = Some(PinnedCompareSlot {
                    source_size: pixels.size,
                    pixels: Arc::new(pixels),
                    indicator_pixels: Arc::new(indicator_pixels),
                    indicator_texture: None,
                    display_name: display_name.clone(),
                    source_idx,
                });
                self.deactivate_compare_view();
                self.show_feedback_toast(format!("比較画像を設定: {display_name}"));
                ctx.request_repaint();
            }
            Err(err) => {
                crate::logger::log(format!("compare pin failed: {err}"));
                self.show_feedback_toast(format!("比較画像を設定できません: {err}"));
            }
        }
    }

    pub(crate) fn poll_compare_pin_load_pending(&mut self, ctx: &egui::Context) {
        let Some((source_idx, source_key)) = self
            .compare_pin_load_pending
            .as_ref()
            .map(|pending| (pending.source_idx, pending.source_key.clone()))
        else {
            return;
        };

        let Some(current_key) = self.metadata_cache_key(source_idx) else {
            self.compare_pin_load_pending = None;
            return;
        };
        if current_key != source_key {
            self.compare_pin_load_pending = None;
            return;
        }

        if self.compare_pin_pending.is_some() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
            return;
        }

        match self.fs_cache.get(&source_idx) {
            Some(FsCacheEntry::Static { .. }) | Some(FsCacheEntry::Animated { .. }) => {
                self.compare_pin_load_pending = None;
                self.start_compare_pin_single(ctx, source_idx);
            }
            Some(FsCacheEntry::Failed) => {
                self.compare_pin_load_pending = None;
                self.show_feedback_toast("比較画像を読み込めませんでした".to_string());
            }
            Some(FsCacheEntry::Video { .. }) => {
                self.compare_pin_load_pending = None;
                self.show_feedback_toast("動画は比較画像に設定できません".to_string());
            }
            None => {
                if !self.fs_pending.contains_key(&source_idx) {
                    self.start_fs_load(source_idx);
                }
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
            }
        }
    }

    pub(crate) fn poll_compare_prepare_pending(&mut self, ctx: &egui::Context) {
        let (pending, draining) = match &self.compare_preparation {
            ComparePreparationState::Preparing(pending) => (pending, false),
            ComparePreparationState::Draining(pending) => (pending, true),
            _ => return,
        };
        let result = match pending.rx.try_recv() {
            Ok(result) => result,
            Err(std::sync::mpsc::TryRecvError::Empty) => {
                return;
            }
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                Err("比較表示の準備が中断されました".to_string())
            }
        };
        let pending = match std::mem::replace(
            &mut self.compare_preparation,
            ComparePreparationState::Unprepared,
        ) {
            ComparePreparationState::Preparing(pending)
            | ComparePreparationState::Draining(pending) => pending,
            _ => unreachable!(),
        };
        let request = pending.request;
        let scope = pending.scope;

        if draining {
            crate::logger::log(
                "[compare-memory] stage=worker-result-drained reason=source-invalidated old_pair_release=before_next_worker",
            );
            ctx.request_repaint();
            return;
        }

        let active_output = ComparePrepareOutput::for_mode(
            self.compare_view_mode,
            cfg!(windows) && self.wgpu_render_state.is_some(),
        );
        if self.fullscreen_idx != Some(request.current_idx) || active_output != Some(request.output)
        {
            crate::logger::log(format!(
                "[compare-memory] stage=worker-result-discarded current_idx={} target_output={} active_idx={:?} active_output={} old_pair_release=before_worker",
                request.current_idx,
                request.output.label(),
                self.fullscreen_idx,
                active_output.map_or("off", ComparePrepareOutput::label),
            ));
            ctx.request_repaint();
            return;
        }

        match result {
            Ok(result) => {
                if result.current_idx != request.current_idx
                    || result.pinned_source_idx != request.pinned_source_idx
                {
                    return;
                }
                if !self
                    .pinned_compare_slot
                    .as_ref()
                    .is_some_and(|slot| slot.source_idx == result.pinned_source_idx)
                {
                    return;
                }
                // worker 開始後に PDF 表示解像度更新などの replacement load が始まる
                // 競合もある。snapshot 元のいずれかが更新中なら、旧 snapshot の完了を
                // Ready として公開せず source 確定後に作り直す。
                if pending
                    .source_indices
                    .iter()
                    .any(|idx| self.fs_pending.contains_key(idx))
                {
                    self.compare_preparation = ComparePreparationState::WaitingForSource(request);
                    ctx.request_repaint_after(std::time::Duration::from_millis(100));
                    return;
                }
                let result_size = [result.width as usize, result.height as usize];
                if result_size != pending.expected_target_size
                    || result.pixels.output() != request.output
                    || !result.pixels.valid_for_size(result_size)
                {
                    crate::logger::log(format!(
                        "compare prepare result withheld: current_idx={} pinned_idx={} expected={}x{} actual={}x{} expected_output={} actual_output={} cpu_bytes={}",
                        request.current_idx,
                        request.pinned_source_idx,
                        pending.expected_target_size[0],
                        pending.expected_target_size[1],
                        result_size[0],
                        result_size[1],
                        request.output.label(),
                        result.pixels.output().label(),
                        result.pixels.allocated_bytes(),
                    ));
                    self.compare_preparation = ComparePreparationState::WaitingForSource(request);
                    ctx.request_repaint_after(std::time::Duration::from_millis(100));
                    return;
                }

                crate::logger::log(format!(
                    "[compare-memory] stage=cpu-ready target={}x{} current_input={}x{} pinned_input={}x{} scope={} output={} prepare_ms={:.3} cpu_total_bytes={} cpu_buffers={} gpu_total_bytes=0 gpu_mips=not-allocated old_pair_release=before_worker",
                    result_size[0],
                    result_size[1],
                    pending.current_input_size[0],
                    pending.current_input_size[1],
                    pending.pinned_input_size[0],
                    pending.pinned_input_size[1],
                    scope.label(),
                    result.pixels.output().label(),
                    pending.started_at.elapsed().as_secs_f64() * 1000.0,
                    result.pixels.allocated_bytes(),
                    result.pixels.buffer_count(),
                ));
                let key = self.compare_prepared_next_key;
                self.compare_prepared_next_key =
                    self.compare_prepared_next_key.wrapping_add(1).max(1);
                self.compare_preparation = ComparePreparationState::Ready(ComparePreparedPair {
                    key,
                    current_idx: result.current_idx,
                    pinned_source_idx: result.pinned_source_idx,
                    current_input_size: pending.current_input_size,
                    pinned_input_size: pending.pinned_input_size,
                    target_size: result_size,
                    pixels: result.pixels,
                    pinned_texture: None,
                    current_texture: None,
                    diff_texture: None,
                });
                ctx.request_repaint();
            }
            Err(err) => {
                crate::logger::log(format!("compare prepare failed: {err}"));
                self.show_feedback_toast(format!("比較表示を準備できません: {err}"));
            }
        }
    }

    pub(crate) fn capture_output_dir_path(&self) -> PathBuf {
        self.settings
            .capture_output_dir
            .clone()
            .unwrap_or_else(crate::capture::default_output_dir)
    }

    pub(crate) fn open_capture_output_dir(&mut self) {
        let output_dir = self.capture_output_dir_path();
        crate::capture::open_output_dir_async(output_dir);
    }

    pub(crate) fn book_root_path(&self) -> PathBuf {
        self.settings.books_root_path()
    }

    pub(crate) fn active_book_name(&self) -> String {
        self.settings.active_book_name_or_default()
    }

    pub(crate) fn active_book_folder_path(&self) -> PathBuf {
        crate::books::book_folder(&self.book_root_path(), &self.active_book_name())
    }

    pub(crate) fn current_folder_is_book_folder(&self) -> bool {
        let Some(folder) = self.current_folder.as_ref() else {
            return false;
        };
        crate::books::is_direct_book_folder(&self.book_root_path(), folder)
    }

    /// 指定した読み込み対象がページ順を固定する「本」文脈か (= 一覧ソートが効かない)。
    /// 製本した本 / 閲覧履歴 / ZIP・PDF・直接閲覧RAR・変換キャッシュを開いている /
    /// 画像のみフォルダを本扱いしている場合に true。
    fn page_order_locked_for_items(
        &self,
        source_path: &Path,
        items: &[GridItem],
        view_kind: PageOrderViewKind,
    ) -> bool {
        if crate::books::is_direct_book_folder(&self.book_root_path(), source_path)
            || view_kind == PageOrderViewKind::ReadingHistory
        {
            return true;
        }
        if crate::folder_tree::is_open_as_container(source_path) {
            return true;
        }

        self.settings.auto_fullscreen_image_folders_enabled()
            && view_kind == PageOrderViewKind::Physical
            && Self::grid_items_are_image_only_folder_pages(items)
    }

    /// 現在のビュー用ラッパー。判定本体は読み込み前にも使える items 引数付き述語へ集約する。
    pub(crate) fn page_order_locked_for_current_view(&self) -> bool {
        if self.items_are_reading_history_view && self.current_folder.is_none() {
            return true;
        }
        let Some(current_folder) = self.current_folder.as_deref() else {
            return false;
        };
        let view_kind = if self.items_are_reading_history_view {
            PageOrderViewKind::ReadingHistory
        } else if self.items_are_rating_view
            || self.items_are_bookmark_view
            || self.items_are_global_search_view
            || self.items_are_tag_view
            || self.items_are_subfolder_expansion_view
            || self.items_are_smart_folder_view
        {
            PageOrderViewKind::Synthetic
        } else {
            PageOrderViewKind::for_loading_source(current_folder)
        };
        self.page_order_locked_for_items(current_folder, &self.items, view_kind)
    }

    fn book_bookmark_view_is_synthetic(&self) -> bool {
        self.items_are_reading_history_view
            || self.items_are_bookmark_view
            || self.items_are_rating_view
            || self.items_are_global_search_view
            || self.items_are_tag_view
            || self.items_are_subfolder_expansion_view
            || self.items_are_smart_folder_view
            || self.items_are_drive_list
    }

    /// 現在ページを、ページ番号ではなく安定したページ identity を持つ本ブックマークへ変換する。
    pub(crate) fn current_book_bookmark_draft(
        &self,
        idx: usize,
    ) -> Option<crate::book_bookmarks::NewBookBookmark> {
        use crate::book_bookmarks::{BookContainerKind, NewBookBookmark, PageIdentity};

        if self.book_bookmark_view_is_synthetic() {
            return None;
        }
        let item = self.items.get(idx)?;
        let (container_path, container_kind, page_identity) = match item {
            GridItem::Image(path) => {
                let folder = self.current_folder.as_ref()?;
                let kind = if self.current_folder_is_book_folder() {
                    BookContainerKind::CompiledBook
                } else if self.settings.auto_fullscreen_image_folders_enabled()
                    && !self.items.is_empty()
                    && self
                        .items
                        .iter()
                        .all(|item| matches!(item, GridItem::Image(_)))
                {
                    BookContainerKind::ImageFolder
                } else {
                    return None;
                };
                let relative = path
                    .strip_prefix(folder)
                    .ok()
                    .filter(|relative| !relative.as_os_str().is_empty())
                    .map(|relative| relative.to_string_lossy().into_owned())
                    .or_else(|| {
                        path.file_name()
                            .map(|name| name.to_string_lossy().into_owned())
                    })?;
                (folder.clone(), kind, PageIdentity::RelativePath(relative))
            }
            GridItem::ZipImage {
                zip_path,
                entry_name,
            } => {
                let container = self
                    .archive_source_override
                    .clone()
                    .unwrap_or_else(|| zip_path.clone());
                let ext = path_extension_lower(&container);
                let kind = if crate::folder_tree::is_zip_extension(&ext) {
                    BookContainerKind::Zip
                } else {
                    BookContainerKind::OtherArchive
                };
                (
                    container,
                    kind,
                    PageIdentity::ArchiveEntry(entry_name.clone()),
                )
            }
            GridItem::PdfPage {
                pdf_path, page_num, ..
            } => (
                pdf_path.clone(),
                BookContainerKind::Pdf,
                PageIdentity::PdfPage(*page_num),
            ),
            _ => return None,
        };
        Some(NewBookBookmark {
            container_path,
            container_kind,
            page_identity,
            page_index_hint: idx,
        })
    }

    fn next_book_bookmark_request_id(&mut self) -> u64 {
        self.book_bookmark_request_seq = self.book_bookmark_request_seq.wrapping_add(1).max(1);
        self.book_bookmark_request_seq
    }

    pub(crate) fn add_current_book_bookmark(&mut self, idx: usize) {
        let Some(entry) = self.current_book_bookmark_draft(idx) else {
            self.show_feedback_toast("この画像は本のブックマーク対象ではありません".to_string());
            return;
        };
        let request_id = self.next_book_bookmark_request_id();
        let Some(service) = self.book_bookmark_service.as_ref() else {
            self.show_feedback_toast("ブックマークDBを利用できません".to_string());
            return;
        };
        service.add(request_id, entry);
        self.book_bookmark_pending_requests.insert(request_id);
    }

    pub(crate) fn ensure_current_book_bookmarks_loaded(&mut self, idx: usize) {
        let Some(entry) = self.current_book_bookmark_draft(idx) else {
            self.current_book_bookmarks.clear();
            self.current_book_bookmarks_key = None;
            self.current_book_bookmarks_request = None;
            self.clear_book_bookmark_title_edit();
            return;
        };
        let key = crate::book_bookmarks::container_key(&entry.container_path);
        if self.current_book_bookmarks_key.as_deref() == Some(key.as_str())
            || self
                .current_book_bookmarks_request
                .as_ref()
                .is_some_and(|(_, pending_key)| pending_key == &key)
        {
            return;
        }
        // 別の本へ移動した直後に、旧コンテナの行を新しい本の行として一瞬表示しない。
        self.current_book_bookmarks.clear();
        self.current_book_bookmarks_key = None;
        self.clear_book_bookmark_title_edit();
        let request_id = self.next_book_bookmark_request_id();
        if let Some(service) = self.book_bookmark_service.as_ref() {
            service.list_for_container(request_id, entry.container_path);
            self.current_book_bookmarks_request = Some((request_id, key));
            self.book_bookmark_pending_requests.insert(request_id);
        }
    }

    pub(crate) fn remove_book_bookmark(&mut self, id: i64) {
        let request_id = self.next_book_bookmark_request_id();
        if let Some(service) = self.book_bookmark_service.as_ref() {
            service.remove(request_id, id);
            self.book_bookmark_pending_requests.insert(request_id);
        }
    }

    pub(crate) fn set_book_bookmark_title(&mut self, id: i64, title: String) {
        let request_id = self.next_book_bookmark_request_id();
        let Some(service) = self.book_bookmark_service.as_ref() else {
            self.show_feedback_toast("ブックマークDBを利用できません".to_string());
            return;
        };
        service.set_title(request_id, id, title);
        self.book_bookmark_pending_requests.insert(request_id);
    }

    pub(crate) fn poll_book_bookmarks(&mut self) {
        loop {
            let event = match self
                .book_bookmark_service
                .as_ref()
                .map(|service| service.try_recv())
            {
                Some(Ok(event)) => event,
                Some(Err(std::sync::mpsc::TryRecvError::Empty)) | None => break,
                Some(Err(std::sync::mpsc::TryRecvError::Disconnected)) => {
                    self.book_bookmark_service = None;
                    self.book_bookmark_pending_requests.clear();
                    self.current_book_bookmarks_request = None;
                    self.clear_book_bookmark_title_edit();
                    self.show_feedback_toast("ブックマークDBとの接続が終了しました".to_string());
                    break;
                }
            };
            match event {
                crate::book_bookmarks::BookBookmarkEvent::Added { request_id, result } => {
                    self.book_bookmark_pending_requests.remove(&request_id);
                    match result {
                        Ok((bookmark, inserted)) => {
                            if self.current_book_bookmarks_key.as_deref()
                                == Some(bookmark.container_key.as_str())
                                && !self
                                    .current_book_bookmarks
                                    .iter()
                                    .any(|entry| entry.id == bookmark.id)
                            {
                                self.current_book_bookmarks.push(bookmark);
                                self.current_book_bookmarks.sort_by_key(|entry| {
                                    (entry.page_index_hint, entry.created_at_ms)
                                });
                            }
                            self.show_feedback_toast(if inserted {
                                "ブックマークを追加しました".to_string()
                            } else {
                                "このページはブックマーク済みです".to_string()
                            });
                            if inserted {
                                self.notify_bookmarks_changed();
                            }
                        }
                        Err(err) => self
                            .show_feedback_toast(format!("ブックマーク追加に失敗しました: {err}")),
                    }
                }
                crate::book_bookmarks::BookBookmarkEvent::Removed { request_id, result } => {
                    self.book_bookmark_pending_requests.remove(&request_id);
                    match result {
                        Ok(id) => {
                            self.current_book_bookmarks.retain(|entry| entry.id != id);
                            if self.book_bookmark_title_edit.as_ref().map(|edit| edit.id)
                                == Some(id)
                            {
                                self.clear_book_bookmark_title_edit();
                            }
                            self.notify_bookmarks_changed();
                            self.show_feedback_toast("ブックマークを削除しました".to_string());
                        }
                        Err(err) => self
                            .show_feedback_toast(format!("ブックマーク削除に失敗しました: {err}")),
                    }
                }
                crate::book_bookmarks::BookBookmarkEvent::TitleUpdated { request_id, result } => {
                    self.book_bookmark_pending_requests.remove(&request_id);
                    match result {
                        Ok((id, title)) => {
                            if let Some(bookmark) = self
                                .current_book_bookmarks
                                .iter_mut()
                                .find(|bookmark| bookmark.id == id)
                            {
                                bookmark.title = title;
                            }
                            if self.book_bookmark_title_edit.as_ref().map(|edit| edit.id)
                                == Some(id)
                            {
                                self.clear_book_bookmark_title_edit();
                            }
                            if self.items_are_bookmark_view {
                                self.refresh_bookmark_browser();
                            }
                            self.show_feedback_toast("ブックマーク名を更新しました".to_string());
                        }
                        Err(err) => self.show_feedback_toast(format!(
                            "ブックマーク名の更新に失敗しました: {err}"
                        )),
                    }
                }
                crate::book_bookmarks::BookBookmarkEvent::ContainerListed {
                    request_id,
                    container_key,
                    result,
                } => {
                    self.book_bookmark_pending_requests.remove(&request_id);
                    if self.current_book_bookmarks_request.as_ref().is_some_and(
                        |(pending_id, pending_key)| {
                            *pending_id == request_id && pending_key == &container_key
                        },
                    ) {
                        self.current_book_bookmarks_request = None;
                        match result {
                            Ok(rows) => {
                                self.current_book_bookmarks = rows;
                                self.current_book_bookmarks_key = Some(container_key);
                            }
                            Err(err) => {
                                // 同じ失敗要求を毎フレーム再送して toast を繰り返さない。
                                // 別コンテナへ移動して戻れば再試行される。
                                self.current_book_bookmarks_key = Some(container_key);
                                self.show_feedback_toast(format!(
                                    "ブックマーク一覧を読み込めませんでした: {err}"
                                ));
                            }
                        }
                    }
                }
                crate::book_bookmarks::BookBookmarkEvent::AllListed { request_id, .. } => {
                    self.book_bookmark_pending_requests.remove(&request_id);
                }
                crate::book_bookmarks::BookBookmarkEvent::PathsMigrated { request_id, result } => {
                    self.book_bookmark_pending_requests.remove(&request_id);
                    match result {
                        Ok(rows) => {
                            if rows > 0 {
                                self.invalidate_book_bookmarks_after_path_migration();
                            }
                        }
                        Err(error) => {
                            crate::logger::log(format!(
                                "book bookmark path migration failed: {error}"
                            ));
                            self.show_feedback_toast(
                                "本ブックマークの引き継ぎに失敗しました".to_string(),
                            );
                        }
                    }
                }
            }
        }
    }

    fn invalidate_book_bookmarks_after_path_migration(&mut self) {
        self.current_book_bookmarks.clear();
        self.current_book_bookmarks_key = None;
        self.current_book_bookmarks_request = None;
        self.clear_book_bookmark_title_edit();
        self.notify_bookmarks_changed();
    }

    pub(crate) fn book_bookmark_item_idx(
        &self,
        bookmark: &crate::book_bookmarks::BookBookmark,
    ) -> Option<usize> {
        let normalize = |value: &str| value.replace('\\', "/").to_lowercase();
        self.items.iter().enumerate().find_map(|(idx, item)| {
            let matches = match (&bookmark.page_identity, item) {
                (
                    crate::book_bookmarks::PageIdentity::RelativePath(relative),
                    GridItem::Image(path),
                ) => {
                    let container = self.current_folder.as_ref()?;
                    path.strip_prefix(container)
                        .ok()
                        .map(|value| normalize(&value.to_string_lossy()) == normalize(relative))
                        .unwrap_or(false)
                }
                (
                    crate::book_bookmarks::PageIdentity::ArchiveEntry(wanted),
                    GridItem::ZipImage { entry_name, .. },
                ) => normalize(entry_name) == normalize(wanted),
                (
                    crate::book_bookmarks::PageIdentity::PdfPage(wanted),
                    GridItem::PdfPage { page_num, .. },
                ) => page_num == wanted,
                _ => false,
            };
            matches.then_some(idx)
        })
    }

    pub(crate) fn jump_to_current_book_bookmark(
        &mut self,
        ctx: &egui::Context,
        bookmark: &crate::book_bookmarks::BookBookmark,
    ) {
        let mut item_idx = self.book_bookmark_item_idx(bookmark);
        if item_idx.is_none() && self.enter_book_bookmark_archive_prefix(bookmark) {
            item_idx = self.book_bookmark_item_idx(bookmark);
        }
        if let Some(idx) = item_idx {
            let provenance = match &bookmark.page_identity {
                crate::book_bookmarks::PageIdentity::RelativePath(relative) => {
                    let Some(provenance) =
                        crate::book_bookmarks::RelativePageProvenance::unresolved(
                            &bookmark.container_path,
                            relative,
                        )
                    else {
                        self.show_feedback_toast(
                            "ブックマーク先のページが不正です（記録は保持されます）".to_string(),
                        );
                        return;
                    };
                    Some(provenance)
                }
                _ => None,
            };
            self.open_bookmark_item_with_provenance(ctx, idx, provenance);
        } else {
            self.show_feedback_toast(
                "ブックマーク先のページが見つかりません（記録は保持されます）".to_string(),
            );
        }
    }

    /// ネスト ZIP の現在表示階層に無いページへ、ブックマークの entry prefix を使って移動する。
    ///
    /// 左パネルと横断一覧のどちらから開いても同じ階層解決を通すことで、現在
    /// materialize 済みの `items` だけに到達可否を左右させない。
    fn enter_book_bookmark_archive_prefix(
        &mut self,
        bookmark: &crate::book_bookmarks::BookBookmark,
    ) -> bool {
        let crate::book_bookmarks::PageIdentity::ArchiveEntry(entry_name) = &bookmark.page_identity
        else {
            return false;
        };
        let normalized = entry_name.replace('\\', "/");
        // `/` を含まない entry の親は ZIP root (`[]`)。保存済み identity に先頭 `/`
        // や `\\` が混ざっていても、空 segment を除いた絶対 prefix として解決する。
        let prefix = normalized
            .rsplit_once('/')
            .map(|(prefix, _)| prefix)
            .unwrap_or_default();
        let segments: Vec<String> = prefix
            .split('/')
            .filter(|segment| !segment.is_empty())
            .map(str::to_string)
            .collect();
        let Some(nav) = self.zip_nav.as_mut() else {
            return false;
        };
        // `ZipNavState::enter` は通常 UI の実在 `ZipDir` 用で、任意 prefix 自体は検証しない。
        // bookmark identity は stale になり得るため、現在階層を変更する前に tree 上の存在を
        // 確認する。root の空 segments は `node_at(&[])` で有効になる。
        if nav.tree.node_at(&segments).is_none() {
            return false;
        }
        let absolute_prefix = if segments.is_empty() {
            String::new()
        } else {
            format!("{}/", segments.join("/"))
        };
        nav.enter(&absolute_prefix);
        self.zip_nav_show_current_level();
        true
    }

    pub(crate) fn ensure_bookmark_panel_thumbnails(&mut self, indices: &[usize]) {
        if indices.is_empty() {
            return;
        }
        for &idx in indices {
            if idx < self.items.len() {
                self.keep_set.insert(idx);
            }
        }
        if let (Some(first), Some(last)) =
            (indices.iter().copied().min(), indices.iter().copied().max())
        {
            self.keep_start_shared.store(first, Ordering::Relaxed);
            self.keep_end_shared
                .store(last.saturating_add(1), Ordering::Relaxed);
            for &idx in indices {
                self.enqueue_details_hover_thumbnail(idx);
            }
        }
    }

    fn ensure_bookmark_presence_loaded(&mut self) {
        if self.settings.facet_filter.uses_bookmark_state()
            && self.bookmark_presence.is_none()
            && self.bookmark_presence_pending.is_none()
        {
            self.refresh_bookmark_presence();
        }
    }

    fn refresh_bookmark_presence(&mut self) {
        if let Some(pending) = self.bookmark_presence_pending.take() {
            pending.cancel();
        }
        self.bookmark_presence_pending = Some(crate::bookmark_browser::spawn_presence_build());
    }

    /// 動画・音声・本のブックマーク CRUD 後に、状態フィルタと保存済みスマートフォルダを
    /// 同じ DB 状態へ追従させる。通常一覧の DB 再読込は必要なセッションだけ非同期で行う。
    pub(crate) fn notify_bookmarks_changed(&mut self) {
        if self.bookmark_presence.is_some()
            || self.bookmark_presence_pending.is_some()
            || self.settings.facet_filter.uses_bookmark_state()
        {
            self.refresh_bookmark_presence();
        }
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Bookmarks,
        );
        if self.items_are_bookmark_view {
            self.refresh_bookmark_browser();
        }
    }

    fn poll_bookmark_presence(&mut self, ctx: &egui::Context) {
        let result = self.bookmark_presence_pending.as_ref().and_then(|pending| {
            match pending.rx.try_recv() {
                Ok(result) => Some(result),
                Err(std::sync::mpsc::TryRecvError::Empty) => None,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    Some(Err("ブックマーク状態ワーカーが終了しました".to_string()))
                }
            }
        });
        if let Some(result) = result {
            self.bookmark_presence_pending = None;
            match result {
                Ok(presence) => {
                    self.bookmark_presence = Some(presence);
                    if self.settings.facet_filter.uses_bookmark_state() {
                        self.rebuild_all_viewer_context_visible_indices();
                    }
                }
                Err(error) if error == "cancelled" => {}
                Err(error) => {
                    // 読み込み失敗を毎フレーム再試行しない。空 snapshot なら「あり」は 0 件、
                    // 「なし」は全件となり、フィルタ結果が未確定のまま残らない。
                    self.bookmark_presence = Some(Default::default());
                    if self.settings.facet_filter.uses_bookmark_state() {
                        self.rebuild_all_viewer_context_visible_indices();
                    }
                    self.show_feedback_toast(format!(
                        "ブックマーク状態を読み込めませんでした: {error}"
                    ));
                }
            }
        }
        if self.bookmark_presence_pending.is_some() {
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
        }
    }

    /// App-globalなbookmark snapshotの更新を、保持中の全viewer contextの
    /// context-owned表示集合へ反映する。DB I/Oは行わず、各bundleをmountして
    /// `visible_indices` / facet / details order / selectionを一体で再計算する。
    fn rebuild_all_viewer_context_visible_indices(&mut self) {
        self.rebuild_visible_indices_preserving_facet_scope();
        #[cfg(windows)]
        {
            if let Some(mut active) = self.active_detached_viewer_context.take() {
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.rebuild_visible_indices_preserving_facet_scope();
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.active_detached_viewer_context = Some(active);
            }
            for window_index in 0..self.detached_image_windows.len() {
                let Some(mut bundle) = self.detached_image_windows[window_index]
                    .paused_bundle
                    .take()
                else {
                    continue;
                };
                self.swap_viewer_context_bundle(&mut bundle);
                self.rebuild_visible_indices_preserving_facet_scope();
                self.swap_viewer_context_bundle(&mut bundle);
                self.detached_image_windows[window_index].paused_bundle = Some(bundle);
            }
        }
    }

    fn item_has_bookmark(
        &self,
        idx: usize,
        item: &GridItem,
        presence: &crate::bookmark_browser::BookmarkPresence,
    ) -> bool {
        if self.items_are_bookmark_view && self.bookmark_browser_rows.get(idx).is_some() {
            return true;
        }
        match item {
            GridItem::Video(path) | GridItem::Audio(path) => presence.has_media_path(path),
            GridItem::Folder(path)
            | GridItem::ZipFile(path)
            | GridItem::PdfFile(path)
            | GridItem::ConvertibleArchive { path, .. } => presence.has_book_container(path),
            GridItem::SearchContainer { path, .. } => presence.has_book_container(path),
            GridItem::ZipDir {
                zip_path,
                dir_prefix,
                ..
            } => {
                let container = self.archive_source_override.as_deref().unwrap_or(zip_path);
                presence.has_archive_prefix(container, dir_prefix)
            }
            GridItem::Image(_) | GridItem::ZipImage { .. } | GridItem::PdfPage { .. } => {
                self.current_book_bookmark_draft(idx).is_some_and(|draft| {
                    presence.has_book_page(&draft.container_path, &draft.page_identity)
                })
            }
            GridItem::Stack { .. } => false,
        }
    }

    pub(crate) fn open_bookmark_browser(&mut self) {
        self.clear_bookmark_view_return_state();
        self.record_folder_nav_transition(&bookmark_view_synthetic_path());
        self.bookmark_view_sort = crate::bookmark_browser::BookmarkViewSort::default();
        self.enter_bookmark_view();
    }

    /// 動画・音声・本のブックマークを、通常のメイン一覧 surface へ読み込む。
    pub(crate) fn enter_bookmark_view(&mut self) {
        // Embedded viewer close transitions the explicit origin state to Restoring. A detached
        // context never calls this: its main context already owns the mounted bookmark grid.
        self.bookmark_view_begin_restore();
        self.gamepad_location_picker = None;
        if self.global_search.active {
            self.global_search.saved_folder = None;
            self.close_global_search();
        }
        if self.favsearch.active {
            self.favsearch.saved_folder = None;
            self.close_favsearch();
        }
        if self.tag_view.active {
            self.tag_view.saved_folder = None;
            self.close_tag_view();
        }
        if self.show_search_bar {
            self.show_search_bar = false;
            self.search_query.clear();
            self.search_filter = None;
            self.search_filter_origin_folder = None;
            self.search_has_focus = false;
            self.search_tag_bridge.clear();
            self.cancel_search_pending();
        }
        if let Some(pending) = self.bookmark_browser_pending.take() {
            pending.cancel();
        }
        self.bookmark_browser_rows.clear();
        self.start_loading_items(
            bookmark_view_synthetic_path(),
            Vec::new(),
            Vec::new(),
            std::collections::HashSet::new(),
            Vec::new(),
            None,
        );
        self.items_are_bookmark_view = true;
        self.top_level_grid_view
            .replace_surface(top_level_grid_view::TopLevelGridSurface::Bookmarks);
        self.address = "ブックマークを読み込み中…".to_string();
        self.refresh_bookmark_browser();
    }

    pub(crate) fn refresh_bookmark_browser(&mut self) {
        if let Some(pending) = self.bookmark_browser_pending.take() {
            pending.cancel();
        }
        self.bookmark_browser_pending = Some(crate::bookmark_browser::spawn_build());
    }

    pub(crate) fn delete_bookmark_browser_rows(
        &mut self,
        rows: &[crate::bookmark_browser::BookmarkBrowserRow],
    ) {
        if !rows.is_empty() && self.bookmark_delete_pending.is_none() {
            self.bookmark_delete_pending = Some(crate::bookmark_browser::spawn_delete(rows));
        }
    }

    pub(crate) fn delete_selected_bookmarks(&mut self) {
        if !self.items_are_bookmark_view || self.bookmark_delete_pending.is_some() {
            return;
        }
        let indices: Vec<usize> = if self.checked.is_empty() {
            self.selected.into_iter().collect()
        } else {
            self.checked.iter().copied().collect()
        };
        let rows: Vec<_> = indices
            .into_iter()
            .filter_map(|idx| self.bookmark_browser_rows.get(idx).cloned())
            .collect();
        self.delete_bookmark_browser_rows(&rows);
    }

    pub(crate) fn bookmark_view_row(
        &self,
        idx: usize,
    ) -> Option<&crate::bookmark_browser::BookmarkBrowserRow> {
        self.items_are_bookmark_view
            .then(|| self.bookmark_browser_rows.get(idx))
            .flatten()
    }

    pub(crate) fn set_bookmark_view_sort(
        &mut self,
        sort: crate::bookmark_browser::BookmarkViewSort,
    ) {
        self.bookmark_view_sort = sort;
        if self.items_are_bookmark_view {
            self.install_bookmark_view_rows();
        }
    }

    fn install_bookmark_view_rows(&mut self) {
        let previous_selected = self.selected;
        let previous_key = previous_selected
            .and_then(|idx| self.bookmark_browser_rows.get(idx))
            .map(crate::bookmark_browser::BookmarkBrowserRow::stable_key);
        let return_grid = self.take_bookmark_restore_grid();
        crate::bookmark_browser::sort_rows(
            &mut self.bookmark_browser_rows,
            self.bookmark_view_sort,
        );
        let mut items: Vec<GridItem> = self
            .bookmark_browser_rows
            .iter()
            .map(|row| row.item.clone())
            .collect();
        let mut image_metas: Vec<Option<(i64, i64)>> = self
            .bookmark_browser_rows
            .iter()
            .map(|row| row.image_meta)
            .collect();
        crate::grid_item::arrange_grid_items(
            &mut items,
            &mut image_metas,
            &self.settings.grid_display_order,
            None,
        );
        let mut rows_by_item: std::collections::HashMap<
            String,
            std::collections::VecDeque<crate::bookmark_browser::BookmarkBrowserRow>,
        > = std::collections::HashMap::new();
        for row in self.bookmark_browser_rows.drain(..) {
            rows_by_item
                .entry(row.item.perf_key())
                .or_default()
                .push_back(row);
        }
        self.bookmark_browser_rows = items
            .iter()
            .map(|item| {
                rows_by_item
                    .get_mut(&item.perf_key())
                    .and_then(std::collections::VecDeque::pop_front)
                    .expect("arranged bookmark item must retain its source row")
            })
            .collect();
        let installed_keys: Vec<_> = self
            .bookmark_browser_rows
            .iter()
            .map(crate::bookmark_browser::BookmarkBrowserRow::stable_key)
            .collect();
        let video_items: Vec<(usize, PathBuf, u64)> = self
            .bookmark_browser_rows
            .iter()
            .enumerate()
            .filter_map(|(idx, row)| match &row.item {
                GridItem::Video(path) if !row.missing && row.marker_thumbnail.is_none() => {
                    let size = row
                        .image_meta
                        .map(|(_, size)| size.max(0) as u64)
                        .unwrap_or(0);
                    Some((idx, path.clone(), size))
                }
                _ => None,
            })
            .collect();
        let existing_keys = std::collections::HashSet::new();
        self.start_loading_items(
            bookmark_view_synthetic_path(),
            items,
            image_metas,
            existing_keys,
            video_items,
            None,
        );
        self.items_are_bookmark_view = true;
        self.top_level_grid_view
            .replace_surface(top_level_grid_view::TopLevelGridSurface::Bookmarks);
        self.address = "ブックマーク".to_string();
        for (idx, image) in self
            .bookmark_browser_rows
            .iter()
            .enumerate()
            .filter_map(|(idx, row)| row.marker_thumbnail.as_ref().map(|image| (idx, image)))
        {
            let [width, height] = image.size;
            self.texture_backlog.push(crate::thumb_loader::ThumbMsg {
                idx,
                image: Some((**image).clone()),
                origin: crate::thumb_loader::ThumbLoadOrigin::FinalCache,
                from_edit_preview: false,
                edit_preview_adjustment: None,
                source_dims: Some((width as u32, height as u32)),
                canceled: false,
                finalized: false,
                input_seq: self.input_seq,
                items_gen: self.items_generation,
            });
        }
        self.rebuild_visible_indices();
        if let Some(return_grid) = return_grid {
            self.restore_bookmark_view_grid(return_grid, &installed_keys);
        } else {
            self.selected = previous_key
                .and_then(|key| {
                    self.bookmark_browser_rows
                        .iter()
                        .position(|row| row.stable_key() == key)
                })
                .filter(|idx| self.visible_indices.contains(idx))
                .or_else(|| self.visible_indices.first().copied());
            self.scroll_to_selected = self.selected.is_some();
        }
    }

    fn restore_bookmark_view_grid(
        &mut self,
        return_grid: BookmarkViewReturnGridState,
        installed_keys: &[(u8, i64)],
    ) {
        let rows_changed = return_grid.row_keys != installed_keys;
        let restore_key = if rows_changed {
            Some(return_grid.opened_key)
        } else {
            return_grid.selected_key
        };
        self.selected = restore_key
            .and_then(|key| {
                self.bookmark_browser_rows
                    .iter()
                    .position(|row| row.stable_key() == key)
            })
            .filter(|idx| self.visible_indices.contains(idx));
        self.scroll_offset_y = return_grid.scroll_offset_y;
        self.pending_grid_scroll = None;
        // 同一一覧なら位置を一切動かさない。一覧が増減・並べ替えされた場合だけ、
        // 開いていた行が見切れていれば既存の ensure-visible 処理に任せる。
        self.scroll_to_selected = rows_changed && self.selected.is_some();
    }

    pub(crate) fn open_bookmark_browser_row(
        &mut self,
        ctx: &egui::Context,
        row: &crate::bookmark_browser::BookmarkBrowserRow,
    ) {
        if row.missing {
            self.show_feedback_toast(
                "ブックマーク先が見つかりません（記録は保持されます）".to_string(),
            );
            return;
        }
        if let Some(previous_request_id) = self
            .bookmark_open_pending
            .as_ref()
            .map(crate::bookmark_browser::PendingBookmarkOpen::request_id)
        {
            self.cancel_bookmark_open_request(previous_request_id, "bookmark_replaced");
        }
        let return_grid = BookmarkViewReturnGridState::capture(
            &self.bookmark_browser_rows,
            self.selected,
            row.stable_key(),
            self.scroll_offset_y,
        );
        self.bookmark_open_request_seq = self
            .bookmark_open_request_seq
            .checked_add(1)
            .expect("bookmark open request sequence exhausted");
        let request_id =
            crate::bookmark_browser::BookmarkOpenRequestId(self.bookmark_open_request_seq);
        match &row.source {
            crate::bookmark_browser::BookmarkRowSource::Media { path, pts_secs, .. } => {
                let target = crate::bookmark_browser::BookmarkViewReturnTarget::Media(path.clone());
                self.bookmark_view_state = Some(BookmarkViewState::Opening {
                    target,
                    grid: return_grid,
                });
                crate::logger::log(format!(
                    "[bookmark-open] request media path={} pts={:.3} presentation={:?}",
                    path.display(),
                    pts_secs,
                    self.viewer_presentation
                ));
                self.bookmark_open_pending =
                    Some(crate::bookmark_browser::PendingBookmarkOpen::Media(
                        crate::bookmark_browser::PendingMediaOpen {
                            request_id,
                            path: path.clone(),
                            pts_secs: *pts_secs,
                            started_at: std::time::Instant::now(),
                            last_wait: None,
                        },
                    ));
                self.start_startup_open_path_resolve(
                    path.clone(),
                    StartupOpenPathSource::Bookmark,
                    ctx,
                );
            }
            crate::bookmark_browser::BookmarkRowSource::Book(bookmark) => {
                let target = crate::bookmark_browser::BookmarkViewReturnTarget::Book(
                    bookmark.container_path.clone(),
                );
                self.bookmark_view_state = Some(BookmarkViewState::Opening {
                    target,
                    grid: return_grid,
                });
                crate::logger::log(format!(
                    "[bookmark-open] request book container={} page={} presentation={:?}",
                    bookmark.container_path.display(),
                    bookmark.page_identity.display_name(),
                    self.viewer_presentation
                ));
                self.bookmark_open_pending =
                    Some(crate::bookmark_browser::PendingBookmarkOpen::Book(
                        crate::bookmark_browser::PendingBookOpen {
                            request_id,
                            bookmark: bookmark.clone(),
                            relative_page_provenance: row.relative_page_provenance.clone(),
                            started_at: std::time::Instant::now(),
                            stage: crate::bookmark_browser::PendingBookOpenStage::Resolving,
                        },
                    ));
                self.start_startup_open_path_resolve(
                    bookmark.container_path.clone(),
                    StartupOpenPathSource::Bookmark,
                    ctx,
                );
            }
        }
    }

    pub(crate) fn poll_bookmark_browser(&mut self, ctx: &egui::Context) {
        let build_result = self
            .bookmark_browser_pending
            .as_ref()
            .and_then(|pending| match pending.rx.try_recv() {
                Ok(result) => Some(result),
                Err(std::sync::mpsc::TryRecvError::Empty) => None,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    Some(Err("ブックマーク一覧ワーカーが終了しました".to_string()))
                }
            });
        if let Some(result) = build_result {
            self.bookmark_browser_pending = None;
            match result {
                Ok(rows) => {
                    let grid_content_unchanged = self.items_are_bookmark_view
                        && crate::bookmark_browser::rows_have_same_grid_content(
                            &self.bookmark_browser_rows,
                            &rows,
                        );
                    if grid_content_unchanged {
                        // detached viewer の close 時も DB は再照合するが、行が同じなら
                        // start_loading_items で可視グリッドとタグキャッシュを作り直さない。
                        // return snapshot は現在の一覧がそのまま残っているので消費済みにする。
                        if matches!(
                            self.bookmark_view_state,
                            Some(BookmarkViewState::Restoring { .. })
                        ) {
                            self.bookmark_view_state = None;
                        }
                        crate::logger::log(
                            "[bookmark-open] bookmark grid refresh unchanged; keep mounted grid",
                        );
                    } else {
                        self.bookmark_browser_rows = rows;
                    }
                    if self.items_are_bookmark_view && !grid_content_unchanged {
                        self.install_bookmark_view_rows();
                    }
                }
                Err(err) => {
                    if matches!(
                        self.bookmark_view_state,
                        Some(BookmarkViewState::Restoring { .. })
                    ) {
                        self.bookmark_view_state = None;
                    }
                    self.show_feedback_toast(format!(
                        "ブックマーク一覧を読み込めませんでした: {err}"
                    ));
                }
            }
        }

        let delete_result = self
            .bookmark_delete_pending
            .as_ref()
            .and_then(|pending| match pending.rx.try_recv() {
                Ok(result) => Some((pending.keys.clone(), result)),
                Err(std::sync::mpsc::TryRecvError::Empty) => None,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => Some((
                    pending.keys.clone(),
                    Err("ブックマーク削除ワーカーが終了しました".to_string()),
                )),
            });
        if let Some((keys, result)) = delete_result {
            self.bookmark_delete_pending = None;
            match result {
                Ok(()) => {
                    let key_set: std::collections::HashSet<_> = keys.iter().copied().collect();
                    self.bookmark_browser_rows
                        .retain(|row| !key_set.contains(&row.stable_key()));
                    self.current_book_bookmarks
                        .retain(|bookmark| !key_set.contains(&(1, bookmark.id)));
                    self.checked.clear();
                    if self.items_are_bookmark_view {
                        self.install_bookmark_view_rows();
                    }
                    self.notify_bookmarks_changed();
                    self.show_feedback_toast(format!(
                        "ブックマークを {} 件削除しました",
                        keys.len()
                    ));
                }
                Err(err) => {
                    self.show_feedback_toast(format!("ブックマーク削除に失敗しました: {err}"))
                }
            }
        }

        self.poll_bookmark_media_open(ctx);
        self.poll_bookmark_book_open(ctx);
        if self.bookmark_browser_pending.is_some()
            || self.bookmark_delete_pending.is_some()
            || self.bookmark_open_pending.is_some()
        {
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
        }
    }

    fn note_bookmark_media_open_wait(
        &mut self,
        wait: crate::bookmark_browser::PendingMediaOpenWait,
    ) {
        let Some(pending) = self
            .bookmark_open_pending
            .as_ref()
            .and_then(crate::bookmark_browser::PendingBookmarkOpen::media)
        else {
            return;
        };
        if pending.last_wait == Some(wait) {
            return;
        }
        let fullscreen_idx = self.fullscreen_idx;
        let current_item = fullscreen_idx
            .and_then(|idx| self.items.get(idx))
            .map(GridItem::display_path)
            .unwrap_or_else(|| "<none>".to_string());
        let player_diag = fullscreen_idx
            .and_then(|idx| self.fs_cache.get(&idx))
            .and_then(|entry| match entry {
                FsCacheEntry::Video { player, .. } => Some(format!(
                    "path={} info={} state={} pos={:.3} serial={}",
                    player.path().display(),
                    player.info().is_some(),
                    player.engine_state_name(),
                    player.position(),
                    player.current_seek_serial()
                )),
                _ => None,
            })
            .unwrap_or_else(|| "<none>".to_string());
        crate::logger::log(format!(
            "[bookmark-open] wait={} elapsed_ms={} target={} pts={:.3} presentation={:?} fullscreen_idx={:?} current_item={} player={}",
            wait.label(),
            pending.started_at.elapsed().as_millis(),
            pending.path.display(),
            pending.pts_secs,
            self.viewer_presentation,
            fullscreen_idx,
            current_item,
            player_diag
        ));
        if let Some(pending) = self
            .bookmark_open_pending
            .as_mut()
            .and_then(crate::bookmark_browser::PendingBookmarkOpen::media_mut)
        {
            pending.last_wait = Some(wait);
        }
    }

    fn poll_bookmark_media_open(&mut self, _ctx: &egui::Context) {
        let Some(pending) = self
            .bookmark_open_pending
            .as_ref()
            .and_then(crate::bookmark_browser::PendingBookmarkOpen::media)
            .cloned()
        else {
            return;
        };
        if pending.started_at.elapsed() > std::time::Duration::from_secs(30) {
            let current_item = self
                .fullscreen_idx
                .and_then(|idx| self.items.get(idx))
                .map(GridItem::display_path)
                .unwrap_or_else(|| "<none>".to_string());
            crate::logger::log(format!(
                "[bookmark-open] timeout media target={} pts={:.3} last_wait={:?} presentation={:?} fullscreen_idx={:?} current_item={}",
                pending.path.display(),
                pending.pts_secs,
                pending.last_wait,
                self.viewer_presentation,
                self.fullscreen_idx,
                current_item
            ));
            self.cancel_bookmark_open_request(pending.request_id, "media_timeout");
            self.show_feedback_toast("ブックマーク位置を開けませんでした".to_string());
            return;
        }
        let Some(idx) = self.fullscreen_idx else {
            self.note_bookmark_media_open_wait(
                crate::bookmark_browser::PendingMediaOpenWait::Fullscreen,
            );
            return;
        };
        let path_matches = self.items.get(idx).is_some_and(|item| match item {
            GridItem::Video(path) | GridItem::Audio(path) => {
                crate::path_key::eq_keep_drive(path, &pending.path)
            }
            _ => false,
        });
        if !path_matches {
            self.note_bookmark_media_open_wait(
                crate::bookmark_browser::PendingMediaOpenWait::MatchingPath,
            );
            return;
        }
        let Some(FsCacheEntry::Video { player, .. }) = self.fs_cache.get(&idx) else {
            self.note_bookmark_media_open_wait(
                crate::bookmark_browser::PendingMediaOpenWait::Player,
            );
            return;
        };
        if !crate::path_key::eq_keep_drive(player.path(), &pending.path) {
            self.note_bookmark_media_open_wait(
                crate::bookmark_browser::PendingMediaOpenWait::Player,
            );
            return;
        }
        // player は info 到着前に fs_cache へ入る。ここで先に marker seek を出すと、
        // info 受信時の open-time resume が後から同じ clock を上書きしてしまう。
        // resume の適用が完了した `info.is_some()` を所有境界として待ち、その後に
        // ユーザーが選んだブックマーク位置を最後の seek として発行する。
        if player.info().is_none() {
            self.note_bookmark_media_open_wait(
                crate::bookmark_browser::PendingMediaOpenWait::PlayerInfo,
            );
            return;
        }
        let target = pending.pts_secs.max(0.0);
        let before = player.position();
        let before_serial = player.current_seek_serial();
        let state = player.engine_state_name();
        let duration = player.duration();
        crate::logger::log(format!(
            "[bookmark-open] seek media path={} target={target:.3} before={before:.3} duration={duration:.3} state={state} serial_before={before_serial} presentation={:?}",
            player.path().display(),
            self.viewer_presentation
        ));
        player.seek(target);
        crate::logger::log(format!(
            "[bookmark-open] seek issued path={} after={:.3} serial_after={}",
            player.path().display(),
            player.position(),
            player.current_seek_serial()
        ));
        if self
            .bookmark_open_pending
            .as_ref()
            .is_some_and(|current| current.request_id() == pending.request_id)
        {
            self.bookmark_open_pending = None;
        }
    }

    fn poll_bookmark_book_open(&mut self, ctx: &egui::Context) {
        let Some(mut pending) = self
            .bookmark_open_pending
            .as_ref()
            .and_then(crate::bookmark_browser::PendingBookmarkOpen::book)
            .cloned()
        else {
            return;
        };
        let (started_at, mut entered_archive_prefix) = match &pending.stage {
            crate::bookmark_browser::PendingBookOpenStage::AwaitingPage {
                started_at,
                entered_archive_prefix,
            } => (*started_at, *entered_archive_prefix),
            crate::bookmark_browser::PendingBookOpenStage::Resolving => {
                // ArchiveConvertState is the active owner while a RAR/7z/LZH is being probed,
                // confirmed, unlocked, or converted. User interaction and real conversions can
                // legitimately exceed the path-resolver timeout; activation/navigation cancel
                // the shared request (and worker) through its ID instead.
                if self.archive_convert_owns_bookmark_request(pending.request_id) {
                    return;
                }
                if pending.started_at.elapsed() > std::time::Duration::from_secs(45) {
                    self.cancel_bookmark_open_request(pending.request_id, "book_resolve_timeout");
                    self.show_feedback_toast("ブックマーク先の本を開けませんでした".to_string());
                }
                return;
            }
        };
        if started_at.elapsed() > std::time::Duration::from_secs(45) {
            self.cancel_bookmark_open_request(pending.request_id, "book_page_timeout");
            self.show_feedback_toast("ブックマーク先の本を開けませんでした".to_string());
            return;
        }
        let same_container = self.effective_folder().is_some_and(|path| {
            crate::folder_tree::path_eq(&path, &pending.bookmark.container_path)
        });
        if !same_container {
            return;
        }
        if let Some(idx) = self.book_bookmark_item_idx(&pending.bookmark) {
            if self
                .bookmark_open_pending
                .as_ref()
                .is_some_and(|current| current.request_id() == pending.request_id)
            {
                self.bookmark_open_pending = None;
            }
            let provenance = pending.relative_page_provenance.clone().or_else(|| {
                let crate::book_bookmarks::PageIdentity::RelativePath(relative) =
                    &pending.bookmark.page_identity
                else {
                    return None;
                };
                crate::book_bookmarks::RelativePageProvenance::unresolved(
                    &pending.bookmark.container_path,
                    relative,
                )
            });
            self.open_bookmark_item_with_provenance(ctx, idx, provenance);
            return;
        }

        if !entered_archive_prefix && self.enter_book_bookmark_archive_prefix(&pending.bookmark) {
            entered_archive_prefix = true;
            pending.stage = crate::bookmark_browser::PendingBookOpenStage::AwaitingPage {
                started_at,
                entered_archive_prefix,
            };
            self.bookmark_open_pending =
                Some(crate::bookmark_browser::PendingBookmarkOpen::Book(pending));
            return;
        }

        let enumeration_pending = self.zip_enumerate_pending.is_some()
            || self.pdf_enumerate_pending.is_some()
            || self.folder_pane_open_pending.is_some()
            || self.pdf_password_request.is_some();
        if !enumeration_pending {
            self.cancel_bookmark_open_request(pending.request_id, "book_page_missing");
            self.show_feedback_toast(
                "ブックマーク先のページが見つかりません（記録は保持されます）".to_string(),
            );
        }
    }

    fn open_bookmark_item_with_provenance(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
        provenance: Option<crate::book_bookmarks::RelativePageProvenance>,
    ) {
        self.bookmark_relative_page_open_once = provenance.map(|value| (idx, value));
        self.open_fullscreen_from_fs_navigation(ctx, idx, crate::app::HistoryTrigger::UserChosen);
        self.bookmark_relative_page_open_once = None;
    }

    fn relative_page_provenance_for_idx(
        &self,
        idx: usize,
    ) -> Option<crate::book_bookmarks::RelativePageProvenance> {
        self.bookmark_relative_page_open_once
            .as_ref()
            .filter(|(candidate_idx, _)| *candidate_idx == idx)
            .map(|(_, provenance)| provenance.clone())
            .or_else(|| {
                self.bookmark_view_row(idx)
                    .and_then(|row| row.relative_page_provenance.clone())
            })
    }

    pub(crate) fn book_address_label_for_path(&self, path: &Path) -> Option<String> {
        let root = self.book_root_path();
        if crate::folder_tree::path_eq(path, &root) {
            return Some("本棚".to_string());
        }
        if !crate::books::is_direct_book_folder(&root, path) {
            return None;
        }
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or(crate::books::DEFAULT_BOOK_NAME);
        Some(format!("本棚 > {name}"))
    }

    pub(crate) fn book_sort_order_for_path(&self, path: &Path) -> crate::settings::SortOrder {
        if crate::books::is_direct_book_folder(&self.book_root_path(), path) {
            crate::settings::SortOrder::Numeric
        } else {
            self.settings.sort_order
        }
    }

    pub(crate) fn open_books_root(&mut self) {
        let root = self.book_root_path();
        if let Err(err) = std::fs::create_dir_all(&root) {
            self.show_feedback_toast(format!(
                "本棚フォルダを作成できません: {}: {err}",
                root.display()
            ));
            return;
        }
        self.load_folder(root);
    }

    pub(crate) fn request_book_list_refresh(&mut self) {
        if self.book_op_pending.is_some() {
            return;
        }
        let root = self.book_root_path();
        let (tx, rx) = std::sync::mpsc::channel();
        match std::thread::Builder::new()
            .name("book-list".into())
            .spawn(move || {
                let result = crate::books::list_books(&root).map(crate::books::BookOpResult::List);
                let _ = tx.send(result);
            }) {
            Ok(_) => {
                self.book_op_pending = Some(crate::books::BookOpPending { rx });
            }
            Err(err) => {
                self.show_feedback_toast(format!("本棚一覧 worker を開始できません: {err}"));
            }
        }
    }

    pub(crate) fn start_book_create(&mut self, ctx: &egui::Context, name: String) {
        let root = self.book_root_path();
        self.start_book_op(ctx, "book-create", move || {
            crate::books::create_book(&root, &name)
        });
    }

    pub(crate) fn start_book_rename(
        &mut self,
        ctx: &egui::Context,
        old_name: String,
        new_name: String,
    ) {
        let root = self.book_root_path();
        self.start_book_op(ctx, "book-rename", move || {
            crate::books::rename_book(&root, &old_name, &new_name)
        });
    }

    pub(crate) fn start_book_delete(&mut self, ctx: &egui::Context, name: String) {
        let root = self.book_root_path();
        self.start_book_op(ctx, "book-delete", move || {
            crate::books::delete_book(&root, &name)
        });
    }

    pub(crate) fn start_book_append(
        &mut self,
        ctx: &egui::Context,
        sources: Vec<crate::books::BookPageSource>,
    ) {
        let book_name = self.active_book_name();
        self.start_book_append_to_named(ctx, book_name, sources);
    }

    /// `start_book_append` の本名指定版 (ツールバーのピン留め本へ追加する用)。
    pub(crate) fn start_book_append_to_named(
        &mut self,
        ctx: &egui::Context,
        book_name: String,
        sources: Vec<crate::books::BookPageSource>,
    ) {
        if sources.is_empty() {
            self.show_feedback_toast("追加するページがありません".to_string());
            return;
        }
        let root = self.book_root_path();
        self.start_book_op(ctx, "book-append", move || {
            crate::books::append_pages(root, book_name, sources)
        });
    }

    pub(crate) fn start_book_reorder_flush(
        &mut self,
        ctx: &egui::Context,
        folder: PathBuf,
        ordered_paths: Vec<PathBuf>,
    ) -> Option<crate::books::BookOpPending> {
        let (tx, rx) = std::sync::mpsc::channel();
        match std::thread::Builder::new()
            .name("book-reorder".into())
            .spawn(move || {
                let result = crate::books::flush_reorder(folder, ordered_paths);
                let _ = tx.send(result);
            }) {
            Ok(_) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
                Some(crate::books::BookOpPending { rx })
            }
            Err(err) => {
                self.show_feedback_toast(format!("並べ替え worker を開始できません: {err}"));
                None
            }
        }
    }

    pub(crate) fn start_book_transfer(
        &mut self,
        ctx: &egui::Context,
        source_folder: PathBuf,
        current_order_paths: Vec<PathBuf>,
        selected_paths: Vec<PathBuf>,
        target_book_name: String,
        kind: crate::books::BookTransferKind,
    ) -> Option<crate::books::BookOpPending> {
        let root = self.book_root_path();
        let (tx, rx) = std::sync::mpsc::channel();
        match std::thread::Builder::new()
            .name("book-transfer".into())
            .spawn(move || {
                let result = crate::books::transfer_pages_between_books(
                    root,
                    source_folder,
                    current_order_paths,
                    selected_paths,
                    target_book_name,
                    kind,
                );
                let _ = tx.send(result);
            }) {
            Ok(_) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
                Some(crate::books::BookOpPending { rx })
            }
            Err(err) => {
                self.show_feedback_toast(format!("ページ転送 worker を開始できません: {err}"));
                None
            }
        }
    }

    pub(crate) fn apply_book_page_edit_copies(
        &mut self,
        mappings: &[crate::books::BookPathMapping],
    ) {
        let mappings = Self::normalized_book_page_edit_mappings(mappings);
        if mappings.is_empty() {
            return;
        }
        let mut errors = Vec::new();
        for (from, to) in mappings {
            self.copy_book_page_edit_key(&from, &to, &mut errors);
        }
        self.finish_book_page_edit_mapping("copy", errors);
    }

    pub(crate) fn apply_book_page_semantic_copies(
        &mut self,
        mappings: &[crate::books::BookPathMapping],
    ) {
        let mappings = Self::normalized_book_page_edit_mappings(mappings);
        if mappings.is_empty() {
            return;
        }
        let mut errors = Vec::new();
        for (from, to) in mappings {
            self.copy_book_page_semantic_key(&from, &to, &mut errors);
        }
        self.finish_book_page_semantic_mapping(errors);
    }

    pub(crate) fn apply_book_page_edit_moves_with_journal(
        &mut self,
        mappings: &[crate::books::BookPathMapping],
        bookmark_migration_journal_id: Option<&str>,
    ) {
        self.migrate_book_page_bookmarks(mappings, bookmark_migration_journal_id);
        let mappings = Self::normalized_book_page_edit_mappings(mappings);
        if mappings.is_empty() {
            return;
        }
        let stamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0);
        let pid = std::process::id();
        let temp_mappings = mappings
            .iter()
            .enumerate()
            .map(|(i, (from, to))| {
                (
                    from.clone(),
                    format!("__miv_book_edit_tmp__/{pid}/{stamp}/{i}"),
                    to.clone(),
                )
            })
            .collect::<Vec<_>>();

        let mut errors = Vec::new();
        for (from, temp, _) in &temp_mappings {
            self.move_book_page_edit_key(from, temp, &mut errors);
        }
        for (_, temp, to) in &temp_mappings {
            self.move_book_page_edit_key(temp, to, &mut errors);
        }
        self.finish_book_page_edit_mapping("move", errors);
    }

    fn migrate_book_page_bookmarks(
        &mut self,
        mappings: &[crate::books::BookPathMapping],
        journal_id: Option<&str>,
    ) {
        let mappings: Vec<_> = mappings
            .iter()
            .filter(|mapping| !crate::folder_tree::path_eq(&mapping.from, &mapping.to))
            .map(|mapping| (mapping.from.clone(), mapping.to.clone()))
            .collect();
        if mappings.is_empty() && journal_id.is_none() {
            return;
        }
        let request_id = self.next_book_bookmark_request_id();
        let Some(service) = self.book_bookmark_service.as_ref() else {
            self.show_feedback_toast("ブックマークDBを利用できません".to_string());
            return;
        };
        service.migrate_paths_with_journal(request_id, mappings, journal_id.map(str::to_string));
        self.book_bookmark_pending_requests.insert(request_id);
    }

    fn normalized_book_page_edit_mappings(
        mappings: &[crate::books::BookPathMapping],
    ) -> Vec<(String, String)> {
        mappings
            .iter()
            .filter_map(|mapping| {
                let from = crate::adjustment_db::normalize_path(&mapping.from);
                let to = crate::adjustment_db::normalize_path(&mapping.to);
                (from != to).then_some((from, to))
            })
            .collect()
    }

    fn copy_book_page_edit_key(&mut self, from: &str, to: &str, errors: &mut Vec<String>) {
        if let Some(db) = &self.adjustment_db {
            match db.copy_page_params_key(from, to) {
                Ok(()) => Self::copy_page_key_presence(&mut self.adjusted_page_keys, from, to),
                Err(e) => errors.push(format!("adjustment: {e}")),
            }
        }
        if let Some(db) = &self.local_adjust_db {
            match db.copy_entry_key(from, to) {
                Ok(()) => Self::copy_page_key_presence(&mut self.local_adjust_page_keys, from, to),
                Err(e) => errors.push(format!("local_adjust: {e}")),
            }
        }
        if let Some(db) = &self.export_crop_db
            && let Err(e) = db.copy_entry_key(from, to)
        {
            errors.push(format!("crop: {e}"));
        }
        if let Some(db) = &self.mask_db {
            match db.copy_entry_key(from, to) {
                Ok(()) => Self::copy_page_key_presence(&mut self.mask_page_keys, from, to),
                Err(e) => errors.push(format!("erase: {e}")),
            }
        }
        if let Some(db) = &self.conceal_db {
            match db.copy_entry_key(from, to) {
                Ok(()) => Self::copy_page_key_presence(&mut self.conceal_page_keys, from, to),
                Err(e) => errors.push(format!("conceal: {e}")),
            }
        }
        if let Some(db) = &self.comic_db {
            match db.copy_entry_key(from, to) {
                Ok(()) => Self::copy_page_key_presence(&mut self.comic_page_keys, from, to),
                Err(e) => errors.push(format!("comic: {e}")),
            }
        }
        if let Some(db) = &self.rating_db
            && let Err(e) = db.copy_entry_key(from, to)
        {
            errors.push(format!("rating: {e}"));
        }
        if let Some(db) = self.tags_db.as_mut()
            && let Err(e) = db.copy_item_key(from, to)
        {
            errors.push(format!("tags: {e}"));
        }
    }

    fn copy_book_page_semantic_key(&mut self, from: &str, to: &str, errors: &mut Vec<String>) {
        if let Some(db) = &self.rating_db
            && let Err(e) = db.copy_entry_key(from, to)
        {
            errors.push(format!("rating: {e}"));
        }
        if let Some(db) = self.tags_db.as_mut()
            && let Err(e) = db.copy_item_key(from, to)
        {
            errors.push(format!("tags: {e}"));
        }
    }

    fn move_book_page_edit_key(&mut self, from: &str, to: &str, errors: &mut Vec<String>) {
        if let Some(db) = &self.adjustment_db {
            match db.move_page_params_key(from, to) {
                Ok(()) => Self::move_page_key_presence(&mut self.adjusted_page_keys, from, to),
                Err(e) => errors.push(format!("adjustment: {e}")),
            }
        }
        if let Some(db) = &self.local_adjust_db {
            match db.move_entry_key(from, to) {
                Ok(()) => Self::move_page_key_presence(&mut self.local_adjust_page_keys, from, to),
                Err(e) => errors.push(format!("local_adjust: {e}")),
            }
        }
        if let Some(db) = &self.export_crop_db
            && let Err(e) = db.move_entry_key(from, to)
        {
            errors.push(format!("crop: {e}"));
        }
        if let Some(db) = &self.mask_db {
            match db.move_entry_key(from, to) {
                Ok(()) => Self::move_page_key_presence(&mut self.mask_page_keys, from, to),
                Err(e) => errors.push(format!("erase: {e}")),
            }
        }
        if let Some(db) = &self.conceal_db {
            match db.move_entry_key(from, to) {
                Ok(()) => Self::move_page_key_presence(&mut self.conceal_page_keys, from, to),
                Err(e) => errors.push(format!("conceal: {e}")),
            }
        }
        if let Some(db) = &self.comic_db {
            match db.move_entry_key(from, to) {
                Ok(()) => Self::move_page_key_presence(&mut self.comic_page_keys, from, to),
                Err(e) => errors.push(format!("comic: {e}")),
            }
        }
        if let Some(db) = &self.rating_db
            && let Err(e) = db.move_entry_key(from, to)
        {
            errors.push(format!("rating: {e}"));
        }
        if let Some(db) = self.tags_db.as_mut()
            && let Err(e) = db.move_item_key(from, to)
        {
            errors.push(format!("tags: {e}"));
        }
    }

    fn finish_book_page_semantic_mapping(&mut self, errors: Vec<String>) {
        self.rating_cache.clear();
        self.invalidate_rating_counts_cache();
        self.clear_tags_cache();
        if errors.is_empty() {
            return;
        }
        let preview = errors
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join(" / ");
        crate::logger::log(format!(
            "book page semantic metadata copy partially failed ({}): {preview}",
            errors.len()
        ));
        self.show_feedback_toast(format!(
            "本ページの評価・タグの引き継ぎに一部失敗しました ({} 件)",
            errors.len()
        ));
    }

    fn finish_book_page_edit_mapping(&mut self, op: &str, errors: Vec<String>) {
        self.clear_page_edit_state();
        self.rating_cache.clear();
        self.invalidate_rating_counts_cache();
        self.clear_tags_cache();
        if errors.is_empty() {
            return;
        }
        let preview = errors
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join(" / ");
        crate::logger::log(format!(
            "book page edit metadata {op} partially failed ({}): {preview}",
            errors.len()
        ));
        self.show_feedback_toast(format!(
            "本ページの編集情報の引き継ぎに一部失敗しました ({} 件)",
            errors.len()
        ));
    }

    fn start_book_op<F>(&mut self, ctx: &egui::Context, thread_name: &'static str, f: F) -> bool
    where
        F: FnOnce() -> Result<crate::books::BookOpResult, String> + Send + 'static,
    {
        if self.book_op_pending.is_some() {
            self.show_feedback_toast("製本処理中です".to_string());
            return false;
        }
        let (tx, rx) = std::sync::mpsc::channel();
        match std::thread::Builder::new()
            .name(thread_name.into())
            .spawn(move || {
                let _ = tx.send(f());
            }) {
            Ok(_) => {
                self.book_op_pending = Some(crate::books::BookOpPending { rx });
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
                true
            }
            Err(err) => {
                self.show_feedback_toast(format!("製本 worker を開始できません: {err}"));
                false
            }
        }
    }

    pub(crate) fn poll_book_op_pending(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.book_op_pending.as_ref() else {
            return;
        };
        let result = match pending.rx.try_recv() {
            Ok(result) => result,
            Err(std::sync::mpsc::TryRecvError::Empty) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(100));
                return;
            }
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                Err("製本処理が中断されました".to_string())
            }
        };
        self.book_op_pending = None;
        match result {
            Ok(crate::books::BookOpResult::Append(summary)) => {
                self.apply_book_page_edit_copies(&summary.edit_copies);
                self.apply_book_page_semantic_copies(&summary.semantic_copies);
                if let Some(rows) = self.book_list_cache.as_mut() {
                    crate::books::apply_append_to_cached_list(
                        rows,
                        &summary.book_name,
                        &summary.folder,
                        summary.added,
                    );
                }
                if self
                    .current_folder
                    .as_ref()
                    .is_some_and(|folder| crate::folder_tree::path_eq(folder, &summary.folder))
                {
                    self.pending_reload = true;
                }
                crate::logger::log(format!(
                    "book append: {} added={} folder={}",
                    summary.book_name,
                    summary.added,
                    summary.folder.display()
                ));
                if summary.erase_fallback_pages > 0 {
                    self.show_feedback_toast_with_duration(
                        format!(
                            "「{}」に {} ページ追加しました\n{} ページの消しゴム補完は簡易処理で再作成しました",
                            summary.book_name,
                            summary.added,
                            summary.erase_fallback_pages,
                        ),
                        4.5,
                    );
                } else {
                    self.show_feedback_toast(format!(
                        "「{}」に {} ページ追加しました",
                        summary.book_name, summary.added
                    ));
                }
                if let Some(path) = summary.first_path {
                    crate::logger::log(format!("book append first page: {}", path.display()));
                }
            }
            Ok(crate::books::BookOpResult::Transfer(summary)) => {
                self.apply_book_page_edit_moves_with_journal(
                    &summary.edit_moves,
                    summary.bookmark_migration_journal_id.as_deref(),
                );
                self.apply_book_page_edit_copies(&summary.edit_copies);
                self.book_list_cache = None;
                if self.current_folder.as_ref().is_some_and(|current| {
                    crate::folder_tree::path_eq(current, &summary.source_folder)
                        || crate::folder_tree::path_eq(current, &summary.target_folder)
                }) {
                    self.pending_reload = true;
                }
                let verb = match summary.kind {
                    crate::books::BookTransferKind::Copy => "コピー",
                    crate::books::BookTransferKind::Move => "移動",
                };
                self.show_feedback_toast(format!(
                    "「{}」へ {} ページ{}しました",
                    summary.target_book_name, summary.pages, verb
                ));
            }
            Ok(crate::books::BookOpResult::List(rows)) => {
                self.book_manager_rename_inputs.clear();
                for row in &rows {
                    self.book_manager_rename_inputs
                        .insert(row.name.clone(), row.name.clone());
                }
                self.book_list_cache = Some(rows);
            }
            Ok(crate::books::BookOpResult::Created { name, path }) => {
                self.settings.active_book_name = name.clone();
                self.settings.save();
                self.book_manager_new_name.clear();
                self.book_manager_rename_name = name.clone();
                self.book_manager_rename_inputs
                    .insert(name.clone(), name.clone());
                self.book_list_cache = None;
                self.show_feedback_toast(format!("本を作成しました: {name}"));
                crate::logger::log(format!("book created: {}", path.display()));
            }
            Ok(crate::books::BookOpResult::Renamed {
                old_name,
                new_name,
                edit_moves,
                bookmark_migration_journal_id,
            }) => {
                self.apply_book_page_edit_moves_with_journal(
                    &edit_moves,
                    bookmark_migration_journal_id.as_deref(),
                );
                if self.settings.active_book_name == old_name {
                    self.settings.active_book_name = new_name.clone();
                    self.settings.save();
                }
                // ツールバーのピン留めも旧名→新名へ追従 (Codex P2: 放置すると exists
                // フィルタでピンが消えたように見える)。
                if let Some(pos) = self
                    .settings
                    .pinned_books
                    .iter()
                    .position(|b| b == &old_name)
                {
                    self.settings.pinned_books[pos] = new_name.clone();
                    self.settings.save();
                }
                self.book_manager_rename_name = new_name.clone();
                self.book_manager_rename_inputs.remove(&old_name);
                self.book_manager_rename_inputs
                    .insert(new_name.clone(), new_name.clone());
                self.book_list_cache = None;
                self.pending_reload = true;
                self.show_feedback_toast(format!("本名を変更しました: {old_name} → {new_name}"));
            }
            Ok(crate::books::BookOpResult::Deleted { name }) => {
                if self.settings.active_book_name == name {
                    self.settings.active_book_name = crate::books::DEFAULT_BOOK_NAME.to_string();
                    self.settings.save();
                    self.book_manager_rename_name = self.settings.active_book_name.clone();
                }
                // 削除された本のピン留めも除去 (Codex P2: 残すと同名再作成でピンが復活する)。
                if let Some(pos) = self.settings.pinned_books.iter().position(|b| b == &name) {
                    self.settings.pinned_books.remove(pos);
                    self.settings.save();
                }
                self.book_manager_delete_confirm = None;
                self.book_manager_rename_inputs.remove(&name);
                self.book_list_cache = None;
                self.pending_reload = true;
                self.show_feedback_toast(format!("本を削除しました: {name}"));
            }
            Ok(crate::books::BookOpResult::Reordered {
                folder,
                count,
                edit_moves,
                bookmark_migration_journal_id,
            }) => {
                self.apply_book_page_edit_moves_with_journal(
                    &edit_moves,
                    bookmark_migration_journal_id.as_deref(),
                );
                self.book_list_cache = None;
                if self
                    .current_folder
                    .as_ref()
                    .is_some_and(|current| crate::folder_tree::path_eq(current, &folder))
                {
                    self.pending_reload = true;
                }
                self.show_feedback_toast(format!("ページ順を保存しました: {count} ページ"));
            }
            Err(err) => {
                crate::logger::log(format!("book op failed: {err}"));
                self.show_feedback_toast(format!("製本処理に失敗しました: {err}"));
            }
        }
        ctx.request_repaint();
    }

    /// 変換済みアーカイブキャッシュ管理ダイアログのワーカー完了を拾う。
    /// Rows 結果はダイアログ表示用、Deleted* 結果はメッセージ反映 + 再ロード spawn。
    pub(crate) fn poll_archive_cache_maint_pending(&mut self) {
        let Some(pending) = self.archive_cache_maint_pending.as_ref() else {
            return;
        };
        let msg = match pending.rx.try_recv() {
            Ok(m) => m,
            Err(std::sync::mpsc::TryRecvError::Empty) => return,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                self.archive_cache_maint_pending = None;
                return;
            }
        };
        self.archive_cache_maint_pending = None;
        match msg {
            crate::cache_maintenance::ArchiveMaintResult::Rows {
                entries,
                total_bytes,
            } => {
                self.archive_cache_rows = Some(entries);
                self.archive_cache_total_bytes = total_bytes;
                self.archive_cache_selection.clear();
            }
            crate::cache_maintenance::ArchiveMaintResult::DeletedSelected { removed } => {
                if removed > 0 {
                    self.archive_cache_manager_result =
                        Some(format!("{} 件のキャッシュを削除しました。", removed));
                }
                self.reload_archive_cache_rows();
            }
            crate::cache_maintenance::ArchiveMaintResult::DeletedMissing { removed } => {
                self.archive_cache_manager_result = Some(format!(
                    "{} 件のキャッシュ (元ファイル消失) を削除しました。",
                    removed
                ));
                self.reload_archive_cache_rows();
            }
            crate::cache_maintenance::ArchiveMaintResult::DeletedAll { removed } => {
                self.archive_cache_manager_result =
                    Some(format!("{} 件のキャッシュを削除しました。", removed));
                self.reload_archive_cache_rows();
            }
            crate::cache_maintenance::ArchiveMaintResult::Error(e) => {
                self.archive_cache_manager_result = Some(format!("操作に失敗しました: {e}"));
            }
        }
    }

    /// archive_cache_rows を再ロードするワーカーを spawn する (既存ハンドルがあれば上書き)。
    pub(crate) fn reload_archive_cache_rows(&mut self) {
        let Some(db) = self.archive_cache_db.clone() else {
            return;
        };
        self.archive_cache_rows = None;
        self.archive_cache_selection.clear();
        self.archive_cache_maint_pending = Some(crate::cache_maintenance::spawn_archive(
            crate::cache_maintenance::ArchiveMaintTask::LoadRows,
            db,
        ));
    }

    /// サムネイルキャッシュ管理ダイアログの集計 / 削除ワーカーの完了を拾う。
    /// 受信したら stats / result を反映してハンドルを drop。
    pub(crate) fn poll_cache_maint_pending(&mut self) {
        let Some(pending) = self.cache_maint_pending.as_ref() else {
            return;
        };
        let msg = match pending.rx.try_recv() {
            Ok(m) => m,
            Err(std::sync::mpsc::TryRecvError::Empty) => return,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                self.cache_maint_pending = None;
                return;
            }
        };
        match msg {
            crate::cache_maintenance::CacheMaintResult::Error(e) => {
                self.cache_manager_result = Some(format!("操作に失敗しました: {e}"));
            }
            crate::cache_maintenance::CacheMaintResult::Stats {
                folders,
                bytes,
                tile_thumb_bytes,
                auto_aspect_entries,
            } => {
                self.cache_manager_stats = Some((folders, bytes));
                self.cache_manager_tile_bytes = Some(tile_thumb_bytes);
                self.cache_manager_auto_aspect_entries = Some(auto_aspect_entries);
            }
            crate::cache_maintenance::CacheMaintResult::DeleteOldDone {
                deleted,
                new_stats,
                auto_aspect_deleted,
                auto_aspect_entries,
            } => {
                self.cache_manager_stats = Some(new_stats);
                // tile cache は対象外なのでサイズを再取得 (= 削除しても変化なしのはず
                // だが、別経路で書き込みが入っている可能性に備えて refresh)。
                self.cache_manager_tile_bytes =
                    Some(crate::video::tile_thumb_cache::TileThumbCache::db_size_bytes());
                self.cache_manager_auto_aspect_entries = Some(auto_aspect_entries);
                let mut msg = format!("{} 件のキャッシュを削除しました。", deleted);
                if auto_aspect_deleted > 0 {
                    msg.push_str(&format!(
                        " (比率自動判定キャッシュも {auto_aspect_deleted} 件削除)"
                    ));
                }
                self.cache_manager_result = Some(msg);
            }
            crate::cache_maintenance::CacheMaintResult::DeleteAllDone {
                tile_thumb,
                auto_aspect_deleted,
                auto_aspect_entries,
            } => {
                self.cache_manager_stats = Some((0, 0));
                self.cache_manager_tile_bytes =
                    Some(crate::video::tile_thumb_cache::TileThumbCache::db_size_bytes());
                self.cache_manager_auto_aspect_entries = Some(auto_aspect_entries);
                let mut msg = String::from("すべてのキャッシュを削除しました。");
                match tile_thumb {
                    crate::cache_maintenance::TileThumbOutcome::Cleared { rows } if rows > 0 => {
                        msg.push_str(&format!(" (動画タイル サムネも {rows} 件削除)"));
                    }
                    crate::cache_maintenance::TileThumbOutcome::FilesErased { files_removed }
                        if files_removed > 0 =>
                    {
                        msg.push_str(" (動画タイル DB を初期化)");
                    }
                    _ => {}
                }
                if auto_aspect_deleted > 0 {
                    msg.push_str(&format!(
                        " (比率自動判定キャッシュも {auto_aspect_deleted} 件削除)"
                    ));
                }
                self.cache_manager_result = Some(msg);
            }
            crate::cache_maintenance::CacheMaintResult::DeleteFolderDone {
                existed,
                folder_name,
                new_stats,
                tile_thumb,
                auto_aspect_deleted,
                auto_aspect_entries,
            } => {
                self.cache_manager_stats = Some(new_stats);
                self.cache_manager_tile_bytes =
                    Some(crate::video::tile_thumb_cache::TileThumbCache::db_size_bytes());
                self.cache_manager_auto_aspect_entries = Some(auto_aspect_entries);
                let tile_rows = match tile_thumb {
                    crate::cache_maintenance::TileThumbOutcome::Cleared { rows } => rows,
                    _ => 0,
                };
                let mut msg = match (existed, tile_rows) {
                    (true, 0) => format!("「{folder_name}」のキャッシュを削除しました。"),
                    (true, n) => format!(
                        "「{folder_name}」のキャッシュを削除しました。(動画タイル サムネも {n} 件削除)"
                    ),
                    (false, 0) => "現在のフォルダにはキャッシュがありません。".to_string(),
                    (false, n) => format!(
                        "現在のフォルダの静止画キャッシュはありませんでした。(動画タイル サムネを {n} 件削除)"
                    ),
                };
                if auto_aspect_deleted > 0 {
                    msg.push_str(&format!(
                        " (比率自動判定キャッシュも {auto_aspect_deleted} 件削除)"
                    ));
                }
                self.cache_manager_result = Some(msg);
            }
        }
        self.cache_maint_pending = None;
    }

    /// `start_loading_items` 用: フル context bump。
    /// cancel_token を flip → 既存 worker 起こす → 新 token に置き換え → catchup epoch +
    /// PDF render context epoch を bump する。後段で worker は再 spawn されるので
    /// cancel_token を flip しても問題ない。
    ///
    /// items 差し替え経路の共通 (docs/pdf-pool-context-epoch-plan.md Phase 4)。
    fn bump_full_context_for_load(&mut self) {
        // cancel_token は per-context (bundle 化済み、review-v2.3.0 P2-9)。detached context の
        // ロードでは detached 自身の旧ロードだけが止まり、main のワーカー / 動画サムネ抽出
        // スレッドには波及しない。
        self.cancel_token.store(true, Ordering::Relaxed);
        // Ctrl+G 結果ビュー専用の動画サムネ抽出スレッドは `cancel_token` ではなく
        // 専用 flag を見ているので、ここで明示的に止める。これをやらないと、Ctrl+G
        // 結果から PDF/ZIP/フォルダを Enter で開いて load_folder 経路に入った後も
        // 旧 Ctrl+G の動画スレッドが裏で Shell 抽出を続ける (Codex P2 #1 指摘)。
        // メッセージは items_gen 不一致で破棄されるが、Shell リトライ等が無駄に走る。
        // これは main 文脈専用の global state なので detached context のロードでは触らない。
        if !self.detached_viewer_context_is_mounted()
            && let Some(old) = self.search_video_thread_cancel.take()
        {
            old.store(true, Ordering::Relaxed);
        }
        self.wake_all_workers();
        self.cancel_token = Arc::new(AtomicBool::new(false));
        // catchup / PDF render epoch は crate-global。detached context のロードで bump すると
        // main 文脈の queue 済み PDF render が stale 扱いで prune され、requested が in-flight の
        // まま固着する (swap 時の requested clear を撤去した P2-8 以降は自己回復しない)。
        // detached 側は epoch prune の恩恵 (Ctrl+↑↓ 高速フォルダめくりの旧ジョブ破棄) を
        // 必要としないので main 文脈のロードに限定する (review-v2.3.0 P2-9)。
        if !self.detached_viewer_context_is_mounted() {
            crate::thumb_loader::bump_catchup_epoch();
            let _ = crate::pdf_loader::bump_render_context_epoch();
        }
    }

    /// 現在 detached viewer context (独立/ピン/Book) がマウント中 (= bundle swap で App が
    /// detached 側の状態を保持している) か。`with_active_detached_viewer_context` が mount 中
    /// だけ suppression depth を上げるので、それを流用する。
    fn detached_viewer_context_is_mounted(&self) -> bool {
        #[cfg(windows)]
        {
            self.detached_viewer_main_history_suppression_depth > 0
        }
        #[cfg(not(windows))]
        {
            false
        }
    }

    /// `replace_search_view_items` (Ctrl+G) 用: PDF render epoch のみ bump。
    /// **cancel_token は touch しない** (Ctrl+G は worker を再 spawn しないので、
    /// flip すると worker が exit して消費者不在になる)。catchup epoch も touch しない
    /// (Ctrl+G は PDF 階層を変えないので neighbor prefetch は引き続き有効)。
    ///
    /// items 差し替え経路の共通 (docs/pdf-pool-context-epoch-plan.md Phase 4)。
    pub(crate) fn bump_render_epoch_only(&mut self) {
        let _ = crate::pdf_loader::bump_render_context_epoch();
    }

    /// condvar.wait() 中の全ワーカーを起床させる。
    /// cancel_token を true にした直後に呼び、ワーカーが即座にキャンセルを検知できるようにする。
    pub(crate) fn wake_all_workers(&self) {
        if let Some(ref q) = self.reload_queue {
            let (_, ref cvar) = **q;
            cvar.notify_all();
        }
        if let Some(ref q) = self.heavy_io_queue {
            let (_, ref cvar) = **q;
            cvar.notify_all();
        }
    }

    /// 永続サムネイルワーカープールを `parallelism.thread_count()` 個 spawn する。
    /// 各ワーカーは `reload_queue` を `scroll_hint` 優先度で消費し続け、
    /// `cancel` が立つまで動作する。
    fn spawn_thumbnail_workers(
        &self,
        tx: &mpsc::Sender<ThumbMsg>,
        cancel: Arc<AtomicBool>,
        reload_queue: Arc<NotifyQueue>,
        heavy_io_queue: Arc<NotifyQueue>,
        cache_map: Arc<
            std::sync::RwLock<std::collections::HashMap<String, crate::catalog::CacheEntry>>,
        >,
        catalog_arc: Option<Arc<crate::catalog::CatalogDb>>,
        pin_db: Option<Arc<crate::folder_thumb_pins::FolderThumbPinDb>>,
    ) {
        let total_threads = self.settings.parallelism.thread_count();
        // I/O ワーカー数: 2 本 (HDD シーク競合と並列性のバランス)
        // ただし全体が 4 本以下なら 1 本に制限
        let io_threads = if total_threads <= 4 { 1 } else { 2 };
        let regular_threads = total_threads.saturating_sub(io_threads).max(1);
        let thumb_px = self.settings.thumb_px;
        let thumb_quality = self.settings.thumb_quality;
        let cache_decision = CacheDecision::from_settings(&self.settings);
        let scroll_hint = Arc::clone(&self.scroll_hint);
        let display_px_shared = Arc::clone(&self.display_px_shared);
        let stats = Arc::clone(&self.stats);
        let cache_gen_done = Arc::clone(&self.cache_gen_done);
        let keep_start_shared = Arc::clone(&self.keep_start_shared);
        let keep_end_shared = Arc::clone(&self.keep_end_shared);
        let visible_end_shared = Arc::clone(&self.visible_end_shared);
        let edit_preview_db = self.edit_preview_cache.as_ref().map(|service| service.db());

        crate::logger::log(format!(
            "  spawning {} regular + {} I/O workers",
            regular_threads, io_threads,
        ));

        // ── 共通のワーカーループ本体 ──
        // queue を受け取り、priority 順に取り出して process_load_request を呼ぶ。
        let spawn_worker = |worker_idx: usize, prefix: &str, queue: Arc<NotifyQueue>| {
            let tx_w = tx.clone();
            let cancel_w = Arc::clone(&cancel);
            let hint_w = Arc::clone(&scroll_hint);
            let cache_map_w = Arc::clone(&cache_map);
            let catalog_w = catalog_arc.clone();
            let done_w = Arc::clone(&cache_gen_done);
            let display_px_w = Arc::clone(&display_px_shared);
            let stats_w = Arc::clone(&stats);
            let ks_w = Arc::clone(&keep_start_shared);
            let ke_w = Arc::clone(&keep_end_shared);
            let ve_w = Arc::clone(&visible_end_shared);
            // pin-aware auto-pick 用に worker thread にも pin DB を共有する。
            // 内部 Mutex<Connection> で並列読みは serialize されるが、cascade lookup
            // 件数は典型的に数件程度なので contention は無視できる。
            let pin_db_w = pin_db.clone();
            let edit_preview_db_w = edit_preview_db.clone();
            let tag = format!("{prefix}{worker_idx}");

            std::thread::spawn(move || {
                let (ref mtx, ref cvar) = *queue;
                // 固定代表が指すページの個別色調補正は UI thread で同期 DB 参照せず、
                // worker ごとの接続から解決する。
                let adjustment_db_w = crate::adjustment_db::AdjustmentDb::open().ok();
                crate::logger::log(format!("  {tag} started"));
                loop {
                    // priority (可視範囲) を最優先、次に scroll_hint に近い順。
                    // キューが空なら condvar で待機し、push 側の notify で起床する。
                    let req = {
                        let mut q = mtx.lock().unwrap();
                        loop {
                            if cancel_w.load(Ordering::Relaxed) {
                                break None;
                            }
                            if !q.is_empty() {
                                let vis = hint_w.load(Ordering::Relaxed);
                                let vis_end = ve_w.load(Ordering::Relaxed);
                                let best = q
                                    .iter()
                                    .enumerate()
                                    .min_by_key(|(_, r)| {
                                        crate::thumb_loader::worker_priority_key(
                                            r.priority, r.idx, vis, vis_end,
                                        )
                                    })
                                    .map(|(pos, _)| pos)
                                    .unwrap();
                                break Some(q.swap_remove(best));
                            }
                            // キューが空 → condvar で待機（spurious wakeup は外側ループで再チェック）
                            q = cvar.wait(q).unwrap();
                        }
                    };

                    let Some(req) = req else {
                        break;
                    };

                    let ks = ks_w.load(Ordering::Relaxed);
                    let ke = ke_w.load(Ordering::Relaxed);
                    if req.idx < ks || req.idx >= ke {
                        crate::logger::log(format!(
                            "  {tag} SKIP idx={:>4} (out of keep [{ks}..{ke}))  {}",
                            req.idx,
                            req.path.file_name().and_then(|n| n.to_str()).unwrap_or("?"),
                        ));
                        if crate::perf::is_enabled() {
                            crate::perf::event(
                                "thumb",
                                "skip",
                                None,
                                req.input_seq,
                                &[
                                    ("idx", serde_json::Value::from(req.idx)),
                                    ("reason", serde_json::Value::from("out_of_keep")),
                                ],
                            );
                        }
                        // canceled=true を送信: UI 側の requested を cleanup し、
                        // Evicted (retriable) に戻す。これを送らないと keep_range が
                        // 戻ったときに再エンキューされず idx がスタックする。
                        let _ = tx_w.send(crate::thumb_loader::ThumbMsg {
                            idx: req.idx,
                            image: None,
                            origin: crate::thumb_loader::ThumbLoadOrigin::Source,
                            from_edit_preview: false,
                            edit_preview_adjustment: None,
                            source_dims: None,
                            canceled: true,
                            finalized: false,
                            input_seq: req.input_seq,
                            items_gen: req.items_gen,
                        });
                        continue;
                    }
                    let vis = hint_w.load(Ordering::Relaxed);
                    let dist = if req.idx < vis {
                        vis - req.idx
                    } else {
                        req.idx - vis
                    };
                    crate::logger::log(format!(
                        "  {tag} pick idx={:>4} pri={} dist={dist:>4}  {}",
                        req.idx,
                        if req.priority { "H" } else { "L" },
                        req.path.file_name().and_then(|n| n.to_str()).unwrap_or("?"),
                    ));
                    if crate::perf::is_enabled() {
                        crate::perf::event(
                            "thumb",
                            "pick",
                            None,
                            req.input_seq,
                            &[
                                ("idx", serde_json::Value::from(req.idx)),
                                ("priority", serde_json::Value::from(req.priority)),
                                ("dist", serde_json::Value::from(dist)),
                                ("worker", serde_json::Value::from(tag.clone())),
                            ],
                        );
                    }
                    let display_px = display_px_w.load(Ordering::Relaxed);
                    process_load_request(
                        &req,
                        &cache_map_w,
                        &tx_w,
                        catalog_w.as_ref(),
                        thumb_px,
                        thumb_quality,
                        display_px,
                        cache_decision,
                        &done_w,
                        &stats_w,
                        Some(&cancel_w),
                        &ks_w,
                        &ke_w,
                        pin_db_w.as_deref(),
                        edit_preview_db_w.as_ref(),
                        adjustment_db_w.as_ref(),
                    );
                }
                crate::logger::log(format!("  {tag} stopped"));
            });
        };

        // 通常ワーカー: reload_queue (Image, ZipImage, PdfPage, PdfFile)
        for i in 0..regular_threads {
            spawn_worker(i, "w", Arc::clone(&reload_queue));
        }
        // I/O ワーカー: heavy_io_queue (Folder, ZipFile, ConvertibleArchive, ZipDir)
        for i in 0..io_threads {
            spawn_worker(i, "io", Arc::clone(&heavy_io_queue));
        }
    }

    /// 動画サムネイル取得スレッドを起動する。
    /// 各動画について Windows Shell API でサムネを取り出し、tx 経由で UI に送信する。
    ///
    /// 取得順は固定ではなく、毎回 `scroll_hint` / `visible_end_shared` を見て
    /// 現在の可視範囲に最も近い動画を優先する。動画が多いフォルダで下にスクロール
    /// しても、表示中ページの動画が先に埋まるようにする。
    pub(crate) fn spawn_video_thread(
        &self,
        tx: mpsc::Sender<ThumbMsg>,
        cancel: Arc<AtomicBool>,
        video_items: Vec<(usize, PathBuf, u64)>,
        thumb_overrides: std::collections::HashMap<String, PathBuf>,
        // Phase 8.B': ユーザーピン留め フレームの WebP マップ (動画 path → WebP)。
        // priority chain の最上位で使う。空 BLOB のものは含まれない (= 抽出失敗で
        // ピンを保存したケース、fall-through する)。
        pin_blobs: std::collections::HashMap<PathBuf, Vec<u8>>,
    ) {
        let thumb_size = self.last_cell_size.max(256.0) as i32;
        let display_px = compute_display_px(
            self.last_cell_size,
            self.last_cell_h,
            self.last_pixels_per_point,
        );
        let stats = Arc::clone(&self.stats);
        let hint = Arc::clone(&self.scroll_hint);
        let vis_end = Arc::clone(&self.visible_end_shared);
        // 世代スナップショット: items が差し替わる前にフリーズ。以降 ThumbMsg に載せ、
        // UI 側は自 items_generation と一致しないものを破棄する (旧 items 混入防止)。
        let items_gen = self.items_generation;

        std::thread::spawn(move || {
            use std::time::{Duration, Instant};

            struct PendingVideo {
                idx: usize,
                path: PathBuf,
                file_size: u64,
                retries: u32,
                next_attempt: Instant,
            }

            // Shell がまだサムネ抽出中の動画に対して `SIIGBF_THUMBNAILONLY` は
            // エラーを返す (= ここで None)。バックオフしながらリトライすると、
            // Windows のバックグラウンド抽出完了後に本物のサムネが取れる。
            //
            // 動画本数が多いフォルダでは Shell の抽出キューが詰まり、特定の
            // ファイルに対して 30〜60 秒以上「未抽出」を返し続けるケースが実測で
            // 見つかった (バッチ内の他ファイルは成功するので Shell 自体は生きている)。
            // そこで以下の 2 段構えにする:
            //
            // 1. 連続失敗は 8 回 (最大 25.5 秒) までは指数バックオフで待つ。
            // 2. 他の動画が 1 件でも成功したら、同じフォルダ内の全残アイテムの
            //    retries を 0 にリセットし next_attempt を now に戻す。Shell が
            //    前進している限り何度でもリトライする (= 他動画が成功し続ける限り
            //    実質無制限)。
            // 3. スレッド全体で 1 件も成功していない場合は (1) の上限で打ち切る。
            const MAX_CONSEC_RETRIES: u32 = 8;

            let override_count = video_items
                .iter()
                .filter(|(_, p, _)| {
                    let full_key = crate::path_key::normalize_keep_drive(p);
                    thumb_overrides.contains_key(&full_key)
                        || thumb_overrides.contains_key(&stem_lower(p))
                })
                .count();
            crate::logger::log(format!(
                "[video thread] start: {} videos (override={}, shell={}), thumb_size={}, display_px={}",
                video_items.len(),
                override_count,
                video_items.len() - override_count,
                thumb_size,
                display_px,
            ));

            let now0 = Instant::now();
            let mut remaining: Vec<PendingVideo> = video_items
                .into_iter()
                .map(|(idx, path, file_size)| PendingVideo {
                    idx,
                    path,
                    file_size,
                    retries: 0,
                    next_attempt: now0,
                })
                .collect();
            let mut success_count = 0u32;
            let mut fail_count = 0u32;

            while !remaining.is_empty() {
                if cancel.load(Ordering::Relaxed) {
                    break;
                }

                // worker_priority_key と同じロジックで可視アイテムを tier 0、
                // その他を距離順に並べる。next_attempt が未来のアイテムは除外。
                let now = Instant::now();
                let vis = hint.load(Ordering::Relaxed);
                let ve = vis_end.load(Ordering::Relaxed);
                let best_pos = remaining
                    .iter()
                    .enumerate()
                    .filter(|(_, v)| v.next_attempt <= now)
                    .min_by_key(|(_, v)| {
                        let priority = v.idx >= vis && v.idx < ve;
                        crate::thumb_loader::worker_priority_key(priority, v.idx, vis, ve)
                    })
                    .map(|(i, _)| i);

                let Some(best_pos) = best_pos else {
                    // 全件リトライ待機中: 最も近い next_attempt まで寝る。
                    // キャンセル応答のため 200ms 刻みで区切る。
                    let earliest = remaining
                        .iter()
                        .map(|v| v.next_attempt)
                        .min()
                        .expect("remaining is non-empty");
                    let delay = earliest
                        .saturating_duration_since(Instant::now())
                        .min(Duration::from_millis(200));
                    std::thread::sleep(delay);
                    continue;
                };
                let PendingVideo {
                    idx,
                    path,
                    file_size,
                    retries,
                    ..
                } = remaining.swap_remove(best_pos);
                let fname = path
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("?")
                    .to_string();
                let call_t0 = Instant::now();

                let stem = stem_lower(&path);
                let full_video_key = crate::path_key::normalize_keep_drive(&path);
                // Phase 8.B': ピン留めフレームを最優先で適用 (priority chain の 1.)。
                // pin_blobs map は spawn 時に snapshot されているので thread 安全。
                // WebP デコード失敗時は fall-through。
                let pin_ci: Option<egui::ColorImage> = pin_blobs
                    .get(&path)
                    .and_then(|webp| crate::catalog::decode_thumb_to_color_image(webp));

                // 動画サムネイル優先順位:
                //   1. ピン留めフレーム (video_pins DB) — ★最優先 (Phase 8.B')
                //   2. 同名ファイル名画像 (sidecar、Settings.video_thumb_use_sidecar_image)
                //   3. Windows Shell の動画自身のデフォルトサムネ
                let (ci, source_tag) = if let Some(ci) = pin_ci {
                    if retries == 0 {
                        crate::logger::log(format!(
                            "  video thumb pin: idx={idx} {}",
                            path.file_name().and_then(|n| n.to_str()).unwrap_or("?")
                        ));
                    }
                    (Some(ci), "pin")
                } else if let Some(img_path) = thumb_overrides
                    .get(&full_video_key)
                    .or_else(|| thumb_overrides.get(&stem))
                {
                    if retries == 0 {
                        crate::logger::log(format!(
                            "  video thumb override: idx={idx} stem={stem} img={}",
                            img_path.display()
                        ));
                    }
                    (
                        crate::thumb_loader::decode_image_for_thumb(img_path, display_px),
                        "override",
                    )
                } else {
                    let (img, diag) = crate::video_thumb::get_video_thumbnail(&path, thumb_size);
                    // 失敗ケースだけ Shell の生データをログする (毎回出すと動画多数の
                    // フォルダで mimageviewer.log が肥大するため)。成功時は下の
                    // 最終 OK 行に dims を載せる。
                    if img.is_none() {
                        crate::logger::log(format!(
                            "  video shell FAIL: idx={idx} retry={retries} req_sz={thumb_size} \
                             stage={} hr={} get_ms={}  {fname}",
                            diag.stage_label(),
                            diag.hresult_hex(),
                            diag.get_image_ms,
                        ));
                    } else if let (Some((w, h)), Some(avg), Some(span)) =
                        (diag.dims, diag.avg_rgb, diag.span_rgb)
                    {
                        // 成功時は avg/span が極端 (真っ黒疑い) のときだけ注記する。
                        let avg_max = avg.0.max(avg.1).max(avg.2);
                        let span_max = span.0.max(span.1).max(span.2);
                        if avg_max < 16 || span_max < 10 {
                            crate::logger::log(format!(
                                "  video shell suspicious: idx={idx} dims={w}x{h} \
                                 avg_rgb=[{},{},{}] span_rgb=[{},{},{}]  {fname}",
                                avg.0, avg.1, avg.2, span.0, span.1, span.2,
                            ));
                        }
                    }
                    (img, "shell")
                };
                let call_ms = call_t0.elapsed().as_millis();

                if ci.is_none() && retries < MAX_CONSEC_RETRIES {
                    // Shell がサムネ抽出中。バックオフして末尾にリトライ予約。
                    // 200ms → 400ms → 800ms → 1.6s → 3.2s → 6.4s → 6.4s (頭打ち)
                    let backoff = Duration::from_millis(200u64 << retries.min(5));
                    let next = Instant::now() + backoff;
                    crate::logger::log(format!(
                        "  video thumb retry: idx={idx} src={source_tag} \
                         retries={}/{} backoff={}ms call_ms={call_ms} remaining={}  {fname}",
                        retries + 1,
                        MAX_CONSEC_RETRIES,
                        backoff.as_millis(),
                        remaining.len(),
                    ));
                    remaining.push(PendingVideo {
                        idx,
                        path,
                        file_size,
                        retries: retries + 1,
                        next_attempt: next,
                    });
                    continue;
                }

                if ci.is_some() {
                    // 成功: 残アイテムの retries をリセットし即時再試行を許可する。
                    // Shell が反応している証拠 = 他のアイテムも抽出が進んでいる可能性が高い。
                    let reset_count = remaining.iter().filter(|v| v.retries > 0).count();
                    if reset_count > 0 {
                        crate::logger::log(format!(
                            "  video thumb progress: reset {reset_count} retry counters  (trigger idx={idx})"
                        ));
                        for v in remaining.iter_mut() {
                            v.retries = 0;
                            v.next_attempt = now;
                        }
                    }
                }

                crate::logger::log(format!(
                    "  video thumb {}: idx={idx} src={source_tag} vis={vis} ve={ve} \
                     retries={retries} call_ms={call_ms} remaining={}  {fname}",
                    if ci.is_some() { "OK" } else { "FAIL-final" },
                    remaining.len(),
                ));
                if ci.is_some() {
                    success_count += 1;
                    if let Ok(mut s) = stats.lock() {
                        s.record_video(file_size);
                    }
                } else {
                    fail_count += 1;
                    if let Ok(mut s) = stats.lock() {
                        s.record_failed();
                    }
                }
                // 動画 Shell API はアップグレード経路を持たないので Source origin。
                // ピクセル寸法は取得できない。動画ロードは LoadRequest を経由しないため
                // input_seq は動画スレッドでは未使用 (計装経路でエンキューされない)。
                let _ = tx.send(crate::thumb_loader::ThumbMsg {
                    idx,
                    image: ci,
                    origin: crate::thumb_loader::ThumbLoadOrigin::Source,
                    from_edit_preview: false,
                    edit_preview_adjustment: None,
                    source_dims: None,
                    canceled: false,
                    finalized: false,
                    input_seq: 0,
                    items_gen,
                });
            }
            crate::logger::log(format!(
                "[video thread] end: success={success_count} fail={fail_count} canceled={}",
                cancel.load(Ordering::Relaxed),
            ));
        });
    }

    fn poll_thumbnails(&mut self, ctx: &egui::Context) {
        // 1 フレームあたりのテクスチャ生成数を制限する。
        // load_texture は GPU テクスチャアップロードを伴い、1 枚 0.5-2 ms かかる。
        // キャッシュヒット時にワーカー全員が一気に結果を返すと 1 フレームで
        // 数十枚の upload が走りフレーム落ちするため、上限を設ける。
        // 上限超過分は texture_backlog に ColorImage のまま保持し次フレームで処理する。
        const MAX_TEXTURES_PER_FRAME: u32 = 8;
        let mut textures_created = 0u32;
        let mut received = 0u32;
        // **黒サムネ回帰修正 (2026-06-19, v1.8.0 regression)**: フルスクリーン close 直後は
        // メインウィンドウの wgpu surface が 1 フレーム消え、その frame に queue した
        // テクスチャ upload (delta) が `paint_and_update_textures` の no-surface early return で
        // 捨てられる。font atlas は `main_font_atlas_resync` が数フレーム再 upload して救済するが、
        // **この窓で `load_texture` した grid サムネは upload だけ捨てられて handle は Loaded** の
        // ため、GPU データ空 = 真っ黒の backdrop だけが描かれる (idle 高画質化が再レンダする
        // ~500ms 後まで固着)。対策: resync 窓の間はサムネのテクスチャ化を `texture_backlog` へ
        // 先送りし、surface が戻ってから upload する。ColorImage は破棄せず保持されるので
        // 数フレーム遅れて正しく表示される。
        let defer_texture_uploads = {
            #[cfg(windows)]
            {
                self.main_font_atlas_resync_defers_texture_uploads()
            }
            #[cfg(not(windows))]
            {
                false
            }
        };
        let mut deferred_for_resync = 0u32;
        let (keep_start, keep_end) = self.keep_range;

        // バックログ + チャネルから受信した結果を統合して処理する。
        // バックログを先に処理（既にデコード済みなので優先）。
        // ループ内で `self` を mutably 借りる経路 (writeback 等) があるため、
        // ここで Vec に collect してから iterate する (借用衝突回避)。
        let backlog = std::mem::take(&mut self.texture_backlog);
        let drain: Vec<_> = backlog
            .into_iter()
            .chain(std::iter::from_fn(|| self.rx.try_recv().ok()))
            .collect();

        for msg in drain {
            let crate::thumb_loader::ThumbMsg {
                idx: i,
                image: color_image_opt,
                origin,
                from_edit_preview,
                edit_preview_adjustment,
                source_dims,
                canceled,
                finalized,
                input_seq: req_input_seq,
                items_gen: msg_items_gen,
            } = msg;
            let from_cache = origin.from_cache();
            let blocks_idle_upgrade = origin.blocks_idle_upgrade();
            // 世代不一致 (旧 items 由来) のメッセージは破棄する。items 差し替え後に
            // 旧ワーカー結果が同じ idx の新 items に適用されるとサムネが化けるため。
            // 全エンキュー経路 (通常 / idle upgrade / 動画スレッド) で現世代をスナップ
            // ショットして載せるので、不一致 = 旧経路と判定してよい。
            if msg_items_gen != self.items_generation {
                continue;
            }
            if i >= self.thumbnails.len() {
                self.requested.remove(&i);
                continue;
            }

            let in_keep_range = self.keep_set.contains(&i);

            // finalized = true: 第 2 シグナル (decode 成功 + cache save 完了)。
            // **`thumbnails[i]` の状態は変更しない**。
            //
            // 状態別の処理:
            //   - Loaded: 正常完了 → requested.remove。
            //   - Pending: 第1シグナルが texture_backlog でアップロード待ち中。
            //     requested をここで抜くと次フレームに Pending && !requested.contains
            //     で再エンキュー → 同じ画像を何度も decode する無限ループになる。
            //     `pending_finalize` に idx を積み、アップロード完了時 (Loaded 遷移時)
            //     にまとめて requested を抜く。
            //   - Evicted / Failed: 第1シグナルは既に処理されており (Loaded 経由で
            //     Evicted になった or ワーカーが失敗を返した)、ワーカーもこのシグナルで
            //     終了。ここで requested を抜いておかないと、再スクロールで戻った時に
            //     `update_keep_range_and_requests` の `requested.contains_key` ガードで
            //     再エンキューが無限にブロックされ、サムネが Evicted のまま固着する。
            //
            // `requested` に無い idx への finalized は、第1シグナルが keep 範囲外で
            // drop された後の幽霊シグナル。pending_finalize に挿入すると stale 状態が
            // 残り続けるので無視する。
            if finalized {
                // 仮想フォルダの先頭ページ完成を親 catalog にミラー (PDFium 再レンダ
                // 防止のための writeback)。requested の cleanup より前にやることで、
                // cache_map から WebP データが消える前に確実に読み出せる。
                self.fire_virtual_folder_writeback_if_ready(i);
                if !self.requested.contains_key(&i) {
                    received += 1;
                    continue;
                }
                match self.thumbnails[i] {
                    ThumbnailState::Loaded { .. } => {
                        self.requested.remove(&i);
                    }
                    ThumbnailState::Pending => {
                        self.pending_finalize.insert(i);
                    }
                    ThumbnailState::Evicted | ThumbnailState::Failed => {
                        // 固着防止: Evicted/Failed で finalize が来たら再エンキュー
                        // 可能な状態に戻す。
                        let state_name = match self.thumbnails[i] {
                            ThumbnailState::Evicted => "Evicted",
                            ThumbnailState::Failed => "Failed",
                            _ => unreachable!(),
                        };
                        self.requested.remove(&i);
                        self.pending_finalize.remove(&i);
                        crate::logger::log(format!(
                            "  [poll] finalize on {state_name} idx={i} → cleanup requested (was stuck candidate)"
                        ));
                    }
                }
                received += 1;
                continue;
            }

            // canceled = true: ワーカーが処理を中断 (STALE 等)。
            // Failed にはせず、Evicted に戻して再試行可能にする。
            // Loaded 状態は維持 (既にテクスチャがある場合は破棄しない)。
            if canceled {
                self.requested.remove(&i);
                self.pending_finalize.remove(&i);
                if !matches!(self.thumbnails[i], ThumbnailState::Loaded { .. }) {
                    self.thumbnails[i] = ThumbnailState::Evicted;
                }
                received += 1;
                continue;
            }

            // 動画は「最初に作った動画サムネは以後ずっと保持する」設計 —
            // update_keep_range_and_requests は Video を Evicted 化しないし
            // make_load_request も Video に None を返すため、一度 Evicted に
            // 落とすと再リクエストされず永遠に復帰しない。下の分岐で keep_range
            // 外でも常に in_range 扱いにすることで、out-of-range 受信でも
            // 必ずテクスチャ化する。
            let is_video = matches!(self.items.get(i), Some(GridItem::Video(_)));
            let treat_as_in_range = in_keep_range || is_video;

            match color_image_opt {
                Some(color_image) => {
                    if treat_as_in_range
                        && textures_created < MAX_TEXTURES_PER_FRAME
                        && !defer_texture_uploads
                    {
                        // cache origin: 1 ショット経路 (cache save なし) → 即 remove。
                        // source origin: from-source 経路。cache save 完了後の
                        //   第 2 シグナル (canceled=true) 到着まで `requested` を保持。
                        //   cache save 進行中の再エンキュー + 二重レンダを防ぐ。
                        if from_cache {
                            self.requested.remove(&i);
                        }
                        let [w, h] = color_image.size;
                        let rendered_at_px = w.max(h) as u32;
                        let prev_state_was_loaded =
                            matches!(self.thumbnails[i], ThumbnailState::Loaded { .. });
                        let upload_t0 = std::time::Instant::now();
                        // サムネ補正用に `color_image` を Arc で保持してからテクスチャ化する。
                        // テクスチャアップロードは ColorImage を消費するので、保持用に clone が必要。
                        // 補正対象は Image / ZipImage / PdfPage のみ
                        // (display-pipeline.md §1.5)。動画 / フォルダ / ZIP・PDF
                        // 代表サムネに global_preset が漏れないようゲートする。
                        let retain_pixels_for_adjust = is_thumb_adjust_target(self.items.get(i));
                        let (arc_pixels_opt, edit_layers_opt, image_to_upload) =
                            if retain_pixels_for_adjust {
                                let (base, layers) = match edit_preview_adjustment {
                                    Some(adjustment) => (
                                        adjustment.base,
                                        Some(std::sync::Arc::new(adjustment.annotation_layers)),
                                    ),
                                    None => (color_image.clone(), None),
                                };
                                (Some(std::sync::Arc::new(base)), layers, color_image)
                            } else {
                                (None, None, color_image)
                            };
                        if let Some(layers) = edit_layers_opt {
                            self.thumb_edit_preview_layers.insert(i, layers);
                        } else {
                            self.thumb_edit_preview_layers.remove(&i);
                        }
                        let handle = ctx.load_texture(
                            format!("thumb_{i}"),
                            image_to_upload,
                            egui::TextureOptions::LINEAR,
                        );
                        let upload_ms = upload_t0.elapsed().as_secs_f64() * 1000.0;
                        if let Some(arc) = arc_pixels_opt {
                            self.thumb_pixels.insert(i, arc);
                        }
                        // 新しいピクセルに差し替わったので、古い補正済みテクスチャは捨てる。
                        // 次フレームで `maybe_apply_thumb_adjustment` により再生成される。
                        self.thumb_adjust_tex.remove(&i);
                        // 完成済み派生 WebP は元 PDF/ZIP 等へ idle quality-upgrade
                        // しない。通常 cache / source へ差し替わった場合は解除する。
                        if blocks_idle_upgrade {
                            self.idle_upgrade_cache_bypass_ineligible.insert(i);
                        } else {
                            self.idle_upgrade_cache_bypass_ineligible.remove(&i);
                        }
                        self.thumbnails[i] = ThumbnailState::Loaded {
                            tex: handle,
                            from_cache,
                            from_edit_preview,
                            rendered_at_px,
                            source_dims,
                        };
                        textures_created += 1;
                        // 見開きの縦横判定はテクスチャ寿命に依存させない。元寸法が無い
                        // 旧 cache 等では、従来の判定と同じくロード済み画像寸法を使う。
                        if let Some(dims) = source_dims
                            .or_else(|| Some((u32::try_from(w).ok()?, u32::try_from(h).ok()?)))
                        {
                            self.page_dims_cache.record(self.items_generation, i, dims);
                        }
                        // auto_aspect: 新規 Loaded のタイミングで比率サンプルを記録。
                        // source_dims が None なら ColorImage の (w, h) を fallback として使う
                        // (動画 Shell サムネ / 旧 cache 由来などで source_dims が無いケース)。
                        if self.settings.thumb_aspect_auto {
                            let ratio = match source_dims {
                                Some((sw, sh)) if sw > 0 => sh as f32 / sw as f32,
                                _ if w > 0 => h as f32 / w as f32,
                                _ => -1.0,
                            };
                            if ratio > 0.0 && ratio.is_finite() {
                                self.auto_aspect.samples.insert(i, ratio);
                            }
                        }
                        // 第2シグナル先着の場合の遅延 requested.remove を実行。
                        if self.pending_finalize.remove(&i) {
                            self.requested.remove(&i);
                        }
                        // Pending/Evicted → Loaded の遷移時のみ ready を emit
                        // (アップグレードで Loaded→Loaded の遷移も起きるためフィルタ)。
                        // seq はエンキュー元のを透過し、decode 中のスクロールで
                        // ready が別操作に紐づくのを防ぐ。
                        if crate::perf::is_enabled() && !prev_state_was_loaded {
                            let perf_key = self.perf_item_key(i);
                            crate::perf::event(
                                "thumb",
                                "ready",
                                perf_key.as_deref(),
                                req_input_seq,
                                &[
                                    ("idx", serde_json::Value::from(i)),
                                    ("w", serde_json::Value::from(w)),
                                    ("h", serde_json::Value::from(h)),
                                    ("from_cache", serde_json::Value::from(from_cache)),
                                    ("upload_ms", serde_json::Value::from(upload_ms)),
                                ],
                            );
                        }
                        // ── スクロール体感: vis 内の Pending → Loaded 遷移を計測 ──
                        if !prev_state_was_loaded
                            && i >= self.last_vis_range.0
                            && i < self.last_vis_range.1
                            && let Some(settle_t) = self.vis_settle_at
                        {
                            let elapsed_ms = settle_t.elapsed().as_secs_f64() * 1000.0;
                            if !self.vis_first_logged {
                                crate::logger::log(format!(
                                    "[vis] first_visible idx={i} +{elapsed_ms:.1}ms after settle",
                                ));
                                self.vis_first_logged = true;
                            }
                            if !self.vis_all_logged {
                                let all_loaded = (self.last_vis_range.0..self.last_vis_range.1)
                                    .all(|j| {
                                        matches!(
                                            self.thumbnails.get(j),
                                            Some(ThumbnailState::Loaded { .. })
                                        )
                                    });
                                if all_loaded {
                                    crate::logger::log(format!(
                                        "[vis] all_loaded vis=[{}..{}) +{elapsed_ms:.1}ms after settle",
                                        self.last_vis_range.0, self.last_vis_range.1,
                                    ));
                                    self.vis_all_logged = true;
                                }
                            }
                        }
                    } else if treat_as_in_range {
                        // 上限到達 or font-atlas-resync 窓 (defer_texture_uploads) で keep_range 内
                        // (or 動画): 次フレームに持ち越す。requested は除去しない (重複リクエスト防止)。
                        if defer_texture_uploads {
                            deferred_for_resync += 1;
                        }
                        self.texture_backlog.push(crate::thumb_loader::ThumbMsg {
                            idx: i,
                            image: Some(color_image),
                            origin,
                            from_edit_preview,
                            edit_preview_adjustment,
                            source_dims,
                            canceled: false,
                            finalized: false,
                            input_seq: req_input_seq,
                            items_gen: msg_items_gen,
                        });
                    } else {
                        // 範囲外: ColorImage を drop し Evicted にしておく。
                        // from_cache / from_source に関わらず、UI 側の要求はここで完了扱い。
                        // from_source 用に requested を残すと、後から届く finalized=true と
                        // 合わせて `pending_finalize` が stale 化し、スクロールで戻っても
                        // `requested.contains_key(&i)` により再エンキューが阻まれる
                        // (= サムネイルが復帰しない) 状態に陥る。
                        // pending_finalize も念のため掃除する (第 2 シグナル先着の場合)。
                        crate::logger::log(format!(
                            "  [main] drop out-of-range thumb: idx={i} keep=[{keep_start}..{keep_end})"
                        ));
                        self.requested.remove(&i);
                        self.pending_finalize.remove(&i);
                        self.thumb_pixels.remove(&i);
                        self.thumb_edit_preview_layers.remove(&i);
                        self.thumb_adjust_tex.remove(&i);
                        self.thumbnails[i] = ThumbnailState::Evicted;
                    }
                }
                None => {
                    self.requested.remove(&i);
                    self.pending_finalize.remove(&i);
                    self.thumbnails[i] = ThumbnailState::Failed;
                }
            }
            received += 1;
        }
        if received > 0 || !self.texture_backlog.is_empty() {
            crate::logger::log(format!(
                "  [main] poll_thumbnails: received {received} ({textures_created} textures, {} backlog)",
                self.texture_backlog.len()
            ));
            ctx.request_repaint();
        }
        if deferred_for_resync > 0 {
            // resync 窓でサムネ upload を先送りした件数。これが出ていれば回帰修正が機能して
            // いる (= 旧来なら黒サムネ化していた upload を surface 復帰まで待たせた)。
            if crate::perf::is_enabled() {
                crate::perf::event(
                    "thumb",
                    "upload_deferred_for_resync",
                    None,
                    self.input_seq,
                    &[("count", serde_json::Value::from(deferred_for_resync))],
                );
            }
            // resync 完了後に backlog を確実に処理させる (surface 復帰フレームで再走)。
            ctx.request_repaint();
        }
        // auto_aspect: 新規 Loaded で samples が増えた可能性があるので切替判定。
        // 6 段ゲート (mode / switches_done / input idle / min_samples / streak / cooldown) は
        // maybe_apply_auto_aspect 内部で行う。received==0 でも streak の時間ベース継続を
        // 評価する必要があるので無条件に呼ぶ (内部の早期 return が安価)。
        // 通常の poll 経路は streak 連勝を要求するので immediate=false。
        self.maybe_apply_auto_aspect(false);
    }

    pub(crate) fn set_details_hover_thumbnail_idx(&mut self, idx: Option<usize>) {
        if self.settings.grid_view_mode != crate::settings::GridViewMode::Details {
            self.clear_details_hover_keep();
            return;
        }

        if self.details_hover_thumb_idx != idx {
            if let Some(prev_idx) = self.details_hover_thumb_idx {
                self.remove_details_hover_thumbnail_request(prev_idx);
                self.evict_grid_thumbnail(prev_idx);
            }
            self.details_hover_thumb_idx = idx;
        }

        let Some(idx) = idx else {
            self.clear_details_hover_keep();
            return;
        };
        if idx >= self.items.len() {
            self.clear_details_hover_keep();
            return;
        }

        self.keep_set.clear();
        self.keep_set.insert(idx);
        self.keep_range = (idx, idx + 1);
        self.keep_start_shared.store(idx, Ordering::Relaxed);
        self.keep_end_shared.store(idx + 1, Ordering::Relaxed);
        self.scroll_hint.store(idx, Ordering::Relaxed);
        self.visible_end_shared.store(idx + 1, Ordering::Relaxed);
        let display_px = (320.0 * self.last_pixels_per_point.max(1.0)).round() as u32;
        self.display_px_shared
            .store(display_px.clamp(128, 1024), Ordering::Relaxed);
        self.enqueue_details_hover_thumbnail(idx);
    }

    fn clear_details_hover_keep(&mut self) {
        if let Some(idx) = self.details_hover_thumb_idx.take() {
            self.remove_details_hover_thumbnail_request(idx);
            self.evict_grid_thumbnail(idx);
        }
        self.keep_range = (0, 0);
        self.keep_set.clear();
        self.keep_start_shared.store(0, Ordering::Relaxed);
        self.keep_end_shared.store(0, Ordering::Relaxed);
    }

    fn remove_details_hover_thumbnail_request(&mut self, idx: usize) {
        if let Some(queue_arc) = self.reload_queue.clone() {
            let (ref mtx, _) = *queue_arc;
            let mut q = mtx.lock().unwrap();
            q.retain(|req| req.idx != idx);
        }
        if let Some(queue_arc) = self.heavy_io_queue.clone() {
            let (ref mtx, _) = *queue_arc;
            let mut q = mtx.lock().unwrap();
            q.retain(|req| req.idx != idx);
        }
        self.requested.remove(&idx);
        self.pending_finalize.remove(&idx);
    }

    fn evict_grid_thumbnail(&mut self, idx: usize) {
        if matches!(self.items.get(idx), Some(GridItem::Video(_))) {
            return;
        }
        if matches!(
            self.thumbnails.get(idx),
            Some(ThumbnailState::Loaded { .. })
        ) && let Some(thumb) = self.thumbnails.get_mut(idx)
        {
            *thumb = ThumbnailState::Evicted;
        }
        self.idle_upgrade_cache_bypass_ineligible.remove(&idx);
        self.thumb_pixels.remove(&idx);
        self.thumb_edit_preview_layers.remove(&idx);
        self.thumb_adjust_tex.remove(&idx);
    }

    /// `keep_set` から外れた通常サムネイルだけを退去させる。
    ///
    /// 差分退去が正しいための不変条件:
    /// 1. `poll_thumbnails` は非動画を Loaded にする時点の `keep_set` 所属を必須にする。
    /// 2. 同じフレームでは `poll_thumbnails` の後、グリッド描画より前に
    ///    `update_keep_range_and_requests` が新しい `keep_set` を作ってここを呼ぶ。
    /// 3. この reconcile を通らず `keep_set` を clear する経路は items 世代を進めるか、
    ///    details hover のように対象を `evict_grid_thumbnail` で明示退去させる。
    ///
    /// したがって同一 items 世代の Loaded は直前の keep_set 内にしか存在せず、差分だけで
    /// 十分。items 差し替え時は Loaded 状態が content key で別 idx へ移される経路があるので、
    /// 世代ごとの初回だけ全 idx を照合する。
    fn reconcile_grid_thumbnail_evictions(
        &mut self,
        previous_keep_set: &std::collections::HashSet<usize>,
        force_full_reconcile: bool,
    ) {
        if force_full_reconcile {
            for idx in 0..self.items.len() {
                if !self.keep_set.contains(&idx) {
                    self.evict_grid_thumbnail(idx);
                }
            }
            return;
        }

        // keep_set は通常数ページ分だけなので、この一時 Vec も数百件程度に留まる。
        // 差分 iterator が self.keep_set を借りたままでは self を変更できないため collect する。
        let leaving: Vec<usize> = previous_keep_set
            .difference(&self.keep_set)
            .copied()
            .collect();
        for idx in leaving {
            self.evict_grid_thumbnail(idx);
        }
    }

    fn enqueue_details_hover_thumbnail(&mut self, idx: usize) {
        if self.requested.contains_key(&idx) {
            return;
        }
        let Some(state) = self.thumbnails.get(idx) else {
            return;
        };
        if !matches!(state, ThumbnailState::Pending | ThumbnailState::Evicted) {
            return;
        }

        let use_full_path_keys = self.use_full_path_cache_keys();
        let req_opt = if self.items_are_drive_list {
            self.items.get(idx).and_then(|item| {
                make_drive_list_pin_load_request(
                    item,
                    idx,
                    self.settings.folder_thumb_sort,
                    self.settings.folder_thumb_depth,
                    &self.folder_pin_map,
                    self.folder_thumb_pin_db.as_deref(),
                )
            })
        } else {
            let Some((mtime, file_size)) = self.image_metas.get(idx).copied().flatten() else {
                return;
            };
            self.items.get(idx).and_then(|item| {
                make_load_request(
                    item,
                    idx,
                    mtime,
                    file_size,
                    false,
                    self.pdf_current_password.as_deref(),
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                    &self.folder_pin_map,
                    &self.converted_archive_cache_paths,
                    self.archive_source_override.as_deref(),
                    self.current_folder.as_deref(),
                    self.folder_thumb_pin_db.as_deref(),
                    self.video_pin_db.as_ref(),
                    use_full_path_keys,
                )
            })
        };

        let Some(mut req) = req_opt else {
            return;
        };
        self.attach_edit_preview_to_request(&mut req);
        if !self.items_are_drive_list
            && let Some(item) = self.items.get(idx)
            && self.should_force_cache_for_drive_list_pin(item)
        {
            req.force_cache = true;
        }
        req.priority = true;
        req.input_seq = self.input_seq;
        req.items_gen = self.items_generation;
        req.context_epoch = crate::pdf_loader::current_render_context_epoch();
        let is_heavy = self.items.get(idx).is_some_and(|item| item.is_heavy_io());
        let queue = if is_heavy {
            self.heavy_io_queue.clone()
        } else {
            self.reload_queue.clone()
        };
        let Some(queue_arc) = queue else {
            return;
        };
        self.requested.insert(idx, false);
        let (ref mtx, ref cvar) = *queue_arc;
        let mut q = mtx.lock().unwrap();
        q.push(req);
        drop(q);
        cvar.notify_one();
    }

    /// 段階 B: ページ単位先読み + eviction のメインロジック。
    /// 段階 D: VRAM 安全ネット (上限超過時に keep_range を縮小)。
    ///
    /// 毎フレーム呼ぶ想定。現在のスクロール位置から keep_range を算出し、
    /// 範囲外の Loaded を Evicted 化し、範囲内の Pending/Evicted を reload_queue に push する。
    fn update_keep_range_and_requests(
        &mut self,
        ctx: &egui::Context,
        frame_t0: std::time::Instant,
    ) {
        // 削除進行中は prefetch / eviction 調整も一時停止する。items にはまだ削除対象の
        // path が残っており、worker が keep_range 内の idx を enqueue するとサムネ再デコードが
        // 走って「Failed」表示が出る (ゴミ箱移動済みなので File::open が失敗する)。
        // Modal で入力は止まっているので keep_range は基本動かず、再 enqueue は発生しない想定。
        if self.delete_pending.is_some() {
            return;
        }
        if self.settings.grid_view_mode == crate::settings::GridViewMode::Details {
            if self.details_thumb_suppression_applied
                && self.thumbnail_eviction_generation == Some(self.items_generation)
            {
                return;
            }
            let previous_keep_set = std::mem::take(&mut self.keep_set);
            self.keep_range = (0, 0);
            self.keep_start_shared.store(0, Ordering::Relaxed);
            self.keep_end_shared.store(0, Ordering::Relaxed);
            self.thumb_pixels.clear();
            self.passthrough_rendition_cache.clear();
            self.thumb_edit_preview_layers.clear();
            self.thumb_adjust_tex.clear();
            let force_full_reconcile =
                self.thumbnail_eviction_generation != Some(self.items_generation);
            self.reconcile_grid_thumbnail_evictions(&previous_keep_set, force_full_reconcile);
            self.thumbnail_eviction_generation = Some(self.items_generation);
            if let Some(queue_arc) = self.reload_queue.clone() {
                let (ref mtx, _) = *queue_arc;
                let mut q = mtx.lock().unwrap();
                for r in q.drain(..) {
                    self.requested.remove(&r.idx);
                }
            }
            if let Some(queue_arc) = self.heavy_io_queue.clone() {
                let (ref mtx, _) = *queue_arc;
                let mut q = mtx.lock().unwrap();
                for r in q.drain(..) {
                    self.requested.remove(&r.idx);
                }
            }
            self.details_thumb_suppression_applied = true;
            return;
        }
        self.details_thumb_suppression_applied = false;
        let total = self.items.len();
        if total == 0 {
            // keep_set と worker atomic boundary も同時にクリアしないと、
            // 空フォルダへの再読み込み直後に前フォルダの bbox が worker に残り続け、
            // 古い enqueue 済みリクエストが in-range 判定で処理されてしまう。
            self.keep_range = (0, 0);
            self.keep_set.clear();
            self.keep_start_shared.store(0, Ordering::Relaxed);
            self.keep_end_shared.store(0, Ordering::Relaxed);
            self.thumbnail_eviction_generation = Some(self.items_generation);
            return;
        }

        // 毎フレーム display_px を更新してワーカーに追従させる
        // (列数変更やウィンドウリサイズに対応)
        let current_display_px = compute_display_px(
            self.last_cell_size,
            self.last_cell_h,
            self.last_pixels_per_point,
        );
        self.display_px_shared
            .store(current_display_px, Ordering::Relaxed);

        let cols = self.settings.grid_cols.max(1);
        // 極端に小さい cell_h (1〜数 px) では `viewport_h / cell_h` が数千行に膨れて
        // keep_set が数万 idx に達し、下流の make_load_request / texture_backlog で
        // UI スレッドが固まる。render_grid 側の MIN_CELL_PX=32 と揃える。
        let cell_h = self.last_cell_h.max(32.0);
        let viewport_h = self.last_viewport_h.max(cell_h);

        let rows_per_page = (viewport_h / cell_h).ceil() as usize;
        let items_per_page = (rows_per_page * cols).max(1);
        // 設計: prefetch / eviction 対象は「display list = visible_indices の一部」を
        // そのまま使い、raw idx の連続範囲には**絶対に潰さない**。
        // `visible_indices` が★フィルタや Ctrl+F で疎になったとき、raw range で扱うと
        // 非可視 idx を大量 (フォルダ 1300 件中 3 件表示 → 991 件の非可視) に enqueue
        // してしまう。詳細は docs/async-architecture.md「display list vs filesystem list」。
        let vis_count = self.visible_indices.len();
        // スクロール位置が vis_count を超えるとき (フィルタ直後の縮退ケース) は末尾に寄せる。
        // さらに vis_count=0 は冒頭で早期 return 済みなのでここでは 1 以上。
        let vis_first_raw = (self.scroll_offset_y / cell_h) as usize * cols;
        let grid_vis_first = vis_first_raw.min(vis_count.saturating_sub(1));
        let vis_first = thumbnail_retention_anchor_position(
            &self.visible_indices,
            grid_vis_first,
            self.fullscreen_idx,
        );
        let fractional_drag_y = crate::ui_main::grid_touch_scroll_remainder(
            ctx,
            self.scroll_offset_y,
            cell_h,
            self.items_generation,
        );
        let strict_visible_end = crate::ui_main::extend_grid_end_for_touch_fraction(
            vis_first.saturating_add(items_per_page),
            cols,
            vis_count,
            fractional_drag_y,
        );
        let strict_visible_items = strict_visible_end.saturating_sub(vis_first);

        let prev_pages = self.settings.thumb_prev_pages as usize;
        let next_pages = self.settings.thumb_next_pages as usize;

        let vis_keep_start = vis_first.saturating_sub(prev_pages * items_per_page);
        let mut vis_keep_end = vis_first
            .saturating_add((1 + next_pages) * items_per_page)
            .min(vis_count);
        vis_keep_end = crate::ui_main::extend_grid_end_for_touch_fraction(
            vis_keep_end,
            cols,
            vis_count,
            fractional_drag_y,
        );

        // ── 共有 VRAM pool: サムネイル保持帯 ───────────────────────────
        // モード別のサムネイル配分を超えている場合だけ、実 texture 寸法と TextureId
        // 重複排除で保持帯を縮める。未ロード項目は 0 texel なので先読み要求自体は許可し、
        // texture が載った後の次フレームで自然に配分へ収束する。現在位置は常に残す。
        let mut vis_keep_start_capped = vis_keep_start;
        let budget = self.vram_pool_budget();
        if let Some(cap_bytes) = budget.thumbnail_bytes {
            let cap_texels = crate::vram_budget::rgba8_bytes_to_texels(cap_bytes);
            let desired = vis_keep_end.saturating_sub(vis_keep_start);
            if desired > 0 {
                let texture_texels_for_bounds = |start: usize, end: usize| {
                    let indices = self
                        .visible_indices
                        .get(start..end)
                        .unwrap_or(&[])
                        .iter()
                        .copied()
                        .collect::<HashSet<_>>();
                    self.thumbnail_texture_texels_for_indices(&indices)
                };
                let desired_texels = texture_texels_for_bounds(vis_keep_start, vis_keep_end);
                if desired_texels > cap_texels {
                    let mut chosen =
                        thumbnail_keep_bounds_for_count(vis_keep_start, vis_keep_end, vis_first, 1);
                    let mut low = 1usize;
                    let mut high = desired;
                    while low <= high {
                        let count = low + (high - low) / 2;
                        let bounds = thumbnail_keep_bounds_for_count(
                            vis_keep_start,
                            vis_keep_end,
                            vis_first,
                            count,
                        );
                        if count == 1 || texture_texels_for_bounds(bounds.0, bounds.1) <= cap_texels
                        {
                            chosen = bounds;
                            low = count.saturating_add(1);
                        } else {
                            high = count.saturating_sub(1);
                        }
                    }
                    vis_keep_start_capped = chosen.0;
                    vis_keep_end = chosen.1;
                    crate::logger::log(format!(
                        "  VRAM thumbnail band reduced: mode={} desired={} kept={} \
                         loaded={} MiB cap={} MiB",
                        self.vram_budget_mode().as_str(),
                        desired,
                        vis_keep_end.saturating_sub(vis_keep_start_capped),
                        crate::vram_budget::rgba8_texels_to_bytes(desired_texels) / (1024 * 1024),
                        cap_bytes / (1024 * 1024),
                    ));
                }
            }
        }
        if crate::ui_main::grid_touch_fraction_is_visible(fractional_drag_y) {
            // The fractional viewport exposes this whole extra row. Even when
            // the VRAM band is capped, do not evict the row currently peeking
            // in at the bottom of the touch-dragged grid.
            vis_keep_start_capped = vis_keep_start_capped.min(vis_first);
            vis_keep_end = vis_keep_end.max(strict_visible_end);
        }

        // keep_set: prefetch / eviction / retain / idle upgrade がこれを使う。
        let keep_slice = self
            .visible_indices
            .get(vis_keep_start_capped..vis_keep_end)
            .unwrap_or(&[]);
        let previous_keep_set = std::mem::take(&mut self.keep_set);
        self.keep_set.extend(keep_slice.iter().copied());

        // keep_range: keep_set の bounding box。worker atomic キャンセル判定で使われる。
        // `visible_indices` は `rebuild_visible_indices` が `for i in 0..n { push(i) }` で
        // 構築するため昇順。その部分列である `keep_slice` も昇順なので、min/max は
        // 端の要素を直接参照すれば O(1)。将来 display list をソート以外の順で構築する
        // 改修が入るときはこの前提ごと再考すること。
        let (keep_start, keep_end) = match (keep_slice.first(), keep_slice.last()) {
            (Some(&mn), Some(&mx)) => (mn, (mx + 1).min(total)),
            _ => (0, 0),
        };
        self.keep_range = (keep_start, keep_end);
        self.keep_start_shared.store(keep_start, Ordering::Relaxed);
        self.keep_end_shared.store(keep_end, Ordering::Relaxed);

        // (1) 範囲外の Loaded を Evicted にする (TextureHandle を drop)
        //     動画サムネイルは一度ロードしたら維持する (別パスのため再要求できない)
        //
        //     重要: ここでは `requested` を触らない。ワーカーが処理中の idx を
        //     requested から抜くと、scroll 戻り時に同じ idx が再エンキューされ、
        //     二重レンダ (特に PDF) を引き起こすため。
        //     requested の cleanup は以下で行う:
        //       - エンキュー済・pop 前の取消: 下の q.retain が dropped idx を remove
        //       - ワーカー pop 後の STALE: worker が canceled=true を送信し
        //         poll_thumbnails が remove
        //       - 正常完了: poll_thumbnails が remove
        let t1 = frame_t0.elapsed();
        let force_full_reconcile =
            self.thumbnail_eviction_generation != Some(self.items_generation);
        self.reconcile_grid_thumbnail_evictions(&previous_keep_set, force_full_reconcile);
        self.thumbnail_eviction_generation = Some(self.items_generation);
        let t2 = frame_t0.elapsed();

        // (2) reload_queue 内の keep_range 外リクエストを除去し、
        //     範囲内の Pending/Evicted を新たに push する。
        //     スクロール中にキューに溜まった古いリクエストをワーカーが無駄に
        //     処理するのを防ぎ、新しい可視領域のリクエストを優先させる。
        //
        //     可視範囲 (1 ページ分) のリクエストは priority=true でマークし、
        //     ワーカーが先読み要求より常に先に処理するようにする。
        let Some(queue_arc) = self.reload_queue.clone() else {
            return;
        };

        // 可視範囲の raw index 範囲を計算 (1 ページ分 + 上下 1 行のマージン)
        let vis_visible_start = vis_first.saturating_sub(cols);
        let vis_visible_end = crate::ui_main::extend_grid_end_for_touch_fraction(
            vis_first.saturating_add(items_per_page + cols),
            cols,
            vis_count,
            fractional_drag_y,
        );
        let visible_raw_start = self
            .visible_indices
            .get(vis_visible_start)
            .copied()
            .unwrap_or(0);
        let visible_raw_end = self
            .visible_indices
            .get(vis_visible_end.saturating_sub(1))
            .copied()
            .map(|i| i + 1)
            .unwrap_or(total)
            .min(total);

        // ── スクロール体感ロギング ─────────────────────────────────────
        // vis 範囲が変化した瞬間 → 安定した瞬間 → 範囲内サムネイルが揃った瞬間を
        // ログに残し、「スクロール停止後にサムネイルが描かれるまでの遅延」を可視化する。
        let cur_vis_range = (visible_raw_start, visible_raw_end);
        if cur_vis_range != self.last_vis_range {
            self.last_vis_range = cur_vis_range;
            self.vis_settle_at = None;
            self.vis_first_logged = false;
            self.vis_all_logged = false;
        } else if self.vis_settle_at.is_none() && cur_vis_range.0 < cur_vis_range.1 {
            self.vis_settle_at = Some(std::time::Instant::now());
            crate::logger::log(format!(
                "[vis] settle vis=[{}..{}) ({} cells)",
                visible_raw_start,
                visible_raw_end,
                visible_raw_end - visible_raw_start,
            ));
            // 安定した瞬間に既に全 Loaded ならその場で all_loaded ログ。
            // 可視セルは visible_indices[vis_visible_start..vis_visible_end] なので
            // そちらを直接走査する (raw range で走ると疎な visible_indices では
            // フィルタで隠れた idx を含んでしまい、all_loaded_now が永久に false になる)。
            let all_loaded_now = self
                .visible_indices
                .get(vis_visible_start..vis_visible_end)
                .map(|slice| {
                    slice.iter().all(|&j| {
                        matches!(self.thumbnails.get(j), Some(ThumbnailState::Loaded { .. }))
                    })
                })
                .unwrap_or(false);
            if all_loaded_now {
                crate::logger::log(
                    "[vis] all_loaded 0ms after settle (already cached)".to_string(),
                );
                self.vis_first_logged = true;
                self.vis_all_logged = true;
            }
        }

        // 通常リクエストと重い I/O リクエストを分けて収集。
        // 反復対象は raw range ではなく keep_set (display list の部分列)。
        // これで ★フィルタ / Ctrl+F で疎になっても非可視 idx が流入しない。
        let mut new_regular: Vec<LoadRequest> = Vec::new();
        let mut new_heavy: Vec<LoadRequest> = Vec::new();
        // PDFium プールの thrash 抑制: PDF 仮想フォルダを開いた直後の grace 期間中は
        // 「現在見えていない PdfPage」(= prefetch) の enqueue をスキップする。
        // 一旦 dispatch すると PDFium は in-flight cancel できないので、ユーザーが
        // 数十 ms 内に Ctrl+↑↓ で次のフォルダに行く場合に「破棄される予定の prefetch
        // render が worker を 200-500ms 占有して、ユーザーが本当に見たいページの render を
        // 後ろに押し出す」という事態を防ぐ。grace を過ぎたら通常通り enqueue する
        // (request_repaint_after で grace 終了時に再実行されるよう確保する)。
        let pdf_prefetch_blocked = self
            .pdf_prefetch_grace_until
            .is_some_and(|t| std::time::Instant::now() < t);
        let mut deferred_pdf_prefetch = false;
        // スクロール中 / visible 待ち中は prefetch enqueue を抑制する gate (decision キャッシュ)。
        // visible 範囲の Pending/Evicted/Requested 数を数えて decide_prefetch_allowed に渡す。
        // **Codex P3-1 (2026-05)**: visible_pending と decision_now は decision とは別に
        // 保持して perf event の field に「実測値」を出す。decision branch から作ると、
        // Backstop3s で visible が pending 残ったまま allow したケースを `visible_ready=true`
        // と誤報告してしまう (= ログ読解で「visible 全部 ready なのに何で遅延?」と混乱)。
        // docs/prefetch-suppression-during-scroll-plan.md 参照。
        let decision_now = std::time::Instant::now();
        let visible_pending_now: usize = self.visible_indices[vis_first..strict_visible_end]
            .iter()
            .filter(|&&raw_idx| {
                !matches!(
                    self.thumbnails.get(raw_idx),
                    Some(ThumbnailState::Loaded { .. }) | Some(ThumbnailState::Failed)
                )
            })
            .count();
        let prefetch_decision: PrefetchDecision = decide_prefetch_allowed(
            decision_now,
            self.last_prefetch_scroll_at,
            visible_pending_now,
        );
        let prefetch_ok = matches!(prefetch_decision, PrefetchDecision::Allow { .. });
        let mut suppressed_regular: usize = 0;
        let mut suppressed_heavy: usize = 0;
        for i in self.keep_set_sorted() {
            if self.requested.contains_key(&i) {
                continue;
            }
            let need_load = matches!(
                self.thumbnails[i],
                ThumbnailState::Pending | ThumbnailState::Evicted
            );
            if !need_load {
                continue;
            }
            // T54: Ctrl+S 検索結果は full-path キーで衝突回避
            let use_full_path_keys = self.use_full_path_cache_keys();
            let req_opt = if self.items_are_drive_list {
                self.items.get(i).and_then(|item| {
                    make_drive_list_pin_load_request(
                        item,
                        i,
                        self.settings.folder_thumb_sort,
                        self.settings.folder_thumb_depth,
                        &self.folder_pin_map,
                        self.folder_thumb_pin_db.as_deref(),
                    )
                })
            } else {
                let Some((mtime, file_size)) = self.image_metas.get(i).copied().flatten() else {
                    continue;
                };
                self.items.get(i).and_then(|item| {
                    make_load_request(
                        item,
                        i,
                        mtime,
                        file_size,
                        false,
                        self.pdf_current_password.as_deref(),
                        Some(self.settings.folder_thumb_sort),
                        self.settings.folder_thumb_depth,
                        &self.folder_pin_map,
                        &self.converted_archive_cache_paths,
                        self.archive_source_override.as_deref(),
                        self.current_folder.as_deref(),
                        self.folder_thumb_pin_db.as_deref(),
                        self.video_pin_db.as_ref(),
                        use_full_path_keys,
                    )
                })
            };
            let Some(mut req) = req_opt else {
                if self.items_are_drive_list {
                    self.thumbnails[i] = ThumbnailState::Failed;
                }
                continue;
            };
            self.attach_edit_preview_to_request(&mut req);
            if !self.items_are_drive_list
                && let Some(item) = self.items.get(i)
                && self.should_force_cache_for_drive_list_pin(item)
            {
                req.force_cache = true;
            }
            req.priority = i >= visible_raw_start && i < visible_raw_end;
            // prefetch suppression: スクロール中 / visible 待ち中は非 priority (= prefetch) を
            // enqueue しない。visible (= priority=true) は常に enqueue する。
            // skip_cache=true は idle upgrade 経路 (本 PR scope 外) なので素通し。
            if !req.priority && !prefetch_ok && !req.skip_cache {
                let is_heavy = self.items.get(i).is_some_and(|it| it.is_heavy_io());
                if is_heavy {
                    suppressed_heavy += 1;
                } else {
                    suppressed_regular += 1;
                }
                continue;
            }
            // grace 中は PdfPage の prefetch (= 非 priority) のみスキップ。現在表示中の
            // PdfPage (= priority=true) は通常通り enqueue する。
            if pdf_prefetch_blocked && !req.priority && req.pdf_page.is_some() {
                deferred_pdf_prefetch = true;
                continue;
            }
            req.input_seq = self.input_seq;
            req.items_gen = self.items_generation;
            // PDF render pool の context epoch を UI スレッドで焼き付ける (TOCTOU 防止)。
            // background 経路は LoadRequest::default() の 0 のまま (= epoch チェック対象外)。
            req.context_epoch = crate::pdf_loader::current_render_context_epoch();
            let is_heavy = self.items.get(i).is_some_and(|it| it.is_heavy_io());
            // perf: エンキューイベント (タスク種別 + 優先度 + 相関 seq)
            if crate::perf::is_enabled() {
                let perf_key = self.perf_item_key(i);
                crate::perf::event(
                    "thumb",
                    "enqueue",
                    perf_key.as_deref(),
                    self.input_seq,
                    &[
                        ("idx", serde_json::Value::from(i)),
                        ("priority", serde_json::Value::from(req.priority)),
                        (
                            "queue",
                            serde_json::Value::from(if is_heavy { "heavy" } else { "regular" }),
                        ),
                        ("items_gen", serde_json::Value::from(self.items_generation)),
                    ],
                );
            }
            if is_heavy {
                new_heavy.push(req);
            } else {
                new_regular.push(req);
            }
        }
        let new_hi = new_regular
            .iter()
            .chain(new_heavy.iter())
            .filter(|r| r.priority)
            .count();
        let new_lo = new_regular.len() + new_heavy.len() - new_hi;
        let t3 = frame_t0.elapsed();
        let regular_count = new_regular.len();
        let mut pruned_regular: usize = 0;
        let mut pruned_heavy: usize = 0;
        {
            let (ref mtx, ref cvar) = *queue_arc;
            let mut q = mtx.lock().unwrap();
            // 範囲外 (keep_set から外れた) キューエントリは取消扱い。pop 前なので worker が
            // 始めてすらいない → requested からも抜いて良い (再入範囲なら次フレームで
            // 再エンキューされる)。keep_set と requested は App の別フィールドなので
            // 事前に分離して disjoint field borrow にする (closure 内で両方必要)。
            //
            // prefetch suppression: priority field は古い (= 前フレの visible_raw 基準) ので、
            // 「now_visible = idx ∈ [visible_raw_start, visible_raw_end)」を inline で再計算する。
            // 非可視 + !skip_cache (= grid prefetch) は prefetch_ok=false なら prune。
            // skip_cache=true は idle upgrade 経路で本 PR scope 外。
            let keep_set = &self.keep_set;
            let requested = &mut self.requested;
            q.retain(|r| {
                let keep = keep_set.contains(&r.idx);
                if !keep {
                    requested.remove(&r.idx);
                    return false;
                }
                let now_visible = r.idx >= visible_raw_start && r.idx < visible_raw_end;
                let is_grid_prefetch = !now_visible && !r.skip_cache;
                if !prefetch_ok && is_grid_prefetch {
                    requested.remove(&r.idx);
                    pruned_regular += 1;
                    return false;
                }
                true
            });
            for r in q.iter_mut() {
                r.priority = r.idx >= visible_raw_start && r.idx < visible_raw_end;
            }
            let _q_before = q.len();
            for r in new_regular {
                requested.insert(r.idx, false);
                q.push(r);
            }
            drop(q);
            for _ in 0..regular_count {
                cvar.notify_one();
            }
        }
        // heavy_io_queue にも同様に push
        let heavy_count = new_heavy.len();
        if let Some(hq) = self.heavy_io_queue.clone() {
            let (ref mtx, ref cvar) = *hq;
            let mut q = mtx.lock().unwrap();
            let keep_set = &self.keep_set;
            let requested = &mut self.requested;
            q.retain(|r| {
                let keep = keep_set.contains(&r.idx);
                if !keep {
                    requested.remove(&r.idx);
                    return false;
                }
                let now_visible = r.idx >= visible_raw_start && r.idx < visible_raw_end;
                let is_grid_prefetch = !now_visible && !r.skip_cache;
                if !prefetch_ok && is_grid_prefetch {
                    requested.remove(&r.idx);
                    pruned_heavy += 1;
                    return false;
                }
                true
            });
            for r in q.iter_mut() {
                r.priority = r.idx >= visible_raw_start && r.idx < visible_raw_end;
            }
            for r in new_heavy {
                requested.insert(r.idx, false);
                q.push(r);
            }
            drop(q);
            for _ in 0..heavy_count {
                cvar.notify_one();
            }
        }
        if new_hi > 0 || new_lo > 0 {
            crate::logger::log(format!(
                "  [queue] push +{new_hi}H +{new_lo}L  keep=[{keep_start}..{keep_end})  vis=[{visible_raw_start}..{visible_raw_end})  requested={}",
                self.requested.len(),
            ));
            // Normal frames also request repaint in the tail via `requested_nonempty`.
            // Fullscreen cleanup / font-atlas resync can return before that tail, so
            // wake the UI from the enqueue site as well.
            ctx.request_repaint();
        }
        let t4 = frame_t0.elapsed();

        // (3) 段階 E: アイドル時の画質アップグレード (対象は `self.keep_set`)
        self.enqueue_idle_upgrades();
        let t5 = frame_t0.elapsed();

        // (4) 固着診断 (5 秒に 1 回): keep_set 内で state が Pending/Evicted
        //     なのに `requested` に居座っているエントリを検出する。
        //     正常時は Pending/Evicted なら再エンキューされて Loaded に進むはず。
        //     この状態が続くと、サムネが「読み込み中」のまま永遠に戻らない。
        if self.last_stuck_scan_at.elapsed().as_secs() >= 5 {
            self.last_stuck_scan_at = std::time::Instant::now();
            let mut stuck: Vec<(usize, &'static str)> = Vec::new();
            for (&idx, _) in &self.requested {
                if !self.keep_set.contains(&idx) {
                    continue;
                }
                let label = match self.thumbnails.get(idx) {
                    Some(ThumbnailState::Pending) => Some("Pending"),
                    Some(ThumbnailState::Evicted) => Some("Evicted"),
                    Some(ThumbnailState::Failed) => Some("Failed"),
                    _ => None,
                };
                if let Some(l) = label {
                    stuck.push((idx, l));
                }
            }
            if !stuck.is_empty() {
                stuck.sort_by_key(|(i, _)| *i);
                let pf = self.pending_finalize.len();
                let bl = self.texture_backlog.len();
                crate::logger::log(format!(
                    "  [stuck] {} entries in requested but not Loaded (keep=[{}..{}) pending_finalize={} backlog={}): {:?}",
                    stuck.len(),
                    keep_start,
                    keep_end,
                    pf,
                    bl,
                    stuck.iter().take(20).collect::<Vec<_>>(),
                ));
            }
        }

        if (t5 - t1).as_millis() > 5 {
            crate::logger::log(format!(
                "    [keep detail] evict={:.1}ms scan={:.1}ms lock+push={:.1}ms idle={:.1}ms",
                (t2 - t1).as_secs_f64() * 1000.0,
                (t3 - t2).as_secs_f64() * 1000.0,
                (t4 - t3).as_secs_f64() * 1000.0,
                (t5 - t4).as_secs_f64() * 1000.0,
            ));
        }

        // grace 中に prefetch を defer したなら、grace 終了時刻に repaint を要求して
        // 自然な再 enqueue タイミングを確保する (= 次フレームでこの関数が再走しても
        // 通常のスクロール repaint が来ない場合でも prefetch が再開される)。
        if pdf_prefetch_blocked && deferred_pdf_prefetch {
            if let Some(deadline) = self.pdf_prefetch_grace_until {
                let remaining = deadline.saturating_duration_since(std::time::Instant::now());
                ctx.request_repaint_after(remaining);
            }
        }
        // grace 期限切れなら field をクリア (毎フレーム比較を省く)。
        if !pdf_prefetch_blocked && self.pdf_prefetch_grace_until.is_some() {
            self.pdf_prefetch_grace_until = None;
        }

        // ── prefetch suppression: repaint 確保 + perf 計装 ──
        // (a) scroll idle / backstop 境界 で再評価が走るよう repaint_after をセット。
        //     scroll idle 不足が原因なら 100ms 後に gate 通過する。
        //     visible 未完了が原因 (idle は満たす) なら thumb worker の ready 経路で repaint
        //     されるが、backstop 3 秒の保険は必ず仕掛ける。
        if !prefetch_ok {
            if let Some(t) = self.last_prefetch_scroll_at {
                let elapsed = t.elapsed();
                let idle_remaining = PREFETCH_IDLE_THRESHOLD.saturating_sub(elapsed);
                if !idle_remaining.is_zero() {
                    ctx.request_repaint_after(idle_remaining);
                }
                let backstop_remaining = PREFETCH_BACKSTOP.saturating_sub(elapsed);
                if !backstop_remaining.is_zero() {
                    ctx.request_repaint_after(backstop_remaining);
                }
            }
        }

        // (b) `prefetch_suppressed` perf event:
        //   start (前フレ allowed → 今フレ blocked) / continue (200ms tick) /
        //   end (前フレ blocked → 今フレ allowed) の 3 種類で emit。
        if crate::perf::is_enabled() {
            let now_pf = std::time::Instant::now();
            let prev_allowed = self.prev_prefetch_allowed;
            let cur_allowed = prefetch_ok;
            let transition: Option<&'static str> = match (prev_allowed, cur_allowed) {
                (Some(false), true) => Some("end"),
                (Some(true), false) | (None, false) => Some("start"),
                (Some(false), false) => {
                    // 200ms tick (= 抑制中の state trace)
                    let tick_elapsed = self
                        .last_prefetch_suppressed_emit_at
                        .map(|t| now_pf.saturating_duration_since(t))
                        .unwrap_or(std::time::Duration::MAX);
                    if tick_elapsed >= std::time::Duration::from_millis(200) {
                        Some("continue")
                    } else {
                        None
                    }
                }
                _ => None,
            };
            if let Some(trans) = transition {
                // **Codex P3-1 (2026-05)**: decision branch から作るのをやめて、実状態
                // (last_prefetch_scroll_at の elapsed + 実 visible_pending count) から
                // 算出する。これで Backstop3s で「visible まだ pending だけど allow した」
                // ケースも `visible_ready=false` / `visible_pending=N` と正直に出る。
                let scroll_idle_elapsed_ms: u64 = self
                    .last_prefetch_scroll_at
                    .map(|t| decision_now.saturating_duration_since(t).as_millis() as u64)
                    .unwrap_or(u64::MAX);
                let scroll_idle =
                    scroll_idle_elapsed_ms >= PREFETCH_IDLE_THRESHOLD.as_millis() as u64;
                let scroll_idle_ms_remaining: u64 = if scroll_idle {
                    0
                } else {
                    (PREFETCH_IDLE_THRESHOLD.as_millis() as u64)
                        .saturating_sub(scroll_idle_elapsed_ms)
                };
                let visible_ready = visible_pending_now == 0;
                let visible_pending = visible_pending_now;
                let allow_reason: Option<&'static str> = match prefetch_decision {
                    PrefetchDecision::Allow {
                        reason: AllowReason::NoScrollYet,
                    } => Some("no_scroll_yet"),
                    PrefetchDecision::Allow {
                        reason: AllowReason::ScrollIdleAndVisibleReady,
                    } => Some("scroll_idle_and_visible_ready"),
                    PrefetchDecision::Allow {
                        reason: AllowReason::Backstop3s,
                    } => Some("backstop_3s"),
                    PrefetchDecision::Block { .. } => None,
                };
                let backstop_hit = matches!(
                    prefetch_decision,
                    PrefetchDecision::Allow {
                        reason: AllowReason::Backstop3s
                    }
                );
                crate::perf::event(
                    "ui",
                    "prefetch_suppressed",
                    None,
                    0,
                    &[
                        ("transition", serde_json::Value::from(trans)),
                        ("scroll_idle", serde_json::Value::from(scroll_idle)),
                        ("visible_ready", serde_json::Value::from(visible_ready)),
                        (
                            "scroll_idle_ms_remaining",
                            serde_json::Value::from(scroll_idle_ms_remaining),
                        ),
                        ("visible_pending", serde_json::Value::from(visible_pending)),
                        (
                            "suppressed_regular",
                            serde_json::Value::from(suppressed_regular),
                        ),
                        (
                            "suppressed_heavy",
                            serde_json::Value::from(suppressed_heavy),
                        ),
                        ("pruned_regular", serde_json::Value::from(pruned_regular)),
                        ("pruned_heavy", serde_json::Value::from(pruned_heavy)),
                        (
                            "allow_reason",
                            allow_reason
                                .map(serde_json::Value::from)
                                .unwrap_or(serde_json::Value::Null),
                        ),
                        ("backstop_hit", serde_json::Value::from(backstop_hit)),
                    ],
                );
                self.last_prefetch_suppressed_emit_at = Some(now_pf);
            }
        }
        self.prev_prefetch_allowed = Some(prefetch_ok);

        // ── PDF pool の visible 昇格 ──
        // スクロール後、`reload_queue` は上で priority を re-tag したが、既に thumb worker が
        // pop して pdf_pool.normal に積んだ Job は priority=false のまま残る。
        // ここで現フレームの visible PDF を集めて pool に「HighNormal lane へ昇格」を依頼する。
        // (docs/scroll-visibility-priority-plan.md Phase 2)
        let visible_keys =
            self.collect_visible_pdf_perf_keys(vis_first, strict_visible_items, vis_count);

        // **Codex P2-2 対応**: dedup 過剰防止。
        // 単に「keys 一致」では、thumb worker が直後に同じ key を pool.normal へ enqueue
        // しても dedup skip で promote が走らない。代わりに以下のいずれかなら lock を取って
        // promote する:
        //   (a) keys が前回と異なる (= スクロールで visible が変わった)
        //   (b) 前回の promote で `not_found_keys > 0` だった (= まだ pool に入ってない key が
        //       後から enqueue されるのを待つ)
        let keys_changed = self.last_promoted_visible_keys.as_ref() != Some(&visible_keys);
        let retry_due_to_pending = self.promote_retry_pending && !visible_keys.is_empty();
        if (keys_changed || retry_due_to_pending) && !visible_keys.is_empty() {
            let stats = crate::pdf_loader::promote_to_high_normal(&visible_keys);
            self.last_promoted_visible_keys = Some(visible_keys);
            // not_found が残っているなら次フレームでも再試行する (= retry latch を立てる)
            self.promote_retry_pending = stats.not_found_keys > 0;
            if crate::perf::is_enabled() && (stats.promoted > 0 || stats.not_found_keys > 0) {
                crate::perf::event(
                    "pdf",
                    "pool_promote_visible",
                    None,
                    0, // input correlation 不要
                    &[
                        ("promoted", serde_json::Value::from(stats.promoted)),
                        ("already_high", serde_json::Value::from(stats.already_high)),
                        ("not_found", serde_json::Value::from(stats.not_found_keys)),
                    ],
                );
            }
        } else if visible_keys.is_empty() {
            // visible が空になった (= PDF 無しフォルダや scroll off で keep_set 0 など)
            // 状態を完全クリア
            self.last_promoted_visible_keys = None;
            self.promote_retry_pending = false;
        }
    }

    /// サムネイル要求と進捗ピークの毎フレーム bookkeeping 境界。
    ///
    /// keep-range 更新は詳細表示・削除中・空一覧で早期 return するが、進捗ピークの寿命は
    /// それらと独立しているため、その後も必ず更新する。
    fn update_thumbnail_frame_bookkeeping(
        &mut self,
        ctx: &egui::Context,
        frame_t0: std::time::Instant,
    ) {
        self.update_keep_range_and_requests(ctx, frame_t0);
        self.update_progress_peaks();
    }

    /// 現フレームの visible 範囲 (strict、prefetch 含まず) に対応する PDF perf_key 集合を返す。
    /// `pdf_loader::promote_to_high_normal` に渡す。
    fn collect_visible_pdf_perf_keys(
        &self,
        vis_first: usize,
        items_per_page: usize,
        vis_count: usize,
    ) -> HashSet<String> {
        let mut keys = HashSet::new();
        let vis_end = vis_first.saturating_add(items_per_page).min(vis_count);
        for &raw_idx in &self.visible_indices[vis_first..vis_end] {
            if let Some(item) = self.items.get(raw_idx) {
                match item {
                    crate::grid_item::GridItem::PdfFile(p) => {
                        keys.insert(crate::grid_item::pdf_page_perf_key(p, 0));
                    }
                    crate::grid_item::GridItem::PdfPage {
                        pdf_path, page_num, ..
                    } => {
                        keys.insert(crate::grid_item::pdf_page_perf_key(pdf_path, *page_num));
                    }
                    _ => {}
                }
            }
        }
        keys
    }

    /// 段階 E: アイドル時に画質アップグレードの要求を投入する。
    ///
    /// 発動条件:
    /// - 設定 `thumb_idle_upgrade` が有効
    /// - スクロールが一定時間 (500 ms) 停止している
    /// - `reload_queue` が空で `requested` も空 (他の作業が全て終わっている)
    ///
    /// アップグレード対象:
    /// 1. `Loaded { from_cache: true }` — キャッシュ (WebP q=75) 由来で画質劣化。
    ///    ただし `FinalCache` origin は対象外集合に記録される
    /// 2. `Loaded { rendered_at_px < current_display_px * 0.8 }` —
    ///    列数変更などで現在のセルサイズより 20% 以上小さい解像度で生成されている
    ///
    /// `keep_set` 内の該当セルを最大 `BATCH` 件ずつ、`skip_cache = true` の
    /// LoadRequest として push する。スクロール優先度付きの worker が visible
    /// 側から先に処理する。
    fn enqueue_idle_upgrades(&mut self) {
        const SCROLL_IDLE_SECS: f64 = 0.5;
        /// ユーザー入力から何秒アイドル経過したらアップグレードを許可するか。
        /// スクロール以外のキー操作やフルスクリーン遷移の直後も PDF ワーカーを
        /// 占有させないために、`last_input_at` ベースのクールダウンを追加している。
        const INPUT_IDLE_SECS: f64 = 0.5;

        if !self.settings.thumb_idle_upgrade || self.items_are_drive_list {
            return;
        }

        // スクロール変化の検出
        if (self.scroll_offset_y - self.last_scroll_offset_y_tracked).abs() > 0.5 {
            self.last_scroll_change_time = std::time::Instant::now();
            self.last_scroll_offset_y_tracked = self.scroll_offset_y;
        }
        let scroll_idle = self.last_scroll_change_time.elapsed().as_secs_f64() >= SCROLL_IDLE_SECS;
        if !scroll_idle {
            return;
        }

        // 入力クールダウン: スクロール以外の入力 (キー・フルスクリーン遷移・ホイール等)
        // の直後もアップグレード起動を抑制する。scroll_offset_y は変わらないが
        // fs_open 等で PDF ワーカーが Critical 要求を処理中かもしれない。
        if let Some(t) = self.last_input_at
            && t.elapsed().as_secs_f64() < INPUT_IDLE_SECS
        {
            return;
        }

        // キューと in-flight が両方空のときだけ走らせる
        if !self.requested.is_empty() {
            return;
        }
        let Some(reload_arc) = self.reload_queue.clone() else {
            return;
        };
        let Some(heavy_arc) = self.heavy_io_queue.clone() else {
            return;
        };
        {
            let (ref mtx, _) = *reload_arc;
            let q = mtx.lock().unwrap();
            if !q.is_empty() {
                return;
            }
        }
        {
            let (ref mtx, _) = *heavy_arc;
            let q = mtx.lock().unwrap();
            if !q.is_empty() {
                return;
            }
        }

        // 現在の display_px (アイドル判定とサイズ比較に使用)
        let current_display_px = self.display_px_shared.load(Ordering::Relaxed);

        // 候補集め: keep_range 内で from_cache=true or 解像度不足のものを全件
        //
        // ※ 以前は BATCH=4 で小分け push していたが、進捗バーが「0/4 → 4/4 → 消える」
        //    を繰り返すちらつき現象が発生していた。現在は keep_range 内の全候補を
        //    一度に push し、進捗バーが 1 本だけ綺麗に伸びるようにする。
        //    - スクロール時は scroll_idle ガードで新規 push されない
        //    - 通常ロードが必要なら requested ガードで先送り
        //    - フォルダ切替は cancel_token で全停止
        //    なので大量 push しても害は無い (古い結果は poll_thumbnails で
        //    keep_set 外なら自動破棄される)。
        let mut upgrade_reqs: Vec<LoadRequest> = Vec::new();
        for i in self.keep_set_sorted() {
            if self.idle_upgrade_cache_bypass_ineligible.contains(&i) {
                continue;
            }
            let needs_upgrade = match self.thumbnails.get(i) {
                Some(ThumbnailState::Loaded {
                    from_cache,
                    from_edit_preview,
                    rendered_at_px,
                    source_dims,
                    ..
                }) => {
                    // 1. キャッシュ由来 (品質アップグレード)
                    // 2. 現在のセルに対して解像度不足 (rendered < target * 0.8)
                    //    u32 オーバーフロー対策で u64 で比較
                    //
                    // target は `min(source_long_edge, current_display_px)`:
                    // 元画像が display_px より小さい場合、どれだけ再デコードしても
                    // 物理的に display_px まで拡大できない (fast_resize は upscale
                    // しない)。source で頭打ちにしないと永久に「解像度不足」判定が
                    // 続き、アイドル時に同じセルを毎サイクル re-enqueue する無限
                    // ループ (進捗バーが高速に左右を往復する原因) になる。
                    let source_long_edge = source_dims.map(|(w, h)| w.max(h));
                    let target_px = source_long_edge
                        .map(|src| src.min(current_display_px))
                        .unwrap_or(current_display_px);
                    !*from_edit_preview
                        && (*from_cache || (*rendered_at_px as u64) * 5 < (target_px as u64) * 4)
                }
                _ => false,
            };
            if !needs_upgrade {
                continue;
            }
            let Some((mtime, file_size)) = self.image_metas.get(i).copied().flatten() else {
                continue;
            };
            // T54: Ctrl+S 検索結果は full-path キーで衝突回避 (= idle upgrade も同じく)
            let use_full_path_keys = self.use_full_path_cache_keys();
            let Some(mut req) = self.items.get(i).and_then(|item| {
                make_load_request(
                    item,
                    i,
                    mtime,
                    file_size,
                    true,
                    self.pdf_current_password.as_deref(),
                    Some(self.settings.folder_thumb_sort),
                    self.settings.folder_thumb_depth,
                    &self.folder_pin_map,
                    &self.converted_archive_cache_paths,
                    self.archive_source_override.as_deref(),
                    self.current_folder.as_deref(),
                    self.folder_thumb_pin_db.as_deref(),
                    self.video_pin_db.as_ref(),
                    use_full_path_keys,
                )
            }) else {
                continue;
            };
            // `--perf-log` の idle-health 検査は、同じ Loaded 状態を入力や世代変更なしに
            // 何度も評価 / 再投入するループを work key 単位で検出する。通常ログだけでは
            // 件数集計が不安定になるため、最終 skip_cache 判定を構造化イベントで残す。
            if crate::perf::is_enabled() {
                let perf_key = self.perf_item_key(i);
                crate::perf::event(
                    "thumb",
                    if req.skip_cache {
                        "idle_upgrade_enqueue"
                    } else {
                        "idle_upgrade_ineligible"
                    },
                    perf_key.as_deref(),
                    self.input_seq,
                    &[
                        ("idx", serde_json::Value::from(i)),
                        ("items_gen", serde_json::Value::from(self.items_generation)),
                        ("skip_cache", serde_json::Value::from(req.skip_cache)),
                    ],
                );
            }
            // `make_load_request` は、catalog を迂回しても改善できない完成済み派生物へ
            // 解決することがある。特に動画ピンは seed 済み WebP をフォルダ自動代表画像で
            // 上書きしないよう `skip_cache = false` を強制する。この最終判定を現在の
            // Loaded サムネイルに memo し、次フレーム以降は pin 解決自体を繰り返さない。
            if !req.skip_cache {
                self.idle_upgrade_cache_bypass_ineligible.insert(i);
                continue;
            }
            req.relative_page_provenance = self.relative_page_provenance_for_idx(i);
            // 通常エンキューと同じく現世代を載せる (旧 items への upgrade 混入防止)
            req.items_gen = self.items_generation;
            // PDF render pool の context epoch を UI スレッドで焼き付ける (TOCTOU 防止)。
            // idle upgrade も UI 経路なので current epoch を使う。
            req.context_epoch = crate::pdf_loader::current_render_context_epoch();
            upgrade_reqs.push(req);
        }

        if upgrade_reqs.is_empty() {
            return;
        }

        crate::logger::log(format!(
            "  idle upgrade: queued {} items (display_px={})",
            upgrade_reqs.len(),
            current_display_px,
        ));
        let mut heavy_reqs: Vec<LoadRequest> = Vec::new();
        let mut regular_reqs: Vec<LoadRequest> = Vec::new();
        for r in upgrade_reqs {
            if self.items.get(r.idx).is_some_and(|it| it.is_heavy_io()) {
                heavy_reqs.push(r);
            } else {
                regular_reqs.push(r);
            }
        }
        for (reqs, queue) in [(regular_reqs, &reload_arc), (heavy_reqs, &heavy_arc)] {
            if reqs.is_empty() {
                continue;
            }
            let count = reqs.len();
            let (ref mtx, ref cvar) = **queue;
            let mut q = mtx.lock().unwrap();
            for r in reqs {
                self.requested.insert(r.idx, true);
                q.push(r);
            }
            drop(q);
            for _ in 0..count {
                cvar.notify_one();
            }
        }
    }

    /// アイドル高画質化の開始条件が時刻待ちだけなら、その時刻に 1 回だけ起こす。
    ///
    /// 以前は範囲外サムネイルの `Pending` が常に repaint を駆動していたため、自然に
    /// 500ms アイドル判定へ到達していた。範囲外 `Pending` で常時描画しないようにした後も、
    /// 高画質化の開始タイミングだけは維持する。
    ///
    /// **MARGIN の意図 (フレーム内境界レース対策、2026-06-19)**:
    /// `enqueue_idle_upgrades` はフレーム先頭 (`update_keep_range_and_requests` 内) で
    /// idle 経過を評価し、本関数はフレーム末尾で評価する。同一フレーム内で経過時間が
    /// ちょうど 500ms 境界をまたぐと、enqueue は「まだ idle 未満」で skip する一方、本関数は
    /// 「idle 到達」とみなして `None` を返し、egui がそのまま就寝してしまう。すると次の
    /// ユーザー入力 (マウス移動等) までアイドル高画質化が一切走らず、ESC で親一覧へ直帰した
    /// 直後にサムネが低画質/灰色のまま固まる (perf-log で約 7.9 秒のフレーム停止を確認、
    /// `tail_repaint action=none reasons=[]` のまま入力まで 0 フレーム)。
    /// そこで wake フレームを閾値より MARGIN だけ後ろに置き、起床したフレーム先頭の
    /// enqueue が確実に「idle 到達済み」で enqueue できるようにする。enqueue が走れば
    /// `requested` が埋まり、上の早期 return が `None` を返して通常の repaint ループに移る。
    fn thumb_idle_upgrade_recheck_delay(&self) -> Option<std::time::Duration> {
        const SCROLL_IDLE: std::time::Duration = std::time::Duration::from_millis(500);
        const INPUT_IDLE: std::time::Duration = std::time::Duration::from_millis(500);
        // フレーム長 + Windows タイマー粒度 (~15ms) を十分に上回る余白。
        const MARGIN: std::time::Duration = std::time::Duration::from_millis(50);

        if !self.settings.thumb_idle_upgrade || !self.requested.is_empty() {
            return None;
        }

        let mut delay =
            (SCROLL_IDLE + MARGIN).saturating_sub(self.last_scroll_change_time.elapsed());
        if let Some(last_input_at) = self.last_input_at {
            delay = delay.max((INPUT_IDLE + MARGIN).saturating_sub(last_input_at.elapsed()));
        }

        if delay.is_zero() { None } else { Some(delay) }
    }

    /// in-flight + キュー内の通常/アップグレード件数を返す。
    ///
    /// `requested` マップは queue に push した時点で insert され、
    /// 結果を受信した時点で remove されるので、キュー待ち + ワーカー処理中の
    /// 全件を正確に反映している。queue を別途カウントすると二重計上になるため
    /// `requested` のみを集計する。
    fn count_pending(&self) -> (usize, usize) {
        let (mut in_normal, mut in_upgrade) = (0usize, 0usize);
        for (&idx, &is_upgrade) in &self.requested {
            // keep_set 外 (非可視 + 先読み範囲外) のリクエストは「処理中だがスクロール
            // またはフィルタ変更で不要になった」もの。進捗バーに含めない
            // (ワーカー完了時に除去される)。
            if !self.keep_set.contains(&idx) {
                continue;
            }
            if is_upgrade {
                in_upgrade += 1;
            } else {
                in_normal += 1;
            }
        }
        (in_normal, in_upgrade)
    }

    /// 現在の要求状況からプログレスバーのピーク値を更新する。
    fn update_progress_peaks(&mut self) {
        let backlog_count = self.texture_backlog.len();
        let (cur_normal_raw, cur_upgrade) = self.count_pending();
        // backlog 内のアイテムは requested に残っており count_pending でカウント
        // 済みだが、実際にはデコード完了済み。pending として見せると分母が膨らむので
        // 差し引く (ただし 0 以下にはしない)。
        let cur_normal = cur_normal_raw.saturating_sub(backlog_count);

        if cur_normal == 0 {
            self.progress_normal_peak = 0;
        } else if cur_normal > self.progress_normal_peak {
            // 新しいスクロール位置で新規リクエストが発生した場合は
            // peak を現在値にリセットする (古い peak が蓄積し続けるのを防ぐ)
            self.progress_normal_peak = cur_normal;
        }
        if cur_upgrade == 0 {
            self.progress_upgrade_peak = 0;
        } else if cur_upgrade > self.progress_upgrade_peak {
            self.progress_upgrade_peak = cur_upgrade;
        }
    }

    /// プログレスバーの現在値を計算して返す。
    /// `(normal (cur, peak), upgrade (cur, peak))`
    pub(crate) fn progress_snapshot(&self) -> ((usize, usize), (usize, usize)) {
        let (cur_normal, cur_upgrade) = self.count_pending();
        (
            (cur_normal, self.progress_normal_peak),
            (cur_upgrade, self.progress_upgrade_peak),
        )
    }

    fn handle_keyboard(&mut self, ctx: &egui::Context) -> Option<crate::ui_main::AddressBarNav> {
        // マウスドライバ / AHK 経由で積まれた進む/戻る pending を early-return より前に
        // drain する。検索バー / ダイアログ / IME 変換中などショートカットを止める分岐で
        // 早期 return しても、ブロック中の pending は今フレームで破棄したい
        // (= フォーカス解除後に遅れて Ctrl+↑/↓ として暴発するのを防ぐため、Codex P2)。
        //
        // ただし fullscreen/detached viewer が入力先になる状態では drain しない。
        // `App::update` は `handle_keyboard` → `render_fullscreen_viewport` の順で呼ぶため、
        // ここで先に drain してしまうと fullscreen の `handle_fs_key_input` 側が pending を
        // 見られず、画像系フルスクリーンの進む/戻る (= egui Key 経路に出ない
        // WM_APPCOMMAND / Browser_Forward) が失われる (Codex 2 周目 P2)。判断の詳細は
        // `main_keyboard_should_drain_mouse_nav` に集約する。
        let main_has_focus = ctx.input(|i| i.viewport().focused).unwrap_or(true);
        let (browser_back_count, browser_forward_count) =
            if self.main_keyboard_should_drain_mouse_nav(main_has_focus) {
                crate::take_pending_mouse_nav()
            } else {
                (0, 0)
            };

        // 「ページを直接開く」設定 ON の ZIP/PDF からの Esc/Enter/右クリックで立った
        // 「親フォルダ (一覧) へ戻る」予約を最優先で処理する。フルスクリーン handler が
        // 前フレームに立てたもので、ここで通常のナビ経路 (load → 内部で close_fullscreen)
        // へ流すことで L2 ページ一覧を見せずに L1 へ抜ける。フォーカス/ダイアログ判定より
        // 前に出す (確実に消化するため)。
        if let Some(nav) = self.take_pending_return_to_parent_nav() {
            return Some(nav);
        }

        // ウィンドウにフォーカスがない場合はキー入力を無視
        if !main_has_focus {
            return None;
        }
        if self.active_detached_viewer_has_foreground() {
            // debug ログ (log_detached_image_window_debug) は detached 実装ごと
            // cfg(windows) なので、この診断部分だけゲートする。
            #[cfg(windows)]
            {
                let has_key_event = ctx.input(|i| {
                    i.events
                        .iter()
                        .any(|event| matches!(event, egui::Event::Key { pressed: true, .. }))
                });
                if has_key_event {
                    self.log_detached_image_window_debug(
                        "main_keyboard_suppressed_active_detached_foreground".to_string(),
                    );
                }
            }
            return None;
        }
        // フルスクリーン、ダイアログ、テキスト入力中はショートカットを無効化
        if self.shortcuts_blocked_by_text_input(ctx) {
            return None;
        }

        // IME 変換直後の Enter 漏れ対策:
        // 検索バー / お気に入り検索バー / 全文検索バーが表示中で、かつ直近に IME イベントが
        // あった場合、この `handle_keyboard` 呼び出しをスキップして Enter がグリッドの
        // フルスクリーン起動ショートカットに回らないようにする。
        // (IME が Commit を吐いたフレームで TextEdit が一瞬 lost_focus → *_has_focus
        //  が false になり、次フレームで Enter が grid 側に漏れるレースをガードする)。
        if (self.show_search_bar
            || self.favsearch.active
            || self.global_search.active
            || self.tag_view.active)
            && self.ime_input_active(ctx)
        {
            return None;
        }

        if let Some(nav) = self.handle_folder_pane_keyboard(ctx) {
            return Some(nav);
        }
        // ペイン開閉トグル (F) は `folder_pane_blocks_grid_keyboard()` の early-return
        // より **前** で処理する。ペイン表示は即フォーカスを奪う (set_folder_tree_pane_visible)
        // ため、early-return の後ろに置くと「F で開く」はできても「F で閉じる」が
        // 効かない片道トグルになる (ペインにフォーカスがある間は閉じられない)。
        // 閉じる時はカーソルが別フォルダへ動いていれば Enter 相当でそこへ移動する
        // (`toggle_folder_tree_pane_from_key`)。
        if !self.address_has_focus
            && !self.search_has_focus
            && !self.favsearch.has_focus
            && !self.global_search.has_focus
            && !self.tag_view.has_focus
            && !self.viewer_session_blocks_main_window()
            && !self.any_dialog_open()
            && self
                .keymap
                .consume_action(ctx, KeyAction::GridToggleFolderTreePane)
        {
            self.toggle_folder_tree_pane_from_key();
            return None;
        }
        if self.folder_pane_blocks_grid_keyboard() {
            return None;
        }

        if let Some(action) = self.keymap.consume_first_action(
            ctx,
            &[CommandScope::Grid],
            LOCATION_NAVIGATION_ACTIONS,
        ) {
            if let Some(nav) =
                self.apply_location_navigation_key_action(ctx, action, "grid-location-key")
            {
                return Some(nav);
            }
            return None;
        }

        if let Some(action) =
            self.keymap
                .consume_first_action(ctx, &[CommandScope::Grid], PINNED_TAG_ACTIONS)
        {
            self.apply_pinned_tag_key_action(action, "grid-pinned-tag-key");
            return None;
        }

        if !self.ime_input_active(ctx) && self.consume_context_shortcuts_help_key(ctx) {
            self.show_context_shortcuts_help = true;
            return None;
        }

        if self
            .keymap
            .consume_action(ctx, KeyAction::GridOpenPreferences)
        {
            self.show_preferences = true;
            return None;
        }
        if self
            .keymap
            .consume_action(ctx, KeyAction::GridOpenOperationCustomize)
        {
            self.show_operation_customize = true;
            return None;
        }

        if self.keymap.consume_action(ctx, KeyAction::GridRename) {
            self.request_grid_rename_dialog();
            return None;
        }
        if self.keymap.consume_action(ctx, KeyAction::GridReload) {
            self.reload_top_level_grid(ctx);
            return None;
        }

        if self
            .keymap
            .consume_action(ctx, KeyAction::GridToggleStackMode)
        {
            self.toggle_stack_mode();
            return None;
        }

        let cols = self.settings.grid_cols.max(1);

        // Ctrl の状態判定。AutoHotKey 等の外部ツールが Ctrl+矢印を送信する場合、
        // Ctrl と矢印が別フレームで届くことがある。直前フレームの Ctrl 押下も
        // 考慮するため、egui の全イベントから Ctrl 修飾子を探す。
        let ctrl_held = ctx.input(|i| {
            // 現在のフレームで Ctrl が押されている
            if i.modifiers.ctrl {
                return true;
            }
            // イベントの中に Ctrl 修飾子付きのキーイベントがあるか
            i.events.iter().any(|e| match e {
                egui::Event::Key { modifiers, .. } => modifiers.ctrl,
                _ => false,
            })
        });
        let alt_held = ctx.input(|i| {
            if i.modifiers.alt {
                return true;
            }
            i.events.iter().any(|e| match e {
                egui::Event::Key { modifiers, .. } => modifiers.alt,
                _ => false,
            })
        });

        let (right, left, down, up, _ctrl_up_raw, _ctrl_down_raw, mouse_back, mouse_forward) = ctx
            .input(|i| {
                (
                    i.key_pressed(egui::Key::ArrowRight),
                    i.key_pressed(egui::Key::ArrowLeft),
                    i.key_pressed(egui::Key::ArrowDown),
                    i.key_pressed(egui::Key::ArrowUp),
                    i.modifiers.ctrl && i.key_pressed(egui::Key::ArrowUp),
                    i.modifiers.ctrl && i.key_pressed(egui::Key::ArrowDown),
                    i.pointer.button_pressed(egui::PointerButton::Extra1),
                    i.pointer.button_pressed(egui::PointerButton::Extra2),
                )
            });

        // マウスドライバが WM_APPCOMMAND / VK_BROWSER_BACK/FORWARD で送る経路 (上で
        // 関数頭で drain 済み) を消費。詳細は main.rs の `install_mouse_nav_hook` 参照。
        let browser_back = browser_back_count > 0;
        let browser_forward = browser_forward_count > 0;
        let mouse_nav_back = mouse_back || browser_back;
        let mouse_nav_forward = mouse_forward || browser_forward;
        if mouse_nav_back || mouse_nav_forward {
            return self.apply_mouse_back_forward_button(
                ctx,
                mouse_nav_forward,
                ActionSurface::MainWindow,
                "grid-mouse",
            );
        }
        if self.update_mouse_middle_short_click(ctx, true, ActionSurface::MainWindow) {
            return self.apply_mouse_button(
                ctx,
                crate::ring_shortcut::MouseButtonSlot::Middle,
                ActionSurface::MainWindow,
                "grid-middle-mouse",
            );
        }
        let space = self.keymap.pressed_action(ctx, KeyAction::GridToggleCheck);
        let open_selected_key = self.keymap.pressed_action(ctx, KeyAction::GridOpenSelected);
        let open_selected_as_page_key = self
            .keymap
            .pressed_action(ctx, KeyAction::GridOpenSelectedAsPage);
        let open_selected_as_list_key = self
            .keymap
            .pressed_action(ctx, KeyAction::GridOpenSelectedAsList);
        let external_player_key = self
            .keymap
            .pressed_action(ctx, KeyAction::GridOpenExternalPlayer);
        let home = self.keymap.pressed_action(ctx, KeyAction::GridMoveFirst);
        let end = self.keymap.pressed_action(ctx, KeyAction::GridMoveLast);
        let page_up = self.keymap.pressed_action(ctx, KeyAction::GridPagePrev);
        let page_down = self.keymap.pressed_action(ctx, KeyAction::GridPageNext);
        let key_r = self.keymap.pressed_action(ctx, KeyAction::GridRotateCw);
        let key_l = self.keymap.pressed_action(ctx, KeyAction::GridRotateCcw);

        let ctrl_up = self
            .keymap
            .consume_action(ctx, KeyAction::GridTreeFolderPrev);
        let ctrl_down = self
            .keymap
            .consume_action(ctx, KeyAction::GridTreeFolderNext);
        if ctrl_up || ctrl_down {
            crate::logger::log(format!(
                "[input-nav] source=grid action={} ctrl_held={ctrl_held} up={up} down={down} \
                 mouse_back={mouse_back} mouse_forward={mouse_forward} browser_back={} \
                 browser_forward={}",
                if ctrl_down {
                    "ctrl_nav_forward"
                } else {
                    "ctrl_nav_back"
                },
                browser_back_count,
                browser_forward_count
            ));
        }
        let ctrl_page_up = self
            .keymap
            .consume_action(ctx, KeyAction::GridSiblingFolderPrev);
        let ctrl_page_down = self
            .keymap
            .consume_action(ctx, KeyAction::GridSiblingFolderNext);
        let history_back_key = self.keymap.consume_action(ctx, KeyAction::GridHistoryBack);
        let history_forward_key = self
            .keymap
            .consume_action(ctx, KeyAction::GridHistoryForward);

        // Ctrl+G の DrilledInto で drill-back する手段は BS (↓で始まる通常ハンドラ)
        // と検索バーの ← ボタンに限定する。
        // 旧実装: ← キーでも drill-back させていたが、グリッドのカーソル左移動を
        // 奪ってしまい「上右下は動くのに左だけ親階層へ戻る」という現象になっていた
        // (ユーザー報告 2026-04)。カーソル移動を優先する設計に戻す。

        // レーティング 1〜5 / 解除 (既定: F1〜F6)
        // (チェック済みアイテムがあれば一括、なければ選択にのみ)
        // コンテナ★ (既定: Shift+F1〜F6): 現在一覧表示中のフォルダ / ZIP / PDF 本体に評価を付与。
        // コンテナ★は可視アイテムが 0 件でも current_folder に対して成立するため、
        // visible_indices の有無に関係なく処理する。
        {
            let shift_rating_key = self.keymap.consume_rating_action(ctx, true);
            if let Some(stars) = shift_rating_key {
                match self.set_current_folder_rating(stars) {
                    Ok(true) => self.show_container_rating_toast(stars),
                    Ok(false) => {}
                    Err(error) => self.report_rating_write_error(&error),
                }
            }
            let rating_key = self.keymap.consume_rating_action(ctx, false);
            if let Some(stars) = rating_key {
                self.apply_rating_to_selection(stars);
            }
        }

        // コンテナ★の Undo/Redo も空表示時に効くよう、可視アイテム数には依存させない。
        self.handle_meta_undo_keys(ctx);

        // F11: メインウィンドウを最大化 ⇔ 復元する (グリッド表示時)。フルスクリーン中は
        // ui_fullscreen 側が F11 を window/全画面トグルに使うのでこの経路には来ない。
        // ウィンドウ操作なので可視アイテム数に依存させない (空フォルダ / 検索 0 件でも効く。
        // Codex P3 2026-06-19: 以前は `if vi_len > 0` 内にあり 0 件グリッドで無反応だった)。
        if self
            .keymap
            .consume_action_no_repeat(ctx, KeyAction::GridToggleMaximize)
        {
            self.toggle_main_window_maximized(ctx);
        }

        let display_order = self.current_grid_order().to_vec();
        let vi = display_order.as_slice();
        let vi_len = vi.len();

        if vi_len > 0 {
            let sel = self
                .selected
                .unwrap_or_else(|| vi.first().copied().unwrap_or(0));
            // visible_indices 内での現在位置
            let vis_pos = vi.iter().position(|&i| i == sel).unwrap_or(0);
            let cell_h = self.last_cell_h.max(1.0);
            let visible_rows = (self.last_viewport_h / cell_h).floor() as usize;
            let nav_cols = if self.settings.grid_view_mode == crate::settings::GridViewMode::Details
            {
                1
            } else {
                cols.max(1)
            };
            let page_items = visible_rows.max(1) * nav_cols;
            let shift = ctx.input(|i| i.modifiers.shift);
            // Shift+矢印の範囲チェックは下で線形区間として扱う。端をループさせると
            // 隣接する 1 回の移動で一覧全体が範囲に入るため、Shift 中だけ従来どおりクランプする。
            let cursor_wrap = self.settings.grid_cursor_wrap && !shift;

            // 画面上の表示順で移動し、raw index に変換する。
            // Ctrl+矢印はフォルダ移動に使うので、通常カーソル移動から除外
            let cursor_direction = if right && !ctrl_held && !alt_held {
                Some(GridCursorDirection::Right)
            } else if left && !ctrl_held && !alt_held {
                Some(GridCursorDirection::Left)
            } else if down && !ctrl_held && !alt_held {
                Some(GridCursorDirection::Down)
            } else if up && !ctrl_held && !alt_held {
                Some(GridCursorDirection::Up)
            } else {
                None
            };
            let new_vis_pos = if let Some(direction) = cursor_direction {
                grid_cursor_nav_target_pos(vis_pos, vi_len, nav_cols, direction, cursor_wrap)
            } else if home {
                Some(0)
            } else if end {
                Some(vi_len - 1)
            } else if page_down && !ctrl_held {
                Some((vis_pos + page_items).min(vi_len - 1))
            } else if page_up && !ctrl_held {
                Some(vis_pos.saturating_sub(page_items))
            } else {
                None
            };

            let new_sel = new_vis_pos.and_then(|vp| vi.get(vp).copied());

            if let Some(s) = new_sel {
                // Shift+カーソル: 移動元から移動先までの画像をチェックに追加
                if shift && new_vis_pos.is_some() {
                    let old_pos = vis_pos;
                    let new_pos = new_vis_pos.unwrap();
                    let (start, end) = if old_pos <= new_pos {
                        (old_pos, new_pos)
                    } else {
                        (new_pos, old_pos)
                    };
                    for vp in start..=end {
                        if let Some(&idx) = vi.get(vp)
                            && self.grid_item_can_be_checked(idx)
                        {
                            self.checked.insert(idx);
                        }
                    }
                }

                self.selected = Some(s);
                self.scroll_to_selected = true;
                self.update_last_selected_image();
                // perf: グリッドのカーソル移動イベントを記録
                self.bump_input_seq("grid_key", Some(&format!("sel={s}")));
            }

            // スペースキー: チェック ON/OFF
            if space {
                if let Some(idx) = self.selected {
                    if self.checked.contains(&idx) {
                        self.checked.remove(&idx);
                    } else if self.grid_item_can_be_checked(idx) {
                        self.checked.insert(idx);
                    }
                }
            }

            // X: サムネイル一覧から比較スロットへピン留め。
            // Ctrl+X のファイルカットとは競合させないため、修飾キーなしのみ拾う。
            let compare_pin_key = self.keymap.consume_action(ctx, KeyAction::GridComparePin);
            if compare_pin_key {
                self.toggle_compare_pin_from_grid_selection(ctx);
            }

            // L/R: 選択画像を回転
            if key_r {
                if let Some(idx) = self.selected {
                    self.rotate_image_cw(idx);
                }
            }
            if key_l {
                if let Some(idx) = self.selected {
                    self.rotate_image_ccw(idx);
                }
            }

            // F7/F8: 消しゴムマスクスロット 1/2 を一括適用
            // F9/F10: 隠蔽マスクスロット 1/2 を一括適用
            // Shift+F7/F8/F9/F10: 適用済みマスクを対象ページから削除
            // (チェック済みアイテムがあれば一括、なければ選択 1 件に)
            // フルスクリーン側 (ui_fullscreen.rs) と同じ既定キーを keymap 経由で扱う。
            {
                enum MaskShortcut {
                    ApplyErase(usize),
                    ApplyConceal(usize),
                    DeleteErase,
                    DeleteConceal,
                }

                let mask_shortcut = if self
                    .keymap
                    .consume_action(ctx, KeyAction::GridDeleteEraseMask)
                {
                    Some(MaskShortcut::DeleteErase)
                } else if self
                    .keymap
                    .consume_action(ctx, KeyAction::GridDeleteConcealMask)
                {
                    Some(MaskShortcut::DeleteConceal)
                } else if self.keymap.consume_action(ctx, KeyAction::GridApplyErase1) {
                    Some(MaskShortcut::ApplyErase(1))
                } else if self.keymap.consume_action(ctx, KeyAction::GridApplyErase2) {
                    Some(MaskShortcut::ApplyErase(2))
                } else if self
                    .keymap
                    .consume_action(ctx, KeyAction::GridApplyConceal1)
                {
                    Some(MaskShortcut::ApplyConceal(1))
                } else if self
                    .keymap
                    .consume_action(ctx, KeyAction::GridApplyConceal2)
                {
                    Some(MaskShortcut::ApplyConceal(2))
                } else {
                    None
                };
                if let Some(mask_shortcut) = mask_shortcut {
                    match mask_shortcut {
                        MaskShortcut::ApplyErase(slot) => self.apply_slot_to_selection(slot),
                        MaskShortcut::ApplyConceal(slot) => {
                            self.apply_conceal_slot_to_selection(slot)
                        }
                        MaskShortcut::DeleteErase => self.delete_erase_masks_from_selection(),
                        MaskShortcut::DeleteConceal => self.delete_conceal_masks_from_selection(),
                    }
                }
            }

            // ──
            // VST3 プラグイン GUI のショートカットキー (旧 V キー) は撤去した。
            // 理由: プラグイン GUI が最前面で開くと mIV メインウィンドウから
            // フォーカスを奪い、その後 V キーを押しても egui がイベントを受け
            // 取れず無反応になる (= "Vキーを何度も押すと表示されなくなる")。
            // ツールバー / フルスクリーンホバーバーの "VST" ボタンから管理
            // パネルを開いて GUI 表示・非表示する UI に統一。
            // ──

            // Ctrl+1〜0: 補正プリセットスロットを一括適用
            {
                const SLOT_ACTIONS: [KeyAction; 10] = [
                    KeyAction::GridAdjustSlot1,
                    KeyAction::GridAdjustSlot2,
                    KeyAction::GridAdjustSlot3,
                    KeyAction::GridAdjustSlot4,
                    KeyAction::GridAdjustSlot5,
                    KeyAction::GridAdjustSlot6,
                    KeyAction::GridAdjustSlot7,
                    KeyAction::GridAdjustSlot8,
                    KeyAction::GridAdjustSlot9,
                    KeyAction::GridAdjustSlot10,
                ];
                let preset_slot = SLOT_ACTIONS
                    .iter()
                    .position(|action| self.keymap.consume_action(ctx, *action));
                if let Some(slot) = preset_slot {
                    // capture_adjust_full でラップして、N ページの一括書き換えを
                    // 1 つの UndoEntry にまとめて Ctrl+Z で全部戻せるようにする (Codex P2)。
                    self.capture_adjust_full(
                        format!(
                            "スロット{}を一括適用",
                            crate::adjustment::slot_key_label(slot)
                        ),
                        |app| app.apply_slot_to_grid_selection(slot),
                    );
                }
            }

            // Q / Ctrl+Backspace: チェック済み (なければ選択 1 件) の個別補正を一括解除
            // フルスクリーン側 (ui_fullscreen.rs) と同じキー割当。
            // Ctrl+Backspace は consume_key しておかないと後段の「BS で親フォルダ」と衝突する。
            {
                let clear_key = self.keymap.consume_action(ctx, KeyAction::GridClearAdjust);
                if clear_key {
                    self.capture_adjust_full("個別設定を一括解除".to_string(), |app| {
                        app.clear_page_params_for_selection()
                    });
                }
            }

            if open_selected_as_page_key || open_selected_as_list_key {
                let mode = if open_selected_as_page_key {
                    GridContainerOpenMode::PageFullscreen
                } else {
                    GridContainerOpenMode::PageList
                };
                return self.open_selected_grid_container_with_mode(
                    ctx,
                    mode,
                    "grid_open_container_mode",
                );
            }

            let external_player_video = external_player_key
                && self
                    .selected
                    .and_then(|idx| self.items.get(idx))
                    .is_some_and(|item| matches!(item, GridItem::Video(_)));
            if open_selected_key || external_player_video {
                // Shift+Enter などに割り当てた専用コマンドで動画を外部プレイヤーで開く
                // (フルスクリーン中と
                // 同じ挙動をグリッドからも使えるようにする)。
                if let Some(idx) = self.selected {
                    if self.items_are_bookmark_view {
                        if let Some(row) = self.bookmark_browser_rows.get(idx).cloned() {
                            self.open_bookmark_browser_row(ctx, &row);
                        }
                        return None;
                    }
                    if !self.guard_reading_history_open(idx) {
                        return None;
                    }
                    // 閲覧履歴ビューから本を開く場合は、閉じたときに閲覧履歴へ戻れるよう予約する。
                    self.note_reading_history_open(idx);
                    // ファイル名スタックの集約グリッドでメディアセルを Enter したら、フラット読書
                    // フルスクリーンへ (スタック/単独画像/動画を直接開く)。コンテナは false で通常へ。
                    // ただし Shift+Enter で動画を外部プレイヤーに渡す経路は intercept より優先する
                    // (= 動画 + shift_enter のときは intercept をスキップして下の Video arm に流す)。
                    let stack_skip_for_external_video = external_player_video
                        && matches!(self.items.get(idx), Some(GridItem::Video(_)));
                    if !stack_skip_for_external_video
                        && self.stack_try_open_from_grid(ctx, idx, false)
                    {
                        return None;
                    }
                    #[cfg(windows)]
                    if self.open_grid_container_in_detached_book_context(ctx, idx) {
                        return None;
                    }
                    match self.items.get(idx) {
                        Some(GridItem::Folder(p))
                        | Some(GridItem::ZipFile(p))
                        | Some(GridItem::PdfFile(p)) => {
                            // 環境設定 ON のとき ZIP/PDF、または画像だけの通常フォルダは
                            // ページ一覧を経由せずフルスクリーンで開く。
                            let p = p.clone();
                            let auto_fs = self.should_auto_fullscreen_grid_container(idx);
                            #[cfg(windows)]
                            if auto_fs
                                && !self.park_active_detached_context_for_new_grid_open(ctx, idx)
                            {
                                return None;
                            }
                            if auto_fs {
                                self.pending_auto_fs_open = true;
                            }
                            self.maybe_suppress_rating_filter_for_opened_container(idx);
                            self.maybe_suppress_facet_filter_for_opened_container(idx);
                            self.record_rating_view_nav_open(&p);
                            self.begin_smart_folder_drill(&p);
                            return Some(crate::ui_main::AddressBarNav::Direct(p));
                        }
                        Some(GridItem::Video(p)) if external_player_video => {
                            crate::ui_helpers::open_external_player(p);
                        }
                        Some(GridItem::Image(_))
                        | Some(GridItem::ZipImage { .. })
                        | Some(GridItem::PdfPage { .. })
                        | Some(GridItem::Video(_))
                        | Some(GridItem::Audio(_)) => {
                            #[cfg(windows)]
                            if !self.prepare_detached_context_for_grid_open(ctx, idx) {
                                return None;
                            }
                            // 動画も画像と同じくフルスクリーン化 → インライン再生。
                            // Shift+Enter は上の専用分岐で外部プレイヤーへ。
                            // Phase 7.J: Enter からの open はグリッド意図扱い。
                            self.bump_input_seq_for_item("grid_enter", idx);
                            self.fs_open_intent_from_grid = true;
                            // P10-1 follow-up: Enter で open した直後、同フレームの
                            // input queue に残った Enter event を `handle_fullscreen_root_key_input`
                            // が拾って即 close する事故を防ぐ。詳細は
                            // `fs_suppress_enter_close_until_release` の doc 参照。
                            self.fs_suppress_enter_close_until_release = true;
                            self.open_fullscreen(idx, crate::app::HistoryTrigger::UserChosen);
                        }
                        Some(GridItem::ConvertibleArchive { path, .. }) => {
                            let pf = path.clone();
                            self.begin_smart_folder_drill(&pf);
                            self.maybe_suppress_rating_filter_for_opened_container(idx);
                            self.maybe_suppress_facet_filter_for_opened_container(idx);
                            let auto_fs = self.settings.effective_auto_fullscreen_zip_pdf();
                            let search_rollback = if self.favsearch.active
                                || self.tag_view.active
                                || self.rating_view_nav_context_active()
                            {
                                Some(self.folder_nav_history_snapshot())
                            } else {
                                None
                            };
                            if self.favsearch.active {
                                self.favsearch.nav_stack.push(pf.clone());
                            }
                            if self.tag_view.active {
                                self.record_tag_view_nav_open(&pf);
                            }
                            self.record_rating_view_nav_open(&pf);
                            let open_outcome = self
                                .load_folder_or_convert_archive_with_auto_fullscreen(pf, auto_fs);
                            match (open_outcome, search_rollback) {
                                (FolderOpenOutcome::ConversionDialogOpened, Some(snapshot)) => {
                                    self.attach_archive_convert_nav_history_rollback(snapshot);
                                }
                                (FolderOpenOutcome::Ignored, Some(snapshot)) => {
                                    self.restore_folder_nav_history(snapshot);
                                }
                                _ => {}
                            }
                            if self.favsearch.active
                                && matches!(open_outcome, FolderOpenOutcome::Loaded)
                            {
                                self.update_favsearch_address();
                            }
                            if self.tag_view.active
                                && matches!(open_outcome, FolderOpenOutcome::Loaded)
                            {
                                self.update_tag_view_address();
                            }
                        }
                        Some(GridItem::SearchContainer { path, kind, .. }) => {
                            // Ctrl+G 結果ビュー (Aggregated) でコンテナを Enter
                            // → drill-down view に切り替え (v1: 1 階層のみ, docs §10.3)
                            let p = path.clone();
                            let is_zip = matches!(kind, crate::grid_item::SearchContainerKind::Zip);
                            // ★コンテナを開いた時、内部画像が未評価で空表示にならないよう
                            // フィルタを一時解除する (Codex P2)。
                            self.maybe_suppress_rating_filter_for_opened_container_path(&p);
                            self.maybe_suppress_facet_filter_for_opened_container_path(&p);
                            self.drill_into_container(p, is_zip);
                            return None;
                        }
                        // レーティング一覧に復元された ZipDir は zip_nav を持たないので、
                        // 外側 ZIP を開いてから該当 prefix へ入る。
                        Some(GridItem::ZipDir {
                            zip_path,
                            dir_prefix,
                            ..
                        }) if self.items_are_rating_view => {
                            self.open_rating_view_zipdir(zip_path.clone(), dir_prefix.clone());
                        }
                        // ネスト ZIP ツリーの子コンテナへ Enter で降りる (Phase 3)。
                        Some(GridItem::ZipDir { dir_prefix, .. }) => {
                            let dp = dir_prefix.clone();
                            // ★付きの本を絞り込み中に開くと中身が空表示になるのを防ぐ
                            // (Codex P2)。enter 前に抑制を仕込む。
                            self.maybe_suppress_rating_filter_for_opened_zip_book(idx);
                            self.maybe_suppress_facet_filter_for_opened_zip_book(idx);
                            self.zip_nav_enter(&dp);
                        }
                        // ファイル名スタック (v2.0.0): 集約グリッドのセルは上の
                        // stack_try_open_from_grid で処理済み (フラットフルスクリーンへ)。
                        // 非スタックモードでは Stack セルは存在しないので網羅性のため no-op。
                        Some(GridItem::Stack { .. }) => {}
                        None => {}
                    }
                }
            }
        }

        // 検索コンテキスト中はファイルシステム遡りを禁止する:
        // - BS はスタックベースで検索ルートまで戻る (favsearch_back)
        // - Ctrl+↑↓ によるフォルダナビゲーションも無効化
        let in_favsearch = self.favsearch.active;
        let in_tag_view = self.tag_view.active;

        // BS: 親フォルダへ (検索中はスタックを戻る)
        // 既定の Ctrl+BS は上の個別補正解除で消費される。カスタムで同じキーへ
        // 割り当てた場合は競合警告の対象にし、先に消費した処理を優先する。
        let parent_key = self.keymap.consume_action(ctx, KeyAction::GridParentFolder);
        if parent_key {
            // フルスクリーン中の BS はフルスクリーン側ビューポートで処理する (ZIP/PDF ページ
            // なら 1 段戻って L2 ページ一覧)。ここは grid (L1/L2) での BS = 親フォルダへ。
            // Fix-B (ユーザー指摘): ★固定 中の BS は snapshot list view (= snapshot.items を
            // render する状態) に戻る。snapshot 内 child folder に居る場合のみ動作し、既に
            // snapshot root 表示中なら通常の親フォルダ移動を試みる (= load_folder guard で
            // 範囲外なら toast block される)。
            if self.is_snapshot_active() && self.snapshot_return_to_list_view() {
                return None;
            }
            // Ctrl+G 絞り込みビュー中なら 1 段上げる (current_path != container_root) か、
            // Aggregated に戻る。自由な fs 遡行は許さない (docs §10.3)。
            if self.global_search.active {
                if self.global_search.drill.is_some() {
                    self.drill_back_one_level();
                    return None;
                }
                // Aggregated (検索仮想階層の最上位) で BS: no-op。BS は「階層を 1 段
                // 上がる・根で停止・検索モードからは出ない」キー。検索の終了は ESC のみ。
                // ここで return しないと FS 親遡行に流れ、search bar が active のまま
                // saved_folder の親 → ドライブ root の中身が表示される事故になる。
                return None;
            }
            if in_favsearch {
                self.favsearch_back();
                // favsearch_back 内で load_folder 済み。navigate 経路には流さない。
                return None;
            }
            if in_tag_view {
                self.tag_view_back();
                return None;
            }
            if self.rating_view_parent_nav_available() {
                self.rating_view_parent_nav();
                return None;
            }
            if self.local_search_blocks_parent_nav() {
                self.cancel_pending_folder_nav();
                return None;
            }
            // ネスト ZIP ツリー内なら、実フォルダ親へ抜ける前に 1 階層戻る (Phase 3)。
            // ルート (スタック底) では zip_nav_back は false → そのまま親フォルダへ抜ける
            // (= load_folder が zip_nav をクリアして ZIP を出る)。
            #[cfg(windows)]
            let close_detached_after_zip_back =
                self.zip_nav.as_ref().is_some_and(|nav| !nav.at_root())
                    && self.should_preserve_active_detached_image_window_for_main_context_change();
            #[cfg(windows)]
            if close_detached_after_zip_back {
                self.preserve_active_detached_image_window_for_main_context_change();
                self.close_fullscreen();
            }
            if self.zip_nav_back() {
                return None;
            }
            #[cfg(windows)]
            self.close_detached_viewer_for_virtual_page_list_parent_nav();
            return self.resolve_grid_parent_nav();
        }

        let history_shortcut_allowed = !self.global_search.active
            && !self.favsearch.active
            && !self.tag_view.active
            && !self.show_search_bar
            && !self.is_snapshot_active(); // Codex P2-1: ★固定 中は履歴ナビ block
        if history_back_key && history_shortcut_allowed {
            return Some(crate::ui_main::AddressBarNav::HistoryBack);
        }
        if history_forward_key && history_shortcut_allowed {
            return Some(crate::ui_main::AddressBarNav::HistoryForward);
        }

        // Ctrl+↓: 深さ優先で次のフォルダへ（画像なしはスキップ）
        // バックグラウンドスレッドで navigate_folder_with_skip を実行し、
        // 結果は poll_folder_nav で非同期に受信する。
        // 検索コンテキスト中は検索結果内での前後移動に置き換える。
        // Ctrl+G 中は file system 遡行を禁止して Ctrl+G の範囲に閉じる
        // (Aggregated 時は Ctrl+↑↓ は no-op、DrilledInto 時は drill-tree DFS)。
        let in_local_search = self.show_search_bar;
        let in_global_search = self.global_search.active;
        let in_global_search_drilled = in_global_search && self.global_search.drill.is_some();
        if ctrl_down {
            // perf: グリッドの Ctrl+↓ を input イベントとして記録 (fullscreen 側と対称)。
            // これで入力 → DFS → load_folder → 初フレームまでを seq で相関できる。
            self.bump_input_seq("grid_ctrl_nav", Some("forward"));
            // ★固定 中はグリッドでも snapshot 内 container entry を巡回 (= §4.6)。
            // snapshot 内 folder の中に居る場合は次の container へ、snapshot root に
            // 居る場合は最初の container を開く。image-like entry は skip。
            if self.is_snapshot_active() {
                let _ = self.snapshot_navigate_grid(true);
            } else if in_global_search_drilled {
                self.global_search_ctrl_nav(true);
            } else if in_global_search {
                // Aggregated 中は何もしない (fs ツリー遡行はユーザ期待に反する)
            } else if in_local_search {
                // Ctrl+F は現在一覧のフィルタ。フォーカスが外れていても
                // Ctrl+↑↓ でフォルダ横断せず、検索状態を保つ。
                self.cancel_pending_folder_nav();
            } else if in_favsearch {
                self.favsearch_ctrl_nav(true);
            } else if in_tag_view {
                self.cancel_pending_folder_nav();
            } else if self.items_are_subfolder_expansion_view {
                self.cancel_pending_folder_nav();
            } else if self.zip_nav_handle_ctrl_updown(true) {
                // ネスト ZIP 内: ツリーを DFS 前順で次のノードへ (#4 改)。ツリーの端では
                // false が返り、下の effective_folder 分岐で ZIP を抜けて実フォルダ DFS へ。
            } else if self.start_smart_folder_scope_nav(true, false) {
            } else if let Some(cur) = self.effective_folder() {
                self.start_folder_nav(cur, true, FolderNavMode::Grid);
            }
        }

        // Ctrl+↑: 深さ優先で前のフォルダへ（画像なしはスキップ）
        if ctrl_up {
            self.bump_input_seq("grid_ctrl_nav", Some("backward"));
            // ★固定 中は snapshot 内 container entry を逆順に巡回
            if self.is_snapshot_active() {
                let _ = self.snapshot_navigate_grid(false);
            } else if in_global_search_drilled {
                self.global_search_ctrl_nav(false);
            } else if in_global_search {
                // Aggregated 中は何もしない
            } else if in_local_search {
                self.cancel_pending_folder_nav();
            } else if in_favsearch {
                self.favsearch_ctrl_nav(false);
            } else if in_tag_view {
                self.cancel_pending_folder_nav();
            } else if self.items_are_subfolder_expansion_view {
                self.cancel_pending_folder_nav();
            } else if self.zip_nav_handle_ctrl_updown(false) {
                // ネスト ZIP 内: ツリーを DFS 逆前順で前のノードへ (#4 改)。
            } else if self.start_smart_folder_scope_nav(false, false) {
            } else if let Some(cur) = self.effective_folder() {
                self.start_folder_nav(cur, false, FolderNavMode::Grid);
            }
        }

        // Ctrl+PageDown / Ctrl+PageUp: 同じ親を持つ次 / 前の兄弟フォルダへ。
        // PageUp/PageDown 単体は一覧のページ移動なので、Ctrl 付きだけをここで扱う。
        if ctrl_page_down {
            self.bump_input_seq("grid_sibling_nav", Some("forward"));
            // ★固定 中: P2-2 fix で Ctrl+↑↓ と Ctrl+PageUp/Down の意味分岐を統一。
            // Ctrl+PageUp/Down は image-like のみ巡回 (= page 版)、Ctrl+↑↓ は全 entry。
            if self.is_snapshot_active() {
                let _ = self.snapshot_navigate_grid_page(true);
            } else if in_global_search || in_favsearch || in_tag_view {
                // 検索ビューは仮想階層なので、実ファイルシステムの兄弟移動は行わない。
            } else if in_local_search {
                self.cancel_pending_folder_nav();
            } else if self.items_are_subfolder_expansion_view || self.items_are_smart_folder_view {
                self.cancel_pending_folder_nav();
            } else if let Some(cur) = self.effective_folder() {
                self.start_folder_nav(cur, true, FolderNavMode::SiblingGrid);
            }
        }
        if ctrl_page_up {
            self.bump_input_seq("grid_sibling_nav", Some("backward"));
            if self.is_snapshot_active() {
                let _ = self.snapshot_navigate_grid_page(false);
            } else if in_global_search || in_favsearch || in_tag_view {
                // 同上。
            } else if in_local_search {
                self.cancel_pending_folder_nav();
            } else if self.items_are_subfolder_expansion_view || self.items_are_smart_folder_view {
                self.cancel_pending_folder_nav();
            } else if let Some(cur) = self.effective_folder() {
                self.start_folder_nav(cur, false, FolderNavMode::SiblingGrid);
            }
        }

        None
    }

    /// 進行中 / 累積中のフォルダナビゲーションを破棄する。
    ///
    /// Ctrl+↑↓ DFS と folder pane open pre-scan はどちらも「あとからフォルダを開く」
    /// 入力なので、検索モードやフルスクリーン状態などの scope が変わったら
    /// 古い入力を新しい表示状態へ適用しないよう明示的に流す。
    pub(crate) fn cancel_pending_folder_nav(&mut self) {
        if let Some(pending) = self.folder_nav_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        // folder scan pending も bundle-owned。mounted detached からキャンセルすると
        // その detached の image open だけが止まり、unmounted main の request には触れない。
        self.cancel_folder_pane_open();
        self.clear_pending_folder_nav_steps();
        self.release_fs_nav_lock();
    }

    /// Ctrl+↑↓ のフォルダナビゲーションをバックグラウンドスレッドで開始する。
    /// `navigate_folder_with_skip` はフォルダツリーの DFS 走査 + `folder_should_stop`
    /// (`read_dir`) を行うためディスク I/O を伴い、HDD では 20-120ms かかる。
    /// UI スレッドをブロックしないよう、結果は `poll_folder_nav` で非同期に受信する。
    ///
    /// **連打の扱い (Step B アキュームレート)**:
    /// in-flight 中に追加の Ctrl+↑↓ が来たら、旧スレッドをキャンセルせず
    /// `pending_folder_nav_steps` に累積する (forward=+1, backward=-1)。
    /// 現 nav が完了したあと `chain_folder_nav_if_pending` で次のステップを連鎖実行する。
    /// これにより「30Hz 連打で 30 ステップ進める」挙動になり、かつ
    /// 同時並行 DFS のファイルシステム競合を避ける。
    ///
    /// **モードの扱い**:
    /// `mode` は DFS の発火元 (grid / fullscreen / favsearch) を示し、
    /// DFS 完了時に `apply_folder_nav_result` がこの mode を見て後処理を分岐する。
    /// in-flight 中に異なるモードで start_folder_nav が呼ばれた場合は、
    /// 旧モードをキャンセルして新モードで仕切り直す (モード混在を避ける)。
    pub(crate) fn start_folder_nav(
        &mut self,
        current: PathBuf,
        forward: bool,
        mode: FolderNavMode,
    ) {
        if let Some(pending) = self.folder_nav_pending.as_ref() {
            if folder_nav_mode_same_kind(&pending.mode, &mode) {
                // 既に同一モードで nav 進行中: 連打を累積するだけ
                let delta: i32 = if forward { 1 } else { -1 };
                self.pending_folder_nav_steps = (self.pending_folder_nav_steps + delta)
                    .clamp(-MAX_PENDING_NAV, MAX_PENDING_NAV);
                return;
            }
            // モードが変わった (例: fullscreen → grid) → 旧 DFS をキャンセル
            pending.cancel.store(true, Ordering::Relaxed);
            self.folder_nav_pending = None;
        }
        // 新しい nav 列開始: アキュームレータをリセットしてから spawn
        self.pending_folder_nav_steps = 0;
        self.pending_folder_nav_mode = mode.clone();
        self.spawn_folder_nav(current, forward, mode);
    }

    /// フルスクリーンの表示待ち lock 中に、既に進行中の DFS が所有する mode を返す。
    ///
    /// 入力ハンドラはこの snapshot を `start_folder_nav` へ戻すだけにし、検索・ZIP・
    /// detached など副作用を持つ context routing をもう一度実行しない。
    pub(crate) fn inflight_fullscreen_folder_nav_mode(
        &self,
        sibling: bool,
    ) -> Option<FolderNavMode> {
        let mode = self.folder_nav_pending.as_ref()?.mode.clone();
        let accepted = if sibling {
            matches!(&mode, FolderNavMode::SiblingFullscreen)
        } else {
            matches!(
                &mode,
                FolderNavMode::Fullscreen
                    | FolderNavMode::Favsearch {
                        fullscreen: true,
                        ..
                    }
                    | FolderNavMode::SmartFolder {
                        fullscreen: true,
                        ..
                    }
            )
        };
        accepted.then_some(mode)
    }

    /// 内部ヘルパー: フォルダ移動ワーカースレッドを spawn する。
    /// `start_folder_nav` (ユーザー押下) と `chain_folder_nav_if_pending` (累積消化) の
    /// 両方から呼ばれる。cancel トークンは DFS / 兄弟移動のどちらにも渡し、
    /// 次のユーザー操作で即座に古い探索を畳めるようにする。
    fn spawn_folder_nav(&mut self, current: PathBuf, forward: bool, mode: FolderNavMode) {
        let skip_limit = self.settings.folder_skip_limit;
        // Phase 4 (spec §8): `folder_tree::*_dfs` は内部で `Settings::load()` を呼ばず
        // 呼び出し側から `FolderTreeOptions` を受ける形に変更済み。ここで一度だけ
        // 値をスナップショットして worker thread に move する。
        let detached_physical = self.navigation_scope.is_detached_physical();
        let mut tree_opts = crate::folder_tree::FolderTreeOptions::from_settings(&self.settings);
        if detached_physical {
            // A detached physical viewer must not open a conversion dialog owned
            // by the main window. Native still containers remain eligible.
            tree_opts.include_convertible_archives = false;
        }
        let show_hidden_files = self.settings.show_hidden_files;
        let (tx, rx) = mpsc::channel();
        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_w = Arc::clone(&cancel);

        // perf: DFS のユーザー入力相関 seq を thread に渡す。
        // chain_folder_nav_if_pending 経由の連鎖 DFS でも同じ seq が伝搬するので、
        // 1 回のキー押下で起きた DFS バーストを 1 つの seq でまとめて追える。
        let perf_seq = self.input_seq;
        let perf_mode = mode.perf_tag();
        let sibling_only = mode.sibling_only();
        let smart_state = match &mode {
            FolderNavMode::SmartFolder { state, .. } => Some(state.clone()),
            _ => None,
        };
        // Detached physical navigation is a still-viewer operation. It shares
        // SlideshowNext's still predicate so media-only folders never promote
        // the independent still window into an unowned media session.
        let still_only = matches!(mode, FolderNavMode::SlideshowNext) || detached_physical;
        let start_path_disp = if crate::perf::is_enabled() {
            current.display().to_string()
        } else {
            String::new()
        };

        std::thread::spawn(move || {
            let t0 = std::time::Instant::now();
            if crate::perf::is_enabled() {
                crate::perf::event(
                    "nav",
                    "dfs_begin",
                    None,
                    perf_seq,
                    &[
                        ("forward", serde_json::Value::from(forward)),
                        ("mode", serde_json::Value::from(perf_mode)),
                        ("start", serde_json::Value::from(start_path_disp.clone())),
                    ],
                );
            }
            let outcome = if let Some(state) = smart_state.as_ref() {
                navigate_smart_folder_scope(
                    state, &current, forward, tree_opts, skip_limit, &cancel_w,
                )
            } else if sibling_only {
                if cancel_w.load(Ordering::Relaxed) {
                    None
                } else {
                    let path = if forward {
                        next_sibling_folder(&current, tree_opts)
                    } else {
                        prev_sibling_folder(&current, tree_opts)
                    };
                    path.map(|path| FolderNavOutcome {
                        hit_image_folder: if still_only {
                            crate::folder_tree::folder_has_still_image_with_options(
                                &path,
                                Some(&cancel_w),
                                tree_opts,
                            )
                        } else {
                            crate::folder_tree::folder_should_stop_with_options(
                                &path,
                                Some(&cancel_w),
                                tree_opts,
                            )
                        },
                        path,
                    })
                }
            } else if forward {
                navigate_folder_with_skip(
                    &current,
                    |p| next_folder_dfs(p, tree_opts),
                    |path, cancel| {
                        if still_only {
                            crate::folder_tree::folder_has_still_image_with_options(
                                path, cancel, tree_opts,
                            )
                        } else {
                            crate::folder_tree::folder_should_stop_with_options(
                                path, cancel, tree_opts,
                            )
                        }
                    },
                    skip_limit,
                    Some(&cancel_w),
                )
            } else {
                navigate_folder_with_skip(
                    &current,
                    |p| prev_folder_dfs(p, tree_opts),
                    |path, cancel| {
                        if still_only {
                            crate::folder_tree::folder_has_still_image_with_options(
                                path, cancel, tree_opts,
                            )
                        } else {
                            crate::folder_tree::folder_should_stop_with_options(
                                path, cancel, tree_opts,
                            )
                        }
                    },
                    skip_limit,
                    Some(&cancel_w),
                )
            };
            let dfs_ms = t0.elapsed().as_secs_f64() * 1000.0;

            // DFS スレッドで事前スキャンまで済ませる: ヒットした先が通常ディレクトリなら、
            // ここで `read_dir` + メタデータ取得を終わらせて UI スレッドの lf_scan
            // (HDD で 100-180ms 級) を除去する。ZIP/PDF ファイルは専用ローダーが
            // 別経路で処理するのでここではスキャンしない。
            let scanned = if cancel_w.load(Ordering::Relaxed) {
                FolderNavScanResult::NotNeeded
            } else if let Some(o) = outcome.as_ref() {
                if o.path.is_dir() {
                    let scan_t0 = std::time::Instant::now();
                    let scan = scan_directory_with_convertible_archives(
                        &o.path,
                        tree_opts.include_convertible_archives,
                        show_hidden_files,
                    );
                    if crate::perf::is_enabled() {
                        let (folders, media, failed) = match scan.as_ref() {
                            Ok(scan) => (scan.folders.len(), scan.all_media.len(), false),
                            Err(_) => (0, 0, true),
                        };
                        crate::perf::event(
                            "nav",
                            "dfs_scan",
                            None,
                            perf_seq,
                            &[
                                (
                                    "ms",
                                    serde_json::Value::from(
                                        scan_t0.elapsed().as_secs_f64() * 1000.0,
                                    ),
                                ),
                                ("folders", serde_json::Value::from(folders)),
                                ("media", serde_json::Value::from(media)),
                                ("failed", serde_json::Value::from(failed)),
                            ],
                        );
                    }
                    match scan {
                        Ok(scan) => FolderNavScanResult::Ready(scan),
                        Err(error) => FolderNavScanResult::Failed(error.to_string()),
                    }
                } else {
                    FolderNavScanResult::NotNeeded
                }
            } else {
                FolderNavScanResult::NotNeeded
            };

            let cancelled = cancel_w.load(Ordering::Relaxed);
            if crate::perf::is_enabled() {
                let hit = outcome
                    .as_ref()
                    .map(|o| o.path.display().to_string())
                    .unwrap_or_else(|| "-".to_string());
                let hit_image_folder = outcome
                    .as_ref()
                    .map(|o| o.hit_image_folder)
                    .unwrap_or(false);
                crate::perf::event(
                    "nav",
                    "dfs_end",
                    None,
                    perf_seq,
                    &[
                        ("ms", serde_json::Value::from(dfs_ms)),
                        (
                            "total_ms",
                            serde_json::Value::from(t0.elapsed().as_secs_f64() * 1000.0),
                        ),
                        ("forward", serde_json::Value::from(forward)),
                        ("mode", serde_json::Value::from(perf_mode)),
                        ("cancelled", serde_json::Value::from(cancelled)),
                        ("found", serde_json::Value::from(outcome.is_some())),
                        (
                            "hit_image_folder",
                            serde_json::Value::from(hit_image_folder),
                        ),
                        ("hit_path", serde_json::Value::from(hit)),
                        (
                            "pre_scanned",
                            serde_json::Value::from(matches!(
                                &scanned,
                                FolderNavScanResult::Ready(_)
                            )),
                        ),
                    ],
                );
            }
            if !cancelled {
                let _ = tx.send(FolderNavThreadResult { outcome, scanned });
            }
        });

        self.folder_nav_pending = Some(FolderNavPending {
            cancel,
            rx,
            forward,
            mode,
        });
    }

    /// 直前の folder_nav 完了後に呼ぶ。累積ステップが残っていれば次の DFS を連鎖実行。
    /// モードと残数は、完了した `FolderNavResult` が所有していた値を引き継ぐ。
    fn chain_folder_nav_if_pending(&mut self, mut queued_steps: i32, mut mode: FolderNavMode) {
        if queued_steps == 0 {
            return;
        }
        let forward = queued_steps > 0;
        // 1 ステップ消費
        queued_steps += if forward { -1 } else { 1 };
        // mode に応じて「次のステップの起点」は変わる:
        //   Grid / Fullscreen → effective_folder() (変換キャッシュに着地した直後は
        //     current_folder がキャッシュ ZIP を指すため、ユーザー視点の元アーカイブを
        //     起点にしないと次の累積ステップが archive_cache 側へ逸れる、Codex P2)
        //   Favsearch        → favsearch.nav_stack.last() (= 現在位置)
        let current = match mode.clone() {
            FolderNavMode::Favsearch { .. } => self.favsearch.nav_stack.last().cloned(),
            FolderNavMode::SmartFolder { fullscreen, .. } => {
                let Some(state) = self.top_level_grid_view.smart_folder().cloned() else {
                    self.clear_pending_folder_nav_steps();
                    self.release_fs_nav_lock();
                    return;
                };
                let current = state
                    .scoped_current()
                    .map(Path::to_path_buf)
                    .unwrap_or_else(|| {
                        smart_folder::smart_folder_synthetic_path(state.definition_id)
                    });
                mode = FolderNavMode::SmartFolder { state, fullscreen };
                Some(current)
            }
            _ => self.effective_folder(),
        };
        if let Some(cur) = current {
            // fullscreen burst の各 folder load は generation を進める。次の DFS が完了する
            // 前に中間ページが表示確定しても holdover を解放しないよう、同じ lock/texture
            // を次段の generation へ引き継ぐ。lock の gate 自体は変えない。
            if self.fs_nav_locked_gen.is_some()
                && matches!(
                    &mode,
                    FolderNavMode::Fullscreen
                        | FolderNavMode::SiblingFullscreen
                        | FolderNavMode::SlideshowNext
                        | FolderNavMode::Favsearch {
                            fullscreen: true,
                            ..
                        }
                        | FolderNavMode::SmartFolder {
                            fullscreen: true,
                            ..
                        }
                )
            {
                self.fs_nav_locked_gen = Some(self.items_generation);
            }
            // `start_loading_items` は無関係な folder change の burst を流すため App 側を
            // clear する。完了した FolderNavResult が所有していた残数だけを、次の DFS を
            // spawn する直前に戻すことで、その load 自身の burst だけを継続する。
            self.pending_folder_nav_steps = queued_steps;
            self.pending_folder_nav_mode = mode.clone();
            self.spawn_folder_nav(cur, forward, mode);
        }
    }

    pub(crate) fn consume_context_shortcuts_help_key(&self, ctx: &egui::Context) -> bool {
        self.keymap.consume_context_shortcuts_help_action(ctx)
    }

    /// フォルダツリーペインのクリック/Enter ナビを worker scan 経由で開始する。
    /// UI スレッドで `scan_directory` を直接走らせず、worker で read_dir + メタ取得を
    /// 済ませる。完了結果は `poll_folder_pane_open` で回収し、通常 nav と同じ
    /// 優先順位で裁定してから開く。対象は実ディレクトリ前提
    /// (フォルダペインは実フォルダのみ表示する)。
    pub(crate) fn start_folder_pane_open(&mut self, path: PathBuf) {
        self.start_folder_open_scan(path, FolderOpenScanPurpose::PaneNavigation);
    }

    #[cfg(windows)]
    fn start_grid_folder_candidate_open(&mut self, path: PathBuf) {
        self.start_folder_open_scan(path, FolderOpenScanPurpose::GridFolderCandidate);
    }

    fn start_detached_image_folder_open(&mut self, image_path: PathBuf) -> bool {
        let Some(parent) = image_path.parent().map(Path::to_path_buf) else {
            return false;
        };
        self.start_folder_open_scan(parent, FolderOpenScanPurpose::DetachedImage { image_path });
        true
    }

    fn start_detached_folder_open(&mut self, folder_path: PathBuf) {
        self.start_folder_open_scan(folder_path, FolderOpenScanPurpose::DetachedFolder);
    }

    fn start_folder_open_scan(&mut self, path: PathBuf, purpose: FolderOpenScanPurpose) {
        // 旧 pending を破棄 (連打で最後のクリックだけ生かす)。
        if let Some(prev) = self.folder_pane_open_pending.take() {
            prev.cancel.store(true, Ordering::Relaxed);
        }
        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_w = Arc::clone(&cancel);
        let (tx, rx) = mpsc::channel();
        let scan_path = path.clone();
        let include_convertible_archives =
            !self.settings.archive_file_handling_ignores_convertible();
        let show_hidden_files = self.settings.show_hidden_files;
        std::thread::spawn(move || {
            if cancel_w.load(Ordering::Relaxed) {
                return;
            }
            let scan = scan_directory_with_convertible_archives(
                &scan_path,
                include_convertible_archives,
                show_hidden_files,
            );
            if !cancel_w.load(Ordering::Relaxed) {
                let _ = tx.send(scan);
            }
        });
        self.folder_pane_open_pending = Some(FolderPaneOpenPending {
            path,
            cancel,
            rx,
            purpose,
        });
    }

    /// 進行中のフォルダペイン open scan をキャンセルして破棄する。
    /// 別の nav 源 (アドレスバー / Ctrl+↑↓ / グリッド) が勝ったときに呼ぶ。
    fn cancel_folder_pane_open(&mut self) {
        if let Some(prev) = self.folder_pane_open_pending.take() {
            prev.cancel.store(true, Ordering::Relaxed);
        }
    }

    /// `start_folder_pane_open` の worker 完了を毎フレーム回収する。
    ///
    /// 完了してもここでは直接 load せず、通常 nav 優先順位の候補として返す。
    /// 採用された場合だけ pre-scan 付きで開くことで、UI スレッドの read_dir を省く。
    fn poll_folder_pane_open(&mut self, ctx: &egui::Context) -> Option<FolderPaneOpenReady> {
        let Some(pending) = self.folder_pane_open_pending.as_ref() else {
            return None;
        };
        match pending.rx.try_recv() {
            Ok(scan) => {
                let pending = self.folder_pane_open_pending.take().unwrap();
                Some(FolderPaneOpenReady {
                    path: pending.path,
                    scan,
                    purpose: pending.purpose,
                })
            }
            Err(mpsc::TryRecvError::Empty) => {
                ctx.request_repaint();
                None
            }
            Err(mpsc::TryRecvError::Disconnected) => {
                // worker が cancel で send せず終了 (= 自分でキャンセルしたケースのみ)。破棄。
                self.folder_pane_open_pending = None;
                None
            }
        }
    }

    /// Resolve a completed main-owned folder scan without conflating "requested as a book"
    /// with "confirmed to be an image book".
    ///
    /// `Some` continues through ordinary main navigation. `None` means the request was consumed
    /// by a detached open, rejected as cross-context state, or failed.
    #[cfg(windows)]
    fn resolve_main_folder_open_ready(
        &mut self,
        ctx: &egui::Context,
        ready: FolderPaneOpenReady,
    ) -> Option<(PathBuf, ScannedDir)> {
        let scan = match ready.scan {
            Ok(scan) => scan,
            Err(error) => {
                crate::logger::log(format!(
                    "folder open scan failed path={} purpose={} error={error}",
                    ready.path.display(),
                    match ready.purpose {
                        FolderOpenScanPurpose::PaneNavigation => "pane-navigation",
                        FolderOpenScanPurpose::GridFolderCandidate => "grid-folder-candidate",
                        FolderOpenScanPurpose::DetachedFolder => "detached-folder",
                        FolderOpenScanPurpose::DetachedImage { .. } => "detached-image",
                    }
                ));
                self.show_feedback_toast("フォルダを読み取れませんでした".to_string());
                return None;
            }
        };

        match ready.purpose {
            FolderOpenScanPurpose::PaneNavigation => Some((ready.path, scan)),
            FolderOpenScanPurpose::GridFolderCandidate => {
                let image_book = self.settings.auto_fullscreen_image_folders_enabled()
                    && self.scanned_folder_is_image_book(&ready.path, &scan);
                let should_detach =
                    self.settings.detached_viewer_open_images_in_window && image_book;
                if !should_detach {
                    // Rejoin the exact main navigation pipeline used by Enter/double-click/
                    // gamepad. This restores history/search/smart-folder behavior for mixed
                    // folders instead of terminating an unmaterialized detached context.
                    if let Some(idx) = self.items.iter().position(|item| {
                        matches!(
                            item,
                            GridItem::Folder(path)
                                if crate::folder_tree::path_eq(path, &ready.path)
                        )
                    }) {
                        self.maybe_suppress_rating_filter_for_opened_container(idx);
                        self.maybe_suppress_facet_filter_for_opened_container(idx);
                    }
                    self.begin_smart_folder_drill(&ready.path);
                    // If the user changed from always-new to full-feature mode during a slow
                    // scan, preserve the current full-feature auto-open policy.
                    self.pending_auto_fs_open = image_book;
                    return Some((ready.path, scan));
                }

                let base_placement = self.active_detached_viewer_current_placement();
                let had_active_detached = self.active_detached_viewer_context.is_some()
                    || self.viewer_session_is_detached();
                if !self.park_and_close_current_active_detached_viewer(ctx) {
                    return None;
                }
                let placement_seed = had_active_detached
                    .then(|| self.offset_detached_image_window_placement(base_placement));
                self.start_active_detached_book_context_from_scanned_folder(
                    ready.path,
                    scan,
                    ctx,
                    placement_seed,
                );
                None
            }
            FolderOpenScanPurpose::DetachedFolder | FolderOpenScanPurpose::DetachedImage { .. } => {
                crate::logger::log(format!(
                    "main folder scan rejected detached-owned result path={}",
                    ready.path.display()
                ));
                None
            }
        }
    }

    /// detached の通常画像 open 用 folder scan を、その detached bundle 内だけで完了する。
    ///
    /// `FolderOpenScanPurpose::DetachedImage` が対象画像を request と一体で所有するため、
    /// scan 待ちの間に main の検索結果・選択・並び順が変わっても参照しない。
    #[cfg(windows)]
    fn poll_detached_physical_folder_open(
        &mut self,
        ctx: &egui::Context,
    ) -> DetachedPhysicalFolderOpenPoll {
        let Some(ready) = self.poll_folder_pane_open(ctx) else {
            return DetachedPhysicalFolderOpenPoll::Waiting;
        };
        let scan = match ready.scan {
            Ok(scan) => scan,
            Err(error) => {
                crate::logger::log(format!(
                    "detached folder scan failed path={} error={error}",
                    ready.path.display()
                ));
                return DetachedPhysicalFolderOpenPoll::Failed;
            }
        };
        match ready.purpose {
            FolderOpenScanPurpose::DetachedImage { image_path } => {
                self.with_detached_viewer_main_history_suppressed(|app| {
                    app.load_folder_with_scan(ready.path, Some(scan));
                });
                // 明示された画像 request は厳密に解決する。snapshot / folder-nav 用 helper は
                // target miss 時に先頭へ fallback するため、ここでは使用しない。Windows の
                // filesystem identity に合わせ、path の大文字小文字差は path_eq で吸収する。
                let Some(image_idx) = self.items.iter().position(|item| {
                    matches!(
                        item,
                        GridItem::Image(candidate)
                            if crate::folder_tree::path_eq(candidate, &image_path)
                    )
                }) else {
                    self.log_detached_image_window_debug(format!(
                        "detached_image_open_target_missing path={} folder={}",
                        image_path.display(),
                        self.current_folder.as_deref().map_or_else(
                            || "<none>".to_string(),
                            |path| path.display().to_string()
                        )
                    ));
                    return DetachedPhysicalFolderOpenPoll::Failed;
                };

                // parked still の再開と同じく、既に割り当てた detached window_id を
                // 保ったまま物理一覧上の対象 index を開く。
                self.detached_viewer_independent_active = true;
                self.detached_viewer_open_next_still_detached_once = true;
                self.fs_open_intent_from_grid = true;
                self.open_fullscreen(image_idx, crate::app::HistoryTrigger::UserChosen);
                self.selected = Some(image_idx);
                self.scroll_to_selected = true;
                self.update_last_selected_image();
                DetachedPhysicalFolderOpenPoll::Applied
            }
            FolderOpenScanPurpose::DetachedFolder => {
                self.with_detached_viewer_main_history_suppressed(|app| {
                    app.load_folder_with_scan(ready.path, Some(scan));
                });
                DetachedPhysicalFolderOpenPoll::Applied
            }
            FolderOpenScanPurpose::PaneNavigation => {
                // active detached viewport はフォルダペインを持たないため通常は到達しない。
                // 将来ペインを共有しても結果を捨てず、その bundle の物理ナビとして適用する。
                self.load_folder_with_scan(ready.path, Some(scan));
                DetachedPhysicalFolderOpenPoll::Applied
            }
            FolderOpenScanPurpose::GridFolderCandidate => {
                // Candidate classification is owned by main. Reaching a detached bundle would
                // cross the ownership boundary, so never materialize it here.
                crate::logger::log(format!(
                    "detached folder scan rejected main-owned grid candidate path={}",
                    ready.path.display()
                ));
                DetachedPhysicalFolderOpenPoll::Failed
            }
        }
    }

    fn poll_folder_nav(&mut self) -> Option<FolderNavResult> {
        let pending = self.folder_nav_pending.as_ref()?;
        match pending.rx.try_recv() {
            Ok(thread_result) => {
                let pending = self.folder_nav_pending.take().unwrap();
                let queued_steps = std::mem::take(&mut self.pending_folder_nav_steps);
                self.pending_folder_nav_mode = FolderNavMode::Grid;
                let (path, hit_image_folder) = match thread_result.outcome {
                    Some(o) => (Some(o.path), o.hit_image_folder),
                    None => (None, false),
                };
                Some(FolderNavResult {
                    path,
                    hit_image_folder,
                    forward: pending.forward,
                    mode: pending.mode,
                    queued_steps,
                    scanned: thread_result.scanned,
                })
            }
            Err(mpsc::TryRecvError::Empty) => None,
            Err(mpsc::TryRecvError::Disconnected) => {
                let pending = self.folder_nav_pending.take().unwrap();
                let queued_steps = std::mem::take(&mut self.pending_folder_nav_steps);
                self.pending_folder_nav_mode = FolderNavMode::Grid;
                Some(FolderNavResult {
                    path: None,
                    hit_image_folder: false,
                    forward: pending.forward,
                    mode: pending.mode,
                    queued_steps,
                    scanned: FolderNavScanResult::NotNeeded,
                })
            }
        }
    }

    pub(crate) fn should_auto_fullscreen_grid_container(&self, idx: usize) -> bool {
        match self.items.get(idx) {
            Some(GridItem::ZipFile(_)) | Some(GridItem::PdfFile(_)) => {
                self.settings.effective_auto_fullscreen_zip_pdf()
            }
            Some(GridItem::Folder(_)) => self.settings.auto_fullscreen_image_folders_enabled(),
            _ => false,
        }
    }

    pub(crate) fn open_selected_grid_container_with_mode(
        &mut self,
        ctx: &egui::Context,
        mode: GridContainerOpenMode,
        source: &'static str,
    ) -> Option<crate::ui_main::AddressBarNav> {
        let Some(idx) = self.selected else {
            self.show_feedback_toast("ZIP/PDF/対応アーカイブを選択してください".into());
            return None;
        };
        self.open_grid_container_with_mode(ctx, idx, mode, source)
    }

    /// 明示的な「ページを開く / 一覧を開く」は、メイン一覧をそのページ一覧へ
    /// 遷移させるフル機能ウィンドウ用コマンド。複数ウィンドウモードでは本を
    /// independent viewer に直開きする契約なので、入口で副作用なしに無効化する。
    pub(crate) fn explicit_grid_container_open_disabled_reason(&self) -> Option<&'static str> {
        self.settings
            .detached_viewer_open_images_in_window
            .then_some("「ページを開く」「一覧を開く」はフル機能ウィンドウで利用できます")
    }

    pub(crate) fn open_grid_container_with_mode(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
        mode: GridContainerOpenMode,
        source: &'static str,
    ) -> Option<crate::ui_main::AddressBarNav> {
        if let Some(reason) = self.explicit_grid_container_open_disabled_reason() {
            crate::logger::log(format!(
                "[input-nav] source={source} ignored explicit container open mode={mode:?} in multi-window mode"
            ));
            self.show_feedback_toast_on(reason.to_string(), ActionSurface::MainWindow);
            return None;
        }
        let Some(item) = self.items.get(idx).cloned() else {
            self.show_feedback_toast("ZIP/PDF/対応アーカイブを選択してください".into());
            return None;
        };
        if !matches!(
            item,
            GridItem::ZipFile(_) | GridItem::PdfFile(_) | GridItem::ConvertibleArchive { .. }
        ) {
            self.show_feedback_toast("ZIP/PDF/対応アーカイブを選択してください".into());
            return None;
        }
        if !self.guard_reading_history_open(idx) {
            return None;
        }
        self.note_reading_history_open(idx);

        let auto_fs = mode.auto_fullscreen();
        match item {
            GridItem::ZipFile(p) | GridItem::PdfFile(p) => {
                #[cfg(windows)]
                if self.open_grid_container_in_detached_book_context_with_auto_fullscreen(
                    ctx, idx, auto_fs,
                ) {
                    return None;
                }
                #[cfg(windows)]
                if auto_fs && !self.park_active_detached_context_for_new_grid_open(ctx, idx) {
                    return None;
                }
                self.pending_auto_fs_open = auto_fs;
                self.maybe_suppress_rating_filter_for_opened_container(idx);
                self.maybe_suppress_facet_filter_for_opened_container(idx);
                self.record_rating_view_nav_open(&p);
                self.begin_smart_folder_drill(&p);
                Some(crate::ui_main::AddressBarNav::Direct(p))
            }
            GridItem::ConvertibleArchive { path, .. } => {
                self.begin_smart_folder_drill(&path);
                self.maybe_suppress_rating_filter_for_opened_container(idx);
                self.maybe_suppress_facet_filter_for_opened_container(idx);
                let search_rollback = if self.favsearch.active
                    || self.tag_view.active
                    || self.rating_view_nav_context_active()
                {
                    Some(self.folder_nav_history_snapshot())
                } else {
                    None
                };
                if self.favsearch.active {
                    self.favsearch.nav_stack.push(path.clone());
                }
                if self.tag_view.active {
                    self.record_tag_view_nav_open(&path);
                }
                self.record_rating_view_nav_open(&path);
                let open_outcome =
                    self.load_folder_or_convert_archive_with_auto_fullscreen(path, auto_fs);
                match (open_outcome, search_rollback) {
                    (FolderOpenOutcome::ConversionDialogOpened, Some(snapshot)) => {
                        self.attach_archive_convert_nav_history_rollback(snapshot);
                    }
                    (FolderOpenOutcome::Ignored, Some(snapshot)) => {
                        self.restore_folder_nav_history(snapshot);
                    }
                    _ => {}
                }
                if self.favsearch.active && matches!(open_outcome, FolderOpenOutcome::Loaded) {
                    self.update_favsearch_address();
                }
                if self.tag_view.active && matches!(open_outcome, FolderOpenOutcome::Loaded) {
                    self.update_tag_view_address();
                }
                None
            }
            _ => unreachable!("explicit container mode is gated above"),
        }
    }

    fn grid_items_are_image_only_folder_pages(items: &[GridItem]) -> bool {
        !items.is_empty() && items.iter().all(|item| matches!(item, GridItem::Image(_)))
    }

    /// Classify a completed physical directory scan with the same boundary used by
    /// `load_folder_with_scan_claimed`.
    ///
    /// Unsupported files are absent from `ScannedDir` and therefore retain the historical
    /// behavior. Recognized child containers, video, or audio make an ordinary folder mixed.
    /// A direct compiled-book folder intentionally ignores non-image entries during load, so
    /// the classifier mirrors that exception as well.
    fn scanned_folder_is_image_book(&self, path: &Path, scan: &ScannedDir) -> bool {
        if crate::books::is_direct_book_folder(&self.book_root_path(), path) {
            return scan
                .all_media
                .iter()
                .any(|(_, kind, _, _)| *kind == crate::app::folder_scan::ScanMediaKind::Image);
        }
        crate::app::folder_scan::is_image_only_book_contents(
            !scan.folders.is_empty(),
            &scan.all_media,
        )
    }

    fn items_are_image_only_folder_pages(&self) -> bool {
        Self::grid_items_are_image_only_folder_pages(&self.items)
    }

    /// ZIP/PDF コンテナ内、または opt-in の画像のみ通常フォルダ内のフルスクリーンで、
    /// 「ページを直接開く」設定の退出ルーティング
    /// (Esc/Enter/右クリック→親一覧 / Backspace→ページ一覧) を使うか判定する。
    ///
    /// 検索 (Ctrl+S / Ctrl+G) 中は、Esc が検索を抜けて実親フォルダへ飛ぶ想定外挙動を
    /// 避けるため適用しない。
    pub(crate) fn auto_open_for_current_container(&self) -> bool {
        if !self.settings.effective_auto_fullscreen_zip_pdf()
            || self.global_search.active
            || self.favsearch.active
            || self.tag_view.active
        {
            return false;
        }
        let Some(current_folder) = self.current_folder.as_deref() else {
            return false;
        };
        if crate::folder_tree::is_open_as_container(current_folder) {
            return true;
        }
        self.settings.auto_fullscreen_image_folders_enabled()
            && !is_synthetic_view_path(current_folder)
            && self.items_are_image_only_folder_pages()
    }

    pub(crate) fn reopen_fullscreen_after_folder_nav_load(
        &mut self,
        ctx: &egui::Context,
        restore_video_tile: bool,
        resume_slideshow: bool,
        history_trigger: HistoryTrigger,
    ) -> &'static str {
        // フォルダナビ経路は特定 leaf を持たない (= target: None)。先頭着地。
        // 退出ルーティング (Esc→L1 / BS→L2) は現在のコンテナと設定で判定するので
        // ここでフラグを立てる必要はない。
        if self.pdf_enumerate_pending.is_some() || self.zip_enumerate_pending.is_some() {
            self.fs_nav_after_pdf_enumerate = Some(DeferredFsReopen {
                history_trigger,
                resume_slideshow,
                target: DeferredFsTarget::None,
                // 「ZIP/PDF × Ctrl+↑↓ 移動」: 続きから / 先頭から を設定で切替。
                resume_to_last_page: self.settings.book_nav_resume.resumes(),
                from_explicit_open: false,
                preserve_after_password_prompt: false,
            });
            return "enumerate_defer";
        }
        // SlideshowNext と切り離し静止画ビューアの物理順ナビは、動画を開かず
        // 静止画のみに着地する。後者は移動先フォルダに動画が先に並んでいても
        // detached still session を media session へ昇格させない。
        let include_video = !resume_slideshow && !self.navigation_scope.is_detached_physical();
        let target_idx = self.find_fullscreen_nav_target_filtered(include_video);
        if self.pdf_enumerate_pending.is_some() || self.zip_enumerate_pending.is_some() {
            // find_fullscreen_nav_target_filtered が loose 画像なしフォルダで先頭 ZIP/PDF を
            // 仮想展開した場合もここに来る (current_folder が ZIP/PDF になっている)。
            self.fs_nav_after_pdf_enumerate = Some(DeferredFsReopen {
                history_trigger,
                resume_slideshow,
                target: DeferredFsTarget::None,
                // 「ZIP/PDF × Ctrl+↑↓ 移動」: 続きから / 先頭から を設定で切替。
                resume_to_last_page: self.settings.book_nav_resume.resumes(),
                from_explicit_open: false,
                preserve_after_password_prompt: false,
            });
            return "enumerate_defer";
        }
        if let Some(new_idx) = target_idx {
            #[cfg(windows)]
            let target_is_video = matches!(self.items.get(new_idx), Some(GridItem::Video(_)));
            #[cfg(not(windows))]
            let _ = restore_video_tile;

            self.open_fullscreen(new_idx, history_trigger);
            self.selected = Some(new_idx);
            self.scroll_to_selected = true;
            self.update_last_selected_image();

            // スライドショー NextFolder の着地: 静止画を開けたのでスライドショーを再開。
            if resume_slideshow {
                self.slideshow_playing = true;
                self.schedule_next_slideshow_from_now();
            }

            #[cfg(windows)]
            if restore_video_tile {
                if target_is_video {
                    self.video_tile_mode_active = true;
                    self.video_tile_reopen_pending = true;
                    self.video_tile_reopen_deadline =
                        Some(std::time::Instant::now() + std::time::Duration::from_secs(3));
                    ctx.request_repaint();
                } else {
                    self.video_tile_mode_active = false;
                    self.video_tile_reopen_pending = false;
                    self.video_tile_reopen_deadline = None;
                }
            }
        } else {
            // navigate_folder_with_skip は画像ありフォルダを返す前提だが、
            // レーティングフィルタ等で visible_indices が空の場合はここに来る。
            // (SlideshowNext で静止画 target が無い場合もここ。スライドショーは
            // close_fullscreen で既に false なので再開しないだけでよい。)
            // fullscreen は close 済みなので、メインビューポートに
            // キーボードフォーカスを戻す (旧同期実装と同じ挙動)。
            if !self.navigation_scope.is_detached_physical() {
                ctx.send_viewport_cmd(egui::ViewportCommand::Focus);
            }
            // フルスクリーン再オープン無しなら nav ロックを使う相手がいないので
            // 明示 release (Codex P1)。次の Ctrl+↑↓ がブロックされない。
            self.release_fs_nav_lock();
        }
        "done"
    }

    /// DFS 完了時の後処理。モードに応じて load_folder / open_fullscreen /
    /// favsearch の stack push や sibling fallback を使い分ける。
    fn apply_folder_nav_result(&mut self, ctx: &egui::Context, result: FolderNavResult) {
        // perf: DFS 結果を UI スレッドで適用する区間 (close_fullscreen + load_folder +
        // open_fullscreen 等) の wall time を計測する。Ctrl+↑↓ 連打中に UI が詰まる
        // 原因がここに集まるため、ms を必ず記録する。
        let apply_t0 = std::time::Instant::now();
        let apply_seq = self.input_seq;
        let apply_mode_tag = result.mode.perf_tag();
        let continuation_mode = result.mode.clone();
        let history_trigger = result.mode.history_trigger();
        let queued_steps = result.queued_steps;
        let mut continue_burst = true;
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "apply_begin",
                None,
                apply_seq,
                &[
                    ("forward", serde_json::Value::from(result.forward)),
                    ("mode", serde_json::Value::from(apply_mode_tag)),
                    ("found", serde_json::Value::from(result.path.is_some())),
                    (
                        "hit_image_folder",
                        serde_json::Value::from(result.hit_image_folder),
                    ),
                ],
            );
        }
        // 内部関数として展開して、全 early-return 前に emit_end を呼ぶ。
        let emit_end =
            |t0: std::time::Instant, seq: u64, mode: &'static str, reason: &'static str| {
                if crate::perf::is_enabled() {
                    crate::perf::event(
                        "nav",
                        "apply_end",
                        None,
                        seq,
                        &[
                            (
                                "ms",
                                serde_json::Value::from(t0.elapsed().as_secs_f64() * 1000.0),
                            ),
                            ("mode", serde_json::Value::from(mode)),
                            ("reason", serde_json::Value::from(reason)),
                        ],
                    );
                }
            };
        let Some(path) = result.path else {
            // DFS が尽きた (forward で末尾、backward で先頭に達した等)
            match result.mode {
                FolderNavMode::SiblingGrid => {
                    self.show_feedback_toast(if result.forward {
                        "次の兄弟フォルダはありません".to_string()
                    } else {
                        "前の兄弟フォルダはありません".to_string()
                    });
                    self.clear_pending_folder_nav_steps();
                    self.release_fs_nav_lock();
                }
                FolderNavMode::SiblingFullscreen => {
                    let hint = crate::ui_fullscreen::FsBoundaryHint::NoSiblingFolder {
                        forward: result.forward,
                        at: std::time::Instant::now(),
                    };
                    self.fs_boundary_hint = Some(hint);
                    #[cfg(windows)]
                    if self.native_video_fullscreen_active_for_main_backdrop() {
                        self.show_native_video_overlay_toast(
                            Self::native_boundary_hint_text(hint),
                            true,
                        );
                    }
                    self.clear_pending_folder_nav_steps();
                    self.release_fs_nav_lock();
                }
                FolderNavMode::Favsearch { fullscreen, .. } => {
                    // favsearch では DFS 尽きた場合は検索結果の前後アイテムへ
                    let delta: isize = if result.forward { 1 } else { -1 };
                    if fullscreen {
                        #[cfg(windows)]
                        let restore_video_tile = self.video_tile_mode_active;
                        #[cfg(not(windows))]
                        let restore_video_tile = false;
                        if let Some(next_path) = self.favsearch_sibling_path(delta) {
                            self.clear_pending_folder_nav_steps();
                            self.close_fullscreen_for_folder_nav_reopen();
                            self.favsearch.nav_stack = vec![next_path.clone()];
                            self.load_folder(next_path);
                            self.update_favsearch_address();
                            let reason = self.reopen_fullscreen_after_folder_nav_load(
                                ctx,
                                restore_video_tile,
                                false,
                                history_trigger,
                            );
                            if reason == "enumerate_defer" {
                                emit_end(apply_t0, apply_seq, apply_mode_tag, reason);
                                return;
                            }
                        } else {
                            let hint = crate::ui_fullscreen::FsBoundaryHint::SearchEnd {
                                forward: result.forward,
                                at: std::time::Instant::now(),
                            };
                            self.fs_boundary_hint = Some(hint);
                            #[cfg(windows)]
                            if self.native_video_fullscreen_active_for_main_backdrop() {
                                self.show_native_video_overlay_toast(
                                    Self::native_boundary_hint_text(hint),
                                    true,
                                );
                            }
                            self.clear_pending_folder_nav_steps();
                            self.release_fs_nav_lock();
                        }
                    } else if !self.favsearch_navigate_sibling(delta) {
                        self.clear_pending_folder_nav_steps();
                    }
                }
                FolderNavMode::SmartFolder { fullscreen, .. } => {
                    if fullscreen {
                        let hint = crate::ui_fullscreen::FsBoundaryHint::SearchEnd {
                            forward: result.forward,
                            at: std::time::Instant::now(),
                        };
                        self.fs_boundary_hint = Some(hint);
                        #[cfg(windows)]
                        if self.native_video_fullscreen_active_for_main_backdrop() {
                            self.show_native_video_overlay_toast(
                                Self::native_boundary_hint_text(hint),
                                true,
                            );
                        }
                        self.release_fs_nav_lock();
                    } else {
                        self.show_feedback_toast(if result.forward {
                            "スマートフォルダ内の次のフォルダはありません".to_string()
                        } else {
                            "スマートフォルダ内の前のフォルダはありません".to_string()
                        });
                    }
                    self.clear_pending_folder_nav_steps();
                }
                FolderNavMode::Fullscreen => {
                    // DFS がツリー末端に達した: フルスクリーンは維持して中央にヒントを出す。
                    // 累積された連打は打ち切る (次回以降も同じ末端に向かうだけ)。
                    let hint = crate::ui_fullscreen::FsBoundaryHint::NoImageFolder {
                        forward: result.forward,
                        at: std::time::Instant::now(),
                    };
                    self.fs_boundary_hint = Some(hint);
                    // native 動画 fullscreen 中は中央 fs_boundary_hint が描画されない
                    // (= eframe backdrop ではなく native presenter overlay が描画する)
                    // ので native toast にも文言を流す。これが無いとユーザーには
                    // Ctrl+↑↓ が無反応に見える。
                    #[cfg(windows)]
                    if self.native_video_fullscreen_active_for_main_backdrop() {
                        self.show_native_video_overlay_toast(
                            Self::native_boundary_hint_text(hint),
                            true,
                        );
                    }
                    self.clear_pending_folder_nav_steps();
                    // items_generation が進まないので poll_fs_nav_lock では解除されない
                    // → 明示的に release して以降の Ctrl+↑↓ を効くようにする (Codex P1)。
                    self.release_fs_nav_lock();
                }
                FolderNavMode::SlideshowNext => {
                    // 次に静止画フォルダが無い (DFS 末端): スライドショーを停止して
                    // 現在画像に留まる。フルスクリーンは維持。
                    self.slideshow_playing = false;
                    self.slideshow_anchor_idx = None;
                    self.continuous_reading_scroll_transition = None;
                    self.slideshow_scroll_range_cache = None;
                    self.clear_pending_folder_nav_steps();
                    self.release_fs_nav_lock();
                }
                FolderNavMode::Grid => {}
            }
            // folder_nav result はグリッド / toast の描画後に回収される。空フォルダなど
            // 他の repaint 要因が無い状態でも、ここでセットした境界 toast / hint を
            // 次フレームで必ず描画する。
            ctx.request_repaint();
            emit_end(apply_t0, apply_seq, apply_mode_tag, "dfs_empty");
            return;
        };
        // SlideshowNext で skip_limit 内に静止画フォルダが見つからなかった場合は、
        // フォルダ移動せずスライドショーを停止して現在画像に留まる (カスケード防止)。
        if matches!(result.mode, FolderNavMode::SlideshowNext) && !result.hit_image_folder {
            self.slideshow_playing = false;
            self.slideshow_anchor_idx = None;
            self.continuous_reading_scroll_transition = None;
            self.slideshow_scroll_range_cache = None;
            self.clear_pending_folder_nav_steps();
            self.release_fs_nav_lock();
            emit_end(
                apply_t0,
                apply_seq,
                apply_mode_tag,
                "slideshow_next_boundary",
            );
            return;
        }
        // Fullscreen モードで skip_limit 尽きフォールバックの場合は、画像・動画の無い
        // フォルダへ飛ばしてフルスクリーンが解除されるのを避けるため、現状維持で
        // 中央ヒントを出す。Grid モードは従来通り移動 (段階的に進める導線)。
        if (matches!(result.mode, FolderNavMode::Fullscreen)
            || (self.navigation_scope.is_detached_physical()
                && matches!(result.mode, FolderNavMode::SiblingFullscreen))
            || matches!(
                result.mode,
                FolderNavMode::SmartFolder {
                    fullscreen: true,
                    ..
                }
            ))
            && !result.hit_image_folder
        {
            let hint = crate::ui_fullscreen::FsBoundaryHint::NoImageFolder {
                forward: result.forward,
                at: std::time::Instant::now(),
            };
            self.fs_boundary_hint = Some(hint);
            // native 動画 fullscreen 中は中央ヒントが見えないので toast でも feedback。
            #[cfg(windows)]
            if self.native_video_fullscreen_active_for_main_backdrop() {
                self.show_native_video_overlay_toast(Self::native_boundary_hint_text(hint), true);
            }
            self.clear_pending_folder_nav_steps();
            // 同上: items_generation 不変のまま return するので明示 release (Codex P1)。
            self.release_fs_nav_lock();
            emit_end(apply_t0, apply_seq, apply_mode_tag, "fs_boundary");
            return;
        }
        // DFS スレッドで事前スキャン済みなら UI スレッドの read_dir を省ける。
        let scanned = match result.scanned {
            FolderNavScanResult::NotNeeded => None,
            FolderNavScanResult::Ready(scan) => Some(scan),
            FolderNavScanResult::Failed(error) => {
                crate::logger::log(format!(
                    "folder navigation scan failed path={} error={error}",
                    path.display()
                ));
                self.clear_pending_folder_nav_steps();
                self.release_fs_nav_lock();
                self.show_feedback_toast("フォルダを読み取れませんでした".to_string());
                emit_end(apply_t0, apply_seq, apply_mode_tag, "scan_failed");
                return;
            }
        };
        match result.mode {
            FolderNavMode::Grid | FolderNavMode::SiblingGrid => {
                if !matches!(
                    self.load_folder_nav_target(path, scanned),
                    FolderOpenOutcome::Loaded
                ) {
                    continue_burst = false;
                    self.clear_pending_folder_nav_steps();
                    self.release_fs_nav_lock();
                }
            }
            FolderNavMode::SmartFolder { fullscreen, .. } => {
                if !self.prepare_smart_folder_nav_target(&path) {
                    self.clear_pending_folder_nav_steps();
                    self.release_fs_nav_lock();
                    emit_end(apply_t0, apply_seq, apply_mode_tag, "smart_scope_changed");
                    return;
                }
                #[cfg(windows)]
                let restore_video_tile = fullscreen && self.video_tile_mode_active;
                #[cfg(not(windows))]
                let restore_video_tile = false;
                if fullscreen {
                    self.close_fullscreen_for_folder_nav_reopen();
                }
                let open_outcome = self.load_folder_nav_target(path, scanned);
                if !matches!(open_outcome, FolderOpenOutcome::Loaded) {
                    self.clear_pending_folder_nav_steps();
                    self.release_fs_nav_lock();
                    emit_end(apply_t0, apply_seq, apply_mode_tag, "open_ignored");
                    return;
                }
                if fullscreen {
                    let reason = self.reopen_fullscreen_after_folder_nav_load(
                        ctx,
                        restore_video_tile,
                        false,
                        history_trigger,
                    );
                    if reason == "enumerate_defer" {
                        self.chain_folder_nav_if_pending(queued_steps, continuation_mode.clone());
                        emit_end(apply_t0, apply_seq, apply_mode_tag, reason);
                        return;
                    }
                }
            }
            FolderNavMode::Fullscreen
            | FolderNavMode::SiblingFullscreen
            | FolderNavMode::SlideshowNext => {
                let resume_slideshow = matches!(result.mode, FolderNavMode::SlideshowNext);
                #[cfg(windows)]
                let restore_video_tile = self.video_tile_mode_active;
                #[cfg(not(windows))]
                let restore_video_tile = false;
                // fs_cache / ai_upscale_cache は item index がキーで、
                // load_folder で items を入れ替えると古い画像を新しい idx で
                // 誤って引く危険がある。close_fullscreen で一括破棄してから
                // 新フォルダを読み直す (PDF Critical 予約は open_fullscreen で再取得)。
                // 注: close_fullscreen は slideshow_playing=false にするが、SlideshowNext は
                // resume_slideshow フラグ (= reopen 側で再開) で復帰するので問題ない。
                self.close_fullscreen_for_folder_nav_reopen();
                let open_outcome = self.load_folder_nav_target(path, scanned);
                if !matches!(open_outcome, FolderOpenOutcome::Loaded) {
                    let deferred_conversion =
                        matches!(open_outcome, FolderOpenOutcome::ConversionDialogOpened)
                            && self.attach_archive_convert_deferred_fullscreen(
                                restore_video_tile,
                                resume_slideshow,
                                history_trigger,
                            );
                    self.clear_pending_folder_nav_steps();
                    if !deferred_conversion {
                        self.release_fs_nav_lock();
                    }
                    let reason = match open_outcome {
                        FolderOpenOutcome::ConversionDialogOpened if deferred_conversion => {
                            "conversion_defer"
                        }
                        FolderOpenOutcome::ConversionDialogOpened => "conversion_dialog",
                        FolderOpenOutcome::Ignored => "open_ignored",
                        FolderOpenOutcome::Loaded => "done",
                    };
                    emit_end(apply_t0, apply_seq, apply_mode_tag, reason);
                    return;
                }
                let reason = self.reopen_fullscreen_after_folder_nav_load(
                    ctx,
                    restore_video_tile,
                    resume_slideshow,
                    history_trigger,
                );
                if reason == "enumerate_defer" {
                    self.chain_folder_nav_if_pending(queued_steps, continuation_mode.clone());
                    emit_end(apply_t0, apply_seq, apply_mode_tag, reason);
                    return;
                }
            }
            FolderNavMode::Favsearch { root, fullscreen } => {
                let delta: isize = if result.forward { 1 } else { -1 };
                if crate::search_index_db::is_under(&path, &root) {
                    if fullscreen && !result.hit_image_folder {
                        let hint = crate::ui_fullscreen::FsBoundaryHint::NoImageFolder {
                            forward: result.forward,
                            at: std::time::Instant::now(),
                        };
                        self.fs_boundary_hint = Some(hint);
                        // native 動画 fullscreen 中は中央ヒントが見えないので toast でも feedback。
                        #[cfg(windows)]
                        if self.native_video_fullscreen_active_for_main_backdrop() {
                            self.show_native_video_overlay_toast(
                                Self::native_boundary_hint_text(hint),
                                true,
                            );
                        }
                        self.clear_pending_folder_nav_steps();
                        self.release_fs_nav_lock();
                        emit_end(apply_t0, apply_seq, apply_mode_tag, "fs_boundary");
                        return;
                    }
                    // サブツリー内 — 通常の DFS 移動として開き、成功したらスタックに push
                    #[cfg(windows)]
                    let restore_video_tile = fullscreen && self.video_tile_mode_active;
                    #[cfg(not(windows))]
                    let restore_video_tile = false;
                    if fullscreen {
                        self.close_fullscreen_for_folder_nav_reopen();
                    }
                    let open_outcome = self.load_folder_nav_target(path.clone(), scanned);
                    if !matches!(open_outcome, FolderOpenOutcome::Loaded) {
                        self.clear_pending_folder_nav_steps();
                        self.release_fs_nav_lock();
                        let reason = match open_outcome {
                            FolderOpenOutcome::ConversionDialogOpened => "conversion_dialog",
                            FolderOpenOutcome::Ignored => "open_ignored",
                            FolderOpenOutcome::Loaded => "done",
                        };
                        emit_end(apply_t0, apply_seq, apply_mode_tag, reason);
                        return;
                    }
                    self.favsearch.nav_stack.push(path.clone());
                    self.update_favsearch_address();
                    if fullscreen {
                        let reason = self.reopen_fullscreen_after_folder_nav_load(
                            ctx,
                            restore_video_tile,
                            false,
                            history_trigger,
                        );
                        if reason == "enumerate_defer" {
                            self.chain_folder_nav_if_pending(
                                queued_steps,
                                continuation_mode.clone(),
                            );
                            emit_end(apply_t0, apply_seq, apply_mode_tag, reason);
                            return;
                        }
                    }
                } else {
                    // サブツリー外へ出ようとしている → 検索結果の前後へ移動
                    continue_burst = false;
                    if fullscreen {
                        #[cfg(windows)]
                        let restore_video_tile = self.video_tile_mode_active;
                        #[cfg(not(windows))]
                        let restore_video_tile = false;
                        if let Some(next_path) = self.favsearch_sibling_path(delta) {
                            self.clear_pending_folder_nav_steps();
                            self.close_fullscreen_for_folder_nav_reopen();
                            self.favsearch.nav_stack = vec![next_path.clone()];
                            self.load_folder(next_path);
                            self.update_favsearch_address();
                            let reason = self.reopen_fullscreen_after_folder_nav_load(
                                ctx,
                                restore_video_tile,
                                false,
                                history_trigger,
                            );
                            if reason == "enumerate_defer" {
                                emit_end(apply_t0, apply_seq, apply_mode_tag, reason);
                                return;
                            }
                        } else {
                            let hint = crate::ui_fullscreen::FsBoundaryHint::SearchEnd {
                                forward: result.forward,
                                at: std::time::Instant::now(),
                            };
                            self.fs_boundary_hint = Some(hint);
                            #[cfg(windows)]
                            if self.native_video_fullscreen_active_for_main_backdrop() {
                                self.show_native_video_overlay_toast(
                                    Self::native_boundary_hint_text(hint),
                                    true,
                                );
                            }
                            self.clear_pending_folder_nav_steps();
                            self.release_fs_nav_lock();
                        }
                    } else if !self.favsearch_navigate_sibling(delta) {
                        self.clear_pending_folder_nav_steps();
                    }
                }
            }
        }
        if continue_burst {
            self.chain_folder_nav_if_pending(queued_steps, continuation_mode);
        }
        emit_end(apply_t0, apply_seq, apply_mode_tag, "done");
    }

    /// Ctrl+↑↓ フルスクリーン遷移後の表示対象 item index を決める。
    ///
    /// 1. まず可視アイテムから画像系を探す。`include_video=false` のときは Video を
    ///    除外する (スライドショー NextFolder の再開で動画に着地しないため、Codex P2)。
    /// 2. 見つからず、ZIP/PDF ファイルだけ置かれているフォルダだった場合は
    ///    最初 (backward 時は最後) の ZIP/PDF に入り、その中の画像系を返す。
    ///    これにより「ZIP/PDF しか入っていない中間フォルダ」でフルスクリーン表示が
    ///    切れず、マンガ/コミックの連続閲覧が続く。
    fn find_fullscreen_nav_target_filtered(&mut self, include_video: bool) -> Option<usize> {
        // Ctrl+↑↓ は方向に関わらず常にフォルダ先頭の画像系アイテムへ着地する
        // (= 一般的なビューワ慣習に合わせ、フォルダ識別性を優先)。後方ナビでも
        // 先頭着地にすることで Ctrl+矢印の mental model が「フォルダにジャンプして
        // 冒頭から見る」の 1 つに統一される。前ページ末尾を見たい場合は Ctrl+↑ で
        // 戻った後 End キーで末尾に飛べる。
        let find_image = |app: &Self| -> Option<usize> {
            let items = &app.items;
            let is_image_like = |i: usize| {
                matches!(
                    items.get(i),
                    Some(GridItem::Image(_))
                        | Some(GridItem::ZipImage { .. })
                        | Some(GridItem::PdfPage { .. })
                ) || (include_video && matches!(items.get(i), Some(GridItem::Video(_))))
            };
            app.visible_indices
                .iter()
                .copied()
                .find(|&i| is_image_like(i))
        };

        if let Some(idx) = find_image(self) {
            return Some(idx);
        }

        // 画像系が無い: 先頭のコンテナファイルを開いて中身を取り出す。
        // ZIP/PDF/変換アーカイブの選び方も同様に「先頭」固定。
        let pick_virtual = |i: usize, items: &[GridItem]| -> Option<PathBuf> {
            match items.get(i) {
                Some(GridItem::ZipFile(p)) | Some(GridItem::PdfFile(p)) => Some(p.clone()),
                Some(GridItem::ConvertibleArchive { path, .. }) => Some(path.clone()),
                _ => None,
            }
        };
        let virtual_path = self
            .visible_indices
            .iter()
            .copied()
            .find_map(|i| pick_virtual(i, &self.items))?;
        if !matches!(
            self.load_folder_nav_target(virtual_path, None),
            FolderOpenOutcome::Loaded
        ) {
            return None;
        }
        find_image(self)
    }

    /// マウスホイールイベントを消費し、行単位でスナップしたオフセットに変換する。
    /// Ctrl+ホイールの場合はグリッド列数を変更する。
    ///
    /// 呼び出し位置に注意: メニュー/ツールバー/アドレスバー/ファセットバー等を描いた後、
    /// グリッド描画の直前で呼ぶ。これより早いと popup 内 ScrollArea の wheel が背面の
    /// サムネイル一覧にも通り抜ける。
    fn floating_ui_blocks_background_scroll(ctx: &egui::Context) -> bool {
        let Some(pointer_pos) = ctx.pointer_latest_pos() else {
            return false;
        };
        ctx.layer_id_at(pointer_pos).is_some_and(|layer| {
            matches!(layer.order, egui::Order::Middle | egui::Order::Foreground)
        })
    }

    /// Applies one discrete grid-column change without choosing a persistence
    /// boundary. Mouse wheel saves immediately; touch pinch batches its save
    /// until the recognizer reports the end of the gesture.
    pub(crate) fn change_grid_cols_by(&mut self, delta: i32) -> bool {
        let new_cols = (self.settings.grid_cols as i32 + delta).clamp(
            crate::settings::MIN_GRID_COLS as i32,
            crate::settings::MAX_GRID_COLS as i32,
        ) as usize;
        if new_cols == self.settings.grid_cols {
            return false;
        }

        self.settings.grid_cols = new_cols;
        self.bump_input_seq("grid_cols", None);
        true
    }

    fn process_scroll(&mut self, ctx: &egui::Context) {
        // ダイアログ / popup / フルスクリーン表示中はスクロールを消費しない
        // (ダイアログや ComboBox popup 内の ScrollArea が正しく動くようにする)。
        // PDF/ZIP enumerate や確認なしアーカイブ変換の deferred reopen 待ち中も
        // 「フルスクリーン継続中」と同じ扱いにする: 静止画 in-window モードでは
        // holdover が main ctx を覆っているのに、その背後で grid がホイールスクロール /
        // Ctrl+ホイール列数変更を受け付けてしまうのを防ぐ。
        if self.viewer_session_blocks_main_window()
            || self.fs_nav_deferred_reopen_wait_active()
            || self.any_dialog_open()
            || ctx.is_popup_open()
            // 新しい egui::Window / Modal を共通状態述語へ追加し忘れても、ポインタ直下が
            // floating layer なら背面グリッドへ wheel を渡さない最終安全網。Tooltip は
            // hover 中の通常グリッドスクロールを妨げるため対象外にする。
            || Self::floating_ui_blocks_background_scroll(ctx)
        {
            return;
        }

        let cell_h = self.last_cell_h.max(1.0);

        // マウスホイールイベントだけを取り出し、egui には渡さない
        let (scroll_delta_y, ctrl) = ctx.input(|i| (i.raw_scroll_delta.y, i.modifiers.ctrl));
        if scroll_delta_y.abs() > 0.5 {
            ctx.input_mut(|i| {
                i.raw_scroll_delta = egui::Vec2::ZERO;
                i.smooth_scroll_delta = egui::Vec2::ZERO;
                // MouseWheel イベントも消費
                i.events
                    .retain(|e| !matches!(e, egui::Event::MouseWheel { .. }));
            });

            if ctrl {
                // Ctrl+ホイール: 列数を増減（1〜10 の範囲）
                let delta = -scroll_delta_y.signum() as i32;
                if self.change_grid_cols_by(delta) {
                    self.settings.save();
                }
            } else {
                // 上スクロール(delta>0) → オフセット減、下スクロール(delta<0) → オフセット増
                let prev_offset = self.scroll_offset_y;
                self.scroll_offset_y = crate::ui_main::grid_wheel_scroll_offset(
                    self.scroll_offset_y,
                    scroll_delta_y,
                    cell_h,
                );
                if (self.scroll_offset_y - prev_offset).abs() > 0.5 {
                    self.bump_input_seq(
                        "grid_wheel",
                        Some(&format!("offset={:.0}", self.scroll_offset_y)),
                    );
                }
            }
        }
    }

    fn suppress_popup_wheel_before_grid(&self, ctx: &egui::Context) {
        if !ctx.is_popup_open() {
            return;
        }
        ctx.input_mut(|i| {
            i.raw_scroll_delta = egui::Vec2::ZERO;
            i.smooth_scroll_delta = egui::Vec2::ZERO;
            i.events
                .retain(|e| !matches!(e, egui::Event::MouseWheel { .. }));
        });
    }

    /// カーソルキー移動後、選択行がビューポートに収まるようオフセットを調整する
    pub(crate) fn apply_scroll_to_selected(&mut self, cols: usize, cell_h: f32) {
        let sel = match self.selected {
            Some(s) => s,
            None => return,
        };
        // フィルタ中/詳細表示中は画面上の表示順での位置から行を計算する。
        let vis_pos = self
            .current_grid_order()
            .iter()
            .position(|&i| i == sel)
            .unwrap_or(sel);
        let row = vis_pos / cols;
        let row_top = row as f32 * cell_h;
        let row_bottom = row_top + cell_h;
        let vp_top = self.scroll_offset_y;
        let vp_bottom = self.scroll_offset_y + self.last_viewport_h;

        if row_top < vp_top {
            // 選択行が上に隠れている → 選択行が最上行になるようスクロール
            self.scroll_offset_y = row_top;
        } else if row_bottom > vp_bottom {
            // 選択行が下に隠れている → 選択行が最下行になるようスクロール
            self.scroll_offset_y = (row_bottom - self.last_viewport_h).max(0.0);
            // 行境界にスナップ
            self.scroll_offset_y = (self.scroll_offset_y / cell_h).ceil() * cell_h;
        }
    }

    /// ウィンドウ位置を記録する（最小化・最大化中は更新しない）。
    fn track_window_rect(&mut self, ctx: &egui::Context) {
        let (outer_rect, inner_rect, pixels_per_point, minimized, maximized) = ctx.input(|i| {
            let vp = i.viewport();
            (
                vp.outer_rect,
                vp.inner_rect,
                i.pixels_per_point,
                vp.minimized.unwrap_or(false),
                vp.maximized.unwrap_or(false),
            )
        });

        if outer_rect.is_none() && self.last_outer_rect.is_none() {
            crate::logger::log(format!(
                "[viewport] outer_rect=None  inner_rect={:?}  pixels_per_point={pixels_per_point:.2}",
                inner_rect.map(|r| format!(
                    "pos=({:.0},{:.0}) size={:.0}x{:.0}",
                    r.min.x,
                    r.min.y,
                    r.width(),
                    r.height()
                ))
            ));
        }

        let best_rect = outer_rect.or(inner_rect);
        self.last_pixels_per_point = pixels_per_point;

        if !minimized && !maximized {
            if let Some(rect) = best_rect {
                let changed = self
                    .last_outer_rect
                    .map(|r| {
                        (r.min - rect.min).length() > 1.0 || (r.size() - rect.size()).length() > 1.0
                    })
                    .unwrap_or(true);
                if changed {
                    crate::logger::log(format!(
                        "[viewport] rect updated: pos=({:.0},{:.0}) size={:.0}x{:.0}  \
                         outer={:?}  inner={:?}  ppp={pixels_per_point:.2}",
                        rect.min.x,
                        rect.min.y,
                        rect.width(),
                        rect.height(),
                        outer_rect.map(|_| "Some"),
                        inner_rect.map(|_| "Some"),
                    ));
                    self.last_outer_rect = Some(rect);
                }
            }
            // inner_rect が取れていればそのサイズも別途保持する。
            // 保存/再適用の値として outer を使うとタイトルバー分だけ毎回小さくなるので、
            // 再起動時の InnerSize 再適用と整合する inner のサイズを優先して保存する。
            if let Some(ir) = inner_rect {
                self.last_inner_size = Some([ir.width(), ir.height()]);
            }
        }
    }

    /// グリッドショートカット (`handle_keyboard` / `handle_clipboard_shortcuts`) を
    /// テキスト入力フォーカス・ダイアログ・フルスクリーン中にブロックするための共通判定。
    /// 検索バー (Ctrl+F / Ctrl+S / Ctrl+G) のいずれかにフォーカスがある状態で
    /// BS / Enter / Ctrl+C 等が grid に漏れないようにするためのゲート。
    ///
    /// deferred reopen 待ちも block 対象に含めるのは、Ctrl+↑↓ で PDF/ZIP や確認なし
    /// 変換アーカイブへ遷移した直後 (= close_fullscreen で `fullscreen_idx = None` の
    /// 数フレーム) に、グリッド側 Ctrl+↑↓ が `FolderNavMode::Grid` で再 enqueue されて
    /// in-flight Fullscreen-mode nav をキャンセルしてしまうのを防ぐため。ユーザーの
    /// 意図はフルスクリーン継続なので、この待ち中はグリッドショートカットを全部抑止する。
    pub(crate) fn shortcuts_blocked_by_text_input(&self, ctx: &egui::Context) -> bool {
        self.keyboard_owner_for_pass(ctx)
            .blocks_legacy_main_shortcuts()
    }

    fn collect_shell_clipboard_paths(&self) -> Result<Vec<PathBuf>, ShellClipboardSelectionError> {
        if !self.checked.is_empty() {
            let mut paths = Vec::with_capacity(self.checked.len());
            for &idx in &self.checked {
                let Some(path) = self.items.get(idx).and_then(GridItem::drag_source_path) else {
                    return Err(ShellClipboardSelectionError::UncopyableItem);
                };
                paths.push(path.to_path_buf());
            }
            return Ok(paths);
        }

        let Some(idx) = self.selected else {
            return Ok(Vec::new());
        };
        let Some(item) = self.items.get(idx) else {
            return Ok(Vec::new());
        };
        let Some(path) = item.drag_source_path() else {
            return Err(ShellClipboardSelectionError::UncopyableItem);
        };
        Ok(vec![path.to_path_buf()])
    }

    fn invoke_shell_clipboard_verb(
        &mut self,
        ctx: &egui::Context,
        verb: crate::native_context_menu::ShellClipboardVerb,
    ) {
        let paths = match self.collect_shell_clipboard_paths() {
            Ok(paths) => paths,
            Err(ShellClipboardSelectionError::UncopyableItem) => {
                self.show_feedback_toast(
                    "ZIP内の画像やPDFページはファイルとしてコピー/カットできません".to_string(),
                );
                return;
            }
        };
        if paths.is_empty() {
            return;
        }
        let Some(hwnd) = self.main_hwnd else {
            crate::logger::log(format!(
                "shell_clipboard: {verb:?} skipped; main HWND unavailable"
            ));
            self.show_feedback_toast("OSクリップボード操作を開始できませんでした".to_string());
            return;
        };

        if matches!(
            verb,
            crate::native_context_menu::ShellClipboardVerb::Copy
                | crate::native_context_menu::ShellClipboardVerb::Cut
        ) {
            crate::ui_dialogs::context_menu::reserve_clipboard_write_sequence();
        }

        let result = crate::native_context_menu::invoke_shell_file_verb(hwnd, &paths, verb);
        Self::resync_egui_modifiers_from_os(ctx);
        match result {
            Ok(()) => ctx.request_repaint(),
            Err(err) => {
                crate::logger::log(format!("shell_clipboard: {verb:?} failed: {err}"));
                self.show_feedback_toast("OSクリップボード操作に失敗しました".to_string());
            }
        }
    }

    pub(crate) fn egui_modifiers_from_physical_state(
        ctrl: bool,
        shift: bool,
        alt: bool,
    ) -> egui::Modifiers {
        egui::Modifiers {
            alt,
            ctrl,
            shift,
            mac_cmd: false,
            command: ctrl,
        }
    }

    /// Win32 Shell のモーダル処理中に egui/winit が modifier KeyUp を取りこぼすと、
    /// `i.modifiers.ctrl` などが次の操作まで stale になり得る。Windows では物理
    /// modifier の hold 状態を OS API から毎フレーム同期し、Shell 復帰直後にも
    /// 明示同期する。個別の Key event に記録された modifiers はイベント時点の情報
    /// として残し、離散ショートカットの判定までは書き換えない。
    pub(crate) fn resync_egui_modifiers_from_os(ctx: &egui::Context) {
        #[cfg(windows)]
        {
            if !ctx.input(|i| i.viewport().focused).unwrap_or(true) {
                return;
            }

            use windows::Win32::UI::Input::KeyboardAndMouse::{VK_CONTROL, VK_MENU, VK_SHIFT};

            let key_down = |vk: u16| {
                crate::key_input::physical_key_down(crate::key_input::PhysicalKeySlot::new(
                    vk.into(),
                    false,
                ))
            };
            let modifiers = Self::egui_modifiers_from_physical_state(
                key_down(VK_CONTROL.0),
                key_down(VK_SHIFT.0),
                key_down(VK_MENU.0),
            );
            ctx.input_mut(|input| {
                input.modifiers = modifiers;
                input.raw.modifiers = modifiers;
            });
        }
        #[cfg(not(windows))]
        let _ = ctx;
    }

    /// Ctrl+C / Ctrl+X / Ctrl+V ショートカットを処理する。
    fn handle_clipboard_shortcuts(&mut self, ctx: &egui::Context) {
        let main_focused = ctx.input(|i| i.viewport().focused).unwrap_or(true);
        if !main_focused || self.shortcuts_blocked_by_text_input(ctx) {
            return;
        }

        let (ctrl_c, ctrl_x) = ctx.input(|i| {
            let mut c = false;
            let mut x = false;
            for event in &i.events {
                match event {
                    egui::Event::Copy => c = true,
                    egui::Event::Cut => x = true,
                    _ => {}
                }
            }
            (c, x)
        });

        let ctrl_v = {
            #[cfg(windows)]
            {
                // Clipboard paste depends on GetAsyncKeyState's transition low
                // bit, which the keyboard level chokepoint intentionally does
                // not model. Synthetic clipboard input is outside S1.
                let ctrl =
                    unsafe { windows::Win32::UI::Input::KeyboardAndMouse::GetAsyncKeyState(0x11) };
                let v =
                    unsafe { windows::Win32::UI::Input::KeyboardAndMouse::GetAsyncKeyState(0x56) };
                (ctrl & (0x8000u16 as i16)) != 0 && (v & (0x8000u16 as i16)) != 0 && (v & 1) != 0
            }
            #[cfg(not(windows))]
            false
        };

        if ctrl_c || ctrl_x {
            let verb = if ctrl_x {
                crate::native_context_menu::ShellClipboardVerb::Cut
            } else {
                crate::native_context_menu::ShellClipboardVerb::Copy
            };
            self.invoke_shell_clipboard_verb(ctx, verb);
        }

        if ctrl_v {
            // 検索結果グリッド表示中はペースト無効 (D&D と同じ判定。検索前の実フォルダへ
            // 誤って貼り付けない)。検索から実フォルダを開いた後は有効に戻る。
            let on_search_results = self.items_are_global_search_view
                || self.favsearch.on_results_grid()
                || self.items_are_tag_view
                || self.tag_view.on_results_grid();
            if !on_search_results
                && let (Some(hwnd), Some(folder)) = (self.main_hwnd, self.current_favorite_target())
            {
                let result = crate::native_context_menu::invoke_shell_folder_background_verb(
                    hwnd,
                    &folder,
                    crate::native_context_menu::ShellClipboardVerb::Paste,
                );
                Self::resync_egui_modifiers_from_os(ctx);
                match result {
                    Ok(()) => ctx.request_repaint(),
                    Err(err) => {
                        crate::logger::log(format!("shell_clipboard: Paste failed: {err}"));
                    }
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // フルスクリーン表示
    // -----------------------------------------------------------------------

    /// 指定 idx が画像本のページ (Image / ZipImage / PdfPage) かどうか。
    /// 読書位置レジュームの対象判定に使う (Folder/Zip/Pdf タイル・動画・区切りは対象外)。
    fn is_readable_page_idx(&self, idx: usize) -> bool {
        matches!(
            self.items.get(idx),
            Some(GridItem::Image(_))
                | Some(GridItem::ZipImage { .. })
                | Some(GridItem::PdfPage { .. })
        )
    }

    /// 現在のフルスクリーンページを「最後に読んだページ」として永続記録する。
    /// 画像本のページのみ対象。dedup 付きで連続ページ送り中の重複書き込みを抑える。
    pub(crate) fn record_book_resume(&mut self, idx: usize) {
        if !self.is_readable_page_idx(idx) {
            return;
        }
        // ネスト ZIP の本の中 (スタック深さ ≥ 2) では記録しない: ここでの idx は
        // 「現在の階層」ローカルだが、resume_page_for_container は再オープン時の
        // ルート階層 items に対して idx を検証するため、同 idx の別アイテムに誤って
        // 「続きから」着地し得る (レビュー P3)。ルート表示 (フラット ZIP / collapse 済み
        // 単一ラッパー) は再オープン時と同じ階層が materialize されるので従来どおり記録する。
        // 深い階層への cross-book resume は将来課題 (docs/nested-zip-tree-plan.md §14)。
        if self.zip_nav.as_ref().is_some_and(|n| !n.at_root()) {
            return;
        }
        let Some(folder) = self.current_folder.clone() else {
            return;
        };
        if self.last_book_resume.as_ref() == Some(&(folder.clone(), idx)) {
            return;
        }
        // 書き込みは background writer へ逃がす (ページ送り毎の UI スレッド同期 I/O 回避)。
        if let Some(writer) = &self.book_resume_writer {
            writer.record(&folder, idx);
        }
        self.last_book_resume = Some((folder, idx));
    }

    /// Records a user-chosen fullscreen item in the persisted viewing history.
    pub(crate) fn record_reading_history(&mut self, idx: usize, trigger: HistoryTrigger) {
        if !trigger.should_record()
            || !self.settings.reading_history_enabled
            || self.reading_history_writer.is_none()
        {
            return;
        }
        let Some(item) = self.items.get(idx) else {
            return;
        };
        let is_media = matches!(item, GridItem::Video(_) | GridItem::Audio(_));
        if !is_media
            && (self.global_search.active
                || self.items_are_global_search_view
                || self.tag_view.active
                || self.items_are_tag_view)
        {
            return;
        }
        let (path, kind, archive_format, last_page, page_count) = match item {
            GridItem::Video(path) => (
                path.clone(),
                crate::reading_history_db::ReadingHistoryKind::Video,
                None,
                None,
                None,
            ),
            GridItem::Audio(path) => (
                path.clone(),
                crate::reading_history_db::ReadingHistoryKind::Audio,
                None,
                None,
                None,
            ),
            _ if self.is_readable_page_idx(idx) => {
                let Some((page_pos, page_count)) = self.current_reading_history_page_position(idx)
                else {
                    return;
                };
                let Some((path, kind, archive_format)) = self.reading_history_target_for_page(idx)
                else {
                    return;
                };
                let keep_progress = !self.zip_nav.as_ref().is_some_and(|n| !n.at_root());
                (
                    path,
                    kind,
                    archive_format,
                    keep_progress.then_some(page_pos),
                    keep_progress.then_some(page_count),
                )
            }
            _ => return,
        };
        let key = crate::path_key::normalize_keep_drive(&path);
        const TOUCH_THROTTLE: std::time::Duration = std::time::Duration::from_secs(30);
        let now = std::time::Instant::now();
        if self
            .last_reading_history_touch
            .as_ref()
            .is_some_and(|(last_key, at)| {
                last_key == &key && now.duration_since(*at) < TOUCH_THROTTLE
            })
        {
            return;
        }

        let title = reading_history_title_for_path(&path);
        let entry = crate::reading_history_db::ReadingHistoryEntry::new(
            path,
            kind,
            archive_format,
            title,
            last_page,
            page_count,
        );
        if let Some(writer) = &self.reading_history_writer {
            writer.record(entry, self.settings.reading_history_limit);
        }
        self.last_reading_history_touch = Some((key, now));
    }

    fn current_reading_history_page_position(&self, idx: usize) -> Option<(i64, i64)> {
        let mut page_count = 0_i64;
        let mut page_pos = None;
        for &candidate in self.current_grid_order() {
            let item = self.items.get(candidate)?;
            if !item.has_page_data() {
                return None;
            }
            page_count += 1;
            if candidate == idx {
                page_pos = Some(page_count);
            }
        }
        page_pos
            .map(|pos| (pos, page_count))
            .filter(|(_, count)| *count > 0)
    }

    fn reading_history_target_for_page(
        &self,
        idx: usize,
    ) -> Option<(
        PathBuf,
        crate::reading_history_db::ReadingHistoryKind,
        Option<crate::archive_converter::ArchiveFormat>,
    )> {
        if let Some(path) = self.archive_source_override.clone() {
            return Some((
                path.clone(),
                crate::reading_history_db::ReadingHistoryKind::Archive,
                crate::reading_history_db::archive_format_for_path(&path),
            ));
        }
        match self.items.get(idx)? {
            GridItem::Image(_) => {
                let folder = self.current_folder.clone()?;
                if is_synthetic_view_path(&folder) {
                    return None;
                }
                Some((
                    folder,
                    crate::reading_history_db::ReadingHistoryKind::Folder,
                    None,
                ))
            }
            GridItem::ZipImage { zip_path, .. } => {
                if crate::rar_loader::is_rar_path(zip_path) {
                    Some((
                        zip_path.clone(),
                        crate::reading_history_db::ReadingHistoryKind::Archive,
                        Some(crate::archive_converter::ArchiveFormat::Rar),
                    ))
                } else {
                    Some((
                        zip_path.clone(),
                        crate::reading_history_db::ReadingHistoryKind::Zip,
                        None,
                    ))
                }
            }
            GridItem::PdfPage { pdf_path, .. } => Some((
                pdf_path.clone(),
                crate::reading_history_db::ReadingHistoryKind::Pdf,
                None,
            )),
            _ => None,
        }
    }

    /// 現在のコンテナ (`current_folder`) の保存済み読書位置を、現在の `items` に対して
    /// 検証して返す。範囲外 / 本ページでない場合は None (= 先頭にフォールバック)。
    pub(crate) fn resume_page_for_container(&self) -> Option<usize> {
        let folder = self.current_folder.as_deref()?;
        let idx = self.book_resume_db.as_ref()?.get(folder)?;
        if self.is_readable_page_idx(idx) {
            Some(idx)
        } else {
            None
        }
    }

    #[cfg(windows)]
    fn viewer_item_supports_session(&self, idx: usize) -> bool {
        matches!(
            self.items.get(idx),
            Some(GridItem::Image(_))
                | Some(GridItem::ZipImage { .. })
                | Some(GridItem::PdfPage { .. })
                | Some(GridItem::Video(_))
                | Some(GridItem::Audio(_))
        )
    }

    #[cfg(windows)]
    fn viewer_item_is_media(&self, idx: usize) -> bool {
        matches!(
            self.items.get(idx),
            Some(GridItem::Video(_)) | Some(GridItem::Audio(_))
        )
    }

    #[cfg(windows)]
    fn viewer_item_supports_egui_detached_viewport(&self, idx: usize) -> bool {
        self.viewer_item_supports_detached_still(idx)
            || matches!(self.items.get(idx), Some(GridItem::Audio(_)))
    }

    #[cfg(windows)]
    fn detached_source_for_idx(&self, idx: usize) -> DetachedSource {
        match self.items.get(idx) {
            Some(GridItem::Video(_)) => DetachedSource::Video,
            Some(GridItem::Audio(_)) => DetachedSource::Audio,
            _ => DetachedSource::Image,
        }
    }

    pub(crate) fn viewer_session_is_detached(&self) -> bool {
        self.fullscreen_idx.is_some()
            && matches!(self.viewer_presentation, ViewerPresentation::DetachedWindow)
    }

    fn current_viewer_session_is_detached_or_switching(&self) -> bool {
        if self.viewer_session_is_detached() {
            return true;
        }
        if self.fullscreen_idx.is_none() {
            return false;
        }
        #[cfg(windows)]
        {
            self.detached_video_host_switch_pending()
                || matches!(
                    self.native_video_mode_switch,
                    Some(pending)
                        if matches!(
                            pending.target_presentation,
                            ViewerPresentation::DetachedWindow
                        )
                )
        }
        #[cfg(not(windows))]
        {
            false
        }
    }

    pub(crate) fn viewer_session_is_detached_or_switching(&self) -> bool {
        #[cfg(windows)]
        if self.active_detached_viewer_context.is_some() {
            return true;
        }
        self.current_viewer_session_is_detached_or_switching()
    }

    pub(crate) fn viewer_session_blocks_main_window(&self) -> bool {
        // The main-focus close consumer must use the same current-session lifecycle fact as tray
        // residency. During a switch to detached, `viewer_presentation` is still the old fullscreen
        // value until PlacementSwitched arrives; treating that transient as main-blocking would let
        // ShowWindow focus close the session that tray hide deliberately retained.
        //
        // Keep the active detached *sibling* context out of this current-session predicate: the main
        // context can own its own fullscreen while a media window is mounted separately.
        self.fullscreen_idx.is_some() && !self.current_viewer_session_is_detached_or_switching()
    }

    pub(crate) fn fullscreen_opened_at(&self) -> Option<std::time::Instant> {
        self.fs_opened_at
    }

    fn reconcile_fullscreen_after_main_focus(
        &mut self,
        ctx: &egui::Context,
        main_viewport_focused: bool,
        fullscreen_root_key_handled: bool,
    ) {
        if !self.viewer_session_blocks_main_window() {
            return;
        }

        const FS_FOCUS_GRACE_MS: u128 = 500;
        if !self.fs_focus_grace_elapsed {
            self.fs_focus_grace_elapsed = self
                .fs_opened_at
                .map(|t| t.elapsed().as_millis() > FS_FOCUS_GRACE_MS)
                .unwrap_or(true);
        }
        #[cfg(windows)]
        let native_video_presenter_active = self.native_video_presenter_hwnd_for_focus_guard();
        #[cfg(not(windows))]
        let native_video_presenter_active = false;
        #[cfg(windows)]
        let embedded_still = self.fullscreen_embedded_still_active();
        #[cfg(not(windows))]
        let embedded_still = false;
        if should_close_fullscreen_from_main_focus(
            self.fs_focus_grace_elapsed,
            main_viewport_focused,
            native_video_presenter_active,
            embedded_still,
            self.settings.fullscreen_keep_on_app_switch,
            fullscreen_root_key_handled,
        ) {
            crate::logger::log(format!(
                "fullscreen: main focus guard closing session presentation={:?} detached_lifecycle={}",
                self.viewer_presentation,
                self.current_viewer_session_is_detached_or_switching()
            ));
            self.close_fullscreen();
        } else if should_restore_fullscreen_focus_from_main_focus(
            self.fs_focus_grace_elapsed,
            main_viewport_focused,
            embedded_still,
            self.settings.fullscreen_keep_on_app_switch,
            fullscreen_root_key_handled,
        ) {
            self.restore_fullscreen_focus_from_main(ctx);
        }
    }

    /// トレイ復帰イベントで、保持中の通常 fullscreen media surface を再び前面化する。
    /// tray 専用の状態は持たず、現在 mount されている media owner だけを見る。
    /// 再生 transport には触れないため、running / paused / EOF の intent と位置はそのまま残る。
    pub(crate) fn restore_media_surface_after_tray(&mut self, ctx: &egui::Context) {
        if self.current_viewer_session_is_detached_or_switching()
            || !matches!(self.viewer_presentation, ViewerPresentation::Fullscreen)
        {
            return;
        }
        let Some(idx) = self.fullscreen_idx else {
            return;
        };
        if !matches!(self.fs_cache.get(&idx), Some(FsCacheEntry::Video { .. })) {
            return;
        }

        // ShowWindow(main) の直後は fullscreen/native surface への Focus/raise が非同期で
        // 反映される。open 直後と同じ既存 grace を再始動して、その反映前に main-focus
        // guard が session を閉じないようにする。
        self.fs_focus_grace_elapsed = false;
        self.fs_opened_at = Some(std::time::Instant::now());
        self.restore_fullscreen_focus_from_main(ctx);
    }

    fn main_window_should_draw_export_dialogs(&self) -> bool {
        !self.viewer_session_blocks_main_window() && !self.viewer_session_is_detached_or_switching()
    }

    #[cfg(windows)]
    fn active_detached_viewer_has_foreground(&self) -> bool {
        if !self.viewer_session_is_detached_or_switching()
            && self.active_detached_viewer_context.is_none()
        {
            return false;
        }
        let Some(hwnd) = self.detached_viewer_host_hwnd_alive() else {
            return false;
        };
        crate::video::native_window::foreground_hwnd() == hwnd
    }

    #[cfg(not(windows))]
    fn active_detached_viewer_has_foreground(&self) -> bool {
        false
    }

    fn main_keyboard_should_drain_mouse_nav(&self, main_has_focus: bool) -> bool {
        if self.viewer_session_blocks_main_window() {
            return false;
        }
        if self.active_detached_viewer_has_foreground() {
            return false;
        }
        if self.viewer_session_is_detached() && !main_has_focus {
            // Static detached viewers rely on the egui viewport handler to consume
            // APPCOMMAND/BrowserBack input. Native detached video has its own Win32
            // window proc, so main can drain the global hook counter to prevent a
            // stale duplicate after the native handler has already moved.
            return matches!(
                self.fullscreen_idx.and_then(|idx| self.items.get(idx)),
                Some(GridItem::Video(_))
            );
        }
        true
    }

    #[cfg(windows)]
    pub(crate) fn request_main_font_atlas_resync(&mut self, reason: &'static str) {
        self.request_main_font_atlas_resync_now(reason);
    }

    #[cfg(windows)]
    fn request_main_font_atlas_resync_now(&mut self, reason: &'static str) {
        if Self::detached_image_window_debug_enabled() {
            crate::logger::log(format!(
                "[ui-fonts][diag] request_now reason={reason} pending_before={} \
                 repeats={} detached_wait={} detached_safe={} active_context={} \
                 session={:?} fullscreen_idx={:?} presentation={:?} fs_shown={} passive_windows={}",
                self.main_font_atlas_resync_pending,
                self.main_font_atlas_resync_repeats_left,
                self.detached_font_atlas_resync_should_wait(),
                self.detached_cleanup_font_atlas_resync_is_safe(),
                self.active_detached_viewer_context.is_some(),
                self.active_detached_session,
                self.fullscreen_idx,
                self.viewer_presentation,
                self.fs_viewport_shown,
                self.detached_image_windows.len()
            ));
        }
        if !self.main_font_atlas_resync_pending {
            crate::logger::log(format!(
                "[ui-fonts] schedule main font atlas resync: {reason}"
            ));
        }
        self.main_font_atlas_resync_pending = true;
        // close 直後の 1 フレームだけメインウィンドウの wgpu surface が消えて full upload が
        // 捨てられる (no-surface early return)。数フレーム再発行して、surface が戻った
        // フレームで確実に届かせる。
        self.main_font_atlas_resync_repeats_left = MAIN_FONT_ATLAS_RESYNC_REPEAT_FRAMES;
        if self.main_font_atlas_resync_reason.is_none() {
            self.main_font_atlas_resync_reason = Some(reason);
        }
    }

    #[cfg(windows)]
    pub(crate) fn request_detached_cleanup_font_atlas_resync(&mut self, source: &'static str) {
        self.defer_main_font_atlas_resync(FONT_ATLAS_RESYNC_REASON_DETACHED_VIEWER_CLEANUP, source);
    }

    #[cfg(windows)]
    fn defer_main_font_atlas_resync(&mut self, reason: &'static str, source: &'static str) {
        if Self::detached_image_window_debug_enabled() {
            crate::logger::log(format!(
                "[ui-fonts][diag] defer_request reason={reason} source={source} \
                 existing={:?} detached_wait={} detached_safe={} active_context={} \
                 session={:?} fullscreen_idx={:?} presentation={:?} fs_shown={} passive_windows={}",
                self.pending_detached_cleanup_font_atlas_resync,
                self.detached_font_atlas_resync_should_wait(),
                self.detached_cleanup_font_atlas_resync_is_safe(),
                self.active_detached_viewer_context.is_some(),
                self.active_detached_session,
                self.fullscreen_idx,
                self.viewer_presentation,
                self.fs_viewport_shown,
                self.detached_image_windows.len()
            ));
        }
        if self.pending_detached_cleanup_font_atlas_resync.is_none() {
            crate::logger::log(format!(
                "[ui-fonts] defer main font atlas resync: reason={reason} source={source}"
            ));
        }
        if self.pending_detached_cleanup_font_atlas_resync.is_none() {
            self.pending_detached_cleanup_font_atlas_resync = Some(reason);
        }
    }

    #[cfg(windows)]
    fn defer_pending_main_font_atlas_resync_for_detached_session(&mut self, source: &'static str) {
        if !self.main_font_atlas_resync_pending {
            return;
        }
        let reason = self
            .main_font_atlas_resync_reason
            .take()
            .unwrap_or("unknown");
        self.main_font_atlas_resync_pending = false;
        self.main_font_atlas_resync_repeats_left = 0;
        self.main_font_atlas_resync_last_fire_frame = u64::MAX;
        crate::logger::log(format!(
            "[ui-fonts] move pending main font atlas resync to detached-deferred: \
             reason={reason} source={source}"
        ));
        self.defer_main_font_atlas_resync(reason, source);
    }

    #[cfg(windows)]
    fn log_font_atlas_pass_probe(&self, ctx: &egui::Context, phase: &'static str) {
        if !Self::detached_image_window_debug_enabled() {
            return;
        }
        let safety = self.main_font_atlas_resync_frame_safety();
        let detached_wait = !safety.is_settled();
        let interesting = self.main_font_atlas_resync_pending
            || self.pending_detached_cleanup_font_atlas_resync.is_some()
            || detached_wait
            || ctx.current_pass_index() > 0
            || ctx.will_discard();
        if !interesting {
            return;
        }
        let urgent = self.main_font_atlas_resync_defers_texture_uploads()
            || ctx.current_pass_index() > 0
            || ctx.will_discard();
        if !urgent && self.frame_counter % 60 != 0 {
            return;
        }
        crate::logger::log(format!(
            "[ui-fonts][diag] pass_probe phase={phase} egui_frame={} egui_pass={} \
             pass_index={} will_discard={} main_pending={} main_reason={} repeats={} \
             last_fire={} generation={} deferred_reason={} detached_wait={} detached_safe={} \
             placement_pending={} cloak_or_backdrop={} opening={} closing={} \
             active_context={} session={:?} fullscreen_idx={:?} presentation={:?} \
             fs_presentation={:?} fs_shown={} passive_windows={} embedded_still={} main_blocked={}",
            ctx.cumulative_frame_nr(),
            ctx.cumulative_pass_nr(),
            ctx.current_pass_index(),
            ctx.will_discard(),
            self.main_font_atlas_resync_pending,
            self.main_font_atlas_resync_reason.unwrap_or("none"),
            self.main_font_atlas_resync_repeats_left,
            self.main_font_atlas_resync_last_fire_frame,
            self.main_font_atlas_resync_generation,
            self.pending_detached_cleanup_font_atlas_resync
                .unwrap_or("none"),
            detached_wait,
            safety.is_settled(),
            safety.placement_pending,
            safety.cloak_or_backdrop_active,
            safety.opening_count,
            safety.closing_count,
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session,
            self.fullscreen_idx,
            self.viewer_presentation,
            self.fs_viewport_presentation,
            self.fs_viewport_shown,
            self.detached_image_windows.len(),
            self.fullscreen_embedded_still_active(),
            self.viewer_session_blocks_main_window()
        ));
    }

    #[cfg(windows)]
    pub(crate) fn main_font_atlas_resync_settled_frame(&self) -> bool {
        self.main_font_atlas_resync_frame_safety().is_settled()
    }

    #[cfg(windows)]
    fn main_font_atlas_resync_video_switch_pending(&self) -> bool {
        self.native_video_mode_switch.is_some()
            || self.pending_detached_video_host_switch.is_some()
            || self.pending_detached_video_host_resync
            || self.native_video_source_swap_pending.is_some()
    }

    #[cfg(windows)]
    fn main_font_atlas_resync_backdrop_or_cloak_active(&self) -> bool {
        self.native_video_main_cloaked || self.native_video_fullscreen_active_for_main_backdrop()
    }

    #[cfg(windows)]
    fn detached_window_runtime_state_count(&self, state: DetachedWindowState) -> usize {
        self.detached_window_manager.state_count(state)
    }

    #[cfg(windows)]
    pub(crate) fn main_font_atlas_resync_frame_safety(&self) -> MainFontAtlasResyncFrameSafety {
        MainFontAtlasResyncFrameSafety {
            placement_pending: self.main_font_atlas_resync_video_switch_pending(),
            cloak_or_backdrop_active: self.main_font_atlas_resync_backdrop_or_cloak_active(),
            opening_count: self.detached_window_runtime_state_count(DetachedWindowState::Opening),
            closing_count: self.detached_window_runtime_state_count(DetachedWindowState::Closing),
        }
    }

    #[cfg(windows)]
    pub(crate) fn main_font_atlas_resync_defers_texture_uploads(&self) -> bool {
        self.main_font_atlas_resync_pending
            && self.main_font_atlas_resync_repeats_left > 0
            && self.main_font_atlas_resync_repeats_left < MAIN_FONT_ATLAS_RESYNC_REPEAT_FRAMES
    }

    #[cfg(windows)]
    pub(crate) fn detached_font_atlas_resync_should_wait(&self) -> bool {
        !self.main_font_atlas_resync_settled_frame()
    }

    #[cfg(windows)]
    pub(crate) fn detached_cleanup_font_atlas_resync_is_safe(&self) -> bool {
        self.main_font_atlas_resync_settled_frame()
    }

    #[cfg(windows)]
    pub(crate) fn flush_pending_detached_cleanup_font_atlas_resync(&mut self) {
        let Some(reason) = self.pending_detached_cleanup_font_atlas_resync else {
            return;
        };
        let safety = self.main_font_atlas_resync_frame_safety();
        if !safety.is_settled() {
            if self.frame_counter % 60 == 0 {
                self.log_detached_image_window_debug(format!(
                    "font_resync_deferred_detached_alive active_context={} session={:?} \
                 fullscreen_idx={:?} presentation={:?} fs_shown={} passive_windows={} \
                 reason={reason} placement_pending={} cloak_or_backdrop={} opening={} closing={}",
                    self.active_detached_viewer_context.is_some(),
                    self.active_detached_session,
                    self.fullscreen_idx,
                    self.viewer_presentation,
                    self.fs_viewport_shown,
                    self.detached_image_windows.len(),
                    safety.placement_pending,
                    safety.cloak_or_backdrop_active,
                    safety.opening_count,
                    safety.closing_count
                ));
            }
            return;
        }
        self.pending_detached_cleanup_font_atlas_resync = None;
        crate::logger::log(format!(
            "[ui-fonts] flush deferred main font atlas resync: reason={reason}"
        ));
        self.request_main_font_atlas_resync_now(reason);
    }

    #[cfg(windows)]
    fn maybe_defer_for_main_font_atlas_resync(
        &mut self,
        ctx: &egui::Context,
        phase: &'static str,
    ) -> bool {
        self.log_font_atlas_pass_probe(ctx, phase);
        if !self.main_font_atlas_resync_pending {
            return false;
        }
        let safety = self.main_font_atlas_resync_frame_safety();
        if !safety.is_settled() {
            if Self::detached_image_window_debug_enabled() && self.frame_counter % 60 == 0 {
                crate::logger::log(format!(
                    "[ui-fonts][diag] resync_wait_settled phase={phase} reason={} \
                     egui_frame={} egui_pass={} pass_index={} placement_pending={} \
                     cloak_or_backdrop={} opening={} closing={} fullscreen_idx={:?} \
                     presentation={:?} fs_presentation={:?} fs_shown={} passive_windows={} \
                     active_context={} session={:?}",
                    self.main_font_atlas_resync_reason.unwrap_or("none"),
                    ctx.cumulative_frame_nr(),
                    ctx.cumulative_pass_nr(),
                    ctx.current_pass_index(),
                    safety.placement_pending,
                    safety.cloak_or_backdrop_active,
                    safety.opening_count,
                    safety.closing_count,
                    self.fullscreen_idx,
                    self.viewer_presentation,
                    self.fs_viewport_presentation,
                    self.fs_viewport_shown,
                    self.detached_image_windows.len(),
                    self.active_detached_viewer_context.is_some(),
                    self.active_detached_session
                ));
            }
            ctx.request_repaint_after(std::time::Duration::from_millis(16));
            return false;
        }
        if self.viewer_session_blocks_main_window() && !self.fullscreen_embedded_still_active() {
            if Self::detached_image_window_debug_enabled() {
                crate::logger::log(format!(
                    "[ui-fonts][diag] resync_wait_main_blocked phase={phase} reason={} \
                     egui_frame={} egui_pass={} pass_index={} fullscreen_idx={:?} presentation={:?}",
                    self.main_font_atlas_resync_reason.unwrap_or("none"),
                    ctx.cumulative_frame_nr(),
                    ctx.cumulative_pass_nr(),
                    ctx.current_pass_index(),
                    self.fullscreen_idx,
                    self.viewer_presentation
                ));
            }
            ctx.request_repaint_after(std::time::Duration::from_millis(16));
            return false;
        }

        // 1 OS フレーム 1 発行へゲートする。discard 再パスや update 内 2 箇所
        // (update_early / pre_main_ui) で同一フレーム内に複数回呼ばれても、2 回目以降は
        // 再発行せず paint を進めさせる (= repeats を 1 フレームで使い切らない / 黒フレーム回避)。
        let frame_nr = ctx.cumulative_frame_nr();
        if self.main_font_atlas_resync_last_fire_frame == frame_nr {
            return false;
        }
        self.main_font_atlas_resync_last_fire_frame = frame_nr;

        // 数フレーム再発行する。最後の 1 回まで pending/reason を保持し、毎フレーム
        // set_fonts で full atlas upload を再要求して surface 復帰フレームに届かせる。
        let repeats_left = self.main_font_atlas_resync_repeats_left.saturating_sub(1);
        self.main_font_atlas_resync_repeats_left = repeats_left;
        let final_fire = repeats_left == 0;
        if final_fire {
            self.main_font_atlas_resync_pending = false;
        }
        self.main_font_atlas_resync_generation =
            self.main_font_atlas_resync_generation.wrapping_add(1);
        let generation = self.main_font_atlas_resync_generation;
        let reason = if final_fire {
            self.main_font_atlas_resync_reason
                .take()
                .unwrap_or("unknown")
        } else {
            self.main_font_atlas_resync_reason.unwrap_or("unknown")
        };
        if Self::detached_image_window_debug_enabled() {
            crate::logger::log(format!(
                "[ui-fonts][diag] set_fonts_for_resync phase={phase} reason={reason} \
                 generation={generation} final_fire={final_fire} repeats_left={repeats_left} \
                 egui_frame={} egui_pass={} pass_index={} will_discard_before={}",
                ctx.cumulative_frame_nr(),
                ctx.cumulative_pass_nr(),
                ctx.current_pass_index(),
                ctx.will_discard()
            ));
        }
        crate::ui_fonts::configure_fonts_for_texture_resync(
            ctx,
            generation,
            &self.settings.ui_font,
        );
        if !final_fire {
            // 次フレームでも再発行する。surface が戻るまで full upload を出し続ける。
            ctx.request_repaint();
        }
        let defer_main_paint = should_defer_main_paint_for_font_atlas_resync(reason);
        if !defer_main_paint {
            // detached cleanup 等、保守的 defer が不要な経路。フォント再アップロードを
            // 予約しただけで、この pass はそのままメイン UI を描く。
            crate::logger::log(format!(
                "[ui-fonts] resync main font atlas without paint defer: phase={phase} \
                 reason={reason} generation={generation} egui_frame={} egui_pass={} pass_index={}",
                ctx.cumulative_frame_nr(),
                ctx.cumulative_pass_nr(),
                ctx.current_pass_index()
            ));
            ctx.request_repaint();
            return false;
        }

        // 通常 fullscreen / 動画 backdrop / F11 recreate の resync 経路。
        //
        // `set_fonts` は「次 pass の begin_pass で適用」される (egui 仕様)。ここで
        // この pass を `request_discard` で破棄すると、egui の run() が **同じ OS
        // フレーム内** でもう一度 begin_pass → update() を走らせる。次 pass の
        // begin_pass で new_font_definitions が適用され、font atlas のフルアップロードが
        // メイン UI 描画より前に入るため、stale texture への部分更新 panic を避けつつ、
        // 破棄された pass は paint されないので黒/空白フレームも出ない。
        // 2 度目の pass は入力 events が空になる (RawInput::take 済み) ので、close や
        // ナビ等の入力起因処理が二重発火しないのも担保される。
        ctx.request_discard(format!("font-atlas-resync:{reason}"));
        if ctx.will_discard() {
            crate::logger::log(format!(
                "[ui-fonts] discard pass for font atlas resync (same-frame repass): \
                 phase={phase} reason={reason} generation={generation} egui_frame={} \
                 egui_pass={} pass_index={}",
                ctx.cumulative_frame_nr(),
                ctx.cumulative_pass_nr(),
                ctx.current_pass_index()
            ));
            // 同一フレーム内で次 pass が走るので request_repaint は不要。
            return true;
        }

        // multi-pass の予算が無い (max_passes 到達 / 他要因の discard と競合等)。
        // 従来どおりこの pass の描画を飛ばし、次フレームで再描画する安全側フォール
        // バック (= 1 フレーム黒)。通常運用ではここには来ない想定。
        crate::logger::log(format!(
            "[ui-fonts] defer main paint for font atlas resync (no discard budget): \
             phase={phase} reason={reason} generation={generation} egui_frame={} \
             egui_pass={} pass_index={}",
            ctx.cumulative_frame_nr(),
            ctx.cumulative_pass_nr(),
            ctx.current_pass_index()
        ));
        ctx.request_repaint();
        true
    }

    pub(crate) fn main_grid_spread_pair_cursor_idx(&mut self) -> Option<usize> {
        if !self.viewer_session_is_detached() {
            return None;
        }
        #[cfg(windows)]
        if self.detached_independent_session_blocks_folder_nav() {
            return None;
        }
        let fs_idx = self.fullscreen_idx?;
        match self.resolve_visible_spread_pair(fs_idx) {
            crate::ui_fullscreen::SpreadPair::Double { left, right } if fs_idx == left => {
                Some(right)
            }
            crate::ui_fullscreen::SpreadPair::Double { left, right } if fs_idx == right => {
                Some(left)
            }
            _ => None,
        }
    }

    pub(crate) fn sync_main_selection_from_viewer_idx(&mut self, idx: usize) {
        if self.items.get(idx).is_none() {
            return;
        }
        #[cfg(windows)]
        if self.viewer_session_is_detached() && self.detached_viewer_independent_still_session() {
            self.last_viewer_sync_stamp = self.viewer_sync_stamp_for_idx(idx);
            return;
        }
        self.selected = Some(idx);
        self.scroll_to_selected = true;
        self.update_last_selected_image();
        #[cfg(windows)]
        {
            self.last_viewer_sync_stamp = if self.viewer_session_is_detached() {
                self.viewer_sync_stamp_for_idx(idx)
            } else {
                None
            };
        }
    }

    #[cfg(windows)]
    fn viewer_item_supports_detached_still(&self, idx: usize) -> bool {
        matches!(
            self.items.get(idx),
            Some(GridItem::Image(_))
                | Some(GridItem::ZipImage { .. })
                | Some(GridItem::PdfPage { .. })
        )
    }

    #[cfg(windows)]
    fn detached_viewer_context_descriptor_for_idx(
        &self,
        idx: usize,
    ) -> Option<ViewerContextDescriptor> {
        match self.items.get(idx)? {
            GridItem::Image(path) => Some(ViewerContextDescriptor::Image { path: path.clone() }),
            GridItem::PdfPage {
                pdf_path, page_num, ..
            } => Some(ViewerContextDescriptor::Pdf {
                path: pdf_path.clone(),
                page_num: Some(*page_num),
            }),
            GridItem::ZipImage {
                zip_path,
                entry_name,
            } => Some(ViewerContextDescriptor::Zip {
                path: zip_path.clone(),
                entry_name: Some(entry_name.clone()),
                archive_source_override: self.archive_source_override.clone(),
            }),
            _ => None,
        }
    }

    /// parked still snapshot に焼き付ける再オープン descriptor。
    /// 通常画像も open ルーティングと parked fallback の双方で同じ `Image`
    /// descriptor を使い、親フォルダの完全な物理一覧から開き直す。
    #[cfg(windows)]
    pub(crate) fn parked_still_reopen_descriptor_for_idx(
        &self,
        idx: usize,
    ) -> Option<ViewerContextDescriptor> {
        self.detached_viewer_context_descriptor_for_idx(idx)
    }

    #[cfg(windows)]
    fn detached_book_context_descriptor_for_grid_idx(
        &self,
        idx: usize,
    ) -> Option<ViewerContextDescriptor> {
        match self.items.get(idx)? {
            GridItem::PdfFile(path) => Some(ViewerContextDescriptor::Pdf {
                path: path.clone(),
                page_num: None,
            }),
            GridItem::ZipFile(path) => Some(ViewerContextDescriptor::Zip {
                path: path.clone(),
                entry_name: None,
                archive_source_override: None,
            }),
            _ => None,
        }
    }

    #[cfg(windows)]
    fn detached_book_context_target(
        descriptor: &ViewerContextDescriptor,
    ) -> Option<crate::snapshot::SnapshotTarget> {
        match descriptor {
            ViewerContextDescriptor::Pdf {
                path,
                page_num: Some(page_num),
            } => Some(crate::snapshot::SnapshotTarget::PdfPage {
                pdf_path: path.clone(),
                page_num: *page_num,
            }),
            ViewerContextDescriptor::Zip {
                path,
                entry_name: Some(entry_name),
                ..
            } => Some(crate::snapshot::SnapshotTarget::ZipImage {
                zip_path: path.clone(),
                entry_name: entry_name.clone(),
            }),
            _ => None,
        }
    }

    #[cfg(windows)]
    fn allocate_detached_viewer_context_generation(&mut self) -> (u64, u64) {
        let context_serial = self.next_detached_viewer_context_serial.max(1);
        self.next_detached_viewer_context_serial = self
            .next_detached_viewer_context_serial
            .wrapping_add(1)
            .max(1);
        let items_generation = DETACHED_VIEWER_CONTEXT_GENERATION_BASE
            | context_serial.wrapping_mul(DETACHED_VIEWER_CONTEXT_GENERATION_STRIDE);
        (context_serial, items_generation)
    }

    #[cfg(windows)]
    fn assign_next_detached_viewer_context_generation(&mut self) -> u64 {
        let (context_serial, items_generation) = self.allocate_detached_viewer_context_generation();
        self.set_items_generation(items_generation);
        context_serial
    }

    #[cfg(windows)]
    fn allocate_detached_viewer_window_id(&mut self) -> u64 {
        let id = self.next_detached_image_window_id.max(1);
        self.next_detached_image_window_id =
            self.next_detached_image_window_id.wrapping_add(1).max(1);
        id
    }

    // ── keep-alive session / marker helpers (docs/detached-viewer-keepalive-design.md §3.7) ──
    // session state と marker は必ずこの helper 経由で触る (直接書き換え禁止)。

    /// アクティブ detached セッションを開始 / 更新する (set)。既に同じ window_id の
    /// セッションがあれば runtime state を Active に戻して据え置く (passive→active 再開や F12 再 ON)。
    #[cfg(windows)]
    pub(crate) fn begin_active_detached_session(&mut self, window_id: u64, source: DetachedSource) {
        let current_state = self.detached_window_state(window_id);
        let changed = self
            .active_detached_session
            .map(|s| {
                s.window_id != window_id
                    || current_state == Some(DetachedWindowState::Closing)
                    || s.source != source
            })
            .unwrap_or(true);
        self.active_detached_session = Some(ActiveDetachedSession { window_id, source });
        if changed || current_state != Some(DetachedWindowState::Active) {
            self.transition_detached_window_state(
                window_id,
                DetachedWindowState::Active,
                "session_begin",
            );
            self.ensure_detached_window_runtime_placement(window_id, "session_begin_seed");
        }
        if changed {
            self.log_detached_image_window_debug(format!(
                "session_begin window_id={window_id} source={source:?}"
            ));
        }
        self.defer_pending_main_font_atlas_resync_for_detached_session("session_begin");
    }

    /// セッション終了処理を開始する (closing=true)。teardown 中は keep-alive を止めるが、
    /// 状態自体は finish まで残す。`reason` は診断用。
    #[cfg(windows)]
    pub(crate) fn begin_active_detached_session_close(&mut self, reason: &'static str) {
        if let Some(window_id) = self.active_detached_window_id()
            && self.detached_window_state(window_id) != Some(DetachedWindowState::Closing)
        {
            self.transition_detached_window_state(window_id, DetachedWindowState::Closing, reason);
            self.log_detached_image_window_debug(format!(
                "session_closing window_id={window_id} reason={reason}"
            ));
        }
    }

    /// terminal close を完了し、session と同じ window_id の runtime を一体で除去する。
    /// `Closing -> Removed` もここで所有し、font-atlas resync を stale runtime で塞がない。
    #[cfg(windows)]
    pub(crate) fn finish_active_detached_session_close(&mut self, reason: &'static str) {
        let Some(session) = self.active_detached_session.take() else {
            return;
        };
        self.log_detached_image_window_debug(format!(
            "session_finish window_id={} reason={reason}",
            session.window_id
        ));
        self.remove_detached_window_runtime(session.window_id, reason);
    }

    /// Active-to-passive is not terminal: the passive renderer keeps the runtime and OS viewport.
    #[cfg(windows)]
    fn finish_active_detached_session_handoff(&mut self, reason: &'static str) {
        if let Some(session) = self.active_detached_session.take() {
            self.log_detached_image_window_debug(format!(
                "session_handoff window_id={} reason={reason}",
                session.window_id
            ));
        }
    }

    /// 今フレーム detached 窓を生かすべきか = 唯一の述語 (§3.1)。
    #[cfg(windows)]
    pub(crate) fn detached_active_window_alive_wanted(&self) -> bool {
        self.active_detached_window_id().is_some() && !self.active_detached_window_is_closing()
    }

    /// active detached bundle が「まだ内部遷移の途中」か。
    /// このフレームで detached window を生かしておく理由が1つでもあれば true。
    ///
    /// 同じ条件列が repaint 要求 / should_drop / keep-alive の3箇所に複製されており、
    /// finalize だけが更新から取り残されて 2026-07 の「Ctrl+↓ で detached window が閉じる」
    /// 回帰を生んだ。以後 pending を増やすときはこの1箇所だけを更新すること。
    #[cfg(windows)]
    pub(crate) fn active_detached_transition_outstanding(&self) -> bool {
        self.folder_nav_pending.is_some()
            || self.folder_pane_open_pending.is_some()
            || self.pdf_enumerate_pending.is_some()
            || self.zip_enumerate_pending.is_some()
            || self.fs_nav_deferred_reopen_wait_active()
            || self.pdf_password_request.is_some()
            || matches!(
                self.bookmark_open_pending,
                Some(crate::bookmark_browser::PendingBookmarkOpen::Book(_))
            )
    }

    /// `fullscreen_viewport_id()` は active detached session が生きている間、その session の
    /// ViewportId を最優先で返す。したがってこの状態で backdrop cleanup を走らせると、
    /// 古い main/fullscreen viewport ではなく **生きている detached 窓** を隠してしまう。
    #[cfg(windows)]
    pub(crate) fn active_detached_session_owns_visible_fullscreen_viewport(&self) -> bool {
        self.detached_active_window_alive_wanted() && self.fs_viewport_shown
    }

    /// アクティブ detached の `show_viewport_immediate(detached_id, …)` を実際に呼んだ直後に
    /// 立てる marker (§3.6)。これ以外 (passive / cleanup / Close / backdrop) では呼ばない。
    #[cfg(windows)]
    pub(crate) fn mark_active_detached_viewport_rendered(&mut self) {
        self.detached_active_viewport_rendered_frame = self.frame_counter;
        if let Some(session) = self.active_detached_session {
            self.log_detached_image_window_debug(format!(
                "active_detached_immediate_rendered frame={} window_id={} viewport={:?}",
                self.frame_counter,
                session.window_id,
                Self::detached_image_window_viewport_id(session.window_id)
            ));
        }
    }

    /// 今フレーム既にアクティブ detached を描画済みか (backstop の二重描画防止)。
    #[cfg(windows)]
    pub(crate) fn active_detached_viewport_rendered_this_frame(&self) -> bool {
        self.detached_active_viewport_rendered_frame == self.frame_counter
    }

    /// 既存描画経路が `show_viewport_immediate(rendered_id, …)` を呼んだ後に使う。
    /// `rendered_id` が**現セッションの detached ViewportId と一致するときだけ** marker を立てる。
    /// gap 中に presentation が揺れて fs_id がセッション id とズレた場合は marker を立てず、
    /// backstop がセッション id を確実に描く。
    #[cfg(windows)]
    pub(crate) fn mark_active_detached_viewport_rendered_if_matches(
        &mut self,
        rendered_id: egui::ViewportId,
    ) {
        if let Some(session) = self.active_detached_session {
            if rendered_id == Self::detached_image_window_viewport_id(session.window_id) {
                self.mark_active_detached_viewport_rendered();
            }
        }
    }

    /// 現セッションの安定 detached ViewportId (backstop が描く対象)。
    #[cfg(windows)]
    pub(crate) fn active_detached_session_viewport_id(&self) -> Option<egui::ViewportId> {
        self.active_detached_session
            .map(|s| Self::detached_image_window_viewport_id(s.window_id))
    }

    /// K0 backstop は「既存の detached OS ウィンドウを描き漏れから守る」ための保険であり、
    /// F12 ON / fresh open の最初の host 生成を担当しない。初回生成は通常の active render
    /// 経路に任せないと、backstop が作った短命 host と active render が採用する host の
    /// 2 段生成になり、DWM の表示アニメーションがちらつきとして見える。
    #[cfg(windows)]
    pub(crate) fn active_detached_session_waiting_for_first_host(&self) -> bool {
        let Some(window_id) = self.active_detached_window_id() else {
            return false;
        };
        self.detached_window_hwnd_raw_for_window_id(window_id) == 0
    }

    #[cfg(windows)]
    fn ensure_detached_viewer_window_id(&mut self) -> u64 {
        if let Some(id) = self.detached_viewer_window_id {
            // この id が passive / ParkedLive 窓として detached_image_windows に居るなら
            // stale なコピー (直前の park で窓は手放したのに main 文脈側の参照が残った)。
            // 再利用すると parked 窓と新セッションが同一 window_id・同一 HWND を取り合い、
            // parked live メディア窓に画像が表示されて点滅・操作不能になる
            // (2026-07-09 実機、review-v2.3.0 checklist 中に発生。BA-7)。下の
            // last_active_detached_window_id 再利用と同じ衝突ガードを直参照側にも適用し、
            // stale なら捨てて新規 allocate へ落とす。
            if !self.detached_image_windows.iter().any(|w| w.id == id) {
                self.last_active_detached_window_id = Some(id);
                return id;
            }
            self.log_detached_image_window_debug(format!(
                "stale_window_id_dropped reason=ensure_detached_viewer_window_id id={id} \
                 (passive/parked window with same id exists)"
            ));
            self.detached_viewer_window_id = None;
        }
        // フォルダナビ (Ctrl+↑↓) の reopen は同じ detached ウィンドウの中で内容を差し替える
        // 継続操作。grid からの新規オープンでない (= !fs_open_intent_from_grid) 場合は、直前に
        // この detached セッションで使っていた window_id を再利用する。`fullscreen_viewport_id`
        // は detached では window_id 由来なので、毎回新しい id を allocate すると ViewportId が
        // 変わり、egui が OS ウィンドウを破棄→再生成してしまう (= 次フォルダへ移るたびに
        // ウィンドウ再表示 + 既定サイズ 822x656 の小窓がカスケード)。PDF/ZIP の非同期 enumerate
        // を跨いで window_id が一旦クリアされても、ここで同じ id を復元して安定させる。
        // 既に passive window として残っている id は衝突するので再利用しない (always-new mode)。
        if !self.fs_open_intent_from_grid
            && let Some(prev) = self.last_active_detached_window_id
            && !self.detached_image_windows.iter().any(|w| w.id == prev)
        {
            self.log_detached_image_window_debug(format!(
                "reuse_active_window_id reason=ensure_detached_viewer_window_id id={prev} \
                 fs_idx={:?} grid_intent={} folder_nav_reuse_once={}",
                self.fullscreen_idx,
                self.fs_open_intent_from_grid,
                self.detached_viewer_folder_nav_reuse_window_once
            ));
            self.detached_viewer_window_id = Some(prev);
            self.transition_detached_window_state(
                prev,
                DetachedWindowState::Opening,
                "ensure_detached_viewer_window_id_reuse",
            );
            return prev;
        }
        let id = self.allocate_detached_viewer_window_id();
        self.log_detached_image_window_debug(format!(
            "allocate_window_id reason=ensure_detached_viewer_window_id id={id} \
             fs_idx={:?} grid_intent={} folder_nav_reuse_once={}",
            self.fullscreen_idx,
            self.fs_open_intent_from_grid,
            self.detached_viewer_folder_nav_reuse_window_once
        ));
        self.detached_viewer_window_id = Some(id);
        self.last_active_detached_window_id = Some(id);
        self.transition_detached_window_state(
            id,
            DetachedWindowState::Opening,
            "ensure_detached_viewer_window_id_allocate",
        );
        id
    }

    #[cfg(windows)]
    fn pause_current_active_detached_viewer_context(&mut self, ctx: &egui::Context) -> bool {
        let Some(mut active) = self.active_detached_viewer_context.take() else {
            return false;
        };

        self.log_detached_image_window_debug(format!(
            "pause_active_context_begin bundle_window_id={:?} bundle_fs_idx={:?} \
             bundle_independent={} bundle_pending={} bundle_cache={} \
             bundle_passive_windows={}",
            active.bundle.viewer_session.detached_window_id,
            active.bundle.fullscreen_idx,
            active.bundle.viewer_session.independent_active,
            active.bundle.fs_pending.len(),
            active.bundle.fs_cache.len(),
            self.detached_image_windows.len()
        ));
        self.swap_viewer_context_bundle(&mut active.bundle);
        if let Some(fs_idx) = self.fullscreen_idx {
            self.reset_detached_pause_foreground_modes(fs_idx);
        }
        self.log_detached_image_window_debug(format!(
            "pause_active_context_mounted window_id={:?} fs_idx={:?} \
             independent={} session_detached={} supported={} current_pending={} \
             pending={} cache={} passive_windows={}",
            self.detached_viewer_window_id,
            self.fullscreen_idx,
            self.detached_viewer_independent_active,
            self.viewer_session_is_detached(),
            self.fullscreen_idx
                .is_some_and(|idx| self.viewer_item_supports_detached_still(idx)),
            self.fullscreen_idx
                .is_some_and(|idx| self.fs_pending.contains_key(&idx)),
            self.fs_pending.len(),
            self.fs_cache.len(),
            self.detached_image_windows.len()
        ));
        let keep_paused_bundle = true;
        let Some(mut snapshot) = self.build_active_detached_image_window_snapshot(Some(ctx)) else {
            self.log_detached_image_window_debug(format!(
                "pause_active_context_snapshot_failed keep_active=true window_id={:?} \
                 fs_idx={:?} pending={} cache={}",
                self.detached_viewer_window_id,
                self.fullscreen_idx,
                self.fs_pending.len(),
                self.fs_cache.len()
            ));
            self.swap_viewer_context_bundle(&mut active.bundle);
            self.active_detached_viewer_context = Some(active);
            return false;
        };
        let snapshot_id = snapshot.id;
        let snapshot_title = snapshot.title.clone();
        let snapshot_descriptor =
            Self::detached_viewer_descriptor_debug_kind(&snapshot.reopen_descriptor);
        let snapshot_has_stamp = snapshot.reopen_sync_stamp.is_some();
        let snapshot_frozen_pages = snapshot.frozen_continuous_pages.len();
        let snapshot_image_dims = snapshot.image_dims;
        let mut paused_bundle = self.take_current_viewer_context_bundle();
        let paused_pending_before = paused_bundle.fs_pending.len();
        let paused_cache_before = paused_bundle.fs_cache.len();
        let paused_fs_idx = paused_bundle.fullscreen_idx;
        paused_bundle.pause_background_work_keep_current_frame();
        let paused_pending_after = paused_bundle.fs_pending.len();
        let paused_cache_after = paused_bundle.fs_cache.len();
        self.swap_viewer_context_bundle(&mut active.bundle);
        if keep_paused_bundle {
            snapshot.paused_bundle = Some(Box::new(paused_bundle));
        }
        self.detached_image_windows.push(snapshot);
        self.update_detached_window_runtime_flags(
            snapshot_id,
            !keep_paused_bundle,
            "pause_active_context",
        );
        self.handoff_active_detached_viewport_to_passive("pause_active_context");
        self.transition_detached_window_state(
            snapshot_id,
            DetachedWindowState::Parked,
            "pause_active_context",
        );
        self.log_detached_image_window_debug(format!(
            "pause_active_context_snapshot_pushed id={snapshot_id} \
             title={snapshot_title:?} descriptor={snapshot_descriptor} stamp={} \
             frozen_pages={snapshot_frozen_pages} image_dims={snapshot_image_dims:?} \
             keep_bundle={keep_paused_bundle} \
             paused_fs_idx={paused_fs_idx:?} paused_pending={paused_pending_before}->{paused_pending_after} \
             paused_cache={paused_cache_before}->{paused_cache_after} passive_windows={}",
            snapshot_has_stamp,
            self.detached_image_windows.len()
        ));
        true
    }

    #[cfg(windows)]
    fn handoff_active_detached_viewport_to_passive(&mut self, reason: &'static str) {
        let session_before = self.active_detached_session;
        let shown_before = self.fs_viewport_shown;
        let presentation_before = self.fs_viewport_presentation;
        let host_before = self.detached_viewer_host_debug_state();

        // 静止画 fullscreen の auto-hide は winit の window 単位の HIDDEN flag として
        // `CursorVisible(false)` を保持する。Active -> Passive は同じ ViewportId / HWND を
        // 閉じずに描画所有者だけ切り替えるため、ここで表示復帰を予約しないと、hidden 中に
        // handoff された旧画像窓へ後からマウスを戻したときもカーソルが消えたままになる。
        // native presenter が独自管理する Video / Audio には送らず、egui がカーソルを所有する
        // Image / Book だけを対象にする。
        if let Some(session) = session_before.filter(|session| {
            matches!(session.source, DetachedSource::Image | DetachedSource::Book)
        }) {
            if !self
                .detached_image_window_cursor_show_pending
                .contains(&session.window_id)
            {
                self.detached_image_window_cursor_show_pending
                    .push(session.window_id);
            }
            // cursor auto-hide state は active viewer の状態なので、passive への所有権移管後に
            // main / 次の viewer へ持ち越さない。新規 viewer は open_fullscreen で timer を
            // 初期化するため、ここでは close_fullscreen と同じ空の baseline に戻す。
            self.cursor_last_activity = None;
            self.cursor_hidden = false;
        }

        // Active -> Passive の切替では OS viewport 自体は閉じない。active session と
        // runtime bookkeeping だけを手放し、次フレームから同じ ViewportId を passive
        // renderer が描く。ここを通常 close と同じ cleanup に流すと Visible(false) が送られ、
        // ユーザーには「ピン留め窓が消えた」ように見える。
        self.begin_active_detached_session_close(reason);
        self.finish_active_detached_session_handoff(reason);
        self.fs_viewport_shown = false;
        self.fs_viewport_presentation = None;
        self.fs_viewport_recreate_after_hide = false;
        self.detached_viewer_recreate_on_next_render = false;
        self.detached_active_viewport_rendered_frame = u64::MAX;
        self.log_detached_image_window_debug(format!(
            "active_viewport_handoff_to_passive reason={reason} session_before={session_before:?} \
             shown_before={shown_before} presentation_before={presentation_before:?} \
             host_before={host_before} passive_windows={} cursor_show_pending={:?}",
            self.detached_image_windows.len(),
            self.detached_image_window_cursor_show_pending
        ));
    }

    #[cfg(windows)]
    fn reset_detached_pause_foreground_modes(&mut self, fs_idx: usize) {
        self.spread_popup_open = false;
        self.fit_popup_open = false;
        self.slideshow_popup_open = false;
        self.cancel_mouse_ring_flick();
        self.capture_region_selection = None;
        self.clear_fullscreen_tag_picker_state();

        self.deactivate_compare_view();
        if self.panorama_state.is_some() {
            self.toggle_panorama_mode(fs_idx);
        }
        self.pano_toast_shown_for_current_fs = false;
        if self.analysis_mode {
            self.toggle_analysis_mode();
        }
        self.show_metadata_panel = false;
        self.metadata_panel_hover_active = false;
        self.fs_loupe_locked = false;

        self.persist_pending_view_trim_state();
        self.view_trim_mode = false;
        self.view_trim_page_apply_root_idx = None;
        self.view_trim_page_spread_separate = self.view_trim_book_settings.spread_separate;

        self.finish_adjustment_drag_for_detached_pause();
        self.adjustment_mode = crate::ui_helpers::MetadataPanelOpenState::Closed;
        self.cache_current_edit_preview_if_ready();
        self.local_adjust_mode = false;
        self.local_adjust_repair_point_pick_active = None;
        self.local_adjust_add_layer_dialog_open = false;
        self.local_adjust_change_mask_dialog_open = false;
        self.local_adjust_change_mask_keep_manual_override = true;
        self.local_adjust_effect_picker_dialog_open = false;
        self.local_adjust_canvas_drag = None;
        self.local_adjust_mask_brush_stroke = None;
        self.local_adjust_mask_lasso_points.clear();
        self.local_adjust_mask_shape_drag_start = None;
        self.local_adjust_mask_shape_drag_end = None;
        self.local_adjust_selected_shape = None;
        self.local_adjust_shape_drag = None;
        self.local_adjust_canvas_drag_before_layers = None;
        self.local_adjust_shape_drag_before_layers = None;
        self.local_adjust_mask_brush_before_layers = None;
        self.local_adjust_brush_deferred_render = None;
        self.local_adjust_lut_pending = None;
        self.local_adjust_segmentation_pending = None;
        self.cancel_all_local_adjust_pending();

        if self.erase_mode {
            self.reset_erase_mode();
        }
        if self.conceal_mode {
            self.reset_conceal_mode();
        }
        if self.text_mode {
            self.text_spread_ctx = None;
            self.reset_text_mode();
        }
        if self.export_crop_mode {
            self.export_crop_spread_ctx = None;
            self.reset_export_crop_mode();
        }
    }

    #[cfg(windows)]
    fn finish_adjustment_drag_for_detached_pause(&mut self) {
        self.adjustment_dragging = false;
        if let Some(session) = self.adjustment_drag_session.take() {
            let in_memory = self.adjustment_page_params.get(&session.fs_idx).cloned();
            if session.before != in_memory {
                if let Some(params) = in_memory.clone() {
                    self.set_page_params(session.fs_idx, params);
                } else {
                    self.clear_page_params(session.fs_idx);
                }
                let after = self.adjustment_page_params.get(&session.fs_idx).cloned();
                self.capture_adjustment_undo(
                    crate::undo_stack::AdjustUndoScope::Page(session.fs_idx),
                    session.before,
                    after,
                    "ページ個別の補正".to_string(),
                );
            }
        }
    }

    #[cfg(windows)]
    fn take_and_close_current_active_detached_viewer_context(
        &mut self,
        ctx: &egui::Context,
        reason: &'static str,
    ) -> Option<ViewerContextBundle> {
        let Some(mut active) = self.active_detached_viewer_context.take() else {
            return None;
        };

        // book context の明示 close = detached セッション終了 (§3.7 closing)。Close 送信前に
        // closing を立て、teardown 後に finish して backstop が窓を復活させないようにする。
        self.begin_active_detached_session_close(reason);
        self.swap_viewer_context_bundle(&mut active.bundle);
        if self.fs_viewport_shown {
            let fs_id = self.fullscreen_viewport_id();
            ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Close);
        }
        self.close_fullscreen();
        let closed_context = self.take_current_viewer_context_bundle();
        self.swap_viewer_context_bundle(&mut active.bundle);
        self.finish_active_detached_session_close(reason);
        // PDF password dialog の UI state 自体は App-global だが、request owner は bundle。
        // viewport 作成前の terminal close で owner を捨てた後に orphan dialog を残さない。
        if closed_context.pdf_password_request.is_some() && self.pdf_password_request.is_none() {
            self.show_pdf_password_dialog = false;
            self.pdf_password_input.clear();
            self.pdf_password_error = None;
            self.pdf_password_save = false;
        }
        Some(closed_context)
    }

    #[cfg(windows)]
    fn close_current_active_detached_viewer_context(&mut self, ctx: &egui::Context) -> bool {
        self.take_and_close_current_active_detached_viewer_context(
            ctx,
            "close_active_detached_viewer_context",
        )
        .is_some()
    }

    #[cfg(windows)]
    pub(crate) fn close_all_detached_viewers_for_mode_change(
        &mut self,
        ctx: &egui::Context,
    ) -> bool {
        let had_detached = self.active_detached_viewer_context.is_some()
            || self.active_detached_session.is_some()
            || self.viewer_session_is_detached_or_switching()
            || self.fs_viewport_presentation == Some(ViewerPresentation::DetachedWindow)
            || self.fs_viewport_shown
            || !self.detached_image_windows.is_empty()
            || !self.detached_window_manager.is_empty()
            || self.pending_detached_video_host_switch.is_some()
            || self.pending_detached_video_host_resync;
        if !had_detached {
            return false;
        }

        self.log_detached_image_window_debug(format!(
            "mode_change_close_all begin active_context={} session={:?} fs_idx={:?} \
             presentation={:?} shown={} passive_windows={} runtimes={} pending_host_switch={}",
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session,
            self.fullscreen_idx,
            self.viewer_presentation,
            self.fs_viewport_shown,
            self.detached_image_windows.len(),
            self.detached_window_manager.len(),
            self.pending_detached_video_host_switch.is_some()
        ));
        crate::dwm_transitions::disable_transitions_for_thread_windows();

        let active_context_window_id = self
            .active_detached_viewer_context
            .as_ref()
            .and_then(|active| active.bundle.viewer_session.detached_window_id);
        if let Some(window_id) = active_context_window_id {
            ctx.send_viewport_cmd_to(
                Self::detached_image_window_viewport_id(window_id),
                egui::ViewportCommand::Close,
            );
        }
        if self.active_detached_viewer_context.is_some() {
            let _ = self.close_current_active_detached_viewer_context(ctx);
        }

        let active_window_id = self
            .active_detached_session
            .map(|session| session.window_id)
            .or(self.detached_viewer_window_id)
            .or(self.last_active_detached_window_id);
        if self.viewer_session_is_detached_or_switching()
            || self.fs_viewport_presentation == Some(ViewerPresentation::DetachedWindow)
            || self.fs_viewport_shown
        {
            let viewport_id = active_window_id
                .map(Self::detached_image_window_viewport_id)
                .unwrap_or_else(|| self.fullscreen_viewport_id());
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Close);
            if let Some(window_id) = active_window_id {
                self.transition_detached_window_state(
                    window_id,
                    DetachedWindowState::Closing,
                    "mode_change_close_all_active",
                );
                self.clear_detached_window_hwnd_for_window_id(window_id);
            }
            self.begin_active_detached_session_close("mode_change_close_all_active");
            self.finish_active_detached_session_close("mode_change_close_all_active");
            if self.fullscreen_idx.is_some() {
                self.close_fullscreen();
            } else {
                self.fs_viewport_shown = false;
                self.fs_viewport_presentation = None;
                self.fs_viewport_recreate_after_hide = false;
                self.detached_viewer_recreate_on_next_render = false;
                self.clear_detached_viewer_host_hwnd();
            }
        }

        let passive_ids = self
            .detached_image_windows
            .iter()
            .map(|window| window.id)
            .collect::<Vec<_>>();
        for id in &passive_ids {
            self.transition_detached_window_state(
                *id,
                DetachedWindowState::Closing,
                "mode_change_close_all_passive",
            );
            self.clear_detached_window_hwnd_for_window_id(*id);
            ctx.send_viewport_cmd_to(
                Self::detached_image_window_viewport_id(*id),
                egui::ViewportCommand::Close,
            );
        }
        self.teardown_paused_media_bundles_for_window_ids(
            &passive_ids,
            "mode_change_close_all_passive",
        );
        self.detached_image_windows.clear();
        self.deferred_detached_image_window_views.clear();
        self.native_video_parked_live_activation_requests.clear();
        self.native_video_parked_live_left_down_window_id = None;
        self.native_video_parked_live_input_window_id = None;

        let runtime_ids = self.detached_window_manager.ids();
        for id in runtime_ids {
            if self.detached_window_state(id) != Some(DetachedWindowState::Closing) {
                self.transition_detached_window_state(
                    id,
                    DetachedWindowState::Closing,
                    "mode_change_close_all_runtime",
                );
            }
            self.remove_detached_window_runtime(id, "mode_change_close_all_runtime");
        }

        self.active_detached_session = None;
        self.active_detached_viewer_context = None;
        self.pending_detached_video_host_switch = None;
        self.pending_detached_video_host_resync = false;
        self.detached_viewer_window_id = None;
        self.last_active_detached_window_id = None;
        self.detached_viewer_independent_active = false;
        self.detached_viewer_open_next_still_detached_once = false;
        self.detached_viewer_folder_nav_reuse_window_once = false;
        self.detached_viewer_focus_requested = false;
        self.detached_viewer_no_activate_once = false;
        self.fs_open_intent_from_grid = false;
        self.fs_viewport_shown = false;
        self.fs_viewport_presentation = None;
        self.fs_viewport_recreate_after_hide = false;
        self.detached_viewer_recreate_on_next_render = false;
        self.clear_detached_viewer_host_hwnd();
        self.clear_detached_viewer_borderless_fullscreen_state();
        self.request_detached_cleanup_font_atlas_resync("mode_change_close_all");
        self.focus_main_after_detached_window_close_if_idle(ctx, "mode_change_close_all");
        ctx.request_repaint();
        self.log_detached_image_window_debug(format!(
            "mode_change_close_all end active_context={} session={:?} fs_idx={:?} \
             presentation={:?} shown={} passive_windows={} runtimes={}",
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session,
            self.fullscreen_idx,
            self.viewer_presentation,
            self.fs_viewport_shown,
            self.detached_image_windows.len(),
            self.detached_window_manager.len()
        ));
        true
    }

    #[cfg(windows)]
    pub(crate) fn detached_image_window_debug_enabled() -> bool {
        static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        *ENABLED.get_or_init(|| std::env::var_os("MIV_DETACHED_WINDOW_DEBUG").is_some())
    }

    #[cfg(windows)]
    pub(crate) fn log_detached_image_window_debug(&self, message: impl AsRef<str>) {
        if Self::detached_image_window_debug_enabled() {
            crate::logger::log(format!("[detached-window-debug] {}", message.as_ref()));
        }
    }

    #[cfg(windows)]
    pub(crate) fn log_detached_viewport_placement_event(
        &self,
        source: &'static str,
        event: &'static str,
        detail: impl AsRef<str>,
    ) {
        if !Self::detached_image_window_debug_enabled() {
            return;
        }
        self.log_detached_image_window_debug(format!(
            "placement_trace source={source} event={event} frame={} fs_idx={:?} \
             presentation={:?} fs_presentation={:?} session={:?} host=\"{}\" {}",
            self.frame_counter,
            self.fullscreen_idx,
            self.viewer_presentation,
            self.fs_viewport_presentation,
            self.active_detached_session,
            self.detached_viewer_host_debug_state(),
            detail.as_ref()
        ));
    }

    #[cfg(windows)]
    pub(crate) fn main_flash_probe_interesting(&self) -> bool {
        Self::detached_image_window_debug_enabled()
            && (self.fullscreen_idx.is_some()
                || self.fs_viewport_shown
                || self.viewer_session_is_detached_or_switching()
                || self.pending_detached_video_host_switch.is_some()
                || self.native_video_mode_switch.is_some()
                || self.active_detached_viewer_context.is_some()
                || !self.detached_image_windows.is_empty())
    }

    #[cfg(windows)]
    pub(crate) fn log_main_flash_probe(&self, stage: &'static str, detail: impl AsRef<str>) {
        if !self.main_flash_probe_interesting() {
            return;
        }
        self.log_detached_image_window_debug(format!(
            "main_flash_probe stage={stage} frame={} fs_idx={:?} presentation={:?} \
             fs_shown={} fs_viewport_presentation={:?} session={:?} active_context={} \
             passive_windows={} native_backdrop={} main_cloaked={} window_visible={} \
             details={}",
            self.frame_counter,
            self.fullscreen_idx,
            self.viewer_presentation,
            self.fs_viewport_shown,
            self.fs_viewport_presentation,
            self.active_detached_session,
            self.active_detached_viewer_context.is_some(),
            self.detached_image_windows.len(),
            self.native_video_fullscreen_active_for_main_backdrop(),
            self.native_video_main_cloaked,
            self.window_visible,
            detail.as_ref()
        ));
    }

    #[cfg(windows)]
    pub(crate) fn active_detached_hwnd_window_id(&self) -> Option<u64> {
        self.native_video_parked_live_input_window_id
            .or_else(|| {
                self.active_detached_session
                    .map(|session| session.window_id)
            })
            .or(self.detached_viewer_window_id)
            .or_else(|| {
                (self.viewer_session_is_detached_or_switching()
                    || self.fs_viewport_presentation == Some(ViewerPresentation::DetachedWindow))
                .then_some(self.last_active_detached_window_id)
                .flatten()
            })
    }

    #[cfg(windows)]
    pub(crate) fn detached_window_hwnd_alive_for_window_id(&self, window_id: u64) -> Option<u64> {
        self.detached_window_hwnd_alive(window_id)
    }

    #[cfg(windows)]
    pub(crate) fn clear_detached_window_hwnd_for_window_id(
        &mut self,
        window_id: u64,
    ) -> Option<u64> {
        let cleared = self.detached_window_hwnd_clear(window_id);
        if cleared.is_some()
            && let Some(window) = self
                .detached_image_windows
                .iter_mut()
                .find(|window| window.id == window_id)
        {
            window.initial_placement_applied = false;
        }
        cleared
    }

    #[cfg(windows)]
    pub(crate) fn detached_window_hwnd_raw_for_window_id(&self, window_id: u64) -> u64 {
        self.detached_window_hwnd_get_raw(window_id).unwrap_or(0)
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_host_hwnd_raw(&self) -> u64 {
        self.active_detached_hwnd_window_id()
            .map(|window_id| self.detached_window_hwnd_raw_for_window_id(window_id))
            .unwrap_or(0)
    }

    #[cfg(windows)]
    pub(crate) fn detached_window_hwnd_snapshot_before_show(
        &mut self,
        window_id: u64,
        label: &'static str,
        viewport_id: egui::ViewportId,
    ) -> Option<Vec<crate::dwm_transitions::ThreadWindowSnapshotEntry>> {
        if self.detached_window_hwnd_alive(window_id).is_some() {
            return None;
        }
        if let Some(dead_hwnd) = self.detached_window_hwnd_clear_if_dead(window_id) {
            self.log_detached_image_window_debug(format!(
                "detached_hwnd_dead window_id={window_id} hwnd=0x{dead_hwnd:x} \
                 label={label} viewport={viewport_id:?}"
            ));
            if self.detached_video_presentation_active_or_targeted() {
                self.pending_detached_video_host_resync = true;
            }
        }
        self.begin_detached_window_hwnd_registration(window_id, label);
        let main_hwnd = self.main_hwnd?;
        let snapshot = crate::dwm_transitions::thread_window_snapshot(
            windows::Win32::Foundation::HWND(main_hwnd as *mut _),
        );
        if Self::detached_image_window_debug_enabled() && self.frame_counter % 60 == 0 {
            self.log_detached_image_window_debug(format!(
                "hwnd_diff_before label={label} frame={} window_id={window_id} \
                 viewport={viewport_id:?} count={} host={}",
                self.frame_counter,
                snapshot.len(),
                self.detached_viewer_host_debug_state()
            ));
        }
        Some(snapshot)
    }

    #[cfg(windows)]
    pub(crate) fn register_detached_window_hwnd_after_show(
        &mut self,
        window_id: u64,
        label: &'static str,
        viewport_id: egui::ViewportId,
        before: Option<&[crate::dwm_transitions::ThreadWindowSnapshotEntry]>,
    ) {
        let Some(before) = before else {
            self.recover_detached_window_hwnd_after_skipped_snapshot(window_id, label, viewport_id);
            return;
        };
        let Some(main_hwnd) = self.main_hwnd else {
            return;
        };
        let after = crate::dwm_transitions::thread_window_snapshot(
            windows::Win32::Foundation::HWND(main_hwnd as *mut _),
        );
        match Self::select_detached_created_hwnd(before, &after) {
            DetachedWindowHwndDiff::Created(hwnd) => {
                let previous = self.detached_window_hwnd_set(window_id, hwnd);
                let state = self.detached_window_state_for_show_label(window_id, label);
                self.transition_detached_window_state(window_id, state, "hwnd_registered");
                self.detached_viewer_host_generation =
                    self.detached_viewer_host_generation.saturating_add(1);
                crate::logger::log(format!(
                    "[detached-viewer] registered host hwnd=0x{hwnd:x} \
                     host_generation={} frame={} window_id={window_id} label={label} \
                     viewport={viewport_id:?} old={} new_state=\"{}\"",
                    self.detached_viewer_host_generation,
                    self.frame_counter,
                    previous
                        .map(|old| format!("0x{old:x}"))
                        .unwrap_or_else(|| "none".to_string()),
                    Self::win32_hwnd_debug_state(hwnd)
                ));
                self.try_resync_detached_video_host_after_registration(window_id);
            }
            DetachedWindowHwndDiff::NoChange => {
                if self.adopt_unclaimed_detached_window_hwnd_after_show(
                    window_id,
                    label,
                    viewport_id,
                    &after,
                    None,
                ) {
                    return;
                }
                self.log_detached_image_window_debug(format!(
                    "hwnd_diff_retry label={label} frame={} window_id={window_id} \
                     viewport={viewport_id:?} reason=no_new_window before_count={} \
                     after_count={} host={}",
                    self.frame_counter,
                    before.len(),
                    after.len(),
                    self.detached_viewer_host_debug_state()
                ));
            }
            DetachedWindowHwndDiff::Ambiguous(candidates) => {
                self.log_detached_image_window_debug(format!(
                    "hwnd_diff_retry label={label} frame={} window_id={window_id} \
                     viewport={viewport_id:?} reason=ambiguous candidates={candidates:x?} \
                     before_count={} after_count={} host={}",
                    self.frame_counter,
                    before.len(),
                    after.len(),
                    self.detached_viewer_host_debug_state()
                ));
            }
        }
    }

    #[cfg(windows)]
    fn recover_detached_window_hwnd_after_skipped_snapshot(
        &mut self,
        window_id: u64,
        label: &'static str,
        viewport_id: egui::ViewportId,
    ) {
        let Some(previous_hwnd) = self.detached_window_hwnd_get_raw(window_id) else {
            return;
        };
        if self.detached_window_hwnd_is_alive(previous_hwnd) {
            return;
        }
        self.detached_window_hwnd_clear(window_id);
        self.begin_detached_window_hwnd_registration(window_id, label);
        self.log_detached_image_window_debug(format!(
            "detached_hwnd_dead_after_show window_id={window_id} hwnd=0x{previous_hwnd:x} \
             label={label} viewport={viewport_id:?}"
        ));
        if self.detached_video_presentation_active_or_targeted() {
            self.pending_detached_video_host_resync = true;
        }

        let Some(main_hwnd) = self.main_hwnd else {
            self.log_detached_image_window_debug(format!(
                "hwnd_unclaimed_retry label={label} frame={} window_id={window_id} \
                 viewport={viewport_id:?} reason=no_main_hwnd old=0x{previous_hwnd:x} host={}",
                self.frame_counter,
                self.detached_viewer_host_debug_state()
            ));
            return;
        };
        let after = crate::dwm_transitions::thread_window_snapshot(
            windows::Win32::Foundation::HWND(main_hwnd as *mut _),
        );
        self.adopt_unclaimed_detached_window_hwnd_after_show(
            window_id,
            label,
            viewport_id,
            &after,
            Some(previous_hwnd),
        );
    }

    #[cfg(windows)]
    fn detached_viewer_descriptor_debug_kind(
        descriptor: &Option<ViewerContextDescriptor>,
    ) -> &'static str {
        match descriptor {
            Some(ViewerContextDescriptor::Pdf { .. }) => "pdf",
            Some(ViewerContextDescriptor::Zip { .. }) => "zip",
            Some(ViewerContextDescriptor::BookFolder { .. }) => "book-folder",
            Some(ViewerContextDescriptor::Image { .. }) => "image",
            None => "none",
        }
    }

    #[cfg(windows)]
    fn grid_item_debug_kind(&self, idx: usize) -> &'static str {
        match self.items.get(idx) {
            Some(GridItem::Image(_)) => "image",
            Some(GridItem::ZipImage { .. }) => "zip-image",
            Some(GridItem::PdfPage { .. }) => "pdf-page",
            Some(GridItem::Video(_)) => "video",
            Some(GridItem::Audio(_)) => "audio",
            Some(GridItem::Folder(_)) => "folder",
            Some(GridItem::ZipFile(_)) => "zip-file",
            Some(GridItem::PdfFile(_)) => "pdf-file",
            Some(GridItem::ZipDir { .. }) => "zip-dir",
            Some(GridItem::Stack { .. }) => "stack",
            Some(GridItem::SearchContainer { .. }) => "search-container",
            Some(GridItem::ConvertibleArchive { .. }) => "convertible-archive",
            None => "missing",
        }
    }

    #[cfg(windows)]
    pub(crate) fn remember_active_detached_viewport_render_probe(
        &mut self,
        outer_rect: egui::Rect,
        pixels_per_point: f32,
    ) {
        self.detached_viewer_last_outer_rect = Some(outer_rect);
        self.detached_viewer_last_pixels_per_point = pixels_per_point;
        self.detached_viewer_last_render_frame = self.frame_counter;
        self.detached_viewer_last_render_at = Some(std::time::Instant::now());
    }

    #[cfg(windows)]
    fn format_optional_duration_ms(value: Option<std::time::Duration>) -> String {
        value
            .map(|duration| format!("{:.1}", duration.as_secs_f64() * 1000.0))
            .unwrap_or_else(|| "none".to_string())
    }

    #[cfg(windows)]
    pub(crate) fn active_detached_viewer_context_present(&self) -> bool {
        self.active_detached_viewer_context.is_some()
    }

    #[cfg(windows)]
    fn viewer_context_bundle_contains_video(bundle: &ViewerContextBundle) -> bool {
        let active_item_is_video = bundle
            .fullscreen_idx
            .and_then(|idx| bundle.items.get(idx))
            .is_some_and(|item| matches!(item, GridItem::Video(_)));
        let deferred_item_is_media = bundle.vst3_deferred_media_open.is_some_and(|idx| {
            bundle.fullscreen_idx == Some(idx)
                && matches!(
                    bundle.items.get(idx),
                    Some(GridItem::Video(_) | GridItem::Audio(_))
                )
        });
        active_item_is_video
            || deferred_item_is_media
            || bundle
                .fs_cache
                .values()
                .any(|entry| matches!(entry, FsCacheEntry::Video { .. }))
    }

    #[cfg(windows)]
    fn viewer_context_bundle_detached_source(bundle: &ViewerContextBundle) -> DetachedSource {
        match bundle.fullscreen_idx.and_then(|idx| bundle.items.get(idx)) {
            Some(GridItem::Audio(_)) => DetachedSource::Audio,
            Some(GridItem::Video(_)) => DetachedSource::Video,
            _ if Self::viewer_context_bundle_contains_video(bundle) => DetachedSource::Video,
            _ => DetachedSource::Book,
        }
    }

    #[cfg(windows)]
    fn viewer_context_bundle_music_window_info(
        &self,
        bundle: &ViewerContextBundle,
    ) -> Option<ParkedLiveMusicWindowInfo> {
        let idx = bundle.fullscreen_idx?;
        let item = bundle.items.get(idx)?;
        let video_audio_mode = bundle.video_audio_mode == Some(idx)
            && !bundle
                .video_audio_vst
                .as_ref()
                .is_some_and(|s| s.fs_idx == idx);
        if !Self::viewer_context_bundle_is_music_consumer(bundle) {
            return None;
        }
        let (position_secs, duration_secs, playing, title, volume, muted) =
            match bundle.fs_cache.get(&idx) {
                Some(FsCacheEntry::Video { player, .. }) => (
                    player.position().max(0.0),
                    player.duration().max(0.0),
                    player.is_playing(),
                    player
                        .info()
                        .and_then(|i| i.title.clone())
                        .filter(|t| !t.trim().is_empty())
                        .unwrap_or_else(|| item.name().to_string()),
                    player.volume(),
                    player.is_muted(),
                ),
                _ => (0.0, 0.0, false, item.name().to_string(), 1.0, false),
            };
        let bookmark_secs: Vec<f64> = bundle.music_bookmarks.iter().map(|b| b.pts_secs).collect();
        Some(ParkedLiveMusicWindowInfo {
            fs_idx: idx,
            title,
            position_secs,
            duration_secs,
            playing,
            video_audio_mode,
            playback_speed: self.video_playback_speed,
            volume,
            muted,
            loop_mode: self.settings.video_loop_mode,
            continuous_mode: self.video_continuous_mode,
            row_secs: self.music_timeline_row_secs,
            normalize_ui_state: bundle
                .normalize_ui_states
                .get(&idx)
                .copied()
                .unwrap_or_default(),
            bookmark_secs,
            bookmarks_loaded: bundle.music_bookmarks_loaded_for.is_some(),
        })
    }

    #[cfg(windows)]
    pub(crate) fn active_detached_viewer_context_contains_video(&self) -> bool {
        self.active_detached_viewer_context
            .as_ref()
            .is_some_and(|active| Self::viewer_context_bundle_contains_video(&active.bundle))
    }

    #[cfg(windows)]
    pub(crate) fn current_viewer_context_contains_video(&self) -> bool {
        let active_item_is_video = self
            .fullscreen_idx
            .and_then(|idx| self.items.get(idx))
            .is_some_and(|item| matches!(item, GridItem::Video(_)));
        let deferred_item_is_media = self.vst3_deferred_media_open.is_some_and(|idx| {
            self.fullscreen_idx == Some(idx)
                && matches!(
                    self.items.get(idx),
                    Some(GridItem::Video(_) | GridItem::Audio(_))
                )
        });
        active_item_is_video
            || deferred_item_is_media
            || self
                .fs_cache
                .values()
                .any(|entry| matches!(entry, FsCacheEntry::Video { .. }))
    }

    #[cfg(windows)]
    fn current_music_fullscreen_idx(&self) -> Option<usize> {
        let idx = self.fullscreen_idx?;
        let is_audio_file = self
            .items
            .get(idx)
            .is_some_and(|item| matches!(item, GridItem::Audio(_)));
        (is_audio_file || self.video_audio_mode_hides_native_presenter_for(idx)).then_some(idx)
    }

    #[cfg(windows)]
    pub(crate) fn parked_live_music_window_info_for_window_id(
        &self,
        window_id: u64,
    ) -> Option<ParkedLiveMusicWindowInfo> {
        self.detached_image_windows
            .iter()
            .find(|window| window.id == window_id)
            .and_then(|window| window.paused_bundle.as_deref())
            .and_then(|bundle| self.viewer_context_bundle_music_window_info(bundle))
    }

    #[cfg(windows)]
    fn update_parked_live_audio_music_view_state(&mut self, ctx: &egui::Context) {
        let Some(fs_idx) = self.current_music_fullscreen_idx() else {
            return;
        };
        if let Some(path) = self.fs_music_source_for_idx(fs_idx) {
            let meta = self.image_metas.get(fs_idx).copied().flatten();
            self.ensure_music_analysis(&path, meta);
            self.ensure_music_bookmarks_loaded(&path);
        }
        self.poll_music_analysis(ctx);
        let (pos, playing) = match self.fs_cache.get(&fs_idx) {
            Some(FsCacheEntry::Video { player, .. }) => {
                (player.position().max(0.0), player.is_playing())
            }
            _ => (0.0, false),
        };
        let pcm = self.music_pcm.clone();
        self.music_spectrum.update(ctx, pcm.as_ref(), pos, playing);
    }

    #[cfg(windows)]
    pub(crate) fn detached_window_state_is_parked_live(&self, window_id: u64) -> bool {
        self.detached_window_state(window_id) == Some(DetachedWindowState::ParkedLive)
    }

    #[cfg(windows)]
    fn parked_live_media_window_ids(&self) -> Vec<u64> {
        self.detached_image_windows
            .iter()
            .filter(|window| {
                self.detached_window_state_is_parked_live(window.id)
                    && window
                        .paused_bundle
                        .as_deref()
                        .is_some_and(Self::viewer_context_bundle_contains_video)
            })
            .map(|window| window.id)
            .collect()
    }

    #[cfg(windows)]
    pub(crate) fn parked_live_media_window_exists(&self) -> bool {
        self.detached_image_windows.iter().any(|window| {
            self.detached_window_state_is_parked_live(window.id)
                && window
                    .paused_bundle
                    .as_deref()
                    .is_some_and(Self::viewer_context_bundle_contains_video)
        })
    }

    /// active / ParkedLive の別メディア窓が音楽ビューを所有しているか。
    /// music_* は bundle に入れない App-global 状態なので、別窓の bundle が参照中は
    /// main 文脈の open/close から破棄してはいけない (review-v2.3.0 P2-3)。
    #[cfg(windows)]
    pub(crate) fn detached_music_window_exists(&self) -> bool {
        self.active_detached_viewer_context
            .as_ref()
            .is_some_and(|active| {
                self.viewer_context_bundle_music_window_info(&active.bundle)
                    .is_some()
            })
            || self.detached_image_windows.iter().any(|window| {
                self.detached_window_state_is_parked_live(window.id)
                    && window.paused_bundle.as_deref().is_some_and(|bundle| {
                        self.viewer_context_bundle_music_window_info(bundle)
                            .is_some()
                    })
            })
    }

    #[cfg(windows)]
    fn viewer_context_bundle_is_music_consumer(bundle: &ViewerContextBundle) -> bool {
        viewer_context_bundle_is_music_consumer(bundle)
    }

    /// App-global な tile companion が、閉じる ParkedLive 窓のものかを判定する。
    /// owner stamp がある tile/source-swap pending を最優先し、pending が無い完成済み
    /// tile は bundle の表示動画 path と「他に video context が無い」事実で帰属を決める。
    /// これにより無関係な mounted tile state を巻き込まない。
    /// (review-v2.3.0 追補3: 角度A-2)
    #[cfg(windows)]
    fn parked_window_owns_video_tile_companion(&self, window_id: u64) -> bool {
        let explicit_owner = self
            .video_tile_swap_pending
            .as_ref()
            .is_some_and(|pending| pending.parked_live_window_id == Some(window_id))
            || self
                .native_video_source_swap_pending
                .as_ref()
                .is_some_and(|pending| {
                    pending.reason == "tile" && pending.parked_live_window_id == Some(window_id)
                });
        if explicit_owner {
            return true;
        }
        // 別 owner (None = mounted を含む) の tile pending があるなら companion はそちら。
        if self.video_tile_swap_pending.is_some()
            || self
                .native_video_source_swap_pending
                .as_ref()
                .is_some_and(|pending| pending.reason == "tile")
        {
            return false;
        }
        if !self.video_tile_mode_active
            && !self.video_tile_reopen_pending
            && self.video_tile_state.is_none()
        {
            return false;
        }

        let bundle_video_path = self
            .detached_image_windows
            .iter()
            .find(|window| window.id == window_id)
            .and_then(|window| window.paused_bundle.as_deref())
            .and_then(|bundle| {
                bundle
                    .fullscreen_idx
                    .and_then(|idx| bundle.items.get(idx))
                    .and_then(|item| match item {
                        GridItem::Video(path) => Some(path.as_path()),
                        _ => None,
                    })
            });
        let Some(bundle_video_path) = bundle_video_path else {
            return false;
        };
        if self.current_viewer_context_contains_video()
            || self.active_detached_viewer_context_contains_video()
        {
            return false;
        }
        let another_parked_video_exists = self.detached_image_windows.iter().any(|window| {
            window.id != window_id
                && window.paused_bundle.as_deref().is_some_and(|bundle| {
                    bundle
                        .fullscreen_idx
                        .and_then(|idx| bundle.items.get(idx))
                        .is_some_and(|item| matches!(item, GridItem::Video(_)))
                })
        });
        if another_parked_video_exists {
            return false;
        }
        self.video_tile_state
            .as_ref()
            .is_none_or(|state| crate::folder_tree::path_eq(&state.video_path, bundle_video_path))
    }

    /// owner stamp を持たない `native_video_mode_switch` が、まとめて閉じる ParkedLive 群の
    /// player だけに帰属すると確定できるか。残すと最長 5 秒、font-atlas settle と native
    /// control availability を塞ぐ。別の mounted/active/surviving parked video があれば
    /// owner を断定できないので温存する。(review-v2.3.0 追補4: mode-switch teardown)
    #[cfg(windows)]
    fn closing_parked_windows_own_native_video_mode_switch(&self, window_ids: &[u64]) -> bool {
        if self.native_video_mode_switch.is_none()
            || self.current_viewer_context_contains_video()
            || self.active_detached_viewer_context_contains_video()
        {
            return false;
        }
        let closing_has_video = self.detached_image_windows.iter().any(|window| {
            window_ids.contains(&window.id)
                && window
                    .paused_bundle
                    .as_deref()
                    .is_some_and(Self::viewer_context_bundle_contains_video)
        });
        closing_has_video
            && !self.detached_image_windows.iter().any(|window| {
                !window_ids.contains(&window.id)
                    && window
                        .paused_bundle
                        .as_deref()
                        .is_some_and(Self::viewer_context_bundle_contains_video)
            })
    }

    /// ParkedLive / passive 窓が所有する bundle を drop する直前のメディア後始末。
    /// fs_idx は context ごとに別空間なので App-global normalize は path で照合する。
    /// (review-v2.3.0 追補 BA-7: parked teardown)
    #[cfg(windows)]
    pub(crate) fn teardown_paused_media_bundles_for_window_ids(
        &mut self,
        window_ids: &[u64],
        reason: &'static str,
    ) {
        let clears_tile_companion = window_ids
            .iter()
            .any(|&window_id| self.parked_window_owns_video_tile_companion(window_id));
        let clears_mode_switch =
            self.closing_parked_windows_own_native_video_mode_switch(window_ids);
        // bundle が既に外されていても、App-global pending の owner は window id で残り得る。
        // teardown seam で先に破棄して presenter/output を孤児化させない。
        // (review-v2.3.0 追補2 BA-7: parked pending teardown)
        for &window_id in window_ids {
            self.discard_parked_native_video_pending_for_window(window_id, reason);
            self.cancel_media_navigation_pending_for_owner(Some(window_id), reason);
        }
        if clears_tile_companion {
            // tile state/reopen/deadline は bundle 外の companion。所有窓の teardown と同時に
            // 畳み、次の動画 open へ tile overlay を持ち越さない (追補3: 角度A-2)。
            self.video_tile_state = None;
            self.video_tile_mode_active = false;
            self.video_tile_reopen_pending = false;
            self.video_tile_reopen_deadline = None;
            self.native_video_deferred_nav_delta = None;
        }
        if clears_mode_switch {
            self.native_video_mode_switch = None;
        }
        let mut dropped_bundles = Vec::new();
        for window in &mut self.detached_image_windows {
            if window_ids.contains(&window.id)
                && let Some(bundle) = window.paused_bundle.take()
            {
                dropped_bundles.push(bundle);
            }
        }
        self.teardown_paused_media_bundles(dropped_bundles, reason);
    }

    #[cfg(windows)]
    fn teardown_paused_media_bundles(
        &mut self,
        mut dropped_bundles: Vec<Box<ViewerContextBundle>>,
        reason: &'static str,
    ) {
        if dropped_bundles.is_empty() {
            return;
        }
        let plans: Vec<ViewerContextMediaTeardownPlan> = dropped_bundles
            .iter()
            .map(|bundle| viewer_context_media_teardown_plan(bundle))
            .collect();
        self.save_viewer_context_media_teardown_resumes(&plans);
        self.cleanup_viewer_context_media_teardown_globals(&plans, reason);
        for bundle in &mut dropped_bundles {
            bundle.normalize_ui_states.clear();
            bundle.normalize_auto_scan_suppressed.clear();
        }
    }

    #[cfg(windows)]
    fn save_viewer_context_media_teardown_resumes(
        &mut self,
        plans: &[ViewerContextMediaTeardownPlan],
    ) {
        let updates: Vec<MediaResumeUpdate> = plans
            .iter()
            .flat_map(|plan| plan.resume_updates.iter().cloned())
            .collect();
        let removed = apply_viewer_context_media_resume_updates(
            &mut self.settings.video_resume_positions,
            &updates,
        );
        for key in removed {
            self.video_resume_thumb_last_request.remove(&key);
        }
        for update in &updates {
            if self
                .settings
                .video_resume_positions
                .contains_key(&update.key)
            {
                self.maybe_schedule_video_resume_thumbnail(
                    &update.path,
                    &update.key,
                    update.position,
                );
            }
        }
    }

    /// Tray hide/restore の presenter visibility を全 viewer context へ同じ ownership で配る。
    /// Transport は変更せず、native output の typed visibility queue だけを遷移させる。
    #[cfg(windows)]
    pub(crate) fn sync_media_presenter_visibility_for_tray(&self, app_visible: bool) -> usize {
        let mounted_music_consumer = self.fullscreen_idx.is_some_and(|idx| {
            let standalone_audio_without_vst =
                matches!(self.items.get(idx), Some(GridItem::Audio(_)))
                    && !self
                        .music_vst_shell
                        .as_ref()
                        .is_some_and(|shell| shell.fs_idx == idx);
            let video_audio_mode_without_vst = self.video_audio_mode == Some(idx)
                && !self
                    .video_audio_vst
                    .as_ref()
                    .is_some_and(|state| state.fs_idx == idx);
            standalone_audio_without_vst || video_audio_mode_without_vst
        });
        let mut routed = 0;
        for (idx, entry) in &self.fs_cache {
            let FsCacheEntry::Video { player, .. } = entry else {
                continue;
            };
            let presenter_visible =
                app_visible && self.fullscreen_idx == Some(*idx) && !mounted_music_consumer;
            player.set_native_window_visible(presenter_visible);
            routed += 1;
        }
        let active = self
            .active_detached_viewer_context
            .as_ref()
            .map(|active| {
                sync_viewer_context_bundle_presenters_for_tray(&active.bundle, app_visible)
            })
            .unwrap_or(0);
        let parked = self
            .detached_image_windows
            .iter()
            .filter_map(|window| window.paused_bundle.as_deref())
            .map(|bundle| sync_viewer_context_bundle_presenters_for_tray(bundle, app_visible))
            .sum::<usize>();
        routed += active + parked;
        if let Some(pending) = self.native_video_source_swap_pending.as_ref() {
            pending
                .native_output
                .set_window_visible(app_visible && !pending.audio_mode_after_swap);
            routed += 1;
        }
        routed
    }

    /// Project the existing media owners into the tray thread's hidden-window wake gate.
    ///
    /// `VideoPlayer::tick` and the continuous EOF navigation decision are UI-owned, while
    /// Windows does not deliver the normal repaint WM_PAINT to a hidden root HWND. Keep the
    /// bridge active only for a current player with live play intent, an unhandled continuous
    /// EOF, an EOF candidate resolver, or the typed media handoff started by that EOF. Keeping the
    /// resolver/handoff states in this projection makes the 50 ms bridge—not the generic hidden
    /// scheduler's 100 ms floor—the clock for EOF and next-track progress. Scheduler direct passes
    /// and bridge `WM_PAINT` callbacks are serialized on the winit main thread, and every update
    /// entry acknowledges the single bridge claim.
    /// Paused/handled-terminal players, cached but non-current players, still images, and tray
    /// residency by itself do not qualify.
    #[cfg(windows)]
    pub(crate) fn tray_resident_media_updates_needed(&self) -> bool {
        if self.window_visible {
            return false;
        }

        let mounted = self
            .fullscreen_idx
            .and_then(|idx| self.fs_cache.get(&idx).map(|entry| (idx, entry)))
            .is_some_and(|(idx, entry)| {
                matches!(entry, FsCacheEntry::Video { player, .. }
                if player_needs_resident_media_updates(
                    player,
                    idx,
                    self.video_continuous_mode,
                    self.video_continuous_last_eof,
                ))
            });
        let active_detached = self
            .active_detached_viewer_context
            .as_ref()
            .is_some_and(|active| {
                viewer_context_bundle_needs_resident_media_updates(
                    &active.bundle,
                    self.video_continuous_mode,
                    self.video_continuous_last_eof,
                )
            });
        let parked = self
            .detached_image_windows
            .iter()
            .filter_map(|window| window.paused_bundle.as_deref())
            .any(|bundle| {
                viewer_context_bundle_needs_resident_media_updates(
                    bundle,
                    self.video_continuous_mode,
                    self.video_continuous_last_eof,
                )
            });
        let eof_resolution = self
            .media_navigation_pending
            .as_ref()
            .is_some_and(|pending| Self::media_navigation_eof_key(&pending.action).is_some());
        let eof_handoff = self.video_continuous_last_eof.is_some()
            && (self.native_video_open_pending.is_some()
                || self.native_video_source_swap_pending.is_some()
                || self.native_video_fast_swap_pending.is_some()
                || self.video_tile_swap_pending.is_some());

        mounted || active_detached || parked || eof_resolution || eof_handoff
    }

    /// Non-Windows builds have no tray residency and no hidden-root wake bridge, so nothing
    /// can be owed an update. The platform difference lives here rather than at each caller:
    /// `hide_to_tray` reads this outside any `cfg` block, and gating it there instead would
    /// leave the next caller to rediscover the same break.
    #[cfg(not(windows))]
    pub(crate) fn tray_resident_media_updates_needed(&self) -> bool {
        false
    }

    /// on_exit 時に mount 外の active detached / ParkedLive bundle から最終 resume を収穫する。
    /// bundle は所有権を移さず、teardown plan の read-only 部分だけを再利用する。
    /// (review-v2.3.0 追補6: R1-2 detached exit resume)
    #[cfg(windows)]
    pub(crate) fn save_detached_video_resume_positions_for_exit(&mut self) {
        let mut plans = Vec::new();
        if let Some(active) = self.active_detached_viewer_context.as_ref() {
            plans.push(viewer_context_media_teardown_plan(&active.bundle));
        }
        plans.extend(
            self.detached_image_windows
                .iter()
                .filter_map(|window| window.paused_bundle.as_deref())
                .map(viewer_context_media_teardown_plan),
        );
        self.save_viewer_context_media_teardown_resumes(&plans);
    }

    #[cfg(windows)]
    fn cleanup_viewer_context_media_teardown_globals(
        &mut self,
        plans: &[ViewerContextMediaTeardownPlan],
        reason: &'static str,
    ) {
        self.cancel_viewer_context_teardown_normalize(plans, reason);
        self.clear_music_state_after_viewer_context_teardown(plans, reason);
    }

    #[cfg(windows)]
    fn cancel_viewer_context_teardown_normalize(
        &mut self,
        plans: &[ViewerContextMediaTeardownPlan],
        reason: &'static str,
    ) {
        let paths: Vec<PathBuf> = plans
            .iter()
            .flat_map(|plan| plan.media_paths.iter().cloned())
            .collect();
        let matches = self
            .normalize_state
            .as_ref()
            .is_some_and(|state| viewer_context_teardown_paths_contain(&paths, &state.file_path));
        if matches {
            self.cancel_matching_viewer_context_normalize(reason);
        }
    }

    #[cfg(windows)]
    fn cancel_matching_viewer_context_normalize(&mut self, _reason: &'static str) {
        if let Some(state) = self.normalize_state.take() {
            state.cancel();
        }
    }

    #[cfg(windows)]
    fn clear_music_state_after_viewer_context_teardown(
        &mut self,
        plans: &[ViewerContextMediaTeardownPlan],
        _reason: &'static str,
    ) {
        let dropped_music = plans.iter().any(|plan| plan.music_consumer);
        let mounted_music = self.current_music_fullscreen_idx().is_some();
        if dropped_music && !mounted_music && !self.detached_music_window_exists() {
            self.clear_music_view_state();
        }
    }

    #[cfg(windows)]
    pub(crate) fn native_video_hud_dimmed_for_current_poll(&self) -> bool {
        self.native_video_parked_live_input_window_id.is_some()
    }

    /// ParkedLive bundle の mount 中は snapshot.paused_bundle が一時的に None なので、その場で
    /// window を retain-drop せず、poll 後の swap-back まで close を遅延する。
    /// (review-v2.3.0 追補6: R1-4 parked open timeout)
    #[cfg(windows)]
    pub(crate) fn request_parked_live_media_close_after_poll(
        &mut self,
        window_id: u64,
        reason: &'static str,
    ) {
        if !self
            .parked_live_media_close_after_poll
            .iter()
            .any(|(known_id, _)| *known_id == window_id)
        {
            self.parked_live_media_close_after_poll
                .push((window_id, reason));
        }
    }

    #[cfg(windows)]
    pub(crate) fn poll_parked_live_detached_windows(&mut self, ctx: &egui::Context) {
        let ids = self.parked_live_media_window_ids();
        for id in ids {
            let Some(pos) = self
                .detached_image_windows
                .iter()
                .position(|window| window.id == id)
            else {
                continue;
            };
            let Some(mut bundle) = self.detached_image_windows[pos].paused_bundle.take() else {
                continue;
            };
            if !Self::viewer_context_bundle_contains_video(&bundle) {
                self.detached_image_windows[pos].paused_bundle = Some(bundle);
                continue;
            }
            if Self::detached_image_window_debug_enabled() && self.frame_counter % 600 == 0 {
                self.log_detached_image_window_debug(format!(
                    "parked_live_poll_begin frame={} id={id} bundle_fs_idx={:?}",
                    self.frame_counter, bundle.fullscreen_idx
                ));
            }
            self.swap_viewer_context_bundle(&mut bundle);
            let saved_input_window_id = self.native_video_parked_live_input_window_id;
            self.native_video_parked_live_input_window_id = Some(id);
            self.poll_video(ctx);
            self.poll_bookmark_media_open(ctx);
            self.update_parked_live_audio_music_view_state(ctx);
            self.native_video_parked_live_input_window_id = saved_input_window_id;
            self.swap_viewer_context_bundle(&mut bundle);
            if let Some(window) = self
                .detached_image_windows
                .iter_mut()
                .find(|window| window.id == id)
            {
                window.paused_bundle = Some(bundle);
            }
            if let Some(request_pos) = self
                .parked_live_media_close_after_poll
                .iter()
                .position(|(window_id, _)| *window_id == id)
            {
                let (_, reason) = self.parked_live_media_close_after_poll.remove(request_pos);
                self.close_detached_image_windows_by_ids(ctx, &[id], &[id], reason, None);
            }
        }
    }

    #[cfg(windows)]
    pub(crate) fn take_parked_live_activation_requests_after_passive_render(&mut self) -> Vec<u64> {
        let mut activation_requests =
            std::mem::take(&mut self.native_video_parked_live_activation_requests);
        let mut seen_activation_requests = std::collections::HashSet::new();
        activation_requests.retain(|id| seen_activation_requests.insert(*id));
        activation_requests
    }

    #[cfg(windows)]
    fn close_parked_live_media_windows_for_new_media(&mut self, reason: &'static str) {
        // The close selector below intentionally accepts only ParkedLive. If a passive bundle
        // owns a player under any other runtime state, the decoder would survive this open and
        // the one-decoder gate would eventually time out. Diagnose that ownership/state split
        // once per media-open event instead of enabling the high-volume detached debug stream.
        let mismatches = self
            .detached_image_windows
            .iter()
            .filter_map(|window| {
                let bundle = window.paused_bundle.as_deref()?;
                if !Self::viewer_context_bundle_contains_video(bundle) {
                    return None;
                }
                let state = self.detached_window_state(window.id);
                if state == Some(DetachedWindowState::ParkedLive) {
                    return None;
                }
                let video_cache_entries = bundle
                    .fs_cache
                    .values()
                    .filter(|entry| matches!(entry, FsCacheEntry::Video { .. }))
                    .count();
                Some(format!(
                    "id={} state={state:?} hwnd=0x{:x} bundle_fullscreen_idx={:?} \
                     video_cache_entries={video_cache_entries}",
                    window.id,
                    self.detached_window_hwnd_raw_for_window_id(window.id),
                    bundle.fullscreen_idx
                ))
            })
            .collect::<Vec<_>>();
        if !mismatches.is_empty() {
            let live_decoders = crate::video::decoder::LIVE_VIDEO_DECODE_THREADS
                .load(std::sync::atomic::Ordering::Acquire);
            crate::logger::log(format!(
                "[detached-media-invariant] new media open found unclassified passive media: \
                 reason={reason} live_video_decode_threads={live_decoders} windows=[{}]",
                mismatches.join("; ")
            ));
        }
        let ids = self.parked_live_media_window_ids();
        if ids.is_empty() {
            return;
        }
        self.log_detached_image_window_debug(format!(
            "parked_live_close_for_new_media ids={ids:?} reason={reason}"
        ));
        for id in &ids {
            self.transition_detached_window_state(*id, DetachedWindowState::Closing, reason);
            self.detached_image_window_close_pending.push(*id);
            self.clear_detached_window_hwnd_for_window_id(*id);
        }
        self.teardown_paused_media_bundles_for_window_ids(&ids, reason);
        self.detached_image_windows
            .retain(|window| !ids.contains(&window.id));
        for id in ids {
            self.remove_detached_window_runtime(id, reason);
        }
    }

    #[cfg(windows)]
    pub(crate) fn should_poll_main_video_context(&self) -> bool {
        !self.active_detached_viewer_context_contains_video()
            && !self.parked_live_media_window_exists()
    }

    #[cfg(windows)]
    pub(crate) fn detached_passive_window_update_activation(
        can_activate: bool,
        activation_ready_frame: u64,
        current_frame: u64,
        activation_armed: &mut bool,
        pointer_pressed: bool,
        pointer_released: bool,
    ) -> bool {
        if current_frame < activation_ready_frame {
            return false;
        }
        if pointer_pressed {
            *activation_armed = true;
        }
        let should_activate = can_activate && *activation_armed && pointer_released;
        if pointer_released {
            *activation_armed = false;
        }
        should_activate
    }

    #[cfg(windows)]
    pub(crate) fn deferred_detached_image_window_shared(
        &mut self,
        view: DeferredDetachedImageWindowView,
    ) -> Arc<DeferredDetachedImageWindowShared> {
        let id = view.id;
        let shared = self
            .deferred_detached_image_window_views
            .entry(id)
            .or_insert_with(|| Arc::new(DeferredDetachedImageWindowShared::new(view.clone())))
            .clone();
        shared.set_view(view);
        shared
    }

    #[cfg(windows)]
    pub(crate) fn prune_deferred_detached_image_window_views(&mut self) {
        let live_ids: HashSet<u64> = self
            .detached_image_windows
            .iter()
            .filter(|window| !self.detached_window_state_is_parked_live(window.id))
            .map(|window| window.id)
            .collect();
        self.deferred_detached_image_window_views
            .retain(|id, _| live_ids.contains(id));
    }

    #[cfg(windows)]
    pub(crate) fn deferred_detached_window_registration_allowed(
        &self,
        window_id: u64,
        unconfirmed_claimed_this_frame: &mut bool,
    ) -> bool {
        if self.detached_window_hwnd_alive(window_id).is_some() {
            return true;
        }
        if *unconfirmed_claimed_this_frame {
            return false;
        }
        *unconfirmed_claimed_this_frame = true;
        true
    }

    #[cfg(windows)]
    pub(crate) fn adopt_deferred_detached_window_hwnd_after_callback(
        &mut self,
        window_id: u64,
        viewport_id: egui::ViewportId,
    ) {
        if self.detached_window_hwnd_alive(window_id).is_some() {
            return;
        }
        let previous_hwnd = self.detached_window_hwnd_clear_if_dead(window_id);
        self.begin_detached_window_hwnd_registration(window_id, "deferred");
        let Some(main_hwnd) = self.main_hwnd else {
            self.log_detached_image_window_debug(format!(
                "hwnd_deferred_retry frame={} window_id={window_id} viewport={viewport_id:?} \
                 reason=no_main_hwnd old={}",
                self.frame_counter,
                previous_hwnd
                    .map(|old| format!("0x{old:x}"))
                    .unwrap_or_else(|| "none".to_string())
            ));
            return;
        };
        let after = crate::dwm_transitions::thread_window_snapshot(
            windows::Win32::Foundation::HWND(main_hwnd as *mut _),
        );
        let claimed = self.detached_window_registered_hwnds();
        match Self::select_detached_unclaimed_hwnd(&after, &claimed) {
            DetachedWindowHwndDiff::Created(hwnd) => {
                let old = self
                    .detached_window_hwnd_set(window_id, hwnd)
                    .or(previous_hwnd);
                let state = self.detached_window_state_for_show_label(window_id, "passive");
                self.transition_detached_window_state(window_id, state, "hwnd_adopted_deferred");
                self.detached_viewer_host_generation =
                    self.detached_viewer_host_generation.saturating_add(1);
                crate::logger::log(format!(
                    "[detached-viewer] hwnd_adopted_deferred hwnd=0x{hwnd:x} \
                     host_generation={} frame={} window_id={window_id} viewport={viewport_id:?} \
                     old={} new_state=\"{}\"",
                    self.detached_viewer_host_generation,
                    self.frame_counter,
                    old.map(|value| format!("0x{value:x}"))
                        .unwrap_or_else(|| "none".to_string()),
                    Self::win32_hwnd_debug_state(hwnd)
                ));
                self.try_resync_detached_video_host_after_registration(window_id);
            }
            DetachedWindowHwndDiff::NoChange => {
                self.log_detached_image_window_debug(format!(
                    "hwnd_deferred_retry frame={} window_id={window_id} viewport={viewport_id:?} \
                     reason=no_unclaimed old={} after_count={} claimed_count={} host={}",
                    self.frame_counter,
                    previous_hwnd
                        .map(|old| format!("0x{old:x}"))
                        .unwrap_or_else(|| "none".to_string()),
                    after.len(),
                    claimed.len(),
                    self.detached_viewer_host_debug_state()
                ));
            }
            DetachedWindowHwndDiff::Ambiguous(candidates) => {
                self.log_detached_image_window_debug(format!(
                    "hwnd_deferred_retry frame={} window_id={window_id} viewport={viewport_id:?} \
                     reason=ambiguous candidates={candidates:x?} old={} after_count={} \
                     claimed_count={} host={}",
                    self.frame_counter,
                    previous_hwnd
                        .map(|old| format!("0x{old:x}"))
                        .unwrap_or_else(|| "none".to_string()),
                    after.len(),
                    claimed.len(),
                    self.detached_viewer_host_debug_state()
                ));
            }
        }
    }

    #[cfg(windows)]
    fn activate_parked_live_media_window_snapshot(&mut self, ctx: &egui::Context, id: u64) -> bool {
        let Some(pos) = self
            .detached_image_windows
            .iter()
            .position(|window| window.id == id)
        else {
            return false;
        };
        if !self.detached_window_state_is_parked_live(id) {
            return false;
        }
        if !self.detached_image_windows[pos]
            .paused_bundle
            .as_deref()
            .is_some_and(Self::viewer_context_bundle_contains_video)
        {
            self.log_detached_image_window_debug(format!(
                "parked_live_activate_aborted id={id} reason=no_video_bundle"
            ));
            return false;
        }
        self.ensure_detached_window_runtime_placement(id, "parked_live_activate_begin");
        self.log_detached_image_window_debug(format!(
            "parked_live_activate_begin id={id} pos={pos} active_context={} session={:?}",
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session
        ));
        self.clear_fullscreen_feedback_for_viewer_switch();

        if !self.park_and_close_current_active_detached_viewer_for_media_handoff(ctx) {
            self.log_detached_image_window_debug(format!(
                "parked_live_activate_aborted id={id} reason=park_current_failed"
            ));
            return false;
        }

        let Some(pos) = self
            .detached_image_windows
            .iter()
            .position(|window| window.id == id)
        else {
            self.log_detached_image_window_debug(format!(
                "parked_live_activate_aborted id={id} reason=snapshot_missing_after_park"
            ));
            return false;
        };
        let mut snapshot = self.detached_image_windows.remove(pos);
        let Some(mut paused_bundle) = snapshot.paused_bundle.take() else {
            self.log_detached_image_window_debug(format!(
                "parked_live_activate_aborted id={id} reason=bundle_missing_after_remove"
            ));
            self.transition_detached_window_state(
                id,
                DetachedWindowState::ParkedLive,
                "parked_live_activate_aborted",
            );
            self.detached_image_windows.insert(pos, snapshot);
            return false;
        };
        if !Self::viewer_context_bundle_contains_video(&paused_bundle) {
            self.log_detached_image_window_debug(format!(
                "parked_live_activate_aborted id={id} reason=bundle_not_video_after_remove"
            ));
            snapshot.paused_bundle = Some(paused_bundle);
            self.transition_detached_window_state(
                id,
                DetachedWindowState::ParkedLive,
                "parked_live_activate_aborted",
            );
            self.detached_image_windows.insert(pos, snapshot);
            return false;
        }

        paused_bundle
            .viewer_session
            .activate_independent_detached(id);
        paused_bundle.fs_open_intent_from_grid = false;
        paused_bundle.pending_auto_fs_open = false;
        paused_bundle.pending_return_to_parent = false;
        paused_bundle.pdf_prefetch_grace_until = None;

        // ParkedLive owner の pending は active context の通常 poll へ引き継ぐ。
        // owner を残すと parked poll が二度と来ず、timeout 判定も含めて永久停止する。
        // (review-v2.3.0 追補2 BA-7: activation pending ownership)
        self.rebind_native_video_pending_owners(Some(id), None, "parked_live_activate_commit");
        self.detached_viewer_window_id = Some(id);
        self.update_detached_window_runtime_flags(id, false, "parked_live_activate_commit");
        self.transition_detached_window_state(
            id,
            DetachedWindowState::Resuming,
            "parked_live_activate_commit",
        );
        self.adopt_active_detached_viewport_runtime_from_passive("resume_parked_live_media");
        self.last_active_detached_window_id = Some(id);
        let source = Self::viewer_context_bundle_detached_source(&paused_bundle);
        self.begin_active_detached_session(id, source);
        self.active_detached_viewer_context = Some(ActiveDetachedViewerContext {
            bundle: *paused_bundle,
        });
        self.log_detached_image_window_debug(format!(
            "parked_live_activate_committed id={id} passive_remaining={} active_context=true \
             session={:?}",
            self.detached_image_windows.len(),
            self.active_detached_session
        ));
        ctx.request_repaint();
        true
    }

    #[cfg(windows)]
    fn reset_active_detached_viewport_runtime_for_new_window(
        &mut self,
        generation: u64,
        reason: &'static str,
    ) {
        self.log_detached_image_window_debug(format!(
            "active_viewport_runtime_reset_new reason={reason} generation={generation} \
             old_shown={} old_presentation={:?} old_host={}",
            self.fs_viewport_shown,
            self.fs_viewport_presentation,
            self.detached_viewer_host_debug_state()
        ));
        self.fs_viewport_shown = false;
        self.fs_viewport_presentation = None;
        self.fs_viewport_virtual_desktop_synced_hwnd = 0;
        self.clear_detached_viewer_host_hwnd();
        self.detached_viewer_borderless_fullscreen = false;
        self.detached_viewer_restore_placement = None;
        self.detached_viewer_borderless_transition = None;
        self.still_fullscreen_viewport_enter_suppress_until = None;
        self.fs_viewport_recreate_after_hide = false;
        self.fs_viewport_generation = generation;
        self.detached_viewer_recreate_on_next_render = false;
        self.detached_viewer_focus_requested = false;
        self.detached_viewer_no_activate_once = false;
        self.detached_viewer_folder_nav_reuse_window_once = false;
        self.fs_opened_at = None;
        self.fs_focus_grace_elapsed = false;
        self.fs_prev_focused = false;
        self.fs_focus_regained_at = None;
        self.fs_prev_foreground_hwnd = 0;
        self.fs_last_native_focus_claim_at = None;
        self.fs_last_main_focus_restore_at = None;
        self.fs_primary_suppression = Default::default();
    }

    #[cfg(windows)]
    fn adopt_active_detached_viewport_runtime_from_passive(&mut self, reason: &'static str) {
        let seed_placement = self
            .active_detached_hwnd_window_id()
            .map(|window_id| self.ensure_detached_window_runtime_placement(window_id, reason));
        self.log_detached_image_window_debug(format!(
            "active_viewport_runtime_adopt_passive reason={reason} old_shown={} \
             old_presentation={:?} old_host={} seed_placement={:?}",
            self.fs_viewport_shown,
            self.fs_viewport_presentation,
            self.detached_viewer_host_debug_state(),
            seed_placement
        ));
        self.fs_viewport_shown = true;
        self.fs_viewport_presentation = Some(ViewerPresentation::DetachedWindow);
        self.fs_viewport_virtual_desktop_synced_hwnd = 0;
        self.detached_viewer_borderless_fullscreen = false;
        self.detached_viewer_restore_placement = None;
        self.detached_viewer_borderless_transition = None;
        self.still_fullscreen_viewport_enter_suppress_until = None;
        self.fs_viewport_recreate_after_hide = false;
        self.detached_viewer_recreate_on_next_render = false;
        self.detached_viewer_focus_requested = true;
        self.detached_viewer_no_activate_once = false;
        self.fs_opened_at = Some(std::time::Instant::now());
        self.fs_focus_grace_elapsed = false;
        self.fs_prev_focused = true;
        self.fs_focus_regained_at = None;
        self.fs_prev_foreground_hwnd = 0;
        self.fs_last_native_focus_claim_at = None;
        self.fs_last_main_focus_restore_at = None;
        self.fs_primary_suppression = Default::default();
    }

    #[cfg(windows)]
    pub(crate) fn focus_main_after_detached_window_close_if_idle(
        &self,
        ctx: &egui::Context,
        reason: &'static str,
    ) {
        if !self.detached_image_windows.is_empty() {
            self.log_detached_image_window_debug(format!(
                "main_focus_after_close_skipped reason={reason} passive_windows={}",
                self.detached_image_windows.len()
            ));
            return;
        }
        if self.active_detached_viewer_context.is_some() || self.fullscreen_idx.is_some() {
            self.log_detached_image_window_debug(format!(
                "main_focus_after_close_skipped reason={reason} active_context={} fs_idx={:?}",
                self.active_detached_viewer_context.is_some(),
                self.fullscreen_idx
            ));
            return;
        }
        self.log_detached_image_window_debug(format!(
            "main_focus_after_close reason={reason} passive_windows={}",
            self.detached_image_windows.len()
        ));
        ctx.send_viewport_cmd_to(egui::ViewportId::ROOT, egui::ViewportCommand::Focus);
        ctx.request_repaint_of(egui::ViewportId::ROOT);
    }

    #[cfg(windows)]
    fn finalize_closed_active_detached_viewport(
        &mut self,
        ctx: &egui::Context,
        viewport_id: egui::ViewportId,
    ) {
        self.log_detached_image_window_debug(format!(
            "active_close_finalize begin viewport={viewport_id:?} fs_idx={:?} shown={} \
             presentation={:?} passive_windows={} host={}",
            self.fullscreen_idx,
            self.fs_viewport_shown,
            self.fs_viewport_presentation,
            self.detached_image_windows.len(),
            self.detached_viewer_host_debug_state()
        ));
        crate::dwm_transitions::disable_transitions_for_thread_windows();
        ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Close);
        self.fs_viewport_shown = false;
        self.fs_viewport_presentation = None;
        self.fs_viewport_recreate_after_hide = false;
        self.clear_detached_viewer_host_hwnd();
        // active detached viewport の teardown 完了 = セッション終了 (§3.7 finish)。
        // terminal close が明示的に宣言され、session が finish 済みまたは Closing のとき
        // だけ呼ばれる。internal reopen (folder-nav / PDF・ZIP 列挙 / scan / password) 中は
        // detached_active_window_alive_wanted() が true なので呼ばれず、session を維持する。
        self.finish_active_detached_session_close("active_close_finalize");
        self.request_detached_cleanup_font_atlas_resync("active_close_finalize");
        self.focus_main_after_detached_window_close_if_idle(ctx, "active_close_finalize");
        self.log_detached_image_window_debug(format!(
            "active_close_finalize end viewport={viewport_id:?} shown={} presentation={:?} \
             recreate_after_hide={} host={}",
            self.fs_viewport_shown,
            self.fs_viewport_presentation,
            self.fs_viewport_recreate_after_hide,
            self.detached_viewer_host_debug_state()
        ));
    }

    #[cfg(windows)]
    fn park_and_close_current_active_detached_viewer(&mut self, ctx: &egui::Context) -> bool {
        self.park_and_close_current_active_detached_viewer_inner(ctx, false)
    }

    #[cfg(windows)]
    fn park_and_close_current_active_detached_viewer_for_media_handoff(
        &mut self,
        ctx: &egui::Context,
    ) -> bool {
        self.park_and_close_current_active_detached_viewer_inner(ctx, true)
    }

    #[cfg(windows)]
    fn park_and_close_current_active_detached_viewer_inner(
        &mut self,
        ctx: &egui::Context,
        preserve_fullfeature_linked_still: bool,
    ) -> bool {
        if self.active_detached_viewer_context_contains_video()
            && self
                .park_active_detached_context_as_live_media(ctx, "park_active_context_live_media")
        {
            self.log_detached_image_window_debug(format!(
                "park_current_active_detached result=parked_live_active_context passive_windows={} \
                 active_context={} session={:?}",
                self.detached_image_windows.len(),
                self.active_detached_viewer_context.is_some(),
                self.active_detached_session
            ));
            return true;
        }
        if self.viewer_session_is_detached()
            && self.current_viewer_context_contains_video()
            && self.park_current_viewer_context_as_live_media(ctx, "park_legacy_live_media")
        {
            self.log_detached_image_window_debug(format!(
                "park_current_active_detached result=parked_live_legacy passive_windows={} \
                 active_context={} session={:?}",
                self.detached_image_windows.len(),
                self.active_detached_viewer_context.is_some(),
                self.active_detached_session
            ));
            return true;
        }
        if self.pause_current_active_detached_viewer_context(ctx) {
            self.log_detached_image_window_debug(format!(
                "park_current_active_detached result=paused passive_windows={} \
                 active_context={} session={:?}",
                self.detached_image_windows.len(),
                self.active_detached_viewer_context.is_some(),
                self.active_detached_session
            ));
            return true;
        } else if self.active_detached_viewer_context.is_some() {
            self.log_detached_image_window_debug(
                "park_current_active_detached result=close_active_context".to_string(),
            );
            return self.close_current_active_detached_viewer_context(ctx);
        } else if self.viewer_session_is_detached() {
            if self.preserve_active_detached_image_window_for_main_context_change_inner(
                preserve_fullfeature_linked_still,
            ) {
                // preserve (legacy park) 自体は main のフルスクリーン状態を触らない
                // (load_folder 直呼び経路では後続のフォルダ install が畳むため)。ここ
                // (parked_live_activate / activate_snapshot などの文脈切替) では畳む者が
                // 居らず、main に fs_idx / presentation=DetachedWindow のゴーストセッションが
                // 残る。残すと次のフォルダ移動で preserve がゴーストの idx に反応し、
                // アクティブなメディア窓へ「別アイテムの画像スナップショット」を焼き付けて
                // park してしまう (2026-07-09 実機 2 件目: 動画窓に画像が表示・点滅)。
                // live-media park (park_current_viewer_context_as_live_media_inner 末尾) と
                // 同じ後始末で main を非 detached へ戻す。
                self.fullscreen_idx = None;
                self.viewer_presentation = self.non_detached_viewer_presentation();
                self.detached_viewer_independent_active = false;
                self.detached_viewer_window_id = None;
                self.last_viewer_sync_stamp = None;
                self.log_detached_image_window_debug(format!(
                    "park_current_active_detached result=parked_legacy_detached fs_idx={:?} \
                     independent={} passive_windows={} session={:?}",
                    self.fullscreen_idx,
                    self.detached_viewer_independent_active,
                    self.detached_image_windows.len(),
                    self.active_detached_session
                ));
                return true;
            }
            self.log_detached_image_window_debug(format!(
                "park_current_active_detached result=close_legacy_detached fs_idx={:?} \
                 independent={} passive_windows={}",
                self.fullscreen_idx,
                self.detached_viewer_independent_active,
                self.detached_image_windows.len()
            ));
            let session_window_id = self
                .active_detached_session
                .map(|session| session.window_id);
            let closing_window_id = session_window_id.or(self.detached_viewer_window_id);
            let fs_id = self.fullscreen_viewport_id();
            self.begin_active_detached_session_close("park_close_legacy_detached");
            if self.fs_viewport_shown {
                ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Close);
            }
            self.finish_active_detached_session_close("park_close_legacy_detached");
            if session_window_id.is_none()
                && let Some(window_id) = closing_window_id
            {
                self.remove_detached_window_runtime(window_id, "park_close_legacy_detached");
            }
            self.close_fullscreen();
            return true;
        }
        self.active_detached_viewer_context.is_none()
    }

    #[cfg(windows)]
    fn start_active_detached_book_context_from_descriptor(
        &mut self,
        descriptor: ViewerContextDescriptor,
        ctx: &egui::Context,
        placement_seed: Option<crate::settings::DetachedViewerWindowPlacement>,
    ) -> bool {
        self.start_active_detached_book_context(descriptor, ctx, placement_seed, None)
    }

    #[cfg(windows)]
    fn start_active_detached_book_context_from_scanned_folder(
        &mut self,
        path: PathBuf,
        scan: ScannedDir,
        ctx: &egui::Context,
        placement_seed: Option<crate::settings::DetachedViewerWindowPlacement>,
    ) -> bool {
        self.start_active_detached_book_context_with_start(
            DetachedBookContextStart::ScannedFolder { path, scan },
            ctx,
            placement_seed,
            None,
        )
    }

    #[cfg(windows)]
    fn start_active_detached_book_context(
        &mut self,
        descriptor: ViewerContextDescriptor,
        ctx: &egui::Context,
        placement_seed: Option<crate::settings::DetachedViewerWindowPlacement>,
        bookmark_pending: Option<crate::bookmark_browser::PendingBookOpen>,
    ) -> bool {
        self.start_active_detached_book_context_with_start(
            DetachedBookContextStart::Descriptor(descriptor),
            ctx,
            placement_seed,
            bookmark_pending,
        )
    }

    #[cfg(windows)]
    fn start_active_detached_book_context_with_start(
        &mut self,
        start: DetachedBookContextStart,
        ctx: &egui::Context,
        placement_seed: Option<crate::settings::DetachedViewerWindowPlacement>,
        mut bookmark_pending: Option<crate::bookmark_browser::PendingBookOpen>,
    ) -> bool {
        let descriptor = match &start {
            DetachedBookContextStart::Descriptor(descriptor) => descriptor.clone(),
            DetachedBookContextStart::ScannedFolder { path, .. } => {
                ViewerContextDescriptor::BookFolder { path: path.clone() }
            }
        };
        let target = Self::detached_book_context_target(&descriptor);
        let mut main_context = self.take_current_viewer_context_bundle();
        // From this point until the bundle is captured, all loads belong to the
        // independent detached still viewer.  The scope travels with the bundle
        // and is restored whenever that viewer is mounted.
        self.navigation_scope = ViewerNavigationScope::DetachedPhysical;
        if let Some(pending) = bookmark_pending.as_mut() {
            pending.begin_page_wait();
            self.bookmark_view_state = Some(BookmarkViewState::Detached {
                target: crate::bookmark_browser::BookmarkViewReturnTarget::Book(
                    pending.bookmark.container_path.clone(),
                ),
            });
        }
        self.bookmark_open_pending =
            bookmark_pending.map(crate::bookmark_browser::PendingBookmarkOpen::Book);
        let context_serial = self.assign_next_detached_viewer_context_generation();
        self.reset_active_detached_viewport_runtime_for_new_window(
            context_serial,
            "start_active_detached_book_context",
        );
        let window_id = self.allocate_detached_viewer_window_id();
        self.log_detached_image_window_debug(format!(
            "allocate_window_id reason=start_active_detached_book_context id={window_id} \
             context_serial={context_serial} folder_nav_reuse_once={}",
            self.detached_viewer_folder_nav_reuse_window_once
        ));
        self.detached_viewer_window_id = Some(window_id);
        self.last_active_detached_window_id = Some(window_id);
        let seed = placement_seed.unwrap_or_else(|| self.detached_viewer_window_placement());
        self.set_detached_window_runtime_placement(
            window_id,
            seed,
            "start_active_detached_book_context",
        );
        self.transition_detached_window_state(
            window_id,
            DetachedWindowState::Opening,
            "start_active_detached_book_context",
        );
        self.detached_viewer_folder_nav_reuse_window_once = false;
        // keep-alive: book context 開始 = detached セッション開始 (§3.7 set)。enumerate 待ちの
        // gap でも backstop が窓を生かせるよう、deferred open を待たずここで session を立てる。
        let session_source = match &descriptor {
            ViewerContextDescriptor::Image { .. } => DetachedSource::Image,
            _ => DetachedSource::Book,
        };
        self.begin_active_detached_session(window_id, session_source);
        // Image はフォルダ load 後に明示 open_fullscreen するので auto-fullscreen 予約を
        // 立てない (立てると「画像のみフォルダ」設定次第で先頭画像が先に開いて二重になる)。
        let is_image_reopen = matches!(descriptor, ViewerContextDescriptor::Image { .. });
        let bookmark_open = self.bookmark_open_pending.is_some();
        self.pending_auto_fs_open = !is_image_reopen && !bookmark_open;
        self.fs_open_intent_from_grid = !is_image_reopen && !bookmark_open;

        self.with_detached_viewer_main_history_suppressed(|app| match start {
            DetachedBookContextStart::Descriptor(descriptor) => match descriptor {
                ViewerContextDescriptor::Zip {
                    path,
                    archive_source_override,
                    ..
                } => {
                    app.load_zip_as_folder(path);
                    if let Some(source) = archive_source_override {
                        app.archive_source_override = Some(source.clone());
                        app.address = source.to_string_lossy().to_string();
                    }
                }
                ViewerContextDescriptor::Pdf { path, .. } => {
                    app.load_pdf_as_folder(path);
                }
                ViewerContextDescriptor::BookFolder { path } => {
                    app.start_detached_folder_open(path);
                }
                ViewerContextDescriptor::Image { path } => {
                    // 仮想一覧の backing snapshot は使わず、親フォルダを worker で完全走査する。
                    // 対象画像は scan request 自身が所有し、結果を detached bundle 内で
                    // materialize した後に物理順の index へ解決する。
                    if !app.start_detached_image_folder_open(path.clone()) {
                        app.log_detached_image_window_debug(format!(
                            "image_reopen_no_parent_for_async_folder_scan path={}",
                            path.display()
                        ));
                    }
                }
            },
            DetachedBookContextStart::ScannedFolder { path, scan } => {
                // The main-owned preflight already established that this is an image book.
                // Transfer the completed scan exactly once; do not re-read the directory or
                // publish a detached session for mixed folders.
                app.load_folder_with_scan(path, Some(scan));
            }
        });

        if !bookmark_open
            && !is_image_reopen
            && let Some(target) = target
        {
            self.fs_nav_after_pdf_enumerate = Some(DeferredFsReopen {
                history_trigger: crate::app::HistoryTrigger::UserChosen,
                resume_slideshow: false,
                target: DeferredFsTarget::Required(target),
                resume_to_last_page: false,
                from_explicit_open: true,
                preserve_after_password_prompt: true,
            });
        }

        let active_context = self.take_current_viewer_context_bundle();
        self.swap_viewer_context_bundle(&mut main_context);
        self.active_detached_viewer_context = Some(ActiveDetachedViewerContext {
            bundle: active_context,
        });
        ctx.request_repaint();
        true
    }

    #[cfg(windows)]
    fn detached_book_context_descriptor_for_grid_item(
        &self,
        idx: usize,
        auto_fullscreen: bool,
    ) -> Option<ViewerContextDescriptor> {
        if auto_fullscreen {
            if let Some(descriptor) = self.detached_book_context_descriptor_for_grid_idx(idx) {
                return Some(descriptor);
            }
        }
        self.detached_viewer_context_descriptor_for_idx(idx)
    }

    #[cfg(windows)]
    fn detached_grid_item_open_plan(
        &self,
        idx: usize,
        auto_fullscreen: bool,
    ) -> Option<DetachedGridItemOpenPlan> {
        if !self.settings.detached_viewer_open_images_in_window {
            return None;
        }
        if auto_fullscreen && let Some(GridItem::Folder(path)) = self.items.get(idx) {
            // Ctrl+G drill folders are navigation nodes, not physical book containers.
            if self.global_search.active && self.global_search.drill.is_some() {
                return None;
            }
            return Some(DetachedGridItemOpenPlan::FolderCandidate { path: path.clone() });
        }
        self.detached_book_context_descriptor_for_grid_item(idx, auto_fullscreen)
            .map(DetachedGridItemOpenPlan::Descriptor)
    }

    #[cfg(windows)]
    pub(crate) fn open_grid_container_in_detached_book_context(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
    ) -> bool {
        self.open_grid_item_in_detached_book_context_with_auto_fullscreen(
            ctx,
            idx,
            self.should_auto_fullscreen_grid_container(idx),
        )
    }

    #[cfg(windows)]
    pub(crate) fn open_grid_container_in_detached_book_context_with_auto_fullscreen(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
        auto_fullscreen: bool,
    ) -> bool {
        self.open_grid_item_in_detached_book_context_with_auto_fullscreen(ctx, idx, auto_fullscreen)
    }

    #[cfg(windows)]
    pub(crate) fn open_grid_item_in_detached_book_context_with_auto_fullscreen(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
        auto_fullscreen: bool,
    ) -> bool {
        let Some(plan) = self.detached_grid_item_open_plan(idx, auto_fullscreen) else {
            return false;
        };

        let descriptor = match plan {
            DetachedGridItemOpenPlan::Descriptor(descriptor) => {
                self.maybe_suppress_rating_filter_for_opened_container(idx);
                self.maybe_suppress_facet_filter_for_opened_container(idx);
                descriptor
            }
            DetachedGridItemOpenPlan::FolderCandidate { path } => {
                // Classification is main-owned. No session/runtime or detached bundle exists
                // until the completed scan proves this is an image book; mixed folders fall
                // back through the normal main navigation arbitration.
                self.start_grid_folder_candidate_open(path);
                ctx.request_repaint();
                return true;
            }
        };

        let base_placement = self.active_detached_viewer_current_placement();
        let had_active_detached =
            self.active_detached_viewer_context.is_some() || self.viewer_session_is_detached();
        if !self.park_and_close_current_active_detached_viewer(ctx) {
            return false;
        }
        let placement_seed = had_active_detached
            .then(|| self.offset_detached_image_window_placement(base_placement));
        self.start_active_detached_book_context_from_descriptor(descriptor, ctx, placement_seed)
    }

    /// Finish an OtherArchive bookmark open after direct-read probing or conversion selected the
    /// readable backing archive. The conversion dialog is App-global, but the resulting reader
    /// still enters the standard detached book context so it cannot replace the main grid.
    #[cfg(windows)]
    pub(crate) fn open_converted_bookmark_in_detached_context(
        &mut self,
        ctx: &egui::Context,
        backing_archive: PathBuf,
        owner: &crate::bookmark_browser::BookmarkOpenRequestOwner,
    ) -> Option<bool> {
        if !self.settings.detached_viewer_open_images_in_window {
            return None;
        }
        if !self.bookmark_open_owner_is_current(owner) {
            return Some(false);
        }
        let pending = self
            .bookmark_open_pending
            .as_ref()
            .and_then(crate::bookmark_browser::PendingBookmarkOpen::book)?;
        if pending.request_id != owner.request_id {
            return Some(false);
        }
        if pending.bookmark.container_kind != crate::book_bookmarks::BookContainerKind::OtherArchive
            || !matches!(
                self.bookmark_view_state.as_ref(),
                Some(BookmarkViewState::Opening {
                    target: crate::bookmark_browser::BookmarkViewReturnTarget::Book(path),
                    ..
                }) if crate::path_key::eq_keep_drive(path, &pending.bookmark.container_path)
            )
        {
            return None;
        }
        let bookmark_container = pending.bookmark.container_path.clone();
        let pending = match self.bookmark_open_pending.take() {
            Some(crate::bookmark_browser::PendingBookmarkOpen::Book(pending)) => pending,
            other => {
                self.bookmark_open_pending = other;
                return None;
            }
        };
        let base_placement = self.active_detached_viewer_current_placement();
        let had_active_detached =
            self.active_detached_viewer_context.is_some() || self.viewer_session_is_detached();
        if !self.park_and_close_current_active_detached_viewer(ctx) {
            self.bookmark_open_pending =
                Some(crate::bookmark_browser::PendingBookmarkOpen::Book(pending));
            return Some(false);
        }
        let placement_seed = had_active_detached
            .then(|| self.offset_detached_image_window_placement(base_placement));
        let descriptor = ViewerContextDescriptor::Zip {
            path: backing_archive,
            entry_name: None,
            // Keep the DB identity as effective_folder even when a multi-volume RAR probe
            // resolves a different first-volume backing path.
            archive_source_override: Some(bookmark_container),
        };
        Some(self.start_active_detached_book_context(
            descriptor,
            ctx,
            placement_seed,
            Some(pending),
        ))
    }

    #[cfg(windows)]
    pub(crate) fn activate_detached_image_window_snapshot(
        &mut self,
        ctx: &egui::Context,
        id: u64,
    ) -> bool {
        if self.detached_window_state_is_parked_live(id) {
            return self.activate_parked_live_media_window_snapshot(ctx, id);
        }
        let Some(pos) = self
            .detached_image_windows
            .iter()
            .position(|window| window.id == id)
        else {
            return false;
        };
        let mut snapshot = self.detached_image_windows.remove(pos);
        self.update_detached_window_runtime_flags(snapshot.id, false, "passive_activate_begin");
        self.transition_detached_window_state(
            snapshot.id,
            DetachedWindowState::Resuming,
            "passive_activate_begin",
        );
        self.log_detached_image_window_debug(format!(
            "passive_activate_begin id={id} pos={pos} has_paused_bundle={} \
             descriptor={} stamp={} passive_remaining={} active_context={} session={:?}",
            snapshot.paused_bundle.is_some(),
            Self::detached_viewer_descriptor_debug_kind(&snapshot.reopen_descriptor),
            snapshot.reopen_sync_stamp.is_some(),
            self.detached_image_windows.len(),
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session
        ));
        self.clear_fullscreen_feedback_for_viewer_switch();

        if let Some(mut paused_bundle) = snapshot.paused_bundle.take() {
            self.log_detached_image_window_debug(format!(
                "passive_activate_resume_paused_bundle id={} bundle_window_id={:?} \
                 bundle_fs_idx={:?} bundle_independent={} \
                 bundle_pending={} bundle_cache={} snapshot_title={:?}",
                snapshot.id,
                paused_bundle.viewer_session.detached_window_id,
                paused_bundle.fullscreen_idx,
                paused_bundle.viewer_session.independent_active,
                paused_bundle.fs_pending.len(),
                paused_bundle.fs_cache.len(),
                snapshot.title
            ));
            self.ensure_detached_window_runtime_placement(snapshot.id, "resume_paused_bundle");
            if !self.park_and_close_current_active_detached_viewer(ctx) {
                self.log_detached_image_window_debug(format!(
                    "passive_activate_resume_paused_bundle_aborted id={} reason=park_current_failed",
                    snapshot.id
                ));
                snapshot.paused_bundle = Some(paused_bundle);
                self.transition_detached_window_state(
                    snapshot.id,
                    DetachedWindowState::Parked,
                    "passive_activate_resume_paused_bundle_aborted",
                );
                self.detached_image_windows.insert(pos, snapshot);
                return false;
            }
            paused_bundle
                .viewer_session
                .activate_independent_detached(snapshot.id);
            paused_bundle.fs_open_intent_from_grid = false;
            paused_bundle.pdf_prefetch_grace_until = None;
            self.adopt_active_detached_viewport_runtime_from_passive("resume_paused_bundle");
            // keep-alive: passive→active 再開 = セッション再開 (§3.7 set)。open_fullscreen を
            // 通らない経路なのでここで明示的に session を立てる。
            self.last_active_detached_window_id = Some(snapshot.id);
            let source = Self::viewer_context_bundle_detached_source(&paused_bundle);
            self.begin_active_detached_session(snapshot.id, source);
            self.active_detached_viewer_context = Some(ActiveDetachedViewerContext {
                bundle: *paused_bundle,
            });
            let _ = self.with_active_detached_viewer_context(|app| {
                app.rearm_final_ai_prefetch_after_detached_resume();
            });
            self.log_detached_image_window_debug(format!(
                "passive_activate_resume_paused_bundle_committed id={} active_context=true \
                 session={:?}",
                snapshot.id, self.active_detached_session
            ));
            ctx.request_repaint();
            return true;
        }

        // 通常画像の parked still はまず同期スタンプ (main の現行 items) で解決する。
        // `Image` descriptor はスタンプが解決できないときのフォールバック専用
        // (親フォルダを窓内コンテキストとして開き直す)。Pdf/Zip descriptor は
        // 従来どおり descriptor 優先 (この if を素通りして下の descriptor 経路へ)。
        let stamp_first = matches!(
            snapshot.reopen_descriptor,
            None | Some(ViewerContextDescriptor::Image { .. })
        );
        if stamp_first
            && let Some(stamp) = snapshot.reopen_sync_stamp.clone()
            && let Some(idx) = self.resolve_viewer_sync_stamp_idx(&stamp).or_else(|| {
                if snapshot.reopen_descriptor.is_none() {
                    self.log_detached_image_window_debug(format!(
                        "passive_activate_still_aborted id={} reason=stamp_not_resolved",
                        snapshot.id
                    ));
                } else {
                    self.log_detached_image_window_debug(format!(
                        "passive_activate_stamp_fallback_to_descriptor id={}",
                        snapshot.id
                    ));
                }
                None
            })
        {
            self.log_detached_image_window_debug(format!(
                "passive_activate_still_snapshot id={} idx={idx} independent=true \
                 descriptor={} zoom_pan={} free_rotation={:.3}",
                snapshot.id,
                Self::detached_viewer_descriptor_debug_kind(&snapshot.reopen_descriptor),
                snapshot.zoom_pan.is_some(),
                snapshot.free_rotation
            ));
            let activate_window_id = snapshot.id;
            self.ensure_detached_window_runtime_placement(
                activate_window_id,
                "resume_still_snapshot",
            );
            let activate_zoom_pan = snapshot.zoom_pan;
            let activate_free_rotation = snapshot.free_rotation;
            if !self.park_and_close_current_active_detached_viewer(ctx) {
                self.log_detached_image_window_debug(format!(
                    "passive_activate_still_aborted id={} reason=park_current_failed",
                    activate_window_id
                ));
                self.transition_detached_window_state(
                    activate_window_id,
                    DetachedWindowState::Parked,
                    "passive_activate_still_aborted",
                );
                self.detached_image_windows.insert(pos, snapshot);
                return false;
            }
            self.detached_viewer_window_id = Some(activate_window_id);
            self.detached_viewer_independent_active = true;
            self.detached_viewer_open_next_still_detached_once = true;
            self.fs_open_intent_from_grid = false;
            self.adopt_active_detached_viewport_runtime_from_passive("resume_still_snapshot");
            self.open_fullscreen(idx, crate::app::HistoryTrigger::UserChosen);
            if let Some((zoom, pan)) = activate_zoom_pan {
                self.fs_zoom = zoom;
                self.fs_pan = pan;
            }
            self.fs_free_rotation = activate_free_rotation;
            self.log_detached_image_window_debug(format!(
                "passive_activate_still_committed id={} active_context={} fs_idx={:?} \
                 independent={} session={:?}",
                activate_window_id,
                self.active_detached_viewer_context.is_some(),
                self.fullscreen_idx,
                self.detached_viewer_independent_active,
                self.active_detached_session
            ));
            ctx.request_repaint();
            return true;
        }

        let Some(descriptor) = snapshot.reopen_descriptor.clone() else {
            self.log_detached_image_window_debug(format!(
                "passive_activate_aborted id={} reason=no_reopen_route",
                snapshot.id
            ));
            self.transition_detached_window_state(
                snapshot.id,
                DetachedWindowState::Parked,
                "passive_activate_aborted",
            );
            self.detached_image_windows.insert(pos, snapshot);
            return false;
        };
        // Image フォールバックは親フォルダが読めることを先に確認する。still 窓を閉じた
        // 後で load に失敗すると窓ごと失われるため、無理なら parked のまま残す。
        // (ユーザーのクリック 1 回につき is_dir 1 回の同期 I/O。恒常経路ではない。)
        if let ViewerContextDescriptor::Image { path } = &descriptor {
            if !path.parent().is_some_and(|p| p.is_dir()) {
                self.log_detached_image_window_debug(format!(
                    "passive_activate_reopen_descriptor_aborted id={} reason=image_parent_missing",
                    snapshot.id
                ));
                self.transition_detached_window_state(
                    snapshot.id,
                    DetachedWindowState::Parked,
                    "passive_activate_reopen_descriptor_aborted",
                );
                self.detached_image_windows.insert(pos, snapshot);
                return false;
            }
            // Descriptor fallback creates a DetachedPhysical bundle below.
            // App-global snapshot lock belongs to the main grid and therefore
            // must not prevent this independent viewer from restoring its file.
        }
        self.log_detached_image_window_debug(format!(
            "passive_activate_reopen_descriptor id={} descriptor={} title={:?}",
            snapshot.id,
            Self::detached_viewer_descriptor_debug_kind(&Some(descriptor.clone())),
            snapshot.title
        ));

        self.transition_detached_window_state(
            snapshot.id,
            DetachedWindowState::Closing,
            "passive_activate_reopen_descriptor",
        );
        ctx.send_viewport_cmd_to(
            Self::detached_image_window_viewport_id(snapshot.id),
            egui::ViewportCommand::Close,
        );
        self.ensure_detached_window_runtime_placement(snapshot.id, "passive_activate_descriptor");
        if !self.park_and_close_current_active_detached_viewer(ctx) {
            self.log_detached_image_window_debug(format!(
                "passive_activate_reopen_descriptor_aborted id={} reason=park_current_failed",
                snapshot.id
            ));
            self.transition_detached_window_state(
                snapshot.id,
                DetachedWindowState::Parked,
                "passive_activate_reopen_descriptor_aborted",
            );
            self.detached_image_windows.insert(pos, snapshot);
            return false;
        }
        self.remove_detached_window_runtime(snapshot.id, "passive_activate_reopen_descriptor");
        self.start_active_detached_book_context_from_descriptor(descriptor, ctx, None)
    }

    #[cfg(windows)]
    fn reconcile_closed_bookmark_detached_context(&mut self, closed: &ViewerContextBundle) {
        let Some(BookmarkViewState::Opening {
            target: main_target,
            ..
        }) = self.bookmark_view_state.as_ref()
        else {
            return;
        };
        let main_target = main_target.clone();
        // main が別の場所へ移動済みなら、その後のユーザー操作を detached close で巻き戻さない。
        if !self.items_are_bookmark_view {
            return;
        }

        let stayed_at_opened_bookmark = closed
            .bookmark_view_state
            .as_ref()
            .and_then(BookmarkViewState::target)
            == Some(&main_target);
        let keep_origin_grid = matches!(
            main_target,
            crate::bookmark_browser::BookmarkViewReturnTarget::Book(_)
        ) || stayed_at_opened_bookmark;
        if keep_origin_grid {
            // 一覧は main に表示されたままなので enter_bookmark_view は不要。viewer 中の
            // 名称変更・追加・削除だけを非同期再構築し、保存済み grid snapshot で位置を戻す。
            // 別ウィンドウ再生中も main は操作できるため、選択・スクロールは「開く直前」より
            // 現在の main 状態を優先する。row_keys / opened_key は増減検知と可視化用に維持する。
            let current_selected_key = self
                .selected
                .and_then(|idx| self.bookmark_browser_rows.get(idx))
                .map(crate::bookmark_browser::BookmarkBrowserRow::stable_key);
            if let Some(return_grid) = self
                .bookmark_view_state
                .as_mut()
                .and_then(BookmarkViewState::origin_grid_mut)
            {
                return_grid.selected_key = current_selected_key;
                return_grid.scroll_offset_y = self.scroll_offset_y;
            }
            self.bookmark_view_begin_restore();
            crate::logger::log(
                "[bookmark-open] detached viewer closed; refresh main bookmark grid",
            );
            self.refresh_bookmark_browser();
            return;
        }

        // Ctrl+↑↓ や前後ファイル移動で対象を離れた場合は、従来仕様どおり viewer が最後に
        // 表示していた実フォルダへ main を移す。close_fullscreen は cursor を selected へ戻すため、
        // bundle の selected item を再選択すれば同じファイルを可視範囲へ戻せる。
        let selected_media_path = closed.selected.and_then(|idx| {
            closed.items.get(idx).and_then(|item| match item {
                GridItem::Video(path) | GridItem::Audio(path) => Some(path.clone()),
                _ => None,
            })
        });
        let destination = closed
            .archive_source_override
            .clone()
            .or_else(|| closed.current_folder.clone());
        self.clear_bookmark_view_return_state();
        let Some(destination) = destination else {
            return;
        };
        crate::logger::log(format!(
            "[bookmark-open] detached media closed after navigation; load main folder={}",
            destination.display()
        ));
        if !matches!(
            self.load_folder_or_convert_archive_with_auto_fullscreen(destination, false),
            FolderOpenOutcome::Loaded
        ) {
            return;
        }
        if let Some(path) = selected_media_path
            && let Some(idx) = self.items.iter().position(|item| match item {
                GridItem::Video(candidate) | GridItem::Audio(candidate) => {
                    crate::path_key::eq_keep_drive(candidate, &path)
                }
                _ => false,
            })
        {
            self.selected = Some(idx);
            self.scroll_to_selected = true;
        }
    }

    #[cfg(windows)]
    pub(crate) fn update_active_detached_viewer_context(&mut self, ctx: &egui::Context) -> bool {
        if self.active_detached_viewer_context.is_none() {
            return false;
        }

        let (should_drop, detached_viewport_finalized) = self
            .with_active_detached_viewer_context(|app| {
                let close_viewport_id = (app.fs_viewport_shown
                    && app.fs_viewport_presentation == Some(ViewerPresentation::DetachedWindow))
                .then(|| app.fullscreen_viewport_id());
                if Self::detached_image_window_debug_enabled() && app.frame_counter % 60 == 0 {
                    app.log_detached_image_window_debug(format!(
                        "active_context_state frame={} window_id={:?} fs_idx={:?} \
                         independent={} session={:?} fs_shown={} presentation={:?} \
                         current_pending={} pending={} cache={} pdf_enum={} zip_enum={} \
                         nav_wait={} passive_windows={}",
                        app.frame_counter,
                        app.detached_viewer_window_id,
                        app.fullscreen_idx,
                        app.detached_viewer_independent_active,
                        app.active_detached_session,
                        app.fs_viewport_shown,
                        app.fs_viewport_presentation,
                        app.fullscreen_idx
                            .is_some_and(|idx| app.fs_pending.contains_key(&idx)),
                        app.fs_pending.len(),
                        app.fs_cache.len(),
                        app.pdf_enumerate_pending.is_some(),
                        app.zip_enumerate_pending.is_some(),
                        app.fs_nav_deferred_reopen_wait_active(),
                        app.detached_image_windows.len()
                    ));
                }
                if let Some(result) = app.poll_folder_nav() {
                    app.apply_folder_nav_result(ctx, result);
                }
                let _ = app.poll_detached_physical_folder_open(ctx);
                app.poll_pdf_enumerate();
                app.poll_zip_enumerate();
                app.poll_prefetch(ctx);
                // per-context 化した thumb channel の掃除 (review-v2.3.0 P2-9): detached
                // context はグリッドを描かず poll_thumbnails を回さないので、ZIP 内動画の
                // サムネ抽出などが送ってきた結果を放置すると自分の rx に溜まり続ける。
                // 表示する場が無いので読み捨てる (サムネ状態は Pending のまま = 従来挙動)。
                app.drain_thumb_results_discard();
                // main の thumbnail/prefetch 結果回収後と同じ位置で、mounted owner の nav lock を poll する。
                app.poll_fs_nav_lock(ctx);
                if app.current_viewer_context_contains_video() {
                    app.poll_video(ctx);
                }
                app.poll_bookmark_media_open(ctx);
                app.poll_bookmark_book_open(ctx);
                // metadata / tag hydrate は表示 context ごとの cache と pending を持つ。
                // active bundle を mount している間に回収し、main grid へ結果を混入させない。
                app.poll_metadata_load();
                app.poll_tag_prewarm_results();
                app.poll_tag_legacy_seed_results();
                // 名前 facet の正規化結果も items と同じ bundle が所有する。active detached
                // を mount したこの境界で pending を回収し、main の cache へ混入させない。
                // 入力の debounce (App 全体の状態) は main を mount した本流だけが進める。
                app.poll_facet_name_cache(ctx);
                app.poll_ai_upscale(ctx);
                app.poll_final_ai(ctx);
                app.poll_erase_inpaint(ctx);
                app.poll_local_adjust_render(ctx);
                app.poll_local_adjust_layer_bypass_preview(ctx);
                app.poll_local_adjust_prefix_preview(ctx);
                app.poll_local_adjust_lut_load(ctx);
                app.poll_local_adjust_segmentation(ctx);

                if app.active_detached_transition_outstanding() {
                    ctx.request_repaint_after(std::time::Duration::from_millis(16));
                }

                if let Some(fs_idx) = app.fullscreen_idx {
                    app.sync_upscale_from_preset(fs_idx);
                    let continuous_keep_set = if !app.reading_flow.is_paged()
                        && app.fs_vertical_cache_keep_set.contains(&fs_idx)
                    {
                        Some(app.fs_vertical_cache_keep_set.clone())
                    } else {
                        None
                    };
                    let spread_other: Option<usize> = match app.resolve_spread_pair(fs_idx) {
                        crate::ui_fullscreen::SpreadPair::Double { left, right } => {
                            Some(if left == fs_idx { right } else { left })
                        }
                        _ => None,
                    };
                    let mut targets: Vec<usize> = Vec::with_capacity(2);
                    targets.push(fs_idx);
                    if let Some(other) = spread_other {
                        targets.push(other);
                    }
                    if let Some(keep_set) = continuous_keep_set.as_ref() {
                        targets.extend(keep_set.iter().copied());
                    }
                    targets.sort_unstable();
                    targets.dedup();
                    for idx in targets {
                        app.maybe_native_rerender_pdf_for_ai(idx);
                    }
                    if let Some(keep_set) = continuous_keep_set.as_ref() {
                        app.evict_final_pipeline_cache_for_keep_set(keep_set);
                    } else {
                        app.evict_final_pipeline_cache(fs_idx);
                    }
                    if let Some(other) = spread_other {
                        app.maybe_start_local_adjust_render(other);
                    }
                    app.maybe_start_local_adjust_render(fs_idx);
                    if let Some(keep_set) = continuous_keep_set.as_ref() {
                        app.evict_adjustment_cache_for_keep_set(keep_set);
                    } else {
                        app.evict_adjustment_cache(fs_idx);
                    }
                    app.prefetch_final_ai(ctx, fs_idx);
                }

                app.keep_fullscreen_viewport_alive(ctx);
                app.render_fullscreen_viewport(ctx);

                if std::mem::take(&mut app.pending_return_to_parent) {
                    app.close_fullscreen();
                }

                let detached_viewport_finalized = if app.fullscreen_idx.is_none()
                    && !app.detached_active_window_alive_wanted()
                    && let Some(viewport_id) = close_viewport_id
                {
                    app.finalize_closed_active_detached_viewport(ctx, viewport_id);
                    true
                } else {
                    false
                };
                let should_drop = app.fullscreen_idx.is_none()
                    && !app.active_detached_transition_outstanding()
                    && !app.fs_viewport_shown;
                (should_drop, detached_viewport_finalized)
            })
            .unwrap_or((false, false));

        if should_drop {
            let closed = if detached_viewport_finalized {
                self.active_detached_viewer_context
                    .take()
                    .map(|active| active.bundle)
            } else {
                self.take_and_close_current_active_detached_viewer_context(
                    ctx,
                    "active_terminal_before_viewport",
                )
            };
            if let Some(closed) = closed {
                self.reconcile_closed_bookmark_detached_context(&closed);
            }
        }
        true
    }

    #[cfg(windows)]
    fn rearm_final_ai_prefetch_after_detached_resume(&mut self) {
        let Some(fs_idx) = self.fullscreen_idx else {
            return;
        };
        let mut resume_targets = self.ai_prefetch_targets(fs_idx);
        resume_targets.push(fs_idx);
        resume_targets.sort_unstable();
        resume_targets.dedup();
        self.final_ai_failed
            .retain(|key| !resume_targets.contains(&key.edit_key.idx));
    }

    #[cfg(windows)]
    fn detached_viewer_open_still_requested(&self, idx: usize) -> bool {
        self.viewer_item_supports_detached_still(idx)
            && (self.settings.detached_viewer_open_images_in_window
                || self.detached_viewer_open_next_still_detached_once)
    }

    #[cfg(windows)]
    fn detached_still_open_is_independent(&self, idx: usize) -> bool {
        self.viewer_item_supports_detached_still(idx)
            && (self.settings.detached_viewer_open_images_in_window
                || self.detached_viewer_open_next_still_detached_once)
    }

    #[cfg(windows)]
    fn detached_image_snapshot_title_for_idx(&self, idx: usize) -> String {
        let name = self
            .items
            .get(idx)
            .map(|item| item.name().into_owned())
            .unwrap_or_default();
        if name.trim().is_empty() {
            "mimageviewer".to_string()
        } else {
            format!("{name} - mimageviewer")
        }
    }

    #[cfg(windows)]
    fn detached_image_snapshot_location_for_idx(&self, idx: usize) -> String {
        self.items
            .get(idx)
            .map(|item| item.name().into_owned())
            .unwrap_or_default()
    }

    #[cfg(windows)]
    fn offset_detached_image_window_placement(
        &self,
        base: crate::settings::DetachedViewerWindowPlacement,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        let mut placement = base;
        placement.x += 40.0;
        placement.y += 40.0;
        placement.maximized = false;
        if placement.is_sane()
            && crate::monitor::title_bar_on_some_monitor(placement.x, placement.y, placement.w)
        {
            placement
        } else {
            self.default_detached_viewer_window_placement()
        }
    }

    #[cfg(windows)]
    pub(crate) fn active_detached_viewer_current_placement(
        &self,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        self.active_detached_seed_placement()
    }

    #[cfg(windows)]
    pub(crate) fn detached_passive_placement_update_looks_like_default_viewport(
        previous: crate::settings::DetachedViewerWindowPlacement,
        candidate: crate::settings::DetachedViewerWindowPlacement,
        pixels_per_point: f32,
        apply_initial_placement: bool,
    ) -> bool {
        if apply_initial_placement || previous.maximized || candidate.maximized {
            return false;
        }
        let ppp = pixels_per_point.clamp(0.5, 4.0);
        let default_w = candidate.w * ppp;
        let default_h = candidate.h * ppp;
        let near_default_800x600 =
            (default_w - 800.0).abs() <= 40.0 && (default_h - 600.0).abs() <= 40.0;
        if !near_default_800x600 {
            return false;
        }
        let shrank_hard = candidate.w < previous.w * 0.80 || candidate.h < previous.h * 0.80;
        let moved_far =
            (candidate.x - previous.x).abs() > 64.0 || (candidate.y - previous.y).abs() > 64.0;
        let previous_was_substantial = previous.w >= 700.0 || previous.h >= 520.0;
        shrank_hard && moved_far && previous_was_substantial
    }

    #[cfg(windows)]
    pub(crate) fn detached_active_placement_update_looks_like_default_viewport(
        previous: crate::settings::DetachedViewerWindowPlacement,
        candidate: crate::settings::DetachedViewerWindowPlacement,
        pixels_per_point: f32,
    ) -> bool {
        if previous.maximized || candidate.maximized {
            return false;
        }
        let ppp = pixels_per_point.clamp(0.5, 4.0);
        let default_w = candidate.w * ppp;
        let default_h = candidate.h * ppp;
        let near_default_800x600 =
            (default_w - 800.0).abs() <= 40.0 && (default_h - 600.0).abs() <= 40.0;
        if !near_default_800x600 {
            return false;
        }
        let shrank_hard = candidate.w < previous.w * 0.80 || candidate.h < previous.h * 0.80;
        let previous_was_substantial = previous.w >= 700.0 || previous.h >= 520.0;
        shrank_hard && previous_was_substantial
    }

    #[cfg(windows)]
    fn build_active_detached_image_window_snapshot(
        &mut self,
        ctx: Option<&egui::Context>,
    ) -> Option<DetachedImageWindowSnapshot> {
        let Some(idx) = self.fullscreen_idx else {
            self.log_detached_image_window_debug(format!(
                "build_active_snapshot_failed reason=no_fullscreen_idx \
                 window_id={:?} pending={} cache={}",
                self.detached_viewer_window_id,
                self.fs_pending.len(),
                self.fs_cache.len()
            ));
            return None;
        };
        if !self.viewer_session_is_detached() || !self.viewer_item_supports_detached_still(idx) {
            self.log_detached_image_window_debug(format!(
                "build_active_snapshot_failed reason=unsupported_or_not_detached idx={idx} \
                 session_detached={} supported={} window_id={:?} \
                 presentation={:?} pending={} cache={}",
                self.viewer_session_is_detached(),
                self.viewer_item_supports_detached_still(idx),
                self.detached_viewer_window_id,
                self.viewer_presentation,
                self.fs_pending.len(),
                self.fs_cache.len()
            ));
            return None;
        }
        let Some(texture) = self.resolve_fs_display_tex(idx, true) else {
            self.log_detached_image_window_debug(format!(
                "build_active_snapshot_failed reason=no_display_texture idx={idx} \
                 window_id={:?} current_pending={} pending={} \
                 cache={} thumb_loaded={} descriptor={} stamp={}",
                self.detached_viewer_window_id,
                self.fs_pending.contains_key(&idx),
                self.fs_pending.len(),
                self.fs_cache.len(),
                matches!(
                    self.thumbnails.get(idx),
                    Some(crate::grid_item::ThumbnailState::Loaded { .. })
                ),
                Self::detached_viewer_descriptor_debug_kind(
                    &self.detached_viewer_context_descriptor_for_idx(idx)
                ),
                self.viewer_sync_stamp_for_idx(idx).is_some()
            ));
            return None;
        };
        let texture_size = texture.size_vec2();
        let rotation = self.get_rotation(idx);
        let zoom_pan = self.fs_zoom_pan();
        let free_rotation = self.fs_free_rotation;
        let id = self.ensure_detached_viewer_window_id();
        let placement = self.ensure_detached_window_runtime_placement(id, "build_active_snapshot");
        let pixels_per_point = ctx
            .map(egui::Context::pixels_per_point)
            .unwrap_or(self.detached_viewer_last_pixels_per_point);
        let (image_rect_norm, image_content_bbox) = self.detached_single_image_snapshot_layout(
            idx,
            placement,
            pixels_per_point,
            texture_size,
            rotation,
            zoom_pan,
            free_rotation,
        );
        let rotated_size = match rotation {
            crate::rotation_db::Rotation::Cw90 | crate::rotation_db::Rotation::Cw270 => {
                egui::vec2(texture_size.y, texture_size.x)
            }
            _ => texture_size,
        };
        let logical_scale = (image_rect_norm.width() * placement.w / rotated_size.x.max(1.0))
            .min(image_rect_norm.height() * placement.h / rotated_size.y.max(1.0));
        let snapshot_rect = egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(placement.w.max(1.0), placement.h.max(1.0)),
        );
        let image_rect = egui::Rect::from_min_max(
            egui::pos2(
                image_rect_norm.min.x * snapshot_rect.width(),
                image_rect_norm.min.y * snapshot_rect.height(),
            ),
            egui::pos2(
                image_rect_norm.max.x * snapshot_rect.width(),
                image_rect_norm.max.y * snapshot_rect.height(),
            ),
        );
        let visible_source_uv_rect =
            crate::displayed_image_transform::DisplayedImageTransform::from_resolved_rect(
                crate::displayed_image_transform::DisplayedImageTransformInput {
                    page_idx: idx,
                    viewport_rect: snapshot_rect,
                    source_size: texture_size,
                    texture_size,
                    rotation,
                    free_rotation_rad: free_rotation,
                    content_bbox: image_content_bbox,
                    fit_mode: crate::settings::FullscreenFitMode::Page,
                    fit_scale_limits:
                        crate::displayed_image_transform::FullscreenFitScaleLimits::default(),
                    pixels_per_point,
                    placement: crate::displayed_image_transform::ResolvedDisplayPlacement::Normal {
                        zoom_pan: None,
                    },
                },
                image_rect,
            )
            .and_then(|transform| transform.visible_source_uv_rect(snapshot_rect));
        let texture = self.fullscreen_paint_resource_for_texture(idx, texture);
        let texture = self.prepare_fullscreen_paint_resource(
            &texture,
            logical_scale,
            pixels_per_point,
            visible_source_uv_rect,
        );
        let frozen_continuous_pages = ctx
            .map(|ctx| self.detached_frozen_pages_for_snapshot(ctx, id, idx, placement))
            .unwrap_or_default();
        let reopen_descriptor = self.parked_still_reopen_descriptor_for_idx(idx);
        let reopen_sync_stamp = self.viewer_sync_stamp_for_idx(idx);
        self.log_detached_image_window_debug(format!(
            "build_active_snapshot_ok id={id} idx={idx} \
             tex=({:.0}x{:.0}) descriptor={} stamp={} frozen_pages={} \
             current_pending={} pending={} cache={} placement={placement:?}",
            texture_size.x,
            texture_size.y,
            Self::detached_viewer_descriptor_debug_kind(&reopen_descriptor),
            reopen_sync_stamp.is_some(),
            frozen_continuous_pages.len(),
            self.fs_pending.contains_key(&idx),
            self.fs_pending.len(),
            self.fs_cache.len()
        ));
        Some(DetachedImageWindowSnapshot {
            id,
            texture,
            title: self.detached_image_snapshot_title_for_idx(idx),
            location_display: self.detached_image_snapshot_location_for_idx(idx),
            image_dims: Some((texture_size.x as u32, texture_size.y as u32)),
            rotation,
            zoom_pan,
            free_rotation,
            image_rect_norm,
            image_content_bbox,
            frozen_continuous_pages,
            reopen_descriptor,
            reopen_sync_stamp,
            activation_ready_frame: self.frame_counter.saturating_add(1),
            activation_armed: false,
            focused_last_frame: false,
            initial_placement_applied: false,
            paused_bundle: None,
        })
    }

    #[cfg(windows)]
    fn build_parked_live_media_window_snapshot(
        &mut self,
        ctx: &egui::Context,
    ) -> Option<DetachedImageWindowSnapshot> {
        let idx = self.fullscreen_idx?;
        if !self.viewer_session_is_detached() || !self.current_viewer_context_contains_video() {
            return None;
        }
        let id = self.ensure_detached_viewer_window_id();
        let placement =
            self.ensure_detached_window_runtime_placement(id, "build_parked_live_media_snapshot");
        let texture = ctx.load_texture(
            format!("parked_live_media_backdrop_{id}"),
            egui::ColorImage::new([1, 1], vec![egui::Color32::BLACK]),
            egui::TextureOptions::LINEAR,
        );
        let title = self.detached_image_snapshot_title_for_idx(idx);
        let location_display = self.detached_image_snapshot_location_for_idx(idx);
        self.log_detached_image_window_debug(format!(
            "build_parked_live_media_snapshot_ok id={id} idx={idx} title={title:?} \
             placement={placement:?}"
        ));
        Some(DetachedImageWindowSnapshot {
            id,
            texture: crate::gpu_lanczos::FullscreenPaintResource::direct(texture),
            title,
            location_display,
            image_dims: None,
            rotation: crate::rotation_db::Rotation::None,
            zoom_pan: None,
            free_rotation: 0.0,
            image_rect_norm: egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)),
            image_content_bbox: None,
            frozen_continuous_pages: Vec::new(),
            reopen_descriptor: None,
            reopen_sync_stamp: None,
            activation_ready_frame: self.frame_counter.saturating_add(1),
            activation_armed: false,
            focused_last_frame: false,
            initial_placement_applied: false,
            paused_bundle: None,
        })
    }

    #[cfg(windows)]
    fn park_current_viewer_context_as_live_media(
        &mut self,
        ctx: &egui::Context,
        reason: &'static str,
    ) -> bool {
        self.park_current_viewer_context_as_live_media_inner(ctx, reason, true)
    }

    /// スタック集約の適用直前に、bundle 化前の detached セッションを退避する
    /// (`poll_stack_script` 専用)。main の items を集約ビューへ差し替えるため、
    /// main items を参照している unbundled セッションを残したまま適用できない。
    /// - メディア (動画/音声): in-place live-park。窓は再生を続け、main 文脈は
    ///   clone で維持される (= 現行フォルダと stack pending が生きる)。
    /// - 画像 still: フォルダ移動時と同じ preserve → close_fullscreen の対で
    ///   parked still 化する (集約後は元 idx が存在しないため能動セッションを残せない)。
    #[cfg(windows)]
    pub(crate) fn park_detached_session_for_stack_aggregation(&mut self, ctx: &egui::Context) {
        if !self.viewer_session_is_detached() {
            return;
        }
        if self.current_viewer_context_contains_video()
            && self.park_current_viewer_context_as_live_media(ctx, "stack_aggregation")
        {
            return;
        }
        self.preserve_active_detached_image_window_for_main_context_change();
        self.close_fullscreen();
    }

    #[cfg(windows)]
    fn park_current_viewer_context_as_live_media_inner(
        &mut self,
        ctx: &egui::Context,
        reason: &'static str,
        preserve_main_context: bool,
    ) -> bool {
        let Some(mut snapshot) = self.build_parked_live_media_window_snapshot(ctx) else {
            return false;
        };
        let snapshot_id = snapshot.id;
        let mut parked_bundle = if preserve_main_context {
            self.split_current_context_preserving_main_grid()
        } else {
            Box::new(self.take_current_viewer_context_bundle())
        };
        if !Self::viewer_context_bundle_contains_video(&parked_bundle) {
            if !preserve_main_context {
                self.swap_viewer_context_bundle(&mut parked_bundle);
            }
            return false;
        }
        parked_bundle
            .viewer_session
            .activate_independent_detached(snapshot_id);
        snapshot.paused_bundle = Some(parked_bundle);
        self.detached_image_windows.push(snapshot);
        // mounted/active owner の pending を ParkedLive window へ焼き直す。別 parked window の
        // owner は一致しないため変更しない (review-v2.3.0 追補2 BA-7)。
        self.rebind_native_video_pending_owners(None, Some(snapshot_id), "parked_live_park_commit");
        self.update_detached_window_runtime_flags(snapshot_id, false, reason);
        self.handoff_active_detached_viewport_to_passive(reason);
        self.transition_detached_window_state(snapshot_id, DetachedWindowState::ParkedLive, reason);
        self.fullscreen_idx = None;
        self.viewer_presentation = self.non_detached_viewer_presentation();
        self.detached_viewer_independent_active = false;
        self.detached_viewer_window_id = None;
        self.last_viewer_sync_stamp = None;
        self.log_detached_image_window_debug(format!(
            "parked_live_media_committed id={snapshot_id} reason={reason} passive_windows={}",
            self.detached_image_windows.len()
        ));
        true
    }

    /// legacy/unbundled viewer 用に、現在 context を main と独立 viewer に分割する。
    ///
    /// main grid が使う一覧 identity / worker 複合体は main に残し、viewer の一時状態だけを
    /// 戻り値へ移す。ParkedLive media と、通常画像を grid から always-new detached viewer
    /// として開く境界の両方がこの primitive を使う。
    ///
    /// `ViewerContextBundle` の全 field を destructure して 3 分類するため、field 追加時は
    /// コンパイルエラーになり、空 bundle + allowlist 方式の状態喪失を再発させない。
    /// (review-v2.3.0 追補4: live-park main 文脈保持)
