    #[cfg(windows)]
    fn current_context_is_materialized_physical_source(&self, physical_context: &Path) -> bool {
        self.current_folder
            .as_deref()
            .is_some_and(|current| crate::folder_tree::path_eq(current, physical_context))
            && !self.items_are_global_search_view
            && !self.items_are_tag_view
            && !self.items_are_reading_history_view
            && !self.items_are_bookmark_view
            && !self.items_are_rating_view
            && !self.items_are_subfolder_expansion_view
            && !self.items_are_smart_folder_view
            && !self.items_are_drive_list
            && !self.is_snapshot_active()
    }

    /// folder / ZIP / PDF の完全な物理一覧を main へ materialize した後に発火する
    /// auto-fullscreen を、main と共有された legacy viewer ではなく active bundle へ移す。
    ///
    /// 仮想一覧の leaf open は `open_grid_item_in_detached_book_context_with_auto_fullscreen`
    /// が先に descriptor 化して非同期列挙する。この fallback は `current_folder` と
    /// materialized source が一致し、仮想 surface flag がすべて落ちた場合にだけ使う。
    #[cfg(windows)]
    fn route_materialized_physical_still_open_to_active_context(&mut self, idx: usize) -> bool {
        if self.active_detached_viewer_context.is_some()
            || !matches!(self.navigation_scope, ViewerNavigationScope::Main)
            || self.detached_viewer_main_history_suppression_depth != 0
            || self.fullscreen_idx.is_some()
            || self.detached_viewer_folder_nav_reuse_window_once
            || !self.fs_open_intent_from_grid
            || !self.detached_still_open_is_independent(idx)
            || !matches!(
                self.effective_viewer_presentation_for_open(idx),
                ViewerPresentation::DetachedWindow
            )
        {
            return false;
        }

        let physical_context = match self.items.get(idx) {
            Some(GridItem::Image(path)) => path.parent().map(Path::to_path_buf),
            Some(GridItem::ZipImage { zip_path, .. }) => Some(zip_path.clone()),
            Some(GridItem::PdfPage { pdf_path, .. }) => Some(pdf_path.clone()),
            _ => None,
        };
        let Some(physical_context) = physical_context else {
            return false;
        };
        if !self.current_context_is_materialized_physical_source(&physical_context) {
            return false;
        }

        let (_context_serial, items_generation) =
            self.allocate_detached_viewer_context_generation();
        let mut bundle = self.split_materialized_physical_context_for_independent_still_open();
        bundle.navigation_scope = ViewerNavigationScope::DetachedPhysical;
        bundle.set_items_generation(items_generation);
        bundle.address = physical_context.display().to_string();
        bundle.current_folder = Some(physical_context.clone());
        bundle.visible_indices = bundle
            .items
            .iter()
            .enumerate()
            .filter_map(|(item_idx, item)| {
                item_belongs_to_detached_physical_scope(item, &physical_context).then_some(item_idx)
            })
            .collect();
        bundle.top_level_grid_view = top_level_grid_view::TopLevelGridView::default();
        bundle.details_thumb_suppression_applied = false;
        bundle.details_order.clear();
        bundle.cached_nav_indices = None;
        bundle.cached_fs_seek_info = None;
        bundle.selected = Some(idx);

        self.active_detached_viewer_context = Some(ActiveDetachedViewerContext { bundle: *bundle });
        self.log_detached_image_window_debug(format!(
            "materialized_physical_context_promoted idx={idx} main_items={} active_context=true",
            self.items.len()
        ));

        self.with_active_detached_viewer_context(|detached| {
            detached.open_fullscreen(idx, crate::app::HistoryTrigger::UserChosen);
        })
        .expect("materialized physical context must remain present while opening");
        true
    }

    #[cfg(windows)]
    fn park_active_detached_context_as_live_media(
        &mut self,
        ctx: &egui::Context,
        reason: &'static str,
    ) -> bool {
        let Some(mut active) = self.active_detached_viewer_context.take() else {
            return false;
        };
        if !Self::viewer_context_bundle_contains_video(&active.bundle) {
            self.active_detached_viewer_context = Some(active);
            return false;
        }
        let parked_window_id = active.bundle.viewer_session.detached_window_id;
        self.swap_viewer_context_bundle(&mut active.bundle);
        let parked = self.park_current_viewer_context_as_live_media_inner(ctx, reason, false);
        self.swap_viewer_context_bundle(&mut active.bundle);
        if !parked {
            self.active_detached_viewer_context = Some(active);
        } else if parked_window_id.is_some() && self.detached_viewer_window_id == parked_window_id {
            // park_inner の window_id クリアは take_current 後の**空バンドル側**に書かれるため、
            // ここで復元した main 文脈には parked 窓 id の stale コピーが残り得る。残すと直後の
            // grid open (ensure_detached_viewer_window_id の直参照分岐) が同じ id を再利用し、
            // parked live メディア窓と新セッションが同一窓を取り合う (2026-07-09 実機、BA-7)。
            self.detached_viewer_window_id = None;
        }
        parked
    }

    #[cfg(windows)]
    fn park_active_detached_image_window(&mut self) -> bool {
        if let Some(fs_idx) = self.fullscreen_idx {
            self.reset_detached_pause_foreground_modes(fs_idx);
        }
        let Some(snapshot) = self.build_active_detached_image_window_snapshot(None) else {
            return false;
        };
        let snapshot_id = snapshot.id;
        self.detached_image_windows.push(snapshot);
        self.update_detached_window_runtime_flags(
            snapshot_id,
            false,
            "park_active_detached_image_window",
        );
        self.transition_detached_window_state(
            snapshot_id,
            DetachedWindowState::Parked,
            "park_active_detached_image_window",
        );
        true
    }

    #[cfg(windows)]
    fn fullfeature_linked_still_media_window_mode(&self) -> bool {
        self.settings.detached_viewer_enabled
            && !self.settings.detached_viewer_open_images_in_window
            && self.settings.effective_media_in_media_window()
    }

    #[cfg(windows)]
    fn should_preserve_active_detached_image_window_for_main_context_change(&self) -> bool {
        self.should_preserve_active_detached_image_window_for_main_context_change_inner(false)
    }

    #[cfg(windows)]
    fn should_preserve_active_detached_image_window_for_main_context_change_inner(
        &self,
        preserve_fullfeature_linked_still: bool,
    ) -> bool {
        let Some(idx) = self.fullscreen_idx else {
            return false;
        };
        // フォルダナビ (Ctrl+↑↓) の reopen 中は、現在の detached ウィンドウを passive
        // snapshot として park せず、そのまま内容を差し替えて再利用する。park すると
        // 旧ウィンドウが passive で残り、reopen 側が新しい window_id を allocate して
        // 別ウィンドウを生成してしまう (= 次フォルダへ移るたびにウィンドウが再生成)。
        if self.fs_nav_is_locked() {
            return false;
        }
        self.viewer_session_is_detached()
            && self.viewer_item_supports_detached_still(idx)
            && (self.settings.detached_viewer_open_images_in_window
                // review-v2.3.0 追補5: §1.7 linked still × media open。
                // 通常の main context change では CUT 後の linked 非 passive 仕様を維持し、
                // media handoff と明示されたときだけ F12 linked still を退避可能にする。
                || (preserve_fullfeature_linked_still
                    && !self.settings.detached_viewer_open_images_in_window
                    && self.settings.fullfeature_media_window))
    }

    #[cfg(windows)]
    fn preserve_active_detached_image_window_for_main_context_change(&mut self) -> bool {
        self.preserve_active_detached_image_window_for_main_context_change_inner(false)
    }

    #[cfg(windows)]
    fn preserve_active_detached_image_window_for_main_context_change_inner(
        &mut self,
        preserve_fullfeature_linked_still: bool,
    ) -> bool {
        if !self.should_preserve_active_detached_image_window_for_main_context_change_inner(
            preserve_fullfeature_linked_still,
        ) {
            let actual_session_window = self
                .active_detached_session
                .map(|session| session.window_id);
            let actual_session_source = self
                .active_detached_session
                .map(|session| format!("{:?}", session.source))
                .unwrap_or_else(|| "None".to_string());
            self.log_detached_image_window_debug(format!(
                "preserve_active_detached_for_main_change skipped fs_idx={:?} \
                 session_detached={} independent={} active_context={} \
                 window_id={:?} actual_session_window={actual_session_window:?} \
                 actual_session_source={actual_session_source} passive_windows={} \
                 fs_nav_locked={}",
                self.fullscreen_idx,
                self.viewer_session_is_detached(),
                self.detached_viewer_independent_active,
                self.active_detached_viewer_context.is_some(),
                self.detached_viewer_window_id,
                self.detached_image_windows.len(),
                self.fs_nav_is_locked()
            ));
            return false;
        }
        let parked_window_id = self.detached_viewer_window_id;
        let parked_as_fullfeature_linked_still =
            preserve_fullfeature_linked_still && self.fullfeature_linked_still_media_window_mode();
        let parked = self.park_active_detached_image_window();
        self.log_detached_image_window_debug(format!(
            "preserve_active_detached_for_main_change result={parked} \
             fs_idx={:?} window_id={:?} passive_windows={} active_context={} \
             session_before_handoff={:?}",
            self.fullscreen_idx,
            self.detached_viewer_window_id,
            self.detached_image_windows.len(),
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session
        ));
        if parked {
            if parked_as_fullfeature_linked_still && let Some(window_id) = parked_window_id {
                // review-v2.3.0 追補5 完結編: media handoff で退避した linked still。
                // Parked + linked を one-shot identity とし、次の still grid open で同じ
                // viewport を取り戻す。close は runtime ごと削除、直接 activate は linked
                // を false にするため stale id を再利用しない。
                self.update_detached_window_runtime_flags(
                    window_id,
                    true,
                    "fullfeature_linked_still_media_handoff",
                );
            }
            self.handoff_active_detached_viewport_to_passive("main_context_change");
            if let Some(window_id) = parked_window_id {
                self.transition_detached_window_state(
                    window_id,
                    DetachedWindowState::Parked,
                    "main_context_change_handoff",
                );
            }
            self.detached_viewer_independent_active = false;
        }
        self.detached_viewer_open_next_still_detached_once = false;
        parked
    }

    #[cfg(windows)]
    fn should_promote_active_detached_video_for_main_context_change(&self) -> bool {
        let Some(idx) = self.fullscreen_idx else {
            return false;
        };
        self.active_detached_viewer_context.is_none()
            // Tray residency keeps both committed detached sessions and an in-flight switch to
            // detached alive. A main-context refresh must use that same lifecycle predicate before
            // replacing `items`, otherwise `start_loading_items` falls through to
            // `close_fullscreen` and drops the session that tray hide deliberately retained.
            && self.viewer_session_is_detached_or_switching()
            && !self.fs_nav_is_locked()
            // 音声もメディア窓を使う (stage-audio / §1.7)。Video 限定だと main の
            // フォルダ移動で detached 音声が promote されず close_fullscreen で
            // 再生ごと止まる (Codex audit P2、複数ウィンドウモードにも存在した既存ギャップ)。
            && self.viewer_item_is_media(idx)
    }

    #[cfg(windows)]
    fn promote_active_detached_video_for_main_context_change(&mut self) -> bool {
        if !self.should_promote_active_detached_video_for_main_context_change() {
            return false;
        }
        let Some(idx) = self.fullscreen_idx else {
            return false;
        };
        let window_id = self.ensure_detached_viewer_window_id();
        let mut bundle = self.take_current_viewer_context_bundle();
        bundle.selected = Some(idx);
        bundle.fullscreen_idx = Some(idx);
        bundle.native_video_in_window_active = false;
        bundle
            .viewer_session
            .activate_independent_detached(window_id);
        bundle.viewer_session.last_sync_stamp = None;
        bundle.fs_open_intent_from_grid = false;
        bundle.pending_auto_fs_open = false;
        bundle.pending_return_to_parent = false;
        self.active_detached_viewer_context = Some(ActiveDetachedViewerContext { bundle });
        self.update_detached_window_runtime_flags(
            window_id,
            false,
            "promote_detached_video_for_main_context_change",
        );
        self.transition_detached_window_state(
            window_id,
            DetachedWindowState::Active,
            "promote_detached_video_for_main_context_change",
        );

        self.fullscreen_idx = None;
        self.viewer_presentation = self.non_detached_viewer_presentation();
        self.detached_viewer_independent_active = false;
        self.detached_viewer_open_next_still_detached_once = false;
        self.detached_viewer_focus_requested = false;
        self.last_viewer_sync_stamp = None;
        self.detached_viewer_window_id = None;
        self.log_detached_image_window_debug(format!(
            "promote_detached_video_for_main_context_change window_id={window_id} idx={idx}"
        ));
        true
    }

    #[cfg(windows)]
    fn prepare_detached_image_windows_for_open(&mut self, idx: usize) {
        if !self.fs_open_intent_from_grid || !self.viewer_item_supports_detached_still(idx) {
            return;
        }
        let always_new = self.settings.detached_viewer_open_images_in_window;
        if !always_new {
            return;
        }

        let current_idx = self.fullscreen_idx;
        let should_park_active = current_idx != Some(idx)
            && self.viewer_session_is_detached()
            && current_idx.is_some_and(|current| self.viewer_item_supports_detached_still(current))
            && always_new;
        let base_placement = self.active_detached_viewer_current_placement();
        let parked = if should_park_active {
            self.park_active_detached_image_window()
        } else {
            false
        };
        if should_park_active {
            self.detached_viewer_independent_active = false;
        }
        let mut should_recreate_active_viewport = false;

        if parked {
            let window_id = self.allocate_detached_viewer_window_id();
            self.log_detached_image_window_debug(format!(
                "allocate_window_id reason=prepare_detached_image_windows_for_open id={window_id} \
                 idx={idx} current_idx={current_idx:?} always_new={always_new} \
                 grid_intent={} folder_nav_reuse_once={} \
                 base_placement={base_placement:?}",
                self.fs_open_intent_from_grid, self.detached_viewer_folder_nav_reuse_window_once
            ));
            self.detached_viewer_window_id = Some(window_id);
            self.transition_detached_window_state(
                window_id,
                DetachedWindowState::Opening,
                "prepare_detached_image_windows_for_open_allocate",
            );
            let offset_placement = self.offset_detached_image_window_placement(base_placement);
            self.set_detached_window_runtime_placement(
                window_id,
                offset_placement,
                "prepare_detached_image_windows_for_open_allocate",
            );
            self.detached_viewer_open_next_still_detached_once = false;
            should_recreate_active_viewport = true;
        }

        if should_recreate_active_viewport
            && self.fs_viewport_shown
            && self.fs_viewport_presentation == Some(ViewerPresentation::DetachedWindow)
        {
            self.reset_active_detached_viewport_runtime_for_new_window(
                self.fs_viewport_generation,
                "prepare_detached_image_windows_for_open",
            );
        }
    }

    #[cfg(windows)]
    fn detached_viewer_independent_still_session(&self) -> bool {
        self.viewer_session_is_detached()
            && self.detached_viewer_independent_active
            && self
                .fullscreen_idx
                .is_some_and(|idx| self.viewer_item_supports_detached_still(idx))
    }

    #[cfg(windows)]
    pub(crate) fn detached_physical_folder_nav_available(&self) -> bool {
        self.navigation_scope.is_detached_physical()
            && self.detached_viewer_independent_still_session()
    }

    #[cfg(windows)]
    fn detached_viewer_independent_session(&self) -> bool {
        self.viewer_session_is_detached() && self.detached_viewer_independent_active
    }

    #[cfg(windows)]
    pub(crate) fn detached_independent_session_blocks_folder_nav(&self) -> bool {
        if self.active_detached_viewer_context.is_some() {
            return true;
        }
        if self.detached_viewer_independent_session() {
            return true;
        }
        // §1.7 第3状態 (フル機能+メディア別窓): メディア窓セッション (bundle 化前を
        // 含む) は複数ウィンドウモードの detached 窓と同じく folder nav を consume する。
        // これを落とすと、メディア窓からの Ctrl+↑↓ が main のフォルダナビとして走り、
        // close/reopen 経路がメディアセッションを巻き込んで閉じる (Codex audit P1)。
        if self.settings.effective_media_in_media_window()
            && self.viewer_session_is_detached()
            && self
                .fullscreen_idx
                .is_some_and(|idx| self.viewer_item_is_media(idx))
        {
            return true;
        }
        self.settings.detached_viewer_open_images_in_window && self.viewer_session_is_detached()
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_image_edit_tools_disabled_reason(&self) -> Option<&'static str> {
        if self.settings.detached_viewer_open_images_in_window
            && self.viewer_session_is_detached_or_switching()
        {
            return Some("毎回新しい別ウィンドウで開く設定では、画像編集機能は利用できません");
        }
        if self.detached_viewer_independent_still_session() {
            return Some("独立した別ウィンドウでは、画像編集機能は利用できません");
        }
        if self.active_detached_viewer_context.is_some() {
            return Some("切り離した別ウィンドウでは、画像編集機能は利用できません");
        }
        None
    }

    #[cfg(windows)]
    pub(crate) fn vst3_playback_ui_context_is_main_fullscreen(&self) -> bool {
        !self.settings.detached_viewer_open_images_in_window
            && matches!(self.viewer_presentation, ViewerPresentation::Fullscreen)
    }

    #[cfg(windows)]
    pub(crate) fn vst3_playback_controls_available(&self) -> bool {
        self.settings.vst3_enabled && self.vst3_playback_ui_context_is_main_fullscreen()
    }

    #[cfg(windows)]
    pub(crate) fn native_video_vst3_controls_available(&self) -> bool {
        self.vst3_playback_controls_available() && self.native_video_mode_switch.is_none()
    }

    #[cfg(windows)]
    pub(crate) fn music_chrome_should_show_vst(&self, fs_idx: usize) -> bool {
        let video_audio_mode = self.video_audio_mode == Some(fs_idx);
        self.vst3_playback_controls_available()
            && (self.video_audio_mode.is_none() || video_audio_mode)
    }

    #[cfg(not(windows))]
    pub(crate) fn detached_viewer_image_edit_tools_disabled_reason(&self) -> Option<&'static str> {
        None
    }

    #[cfg(windows)]
    fn detached_toggle_disabled_by_always_new_images(&self) -> bool {
        if !self.settings.detached_viewer_open_images_in_window {
            return false;
        }
        !self
            .fullscreen_idx
            .is_some_and(|idx| self.viewer_item_is_media(idx))
    }

    #[cfg(windows)]
    pub(crate) fn always_new_media_f12_target_presentation(&self) -> Option<ViewerPresentation> {
        // §1.7: フル機能+メディア別窓でも同じ F12 トグル (メディア窓 ⇔ メイン) を使う。
        if !self.settings.effective_media_in_media_window() {
            return None;
        }
        let idx = self.fullscreen_idx?;
        if !self.viewer_item_is_media(idx) {
            return None;
        }
        Some(
            if matches!(self.viewer_presentation, ViewerPresentation::DetachedWindow) {
                self.non_detached_viewer_presentation()
            } else {
                ViewerPresentation::DetachedWindow
            },
        )
    }

    #[cfg(windows)]
    pub(crate) fn should_block_detached_independent_still_navigation_to_video(
        &self,
        idx: usize,
    ) -> bool {
        self.detached_viewer_independent_still_session() && self.viewer_item_is_media(idx)
    }

    #[cfg(windows)]
    fn viewer_sync_stamp_for_idx(&self, idx: usize) -> Option<ViewerSyncStamp> {
        if !self.viewer_item_supports_session(idx) {
            return None;
        }
        Some(ViewerSyncStamp {
            idx,
            item_key: self.metadata_cache_key(idx)?,
            items_generation: self.items_generation,
        })
    }

    #[cfg(windows)]
    fn resolve_viewer_sync_stamp_idx(&self, stamp: &ViewerSyncStamp) -> Option<usize> {
        if self.items_generation == stamp.items_generation
            && self
                .viewer_sync_stamp_for_idx(stamp.idx)
                .as_ref()
                .is_some_and(|current| current.item_key == stamp.item_key)
        {
            return Some(stamp.idx);
        }

        self.items.iter().enumerate().find_map(|(idx, _)| {
            if !self.viewer_item_supports_detached_still(idx) {
                return None;
            }
            let key = self.metadata_cache_key(idx)?;
            (key == stamp.item_key).then_some(idx)
        })
    }

    #[cfg(windows)]
    fn non_detached_viewer_presentation(&self) -> ViewerPresentation {
        if self.settings.video_in_window_mode {
            ViewerPresentation::MainWindow
        } else {
            ViewerPresentation::Fullscreen
        }
    }

    #[cfg(windows)]
    fn requested_viewer_presentation_for_open(&self, idx: usize) -> ViewerPresentation {
        if (self.viewer_session_is_detached()
            && self.detached_viewer_independent_active
            && self.viewer_item_supports_detached_still(idx))
            || (self.settings.effective_media_in_media_window() && self.viewer_item_is_media(idx))
            || (self.settings.detached_viewer_enabled && self.viewer_item_supports_session(idx))
            || self.detached_viewer_open_still_requested(idx)
        {
            ViewerPresentation::DetachedWindow
        } else {
            self.non_detached_viewer_presentation()
        }
    }

    #[cfg(windows)]
    fn effective_viewer_presentation_for_open(&self, idx: usize) -> ViewerPresentation {
        match self.requested_viewer_presentation_for_open(idx) {
            ViewerPresentation::DetachedWindow if self.viewer_item_supports_session(idx) => {
                ViewerPresentation::DetachedWindow
            }
            ViewerPresentation::DetachedWindow => self.non_detached_viewer_presentation(),
            presentation => presentation,
        }
    }

    #[cfg(windows)]
    fn clear_pending_main_foreground_reclaim(&mut self) {
        self.pending_main_foreground_reclaim = false;
        self.pending_main_foreground_reclaim_after_hwnd = 0;
        self.pending_main_foreground_reclaim_force_at = None;
    }

    #[cfg(windows)]
    pub(crate) fn viewer_presentation_to_native_video_placement(
        presentation: ViewerPresentation,
    ) -> crate::video::NativeVideoPlacement {
        match presentation {
            ViewerPresentation::MainWindow => crate::video::NativeVideoPlacement::MainWindowChild,
            ViewerPresentation::Fullscreen => {
                crate::video::NativeVideoPlacement::FullscreenBorderless
            }
            ViewerPresentation::DetachedWindow => {
                crate::video::NativeVideoPlacement::DetachedViewerChild
            }
        }
    }

    #[cfg(windows)]
    pub(crate) fn native_video_placement_to_viewer_presentation(
        placement: crate::video::NativeVideoPlacement,
    ) -> ViewerPresentation {
        match placement {
            crate::video::NativeVideoPlacement::MainWindowChild => ViewerPresentation::MainWindow,
            crate::video::NativeVideoPlacement::FullscreenBorderless => {
                ViewerPresentation::Fullscreen
            }
            crate::video::NativeVideoPlacement::DetachedViewerChild
            | crate::video::NativeVideoPlacement::DetachedWindow => {
                ViewerPresentation::DetachedWindow
            }
        }
    }

    #[cfg(windows)]
    pub(crate) fn clear_detached_viewer_host_hwnd(&mut self) {
        let Some(window_id) = self.active_detached_hwnd_window_id() else {
            return;
        };
        if let Some(hwnd) = self.detached_window_hwnd_clear(window_id) {
            crate::logger::log(format!(
                "[detached-viewer] clear host window_id={window_id} hwnd=0x{hwnd:x}",
            ));
        }
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_host_hwnd_alive(&self) -> Option<u64> {
        let window_id = self.active_detached_hwnd_window_id()?;
        self.detached_window_hwnd_alive(window_id)
    }

    /// detached viewer の OS 窓を「新規生成 / 再生成する可能性があるフレームか」を返す。
    ///
    /// host HWND が生存していない (未捕捉= 0、または stale = 死んだ HWND を !=0 で指したまま)
    /// なら、egui は次の `show_viewport_immediate` でその ViewportId の OS 窓を作り直す。その
    /// 再生成は最後に渡した builder を使うため、placement を seed しないと既定サイズ 822x656 の
    /// 小窓で生成されてから保存配置へリサイズされ、一瞬フラッシュする (2026-07-01 ハンドオフ)。
    /// 生存しているときは既存窓なので geometry を触らない (enumerate 待ち中のユーザー
    /// drag/resize を古い placement で引き戻さない = Codex P2)。active / inactive / keep-alive
    /// backstop の 3 経路すべてがこの判定を共有する。
    #[cfg(windows)]
    pub(crate) fn detached_viewer_should_seed_placement(&self) -> bool {
        self.detached_viewer_host_hwnd_alive().is_none()
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_host_lost(&self) -> bool {
        let Some(window_id) = self.active_detached_hwnd_window_id() else {
            return false;
        };
        let hwnd_raw = self.detached_window_hwnd_raw_for_window_id(window_id);
        if hwnd_raw == 0 {
            return false;
        }
        use windows::Win32::Foundation::HWND;
        use windows::Win32::UI::WindowsAndMessaging::IsWindow;

        let hwnd = HWND(hwnd_raw as *mut _);
        unsafe { !IsWindow(Some(hwnd)).as_bool() }
    }

    /// host_lost を検出したときの処理。**viewport を recreate しない**。
    ///
    /// recreate は `fs_viewport_generation` を bump して ViewportId を変え、egui に
    /// OS 窓を破棄・再生成させる。だが detached の host 捕捉は geometry 依存
    /// (`find_visible_thread_window_matching_rect` による rect 一致) なので、生成直後・
    /// resize 途中・DPI 差・多窓で誤判定 (`candidate=none`) しやすい。recreate を許すと
    /// folder-nav のたびに既定サイズの窓が一瞬生成されるフラッシュ + host_lost→recreate→
    /// 既定サイズ窓→host_lost… の自己駆動ループになっていた。
    /// 詳細: docs/detached-viewer-lifecycle-redesign-proposal.md BA-1/BA-2/BA-3。
    ///
    /// ここでは診断ログを残し、stale hwnd を捨てるだけにする。生きている window は
    /// 次フレームの capture が rect 一致で取り直す (取れなければ host=0 のままで
    /// host_lost() は false を返すので無害)。ユーザーが OS の×で閉じた等の真の
    /// close は `close_requested` 経路で処理する。
    #[cfg(windows)]
    pub(crate) fn handle_detached_viewer_host_lost_before_render(&mut self) {
        self.log_detached_viewer_host_lost_diagnostic("host_lost_before_render");
        // detached 動画再生中に host が消えた場合、presenter child は失われた host の子の
        // まま (= もうすぐ道連れ死)。次に新 host を capture したフレームで現 host へ
        // 再親付けするよう要求を立てておく。clear 後は host=0 で即時 sync できないので、
        // capture 時の `pending_detached_video_host_resync` 経路で拾わせる (P2a)。
        if self.detached_video_presentation_active_or_targeted() {
            self.pending_detached_video_host_resync = true;
        }
        self.clear_detached_viewer_host_hwnd();
    }

    #[cfg(windows)]
    pub(crate) fn win32_hwnd_debug_state(hwnd_raw: u64) -> String {
        if hwnd_raw == 0 {
            return "hwnd=0".to_string();
        }

        use windows::Win32::Foundation::{HWND, RECT};
        use windows::Win32::UI::WindowsAndMessaging::{
            GetWindowRect, IsIconic, IsWindow, IsWindowVisible,
        };

        let hwnd = HWND(hwnd_raw as *mut _);
        unsafe {
            let alive = IsWindow(Some(hwnd)).as_bool();
            let visible = alive && IsWindowVisible(hwnd).as_bool();
            let iconic = alive && IsIconic(hwnd).as_bool();
            let mut rect = RECT::default();
            let rect_ok = alive && GetWindowRect(hwnd, &mut rect).is_ok();
            if rect_ok {
                format!(
                    "hwnd=0x{hwnd_raw:x} alive={alive} visible={visible} iconic={iconic} \
                     rect=({},{} {}x{})",
                    rect.left,
                    rect.top,
                    rect.right - rect.left,
                    rect.bottom - rect.top
                )
            } else {
                format!(
                    "hwnd=0x{hwnd_raw:x} alive={alive} visible={visible} iconic={iconic} rect=<none>"
                )
            }
        }
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_host_debug_state(&self) -> String {
        let hwnd = self
            .active_detached_hwnd_window_id()
            .map(|window_id| self.detached_window_hwnd_raw_for_window_id(window_id))
            .unwrap_or(0);
        Self::win32_hwnd_debug_state(hwnd)
    }

    #[cfg(windows)]
    pub(crate) fn log_detached_viewer_host_lost_diagnostic(&mut self, reason: &'static str) {
        if !Self::detached_image_window_debug_enabled() {
            return;
        }

        let now = std::time::Instant::now();
        let since_render_ms = Self::format_optional_duration_ms(
            self.detached_viewer_last_render_at
                .map(|last| now.saturating_duration_since(last)),
        );
        let since_lost_ms = Self::format_optional_duration_ms(
            self.detached_viewer_last_host_lost_at
                .map(|last| now.saturating_duration_since(last)),
        );
        let previous_lost_frame = self.detached_viewer_last_host_lost_frame;
        self.detached_viewer_last_host_lost_frame = self.frame_counter;
        self.detached_viewer_last_host_lost_at = Some(now);

        let window_id = self.active_detached_hwnd_window_id();
        let captured_hwnd = window_id
            .map(|id| self.detached_window_hwnd_raw_for_window_id(id))
            .unwrap_or(0);
        let last_outer_text = self
            .detached_viewer_last_outer_rect
            .map(|rect| {
                format!(
                    "pos=({:.0},{:.0}) size={:.0}x{:.0}",
                    rect.min.x,
                    rect.min.y,
                    rect.width(),
                    rect.height()
                )
            })
            .unwrap_or_else(|| "none".to_string());
        let main_hwnd_text = self
            .main_hwnd
            .map(|hwnd| format!("0x{:x}", hwnd as usize))
            .unwrap_or_else(|| "none".to_string());

        crate::logger::log(format!(
            "[detached-viewer] host_lost_diag reason={reason} frame={} \
             last_render_frame={} frames_since_render={} since_render_ms={} \
             prev_lost_frame={} frames_since_prev_lost={} since_prev_lost_ms={} \
             fullscreen_idx={:?} viewer_presentation={:?} fs_presentation={:?} \
             generation={} detached_window_id={:?} registry_window_id={:?} \
             captured_hwnd=0x{:x} captured_state=\"{}\" main_hwnd={} \
             last_outer=\"{}\" last_ppp={:.2}",
            self.frame_counter,
            self.detached_viewer_last_render_frame,
            self.frame_counter
                .saturating_sub(self.detached_viewer_last_render_frame),
            since_render_ms,
            previous_lost_frame,
            self.frame_counter.saturating_sub(previous_lost_frame),
            since_lost_ms,
            self.fullscreen_idx,
            self.viewer_presentation,
            self.fs_viewport_presentation,
            self.fs_viewport_generation,
            self.detached_viewer_window_id,
            window_id,
            captured_hwnd,
            self.detached_viewer_host_debug_state(),
            main_hwnd_text,
            last_outer_text,
            self.detached_viewer_last_pixels_per_point,
        ));
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_client_rect_physical(
        &self,
    ) -> Option<windows::Win32::Foundation::RECT> {
        use windows::Win32::Foundation::{HWND, RECT};
        use windows::Win32::UI::WindowsAndMessaging::GetClientRect;

        let hwnd = self.detached_viewer_host_hwnd_alive()?;
        let mut rect = RECT::default();
        if unsafe { GetClientRect(HWND(hwnd as *mut _), &mut rect) }.is_err() {
            return None;
        }
        let w = rect.right - rect.left;
        let h = rect.bottom - rect.top;
        (w > 0 && h > 0).then_some(rect)
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_video_host_ready(&self) -> bool {
        self.detached_viewer_client_rect_physical().is_some()
    }

    #[cfg(windows)]
    pub(crate) fn sync_fullscreen_viewport_virtual_desktop_from_logical_rect(
        &mut self,
        outer_rect: egui::Rect,
        pixels_per_point: f32,
    ) {
        use windows::Win32::Foundation::{HWND, RECT};

        let Some(main_hwnd) = self.main_hwnd else {
            return;
        };
        let scale = pixels_per_point.max(0.5);
        let expected = RECT {
            left: (outer_rect.min.x * scale).round() as i32,
            top: (outer_rect.min.y * scale).round() as i32,
            right: (outer_rect.max.x * scale).round() as i32,
            bottom: (outer_rect.max.y * scale).round() as i32,
        };
        let Some(hwnd) = crate::dwm_transitions::find_visible_thread_window_matching_rect(
            HWND(main_hwnd as *mut _),
            expected,
        ) else {
            return;
        };
        let hwnd_raw = hwnd.0 as usize as u64;
        if hwnd_raw == 0 || hwnd_raw == self.fs_viewport_virtual_desktop_synced_hwnd {
            return;
        }
        let owner = HWND(main_hwnd as *mut _);
        if let Err(err) = crate::dwm_transitions::move_window_to_desktop_of(owner, hwnd) {
            crate::logger::log(format!(
                "[fullscreen] virtual desktop sync failed hwnd=0x{hwnd_raw:x}: {err:?}"
            ));
        } else {
            crate::logger::log(format!(
                "[fullscreen] virtual desktop synced hwnd=0x{hwnd_raw:x}"
            ));
        }
        self.fs_viewport_virtual_desktop_synced_hwnd = hwnd_raw;
    }

    #[cfg(windows)]
    pub(crate) fn native_video_target_for_presentation(
        &self,
        presentation: ViewerPresentation,
    ) -> Option<(
        crate::video::NativeVideoPlacement,
        windows::Win32::Foundation::RECT,
        u64,
    )> {
        let placement = Self::viewer_presentation_to_native_video_placement(presentation);
        match presentation {
            ViewerPresentation::DetachedWindow => {
                let owner_hwnd = self.detached_viewer_host_hwnd_alive()?;
                let rect = self.detached_viewer_client_rect_physical()?;
                Some((placement, rect, owner_hwnd))
            }
            ViewerPresentation::MainWindow | ViewerPresentation::Fullscreen => {
                let owner_hwnd = self.main_hwnd? as u64;
                let rect = self.native_video_rect_for_presentation(presentation)?;
                Some((placement, rect, owner_hwnd))
            }
        }
    }

    #[cfg(windows)]
    fn default_detached_viewer_window_placement(
        &self,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        let (x, y) = self
            .last_outer_rect
            .map(|rect| (rect.min.x + 48.0, rect.min.y + 48.0))
            .unwrap_or((80.0, 80.0));
        crate::settings::DetachedViewerWindowPlacement {
            x,
            y,
            w: 960.0,
            h: 720.0,
            maximized: false,
        }
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_window_placement(
        &self,
    ) -> crate::settings::DetachedViewerWindowPlacement {
        self.settings
            .detached_viewer_window_placement
            .filter(|p| p.is_sane() && crate::monitor::title_bar_on_some_monitor(p.x, p.y, p.w))
            .unwrap_or_else(|| self.default_detached_viewer_window_placement())
    }

    #[cfg(windows)]
    fn detached_viewer_monitor_rect_logical(&self) -> Option<egui::Rect> {
        use windows::Win32::Foundation::{HWND, RECT};
        use windows::Win32::UI::WindowsAndMessaging::GetWindowRect;

        if let Some(hwnd_raw) = self.detached_viewer_host_hwnd_alive() {
            let mut rect = RECT::default();
            if unsafe { GetWindowRect(HWND(hwnd_raw as *mut _), &mut rect) }.is_ok() {
                let x = (rect.left + rect.right) as f32 * 0.5;
                let y = (rect.top + rect.bottom) as f32 * 0.5;
                if let Some(monitor_rect) = crate::monitor::get_monitor_logical_rect_at(x, y) {
                    return Some(monitor_rect);
                }
            }
        }

        let placement = self.active_detached_viewer_current_placement();
        let scale = crate::settings::native_pixels_per_point_from_effective(
            self.last_pixels_per_point,
            self.settings.ui_scale_factor,
        )
        .max(0.5);
        let x = (placement.x + placement.w * 0.5) * scale;
        let y = (placement.y + placement.h * 0.5) * scale;
        crate::monitor::get_monitor_logical_rect_at(x, y)
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_borderless_target_rect(&self) -> egui::Rect {
        self.detached_viewer_monitor_rect_logical()
            .unwrap_or_else(|| {
                let placement = self.active_detached_viewer_current_placement();
                egui::Rect::from_min_size(
                    egui::pos2(placement.x, placement.y),
                    egui::vec2(placement.w, placement.h),
                )
            })
    }

    #[cfg(windows)]
    pub(crate) fn clear_detached_viewer_borderless_fullscreen_state(&mut self) {
        self.detached_viewer_borderless_fullscreen = false;
        self.detached_viewer_restore_placement = None;
        self.detached_viewer_borderless_transition = None;
    }

    #[cfg(windows)]
    pub(crate) fn toggle_detached_viewer_borderless_fullscreen(&mut self, ctx: &egui::Context) {
        if !self.viewer_session_is_detached() {
            return;
        }
        if self.detached_viewer_borderless_transition.is_some() {
            return;
        }
        let target_borderless = !self.detached_viewer_borderless_fullscreen;
        if target_borderless {
            self.detached_viewer_restore_placement =
                Some(self.active_detached_viewer_current_placement());
        }
        self.detached_viewer_borderless_transition = Some(DetachedViewerBorderlessTransition {
            target_borderless,
            phase: DetachedViewerBorderlessTransitionPhase::PrimeBlackFrame,
        });
        self.show_feedback_toast(if target_borderless {
            "別ウィンドウを仮想フルスクリーンにしました".to_string()
        } else {
            "別ウィンドウを通常表示に戻しました".to_string()
        });
        ctx.request_repaint();
    }

    /// メインウィンドウ (ROOT viewport) の最大化 ⇔ 復元をトグルする。
    /// グリッド表示時の F11 / リング・マウスショートカット `ToggleMaximize` から呼ぶ。
    pub(crate) fn toggle_main_window_maximized(&self, ctx: &egui::Context) {
        let is_max = ctx.input(|i| i.viewport().maximized.unwrap_or(false));
        ctx.send_viewport_cmd_to(
            egui::ViewportId::ROOT,
            egui::ViewportCommand::Maximized(!is_max),
        );
        ctx.request_repaint();
    }

    #[cfg(windows)]
    fn apply_detached_viewer_borderless_target(
        &mut self,
        ctx: &egui::Context,
        target_borderless: bool,
    ) {
        let viewport_id = self.fullscreen_viewport_id();
        if !target_borderless {
            let placement = self
                .detached_viewer_restore_placement
                .take()
                .unwrap_or_else(|| self.active_detached_viewer_current_placement());
            self.detached_viewer_borderless_fullscreen = false;
            if let Some(window_id) = self.active_detached_hwnd_window_id() {
                self.set_detached_window_runtime_placement(
                    window_id,
                    placement,
                    "borderless_restore",
                );
            }
            self.log_detached_viewport_placement_event(
                "borderless_restore",
                "viewport_cmd",
                format!(
                    "viewport={viewport_id:?} command=OuterPosition/InnerSize placement={placement:?}"
                ),
            );
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Maximized(false));
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Decorations(true));
            let viewport_position = egui::pos2(
                crate::settings::window_geometry_to_viewport_points(
                    placement.x,
                    self.settings.ui_scale_factor,
                ),
                crate::settings::window_geometry_to_viewport_points(
                    placement.y,
                    self.settings.ui_scale_factor,
                ),
            );
            let viewport_inner_size = egui::vec2(
                crate::settings::window_geometry_to_viewport_points(
                    placement.w,
                    self.settings.ui_scale_factor,
                ),
                crate::settings::window_geometry_to_viewport_points(
                    placement.h,
                    self.settings.ui_scale_factor,
                ),
            );
            ctx.send_viewport_cmd_to(
                viewport_id,
                egui::ViewportCommand::OuterPosition(viewport_position),
            );
            ctx.send_viewport_cmd_to(
                viewport_id,
                egui::ViewportCommand::InnerSize(viewport_inner_size),
            );
            if placement.maximized {
                ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Maximized(true));
            }
        } else {
            let rect = self.detached_viewer_borderless_target_rect();
            let viewport_position = egui::pos2(
                crate::settings::window_geometry_to_viewport_points(
                    rect.min.x,
                    self.settings.ui_scale_factor,
                ),
                crate::settings::window_geometry_to_viewport_points(
                    rect.min.y,
                    self.settings.ui_scale_factor,
                ),
            );
            let viewport_inner_size = egui::vec2(
                crate::settings::window_geometry_to_viewport_points(
                    rect.width(),
                    self.settings.ui_scale_factor,
                ),
                crate::settings::window_geometry_to_viewport_points(
                    rect.height(),
                    self.settings.ui_scale_factor,
                ),
            );
            self.detached_viewer_borderless_fullscreen = true;
            self.log_detached_viewport_placement_event(
                "borderless_enter",
                "viewport_cmd",
                format!(
                    "viewport={viewport_id:?} command=OuterPosition/InnerSize \
                     rect=({:.3},{:.3} {:.3}x{:.3})",
                    rect.min.x,
                    rect.min.y,
                    rect.width(),
                    rect.height()
                ),
            );
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Maximized(false));
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Decorations(false));
            ctx.send_viewport_cmd_to(
                viewport_id,
                egui::ViewportCommand::OuterPosition(viewport_position),
            );
            ctx.send_viewport_cmd_to(
                viewport_id,
                egui::ViewportCommand::InnerSize(viewport_inner_size),
            );
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Focus);
        }
        ctx.request_repaint();
    }

    #[cfg(windows)]
    pub(crate) fn step_detached_viewer_borderless_transition(
        &mut self,
        ctx: &egui::Context,
    ) -> bool {
        let Some(mut transition) = self.detached_viewer_borderless_transition.take() else {
            return false;
        };
        match transition.phase {
            DetachedViewerBorderlessTransitionPhase::PrimeBlackFrame => {
                transition.phase = DetachedViewerBorderlessTransitionPhase::ApplyWindowMode;
                self.detached_viewer_borderless_transition = Some(transition);
                ctx.request_repaint_after(std::time::Duration::from_millis(16));
                true
            }
            DetachedViewerBorderlessTransitionPhase::ApplyWindowMode => {
                self.apply_detached_viewer_borderless_target(ctx, transition.target_borderless);
                transition.phase = DetachedViewerBorderlessTransitionPhase::Settle {
                    until: std::time::Instant::now() + std::time::Duration::from_millis(96),
                };
                self.detached_viewer_borderless_transition = Some(transition);
                ctx.request_repaint_after(std::time::Duration::from_millis(16));
                true
            }
            DetachedViewerBorderlessTransitionPhase::Settle { until } => {
                if std::time::Instant::now() < until {
                    self.detached_viewer_borderless_transition = Some(transition);
                    ctx.request_repaint_after(std::time::Duration::from_millis(16));
                    true
                } else {
                    let _ = self.sync_detached_video_child_presenter_rect();
                    ctx.request_repaint();
                    false
                }
            }
        }
    }

    #[cfg(windows)]
    pub(crate) fn detached_viewer_rect_physical(&self) -> windows::Win32::Foundation::RECT {
        let placement = self.active_detached_viewer_current_placement();
        let scale = crate::settings::native_pixels_per_point_from_effective(
            self.last_pixels_per_point,
            self.settings.ui_scale_factor,
        )
        .max(0.5);
        windows::Win32::Foundation::RECT {
            left: (placement.x * scale).round() as i32,
            top: (placement.y * scale).round() as i32,
            right: ((placement.x + placement.w) * scale).round() as i32,
            bottom: ((placement.y + placement.h) * scale).round() as i32,
        }
    }

    #[cfg(windows)]
    pub(crate) fn native_video_rect_for_presentation(
        &self,
        presentation: ViewerPresentation,
    ) -> Option<windows::Win32::Foundation::RECT> {
        use windows::Win32::Foundation::{HWND, RECT};
        use windows::Win32::Graphics::Gdi::{
            GetMonitorInfoW, MONITOR_DEFAULTTONEAREST, MONITORINFO, MonitorFromWindow,
        };
        use windows::Win32::UI::WindowsAndMessaging::GetClientRect;

        match presentation {
            ViewerPresentation::DetachedWindow => Some(self.detached_viewer_rect_physical()),
            ViewerPresentation::MainWindow => {
                let hwnd = HWND(self.main_hwnd.unwrap_or_default() as *mut _);
                let mut client = RECT::default();
                if unsafe { GetClientRect(hwnd, &mut client) }.is_err() {
                    return None;
                }
                Some(client)
            }
            ViewerPresentation::Fullscreen => {
                let hwnd = HWND(self.main_hwnd.unwrap_or_default() as *mut _);
                let monitor = unsafe { MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST) };
                let mut info = MONITORINFO {
                    cbSize: std::mem::size_of::<MONITORINFO>() as u32,
                    ..Default::default()
                };
                if !unsafe { GetMonitorInfoW(monitor, &mut info) }.as_bool() {
                    return None;
                }
                Some(info.rcMonitor)
            }
        }
    }

    #[cfg(windows)]
    pub(crate) fn take_detached_viewer_activate_on_show(&mut self) -> bool {
        if self.detached_viewer_no_activate_once {
            self.detached_viewer_no_activate_once = false;
            false
        } else {
            true
        }
    }

    #[cfg(all(windows, test))]
    pub(crate) fn save_detached_viewer_placement_from_logical_rect(
        &mut self,
        outer_rect: egui::Rect,
        inner_rect: Option<egui::Rect>,
        pixels_per_point: f32,
        maximized: bool,
    ) -> Option<crate::settings::DetachedViewerWindowPlacement> {
        self.save_detached_viewer_placement_from_logical_rect_with_source(
            "unspecified",
            outer_rect,
            inner_rect,
            pixels_per_point,
            maximized,
        )
    }

    #[cfg(windows)]
    pub(crate) fn save_detached_viewer_placement_from_logical_rect_with_source(
        &mut self,
        source: &'static str,
        outer_rect: egui::Rect,
        inner_rect: Option<egui::Rect>,
        pixels_per_point: f32,
        maximized: bool,
    ) -> Option<crate::settings::DetachedViewerWindowPlacement> {
        if self.detached_viewer_borderless_fullscreen
            || self.detached_viewer_borderless_transition.is_some()
        {
            return None;
        }
        let ui_scale = self.settings.ui_scale_factor;
        let to_window_geometry_rect = |rect: egui::Rect| {
            egui::Rect::from_min_max(
                egui::pos2(
                    crate::settings::viewport_points_to_window_geometry(rect.min.x, ui_scale),
                    crate::settings::viewport_points_to_window_geometry(rect.min.y, ui_scale),
                ),
                egui::pos2(
                    crate::settings::viewport_points_to_window_geometry(rect.max.x, ui_scale),
                    crate::settings::viewport_points_to_window_geometry(rect.max.y, ui_scale),
                ),
            )
        };
        let outer_rect = to_window_geometry_rect(outer_rect);
        let inner_rect = inner_rect.map(to_window_geometry_rect);
        let geometry_ppp =
            crate::settings::native_pixels_per_point_from_effective(pixels_per_point, ui_scale);
        let Some(window_id) = self.active_detached_hwnd_window_id() else {
            self.log_detached_viewport_placement_event(
                source,
                "active_placement_update_skipped",
                "reason=no_window_id".to_string(),
            );
            return None;
        };
        if maximized {
            let mut placement = self.detached_window_seed_placement(window_id);
            placement.maximized = true;
            self.log_detached_viewport_placement_event(
                source,
                "active_placement_update_maximized",
                format!(
                    "window_id={window_id} outer=({:.3},{:.3} {:.3}x{:.3}) ppp={pixels_per_point:.3} \
                     seed_now={}",
                    outer_rect.min.x,
                    outer_rect.min.y,
                    outer_rect.width(),
                    outer_rect.height(),
                    self.detached_viewer_should_seed_placement()
                ),
            );
            self.set_detached_window_runtime_placement(
                window_id,
                placement,
                "active_placement_update_maximized",
            );
            return None;
        }
        let size_rect = inner_rect.unwrap_or(outer_rect);
        if !outer_rect.min.x.is_finite()
            || !outer_rect.min.y.is_finite()
            || !size_rect.width().is_finite()
            || !size_rect.height().is_finite()
            || size_rect.width() < 320.0
            || size_rect.height() < 240.0
        {
            return None;
        }
        if !maximized
            && !crate::monitor::title_bar_on_some_monitor(
                outer_rect.min.x,
                outer_rect.min.y,
                outer_rect.width(),
            )
        {
            return None;
        }
        let placement = crate::settings::DetachedViewerWindowPlacement {
            x: outer_rect.min.x,
            y: outer_rect.min.y,
            w: size_rect.width(),
            h: size_rect.height(),
            maximized: false,
        };
        // switching も含める: F12 で動画を detach する遷移中は presentation がまだ
        // DetachedWindow に変わっておらず `viewer_session_is_detached()` が false になる窓がある。
        // その間に egui が既定サイズ窓を報告すると、狭い判定では default-rejection が発火せず
        // 既定 placement を保存 + 既定サイズ窓を capture してしまう (Codex P1)。render 側は
        // `viewer_session_is_detached_or_switching()` を detached 判定に使っているので揃える。
        if self.viewer_session_is_detached_or_switching() {
            let previous = self
                .detached_window_runtime_placement(window_id)
                .or(self.settings.detached_viewer_window_placement)
                .filter(|p| {
                    p.is_sane() && crate::monitor::title_bar_on_some_monitor(p.x, p.y, p.w)
                });
            if let Some(previous) = previous
                && Self::detached_active_placement_update_looks_like_default_viewport(
                    previous,
                    placement,
                    geometry_ppp,
                )
            {
                self.log_detached_viewport_placement_event(
                    source,
                    "active_placement_update_rejected_default",
                    format!(
                        "window_id={window_id} previous={previous:?} candidate={placement:?} \
                         ppp={pixels_per_point:.3} seed_now={}",
                        self.detached_viewer_should_seed_placement()
                    ),
                );
                self.set_detached_window_runtime_placement(
                    window_id,
                    previous,
                    "active_placement_update_rejected_default",
                );
                return Some(previous);
            }
        }
        self.log_detached_viewport_placement_event(
            source,
            "active_placement_update",
            format!(
                "window_id={window_id} outer=({:.3},{:.3} {:.3}x{:.3}) inner={} \
                 placement={placement:?} ppp={pixels_per_point:.3} maximized={maximized} \
                 seed_now={}",
                outer_rect.min.x,
                outer_rect.min.y,
                outer_rect.width(),
                outer_rect.height(),
                inner_rect
                    .map(|rect| format!(
                        "({:.3},{:.3} {:.3}x{:.3})",
                        rect.min.x,
                        rect.min.y,
                        rect.width(),
                        rect.height()
                    ))
                    .unwrap_or_else(|| "none".to_string()),
                self.detached_viewer_should_seed_placement()
            ),
        );
        self.set_detached_window_runtime_placement(window_id, placement, "active_placement_update");
        None
    }

    #[cfg(windows)]
    pub(crate) fn sync_detached_viewer_to_selected(&mut self, ctx: &egui::Context) {
        if !self.settings.detached_viewer_enabled || !self.viewer_session_is_detached() {
            return;
        }
        if self.detached_viewer_independent_still_session() {
            return;
        }
        if self.settings.detached_viewer_open_images_in_window {
            return;
        }
        let Some(selected) = self.selected else {
            return;
        };
        // §1.7 フル機能+メディア別窓: メディアセッションはメイン一覧カーソルに追従せず、
        // 連動 still 窓も media 選択には追従しない。media は Enter / ダブルクリックの
        // grid-open seam からメディア窓へ渡す。複数ウィンドウ mode は直前で return 済み。
        if self.settings.effective_media_in_media_window()
            && (self
                .fullscreen_idx
                .is_some_and(|idx| self.viewer_item_is_media(idx))
                || self.viewer_item_is_media(selected))
        {
            return;
        }
        let Some(stamp) = self.viewer_sync_stamp_for_idx(selected) else {
            return;
        };
        if self.last_viewer_sync_stamp.as_ref() == Some(&stamp) {
            return;
        }

        let item_key_changed = self
            .last_viewer_sync_stamp
            .as_ref()
            .is_some_and(|old| old.idx == selected && old.item_key != stamp.item_key);
        self.detached_viewer_no_activate_once = true;
        if self.fullscreen_idx == Some(selected) {
            if item_key_changed {
                self.fs_cache.remove(&selected);
                self.fs_margin_bbox_cache.remove(&selected);
                if let Some((cancel, _, _)) = self.fs_pending.remove(&selected) {
                    cancel.store(true, std::sync::atomic::Ordering::Relaxed);
                }
                self.fs_upload_backlog
                    .retain(|(idx, _, _)| *idx != selected);
            }
            let cursor_state = self.fullscreen_cursor_state();
            self.open_fullscreen(selected, crate::app::HistoryTrigger::UserChosen);
            self.restore_fullscreen_cursor_state(ctx, cursor_state);
        } else {
            self.open_fullscreen_from_fs_navigation(
                ctx,
                selected,
                crate::app::HistoryTrigger::UserChosen,
            );
        }
        self.selected = Some(selected);
        self.scroll_to_selected = true;
        self.update_last_selected_image();
        self.last_viewer_sync_stamp = Some(stamp);
        ctx.request_repaint();
    }

    #[cfg(windows)]
    fn raise_active_detached_media_for_grid_open(
        &mut self,
        ctx: &egui::Context,
        target_path: &std::path::Path,
    ) -> bool {
        let Some(active) = self.active_detached_viewer_context.as_ref() else {
            return false;
        };
        if !viewer_context_bundle_displays_media_path(&active.bundle, target_path) {
            return false;
        }
        let Some(idx) = active.bundle.fullscreen_idx else {
            return false;
        };
        let window_id = active.bundle.viewer_session.detached_window_id.or_else(|| {
            self.active_detached_session
                .map(|session| session.window_id)
        });
        let presenter_player = match active.bundle.fs_cache.get(&idx) {
            Some(FsCacheEntry::Video { player, .. }) => Some(player.as_ref()),
            _ => None,
        };
        let presenter_target = matches!(active.bundle.items.get(idx), Some(GridItem::Video(_)))
            && !Self::viewer_context_bundle_is_music_consumer(&active.bundle)
            && presenter_player.is_some();
        if let Some(player) = presenter_player.filter(|_| presenter_target) {
            player.request_presenter_raise();
        }
        if presenter_target {
            self.native_video_front_recover_after_external_foreground = true;
            self.native_video_front_last_raise = None;
        } else if let Some(window_id) = window_id {
            let viewport_id = Self::detached_image_window_viewport_id(window_id);
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Minimized(false));
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Visible(true));
            ctx.send_viewport_cmd_to(viewport_id, egui::ViewportCommand::Focus);
        }
        ctx.request_repaint();
        true
    }

    #[cfg(windows)]
    pub(crate) fn activate_existing_detached_viewer_for_grid_open(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
    ) -> bool {
        let mounted_matches = self.viewer_session_is_detached()
            && self.fullscreen_idx == Some(idx)
            && self
                .viewer_sync_stamp_for_idx(idx)
                .is_some_and(|stamp| self.last_viewer_sync_stamp.as_ref() == Some(&stamp));

        // 音声と動画→音声モード (VST host 非表示) は still と同じ egui viewport が描く。
        // hidden presenter を raise せず、見えている音楽 viewport を前面化する。
        // VST host 中は current_music_fullscreen_idx() が None なので従来どおり presenter。
        // (review-v2.3.0 追補2 P2: visible media surface)
        if mounted_matches
            && (self.viewer_item_supports_detached_still(idx)
                || self.current_music_fullscreen_idx() == Some(idx))
        {
            let fs_id = self.fullscreen_viewport_id();
            ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Minimized(false));
            ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Visible(true));
            ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Focus);
        } else if mounted_matches && matches!(self.items.get(idx), Some(GridItem::Video(_))) {
            self.native_video_front_recover_after_external_foreground = true;
            self.native_video_front_last_raise = None;
            if let Some(FsCacheEntry::Video { player, .. }) = self.fs_cache.get(&idx) {
                player.request_presenter_raise();
            }
        }
        if mounted_matches {
            ctx.request_repaint();
            return true;
        }

        let Some(target_path) = self
            .items
            .get(idx)
            .and_then(grid_item_media_path)
            .map(std::path::Path::to_path_buf)
        else {
            return false;
        };
        // context ごとに idx 空間が違うため、promote / ParkedLive 済み media は path で探す。
        // parked は窓クリックと同じ activation 経路を通してから raise する。
        // (review-v2.3.0 追補 BA-7: same-media raise)
        if self.raise_active_detached_media_for_grid_open(ctx, &target_path) {
            return true;
        }
        let parked_id = self.detached_image_windows.iter().find_map(|window| {
            (self.detached_window_state_is_parked_live(window.id)
                && window.paused_bundle.as_deref().is_some_and(|bundle| {
                    viewer_context_bundle_displays_media_path(bundle, &target_path)
                }))
            .then_some(window.id)
        });
        if let Some(window_id) = parked_id
            && self.activate_parked_live_media_window_snapshot(ctx, window_id)
        {
            let _ = self.raise_active_detached_media_for_grid_open(ctx, &target_path);
            return true;
        }
        false
    }

    /// grid の leaf open 共通前処理。同じ active/ParkedLive メディアなら前面化して open を
    /// 消費し、それ以外だけ既存 context の park/close へ進める。Enter / ダブルクリック /
    /// ゲームパッド / stack フラット open の順序を同じ seam で固定する。
    /// (review-v2.3.0 追補4: same-media grid open)
    #[cfg(windows)]
    pub(crate) fn prepare_detached_context_for_grid_open(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
    ) -> bool {
        if self.activate_existing_detached_viewer_for_grid_open(ctx, idx) {
            return false;
        }
        self.park_active_detached_context_for_new_grid_open(ctx, idx)
    }

    /// grid から別の画像/動画を明示 open するとき、独立 active context は passive /
    /// ParkedLive へ退避する。通常の linked detached セッションは CUT 後の仕様では passive
    /// にならないため対象外 (= 従来どおり reuse / 追従)。ただし media-window へ handoff
    /// するときだけ、window_id 衝突を避けるため mounted still を先に passive へ退避する。
    #[cfg(windows)]
    pub(crate) fn park_active_detached_context_for_new_grid_open(
        &mut self,
        ctx: &egui::Context,
        opening_idx: usize,
    ) -> bool {
        self.log_detached_image_window_debug(format!(
            "park_active_context_for_grid_open begin active_context={} session={:?} \
             fs_idx={:?} presentation={:?} window_id={:?} independent={} \
             passive_windows={}",
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session,
            self.fullscreen_idx,
            self.viewer_presentation,
            self.detached_viewer_window_id,
            self.detached_viewer_independent_active,
            self.detached_image_windows.len()
        ));
        if self.active_detached_viewer_context.is_some() {
            let ok = self.park_and_close_current_active_detached_viewer(ctx);
            self.log_detached_image_window_debug(format!(
                "park_active_context_for_grid_open result={ok} passive_windows={} \
                 active_context={} session={:?}",
                self.detached_image_windows.len(),
                self.active_detached_viewer_context.is_some(),
                self.active_detached_session
            ));
            return ok;
        }
        // review-v2.3.0 追補5: §1.7 linked still × media open。
        // mounted detached still は media open 前に passive へ handoff し、window_id を分ける。
        if self.settings.effective_media_in_media_window()
            && self.viewer_item_is_media(opening_idx)
            && self.viewer_session_is_detached()
            && self
                .fullscreen_idx
                .is_some_and(|idx| self.viewer_item_supports_detached_still(idx))
        {
            return self.park_and_close_current_active_detached_viewer_for_media_handoff(ctx);
        }
        // §1.7 メディア別窓: bundle 化前の連動 detached メディアセッション (grid から
        // 動画/音声を開いた直後で main 文脈のまま) も、次の grid open が presentation を
        // 取り戻す前に live-park する。これを落とすと `prepare_viewer_presentation_open`
        // の open_non_detached 経路がメディアセッションごと閉じて再生が止まる。
        // 注: `current_viewer_context_contains_video` は名前に反して**音声も含む**
        // (音声再生も `FsCacheEntry::Video` を使うため)。音声だけ判定から漏らさないこと。
        if self.settings.effective_media_in_media_window()
            && self.viewer_session_is_detached()
            && self.current_viewer_context_contains_video()
        {
            let ok = self.park_and_close_current_active_detached_viewer(ctx);
            self.log_detached_image_window_debug(format!(
                "park_active_context_for_grid_open result={ok} reason=unbundled_media \
                 passive_windows={} session={:?}",
                self.detached_image_windows.len(),
                self.active_detached_session
            ));
            return ok;
        }
        true
    }

    fn restore_fullscreen_focus_from_main(&mut self, ctx: &egui::Context) {
        let Some(idx) = self.fullscreen_idx else {
            return;
        };
        if self.viewer_session_is_detached() {
            return;
        }

        const RESTORE_DEBOUNCE: std::time::Duration = std::time::Duration::from_millis(250);
        let now = std::time::Instant::now();
        if let Some(last) = self.fs_last_main_focus_restore_at {
            let elapsed = now.saturating_duration_since(last);
            if elapsed < RESTORE_DEBOUNCE {
                ctx.request_repaint_after(RESTORE_DEBOUNCE - elapsed);
                return;
            }
        }
        self.fs_last_main_focus_restore_at = Some(now);

        let mut restored = false;
        let mut target = "fullscreen_viewport";
        if self.fs_viewport_shown {
            let fs_id = self.fullscreen_viewport_id();
            ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Minimized(false));
            ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Visible(true));
            ctx.send_viewport_cmd_to(fs_id, egui::ViewportCommand::Focus);
            restored = true;
        }

        #[cfg(windows)]
        if let Some(FsCacheEntry::Video { player, .. }) = self.fs_cache.get(&idx) {
            self.native_video_front_recover_after_external_foreground = true;
            self.native_video_front_last_raise = None;
            player.request_presenter_raise();
            target = "native_video";
            restored = true;
        }

        if restored {
            self.fs_focus_regained_at = Some(now);
            crate::logger::log(format!(
                "[fs-focus] restore fullscreen from main focus target={target} idx={idx}"
            ));
        }
        ctx.request_repaint();
    }

    /// open 時に採用する presentation を決める。
    ///
    /// `fs_media_open_forced_presentation` one-shot が立っていれば直前のメディアの presentation を
    /// そのまま維持し、「別ウィンドウで開く」設定の再適用 (= detached 化) を抑止する。この
    /// one-shot の主な発生源は `open_fullscreen` 冒頭の一括ガード: **grid からの新規 open では
    /// なく (fs_open_intent_from_grid=false)、既にフルスクリーン中で、動画を開く** viewer 内ナビ
    /// (矢印 / wheel / Home / End / Ctrl+G / 検索ジャンプ / fast-swap deferred 完了) のときだけ、
    /// `viewer_presentation` が書き換わる前に現在値を焼き付ける (連続再生の自動次送りは加えて
    /// 明示設定もする)。これにより、F12 で main に出した動画を手動ナビで送っても別窓へ飛ばさない
    /// (実機 FB 2026-07-02)。one-shot が無い open (= grid からの新規 open: Enter / ダブルクリック)
    /// だけが従来どおり設定ベース (`effective_...`) に従う。one-shot は消費する。
    #[cfg(windows)]
    fn resolve_viewer_presentation_for_open(
        &mut self,
        idx: usize,
        entering_media: bool,
    ) -> ViewerPresentation {
        match self.fs_media_open_forced_presentation.take() {
            Some(p) if entering_media => p,
            _ => self.effective_viewer_presentation_for_open(idx),
        }
    }

    #[cfg(windows)]
    fn take_parked_fullfeature_linked_still_for_grid_open(
        &mut self,
        idx: usize,
        presentation: ViewerPresentation,
    ) -> Option<u64> {
        if !self.fs_open_intent_from_grid
            || !matches!(presentation, ViewerPresentation::DetachedWindow)
            || !self.viewer_item_supports_detached_still(idx)
            || !self.fullfeature_linked_still_media_window_mode()
            || self.active_detached_session.is_some()
            || self.detached_viewer_window_id.is_some()
        {
            return None;
        }

        let candidates = self
            .detached_image_windows
            .iter()
            .enumerate()
            .filter_map(|(pos, window)| {
                let runtime = self.detached_window_manager.runtime(window.id)?;
                (window.paused_bundle.is_none()
                    && runtime.linked
                    && runtime.state == DetachedWindowState::Parked)
                    .then_some((pos, window.id))
            })
            .collect::<Vec<_>>();
        let [(pos, window_id)] = candidates.as_slice() else {
            if candidates.len() > 1 {
                self.log_detached_image_window_debug(format!(
                    "fullfeature_linked_still_reuse_skipped reason=ambiguous candidates={candidates:?}"
                ));
            }
            return None;
        };
        let pos = *pos;
        let window_id = *window_id;
        let snapshot = self.detached_image_windows.remove(pos);
        self.deferred_detached_image_window_views.remove(&window_id);
        self.detached_viewer_window_id = Some(window_id);
        self.last_active_detached_window_id = Some(window_id);
        self.detached_viewer_independent_active = false;
        self.detached_viewer_open_next_still_detached_once = false;
        self.transition_detached_window_state(
            window_id,
            DetachedWindowState::Resuming,
            "fullfeature_linked_still_grid_reuse",
        );
        self.adopt_active_detached_viewport_runtime_from_passive(
            "fullfeature_linked_still_grid_reuse",
        );
        self.log_detached_image_window_debug(format!(
            "fullfeature_linked_still_reuse id={window_id} idx={idx} title={:?} passive_remaining={}",
            snapshot.title,
            self.detached_image_windows.len()
        ));
        Some(window_id)
    }

    #[cfg(windows)]
    fn prepare_viewer_presentation_open(&mut self, idx: usize, entering_native_video: bool) {
        let entering_media =
            entering_native_video || matches!(self.items.get(idx), Some(GridItem::Audio(_)));
        if entering_media {
            self.close_parked_live_media_windows_for_new_media("new_media_open");
        }
        let presentation = self.resolve_viewer_presentation_for_open(idx, entering_media);
        let detached_still = matches!(presentation, ViewerPresentation::DetachedWindow)
            && self.viewer_item_supports_detached_still(idx);
        let independent_detached_still =
            detached_still && self.detached_still_open_is_independent(idx);
        let focus_detached_from_grid = matches!(presentation, ViewerPresentation::DetachedWindow)
            && self.fs_open_intent_from_grid;
        self.log_detached_image_window_debug(format!(
            "prepare_viewer_presentation_open_begin idx={idx} entering_video={entering_native_video} \
             item_kind={} resolved={presentation:?} detached_still={detached_still} \
             independent_still={independent_detached_still} fs_idx_before={:?} \
             current_presentation={:?} enabled={} always_new={} open_next_once={} \
             grid_intent={} active_context={} session={:?} window_id={:?} \
             independent={} passive_windows={}",
            self.grid_item_debug_kind(idx),
            self.fullscreen_idx,
            self.viewer_presentation,
            self.settings.detached_viewer_enabled,
            self.settings.detached_viewer_open_images_in_window,
            self.detached_viewer_open_next_still_detached_once,
            self.fs_open_intent_from_grid,
            self.active_detached_viewer_context.is_some(),
            self.active_detached_session,
            self.detached_viewer_window_id,
            self.detached_viewer_independent_active,
            self.detached_image_windows.len()
        ));
        self.viewer_presentation = presentation;
        if detached_still && !independent_detached_still {
            let _ = self.take_parked_fullfeature_linked_still_for_grid_open(idx, presentation);
        }
        if matches!(presentation, ViewerPresentation::DetachedWindow) {
            let id = self.ensure_detached_viewer_window_id();
            // keep-alive: detached を開いた = セッション開始 (§3.7 set)。book context が
            // あれば Book、なければ Image。folder-nav reopen でも同じ window_id で据え置く。
            let source = if self.active_detached_viewer_context_present() {
                DetachedSource::Book
            } else {
                self.detached_source_for_idx(idx)
            };
            self.begin_active_detached_session(id, source);
        } else {
            // 非 detached を開いた (動画 fullscreen / detached 非対応アイテム等) =
            // detached セッションは終了。明示遷移なので session を畳む (§3.7)。
            //
            // ただし active_detached_viewer_context が外側に存在する状態でここへ来た場合、
            // これは **メイン context 側** の open であり、active detached session の所有者ではない。
            // その session を畳むと、独立 PDF などの別ウィンドウ context が main 側の
            // ページ切替に巻き込まれ、同じ ViewportId / bundle が混線する。
            let owns_active_detached_session = self.active_detached_viewer_context.is_none();
            if owns_active_detached_session && self.active_detached_session.is_some() {
                self.begin_active_detached_session_close("open_non_detached");
                self.finish_active_detached_session_close("open_non_detached");
            }
            self.detached_viewer_window_id = None;
        }
        self.detached_viewer_independent_active = independent_detached_still;
        if matches!(presentation, ViewerPresentation::DetachedWindow)
            && let Some(window_id) = self.detached_viewer_window_id
        {
            self.update_detached_window_runtime_flags(
                window_id,
                !independent_detached_still,
                "prepare_viewer_presentation_open",
            );
        }
        if focus_detached_from_grid {
            self.detached_viewer_focus_requested = true;
        }
        if self.viewer_item_supports_egui_detached_viewport(idx) {
            self.detached_viewer_open_next_still_detached_once = false;
        }
        if !matches!(presentation, ViewerPresentation::DetachedWindow)
            || !self.viewer_item_supports_egui_detached_viewport(idx)
        {
            self.detached_viewer_independent_active = false;
            self.detached_viewer_focus_requested = false;
        }
        self.last_viewer_sync_stamp = if matches!(presentation, ViewerPresentation::DetachedWindow)
        {
            self.viewer_sync_stamp_for_idx(idx)
        } else {
            None
        };
        // フルスクリーン入場時に「このセッションが in-window モードか」を
        // 設定値から確定する。動画 (native presenter) でも静止画 (embedded
        // 描画) でも採用し、毎フレームの分岐が参照する「実モード」として
        // 記録する。これにより in-window 動画 ⇔ 静止画をホイールで往復しても
        // モードが一貫する。
        self.native_video_in_window_active = matches!(presentation, ViewerPresentation::MainWindow);
        // 新しい fullscreen を開くので、進行中だったトグル切替 pending は破棄する。
        self.native_video_mode_switch = None;
        self.log_detached_image_window_debug(format!(
            "prepare_viewer_presentation_open_state idx={idx} presentation={:?} \
             fs_idx={:?} session={:?} window_id={:?} independent={} \
             focus_requested={} last_stamp={} passive_windows={}",
            self.viewer_presentation,
            self.fullscreen_idx,
            self.active_detached_session,
            self.detached_viewer_window_id,
            self.detached_viewer_independent_active,
            self.detached_viewer_focus_requested,
            self.last_viewer_sync_stamp.is_some(),
            self.detached_image_windows.len()
        ));

        if entering_native_video {
            // Video-to-video source swaps keep the native presenter HWND alive.
            // Re-cloaking the main HWND for those swaps creates an unnecessary
            // DWM state transition on every wheel tick and can leak as a
            // physical-screen-only flicker even though OBS/window capture misses it.
            //
            // in-window モード: presenter は main HWND の子として client 領域に
            // 重なるので main は cloak しない (cloak すると親ごと DWM 合成から
            // 外れて子も消える)。
            if matches!(presentation, ViewerPresentation::Fullscreen)
                && self.native_video_presenter_hwnd().is_none()
            {
                self.sync_native_video_main_cloak(true);
            } else {
                self.sync_native_video_main_cloak(false);
            }
            // 黒 chrome は fullscreen/backdrop viewport を描画した後の update 末尾で
            // 適用する。ここで先に DWM chrome だけ変えると、通常ウィンドウの
            // タイトルバーが黒くなってから fullscreen が出る 1-frame race が見える。
            self.native_video_main_chrome_restore_at = None;
        } else {
            self.sync_native_video_main_cloak(false);
        }

        // 動画フルスクリーン → 別 idx を直接 open する経路 (例: 動画→画像遷移、
        // open_fullscreen_from_fs_navigation の継続ナビ) では、close_fullscreen を
        // 経由しないので奪還候補がそのまま残る。継続ナビなら新しい fullscreen が
        // 引き続き表示されているため reclaim 不要 → ここでクリアする。
        self.clear_pending_main_foreground_reclaim();
    }

    #[cfg(windows)]
    fn take_detached_folder_nav_reuse_window_for_open(&mut self, idx: usize) -> bool {
        if !self.detached_viewer_folder_nav_reuse_window_once {
            return false;
        }
        let presentation = self.effective_viewer_presentation_for_open(idx);
        let reuse = matches!(presentation, ViewerPresentation::DetachedWindow)
            && self.viewer_item_supports_detached_still(idx)
            && self.detached_viewer_window_id.is_some();
        self.detached_viewer_folder_nav_reuse_window_once = false;
        if reuse {
            self.fs_open_intent_from_grid = false;
            self.log_detached_image_window_debug(format!(
                "folder_nav_reuse_window_open idx={idx} window_id={:?} \
                 generation={} presentation={presentation:?}",
                self.detached_viewer_window_id, self.fs_viewport_generation
            ));
        } else {
            self.log_detached_image_window_debug(format!(
                "folder_nav_reuse_window_skip idx={idx} window_id={:?} \
                 presentation={presentation:?} supports_still={} grid_intent={}",
                self.detached_viewer_window_id,
                self.viewer_item_supports_detached_still(idx),
                self.fs_open_intent_from_grid
            ));
        }
        reuse
    }

    /// フルスクリーン表示を開始する。
    /// キャッシュ済みなら即座に表示し、そうでなければ読み込みを開始する。
    /// 動画アイテムの場合はサムネイル＋再生ボタンを表示するだけで読み込みは不要。
    ///
    /// **perf 計装の注意**: この関数は `input_seq` を bump しない。呼び出し元が
    /// ユーザー入力起点の場合は事前に `bump_input_seq` すること。slideshow や
    /// 見開き正規化のような内部起動は bump しないので、fs load は現在の
    /// `self.input_seq` (= 直近のユーザー入力) に紐づく。
    pub fn open_fullscreen(&mut self, idx: usize, history_trigger: HistoryTrigger) {
        self.open_fullscreen_with_materialization(
            idx,
            history_trigger,
            FsOpenMaterialization::Eager,
        );
    }

    pub(crate) fn open_fullscreen_with_materialization(
        &mut self,
        idx: usize,
        history_trigger: HistoryTrigger,
        materialization: FsOpenMaterialization,
    ) {
        #[cfg(windows)]
        if self.route_materialized_physical_still_open_to_active_context(idx) {
            return;
        }

        // viewer 内ページ送りでは idx を差し替える前に、カラー化待ち用の完成表示と
        // 前ページの完成済み編集結果を退避する。grid からの新規入場では
        // fullscreen_idx=None なので holdover は空になる。
        if self.fullscreen_idx != Some(idx) {
            if materialization.is_eager() {
                self.capture_colorize_page_transition_holdover(idx);
            } else {
                self.clear_colorize_display_unit_holdover();
            }
        }
        if self.fullscreen_idx.is_some() && self.fullscreen_idx != Some(idx) {
            self.cache_current_edit_preview_if_ready();
        }
        // 明示 open の左右パネルはファイル単位の一時状態。新規入場と viewer 内の
        // ファイル移動が集約されるこの境界で、前ファイルの owner を引き継がない。
        self.reset_fs_side_panel_runtime_for_file_change();
        crate::logger::log(format!("=== open_fullscreen: idx={idx} ==="));
        // 別アイテムへナビ / 新規オープンする時点で、前アイテムの「動画→音声モード」(Inc 7) は
        // 終わる。stale index (同 idx が別 item を指す) 事故を避けるため必ずクリアする
        // (Codex 7c 設計)。前アイテムの動画プレイヤーはこの後 evict されるので再 attach は不要。
        self.video_audio_mode = None;
        // 7e: 別アイテムへ open するなら VST ホスト状態も落とす (stale idx 防止)。
        self.video_audio_vst = None;
        #[cfg(windows)]
        {
            self.video_audio_mode_entry_target = None;
            self.video_audio_exit_pending = None;
        }
        // viewer 内の手動ナビ (grid からの新規 open ではない = `fs_open_intent_from_grid` が false、
        // かつ既にフルスクリーン中) で **メディア (動画/音声)** を開くときは、現在の presentation を維持する
        // (one-shot 焼き付け)。「別ウィンドウで開く」設定は grid からの新規 open (Enter /
        // ダブルクリック) だけに適用し、F12 で main に出した動画を矢印 / wheel / Home / End /
        // Ctrl+G / 検索ジャンプで送っても別窓へ飛ばさない (実機 FB 2026-07-02、Codex 実機 P1/P2)。
        // 全 nav 経路が open_fullscreen に集約するのでここ 1 箇所で塞ぐ。deferred source-swap は
        // 完了時にこの open_fullscreen を通り、その時点の `viewer_presentation` を読む。
        // pending 中の F12 は共通入口で無視するため、player 不在時に設定だけが反転することもない。
        // auto-advance が明示 one-shot
        // を立てている場合はそれを尊重する (is_none 判定)。この判定は `fullscreen_idx` を idx へ
        // 更新する前・`prepare_viewer_presentation_open` が presentation を書き換える前に行う。
        #[cfg(windows)]
        if self.fs_media_open_forced_presentation.is_none()
            && !self.fs_open_intent_from_grid
            && self.fullscreen_idx.is_some()
            && self.viewer_item_is_media(idx)
        {
            self.fs_media_open_forced_presentation = Some(self.viewer_presentation);
        }
        #[cfg(windows)]
        let reuse_detached_window_for_folder_nav =
            self.take_detached_folder_nav_reuse_window_for_open(idx);
        #[cfg(windows)]
        if !reuse_detached_window_for_folder_nav {
            self.prepare_detached_image_windows_for_open(idx);
        }
        #[cfg(windows)]
        if self.vst3_deferred_media_open.is_some() && self.vst3_deferred_media_open != Some(idx) {
            self.vst3_deferred_media_open = None;
        }
        // フルスクリーン側ではページ単位 (= 1 ファイル/1 ページ) 操作中心になるため、
        // グリッド側で積み上げた Undo は破棄する。フルスクリーン中の操作は新しい
        // スタックで管理する (画像移動でさらにクリアされる)。
        self.clear_meta_undo();
        self.capture_region_selection = None;
        if self.fullscreen_idx.is_none() {
            self.fs_pdf_display_target = None;
        }
        self.fullscreen_idx = Some(idx);
        // 音声以外を開いたら音楽ビュー (Inc 3b/4) の状態を破棄する。フルスクリーン内で
        // 音声→画像/動画へ移動しても draw_fs_music_view は呼ばれず、放置すると旧音声の解析
        // ワーカー / 常駐 PCM / parked な spectrum worker が次の音声 open か close まで残る
        // (Codex Inc 4 P2)。音声→別音声は draw_fs_music_view の ensure_music_analysis が path
        // 比較で処理するのでここでは触らない。
        // ParkedLive の音楽窓が global music_* を消費中の非メディア open は破棄しない
        // (詳細は should_clear_music_view_on_open、review-v2.3.0 P2-3)。
        if self.should_clear_music_view_on_open(idx) {
            self.clear_music_view_state();
        }
        // 本ごとの読書位置レジューム: 画像本のページを開くたびに最後のページを記録
        // (再起動を跨いで復元する。dedup 付きなので連続ページ送りでも書き込みは最小)。
        self.record_book_resume(idx);
        self.record_reading_history(idx, history_trigger);
        self.video_continuous_last_eof = None;
        #[cfg(windows)]
        let entering_native_video_fullscreen =
            matches!(self.items.get(idx), Some(GridItem::Video(_)));
        #[cfg(windows)]
        self.prepare_viewer_presentation_open(idx, entering_native_video_fullscreen);
        // フルスクリーン入場時にカーソル idle タイマをリセット (= 直前まで隠れていた
        // 状態を引き継がないようにする)。前回フルスクリーンを 5 分放置した後に
        // すぐ再入場した場合、Some(<古い時刻>) のままだと 1 フレーム目で
        // 「設定秒数以上経過」と判定されカーソルが即時消える事故を防ぐ。
        // NOTE: この無条件リセットは「新規入場」向け。ページ送り / スライドショーなどの
        // fullscreen 内ナビは cursor 状態を保存・復元する
        // `open_fullscreen_from_fs_navigation` のようなラッパーを通すこと。
        self.cursor_last_activity = Some(std::time::Instant::now());
        self.cursor_hidden = false;
        self.refresh_fullscreen_video_marker_cache(idx);
        self.adjust_spread_target = AdjustSpreadTarget::Left;
        // PDF pool の Critical 予約は `pdf_loader::CRITICAL_RESERVATION_ACTIVE` を
        // 常時 ON にする方針 (v1.0.0)。グリッドからの Enter (= Critical な
        // enumerate_pages_async) が、サムネ先読みの Normal ジョブ in-flight 待ちで
        // 2-3 秒詰まる事例を解消するため。ここでの再設定は不要。
        self.fs_opened_at = Some(std::time::Instant::now());
        self.fs_focus_grace_elapsed = false;
        // 初回フレームでフォーカス遷移 (false→true) が誤検出されないように
        // true 始まりにする (グレース期間中にフォーカス復帰扱いされるのを防ぐ)
        self.fs_prev_focused = true;
        self.fs_focus_regained_at = None;
        self.fs_prev_foreground_hwnd = 0;
        self.fs_last_native_focus_claim_at = None;
        self.fs_last_main_focus_restore_at = None;
        self.fs_primary_suppression = Default::default();
        self.reset_erase_mode();

        // 360 度パノラマビュー: 別画像へナビ時は GPU リソースを解放する
        // (Arc + LRU 1 設計、§4.1)。state は保持して同セッションで equirect に
        // 戻ったときに yaw/pitch を引き継げるようにする (§6.3)。
        // CallbackResources からも UploadedPanoTextureRef を除去 (Codex P2 第 18 ラウンド)。
        self.clear_pano_upload();
        // Phase 2a (§4.6.3 step 8): refinement を drop + 進行中の追加 worker を cancel。
        //
        // **HighResSource の保持ポリシー** (Codex P1 第 2 ラウンド指摘反映、2026-05):
        // 新しく開く idx の source_key に対応する HighResSource は **残す**。理由:
        //   - prefetch で tee 済みの画像 (= 先回りで pano_high_res_source に入れた) で、
        //     その idx を開いた瞬間に clear すると settle が永久ロード中になる
        //   - 同セッション中の再オープン (戻る/進む) でも HighResSource が必要なら
        //     再デコードを強いられる
        // 他 entry は drop することで「LRU 1 (active のみ)」を維持。
        // refinement は **cancel signaling 付きヘルパ**で落とす (Codex P0 第 5、2026-05)。
        self.clear_pano_refinement();
        let keep_source_key: Option<String> = self.metadata_cache_key(idx);
        match keep_source_key.as_ref() {
            Some(k) => {
                self.pano_high_res_source.retain(|key, _| key == k);
            }
            None => {
                // metadata_cache_key 取得失敗の一時的なケース (= idx 自体は存在するが
                // path 解決に失敗、稀)。**全 entry を破棄せず保持** (Codex P2 第 5、
                // 2026-05): 元実装は `clear()` だったが、これは prefetch tee 済みの
                // HighResSource を一発で消し飛ばす。None フォールバックでは安全側に
                // 振って何もしない (= LRU 1 ポリシーは次回正しい open_fullscreen で
                // 再評価される)。
                let _ = self.pano_high_res_source.len(); // borrow hint, no-op
            }
        }
        // `pano_high_res_pending` も新 idx の entry は保持する (Codex P2 第 5、2026-05):
        // prefetch 経路で先に走った load が完了直前のときに drain で cancel すると、
        // 直後に開いた画像で auto-kick が再起動する。HighResSource の retain ポリシーと
        // 揃えて、**新 idx の source_key は cancel しない**。
        match keep_source_key.as_ref() {
            Some(k) => {
                self.pano_high_res_pending.retain(|key, req| {
                    if key == k {
                        true
                    } else {
                        req.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
                        false
                    }
                });
            }
            None => {
                // None フォールバック: 何もしない (上の HighResSource None branch と同じ判断)
            }
        }
        self.pano_banner_remember_session = false;
        // 案内トースト用フラグをリセット (Codex P2 第 18 ラウンド)。実発火は
        // ページ補正トーストとの競合回避のため後段でまとめる (Codex P3 第 20 ラウンド)。
        self.pano_toast_shown_for_current_fs = false;

        // トースト発火 (Codex P3 第 20 ラウンド: 競合回避):
        // 360 候補画像 + ページ個別補正の両方が当てはまる場合、後の `show_feedback_toast`
        // が前の表示を即上書きしてしまう。**ユーザー体験上 360 案内のほうが希少 + 重要**
        // (補正適用は静かに動いてもバナーで気づける、360 案内は逃すと存在に気づかない)
        // なので、360 トーストが立った場合は補正トーストを抑止する優先順位ポリシー。
        let pano_toast_fired = self.try_show_pano_hint_toast_returning_fired(idx);
        if !pano_toast_fired && self.adjustment_page_params.contains_key(&idx) {
            self.show_feedback_toast("ページ補正適用".to_string());
        }
        // legacy の表示用補正 texture はページ入場時に作り直す。final pipeline は
        // edit/source generation と AdjustParams hash で正当性を判定できるため、
        // ここで adjustment generation を bump してはいけない。bump すると次ページの
        // 完成済みカラー化先読みと進行中 worker を、表示直前に自分で破棄してしまう。
        self.adjustment_cache.remove(&idx);
        self.invalidate_compare_prepared_for_idx(idx);
        let grid_open_intent = std::mem::take(&mut self.fs_open_intent_from_grid);
        let video_ignore_resume_once = self.fs_video_open_ignore_resume_once;

        // 画像切り替え時にズーム/パン/キャッシュをリセット
        self.analysis_zoom = 1.0;
        self.analysis_pan = egui::Vec2::ZERO;
        self.analysis_pan_drag_start = None;
        self.analysis_guide_drag = None;
        self.analysis_overlay_cache = None;
        self.analysis_hist_cache = None;
        self.analysis_sv_cache = None;
        self.fs_zoom = 1.0;
        self.fs_pan = egui::Vec2::ZERO;
        self.fs_pan_drag_start = None;
        self.fs_vertical_scroll = 0.0;
        self.continuous_reading_scroll_transition = None;
        self.slideshow_scroll_range_cache = None;
        self.fs_seek_drag_active = false;
        self.fs_seek_overlay_visible = false;
        self.fs_vertical_cache_keep_set.clear();
        self.continuous_page_transitions.clear();
        self.fs_free_rotation = 0.0;
        self.fs_rotation_drag_start = None;
        // 透過背景は「一時的な好み」なので画像切替時にリセット (plan-v0.7.0.md の方針)
        self.fs_transparent_bg_mode = 0;

        match self.items.get(idx) {
            Some(GridItem::Image(_))
            | Some(GridItem::ZipImage { .. })
            | Some(GridItem::PdfPage { .. }) => {
                if materialization.is_eager() {
                    let load_state = self.ensure_fs_page_load(idx);
                    if load_state.is_display_ready() {
                        crate::logger::log(format!("  cache hit idx={idx} → instant display"));
                    }
                    if self.reading_flow.is_paged() {
                        self.update_prefetch_window(idx);
                    }
                }
            }
            Some(GridItem::Video(_)) => {
                // 動画はインライン再生 (フルスクリーン化と同時に VideoPlayer を起動)。
                // start_fs_load の早期分岐で GridItem::Video を検出し、
                // FsCacheEntry::Video を fs_cache に挿入する。
                if self.fs_cache.contains_key(&idx) {
                    self.fs_video_open_autoplay_override = None;
                    self.fs_video_open_ignore_resume_once = false;
                    #[cfg(windows)]
                    {
                        self.vst3_deferred_media_open = None;
                    }
                    if video_ignore_resume_once {
                        if let Some(FsCacheEntry::Video { player, .. }) = self.fs_cache.get(&idx) {
                            player.seek(0.0);
                        }
                    }
                    // タイルモード (video_tile_*) は native presenter 前提の Windows 専用。
                    #[cfg(windows)]
                    let should_autoplay_cached_video =
                        !self.video_tile_mode_active && !self.video_tile_reopen_pending;
                    #[cfg(not(windows))]
                    let should_autoplay_cached_video = true;
                    if should_autoplay_cached_video {
                        #[cfg(windows)]
                        let started_normalize_scan =
                            self.start_normalize_scan_for_deferred_play_intent(idx);
                        #[cfg(not(windows))]
                        let started_normalize_scan = false;
                        if !started_normalize_scan {
                            #[cfg(windows)]
                            {
                                self.resume_deferred_normalize_playback_without_scan(idx);
                                self.maybe_start_normalize_scan_for_play_intent(idx);
                            }
                            #[cfg(not(windows))]
                            if let Some(FsCacheEntry::Video { player, .. }) =
                                self.fs_cache.get(&idx)
                            {
                                player.set_playing(true);
                            }
                        }
                    }
                    crate::logger::log(format!("  video cache hit idx={idx} → resume playback"));
                } else {
                    #[cfg(windows)]
                    if self.vst3_startup_load_pending() {
                        crate::logger::log(format!(
                            "[VST3 startup] defer video open idx={idx} until background load completes"
                        ));
                        self.fs_open_intent_from_grid = grid_open_intent;
                        self.vst3_deferred_media_open = Some(idx);
                        return;
                    }
                    crate::logger::log(format!("  video idx={idx} → start inline playback"));
                    self.fs_open_intent_from_grid = grid_open_intent;
                    self.start_fs_load(idx);
                }
            }
            Some(GridItem::Audio(_)) => {
                // 音声: headless プレイヤーで音楽ビュー再生 (D3、Inc 3)。
                // cache があれば再生再開、無ければ start_fs_load が headless player を作る。
                if self.fs_cache.contains_key(&idx) {
                    if let Some(FsCacheEntry::Video { player, .. }) = self.fs_cache.get(&idx) {
                        player.set_playing(true);
                    }
                    // ノーマライズ UI 状態は close_fullscreen で normalize_ui_states が cleanup
                    // されるので、キャッシュ再生で戻ってきたら再同期する (でないと player には
                    // gain 適用済みなのに HUD ボタンが Off 表示になり不整合、Codex P3)。DB
                    // ヒットなら gain 再適用 + OnApplied、ミスなら OnUnmeasured、OFF なら Off。
                    #[cfg(windows)]
                    self.init_normalize_state_for_opened_video(idx);
                    crate::logger::log(format!("  audio cache hit idx={idx} → resume playback"));
                } else {
                    // 起動時 VST3 チェーンロード中に音声を再生開始すると、まだ不安定な
                    // (add_plugin のリセットで in/out ring drain 中の) チェーンに pump が小ブロックを
                    // push → process_block が 100ms timeout、3 回連続で VST3 チェーンが auto-disable
                    // され、動画 VST まで巻き添えでセッション全体死ぬ (実害 2026-07-04)。動画 open と
                    // 同じくロード完了まで遅延する (Inc 6 ① で音声が VST を通るようになって顕在化)。
                    #[cfg(windows)]
                    if self.vst3_startup_load_pending() {
                        crate::logger::log(format!(
                            "[VST3 startup] defer audio open idx={idx} until background load completes"
                        ));
                        self.fs_open_intent_from_grid = grid_open_intent;
                        self.vst3_deferred_media_open = Some(idx);
                        return;
                    }
                    crate::logger::log(format!("  audio idx={idx} → start music view playback"));
                    // open_fullscreen 冒頭で take した grid/nav ワンショットを start_fs_load の
                    // 音声分岐が再度 take するので、動画分岐 (25987) と同じく戻してから呼ぶ。
                    // これで「音声 × 一覧から開く」設定 (music_open_resume) が効く (Codex P2)。
                    self.fs_open_intent_from_grid = grid_open_intent;
                    self.start_fs_load(idx);
                }
            }
            _ => {}
        }

        // AI / EXIF / XMP メタデータ読み込みは **バックグラウンドスレッド** で実行する。
        // XMP は JPEG/PNG 全体を読むため UI スレッドで同期実行すると 20MP 画像で
        // 100ms 級にブロックする。メタデータパネルは値到着まで空表示。
        self.start_metadata_load(idx);
    }

    /// メタデータ / EXIF / XMP キャッシュ用の正規化キーを返す。
    ///
    /// `Image` / `Video` / `Audio` は正規化パス、`ZipImage` は `zip_path::entry_name`、
    /// `PdfPage` は `pdf_path::page_N` の形式で、ZIP エントリ・PDF ページごとに
    /// 衝突しないキーを返す ([`App::page_path_key`] と同じ規約)。
    /// 動画は EXIF/AI metadata は持たないが、mXD が埋めた XMP (X ツイート情報)
    /// を表示する必要があるため、メタデータキーを発行する。音声も詳細ビューの
    /// 遅延メタ (長さ / コーデック) の格納キーとしてこのキーを使う。
    pub(crate) fn metadata_cache_key(&self, idx: usize) -> Option<String> {
        let item = self.items.get(idx)?;
        let key = match item {
            GridItem::Image(p) | GridItem::Video(p) | GridItem::Audio(p) => {
                crate::adjustment_db::normalize_path(p)
            }
            GridItem::ZipImage {
                zip_path,
                entry_name,
            } => {
                format!(
                    "{}::{}",
                    crate::adjustment_db::normalize_path(zip_path),
                    entry_name.to_lowercase()
                )
            }
            GridItem::PdfPage {
                pdf_path, page_num, ..
            } => {
                format!(
                    "{}::page_{}",
                    crate::adjustment_db::normalize_path(pdf_path),
                    page_num
                )
            }
            _ => return None,
        };
        Some(key)
    }

    fn details_lazy_cache_key(&self, idx: usize) -> Option<String> {
        if let Some(key) = self.metadata_cache_key(idx) {
            return Some(key);
        }
        match self.items.get(idx)? {
            GridItem::Folder(path)
            | GridItem::ZipFile(path)
            | GridItem::PdfFile(path)
            | GridItem::ConvertibleArchive { path, .. } => {
                Some(crate::adjustment_db::normalize_path(path))
            }
            GridItem::ZipDir {
                zip_path,
                dir_prefix,
                ..
            } => Some(format!(
                "{}::zipdir:{}",
                crate::adjustment_db::normalize_path(zip_path),
                dir_prefix.to_lowercase()
            )),
            _ => None,
        }
    }

    /// 指定 idx の AI/EXIF/XMP メタデータ読み込みをバックグラウンドで開始する。
    /// 全キャッシュが既にヒットしていれば spawn しない (no-op)。
    /// 既存 pending があれば cancel して置き換える (連打時は最新だけ処理)。
    ///
    /// UI 側 (`ui_metadata_panel`) はキャッシュヒット時のみ内容を表示するので、
    /// 結果到着まではパネルは空表示のまま (None 扱い) になる。
    fn start_metadata_load(&mut self, idx: usize) {
        let Some(key) = self.metadata_cache_key(idx) else {
            return;
        };

        // 全キャッシュが既に揃っているなら何もしない
        let ai_hit = self.metadata_cache.contains_key(&key);
        let exif_hit = self.exif_cache.contains_key(&key);
        let xmp_hit = self.xmp_cache.contains_key(&key);
        let panorama_hit = self.xmp_panorama_info.contains_key(&key);
        let sidecar_hit = self.sidecar_display_cache.contains_key(&key);
        if ai_hit && exif_hit && xmp_hit && panorama_hit && sidecar_hit {
            return;
        }

        // 既存の in-flight を cancel (新 idx なら旧結果は不要)
        if let Some(pending) = self.metadata_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }

        // スレッドに渡すため item を snapshot (clone)
        let item = match self.items.get(idx) {
            Some(g) => g.clone(),
            None => return,
        };
        let relative_page_provenance = self.relative_page_provenance_for_idx(idx);
        let hidden: Vec<String> = self.settings.exif_hidden_tags.clone();
        let key_owned = key.clone();
        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_w = Arc::clone(&cancel);
        let (tx, rx) = mpsc::channel();

        std::thread::Builder::new()
            .name(format!("metadata-load-{idx}"))
            .spawn(move || {
                let result = run_metadata_load(
                    key_owned,
                    item,
                    relative_page_provenance,
                    &hidden,
                    &cancel_w,
                );
                if cancel_w.load(Ordering::Relaxed) {
                    return;
                }
                if let Some(r) = result {
                    let _ = tx.send(r);
                }
            })
            .ok();

        self.metadata_pending = Some(MetadataLoadPending { cancel, rx });
    }

    /// メタデータ読み込み結果を非同期に受信してキャッシュに投入する。
    /// 毎フレーム呼ばれる。ヒット時はパネルが自動的に内容を表示する。
    pub(crate) fn poll_metadata_load(&mut self) {
        let Some(pending) = self.metadata_pending.as_ref() else {
            return;
        };
        match pending.rx.try_recv() {
            Ok(r) => {
                self.metadata_cache.insert(r.key.clone(), r.metadata);
                self.exif_cache.insert(r.key.clone(), r.exif);
                self.xmp_cache.insert(r.key.clone(), r.xmp);
                self.sidecar_display_cache.insert(r.key.clone(), r.sidecar);
                // GPano は実画像でのみ非 None。動画 / 構造アイテムは worker 側で
                // None を返すが、cache hit 判定のため key を挿入する (再 spawn 抑止)。
                let arrived_key = r.key.clone();
                self.xmp_panorama_info.insert(r.key, r.panorama);
                self.metadata_pending = None;
                // 360 案内トースト補完: 到着 key が現フルスクリーン idx の source_key
                // と一致するなら、初回 toast を試行 (Codex P2 第 18 ラウンド)。
                // open_fullscreen で発火失敗 (= XMP 未到着) だったケースをここで救う。
                if let Some(fs_idx) = self.fullscreen_idx
                    && let Some(current_key) = self.metadata_cache_key(fs_idx)
                    && current_key == arrived_key
                {
                    self.maybe_show_panorama_hint_toast(fs_idx);
                    // Codex P2 第 2 (2026-05): XMP が fs_cache より遅れて到着した
                    // 360 候補 (例: DSLR partial-FOV、aspect 非 2:1) で、tee 不採用
                    // だった画像でも、ここで quality state を再評価し、必要なら
                    // settle を起動できるようにする。
                    // - SettleReady の場合: fs_cache の pixels をフル RGBA とみなして
                    //   HighResSource::Decoded に詰め直す経路はコスト高なので、
                    //   `update_pano_refinement` 側の自動再要求 (start_pano_high_res_load)
                    //   経路に任せる。ここでは state の確定だけを行う。
                    self.maybe_update_pano_quality_state_from_static(fs_idx);
                }
            }
            Err(mpsc::TryRecvError::Empty) => {}
            Err(mpsc::TryRecvError::Disconnected) => {
                self.metadata_pending = None;
            }
        }
    }

    fn apply_details_lazy_meta_patch(
        &mut self,
        key: String,
        meta: DetailsLazyMeta,
        loaded: DetailsLazyFieldFlags,
    ) {
        let replaced_existing_source = match self.details_lazy_meta.entry(key) {
            std::collections::hash_map::Entry::Vacant(entry) => {
                let mut value = DetailsLazyMeta::default();
                value.apply_patch(meta, loaded);
                entry.insert(value);
                false
            }
            std::collections::hash_map::Entry::Occupied(mut entry) => {
                entry.get_mut().apply_patch(meta, loaded)
            }
        };
        if replaced_existing_source {
            self.details_cell_content_revisions.bump_all_lazy_fields();
        } else {
            self.details_cell_content_revisions.bump_lazy_fields(loaded);
        }
    }

    fn details_page_count_uses_visible_stages(&self) -> bool {
        self.settings.grid_view_mode == crate::settings::GridViewMode::Details
            && self.settings.details_show_page_count
            && self.settings.details_sort_key != crate::settings::DetailsSortKey::PageCount
    }

    fn details_visible_page_count_needs_load(&self) -> bool {
        self.details_tag_prewarm_indices.iter().copied().any(|idx| {
            self.lazy_load_page_count_for_idx(idx)
                && self
                    .details_lazy_meta_for_idx(idx)
                    .is_none_or(|meta| !self.details_page_count_meta_satisfies_idx(idx, meta))
        })
    }

    fn finish_details_lazy_session(&mut self, failed: usize) {
        self.details_image_dims_state = LazyColumnState::Ready { failed };
        self.prune_details_lazy_meta_cache();
        if self.facet_ai_filter_active() {
            let ready_state = self.details_image_dims_state;
            self.rebuild_visible_indices();
            self.details_image_dims_state = ready_state;
        }
        if self.settings.grid_view_mode == crate::settings::GridViewMode::Details
            && matches!(
                self.settings.details_sort_key,
                crate::settings::DetailsSortKey::PageCount
                    | crate::settings::DetailsSortKey::ImageDimensions
                    | crate::settings::DetailsSortKey::Created
                    | crate::settings::DetailsSortKey::VideoDuration
                    | crate::settings::DetailsSortKey::VideoDimensions
                    | crate::settings::DetailsSortKey::VideoCodec
            )
        {
            self.rebuild_details_order();
        }
    }

    /// 詳細一覧の描画で可視 + 先読み範囲が確定した後、ジョブではなく走査セッションを
    /// 完了できるか判定する。未取得ページ数があれば同じセッションの次ジョブを開始し、
    /// 無ければここだけが staged page-count セッションを Ready にする。
    pub(crate) fn reconcile_details_lazy_session_after_grid(&mut self, ctx: &egui::Context) {
        if !self.details_page_count_uses_visible_stages() {
            return;
        }

        let failed = match self.details_image_dims_state {
            LazyColumnState::Reconciling { failed, .. } => Some(failed),
            LazyColumnState::Ready { .. } if self.details_visible_page_count_needs_load() => None,
            _ => return,
        };

        if self.details_visible_page_count_needs_load() {
            self.details_lazy_visible_revision = self.details_lazy_visible_revision.wrapping_add(1);
            self.details_image_dims_state = LazyColumnState::NotRequested;
            self.start_details_meta_load(ctx);
        } else if let Some(failed) = failed {
            self.finish_details_lazy_session(failed);
            ctx.request_repaint();
        }
    }

    pub(crate) fn poll_details_meta_load(&mut self, ctx: &egui::Context) {
        if !self.details_lazy_columns_visible() {
            if let Some(pending) = self.details_meta_pending.take() {
                pending.cancel.store(true, Ordering::Relaxed);
            }
            self.details_lazy_visible_revision = self.details_lazy_visible_revision.wrapping_add(1);
            self.details_image_dims_state = LazyColumnState::Disabled;
            return;
        }

        if matches!(self.details_image_dims_state, LazyColumnState::Disabled) {
            self.details_image_dims_state = LazyColumnState::NotRequested;
        }

        // filter / 表示集合変更は target membership を変える。scroll は revision を変えないので、
        // この境界でだけ plan / worker を破棄して新しい走査 session を開始する。
        let requirements_stale = self
            .details_meta_pending
            .as_ref()
            .is_some_and(|pending| pending.visible_revision != self.details_lazy_visible_revision);
        if requirements_stale {
            if let Some(pending) = self.details_meta_pending.take() {
                pending.cancel.store(true, Ordering::Relaxed);
            }
            self.details_image_dims_state = LazyColumnState::NotRequested;
            ctx.request_repaint();
        }

        // ページ数ソート以外は画面外の全コンテナを開かず、可視範囲 + 先読み範囲だけを
        // 段階取得する。前の範囲が Ready でもスクロール先に未取得行があれば次ジョブを開始。
        if self.details_page_count_uses_visible_stages()
            && matches!(self.details_image_dims_state, LazyColumnState::Ready { .. })
            && self.details_visible_page_count_needs_load()
        {
            self.details_lazy_visible_revision = self.details_lazy_visible_revision.wrapping_add(1);
            self.details_image_dims_state = LazyColumnState::NotRequested;
        }

        // 大きく scroll して可視近傍が移ったら、全件 plan / worker を作り直さず、現在の
        // 可視 target だけを priority queue へ差し込む。idle gate は従来どおり共有する。
        if self.settings.grid_view_mode == crate::settings::GridViewMode::Details
            && self.details_meta_pending.is_some()
        {
            let current_visible_order: Vec<usize> = self
                .details_tag_prewarm_indices
                .iter()
                .copied()
                .filter(|&idx| {
                    self.details_item_requires_lazy_meta(idx)
                        && self
                            .details_lazy_meta_for_idx(idx)
                            .is_none_or(|meta| !self.details_lazy_meta_satisfies_idx(idx, meta))
                })
                .collect();
            let current_visible_indices: HashSet<usize> =
                current_visible_order.iter().copied().collect();
            let current_visible: HashSet<String> = current_visible_indices
                .iter()
                .copied()
                .filter_map(|idx| self.details_lazy_cache_key(idx))
                .collect();
            let reprioritize_candidate =
                self.details_meta_pending.as_ref().is_some_and(|pending| {
                    details_meta_reprioritize_candidate(
                        &current_visible,
                        &pending.normal_target_keys,
                    )
                });
            let now = std::time::Instant::now();
            let reprioritize = self.details_meta_pending.as_ref().is_some_and(|pending| {
                details_meta_reprioritize_allowed(
                    now,
                    self.last_prefetch_scroll_at,
                    &current_visible,
                    &pending.normal_target_keys,
                )
            });
            if reprioritize_candidate
                && !reprioritize
                && let Some(last_scroll_at) = self.last_prefetch_scroll_at
            {
                let elapsed = now.saturating_duration_since(last_scroll_at);
                if elapsed < PREFETCH_IDLE_THRESHOLD {
                    ctx.request_repaint_after(PREFETCH_IDLE_THRESHOLD - elapsed);
                }
            }
            if reprioritize {
                let priority_targets: Vec<DetailsMetaTarget> = current_visible_order
                    .iter()
                    .copied()
                    .filter_map(|idx| {
                        self.details_meta_target_for_idx(idx, &current_visible_indices, true)
                    })
                    .collect();
                let priority_count = priority_targets.len();
                if let Some(pending) = self.details_meta_pending.as_mut() {
                    pending.normal_target_keys = current_visible;
                    match &mut pending.phase {
                        DetailsMetaPendingPhase::Planning(plan) => {
                            plan.visible_near = current_visible_indices;
                        }
                        DetailsMetaPendingPhase::Loading { priority_tx, .. } => {
                            if !priority_targets.is_empty() {
                                let _ = priority_tx.send(priority_targets);
                            }
                        }
                    }
                }
                if crate::perf::is_enabled() {
                    crate::perf::event(
                        "details_meta",
                        "priority_update",
                        None,
                        self.items_generation,
                        &[("targets", serde_json::Value::from(priority_count))],
                    );
                }
                ctx.request_repaint();
            }
        }

        if self.selection_info_only_lazy_load() {
            let target_key = self.selection_info_lazy_target_key();
            let pending_is_stale = self.details_meta_pending.as_ref().is_some_and(|pending| {
                details_selection_pending_is_stale(
                    target_key.as_deref(),
                    pending.selection_target_key.as_deref(),
                )
            });
            if pending_is_stale {
                if let Some(pending) = self.details_meta_pending.take() {
                    pending.cancel.store(true, Ordering::Relaxed);
                }
                self.details_lazy_visible_revision =
                    self.details_lazy_visible_revision.wrapping_add(1);
                self.details_image_dims_state = LazyColumnState::NotRequested;
                ctx.request_repaint();
            } else if self.details_meta_pending.is_none()
                && self.selection_info_needs_lazy_meta_request()
                && !matches!(
                    self.details_image_dims_state,
                    LazyColumnState::NotRequested
                        | LazyColumnState::Loading { .. }
                        | LazyColumnState::Reconciling { .. }
                )
            {
                self.details_lazy_visible_revision =
                    self.details_lazy_visible_revision.wrapping_add(1);
                self.details_image_dims_state = LazyColumnState::NotRequested;
            }
        }

        self.advance_details_meta_target_plan(ctx);

        let mut disconnected = false;
        loop {
            let event = match self.details_meta_pending.as_ref() {
                Some(DetailsMetaPending {
                    phase: DetailsMetaPendingPhase::Loading { rx, .. },
                    ..
                }) => match rx.try_recv() {
                    Ok(event) => Some(event),
                    Err(mpsc::TryRecvError::Empty) => None,
                    Err(mpsc::TryRecvError::Disconnected) => {
                        disconnected = true;
                        None
                    }
                },
                Some(DetailsMetaPending {
                    phase: DetailsMetaPendingPhase::Planning(_),
                    ..
                }) => None,
                None => None,
            };
            let Some(event) = event else {
                break;
            };
            match event {
                DetailsMetaEvent::Progress {
                    generation,
                    done,
                    total,
                } if generation == self.items_generation => {
                    self.details_image_dims_state = LazyColumnState::Loading { done, total };
                    ctx.request_repaint();
                }
                DetailsMetaEvent::Item {
                    generation,
                    key,
                    meta,
                    loaded,
                } if generation == self.items_generation => {
                    self.apply_details_lazy_meta_patch(key, meta, loaded);
                    self.facet_ai_model_counts_cache = None;
                    self.facet_ai_tool_counts_cache = None;
                    ctx.request_repaint();
                }
                DetailsMetaEvent::Finished { generation, failed }
                    if generation == self.items_generation =>
                {
                    let revision_matches = self
                        .details_meta_pending
                        .as_ref()
                        .is_some_and(|p| p.visible_revision == self.details_lazy_visible_revision);
                    self.details_meta_pending = None;
                    if revision_matches {
                        if self.details_page_count_uses_visible_stages() {
                            let total = match self.details_image_dims_state {
                                LazyColumnState::Loading { total, .. } => total,
                                _ => 0,
                            };
                            self.details_image_dims_state = LazyColumnState::Reconciling {
                                done: total,
                                total,
                                failed,
                            };
                        } else {
                            self.finish_details_lazy_session(failed);
                        }
                    } else {
                        self.details_image_dims_state = LazyColumnState::NotRequested;
                    }
                    ctx.request_repaint();
                    break;
                }
                _ => {}
            }
        }

        if disconnected {
            self.details_meta_pending = None;
            if self.details_image_dims_state.is_loading() {
                self.details_image_dims_state = LazyColumnState::Cancelled;
            }
        }

        if matches!(self.details_image_dims_state, LazyColumnState::NotRequested) {
            self.start_details_meta_load(ctx);
        }
    }

    pub(crate) fn cancel_details_meta_loading(&mut self) {
        if let Some(pending) = self.details_meta_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        if self.details_lazy_columns_visible() {
            self.details_image_dims_state = LazyColumnState::Cancelled;
        } else {
            self.details_image_dims_state = LazyColumnState::Disabled;
        }
    }

    /// 表示列など、遅延メタデータの読み込み要件が変わったときに旧ジョブを無効化する。
    ///
    /// `NotRequested` へ戻すだけでは、変更前の列構成を snapshot した worker の
    /// `Finished` が同じ revision で受理され、新しい列が未取得のまま `Ready` に
    /// なり得る。cancel と受信側の破棄、revision 更新を同じ所有境界で行う。
    pub(crate) fn invalidate_details_meta_requirements(&mut self) {
        if let Some(pending) = self.details_meta_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        self.details_lazy_visible_revision = self.details_lazy_visible_revision.wrapping_add(1);
        self.details_image_dims_state = if self.details_lazy_columns_visible() {
            LazyColumnState::NotRequested
        } else {
            LazyColumnState::Disabled
        };
    }

    pub(crate) fn resume_details_meta_loading(&mut self) {
        if self.details_lazy_columns_visible() {
            self.details_image_dims_state = LazyColumnState::NotRequested;
        }
    }

    pub(crate) fn details_lazy_columns_visible(&self) -> bool {
        if self.items_are_drive_list || self.items.is_empty() {
            return false;
        }
        match self.settings.grid_view_mode {
            crate::settings::GridViewMode::Details => {
                self.details_any_lazy_columns_enabled()
                    || self.ai_model_facet_should_load()
                    || self.selection_info_lazy_target_idx().is_some()
            }
            crate::settings::GridViewMode::Thumbnail => {
                self.ai_model_facet_should_load() || self.selection_info_lazy_target_idx().is_some()
            }
        }
    }

    fn details_any_lazy_columns_enabled(&self) -> bool {
        self.settings.details_show_page_count
            || self.settings.details_show_created
            || self.settings.details_show_image_dimensions
            || self.settings.details_show_video_duration
            || self.settings.details_show_video_dimensions
            || self.settings.details_show_video_codec
    }

    fn selection_info_lazy_target_idx(&self) -> Option<usize> {
        if self.items_are_drive_list
            || self.items.is_empty()
            || (!self.settings.selection_info_display_mode.shows_tooltip()
                && !self.settings.selection_info_display_mode.shows_bottom_bar())
        {
            return None;
        }
        let idx = self.selected?;
        if idx >= self.items.len() || !self.selection_info_item_requires_lazy_meta(idx) {
            return None;
        }
        Some(idx)
    }

    fn selection_info_lazy_target_key(&self) -> Option<String> {
        let idx = self.selection_info_lazy_target_idx()?;
        self.details_lazy_cache_key(idx)
    }

    fn selection_info_needs_lazy_meta_request(&self) -> bool {
        let Some(idx) = self.selection_info_lazy_target_idx() else {
            return false;
        };
        self.details_lazy_meta_for_idx(idx)
            .map(|meta| !self.details_lazy_meta_satisfies_idx(idx, meta))
            .unwrap_or(true)
    }

    fn selection_info_only_lazy_load(&self) -> bool {
        !self.ai_model_facet_should_load()
            && match self.settings.grid_view_mode {
                crate::settings::GridViewMode::Thumbnail => true,
                crate::settings::GridViewMode::Details => !self.details_any_lazy_columns_enabled(),
            }
    }

    fn selection_info_item_requires_lazy_meta(&self, idx: usize) -> bool {
        use crate::ui_main::{DetailsColumn, selection_info_bottom_bar_shows_column};

        ((self.settings.thumb_tooltip_show_created
            || selection_info_bottom_bar_shows_column(&self.settings, DetailsColumn::Created))
            && self.details_item_supports_created_at(idx))
            || ((self.settings.thumb_tooltip_show_page_count
                || selection_info_bottom_bar_shows_column(
                    &self.settings,
                    DetailsColumn::PageCount,
                ))
                && self.details_item_supports_page_count(idx))
            || ((self.settings.thumb_tooltip_show_image_dimensions
                || selection_info_bottom_bar_shows_column(
                    &self.settings,
                    DetailsColumn::ImageDimensions,
                ))
                && self.details_item_supports_image_dims(idx))
            || match self.items.get(idx) {
                Some(GridItem::Video(_)) => {
                    self.settings.thumb_tooltip_show_video_duration
                        || selection_info_bottom_bar_shows_column(
                            &self.settings,
                            DetailsColumn::VideoDuration,
                        )
                        || self.settings.thumb_tooltip_show_video_dimensions
                        || selection_info_bottom_bar_shows_column(
                            &self.settings,
                            DetailsColumn::VideoDimensions,
                        )
                        || self.settings.thumb_tooltip_show_video_codec
                        || selection_info_bottom_bar_shows_column(
                            &self.settings,
                            DetailsColumn::VideoCodec,
                        )
                }
                Some(GridItem::Audio(_)) => {
                    self.settings.thumb_tooltip_show_video_duration
                        || selection_info_bottom_bar_shows_column(
                            &self.settings,
                            DetailsColumn::VideoDuration,
                        )
                        || self.settings.thumb_tooltip_show_video_codec
                        || selection_info_bottom_bar_shows_column(
                            &self.settings,
                            DetailsColumn::VideoCodec,
                        )
                }
                _ => false,
            }
    }

    fn lazy_load_created_for_idx(&self, idx: usize) -> bool {
        let requested = match self.settings.grid_view_mode {
            crate::settings::GridViewMode::Details => {
                self.settings.details_show_created
                    || (self.selection_info_only_lazy_load()
                        && self.selection_info_lazy_target_idx() == Some(idx)
                        && self.settings.thumb_tooltip_show_created)
            }
            crate::settings::GridViewMode::Thumbnail => {
                self.settings.thumb_tooltip_show_created
                    || crate::ui_main::selection_info_bottom_bar_shows_column(
                        &self.settings,
                        crate::ui_main::DetailsColumn::Created,
                    )
            }
        };
        requested && self.details_item_supports_created_at(idx)
    }

    fn lazy_load_page_count_for_idx(&self, idx: usize) -> bool {
        let requested = match self.settings.grid_view_mode {
            crate::settings::GridViewMode::Details => {
                self.settings.details_show_page_count
                    || (self.selection_info_only_lazy_load()
                        && self.selection_info_lazy_target_idx() == Some(idx)
                        && self.settings.thumb_tooltip_show_page_count)
            }
            crate::settings::GridViewMode::Thumbnail => {
                self.settings.thumb_tooltip_show_page_count
                    || crate::ui_main::selection_info_bottom_bar_shows_column(
                        &self.settings,
                        crate::ui_main::DetailsColumn::PageCount,
                    )
            }
        };
        requested && self.details_item_supports_page_count(idx)
    }

    fn lazy_load_image_dims_for_idx(&self, idx: usize) -> bool {
        let requested = match self.settings.grid_view_mode {
            crate::settings::GridViewMode::Details => {
                self.settings.details_show_image_dimensions
                    || (self.selection_info_only_lazy_load()
                        && self.selection_info_lazy_target_idx() == Some(idx)
                        && self.settings.thumb_tooltip_show_image_dimensions)
            }
            crate::settings::GridViewMode::Thumbnail => {
                self.settings.thumb_tooltip_show_image_dimensions
                    || crate::ui_main::selection_info_bottom_bar_shows_column(
                        &self.settings,
                        crate::ui_main::DetailsColumn::ImageDimensions,
                    )
            }
        };
        requested && self.details_item_supports_image_dims(idx)
    }

    fn lazy_load_video_meta_for_idx(&self, idx: usize) -> bool {
        let (want_duration, want_dims, want_codec) = match self.settings.grid_view_mode {
            crate::settings::GridViewMode::Details => {
                let selection_target = self.selection_info_only_lazy_load()
                    && self.selection_info_lazy_target_idx() == Some(idx);
                (
                    self.settings.details_show_video_duration
                        || (selection_target && self.settings.thumb_tooltip_show_video_duration),
                    self.settings.details_show_video_dimensions
                        || (selection_target && self.settings.thumb_tooltip_show_video_dimensions),
                    self.settings.details_show_video_codec
                        || (selection_target && self.settings.thumb_tooltip_show_video_codec),
                )
            }
            crate::settings::GridViewMode::Thumbnail => (
                self.settings.thumb_tooltip_show_video_duration
                    || crate::ui_main::selection_info_bottom_bar_shows_column(
                        &self.settings,
                        crate::ui_main::DetailsColumn::VideoDuration,
                    ),
                self.settings.thumb_tooltip_show_video_dimensions
                    || crate::ui_main::selection_info_bottom_bar_shows_column(
                        &self.settings,
                        crate::ui_main::DetailsColumn::VideoDimensions,
                    ),
                self.settings.thumb_tooltip_show_video_codec
                    || crate::ui_main::selection_info_bottom_bar_shows_column(
                        &self.settings,
                        crate::ui_main::DetailsColumn::VideoCodec,
                    ),
            ),
        };
        match self.items.get(idx) {
            Some(GridItem::Video(_)) => want_duration || want_dims || want_codec,
            // 音声は解像度を持たないので、長さ / コーデックのどちらかが要求されたときだけ
            // probe する (解像度トグルだけ ON では音声に表示できる値が無く probe が無駄)。
            Some(GridItem::Audio(_)) => want_duration || want_codec,
            _ => false,
        }
    }

    fn lazy_load_ai_metadata_for_idx(&self, idx: usize) -> bool {
        self.ai_model_facet_should_load() && self.details_item_supports_ai_metadata(idx)
    }

    pub(crate) fn request_ai_model_facet_load(&mut self) {
        if !self.ai_model_facet_requested {
            self.ai_model_facet_requested = true;
            if self.details_meta_pending.is_none() && !self.details_image_dims_state.is_loading() {
                self.details_image_dims_state = LazyColumnState::NotRequested;
            }
        }
    }

    pub(crate) fn facet_ai_filter_active(&self) -> bool {
        !self.settings.facet_filter.ai_models.is_empty()
            || !self.settings.facet_filter.ai_tools.is_empty()
    }

    fn ai_model_facet_should_load(&self) -> bool {
        self.ai_model_facet_requested || self.facet_ai_filter_active()
    }

    pub(crate) fn details_image_dims_sort_ready(&self) -> bool {
        self.details_image_dims_state.is_ready()
    }

    pub(crate) fn details_lazy_sort_ready(&self) -> bool {
        self.details_image_dims_state.is_ready()
    }

    pub(crate) fn details_created_text(&self, idx: usize) -> String {
        if !self.details_item_supports_created_at(idx) {
            return "-".to_string();
        }
        if let Some(meta) = self.details_lazy_meta_for_idx(idx) {
            if let Some(created_at) = meta.created_at {
                return format_details_timestamp(
                    created_at,
                    self.settings.details_timestamp_show_seconds,
                );
            }
            if meta.created_at_failed {
                return "-".to_string();
            }
        }
        match self.details_image_dims_state {
            LazyColumnState::Disabled => String::new(),
            LazyColumnState::Ready { .. } => "-".to_string(),
            LazyColumnState::NotRequested
            | LazyColumnState::Loading { .. }
            | LazyColumnState::Reconciling { .. }
            | LazyColumnState::Cancelled => "...".to_string(),
        }
    }

    pub(crate) fn details_page_count_text(&self, idx: usize) -> String {
        if !self.details_item_supports_page_count(idx) {
            return "-".to_string();
        }
        if let Some(meta) = self.details_lazy_meta_for_idx(idx)
            && meta.page_count_checked
        {
            return meta
                .page_count
                .map(|count| count.to_string())
                .unwrap_or_else(|| "-".to_string());
        }
        match self.details_image_dims_state {
            LazyColumnState::Disabled => String::new(),
            // Ready is stage-local for page counts: a newly scrolled-in row may still be waiting
            // for the next visible-range job. Only a checked failure is rendered as `-` above.
            LazyColumnState::Ready { .. } => "...".to_string(),
            LazyColumnState::NotRequested
            | LazyColumnState::Loading { .. }
            | LazyColumnState::Reconciling { .. }
            | LazyColumnState::Cancelled => "...".to_string(),
        }
    }

    pub(crate) fn details_page_count_sort_value(&self, idx: usize) -> Option<u64> {
        if !self.details_lazy_sort_ready() {
            return None;
        }
        self.details_lazy_meta_for_idx(idx)
            .filter(|meta| meta.page_count_checked)
            .and_then(|meta| meta.page_count)
            .map(u64::from)
    }

    pub(crate) fn details_created_sort_value(&self, idx: usize) -> Option<i64> {
        if !self.details_lazy_sort_ready() {
            return None;
        }
        self.details_lazy_meta_for_idx(idx)
            .and_then(|meta| meta.created_at)
    }

    pub(crate) fn details_image_dims_text(&self, idx: usize) -> String {
        if !self.details_item_supports_image_dims(idx) {
            return "-".to_string();
        }
        if let Some(meta) = self.details_lazy_meta_for_idx(idx) {
            if let Some((w, h)) = meta.image_dims {
                return format!("{w}x{h}");
            }
            if meta.image_dims_failed {
                return "-".to_string();
            }
        }
        match self.details_image_dims_state {
            LazyColumnState::Disabled => String::new(),
            LazyColumnState::Ready { .. } => "-".to_string(),
            LazyColumnState::NotRequested
            | LazyColumnState::Loading { .. }
            | LazyColumnState::Reconciling { .. }
            | LazyColumnState::Cancelled => "...".to_string(),
        }
    }

    pub(crate) fn details_image_dims_sort_value(&self, idx: usize) -> Option<u64> {
        if !self.details_image_dims_sort_ready() {
            return None;
        }
        self.details_lazy_meta_for_idx(idx)
            .and_then(|meta| meta.image_dims)
            .map(|(w, h)| (w as u64) * (h as u64))
    }

    pub(crate) fn details_video_duration_text(&self, idx: usize) -> String {
        // 長さは動画・音声の両方が持つ (音声も詳細ビューで長さを表示する)。
        if !matches!(
            self.items.get(idx),
            Some(GridItem::Video(_)) | Some(GridItem::Audio(_))
        ) {
            return "-".to_string();
        }
        if let Some(meta) = self.details_lazy_meta_for_idx(idx) {
            if let Some(secs) = meta.video_duration_secs {
                return format_details_duration(secs);
            }
            if meta.video_meta_failed {
                return "-".to_string();
            }
        }
        match self.details_image_dims_state {
            LazyColumnState::Disabled => String::new(),
            LazyColumnState::Ready { .. } => "-".to_string(),
            LazyColumnState::NotRequested
            | LazyColumnState::Loading { .. }
            | LazyColumnState::Reconciling { .. }
            | LazyColumnState::Cancelled => "...".to_string(),
        }
    }

    pub(crate) fn details_video_dims_text(&self, idx: usize) -> String {
        if !matches!(self.items.get(idx), Some(GridItem::Video(_))) {
            return "-".to_string();
        }
        if let Some(meta) = self.details_lazy_meta_for_idx(idx) {
            if let Some((w, h)) = meta.video_dims {
                return format!("{w}x{h}");
            }
            if meta.video_meta_failed {
                return "-".to_string();
            }
        }
        match self.details_image_dims_state {
            LazyColumnState::Disabled => String::new(),
            LazyColumnState::Ready { .. } => "-".to_string(),
            LazyColumnState::NotRequested
            | LazyColumnState::Loading { .. }
            | LazyColumnState::Reconciling { .. }
            | LazyColumnState::Cancelled => "...".to_string(),
        }
    }

    pub(crate) fn details_video_codec_text(&self, idx: usize) -> String {
        // コーデックは動画・音声の両方が持つ。
        if !matches!(
            self.items.get(idx),
            Some(GridItem::Video(_)) | Some(GridItem::Audio(_))
        ) {
            return "-".to_string();
        }
        if let Some(meta) = self.details_lazy_meta_for_idx(idx) {
            if let Some(codec) = meta.video_codec.as_ref() {
                return codec.clone();
            }
            if meta.video_meta_failed {
                return "-".to_string();
            }
        }
        match self.details_image_dims_state {
            LazyColumnState::Disabled => String::new(),
            LazyColumnState::Ready { .. } => "-".to_string(),
            LazyColumnState::NotRequested
            | LazyColumnState::Loading { .. }
            | LazyColumnState::Reconciling { .. }
            | LazyColumnState::Cancelled => "...".to_string(),
        }
    }

    pub(crate) fn details_video_duration_sort_value(&self, idx: usize) -> Option<u64> {
        if !self.details_image_dims_sort_ready() {
            return None;
        }
        self.details_lazy_meta_for_idx(idx)
            .and_then(|meta| meta.video_duration_secs)
            .filter(|secs| secs.is_finite() && *secs > 0.0)
            .map(|secs| (secs * 1000.0).round() as u64)
    }

    pub(crate) fn details_video_dims_sort_value(&self, idx: usize) -> Option<u64> {
        if !self.details_image_dims_sort_ready() {
            return None;
        }
        self.details_lazy_meta_for_idx(idx)
            .and_then(|meta| meta.video_dims)
            .map(|(w, h)| (w as u64) * (h as u64))
    }

    pub(crate) fn details_video_codec_sort_value(&self, idx: usize) -> Option<String> {
        if !self.details_image_dims_sort_ready() {
            return None;
        }
        self.details_lazy_meta_for_idx(idx)
            .and_then(|meta| meta.video_codec.clone())
    }

    fn start_details_meta_load(&mut self, ctx: &egui::Context) {
        if self.details_meta_pending.is_some() {
            return;
        }

        let generation = self.items_generation;
        let ai_facet_load = self.ai_model_facet_should_load();
        let selection_info_only = self.selection_info_only_lazy_load();
        let load_all_page_counts = self.settings.grid_view_mode
            == crate::settings::GridViewMode::Details
            && self.settings.details_sort_key == crate::settings::DetailsSortKey::PageCount;
        let visible_page_count_stage_only = self.settings.grid_view_mode
            == crate::settings::GridViewMode::Details
            && !load_all_page_counts
            && !ai_facet_load
            && !self.settings.details_show_created
            && !self.settings.details_show_image_dimensions
            && !self.settings.details_show_video_duration
            && !self.settings.details_show_video_dimensions
            && !self.settings.details_show_video_codec;
        // ページ認識規則・フォルダ用拡張子列・暗号化PDF資格情報はジョブ単位で1回だけ
        // snapshot 化する。target ごとの Vec clone / UI thread DPAPI 復号を避ける。
        let page_count_config = DetailsPageCountConfig {
            fingerprint: crate::app::folder_scan::image_page_recognition_fingerprint(
                &self.settings,
            ),
            image_folder_options: Some(crate::app::folder_scan::image_folder_page_count_options(
                &self.settings,
            )),
            pdf_passwords: self.pdf_passwords.clone(),
        };
        let (order, visible_near) = if selection_info_only {
            let order: Vec<usize> = self.selection_info_lazy_target_idx().into_iter().collect();
            let visible_near: HashSet<usize> = order.iter().copied().collect();
            (
                DetailsMetaScanOrder::Explicit {
                    indices: order,
                    cursor: 0,
                },
                visible_near,
            )
        } else if visible_page_count_stage_only {
            let mut order = self.details_tag_prewarm_indices.to_vec();
            order.sort_unstable();
            let visible_near: HashSet<usize> = order.iter().copied().collect();
            (
                DetailsMetaScanOrder::Explicit {
                    indices: order,
                    cursor: 0,
                },
                visible_near,
            )
        } else {
            (
                DetailsMetaScanOrder::CurrentGrid {
                    cursor: 0,
                    len: self.current_grid_order().len(),
                    order_revision: self.details_order_revision,
                },
                self.details_tag_prewarm_indices.iter().copied().collect(),
            )
        };
        let cancel = Arc::new(AtomicBool::new(false));
        self.details_meta_pending = Some(DetailsMetaPending {
            visible_revision: self.details_lazy_visible_revision,
            selection_target_key: selection_info_only
                .then(|| self.selection_info_lazy_target_key())
                .flatten(),
            normal_target_keys: visible_near
                .iter()
                .filter_map(|&idx| self.details_lazy_cache_key(idx))
                .collect(),
            cancel,
            phase: DetailsMetaPendingPhase::Planning(DetailsMetaTargetPlan {
                generation,
                order,
                visible_near,
                load_all_page_counts,
                ai_facet_load,
                page_count_config,
                visible_targets: Vec::new(),
                background_targets: Vec::new(),
                cached_done: 0,
                cached_failed: 0,
                total: 0,
                scan_slices: 0,
                scan_started_at: crate::perf::is_enabled().then(std::time::Instant::now),
            }),
        });
        self.advance_details_meta_target_plan(ctx);
    }

    /// 全件対象の遅延列でも target 構築を 1 frame の予算内で進める。
    /// Explicit は selection / 可視 page-count の小集合なので従来どおり同一 frame で完了する。
    fn advance_details_meta_target_plan(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.details_meta_pending.take() else {
            return;
        };
        if !matches!(&pending.phase, DetailsMetaPendingPhase::Planning(_)) {
            self.details_meta_pending = Some(pending);
            return;
        }
        let DetailsMetaPending {
            visible_revision,
            selection_target_key,
            normal_target_keys,
            cancel,
            phase,
        } = pending;
        let DetailsMetaPendingPhase::Planning(mut plan) = phase else {
            unreachable!();
        };

        let order_stale = matches!(
            plan.order,
            DetailsMetaScanOrder::CurrentGrid { order_revision, .. }
                if order_revision != self.details_order_revision
        );
        if plan.generation != self.items_generation
            || visible_revision != self.details_lazy_visible_revision
            || order_stale
        {
            cancel.store(true, Ordering::Relaxed);
            self.details_image_dims_state = LazyColumnState::NotRequested;
            ctx.request_repaint();
            return;
        }

        let scan_budget = if plan.order.is_incremental() {
            DETAILS_META_TARGET_SCAN_BUDGET_PER_FRAME
        } else {
            usize::MAX
        };
        let slice_t0 = crate::perf::is_enabled().then(std::time::Instant::now);
        let slice_start = plan.order.scanned();
        for _ in 0..scan_budget {
            let idx = match &mut plan.order {
                DetailsMetaScanOrder::Explicit { indices, cursor } => {
                    let Some(idx) = indices.get(*cursor).copied() else {
                        break;
                    };
                    *cursor += 1;
                    idx
                }
                DetailsMetaScanOrder::CurrentGrid { cursor, len, .. } => {
                    if *cursor >= *len {
                        break;
                    }
                    let Some(idx) = self.current_grid_order().get(*cursor).copied() else {
                        break;
                    };
                    *cursor += 1;
                    idx
                }
            };

            if !self.details_item_requires_lazy_meta(idx) {
                continue;
            }
            if let Some(meta) = self.details_lazy_meta_for_idx(idx)
                && self.details_lazy_meta_satisfies_idx(idx, meta)
            {
                plan.total += 1;
                plan.cached_done += 1;
                plan.cached_failed += usize::from(
                    meta.page_count_failed
                        || meta.image_dims_failed
                        || meta.video_meta_failed
                        || meta.created_at_failed,
                );
                continue;
            }
            if let Some(target) = self.details_meta_target_for_idx(
                idx,
                &plan.visible_near,
                plan.load_all_page_counts || plan.visible_near.contains(&idx),
            ) {
                plan.total += 1;
                if target.priority >= crate::io_semaphore::IoPriority::Normal {
                    plan.visible_targets.push(target);
                } else {
                    plan.background_targets.push(target);
                }
            }
        }
        plan.scan_slices += 1;
        let slice_items = plan.order.scanned().saturating_sub(slice_start);
        let scan_complete = plan.order.is_complete();
        if let Some(t0) = slice_t0 {
            crate::perf::event(
                "details_meta",
                "target_scan_slice",
                None,
                plan.generation,
                &[
                    ("items", serde_json::Value::from(slice_items)),
                    ("scanned", serde_json::Value::from(plan.order.scanned())),
                    ("order_items", serde_json::Value::from(plan.order.len())),
                    ("slices", serde_json::Value::from(plan.scan_slices)),
                    ("complete", serde_json::Value::from(scan_complete)),
                    (
                        "ms",
                        serde_json::Value::from(t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                ],
            );
        }

        if !scan_complete {
            self.details_image_dims_state = LazyColumnState::Loading {
                done: plan.cached_done,
                total: plan.total,
            };
            self.details_meta_pending = Some(DetailsMetaPending {
                visible_revision,
                selection_target_key,
                normal_target_keys,
                cancel,
                phase: DetailsMetaPendingPhase::Planning(plan),
            });
            ctx.request_repaint();
            return;
        }

        self.launch_details_meta_worker(ctx, visible_revision, selection_target_key, cancel, plan);
    }

    fn launch_details_meta_worker(
        &mut self,
        ctx: &egui::Context,
        visible_revision: u64,
        selection_target_key: Option<String>,
        cancel: Arc<AtomicBool>,
        plan: DetailsMetaTargetPlan,
    ) {
        let target_count = plan.visible_targets.len() + plan.background_targets.len();
        if plan.total == 0 || target_count == 0 {
            self.finish_details_lazy_session(plan.cached_failed);
            return;
        }

        // target plan 中に scroll した場合も、起動時点の可視範囲を worker の先頭へ差し込む。
        // 元の background target は idx bitmap で重複排除され、全件走査 cursor は巻き戻さない。
        let current_visible_order: Vec<usize> = self
            .details_tag_prewarm_indices
            .iter()
            .copied()
            .filter(|&idx| {
                self.details_item_requires_lazy_meta(idx)
                    && self
                        .details_lazy_meta_for_idx(idx)
                        .is_none_or(|meta| !self.details_lazy_meta_satisfies_idx(idx, meta))
            })
            .collect();
        let current_visible_indices: HashSet<usize> =
            current_visible_order.iter().copied().collect();
        let initial_priority_targets: Vec<DetailsMetaTarget> = current_visible_order
            .iter()
            .copied()
            .filter_map(|idx| self.details_meta_target_for_idx(idx, &current_visible_indices, true))
            .collect();
        let normal_target_keys = initial_priority_targets
            .iter()
            .map(|target| target.key.clone())
            .collect();

        let normal_targets = plan.visible_targets.len();
        let low_targets = plan.background_targets.len();
        let all_targets = plan
            .visible_targets
            .iter()
            .chain(plan.background_targets.iter());
        let ai_targets = all_targets
            .clone()
            .filter(|target| target.load_ai_metadata)
            .count();
        let created_targets = all_targets
            .clone()
            .filter(|target| target.load_created_at)
            .count();
        let page_count_targets = all_targets
            .clone()
            .filter(|target| target.load_page_count)
            .count();
        let image_dim_targets = all_targets
            .clone()
            .filter(|target| target.load_image_dims)
            .count();
        let video_meta_targets = all_targets.filter(|target| target.load_video_meta).count();

        self.details_image_dims_state = LazyColumnState::Loading {
            done: plan.cached_done,
            total: plan.total,
        };
        let cancel_w = Arc::clone(&cancel);
        let (tx, rx) = mpsc::channel();
        let (priority_tx, priority_rx) = mpsc::channel();
        if !initial_priority_targets.is_empty() {
            let _ = priority_tx.send(initial_priority_targets);
        }
        let cache_dir = crate::catalog::default_cache_dir();
        let io_sem = self
            .indexer_manager
            .as_ref()
            .map(|mgr| mgr.io_sem())
            .unwrap_or_else(|| {
                Arc::new(crate::io_semaphore::GlobalIoSemaphore::new(
                    self.settings.indexer_speed_profile.io_permits().max(1),
                ))
            });

        if crate::perf::is_enabled() {
            crate::perf::event(
                "details_meta",
                "target_scan_done",
                None,
                plan.generation,
                &[
                    ("items", serde_json::Value::from(plan.order.scanned())),
                    ("slices", serde_json::Value::from(plan.scan_slices)),
                    (
                        "ms",
                        serde_json::Value::from(
                            plan.scan_started_at
                                .map(|t0| t0.elapsed().as_secs_f64() * 1000.0)
                                .unwrap_or(0.0),
                        ),
                    ),
                ],
            );
            crate::perf::event(
                "details_meta",
                "load_start",
                None,
                plan.generation,
                &[
                    ("targets", serde_json::Value::from(target_count)),
                    ("total", serde_json::Value::from(plan.total)),
                    ("cached_done", serde_json::Value::from(plan.cached_done)),
                    ("cached_failed", serde_json::Value::from(plan.cached_failed)),
                    ("normal_targets", serde_json::Value::from(normal_targets)),
                    ("low_targets", serde_json::Value::from(low_targets)),
                    ("ai_targets", serde_json::Value::from(ai_targets)),
                    ("created_targets", serde_json::Value::from(created_targets)),
                    (
                        "page_count_targets",
                        serde_json::Value::from(page_count_targets),
                    ),
                    (
                        "image_dim_targets",
                        serde_json::Value::from(image_dim_targets),
                    ),
                    (
                        "video_meta_targets",
                        serde_json::Value::from(video_meta_targets),
                    ),
                    ("ai_facet_load", serde_json::Value::from(plan.ai_facet_load)),
                    (
                        "grid_mode",
                        serde_json::Value::from(match self.settings.grid_view_mode {
                            crate::settings::GridViewMode::Thumbnail => "thumbnail",
                            crate::settings::GridViewMode::Details => "details",
                        }),
                    ),
                ],
            );
        }

        std::thread::Builder::new()
            .name("details-meta-load".to_string())
            .spawn(move || {
                run_details_meta_load(
                    plan.generation,
                    plan.visible_targets,
                    plan.background_targets,
                    plan.cached_done,
                    plan.cached_failed,
                    plan.total,
                    cache_dir,
                    io_sem,
                    cancel_w,
                    tx,
                    priority_rx,
                    plan.page_count_config,
                );
            })
            .ok();

        self.details_meta_pending = Some(DetailsMetaPending {
            visible_revision,
            selection_target_key,
            normal_target_keys,
            cancel,
            phase: DetailsMetaPendingPhase::Loading { rx, priority_tx },
        });
        ctx.request_repaint();
    }

    fn details_lazy_meta_for_idx(&self, idx: usize) -> Option<&DetailsLazyMeta> {
        let key = self.details_lazy_cache_key(idx)?;
        let source = self.image_metas.get(idx).copied().flatten();
        self.details_lazy_meta
            .get(&key)
            .filter(|meta| meta.matches_source(source))
    }

    /// 保存済み PDF パスワードの変更後に、同じ起動中の古いページ数結果を破棄する。
    ///
    /// 一覧のメタデータ取得が並行中の場合は、変更前の認証状態で完了した結果が
    /// 再挿入されないようジョブ全体をキャンセルし、必要な列だけ次フレームで再開する。
    fn invalidate_details_pdf_page_count(&mut self, pdf_path: &Path) {
        if self
            .details_lazy_meta
            .remove(&crate::adjustment_db::normalize_path(pdf_path))
            .is_some()
        {
            DetailsCellContentRevisions::bump(&mut self.details_cell_content_revisions.page_count);
        }
        self.invalidate_details_meta_requirements();
    }

    fn prune_details_lazy_meta_cache(&mut self) {
        if self.details_lazy_meta.len() <= DETAILS_LAZY_META_STALE_CAP {
            return;
        }
        let current_keys: std::collections::HashSet<String> = (0..self.items.len())
            .filter_map(|idx| self.details_lazy_cache_key(idx))
            .collect();
        if current_keys.is_empty() {
            self.details_lazy_meta.clear();
            return;
        }
        self.details_lazy_meta
            .retain(|key, _| current_keys.contains(key));
    }

    fn details_lazy_meta_satisfies_idx(&self, idx: usize, meta: &DetailsLazyMeta) -> bool {
        if self.lazy_load_page_count_for_idx(idx)
            && !self.details_page_count_meta_satisfies_idx(idx, meta)
        {
            return false;
        }
        if self.lazy_load_created_for_idx(idx)
            && meta.created_at.is_none()
            && !meta.created_at_failed
        {
            return false;
        }
        if self.lazy_load_ai_metadata_for_idx(idx) && !meta.ai_metadata_checked {
            return false;
        }
        if self.lazy_load_image_dims_for_idx(idx)
            && meta.image_dims.is_none()
            && !meta.image_dims_failed
        {
            return false;
        }
        if self.lazy_load_video_meta_for_idx(idx)
            && meta.video_duration_secs.is_none()
            && meta.video_dims.is_none()
            && meta.video_codec.is_none()
            && !meta.video_meta_failed
        {
            return false;
        }
        true
    }

    fn details_page_count_meta_satisfies_idx(&self, idx: usize, meta: &DetailsLazyMeta) -> bool {
        if !meta.page_count_checked {
            return false;
        }
        if let Some(GridItem::PdfFile(path)) = self.items.get(idx) {
            return meta.page_count_pdf_password_revision
                == Some(self.pdf_passwords.credential_revision(path));
        }
        true
    }

    fn details_item_supports_created_at(&self, idx: usize) -> bool {
        self.items
            .get(idx)
            .and_then(details_created_time_path)
            .is_some()
    }

    pub(crate) fn details_item_supports_page_count(&self, idx: usize) -> bool {
        match self.items.get(idx) {
            Some(GridItem::ZipFile(_)) | Some(GridItem::PdfFile(_)) => true,
            Some(GridItem::Folder(_)) => true,
            Some(GridItem::ZipDir {
                is_archive: true, ..
            }) => true,
            Some(GridItem::ConvertibleArchive {
                format: crate::archive_converter::ArchiveFormat::Rar,
                ..
            }) => true,
            _ => false,
        }
    }

    fn details_item_supports_image_dims(&self, idx: usize) -> bool {
        matches!(
            self.items.get(idx),
            Some(GridItem::Image(_))
                | Some(GridItem::ZipImage { .. })
                | Some(GridItem::PdfPage { .. })
        )
    }

    fn details_item_supports_ai_metadata(&self, idx: usize) -> bool {
        match self.items.get(idx) {
            Some(GridItem::Image(path)) => crate::png_metadata::metadata_path_may_contain_ai(path),
            Some(GridItem::ZipImage { entry_name, .. }) => {
                crate::png_metadata::metadata_path_may_contain_ai(std::path::Path::new(entry_name))
            }
            _ => false,
        }
    }

    fn details_item_requires_lazy_meta(&self, idx: usize) -> bool {
        self.lazy_load_page_count_for_idx(idx)
            || self.lazy_load_created_for_idx(idx)
            || self.lazy_load_ai_metadata_for_idx(idx)
            || self.lazy_load_image_dims_for_idx(idx)
            || self.lazy_load_video_meta_for_idx(idx)
    }

    fn details_meta_target_for_idx(
        &self,
        idx: usize,
        visible_near: &std::collections::HashSet<usize>,
        allow_page_count: bool,
    ) -> Option<DetailsMetaTarget> {
        let item = self.items.get(idx)?.clone();
        let key = self.details_lazy_cache_key(idx)?;
        let (source_mtime, source_size) = self
            .image_metas
            .get(idx)
            .copied()
            .flatten()
            .unwrap_or((0, 0));
        let (catalog_folder, catalog_key) = self.details_catalog_lookup_for_item(&item);
        let priority = if visible_near.contains(&idx) {
            crate::io_semaphore::IoPriority::Normal
        } else {
            crate::io_semaphore::IoPriority::Low
        };
        let existing_meta = self.details_lazy_meta_for_idx(idx);
        let load_image_dims = self.lazy_load_image_dims_for_idx(idx)
            && existing_meta
                .is_none_or(|meta| meta.image_dims.is_none() && !meta.image_dims_failed);
        let load_video_meta = self.lazy_load_video_meta_for_idx(idx)
            && existing_meta.is_none_or(|meta| {
                meta.video_duration_secs.is_none()
                    && meta.video_dims.is_none()
                    && meta.video_codec.is_none()
                    && !meta.video_meta_failed
            });
        let load_page_count = allow_page_count
            && self.lazy_load_page_count_for_idx(idx)
            && existing_meta
                .is_none_or(|meta| !self.details_page_count_meta_satisfies_idx(idx, meta));
        let load_created_at = self.lazy_load_created_for_idx(idx)
            && existing_meta
                .is_none_or(|meta| meta.created_at.is_none() && !meta.created_at_failed);
        let load_ai_metadata = self.lazy_load_ai_metadata_for_idx(idx)
            && existing_meta.is_none_or(|meta| !meta.ai_metadata_checked);
        let pdf_password_revision = if load_page_count {
            match &item {
                GridItem::PdfFile(path) => Some(self.pdf_passwords.credential_revision(path)),
                _ => None,
            }
        } else {
            None
        };
        let warm_page_count = if load_page_count {
            match &item {
                GridItem::ZipDir {
                    zip_path,
                    dir_prefix,
                    ..
                } => self
                    .zip_nav
                    .as_ref()
                    .filter(|nav| nav.tree.zip_path == *zip_path)
                    .and_then(|nav| nav.tree.page_count_for_prefix_str(dir_prefix)),
                _ => None,
            }
        } else {
            None
        };
        if !load_page_count
            && !load_created_at
            && !load_ai_metadata
            && !load_image_dims
            && !load_video_meta
        {
            return None;
        }
        Some(DetailsMetaTarget {
            idx,
            key,
            item,
            relative_page_provenance: self.relative_page_provenance_for_idx(idx),
            source_mtime,
            source_size,
            catalog_folder,
            catalog_key,
            warm_image_dims: self.details_warm_image_dims(idx),
            warm_page_count,
            pdf_password_revision,
            load_page_count,
            load_created_at,
            load_ai_metadata,
            load_image_dims,
            load_video_meta,
            priority,
        })
    }

    fn details_catalog_lookup_for_item(
        &self,
        item: &GridItem,
    ) -> (Option<PathBuf>, Option<String>) {
        match item {
            GridItem::Image(path) => {
                if self.use_full_path_cache_keys() {
                    (
                        self.current_folder.clone(),
                        Some(image_full_path_cache_key(path)),
                    )
                } else {
                    (
                        path.parent().map(Path::to_path_buf),
                        path.file_name()
                            .and_then(|n| n.to_str())
                            .map(str::to_string),
                    )
                }
            }
            GridItem::ZipImage {
                zip_path,
                entry_name,
            } => (Some(zip_path.clone()), Some(entry_name.clone())),
            GridItem::PdfPage {
                pdf_path, page_num, ..
            } => (
                Some(pdf_path.clone()),
                Some(crate::grid_item::pdf_page_cache_key(*page_num)),
            ),
            GridItem::Folder(path)
            | GridItem::ZipFile(path)
            | GridItem::PdfFile(path)
            | GridItem::ConvertibleArchive { path, .. } => (
                path.parent().map(Path::to_path_buf),
                path.file_name()
                    .and_then(|name| name.to_str())
                    .map(str::to_string),
            ),
            _ => (None, None),
        }
    }

    fn details_warm_image_dims(&self, idx: usize) -> Option<(u32, u32)> {
        if let Some(GridItem::PdfPage {
            content_type: Some(crate::pdf_loader::PdfPageContentType::Raster { w, h }),
            ..
        }) = self.items.get(idx)
            && *w > 0
            && *h > 0
        {
            return Some((*w, *h));
        }
        match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Static {
                source_dims: Some([w, h]),
                ..
            }) if *w > 0 && *h > 0 => Some((*w as u32, *h as u32)),
            _ => None,
        }
    }

    /// 現在の main surface が通常フォルダで、走査キャッシュも同じ場所なら内訳を返す。
    pub(crate) fn current_normal_folder_omitted_counts(
        &self,
    ) -> Option<folder_scan::OmittedFolderEntryCounts> {
        if self.navigation_scope.is_detached_physical()
            || self.search_filter.is_some()
            || self.search_pending.is_some()
            || self.stack_mode_requested
            || !matches!(
                self.top_level_grid_view.surface(),
                top_level_grid_view::TopLevelGridSurface::Folder
            )
        {
            // サブ展開・スマートフォルダ・検索結果・スタックは後追い範囲。物理フォルダの
            // scan/filter を共有していても、素の通常フォルダ一覧以外にはチップを出さない。
            return None;
        }
        let current = self.current_folder.as_deref()?;
        self.normal_folder_omitted_entries
            .as_ref()
            .filter(|entries| crate::folder_tree::path_eq(&entries.folder, current))
            .map(|entries| entries.counts)
    }

    /// 同名ファイルフィルタを適用し、実際に一覧から畳んだ合計件数を返す。
    fn apply_duplicate_filters(
        &mut self,
        folders: &mut Vec<GridItem>,
        folder_metas: &mut Vec<Option<(i64, i64)>>,
        all_media: &mut Vec<(PathBuf, crate::app::folder_scan::ScanMediaKind, i64, i64)>,
    ) -> usize {
        let mut omitted = 0usize;
        if self.settings.skip_zip_if_folder_exists {
            omitted = omitted.saturating_add(Self::filter_virtual_folder_duplicates(
                folders,
                folder_metas,
            ));
        }
        if self.settings.skip_archive_if_zip_exists {
            omitted = omitted.saturating_add(Self::filter_convertible_archive_duplicates(
                folders,
                folder_metas,
            ));
        }
        if self.settings.skip_image_if_video_exists {
            omitted = omitted.saturating_add(self.filter_video_image_duplicates(all_media));
        }
        if self.settings.skip_duplicate_images {
            omitted = omitted.saturating_add(crate::app::folder_scan::filter_image_ext_duplicates(
                all_media,
                &self.settings.image_ext_priority,
            ));
        }
        omitted
    }

    /// ZIP/PDF + フォルダの重複: 同名フォルダがあれば ZIP/PDF エントリをスキップ。
    /// folders と folder_metas は同じ順序で対応しているため、同期して削除する。
    ///
    /// 仮想フォルダ (ZIP/PDF) 判定は [`folder_tree::sorted_subdirs`] の Ctrl+↑↓ 用
    /// フィルタと揃える必要がある。片側だけ PDF を除外すると、グリッドに表示されている
    /// PDF が folder tree 側では sibling 扱いされず Ctrl+↑↓ の位置検索が失敗する。
    fn filter_virtual_folder_duplicates(
        folders: &mut Vec<GridItem>,
        folder_metas: &mut Vec<Option<(i64, i64)>>,
    ) -> usize {
        crate::app::folder_scan::filter_virtual_folder_duplicates(folders, folder_metas)
    }

    /// Prefer native ZIP/CBZ over a same-stem RAR/7z/LZH archive.
    fn filter_convertible_archive_duplicates(
        folders: &mut Vec<GridItem>,
        folder_metas: &mut Vec<Option<(i64, i64)>>,
    ) -> usize {
        crate::app::folder_scan::filter_convertible_archive_duplicates(folders, folder_metas)
    }

    /// 動画 + 画像の重複: 同名の動画があれば画像をスキップし、
    /// 画像ファイルを動画のサムネイルソースとして記録する。
    ///
    /// Phase 5.3: `Settings.video_thumb_use_sidecar_image` で有効/無効を切替可能に。
    /// OFF のときは override を記録しない (= グリッドではシェル既定サムネのみ採用)
    /// が、画像ファイルの listing からの除外は維持する (= 同名画像が動画と並んで二重
    /// 表示されるのは望ましくないため)。
    fn filter_video_image_duplicates(
        &mut self,
        all_media: &mut Vec<(PathBuf, crate::app::folder_scan::ScanMediaKind, i64, i64)>,
    ) -> usize {
        let use_sidecar = self.settings.video_thumb_use_sidecar_image;
        let filtered =
            crate::app::folder_scan::filter_video_image_duplicates(all_media, use_sidecar);
        for (video, image) in filtered.sidecars {
            self.video_thumb_overrides.insert(stem_lower(&video), image);
        }
        filtered.omitted
    }

    /// `search_filter` とレーティングフィルタに基づいて `visible_indices` を再計算する。
    /// 両者は AND 結合。レーティングフィルタはレーティング対象に適用される:
    /// ページ単位 (Image / ZipImage / PdfPage) + コンテナ (Folder / ZipFile / PdfFile) の両方。
    /// 動画 / セパレータ / ConvertibleArchive などは常に通す。
    pub(crate) fn rebuild_visible_indices(&mut self) {
        self.rebuild_visible_indices_impl(true);
    }

    /// DB / bookmarkなど外部snapshotの更新で、現在mount中のcontext-owned表示集合だけを
    /// 再計算する。`facet_filter_scope`とsuppressionはApp-globalなので、detached/pausedを
    /// 一時mountする経路ではnavigation扱いのscope同期を行わない。
    fn rebuild_visible_indices_preserving_facet_scope(&mut self) {
        self.rebuild_visible_indices_impl(false);
    }

    fn rebuild_visible_indices_impl(&mut self, sync_facet_scope: bool) {
        if self.navigation_scope.is_detached_physical() {
            // Detached physical viewers intentionally ignore every App-global
            // display filter. Their raw order is still constrained to the
            // physical folder/container identity owned by this bundle because
            // a virtual-list backing snapshot may contain several parents.
            self.visible_indices = self
                .current_folder
                .as_deref()
                .map(|physical_scope| {
                    self.items
                        .iter()
                        .enumerate()
                        .filter_map(|(idx, item)| {
                            item_belongs_to_detached_physical_scope(item, physical_scope)
                                .then_some(idx)
                        })
                        .collect()
                })
                .unwrap_or_default();
            self.details_thumb_suppression_applied = false;
            self.details_order.clear();
            self.cached_nav_indices = None;
            self.cached_fs_seek_info = None;
            if !self.checked.is_empty() {
                let vi = &self.visible_indices;
                self.checked.retain(|idx| vi.binary_search(idx).is_ok());
            }
            self.ensure_selected_visible_or_first();
            return;
        }
        self.ensure_bookmark_presence_loaded();
        let color_filter_t0 = if self.color_filter.enabled && crate::perf::is_enabled() {
            Some(std::time::Instant::now())
        } else {
            None
        };
        let facet_name_filter_t0 = (crate::perf::is_enabled()
            && !self.facet_name_tokens.is_empty()
            && self.facet_name_cache_generation == Some(self.items_generation)
            && self.facet_name_cache.len() == self.items.len())
        .then(std::time::Instant::now);
        // 表示集合が変わると facet 件数も変わる (ui_main::facet_*_counts)。
        self.facet_tag_counts_cache = None;
        self.facet_place_counts_cache = None;
        self.facet_ai_model_counts_cache = None;
        self.facet_ai_tool_counts_cache = None;
        if sync_facet_scope {
            self.sync_facet_filter_scope();
        }
        let search_filter = self.search_filter.clone();
        // Codex P1-2 fix: effective_rating_filter() で ★一時解除中は [true;6] が返るので
        // 表示は全 ON 相当になる。旧版は settings.rating_filter を書き換えて同じ効果を
        // 出していたが、ユーザー設定が壊れる hidden mode だった。
        let rating_filter = self.effective_rating_filter();
        // すべてのバケットが true ならレーティングフィルタは無効 (常に通す)
        let rating_filter_active = !self.items_are_drive_list
            && !self.items_are_reading_history_view
            && !self.items_are_rating_view
            && !rating_filter.iter().all(|&b| b);
        let color_scope_signature =
            if self.color_filter.enabled && self.color_filter_available_in_current_view() {
                self.color_current_scope_signature()
            } else {
                None
            };

        let n = self.items.len();
        let mut result = Vec::with_capacity(n);
        for i in 0..n {
            if let Some(ref f) = search_filter {
                if !f.contains(&i) {
                    continue;
                }
            }
            if rating_filter_active {
                let stars = self.get_rating(i);
                if let Some(item) = self.items.get(i) {
                    if !passes_rating_filter(item, stars, &rating_filter) {
                        continue;
                    }
                }
            }
            if !self.bookmark_view_matches_filter(i) || !self.reading_history_view_matches_filter(i)
            {
                continue;
            }
            if !self.passes_facet_filter(i, None) {
                continue;
            }
            if !self.passes_color_filter_for_scope(i, color_scope_signature) {
                continue;
            }
            result.push(i);
        }
        self.visible_indices = result;
        if let Some(t0) = facet_name_filter_t0 {
            crate::perf::event(
                "facet_name",
                "filter_apply",
                None,
                0,
                &[
                    ("items", serde_json::Value::from(n)),
                    (
                        "visible",
                        serde_json::Value::from(self.visible_indices.len()),
                    ),
                    (
                        "tokens",
                        serde_json::Value::from(self.facet_name_tokens.len()),
                    ),
                    (
                        "ms",
                        serde_json::Value::from(t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                ],
            );
        }
        if let (Some(t0), Some(scope_signature)) = (color_filter_t0, color_scope_signature) {
            crate::perf::event(
                "color",
                "filter_apply",
                None,
                0,
                &[
                    ("items", serde_json::Value::from(n)),
                    (
                        "visible",
                        serde_json::Value::from(self.visible_indices.len()),
                    ),
                    (
                        "applied",
                        serde_json::Value::from(
                            self.color_filter.applied_scope_signature == Some(scope_signature),
                        ),
                    ),
                    (
                        "ms",
                        serde_json::Value::from(t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                ],
            );
        }
        self.details_thumb_suppression_applied = false;
        if self.details_any_lazy_columns_enabled() || self.ai_model_facet_should_load() {
            self.details_lazy_visible_revision = self.details_lazy_visible_revision.wrapping_add(1);
            if self.details_meta_pending.is_none() && !self.details_image_dims_state.is_ready() {
                self.details_image_dims_state = LazyColumnState::NotRequested;
            }
        }
        if self.settings.grid_view_mode == crate::settings::GridViewMode::Details {
            self.rebuild_details_order();
        } else {
            self.details_order.clear();
        }
        self.cached_nav_indices = None;
        self.cached_fs_seek_info = None;
        // WYSIWYG 原則: 非表示になったアイテムは checked / selected の対象から外す。
        // これで `handle_grid_keys` の `position().unwrap_or(0)` 起因の
        // 「F1 で非表示にした後、矢印キーで一覧先頭に飛ぶ」挙動も解消される。
        if !self.checked.is_empty() {
            let vi = &self.visible_indices;
            self.checked.retain(|idx| vi.binary_search(idx).is_ok());
        }
        self.ensure_selected_visible_or_first();
    }

    fn sync_facet_filter_scope(&mut self) {
        let scope = self.effective_folder();
        if self.facet_filter_scope == scope {
            return;
        }
        let previous_scope = self.facet_filter_scope.clone();
        self.facet_filter_scope = scope;
        self.update_facet_filter_suppression_for_scope_change(previous_scope);
    }

    fn update_facet_filter_suppression_for_scope_change(
        &mut self,
        previous_scope: Option<PathBuf>,
    ) {
        let current = self.facet_filter_scope.clone();
        if previous_scope != current {
            self.clear_place_facet_for_scope_change();
        }
        self.restore_facet_filter_suppression_for_path(current.as_deref());

        if !self.facet_filter_active() {
            return;
        }
        let (Some(prev), Some(cur)) = (previous_scope.as_ref(), current.as_ref()) else {
            return;
        };
        if prev != cur && path_in_subtree_ci(cur, prev) {
            self.suppress_current_facet_filter_at(
                cur.clone(),
                "親の絞り込みを退避しました (戻ると復元)".to_string(),
            );
        }
    }

    fn clear_place_facet_for_scope_change(&mut self) {
        self.settings.facet_filter.place_keys.clear();
        for suppression in &mut self.facet_filter_suppression_stack {
            suppression.saved_filter.place_keys.clear();
        }
        self.facet_filter_suppression_stack
            .retain(|suppression| suppression.saved_filter.is_active());
    }

    pub(crate) fn restore_facet_filter_suppression_for_path(&mut self, current: Option<&Path>) {
        while let Some(top) = self.facet_filter_suppression_stack.last() {
            if current.is_some_and(|cur| path_in_subtree_ci(cur, &top.anchor)) {
                break;
            }
            self.restore_facet_filter_suppression();
        }
    }

    pub(crate) fn facet_candidate_indices(&mut self, ignore: FacetField) -> Vec<usize> {
        let search_filter = self.search_filter.clone();
        let rating_filter = self.effective_rating_filter();
        let rating_filter_active = !self.items_are_drive_list
            && !self.items_are_reading_history_view
            && !self.items_are_rating_view
            && !rating_filter.iter().all(|&b| b);
        let mut out = Vec::new();
        for i in 0..self.items.len() {
            if let Some(ref f) = search_filter {
                if !f.contains(&i) {
                    continue;
                }
            }
            if rating_filter_active && ignore != FacetField::Rating {
                let stars = self.get_rating(i);
                if let Some(item) = self.items.get(i) {
                    if !passes_rating_filter(item, stars, &rating_filter) {
                        continue;
                    }
                }
            }
            if !self.bookmark_view_matches_filter(i) || !self.reading_history_view_matches_filter(i)
            {
                continue;
            }
            if self.passes_facet_filter(i, Some(ignore)) {
                out.push(i);
            }
        }
        out
    }

    pub(crate) fn facet_item_kind(&self, idx: usize) -> Option<crate::settings::FacetItemKind> {
        self.items.get(idx).map(facet_kind_for_item)
    }

    pub(crate) fn bookmark_view_matches_filter(&self, idx: usize) -> bool {
        if !self.items_are_bookmark_view {
            return true;
        }
        let Some(row) = self.bookmark_browser_rows.get(idx) else {
            return false;
        };
        if self.bookmark_media_filter != crate::bookmark_browser::MediaFilter::All
            && row.media_filter() != self.bookmark_media_filter
        {
            return false;
        }
        match &row.source {
            crate::bookmark_browser::BookmarkRowSource::Book(bookmark) => self
                .bookmark_book_kind_filter
                .matches(bookmark.container_kind),
            _ => true,
        }
    }

    pub(crate) fn reading_history_view_matches_filter(&self, idx: usize) -> bool {
        use crate::bookmark_browser::{BookKindFilter, MediaFilter};
        use crate::reading_history_db::ReadingHistoryKind;

        if !self.items_are_reading_history_view {
            return true;
        }
        let Some(entry) = self
            .items
            .get(idx)
            .and_then(reading_history_key_for_item)
            .and_then(|key| self.reading_history_rows.get(&key))
        else {
            return false;
        };
        let media = match entry.kind {
            ReadingHistoryKind::Video => MediaFilter::Video,
            ReadingHistoryKind::Audio => MediaFilter::Audio,
            ReadingHistoryKind::Folder
            | ReadingHistoryKind::Zip
            | ReadingHistoryKind::Pdf
            | ReadingHistoryKind::Archive => MediaFilter::Book,
        };
        if self.reading_history_media_filter != MediaFilter::All
            && self.reading_history_media_filter != media
        {
            return false;
        }
        if media != MediaFilter::Book {
            return true;
        }
        match self.reading_history_book_kind_filter {
            BookKindFilter::All => true,
            BookKindFilter::ImageFolder => entry.kind == ReadingHistoryKind::Folder,
            BookKindFilter::Zip => entry.kind == ReadingHistoryKind::Zip,
            BookKindFilter::Pdf => entry.kind == ReadingHistoryKind::Pdf,
            BookKindFilter::OtherArchive => entry.kind == ReadingHistoryKind::Archive,
        }
    }

    pub(crate) fn facet_item_ext(&self, idx: usize) -> String {
        self.items
            .get(idx)
            .map(facet_ext_for_item)
            .unwrap_or_default()
    }

    pub(crate) fn facet_place_label_for_key(&self, key: &str) -> String {
        for (idx, _item) in self.items.iter().enumerate() {
            let Some(path) = self.facet_place_path_for_idx(idx) else {
                continue;
            };
            if crate::adjustment_db::normalize_path(&path) == key {
                return self.facet_place_label_for_path(&path);
            }
        }
        key.to_string()
    }

    pub(crate) fn facet_place_label_for_path(&self, path: &Path) -> String {
        if self.items_are_subfolder_expansion_view
            && let Some(root) = self.subfolder_expansion_root.as_deref()
            && let Some(label) = subfolder_expansion::relative_place_label(root, path)
        {
            return label;
        }
        self.book_address_label_for_path(path)
            .unwrap_or_else(|| path.display().to_string())
    }

    pub(crate) fn facet_place_path_for_item(&self, item: &GridItem) -> Option<PathBuf> {
        match item {
            GridItem::Folder(path) => Some(path.clone()),
            GridItem::Image(path)
            | GridItem::Video(path)
            | GridItem::Audio(path)
            | GridItem::ZipFile(path)
            | GridItem::PdfFile(path)
            | GridItem::ConvertibleArchive { path, .. }
            | GridItem::Stack {
                representative: path,
                ..
            } => path.parent().map(Path::to_path_buf),
            GridItem::SearchContainer { path, kind, .. } => match kind {
                crate::grid_item::SearchContainerKind::Folder => Some(path.clone()),
                crate::grid_item::SearchContainerKind::Zip => path.parent().map(Path::to_path_buf),
            },
            GridItem::ZipImage { zip_path, .. } | GridItem::ZipDir { zip_path, .. } => {
                zip_path.parent().map(Path::to_path_buf)
            }
            GridItem::PdfPage { pdf_path, .. } => pdf_path.parent().map(Path::to_path_buf),
        }
    }

    pub(crate) fn facet_place_path_for_idx(&self, idx: usize) -> Option<PathBuf> {
        if let Some(row) = self.bookmark_view_row(idx) {
            return match &row.source {
                crate::bookmark_browser::BookmarkRowSource::Media { path, .. } => {
                    path.parent().map(Path::to_path_buf)
                }
                crate::bookmark_browser::BookmarkRowSource::Book(bookmark) => {
                    if matches!(
                        bookmark.container_kind,
                        crate::book_bookmarks::BookContainerKind::CompiledBook
                            | crate::book_bookmarks::BookContainerKind::ImageFolder
                    ) {
                        Some(bookmark.container_path.clone())
                    } else {
                        bookmark.container_path.parent().map(Path::to_path_buf)
                    }
                }
            };
        }
        self.items
            .get(idx)
            .and_then(|item| self.facet_place_path_for_item(item))
    }

    pub(crate) fn facet_filter_active(&self) -> bool {
        self.settings.facet_filter.is_active()
    }

    pub(crate) fn facet_filter_effectively_active(&self) -> bool {
        self.facet_filter_active()
    }

    pub(crate) fn grid_edit_badges(&self, idx: usize) -> GridEditBadges {
        GridEditBadges {
            page_override: self.adjustment_page_params.contains_key(&idx)
                || self.item_has_one_level_edit_key(idx, &self.adjusted_page_keys),
            local_adjust: self.local_adjust_pages.contains(&idx)
                || self.item_has_one_level_edit_key(idx, &self.local_adjust_page_keys),
            mask: self.mask_pages.contains(&idx)
                || self.item_has_one_level_edit_key(idx, &self.mask_page_keys),
            conceal: self.conceal_pages.contains(&idx)
                || self.item_has_one_level_edit_key(idx, &self.conceal_page_keys),
            comic: self.comic_pages.contains(&idx)
                || self.item_has_one_level_edit_key(idx, &self.comic_page_keys),
            rotation: self.item_has_one_level_rotation(idx),
        }
    }

    fn attach_edit_preview_to_request(&mut self, req: &mut LoadRequest) {
        req.relative_page_provenance = self.relative_page_provenance_for_idx(req.idx);
        if !self.settings.edit_preview_cache_enabled || self.edit_preview_cache.is_none() {
            req.edit_preview_key = None;
            req.edit_preview_validate_container = false;
            if let Some(key) = req.pinned_page_adjustment_key.as_ref() {
                self.thumb_edit_preview_keys.insert(req.idx, key.clone());
            } else {
                self.thumb_edit_preview_keys.remove(&req.idx);
            }
            return;
        }
        if req.edit_preview_key.is_none() {
            let badges = self.grid_edit_badges(req.idx);
            // 色調補正は既存の thumb_adjust_tex が安価に再現する。永続プレビューには
            // source 解像度の edit-result + 注釈 + 最後段 crop だけを含める。
            if badges.local_adjust
                || badges.mask
                || badges.conceal
                || badges.comic
                || self.export_crop_pages.contains(&req.idx)
            {
                req.edit_preview_key = self.page_path_key(req.idx);
            }
        }
        if let Some(key) = req
            .edit_preview_key
            .as_ref()
            .or(req.pinned_page_adjustment_key.as_ref())
        {
            self.thumb_edit_preview_keys.insert(req.idx, key.clone());
        } else {
            self.thumb_edit_preview_keys.remove(&req.idx);
        }
    }

    fn page_key_set_has_prefix(keys: &std::collections::BTreeSet<String>, prefix: &str) -> bool {
        keys.range(prefix.to_owned()..)
            .next()
            .is_some_and(|key| key.starts_with(prefix))
    }

    fn normalized_folder_page_prefix(path: &std::path::Path) -> String {
        let mut prefix = crate::adjustment_db::normalize_path(path);
        if !prefix.ends_with('/') {
            prefix.push('/');
        }
        prefix
    }

    fn normalized_archive_page_prefix(path: &std::path::Path) -> String {
        format!("{}::", crate::adjustment_db::normalize_path(path))
    }

    fn page_key_is_direct_child_of_folder(key: &str, folder_prefix: &str) -> bool {
        let Some(rest) = key.strip_prefix(folder_prefix) else {
            return false;
        };
        if rest.is_empty() {
            return false;
        }
        match (rest.find('/'), rest.find("::")) {
            (Some(slash), Some(virtual_sep)) => virtual_sep < slash,
            (Some(_), None) => false,
            _ => true,
        }
    }

    fn page_key_is_direct_file_child_of_folder(key: &str, folder_prefix: &str) -> bool {
        let Some(rest) = key.strip_prefix(folder_prefix) else {
            return false;
        };
        !rest.is_empty() && !rest.contains('/') && !rest.contains("::")
    }

    fn page_key_is_direct_child_of_virtual_prefix(key: &str, prefix: &str) -> bool {
        let Some(rest) = key.strip_prefix(prefix) else {
            return false;
        };
        !rest.is_empty() && !rest.contains('/')
    }

    fn folder_contains_page_key(
        keys: &std::collections::BTreeSet<String>,
        path: &std::path::Path,
        include_descendants: bool,
    ) -> bool {
        let prefix = Self::normalized_folder_page_prefix(path);
        if include_descendants {
            return Self::page_key_set_has_prefix(keys, &prefix);
        }
        for key in keys.range(prefix.clone()..) {
            if !key.starts_with(&prefix) {
                break;
            }
            if Self::page_key_is_direct_child_of_folder(key, &prefix) {
                return true;
            }
        }
        false
    }

    fn folder_contains_one_level_edit_key(
        keys: &std::collections::BTreeSet<String>,
        path: &std::path::Path,
    ) -> bool {
        let prefix = Self::normalized_folder_page_prefix(path);
        for key in keys.range(prefix.clone()..) {
            if !key.starts_with(&prefix) {
                break;
            }
            if Self::page_key_is_direct_file_child_of_folder(key, &prefix) {
                return true;
            }
        }
        false
    }

    fn archive_contains_page_key(
        keys: &std::collections::BTreeSet<String>,
        path: &std::path::Path,
    ) -> bool {
        let prefix = Self::normalized_archive_page_prefix(path);
        Self::page_key_set_has_prefix(keys, &prefix)
    }

    fn converted_archive_cache_path(&self, path: &std::path::Path) -> Option<&std::path::Path> {
        self.converted_archive_cache_paths
            .get(&crate::path_key::normalize_keep_drive(path))
            .map(std::path::PathBuf::as_path)
    }

    fn archive_or_converted_cache_contains_page_key(
        &self,
        keys: &std::collections::BTreeSet<String>,
        path: &std::path::Path,
    ) -> bool {
        Self::archive_contains_page_key(keys, path)
            || self
                .converted_archive_cache_path(path)
                .is_some_and(|cache_zip| Self::archive_contains_page_key(keys, cache_zip))
    }

    fn zip_dir_contains_page_key(
        keys: &std::collections::BTreeSet<String>,
        zip_path: &std::path::Path,
        dir_prefix: &str,
    ) -> bool {
        let prefix = format!(
            "{}::{}",
            crate::adjustment_db::normalize_path(zip_path),
            dir_prefix.to_lowercase()
        );
        Self::page_key_set_has_prefix(keys, &prefix)
    }

    fn zip_dir_or_converted_cache_contains_page_key(
        &self,
        keys: &std::collections::BTreeSet<String>,
        zip_path: &std::path::Path,
        dir_prefix: &str,
    ) -> bool {
        Self::zip_dir_contains_page_key(keys, zip_path, dir_prefix)
            || self
                .converted_archive_cache_path(zip_path)
                .is_some_and(|cache_zip| {
                    Self::zip_dir_contains_page_key(keys, cache_zip, dir_prefix)
                })
    }

    fn zip_dir_contains_one_level_edit_key(
        keys: &std::collections::BTreeSet<String>,
        zip_path: &std::path::Path,
        dir_prefix: &str,
        is_archive: bool,
    ) -> bool {
        let prefix = format!(
            "{}::{}",
            crate::adjustment_db::normalize_path(zip_path),
            dir_prefix.to_lowercase()
        );
        if is_archive {
            return Self::page_key_set_has_prefix(keys, &prefix);
        }
        for key in keys.range(prefix.clone()..) {
            if !key.starts_with(&prefix) {
                break;
            }
            if Self::page_key_is_direct_child_of_virtual_prefix(key, &prefix) {
                return true;
            }
        }
        false
    }

    fn zip_dir_or_converted_cache_contains_one_level_edit_key(
        &self,
        keys: &std::collections::BTreeSet<String>,
        zip_path: &std::path::Path,
        dir_prefix: &str,
        is_archive: bool,
    ) -> bool {
        Self::zip_dir_contains_one_level_edit_key(keys, zip_path, dir_prefix, is_archive)
            || self
                .converted_archive_cache_path(zip_path)
                .is_some_and(|cache_zip| {
                    Self::zip_dir_contains_one_level_edit_key(
                        keys, cache_zip, dir_prefix, is_archive,
                    )
                })
    }

    fn item_has_one_level_edit_key(
        &self,
        idx: usize,
        keys: &std::collections::BTreeSet<String>,
    ) -> bool {
        let Some(item) = self.items.get(idx) else {
            return false;
        };
        match item {
            GridItem::Image(_) | GridItem::ZipImage { .. } | GridItem::PdfPage { .. } => self
                .page_path_key(idx)
                .is_some_and(|key| keys.contains(&key)),
            GridItem::Folder(path) => Self::folder_contains_one_level_edit_key(keys, path),
            GridItem::ZipFile(path) | GridItem::PdfFile(path) => {
                Self::archive_contains_page_key(keys, path)
            }
            GridItem::ConvertibleArchive { path, .. } => {
                self.archive_or_converted_cache_contains_page_key(keys, path)
            }
            GridItem::ZipDir {
                zip_path,
                dir_prefix,
                is_archive,
                ..
            } => self.zip_dir_or_converted_cache_contains_one_level_edit_key(
                keys,
                zip_path,
                dir_prefix,
                *is_archive,
            ),
            GridItem::SearchContainer { path, kind, .. } => match kind {
                crate::grid_item::SearchContainerKind::Folder => {
                    Self::folder_contains_one_level_edit_key(keys, path)
                }
                crate::grid_item::SearchContainerKind::Zip => {
                    Self::archive_contains_page_key(keys, path)
                }
            },
            _ => false,
        }
    }

    fn item_has_page_edit_key(
        &self,
        idx: usize,
        keys: &std::collections::BTreeSet<String>,
        include_descendants: bool,
    ) -> bool {
        let Some(item) = self.items.get(idx) else {
            return false;
        };
        match item {
            GridItem::Image(_) | GridItem::ZipImage { .. } | GridItem::PdfPage { .. } => self
                .page_path_key(idx)
                .is_some_and(|key| keys.contains(&key)),
            GridItem::Folder(path) => {
                Self::folder_contains_page_key(keys, path, include_descendants)
            }
            GridItem::ZipFile(path) | GridItem::PdfFile(path) => {
                Self::archive_contains_page_key(keys, path)
            }
            GridItem::ConvertibleArchive { path, .. } => {
                self.archive_or_converted_cache_contains_page_key(keys, path)
            }
            GridItem::ZipDir {
                zip_path,
                dir_prefix,
                ..
            } => self.zip_dir_or_converted_cache_contains_page_key(keys, zip_path, dir_prefix),
            GridItem::SearchContainer { path, kind, .. } => match kind {
                crate::grid_item::SearchContainerKind::Folder => {
                    Self::folder_contains_page_key(keys, path, include_descendants)
                }
                crate::grid_item::SearchContainerKind::Zip => {
                    Self::archive_contains_page_key(keys, path)
                }
            },
            _ => false,
        }
    }

    fn item_has_one_level_rotation(&self, idx: usize) -> bool {
        let Some(item) = self.items.get(idx) else {
            return false;
        };
        match item {
            GridItem::Image(_)
            | GridItem::ZipImage { .. }
            | GridItem::PdfPage { .. }
            | GridItem::Video(_) => {
                self.rotation_cache
                    .get(&idx)
                    .is_some_and(|rot| !rot.is_none())
                    || self
                        .rotation_key_for_idx(idx)
                        .is_some_and(|key| self.rotation_page_keys.contains(&key))
            }
            _ => self.item_has_one_level_edit_key(idx, &self.rotation_page_keys),
        }
    }

    fn item_has_rotation_edit(&mut self, idx: usize, include_descendants: bool) -> bool {
        let Some(item) = self.items.get(idx).cloned() else {
            return false;
        };
        match item {
            GridItem::Image(_)
            | GridItem::ZipImage { .. }
            | GridItem::PdfPage { .. }
            | GridItem::Video(_) => !self.get_rotation(idx).is_none(),
            GridItem::Folder(path) => {
                Self::folder_contains_page_key(&self.rotation_page_keys, &path, include_descendants)
            }
            GridItem::ZipFile(path) | GridItem::PdfFile(path) => {
                Self::archive_contains_page_key(&self.rotation_page_keys, &path)
            }
            GridItem::ConvertibleArchive { path, .. } => {
                self.archive_or_converted_cache_contains_page_key(&self.rotation_page_keys, &path)
            }
            GridItem::ZipDir {
                zip_path,
                dir_prefix,
                ..
            } => self.zip_dir_or_converted_cache_contains_page_key(
                &self.rotation_page_keys,
                &zip_path,
                &dir_prefix,
            ),
            GridItem::SearchContainer { path, kind, .. } => match kind {
                crate::grid_item::SearchContainerKind::Folder => Self::folder_contains_page_key(
                    &self.rotation_page_keys,
                    &path,
                    include_descendants,
                ),
                crate::grid_item::SearchContainerKind::Zip => {
                    Self::archive_contains_page_key(&self.rotation_page_keys, &path)
                }
            },
            _ => false,
        }
    }

    fn passes_facet_filter(&mut self, idx: usize, ignore: Option<FacetField>) -> bool {
        use crate::settings::{FacetEditFlag, FacetTagMode};

        if !self.facet_filter_effectively_active() {
            return true;
        }
        if ignore != Some(FacetField::Name) && !self.passes_facet_name_filter(idx) {
            return false;
        }
        let Some(item) = self.items.get(idx).cloned() else {
            return false;
        };

        if ignore != Some(FacetField::Kind)
            && !self.settings.facet_filter.kinds.is_empty()
            && !self
                .settings
                .facet_filter
                .kinds
                .contains(&facet_kind_for_item(&item))
        {
            return false;
        }

        if ignore != Some(FacetField::Ext) && !self.settings.facet_filter.exts.is_empty() {
            let ext = facet_ext_for_item(&item);
            if ext.is_empty() || !self.settings.facet_filter.exts.contains(&ext) {
                return false;
            }
        }

        if ignore != Some(FacetField::Place) && !self.settings.facet_filter.place_keys.is_empty() {
            let Some(place_key) = self
                .facet_place_path_for_idx(idx)
                .map(|path| crate::adjustment_db::normalize_path(&path))
            else {
                return false;
            };
            if !self.settings.facet_filter.place_keys.contains(&place_key) {
                return false;
            }
        }

        let ai_filter_active = !self.settings.facet_filter.ai_models.is_empty()
            || !self.settings.facet_filter.ai_tools.is_empty();
        if ai_filter_active && !self.details_lazy_sort_ready() {
            return true;
        }
        if ignore != Some(FacetField::AiModel)
            && !self.settings.facet_filter.ai_models.is_empty()
            && facet_ai_filter_applies(&item)
        {
            let models = self.facet_ai_model_values(idx);
            if models.is_empty()
                || !models
                    .iter()
                    .any(|model| self.settings.facet_filter.ai_models.contains(model))
            {
                return false;
            }
        }
        if ignore != Some(FacetField::AiTool)
            && !self.settings.facet_filter.ai_tools.is_empty()
            && facet_ai_filter_applies(&item)
        {
            let tool = self.facet_ai_tool_value(idx);
            if tool.is_empty() || !self.settings.facet_filter.ai_tools.contains(&tool) {
                return false;
            }
        }

        if ignore != Some(FacetField::Tags) {
            let filter = &self.settings.facet_filter;
            if (!filter.tags.is_empty() || filter.include_untagged)
                && facet_tag_filter_applies(&item)
            {
                if self.cell_tags_loaded(idx) {
                    let tags = self.cell_tag_list(idx);
                    let untagged_match = filter.include_untagged && tags.is_empty();
                    let selected_match = if filter.tags.is_empty() {
                        false
                    } else {
                        match filter.tag_mode {
                            FacetTagMode::Any => filter.tags.iter().any(|wanted| {
                                tags.iter()
                                    .any(|tag| crate::tags_db::normalize_tag_key(tag) == *wanted)
                            }),
                            FacetTagMode::All => filter.tags.iter().all(|wanted| {
                                tags.iter()
                                    .any(|tag| crate::tags_db::normalize_tag_key(tag) == *wanted)
                            }),
                        }
                    };
                    if !untagged_match && !selected_match {
                        return false;
                    }
                }
            }
        }

        if ignore != Some(FacetField::Date) {
            if let Some(preset) = self.settings.facet_filter.date_preset {
                let Some((mtime, _)) = self.details_meta_value(idx) else {
                    return false;
                };
                let now = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_secs() as i64)
                    .unwrap_or(i64::MAX);
                if !preset.matches_mtime(mtime, now) {
                    return false;
                }
            }
        }

        if ignore != Some(FacetField::Size) {
            if let Some(preset) = self.settings.facet_filter.size_preset {
                let Some((_, size)) = self.details_meta_value(idx) else {
                    return false;
                };
                if size <= 0 {
                    return false;
                }
                let size = size as u64;
                let (min, max) = preset.range_bytes();
                if size < min || max.is_some_and(|m| size >= m) {
                    return false;
                }
            }
        }

        let edit_flags =
            if ignore != Some(FacetField::Edits) && !self.settings.facet_filter.edits.is_empty() {
                self.settings
                    .facet_filter
                    .edits
                    .iter()
                    .copied()
                    .collect::<Vec<_>>()
            } else {
                Vec::new()
            };

        if !edit_flags.is_empty() {
            let stars = if item.accepts_rating() {
                self.get_rating(idx)
            } else {
                0
            };
            let include_descendants = self.settings.facet_filter.edit_include_descendants;
            for flag in edit_flags {
                let matched = match flag {
                    FacetEditFlag::Adjustment | FacetEditFlag::AiAdjustment => {
                        self.adjustment_page_params.contains_key(&idx)
                            || self.item_has_page_edit_key(
                                idx,
                                &self.adjusted_page_keys,
                                include_descendants,
                            )
                    }
                    FacetEditFlag::LocalAdjustment => {
                        self.local_adjust_pages.contains(&idx)
                            || self.item_has_page_edit_key(
                                idx,
                                &self.local_adjust_page_keys,
                                include_descendants,
                            )
                    }
                    FacetEditFlag::Mask => {
                        self.mask_pages.contains(&idx)
                            || self.item_has_page_edit_key(
                                idx,
                                &self.mask_page_keys,
                                include_descendants,
                            )
                    }
                    FacetEditFlag::Conceal => {
                        self.conceal_pages.contains(&idx)
                            || self.item_has_page_edit_key(
                                idx,
                                &self.conceal_page_keys,
                                include_descendants,
                            )
                    }
                    FacetEditFlag::Annotation => {
                        self.comic_pages.contains(&idx)
                            || self.item_has_page_edit_key(
                                idx,
                                &self.comic_page_keys,
                                include_descendants,
                            )
                    }
                    FacetEditFlag::Rotation => {
                        self.item_has_rotation_edit(idx, include_descendants)
                    }
                    FacetEditFlag::Tagged => {
                        item_supports_tags(&item)
                            && (!self.cell_tags_loaded(idx) || !self.cell_tag_list(idx).is_empty())
                    }
                    FacetEditFlag::Untagged => {
                        item_supports_tags(&item)
                            && (!self.cell_tags_loaded(idx) || self.cell_tag_list(idx).is_empty())
                    }
                    FacetEditFlag::Rated => item.accepts_rating() && stars > 0,
                    FacetEditFlag::Unrated => item.accepts_rating() && stars == 0,
                    FacetEditFlag::Bookmarked => self
                        .bookmark_presence
                        .as_ref()
                        .is_none_or(|presence| self.item_has_bookmark(idx, &item, presence)),
                    FacetEditFlag::Unbookmarked => self
                        .bookmark_presence
                        .as_ref()
                        .is_none_or(|presence| !self.item_has_bookmark(idx, &item, presence)),
                };
                if !matched {
                    return false;
                }
            }
        }

        true
    }

    pub(crate) fn facet_ai_model_values(&self, idx: usize) -> Vec<String> {
        if !self.details_item_supports_ai_metadata(idx) {
            return Vec::new();
        }
        let Some(meta) = self.details_lazy_meta_for_idx(idx) else {
            return Vec::new();
        };
        if !meta.ai_metadata_checked {
            return Vec::new();
        }
        if meta.ai_models.is_empty() {
            vec![crate::png_metadata::MODEL_INFO_NONE_LABEL.to_string()]
        } else {
            meta.ai_models.clone()
        }
    }

    pub(crate) fn facet_ai_tool_value(&self, idx: usize) -> String {
        if !self.details_item_supports_ai_metadata(idx) {
            return String::new();
        }
        let Some(meta) = self.details_lazy_meta_for_idx(idx) else {
            return String::new();
        };
        if !meta.ai_metadata_checked {
            return String::new();
        }
        meta.ai_tool
            .clone()
            .unwrap_or_else(|| crate::png_metadata::TOOL_INFO_NONE_LABEL.to_string())
    }

    pub(crate) fn current_grid_order(&self) -> &[usize] {
        if !self.items_are_reading_history_view
            && self.settings.grid_view_mode == crate::settings::GridViewMode::Details
            && self.details_order.len() == self.visible_indices.len()
        {
            &self.details_order
        } else {
            &self.visible_indices
        }
    }

    pub(crate) fn set_grid_view_mode(&mut self, mode: crate::settings::GridViewMode) {
        if self.settings.grid_view_mode == mode {
            return;
        }
        self.settings.grid_view_mode = mode;
        self.details_thumb_suppression_applied = false;
        match mode {
            crate::settings::GridViewMode::Details => {
                self.rebuild_details_order();
                if self.details_any_lazy_columns_enabled() {
                    self.details_image_dims_state = LazyColumnState::NotRequested;
                }
            }
            crate::settings::GridViewMode::Thumbnail => {
                self.clear_details_hover_keep();
                self.cancel_details_meta_loading();
                self.details_order.clear();
                self.details_order_revision = self.details_order_revision.wrapping_add(1);
                self.details_tag_prewarm_indices.clear();
            }
        }
        self.scroll_to_selected = true;
        self.settings.save();
    }

    pub(crate) fn toggle_grid_details_view(&mut self) {
        let next = if self.settings.grid_view_mode == crate::settings::GridViewMode::Details {
            crate::settings::GridViewMode::Thumbnail
        } else {
            crate::settings::GridViewMode::Details
        };
        self.set_grid_view_mode(next);
    }

    pub(crate) fn details_header_sort_active(&self) -> bool {
        self.settings.grid_view_mode == crate::settings::GridViewMode::Details
            && !self.current_folder_is_book_folder()
            && !self.items_are_reading_history_view
            && self.settings.details_sort_key != crate::settings::DetailsSortKey::Toolbar
    }

    pub(crate) fn reset_details_sort_if_hidden(&mut self) {
        if !self.details_sort_key_visible(self.settings.details_sort_key) {
            self.settings.details_sort_key = crate::settings::DetailsSortKey::Toolbar;
            self.settings.details_sort_ascending = true;
            self.rebuild_details_order();
        }
    }

    fn details_sort_key_visible(&self, key: crate::settings::DetailsSortKey) -> bool {
        use crate::settings::DetailsSortKey;
        match key {
            DetailsSortKey::Toolbar | DetailsSortKey::Name => true,
            DetailsSortKey::Rating => self.settings.details_show_rating,
            DetailsSortKey::Tags => self.settings.details_show_tags,
            DetailsSortKey::Kind => self.settings.details_show_kind,
            DetailsSortKey::PageCount => self.settings.details_show_page_count,
            DetailsSortKey::Place => self.settings.details_show_place,
            DetailsSortKey::Size => self.settings.details_show_size,
            DetailsSortKey::Modified => self.settings.details_show_modified,
            DetailsSortKey::Created => self.settings.details_show_created,
            DetailsSortKey::State => self.settings.details_show_state,
            DetailsSortKey::ImageDimensions => self.settings.details_show_image_dimensions,
            DetailsSortKey::VideoDuration => self.settings.details_show_video_duration,
            DetailsSortKey::VideoDimensions => self.settings.details_show_video_dimensions,
            DetailsSortKey::VideoCodec => self.settings.details_show_video_codec,
        }
    }

    pub(crate) fn set_details_sort_key(&mut self, key: crate::settings::DetailsSortKey) {
        if self.items_are_reading_history_view {
            return;
        }
        let lazy_key = matches!(
            key,
            crate::settings::DetailsSortKey::PageCount
                | crate::settings::DetailsSortKey::Created
                | crate::settings::DetailsSortKey::ImageDimensions
                | crate::settings::DetailsSortKey::VideoDuration
                | crate::settings::DetailsSortKey::VideoDimensions
                | crate::settings::DetailsSortKey::VideoCodec
        );
        if lazy_key && !self.details_lazy_sort_ready() {
            return;
        }
        let previous_key = self.settings.details_sort_key;
        if self.settings.details_sort_key == key {
            if self.settings.details_sort_ascending {
                self.settings.details_sort_ascending = false;
            } else {
                self.settings.details_sort_key = crate::settings::DetailsSortKey::Toolbar;
                self.settings.details_sort_ascending = true;
            }
        } else {
            self.settings.details_sort_key = key;
            self.settings.details_sort_ascending = true;
        }
        let entered_page_count_sort = previous_key != crate::settings::DetailsSortKey::PageCount
            && self.settings.details_sort_key == crate::settings::DetailsSortKey::PageCount;
        let left_page_count_sort = previous_key == crate::settings::DetailsSortKey::PageCount
            && self.settings.details_sort_key != crate::settings::DetailsSortKey::PageCount;
        if entered_page_count_sort {
            // 通常表示の page-count Ready は「現在の可視近傍を取得済み」という段階状態。
            // 全件ソートへ遷移するときは別ジョブとして明示的に再始動し、画面外の None を
            // 並べた不正確な順序を一度も確定しない。
            if let Some(pending) = self.details_meta_pending.take() {
                pending.cancel.store(true, Ordering::Relaxed);
            }
            self.details_lazy_visible_revision = self.details_lazy_visible_revision.wrapping_add(1);
            self.details_image_dims_state = LazyColumnState::NotRequested;
        } else if left_page_count_sort {
            // 進行中の全件ジョブだけを止め、次フレームに現在の列構成へ合わせた
            // 可視範囲ジョブを再構築する。全件取得済みの Ready + pending なしは、
            // 他の遅延列も充足済みなので維持し、UI thread の O(N) 再評価を避ける。
            let had_pending = if let Some(pending) = self.details_meta_pending.take() {
                pending.cancel.store(true, Ordering::Relaxed);
                true
            } else {
                false
            };
            if had_pending || self.details_image_dims_state.is_loading() {
                self.details_lazy_visible_revision =
                    self.details_lazy_visible_revision.wrapping_add(1);
                self.details_image_dims_state = LazyColumnState::NotRequested;
            }
        }
        self.rebuild_details_order();
        self.scroll_to_selected = true;
        self.settings.save();
    }

    pub(crate) fn rebuild_details_order(&mut self) {
        self.details_order_revision = self.details_order_revision.wrapping_add(1);
        self.cached_nav_indices = None;
        self.cached_fs_seek_info = None;
        let mut key = self.settings.details_sort_key;
        let mut ascending = self.settings.details_sort_ascending;
        if !self.details_sort_key_visible(key) {
            self.settings.details_sort_key = crate::settings::DetailsSortKey::Toolbar;
            self.settings.details_sort_ascending = true;
            key = self.settings.details_sort_key;
            ascending = self.settings.details_sort_ascending;
        }
        if key == crate::settings::DetailsSortKey::PageCount
            && !self.details_image_dims_state.is_ready()
        {
            // PageCount へ切り替えた直後は全件取得が終わるまで toolbar 順を維持する。
            // Finished で Ready になった時点で poll_details_meta_load が再構築する。
            self.details_order = self.visible_indices.clone();
            return;
        }
        if key == crate::settings::DetailsSortKey::Toolbar
            || self.current_folder_is_book_folder()
            || self.items_are_reading_history_view
        {
            self.details_order = self.visible_indices.clone();
            return;
        }
        let visible = self.visible_indices.clone();
        let mut rows: Vec<DetailsSortRow> = visible
            .into_iter()
            .map(|idx| self.details_sort_row(idx, key))
            .collect();
        rows.sort_by(|a, b| Self::compare_details_sort_rows(a, b, key, ascending));
        self.details_order = rows.into_iter().map(|row| row.idx).collect();
    }

    fn details_sort_row(
        &mut self,
        idx: usize,
        key: crate::settings::DetailsSortKey,
    ) -> DetailsSortRow {
        use crate::settings::DetailsSortKey;
        let name = self
            .items
            .get(idx)
            .map(|item| item.name().into_owned())
            .unwrap_or_default();
        let primary = match key {
            DetailsSortKey::Toolbar => DetailsSortPrimary::None,
            DetailsSortKey::Name => DetailsSortPrimary::None,
            DetailsSortKey::Rating => DetailsSortPrimary::U8(self.get_rating(idx)),
            DetailsSortKey::Tags => DetailsSortPrimary::Text(self.cell_tag_list(idx).join(" ")),
            DetailsSortKey::Kind => DetailsSortPrimary::Text(self.details_kind_sort_key(idx)),
            DetailsSortKey::PageCount => {
                DetailsSortPrimary::U64(self.details_page_count_sort_value(idx))
            }
            DetailsSortKey::Place => DetailsSortPrimary::Text(
                self.facet_place_path_for_idx(idx)
                    .map(|path| self.facet_place_label_for_path(&path))
                    .unwrap_or_default(),
            ),
            DetailsSortKey::Size => {
                DetailsSortPrimary::I64(self.details_meta_value(idx).map(|(_, size)| size))
            }
            DetailsSortKey::Modified => {
                DetailsSortPrimary::I64(self.details_meta_value(idx).map(|(mtime, _)| mtime))
            }
            DetailsSortKey::Created => {
                DetailsSortPrimary::I64(self.details_created_sort_value(idx))
            }
            DetailsSortKey::State => DetailsSortPrimary::U32(self.details_state_bits_for_sort(idx)),
            DetailsSortKey::ImageDimensions => {
                DetailsSortPrimary::U64(self.details_image_dims_sort_value(idx))
            }
            DetailsSortKey::VideoDuration => {
                DetailsSortPrimary::U64(self.details_video_duration_sort_value(idx))
            }
            DetailsSortKey::VideoDimensions => {
                DetailsSortPrimary::U64(self.details_video_dims_sort_value(idx))
            }
            DetailsSortKey::VideoCodec => DetailsSortPrimary::Text(
                self.details_video_codec_sort_value(idx).unwrap_or_default(),
            ),
        };
        DetailsSortRow {
            idx,
            primary,
            name_key: crate::filename_sort::SortNameKey::file_name(&name),
        }
    }

    fn compare_details_sort_rows(
        a: &DetailsSortRow,
        b: &DetailsSortRow,
        key: crate::settings::DetailsSortKey,
        ascending: bool,
    ) -> std::cmp::Ordering {
        use crate::settings::DetailsSortKey;
        use std::cmp::Ordering;

        let primary = match key {
            DetailsSortKey::Toolbar => Ordering::Equal,
            DetailsSortKey::Name => Self::compare_details_sort_names(a, b),
            DetailsSortKey::Size | DetailsSortKey::Modified | DetailsSortKey::Created => {
                let DetailsSortPrimary::I64(av) = &a.primary else {
                    return Ordering::Equal;
                };
                let DetailsSortPrimary::I64(bv) = &b.primary else {
                    return Ordering::Equal;
                };
                cmp_option_last(*av, *bv, ascending)
            }
            DetailsSortKey::PageCount
            | DetailsSortKey::ImageDimensions
            | DetailsSortKey::VideoDuration
            | DetailsSortKey::VideoDimensions => {
                let DetailsSortPrimary::U64(av) = &a.primary else {
                    return Ordering::Equal;
                };
                let DetailsSortPrimary::U64(bv) = &b.primary else {
                    return Ordering::Equal;
                };
                cmp_option_last(*av, *bv, ascending)
            }
            _ => Self::compare_details_sort_primary(&a.primary, &b.primary),
        };

        let primary = match key {
            DetailsSortKey::Size
            | DetailsSortKey::Modified
            | DetailsSortKey::Created
            | DetailsSortKey::PageCount
            | DetailsSortKey::ImageDimensions
            | DetailsSortKey::VideoDuration
            | DetailsSortKey::VideoDimensions => primary,
            _ if ascending => primary,
            _ => primary.reverse(),
        };

        if primary != Ordering::Equal {
            return primary;
        }
        Self::compare_details_sort_names(a, b).then_with(|| a.idx.cmp(&b.idx))
    }

    fn compare_details_sort_primary(
        a: &DetailsSortPrimary,
        b: &DetailsSortPrimary,
    ) -> std::cmp::Ordering {
        match (a, b) {
            (DetailsSortPrimary::Text(a), DetailsSortPrimary::Text(b)) => a.cmp(b),
            (DetailsSortPrimary::U8(a), DetailsSortPrimary::U8(b)) => a.cmp(b),
            (DetailsSortPrimary::U32(a), DetailsSortPrimary::U32(b)) => a.cmp(b),
            (DetailsSortPrimary::U64(a), DetailsSortPrimary::U64(b)) => a.cmp(b),
            _ => std::cmp::Ordering::Equal,
        }
    }

    fn compare_details_sort_names(a: &DetailsSortRow, b: &DetailsSortRow) -> std::cmp::Ordering {
        a.name_key.compare_file_name(&b.name_key)
    }

    fn details_meta_value(&self, idx: usize) -> Option<(i64, i64)> {
        self.image_metas
            .get(idx)
            .copied()
            .flatten()
            .filter(|(mtime, size)| *mtime > 0 || *size > 0)
    }

    fn details_kind_sort_key(&self, idx: usize) -> String {
        let Some(item) = self.items.get(idx) else {
            return String::new();
        };
        match item {
            GridItem::Folder(_) => "0-folder".to_string(),
            GridItem::Image(p) => format!("1-image-{}", path_extension_lower(p)),
            GridItem::Video(p) => format!("2-video-{}", path_extension_lower(p)),
            GridItem::Audio(p) => format!("2-video-audio-{}", path_extension_lower(p)),
            GridItem::ZipFile(p) => format!("3-zip-{}", path_extension_lower(p)),
            GridItem::PdfFile(p) => format!("4-pdf-{}", path_extension_lower(p)),
            GridItem::ConvertibleArchive { format, .. } => format!("5-{}", format.label()),
            GridItem::ZipImage { .. } => "6-zip-image".to_string(),
            GridItem::PdfPage { .. } => "7-pdf-page".to_string(),
            // ネスト ZIP 子コンテナ: ZIP 内には実フォルダが無いので、コンテナ慣習に従い
            // 先頭グループ (ZipImage より前) に並べる。
            GridItem::ZipDir { .. } => "0-zipdir".to_string(),
            GridItem::SearchContainer { kind, .. } => match kind {
                crate::grid_item::SearchContainerKind::Folder => "9-search-folder".to_string(),
                crate::grid_item::SearchContainerKind::Zip => "9-search-zip".to_string(),
            },
            // ファイル名スタックの集約セルは画像枠で並べる (代表画像の拡張子で副キー)。
            GridItem::Stack { representative, .. } => {
                format!("1-image-{}", path_extension_lower(representative))
            }
        }
    }

    fn details_state_bits(&self, idx: usize) -> u32 {
        let mut bits = 0u32;
        let badges = self.grid_edit_badges(idx);
        if badges.page_override {
            bits |= 1 << 0;
        }
        if badges.local_adjust {
            bits |= 1 << 1;
        }
        if badges.mask {
            bits |= 1 << 2;
        }
        if badges.conceal {
            bits |= 1 << 3;
        }
        if badges.comic {
            bits |= 1 << 4;
        }
        if badges.rotation {
            bits |= 1 << 5;
        }
        bits
    }

    fn details_state_bits_for_sort(&mut self, idx: usize) -> u32 {
        let mut bits = self.details_state_bits(idx);
        if !self.get_rotation(idx).is_none() {
            bits |= 1 << 5;
        }
        bits
    }

    /// `visible_indices` に含まれる (= フィルタ後の一覧に出ている) かを返す。
    /// `visible_indices` は items 順 (昇順) なので binary_search で O(log n)。
    /// より狭い「prefetch 対象」判定が欲しい場合は [`Self::keep_set`] を直接参照する。
    pub(crate) fn idx_visible(&self, idx: usize) -> bool {
        self.visible_indices.binary_search(&idx).is_ok()
    }

    /// `keep_set` の内容を idx 昇順の Vec で返す。enqueue ログの順序安定や
    /// idle upgrade / tag prewarm / 補正テクスチャなど「先頭から順に処理したい」
    /// 背景処理用。worker 側は priority + distance で並べ直すので機能影響はない。
    fn keep_set_sorted(&self) -> Vec<usize> {
        let mut v: Vec<usize> = self.keep_set.iter().copied().collect();
        v.sort_unstable();
        v
    }

    /// 親復帰で解決済みの item を選択し、通常の ensure-visible 経路へ渡す。
    /// 名前ヒントと smart-folder の exact root-entry 解決が同じ適用規則を共有する。
    fn select_item_after_load(&mut self, idx: usize) {
        debug_assert!(idx < self.items.len());
        self.selected = Some(idx);
        self.scroll_to_selected = true;
        self.redirect_selected_to_visible();
    }

    /// `select_after_load` のヒントで items 内をケース無視で検索し、見つかれば
    /// selected を更新して true を返す。フィルタで隠れていれば直近の可視 idx に逃がす
    /// (`redirect_selected_to_visible` と同じ WYSIWYG 不変条件)。
    fn try_select_after_load(&mut self) -> bool {
        let Some(name) = self.select_after_load.take() else {
            return false;
        };
        let name_lower = name.to_lowercase();
        let Some(idx) = self
            .items
            .iter()
            .position(|item| item.name().to_lowercase() == name_lower)
        else {
            return false;
        };
        self.select_item_after_load(idx);
        true
    }

    /// `self.selected` が visible_indices から外れていたら、items 順で直近の
    /// visible idx にリダイレクトする (手前優先、無ければ次)。
    /// `rebuild_visible_indices` の末尾と、`load_folder` の履歴から selected を
    /// 復元した直後で呼ぶ (Codex P2: 履歴復元で stale な hidden idx が入り得るため)。
    pub(crate) fn redirect_selected_to_visible(&mut self) {
        let Some(sel) = self.selected else {
            return;
        };
        let vi = &self.visible_indices;
        if vi.binary_search(&sel).is_ok() {
            return;
        }
        let pos = vi.partition_point(|&i| i < sel);
        let prev = pos.checked_sub(1).map(|p| vi[p]);
        let next = vi.get(pos).copied();
        self.selected = prev.or(next);
        if self.selected.is_some() {
            self.scroll_to_selected = true;
        }
    }

    /// 選択カーソルを常に可視アイテム上に置く。フィルタやフォルダ切替で未選択に
    /// なった場合は、先頭可視アイテムを選ぶ。
    pub(crate) fn ensure_selected_visible_or_first(&mut self) {
        self.redirect_selected_to_visible();
        if self.selected.is_some() {
            return;
        }
        let first_selectable = self.visible_indices.first().copied();
        if let Some(idx) = first_selectable {
            self.selected = Some(idx);
            self.scroll_to_selected = true;
        }
    }

    /// メタデータキーワード検索を実行する。
    /// フォルダ内の全 PNG 画像の tEXt チャンクを読み、
    /// キーワード（大文字小文字無視）にマッチするアイテムのみをフィルタ表示する。
    /// メタデータ検索 (Ctrl+F) をバックグラウンドスレッドで開始する。
    ///
    /// 旧実装は UI スレッドで `read_tweet_info` / `build_searchable_from_path` を
    /// 同期実行しており、大フォルダで数秒フリーズしていた。このメソッドでは
    /// スレッドを spawn し、結果は `poll_search` で受け取る。連打/新クエリで
    /// 既存検索をキャンセルできるよう `SearchPending.cancel` を立てる。
    pub(crate) fn execute_search(&mut self, ctx: &egui::Context) {
        // 既存の in-flight 検索をキャンセル (新クエリ / 再 Enter)。
        if let Some(pending) = self.search_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }

        // クエリ構文: space = AND / `-word` = NOT / `"..."` = フレーズ (`-"..."` も可)。
        let tokens = crate::search_query::parse(&self.search_query);
        if tokens.is_empty() {
            self.search_filter = None;
            self.search_filter_origin_folder = None;
            self.search_tag_bridge.clear();
            self.rebuild_visible_indices();
            self.refresh_color_filter_for_scope_change(ctx);
            return;
        }
        self.search_filter_origin_folder = self.effective_folder();
        // タグ橋渡し (D17): クエリ語が mIV タグと一致するなら「タグビューで表示」
        // チップを出す。検索実行時に tags.db を 1 回引くだけで、Ctrl+F の検索対象に
        // タグを混ぜるわけではない (Ctrl+G と同じ仕組み)。v1.0 で Ctrl+F `#タグ` を
        // 常用していたユーザーが「ゼロヒット + 無誘導」で迷子になるのを防ぐ。
        self.search_tag_bridge = self
            .tags_db
            .as_ref()
            .map(|db| {
                crate::global_search_ui::tag_bridge_suggestions_for_query(db, &self.search_query, 3)
            })
            .unwrap_or_default();

        // スレッドに渡すスナップショット: items は中身 PathBuf を含むので clone コストは
        // あるが、検索は低頻度操作なので許容範囲。xmp_cache は既読分のルックアップ
        // 専用で、スレッドは自分が読み取った分は `xmp_additions` で UI に返す。
        let items_snapshot = self.items.clone();
        let xmp_snapshot = self.xmp_cache.clone();
        // PDF document info 照合 (§4.1.1) はワーカースレッドで保存済みパスワードを
        // 引く。ストアごと clone してスレッドへ渡す (decrypt は照合対象 PDF だけ遅延)。
        let pdf_passwords = self.pdf_passwords.clone();
        // INDEX_VERSION=5 で fts_meta から原文 (`*_norm`) が無くなったため、Ctrl+F は
        // 表示中アイテムを on-demand 経路 (PNG / EXIF / XMP / 動画メタ) で
        // 判定する。`run_metadata_search` は引数として fts_meta を受け取るが現在は
        // 未使用 (将来 Tantivy STORED への切替路の余地として残してある)。
        let fts_meta_clone: Option<std::sync::Arc<crate::fts_meta::FtsMetaDb>> = self
            .indexer_manager
            .as_ref()
            .map(|mgr| mgr.clone_fts_meta());
        // §4.1.2: ZIP 表示中は検索対象をファイル名に固定する。ユーザーが選んだ
        // self.search_target (メタ系) はそのまま保持し、ここでの override は
        // ZIP グリッドに限る (通常フォルダに戻れば元の target で検索される)。
        let target = if self.grid_is_zip_entries() {
            crate::fts_index::SearchTarget::Only(vec![crate::fts_index::SourceKind::Filename])
        } else {
            self.search_target.clone()
        };
        let mode: crate::search_query::MatchMode = self.search_or_mode.into();
        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_w = Arc::clone(&cancel);
        let progress = Arc::new(SearchProgressShared::new(ctrl_f_progress_total(
            &items_snapshot,
        )));
        let progress_w = Arc::clone(&progress);
        let (tx, rx) = mpsc::channel();
        // perf 計装上、検索開始を input イベントとして記録する (input_seq は副作用で更新)。
        self.bump_input_seq("search", Some(&self.search_query.clone()));

        std::thread::Builder::new()
            .name("metadata-search".to_string())
            .spawn(move || {
                let result = run_metadata_search(
                    &tokens,
                    &items_snapshot,
                    &xmp_snapshot,
                    fts_meta_clone.as_ref(),
                    &pdf_passwords,
                    &target,
                    mode,
                    &cancel_w,
                    Some(progress_w.as_ref()),
                );
                let _ = tx.send(result);
            })
            .ok();

        self.search_pending = Some(SearchPending {
            cancel,
            progress,
            rx,
        });
    }

    /// in-flight 検索があればキャンセルする (検索バーを閉じる等の経路で呼ぶ)。
    pub(crate) fn cancel_search_pending(&mut self) {
        if let Some(pending) = self.search_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
    }

    /// グリッドが PDF のページ表示で構成されているか (= PDF を開いている)。
    /// PDF ページは連番の合成名しか持たず検索の意味が無いため、true のとき
    /// Ctrl+F を無効化する (docs/search-container-item-redesign.md §4.1.1)。
    pub(crate) fn grid_is_pdf_pages(&self) -> bool {
        self.items
            .first()
            .is_some_and(|it| matches!(it, crate::grid_item::GridItem::PdfPage { .. }))
    }

    /// グリッドが ZIP 内エントリで構成されているか (= ZIP を開いている)。
    /// ZIP 内では Ctrl+F をファイル名フィルタに固定する (§4.1.2)。
    ///
    /// ネスト ZIP ツリーナビ (v1.3.0) では、ルート階層が ZipDir のみ (直下画像 0 枚) の
    /// ことがある。その場合 items に ZipImage が無いので、`zip_nav` の有無も見て ZIP 内と
    /// 判定する。さもないと Ctrl+F が filename 固定にならず、検索対象が tags/EXIF 等のとき
    /// ZipDir の名前照合 (filename 次元) が無効化されてコンテナが全消えする (Codex P2)。
    pub(crate) fn grid_is_zip_entries(&self) -> bool {
        self.zip_nav.is_some()
            || self.items.first().is_some_and(|it| {
                matches!(
                    it,
                    crate::grid_item::GridItem::ZipImage { .. }
                        | crate::grid_item::GridItem::ZipDir { .. }
                )
            })
    }

    /// in-flight 検索の結果を非同期に受信する。
    /// フォルダ切替 / 検索バー閉じ / 新検索で旧スレッドはキャンセルされるため、
    /// 受信時は「まだ同じ検索コンテキストか」の追加チェックは不要 (cancel されれば
    /// スレッドは結果を送らない)。
    ///
    /// 検索 in-flight 中は毎フレーム repaint を要求する必要がある (egui はアイドルで
    /// 寝るため、ワーカーが送信しても UI が拾いに来ない)。呼び出し元の update() が
    /// ctx.request_repaint() を最後に呼ぶのでそちらに任せる (個別 ctx 保持不要)。
    pub(crate) fn poll_search(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.search_pending.as_ref() else {
            return;
        };
        match pending.rx.try_recv() {
            Ok(SearchThreadResult::Done {
                matches,
                xmp_additions,
            }) => {
                // ワーカーが新規に読み取った XMP をキャッシュにマージする。
                // 既存キーは上書きしない (並行して別スレッドが先に書き込んだケースを尊重)。
                for (key, xmp) in xmp_additions {
                    self.xmp_cache.entry(key).or_insert(xmp);
                }
                self.search_filter = Some(matches);
                self.search_filter_origin_folder = self.effective_folder();
                self.rebuild_visible_indices();
                self.selected = None;
                self.scroll_offset_y = 0.0;
                self.pending_grid_scroll = None;
                self.search_pending = None;
                self.refresh_color_filter_for_scope_change(ctx);
            }
            Err(mpsc::TryRecvError::Empty) => {}
            Err(mpsc::TryRecvError::Disconnected) => {
                // キャンセル済みで送信されなかった or スレッドパニック。
                self.search_pending = None;
            }
        }
    }

    /// 指定 idx の回転角度を取得する（キャッシュ + DB）。
    pub(crate) fn get_rotation(&mut self, idx: usize) -> crate::rotation_db::Rotation {
        if let Some(&rot) = self.rotation_cache.get(&idx) {
            return rot;
        }
        let Some(key) = self.rotation_key_for_idx(idx) else {
            return crate::rotation_db::Rotation::None;
        };
        let rot = self
            .rotation_db
            .as_ref()
            .and_then(|db| db.get_key(&key))
            .unwrap_or(crate::rotation_db::Rotation::None);
        self.rotation_cache.insert(idx, rot);
        rot
    }

    fn rotation_key_for_idx(&self, idx: usize) -> Option<String> {
        match self.items.get(idx)? {
            GridItem::Image(_) | GridItem::ZipImage { .. } | GridItem::PdfPage { .. } => {
                self.page_path_key(idx)
            }
            // 旧実装との互換: 動画サムネの回転キーは実パスのまま維持する。
            GridItem::Video(p) => Some(crate::adjustment_db::normalize_path(p)),
            _ => None,
        }
    }

    /// 指定 idx の画像を時計回りに 90° 回転する。
    pub(crate) fn rotate_image_cw(&mut self, idx: usize) {
        if self.idx_is_compiled_book_page(idx) {
            self.show_feedback_toast("本のページは回転できません".to_string());
            return;
        }
        let current = self.get_rotation(idx);
        let new_rot = current.rotate_cw();
        self.apply_rotation(idx, new_rot);
    }

    /// 指定 idx の画像を反時計回りに 90° 回転する。
    pub(crate) fn rotate_image_ccw(&mut self, idx: usize) {
        if self.idx_is_compiled_book_page(idx) {
            self.show_feedback_toast("本のページは回転できません".to_string());
            return;
        }
        let current = self.get_rotation(idx);
        let new_rot = current.rotate_ccw();
        self.apply_rotation(idx, new_rot);
    }

    /// 指定 idx の画像を選択された絶対角度へ設定する。
    pub(crate) fn set_image_rotation(
        &mut self,
        idx: usize,
        rotation: crate::rotation_db::Rotation,
    ) {
        if self.idx_is_compiled_book_page(idx) {
            self.show_feedback_toast("本のページは回転できません".to_string());
            return;
        }
        self.apply_rotation(idx, rotation);
    }

    fn apply_rotation(&mut self, idx: usize, rot: crate::rotation_db::Rotation) {
        let Some(key) = self.rotation_key_for_idx(idx) else {
            return;
        };
        self.rotation_cache.insert(idx, rot);
        if let Some(ref db) = self.rotation_db {
            let _ = db.set_key(&key, rot);
        }
        Self::set_page_key_presence(&mut self.rotation_page_keys, &key, !rot.is_none());
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Edits,
        );
    }

    // ── レーティング ───────────────────────────────────────────────

    /// レーティング DB キーを返す。
    /// ページ単位 (画像 / ZIP 内画像 / PDF ページ) は `page_path_key` と同じ形式。
    /// コンテナ (フォルダ / ZIP / PDF 本体) はそのパスを `normalize_path` したもの。
    /// `::` セパレータの有無でページとコンテナを区別するので衝突しない。
    pub(crate) fn rating_path_key(&self, idx: usize) -> Option<String> {
        let item = self.items.get(idx)?;
        match item {
            GridItem::Image(_) | GridItem::ZipImage { .. } | GridItem::PdfPage { .. } => {
                self.page_path_key(idx)
            }
            // Video / Audio は単一ファイルだがパス正規化はコンテナと同じ規則 (DB キーは
            // フルパス normalize)。leaf vs container の分類は `is_rating_leaf` /
            // `is_container_ratable` で行う。
            GridItem::Folder(p)
            | GridItem::ZipFile(p)
            | GridItem::PdfFile(p)
            | GridItem::Video(p)
            | GridItem::Audio(p) => Some(crate::adjustment_db::normalize_path(p)),
            GridItem::ConvertibleArchive { path, .. } => {
                Some(crate::adjustment_db::normalize_path(path))
            }
            // ネスト ZIP ツリーの本 (v1.3.0): 実パスを持たないので、ピン/見開きと同じ
            // 合成パス (zip_path + literal prefix セグメント) を正規化してキーにする。
            // set/get とも同じセル (literal dir_prefix) 経由なので自己整合する。
            GridItem::ZipDir {
                zip_path,
                dir_prefix,
                ..
            } => {
                let root = zip_rating_root_path(
                    zip_path,
                    self.archive_source_override.as_deref(),
                    self.current_folder.as_deref(),
                );
                Some(crate::adjustment_db::normalize_path(&book_container_key(
                    root, dir_prefix,
                )))
            }
            _ => None,
        }
    }

    /// レーティング操作の対象となる物理パスを返す (XMP 書き込み先 / Undo の source_path 用)。
    /// `rating_path_key` と同じアイテム範囲を扱うので、対応するアイテム種別を増減する
    /// 場合は両方を一緒に更新すること。
    pub(crate) fn rating_source_path(&self, idx: usize) -> Option<PathBuf> {
        match self.items.get(idx)? {
            GridItem::Image(p)
            | GridItem::Video(p)
            | GridItem::Audio(p)
            | GridItem::Folder(p)
            | GridItem::ZipFile(p)
            | GridItem::PdfFile(p) => Some(p.clone()),
            GridItem::ConvertibleArchive { path, .. } => Some(path.clone()),
            GridItem::ZipImage { zip_path, .. } => Some(zip_path.clone()),
            GridItem::ZipDir { zip_path, .. } => Some(
                zip_rating_root_path(
                    zip_path,
                    self.archive_source_override.as_deref(),
                    self.current_folder.as_deref(),
                )
                .to_path_buf(),
            ),
            GridItem::PdfPage { pdf_path, .. } => Some(pdf_path.clone()),
            _ => None,
        }
    }

    /// Return the exact physical file that may receive `xmp:Rating` for this
    /// item. This is the shared eligibility boundary for normal writes and
    /// Undo/Redo capture: compiled-book pages are intentionally DB-only even
    /// though their source files are writable JPEG/PNG/WebP images.
    pub(crate) fn rating_xmp_target_for_idx(&self, idx: usize) -> Option<PathBuf> {
        if self.idx_is_compiled_book_page(idx) {
            return None;
        }
        match self.items.get(idx) {
            Some(GridItem::Image(path)) if crate::xmp_writer::is_writable_format(path) => {
                Some(path.clone())
            }
            _ => None,
        }
    }

    pub(crate) fn rating_meta_for_idx(&self, idx: usize) -> Option<crate::rating_db::RatingMeta> {
        use crate::rating_db::{RatingItemKind, RatingMeta};
        let item = self.items.get(idx)?;
        let mut meta = match item {
            GridItem::Image(path) => RatingMeta::new(RatingItemKind::Image).with_source_path(path),
            GridItem::Video(path) => RatingMeta::new(RatingItemKind::Video).with_source_path(path),
            GridItem::Audio(path) => RatingMeta::new(RatingItemKind::Audio).with_source_path(path),
            GridItem::Folder(path) => {
                RatingMeta::new(RatingItemKind::Folder).with_source_path(path)
            }
            GridItem::ZipFile(path) => {
                RatingMeta::new(RatingItemKind::ZipFile).with_source_path(path)
            }
            GridItem::PdfFile(path) => {
                RatingMeta::new(RatingItemKind::PdfFile).with_source_path(path)
            }
            GridItem::ConvertibleArchive { path, format } => {
                let mut meta =
                    RatingMeta::new(RatingItemKind::ConvertibleArchive).with_source_path(path);
                meta.archive_format = Some(archive_format_to_rating_str(*format).to_string());
                meta
            }
            GridItem::ZipImage {
                zip_path,
                entry_name,
            } => {
                let mut meta = RatingMeta::new(RatingItemKind::ZipImage).with_source_path(zip_path);
                meta.entry_name = Some(entry_name.clone());
                meta
            }
            GridItem::PdfPage {
                pdf_path, page_num, ..
            } => {
                let mut meta = RatingMeta::new(RatingItemKind::PdfPage).with_source_path(pdf_path);
                meta.page_num = Some(*page_num);
                meta
            }
            GridItem::ZipDir {
                zip_path,
                dir_prefix,
                is_archive,
                representative,
            } => {
                let root = zip_rating_root_path(
                    zip_path,
                    self.archive_source_override.as_deref(),
                    self.current_folder.as_deref(),
                );
                let mut meta = RatingMeta::new(RatingItemKind::ZipDir).with_source_path(root);
                meta.dir_prefix = Some(dir_prefix.clone());
                meta.zipdir_is_archive = Some(*is_archive);
                meta.zipdir_representative = representative.clone();
                meta
            }
            _ => return None,
        };
        if meta.source_path.is_none()
            && let Some(source) = self.rating_source_path(idx)
        {
            meta.source_path = Some(source.to_string_lossy().to_string());
        }
        Some(meta)
    }

    pub(crate) fn rating_meta_for_key_and_source(
        &self,
        key: &str,
        source_path: &Path,
    ) -> Option<crate::rating_db::RatingMeta> {
        use crate::rating_db::{RatingItemKind, RatingMeta};
        let ext = source_path
            .extension()
            .and_then(|e| e.to_str())
            .map(|e| e.to_ascii_lowercase())
            .unwrap_or_default();
        let mut meta = if let Some((_, right)) = key.split_once("::") {
            if ext == "pdf" {
                let page_num = right.strip_prefix("page_")?.parse::<u32>().ok()?;
                let mut meta =
                    RatingMeta::new(RatingItemKind::PdfPage).with_source_path(source_path);
                meta.page_num = Some(page_num);
                meta
            } else if entry_name_is_image(right) {
                let mut meta =
                    RatingMeta::new(RatingItemKind::ZipImage).with_source_path(source_path);
                meta.entry_name = Some(right.to_string());
                meta
            } else {
                return None;
            }
        } else if std::fs::metadata(source_path)
            .ok()
            .is_some_and(|m| m.is_dir())
        {
            RatingMeta::new(RatingItemKind::Folder).with_source_path(source_path)
        } else if crate::folder_tree::is_recognized_image_ext(&ext) {
            RatingMeta::new(RatingItemKind::Image).with_source_path(source_path)
        } else if crate::folder_tree::SUPPORTED_VIDEO_EXTENSIONS.contains(&ext.as_str()) {
            RatingMeta::new(RatingItemKind::Video).with_source_path(source_path)
        } else if crate::folder_tree::is_zip_extension(&ext) {
            RatingMeta::new(RatingItemKind::ZipFile).with_source_path(source_path)
        } else if ext == "pdf" {
            RatingMeta::new(RatingItemKind::PdfFile).with_source_path(source_path)
        } else if let Some(format) = crate::archive_converter::ArchiveFormat::from_extension(&ext) {
            let mut meta =
                RatingMeta::new(RatingItemKind::ConvertibleArchive).with_source_path(source_path);
            meta.archive_format = Some(archive_format_to_rating_str(format).to_string());
            meta
        } else {
            return None;
        };
        if meta.source_path.is_none() {
            meta.source_path = Some(source_path.to_string_lossy().to_string());
        }
        Some(meta)
    }

    fn rating_session_generation_for_key(&self, key: &str) -> u64 {
        self.rating_session_writes
            .get(key)
            .map(|write| write.generation)
            .unwrap_or(0)
    }

    pub(crate) fn record_rating_session_write(
        &mut self,
        key: String,
        stars: u8,
        explicit_user: bool,
    ) {
        self.rating_session_write_generation =
            self.rating_session_write_generation.wrapping_add(1).max(1);
        self.rating_session_writes.insert(
            key,
            RatingSessionWrite {
                generation: self.rating_session_write_generation,
                stars: stars.min(5),
                explicit_user,
            },
        );
    }

    /// Single ownership boundary for every user-originated rating DB write.
    /// The path generation ledger is App-global while display caches remain
    /// context-local, so detached and main contexts converge without sharing a
    /// mutable cache instance.
    pub(crate) fn write_user_rating_shared(
        &mut self,
        key: &str,
        stars: u8,
        meta: Option<&crate::rating_db::RatingMeta>,
    ) -> Result<(), String> {
        self.rating_db
            .as_ref()
            .ok_or_else(|| "レーティング DB を利用できません".to_string())?
            .set_user_rating(key, stars, meta)
            .map_err(|error| format!("レーティング DB への保存に失敗しました: {error}"))?;
        // A generation is a publication record, not an attempted-write
        // counter. Detached/main contexts may consume it only after SQLite is
        // the durable source of truth.
        self.record_rating_session_write(key.to_string(), stars, true);
        self.sync_current_context_rating_session_writes();
        Ok(())
    }

    /// Atomic multi-row form of [`Self::write_user_rating_shared`]. Session
    /// generations and context caches are published only after the SQLite
    /// transaction commits, so callers can keep their UI/Undo state unchanged
    /// on failure.
    pub(crate) fn write_user_ratings_shared(
        &mut self,
        writes: &[(String, u8, Option<crate::rating_db::RatingMeta>)],
    ) -> Result<(), String> {
        if writes.is_empty() {
            return Ok(());
        }
        let db_writes = writes
            .iter()
            .map(|(key, stars, meta)| (key.as_str(), *stars, meta.as_ref()))
            .collect::<Vec<_>>();
        self.rating_db
            .as_ref()
            .ok_or_else(|| "レーティング DB を利用できません".to_string())?
            .set_user_ratings(&db_writes)
            .map_err(|error| format!("レーティング DB への保存に失敗しました: {error}"))?;
        for (key, stars, _) in writes {
            self.record_rating_session_write(key.clone(), *stars, true);
        }
        self.sync_current_context_rating_session_writes();
        Ok(())
    }

    pub(crate) fn report_rating_write_error(&mut self, error: &str) {
        crate::logger::log(format!("[RATING] user write failed: {error}"));
        self.show_feedback_toast(format!("レーティングを保存できませんでした: {error}"));
    }

    /// App-global path rating 更新を、現在 mount 中 context の idx cache へ反映する。
    ///
    /// context ごとの cache ownership は維持しつつ、DB とユーザー最終値だけを共有する。
    /// `ViewerContextBundle` の swap 前後と新規一覧の DB prewarm 後に呼ばれるため、行 identity が
    /// 同じで bookmark grid の再 install を省略しても古い星を表示し続けない。
    fn sync_current_context_rating_session_writes(&mut self) -> bool {
        let seen = self.rating_session_write_seen_generation;
        let current = self.rating_session_write_generation;
        if seen == current {
            return false;
        }

        let item_updates = self
            .items
            .iter()
            .enumerate()
            .filter_map(|(idx, _)| {
                let key = self.rating_path_key(idx)?;
                let write = self.rating_session_writes.get(&key)?;
                (write.generation > seen).then_some((idx, write.stars))
            })
            .collect::<Vec<_>>();
        let folder_update = self
            .current_container_rating_key_and_source()
            .and_then(|(key, _)| self.rating_session_writes.get(&key).copied())
            .filter(|write| write.generation > seen)
            .map(|write| write.stars);

        let mut changed = false;
        for (idx, stars) in item_updates {
            changed |= self.rating_cache.insert(idx, stars) != Some(stars);
        }
        if let Some(stars) = folder_update {
            changed |= self.current_folder_rating_cache.replace(stars) != Some(stars);
        }
        self.rating_session_write_seen_generation = current;
        changed
    }

    /// 指定 idx のレーティング (0..=5) を取得する (キャッシュ + DB)。
    /// 動画 / セパレータ等は常に 0 を返す (レーティング対象外)。
    /// フォルダ / ZIP / PDF ファイル本体も対象 (コンテナレーティング)。
    /// 非対象アイテムはキャッシュを汚さないように insert しない。
    pub(crate) fn get_rating(&mut self, idx: usize) -> u8 {
        self.sync_current_context_rating_session_writes();
        if let Some(&v) = self.rating_cache.get(&idx) {
            return v;
        }
        // サブ展開は準備 worker が DB の全対象キーを一括確認し、非ゼロだけを sparse
        // cache に載せる。miss は未評価と確定しているので UI スレッドから点 query しない。
        if self.items_are_subfolder_expansion_view || self.items_are_smart_folder_view {
            return 0;
        }
        let accepts = matches!(self.items.get(idx), Some(it) if it.accepts_rating());
        if !accepts {
            return 0;
        }
        let key = match self.rating_path_key(idx) {
            Some(k) => k,
            None => return 0,
        };
        let stars = self.rating_db.as_ref().map(|db| db.get(&key)).unwrap_or(0);
        self.rating_cache.insert(idx, stars);
        stars
    }

    /// 指定 idx のレーティングを設定する (0..=5)。
    /// レーティング対象外アイテムの場合は何もしない。
    /// フォルダ / ZIP / PDF ファイル本体も対象 (コンテナレーティング)。
    pub(crate) fn set_rating(&mut self, idx: usize, stars: u8) -> bool {
        match self.set_rating_result(idx, stars) {
            Ok(changed) => changed,
            Err(error) => {
                self.report_rating_write_error(&error);
                false
            }
        }
    }

    fn set_rating_result(&mut self, idx: usize, stars: u8) -> Result<bool, String> {
        let accepts = matches!(self.items.get(idx), Some(it) if it.accepts_rating());
        if !accepts {
            return Ok(false);
        }
        self.sync_current_context_rating_session_writes();
        let stars = stars.min(5);
        let key = match self.rating_path_key(idx) {
            Some(k) => k,
            None => return Ok(false),
        };
        let meta = self.rating_meta_for_idx(idx);
        let xmp_target = self.rating_xmp_target_for_idx(idx);
        // prewarm で全 item が cache に載っている前提。未取得なら 0 扱いで OK。
        let old_stars = self.rating_cache.get(&idx).copied().unwrap_or(0);
        // DB write と App-global path generation の記録を同じ ownership
        // boundary に通す。detached unmount 時は swap 境界が main / parked
        // cache へ同じ値を反映する。
        self.write_user_rating_shared(&key, stars, meta.as_ref())?;
        self.rating_cache.insert(idx, stars);
        self.invalidate_rating_counts_cache();
        // コンテナ自身の★は子孫集計と別軸なので、単一ファイルレーティング (画像 / 動画 /
        // ZIP 内画像 / PDF ページ) のみ親フォルダの集計に伝搬する。
        if matches!(self.items.get(idx), Some(it) if it.is_rating_leaf()) {
            self.apply_rating_delta_to_folder_counts(&key, old_stars, stars);
        }
        // コンテナへの rating 変更は current_folder と同じパスを指す可能性があるので
        // アドレスバーキャッシュを lazy 再計算させる。
        if matches!(self.items.get(idx), Some(it) if it.is_container_ratable()) {
            self.current_folder_rating_cache = None;
        }
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Rating,
        );
        // 設定 ON + Image (JPEG/PNG/WebP) のときだけ XMP にも書き込む。
        // コンテナや ZIP 内画像・PDF ページには書き込み先がないので DB 止まり。
        if self.settings.write_rating_to_xmp
            && let Some(path) = xmp_target
        {
            self.ensure_rating_write_handle();
            if let Some(h) = self.rating_write_handle.as_ref() {
                h.submit(crate::rating_write_worker::RatingWriteJob {
                    path,
                    rating: if stars == 0 { None } else { Some(stars) },
                });
            }
        }
        Ok(true)
    }

    /// 任意のフォルダパスの★ (コンテナレーティング) を DB から読む (Inc 5 FB)。
    /// フルスクリーンでは対象フォルダがグリッドアイテムでない (idx がない) ので、
    /// idx ベースの `get_rating` ではなくパスキー直読みで取得する。
    pub(crate) fn folder_rating_by_path(&self, folder: &std::path::Path) -> u8 {
        let key = crate::adjustment_db::normalize_path(folder);
        self.rating_db.as_ref().map(|db| db.get(&key)).unwrap_or(0)
    }

    /// 任意のフォルダパスの★ (コンテナレーティング) を設定する (Inc 5 FB)。
    /// `set_rating` のコンテナ分岐と同じキャッシュ無効化を行う (idx キャッシュはフォルダに
    /// エントリを持たないので触らない。グリッド復帰時に DB から読み直される)。
    pub(crate) fn set_folder_rating_by_path(
        &mut self,
        folder: &std::path::Path,
        stars: u8,
    ) -> bool {
        let stars = stars.min(5);
        let key = crate::adjustment_db::normalize_path(folder);
        let meta = crate::rating_db::RatingMeta::new(crate::rating_db::RatingItemKind::Folder)
            .with_source_path(folder);
        if let Err(error) = self.write_user_rating_shared(&key, stars, Some(&meta)) {
            self.report_rating_write_error(&error);
            return false;
        }
        self.invalidate_rating_counts_cache();
        self.current_folder_rating_cache = Some(stars);
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Rating,
        );
        true
    }

    /// レーティング XMP 書き込み worker を必要なら起動する (遅延初期化)。
    pub(crate) fn ensure_rating_write_handle(&mut self) {
        if self.rating_write_handle.is_none() {
            self.rating_write_handle = Some(crate::rating_write_worker::RatingWriteHandle::spawn());
        }
    }

    /// rating worker の結果を回収し、失敗があればトースト表示する。
    /// タグ書き込み ([`poll_tag_write_results`]) と同じポリシー。
    pub(crate) fn poll_rating_write_results(&mut self) {
        let mut errors: Vec<(PathBuf, String)> = Vec::new();
        if let Some(h) = self.rating_write_handle.as_ref() {
            while let Some(res) = h.try_recv_result() {
                match res.result {
                    Ok(()) => {
                        crate::logger::log(format!(
                            "[RATING] ✓ XMP written → {}",
                            res.path.display()
                        ));
                    }
                    Err(e) => {
                        crate::logger::log(format!(
                            "[RATING] ✗ XMP write failed: {e} → {}",
                            res.path.display()
                        ));
                        errors.push((res.path, e));
                    }
                }
            }
        }
        if !errors.is_empty() {
            let preview = errors
                .iter()
                .take(3)
                .map(|(p, e)| {
                    format!(
                        "{}: {}",
                        p.file_name().and_then(|n| n.to_str()).unwrap_or("?"),
                        e
                    )
                })
                .collect::<Vec<_>>()
                .join(" / ");
            self.show_feedback_toast(format!(
                "レーティング書き込み失敗 {} 件: {}",
                errors.len(),
                preview
            ));
        }
    }

    // ── 再帰レーティングフィルタ (子孫★集計) ─────────────────────

    /// `folder_rating_counts` を空にし、worker を cancel する。フォルダ切替時に呼ぶ。
    pub(crate) fn reset_folder_rating_counts(&mut self) {
        self.folder_rating_counts.clear();
        self.folder_rating_counts_loaded = false;
        self.folder_rating_counts_folder_key = None;
        if let Some(h) = self.folder_rating_counter_handle.take() {
            h.cancel();
        }
    }

    /// レーティングフィルタが有効か (バケットが 1 つでも OFF なら true)。
    /// フィルタが全 ON の状態は「フィルタ未使用」として worker を動かさない。
    ///
    /// ⚠ Codex P1-2 fix 後: この関数は **ユーザー設定** (`settings.rating_filter`) を
    /// 直接見る。★一時解除中は内部で effective_rating_filter() が [true;6] を返すが、
    /// settings 自体は書き換えていないので嘘をつかない。
    pub(crate) fn rating_filter_active(&self) -> bool {
        !self.settings.rating_filter.iter().all(|&b| b)
    }

    /// 表示に使う実効フィルタ (= effective rating filter)。
    ///
    /// - ★一時解除中: `[true; 6]` (= 全 ON、画面表示は filter なし状態)
    /// - それ以外: `settings.rating_filter` (= ユーザー設定そのまま)
    ///
    /// Codex P1-2 fix: 旧版は ★一時解除発動時に `settings.rating_filter` を直接
    /// `[true; 6]` に書き換える hidden mode だったため、`rating_filter_active()`
    /// が嘘をつき、自己破壊ループ等のバグを誘発していた。本関数の導入で
    /// 「ユーザー設定」と「実効フィルタ」を完全分離。
    pub(crate) fn effective_rating_filter(&self) -> [bool; 6] {
        if self.rating_filter_suppressed_at.is_some() {
            [true; 6]
        } else {
            self.settings.rating_filter
        }
    }

    /// `maybe_suppress_rating_filter_for_opened_container` の path 版。
    /// Ctrl+G の `SearchContainer` を開く経路 (`drill_into_container`) は idx 経由の
    /// `container_path()` / `get_rating()` で対応していない (SearchContainer は
    /// page_path_key にも rating_path_key にも載っていない疑似アイテム)。
    /// パスから直接 rating_db を引いて、コンテナ★がフィルタを通るなら一時解除する。
    ///
    /// 効果: ★5 を本に付けて★5 フィルタ ON のまま Ctrl+G 集約結果からそのフォルダを
    /// 開いても、中の画像が未評価でも空にならない (Codex P2 対応)。
    pub(crate) fn maybe_suppress_rating_filter_for_opened_container_path(&mut self, anchor: &Path) {
        if self.rating_filter_suppressed_at.is_some() {
            return;
        }
        if !self.rating_filter_active() {
            return;
        }
        let Some(db) = self.rating_db.as_ref() else {
            return;
        };
        let key = crate::adjustment_db::normalize_path(anchor);
        let stars = db.get(&key);
        if !(1..=5).contains(&stars) {
            return;
        }
        // Folder/ZipFile/PdfFile と同じく `s <= 5 && rf[s]` 規約。SearchContainer
        // 自身は accepts_rating=false なので passes_rating_filter は使えず、ここで
        // 直接判定する。
        let s = stars as usize;
        if s > 5 || !self.settings.rating_filter[s] {
            return;
        }
        // Codex P1-2 fix: settings.rating_filter は書き換えない。
        // effective_rating_filter() が rating_filter_suppressed_at の有無で
        // [true;6] / settings 値を返し分ける。
        let saved = self.settings.rating_filter; // 互換性のため field に残す (= 未使用)
        self.rating_filter_suppressed_at = Some((anchor.to_path_buf(), saved));
        self.show_feedback_toast("★フィルタ一時解除中 (親へ戻ると復元)".to_string());
    }

    /// 「自身に★が付いたコンテナ (Folder / ZIP / PDF) を開く」操作時に呼ぶ。
    /// コンテナ自身の★が現在フィルタを通るなら、フィルタを一時解除して anchor を記録する。
    ///
    /// これにより `★5 の ZIP を絞り込みで見つけて開く → 中身が未評価で全部消える`
    /// 事故を防ぐ。階層ナビ用のフォルダ (自身★なし) では発動しないので、
    /// `★5 を保って深く掘る` ワークフローは壊れない。
    ///
    /// 既に suppression 中ならネストさせず no-op (単一階層だけで十分)。
    pub(crate) fn maybe_suppress_rating_filter_for_opened_container(&mut self, idx: usize) {
        if self.rating_filter_suppressed_at.is_some() {
            return;
        }
        if !self.rating_filter_active() {
            return;
        }
        // item borrow は get_rating (mut) と競合するので先に path を取り出してから release する。
        let Some(anchor) = self
            .items
            .get(idx)
            .and_then(|it| it.container_path())
            .map(Path::to_path_buf)
        else {
            return;
        };
        let stars = self.get_rating(idx);
        if !(1..=5).contains(&stars) {
            return;
        }
        // bucket の index safety + `accepts_rating` 判定を passes_rating_filter に委譲。
        // RAR/7z/LZH などの ConvertibleArchive もコンテナ★対象なので、ZIP/PDF と同じく
        // 自身の★がフィルタを通るときだけ一時解除する。
        let item = &self.items[idx];
        if !passes_rating_filter(item, stars, &self.settings.rating_filter) {
            // 自身の★が現在フィルタに通っていない = 親ビューで見えなかったはず
            // (= ユーザーが address bar や Ctrl+↑↓ で直接辿り着いた)。意図した操作と
            // 見なしてフィルタは保持する。
            return;
        }
        // Codex P1-2 fix: settings.rating_filter は書き換えない (= ユーザー設定を保持)。
        // 表示は effective_rating_filter() が suppress 状態を見て [true;6] / settings を切替。
        let saved = self.settings.rating_filter; // 互換性のため field に残す (= 未使用)
        self.rating_filter_suppressed_at = Some((anchor, saved));
        self.show_feedback_toast("★フィルタ一時解除中 (親へ戻ると復元)".to_string());
    }

    /// ネスト ZIP の本 (`GridItem::ZipDir`) を開く時に呼ぶ。本自身に★が付いていて
    /// それが現在のフィルタを通るなら、フィルタを一時解除する。
    ///
    /// `maybe_suppress_rating_filter_for_opened_container` の ZipDir 版。ZipDir は
    /// 実パスを持たず `container_path()` が `None` を返すので既存ヘルパーでは扱えない。
    /// アンカーには本の合成キー (`book_container_key` = zip_path + literal prefix) を使う。
    /// これで `★5 の本を絞り込みで見つけて開く → 中身が未評価で全部消える` 事故を防ぐ
    /// (Codex P2)。復元は `maybe_restore_rating_filter_after_zip_level_change` が
    /// 本より上の階層へ戻ったときに、ZIP を抜けたときは `load_folder` 末尾の
    /// `maybe_restore_rating_filter_if_out_of_scope` が行う。
    pub(crate) fn maybe_suppress_rating_filter_for_opened_zip_book(&mut self, idx: usize) {
        if self.rating_filter_suppressed_at.is_some() || !self.rating_filter_active() {
            return;
        }
        let Some(GridItem::ZipDir {
            zip_path,
            dir_prefix,
            ..
        }) = self.items.get(idx)
        else {
            return;
        };
        let zip_path = zip_path.clone();
        let dir_prefix = dir_prefix.clone();
        let stars = self.get_rating(idx);
        if !(1..=5).contains(&stars) {
            return;
        }
        let s = stars as usize;
        if s > 5 || !self.settings.rating_filter[s] {
            // 本の★が現在のフィルタを通っていない = 親階層で見えていなかったはず
            // (= ユーザーが Ctrl+↑↓ / アドレス欄で直接辿り着いた)。意図操作とみなし保持。
            return;
        }
        let root = zip_rating_root_path(
            &zip_path,
            self.archive_source_override.as_deref(),
            self.current_folder.as_deref(),
        );
        let anchor = book_container_key(root, &dir_prefix);
        let saved = self.settings.rating_filter;
        self.rating_filter_suppressed_at = Some((anchor, saved));
        self.show_feedback_toast("★フィルタ一時解除中 (本から戻ると復元)".to_string());
    }

    /// `load_folder` の最後に呼ぶ: suppression の自動再評価。
    ///
    /// 1. 既に suppress 中 + anchor の subtree 内 → 維持 (= 子孫探索中は継続)
    /// 2. 既に suppress 中 + anchor の subtree 外 → 一旦 restore
    /// 3. fall through (= suppress なし) で現在 folder の★を見て suppress 発動可否を判定
    ///
    /// これにより Ctrl+↑↓ / Ctrl+PageUp/Down で別の★付き folder に移動した際にも
    /// 自動的に ★一時解除 が発動する。
    ///
    /// 関数名は互換性のため維持 (= 呼び出し元: load_folder_with_scan 末尾)。
    ///
    /// Codex P1-2 fix 後: settings.rating_filter は書き換えないので、active 判定は
    /// 直接 rating_filter_active() を見れば良い (= 旧版の自己破壊ループ回避が不要に)。
    pub(crate) fn maybe_restore_rating_filter_if_out_of_scope(&mut self) {
        let Some(current) = self.effective_folder() else {
            // 現在フォルダが取れない状態 (起動直後など) は触らない
            return;
        };
        // 既に suppress 中: anchor の subtree 内なら維持、外なら一旦 restore
        if let Some((anchor, _)) = self.rating_filter_suppressed_at.as_ref() {
            let anchor_owned = anchor.clone(); // immutable borrow を切る
            if path_in_subtree_ci(&current, &anchor_owned) {
                return;
            }
            // subtree 外 → restore してから再評価
            self.restore_rating_filter_suppression();
        }
        // suppress なし状態で再評価: rating_filter_active なら現在 folder の★で発動可否判定
        if !self.rating_filter_active() {
            return;
        }
        // 現在 folder の★を見て suppress を発動可否判定 (= 既存 helper を再利用)。
        // 発動条件: folder 自身に★が付いている + その★が現在 filter で通る
        // (= ★なし folder では発動しない、フィルタ外 folder でも発動しない)。
        self.maybe_suppress_rating_filter_for_opened_container_path(&current);
    }

    /// suppression anchor を取り出し、保存されていたフィルタを復元する。
    /// suppression 中でなければ `false` を返す (呼び出し側が no-op を検出できる)。
    ///
    /// `maybe_restore_rating_filter_if_out_of_scope` (scope 外自動復元) と
    /// toolbar の「★一時解除中」バッジクリック (即時復元) の両方から使う。
    pub(crate) fn restore_rating_filter_suppression(&mut self) -> bool {
        if self.rating_filter_suppressed_at.take().is_some() {
            // Codex P1-2 fix: settings.rating_filter は書き換えていないので復元不要。
            // suppressed_at = None になった時点で effective_rating_filter() が
            // settings 値を返すようになる。
            true
        } else {
            false
        }
    }

    /// ユーザーが手動でフィルタを変更した時に呼ぶ: suppression anchor を破棄する。
    /// 復元はせず (現在のフィルタはユーザー自身の操作なのでそれが正)、anchor だけ消す。
    pub(crate) fn drop_rating_filter_suppression_on_user_edit(&mut self) {
        self.rating_filter_suppressed_at = None;
    }

    fn suppress_current_facet_filter_at(&mut self, anchor: PathBuf, message: String) {
        if !self.facet_filter_active() {
            return;
        }
        if self
            .facet_filter_suppression_stack
            .last()
            .is_some_and(|top| top.anchor == anchor)
        {
            return;
        }
        let saved_filter = std::mem::take(&mut self.settings.facet_filter);
        self.sync_facet_name_runtime_from_filter();
        self.facet_filter_suppression_stack
            .push(FacetFilterSuppression {
                anchor,
                saved_filter,
            });
        self.show_feedback_toast(message);
    }

    pub(crate) fn maybe_suppress_facet_filter_for_opened_container_path(&mut self, anchor: &Path) {
        self.suppress_current_facet_filter_at(
            anchor.to_path_buf(),
            "親の絞り込みを退避しました (戻ると復元)".to_string(),
        );
    }

    pub(crate) fn maybe_suppress_facet_filter_for_opened_container(&mut self, idx: usize) {
        if !self.facet_filter_active() {
            return;
        }
        if !self.passes_facet_filter(idx, None) {
            return;
        }
        let Some(anchor) = self
            .items
            .get(idx)
            .and_then(|it| it.container_path())
            .map(Path::to_path_buf)
        else {
            return;
        };
        self.suppress_current_facet_filter_at(
            anchor,
            "親の絞り込みを退避しました (戻ると復元)".to_string(),
        );
    }

    pub(crate) fn maybe_suppress_facet_filter_for_opened_zip_book(&mut self, idx: usize) {
        if !self.facet_filter_active() {
            return;
        }
        if !self.passes_facet_filter(idx, None) {
            return;
        }
        let Some(GridItem::ZipDir {
            zip_path,
            dir_prefix,
            ..
        }) = self.items.get(idx)
        else {
            return;
        };
        let root = zip_rating_root_path(
            zip_path,
            self.archive_source_override.as_deref(),
            self.current_folder.as_deref(),
        );
        let anchor = book_container_key(root, dir_prefix);
        self.suppress_current_facet_filter_at(
            anchor,
            "親の絞り込みを退避しました (本から戻ると復元)".to_string(),
        );
    }

    pub(crate) fn restore_facet_filter_suppression(&mut self) -> bool {
        if let Some(suppression) = self.facet_filter_suppression_stack.pop() {
            self.settings.facet_filter = suppression.saved_filter;
            self.sync_facet_name_runtime_from_filter();
            self.settings.save();
            true
        } else {
            false
        }
    }

    pub(crate) fn facet_filter_suppressed(&self) -> bool {
        !self.facet_filter_suppression_stack.is_empty()
    }

    /// ZIP 階層の移動 (`zip_nav_show_current_level`) 後に呼ぶ: ★付きの本を開いて
    /// 一時解除したフィルタを、その本より上の階層へ戻ったら復元する。
    ///
    /// 判定はアンカーの正規化キー (= 抑制した本の rating キー) と現在階層のコンテナ
    /// キーの **接頭辞包含** で行う。本のセル literal prefix は入った後の effective
    /// prefix の接頭辞なので、collapse された本でも「中にいる間は cur_key が anchor_key を
    /// 接頭辞に持つ」が成り立つ (= 中にいる限り誤復元しない)。判定不能 (検索ビュー等で
    /// `current_container_rating_key_and_source` が `None`) のときは **復元しない**
    /// (= 保持側に倒す)。ZIP を完全に抜けた場合は `load_folder` 末尾の
    /// `maybe_restore_rating_filter_if_out_of_scope` が拾う。
    fn maybe_restore_rating_filter_after_zip_level_change(&mut self) {
        let Some((anchor, _)) = self.rating_filter_suppressed_at.as_ref() else {
            return;
        };
        let anchor_key = crate::adjustment_db::normalize_path(anchor);
        let Some((cur_key, _)) = self.current_container_rating_key_and_source() else {
            return;
        };
        let inside = cur_key == anchor_key || cur_key.starts_with(&format!("{anchor_key}/"));
        if !inside {
            self.restore_rating_filter_suppression();
            self.current_folder_rating_cache = None;
        }
    }

    fn maybe_restore_facet_filter_after_zip_level_change(&mut self) {
        let Some((cur_key, _)) = self.current_container_rating_key_and_source() else {
            return;
        };
        while let Some(top) = self.facet_filter_suppression_stack.last() {
            let anchor_key = crate::adjustment_db::normalize_path(&top.anchor);
            let inside = cur_key == anchor_key || cur_key.starts_with(&format!("{anchor_key}/"));
            if inside {
                break;
            }
            self.restore_facet_filter_suppression();
        }
    }

    /// 毎フレーム呼ぶ: フィルタ ON かつ現フォルダ未スキャンなら worker 起動、
    /// フィルタ OFF ならバッファを片付ける。Ctrl+G 検索結果ビュー / rating_db 無し /
    /// current_folder 無しは no-op。
    ///
    /// change-detection は `folder_rating_counts_folder_key` のみを見る。handle の有無を
    /// 条件に入れると worker 終了直後 (handle=None) に再 spawn するループで点滅する。
    pub(crate) fn ensure_folder_rating_counter(&mut self) {
        if !self.rating_filter_active() {
            if self.folder_rating_counter_handle.is_some()
                || !self.folder_rating_counts.is_empty()
                || self.folder_rating_counts_folder_key.is_some()
            {
                self.reset_folder_rating_counts();
            }
            return;
        }

        let Some(current) = self.current_folder.clone() else {
            return;
        };
        if is_synthetic_view_path(&current) || self.global_search.active {
            return;
        }
        if self.rating_db.is_none() {
            return;
        }
        let folder_key = crate::adjustment_db::normalize_path(&current);
        if self.folder_rating_counts_folder_key.as_deref() == Some(&folder_key) {
            return;
        }
        if let Some(h) = self.folder_rating_counter_handle.take() {
            h.cancel();
        }
        self.folder_rating_counts.clear();
        self.folder_rating_counts_loaded = false;
        let db_path = crate::data_dir::get().join("rating.db");
        self.folder_rating_counter_handle = Some(crate::folder_rating_counter::spawn_for_folder(
            db_path,
            folder_key.clone(),
        ));
        self.folder_rating_counts_folder_key = Some(folder_key);
    }

    /// worker からの部分結果を取り込む。毎フレーム呼ぶ。
    /// 再描画は update ループ末尾の repaint ゲートが担当する。
    ///
    /// 100k+ 件の DB でキューに batch が溜まっていると `try_recv` 連続 drain が UI
    /// フレーム hitch になるため、1 フレームで最大 `MAX_BATCHES_PER_FRAME` 件までに
    /// 制限する (残りは次フレーム)。
    pub(crate) fn poll_folder_rating_counts(&mut self) {
        const MAX_BATCHES_PER_FRAME: usize = 8;
        let Some(h) = self.folder_rating_counter_handle.as_ref() else {
            return;
        };
        for _ in 0..MAX_BATCHES_PER_FRAME {
            match h.rx.try_recv() {
                Ok(batch) => {
                    for (key, counts) in batch.entries {
                        let e = self.folder_rating_counts.entry(key).or_insert([0u32; 5]);
                        for i in 0..5 {
                            e[i] = e[i].saturating_add(counts[i]);
                        }
                    }
                    if batch.finished {
                        self.folder_rating_counts_loaded = true;
                    }
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => return,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    self.folder_rating_counts_loaded = true;
                    self.folder_rating_counter_handle = None;
                    return;
                }
            }
        }
    }

    /// 指定 idx (Folder / ZipFile / PdfFile) のフィルタ一致件数と per-star 内訳を返す。
    /// worker 未起動 / キー無し / フィルタ対象外 / 合計 0 件 は `None`。
    /// `per_star` はマスク前の全★別件数で、tooltip 内訳表示に使う。
    ///
    /// Ctrl+G drilled view の場合は `search_drilled_folder_counts` (★なし含む 6 バケット)
    /// を優先参照する。folder_rating_counter worker が Ctrl+G 中は走らないため、
    /// `state.all_hits` から直接集計した値をここで使う。
    ///
    /// バッジ合計は通常フォルダと同じく `rf[1..5]` (★1..★5) のみで集計する。
    /// `rf[0]` (なし) はフォルダ自身の表示可否 (`rebuild_visible_indices`) 側でしか
    /// 使わない — 通常表示と検索結果で見た目が揃うようにするため。
    pub(crate) fn folder_rating_match(&self, idx: usize) -> Option<(u32, [u32; 5])> {
        // フィルタ全 ON (= 非アクティブ) のときはバッジを出さない。通常フォルダは
        // ensure_folder_rating_counter がそもそも worker を起動せずカウントが空なので
        // 自然に None になる。検索結果 drilled view は search_drilled_folder_counts を
        // 常に保持しているため、ここで明示的に揃える必要がある。
        if !self.rating_filter_active() {
            return None;
        }
        let path = match self.items.get(idx)? {
            GridItem::Folder(p) | GridItem::ZipFile(p) | GridItem::PdfFile(p) => p,
            _ => return None,
        };
        let key = crate::adjustment_db::normalize_path(path);
        // Codex P1-2 fix: effective filter で ★一時解除中の表示に整合させる
        let rf_owned = self.effective_rating_filter();
        let rf = &rf_owned;
        // 合成 drilled view (検索結果一覧そのもの) のときだけ search_drilled_folder_counts
        // を参照する。Ctrl+G 経由で実フォルダ/ZIP/PDF を開いた実体ビューでは
        // items_are_global_search_view=false になっており、items は実体側の中身なので
        // 検索ヒット由来のキャッシュを引くと別フォルダの件数を流用してしまう。
        let in_global_drilled = self.global_search.active
            && self.items_are_global_search_view
            && self.global_search.drill.is_some();
        // tooltip 用 per_star は ★1..★5 (旧インターフェース維持)。
        let per_star: [u32; 5] = if in_global_drilled {
            let counts6 = *self.search_drilled_folder_counts.get(&key)?;
            [counts6[1], counts6[2], counts6[3], counts6[4], counts6[5]]
        } else {
            *self.folder_rating_counts.get(&key)?
        };
        // rating_filter[i+1] が ★(i+1) に対応。rf[0] は未評価フィルタなので無視。
        let total: u32 = (0..5)
            .filter(|i| *rf.get(i + 1).unwrap_or(&true))
            .map(|i| per_star[i])
            .sum();
        // 0 件はバッジ表示しない (「0→N」遷移で UI が揺れないように)。
        if total == 0 {
            return None;
        }
        Some((total, per_star))
    }

    /// rating が変わったとき、子孫集計に反映する。
    ///
    /// スキャン完了後 (`loaded=true`) なら old→new の delta で直下コンテナに増減を加える。
    /// スキャン進行中は、worker の batch と bump の加算順序で二重計上・取りこぼしが起きる
    /// (Codex レビュー P1) ので、局所 bump は諦めて worker を restart する。
    pub(crate) fn apply_rating_delta_to_folder_counts(
        &mut self,
        key: &str,
        old_stars: u8,
        new_stars: u8,
    ) {
        if old_stars == new_stars {
            return;
        }
        if self.folder_rating_counts_folder_key.is_none() {
            return;
        }
        if !self.folder_rating_counts_loaded {
            // スキャン中は restart で確実に最新値を反映させる。handle を落として
            // folder_key もクリアすることで次フレームの ensure_folder_rating_counter が
            // まっさらに spawn しなおす。
            self.reset_folder_rating_counts();
            return;
        }
        let folder_key = self.folder_rating_counts_folder_key.clone().unwrap();
        let prefix = format!("{folder_key}/");
        let Some(agg_key) =
            crate::folder_rating_counter::aggregation_key_for(key, &prefix).map(|s| s.to_string())
        else {
            return;
        };
        let entry = self
            .folder_rating_counts
            .entry(agg_key)
            .or_insert([0u32; 5]);
        if (1..=5).contains(&old_stars) {
            let i = (old_stars - 1) as usize;
            entry[i] = entry[i].saturating_sub(1);
        }
        if (1..=5).contains(&new_stars) {
            let i = (new_stars - 1) as usize;
            entry[i] = entry[i].saturating_add(1);
        }
    }

    /// フォルダ読み込み直後に rating_cache を一括プリウォームする。
    /// 単発の SELECT を N 回投げる代わりに `WHERE path IN (...)` を 1 回で済ませる。
    /// 結果に含まれないキーは 0 (未評価) としてキャッシュに入れ、以後の DB アクセスを抑制する。
    /// ページ単位とコンテナの両方を対象とする。
    pub(crate) fn prewarm_rating_cache(&mut self) {
        if self.rating_db.is_none() {
            return;
        }
        let mut idx_keys: Vec<(usize, String)> = Vec::with_capacity(self.items.len());
        for (idx, item) in self.items.iter().enumerate() {
            if !item.accepts_rating() {
                continue;
            }
            if let Some(k) = self.rating_path_key(idx) {
                idx_keys.push((idx, k));
            }
        }
        let keys: Vec<String> = idx_keys.iter().map(|(_, k)| k.clone()).collect();
        let map = self
            .rating_db
            .as_ref()
            .map(|db| db.get_many(&keys))
            .unwrap_or_default();
        for (idx, key) in idx_keys {
            let stars = map.get(&key).copied().unwrap_or(0);
            self.rating_cache.insert(idx, stars);
        }
    }

    /// Shift+F1〜F6 / アドレスバー★が対象にする「現在表示中コンテナ」の
    /// rating DB キーと、Undo/XMP 判定用の source path を返す。
    ///
    /// 通常フォルダ / ZIP / PDF / RAR 等は従来どおりユーザー視点のコンテナ。
    /// ネスト ZIP ツリー内では
    /// - ルート表示: 外側 ZIP 本体。RAR/7z/LZH 変換キャッシュ閲覧中は元アーカイブ
    /// - 本の中: BS で戻った親階層に表示される `ZipDir` セルと同じ合成キー
    /// を使う。collapse で `bookB/only/` まで自動降下していても、親セルが `bookB/`
    /// なら `root\bookB` に保存する。
    pub(crate) fn current_container_rating_target(
        &self,
    ) -> Option<(String, PathBuf, crate::rating_db::RatingMeta)> {
        use crate::rating_db::{RatingItemKind, RatingMeta};
        if self.global_search.active {
            return None;
        }
        if let Some(nav) = self.zip_nav.as_ref() {
            let root = zip_rating_root_path(
                &nav.tree.zip_path,
                self.archive_source_override.as_deref(),
                self.current_folder.as_deref(),
            );
            let (key_path, meta) = if nav.at_root() {
                let kind = archive_rating_kind_for_path(root);
                let mut meta = RatingMeta::new(kind).with_source_path(root);
                if kind == RatingItemKind::ConvertibleArchive
                    && let Some(format) = archive_format_for_rating_path(root)
                {
                    meta.archive_format = Some(archive_format_to_rating_str(format).to_string());
                }
                (root.to_path_buf(), meta)
            } else {
                let prefix = nav.current_parent_zipdir_prefix()?;
                let key_path = book_container_key_from_segs(root, &prefix);
                let dir_prefix = prefix.join("/");
                let dir_prefix = if dir_prefix.is_empty() {
                    dir_prefix
                } else {
                    format!("{dir_prefix}/")
                };
                let mut meta = RatingMeta::new(RatingItemKind::ZipDir).with_source_path(root);
                meta.dir_prefix = Some(dir_prefix.clone());
                meta.zipdir_is_archive = Some(zipdir_prefix_is_archive(&dir_prefix));
                (key_path, meta)
            };
            return Some((
                crate::adjustment_db::normalize_path(&key_path),
                root.to_path_buf(),
                meta,
            ));
        }
        let folder = self.current_folder.as_ref()?;
        // 検索結果 / 閲覧履歴 / レーティング一覧の擬似パスは実コンテナではない。
        if is_synthetic_view_path(folder) {
            return None;
        }
        let kind = archive_rating_kind_for_path(folder);
        let mut meta = RatingMeta::new(kind).with_source_path(folder);
        if kind == RatingItemKind::ConvertibleArchive
            && let Some(format) = archive_format_for_rating_path(folder)
        {
            meta.archive_format = Some(archive_format_to_rating_str(format).to_string());
        }
        Some((
            crate::adjustment_db::normalize_path(folder),
            folder.clone(),
            meta,
        ))
    }

    pub(crate) fn current_container_rating_key_and_source(&self) -> Option<(String, PathBuf)> {
        self.current_container_rating_target()
            .map(|(key, source, _)| (key, source))
    }

    /// 現在一覧表示中のコンテナ (フォルダ / ZIP / PDF / ネスト ZIP の本) の
    /// レーティングを取得する。
    /// アドレスバー右端の★表示で毎フレーム呼ばれるため、`current_folder_rating_cache`
    /// でメモ化して SQLite クエリと path 正規化コストを回避する。
    /// 検索結果ビューなど、実在しない合成パスに対しては 0 を返す。
    /// Ctrl+G 検索中は `current_folder` が検索前のフォルダを指したままなので、
    /// 直前に開いていた実フォルダの★が表示されないように 0 を返す。
    pub(crate) fn current_folder_rating(&mut self) -> u8 {
        if let Some(v) = self.current_folder_rating_cache {
            return v;
        }
        let value = self
            .current_container_rating_key_and_source()
            .and_then(|(key, _)| self.rating_db.as_ref().map(|db| db.get(&key)))
            .unwrap_or(0);
        self.current_folder_rating_cache = Some(value);
        value
    }

    pub(crate) fn invalidate_rating_counts_cache(&mut self) {
        self.rating_counts_cache = None;
    }

    pub(crate) fn rating_counts(&mut self) -> Option<[usize; 6]> {
        if self.rating_counts_cache.is_none() {
            self.rating_counts_cache = self
                .rating_db
                .as_ref()
                .and_then(|db| db.count_by_stars().ok());
        }
        self.rating_counts_cache
    }

    /// Shift+F1〜F6 成功時のトースト表示 (グリッド / フルスクリーン共通)。
    /// `stars == 0` は解除、1〜5 は★の並び。
    pub(crate) fn show_container_rating_toast(&mut self, stars: u8) {
        let msg = if stars == 0 {
            "[フォルダ★解除]".to_string()
        } else {
            format!("[フォルダ{}]", "★".repeat(stars as usize))
        };
        self.show_feedback_toast(msg);
    }

    /// 現在一覧表示中のコンテナにレーティングを設定する (Shift+F1〜F6 用)。
    /// 合成パス (検索結果ビュー等) はスキップして `Ok(false)` を返す。
    /// Ctrl+G 検索中は `current_folder` が検索前のフォルダを指したままなので、
    /// 直前に開いていた実フォルダを誤って書き換えないよう `Ok(false)` を返す。
    /// DB エラーは表示 cache を変えず `Err`、成功時は rating_cache も同期して
    /// visible_indices を rebuild する。
    pub(crate) fn set_current_folder_rating(&mut self, stars: u8) -> Result<bool, String> {
        self.set_current_folder_rating_internal(stars, true)
    }

    pub(crate) fn preview_current_folder_rating(&mut self, stars: u8) -> Result<bool, String> {
        self.set_current_folder_rating_internal(stars, false)
    }

    fn set_current_folder_rating_internal(
        &mut self,
        stars: u8,
        capture_undo: bool,
    ) -> Result<bool, String> {
        let Some((key, _, meta)) = self.current_container_rating_target() else {
            return Ok(false);
        };
        let stars = stars.min(5);
        // Undo 用に変更前の値をキャッシュ or DB から取得 (なければ 0)。
        let before = self
            .current_folder_rating_cache
            .or_else(|| self.rating_db.as_ref().map(|db| db.get(&key)))
            .unwrap_or(0);
        self.write_user_rating_shared(&key, stars, Some(&meta))?;
        if capture_undo && before != stars {
            self.capture_container_rating_undo(before, stars);
        }
        self.invalidate_rating_counts_cache();
        self.current_folder_rating_cache = Some(stars);
        // items 内の同じ rating key を指すコンテナがあればキャッシュ更新。
        // (1 階層上に戻ったときに cached な古い値を表示しないため。通常 current_folder は
        // items に含まれないが、search container 絞り込みビュー中は含まれうる。ZipDir も
        // 親階層に表示中なら同じ経路で同期できる。)
        let matching: Vec<usize> = self
            .items
            .iter()
            .enumerate()
            .filter_map(|(i, _)| {
                (self.rating_path_key(i).as_deref() == Some(key.as_str())).then_some(i)
            })
            .collect();
        for i in matching {
            self.rating_cache.insert(i, stars);
        }
        if before != stars {
            self.schedule_current_smart_folder_metadata_refresh(
                smart_folder::SmartFolderMetadataDependency::Rating,
            );
        }
        self.rebuild_visible_indices();
        Ok(true)
    }

    pub(crate) fn set_tags_cache_entry(&mut self, key: String, tags: Vec<String>) -> bool {
        if self.tags_cache.get(&key) == Some(&tags) {
            return false;
        }
        self.tags_cache.insert(key, tags);
        DetailsCellContentRevisions::bump(&mut self.details_cell_content_revisions.tags);
        true
    }

    pub(crate) fn clear_tags_cache(&mut self) -> bool {
        if self.tags_cache.is_empty() {
            return false;
        }
        self.tags_cache.clear();
        DetailsCellContentRevisions::bump(&mut self.details_cell_content_revisions.tags);
        true
    }

    pub(crate) fn replace_tags_cache(
        &mut self,
        replacement: std::collections::HashMap<String, Vec<String>>,
    ) {
        self.tags_cache = replacement;
        DetailsCellContentRevisions::bump(&mut self.details_cell_content_revisions.tags);
    }

    pub(crate) fn retain_tags_cache(&mut self, mut keep: impl FnMut(&String) -> bool) -> bool {
        let before = self.tags_cache.len();
        self.tags_cache.retain(|key, _| keep(key));
        if self.tags_cache.len() == before {
            return false;
        }
        DetailsCellContentRevisions::bump(&mut self.details_cell_content_revisions.tags);
        true
    }

    /// グリッドのタグバッジ表示用キャッシュを埋める。フォルダ切替時に 1 回呼ぶ。
    ///
    /// タグ正本は `tags.db`。フォルダ切替時に表示中の実パス item だけを一括取得し、
    /// 未タグ item も空 Vec として載せることで facet の「タグなし」を即判定できる。
    ///
    /// rating の opt-in XMP ハイドレーションだけは既存 `tag_prewarm` worker を使う。
    pub(crate) fn prewarm_grid_tags(&mut self) {
        // 旧プリフェッチ (別フォルダの残り) は cancel: 以降の XMP 読みを無駄にしない。
        if let Some(pending) = self.tag_prewarm_pending.take() {
            pending.cancel();
        }
        self.tag_prewarm_queued.clear();
        if let Some(pending) = self.tag_legacy_seed_pending.take() {
            pending.cancel();
        }

        let mut keys = Vec::new();
        for item in &self.items {
            if let Some(path) = tag_item_path(item) {
                keys.push(crate::tags_db::item_key_for_path(path));
            }
        }
        keys.sort();
        keys.dedup();

        if let Some(db) = self.tags_db.as_ref() {
            let mut loaded = db.get_many_display_tags(&keys);
            for key in keys {
                let tags = loaded.remove(&key).unwrap_or_default();
                self.set_tags_cache_entry(key, tags);
            }
        } else {
            for key in keys {
                self.set_tags_cache_entry(key, Vec::new());
            }
        }

        if self.settings.write_rating_to_xmp {
            self.tag_prewarm_pending = Some(crate::tag_prewarm::spawn());
        }
        self.start_tag_legacy_seed_for_current_items();
    }

    fn start_tag_legacy_seed_for_current_items(&mut self) {
        if self.items_are_global_search_view || self.items_are_tag_view {
            return;
        }
        let paths = self
            .items
            .iter()
            .enumerate()
            .filter(|(idx, _)| !self.idx_is_compiled_book_page(*idx))
            .filter_map(|(_, item)| match item {
                GridItem::Image(path) | GridItem::Video(path) => Some(path.clone()),
                _ => None,
            })
            .collect::<Vec<_>>();
        self.start_tag_legacy_seed(paths);
    }

    fn start_tag_legacy_seed(&mut self, paths: Vec<PathBuf>) {
        if self.tags_db.is_none() {
            return;
        }
        if paths.is_empty() {
            return;
        }
        self.tag_legacy_seed_pending = Some(crate::tag_legacy_seed_worker::spawn(
            crate::data_dir::get(),
            paths,
        ));
    }

    /// 毎フレーム呼ぶ: 現在の画面付近にある Image のうち、rating DB が未登録のものを
    /// XMP rating hydration worker に push する。
    ///
    /// サムネモードは `keep_set` (可視範囲 + prev/next ページの display list 部分列) を使う。
    /// 詳細モードはサムネ要求抑制のため `keep_set` が空なので、`render_details_list` が
    /// 記録した詳細行の可視近傍を使う。
    /// `tag_prewarm_queued` (idx セット) で二重 push を防ぐので、毎フレームの走査は
    /// ~175 件 × HashSet lookup で十分軽い (過去は keep_range bounding box 比較で
    /// アイドルフレームを早期終了していたが、フィルタ変更で bbox 不変 × 内部構成変化 の
    /// ケースを取り逃す不具合があり廃止した)。
    pub(crate) fn enqueue_visible_tag_prewarms(&mut self) {
        // 削除進行中は新規 XMP プリウォームを停止。削除予定パスを worker が読もうとすると
        // File::open が失敗して無駄なキャッシュ汚染や redundant log になる。
        if self.delete_pending.is_some() {
            return;
        }
        let Some(pending) = self.tag_prewarm_pending.as_ref() else {
            return;
        };
        let targets = if self.settings.grid_view_mode == crate::settings::GridViewMode::Details {
            if self.details_tag_prewarm_indices.is_empty() {
                self.current_grid_order()
                    .iter()
                    .copied()
                    .take(128)
                    .collect::<Vec<_>>()
            } else {
                self.details_tag_prewarm_indices.clone()
            }
        } else {
            if self.keep_set.is_empty() {
                return;
            }
            self.keep_set_sorted()
        };
        for idx in targets {
            if idx >= self.items.len() {
                continue;
            }
            if self.idx_is_compiled_book_page(idx) {
                self.tag_prewarm_queued.insert(idx);
                continue;
            }
            // idx ベースで dedup: 処理済み idx は cache_key 文字列を組み立てずスキップ。
            if self.tag_prewarm_queued.contains(&idx) {
                continue;
            }
            let p = match self.items.get(idx) {
                Some(GridItem::Image(p)) => p,
                _ => {
                    // 非 Image は XMP rating hydration 対象外。
                    self.tag_prewarm_queued.insert(idx);
                    continue;
                }
            };
            if !crate::xmp_writer::is_writable_format(p) {
                self.tag_prewarm_queued.insert(idx);
                continue;
            }
            // 設定 ON かつ DB で rating 未登録 (= 0) のときだけ XMP から rating を読んで
            // ハイドレートする。既に DB に値がある場合は XMP 読みを節約。
            let read_rating = self.settings.write_rating_to_xmp
                && self.rating_cache.get(&idx).copied().unwrap_or(0) == 0;
            if !read_rating {
                self.tag_prewarm_queued.insert(idx);
                continue;
            }
            self.tag_prewarm_queued.insert(idx);
            let key = crate::adjustment_db::normalize_path(p);
            pending.push_job(p.clone(), self.rating_session_generation_for_key(&key));
        }
    }

    /// `tag_prewarm` ワーカーからの XMP rating hydration 結果を UI スレッドで回収する。
    /// 毎フレーム `App::update` から呼ぶ。`on_result_drained` で in_flight を減らし、
    /// 残ジョブがあれば呼び出し側が `request_repaint()` する。
    pub(crate) fn poll_tag_prewarm_results(&mut self) {
        let Some(pending) = self.tag_prewarm_pending.as_ref() else {
            return;
        };
        // このフレームで届いた分だけ drain。
        let mut rating_hydrations: Vec<(PathBuf, u8, u64)> = Vec::new();
        loop {
            match pending.rx.try_recv() {
                Ok(res) => {
                    // XMP から rating > 0 が読めたらハイドレート候補に積む
                    // (DB を UI スレッドで触らないように後段でまとめて書く)。
                    if let Some(stars) = res.rating {
                        if stars > 0 {
                            rating_hydrations.push((
                                res.path.clone(),
                                stars,
                                res.rating_generation,
                            ));
                        }
                    }
                    pending.on_result_drained();
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => break,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    self.tag_prewarm_pending = None;
                    break;
                }
            }
        }
        // DB + rating_cache に反映。既に DB に非ゼロ値があれば (= ユーザーが mIV で
        // 付けた値) 上書きしない (旧ファイル移動先 → 新フォルダで XMP ハイドレートを
        // 期待するのは DB が 0 = 未登録のときだけ)。
        if !rating_hydrations.is_empty() {
            self.hydrate_ratings_from_xmp(rating_hydrations);
        }
    }

    pub(crate) fn poll_tag_legacy_seed_results(&mut self) {
        let Some(pending) = self.tag_legacy_seed_pending.as_ref() else {
            return;
        };
        match pending.rx.try_recv() {
            Ok(Ok(result)) => {
                self.tag_legacy_seed_pending = None;
                self.apply_tag_legacy_seed_result(result);
            }
            Ok(Err(msg)) => {
                self.tag_legacy_seed_pending = None;
                crate::logger::log(format!("[TAG] legacy seed failed: {msg}"));
            }
            Err(std::sync::mpsc::TryRecvError::Empty) => {}
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                self.tag_legacy_seed_pending = None;
            }
        }
    }

    fn apply_tag_legacy_seed_result(
        &mut self,
        result: crate::tag_legacy_seed_worker::LegacySeedResult,
    ) {
        let report = result.report.clone();
        let mut changed = false;
        for (path, tags) in result.cache_updates {
            let key = crate::tags_db::item_key_for_path(&path);
            self.set_tags_cache_entry(key, tags.clone());
            if let Some(target) = crate::tag_write_worker::sidecar_target_for_real_file(&path) {
                self.mirror_tag_sidecar_update(&target, &tags);
            }
            changed = true;
        }
        if changed {
            self.schedule_current_smart_folder_metadata_refresh(
                smart_folder::SmartFolderMetadataDependency::Tags,
            );
        }
        if changed && self.settings.facet_filter.uses_tag_state() {
            self.rebuild_visible_indices_preserving_facet_scope();
        }
        if report.imported_items > 0
            || report.marked_empty_items > 0
            || report.read_errors > 0
            || report.db_errors > 0
        {
            crate::logger::log(format!(
                "[TAG] legacy seed complete: candidates={} read={} imported_items={} \
                 inserted_tags={} marked_empty={} skipped_decided={} read_errors={} db_errors={}",
                report.candidate_items,
                report.read_items,
                report.imported_items,
                report.inserted_tags,
                report.marked_empty_items,
                report.skipped_decided_items,
                report.read_errors,
                report.db_errors
            ));
        }
    }

    /// tag_prewarm から回収した XMP 由来 rating を rating_db + rating_cache に反映する。
    /// DB に非ゼロ値がある idx はスキップ (mIV 側で付けた値を XMP で踏まない)。
    ///
    /// 実装: normalize_path を 1 回だけ走らせ、items の逆引き HashMap を 1 回構築、
    /// `db.get_many` でバッチ SELECT、何も変化しなければ `rebuild_visible_indices` は
    /// 呼ばない (大フォルダで UI スレッドに来たときの per-frame 再構築コスト回避)。
    fn hydrate_ratings_from_xmp(&mut self, hydrations: Vec<(PathBuf, u8, u64)>) {
        let Some(db) = self.rating_db.as_ref() else {
            return;
        };
        if hydrations.is_empty() {
            return;
        }
        // key → (XMP 由来★, 元 path, request 開始時の path 世代) の最終マップ。
        let mut target: std::collections::HashMap<String, (u8, PathBuf, u64)> =
            std::collections::HashMap::with_capacity(hydrations.len());
        for (path, stars, generation) in hydrations {
            target.insert(
                crate::adjustment_db::normalize_path(&path),
                (stars, path, generation),
            );
        }
        // DB の現在値を 1 クエリでまとめて引く
        let keys: Vec<String> = target.keys().cloned().collect();
        let current = db.get_many(&keys);
        // DB が 0 (未登録) のエントリだけ実際にハイドレート対象にする。
        // request 後に同じ path へ書き込みがあれば世代不一致で破棄する。さらに、request
        // 開始前の明示クリアも XMP writer より古い値を読めるため、最新ユーザー値が 0 の
        // path は同世代でも取り込まない。
        let mut to_write: Vec<(String, u8, PathBuf)> = Vec::new();
        for (key, (stars, path, started_generation)) in &target {
            let session_write = self.rating_session_writes.get(key).copied();
            let current_generation = session_write.map(|write| write.generation).unwrap_or(0);
            let explicitly_cleared =
                session_write.is_some_and(|write| write.explicit_user && write.stars == 0);
            if current.get(key).copied().unwrap_or(0) == 0
                && current_generation == *started_generation
                && !explicitly_cleared
            {
                to_write.push((key.clone(), *stars, path.clone()));
            }
        }
        if to_write.is_empty() {
            return;
        }
        let write_keys: std::collections::HashSet<&String> =
            to_write.iter().map(|(k, _, _)| k).collect();
        // items の逆引き: path → idx (Image だけ)
        for (idx, item) in self.items.iter().enumerate() {
            if let GridItem::Image(p) = item {
                let k = crate::adjustment_db::normalize_path(p);
                if write_keys.contains(&k) {
                    let stars = target[&k].0;
                    self.rating_cache.insert(idx, stars);
                }
            }
        }
        let mut rating_written = false;
        let mut imported_writes = Vec::new();
        for (key, stars, path) in &to_write {
            let meta = crate::rating_db::RatingMeta::new(crate::rating_db::RatingItemKind::Image)
                .with_source_path(path);
            if db.set_imported_rating(key, *stars, Some(&meta)).is_ok() {
                rating_written = true;
                imported_writes.push((key.clone(), *stars));
            }
        }
        for (key, stars) in imported_writes {
            self.record_rating_session_write(key, stars, false);
        }
        self.sync_current_context_rating_session_writes();
        if rating_written {
            self.schedule_current_smart_folder_metadata_refresh(
                smart_folder::SmartFolderMetadataDependency::Rating,
            );
        }
        self.invalidate_rating_counts_cache();
        // 子孫★集計バッジにも反映 (to_write は DB が 0 だった path のみ = old_stars=0)。
        for (key, stars, _) in &to_write {
            self.apply_rating_delta_to_folder_counts(key, 0, *stars);
        }
        // 実際に rating_cache が更新されたのでフィルタ影響あり
        self.rebuild_visible_indices_preserving_facet_scope();
    }

    /// 指定 idx の grid cell に描くタグ列。`tags_cache` のみを引く (同期 I/O を避ける)。
    /// キャッシュに載っていない = 未ロード → 空を返す (バッジ非表示)。
    pub(crate) fn cell_tag_list(&self, idx: usize) -> &[String] {
        let p = match self.items.get(idx).and_then(tag_item_path) {
            Some(p) => p,
            _ => return &[],
        };
        let key = crate::tags_db::item_key_for_path(p);
        self.tags_cache
            .get(&key)
            .map(|v| v.as_slice())
            .unwrap_or(&[])
    }

    fn cell_tags_loaded(&self, idx: usize) -> bool {
        let p = match self.items.get(idx).and_then(tag_item_path) {
            Some(p) => p,
            _ => return true,
        };
        let key = crate::tags_db::item_key_for_path(p);
        self.tags_cache.contains_key(&key)
            || self.items_are_subfolder_expansion_view
            || self.items_are_smart_folder_view
    }

    /// F 系・Ctrl+Num 系の一括適用で使う、グリッド上の対象 idx を決める共通規則。
    /// チェック済みがあればそれら、無ければカーソル位置 (selected)、それも無ければ空。
    /// 述語で「受け入れる GridItem 種別」を切り替える:
    /// - レーティング (F1〜F6) は `accepts_rating` (コンテナ含む)
    /// - 補正プリセット / マスクスロット (Ctrl+1〜0 / F7F8) は `has_page_data` (ページ専用)
    ///
    /// `rebuild_visible_indices` が `checked` / `selected` を可視範囲内に保つ不変条件を
    /// 維持しているが、`load_folder` の履歴復元で `selected` を後から差し戻すケース等で
    /// 一時的に非可視な idx を指す可能性があるので、ここでも `idx_visible` で防御する。
    fn targets_matching(&self, pred: impl Fn(&GridItem) -> bool) -> Vec<usize> {
        if !self.checked.is_empty() {
            self.checked
                .iter()
                .copied()
                .filter(|&idx| self.idx_visible(idx) && self.items.get(idx).is_some_and(&pred))
                .collect()
        } else if let Some(idx) = self.selected
            && self.idx_visible(idx)
            && self.items.get(idx).is_some_and(&pred)
        {
            vec![idx]
        } else {
            Vec::new()
        }
    }

    fn ratable_targets(&self) -> Vec<usize> {
        self.targets_matching(GridItem::accepts_rating)
    }

    fn ratable_page_targets(&self) -> Vec<usize> {
        self.targets_matching(GridItem::has_page_data)
    }

    /// グリッド画面から F7/F8 で呼ばれる消しゴムマスクスロット一括適用。
    /// 実際の inpaint は各ページをフルスクリーンで開いたときに `auto_apply_saved_mask`
    /// が走る。ここでは DB + サイドカーにスロットの内容 (ビットマップ + ベクタ) を
    /// 書き込むだけで十分。
    pub(crate) fn apply_slot_to_selection(&mut self, slot: usize) {
        let targets = self.ratable_page_targets();

        if targets.is_empty() {
            self.show_feedback_toast("[適用対象なし]".to_string());
            return;
        }

        // スロットのデータを一度だけ取得 (元サイズのまま)。
        // 各ページに書き込むとき w/h はスロットの元サイズとして記録し、
        // フルスクリーンで開かれたときに get_full 側で自動リスケールされる。
        let (slot_bitmap, slot_vectors, sw, sh) = match self.mask_db.as_ref() {
            Some(db) => {
                let Some((sw, sh)) = db.slot_size(slot) else {
                    self.show_feedback_toast(format!("[消しゴムスロット{slot}は空です]"));
                    return;
                };
                let Some((mask, vectors)) = db.get_slot_full(slot, sw, sh) else {
                    self.show_feedback_toast(format!("[消しゴムスロット{slot}は空です]"));
                    return;
                };
                if !mask.iter().any(|&m| m) && vectors.is_empty() {
                    self.show_feedback_toast(format!("[消しゴムスロット{slot}は空です]"));
                    return;
                }
                (mask, vectors, sw, sh)
            }
            None => {
                self.show_feedback_toast("[マスクDB未初期化]".to_string());
                return;
            }
        };

        // 圧縮・JSON 化はループ外で 1 回だけ: N ページに同じマスクを配るので
        // deflate を共有する (N=100 等で実測効果が大きい)。
        let compressed = crate::mask_db::compress_mask(&slot_bitmap);
        let shapes_json = crate::mask_db::shapes_to_json(&slot_vectors);
        let total = targets.len();
        for idx in &targets {
            // フルスクリーンで現在これらのページを開いている可能性は低い (grid モード) が、
            // 念のため inpaint 結果キャッシュを落として次回開いたときに再適用させる。
            self.erase_base_cache.remove(idx);
            self.clear_erase_result_caches_for_idx(*idx);
            self.conceal_base_cache.remove(idx);
            self.conceal_cache.remove(idx);
            self.comic_cache.remove(idx);
            self.save_mask_raw_with_sidecar(
                *idx,
                &compressed,
                &slot_vectors,
                shapes_json.as_deref(),
                sw,
                sh,
            );
        }

        self.checked.clear();
        crate::logger::log(format!("[ERASE] Bulk apply slot {slot} to {total} items"));
        self.show_feedback_toast(format!("[消しゴムスロット{slot}を{total}枚に適用]"));
    }

    fn load_conceal_slot_payload(
        &mut self,
        slot: usize,
    ) -> Option<(Vec<bool>, Vec<crate::mask_db::Shape>, usize, usize)> {
        match self.conceal_db.as_ref() {
            Some(db) => {
                let Some((sw, sh)) = db.slot_size(slot) else {
                    self.show_feedback_toast(format!("[隠蔽スロット{slot}は空です]"));
                    return None;
                };
                let Some((mask, shapes)) = db.get_slot_full(slot, sw, sh) else {
                    self.show_feedback_toast(format!("[隠蔽スロット{slot}は空です]"));
                    return None;
                };
                if !mask.iter().any(|&m| m) && shapes.is_empty() {
                    self.show_feedback_toast(format!("[隠蔽スロット{slot}は空です]"));
                    return None;
                }
                Some((mask, shapes, sw, sh))
            }
            None => {
                self.show_feedback_toast("[隠蔽DB未初期化]".to_string());
                None
            }
        }
    }

    /// グリッド画面から F9/F10 で呼ばれる隠蔽マスクスロット一括適用。
    /// 隠蔽は inpaint worker を持たないため、DB + サイドカーへ保存して
    /// 表示キャッシュを破棄すれば次回表示で合成される。
    pub(crate) fn apply_conceal_slot_to_selection(&mut self, slot: usize) {
        let targets = self.ratable_page_targets();

        if targets.is_empty() {
            self.show_feedback_toast("[適用対象なし]".to_string());
            return;
        }

        let Some((slot_bitmap, slot_shapes, sw, sh)) = self.load_conceal_slot_payload(slot) else {
            return;
        };

        let compressed = crate::mask_db::compress_mask(&slot_bitmap);
        let shapes_json = crate::mask_db::shapes_to_json(&slot_shapes);
        let total = targets.len();
        for idx in &targets {
            self.clear_conceal_caches(*idx);
            self.conceal_base_cache.remove(idx);
            self.save_conceal_raw_with_sidecar(
                *idx,
                &compressed,
                &slot_shapes,
                shapes_json.as_deref(),
                sw,
                sh,
            );
        }

        self.checked.clear();
        crate::logger::log(format!("[CONCEAL] Bulk apply slot {slot} to {total} items"));
        self.show_feedback_toast(format!("[隠蔽スロット{slot}を{total}枚に適用]"));
    }

    /// フルスクリーン表示中 (隠蔽加工モード外) で F9/F10 から呼ばれる。
    /// スロット N の隠蔽マスクを現ページへ差し替えて保存する。
    pub(crate) fn apply_conceal_slot_in_viewing_mode(&mut self, slot: usize) {
        if self.is_overlay_edit_mode_active() {
            return;
        }
        let Some(fs_idx) = self.fullscreen_idx else {
            return;
        };
        if !self.items.get(fs_idx).is_some_and(GridItem::has_page_data) {
            self.show_feedback_toast("[適用対象なし]".to_string());
            return;
        }

        let Some((slot_bitmap, slot_shapes, sw, sh)) = self.load_conceal_slot_payload(slot) else {
            return;
        };
        let compressed = crate::mask_db::compress_mask(&slot_bitmap);
        let shapes_json = crate::mask_db::shapes_to_json(&slot_shapes);
        self.clear_conceal_caches(fs_idx);
        self.conceal_base_cache.remove(&fs_idx);
        self.save_conceal_raw_with_sidecar(
            fs_idx,
            &compressed,
            &slot_shapes,
            shapes_json.as_deref(),
            sw,
            sh,
        );

        crate::logger::log(format!(
            "conceal: apply_conceal_slot_in_viewing_mode slot={slot} idx={fs_idx}"
        ));
        self.show_feedback_toast(format!("[隠蔽スロット{slot}適用]"));
    }

    /// フルスクリーン表示中に適用済み消しゴムマスクを削除する。
    pub(crate) fn delete_erase_mask_in_viewing_mode(&mut self) {
        if self.is_overlay_edit_mode_active() {
            return;
        }
        let Some(fs_idx) = self.fullscreen_idx else {
            return;
        };
        if !self.items.get(fs_idx).is_some_and(GridItem::has_page_data) {
            self.show_feedback_toast("[削除対象なし]".to_string());
            return;
        }

        let had_mask = self.mask_pages.contains(&fs_idx);
        self.delete_mask_with_sidecar(fs_idx);
        self.clear_erase_result_caches_for_idx(fs_idx);
        self.erase_base_cache.remove(&fs_idx);
        self.erase_base_tex_cache.remove(&fs_idx);
        self.clear_conceal_caches(fs_idx);
        self.conceal_base_cache.remove(&fs_idx);

        if had_mask {
            self.show_feedback_toast("[消しゴムマスク削除]".to_string());
        } else {
            self.show_feedback_toast("[消しゴムマスクなし]".to_string());
        }
    }

    /// フルスクリーン表示中に適用済み隠蔽マスクを削除する。
    pub(crate) fn delete_conceal_mask_in_viewing_mode(&mut self) {
        if self.is_overlay_edit_mode_active() {
            return;
        }
        let Some(fs_idx) = self.fullscreen_idx else {
            return;
        };
        if !self.items.get(fs_idx).is_some_and(GridItem::has_page_data) {
            self.show_feedback_toast("[削除対象なし]".to_string());
            return;
        }

        let had_mask = self.conceal_pages.contains(&fs_idx);
        self.delete_conceal_with_sidecar(fs_idx);
        self.clear_conceal_caches(fs_idx);
        self.conceal_base_cache.remove(&fs_idx);

        if had_mask {
            self.show_feedback_toast("[隠蔽マスク削除]".to_string());
        } else {
            self.show_feedback_toast("[隠蔽マスクなし]".to_string());
        }
    }

    /// グリッド画面から Shift+F7/F8 で呼ばれる消しゴムマスク一括削除。
    pub(crate) fn delete_erase_masks_from_selection(&mut self) {
        let targets = self.ratable_page_targets();
        if targets.is_empty() {
            self.show_feedback_toast("[削除対象なし]".to_string());
            return;
        }

        let mut removed = 0usize;
        for idx in &targets {
            if self.mask_pages.contains(idx) {
                removed += 1;
            }
            self.delete_mask_with_sidecar(*idx);
            self.clear_erase_result_caches_for_idx(*idx);
            self.erase_base_cache.remove(idx);
            self.erase_base_tex_cache.remove(idx);
            self.clear_conceal_caches(*idx);
            self.conceal_base_cache.remove(idx);
        }

        self.checked.clear();
        if removed == 0 {
            self.show_feedback_toast("[消しゴムマスクなし]".to_string());
        } else {
            crate::logger::log(format!("[ERASE] Bulk delete masks from {removed} items"));
            self.show_feedback_toast(format!("[消しゴムマスクを{removed}枚から削除]"));
        }
    }

    /// グリッド画面から Shift+F9/F10 で呼ばれる隠蔽マスク一括削除。
    pub(crate) fn delete_conceal_masks_from_selection(&mut self) {
        let targets = self.ratable_page_targets();
        if targets.is_empty() {
            self.show_feedback_toast("[削除対象なし]".to_string());
            return;
        }

        let mut removed = 0usize;
        for idx in &targets {
            if self.conceal_pages.contains(idx) {
                removed += 1;
            }
            self.delete_conceal_with_sidecar(*idx);
            self.clear_conceal_caches(*idx);
            self.conceal_base_cache.remove(idx);
        }

        self.checked.clear();
        if removed == 0 {
            self.show_feedback_toast("[隠蔽マスクなし]".to_string());
        } else {
            crate::logger::log(format!("[CONCEAL] Bulk delete masks from {removed} items"));
            self.show_feedback_toast(format!("[隠蔽マスクを{removed}枚から削除]"));
        }
    }

    pub(crate) fn apply_rating_to_selection(&mut self, stars: u8) {
        if self.items_are_drive_list {
            return;
        }
        let stars = stars.min(5);
        let targets = self.ratable_targets();
        if targets.is_empty() {
            return;
        }
        // DB write に成功した項目だけを Undo / 派生ビュー更新の対象にする。失敗項目を
        // optimistic cache や undo stack へ公開しない。
        let mut pending_records: Vec<(usize, u8, u8)> = Vec::with_capacity(targets.len());
        for &idx in &targets {
            let before = self.rating_cache.get(&idx).copied().unwrap_or(0);
            pending_records.push((idx, before, stars));
        }
        let mut successful_targets = Vec::with_capacity(targets.len());
        let mut undo_records = Vec::with_capacity(targets.len());
        let mut first_error = None;
        for record @ (idx, _, _) in pending_records {
            match self.set_rating_result(idx, stars) {
                Ok(true) => {
                    successful_targets.push(idx);
                    undo_records.push(record);
                }
                Ok(false) => {}
                Err(error) => {
                    first_error.get_or_insert(error);
                }
            }
        }
        if let Some(error) = first_error {
            self.report_rating_write_error(&error);
        }
        if successful_targets.is_empty() {
            return;
        }
        let summary = if successful_targets.len() > 1 {
            if stars == 0 {
                format!("★解除を {} 件に適用", successful_targets.len())
            } else {
                format!("★{stars} を {} 件に付与", successful_targets.len())
            }
        } else if stars == 0 {
            "★解除".to_string()
        } else {
            format!("★{stars}")
        };
        self.capture_rating_undo(undo_records, summary);
        let rating_view_changes: Vec<(String, u8)> = if self.items_are_rating_view {
            successful_targets
                .iter()
                .filter_map(|&idx| self.rating_path_key(idx).map(|key| (key, stars)))
                .collect()
        } else {
            Vec::new()
        };
        let bulk = successful_targets.len() > 1;
        if bulk {
            crate::logger::log(format!(
                "[RATING] Bulk apply {stars} stars to {} items",
                successful_targets.len(),
            ));
            self.checked.clear();
        } else {
            crate::logger::log(format!(
                "[RATING] Set {stars} stars on idx {}",
                successful_targets[0]
            ));
        }
        // Ctrl+G ヒットの stars はバッチ受信時の snapshot。レーティング変更後に
        // drilled view のサブフォルダ件数 / 枝刈りが古いまま残らないよう、
        // 該当する all_hits エントリを最新値で書き換える (Codex P3)。
        // 合成ビューを再構築するのは現在 items が合成ビュー由来のときだけ:
        // Ctrl+G から実フォルダ/ZIP/PDF を開いた直後は items が PDF ページ等の
        // 実体ビューなので、ここで rebuild_items_from_global_search を呼ぶと
        // ページ一覧が検索 drilled view の合成 items に置き換わる事故になる
        // (Codex P2)。
        if self.global_search.active {
            self.refresh_global_search_hit_stars(&successful_targets);
        }
        if self.items_are_rating_view {
            self.refresh_rating_view_after_rating_changes(&rating_view_changes);
        } else if self.global_search.active && self.items_are_global_search_view {
            self.rebuild_items_from_global_search();
        } else {
            self.rebuild_visible_indices();
        }
    }

    /// `set_rating` で書き換えた idx 群について、Ctrl+G の `all_hits` 中の対応する
    /// hit エントリの `stars` を最新値で更新する。drilled view バッジ件数 / 枝刈り /
    /// 直下ファイルフィルタが snapshot のまま古くならないようにする (Codex P3)。
    fn refresh_global_search_hit_stars(&mut self, idxs: &[usize]) {
        // 対象 idx → (rating_db キー, 新 stars) の対応を作る
        let mut updates: std::collections::HashMap<String, u8> = std::collections::HashMap::new();
        for &idx in idxs {
            let Some(key) = self.rating_path_key(idx) else {
                continue;
            };
            let new_stars = self.rating_cache.get(&idx).copied().unwrap_or(0);
            updates.insert(key, new_stars);
        }
        if updates.is_empty() {
            return;
        }
        for h in self.global_search.all_hits.iter_mut() {
            let hit_key = crate::global_search_ui::hit_rating_key(&h.path);
            if let Some(&v) = updates.get(&hit_key) {
                h.stars = v;
            }
        }
    }

    /// 現在動画の mute を反転し、セッション状態と次回起動用の保存状態にも反映する。
    /// 戻り値は `fs_idx` が生きている動画エントリだったかを表す。
    pub(crate) fn toggle_video_session_mute_for_fs_idx(&mut self, fs_idx: usize) -> bool {
        if let Some(FsCacheEntry::Video { player, .. }) = self.fs_cache.get(&fs_idx) {
            let muted = !player.is_muted();
            player.set_muted(muted);
            self.video_session_muted = muted;
            if self.settings.video_muted != muted {
                self.settings.video_muted = muted;
                self.settings.save();
            }
            true
        } else {
            false
        }
    }

    /// フルスクリーン通常 open 用の動画プレイヤーを構築する。
    fn build_video_player_for_open(
        &mut self,
        _idx: usize,
        vp: PathBuf,
        from_grid: bool,
        autoplay_override: Option<bool>,
        ignore_resume: bool,
        #[cfg(windows)] native_output_config: Option<crate::video::NativeVideoOutputConfig>,
    ) -> (crate::video::VideoPlayer, bool) {
        // 通常 open の spawn 制限は呼び出し側 (`start_fs_load` →
        // `defer_native_video_open_if_decoder_busy`) で行う。ここに到達した時点では
        // live decoder 数が上限未満か、HW decode 無効の経路。ここでは診断用に
        // open 開始時点の live 数を記録するだけにする。
        let live_before = crate::video::decoder::LIVE_VIDEO_DECODE_THREADS
            .load(std::sync::atomic::Ordering::Acquire);
        let regular_open_pressure_threshold = crate::video::decoder::MAX_LIVE_VIDEO_DECODE_THREADS;
        if live_before >= regular_open_pressure_threshold {
            crate::logger::log(format!(
                "[native-video] regular open with live_video_decode_threads={live_before} >= {regular_open_pressure_threshold}: pending gate should normally defer this open"
            ));
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "native_video",
                "regular_open_begin",
                None,
                0,
                &[
                    (
                        "live_video_decode_threads",
                        serde_json::Value::from(live_before as i64),
                    ),
                    (
                        "pressure_suspected",
                        serde_json::Value::from(live_before >= regular_open_pressure_threshold),
                    ),
                ],
            );
        }

        let vol = crate::settings::clamp_video_volume(self.settings.video_volume);
        let autoplay = autoplay_override.unwrap_or(true);
        let path_key = crate::adjustment_db::normalize_path(&vp);
        let play_test_for_video = self.play_test.as_ref().filter(|state| {
            let config_key = crate::adjustment_db::normalize_path(&state.config.path);
            config_key == path_key
        });
        let play_test_start = play_test_for_video.and_then(|state| state.config.start_secs);
        let play_test_mute = play_test_for_video.is_some_and(|state| state.config.mute);
        let saved_resume = self.settings.video_resume_positions.get(&path_key).copied();
        let resume = if ignore_resume {
            play_test_start
        } else {
            play_test_start.or_else(|| {
                video_resume_for_open(
                    saved_resume,
                    from_grid,
                    self.settings.video_grid_open_starts_from_beginning,
                    self.settings.video_nav_resume,
                )
            })
        };
        let video_hw_decode = self.settings.video_hw_decode;
        let video_deinterlace = self.settings.video_deinterlace;
        let initial_normalize_lookup = if self.settings.audio_normalize_enabled {
            let target_milli = self.settings.clamped_audio_normalize_target_lufs_milli();
            self.audio_normalize_db
                .as_ref()
                .and_then(|db| db.lookup(&vp, target_milli))
        } else {
            None
        };
        let initial_normalize_gain = initial_normalize_lookup
            .as_ref()
            .map(|result| 10.0_f64.powf(result.gain_db as f64 / 20.0))
            .unwrap_or(1.0);
        let start_normalize_scan_before_play =
            self.settings.audio_normalize_enabled && initial_normalize_lookup.is_none() && autoplay;
        let open_autoplay = autoplay && !start_normalize_scan_before_play;
        let player = crate::video::VideoPlayer::open(
            vp,
            vol,
            initial_normalize_gain,
            start_normalize_scan_before_play,
            open_autoplay,
            resume,
            video_hw_decode,
            video_deinterlace,
            #[cfg(windows)]
            if video_hw_decode {
                self.gpu_video_device.clone()
            } else {
                None
            },
            #[cfg(windows)]
            Some(self.dsp_bridge.clone()),
            #[cfg(windows)]
            native_output_config,
        );
        player.set_playback_speed(self.video_playback_speed);
        if play_test_mute || self.video_session_muted {
            player.set_muted(true);
        }
        (player, start_normalize_scan_before_play)
    }

    /// 音楽ビューを開いている間、対象パスのタイムライン解析を確実に走らせる (Inc 3b)。
    ///
    /// 契機は「音楽ビューを開いたとき」。フォルダ閲覧のたびに全音声を pre-decode するのは
    /// 無駄なので、ここで初めて起動する (docs/music-integration-plan.md Inc 3)。開いている
    /// ファイルが変わったら旧ワーカーを cancel し、row raster cache を clear して作り直す。
    ///
    /// `meta` は `image_metas[idx]` の (mtime, size)。in-memory LRU のルックアップ (楽観的な即
    /// 表示) に使う。ヒットすればタイムラインを即表示 (`want_analysis=false`)、miss なら
    /// decode+analyze 完了まで待つ。UI スレッドでは `std::fs::metadata` しない (Codex 設計 P2):
    /// ルックアップキーは既に持っている `image_metas` から作る。ただし `image_metas` は
    /// フォルダスキャン時点のスナップショットなので、ワーカーが背景で fresh stat して検証し、
    /// ヒットに使った (mtime,size) と食い違えば解析し直す (Codex code P2 = 外部更新の stale ヒット
    /// 補正)。LRU への挿入キーはワーカーが返す検証済み (mtime,size) を使う。
    /// spectrum 用 PCM のデコードは LRU ヒットでも走る (全尺 PCM は毎回必要)。
    pub(crate) fn ensure_music_analysis(
        &mut self,
        path: &std::path::Path,
        meta: Option<(i64, i64)>,
    ) {
        if self.music_analysis_path.as_deref() == Some(path) {
            return; // 同じファイル: worker/結果を保持したまま。
        }

        // ── ファイルが変わった: 旧状態を全て捨てる ──
        self.cancel_music_analysis();
        self.music_timeline_cache.clear();
        self.music_spectrum.clear();
        // 新ファイルは先頭再生 = playhead が上端に来るので追従クールダウンは解除しておく。
        self.music_timeline_scroll_cooldown_until = None;
        self.music_timeline_last_scroll_offset = 0.0;
        self.music_timeline_programmatic_scroll_until = None;
        // ▲▼ ボタンの保留スクロール量は前ファイル向けなので破棄する (Codex P3: クリック直後に
        // 別ファイルへ移動すると古い delta が次のタイムラインに適用されてしまう)。
        self.music_timeline_scroll_req = 0.0;
        self.music_timeline_reanchor_playhead_once = false;
        self.set_music_analysis(None);
        self.music_pcm = None;
        self.music_probe = None;
        self.music_analysis_error = None;
        self.music_analysis_path = Some(path.to_path_buf());
        // 左ジャンプパネルは楽曲単位のセッション状態。音声→音声ナビでも引き継がない。
        self.music_left_panel_open = crate::ui_helpers::MetadataPanelOpenState::Closed;

        // ルックアップキー: size>0 (信頼できる) のときだけ作る。size 不明のビュー (mtime のみ等)
        // では LRU を使わない。
        let key = meta.and_then(|(mtime, size)| {
            (size > 0).then(|| MusicAnalysisKey {
                path: crate::adjustment_db::normalize_path(path),
                size,
                mtime,
            })
        });

        // LRU ヒットならタイムラインを即セット (worker は spectrum PCM + 検証のために走らせる)。
        // hit_meta = ヒットに使った (mtime,size)。worker はこれと fresh stat を突き合わせて
        // stale なら解析し直す。
        let mut want_analysis = true;
        let mut hit_meta: Option<(i64, i64)> = None;
        if let Some(k) = key.as_ref()
            && let Some(arc) = self.music_analysis_lru_get(k)
        {
            self.set_music_analysis(Some(arc));
            want_analysis = false;
            hit_meta = Some((k.mtime, k.size));
        }

        let cancel = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let (tx, rx) = std::sync::mpsc::channel::<MusicAnalysisMsg>();
        let worker_cancel = std::sync::Arc::clone(&cancel);
        let worker_path = path.to_path_buf();
        let spawned = std::thread::Builder::new()
            .name("miv-music-analysis".into())
            .spawn(move || {
                // ワーカーは timeline / PCM を複数メッセージで送る。送り終えると tx を drop し、
                // 受信側は Disconnected で完了を知る。cancel 済みなら send 失敗は無視される。
                run_music_analysis(&worker_path, &worker_cancel, &tx, want_analysis, hit_meta);
            });
        if spawned.is_ok() {
            self.music_analysis_pending = Some(MusicAnalysisPending {
                path: path.to_path_buf(),
                cancel,
                rx,
            });
        } else {
            // スレッド生成に失敗したら「解析中」で固まらないようエラーを出す (Codex P3)。
            // LRU ヒットで既にタイムラインがある (want_analysis=false) ならエラーにしない。
            if want_analysis {
                self.music_analysis_error = Some("解析ワーカーを起動できませんでした".to_string());
            }
        }
    }

    /// in-memory LRU からキー一致の解析結果を取り出し、最新位置へ繰り上げる (move-to-front)。
    fn music_analysis_lru_get(
        &mut self,
        key: &MusicAnalysisKey,
    ) -> Option<std::sync::Arc<music_core::TimelineAnalysis>> {
        music_analysis_lru_get(&mut self.music_analysis_lru, key)
    }

    /// 確定した解析結果を in-memory LRU に載せる。件数上限 + bin 総数予算で古いものから追い出す。
    /// 単曲が予算を超える場合は載せない (小さい有用エントリを追い出さないため、Codex P2)。
    fn music_analysis_lru_insert(
        &mut self,
        key: MusicAnalysisKey,
        analysis: std::sync::Arc<music_core::TimelineAnalysis>,
    ) {
        music_analysis_lru_insert(&mut self.music_analysis_lru, key, analysis);
    }

    /// 解析ワーカーの結果を 1 フレームで取り込む (UI スレッド)。pending 中は repaint を要求。
    ///
    /// ワーカーは timeline / spectrum PCM を複数メッセージで送るので、届いている分を全て drain
    /// してから pending を戻す。全メッセージ送信後にワーカーが tx を drop すると Disconnected を
    /// 検出して pending をクリアする。
    pub(crate) fn poll_music_analysis(&mut self, ctx: &egui::Context) {
        // pending を一旦 self から取り出す (drain ループ中に self.music_* を書き換えるため、
        // pending 経由の self 借用と衝突させない)。まだ続くなら末尾で戻す。
        let Some(pending) = self.music_analysis_pending.take() else {
            return;
        };
        // 取り違え防止: 完了したワーカーのパスが現在の対象と一致するときだけ採用。
        let matches = self.music_analysis_path.as_deref() == Some(pending.path.as_path());
        let mut got_any = false;
        let mut disconnected = false;
        loop {
            match pending.rx.try_recv() {
                Ok(msg) => {
                    got_any = true;
                    if matches {
                        match msg {
                            // progressive 途中経過: 表示だけ更新 (LRU には載せない)。
                            MusicAnalysisMsg::Timeline(Ok(analysis)) => {
                                self.set_music_analysis(Some(std::sync::Arc::new(analysis)));
                                self.music_analysis_error = None;
                            }
                            MusicAnalysisMsg::Timeline(Err(e)) => {
                                self.set_music_analysis(None);
                                self.music_analysis_error = Some(e);
                            }
                            // 全尺デコード後の確定版: 表示更新 + in-memory LRU に載せる。
                            // キーはワーカーが実ファイルを fresh stat した検証済み (mtime,size)
                            // を使う (image_metas スナップショットが stale でも正しい key、Codex
                            // code P2)。meta が None (stat 失敗 / size=0) ならキャッシュしない。
                            MusicAnalysisMsg::TimelineComplete { analysis, meta } => {
                                let arc = std::sync::Arc::new(analysis);
                                self.set_music_analysis(Some(arc.clone()));
                                self.music_analysis_error = None;
                                if let Some((mtime, size)) = meta {
                                    let key = MusicAnalysisKey {
                                        path: crate::adjustment_db::normalize_path(&pending.path),
                                        size,
                                        mtime,
                                    };
                                    self.music_analysis_lru_insert(key, arc);
                                }
                            }
                            MusicAnalysisMsg::Pcm(pcm) => {
                                self.music_pcm = Some(pcm);
                            }
                            MusicAnalysisMsg::Probe(probe) => {
                                self.music_probe = Some(probe);
                            }
                        }
                    }
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => break,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    disconnected = true;
                    break;
                }
            }
        }

        if disconnected {
            // ワーカーが全メッセージを送り終えて終了した。結果もエラーも無ければ異常終了扱い
            // (「解析中」で固まらないよう印を残す、Codex P3)。pending は戻さない (= クリア)。
            if matches && self.music_analysis.is_none() && self.music_analysis_error.is_none() {
                self.music_analysis_error = Some("解析ワーカーが異常終了しました".to_string());
            }
            ctx.request_repaint();
        } else {
            // まだ解析中: pending を戻して待つ。
            self.music_analysis_pending = Some(pending);
            if got_any {
                ctx.request_repaint();
            } else {
                // busy repaint を避けるため軽い間隔で再ポーリングする (Codex P3)。再生中は
                // VideoPlayer 側が毎フレーム repaint を駆動するので、これは pause 中の全速 spin
                // を防ぐためのもの。
                ctx.request_repaint_after(std::time::Duration::from_millis(50));
            }
        }
    }

    /// 実行中の解析ワーカーを cancel する (music ビューを閉じる / 別ファイルに移るとき)。
    pub(crate) fn cancel_music_analysis(&mut self) {
        if let Some(pending) = self.music_analysis_pending.take() {
            pending
                .cancel
                .store(true, std::sync::atomic::Ordering::Relaxed);
        }
    }

    /// 音楽ビュー (Inc 3b/4) の状態を全て破棄する: 解析ワーカー cancel + タイムライン raster +
    /// spectrum worker + 常駐 PCM。フルスクリーンを抜けた / 音声以外へ移ったときに呼ぶ
    /// (§7.9 grid/viewer lifecycle)。Inc 4 で spectrum worker が parked のまま + PCM が常駐する
    /// ようになったため、音声→画像/動画への移動でも確実に teardown する必要がある (Codex P2)。
    /// `open_fullscreen` で音楽ビュー状態 (`music_*`) を破棄すべきか (review-v2.3.0 P2-3)。
    ///
    /// - 音声を開くとき: 破棄しない (音声→別音声は `ensure_music_analysis` が path 比較で処理)。
    /// - ParkedLive の音楽窓が global music_* を消費中で、開くのが非メディア (画像 / PDF
    ///   ページ等): 破棄しない。破棄すると「別窓 BGM 再生中にメイン窓で画像を見る」際、
    ///   ページを開くたびに解析ワーカー respawn + PCM 全尺再デコードが走り、parked 窓の
    ///   スペクトラムが playhead 追いつきまで空白になる (1h 級ファイルで数十秒 + ~GB 級の
    ///   アロケーション churn)。
    /// - 動画を開くとき: 従来どおり破棄する。直後の `prepare_viewer_presentation_open` →
    ///   `close_parked_live_media_windows_for_new_media` が parked メディア窓ごと閉じる
    ///   (メディア窓 1 本規則) ので、音楽状態の消費者は残らない。
    fn should_clear_music_view_on_open(&self, idx: usize) -> bool {
        if matches!(self.items.get(idx), Some(GridItem::Audio(_))) {
            return false;
        }
        #[cfg(windows)]
        if !matches!(self.items.get(idx), Some(GridItem::Video(_)))
            && self.detached_music_window_exists()
        {
            return false;
        }
        true
    }

    /// `music_analysis` の代入は必ずここを通し、版数を進める (フィールドコメント参照、
    /// review-v2.3.0 P2-4)。
    fn set_music_analysis(
        &mut self,
        analysis: Option<std::sync::Arc<music_core::TimelineAnalysis>>,
    ) {
        self.music_analysis = analysis;
        self.music_analysis_version = self.music_analysis_version.wrapping_add(1);
    }

    pub(crate) fn clear_music_view_state(&mut self) {
        self.cancel_music_analysis();
        self.music_timeline_cache.clear();
        self.music_spectrum.clear();
        self.set_music_analysis(None);
        // LRU 本体 (直近 N 曲) はセッション中保持して音声への再入を即時にする。キーは
        // path+size+mtime + ワーカーの fresh stat 検証なので stale hit は起きない。
        self.music_pcm = None;
        self.music_probe = None;
        self.music_analysis_error = None;
        self.music_analysis_path = None;
        // ▲▼ ボタンの保留スクロール量も teardown で破棄する (Codex P3、上記 path 変更と同じ理由)。
        self.music_timeline_scroll_req = 0.0;
        self.music_timeline_reanchor_playhead_once = false;
        self.music_timeline_scroll_cooldown_until = None;
        self.music_timeline_last_scroll_offset = 0.0;
        self.music_timeline_programmatic_scroll_until = None;
        // 端ホバーパネルの開閉ラッチは transient hover state なので teardown でリセットする。
        // 残すと次に音声を開いた際、5% edge trigger を踏まずカーソルが panel+sustain 内にある
        // だけでパネルが再表示される (Codex P3)。
        self.music_left_panel_active = false;
        self.music_right_panel_active = false;
        self.music_left_panel_open = crate::ui_helpers::MetadataPanelOpenState::Closed;
        // ブックマークの一時状態 (キャッシュ / 改名ダイアログ / 一括登録ダイアログ) は破棄する。
        // ループ設定はセッション設定として保持する。
        self.music_bookmarks.clear();
        self.music_bookmarks_loaded_for = None;
        #[cfg(windows)]
        {
            self.music_bookmark_title_edit = None;
            self.music_bulk_bookmark_dialog = None;
        }
    }

    /// 音声ファイル用の headless `VideoPlayer` を作る (映像出力なし・native presenter なし)。
    ///
    /// 音楽ビュー (D3) は egui で描くので GPU 映像経路 (`gpu_video_device`) と native
    /// presenter (`native_output_config`) は使わない。VST3 (`dsp_bridge`) は動画と同じく常に
    /// 渡し、audio pump が `normalize -> VST3 -> limiter` を通す (Inc 6、「音声=映像なし動画」
    /// パリティ)。有効化・チェーン定義はプロセス共有の `DspBridge` singleton に従うので、
    /// 環境設定/動画側で設定したチェーンがそのまま音声にも効く (音楽ビュー自体に VST UI は
    /// 持たない = 追加の HWND 配線なし)。音量ノーマライズは既存 `audio_normalize_db` の cache 値があれば適用するが、
    /// スキャン起動はしない (Inc 3a; スキャン連携は後続)。再生位置の復元は音声の resume 設定
    /// (`music_open_resume` / `music_nav_resume`、既定=最初から) に従う。位置は動画と同じ
    /// `video_resume_positions` に path キーで保存済み (poll_video)。
    fn build_audio_player_for_open(
        &self,
        path: PathBuf,
        from_grid: bool,
    ) -> (crate::video::VideoPlayer, bool) {
        let vol = crate::settings::clamp_video_volume(self.settings.video_volume);
        // 音量ノーマライズ (D13、「映像なし動画」パリティ): グローバル ON なら DB を引き、
        // ヒットすれば gain を即適用する。ミスなら動画と同じく「再生前スキャン」に入るため
        // ここでは gain=1.0 のまま開き、preroll を suspended + autoplay off で開始して、
        // start_fs_load 側でスキャンを起動→完了時に補正 gain 付きで再生を始める
        // (未補正音の一瞬の burst を避ける)。スキャン機構は windows 限定。
        let normalize_lookup = if self.settings.audio_normalize_enabled {
            let target_milli = self.settings.clamped_audio_normalize_target_lufs_milli();
            self.audio_normalize_db
                .as_ref()
                .and_then(|db| db.lookup(&path, target_milli))
        } else {
            None
        };
        let normalize_gain = normalize_lookup
            .as_ref()
            .map(|r| 10.0_f64.powf(r.gain_db as f64 / 20.0))
            .unwrap_or(1.0);
        let autoplay = true;
        // ON + 未測定 + autoplay のときだけ再生前スキャンする (動画 build_video_player_for_open と同型)。
        let start_normalize_scan_before_play = {
            #[cfg(windows)]
            {
                self.settings.audio_normalize_enabled && normalize_lookup.is_none() && autoplay
            }
            #[cfg(not(windows))]
            {
                let _ = &normalize_lookup;
                false
            }
        };
        let open_autoplay = autoplay && !start_normalize_scan_before_play;
        // 一覧から開いた (`fs_open_intent_from_grid`) か移動 (↓↑/ホイール/Ctrl+↑↓) かで
        // 音声 resume 設定を選び、保存済み位置を使うか先頭からかを決める (動画の
        // `video_resume_for_open` を音声設定で共有)。
        let path_key = crate::adjustment_db::normalize_path(&path);
        let saved_resume = self.settings.video_resume_positions.get(&path_key).copied();
        let resume = video_resume_for_open(
            saved_resume,
            from_grid,
            matches!(
                self.settings.music_open_resume,
                crate::settings::ResumeMode::FromStart
            ),
            self.settings.music_nav_resume,
        );
        let player = crate::video::VideoPlayer::open(
            path,
            vol,
            normalize_gain,
            start_normalize_scan_before_play, // audio_preroll_suspended (スキャン完了まで先読み停止)
            open_autoplay,                    // 再生前スキャン時は false = 補正確定後に再生開始
            resume,                           // 音声 resume 設定に従う (既定=最初から)
            false,                            // hw_decode (音声のみ、GPU 不要)
            self.settings.video_deinterlace,
            #[cfg(windows)]
            None, // gpu_video_device (headless)
            #[cfg(windows)]
            Some(self.dsp_bridge.clone()), // dsp_bridge: 動画と同じ VST3 チェーンを共有 (Inc 6)
            #[cfg(windows)]
            None, // native_output_config (headless = 音楽ビューは egui 描画)
        );
        // 音声ファイルは動画の hidden 音声モードと同じ readiness 要件を使う。
        player.set_media_visual_mode(music_core::MediaVisualMode::Music);
        player.set_playback_speed(self.video_playback_speed);
        if self.video_session_muted {
            player.set_muted(true);
        }
        // ループ/連続の設定は共有 video_loop_mode / video_continuous_mode に従い、
        // fs_cache へ insert した後に apply_music_loop_mode で反映する (start_fs_load 音声 branch)。
        (player, start_normalize_scan_before_play)
    }

    pub(crate) fn fs_pdf_render_context_epoch(_priority: crate::pdf_loader::JobPriority) -> u64 {
        // Fullscreen fs_load is scoped to the open viewer context, not to the main
        // grid context. fs_pending cancel tokens own its lifetime.
        0
    }

    pub(crate) fn fs_pdf_render_error_is_cancel_like(
        cancel_flag_set: bool,
        error: &std::io::Error,
    ) -> bool {
        cancel_flag_set || error.kind() == std::io::ErrorKind::Interrupted
    }

    fn with_verified_fullscreen_relative_page_bytes<T>(
        provenance: &crate::book_bookmarks::RelativePageProvenance,
        consume: impl FnOnce(Vec<u8>) -> T,
    ) -> std::io::Result<T> {
        provenance.read_verified().map(consume)
    }

    /// 1枚のフルサイズ画像を非同期で読み込み開始する。
    /// 通常画像 / ZIP エントリ / PDF ページ の全てに対応。
    /// GIF / APNG (通常画像) と WebP (通常画像 / ZIP 内画像) は
    /// アニメーションフレームを全デコードして FsLoadResult::Animated を送信する。
    pub(crate) fn start_fs_load(&mut self, idx: usize) {
        // 360 度パノラマビュー Phase 2a: 内部で使う tee 判定パラメータ。
        // `start_fs_load` 開始時点で App の状態をスナップショットして worker に渡す
        // (docs/panorama-360-view-plan.md §4.6.0)。
        //
        // 名前付きクロージャ的な存在で、外部 API に露出する必要はない。
        #[allow(dead_code)]
        #[derive(Clone)]
        struct PanoHighResIntent {
            is_xmp_pano: bool,
            approved_max_pixels: u64,
            prev_base_only: bool,
        }
        // 動画は専用パス: VideoPlayer を作って fs_cache に直接入れる。
        // 通常の画像デコードスレッドは起動しない。
        if let Some(GridItem::Video(vp)) = self.items.get(idx).cloned() {
            // 1 動画につき 1 cpal stream に限定する。`contains_key(idx)` チェックの
            // 外で実行することで、再 start_fs_load (= fullscreen 戻り遷移) でも
            // 古い video エントリが残らないことを保証する (Codex 助言)。
            let other_video_idxs: Vec<usize> = self
                .fs_cache
                .iter()
                .filter_map(|(k, v)| {
                    if *k != idx && matches!(v, FsCacheEntry::Video { .. }) {
                        Some(*k)
                    } else {
                        None
                    }
                })
                .collect();
            if !other_video_idxs.is_empty() {
                self.save_all_video_resume_positions();
                for k in other_video_idxs {
                    #[cfg(windows)]
                    self.cleanup_normalize_state_for_fs_idx(k);
                    self.fs_cache.remove(&k);
                    self.fs_margin_bbox_cache.remove(&k);
                }
            }
            if !self.fs_cache.contains_key(&idx) {
                let from_grid = std::mem::take(&mut self.fs_open_intent_from_grid);
                let autoplay_override = self.fs_video_open_autoplay_override.take();
                let ignore_resume = std::mem::take(&mut self.fs_video_open_ignore_resume_once);
                #[cfg(windows)]
                if self.defer_native_video_open_if_decoder_busy(
                    idx,
                    &vp,
                    from_grid,
                    autoplay_override,
                    ignore_resume,
                ) {
                    return;
                }
                #[cfg(windows)]
                let native_config = {
                    let presentation = self.viewer_presentation;
                    let target = self.native_video_target_for_presentation(presentation);
                    if target.is_none()
                        && matches!(presentation, ViewerPresentation::DetachedWindow)
                        && self.defer_native_video_open_until_detached_host(
                            idx,
                            &vp,
                            from_grid,
                            autoplay_override,
                            ignore_resume,
                        )
                    {
                        return;
                    }
                    // ParkedLive 中に初めて player を作る deferred open は、既存の非アクティブ窓を
                    // owner にしても前面を奪わない。通常の active detached だけ one-shot を消費する。
                    let activate_on_show = self.native_video_parked_live_input_window_id.is_none()
                        && (!matches!(presentation, ViewerPresentation::DetachedWindow)
                            || self.take_detached_viewer_activate_on_show());
                    target.and_then(|(placement, rect, owner_hwnd)| {
                        native_video_presenter_config(
                            owner_hwnd,
                            rect,
                            placement,
                            activate_on_show,
                            self.window_visible,
                            vp.file_name()
                                .and_then(|name| name.to_str())
                                .unwrap_or("video")
                                .to_string(),
                            self.video_perf_overlay_visible,
                            self.video_tile_mode_active || self.video_tile_reopen_pending,
                            self.settings.vst3_enabled,
                            self.checked.contains(&idx),
                            self.settings.ui_scale_factor,
                            self.settings.text_contrast,
                            self.settings.ui_font.clone(),
                            self.settings.fullscreen_cursor_hide_delay_secs,
                            // CP7: HUD raise の allowlist 用 snapshot を `DspBridge` から clone して渡す。
                            Some(self.dsp_bridge.editor_hwnds_snapshot()),
                            self.main_hwnd.unwrap_or(0) as u64,
                            self.creative_lut_library.video_snapshot(
                                &self.settings.creative_luts,
                                &self.settings.video_adjustments,
                                &self.settings.video_preset_slots,
                            ),
                            // 動画経路: 常に映像フレームを持つ。
                            false,
                        )
                    })
                };
                #[cfg(windows)]
                let native_config_missing = native_config.is_none();
                // 動画オープン開始時点で indexer に「いま忙しい」を通知する。
                // `build_video_player_for_open` 内で `VideoPlayer::open` → `decoder::spawn`
                // が走り demux thread が即時に `avformat_open_input` を始めるので、
                // build の **前** で bump しないと初動の数十-数百 ms が gate 無しに
                // なる (Codex P2 第 16 ラウンド指摘)。入力イベント由来であれば
                // 既に bump 済みだが、自動オープン経路や直前に bump が無い経路
                // (fast-swap で再帰的に呼ばれる場合) の保険として明示的に bump する。
                self.activity_gate.bump();
                #[allow(unused_mut)]
                let (mut player, start_normalize_scan_before_play) = self
                    .build_video_player_for_open(
                        idx,
                        vp,
                        from_grid,
                        autoplay_override,
                        ignore_resume,
                        #[cfg(windows)]
                        native_config,
                    );
                #[cfg(windows)]
                if native_config_missing {
                    player.fail_native_init(
                        "ネイティブ動画プレゼンターの設定取得に失敗しました (モニター情報を取れません)"
                            .to_string(),
                    );
                }
                self.fs_cache.insert(
                    idx,
                    FsCacheEntry::Video {
                        player: Box::new(player),
                        load_seq: self.input_seq,
                    },
                );
                self.fs_margin_bbox_cache.remove(&idx);
                #[cfg(windows)]
                self.init_normalize_state_for_opened_video(idx);
                #[cfg(windows)]
                if start_normalize_scan_before_play {
                    if !self.start_normalize_scan_for_deferred_play_intent(idx) {
                        self.resume_deferred_normalize_playback_without_scan(idx);
                    }
                } else {
                    self.maybe_start_normalize_scan_for_play_intent(idx);
                }
            }
            return;
        }

        // 音声も専用パス: headless VideoPlayer を作って音楽ビュー (egui) で再生する。
        // native presenter は使わない (D3)。fs_cache は動画と同じ FsCacheEntry::Video を
        // 再利用する (中身は VideoPlayer なので identical)。通常の画像デコードは起動しない。
        if let Some(GridItem::Audio(ap)) = self.items.get(idx).cloned() {
            // 1 メディア = 1 cpal stream。既存の Video/Audio プレイヤー (= FsCacheEntry::Video)
            // を畳んでから開く (動画と同じ singleton 規約)。
            let other_player_idxs: Vec<usize> = self
                .fs_cache
                .iter()
                .filter_map(|(k, v)| {
                    (*k != idx && matches!(v, FsCacheEntry::Video { .. })).then_some(*k)
                })
                .collect();
            if !other_player_idxs.is_empty() {
                // 畳む前に現在位置を保存する (動画分岐と同じ)。poll_video の 5 秒周期保存より
                // 前に素早く曲を切り替えると直近位置が失われ、resume=続きから が効かない (Codex P2)。
                self.save_all_video_resume_positions();
            }
            for k in other_player_idxs {
                #[cfg(windows)]
                self.cleanup_normalize_state_for_fs_idx(k);
                self.fs_cache.remove(&k);
                self.fs_margin_bbox_cache.remove(&k);
                // ループ境界 baseline を掃除 (player を畳んだので stale entry を残さない、Codex P3)。
                self.last_loop_pos.remove(&k);
            }
            if !self.fs_cache.contains_key(&idx) {
                self.activity_gate.bump();
                // 一覧から開いた (grid) か移動 (nav) かのワンショットフラグを消費する
                // (動画分岐と同じ std::mem::take 規約)。resume 設定の選択に使う。
                let from_grid = std::mem::take(&mut self.fs_open_intent_from_grid);
                let (player, start_normalize_scan_before_play) =
                    self.build_audio_player_for_open(ap, from_grid);
                self.fs_cache.insert(
                    idx,
                    FsCacheEntry::Video {
                        player: Box::new(player),
                        load_seq: self.input_seq,
                    },
                );
                self.fs_margin_bbox_cache.remove(&idx);
                // 共有 video_loop_mode / video_continuous_mode を新プレイヤーへ反映。
                self.apply_music_loop_mode(idx);
                // 音量ノーマライズ (D13、「映像なし動画」パリティ): 動画の start_fs_load 分岐
                // (init_normalize_state_for_opened_video + 再生前 / 再生 intent スキャン) と同型に
                // 揃える。DB ヒットなら build 時に gain 適用済み + ここで OnApplied 表示、ミスなら
                // OnUnmeasured → 初回スキャン (再生前スキャンなら deferred、それ以外は intent 経路)。
                #[cfg(windows)]
                {
                    self.init_normalize_state_for_opened_video(idx);
                    if start_normalize_scan_before_play {
                        if !self.start_normalize_scan_for_deferred_play_intent(idx) {
                            self.resume_deferred_normalize_playback_without_scan(idx);
                        }
                    } else {
                        self.maybe_start_normalize_scan_for_play_intent(idx);
                    }
                }
                #[cfg(not(windows))]
                let _ = start_normalize_scan_before_play;
            }
            return;
        }

        let (path, zip_entry, pdf_page, pdf_password) = match self.items.get(idx) {
            Some(GridItem::Image(p)) => (p.clone(), None, None, None),
            Some(GridItem::ZipImage {
                zip_path,
                entry_name,
            }) => (zip_path.clone(), Some(entry_name.clone()), None, None),
            Some(GridItem::PdfPage {
                pdf_path, page_num, ..
            }) => (
                pdf_path.clone(),
                None,
                Some(*page_num),
                self.pdf_current_password.clone(),
            ),
            _ => return,
        };
        let relative_page_provenance = self.relative_page_provenance_for_idx(idx);
        let pdf_display_request = if pdf_page.is_some() {
            // PDF は実際に描く viewport が確定するまで enqueue しない。専用 fullscreen、
            // detached、in-window は別々の egui context / ppp を持ち得るため、推測値で
            // 先行すると初回だけ過大・過小レンダになる。
            let Some(viewport) = self.fs_pdf_display_target else {
                return;
            };
            let rotation = self.get_rotation(idx);
            let swap_page_axes = matches!(
                rotation,
                crate::rotation_db::Rotation::Cw90 | crate::rotation_db::Rotation::Cw270
            );
            Some((viewport, swap_page_axes))
        } else {
            None
        };

        if pdf_page.is_some() {
            if self.has_retained_pdf_final_ai_for_current_params(idx) {
                crate::logger::log(format!(
                    "[PDF] Retained page final-ai available idx={idx} reason=start_fs_load_skip_pdf_render"
                ));
                return;
            }
            let (viewport, swap_page_axes) = pdf_display_request.unwrap();
            if let Some((pixels, source_dims)) = self.lookup_retained_pdf_page_raster_for_display(
                idx,
                viewport,
                swap_page_axes,
                "start_fs_load",
            ) {
                self.enqueue_retained_pdf_page_raster_result(
                    idx,
                    pixels,
                    source_dims,
                    self.input_seq,
                    "start_fs_load",
                );
                return;
            }
        }

        // フルスクリーン現在ページ (ユーザーが待っているもの) は Critical、
        // それ以外 (先読み) は Normal。Critical はプールの予約ワーカーで即処理される。
        let pdf_priority = if self.fullscreen_idx == Some(idx) {
            crate::pdf_loader::JobPriority::Critical
        } else {
            crate::pdf_loader::JobPriority::Normal
        };
        let pdf_context_epoch = Self::fs_pdf_render_context_epoch(pdf_priority);

        let cancel = Arc::new(AtomicBool::new(false));
        let (tx, rx) = mpsc::channel::<FsLoadResult>();
        let pdf_ct_tx = self.pdf_content_type_tx.clone();
        let perf_key = self.perf_item_key(idx);
        let perf_seq = self.input_seq;
        self.fs_pending
            .insert(idx, (Arc::clone(&cancel), rx, perf_seq));
        // 360 度パノラマビュー Phase 2a: 通常画像 (= PDF / ZIP 除く) のみで
        // tee デコード判断を持ち込む (§3.6.2 / §4.6.0)。
        // App 側で「XMP equirect 判定済みか」「approved_max_pixels」「BaseOnly か」を
        // snapshot し、worker は probe_dims 結果と合わせて tee or 通常パスを決める。
        // **prefetch では tee しない** (Codex P2 第 10、2026-05): tee は worker 内で
        // フル RGBA を確保 (>8K 画像で 200-800 MB) するので、同時に複数 prefetch worker
        // が走ると memory peak が嵩む (5 prefetch slot × 800 MB = 4 GB)。
        // `pano_intent` を **fullscreen_idx == idx のときだけ Some** にすることで、
        // prefetch は通常 Static パスで完了する。トレードオフ: prefetch 済み画像を
        // 360 モード ON した瞬間に高画質ロードが auto-kick される (= 1 回の追加
        // デコード = 3-5 秒の「高画質 ロード中...」表示)。これは元設計と同等の UX
        // (LRU 1 + 戻る/進む時の cache hit で settle 即復活経路) で受け入れ可能。
        let is_current_fs = self.fullscreen_idx == Some(idx);
        let pano_intent: Option<PanoHighResIntent> =
            if is_current_fs && pdf_page.is_none() && zip_entry.is_none() {
                let source_key = self.metadata_cache_key(idx);
                let is_xmp_pano = source_key
                    .as_ref()
                    .and_then(|k| self.xmp_panorama_info.get(k))
                    .and_then(|o| o.as_ref())
                    .map(|info| info.is_equirectangular())
                    .unwrap_or(false);
                let prev_base_only = source_key
                    .as_ref()
                    .and_then(|k| self.pano_quality_state.get(k))
                    .map(|s| matches!(s, crate::panorama::PanoramaQualityState::BaseOnly))
                    .unwrap_or(false);
                Some(PanoHighResIntent {
                    is_xmp_pano,
                    approved_max_pixels: self.pano_session_approved_max_pixels,
                    prev_base_only,
                })
            } else {
                None
            };
        if crate::perf::is_enabled() {
            crate::perf::event(
                "fs",
                "load_begin",
                perf_key.as_deref(),
                perf_seq,
                &[
                    ("idx", serde_json::Value::from(idx)),
                    ("is_pdf", serde_json::Value::from(pdf_page.is_some())),
                    ("is_zip", serde_json::Value::from(zip_entry.is_some())),
                    (
                        "priority",
                        serde_json::Value::from(format!("{pdf_priority:?}")),
                    ),
                ],
            );
        }
        let perf_key_worker = perf_key.clone();

        std::thread::spawn(move || {
            // perf: スレッド起動直後の cancel 状態を記録し、早期終了した本数を把握する
            let early_cancelled = cancel.load(Ordering::Relaxed);
            if crate::perf::is_enabled() {
                crate::perf::event(
                    "fs",
                    "cancel_check",
                    perf_key_worker.as_deref(),
                    perf_seq,
                    &[("cancelled", serde_json::Value::from(early_cancelled))],
                );
            }
            // スレッド出口で reason を記録する小ヘルパー (全 return 直前に呼ぶ)
            let emit_exit = |reason: &'static str| {
                if crate::perf::is_enabled() {
                    crate::perf::event(
                        "fs",
                        "thread_exit",
                        perf_key_worker.as_deref(),
                        perf_seq,
                        &[("reason", serde_json::Value::from(reason))],
                    );
                }
            };
            if early_cancelled {
                emit_exit("early_cancel");
                return;
            }
            let verified_source_bytes = match relative_page_provenance.as_ref() {
                Some(provenance) => {
                    match Self::with_verified_fullscreen_relative_page_bytes(provenance, |bytes| {
                        bytes
                    }) {
                        Ok(bytes) => Some(bytes),
                        Err(error) => {
                            crate::logger::log(format!(
                                "  fs relative bookmark page rejected: {error}  {}",
                                path.display()
                            ));
                            let _ = tx.send(FsLoadResult::Failed);
                            emit_exit("relative_page_rejected");
                            return;
                        }
                    }
                }
                None => None,
            };
            let t = std::time::Instant::now();
            if crate::perf::is_enabled() {
                crate::perf::event(
                    "fs",
                    "decode_begin",
                    perf_key_worker.as_deref(),
                    perf_seq,
                    &[],
                );
            }

            // ローカル画像ファイルはヘッダ数バイトで寸法が取れる (数 ms)。
            // 本デコード前にホバーバーへサイズ / ダウンスケール警告を出すため先行送信。
            if pdf_page.is_none() && zip_entry.is_none() {
                let dims = match verified_source_bytes.as_deref() {
                    Some(bytes) => crate::fast_resize::probe_dims_from_bytes(bytes),
                    None => crate::fast_resize::probe_dims(&path),
                };
                if let Some(dims) = dims {
                    let _ = tx.send(FsLoadResult::DimsOnly { source_dims: dims });
                }
            }

            // 表示名と拡張子を取得
            let (name, ext) = if let Some(page_num) = pdf_page {
                (format!("Page {}", page_num + 1), "pdf".to_string())
            } else if let Some(ref entry_name) = zip_entry {
                let base = crate::zip_loader::entry_basename(entry_name).to_string();
                let ext = base.rsplit('.').next().unwrap_or("").to_lowercase();
                (base, ext)
            } else {
                let n = path
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("?")
                    .to_string();
                let ext = path
                    .extension()
                    .and_then(|e| e.to_str())
                    .unwrap_or("")
                    .to_lowercase();
                (n, ext)
            };

            // PDF ページの場合はラスタライズ
            if let Some(page_num) = pdf_page {
                let (viewport, swap_page_axes) = pdf_display_request.unwrap();
                let mut pdf_exit = "pdf_ok";
                match crate::pdf_loader::render_page_for_display(
                    &path,
                    page_num,
                    viewport,
                    swap_page_axes,
                    pdf_password.as_deref(),
                    Some(cancel.clone()),
                    pdf_priority,
                    pdf_context_epoch,
                    // フルスクリーンは fs_cache (memory) のみで永続 cache 無し。
                    // Critical 経路は即時応答 UX 優先 → AbortOnCancel。
                    crate::pdf_loader::CancelWaitPolicy::AbortOnCancel,
                ) {
                    Ok(crate::pdf_loader::RenderResult {
                        image: img,
                        content_type,
                        page_count: _,
                    }) => {
                        let elapsed = t.elapsed().as_secs_f64() * 1000.0;
                        crate::logger::log(format!(
                            "  fs load pdf: {elapsed:.0}ms  idx={idx}  {name}  {}x{}  {:?}",
                            img.width(),
                            img.height(),
                            content_type
                        ));
                        // GPU テクスチャ上限に収まらない巨大レンダ結果をここで縮小しておく。
                        // (request_pdf_rerender は 8192 に clamp 済なので通常は no-op)
                        let source_dims = [img.width() as usize, img.height() as usize];
                        let img = clamp_dynamic_for_gpu(img);
                        let (w, h) = (img.width(), img.height());
                        let ci = dynamic_image_to_color_image(&img);
                        if crate::perf::is_enabled() {
                            crate::perf::event(
                                "fs",
                                "decode_end",
                                perf_key_worker.as_deref(),
                                perf_seq,
                                &[
                                    ("ms", serde_json::Value::from(elapsed)),
                                    ("format", serde_json::Value::from("pdf")),
                                    ("w", serde_json::Value::from(w)),
                                    ("h", serde_json::Value::from(h)),
                                ],
                            );
                        }
                        let _ = tx.send(FsLoadResult::Static { ci, source_dims });
                        // content_type をメインスレッドに送る
                        let _ = pdf_ct_tx.send((idx, content_type));
                    }
                    Err(e) => {
                        let cancel_like = Self::fs_pdf_render_error_is_cancel_like(
                            cancel.load(Ordering::Relaxed),
                            &e,
                        );
                        if cancel_like {
                            crate::logger::log(format!(
                                "  fs pdf render cancelled/interrupted  {name}"
                            ));
                            if crate::perf::is_enabled() {
                                crate::perf::event(
                                    "fs",
                                    "decode_cancel",
                                    perf_key_worker.as_deref(),
                                    perf_seq,
                                    &[],
                                );
                            }
                            pdf_exit = "pdf_cancel";
                        } else {
                            crate::logger::log(format!("  fs pdf render FAIL: {e}  {name}"));
                            if crate::perf::is_enabled() {
                                crate::perf::event(
                                    "fs",
                                    "decode_fail",
                                    perf_key_worker.as_deref(),
                                    perf_seq,
                                    &[("format", serde_json::Value::from("pdf"))],
                                );
                            }
                            let _ = tx.send(FsLoadResult::Failed);
                            pdf_exit = "pdf_fail";
                        }
                    }
                }
                emit_exit(pdf_exit);
                return;
            }

            // ZIP エントリの場合は先にバイト列を抽出
            let zip_bytes: Option<Vec<u8>> = if let Some(ref entry_name) = zip_entry {
                match crate::zip_loader::read_entry_bytes(&path, entry_name) {
                    Ok(b) => Some(b),
                    Err(e) => {
                        crate::logger::log(format!("  fs zip read FAIL: {e}  {name}"));
                        if crate::perf::is_enabled() {
                            crate::perf::event(
                                "fs",
                                "decode_fail",
                                perf_key_worker.as_deref(),
                                perf_seq,
                                &[("format", serde_json::Value::from("zip_read"))],
                            );
                        }
                        // PDF / 静止画のデコード失敗 arm と同じく、UI が「読込中...」の
                        // まま固着しないよう失敗を明示通知する (送らないと tx drop で
                        // チャネル切断 → poll_prefetch が Failed を入れず is_loading が
                        // 永久 true になる。v1.0.0 安定性レビュー P2-1)。
                        let _ = tx.send(FsLoadResult::Failed);
                        emit_exit("zip_read_fail");
                        return;
                    }
                }
            } else {
                None
            };
            let source_bytes = verified_source_bytes.or(zip_bytes);

            // GIF: アニメーション試行 (通常パスのみ, ZIP は未対応)
            if ext == "gif" && zip_entry.is_none() {
                let frames = match source_bytes.as_deref() {
                    Some(bytes) => decode_gif_frames_from_bytes(bytes),
                    None => decode_gif_frames(&path),
                };
                if let Some(frames) = frames {
                    let elapsed = t.elapsed().as_secs_f64() * 1000.0;
                    crate::logger::log(format!(
                        "  fs load anim-gif: {elapsed:.0}ms  idx={idx}  {name}  {} frames",
                        frames.len()
                    ));
                    if crate::perf::is_enabled() {
                        crate::perf::event(
                            "fs",
                            "decode_end",
                            perf_key_worker.as_deref(),
                            perf_seq,
                            &[
                                ("ms", serde_json::Value::from(elapsed)),
                                ("format", serde_json::Value::from("gif_anim")),
                                ("frames", serde_json::Value::from(frames.len())),
                            ],
                        );
                    }
                    let _ = tx.send(FsLoadResult::Animated(frames));
                    emit_exit("gif_anim");
                    return;
                }
            }

            // PNG: APNG アニメーション試行 (通常パスのみ, ZIP は未対応)
            if ext == "png" && zip_entry.is_none() {
                let frames = match source_bytes.as_deref() {
                    Some(bytes) => decode_apng_frames_from_bytes(bytes),
                    None => decode_apng_frames(&path),
                };
                if let Some(frames) = frames {
                    let elapsed = t.elapsed().as_secs_f64() * 1000.0;
                    crate::logger::log(format!(
                        "  fs load anim-png: {elapsed:.0}ms  idx={idx}  {name}  {} frames",
                        frames.len()
                    ));
                    if crate::perf::is_enabled() {
                        crate::perf::event(
                            "fs",
                            "decode_end",
                            perf_key_worker.as_deref(),
                            perf_seq,
                            &[
                                ("ms", serde_json::Value::from(elapsed)),
                                ("format", serde_json::Value::from("png_anim")),
                                ("frames", serde_json::Value::from(frames.len())),
                            ],
                        );
                    }
                    let _ = tx.send(FsLoadResult::Animated(frames));
                    emit_exit("png_anim");
                    return;
                }
            }

            // WebP: アニメーション試行。通常ファイルと ZIP 内 bytes の両方に対応する。
            if ext == "webp" {
                let frames = match source_bytes.as_deref() {
                    Some(bytes) => decode_webp_frames_from_bytes(bytes),
                    None => decode_webp_frames(&path),
                };
                if let Some(frames) = frames {
                    let elapsed = t.elapsed().as_secs_f64() * 1000.0;
                    crate::logger::log(format!(
                        "  fs load anim-webp: {elapsed:.0}ms  idx={idx}  {name}  {} frames",
                        frames.len()
                    ));
                    if crate::perf::is_enabled() {
                        crate::perf::event(
                            "fs",
                            "decode_end",
                            perf_key_worker.as_deref(),
                            perf_seq,
                            &[
                                ("ms", serde_json::Value::from(elapsed)),
                                ("format", serde_json::Value::from("webp_anim")),
                                ("frames", serde_json::Value::from(frames.len())),
                                ("is_zip", serde_json::Value::from(zip_entry.is_some())),
                            ],
                        );
                    }
                    let _ = tx.send(FsLoadResult::Animated(frames));
                    emit_exit("webp_anim");
                    return;
                }
            }

            // 静止画フォールバック
            // image クレート → WIC → Susie プラグインの順で試す
            // ZIP エントリは SHCreateMemStream + CreateDecoderFromStream 経由で WIC へフォールバック
            let open_result = if let Some(bytes) = source_bytes.as_deref() {
                let hint = zip_entry
                    .as_deref()
                    .or_else(|| path.file_name().and_then(|name| name.to_str()))
                    .unwrap_or("");
                match image::load_from_memory(bytes) {
                    Ok(img) => Ok(img),
                    Err(e) => {
                        match crate::wic_decoder::decode_to_dynamic_image_from_bytes(bytes) {
                            Some(img) => Ok(img),
                            // フルスクリーン画像ロードは現在表示中のため priority=true
                            None => {
                                match crate::susie_loader::decode_bytes(hint, bytes, true, None) {
                                    Ok(img) => Ok(img),
                                    Err(_) => Err(e),
                                }
                            }
                        }
                    }
                }
            } else {
                match image::open(&path) {
                    Ok(img) => Ok(img),
                    Err(e) => match crate::wic_decoder::decode_to_dynamic_image(&path) {
                        Some(img) => Ok(img),
                        // フルスクリーン画像ロードは現在表示中のため priority=true
                        None => match crate::susie_loader::decode_file(&path, true, None) {
                            Ok(img) => Ok(img),
                            Err(_) => Err(e),
                        },
                    },
                }
            };
            match open_result {
                Ok(img) => {
                    // EXIF Orientation 自動回転。ZIP はエントリのバイト列から読む。
                    let img = match source_bytes.as_deref() {
                        Some(bytes) => {
                            crate::thumb_loader::apply_exif_orientation_from_bytes(img, bytes)
                        }
                        None => crate::thumb_loader::apply_exif_orientation(img, &path),
                    };
                    let source_dims = [img.width() as usize, img.height() as usize];
                    let source_pixels = (source_dims[0] as u64) * (source_dims[1] as u64);
                    // 360 度パノラマビュー Phase 2a: tee 判定
                    // (docs/panorama-360-view-plan.md §4.6.0)。
                    // `pano_intent` は通常画像のみ有効 (PDF / ZIP は None)。
                    // 候補条件: XMP equirect 検出済み OR アスペクト 2:1
                    // tee 条件: 候補かつ BaseOnly でなく、源解像度が ≤ 200 MP または
                    // 前回承認の 1.25 倍以内。**かつ source が >8K** (= 8K clamp で
                    // 画質が下がるケースだけ HighResSource を作る、Codex P2 第 5、2026-05):
                    // ≤8K source では fs_cache の ColorImage が既にフル解像度で、
                    // HighResSource は同じデータの重複保持 (~134 MB 無駄) になる。
                    let max_dim_u = MAX_TEXTURE_DIM as u32;
                    let source_exceeds_8k =
                        (source_dims[0] as u32) > max_dim_u || (source_dims[1] as u32) > max_dim_u;
                    let want_tee = source_exceeds_8k
                        && pano_intent.as_ref().is_some_and(|intent| {
                            let aspect = source_dims[0] as f32 / source_dims[1].max(1) as f32;
                            let is_aspect_2to1 = (crate::panorama::ASPECT_LOW
                                ..=crate::panorama::ASPECT_HIGH)
                                .contains(&aspect);
                            let is_candidate = intent.is_xmp_pano || is_aspect_2to1;
                            if !is_candidate || intent.prev_base_only {
                                return false;
                            }
                            let approved_max = intent.approved_max_pixels;
                            source_pixels <= crate::panorama::PANO_SETTLE_MAX_PIXELS
                                || source_pixels <= approved_max.saturating_mul(125) / 100
                        });
                    if want_tee {
                        // tee 経路: フル RGBA を作って HighResSource に格納 +
                        // 8K リサイズ ColorImage を fs_cache 用に作る。
                        let rgba_img = img.into_rgba8();
                        let (full_w, full_h) = (rgba_img.width(), rgba_img.height());
                        let max_dim = MAX_TEXTURE_DIM as u32;
                        let (ci, ci_w, ci_h) = if full_w > max_dim || full_h > max_dim {
                            let scale = max_dim as f64 / full_w.max(full_h) as f64;
                            let new_w = ((full_w as f64 * scale).round() as u32).max(1);
                            let new_h = ((full_h as f64 * scale).round() as u32).max(1);
                            let resized = crate::fast_resize::resize_rgba8_exact(
                                &rgba_img,
                                new_w,
                                new_h,
                                crate::fast_resize::Quality::Bilinear,
                            );
                            let ci = egui::ColorImage::from_rgba_unmultiplied(
                                [new_w as usize, new_h as usize],
                                resized.as_raw(),
                            );
                            (ci, new_w, new_h)
                        } else {
                            let ci = egui::ColorImage::from_rgba_unmultiplied(
                                [full_w as usize, full_h as usize],
                                rgba_img.as_raw(),
                            );
                            (ci, full_w, full_h)
                        };
                        // フル RGBA を Arc で共有 (settle render が zero-copy で参照)
                        let raw: Vec<u8> = rgba_img.into_raw();
                        let high_res_rgba = std::sync::Arc::new(raw);
                        let high_res = crate::panorama::HighResSource::Decoded {
                            rgba: high_res_rgba,
                            w: full_w,
                            h: full_h,
                        };
                        let elapsed = t.elapsed().as_secs_f64() * 1000.0;
                        crate::logger::log(format!(
                            "  fs load pano tee: {elapsed:.0}ms  idx={idx}  {name}  full={full_w}x{full_h} ci={ci_w}x{ci_h}"
                        ));
                        if crate::perf::is_enabled() {
                            crate::perf::event(
                                "fs",
                                "decode_end",
                                perf_key_worker.as_deref(),
                                perf_seq,
                                &[
                                    ("ms", serde_json::Value::from(elapsed)),
                                    ("format", serde_json::Value::from(ext.clone())),
                                    ("w", serde_json::Value::from(ci_w)),
                                    ("h", serde_json::Value::from(ci_h)),
                                    ("pano_tee", serde_json::Value::from(true)),
                                    ("full_w", serde_json::Value::from(full_w)),
                                    ("full_h", serde_json::Value::from(full_h)),
                                ],
                            );
                        }
                        let _ = tx.send(FsLoadResult::StaticPanorama {
                            ci,
                            source_dims,
                            high_res,
                        });
                        emit_exit("static_pano_tee");
                        return;
                    }
                    // 既存パス (非 360 候補 / BaseOnly / NeedsUserConfirmation):
                    // GPU テクスチャ上限 (MAX_TEXTURE_DIM=8192) を超える巨大画像は
                    // worker で DynamicImage のまま Bilinear リサイズしておく。
                    let img = clamp_dynamic_for_gpu(img);
                    let (w, h) = (img.width(), img.height());
                    let ci = dynamic_image_to_color_image(&img);
                    let elapsed = t.elapsed().as_secs_f64() * 1000.0;
                    crate::logger::log(format!(
                        "  fs load: {elapsed:.0}ms  idx={idx}  {name}  {w}x{h}"
                    ));
                    if crate::perf::is_enabled() {
                        crate::perf::event(
                            "fs",
                            "decode_end",
                            perf_key_worker.as_deref(),
                            perf_seq,
                            &[
                                ("ms", serde_json::Value::from(elapsed)),
                                ("format", serde_json::Value::from(ext.clone())),
                                ("w", serde_json::Value::from(w)),
                                ("h", serde_json::Value::from(h)),
                            ],
                        );
                    }
                    let _ = tx.send(FsLoadResult::Static { ci, source_dims });
                    emit_exit("static_ok");
                }
                Err(e) => {
                    crate::logger::log(format!("  fs load FAIL: {e}  {name}"));
                    if crate::perf::is_enabled() {
                        crate::perf::event(
                            "fs",
                            "decode_fail",
                            perf_key_worker.as_deref(),
                            perf_seq,
                            &[("format", serde_json::Value::from(ext.clone()))],
                        );
                    }
                    // UI が「読込中...」のまま固まらないよう、失敗を明示的に通知する
                    let _ = tx.send(FsLoadResult::Failed);
                    emit_exit("static_fail");
                }
            }
        });
    }

    fn pdf_display_render_long_edge_for_idx(
        &mut self,
        idx: usize,
        content_type: Option<crate::pdf_loader::PdfPageContentType>,
        content_bbox: Option<egui::Rect>,
    ) -> Option<u32> {
        let viewport = self.fs_pdf_display_target?;
        let (page_w, page_h) = match content_type {
            Some(crate::pdf_loader::PdfPageContentType::Raster { w, h }) => (w as f32, h as f32),
            _ => match self.fs_cache.get(&idx) {
                Some(FsCacheEntry::Static { pixels, .. }) => {
                    (pixels.size[0] as f32, pixels.size[1] as f32)
                }
                _ => return None,
            },
        };
        let rotation = self.get_rotation(idx);
        let swap_page_axes = matches!(
            rotation,
            crate::rotation_db::Rotation::Cw90 | crate::rotation_db::Rotation::Cw270
        );
        let content_type = content_type.unwrap_or(crate::pdf_loader::PdfPageContentType::Vector);
        Some(match content_bbox {
            Some(bbox) => crate::pdf_loader::display_render_long_edge_for_content_bbox(
                viewport,
                page_w,
                page_h,
                swap_page_axes,
                content_type,
                bbox.width(),
                bbox.height(),
            ),
            None => crate::pdf_loader::display_render_long_edge(
                viewport,
                page_w,
                page_h,
                swap_page_axes,
                content_type,
            ),
        })
    }

    pub(crate) fn ensure_pdf_display_resolution(
        &mut self,
        idx: usize,
        content_bbox: Option<egui::Rect>,
    ) {
        let content_type = match self.items.get(idx) {
            Some(GridItem::PdfPage { content_type, .. }) => *content_type,
            _ => return,
        };
        let cached_long = match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Static { pixels, .. }) => pixels.size[0].max(pixels.size[1]) as u32,
            _ => return,
        };
        let Some(target_px) =
            self.pdf_display_render_long_edge_for_idx(idx, content_type, content_bbox)
        else {
            return;
        };
        if (cached_long as f32) < (target_px as f32 * 0.9) {
            self.request_pdf_rerender_at_target(idx, target_px, true);
        }
    }

    /// PDF ページをズーム倍率に応じた解像度で非同期再レンダリングする。
    ///
    /// ワーカーに直接リクエストを送り、結果は `poll_pdf_rerender` で受け取る。
    /// UI スレッドを一切ブロックしない。
    /// `priority=true`: 表示中ページ等の即応再レンダ (PDF worker の priority レーン)。
    /// `priority=false`: AI 先読み用の非表示ページ native 再レンダ (通常レーン、
    /// visible の再レンダ / UI ナビを妨げない)。
    pub(crate) fn request_pdf_rerender(&mut self, idx: usize, zoom: f32, priority: bool) {
        let content_type = match self.items.get(idx) {
            Some(GridItem::PdfPage { content_type, .. }) => *content_type,
            _ => return,
        };

        // ズーム基準は初回と同じ実 viewport×ppp。これにより初回を小さくしても、
        // ズーム時は倍率に応じて従来どおり再レンダされる。AI が native 入力を必要とする
        // raster だけは native を基準にし、全 raster で原稿長辺を絶対上限にする。
        let ai_native_long = match content_type {
            Some(crate::pdf_loader::PdfPageContentType::Raster { w, h }) => {
                let native_long = w.max(h);
                let params = self.effective_params(idx);
                let ai_needs_native = (self.effective_upscale_request(params).is_some()
                    && crate::ai::upscale::should_process_rect(
                        w,
                        h,
                        self.settings.ai_upscale_limit(),
                    ))
                    || (self.effective_denoise_request(params).is_some()
                        && crate::ai::upscale::should_process_rect(
                            w,
                            h,
                            self.settings.ai_denoise_limit(),
                        ));
                ai_needs_native.then_some(native_long)
            }
            _ => None,
        };
        let (base_px, native_cap) = if let Some(native_long) = ai_native_long {
            (native_long, Some(native_long))
        } else {
            let content_bbox = self.pdf_content_bbox_for_display_idx(idx);
            let display_base_px = self
                .pdf_display_render_long_edge_for_idx(idx, content_type, content_bbox)
                .unwrap_or(4096);
            let native_cap = content_type.and_then(|content_type| content_type.native_long_edge());
            (display_base_px, native_cap)
        };
        let target_px = crate::pdf_loader::zoom_render_long_edge(base_px, zoom, native_cap);

        self.request_pdf_rerender_at_target(idx, target_px, priority);
    }

    fn request_pdf_rerender_at_target(&mut self, idx: usize, target_px: u32, priority: bool) {
        let (pdf_path, page_num, password) = match self.items.get(idx) {
            Some(GridItem::PdfPage {
                pdf_path, page_num, ..
            }) => (
                pdf_path.clone(),
                *page_num,
                self.pdf_current_password.clone(),
            ),
            _ => return,
        };

        if self.has_retained_pdf_final_ai_for_current_params(idx) {
            crate::logger::log(format!(
                "[PDF] Retained page final-ai available idx={idx} target_px={target_px} \
                 reason=request_pdf_rerender_skip_pdf_render"
            ));
            return;
        }

        // 既に同じ解像度のキャッシュがあれば不要
        if let Some(FsCacheEntry::Static { pixels, .. }) = self.fs_cache.get(&idx) {
            let cached_long = pixels.size[0].max(pixels.size[1]) as u32;
            let ratio = cached_long as f32 / target_px as f32;
            if (0.9..=1.1).contains(&ratio) {
                return;
            }
        }

        if let Some((pixels, source_dims)) =
            self.lookup_retained_pdf_page_raster(idx, target_px, "request_pdf_rerender")
        {
            if let Some((cancel, _, _)) = self.fs_pending.remove(&idx) {
                cancel.store(true, Ordering::Relaxed);
            }
            self.enqueue_retained_pdf_page_raster_result(
                idx,
                pixels,
                source_dims,
                self.input_seq,
                "request_pdf_rerender",
            );
            return;
        }

        // 進行中の再レンダリングがあればキャンセル
        if let Some((cancel, _, _)) = self.fs_pending.remove(&idx) {
            cancel.store(true, Ordering::Relaxed);
        }

        // ワーカーに非同期リクエスト (UI スレッドをブロックしない)
        let (cancel, render_rx) = crate::pdf_loader::render_page_async(
            &pdf_path,
            page_num,
            target_px,
            password.as_deref(),
            priority,
        );

        // render_page_async は DynamicImage チャネルを返すが、fs_pending は
        // FsLoadResult チャネルを期待するため、ブリッジスレッドで変換する
        let (fs_tx, fs_rx) = mpsc::channel::<FsLoadResult>();
        let perf_seq = self.input_seq;
        self.fs_pending
            .insert(idx, (Arc::clone(&cancel), fs_rx, perf_seq));

        std::thread::spawn(move || {
            match render_rx.recv() {
                Ok(Ok(crate::pdf_loader::RenderResult {
                    image: img,
                    content_type: _content_type,
                    page_count: _,
                })) => {
                    if cancel.load(Ordering::Relaxed) {
                        return;
                    }
                    crate::logger::log(format!(
                        "  pdf rerender done: page={} target_px={target_px} {}x{}",
                        page_num + 1,
                        img.width(),
                        img.height()
                    ));
                    // PDF 再レンダ結果は request_pdf_rerender が 8192 に clamp してから
                    // 投げているので `clamp_dynamic_for_gpu` は実質 no-op だが、不変条件
                    // (fs_cache.pixels ≤ MAX_TEXTURE_DIM) を型レベルで保つため通す。
                    let source_dims = [img.width() as usize, img.height() as usize];
                    let img = clamp_dynamic_for_gpu(img);
                    let ci = dynamic_image_to_color_image(&img);
                    let _ = fs_tx.send(FsLoadResult::Static { ci, source_dims });
                }
                Ok(Err(e)) => {
                    crate::logger::log(format!("  pdf rerender FAIL: {e}"));
                    let _ = fs_tx.send(FsLoadResult::Failed);
                }
                Err(_) => {
                    crate::logger::log("  pdf rerender: cancelled (channel closed)".to_string());
                    // キャンセル時は fs_tx を drop して poll_prefetch が Disconnected で除去
                }
            }
        });
    }

    /// 先読みウィンドウを更新する。
    /// settings の prefetch_back / prefetch_forward に従って先読みを開始し、
    /// ウィンドウ外のキャッシュ・読み込みを破棄する。
    pub(crate) fn update_prefetch_window(&mut self, current_idx: usize) {
        let image_indices = self.collect_image_indices();
        let Some(pos) = image_indices.iter().position(|&i| i == current_idx) else {
            return;
        };
        let n = image_indices.len();

        let pf_back = self.settings.prefetch_back;
        let pf_forward = self.settings.prefetch_forward;
        // KEEP はそれぞれ +1 だけ広く保持してテクスチャ破棄を遅延させる
        let keep_back = pf_back + 1;
        let keep_forward = pf_forward + 1;

        let keep_set: std::collections::HashSet<usize> = (pos.saturating_sub(keep_back)
            ..=((pos + keep_forward).min(n - 1)))
            .map(|p| image_indices[p])
            .collect();

        let prefetch_targets: Vec<usize> =
            interleaved_prefetch_targets(&image_indices, pos, n, pf_forward, pf_back);

        // 退避前に動画の再生位置を保存 (退避された Video エントリは drop で消える)
        self.save_all_video_resume_positions();
        #[cfg(windows)]
        {
            let evicted_video_idxs: Vec<usize> = self
                .fs_cache
                .iter()
                .filter_map(|(k, v)| {
                    (!keep_set.contains(k) && matches!(v, FsCacheEntry::Video { .. })).then_some(*k)
                })
                .collect();
            for idx in evicted_video_idxs {
                self.cleanup_normalize_state_for_fs_idx(idx);
            }
        }
        // KEEP 範囲外のテクスチャを破棄（VRAM 節約）
        self.fs_cache.retain(|k, _| keep_set.contains(k));
        self.fs_lanczos_cache.retain_page_indices(&keep_set);
        self.fs_margin_bbox_cache
            .retain(|k, _| keep_set.contains(k));

        // 現在表示中の画像がまだ表示可能な状態へ到達していないなら、
        // その画像に CPU を独占させるため他の pending をすべてキャンセルする。
        // 現在画像が完了したあと poll_prefetch から再度 update_prefetch_window が
        // 呼ばれ、そこで先読みが開始される。これにより 1→2 遷移 (サムネ → フル解像度) が
        // 先読みスレッドに待たされなくなる。retained PDF final-AI は raw fs_cache が無くても
        // 表示可能なので、typed state では loading に分類しない。
        let current_loading = self.fs_page_load_state(current_idx).waiting_for_display();

        let to_cancel: Vec<usize> = self
            .fs_pending
            .keys()
            .filter(|&&k| {
                if k == current_idx {
                    return false;
                }
                // 現在画像がロード中なら全 pending をキャンセル。そうでなければ KEEP 範囲外のみ。
                current_loading || !keep_set.contains(&k)
            })
            .cloned()
            .collect();
        for k in to_cancel {
            if let Some((cancel, _, _)) = self.fs_pending.remove(&k) {
                cancel.store(true, Ordering::Relaxed);
            }
            // 先行 dims ヒントはキャンセルされた idx では意味がないので破棄。
            self.fs_early_dims.remove(&k);
        }

        if current_loading {
            // Paged and continuous-reading prefetch must both re-assert the
            // current producer: `NeedsLoad` may cancel siblings but must not
            // leave the display target without an in-flight request.
            self.ensure_fs_page_load(current_idx);
            return;
        }

        // まだキャッシュにも pending にもない先読み対象を読み込み開始
        for idx in prefetch_targets {
            if self.fs_page_load_state(idx).needs_load_request() {
                crate::logger::log(format!("  prefetch start idx={idx}"));
                self.ensure_fs_page_load(idx);
            }
        }
    }

    /// 現在の表示順の中の画像アイテム (通常 + ZIP 内 + PDF) の item_idx 一覧を返す。
    ///
    /// フルスクリーンの前後移動 / スライドショーはフィルタ後かつ詳細表示では
    /// `details_order` 適用後の display list を使うため、先読みも同じ順序に揃える。
    /// ★フィルタや Ctrl+F で疎な一覧になっても、非表示の raw idx を先読みしない。
    fn collect_image_indices(&self) -> Vec<usize> {
        Self::collect_image_indices_from(&self.items, self.current_grid_order())
    }

    fn collect_image_indices_from(items: &[GridItem], visible_indices: &[usize]) -> Vec<usize> {
        visible_indices
            .iter()
            .copied()
            .filter(|&i| {
                matches!(
                    items.get(i),
                    Some(GridItem::Image(_))
                        | Some(GridItem::ZipImage { .. })
                        | Some(GridItem::PdfPage { .. })
                )
            })
            .collect()
    }

    /// フルスクリーンの「閉じる」要求 (Esc / Enter / 右クリック / ビューポート close) の共通処理。
    ///
    /// **「ページを直接開く」設定が ON で ZIP/PDF ページ、または追加設定 ON の画像のみ
    /// 通常フォルダを見ているとき**は、ページ一覧 (L2) を経由せずファイル一覧 (L1) まで戻る。
    /// 判定は `auto_open_for_current_container()` (= 設定 ON & 対象コンテナ内 & 非検索) のみで、
    /// 直接オープン由来かどうかは見ない。それ以外 (設定 OFF / 対象外の通常画像) は 1 段だけ閉じる
    /// (`close_fullscreen`: コンテナなら L2 ページ一覧、通常画像なら親フォルダグリッド)。
    ///
    /// L1 へ戻る経路は L2 を 1 フレームも見せないため、その場では close せず
    /// `pending_return_to_parent` を立てるだけにし、`App::update` の入力ナビ合流点が
    /// 通常のナビ (load → 内部で close_fullscreen) を発行する。BS は階層を 1 段だけ戻す
    /// (= 常に L2) ので本関数を通さず `close_fullscreen` を直接呼ぶ (ui_fullscreen 側)。
    pub(crate) fn handle_fullscreen_close_request(&mut self) {
        // Detached bookmark viewers never navigate their own bundle to the bookmark surface: the
        // origin grid is still mounted in main. Embedded viewers instead use the normal Bookmarks
        // navigation transition. Ownership is explicit in BookmarkViewState, not inferred from a
        // missing grid snapshot.
        if !matches!(
            self.bookmark_view_state,
            Some(BookmarkViewState::Detached { .. })
        ) && self.bookmark_view_close_nav().is_some()
        {
            self.pending_return_to_parent = true;
            return;
        }
        if let Some(BookmarkViewState::Detached {
            target: target @ crate::bookmark_browser::BookmarkViewReturnTarget::Media(_),
        }) = self.bookmark_view_state.as_ref()
            && !self.bookmark_target_is_current(target)
        {
            // Media navigation changes the detached context's disposition: closing after moving
            // to another file returns main to that real folder. Books intentionally keep their
            // origin grid even after page/container navigation.
            self.bookmark_view_state = None;
        }
        if self.auto_open_for_current_container() {
            self.pending_return_to_parent = true;
            return;
        }
        // グリッドへ戻る = detached セッションの明示終了 (§3.7 closing)。folder-nav の
        // 内部 close とは別経路なので、ここでは確実に session を畳んでよい。
        #[cfg(windows)]
        {
            self.begin_active_detached_session_close("handle_fullscreen_close_request");
            self.finish_active_detached_session_close("handle_fullscreen_close_request");
        }
        self.close_fullscreen();
    }

    /// `App::update` の通常の pending-nav 消化点より後で届く close イベント向け。
    ///
    /// Windows native presenter のキー・マウス・ウィンドウイベントは、そのフレームの
    /// pending-nav 消化後に処理されることがある。通常の close 要求を発行した直後に同じ
    /// ナビをここで消化し、ブックマーク一覧への復帰を次フレームへ取り残さない。
    pub(crate) fn handle_fullscreen_close_request_immediate(&mut self) {
        self.handle_fullscreen_close_request();
        let Some(nav) = self.take_pending_return_to_parent_nav() else {
            return;
        };
        if !self.apply_fullscreen_close_nav_immediate(nav) {
            // 現在 resolve_return_to_parent_nav が返すナビはすべて即時適用可能だが、
            // 将来対象外のナビが増えても要求を失わず通常の update 経路へ戻す。
            self.pending_return_to_parent = true;
        }
    }

    #[cfg(windows)]
    fn prepare_viewer_presentation_close(&mut self) {
        // フォルダナビ (Ctrl+↑↓) の reopen 中は detached セッションの identity を保つ。
        // load_folder → start_loading_items が new items 導入前に close_fullscreen を呼ぶため、
        // ここで detached_viewer_window_id をクリアすると、reopen 側の
        // ensure_detached_viewer_window_id が新しい window_id を allocate し、
        // fullscreen_viewport_id (= detached では window_id 由来) が変わって egui が
        // OS ウィンドウを破棄→再生成する。これが「次フォルダへ移るたびにウィンドウが
        // 再表示される / 既定サイズ (822x656) の小窓が一瞬カスケード表示される」症状の
        // 原因 (実機動画 2026-06-28 で確認)。ロック中は window_id / presentation /
        // live placement を維持して、同じウィンドウの中で内容だけ差し替える。
        // 判定は fs_nav ロックだけに頼らない。PDF/ZIP の非同期 enumerate 待ちでは
        // load_pdf_as_folder / start_loading_items の close 時点で fs_nav ロックが
        // 立っていないことがあり、その場合 presentation が non-detached に落ちて
        // keep_fullscreen_viewport_alive が detached viewport を描画しなくなり、
        // egui が detached の OS ウィンドウを破棄→reopen で再生成 (= 小窓) してしまう。
        // wrapper (close_fullscreen_for_folder_nav_reopen) が立てる reuse 意図
        // (detached_viewer_folder_nav_reuse_window_once) も条件に含めて、folder-nav
        // reopen の間ずっと detached identity を維持する。
        // 判定は session 状態 (`detached_active_window_alive_wanted`) を使う。close_fullscreen は
        // 先に `fullscreen_idx=None` にしてから本関数を呼ぶことがあり、`viewer_session_is_detached()`
        // (= fullscreen_idx.is_some() 必須) だと folder-nav 中でも false になって borderless 等を
        // 誤クリアする (window_id は reuse フォールバックで救われていたが borderless は救われず、
        // F11 仮想フルスクリーンが folder-nav で最大化に化けていた)。session が alive (=未 close)
        // の間は detached identity を維持する。
        let preserve_detached_for_folder_nav = self.detached_active_window_alive_wanted();
        if !preserve_detached_for_folder_nav {
            self.viewer_presentation = self.non_detached_viewer_presentation();
            self.last_viewer_sync_stamp = None;
            self.detached_viewer_focus_requested = false;
            self.detached_viewer_recreate_on_next_render = false;
            self.detached_viewer_independent_active = false;
            self.detached_viewer_open_next_still_detached_once = false;
            self.detached_viewer_folder_nav_reuse_window_once = false;
            self.detached_viewer_window_id = None;
            self.fs_viewport_virtual_desktop_synced_hwnd = 0;
            self.clear_detached_viewer_borderless_fullscreen_state();
        }
        self.vst3_deferred_media_open = None;
        self.native_video_front_synced_hwnd = 0;
        self.native_video_front_last_raise = None;
        self.native_video_front_recover_after_external_foreground = false;
        self.native_video_pointer_down = None;
        self.native_video_context_menu_dismiss_click_started_at = None;
        self.native_video_secondary_press_start = None;
        self.native_video_middle_press_start = None;
        self.schedule_native_video_main_chrome_restore();
        let native_video_was_active = self.native_video_fullscreen_active_for_main_backdrop();
        if native_video_was_active || self.native_video_main_cloaked {
            // SetForegroundWindow cannot reliably target a cloaked HWND. Bring
            // the main window back into DWM composition before scheduling the
            // foreground reclaim, while the presenter/backdrop still mask it.
            self.sync_native_video_main_cloak(false);
        }
        if native_video_was_active && let Some(hwnd_raw) = self.main_hwnd {
            crate::dwm_iconic_thumbnail::sync_video_source(hwnd_raw as u64, None);
        }
        // 動画フルスクリーンだったときだけ奪還候補。
        // mIV が foreground を持っていた瞬間にだけ true にする (ユーザーが他アプリを
        // 意図的に前面にしていたケースで奪い返さないため)。
        // foreground=null/pid=0 の不確定ケースは保守的に false 扱い。
        let foreground_is_ours =
            crate::video::native_window::foreground_belongs_to_current_process_strict();
        // in-window モードでは presenter は main の子で、close 時も main が
        // foreground のまま。fullscreen 用の foreground 奪還は不要なのでスキップ
        // (Codex P2)。
        if native_video_was_active && foreground_is_ours && !self.native_video_in_window_active {
            self.pending_main_foreground_reclaim = true;
            self.pending_main_foreground_reclaim_after_hwnd =
                self.native_video_presenter_hwnd().unwrap_or(0);
            self.pending_main_foreground_reclaim_force_at =
                Some(std::time::Instant::now() + std::time::Duration::from_millis(200));
        } else {
            self.clear_pending_main_foreground_reclaim();
            if native_video_was_active {
                crate::logger::log(
                    "[native-video] foreground_unknown_or_foreign at close_fullscreen, \
                     skip reclaim"
                        .to_string(),
                );
            }
        }
    }

    /// フォルダ横断ナビ用にフルスクリーン状態だけを閉じる。
    ///
    /// 通常の `close_fullscreen` は次フレームの cleanup で viewport を隠し、必要なら
    /// ViewportId 世代を進める。Ctrl+↑↓ / 進む戻るボタンのフォルダ移動では直後に
    /// `open_fullscreen` で再表示するため、detached viewer の OS ウィンドウまで
    /// 再生成するとサイズ復元やフォーカスで不自然な動きになる。detached のときだけ
    /// viewport ホストを保持し、中身のセッション状態は `close_fullscreen` と同じく
    /// 破棄してから次フォルダを開く。
    pub(crate) fn close_fullscreen_for_folder_nav_reopen(&mut self) {
        #[cfg(windows)]
        {
            let preserve_detached_viewport = self.viewer_session_is_detached()
                && self.fs_viewport_shown
                && self.fs_viewport_presentation == Some(ViewerPresentation::DetachedWindow);
            if preserve_detached_viewport {
                let viewer_presentation = self.viewer_presentation;
                let fs_viewport_presentation = self.fs_viewport_presentation;
                let detached_viewer_window_id = self.detached_viewer_window_id;
                let detached_viewer_borderless_fullscreen =
                    self.detached_viewer_borderless_fullscreen;
                let detached_viewer_restore_placement = self.detached_viewer_restore_placement;
                let detached_viewer_independent_active = self.detached_viewer_independent_active;
                let detached_viewer_open_next_still_detached_once =
                    self.detached_viewer_open_next_still_detached_once;
                let fs_viewport_generation = self.fs_viewport_generation;
                self.close_fullscreen();
                // Ctrl+↑↓ is an internal viewer-to-viewer reopen. If a stale
                // grid-open intent survives here, always-new detached mode can
                // allocate a fresh window_id and briefly show the default-sized
                // viewport instead of reusing the existing detached host.
                self.fs_open_intent_from_grid = false;
                self.fs_viewport_shown = true;
                self.viewer_presentation = viewer_presentation;
                self.fs_viewport_presentation = fs_viewport_presentation;
                self.detached_viewer_window_id = detached_viewer_window_id;
                self.detached_viewer_borderless_fullscreen = detached_viewer_borderless_fullscreen;
                self.detached_viewer_restore_placement = detached_viewer_restore_placement;
                self.detached_viewer_independent_active = detached_viewer_independent_active;
                self.detached_viewer_open_next_still_detached_once =
                    detached_viewer_open_next_still_detached_once;
                self.fs_viewport_generation = fs_viewport_generation;
                self.fs_viewport_recreate_after_hide = false;
                self.detached_viewer_folder_nav_reuse_window_once =
                    detached_viewer_window_id.is_some();
                self.clear_pending_main_foreground_reclaim();
                crate::logger::log(format!(
                    "[detached-viewer] preserve viewport for folder-nav reopen: selected={:?} \
                     generation={} window_id={:?} reuse_once={} host={}",
                    self.selected,
                    self.fs_viewport_generation,
                    self.detached_viewer_window_id,
                    self.detached_viewer_folder_nav_reuse_window_once,
                    self.detached_viewer_host_debug_state()
                ));
                return;
            }
        }
        self.close_fullscreen();
        // Folder navigation is never a grid-originated open; prevent a stale
        // intent from changing detached window allocation on the next reopen.
        self.fs_open_intent_from_grid = false;
    }

    /// フルスクリーン表示を終了し、先読みキャッシュを全クリアする。
    ///
    /// `fs_viewport_shown` は意図的に残す: 次フレームの
    /// `keep_fullscreen_viewport_alive` がこのフラグを見て Visible(false) を
    /// 送信し、その直後に false に落とす。ここで先に落とすと送信が抑止される。
    pub(crate) fn close_fullscreen(&mut self) {
        // teardown で fullscreen_idx / edit_result_cache を落とす前に、現在見えている
        // 最新の edit-result を snapshot。実際の encode / 保存は reset 系の DB 更新
        // command より後へ enqueue し、旧 preview の invalidate が後着しない順序にする。
        let edit_preview_close_update = self
            .fullscreen_idx
            .and_then(|idx| self.snapshot_edit_preview_close_update(idx));
        self.cancel_media_navigation_pending_for_current_context("close_fullscreen");
        // 表示モード / フィットのポップアップを開いたまま抜けると、次回フルスクリーンで
        // メニューが残り、カーソル自動非表示やページ送りの抑制が効いたままになるため解除する。
        self.spread_popup_open = false;
        self.fit_popup_open = false;
        self.slideshow_popup_open = false;
        self.cancel_mouse_ring_flick();
        self.capture_region_selection = None;
        self.clear_fullscreen_tag_picker_state();
        // 音楽ビュー (Inc 3b/4) の解析ワーカー + row raster + spectrum worker + PCM を止めて捨てる
        // (フルスクリーンを抜けたら別ファイル扱い。§7.9 grid/viewer lifecycle)。
        // ただし別メディア窓の active / ParkedLive bundle が global music_* を消費中なら
        // 破棄しない。実際のメディア窓 close は bundle を mount してからここへ入るため、
        // その場合は consumer が残らず従来どおり teardown される (review-v2.3.0 P2-3)。
        #[cfg(windows)]
        let detached_music_alive = self.detached_music_window_exists();
        #[cfg(not(windows))]
        let detached_music_alive = false;
        if !detached_music_alive {
            self.clear_music_view_state();
        }
        // 「動画→音声モード」(Inc 7) はフルスクリーンを閉じたら終わる。動画プレイヤーはこの後
        // fs_cache.clear() で drop されるので、ここではフラグを落とすだけでよい (Codex 7c 設計)。
        self.video_audio_mode = None;
        // 7e: VST ホスト状態も落とす。VST GUI の hide/re-owner は下の VST cleanup
        // (show_vst3_manager 経路) が、presenter の drop は fs_cache.clear() が行うので、
        // ここではフラグを落とすだけでよい (re-hide 不要 = presenter ごと drop される)。
        self.video_audio_vst = None;
        #[cfg(windows)]
        {
            self.video_audio_mode_entry_target = None;
            self.video_audio_exit_pending = None;
        }
        // 音声 VST シェル (Inc 6 ②-3): フルスクリーンを完全に閉じるならシェル状態も落とす。
        // VST GUI の hide/re-owner は下の VST cleanup (show_vst3_manager 経路) が、native 出力の
        // drop は fs_cache.clear() が行うので、ここではフラグを落とすだけでよい。
        #[cfg(windows)]
        {
            self.music_vst_shell = None;
        }
        // 分析モード (Z) は一覧に戻ったら必ず解除する。さもないと次にフルスクリーンを
        // 開いたとき分析モードのまま起動してしまう (fullscreen_idx がまだ有効なうちに呼ぶ)。
        if self.analysis_mode {
            self.reset_analysis_mode();
        }
        // ZipPla 風全画面ズーム (Z) も一覧に戻ったら解除する (倍率はセッション保持のため残す)。
        self.fs_zoom_reset();
        // フルスクリーン解除前に動画再生位置を保存 (drop で消える前に)
        self.save_all_video_resume_positions();
        // 進行中のノーマライズスキャンをキャンセル + 全 fs_idx の UI 状態をクリア
        // (= フルスクリーン抜けると別動画扱い、stale fs_idx 復活防止)
        #[cfg(windows)]
        {
            self.pending_detached_video_host_switch = None;
            let fs_idxs: Vec<usize> = self.normalize_ui_states.keys().copied().collect();
            for idx in fs_idxs {
                self.cleanup_normalize_state_for_fs_idx(idx);
            }
        }
        self.restore_grid_cursor_to_fullscreen_item();
        #[cfg(windows)]
        self.prepare_viewer_presentation_close();
        #[cfg(windows)]
        if self.show_vst3_manager || self.settings.vst3_gui_visible {
            self.native_video_owner_synced_hwnd = 0;
            // The normal per-frame fullscreen-state watcher also hides VST
            // editors, but doing it here keeps bridge-owned plugin surfaces
            // from lingering for a frame after the fullscreen viewport closes.
            self.dsp_bridge.set_existing_guis_owner_to_main();
            self.dsp_bridge.set_all_guis_visible(false);
            self.dsp_bridge.set_all_guis_topmost(false);
            self.show_vst3_manager = false;
            self.vst3_was_fullscreen = false;
            if self.settings.vst3_gui_visible {
                self.settings.vst3_gui_visible = false;
                self.settings.save();
            }
        }
        // Phase 8.B': 動画ピン留めが変更されていたら現在フォルダを再ロードして
        // グリッドサムネに反映 (= ピンの WebP がグリッド表示に出る)。
        // close_fullscreen + メインの update 両方から拾うため共通ヘルパー経由
        // (folder_thumb_pin_dirty と同じ構造。フル機能モード + メディア別ウィンドウ
        // では close_fullscreen を通らずメイン窓のグリッドが開きっぱなしになるため)。
        self.consume_video_thumb_overrides_dirty();
        // 親コンテナ (Folder/ZipFile/PdfFile) の代表サムネピンが書き換わっていたら
        // 同じく現フォルダを再ロードしてグリッドに反映する。
        // close_fullscreen + メインの update 両方から拾うため共通ヘルパー経由
        // (Codex Phase D P2 指摘: dirty が close_fullscreen でしか consume されず、
        // グリッドモードで 📌 を押しても次の fullscreen 開閉まで反映されなかった)。
        self.consume_folder_thumb_pin_dirty();
        // perf: close_fullscreen は fs_cache / ai_upscale_cache / pending スレッドの
        // キャンセル通知を行うため、Ctrl+↑↓ (Fullscreen モード) の sync パスで
        // 実行される。ms を計測してブロックの所在を特定する。
        let cf_t0 = std::time::Instant::now();
        let cf_seq = self.input_seq;
        let cf_was_open = self.fullscreen_idx.is_some();
        let cf_fs_cache = self.fs_cache.len();
        let cf_ai_cache = self.ai_upscale_cache.len();
        if cf_was_open
            && matches!(
                self.bookmark_view_state,
                Some(BookmarkViewState::Opening { .. })
            )
        {
            // 一覧へ戻る close は `handle_fullscreen_close_request` が先に nav を予約し、
            // `enter_bookmark_view` でこの target を消費してからここへ来る。ここに target が
            // 残っている real close は、別ファイル移動後 / BS 等で実フォルダへ戻る経路なので、
            // 後から元ファイルを再度開いた際に stale な一覧復帰が発火しないよう破棄する。
            self.clear_bookmark_view_return_state();
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "close_fullscreen_begin",
                None,
                cf_seq,
                &[
                    ("was_open", serde_json::Value::from(cf_was_open)),
                    ("fs_cache", serde_json::Value::from(cf_fs_cache)),
                    ("ai_cache", serde_json::Value::from(cf_ai_cache)),
                ],
            );
        }
        // フルスクリーン発起点の Ctrl+↑↓ DFS が走っていたら、ユーザーが
        // フルスクリーンを抜けた = フルスクリーン復帰の意図がなくなったとみなし
        // キャンセルする。apply_folder_nav_result 内の close_fullscreen
        // (Fullscreen / Favsearch fullscreen ブランチ) は既に poll で
        // folder_nav_pending を取り出した後なので、
        // self.folder_nav_pending は None = ここでキャンセルされない。
        if let Some(pending) = self.folder_nav_pending.as_ref() {
            if matches!(
                pending.mode,
                FolderNavMode::Fullscreen
                    | FolderNavMode::SiblingFullscreen
                    | FolderNavMode::Favsearch {
                        fullscreen: true,
                        ..
                    }
            ) {
                pending.cancel.store(true, Ordering::Relaxed);
                self.folder_nav_pending = None;
                self.clear_pending_folder_nav_steps();
                // ユーザーが Esc 等で DFS 中にフルスクリーンを抜けた場合、items は
                // 入れ替わらないので poll_fs_nav_lock では release されない。
                // ここで明示的に lock / holdover を捨てる (Codex P1)。
                // apply_folder_nav_result 内の close_fullscreen は事前に
                // pending を take しているので folder_nav_pending=None でこの分岐に
                // 入らず、内部 close→open 遷移のロックは保持される。
                self.release_fs_nav_lock();
            }
        }
        #[cfg(windows)]
        let preserve_viewport_for_folder_nav_reopen = self.fs_nav_locked_gen.is_some()
            && self.fs_viewport_shown
            && matches!(
                self.fs_viewport_presentation,
                Some(ViewerPresentation::Fullscreen | ViewerPresentation::DetachedWindow)
            )
            && !self.native_video_fullscreen_active_for_main_backdrop();
        #[cfg(not(windows))]
        let preserve_viewport_for_folder_nav_reopen =
            self.fs_nav_locked_gen.is_some() && self.fs_viewport_shown;

        self.reset_fs_side_panel_runtime_for_file_change();
        self.fullscreen_idx = None;
        self.fs_pdf_display_target = None;
        // `close_fullscreen` is also used as a generic teardown from
        // `start_loading_items`, even when no viewer is open.  Refreshing the
        // bookmark surface in that path creates a loop:
        // install rows -> start_loading_items -> close_fullscreen -> refresh -> install rows.
        // Only a real viewer close may need to pick up bookmark changes made
        // while the viewer was open.
        if cf_was_open && self.items_are_bookmark_view {
            self.refresh_bookmark_browser();
        }
        // Ctrl+E ダイアログ / 進捗モーダルはフルスクリーン文脈に紐付くので、
        // close_fullscreen と同時に閉じる (Codex review CONFIRMED)。
        // 進捗中の worker は cancel フラグを立てて自然終了を待つ (= 進行中エントリは
        // 完了まで残るが、後続エントリは drop される)。
        self.export_dialog = None;
        if let Some(pending) = self.export_pending.as_ref() {
            pending
                .cancel
                .store(true, std::sync::atomic::Ordering::Relaxed);
        }
        self.export_pending = None;
        // **`export_folder_refresh_pending` は触らない**: これは「一覧に戻ったら
        // サムネ更新」の dirty フラグ (commit 1cdf9c53 で導入) で、`consume_*` が
        // 同フレ末で取り出す前提。close_fullscreen 内で None に戻すと取り出す前に
        // 消えて、エクスポート後にサムネが更新されない (Codex review P1 再指摘)。
        self.fullscreen_video_marker_cache = None;
        self.cancel_fullscreen_video_marker_thumb_decode();
        // 360 度パノラマビュー: フルスクリーン退出で state と GPU リソースを drop。
        // docs/panorama-360-view-plan.md §5.1 / §6.3。CallbackResources からも
        // UploadedPanoTextureRef を除去 (Codex P2 第 18 ラウンド)。
        self.panorama_state = None;
        self.clear_pano_upload();
        self.pano_toast_shown_for_current_fs = false;
        // Phase 2a (§4.6.3 step 8): フル RGBA (最大 2.15 GB) を drop + 進行中 worker を cancel。
        // refinement は **cancel signaling 付きヘルパ**で落とす (Codex P0 第 5、2026-05)。
        self.clear_pano_refinement();
        self.pano_high_res_source.clear();
        for (_, req) in self.pano_high_res_pending.drain() {
            req.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        // `pano_quality_state` を session 内で完全保持しない (Codex P2 第 5、2026-05):
        // 元実装には clear/remove が一切無く、長時間セッションで 100k+ 画像を開くと
        // 際限なく成長する。close_fullscreen は session 内の自然な境界なので、ここで
        // **NeedsUserConfirmation / SettleApproved 以外** をクリーンアップする。
        // 「ユーザーが明示判断したエントリ (NeedsUserConfirmation / BaseOnly /
        // SettleApproved)」は次回 360 表示で同じ判断を反映するため保持する。
        //
        // **ただし `pano_high_res_failed` のエントリに対応する BaseOnly は除去**
        // (Codex P2 第 8、2026-05): failure 起因で BaseOnly に倒したエントリは
        // 「ユーザー明示判断」ではないので、次回 reopen で再分類できるよう state も
        // 一緒に破棄する。これで failure が transient (= 一時的なファイルロック等)
        // だった場合に次回試行できる。
        let failed_keys: std::collections::HashSet<String> =
            self.pano_high_res_failed.iter().cloned().collect();
        self.pano_quality_state.retain(|key, s| {
            // SettleReady: 一律 drop (= status indicator のフォールスルー用、保持不要)
            if matches!(s, crate::panorama::PanoramaQualityState::SettleReady) {
                return false;
            }
            // failure 起因の BaseOnly: drop (= 次回 reopen で再分類)
            if matches!(s, crate::panorama::PanoramaQualityState::BaseOnly)
                && failed_keys.contains(key)
            {
                return false;
            }
            true
        });
        self.pano_high_res_failed.clear();
        self.pano_banner_remember_session = false;
        #[cfg(windows)]
        {
            self.pending_pin_thumb_refresh = None;
        }
        // 動画ループの baseline (= 直前 tick の position/serial) もクリアする。
        // 次回フルスクリーンで別動画を開いたときに古い baseline を引き継いで誤爆 seek を
        // 起こさないため。
        self.last_loop_pos.clear();
        self.video_continuous_last_eof = None;
        // Ctrl+↑↓ のフォルダ横断は close → load → reopen の内部遷移として扱う。
        // PDF/ZIP は非同期 enumerate を挟むため、fullscreen_idx=None の待機窓が
        // 数フレーム生じる。この間に viewport を再作成対象へ回すと、列挙完了後の
        // reopen が新規入場のように見える。nav lock が生きている内部遷移では
        // 既存 viewport を維持し、通常の Esc/Enter close だけ再作成対象にする。
        self.fs_viewport_recreate_after_hide = !preserve_viewport_for_folder_nav_reopen;
        #[cfg(windows)]
        {
            self.still_fullscreen_viewport_enter_suppress_until = None;
        }
        // 次回フルスクリーン入場時に古い活動時刻 / hidden 状態を引き継がないようクリア。
        self.cursor_last_activity = None;
        self.cursor_hidden = false;
        // ※ ここで `fs_nav_locked` / `fs_holdover_tex` を即時クリアしてはいけない:
        //   `apply_folder_nav_result` の Fullscreen 分岐は close_fullscreen → load_folder
        //   → open_fullscreen と直列に呼ぶ。途中で lock を捨てると PDF/ZIP enumerate defer
        //   中の黒画面抑止や連続入力抑止が効かなくなるため、`poll_fs_nav_lock` 側で
        //   新ページの tex 準備、またはフルスクリーンが本当に閉じたことを確認してから
        //   解除する。実ページ描画で旧 holdover を使うかどうかは
        //   `fs_nav_holdover_for_draw` が別途判定する。
        // PDF pool の Critical 予約は v1.0.0 から常時 ON 方針なので、ここで切替えない。
        // フルスクリーン中の Undo スタックはここで破棄。グリッドに戻ったら新しい操作を積む。
        self.clear_meta_undo();
        self.slideshow_playing = false;
        self.slideshow_anchor_idx = None;
        self.continuous_reading_scroll_transition = None;
        self.slideshow_scroll_range_cache = None;
        self.fs_opened_at = None;
        self.fs_focus_grace_elapsed = false;
        self.fs_prev_focused = false;
        self.fs_focus_regained_at = None;
        self.fs_prev_foreground_hwnd = 0;
        self.fs_last_native_focus_claim_at = None;
        self.fs_last_main_focus_restore_at = None;
        self.fs_primary_suppression = Default::default();
        self.fs_secondary_press_start = None;
        #[cfg(windows)]
        {
            self.native_video_secondary_press_start = None;
            self.native_video_middle_press_start = None;
        }
        self.mouse_ring_flick = None;
        self.mouse_gesture = None;
        self.gamepad_favorite_picker = None;
        self.gamepad_location_picker = None;
        self.gamepad_video_marker_picker = None;
        self.mouse_ring_grid_target_idx = None;
        self.mouse_gesture_grid_target_idx = None;
        self.mouse_ring_suppress_context_menu_once = false;
        self.fs_middle_zoom_drag = None;
        self.mouse_middle_click_start = None;
        self.fs_seek_drag_active = false;
        self.fs_seek_overlay_visible = false;
        self.fs_context_menu_idx = None;
        // Phase 5.5: タイルモードもフルスクリーン解除と同時に閉じる (Codex H2 反映)。
        #[cfg(windows)]
        {
            let detached_pending_owner = self.active_detached_viewer_context_contains_video()
                || self.parked_live_media_window_exists()
                || self
                    .native_video_source_swap_pending
                    .as_ref()
                    .is_some_and(|pending| pending.parked_live_window_id.is_some())
                || self
                    .native_video_open_pending
                    .as_ref()
                    .is_some_and(|pending| pending.parked_live_window_id.is_some())
                || self
                    .native_video_fast_swap_pending
                    .as_ref()
                    .is_some_and(|pending| pending.parked_live_window_id.is_some())
                || self
                    .video_tile_swap_pending
                    .as_ref()
                    .is_some_and(|pending| pending.parked_live_window_id.is_some());
            if !detached_pending_owner {
                self.video_tile_state = None;
                self.video_tile_mode_active = false;
                self.video_tile_reopen_pending = false;
                self.video_tile_reopen_deadline = None;
                self.video_tile_swap_pending = None;
                self.native_video_deferred_nav_delta = None;
            }
            // App-global native pending は mounted context owner (None) だけ閉じる。
            // Some(window_id) は別 ParkedLive context の presenter/open を所有しているため、
            // main 画像の close から破棄しない (review-v2.3.0 追補2 BA-7)。
            self.clear_mounted_native_video_pending();
        }
        self.reset_erase_mode();
        self.reset_conceal_mode();
        // テキストモードもフルスクリーン解除時に保存して閉じる (Codex P1: 閉じ経路で
        // text_mode がリークすると次回フルスクリーンで通常ショートカットが効かなくなり、
        // 編集も保存されない)。reset_conceal_mode と同じくこの時点では fullscreen_idx が
        // まだ有効なので save_comic_objects が正しいページに効く。export_crop と同じ理由で
        // spread_ctx は復元せず破棄する (close は fullscreen_idx=None を維持するため)。
        self.text_spread_ctx = None;
        self.reset_text_mode();
        // close は fullscreen_idx=None を維持する。spread_ctx を残すと
        // reset_export_crop_mode が fullscreen_idx を旧ページへ復元してしまい、
        // フォルダロード経路 (start_loading_items→close_fullscreen) で stale な
        // fullscreen idx を引き継ぐため、復元せず破棄する (Codex P1)。
        self.export_crop_spread_ctx = None;
        self.reset_export_crop_mode();
        self.persist_pending_view_trim_state();
        self.view_trim_mode = false;
        self.view_trim_page_apply_root_idx = None;
        self.view_trim_page_spread_separate = self.view_trim_book_settings.spread_separate;
        self.local_adjust_mode = false;
        self.local_adjust_repair_point_pick_active = None;
        self.local_adjust_add_layer_dialog_open = false;
        self.local_adjust_change_mask_dialog_open = false;
        self.local_adjust_change_mask_keep_manual_override = true;
        self.local_adjust_effect_picker_dialog_open = false;
        self.local_adjust_canvas_drag = None;
        self.local_adjust_mask_brush_stroke = None;
        self.local_adjust_mask_lasso_points.clear();
        self.local_adjust_mask_shape_drag_start = None;
        self.local_adjust_mask_shape_drag_end = None;
        self.local_adjust_selected_shape = None;
        self.local_adjust_shape_drag = None;
        self.local_adjust_canvas_drag_before_layers = None;
        self.local_adjust_shape_drag_before_layers = None;
        self.local_adjust_mask_brush_before_layers = None;
        self.local_adjust_brush_deferred_render = None;
        self.local_adjust_segmentation_pending = None;
        self.enqueue_edit_preview_close_update(edit_preview_close_update);
        self.erase_base_cache.clear();
        self.conceal_base_cache.clear();
        self.conceal_cache.clear();
        self.comic_cache.clear();
        self.cancel_all_comic_bakes();
        self.erase_result_cache.clear();
        self.edit_result_cache.clear();
        self.clear_all_final_pipeline_caches_for_session_close();
        for (cancel, _, _) in self.fs_pending.values() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.fs_pending.clear();
        self.fs_early_dims.clear();
        // 2026-05-15: fs_cache.clear() は内部で `Drop for VideoPlayer` → `Drop for
        // NativeVideoOutput` → `Drop for AudioOutput` の連鎖を起こし、各 Drop で
        // worker thread の join (cancel + 待ち) が走る。back-pressure deadlock や
        // GPU stuck 状態だと UI thread が無期限ブロックする可能性があるので、
        // 所要時間を perf event に記録して "応答なし" の発生位置を切り分け可能にする
        // (Codex 助言 #3)。エントリ数も合わせて記録。
        let fc_drop_t0 = std::time::Instant::now();
        let fc_drop_count = self.fs_cache.len();
        self.fs_cache.clear();
        self.fs_lanczos_cache.clear();
        self.fs_margin_bbox_cache.clear();
        let fc_drop_ms = fc_drop_t0.elapsed().as_secs_f64() * 1000.0;
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "close_fullscreen_fs_cache_clear",
                None,
                cf_seq,
                &[
                    ("ms", serde_json::Value::from(fc_drop_ms)),
                    ("entries", serde_json::Value::from(fc_drop_count as i64)),
                    (
                        "live_decoders",
                        serde_json::Value::from(
                            crate::video::decoder::LIVE_VIDEO_DECODE_THREADS.load(Ordering::Acquire)
                                as i64,
                        ),
                    ),
                ],
            );
        }
        if fc_drop_ms > 50.0 {
            crate::logger::log(format!(
                "[close-fullscreen] fs_cache.clear took {fc_drop_ms:.1}ms entries={fc_drop_count}"
            ));
        }
        // backlog はフォルダ外の画像 ColorImage を保持しているため、閉じたら破棄する。
        // 保持していると次フォルダで同 idx に違う画像が割当たって表示が化ける。
        self.fs_upload_backlog.clear();
        // AI キャッシュもクリア
        for (cancel, _) in self.ai_upscale_pending.values() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.ai_upscale_pending.clear();
        self.ai_upscale_cache.clear();
        self.ai_classify_cache.clear();
        self.bump_all_input_generations();
        // フルスクリーン向けメタデータ読み込みもキャンセル (閉じた後のキャッシュ書き込みを防ぐ)
        if let Some(pending) = self.metadata_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        if crate::perf::is_enabled() {
            crate::perf::event(
                "nav",
                "close_fullscreen_end",
                None,
                cf_seq,
                &[
                    (
                        "ms",
                        serde_json::Value::from(cf_t0.elapsed().as_secs_f64() * 1000.0),
                    ),
                    ("was_open", serde_json::Value::from(cf_was_open)),
                    ("fs_cache", serde_json::Value::from(cf_fs_cache)),
                    ("ai_cache", serde_json::Value::from(cf_ai_cache)),
                ],
            );
        }
    }

    /// フルスクリーン終了後のグリッドカーソルを、最後に表示していた item に戻す。
    ///
    /// グリッドでダブルクリックした時点の `selected` と、フルスクリーン側で現在表示中の
    /// `fullscreen_idx` は別々に進むことがある。終了時に同期しておくと、動画を右クリックで
    /// 閉じた場合も画像と同じく「今見ていた場所」へスクロールして戻れる。
    fn restore_grid_cursor_to_fullscreen_item(&mut self) {
        let Some(idx) = self.fullscreen_idx else {
            return;
        };
        #[cfg(windows)]
        if self.viewer_session_is_detached() && self.detached_viewer_independent_still_session() {
            return;
        }
        if self.items.get(idx).is_none() {
            return;
        }
        self.selected = Some(idx);
        self.scroll_to_selected = true;
        self.update_last_selected_image();
        self.redirect_selected_to_visible();
    }

    // -------------------------------------------------------------------
    // AI アップスケール
    // -------------------------------------------------------------------

    /// AI アップスケール時の有効な背景モード (0=黒 / 1=白)。
    /// composite-first 方式では市松 (mode 2) は使えないので 0 に丸める。
    /// アップスケール無効時 (デノイズのみ or 完全 OFF) は出力が背景非依存になるので、
    /// キャッシュキーを単一 (0) に固定する。
    pub(crate) fn effective_upscale_bg_mode(&self) -> u8 {
        if !self.ai_upscale_enabled {
            0
        } else if self.fs_transparent_bg_mode == 1 {
            1
        } else {
            0
        }
    }

    /// fs_cache の Static 元画像が透過 (alpha<255) を含むか。
    pub(crate) fn fs_static_has_alpha(&self, idx: usize) -> bool {
        match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Static { pixels, .. }) => pixels.pixels.iter().any(|p| p.a() < 255),
            _ => false,
        }
    }

    /// 消しゴム用の AI 背景モード。
    ///
    /// 透過画像の消しゴムは黒固定の不透明ベースに統一しているため、Shift+B で白背景を
    /// 選んでいても composite-first AI cache は bg=0 を使う。これにより白背景が
    /// `erase_base_cache` / MI-GAN 入力へ混ざるのを防ぐ。
    pub(crate) fn erase_upscale_bg_mode(&self, idx: usize) -> u8 {
        if self.ai_upscale_enabled && self.fs_static_has_alpha(idx) {
            0
        } else {
            self.effective_upscale_bg_mode()
        }
    }

    /// 消しゴム入力用に必要なら黒で不透明化する。
    pub(crate) fn black_flatten_erase_source_if_needed(
        &self,
        idx: usize,
        pixels: Arc<egui::ColorImage>,
    ) -> Arc<egui::ColorImage> {
        if self.fs_static_has_alpha(idx) || pixels.pixels.iter().any(|p| p.a() < 255) {
            match Self::black_flatten_if_transparent(&pixels) {
                Some(flat) => Arc::new(flat),
                None => pixels,
            }
        } else {
            pixels
        }
    }

    /// 消しゴム用ソースへの補正適用。
    ///
    /// inpaint 入力は通常の表示パイプラインと同じく post-filter 込み、編集中の
    /// base 表示だけは精密に塗れるよう `include_post_filter=false` で呼ぶ。
    #[allow(dead_code)] // Legacy P2.4 removal path: edit source is raw in v1.1.0.
    pub(crate) fn apply_erase_adjustments_to_source(
        &self,
        idx: usize,
        pixels: Arc<egui::ColorImage>,
        include_post_filter: bool,
    ) -> Arc<egui::ColorImage> {
        let params = self.effective_params(idx).clone();
        let apply_colorize = include_post_filter && params.colorize.is_enabled();
        let apply_pf =
            include_post_filter && params.post_filter != crate::adjustment::PostFilter::None;
        if params.is_color_identity() && !apply_colorize && !apply_pf {
            return pixels;
        }
        let adjusted = crate::adjustment::apply_adjustments_fast(&pixels, &params);
        let colorized = if apply_colorize {
            crate::colorize::apply(&adjusted, &params.colorize)
        } else {
            adjusted
        };
        let post_filtered = if apply_pf {
            crate::post_filter::apply(&colorized, params.post_filter)
        } else {
            colorized
        };
        Arc::new(post_filtered)
    }

    /// 指定 idx の AI アップスケールキャッシュ・pending・failed を全 bg バリアント分まとめて削除する。
    /// pending はキャンセルトークンも立てる。
    pub(crate) fn purge_upscale_for_idx(&mut self, idx: usize) {
        for bg in [0u8, 1u8] {
            self.ai_upscale_cache.remove(&(idx, bg));
            self.ai_upscale_failed.remove(&(idx, bg));
            if let Some((cancel, _)) = self.ai_upscale_pending.remove(&(idx, bg)) {
                cancel.store(true, Ordering::Relaxed);
            }
        }
        self.clear_final_pipeline_caches_for_idx(idx);
    }

    /// AI 利用範囲が変わったとき、実行中/完了済み AI 出力を全体で無効化する。
    pub(crate) fn apply_ai_feature_mode_change(&mut self) {
        for (_, (cancel, _)) in self.ai_upscale_pending.drain() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.ai_upscale_cache.clear();
        self.ai_upscale_failed.clear();
        self.clear_retained_final_ai_cache("ai_feature_mode_change");
        self.bump_all_ai_generations();
        if let Some(idx) = self.fullscreen_idx {
            self.sync_upscale_from_preset(idx);
        } else {
            self.ai_upscale_enabled = false;
            self.ai_upscale_model_override = None;
            self.ai_denoise_model = None;
        }
    }

    /// AI 処理サイズ上限 (`ai_upscale_size_limit` / `ai_denoise_size_limit`) の変更を
    /// 反映する。キャッシュ key にサイズ上限は含まれないため、明示的に破棄しないと
    /// 旧判定での結果 (failed 含む) が残り続ける。final AI cache / failed / pending と
    /// 旧 AI cache の両系統を無効化する。
    pub(crate) fn apply_ai_size_limit_change(&mut self) {
        for (_, (cancel, _)) in self.ai_upscale_pending.drain() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.ai_upscale_cache.clear();
        self.ai_upscale_failed.clear();
        self.clear_retained_final_ai_cache("ai_size_limit_change");
        // bump_all_ai_generations が clear_all_final_pipeline_caches を内包する
        // (= final_ai_pending cancel + final_ai_cache / failed / composite 破棄)。
        self.bump_all_ai_generations();
    }

    /// AI バックエンド設定変更をホットリロードする (Phase 3、再起動不要)。
    ///
    /// 引数 `new_backend_str`: 新しい設定値 (`"directml"` / `"tensorrt"` / `"cpu"` / None)。
    ///
    /// 動作:
    /// - TensorRT に変わった: TrtWorkerPool を spawn して runtime に attach
    /// - TensorRT から DirectML に戻った: 既存の worker pool を detach (子プロセスは
    ///   Drop で shutdown される)
    /// - 同じ → 何もしない
    pub(crate) fn apply_ai_backend_change(&mut self, new_backend_str: Option<&str>) {
        let Some(runtime) = self.ai_runtime.as_ref() else {
            crate::logger::log("[AI] runtime 未初期化のためバックエンド変更はスキップ".to_string());
            return;
        };
        let want_trt = new_backend_str.and_then(crate::ai::AiBackend::from_str)
            == Some(crate::ai::AiBackend::TensorRt);
        let has_trt = runtime.has_worker_pool();

        // TRT 選択でも pack が未インストールなら spawn 試行しない
        // (= UI 側で「DirectML で動作」と既に表示済みだが、pack を後で
        // インストールしたときに settings.json の TensorRT が活きるよう設定値は維持)。
        if want_trt && !crate::ai::tensorrt_pack::is_pack_installed() {
            crate::logger::log(
                "[AI] AI バックエンド: TensorRT 選択中だが pack 未インストール、DirectML で動作"
                    .to_string(),
            );
            return;
        }

        match (want_trt, has_trt) {
            (true, false) => {
                crate::logger::log(
                    "[AI] AI バックエンド変更: → TensorRT (worker pool 起動)".to_string(),
                );
                Self::spawn_trt_worker_pool(runtime);
            }
            (false, true) => {
                crate::logger::log(
                    "[AI] AI バックエンド変更: → DirectML (worker pool 停止)".to_string(),
                );
                runtime.detach_worker_pool();
            }
            _ => {
                // 変更なし (TRT pack 未インストール等で TRT を選んでも spawn 失敗、
                // または同じ設定値) — ログのみ
                crate::logger::log(format!(
                    "[AI] AI バックエンド変更: state 変化なし (want_trt={want_trt}, has_trt={has_trt})"
                ));
            }
        }
    }

    /// AI ランタイムとモデルマネージャを遅延初期化する。
    ///
    /// Phase 3 アーキテクチャ:
    /// - メイン: 常に DirectML で AiRuntime を作る (`ai_backend` 設定値に依らない)
    /// - 起動時は TensorRT 設定でも worker pool を自動起動しない。CUDA/TensorRT
    ///   provider DLL はプロセス境界外とはいえ driver crash を誘発し得るため、実際に
    ///   AI 処理が必要になったタイミングで遅延起動する。
    pub(crate) fn ensure_ai_runtime(&mut self) {
        if self.ai_runtime.is_none() {
            // 常に DirectML で起動 (Phase 3)
            match crate::ai::runtime::AiRuntime::new_with_backend(crate::ai::AiBackend::DirectMl) {
                Ok(rt) => {
                    let active = rt.active_backend();
                    crate::logger::log(format!(
                        "[AI] Runtime initialized (DirectML always in main, requested={:?}, effective={:?})",
                        active.requested, active.effective
                    ));
                    let runtime_arc = std::sync::Arc::new(rt);

                    self.ai_runtime = Some(runtime_arc);
                }
                Err(e) => {
                    crate::logger::log(format!("[AI] Runtime init failed: {e}"));
                }
            }
        }
    }

    /// 単一 AI ワーカー + 優先度キューを遅延起動する (初回 final AI ジョブ時)。
    /// ワーカースレッドは 1 本だけ生成し、結果は `final_ai_rx` で受ける。
    fn ensure_ai_job_queue(&mut self) {
        if self.ai_job_queue.is_none() {
            let (queue, rx) = AiJobQueue::new();
            self.ai_job_queue = Some(queue);
            self.final_ai_rx = Some(rx);
        }
    }

    fn maybe_start_trt_worker_pool_for_ai_use(
        &self,
        runtime: &std::sync::Arc<crate::ai::runtime::AiRuntime>,
    ) {
        let want_trt = self
            .settings
            .ai_backend
            .as_deref()
            .and_then(crate::ai::AiBackend::from_str)
            == Some(crate::ai::AiBackend::TensorRt);
        if !want_trt || runtime.has_worker_pool() {
            return;
        }
        if !crate::ai::tensorrt_pack::is_pack_installed() {
            crate::logger::log(
                "[AI] TensorRT 選択中だが pack 未インストール、DirectML で動作".to_string(),
            );
            return;
        }
        crate::logger::log("[AI] TensorRT worker pool を初回 AI 処理で遅延起動します".to_string());
        Self::spawn_trt_worker_pool_guarded(runtime, self.trt_restart_in_flight.clone());
    }

    /// TRT ワーカープールをバックグラウンドで起動して runtime に attach する。
    ///
    /// 起動には ORT init + DLL preload + ハンドシェイクで数秒かかるので、
    /// メインスレッドで同期実行すると UI が固まる。`std::thread::spawn` で
    /// 別スレッドに逃がし、起動完了したら attach する。
    ///
    /// 起動失敗時は AiRuntime は DirectML のままで動作続行し、ログにエラーを残す。
    ///
    /// **多重 spawn ガード**: `App.trt_restart_in_flight` を CAS で立てる。
    /// 既に立っていたら早期 return (= 別の spawn が進行中)。worker 死亡時に
    /// 並行する複数の AI 推論が同じ DiedDuringInfer を観測しても 1 回しか
    /// 新 pool を起こさない (Codex P2 指摘)。
    pub(crate) fn spawn_trt_worker_pool(runtime: &std::sync::Arc<crate::ai::runtime::AiRuntime>) {
        Self::spawn_trt_worker_pool_inner(
            runtime,
            /* guard = */ None,
            std::time::Duration::ZERO,
        );
    }

    /// `spawn_trt_worker_pool` の guard 付き版。worker 死亡時の自動再起動から
    /// 呼ぶ際に使う (= 複数の死亡通知が並行して走る場合の多重 spawn を防ぐ)。
    pub(crate) fn spawn_trt_worker_pool_guarded(
        runtime: &std::sync::Arc<crate::ai::runtime::AiRuntime>,
        guard: std::sync::Arc<std::sync::atomic::AtomicBool>,
    ) {
        Self::spawn_trt_worker_pool_inner(runtime, Some(guard), std::time::Duration::ZERO);
    }

    /// `spawn_trt_worker_pool_guarded` の遅延版。起動 timeout 直後の transient retry で
    /// CUDA / TensorRT provider 初期化状態を少し落ち着かせるために使う。
    pub(crate) fn spawn_trt_worker_pool_guarded_after(
        runtime: &std::sync::Arc<crate::ai::runtime::AiRuntime>,
        guard: std::sync::Arc<std::sync::atomic::AtomicBool>,
        delay: std::time::Duration,
    ) {
        Self::spawn_trt_worker_pool_inner(runtime, Some(guard), delay);
    }

    fn spawn_trt_worker_pool_inner(
        runtime: &std::sync::Arc<crate::ai::runtime::AiRuntime>,
        guard: Option<std::sync::Arc<std::sync::atomic::AtomicBool>>,
        delay: std::time::Duration,
    ) {
        // CAS: false → true。すでに in-flight なら true のままで、ここは false 戻り → skip。
        if let Some(g) = guard.as_ref() {
            if g.compare_exchange(
                false,
                true,
                std::sync::atomic::Ordering::SeqCst,
                std::sync::atomic::Ordering::SeqCst,
            )
            .is_err()
            {
                crate::logger::log(
                    "[AI] TRT worker pool 起動はすでに進行中、新規 spawn を skip".to_string(),
                );
                return;
            }
        }
        let runtime_for_thread = runtime.clone();
        let guard_for_thread = guard.clone();
        if let Err(e) = std::thread::Builder::new()
            .name("trt-worker-spawn".to_string())
            .spawn(move || {
                if !delay.is_zero() {
                    crate::logger::log(format!(
                        "[AI] TRT worker pool 再起動を {} ms 待ってから試行します",
                        delay.as_millis()
                    ));
                    std::thread::sleep(delay);
                }
                crate::logger::log(
                    "[AI] TRT worker pool バックグラウンド起動を試行中...".to_string(),
                );
                match crate::ai::trt_worker_pool::TrtWorkerPool::start() {
                    Ok(pool) => {
                        runtime_for_thread.attach_worker_pool(std::sync::Arc::new(pool));
                        crate::logger::log(
                            "[AI] TRT worker pool 起動成功、attach 完了".to_string(),
                        );
                        // spawn 試行が完了 → guard を解放。
                        if let Some(g) = guard_for_thread.as_ref() {
                            g.store(false, std::sync::atomic::Ordering::SeqCst);
                        }
                    }
                    Err(e) => {
                        // 起動失敗 (TRT pack 不在 / engine 不整合 / DLL ロード失敗 等)。
                        // DirectML で動作続行するが、UI に通知して気付かせる
                        // (Phase 3 Step 5)。ログだけだとユーザーが「なぜ TRT に
                        // ならないか」を追えない。
                        //
                        // 通知を見た UI が同じ frame で retry を起動できるよう、
                        // report 前に guard を下ろしておく。
                        if let Some(g) = guard_for_thread.as_ref() {
                            g.store(false, std::sync::atomic::Ordering::SeqCst);
                        }
                        runtime_for_thread.report_worker_spawn_failed(e);
                    }
                }
            })
        {
            crate::logger::log(format!("[AI] TRT worker pool 起動 thread 作成に失敗: {e}"));
            if let Some(g) = guard {
                g.store(false, std::sync::atomic::Ordering::SeqCst);
            }
        }
    }

    /// AI アップスケールの完了をポーリングし、テクスチャに変換してキャッシュする。
    pub(crate) fn poll_ai_upscale(&mut self, ctx: &egui::Context) {
        if !self.ai_upscale_enabled && self.ai_denoise_model.is_none() {
            return;
        }

        let mut completed: Vec<((usize, u8), crate::ai::upscale::UpscaleResult)> = Vec::new();
        let mut disconnected: Vec<(usize, u8)> = Vec::new();

        for (&key, (_, rx)) in &self.ai_upscale_pending {
            match rx.try_recv() {
                Ok(result) => completed.push((key, result)),
                Err(mpsc::TryRecvError::Disconnected) => disconnected.push(key),
                Err(mpsc::TryRecvError::Empty) => {}
            }
        }

        for key in disconnected {
            // cancel フラグが立っているなら「ユーザー操作によるキャンセル」であり、
            // 真の失敗ではない。failed に登録すると次回以降の upscale が永久に
            // 起動しなくなる (start_ai_upscale_pending が failed を見て早期 return)。
            //
            // 連続モデル切替で worker mutex キューが詰まっているとき、新しい
            // 要求が前の要求を cancel → 前の thread がキューから取り出されて
            // 1 タイル走った後に cancel 検知 → 結果送らず disconnect、というパターンで
            // ここに来ると idx が誤って永久 failed になる (Apr 28 のユーザー報告)。
            let was_cancelled = self
                .ai_upscale_pending
                .get(&key)
                .map(|(cancel, _)| cancel.load(Ordering::Relaxed))
                .unwrap_or(false);
            self.ai_upscale_pending.remove(&key);
            if !was_cancelled {
                // 真の失敗 (panic / ORT エラー等) のみ failed に登録してリトライ防止
                self.ai_upscale_failed.insert(key);
            }
        }

        let repaint = !completed.is_empty();
        for (key, result) in completed {
            let (idx, bg) = key;
            self.ai_upscale_pending.remove(&key);
            let pixels = std::sync::Arc::new(result.image);
            let upload = clamp_for_gpu(&pixels);
            let [w, h] = pixels.size;
            let upload_t0 = std::time::Instant::now();
            let handle = ctx.load_texture(
                format!("ai_fs_{idx}_{bg}"),
                upload.into_owned(),
                DISPLAY_IMAGE_TEXTURE_OPTIONS,
            );
            let upload_ms = upload_t0.elapsed().as_secs_f64() * 1000.0;
            if crate::perf::is_enabled() {
                let perf_key = self.perf_item_key(idx);
                crate::perf::event(
                    "ai",
                    "job_ready",
                    perf_key.as_deref(),
                    self.input_seq,
                    &[
                        ("idx", serde_json::Value::from(idx)),
                        ("bg", serde_json::Value::from(bg)),
                        ("w", serde_json::Value::from(w)),
                        ("h", serde_json::Value::from(h)),
                        ("upload_ms", serde_json::Value::from(upload_ms)),
                    ],
                );
            }
            self.adjustment_cache.remove(&idx);
            self.invalidate_compare_prepared_for_idx(idx);
            self.bump_adjustment_generation(idx);
            // 派生キャッシュ。fs.paint は fs_cache 側から load_seq を拾うためここでは 0。
            // source_dims はダウンスケール警告用で、派生エントリは元画像の fs_cache 側を
            // 参照すればよいのでここでは None を入れておく。
            self.ai_upscale_cache.insert(
                key,
                FsCacheEntry::Static {
                    tex: handle,
                    pixels,
                    source_dims: None,
                    load_seq: 0,
                },
            );
            // 360 度パノラマビュー: AI 完了で cache 内容が変わったので世代 bump (§3.6.2.2)。
            self.bump_ai_generation(idx);
            crate::logger::log(format!("[AI] Upscale complete for idx={idx} bg={bg}"));
        }

        if repaint {
            ctx.request_repaint();
        }
    }

    /// 現在のフルスクリーン画像に対して AI 処理（デノイズ / アップスケール）を開始する。
    /// - 先読みが全完了している場合のみ開始
    /// - すでに処理済み or pending の場合はスキップ
    /// - アップスケール時: 2K 以上の画像はスキップ
    #[allow(dead_code)] // Legacy AI cache is kept until P2.4 staged deletion.
    pub(crate) fn maybe_start_ai_upscale(&mut self, current_idx: usize) {
        let denoise_enabled = self.ai_denoise_model.is_some();
        let upscale_enabled = self.ai_upscale_enabled;

        if !denoise_enabled && !upscale_enabled {
            return;
        }

        // composite-first 方式: 現在の bg と一致するエントリのみが対象。
        // 他 bg バリアントは別キャッシュに残るので独立にスケジュールする。
        let bg = self.effective_upscale_bg_mode();
        let cur_key = (current_idx, bg);

        // すでに処理済み、処理中、または失敗済み
        if self.ai_upscale_cache.contains_key(&cur_key)
            || self.ai_upscale_pending.contains_key(&cur_key)
            || self.ai_upscale_failed.contains(&cur_key)
        {
            return;
        }

        // 表示中画像が **実際に AI 処理されるか** を、先読みキャンセルより前に確定させる。
        // ここで源泉 (fs_cache の Static) を取得し、サイズ上限 (`should_process_rect`) で
        // 範囲外なら即 return する。源泉あり + サイズ範囲内のときだけ、下の
        // 「先読みを優先キャンセル」ブロックに進む。
        //
        // ⚠ 再発防止 (2026-05、v0.9.x からの既存バグ): この範囲チェックを
        // キャンセルブロックより **後** に置くと、skip_px 超で処理対象外の大きい画像を
        // 表示している間、現在画像は spawn されないのに先読みだけが毎フレーム
        // キャンセルされる。prefetch が翌フレーム再投入 → タイル 1 枚処理後に即
        // キャンセル、を ~25 回/秒で無限ループし GPU を焼き続ける
        // (cancel された job は `poll_ai_upscale` で failed 扱いされず再試行されるため)。
        // 処理対象外なら先読みを温存して抜けることでループを断つ。
        let source_image = match self.fs_cache.get(&current_idx) {
            Some(FsCacheEntry::Static { pixels, .. }) => pixels.clone(),
            _ => return,
        };

        let (w, h) = (source_image.size[0] as u32, source_image.size[1] as u32);
        let upscale_in_range =
            crate::ai::upscale::should_process_rect(w, h, self.settings.ai_upscale_limit());
        let denoise_in_range =
            crate::ai::upscale::should_process_rect(w, h, self.settings.ai_denoise_limit());
        // 両方の範囲外ならスキップ (先読みをキャンセルする前に抜ける)
        if (!upscale_enabled || !upscale_in_range) && (!denoise_enabled || !denoise_in_range) {
            return;
        }

        // ここに到達 = 表示中画像は実際に AI 処理される。
        // 同時実行は 1 枚まで（GPU メモリと帯域の制約）。ただし現在表示中の
        // 画像を処理するケースでは、ユーザーが既に先に進んでいるので古い
        // 先読み（別 idx or 別 bg）を優先キャンセルして枠を空ける。
        if !self.ai_upscale_pending.is_empty() {
            if self.fullscreen_idx == Some(current_idx) {
                let to_cancel: Vec<(usize, u8)> = self
                    .ai_upscale_pending
                    .keys()
                    .filter(|&&k| k != cur_key)
                    .copied()
                    .collect();
                for k in to_cancel {
                    // **cancel フラグだけ立てて pending entry は残す**。worker は次の
                    // tile boundary で cancel を見て Err(Cancelled) を返す (= channel
                    // disconnect → poll_ai_upscale で silent remove)。
                    // ただし最後の tile が完了直前ならそのまま Ok で返ることもあり、
                    // その場合 tx.send で結果が rx に届く → cache に保存される。
                    // (Apr 29: 高速スクロール時に最後の tile 完了直後で entry を remove
                    // していたため Ok 結果が捨てられて、戻り再訪時にアップスケールが
                    // 効かない問題があった)。
                    if let Some((cancel, _)) = self.ai_upscale_pending.get(&k) {
                        if !cancel.load(Ordering::Relaxed) {
                            cancel.store(true, Ordering::Relaxed);
                            crate::logger::log(format!(
                                "[AI] Cancelled prefetch {:?} to prioritize current {:?}",
                                k, cur_key
                            ));
                        }
                    }
                }
            }
            // 「pending に何か残っている → 新規 spawn しない」のガード。
            // ただしキャンセル済み entry は既に終わりに向かっているので新規 spawn の
            // 妨げにしない (= 1〜数 ms のオーバーラップを許可)。これにより上の
            // 「Cancelled prefetch」で entry を残したままでも新しい current_idx の
            // upscale を即時開始できる。
            let has_active_pending = self
                .ai_upscale_pending
                .values()
                .any(|(cancel, _)| !cancel.load(Ordering::Relaxed));
            if has_active_pending {
                return;
            }
        }

        // AI ランタイム / モデルマネージャを遅延初期化
        self.ensure_ai_runtime();

        let Some(runtime) = self.ai_runtime.clone() else {
            return;
        };
        self.maybe_start_trt_worker_pool_for_ai_use(&runtime);
        let manager = self.ai_model_manager.clone();

        // デノイズモデル選択・ロード
        let denoise_model = if denoise_enabled && denoise_in_range {
            let kind = match self.ai_denoise_model {
                Some(k) => k,
                None => return, // デノイズ有効だがモデル未設定
            };
            let Some(model_path) = manager.model_path(kind) else {
                // モデル未ダウンロード → スキップ（起動時ダイアログでダウンロード）
                return;
            };
            if !runtime.is_loaded(kind) {
                if let Err(e) = runtime.load_model(kind, &model_path) {
                    crate::logger::log(format!("[AI] Denoise model load failed: {e}"));
                    return;
                }
            }
            Some(kind)
        } else {
            None
        };

        // アップスケールモデル選択・ロード
        let upscale_model = if upscale_enabled && upscale_in_range {
            let kind = match self.ai_upscale_model_override {
                Some(k) => k,
                None => {
                    let category = self
                        .ai_classify_cache
                        .get(&current_idx)
                        .copied()
                        .unwrap_or_else(|| {
                            let dynimg = color_image_to_dynamic(&source_image);
                            let cat = crate::ai::classify::classify_heuristic(&dynimg);
                            self.ai_classify_cache.insert(current_idx, cat);
                            cat
                        });
                    let Some(kind) = self.settings.ai_feature_mode.auto_upscale_model(category)
                    else {
                        return;
                    };
                    kind
                }
            };
            match manager.model_path(kind) {
                Some(model_path) => {
                    if !runtime.is_loaded(kind) {
                        if let Err(e) = runtime.load_model(kind, &model_path) {
                            crate::logger::log(format!("[AI] Upscale model load failed: {e}"));
                            if denoise_model.is_none() {
                                return;
                            }
                            None
                        } else {
                            Some(kind)
                        }
                    } else {
                        Some(kind)
                    }
                }
                None => {
                    crate::logger::log(format!(
                        "[AI] Upscale model {:?} not available, skipping for idx={current_idx}",
                        kind
                    ));
                    if denoise_model.is_none() {
                        return;
                    }
                    None
                }
            }
        } else {
            None
        };

        if denoise_model.is_none() && upscale_model.is_none() {
            return;
        }

        // バックグラウンドスレッドで AI 処理実行
        let cancel = Arc::new(AtomicBool::new(false));
        let (tx, rx) = mpsc::channel();
        let cancel_clone = cancel.clone();
        let idx = current_idx;
        // composite-first 用の背景色 (bg=1 のみ白、それ以外は黒)
        let bg_rgb: [u8; 3] = if bg == 1 { [255, 255, 255] } else { [0, 0, 0] };
        // composite-first はアップスケールパスのみ必要 (1x のデノイズは Lanczos 拡大の
        // ズレが生じないため、アルファ保持パスでそのまま処理できる)。
        let composite_first = upscale_model.is_some();

        std::thread::spawn(move || {
            // composite-first: アップスケールあり時のみ bg 単色に合成してから AI に渡す。
            // これにより AI モデルがアルファ境界の RGB ガベージに引きずられず、
            // 輪郭がきれいにアップスケールされる。背景色は出力に焼き付くため、
            // bg 切替時は別キャッシュエントリとして再生成する。
            // デノイズのみの場合はアルファ保持パスを通って透明度がそのまま残る。
            let mut dynimg = if composite_first {
                color_image_to_dynamic_composited(&source_image, bg_rgb)
            } else {
                color_image_to_dynamic(&source_image)
            };

            // Step 1: デノイズ (1x)
            if let Some(denoise_kind) = denoise_model {
                match crate::ai::denoise::denoise(&runtime, denoise_kind, &dynimg, &cancel_clone) {
                    Ok(denoised) => {
                        if upscale_model.is_some() {
                            // アップスケールが後続する場合のみ DynamicImage に変換
                            // (denoised は補正済み RGB なのでアルファ合成は不要)
                            dynimg = color_image_to_dynamic(&denoised);
                        } else {
                            // デノイズのみ: 結果をそのまま送信（変換を省略）
                            let _ = tx.send(crate::ai::upscale::UpscaleResult {
                                idx,
                                image: denoised,
                            });
                            return;
                        }
                    }
                    Err(e) => {
                        crate::logger::log(format!("[AI] Denoise failed for idx={idx}: {e}"));
                        if upscale_model.is_none() {
                            return;
                        }
                    }
                }
            }

            // Step 2: アップスケール (4x)
            if let Some(upscale_kind) = upscale_model {
                match crate::ai::upscale::upscale(&runtime, upscale_kind, &dynimg, &cancel_clone) {
                    Ok(upscaled) => {
                        let _ = tx.send(crate::ai::upscale::UpscaleResult {
                            idx,
                            image: upscaled,
                        });
                    }
                    Err(e) => {
                        crate::logger::log(format!("[AI] Upscale failed for idx={idx}: {e}"));
                    }
                }
            }
        });

        self.ai_upscale_pending.insert(cur_key, (cancel, rx));
        crate::logger::log(format!(
            "[AI] AI processing started for idx={current_idx} bg={bg} denoise={:?} upscale={:?}",
            denoise_model, upscale_model
        ));
        if crate::perf::is_enabled() {
            let perf_key = self.perf_item_key(current_idx);
            crate::perf::event(
                "ai",
                "job_start",
                perf_key.as_deref(),
                self.input_seq,
                &[
                    ("idx", serde_json::Value::from(current_idx)),
                    ("bg", serde_json::Value::from(bg)),
                    (
                        "denoise",
                        serde_json::Value::from(format!("{:?}", denoise_model)),
                    ),
                    (
                        "upscale",
                        serde_json::Value::from(format!("{:?}", upscale_model)),
                    ),
                ],
            );
        }
    }

    /// 先読み範囲内の item_idx 集合を計算する。
    fn compute_keep_set(&self, current_idx: usize) -> std::collections::HashSet<usize> {
        let image_indices = self.collect_image_indices();
        let Some(pos) = image_indices.iter().position(|&i| i == current_idx) else {
            // フルスクリーン表示中に★/Ctrl+Fフィルタが変わり、現在ページが
            // visible_indices から外れても、表示中ページの派生キャッシュは守る。
            let mut keep = std::collections::HashSet::new();
            keep.insert(current_idx);
            return keep;
        };
        let n = image_indices.len();
        let keep_back = self.settings.prefetch_back + 1;
        let keep_forward = self.settings.prefetch_forward + 1;
        (pos.saturating_sub(keep_back)..=((pos + keep_forward).min(n - 1)))
            .map(|p| image_indices[p])
            .collect()
    }

    /// AI アップスケールキャッシュの eviction（先読み範囲外を破棄）。
    #[allow(dead_code)] // Legacy AI cache is kept until P2.4 staged deletion.
    fn evict_ai_upscale_cache(&mut self, current_idx: usize) {
        let keep_set = self.compute_keep_set(current_idx);
        // 全 bg バリアントとも、idx が範囲外なら破棄
        self.ai_upscale_cache.retain(|k, _| keep_set.contains(&k.0));

        // 範囲外の pending をキャンセル
        let to_cancel: Vec<(usize, u8)> = self
            .ai_upscale_pending
            .keys()
            .filter(|k| !keep_set.contains(&k.0))
            .cloned()
            .collect();
        for k in to_cancel {
            // **cancel フラグだけ立てて pending entry は残す** (= worker が完了寸前
            // なら Ok の結果が rx 経由で届いて cache に保存される)。entry 自体は
            // poll_ai_upscale が channel disconnect を見たときに削除する。
            if let Some((cancel, _)) = self.ai_upscale_pending.get(&k) {
                cancel.store(true, Ordering::Relaxed);
            }
        }
    }

    /// AI 先読み対象の item_idx を前方優先（+1..+pf_forward, -1..-pf_back）で返す。
    pub(crate) fn ai_prefetch_targets(&self, current_idx: usize) -> Vec<usize> {
        let image_indices = self.collect_image_indices();
        let Some(pos) = image_indices.iter().position(|&i| i == current_idx) else {
            return Vec::new();
        };
        let n = image_indices.len();
        let pf_back = self.settings.ai_upscale_prefetch_back;
        let pf_forward = self.settings.ai_upscale_prefetch_forward;
        interleaved_prefetch_targets(&image_indices, pos, n, pf_forward, pf_back)
    }

    /// AI アップスケールの先読み（表示中画像の前後）。
    #[allow(dead_code)] // Legacy AI cache is kept until P2.4 staged deletion.
    fn prefetch_ai_upscale(&mut self, current_idx: usize) {
        if !self.ai_upscale_enabled && self.ai_denoise_model.is_none() {
            return;
        }
        for idx in self.ai_prefetch_targets(current_idx) {
            self.maybe_start_ai_upscale(idx);
        }
    }

    /// 進行中の (= cancel フラグが立っていない) final_ai pending が 1 件でも
    /// あるかを返す。先読みの起動可否判定 (= 現在ページの AI が完了するまで
    /// 待つ) に使う。
    pub(crate) fn has_uncancelled_final_ai_pending(&self) -> bool {
        self.final_ai_pending
            .values()
            .any(|p| !p.cancel.load(Ordering::Relaxed))
    }

    /// 指定 idx の AI 処理が「完了」または「skip 確定」(= AI 不要 / failed) の
    /// いずれかかを判定する。先読み進捗バー (`draw_fs_ai_status`) の done/total
    /// 計算に使う pub(crate) helper。
    ///
    /// 戻り値:
    /// - `true`: 結果が cache にある / 失敗確定 / AI モデル未設定 / skip_px 超過
    /// - `false`: まだ処理待ち、もしくは source pixels すら準備できていない
    ///
    /// `final_ai_key_for_pixels` と同じ判定式を共有するため、skip_px や bg mode の
    /// 整合性は自動で保たれる。
    pub(crate) fn is_idx_final_ai_done_or_skipped(&self, idx: usize) -> bool {
        // source pixels が無ければ判定不能 → pending 扱い (= done 数に入れない)
        let Some(pixels) = self.current_raw_source_pixels(idx) else {
            return false;
        };
        let params = self.effective_params(idx);
        let edit_key = self.current_edit_result_key(idx);
        let Some(key) = self.final_ai_key_for_pixels(edit_key, pixels.size, params) else {
            // AI 不要 (= モデル未設定 or skip_px 超) → done
            return true;
        };
        self.final_ai_cache.contains_key(&key)
            || self.has_retained_final_ai(idx, key, pixels.size)
            || self.final_ai_failed.contains(&key)
    }

    /// 先読み進捗バー用の (done, total) を返す。総 target が 0 ならバー非表示
    /// (= None)。現在ページの AI 処理が走っている間 (= `current_busy`) は先読み
    /// バーを隠して「AI 処理中」ラベルだけ見せる。
    pub(crate) fn final_ai_prefetch_progress(&self, fs_idx: usize) -> Option<(usize, usize)> {
        let targets = self.ai_prefetch_targets(fs_idx);
        let total = targets.len();
        if total == 0 {
            return None;
        }
        let done = targets
            .iter()
            .filter(|&&i| self.is_idx_final_ai_done_or_skipped(i))
            .count();
        let current_busy = self
            .final_ai_pending
            .keys()
            .any(|key| key.edit_key.idx == fs_idx);
        if done < total && !current_busy {
            Some((done, total))
        } else {
            None
        }
    }

    fn record_final_effect_prefetch_admission(
        &mut self,
        idx: usize,
        admission: FinalEffectPrefetchAdmission,
        loaded_texels: usize,
        low_watermark: usize,
    ) {
        if !crate::perf::is_enabled() {
            return;
        }
        let now = std::time::Instant::now();
        if !self
            .final_effect_prefetch_block_log
            .observe(idx, admission, now)
        {
            return;
        }
        let Some(reason) = admission.blocked_reason() else {
            return;
        };
        crate::perf::event(
            "fs",
            "final_effect_prefetch_blocked",
            None,
            self.input_seq,
            &[
                ("idx", (idx as u64).into()),
                ("reason", reason.into()),
                ("loaded_texels", (loaded_texels as u64).into()),
                ("low_watermark", (low_watermark as u64).into()),
            ],
        );
    }

    /// カラー化を含む final composite の先読み。AI と同じ前後枚数を使い、
    /// 非表示ページは CPU pixels だけを worker へ渡す。完了時の GPU upload は
    /// `poll_final_effects` の 1 結果として行い、ページ移動時は完成 texture が即 hit する。
    pub(crate) fn prefetch_final_effects(
        &mut self,
        ctx: &egui::Context,
        current_idx: usize,
        continuous_prepare_set: Option<&std::collections::HashSet<usize>>,
    ) {
        if self.post_filter_bypassed
            || self
                .final_effect_pending
                .values()
                .any(|pending| !pending.cancel.load(Ordering::Relaxed))
        {
            return;
        }
        let reading_is_paged = self.reading_flow.is_paged();
        let continuous_loaded_texels = if reading_is_paged {
            0
        } else {
            self.continuous_reading_loaded_texels()
        };
        let continuous_low_watermark = if reading_is_paged {
            None
        } else {
            self.vram_pool_budget().fullscreen_watermarks().low_texels
        };
        for idx in self.ai_prefetch_targets(current_idx) {
            let in_prepare_band = continuous_prepare_set.is_some_and(|set| set.contains(&idx));
            let admission = should_prefetch_final_effect(
                reading_is_paged,
                &self.fs_vertical_cache_keep_set,
                idx,
                in_prepare_band,
                continuous_loaded_texels,
                continuous_low_watermark,
            );
            self.record_final_effect_prefetch_admission(
                idx,
                admission,
                continuous_loaded_texels,
                continuous_low_watermark.unwrap_or(0),
            );
            if admission != FinalEffectPrefetchAdmission::Allow {
                continue;
            }
            let params = self.effective_params(idx).clone();
            let creative_lut = (!params.creative_lut.is_identity())
                .then(|| {
                    self.creative_lut_library
                        .get(params.creative_lut.id)
                        .map(|lut| (lut, params.creative_lut.strength))
                })
                .flatten();
            if !params.colorize.is_enabled() && creative_lut.is_none() {
                continue;
            }
            let Some((edit_key, edit_pixels)) = self.ensure_edit_result_pixels_cpu(ctx, idx) else {
                continue;
            };
            let final_key =
                self.final_composite_key_for_pixels(edit_key, edit_pixels.size, &params);
            if self
                .final_composite_cache
                .get(&final_key)
                .is_some_and(|entry| entry.complete)
                || self.final_effect_pending.contains_key(&final_key)
            {
                continue;
            }

            let ai_key = self.final_ai_key_for_pixels(edit_key, edit_pixels.size, &params);
            let (source, used_upscale, adjust_before_effect) = match ai_key {
                Some(key) => {
                    if let Some(entry) = self.final_ai_cache.get(&key).cloned() {
                        (entry.pixels, entry.used_upscale, None)
                    } else if self.final_ai_failed.contains(&key) {
                        let adjust = (!params.is_color_identity()).then_some(params.clone());
                        (Arc::clone(&edit_pixels), false, adjust)
                    } else {
                        // AI 結果が到着してから final effect を作る。AI 前の完成 entry を
                        // 同じ key へ入れると Ready 到着後も stale な白黒結果が残る。
                        continue;
                    }
                }
                None => {
                    let adjust = (!params.is_color_identity()).then_some(params.clone());
                    (Arc::clone(&edit_pixels), false, adjust)
                }
            };
            let job = FinalEffectJob {
                source,
                adjust_before_effect,
                smart_sharpen: params.effective_smart_sharpen(used_upscale),
                colorize: params.colorize.clone(),
                colorize_applicable_override: None,
                creative_lut,
                post_filter: params.post_filter,
            };
            if self.spawn_final_effect_job(ctx, final_key, job, true, true) {
                // 背景 CPU / GPU と完成時 upload を一度に積み上げない。
                return;
            }
        }
    }

    /// 新パイプライン (v1.1.0+) の AI 先読み。表示中画像の前後について
    /// `final_ai_cache` を埋め、ページ送り時に AI 結果が即 hit する状態にする。
    ///
    /// ## 設計判断
    /// - 旧 `prefetch_ai_upscale` は Pipeline P1 リファクタ後 dead code 化していた
    ///   (= 呼び出し元が同時に削除され、新パイプライン版が未実装)。
    /// - 同時起動は 1 ジョブのみ (= 旧設計の `current_done &&
    ///   ai_upscale_pending.is_empty()` 条件を踏襲)。これで一括 spawn による
    ///   ai_runtime の競合 / VRAM 不足を防ぐ。
    /// - 各 idx ごとに `ensure_edit_result_pixels_cpu` を呼ぶため、隣接ページの source
    ///   pixels が `fs_cache` に乗っていなければそのターゲットは skip される
    ///   (= fs_prefetch の完了を毎フレ retry で待つ、コスト軽い)。これで **edit_result の
    ///   表示テクスチャ** の前倒し upload は避ける (F2、表示時に lazy upload)。
    ///   ただし編集済みページ (隠蔽 / 局所補正 / 消しゴム) は `assemble_edit_result_pixels`
    ///   内で各 layer の texture を UI スレッドで upload しうる (R2-5 既知残、別途・中規模)。
    /// - `maybe_start_final_ai` 内の "active pending check" は cancel 済を除外
    ///   しないため、ここで `has_uncancelled_final_ai_pending` を別途 gate する。
    pub(crate) fn prefetch_final_ai(&mut self, ctx: &egui::Context, current_idx: usize) {
        // 背景 final-effect は現在ページの ensure 経路に依存せず、fullscreen work
        // セクション自体で回収する。ensure 側の poll はコピー / 書き出し等の入口用に残す。
        self.poll_final_effects(ctx);
        // ページ送りのカラー化先読みは従来どおりここで回す。連結読みは描画レイアウトが
        // 算出した準備帯を渡す必要があるため `draw_fs_continuous_reading` から起動する。
        if self.reading_flow.is_paged() {
            self.prefetch_final_effects(ctx, current_idx, None);
        }
        // 現在ページの AI が走っている間 (= cancel されていない pending あり) は
        // 先読みしない。旧設計 `current_done && empty` 条件と同等。
        if self.has_uncancelled_final_ai_pending() {
            return;
        }
        let targets = self.ai_prefetch_targets(current_idx);
        for idx in targets {
            // 直前で has_uncancelled_final_ai_pending が false でも、ループ内で
            // maybe_start_final_ai が pending を 1 件増やすので、次以降の idx は
            // 自然に gate される (= 旧設計と同じ「同時 1 ジョブ」ポリシー)。
            if self.has_uncancelled_final_ai_pending() {
                return;
            }
            // Raster PDF の現行 display-fit 結果が AI 用 native 入力と異なるページは、
            // 現行結果に AI 先読みを流しても native 再レンダで捨てられる。
            // 代わりに native 再レンダを **通常レーンで先に起動** (visible を妨げない) し、
            // AI 先読みは native 着地まで保留する。これで画像の先読みと同様、移動時に
            // native + final AI が揃って即表示できる。
            if self.pdf_prefetch_should_defer_ai(idx) {
                if let Some((key, entry, _)) =
                    self.lookup_retained_pdf_final_ai(idx, "prefetch_final_ai")
                {
                    self.final_ai_cache.insert(key, entry);
                    continue;
                }
                // 既に再レンダ中なら二重起動しない (cancel→respawn ループ防止)。
                if !self.fs_pending.contains_key(&idx) && !self.fs_upload_backlog_contains(idx) {
                    self.request_pdf_rerender(idx, 1.0, false);
                }
                continue;
            }
            // 先読みは edit_result の表示テクスチャを前倒し upload しない (F2)。AI 入力は CPU
            // ピクセルで足りる。表示に入った時に ensure_edit_result_pixels が lazy アップロード
            // する。(注: 編集済みページの conceal/局所補正/消しゴム layer texture は
            // assemble_edit_result_pixels 内で upload されうる = R2-5 既知残。)
            let Some((edit_key, edit_pixels)) = self.ensure_edit_result_pixels_cpu(ctx, idx) else {
                continue;
            };
            let params = self.effective_params(idx).clone();
            let Some(key) = self.final_ai_key_for_pixels(edit_key, edit_pixels.size, &params)
            else {
                continue;
            };
            if !self.final_ai_cache.contains_key(&key)
                && let Some(entry) = self.lookup_retained_final_ai(idx, key, edit_pixels.size)
            {
                self.final_ai_cache.insert(key, entry);
                continue;
            }
            if self.final_ai_cache.contains_key(&key)
                || self.final_ai_pending.contains_key(&key)
                || self.final_ai_failed.contains(&key)
            {
                continue;
            }
            // prefetch 経路は戻り値不要 (composite を作らないので complete 判定がない)。
            let _ = self.maybe_start_final_ai(idx, key, edit_pixels, params, false);
        }
    }

    // ── 画像補正 ──────────────────────────────────────────────────

    /// ページの正規化キーを返す（DB 保存用）。
    pub(crate) fn page_path_key(&self, idx: usize) -> Option<String> {
        let item = self.items.get(idx)?;
        let key = match item {
            GridItem::Image(p) => crate::adjustment_db::normalize_path(p),
            GridItem::ZipImage {
                zip_path,
                entry_name,
            } => {
                // Keep released cache-ZIP page keys intact. Direct/cache parity would require an
                // explicit user-data migration and is deliberately deferred.
                crate::adjustment_db::zip_entry_key(zip_path, entry_name)
            }
            GridItem::PdfPage {
                pdf_path, page_num, ..
            } => crate::adjustment_db::zip_entry_key(pdf_path, &format!("page_{page_num}")),
            _ => return None,
        };
        Some(key)
    }

    pub(crate) fn invalidate_edit_preview_cache_for_key(&self, item_key: &str) {
        if let Some(service) = &self.edit_preview_cache {
            service.delete(item_key.to_string());
        }
    }

    fn snapshot_edit_preview_close_update(&mut self, idx: usize) -> Option<EditPreviewCloseUpdate> {
        if !self.settings.edit_preview_cache_enabled || self.edit_preview_cache.is_none() {
            return None;
        }
        let item_key = self.page_path_key(idx)?;
        let (source_mtime, source_size) = self.image_metas.get(idx).copied().flatten()?;
        // ZIP/PDF の container stat は encode と同じ専用 worker で行う。親コンテナの
        // 手動代表サムネイルは entry size を持たないため、保存時の container identity
        // を別に記録して照合する。
        let source_container_path = match self.items.get(idx)? {
            GridItem::ZipImage { zip_path, .. } => Some(zip_path.clone()),
            GridItem::PdfPage { pdf_path, .. } => Some(pdf_path.clone()),
            _ => None,
        };
        let has_source_edits = self.local_adjust_pages.contains(&idx)
            || self.mask_pages.contains(&idx)
            || self.conceal_pages.contains(&idx);
        let has_crop = self.export_crop_pages.contains(&idx);
        // fullscreen で読み込み済みの in-memory scene を使う。DB の debounce 確定前でも
        // 編集中の最新テキスト / スタンプを snapshot できる。
        let annotation_objects = self
            .comic_docs
            .get(&item_key)
            .filter(|objects| !objects.is_empty())
            .cloned();
        let has_annotations = annotation_objects.is_some();
        if !has_source_edits && !has_annotations && !has_crop {
            return Some(EditPreviewCloseUpdate::DeleteIfPresent { item_key });
        }

        let edit_key = self.current_edit_result_key(idx);
        let Some(entry) = self.edit_result_cache.get(&edit_key) else {
            // 最新世代がまだ完成していない場合、古いプレビューを表示する方が危険。
            // 今回は削除し、次に完成結果を表示して閉じた時に再生成する。
            return Some(EditPreviewCloseUpdate::DeleteIfPresent { item_key });
        };
        let pixels = Arc::clone(&entry.pixels);
        let crop = self.export_crop_rect_for_pixels(idx, pixels.size);
        let annotations = if let Some(objects) = annotation_objects {
            // fullscreen の comic 表示時に解決済みの FontSet を Arc clone する。close / page
            // navigation 境界で新しいフォント列挙やファイル読み込みを同期実行しない。
            let Some(fonts) = self.comic_fonts.clone() else {
                // 注釈を欠いたプレビューで旧結果を上書きしない。
                return Some(EditPreviewCloseUpdate::DeleteIfPresent { item_key });
            };
            let (source_w, source_h) = self
                .source_dims_for_idx(idx)
                .unwrap_or((pixels.size[0] as f32, pixels.size[1] as f32));
            Some(crate::edit_preview_cache::EditPreviewAnnotations {
                objects,
                fonts,
                stamp_cache: self.comic_stamp_cache.clone(),
                source_dims: [
                    source_w.round().max(1.0) as usize,
                    source_h.round().max(1.0) as usize,
                ],
            })
        } else {
            None
        };
        Some(EditPreviewCloseUpdate::Save {
            item_key,
            source_mtime,
            source_size,
            source_container_path,
            pixels,
            annotations,
            crop,
        })
    }

    fn enqueue_edit_preview_close_update(&self, update: Option<EditPreviewCloseUpdate>) {
        let (Some(service), Some(update)) = (&self.edit_preview_cache, update) else {
            return;
        };
        match update {
            EditPreviewCloseUpdate::Save {
                item_key,
                source_mtime,
                source_size,
                source_container_path,
                pixels,
                annotations,
                crop,
            } => service.save(
                item_key,
                source_mtime,
                source_size,
                source_container_path,
                pixels,
                annotations,
                crop,
                self.settings.edit_preview_cache_max_bytes.max(1_000_000),
                self.edit_preview_repaint_ctx.clone(),
            ),
            EditPreviewCloseUpdate::DeleteIfPresent { item_key } => {
                service.delete_if_present(item_key)
            }
        }
    }

    /// 補正レイヤーモード退出・別編集モードへの切替・ページ移動の境界で、現在ページの
    /// 完成済み edit-result を保存する。未完成なら旧 preview を削除するだけに留める。
    pub(crate) fn cache_current_edit_preview_if_ready(&mut self) {
        let update = self
            .fullscreen_idx
            .and_then(|idx| self.snapshot_edit_preview_close_update(idx));
        self.enqueue_edit_preview_close_update(update);
    }

    fn evict_thumbnail_for_edit_preview_refresh(&mut self, idx: usize) {
        for queue in [&self.reload_queue, &self.heavy_io_queue]
            .into_iter()
            .flatten()
        {
            if let Ok(mut pending) = queue.0.lock() {
                pending.retain(|req| req.idx != idx);
            }
        }
        self.requested.remove(&idx);
        self.pending_finalize.remove(&idx);
        self.texture_backlog.retain(|msg| msg.idx != idx);
        self.thumb_pixels.remove(&idx);
        self.thumb_edit_preview_layers.remove(&idx);
        self.thumb_adjust_tex.remove(&idx);
        self.idle_upgrade_cache_bypass_ineligible.remove(&idx);
        if let Some(state) = self.thumbnails.get_mut(idx) {
            *state = ThumbnailState::Evicted;
        }
    }

    fn thumbnail_indices_for_edit_preview_key(&self, item_key: &str) -> Vec<usize> {
        (0..self.items.len())
            .filter(|&idx| {
                self.page_path_key(idx).as_deref() == Some(item_key)
                    || self
                        .thumb_edit_preview_keys
                        .get(&idx)
                        .is_some_and(|key| key == item_key)
            })
            .collect()
    }

    fn clear_current_edit_preview_materializations(&mut self) {
        let mut invalidated: std::collections::HashSet<usize> =
            self.thumb_edit_preview_keys.keys().copied().collect();
        invalidated.extend(
            self.thumbnails
                .iter()
                .enumerate()
                .filter_map(|(idx, state)| {
                    matches!(
                        state,
                        ThumbnailState::Loaded {
                            from_edit_preview: true,
                            ..
                        }
                    )
                    .then_some(idx)
                }),
        );
        for idx in invalidated {
            self.evict_thumbnail_for_edit_preview_refresh(idx);
        }
        self.thumb_edit_preview_keys.clear();
        self.edit_preview_refresh_pending.clear();
    }

    /// 永続preview cacheはApp-globalなので、clear通知もmainだけでなく保持中の
    /// detached / paused contextへ同じ所有権境界で適用する。
    fn clear_all_edit_preview_materializations(&mut self) {
        self.clear_current_edit_preview_materializations();
        #[cfg(windows)]
        {
            if let Some(mut active) = self.active_detached_viewer_context.take() {
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.clear_current_edit_preview_materializations();
                self.swap_viewer_context_bundle(&mut active.bundle);
                self.active_detached_viewer_context = Some(active);
            }
            for index in 0..self.detached_image_windows.len() {
                let Some(mut bundle) = self.detached_image_windows[index].paused_bundle.take()
                else {
                    continue;
                };
                self.swap_viewer_context_bundle(&mut bundle);
                self.clear_current_edit_preview_materializations();
                self.swap_viewer_context_bundle(&mut bundle);
                self.detached_image_windows[index].paused_bundle = Some(bundle);
            }
        }
    }

    fn reconcile_pinned_adjustment_refreshes(&mut self) {
        if self.pinned_adjustment_refresh_keys.is_empty() {
            return;
        }
        // Only already materialized parent thumbnails can be stale. Future requests always read
        // the current DB value, so retaining unmatched page keys would grow this set for every
        // ordinary page adjustment during the process lifetime.
        let keys = std::mem::take(&mut self.pinned_adjustment_refresh_keys);
        for key in keys {
            let matching: Vec<usize> = self
                .thumb_edit_preview_keys
                .iter()
                .filter_map(|(&idx, preview_key)| {
                    (preview_key == &key
                        && self
                            .items
                            .get(idx)
                            .is_some_and(|item| !item.has_page_data()))
                    .then_some(idx)
                })
                .collect();
            for idx in matching {
                self.evict_thumbnail_for_edit_preview_refresh(idx);
            }
        }
    }

    fn poll_edit_preview_cache(&mut self, ctx: &egui::Context) {
        let mut events = Vec::new();
        if let Some(service) = &self.edit_preview_cache {
            while let Ok(event) = service.try_recv() {
                events.push(event);
            }
        }
        for event in events {
            match event {
                crate::edit_preview_cache::EditPreviewEvent::Saved { item_key } => {
                    let matching = self.thumbnail_indices_for_edit_preview_key(&item_key);
                    for idx in matching {
                        self.evict_thumbnail_for_edit_preview_refresh(idx);
                    }
                    self.edit_preview_refresh_pending.insert(
                        item_key,
                        std::time::Instant::now() + std::time::Duration::from_secs(10),
                    );
                }
                crate::edit_preview_cache::EditPreviewEvent::Invalidated { item_key } => {
                    let matching = self.thumbnail_indices_for_edit_preview_key(&item_key);
                    for idx in matching {
                        self.evict_thumbnail_for_edit_preview_refresh(idx);
                    }
                    self.edit_preview_refresh_pending.remove(&item_key);
                }
                crate::edit_preview_cache::EditPreviewEvent::Cleared => {
                    self.clear_all_edit_preview_materializations();
                }
            }
        }
        if !self.edit_preview_refresh_pending.is_empty() {
            ctx.request_repaint();
        }
    }

    fn reconcile_edit_preview_refreshes(&mut self, ctx: &egui::Context) {
        let now = std::time::Instant::now();
        let pending: Vec<(String, std::time::Instant)> = self
            .edit_preview_refresh_pending
            .iter()
            .map(|(key, deadline)| (key.clone(), *deadline))
            .collect();
        for (item_key, deadline) in pending {
            let matching = self.thumbnail_indices_for_edit_preview_key(&item_key);
            if matching.is_empty() {
                if now >= deadline {
                    self.edit_preview_refresh_pending.remove(&item_key);
                }
                continue;
            }
            let all_previews_loaded = matching.iter().all(|&idx| {
                matches!(
                    self.thumbnails.get(idx),
                    Some(ThumbnailState::Loaded {
                        from_edit_preview: true,
                        ..
                    })
                )
            });
            if all_previews_loaded || now >= deadline {
                self.edit_preview_refresh_pending.remove(&item_key);
                continue;
            }
            // 保存通知より前に開始済みだった raw decode が後着した場合も、次の
            // フレームで再度 Evicted にして preview cache を必ず読み直す。
            for idx in matching {
                if matches!(
                    self.thumbnails.get(idx),
                    Some(ThumbnailState::Loaded { .. }) | Some(ThumbnailState::Failed)
                ) {
                    self.evict_thumbnail_for_edit_preview_refresh(idx);
                }
            }
        }
        if !self.edit_preview_refresh_pending.is_empty() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
    }

    /// ページのサイドカー置き場 (= 対応する `mimageviewer.dat` が置かれるフォルダ) を返す。
    /// `page_path_key` と対になるヘルパー。3 バリアント対応漏れを避けるため同じ構造で書いている。
    pub(crate) fn sidecar_folder(&self, idx: usize) -> Option<std::path::PathBuf> {
        let item = self.items.get(idx)?;
        match item {
            GridItem::Image(p) => p.parent().map(|d| d.to_path_buf()),
            GridItem::ZipImage { zip_path, .. } => zip_path.parent().map(|d| d.to_path_buf()),
            GridItem::PdfPage { pdf_path, .. } => pdf_path.parent().map(|d| d.to_path_buf()),
            _ => None,
        }
    }

    /// サイドカー内のフォルダ相対キーを返す。小文字化され、`page_path_key` で使われる
    /// セパレータと整合する形式になる。
    pub(crate) fn sidecar_relative_key(&self, idx: usize) -> Option<String> {
        let item = self.items.get(idx)?;
        match item {
            GridItem::Image(p) => crate::sidecar::real_file_rel_key(p),
            GridItem::ZipImage {
                zip_path,
                entry_name,
            } => {
                let name = zip_path.file_name()?.to_string_lossy().to_lowercase();
                Some(format!("{name}::{}", entry_name.to_lowercase()))
            }
            GridItem::PdfPage {
                pdf_path, page_num, ..
            } => {
                let name = pdf_path.file_name()?.to_string_lossy().to_lowercase();
                Some(format!("{name}::page_{page_num}"))
            }
            _ => None,
        }
    }

    /// (sidecar_folder, sidecar_relative_key) のペアを取得する。
    pub(crate) fn sidecar_coords(&self, idx: usize) -> Option<(std::path::PathBuf, String)> {
        Some((self.sidecar_folder(idx)?, self.sidecar_relative_key(idx)?))
    }

    /// 指定フォルダのサイドカーへ可変参照を取得する。メモリ上に未ロードならロードする。
    /// `sidecar_backup_enabled` が OFF なら None を返す (呼び出し側は no-op になる)。
    fn sidecar_mut(
        &mut self,
        folder: &std::path::Path,
    ) -> Option<&mut crate::sidecar::SidecarFile> {
        if !self.settings.sidecar_backup_enabled {
            return None;
        }
        if !self.sidecars.contains_key(folder) {
            let loaded = crate::sidecar::SidecarFile::load(folder);
            self.sidecars.insert(folder.to_path_buf(), loaded);
        }
        self.sidecars.get_mut(folder)
    }

    /// タグ用サイドカーの可変参照を取得する。補正/マスク用とは独立した設定で gate する。
    fn tag_sidecar_mut(
        &mut self,
        folder: &std::path::Path,
    ) -> Option<&mut crate::sidecar::SidecarFile> {
        if !self.settings.tag_sidecar_backup_enabled {
            return None;
        }
        if !self.sidecars.contains_key(folder) {
            let loaded = crate::sidecar::SidecarFile::load(folder);
            self.sidecars.insert(folder.to_path_buf(), loaded);
        }
        self.sidecars.get_mut(folder)
    }

    pub(crate) fn mirror_tag_sidecar_update(
        &mut self,
        target: &crate::tag_write_worker::TagSidecarTarget,
        tags: &[String],
    ) {
        if let Some(sc) = self.tag_sidecar_mut(&target.folder) {
            sc.set_tags(&target.rel_key, tags);
        }
    }

    /// 指定 `idx` のページに対応するサイドカーに対し `op` を実行する。
    /// 設定 OFF・idx が画像系でない・フォルダ解決不能のいずれかなら黙って no-op。
    /// 書き込みミラーの 1 行化に使う。
    fn with_sidecar_mut<F>(&mut self, idx: usize, op: F)
    where
        F: FnOnce(&mut crate::sidecar::SidecarFile, &str),
    {
        if self.idx_is_compiled_book_page(idx) {
            return;
        }
        if let Some((folder, rel)) = self.sidecar_coords(idx) {
            if let Some(sc) = self.sidecar_mut(&folder) {
                op(sc, &rel);
            }
        }
    }

    /// 一覧 idx が変化した後でも、操作開始時に固定した sidecar 座標へ mirror する。
    pub(crate) fn with_sidecar_coords_mut<F>(
        &mut self,
        coords: Option<&(std::path::PathBuf, String)>,
        op: F,
    ) where
        F: FnOnce(&mut crate::sidecar::SidecarFile, &str),
    {
        let Some((folder, rel_key)) = coords else {
            return;
        };
        if let Some(sidecar) = self.sidecar_mut(folder) {
            op(sidecar, rel_key);
        }
    }

    /// すべての dirty なサイドカーをディスクにフラッシュする。
    /// 呼び出し側: フォルダ切替時・アプリ終了時・5 秒アイドル時。
    pub(crate) fn flush_all_sidecars(&mut self) {
        for sidecar in self.sidecars.values_mut() {
            sidecar.flush();
        }
    }

    /// アプリ終了時・トレイ退避時の共通永続化処理:
    /// ウィンドウ位置・サイズを settings に書き戻し、save + サイドカーを flush する。
    ///
    /// - サイズは `ViewportBuilder::with_inner_size` と整合する inner_size のみを書く
    ///   (不明なら前回保存値を維持。outer に fallback すると titlebar 分だけ縮小する
    ///    問題が再発するので fallback しない)。
    /// - 位置は outer_rect から取る (`with_position` は outer 座標を受け取る)。
    pub(crate) fn persist_window_state_and_flush(&mut self) {
        // スマートフォルダ管理画面は TextEdit 中の値をローカル draft に保持する。
        // 終了 / トレイ退避はダイアログ描画より先にこの経路へ来るため、Settings.save
        // より前に正規化・検証・反映だけを行う（再走査 worker は開始しない）。
        self.commit_smart_folder_editor_draft_for_persistence();
        if let Some(rect) = self.last_outer_rect {
            let x = crate::settings::viewport_points_to_window_geometry(
                rect.min.x,
                self.settings.ui_scale_factor,
            );
            let y = crate::settings::viewport_points_to_window_geometry(
                rect.min.y,
                self.settings.ui_scale_factor,
            );
            let w = crate::settings::viewport_points_to_window_geometry(
                rect.width(),
                self.settings.ui_scale_factor,
            );
            if crate::monitor::title_bar_on_some_monitor(x, y, w) {
                self.settings.window_pos = Some([x, y]);
            } else {
                crate::logger::log(format!(
                    "[window] skipped saving off-screen main window position: ({:.1}, {:.1}) size={:.1}x{:.1}",
                    x,
                    y,
                    w,
                    crate::settings::viewport_points_to_window_geometry(
                        rect.height(),
                        self.settings.ui_scale_factor,
                    )
                ));
            }
        }
        if let Some(raw_size) = self.last_inner_size {
            let size = [
                crate::settings::viewport_points_to_window_geometry(
                    raw_size[0],
                    self.settings.ui_scale_factor,
                ),
                crate::settings::viewport_points_to_window_geometry(
                    raw_size[1],
                    self.settings.ui_scale_factor,
                ),
            ];
            if size[0].is_finite()
                && size[1].is_finite()
                && size[0] >= 320.0
                && size[1] >= 240.0
                && size[0] <= 16_384.0
                && size[1] <= 16_384.0
            {
                self.settings.window_size = Some(size);
            } else {
                crate::logger::log(format!(
                    "[window] skipped saving invalid main window size: {:.1}x{:.1}",
                    size[0], size[1]
                ));
            }
        }
        self.settings.save();
        self.flush_all_sidecars();
    }

    /// マスクとベクタを DB に保存し、サイドカーにもミラーする。消しゴムモード終了時に呼ぶ。
    /// ビットマップが全 false かつベクタが空なら DB からもサイドカーからも削除する
    /// (mask_db.set の仕様と揃える)。サムネイルバッジ用の `mask_pages` もここで更新する。
    pub(crate) fn save_mask_with_sidecar(
        &mut self,
        idx: usize,
        mask: &[bool],
        shapes: &[crate::mask_db::Shape],
        w: usize,
        h: usize,
    ) {
        // bitmap が空 + shapes が空、または composite (bitmap + shapes rasterize 結果)
        // が全 false (= subtract-only 等) のときは DB + サイドカー側でも削除する。
        // 旧コードは bitmap_empty && shapes.is_empty() しか見ておらず、subtract-only
        // のマスクが永続化されて badge / display 経路で扱いに迷うケースが
        // 発生していた (Phase 1-5 code-review CONFIRMED)。
        if Self::composite_is_empty(mask, shapes, w, h) {
            self.delete_mask_with_sidecar(idx);
            return;
        }
        // 圧縮とベクタ JSON 化を 1 回だけ行い、DB 書き込みとサイドカー両方で共有。
        // 一括適用 (apply_slot_to_selection) で N ページに同じマスクを配るときの
        // N 倍 deflate を回避する。
        let compressed = crate::mask_db::compress_mask(mask);
        let shapes_json = crate::mask_db::shapes_to_json(shapes);
        self.save_mask_raw_with_sidecar(idx, &compressed, shapes, shapes_json.as_deref(), w, h);
    }

    /// 与えられた bitmap + shapes を rasterize した composite が全 false なら true。
    /// subtract-only の mask が永続化されて badge / display で混乱するのを防ぐため
    /// 共通判定として `save_*_with_sidecar` で使う。
    fn composite_is_empty(
        mask: &[bool],
        shapes: &[crate::mask_db::Shape],
        w: usize,
        h: usize,
    ) -> bool {
        let bitmap_empty = !mask.iter().any(|&m| m);
        if bitmap_empty && shapes.is_empty() {
            return true;
        }
        if w == 0 || h == 0 || mask.len() != w * h {
            // 元データが空 / サイズ不整合: 安全側で「空」扱いにして永続化しない。
            return true;
        }
        let mut composite = mask.to_vec();
        crate::mask_db::rasterize_shapes_into(&mut composite, shapes, w, h);
        !composite.iter().any(|&m| m)
    }

    /// 既に deflate 済みのビットマップ + JSON 済みベクタを DB + サイドカーに書き込む。
    /// `save_mask_with_sidecar` と一括適用パスの共通バックエンド。
    fn save_mask_raw_with_sidecar(
        &mut self,
        idx: usize,
        compressed: &[u8],
        shapes: &[crate::mask_db::Shape],
        shapes_json: Option<&str>,
        w: usize,
        h: usize,
    ) {
        let key = match self.page_path_key(idx) {
            Some(k) => k,
            None => return,
        };
        self.invalidate_edit_preview_cache_for_key(&key);
        if let Some(db) = &self.mask_db {
            let _ = db.set_raw(&key, compressed, shapes_json, w, h);
        }
        Self::set_page_key_presence(&mut self.mask_page_keys, &key, true);
        self.mask_pages.insert(idx);
        self.bump_erase_mask_generation(idx);
        let sidecar_mask =
            crate::sidecar::SidecarMask::from_raw(compressed, shapes, w as u32, h as u32);
        self.with_sidecar_mut(idx, move |sc, rel| sc.set_mask(rel, sidecar_mask));
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Edits,
        );
    }

    /// マスクを DB から削除し、サイドカーからも削除する。「マスク全削除」ボタン用。
    pub(crate) fn delete_mask_with_sidecar(&mut self, idx: usize) {
        let key = match self.page_path_key(idx) {
            Some(k) => k,
            None => return,
        };
        self.invalidate_edit_preview_cache_for_key(&key);
        if let Some(db) = &self.mask_db {
            let _ = db.delete(&key);
        }
        Self::set_page_key_presence(&mut self.mask_page_keys, &key, false);
        self.mask_pages.remove(&idx);
        self.bump_erase_mask_generation(idx);
        self.with_sidecar_mut(idx, |sc, rel| sc.remove_mask(rel));
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Edits,
        );
    }

    // ── 隠蔽加工マスクの永続化 (消しゴムと並列、Phase 4) ────────────────────
    //
    // パラメータ (タイプ・タイル倍率・境界モード・不透明度等) は settings 側に
    // グローバルで保存されるため、ここで扱うのは「マスクの形」(ビットマップ + ベクタ)
    // のみ。`conceal_db.set` / `conceal_db.delete` のラッパー + サイドカーミラー +
    // バッジ集合 (`conceal_pages`) の同期更新を 1 箇所に集約する。

    /// 隠蔽加工マスクを DB + サイドカーに保存する。`reset_conceal_mode` 終了時に呼ぶ。
    /// ビットマップが全 false かつ shapes が空なら `delete_conceal_with_sidecar` に委譲する
    /// (conceal_db.set の挙動と揃える)。
    pub(crate) fn save_conceal_with_sidecar(
        &mut self,
        idx: usize,
        mask: &[bool],
        shapes: &[crate::mask_db::Shape],
        w: usize,
        h: usize,
    ) {
        // composite_is_empty: bitmap + shapes rasterize 結果が全 false なら削除する。
        // subtract-only mask が badge 表示されたまま inpaint されないゴミ entry に
        // ならないようにする (Phase 1-5 code-review CONFIRMED)。
        if Self::composite_is_empty(mask, shapes, w, h) {
            self.delete_conceal_with_sidecar(idx);
            return;
        }
        // 圧縮とベクタ JSON 化を 1 回だけ行い、DB + サイドカーで共有
        let compressed = crate::mask_db::compress_mask(mask);
        let shapes_json = crate::mask_db::shapes_to_json(shapes);
        self.save_conceal_raw_with_sidecar(idx, &compressed, shapes, shapes_json.as_deref(), w, h);
    }

    /// 既に deflate 済みのビットマップ + JSON 済みベクタを DB + サイドカーに書き込む。
    /// `save_conceal_with_sidecar` の共通バックエンド (現在は単一 caller のみだが、
    /// erase 側 `save_mask_raw_with_sidecar` と対称の形を維持して将来の一括適用に備える)。
    fn save_conceal_raw_with_sidecar(
        &mut self,
        idx: usize,
        compressed: &[u8],
        shapes: &[crate::mask_db::Shape],
        shapes_json: Option<&str>,
        w: usize,
        h: usize,
    ) {
        let key = match self.page_path_key(idx) {
            Some(k) => k,
            None => return,
        };
        self.invalidate_edit_preview_cache_for_key(&key);
        if let Some(db) = &self.conceal_db {
            let _ = db.set_raw(&key, compressed, shapes_json, w, h);
        }
        Self::set_page_key_presence(&mut self.conceal_page_keys, &key, true);
        self.conceal_pages.insert(idx);
        self.bump_conceal_mask_generation(idx);
        let sidecar_conceal =
            crate::sidecar::SidecarMask::from_raw(compressed, shapes, w as u32, h as u32);
        self.with_sidecar_mut(idx, move |sc, rel| sc.set_conceal(rel, sidecar_conceal));
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Edits,
        );
    }

    /// 隠蔽加工マスクを DB + サイドカーから削除する。「マスク全削除」ボタン用 +
    /// `save_conceal_with_sidecar` の空マスク経路から呼ばれる。
    pub(crate) fn delete_conceal_with_sidecar(&mut self, idx: usize) {
        let key = match self.page_path_key(idx) {
            Some(k) => k,
            None => return,
        };
        self.invalidate_edit_preview_cache_for_key(&key);
        if let Some(db) = &self.conceal_db {
            let _ = db.delete(&key);
        }
        Self::set_page_key_presence(&mut self.conceal_page_keys, &key, false);
        self.conceal_pages.remove(&idx);
        self.bump_conceal_mask_generation(idx);
        self.with_sidecar_mut(idx, |sc, rel| sc.remove_conceal(rel));
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Edits,
        );
    }

    // ── local_adjust_cache / conceal_cache の世代管理 + invalidate ヘルパー ──

    /// 指定 idx の補正レイヤー配列を DB と in-memory state に反映する。
    /// 空配列は「補正レイヤーなし」として DB からも削除する。
    pub(crate) fn set_local_adjust_layers_for_idx(
        &mut self,
        idx: usize,
        layers: Vec<local_adjust_core::LocalAdjustmentLayer>,
    ) {
        let key = match self.page_path_key(idx) {
            Some(key) => key,
            None => return,
        };
        self.invalidate_edit_preview_cache_for_key(&key);
        if let Some(db) = &self.local_adjust_db {
            if let Err(err) = db.set_layers(&key, &layers) {
                crate::logger::log(format!(
                    "local_adjust: failed to save layers idx={idx} error={err}"
                ));
            }
        }
        Self::set_page_key_presence(&mut self.local_adjust_page_keys, &key, !layers.is_empty());
        if layers.is_empty() {
            self.with_sidecar_mut(idx, |sc, rel| sc.remove_local_adjust_layers(rel));
        } else {
            let sidecar_layers = layers.clone();
            self.with_sidecar_mut(idx, move |sc, rel| {
                sc.set_local_adjust_layers(rel, sidecar_layers)
            });
        }
        self.set_local_adjust_layers_for_idx_memory_only(idx, layers);
        self.schedule_current_smart_folder_metadata_refresh(
            smart_folder::SmartFolderMetadataDependency::Edits,
        );
    }

    /// 指定 idx の補正レイヤー配列を in-memory state だけに反映する。
    /// 画像上ドラッグなど高頻度更新では DB I/O を避け、release 時やパネル操作で保存する。
    pub(crate) fn set_local_adjust_layers_for_idx_memory_only(
        &mut self,
        idx: usize,
        layers: Vec<local_adjust_core::LocalAdjustmentLayer>,
    ) {
        self.set_local_adjust_layers_for_idx_memory_only_inner(idx, layers);
        self.bump_local_adjust_generation(idx);
    }

    pub(crate) fn set_local_adjust_layers_for_idx_memory_only_defer_render(
        &mut self,
        idx: usize,
        layers: Vec<local_adjust_core::LocalAdjustmentLayer>,
    ) {
        self.set_local_adjust_layers_for_idx_memory_only_inner(idx, layers);
        self.defer_local_adjust_brush_render(idx);
    }

    fn set_local_adjust_layers_for_idx_memory_only_inner(
        &mut self,
        idx: usize,
        layers: Vec<local_adjust_core::LocalAdjustmentLayer>,
    ) {
        if layers.is_empty() {
            self.local_adjust_page_layers.remove(&idx);
            self.local_adjust_pages.remove(&idx);
            self.local_adjust_selected_layers.remove(&idx);
        } else {
            let selected = self
                .local_adjust_selected_layers
                .get(&idx)
                .copied()
                .unwrap_or(0)
                .min(layers.len().saturating_sub(1));
            self.local_adjust_selected_layers.insert(idx, selected);
            self.local_adjust_page_layers.insert(idx, layers);
            self.local_adjust_pages.insert(idx);
        }
    }

    pub(crate) fn ensure_local_adjust_masks_match_source_dims(&mut self, idx: usize) -> bool {
        let Some(source) = self.current_local_adjust_source_pixels(idx) else {
            return false;
        };
        let [width, height] = source.size;
        let width = width.max(1);
        let height = height.max(1);
        let needs_resize = self
            .local_adjust_page_layers
            .get(&idx)
            .is_some_and(|layers| {
                layers
                    .iter()
                    .any(|layer| !layer.masks_match_dims(width, height))
            });
        if !needs_resize {
            return true;
        }
        self.local_adjust_cache.retain(|key, _| key.idx != idx);
        self.maybe_start_local_adjust_render(idx);
        false
    }

    /// 指定 idx の最後段 crop 設定を DB / サイドカー / in-memory state に反映する。
    /// `None` または full rect は「crop なし」として削除する。
    pub(crate) fn set_export_crop_for_idx(
        &mut self,
        idx: usize,
        settings: Option<crate::export_crop::CropSettings>,
        image_size: [usize; 2],
    ) {
        let key = match self.page_path_key(idx) {
            Some(key) => key,
            None => return,
        };
        let normalized = settings
            .map(|settings| settings.sanitized(image_size[0], image_size[1]))
            .filter(|settings| !settings.is_full(image_size[0], image_size[1]));

        if let Some(settings) = normalized {
            if let Some(db) = &self.export_crop_db {
                if let Err(err) = db.set(&key, settings) {
                    crate::logger::log(format!(
                        "export_crop: failed to save crop idx={idx} error={err}"
                    ));
                }
            }
            self.with_sidecar_mut(idx, move |sc, rel| sc.set_export_crop(rel, settings));
            self.export_crop_page_settings.insert(idx, settings);
            self.export_crop_pages.insert(idx);
        } else {
            if let Some(db) = &self.export_crop_db {
                if let Err(err) = db.remove(&key) {
                    crate::logger::log(format!(
                        "export_crop: failed to remove crop idx={idx} error={err}"
                    ));
                }
            }
            self.with_sidecar_mut(idx, |sc, rel| sc.remove_export_crop(rel));
            self.export_crop_page_settings.remove(&idx);
            self.export_crop_pages.remove(&idx);
        }
        // crop は edit-result / final AI を作り直さないが、永続編集プレビューの最終段には
        // 含まれる。確定した矩形が変わった時点で旧 WebP だけを失効させる。
        self.invalidate_edit_preview_cache_for_key(&key);
        self.invalidate_smart_folder_resort_metadata();
        // crop は表示パイプライン (edit_result / final composite) に含まれない (暗転
        // overlay のみ。実切り出しは save 時)。よって edit_result / final AI キャッシュは
        // 無効化しない。無効化すると crop ドラッグのたびに AI アップスケールを無駄に
        // 再実行 / キャンセルしてしまう (Codex P2)。
    }

    pub(crate) fn set_export_crop_for_idx_memory_only(
        &mut self,
        idx: usize,
        settings: Option<crate::export_crop::CropSettings>,
        image_size: [usize; 2],
    ) {
        let normalized = settings
            .map(|settings| settings.sanitized(image_size[0], image_size[1]))
            .filter(|settings| !settings.is_full(image_size[0], image_size[1]));
        if let Some(settings) = normalized {
            self.export_crop_page_settings.insert(idx, settings);
            self.export_crop_pages.insert(idx);
        } else {
            self.export_crop_page_settings.remove(&idx);
            self.export_crop_pages.remove(&idx);
        }
        // (上記 set_export_crop_for_idx と同じ理由でキャッシュ無効化しない。Codex P2)
    }

    pub(crate) fn export_crop_for_idx(
        &self,
        idx: usize,
        image_size: [usize; 2],
    ) -> Option<crate::export_crop::CropSettings> {
        self.export_crop_page_settings
            .get(&idx)
            .copied()
            .map(|settings| settings.sanitized(image_size[0], image_size[1]))
            .filter(|settings| !settings.is_full(image_size[0], image_size[1]))
    }

    /// 保存対象画像 (final composite。AI アップスケールで source とサイズが違うことが
    /// ある) のピクセル座標へスケールした crop 矩形を返す。crop は source 座標で保存
    /// されているので、`target_size / source_size` の比で等比拡縮する。表示は切り取らず
    /// capture / export の最終段でだけ使う。
    pub(crate) fn export_crop_rect_for_pixels(
        &self,
        idx: usize,
        target_size: [usize; 2],
    ) -> Option<crate::export_crop::CropRect> {
        let source_size = self.current_raw_source_pixels(idx)?.size;
        let crop = self.export_crop_for_idx(idx, source_size)?;
        if source_size == target_size {
            return Some(crop.rect);
        }
        let sx = target_size[0] as f32 / source_size[0].max(1) as f32;
        let sy = target_size[1] as f32 / source_size[1].max(1) as f32;
        Some(
            crate::export_crop::CropRect {
                min_x: crop.rect.min_x * sx,
                min_y: crop.rect.min_y * sy,
                max_x: crop.rect.max_x * sx,
                max_y: crop.rect.max_y * sy,
            }
            .sanitized(target_size[0], target_size[1]),
        )
    }

    /// 現在の input / erase mask / local adjust 世代から、補正レイヤー cache key を作る。
    pub(crate) fn current_local_adjust_key(&self, idx: usize) -> LocalAdjustResultKey {
        LocalAdjustResultKey {
            idx,
            input_gen: self.input_generation.get(&idx).copied().unwrap_or(0),
            erase_mask_gen: self.erase_mask_generation.get(&idx).copied().unwrap_or(0),
            local_gen: self.local_adjust_generation.get(&idx).copied().unwrap_or(0),
        }
    }

    /// 指定 idx の補正レイヤー cache を全世代分破棄する。
    pub(crate) fn clear_local_adjust_caches_for_idx(&mut self, idx: usize) {
        self.cancel_local_adjust_pending_for_idx(idx);
        self.local_adjust_cache.retain(|key, _| key.idx != idx);
        if self
            .local_adjust_layer_bypass_pending
            .as_ref()
            .is_some_and(|pending| pending.key.result_key.idx == idx)
        {
            self.cancel_local_adjust_layer_bypass_pending();
        }
        self.local_adjust_layer_bypass_cache
            .retain(|key, _| key.result_key.idx != idx);
        if self
            .local_adjust_prefix_preview_pending
            .as_ref()
            .is_some_and(|pending| pending.key.result_key.idx == idx)
        {
            self.cancel_local_adjust_prefix_preview_pending();
        }
        self.local_adjust_prefix_preview_cache
            .retain(|key, _| key.result_key.idx != idx);
    }

    fn cancel_local_adjust_pending_for_idx(&mut self, idx: usize) {
        if let Some(pending) = self.local_adjust_pending.remove(&idx) {
            pending.cancel.store(true, Ordering::Relaxed);
        }
    }

    fn cancel_conceal_materialize_pending_for_idx(&mut self, idx: usize) {
        let is_conceal = self.local_adjust_pending.get(&idx).is_some_and(|pending| {
            matches!(pending.request.kind, EditMaterializeKind::Conceal { .. })
        });
        if is_conceal {
            self.cancel_local_adjust_pending_for_idx(idx);
        }
    }

    fn cancel_all_conceal_materialize_pending(&mut self) {
        let indices = self
            .local_adjust_pending
            .iter()
            .filter_map(|(&idx, pending)| {
                matches!(pending.request.kind, EditMaterializeKind::Conceal { .. }).then_some(idx)
            })
            .collect::<Vec<_>>();
        for idx in indices {
            self.cancel_local_adjust_pending_for_idx(idx);
        }
    }

    fn cancel_local_adjust_layer_bypass_pending(&mut self) {
        if let Some(pending) = self.local_adjust_layer_bypass_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
    }

    fn cancel_local_adjust_prefix_preview_pending(&mut self) {
        if let Some(pending) = self.local_adjust_prefix_preview_pending.take() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
    }

    fn cancel_all_local_adjust_pending(&mut self) {
        for pending in self.local_adjust_pending.values() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        self.local_adjust_pending.clear();
        self.cancel_local_adjust_layer_bypass_pending();
        self.cancel_local_adjust_prefix_preview_pending();
    }

    fn cancel_final_ai_for_idx(&mut self, idx: usize) {
        let keys: Vec<FinalAiKey> = self
            .final_ai_pending
            .keys()
            .copied()
            .filter(|key| key.edit_key.idx == idx)
            .collect();
        for key in keys {
            if let Some(pending) = self.final_ai_pending.remove(&key) {
                pending.cancel.store(true, Ordering::Relaxed);
            }
        }
    }

    fn cancel_final_ai_pending_for_retained_key(
        &mut self,
        retained_key: &RetainedFinalAiKey,
        reason: &str,
    ) -> usize {
        let keys: Vec<FinalAiKey> = self
            .final_ai_pending
            .iter()
            .filter(|(_, pending)| pending.retained_key.as_ref() == Some(retained_key))
            .map(|(key, _)| *key)
            .collect();
        let mut cancelled = 0usize;
        for key in keys {
            if let Some(pending) = self.final_ai_pending.remove(&key) {
                pending.cancel.store(true, Ordering::Relaxed);
                cancelled += 1;
                crate::logger::log(format!(
                    "[AI] Final AI pending cancelled by retained cache idx={} item={} \
                     source={}x{} hash={} bg={} job_id={} reason={reason}",
                    key.edit_key.idx,
                    retained_key.item_key,
                    retained_key.edit_size[0],
                    retained_key.edit_size[1],
                    retained_key.color_ai_hash,
                    retained_key.bg,
                    pending.job_id,
                ));
            }
        }
        cancelled
    }

    fn maybe_orphan_final_ai_for_retained_store(&mut self, key: FinalAiKey, reason: &str) -> bool {
        let Some(pending) = self.final_ai_pending.get(&key) else {
            return false;
        };
        let retained_key = pending.retained_key.clone();
        let should_orphan = pending.allow_retained_orphan
            && retained_key.is_some()
            && pending.retained_epoch == self.retained_final_ai_epoch
            && self.retained_final_ai_budget().is_some()
            && self.retained_final_ai_orphans.len() < MAX_RETAINED_FINAL_AI_ORPHAN_JOBS;
        if should_orphan {
            let Some(mut pending) = self.final_ai_pending.remove(&key) else {
                return false;
            };
            pending.cancel_on_drop = false;
            let job_id = pending.job_id;
            let retained_key = retained_key.expect("checked retained_key.is_some()");
            self.retained_final_ai_orphans.insert(key, job_id);
            crate::logger::log(format!(
                "[AI] Final AI retained orphan idx={} item={} source={}x{} \
                 hash={} bg={} job_id={} reason={reason} orphans={} max_orphans={}",
                key.edit_key.idx,
                retained_key.item_key,
                retained_key.edit_size[0],
                retained_key.edit_size[1],
                key.color_ai_hash,
                key.bg,
                job_id,
                self.retained_final_ai_orphans.len(),
                MAX_RETAINED_FINAL_AI_ORPHAN_JOBS,
            ));
            true
        } else {
            false
        }
    }

    fn cancel_or_orphan_final_ai_for_session(&mut self, key: FinalAiKey, reason: &str) {
        if self.maybe_orphan_final_ai_for_retained_store(key, reason) {
            return;
        }
        if let Some(pending) = self.final_ai_pending.remove(&key) {
            pending.cancel.store(true, Ordering::Relaxed);
        }
    }

    fn mark_cancel_or_orphan_final_ai_for_evict(&mut self, key: FinalAiKey, reason: &str) {
        if self.maybe_orphan_final_ai_for_retained_store(key, reason) {
            return;
        }
        if let Some(pending) = self.final_ai_pending.get(&key) {
            pending.cancel.store(true, Ordering::Relaxed);
        }
    }

    fn clear_edit_result_caches_for_idx(&mut self, idx: usize) {
        self.edit_result_cache.retain(|key, _| key.idx != idx);
        self.clear_final_pipeline_caches_for_idx(idx);
    }

    fn clear_edit_result_caches_for_idx_preserving_retained_final_ai(&mut self, idx: usize) {
        self.edit_result_cache.retain(|key, _| key.idx != idx);
        self.clear_final_pipeline_caches_for_idx_preserving_retained_final_ai(idx);
    }

    fn clear_final_pipeline_caches_for_idx(&mut self, idx: usize) {
        self.clear_final_pipeline_caches_for_idx_inner(idx, true);
    }

    fn clear_final_pipeline_caches_for_idx_preserving_retained_final_ai(&mut self, idx: usize) {
        self.clear_final_pipeline_caches_for_idx_inner(idx, false);
    }

    fn clear_final_pipeline_caches_for_idx_inner(&mut self, idx: usize, clear_retained: bool) {
        self.cancel_final_ai_for_idx(idx);
        self.cancel_final_effects_for_idx(idx);
        self.final_ai_cache.retain(|key, _| key.edit_key.idx != idx);
        self.final_ai_failed.retain(|key| key.edit_key.idx != idx);
        self.final_composite_cache
            .retain_with_drop_reason("pipeline_invalidate_idx", |key, _| key.edit_key.idx != idx);
        if clear_retained {
            self.clear_retained_final_ai_for_idx(idx);
        }
        // comic は final composite を下地にするので連動破棄 (base_ptr の ABA 回避)。
        self.comic_cache.remove(&idx);
        // 進行中の comic ベイク worker も cancel (stale 結果の upload を防ぐ、Codex P1)。
        self.cancel_comic_bake_for_idx(idx);
    }

    pub(crate) fn clear_all_final_pipeline_caches(&mut self) {
        for pending in self.final_ai_pending.values() {
            pending.cancel.store(true, Ordering::Relaxed);
        }
        self.final_ai_pending.clear();
        self.final_ai_cache.clear();
        self.final_ai_failed.clear();
        self.cancel_all_final_effects();
        self.final_composite_cache
            .clear_with_drop_reason("pipeline_invalidate_all");
        self.comic_cache.clear();
        self.cancel_all_comic_bakes();
    }

    fn clear_all_final_pipeline_caches_for_session_close(&mut self) {
        let keys: Vec<FinalAiKey> = self.final_ai_pending.keys().copied().collect();
        for key in keys {
            self.cancel_or_orphan_final_ai_for_session(key, "session_close");
        }
        self.final_ai_cache.clear();
        self.final_ai_failed.clear();
        self.cancel_all_final_effects();
        self.final_composite_cache
            .clear_with_drop_reason("session_close");
        self.comic_cache.clear();
        self.cancel_all_comic_bakes();
    }

    /// 補正レイヤーが変わったことを idx 単位の世代で表す。
    pub(crate) fn bump_local_adjust_generation(&mut self, idx: usize) {
        self.cancel_deferred_local_adjust_brush_render(idx);
        let slot = self.local_adjust_generation.entry(idx).or_insert(0);
        *slot = slot.wrapping_add(1);
        self.clear_local_adjust_caches_for_idx(idx);
        self.clear_conceal_caches(idx);
        self.clear_edit_result_caches_for_idx(idx);
    }

    pub(crate) fn defer_local_adjust_brush_render(&mut self, idx: usize) {
        if self
            .local_adjust_brush_deferred_render
            .is_some_and(|pending| pending.idx != idx)
        {
            self.flush_deferred_local_adjust_brush_render();
        }
        self.local_adjust_brush_deferred_render = Some(LocalAdjustBrushDeferredRender {
            idx,
            last_input_at: std::time::Instant::now(),
        });
    }

    pub(crate) fn cancel_deferred_local_adjust_brush_render(&mut self, idx: usize) {
        if self
            .local_adjust_brush_deferred_render
            .is_some_and(|pending| pending.idx == idx)
        {
            self.local_adjust_brush_deferred_render = None;
        }
    }

    pub(crate) fn flush_deferred_local_adjust_brush_render(&mut self) -> bool {
        let Some(pending) = self.local_adjust_brush_deferred_render.take() else {
            return false;
        };
        self.bump_local_adjust_generation(pending.idx);
        true
    }

    pub(crate) fn poll_deferred_local_adjust_brush_render_at(
        &mut self,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        let pending = self.local_adjust_brush_deferred_render?;
        let defer_for = std::time::Duration::from_millis(LOCAL_ADJUST_BRUSH_EFFECT_DEFER_MS);
        let elapsed = now.saturating_duration_since(pending.last_input_at);
        if elapsed >= defer_for {
            self.flush_deferred_local_adjust_brush_render();
            None
        } else {
            Some(defer_for - elapsed)
        }
    }

    /// 現在世代に一致する補正レイヤー結果テクスチャを返す。
    pub(crate) fn current_local_adjust_texture(&self, idx: usize) -> Option<egui::TextureHandle> {
        let key = self.current_local_adjust_key(idx);
        self.local_adjust_cache
            .get(&key)
            .map(|entry| entry.texture.clone())
    }

    /// 現在世代に一致する補正レイヤー結果ピクセルを返す。
    pub(crate) fn current_local_adjust_pixels(&self, idx: usize) -> Option<Arc<egui::ColorImage>> {
        let key = self.current_local_adjust_key(idx);
        self.local_adjust_cache
            .get(&key)
            .map(|entry| Arc::clone(&entry.pixels))
    }

    pub(crate) fn current_local_adjust_layer_bypass_key(
        &self,
        idx: usize,
        layer_idx: usize,
    ) -> LocalAdjustLayerBypassPreviewKey {
        LocalAdjustLayerBypassPreviewKey {
            result_key: self.current_local_adjust_key(idx),
            layer_idx,
        }
    }

    pub(crate) fn current_local_adjust_layer_bypass_texture(
        &self,
        idx: usize,
        layer_idx: usize,
    ) -> Option<egui::TextureHandle> {
        let key = self.current_local_adjust_layer_bypass_key(idx, layer_idx);
        self.local_adjust_layer_bypass_cache
            .get(&key)
            .map(|entry| entry.texture.clone())
    }

    pub(crate) fn current_local_adjust_prefix_preview_key(
        &self,
        idx: usize,
        layer_count: usize,
    ) -> LocalAdjustPrefixPreviewKey {
        LocalAdjustPrefixPreviewKey {
            result_key: self.current_local_adjust_key(idx),
            layer_count,
        }
    }

    pub(crate) fn current_local_adjust_prefix_preview_texture(
        &self,
        idx: usize,
        layer_count: usize,
    ) -> Option<egui::TextureHandle> {
        let key = self.current_local_adjust_prefix_preview_key(idx, layer_count);
        self.local_adjust_prefix_preview_cache
            .get(&key)
            .map(|entry| entry.texture.clone())
    }

    fn local_adjust_layers_with_selected_layer_bypassed(
        &self,
        idx: usize,
        layer_idx: usize,
    ) -> Option<Vec<local_adjust_core::LocalAdjustmentLayer>> {
        let mut layers = self.local_adjust_layers_for_render(idx)?;
        let layer = layers.get_mut(layer_idx)?;
        layer.enabled = false;
        layers
            .iter()
            .any(|layer| layer.enabled && layer.opacity > 0.0)
            .then_some(layers)
    }

    fn local_adjust_layers_until(
        &self,
        idx: usize,
        layer_count: usize,
    ) -> Option<Vec<local_adjust_core::LocalAdjustmentLayer>> {
        let layers = self.local_adjust_page_layers.get(&idx)?;
        let count = layer_count.min(layers.len());
        if count == 0 || count >= layers.len() {
            return None;
        }
        let preview_layers = layers[..count].to_vec();
        preview_layers
            .iter()
            .any(|layer| layer.enabled && layer.opacity > 0.0)
            .then_some(preview_layers)
    }

    fn local_adjust_layers_for_render(
        &self,
        idx: usize,
    ) -> Option<Vec<local_adjust_core::LocalAdjustmentLayer>> {
        let layers = self.local_adjust_page_layers.get(&idx)?;
        layers
            .iter()
            .any(|layer| layer.enabled && layer.opacity > 0.0)
            .then(|| layers.clone())
    }

    pub(crate) fn has_active_local_adjust_layers(&self, idx: usize) -> bool {
        self.local_adjust_page_layers
            .get(&idx)
            .is_some_and(|layers| {
                layers
                    .iter()
                    .any(|layer| layer.enabled && layer.opacity > 0.0)
            })
    }

    pub(crate) fn current_local_adjust_source_pixels(
        &self,
        idx: usize,
    ) -> Option<Arc<egui::ColorImage>> {
        if let Some(pixels) = self.current_erase_result_pixels(idx) {
            return Some(pixels);
        }
        if self.mask_pages.contains(&idx) {
            return None;
        }
        self.current_raw_source_pixels(idx)
    }

    pub(crate) fn maybe_start_local_adjust_render(&mut self, idx: usize) {
        self.maybe_start_local_adjust_render_with_continuation(
            idx,
            LocalMaterializeContinuation::Display,
        );
    }

    pub(crate) fn maybe_start_local_adjust_render_with_continuation(
        &mut self,
        idx: usize,
        continuation: LocalMaterializeContinuation,
    ) {
        if !self.local_adjust_pages.contains(&idx)
            && !self.local_adjust_page_layers.contains_key(&idx)
        {
            return;
        }
        let key = self.current_local_adjust_key(idx);
        let request = EditMaterializeRequest {
            items_generation: self.items_generation,
            input_seq: self.input_seq,
            kind: EditMaterializeKind::Local { key, continuation },
        };
        if self.local_adjust_pending.get(&idx).is_some_and(|pending| {
            pending.request.items_generation == request.items_generation
                && pending.request.kind == request.kind
        }) {
            return;
        }
        let Some(source) = self.current_local_adjust_source_pixels(idx) else {
            return;
        };
        let [width, height] = source.size;
        let masks_need_resize = self
            .local_adjust_page_layers
            .get(&idx)
            .is_some_and(|layers| {
                layers
                    .iter()
                    .any(|layer| !layer.masks_match_dims(width.max(1), height.max(1)))
            });
        let loaded_layers_are_inactive =
            self.local_adjust_page_layers
                .get(&idx)
                .is_some_and(|layers| {
                    !layers
                        .iter()
                        .any(|layer| layer.enabled && layer.opacity > 0.0)
                });
        if loaded_layers_are_inactive && !masks_need_resize {
            return;
        }
        if self.current_local_adjust_texture(idx).is_some() && !masks_need_resize {
            return;
        }
        if masks_need_resize {
            self.local_adjust_cache
                .retain(|cache_key, _| cache_key.idx != idx);
        }
        let layers_source = if let Some(layers) = self.local_adjust_page_layers.get(&idx) {
            LocalMaterializeLayers::Memory(layers.clone())
        } else {
            let Some(page_key) = self.page_path_key(idx) else {
                self.local_adjust_pages.remove(&idx);
                return;
            };
            LocalMaterializeLayers::Database {
                path: crate::local_adjust_db::LocalAdjustDb::db_path(),
                page_key,
            }
        };

        self.cancel_local_adjust_pending_for_idx(idx);
        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_worker = Arc::clone(&cancel);
        let (tx, rx) = mpsc::channel();
        let spawn_result = std::thread::Builder::new()
            .name("local-adjust-render".to_string())
            .spawn(move || {
                let result = run_local_materialize(request, source, layers_source, cancel_worker);
                let _ = tx.send(result);
            });
        if let Err(err) = spawn_result {
            crate::logger::log(format!("local_adjust: render worker spawn failed: {err}"));
            return;
        }

        self.local_adjust_pending.insert(
            idx,
            LocalAdjustRenderPending {
                request,
                cancel,
                rx,
                ready: None,
            },
        );
    }

    pub(crate) fn maybe_start_local_adjust_layer_bypass_preview(
        &mut self,
        idx: usize,
        layer_idx: usize,
    ) {
        if !self.local_adjust_page_layers.contains_key(&idx) {
            self.maybe_start_local_adjust_render(idx);
            return;
        }
        if self
            .current_local_adjust_layer_bypass_texture(idx, layer_idx)
            .is_some()
        {
            return;
        }
        let key = self.current_local_adjust_layer_bypass_key(idx, layer_idx);
        if self
            .local_adjust_layer_bypass_pending
            .as_ref()
            .is_some_and(|pending| pending.key == key)
        {
            return;
        }
        let Some(layers) = self.local_adjust_layers_with_selected_layer_bypassed(idx, layer_idx)
        else {
            return;
        };
        let Some(source) = self.current_local_adjust_source_pixels(idx) else {
            return;
        };

        self.cancel_local_adjust_layer_bypass_pending();
        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_worker = Arc::clone(&cancel);
        let render_key = key.result_key;
        let (tx, rx) = mpsc::channel();
        let spawn_result = std::thread::Builder::new()
            .name("local-adjust-layer-bypass-preview".to_string())
            .spawn(move || {
                let result = run_local_adjust_render(render_key, source, layers, cancel_worker);
                let _ = tx.send(result);
            });
        if let Err(err) = spawn_result {
            crate::logger::log(format!(
                "local_adjust: layer bypass preview worker spawn failed: {err}"
            ));
            return;
        }

        self.local_adjust_layer_bypass_pending =
            Some(LocalAdjustLayerBypassPending { key, cancel, rx });
    }

