// セル描画
// -----------------------------------------------------------------------

/// Container (Folder/ZipFile/PdfFile) の catalog cache 基底キー (`folderthumb:...` /
/// `zipthumb:...` / `pdfthumb:...`) を組み立てる共通ヘルパー (T54 + Codex follow-on / 2026-05-16)。
/// Folder の自動代表キーには選定アルゴリズム版・ソート種別・探索深度を含める。
///
/// `use_full_path` が `true` のときは basename ではなく full path 文字列を使う。
/// これは Ctrl+S 検索結果 (= 複数フォルダの同名コンテナが同一リストに混在しうる) で衝突を
/// 避けるために必要。`make_load_request` / `apply_folder_thumb_pin` (= 読み出し側) と
/// `seed_folder_video_pin_thumbs` / `folder_thumb_existing_keys_for` (= 書き込み / 掃除側)
/// が **必ず同じ関数を呼ぶ** ことで、key 構築の重複と乖離を構造的に防ぐ。
///
/// Image / ZipImage / PdfPage 等 container 以外には対応しない (= 呼び出し側で
/// match して使い分け)。`None` が返るのは `file_name` が UTF-8 で取れなかった
/// 極端なケースのみ。
fn container_cache_base_key(
    item: &GridItem,
    use_full_path: bool,
    folder_thumb_sort: Option<crate::settings::SortOrder>,
    folder_thumb_depth: u32,
) -> Option<String> {
    let (path, prefix) = match item {
        GridItem::Folder(p) => {
            let sort = folder_thumb_sort.unwrap_or(crate::settings::SortOrder::Numeric);
            return crate::thumb_loader::folder_thumb_auto_cache_key_for_path(
                p,
                use_full_path,
                sort,
                folder_thumb_depth,
            );
        }
        GridItem::ZipFile(p) => (p, CACHE_KEY_ZIP),
        GridItem::PdfFile(p) => (p, CACHE_KEY_PDF),
        _ => return None,
    };
    if use_full_path {
        // PathBuf::to_string_lossy はゼロ alloc な Cow を返すが、format! でどうせ
        // 文字列を作るので素直に String 化する。
        Some(format!("{}{}", prefix, path.to_string_lossy()))
    } else {
        let fname = path.file_name().and_then(|n| n.to_str())?;
        Some(format!("{prefix}{fname}"))
    }
}

fn archive_thumb_format_token(format: crate::archive_converter::ArchiveFormat) -> &'static str {
    match format {
        crate::archive_converter::ArchiveFormat::Rar => "rar",
        crate::archive_converter::ArchiveFormat::SevenZ => "7z",
        crate::archive_converter::ArchiveFormat::Lzh => "lzh",
        crate::archive_converter::ArchiveFormat::Zip => "zip",
    }
}

fn convertible_archive_cache_base_key(
    path: &std::path::Path,
    format: crate::archive_converter::ArchiveFormat,
    use_full_path: bool,
) -> Option<String> {
    let identity = if use_full_path {
        path.to_string_lossy().into_owned()
    } else {
        path.file_name().and_then(|n| n.to_str())?.to_string()
    };
    Some(format!(
        "{}{}:{}",
        CACHE_KEY_ARCHIVE,
        archive_thumb_format_token(format),
        identity
    ))
}

fn pin_source_id_with_container_identity(
    source: &crate::folder_thumb_pins::FolderPinSource,
    mtime: i64,
    file_size: i64,
) -> String {
    format!(
        "{}{}|{}",
        pin_source_id_cache_prefix(source),
        mtime,
        file_size
    )
}

fn convertible_archive_pinned_cache_key(
    base_key: &str,
    source: &crate::folder_thumb_pins::FolderPinSource,
    mtime: i64,
    file_size: i64,
) -> String {
    format!(
        "{}{}{}",
        base_key,
        crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
        pin_source_id_with_container_identity(source, mtime, file_size)
    )
}

impl App {
    /// サムネイル cache key に full-path を使うべきコンテキストか。
    ///
    /// Ctrl+S / Ctrl+G / Ctrl+T 検索結果ビューとドライブルートでは、basename ベースの
    /// cache key だと別スコープの同名項目を誤表示しうる。このメソッドが true を返す
    /// コンテキストでは `make_load_request` が full-path を含むキーを使う。
    /// サムネ読み出し側、`delete_missing` の存続キー、seed 側で必ず同じ判定を共有すること。
    pub(crate) fn use_full_path_cache_keys(&self) -> bool {
        self.current_folder
            .as_deref()
            .is_some_and(use_full_path_cache_keys_for_folder)
            || self.items_are_global_search_view
            || self.items_are_tag_view
            || self.items_are_reading_history_view
            || self.items_are_rating_view
    }
}

fn use_full_path_cache_keys_for_folder(path: &std::path::Path) -> bool {
    is_synthetic_view_path(path) || crate::path_key::is_drive_or_share_root(path)
}

/// 検索結果ビュー (Ctrl+S / Ctrl+G) の画像用 full-path cache key (Codex P1)。
/// basename だと複数フォルダの同名画像が衝突する。full path は `:` `/` を含むので
/// 通常の basename キー・コンテナキー (`folderthumb:` 等) と自然に区別される。
fn image_full_path_cache_key(path: &std::path::Path) -> String {
    format!("imgthumb:{}", path.to_string_lossy())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReadingHistoryOpenPathStatus {
    Available,
    Missing,
    Unavailable,
}

pub(crate) fn reading_history_open_path_status(
    path: &std::path::Path,
) -> ReadingHistoryOpenPathStatus {
    match path.try_exists() {
        Ok(true) => ReadingHistoryOpenPathStatus::Available,
        Ok(false) if reading_history_storage_root_available(path) => {
            ReadingHistoryOpenPathStatus::Missing
        }
        Ok(false) | Err(_) => ReadingHistoryOpenPathStatus::Unavailable,
    }
}

#[cfg(windows)]
fn reading_history_storage_root_available(path: &std::path::Path) -> bool {
    use std::path::{Component, Prefix};

    let mut components = path.components();
    let Some(Component::Prefix(prefix)) = components.next() else {
        return true;
    };
    match prefix.kind() {
        Prefix::Disk(letter) | Prefix::VerbatimDisk(letter) => {
            let drive = format!("{}:\\", char::from(letter));
            std::path::Path::new(&drive).try_exists().unwrap_or(false)
        }
        Prefix::UNC(server, share) | Prefix::VerbatimUNC(server, share) => {
            let root = std::path::PathBuf::from(format!(
                r"\\{}\{}",
                server.to_string_lossy(),
                share.to_string_lossy()
            ));
            root.try_exists().unwrap_or(false)
        }
        _ => true,
    }
}

#[cfg(not(windows))]
fn reading_history_storage_root_available(_path: &std::path::Path) -> bool {
    true
}

struct ReadingHistoryLoadInputs {
    items: Vec<GridItem>,
    image_metas: Vec<Option<(i64, i64)>>,
    video_items: Vec<(usize, PathBuf, u64)>,
    rows: std::collections::HashMap<String, crate::reading_history_db::ReadingHistoryEntry>,
}

fn reading_history_load_inputs(
    entries: Vec<crate::reading_history_db::ReadingHistoryEntry>,
) -> ReadingHistoryLoadInputs {
    let mut items = Vec::with_capacity(entries.len());
    let mut image_metas = Vec::with_capacity(entries.len());
    let mut video_items = Vec::new();
    let mut rows = std::collections::HashMap::with_capacity(entries.len());
    for entry in entries {
        let idx = items.len();
        let item = reading_history_grid_item(&entry);
        if matches!(item, GridItem::Video(_)) {
            let file_size = entry
                .file_size
                .and_then(|size| u64::try_from(size).ok())
                .unwrap_or(0);
            video_items.push((idx, entry.path.clone(), file_size));
        }
        image_metas.push(reading_history_meta_for_entry(&entry));
        items.push(item);
        rows.insert(entry.key.clone(), entry);
    }
    ReadingHistoryLoadInputs {
        items,
        image_metas,
        video_items,
        rows,
    }
}

fn reading_history_grid_item(entry: &crate::reading_history_db::ReadingHistoryEntry) -> GridItem {
    match entry.kind {
        crate::reading_history_db::ReadingHistoryKind::Folder => {
            GridItem::Folder(entry.path.clone())
        }
        crate::reading_history_db::ReadingHistoryKind::Zip => GridItem::ZipFile(entry.path.clone()),
        crate::reading_history_db::ReadingHistoryKind::Pdf => GridItem::PdfFile(entry.path.clone()),
        crate::reading_history_db::ReadingHistoryKind::Archive => {
            if let Some(format) = entry
                .archive_format
                .or_else(|| crate::reading_history_db::archive_format_for_path(&entry.path))
            {
                GridItem::ConvertibleArchive {
                    path: entry.path.clone(),
                    format,
                }
            } else {
                GridItem::ZipFile(entry.path.clone())
            }
        }
        crate::reading_history_db::ReadingHistoryKind::Video => GridItem::Video(entry.path.clone()),
        crate::reading_history_db::ReadingHistoryKind::Audio => GridItem::Audio(entry.path.clone()),
    }
}

fn reading_history_meta_for_entry(
    entry: &crate::reading_history_db::ReadingHistoryEntry,
) -> Option<(i64, i64)> {
    let mtime = entry.mtime_ms.map(|ms| ms / 1000).unwrap_or(0);
    let file_size = entry.file_size.unwrap_or(0);
    Some((mtime, file_size))
}

pub(crate) fn reading_history_key_for_item(item: &GridItem) -> Option<String> {
    let path = match item {
        GridItem::Video(path) | GridItem::Audio(path) => path.as_path(),
        _ => item.container_path()?,
    };
    Some(crate::path_key::normalize_keep_drive(path))
}

fn reading_history_title_for_path(path: &std::path::Path) -> String {
    path.file_name()
        .and_then(|n| n.to_str())
        .map(str::to_string)
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| path.to_string_lossy().to_string())
}

fn archive_rating_kind_for_path(path: &std::path::Path) -> crate::rating_db::RatingItemKind {
    use crate::rating_db::RatingItemKind;
    if path.is_dir() {
        return RatingItemKind::Folder;
    }
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_ascii_lowercase())
        .unwrap_or_default();
    if crate::folder_tree::is_zip_extension(&ext) {
        RatingItemKind::ZipFile
    } else if ext == "pdf" {
        RatingItemKind::PdfFile
    } else if crate::archive_converter::ArchiveFormat::from_extension(&ext).is_some() {
        RatingItemKind::ConvertibleArchive
    } else {
        RatingItemKind::Folder
    }
}

fn archive_format_for_rating_path(
    path: &std::path::Path,
) -> Option<crate::archive_converter::ArchiveFormat> {
    path.extension()
        .and_then(|e| e.to_str())
        .and_then(crate::archive_converter::ArchiveFormat::from_extension)
}

fn archive_format_to_rating_str(format: crate::archive_converter::ArchiveFormat) -> &'static str {
    match format {
        crate::archive_converter::ArchiveFormat::Rar => "rar",
        crate::archive_converter::ArchiveFormat::SevenZ => "7z",
        crate::archive_converter::ArchiveFormat::Lzh => "lzh",
        crate::archive_converter::ArchiveFormat::Zip => "zip",
    }
}

fn zipdir_prefix_is_archive(prefix: &str) -> bool {
    let trimmed = prefix.trim_end_matches('/');
    let last = trimmed.rsplit('/').next().unwrap_or(trimmed);
    let ext = last
        .rsplit_once('.')
        .map(|(_, ext)| ext.to_ascii_lowercase())
        .unwrap_or_default();
    crate::folder_tree::is_zip_extension(&ext)
        || crate::archive_converter::ArchiveFormat::from_extension(&ext).is_some()
}

fn entry_name_is_image(entry_name: &str) -> bool {
    let ext = entry_name
        .rsplit_once('.')
        .map(|(_, ext)| ext.to_ascii_lowercase())
        .unwrap_or_default();
    crate::folder_tree::is_recognized_image_ext(&ext)
}

fn drive_list_catalog_path() -> PathBuf {
    PathBuf::from("__mimageviewer_drive_list__")
}

fn drive_list_last_folder_sentinel() -> PathBuf {
    PathBuf::new()
}

fn is_drive_list_last_folder(path: &std::path::Path) -> bool {
    path.as_os_str().is_empty()
}

fn should_start_in_drive_list(settings: &crate::settings::Settings) -> bool {
    settings.startup_folder_mode == crate::settings::StartupFolderMode::Drives
        || (settings.startup_folder_mode == crate::settings::StartupFolderMode::Previous
            && settings
                .last_folder
                .as_deref()
                .is_some_and(is_drive_list_last_folder))
}

fn drive_display_label(path: &std::path::Path) -> Option<String> {
    let s = path.as_os_str().to_string_lossy();
    let trimmed = s.trim_end_matches(['\\', '/']);
    let bytes = trimmed.as_bytes();
    if bytes.len() == 2 && bytes[0].is_ascii_alphabetic() && bytes[1] == b':' {
        Some(trimmed.to_ascii_uppercase())
    } else {
        None
    }
}

fn pin_source_id_cache_prefix(source: &crate::folder_thumb_pins::FolderPinSource) -> String {
    let entry_part = match source {
        crate::folder_thumb_pins::FolderPinSource::ZipEntry { entry, .. } => entry.as_str(),
        crate::folder_thumb_pins::FolderPinSource::ZipDir { dir_prefix, .. } => dir_prefix.as_str(),
        _ => "-",
    };
    let page_part = match source {
        crate::folder_thumb_pins::FolderPinSource::PdfPage { page, .. } => page.to_string(),
        _ => "-".to_string(),
    };
    format!(
        "{}|{}|{}|{}|",
        source.db_kind(),
        source.rel(),
        entry_part,
        page_part
    )
}

fn drive_list_pinned_cache_key_prefix(
    base_key: &str,
    source: &crate::folder_thumb_pins::FolderPinSource,
) -> String {
    format!(
        "{}{}{}",
        base_key,
        crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
        pin_source_id_cache_prefix(source)
    )
}

fn drive_list_pinned_cache_key(prefix: &str, mtime: i64, file_size: i64) -> String {
    format!("{prefix}{mtime}|{file_size}")
}

fn direct_pin_rel_file_name(rel: &str) -> Option<String> {
    let path = std::path::Path::new(rel);
    if path.components().count() != 1 {
        return None;
    }
    path.file_name().and_then(|n| n.to_str()).map(str::to_owned)
}

fn make_drive_list_pin_load_request(
    item: &GridItem,
    idx: usize,
    folder_thumb_sort: crate::settings::SortOrder,
    folder_thumb_depth: u32,
    pin_map: &std::collections::HashMap<String, crate::folder_thumb_pins::FolderPinSource>,
    _pin_db: Option<&crate::folder_thumb_pins::FolderThumbPinDb>,
) -> Option<LoadRequest> {
    let GridItem::Folder(container_path) = item else {
        return None;
    };
    let container_key = crate::path_key::normalize_keep_drive(container_path);
    let source = pin_map.get(&container_key)?;
    if !pin_source_compatible_with_container(ContainerKindForPin::Folder, source) {
        crate::logger::log(format!(
            "drive-list pin: incompatible source for {} (source={:?})",
            container_path.display(),
            source,
        ));
        return None;
    }
    let base_key =
        container_cache_base_key(item, true, Some(folder_thumb_sort), folder_thumb_depth)?;
    let cache_key_prefix = drive_list_pinned_cache_key_prefix(&base_key, source);
    Some(LoadRequest {
        idx,
        path: container_path.clone(),
        cache_key_override: Some(base_key.clone()),
        folder_thumb_sort: Some(folder_thumb_sort),
        folder_thumb_depth,
        pinned_only: Some(crate::thumb_loader::PinnedOnlyRequest { cache_key_prefix }),
        ..Default::default()
    })
}

/// GridItem から LoadRequest を構築する。画像 / ZIP 内画像 / PDF ページ / フォルダ以外は None を返す。
///
/// `pin_map` は親コンテナ (Folder/ZipFile/PdfFile) のピン source 一覧で、
/// `App::folder_pin_map` の参照を渡す。空 HashMap でも構わない (= pin 機能なし相当)。
/// pin が見つかったコンテナは `apply_folder_thumb_pin` で `LoadRequest` を target
/// 種別の形に書き換える (cache_key は親 prefix を維持し suffix で identity を載せる)。
/// ネスト ZIP の「本」(= 内側 ZIP / サブフォルダ) の代表サムネピン用コンテナキー。
/// `zip_path` に `dir_prefix` ("a/b/") のセグメントを join した合成パス。
/// `App::spread_container_key` (zip_path + 現在の実効 prefix) と同じ構成で、非崩しの
/// 通常本では「本の中で pin したキー」と「親で ZipDir セルを引くキー」が一致する。
fn book_container_key(zip_path: &std::path::Path, dir_prefix: &str) -> PathBuf {
    let mut p = zip_path.to_path_buf();
    for seg in dir_prefix.split('/').filter(|s| !s.is_empty()) {
        p.push(seg);
    }
    p
}

/// `book_container_key` のセグメント列版 (`collapse_redundant` の実効 prefix から作る)。
fn book_container_key_from_segs(zip_path: &std::path::Path, segs: &[String]) -> PathBuf {
    let mut p = zip_path.to_path_buf();
    for seg in segs {
        p.push(seg);
    }
    p
}

fn zip_dir_prefix_segments(dir_prefix: &str) -> Vec<String> {
    dir_prefix
        .split('/')
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .collect()
}

fn zip_dir_prefix_from_segs(segs: &[String]) -> String {
    if segs.is_empty() {
        String::new()
    } else {
        format!("{}/", segs.join("/"))
    }
}

/// ZIP ツリーナビ内の「本」キーで使う root path。
///
/// 通常 ZIP は `zip_path` そのものを使う。RAR/7z/LZH を変換キャッシュ ZIP として
/// 開いているときだけ、ユーザー視点の元アーカイブ (`archive_source_override`) を
/// root にする。これにより、変換後ビュー内で付けたピンが親フォルダの
/// `ConvertibleArchive` タイルからも同じ key で参照できる。
fn zip_pin_root_path<'a>(
    zip_path: &'a std::path::Path,
    archive_source_override: Option<&'a std::path::Path>,
    current_folder: Option<&std::path::Path>,
) -> &'a std::path::Path {
    if let Some(source) = archive_source_override
        && current_folder.is_some_and(|cur| crate::folder_tree::path_eq(cur, zip_path))
    {
        source
    } else {
        zip_path
    }
}

/// ZIP ツリーナビ内のコンテナレーティングで使う root path。
///
/// 通常 ZIP は `zip_path`、RAR/7z/LZH 変換キャッシュ ZIP では元アーカイブを使う。
/// これにより、親フォルダの `ConvertibleArchive` セルに F2 で付けた★と、
/// 変換後ビューの root で Shift+F2 した★が同じ key を共有する。
fn zip_rating_root_path<'a>(
    zip_path: &'a std::path::Path,
    archive_source_override: Option<&'a std::path::Path>,
    current_folder: Option<&std::path::Path>,
) -> &'a std::path::Path {
    zip_pin_root_path(zip_path, archive_source_override, current_folder)
}

/// ネスト ZIP の階層 re-materialize (`zip_nav_show_current_level`) でサムネを使い回す
/// ための content key。同一 ZIP 内の移動専用なので zip_path は含めない。
///
/// - ZipImage = `i:{entry_name}` (フルパス)。
/// - ZipDir = `d:{dir_prefix}#{representative}`。**`representative` を必ず含める**:
///   `materialize_level` は代表画像をソート順準拠で選ぶため、ソート変更の
///   re-materialize で同じ `dir_prefix` でも代表が変わり得る。`dir_prefix` だけで
///   同一視すると旧代表の Loaded サムネが移植されたまま再ロードが走らず、
///   表紙が古いまま残る (Codex P2)。代表が変わったセルはキー不一致 → Pending に
///   戻って新代表で読み直す。ピン済みセルは表示が pinned entry なので代表変化は
///   無関係だが、キー不一致で再ロードされるだけ (キャッシュ hit、無害) なので
///   ここでは pin を考慮しない。
/// - `i:`/`d:` の型タグでキー空間を分離する (`#` を含む entry 名と
///   `{dir_prefix}#{representative}` の理論衝突を防ぐ)。
fn zip_level_thumb_reuse_key(item: &GridItem) -> Option<String> {
    match item {
        GridItem::ZipImage { entry_name, .. } => Some(format!("i:{entry_name}")),
        GridItem::ZipDir {
            dir_prefix,
            representative,
            ..
        } => Some(format!(
            "d:{dir_prefix}#{}",
            representative.as_deref().unwrap_or("")
        )),
        _ => None,
    }
}

/// 手動代表 pin が特定の編集可能ページへ解決されたとき、そのページの永続
/// edit-preview key と検証方式を返す。
///
/// ZIP/PDF は parent request が page size を持たないため container identity で検証する。
/// Folder/ZipDir/ZipFirstImage は worker が後から代表を選ぶため、固定 page key を付けない。
fn pinned_edit_preview_target(
    kind: crate::folder_thumb_pins::ResolvedKind,
    request_path: &std::path::Path,
    zip_entry: Option<&str>,
    pdf_page: Option<u32>,
) -> (Option<String>, bool) {
    use crate::folder_thumb_pins::ResolvedKind;
    match kind {
        ResolvedKind::Image => (
            Some(crate::adjustment_db::normalize_path(request_path)),
            false,
        ),
        ResolvedKind::ZipEntry => (
            zip_entry.map(|entry| crate::adjustment_db::zip_entry_key(request_path, entry)),
            true,
        ),
        ResolvedKind::PdfFirstPage | ResolvedKind::PdfPage => (
            pdf_page.map(|page| {
                crate::adjustment_db::zip_entry_key(request_path, &format!("page_{page}"))
            }),
            true,
        ),
        ResolvedKind::Video
        | ResolvedKind::Folder
        | ResolvedKind::ZipFirstImage
        | ResolvedKind::ZipDirRepresentative => (None, false),
    }
}

#[allow(clippy::too_many_arguments)]
fn make_load_request(
    item: &GridItem,
    idx: usize,
    mtime: i64,
    file_size: i64,
    skip_cache: bool,
    pdf_password: Option<&str>,
    folder_thumb_sort: Option<crate::settings::SortOrder>,
    folder_thumb_depth: u32,
    pin_map: &std::collections::HashMap<String, crate::folder_thumb_pins::FolderPinSource>,
    converted_archive_cache_paths: &std::collections::HashMap<String, PathBuf>,
    archive_source_override: Option<&std::path::Path>,
    current_folder: Option<&std::path::Path>,
    pin_db: Option<&crate::folder_thumb_pins::FolderThumbPinDb>,
    video_pin_db: Option<&crate::video_pins::VideoPinDb>,
    // T54 (Codex R-SEARCH-001 / 2026-05-16): Ctrl+S 結果のように「複数フォルダの
    // 同名コンテナが同一リストに混在しうる」コンテキストでは、basename だけの
    // cache key (`folderthumb:cover` / `zipthumb:cover.zip` 等) が衝突して別フォルダの
    // サムネを誤表示する。`true` を渡すと full path を含むキーを使う。
    // 通常閲覧 (= 同一親フォルダ内なので basename ユニーク) は `false` で OK。
    use_full_path_keys: bool,
) -> Option<LoadRequest> {
    // 共通フィールド (idx/path/mtime/file_size/skip_cache) 以外は Default (0/None/false)
    // を基底にして差分だけ上書きする。入力 seq / items_gen は後段のエンキューで上書きされる。
    let base = LoadRequest {
        idx,
        mtime,
        file_size,
        skip_cache,
        ..Default::default()
    };
    match item {
        GridItem::Image(p) => {
            // 検索結果ビューでは複数フォルダの同名画像が混在しうるので、basename では
            // なく full-path ベースの cache key を使う (Codex P1)。
            let cache_key_override = use_full_path_keys.then(|| image_full_path_cache_key(p));
            Some(LoadRequest {
                path: p.clone(),
                cache_key_override,
                ..base
            })
        }
        GridItem::Stack { representative, .. } => {
            // ファイル名スタックの集約セル: 代表画像 (実ファイル) のサムネをそのまま要求する。
            // 専用 cache key は不要 — その実ファイルの通常 per-file サムネを再利用するので、
            // スタックモード ON/OFF を跨いでキャッシュが命中する。
            let cache_key_override =
                use_full_path_keys.then(|| image_full_path_cache_key(representative));
            Some(LoadRequest {
                path: representative.clone(),
                cache_key_override,
                ..base
            })
        }
        GridItem::ZipImage {
            zip_path,
            entry_name,
        } => Some(LoadRequest {
            path: zip_path.clone(),
            zip_entry: Some(entry_name.clone()),
            ..base
        }),
        GridItem::ZipDir {
            zip_path,
            dir_prefix,
            representative,
            ..
        } => {
            // ネスト ZIP ツリーの子コンテナ代表サムネ (v1.3.0)。代表画像のバイトを
            // zip_entry 経由で読み、カタログには zipdir:{dir_prefix} キーで保存する
            // (entry_name キーと非衝突, additive)。cache_key_override が zipdir: で
            // folder/zip thumb prefix と一致しないため、ワーカーはコンテナ列挙ではなく
            // 「zip_entry を直接読む」経路に乗る。
            //
            // 本ごとの代表サムネピン (zip_path + dir_prefix キー) があれば、それを代表にする。
            // ZipDir source は通常フォルダの子フォルダ pin と同じく cascade 解決する。
            let archive_key = crate::path_key::normalize_keep_drive(zip_path);
            let load_zip_path = converted_archive_cache_paths
                .get(&archive_key)
                .unwrap_or(zip_path);
            let book_root = zip_pin_root_path(zip_path, archive_source_override, current_folder);
            let book_container = book_container_key(book_root, dir_prefix);
            let book_key = crate::path_key::normalize_keep_drive(&book_container);
            if let Some(source) = pin_map.get(&book_key) {
                match source {
                    crate::folder_thumb_pins::FolderPinSource::ZipEntry { zip_rel, entry }
                        if zip_rel.is_empty() && !entry.is_empty() =>
                    {
                        return Some(LoadRequest {
                            path: load_zip_path.clone(),
                            zip_entry: Some(entry.clone()),
                            edit_preview_key: Some(crate::adjustment_db::zip_entry_key(
                                load_zip_path,
                                entry,
                            )),
                            edit_preview_validate_container: true,
                            pinned_page_adjustment_key: Some(crate::adjustment_db::zip_entry_key(
                                load_zip_path,
                                entry,
                            )),
                            cache_key_override: Some(format!(
                                "{}{}{}",
                                crate::grid_item::zipdir_cache_key(dir_prefix),
                                crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                                entry
                            )),
                            ..base
                        });
                    }
                    crate::folder_thumb_pins::FolderPinSource::ZipDir { zip_rel, .. }
                        if zip_rel.is_empty() =>
                    {
                        if let Some(resolved) = resolve_pin_target_cascaded(
                            &book_container,
                            source,
                            pin_db,
                            folder_thumb_depth as usize,
                        ) {
                            let cache_key = format!(
                                "{}{}{}",
                                crate::grid_item::zipdir_cache_key(dir_prefix),
                                crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                                resolved.source_id,
                            );
                            match resolved.kind {
                                crate::folder_thumb_pins::ResolvedKind::ZipEntry => {
                                    let (edit_preview_key, edit_preview_validate_container) =
                                        pinned_edit_preview_target(
                                            resolved.kind,
                                            load_zip_path,
                                            resolved.zip_entry.as_deref(),
                                            resolved.pdf_page,
                                        );
                                    return Some(LoadRequest {
                                        path: load_zip_path.clone(),
                                        zip_entry: resolved.zip_entry,
                                        pinned_page_adjustment_key: edit_preview_key.clone(),
                                        edit_preview_key,
                                        edit_preview_validate_container,
                                        cache_key_override: Some(cache_key),
                                        mtime: resolved.mtime,
                                        file_size: resolved.file_size,
                                        ..base
                                    });
                                }
                                crate::folder_thumb_pins::ResolvedKind::ZipDirRepresentative => {
                                    return Some(LoadRequest {
                                        path: load_zip_path.clone(),
                                        zip_dir_prefix: resolved.zip_dir_prefix,
                                        cache_key_override: Some(cache_key),
                                        resolve_override: Some(
                                            crate::thumb_loader::ResolveStrategy::ZipDirRepresentative,
                                        ),
                                        folder_thumb_sort,
                                        folder_thumb_depth,
                                        mtime: resolved.mtime,
                                        file_size: resolved.file_size,
                                        ..base
                                    });
                                }
                                _ => {}
                            }
                        }
                    }
                    _ => {}
                }
            }
            let entry = representative.clone()?;
            Some(LoadRequest {
                path: load_zip_path.clone(),
                zip_entry: Some(entry),
                cache_key_override: Some(crate::grid_item::zipdir_cache_key(dir_prefix)),
                ..base
            })
        }
        GridItem::PdfPage {
            pdf_path, page_num, ..
        } => Some(LoadRequest {
            path: pdf_path.clone(),
            pdf_page: Some(*page_num),
            pdf_password: pdf_password.map(String::from),
            ..base
        }),
        GridItem::ConvertibleArchive { path, format } => {
            let archive_key = crate::path_key::normalize_keep_drive(path);
            let cached_zip = converted_archive_cache_paths.get(&archive_key)?;
            let base_key = convertible_archive_cache_base_key(path, *format, use_full_path_keys)?;
            if let Some(
                source @ crate::folder_thumb_pins::FolderPinSource::ZipEntry { zip_rel, entry },
            ) = pin_map.get(&archive_key)
                && zip_rel.is_empty()
                && !entry.is_empty()
            {
                return Some(LoadRequest {
                    path: cached_zip.clone(),
                    zip_entry: Some(entry.clone()),
                    edit_preview_key: Some(crate::adjustment_db::zip_entry_key(cached_zip, entry)),
                    edit_preview_validate_container: true,
                    pinned_page_adjustment_key: Some(crate::adjustment_db::zip_entry_key(
                        cached_zip, entry,
                    )),
                    cache_key_override: Some(convertible_archive_pinned_cache_key(
                        &base_key, source, mtime, file_size,
                    )),
                    ..base
                });
            }
            if let Some(source @ crate::folder_thumb_pins::FolderPinSource::ZipDir { zip_rel, .. }) =
                pin_map.get(&archive_key)
                && zip_rel.is_empty()
                && let Some(resolved) =
                    resolve_pin_target_cascaded(path, source, pin_db, folder_thumb_depth as usize)
            {
                let cache_key = format!(
                    "{}{}{}",
                    base_key,
                    crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                    resolved.source_id,
                );
                match resolved.kind {
                    crate::folder_thumb_pins::ResolvedKind::ZipEntry => {
                        let (edit_preview_key, edit_preview_validate_container) =
                            pinned_edit_preview_target(
                                resolved.kind,
                                cached_zip,
                                resolved.zip_entry.as_deref(),
                                resolved.pdf_page,
                            );
                        return Some(LoadRequest {
                            path: cached_zip.clone(),
                            zip_entry: resolved.zip_entry,
                            pinned_page_adjustment_key: edit_preview_key.clone(),
                            edit_preview_key,
                            edit_preview_validate_container,
                            cache_key_override: Some(cache_key),
                            mtime: resolved.mtime,
                            file_size: resolved.file_size,
                            ..base
                        });
                    }
                    crate::folder_thumb_pins::ResolvedKind::ZipDirRepresentative => {
                        return Some(LoadRequest {
                            path: cached_zip.clone(),
                            zip_dir_prefix: resolved.zip_dir_prefix,
                            cache_key_override: Some(cache_key),
                            resolve_override: Some(
                                crate::thumb_loader::ResolveStrategy::ZipDirRepresentative,
                            ),
                            folder_thumb_sort,
                            folder_thumb_depth,
                            mtime: resolved.mtime,
                            file_size: resolved.file_size,
                            ..base
                        });
                    }
                    _ => {}
                }
            }
            Some(LoadRequest {
                path: cached_zip.clone(),
                cache_key_override: Some(base_key),
                resolve_override: Some(crate::thumb_loader::ResolveStrategy::ZipFirstImage),
                ..base
            })
        }
        GridItem::ZipFile(p) => {
            // zip_entry は None のままにしておき、ワーカー側でキャッシュミス時に
            // 遅延解決する (UI スレッドで ZIP を開く I/O を避けるため)。
            // T54: container_cache_base_key で full_path / basename を統一管理
            let base_key = container_cache_base_key(
                item,
                use_full_path_keys,
                folder_thumb_sort,
                folder_thumb_depth,
            )?;
            let req = LoadRequest {
                path: p.clone(),
                cache_key_override: Some(base_key.clone()),
                folder_thumb_sort,
                folder_thumb_depth,
                ..base
            };
            Some(apply_folder_thumb_pin(
                req,
                p,
                &base_key,
                ContainerKindForPin::ZipFile,
                pin_map,
                pin_db,
                video_pin_db,
                pdf_password,
            ))
        }
        GridItem::PdfFile(p) => {
            let base_key = container_cache_base_key(
                item,
                use_full_path_keys,
                folder_thumb_sort,
                folder_thumb_depth,
            )?;
            let req = LoadRequest {
                path: p.clone(),
                pdf_page: Some(0),
                pdf_password: pdf_password.map(String::from),
                cache_key_override: Some(base_key.clone()),
                folder_thumb_sort,
                folder_thumb_depth,
                ..base
            };
            Some(apply_folder_thumb_pin(
                req,
                p,
                &base_key,
                ContainerKindForPin::PdfFile,
                pin_map,
                pin_db,
                video_pin_db,
                pdf_password,
            ))
        }
        GridItem::Folder(p) => {
            let base_key = container_cache_base_key(
                item,
                use_full_path_keys,
                folder_thumb_sort,
                folder_thumb_depth,
            )?;
            let req = LoadRequest {
                path: p.clone(),
                cache_key_override: Some(base_key.clone()),
                folder_thumb_sort,
                folder_thumb_depth,
                ..base
            };
            Some(apply_folder_thumb_pin(
                req,
                p,
                &base_key,
                ContainerKindForPin::Folder,
                pin_map,
                pin_db,
                video_pin_db,
                pdf_password,
            ))
        }
        GridItem::SearchContainer {
            representative: Some(rep),
            ..
        } => {
            // 代表サムネのキャッシュキー (Codex P1 対応):
            // - filename 単体を使うと別コンテナの同名画像 (例: 複数フォルダの `cover.jpg`)
            //   で衝突し、placeholder mtime=0 の entry で先に書かれた thumb を読んでしまう。
            // - `{CACHE_KEY_SEARCH_REP}{full_path}[::{zip_entry|#page}]` をキーにしてユニーク化。
            //   通常閲覧のキャッシュ (filename 単体キー) とは別空間なので互いを壊さない。
            let path_str = rep.path.to_string_lossy();
            let key = match (&rep.zip_entry, rep.pdf_page) {
                (Some(entry), _) => format!("{}{}::{}", CACHE_KEY_SEARCH_REP, path_str, entry),
                (None, Some(page)) => {
                    format!("{}{}#p{}", CACHE_KEY_SEARCH_REP, path_str, page)
                }
                (None, None) => format!("{}{}", CACHE_KEY_SEARCH_REP, path_str),
            };
            Some(LoadRequest {
                path: rep.path.clone(),
                zip_entry: rep.zip_entry.clone(),
                pdf_page: rep.pdf_page,
                pdf_password: pdf_password.map(String::from),
                cache_key_override: Some(key),
                ..base
            })
        }
        _ => None,
    }
}

/// 1 つの GridItem に対応する catalog cache key を全部 (base + pinned) 返す。
///
/// `delete_missing` に渡す `existing_keys` の構築に使う。pinned 形式
/// (`{base}#pin:{source_id}`) を含めないと、`apply_folder_thumb_pin` が書いた
/// 行が毎回のフォルダロードで catalog から削除されて再生成が走り続ける
/// (Codex Phase B P2 指摘)。
fn folder_thumb_existing_keys_for(
    item: &GridItem,
    item_meta: Option<(i64, i64)>,
    pin_map: &std::collections::HashMap<String, crate::folder_thumb_pins::FolderPinSource>,
    pin_db: Option<&crate::folder_thumb_pins::FolderThumbPinDb>,
    folder_thumb_sort: Option<crate::settings::SortOrder>,
    folder_thumb_depth: u32,
    // T54 follow-on (Codex post-merge / 2026-05-16): make_load_request と同じく
    // 検索結果 / ドライブルートのコンテキストでは full-path 込みキーを使う。
    // `delete_missing` の存続キー集合と make_load_request の読み書きキーが乖離
    // しないように、必ず同じ helper (`container_cache_base_key`) を経由する。
    use_full_path_keys: bool,
) -> Vec<String> {
    let (container_path, convertible_format) = match item {
        GridItem::Image(p) => {
            // Image はそもそも pinned 経路に乗らないので 1 つだけ。
            return if use_full_path_keys {
                vec![image_full_path_cache_key(p)]
            } else {
                p.file_name()
                    .and_then(|n| n.to_str())
                    .map(|n| vec![n.to_string()])
                    .unwrap_or_default()
            };
        }
        GridItem::Folder(p) | GridItem::ZipFile(p) | GridItem::PdfFile(p) => (p, None),
        GridItem::ConvertibleArchive { path, format } => (path, Some(*format)),
        _ => return Vec::new(),
    };

    if let Some(format) = convertible_format {
        let Some(base_key) =
            convertible_archive_cache_base_key(container_path, format, use_full_path_keys)
        else {
            return Vec::new();
        };
        let mut keys = vec![base_key.clone()];
        let container_key = crate::path_key::normalize_keep_drive(container_path);
        if let (Some((mtime, file_size)), Some(source)) = (item_meta, pin_map.get(&container_key))
            && matches!(
                source,
                crate::folder_thumb_pins::FolderPinSource::ZipEntry { zip_rel, entry }
                    if zip_rel.is_empty() && !entry.is_empty()
            )
        {
            keys.push(convertible_archive_pinned_cache_key(
                &base_key, source, mtime, file_size,
            ));
        }
        if let Some(source @ crate::folder_thumb_pins::FolderPinSource::ZipDir { zip_rel, .. }) =
            pin_map.get(&container_key)
            && zip_rel.is_empty()
            && let Some(resolved) = resolve_pin_target_cascaded(
                container_path,
                source,
                pin_db,
                folder_thumb_depth as usize,
            )
        {
            keys.push(format!(
                "{}{}{}",
                base_key,
                crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                resolved.source_id,
            ));
        }
        return keys;
    }

    let Some(base_key) = container_cache_base_key(
        item,
        use_full_path_keys,
        folder_thumb_sort,
        folder_thumb_depth,
    ) else {
        return Vec::new();
    };

    let mut keys = vec![base_key.clone()];
    let container_key = crate::path_key::normalize_keep_drive(container_path);
    if let Some(source) = pin_map.get(&container_key) {
        // cascade 解決後の leaf source_id を使う (= `apply_folder_thumb_pin` が
        // 書く pinned_key と同じ)。cascade を考慮せず immediate のままだと、
        // delete_missing が cascade 由来の cache 行を毎回掃除してしまう。
        // folder_thumb_depth は呼び出し側 (load_folder) が `Settings.folder_thumb_depth`
        // を渡してくる。
        if let Some(resolved) =
            resolve_pin_target_cascaded(container_path, source, pin_db, folder_thumb_depth as usize)
        {
            keys.push(format!(
                "{}{}{}",
                base_key,
                crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
                resolved.source_id,
            ));
        }
    }
    keys
}

/// `apply_folder_thumb_pin` 用の container kind discriminator。
/// 互換性検査 (container と source の組合せが妥当か) に使う。
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ContainerKindForPin {
    Folder,
    ZipFile,
    PdfFile,
}

/// container と source の組合せが妥当か検査する。
///
/// 妥当な組合せ:
/// - **Folder**: 全 source 形を受け入れる (File/ZipEntry/ZipDir/PdfPage)。
///   - ただし ZipEntry / PdfPage は `*_rel` が **空でない** (= サブの ZIP/PDF を指す) ことを要求。
/// - **ZipFile**: `ZipEntry { zip_rel: "" }` / `ZipDir { zip_rel: "" }` (= container 自身の中身)
/// - **PdfFile**: `PdfPage { pdf_rel: "" }` のみ
fn pin_source_compatible_with_container(
    container: ContainerKindForPin,
    source: &crate::folder_thumb_pins::FolderPinSource,
) -> bool {
    use crate::folder_thumb_pins::FolderPinSource as S;
    match (container, source) {
        // Folder は何でも受け入れる (ただし内側参照 (`_rel==""`) は不可)
        (ContainerKindForPin::Folder, S::File { .. }) => true,
        (ContainerKindForPin::Folder, S::ZipEntry { zip_rel, .. }) => !zip_rel.is_empty(),
        (ContainerKindForPin::Folder, S::ZipDir { zip_rel, .. }) => !zip_rel.is_empty(),
        (ContainerKindForPin::Folder, S::PdfPage { pdf_rel, .. }) => !pdf_rel.is_empty(),
        // ZipFile は内側 ZipEntry / ZipDir のみ
        (ContainerKindForPin::ZipFile, S::ZipEntry { zip_rel, .. }) => zip_rel.is_empty(),
        (ContainerKindForPin::ZipFile, S::ZipDir { zip_rel, .. }) => zip_rel.is_empty(),
        (ContainerKindForPin::ZipFile, _) => false,
        // PdfFile は内側 PdfPage のみ
        (ContainerKindForPin::PdfFile, S::PdfPage { pdf_rel, .. }) => pdf_rel.is_empty(),
        (ContainerKindForPin::PdfFile, _) => false,
    }
}

/// cascade 解決: Folder / ZipFile / PdfFile / ZipDir の pin 連鎖を最終 leaf
/// (固定ページ等、または pin 無しコンテナ) まで辿って `ResolvedPinTarget` を返す。
///
/// 動機: A が B (Folder) を pin、B が C (Image) を pin している場合、ユーザーは A の
/// 親 grid で A のタイルが C を表示することを期待する。cascade なしだと A の pin は
/// B の auto-pick (= B 内最初の画像) になり、B 自身の pin (= C) を反映できない。
///
/// 動作:
/// - 1 段目: `pin_map` 由来の immediate_source を使う (UI スレッドで lookup 済み)
/// - 2 段目以降: `pin_db` で直接 DB lookup (cheap single-row)
/// - 終了条件: 非コンテナ kind に到達 / pin 無しコンテナに到達 / サイクル検出 /
///   `max_depth` 超過
/// - サイクル A↔B の場合は visited HashSet で 2 周目を検知して停止
///
/// `max_depth` は `Settings.folder_thumb_depth` (規定 3、範囲 0〜10) と揃える。
/// pin が無いときに `resolve_folder_thumb_image` がサブフォルダを何階層まで辿るかと
/// 同じ上限。0 のとき cascade は完全に無効化される (= 旧 Phase B 互換挙動)。
///
/// 返値: 最終 leaf の `ResolvedPinTarget`。
/// - 固定 leaf (Image / Video / ZipEntry / PdfPage):
///   そのまま target として使う
/// - pin 無しコンテナ leaf: Folder / ZIP / PDF / ZipDir ごとの strategy で auto-pick する
fn resolve_pin_target_cascaded(
    container: &std::path::Path,
    immediate_source: &crate::folder_thumb_pins::FolderPinSource,
    pin_db: Option<&crate::folder_thumb_pins::FolderThumbPinDb>,
    max_depth: usize,
) -> Option<crate::folder_thumb_pins::ResolvedPinTarget> {
    // closure 版に委譲。worker 側 (`resolve_folder_thumb_image`) でも同じヘルパーを
    // 異なる lookup closure で再利用する。
    let lookup = |p: &std::path::Path| -> Option<crate::folder_thumb_pins::FolderPinSource> {
        pin_db.and_then(|db| db.lookup(p))
    };
    crate::folder_thumb_pins::resolve_pin_target_cascaded_via(
        container,
        immediate_source,
        lookup,
        max_depth,
    )
}

/// 親コンテナ用 `LoadRequest` (Folder/ZipFile/PdfFile) に対し、手動ピンがあれば
/// target 種別のリクエストに書き換える。
///
/// 動作:
/// - `pin_map` から container のピン source を引く。無ければ `base_req` をそのまま返す。
/// - **Folder / ZipFile / PdfFile / ZipDir の cascade を最終 leaf まで追跡**
///   (`resolve_pin_target_cascaded`)。子コンテナがさらに pin を持っていれば、その固定ページを
///   再帰的に採用する。
/// - target 種別に応じて `path` / `zip_entry` / `pdf_page` / `resolve_override` を上書き。
/// - `cache_key_override` は `{base_key}#pin:{source_id}` にする。cascade 時の source_id は
///   経路 hash + leaf identity なので、途中または leaf が変わると古い WebP を catch しない。
/// - `mtime` / `file_size` を leaf 自身のものに差し替える (= catalog の hit 判定が leaf
///   metadata に対して行われる)。
///
/// Phase C 注意 (Video pin):
/// - Video pin (`ResolvedKind::Video`) は `seed_folder_video_pin_thumbs` が事前に
///   `video_pins` DB の WebP を `folderthumb:auto-v...#pin:{source_id}` で catalog + cache_map
///   にミラーしているので、worker は通常の cache_hit 経路で動画フレームを取り出せる。
///   ここで返す LoadRequest は `path = container` (folder) + `cache_key_override =
///   pinned_key` + `mtime/file_size = 動画のもの` (= seed と整合)。
fn apply_folder_thumb_pin(
    base_req: LoadRequest,
    container: &std::path::Path,
    base_key: &str,
    container_kind: ContainerKindForPin,
    pin_map: &std::collections::HashMap<String, crate::folder_thumb_pins::FolderPinSource>,
    pin_db: Option<&crate::folder_thumb_pins::FolderThumbPinDb>,
    // cascade resolve が Video kind に到達したとき、`video_pins.db` に有効な WebP が
    // あるか確認するために渡す。WebP が無い (= フルスクリーン pin 削除済み / 旧版の
    // dead pin) 場合は pinned_key の LoadRequest を作らず `base_req` に戻す
    // (Codex post-merge P2: dead video pin が pinned_key 下に auto-pick を再生成し
    //  続ける churn を防ぐ)。
    video_pin_db: Option<&crate::video_pins::VideoPinDb>,
    pdf_password: Option<&str>,
) -> LoadRequest {
    let container_key = crate::path_key::normalize_keep_drive(container);
    let Some(source) = pin_map.get(&container_key) else {
        return base_req;
    };
    // container / source の不整合を弾く (Codex Phase B P2 指摘)。
    // UI 経由では発生しないが、DB 行汚染 / 将来のスキーマ変更で起き得る。
    if !pin_source_compatible_with_container(container_kind, source) {
        crate::logger::log(format!(
            "folder_thumb_pin: incompatible source for container {} (kind={:?}, source={:?}) — falling back",
            container.display(),
            container_kind,
            source,
        ));
        return base_req;
    }
    // cascade 解決: Folder / ZipFile / PdfFile / ZipDir の pin 連鎖を leaf まで辿る。
    // max_depth は base_req の folder_thumb_depth (= Settings.folder_thumb_depth) に揃える。
    // pin 無し時の `resolve_folder_thumb_image` のサブフォルダ探索上限と同じ仕様にする。
    let Some(resolved) = resolve_pin_target_cascaded(
        container,
        source,
        pin_db,
        base_req.folder_thumb_depth as usize,
    ) else {
        crate::logger::log(format!(
            "folder_thumb_pin: target unresolved for {} (source={:?}) — falling back to auto-select",
            container.display(),
            source,
        ));
        return base_req;
    };

    use crate::folder_thumb_pins::ResolvedKind;
    use crate::thumb_loader::ResolveStrategy;

    let pinned_key = format!(
        "{}{}{}",
        base_key,
        crate::thumb_loader::CACHE_KEY_PIN_SUFFIX,
        resolved.source_id,
    );
    // ネスト時の解決経路を確認するための診断ログ。Folder/ZipFile/PdfFile pin の挙動を
    // 切り分けやすくする。`mimageviewer.log` の grep `folder_thumb_pin: apply` で
    // すべての pin 適用箇所を一覧できる。
    crate::logger::log(format!(
        "folder_thumb_pin: apply container={} kind={:?} -> resolved={} \
         (kind={:?} mtime={} size={}) pinned_key=`{}`",
        container.display(),
        container_kind,
        resolved.abs_path.display(),
        resolved.kind,
        resolved.mtime,
        resolved.file_size,
        pinned_key,
    ));

    // Video pin は seed_folder_video_pin_thumbs が `pinned_key` で video_pins WebP を
    // catalog + cache_map に書き込んでいる前提。worker はそのまま cache_hit で
    // 動画フレームを取り出す。
    if matches!(resolved.kind, ResolvedKind::Video) {
        // **dead video pin の churn 防止 (Codex post-merge P2)**:
        // `video_pins.db` に有効な WebP が無い video source は、pinned_key の
        // LoadRequest を作らず `base_req` に戻す。pinned_key を作ってしまうと、
        // seed は WebP 無しで seed を skip → worker は cache miss → is_folder_thumb
        // 経路で folder auto-pick を pinned_key 下に保存 → 次回 seed が purge という
        // churn が毎ロード走る。base_req に戻せば worker は base_key を使い、
        // auto-pick は base_key 下に普通に保存され churn しない。
        // WebP は通常 set 時に `try_set_folder_thumb_pin_with_video_guard` が存在を
        // 保証するが、フルスクリーンで pin 削除 / 旧版の dead pin で欠落し得る。
        let has_webp = video_pin_db
            .and_then(|db| db.lookup(&resolved.abs_path))
            .map(|pin| !pin.thumb_webp.is_empty())
            .unwrap_or(false);
        if !has_webp {
            crate::logger::log(format!(
                "folder_thumb_pin: video pin has no WebP ({}) — falling back to base_req",
                resolved.abs_path.display()
            ));
            return base_req;
        }
        // ZipFile / PdfFile 親コンテナの場合は Video pin は組合せ不可
        // (`pin_source_compatible_with_container` で弾く) ので、ここに来る container
        // は必ず Folder 種別。`path = container` のままで worker の prefix 判定が
        // CACHE_KEY_FOLDER → is_folder_thumb=true となり、cache miss 時に
        // resolve_folder_thumb_image(folder, sort, depth) が走る。
        //
        // `skip_cache` は **常に false** (Codex Phase C P1 指摘)。video_pin の WebP は
        // grid 表示用に既に確定済みで、idle quality-upgrade の「元画像から再 decode」が
        // 意味を持たない。base_req.skip_cache=true (アップグレード再エンキュー) を継承
        // すると cache_hit を踏み越えて is_folder_thumb 経路で folder の auto-pick を
        // pinned_key 下に書き戻してしまい、video frame が消える。
        return LoadRequest {
            path: container.to_path_buf(),
            relative_page_provenance: None,
            zip_entry: None,
            zip_dir_prefix: None,
            pdf_page: None,
            pdf_password: pdf_password.map(String::from),
            cache_key_override: Some(pinned_key),
            // mtime/size は target 動画のもの。seed_folder_video_pin_thumbs が同じ
            // 値で catalog 行を書いているので、worker の cache_hit 比較が成立する。
            mtime: resolved.mtime,
            file_size: resolved.file_size,
            edit_preview_key: None,
            edit_preview_validate_container: false,
            pinned_page_adjustment_key: None,
            resolve_override: None,
            folder_thumb_sort: base_req.folder_thumb_sort,
            folder_thumb_depth: base_req.folder_thumb_depth,
            idx: base_req.idx,
            skip_cache: false,
            priority: base_req.priority,
            input_seq: base_req.input_seq,
            items_gen: base_req.items_gen,
            context_epoch: base_req.context_epoch,
            pinned_only: None,
            force_cache: false,
        };
    }

    let (edit_preview_key, edit_preview_validate_container) = pinned_edit_preview_target(
        resolved.kind,
        &resolved.abs_path,
        resolved.zip_entry.as_deref(),
        resolved.pdf_page,
    );
    let pinned_page_adjustment_key = edit_preview_key.clone();

    // dispatch field を target 種別ごとに組み立てる。
    let (resolve_override, zip_entry, zip_dir_prefix, pdf_page) = match resolved.kind {
        ResolvedKind::Image => (Some(ResolveStrategy::DirectImage), None, None, None),
        ResolvedKind::Folder => (
            Some(ResolveStrategy::FolderRepresentative),
            None,
            None,
            None,
        ),
        ResolvedKind::ZipFirstImage => (Some(ResolveStrategy::ZipFirstImage), None, None, None),
        ResolvedKind::ZipDirRepresentative => (
            Some(ResolveStrategy::ZipDirRepresentative),
            None,
            resolved.zip_dir_prefix.clone(),
            None,
        ),
        ResolvedKind::PdfFirstPage => (None, None, None, Some(0u32)),
        ResolvedKind::ZipEntry => (None, resolved.zip_entry.clone(), None, None),
        ResolvedKind::PdfPage => (None, None, None, resolved.pdf_page),
        // Video は上で early-return 済み
        ResolvedKind::Video => unreachable!("Video pin handled above"),
    };

    LoadRequest {
        path: resolved.abs_path,
        relative_page_provenance: None,
        zip_entry,
        zip_dir_prefix,
        pdf_page,
        pdf_password: pdf_password.map(String::from),
        cache_key_override: Some(pinned_key),
        mtime: resolved.mtime,
        file_size: resolved.file_size,
        edit_preview_key,
        edit_preview_validate_container,
        pinned_page_adjustment_key,
        resolve_override,
        // フォルダ自動選定パラメータ (sort/depth) は Folder strategy のときだけ意味がある。
        // base_req から継承するので Folder → Folder の pin で sort/depth が消えない。
        folder_thumb_sort: base_req.folder_thumb_sort,
        folder_thumb_depth: base_req.folder_thumb_depth,
        idx: base_req.idx,
        skip_cache: base_req.skip_cache,
        priority: base_req.priority,
        input_seq: base_req.input_seq,
        items_gen: base_req.items_gen,
        context_epoch: base_req.context_epoch,
        pinned_only: None,
        force_cache: false,
    }
}

/// DynamicImage を egui::ColorImage に変換する (リサイズなし)。
/// フルスクリーン表示や PDF 再レンダリング結果の変換で使用。
/// 360 度パノラマビュー Phase 2a (Codex P1 第 2、2026-05): viewport から settle
/// 出力サイズを計算する。長辺 1920 で cap し、aspect は viewport を維持。
/// 1920×1080 で ~2 MP (50-100 ms CPU レンダ)、GPU 側で 4K viewport に線形拡大される。
pub(crate) fn compute_pano_settle_output_size(viewport: (u32, u32)) -> (u32, u32) {
    let (vw, vh) = (viewport.0.max(1), viewport.1.max(1));
    const CAP: u32 = 1920;
    if vw <= CAP && vh <= CAP {
        return (vw, vh);
    }
    if vw >= vh {
        let new_w = CAP;
        let new_h = ((new_w as f32) * (vh as f32) / (vw as f32))
            .round()
            .clamp(1.0, CAP as f32) as u32;
        (new_w, new_h)
    } else {
        let new_h = CAP;
        let new_w = ((new_h as f32) * (vw as f32) / (vh as f32))
            .round()
            .clamp(1.0, CAP as f32) as u32;
        (new_w, new_h)
    }
}

pub(crate) fn dynamic_image_to_color_image(img: &image::DynamicImage) -> egui::ColorImage {
    let rgba = img.to_rgba8();
    let size = [rgba.width() as usize, rgba.height() as usize];
    egui::ColorImage::from_rgba_unmultiplied(size, rgba.as_raw())
}

/// wgpu テクスチャの最大次元。wgpu デフォルト制限は 8192px。
/// GPU 実機はもっと大きいが (RTX 4090 = 16384)、eframe が
/// デフォルト Limits で初期化するため 8192 を超えるとパニックする。
pub(crate) const MAX_TEXTURE_DIM: usize = 8192;

/// GPU テクスチャ上限を超える `ColorImage` を縮小して返す。
/// 上限内であればクローンせず共有参照をそのまま `Cow::Borrowed` で返す。
///
/// UI スレッドからの呼び出し時に上限超過を検知するとここで
/// `resize_exact(Triangle)` が走り、7K-9K クラスの画像で 5 秒単位の同期ハングになる。
/// フルスクリーン静止画の主経路 (start_fs_load) は worker 側で先に
/// `clamp_dynamic_for_gpu` を掛けているので、ここは通常 `Cow::Borrowed` のみを
/// 辿る前提になっている。異常経路の安全網として残してある。
pub(crate) fn clamp_for_gpu(ci: &egui::ColorImage) -> std::borrow::Cow<'_, egui::ColorImage> {
    let [w, h] = ci.size;
    if w <= MAX_TEXTURE_DIM && h <= MAX_TEXTURE_DIM {
        return std::borrow::Cow::Borrowed(ci);
    }
    // 長辺を MAX_TEXTURE_DIM に収めるスケール
    let scale = MAX_TEXTURE_DIM as f64 / w.max(h) as f64;
    let new_w = ((w as f64 * scale).round() as u32).max(1);
    let new_h = ((h as f64 * scale).round() as u32).max(1);
    let t0 = std::time::Instant::now();
    let dynimg = color_image_to_dynamic(ci);
    let resized = dynimg.resize_exact(new_w, new_h, image::imageops::FilterType::Triangle);
    crate::logger::log(format!(
        "  clamp_for_gpu (UI-thread fallback): {w}x{h} → {new_w}x{new_h} (limit {MAX_TEXTURE_DIM}) in {:.0}ms",
        t0.elapsed().as_secs_f64() * 1000.0
    ));
    std::borrow::Cow::Owned(dynamic_image_to_color_image(&resized))
}

/// worker スレッド向け: GPU 上限を超える `ColorImage` を SIMD リサイズで縮小する。
///
/// final AI (4x アップスケール) の出力が `MAX_TEXTURE_DIM` を超えるケース
/// (例: サイズ上限 4096 x 2048 で 2720x1920 を 4x → 10880x7680) で使う。
/// UI スレッドの `clamp_for_gpu` まで遅らせると秒単位の同期ハングになるため、
/// `run_final_ai_job` (AI worker) 内で final_ai_cache へ格納する前に縮小する。
/// 上限内なら入力をそのまま返す (クローンなし)。
///
/// `Color32` は premultiplied RGBA8 なのでバイト列をそのまま U8x4 として
/// リサイズし、premultiplied のまま `ColorImage` に戻す (unmultiply 往復による
/// 精度損失と余分な変換コストを避ける)。
pub(crate) fn clamp_color_image_for_gpu(ci: egui::ColorImage) -> egui::ColorImage {
    let [w, h] = ci.size;
    if w <= MAX_TEXTURE_DIM && h <= MAX_TEXTURE_DIM {
        return ci;
    }
    let scale = MAX_TEXTURE_DIM as f64 / w.max(h) as f64;
    let new_w = ((w as f64 * scale).round() as u32).max(1);
    let new_h = ((h as f64 * scale).round() as u32).max(1);
    let t0 = std::time::Instant::now();
    let src = image::RgbaImage::from_raw(w as u32, h as u32, ci.as_raw().to_vec())
        .expect("ColorImage raw buffer matches dimensions");
    let resized = crate::fast_resize::resize_rgba8_exact(
        &src,
        new_w,
        new_h,
        crate::fast_resize::Quality::Bilinear,
    );
    crate::logger::log(format!(
        "  clamp_color_image_for_gpu: {w}x{h} → {new_w}x{new_h} (limit {MAX_TEXTURE_DIM}) in {:.0}ms",
        t0.elapsed().as_secs_f64() * 1000.0
    ));
    egui::ColorImage::from_rgba_premultiplied([new_w as usize, new_h as usize], resized.as_raw())
}

/// worker スレッド向け: GPU 上限を超える `DynamicImage` を Bilinear リサイズで縮小する。
/// `fast_image_resize` (AVX2/SSE4.1 SIMD) 実装を使うので、image crate の
/// スカラー `resize_exact(Triangle)` に比べて 7K-9K クラスで 5-10 倍速い。
/// 上限内なら入力をそのまま返す (クローンなし)。
pub(crate) fn clamp_dynamic_for_gpu(img: image::DynamicImage) -> image::DynamicImage {
    let (w, h) = (img.width() as usize, img.height() as usize);
    if w <= MAX_TEXTURE_DIM && h <= MAX_TEXTURE_DIM {
        return img;
    }
    let scale = MAX_TEXTURE_DIM as f64 / w.max(h) as f64;
    let new_w = ((w as f64 * scale).round() as u32).max(1);
    let new_h = ((h as f64 * scale).round() as u32).max(1);
    let t0 = std::time::Instant::now();
    let resized = crate::fast_resize::resize_dynamic_exact(
        &img,
        new_w,
        new_h,
        crate::fast_resize::Quality::Bilinear,
    );
    crate::logger::log(format!(
        "  clamp_dynamic_for_gpu: {w}x{h} → {new_w}x{new_h} (limit {MAX_TEXTURE_DIM}) in {:.0}ms",
        t0.elapsed().as_secs_f64() * 1000.0
    ));
    resized
}

/// 回転した画像を Mesh で描画する。
/// `free_rotation_rad` が非ゼロの場合、`center` 基準で頂点を任意角度回転する。
pub(crate) fn draw_rotated_image_ex(
    painter: &egui::Painter,
    texture_id: egui::TextureId,
    rect: egui::Rect,
    rotation: crate::rotation_db::Rotation,
    free_rotation_rad: f32,
    center: egui::Pos2,
) {
    // UV 座標を回転に合わせて変換
    // 頂点順: 左上, 右上, 右下, 左下 (画面座標)
    let uvs = match rotation {
        crate::rotation_db::Rotation::None => [
            egui::pos2(0.0, 0.0),
            egui::pos2(1.0, 0.0),
            egui::pos2(1.0, 1.0),
            egui::pos2(0.0, 1.0),
        ],
        crate::rotation_db::Rotation::Cw90 => [
            egui::pos2(0.0, 1.0),
            egui::pos2(0.0, 0.0),
            egui::pos2(1.0, 0.0),
            egui::pos2(1.0, 1.0),
        ],
        crate::rotation_db::Rotation::Cw180 => [
            egui::pos2(1.0, 1.0),
            egui::pos2(0.0, 1.0),
            egui::pos2(0.0, 0.0),
            egui::pos2(1.0, 0.0),
        ],
        crate::rotation_db::Rotation::Cw270 => [
            egui::pos2(1.0, 0.0),
            egui::pos2(1.0, 1.0),
            egui::pos2(0.0, 1.0),
            egui::pos2(0.0, 0.0),
        ],
    };

    let mut positions = [
        rect.left_top(),
        rect.right_top(),
        rect.right_bottom(),
        rect.left_bottom(),
    ];

    // 任意角度回転: 頂点を center 基準で回転
    if free_rotation_rad.abs() > 0.001 {
        let cos_r = free_rotation_rad.cos();
        let sin_r = free_rotation_rad.sin();
        for p in &mut positions {
            let dx = p.x - center.x;
            let dy = p.y - center.y;
            p.x = center.x + dx * cos_r - dy * sin_r;
            p.y = center.y + dx * sin_r + dy * cos_r;
        }
    }

    let mut mesh = egui::Mesh::with_texture(texture_id);
    for i in 0..4 {
        mesh.vertices.push(egui::epaint::Vertex {
            pos: positions[i],
            uv: uvs[i],
            color: egui::Color32::WHITE,
        });
    }
    mesh.indices.extend_from_slice(&[0, 1, 2, 0, 2, 3]);
    painter.add(egui::Shape::mesh(mesh));
}

/// 回転した画像を Mesh で描画する（90° 単位のみ）。
pub(crate) fn draw_rotated_image(
    painter: &egui::Painter,
    texture_id: egui::TextureId,
    rect: egui::Rect,
    rotation: crate::rotation_db::Rotation,
) {
    draw_rotated_image_ex(painter, texture_id, rect, rotation, 0.0, rect.center());
}

/// resume 対象とみなす最小 position (秒)。これ未満は「最初から」扱い。
pub(crate) const VIDEO_RESUME_MIN_POSITION_SECS: f64 = 3.0;
/// 動画末端からこの秒数以下に位置していたら完走扱いで削除する。
pub(crate) const VIDEO_RESUME_END_GUARD_SECS: f64 = 5.0;

/// 動画再生位置を `Settings::video_resume_positions` に保存する。
/// - engine state が EOF → duration に関係なくエントリ削除
/// - position が `VIDEO_RESUME_MIN_POSITION_SECS` 未満 → エントリ削除 (最初から)
/// - 残り `VIDEO_RESUME_END_GUARD_SECS` 以下 → エントリ削除 (完走済み)
/// - それ以外 → position を保存
fn save_video_resume_position(
    map: &mut std::collections::HashMap<String, f64>,
    key: String,
    position: f64,
    duration: f64,
    at_eof: bool,
) -> bool {
    if at_eof {
        map.remove(&key);
        return false;
    }
    if position < VIDEO_RESUME_MIN_POSITION_SECS {
        map.remove(&key);
        return false;
    }
    if duration > 0.0 && position >= duration - VIDEO_RESUME_END_GUARD_SECS {
        map.remove(&key);
        return false;
    }
    map.insert(key, position);
    true
}

/// AI worker スレッド上で 1 ジョブ (denoise / upscale) を実行する。
///
/// **モデルのロード (= `AiRuntime` の sessions Mutex を握る重い処理) はここで初めて
/// 行う**。UI スレッドは種別決定 (`model_path` 存在チェック) までしかやらないので、
/// 推論 backlog がロックを握っていても UI が固まらない。
fn run_final_ai_job(job: &AiJob) -> FinalAiResult {
    let job_id = job.job_id;
    let key = job.key;
    let runtime = &job.runtime;
    let manager = &job.manager;
    let cancel = &job.cancel;
    let source_size = job.source.size;
    let retained_key = job.retained_key.clone();
    let retained_epoch = job.retained_epoch;

    // モデルロードは worker 上で。ロードに失敗したモデルは「使えない」扱いに落とす
    // (UI スレッドで load していた旧設計と最終状態は同じ: 両方不可なら Failed)。
    let denoise_model = match job.denoise_kind {
        Some(kind) => match ensure_model_loaded(runtime, manager, kind) {
            Ok(()) => Some(kind),
            Err(err) => {
                crate::logger::log(format!("[AI] Final denoise model load failed: {err}"));
                None
            }
        },
        None => None,
    };
    let upscale_model = match job.upscale_kind {
        Some(kind) => match ensure_model_loaded(runtime, manager, kind) {
            Ok(()) => Some(kind),
            Err(err) => {
                crate::logger::log(format!("[AI] Final upscale model load failed: {err}"));
                None
            }
        },
        None => None,
    };
    if denoise_model.is_none() && upscale_model.is_none() {
        return FinalAiResult::Failed {
            job_id,
            key,
            error: "no usable AI model (load failed)".to_string(),
        };
    }
    if cancel.load(Ordering::Relaxed) {
        return FinalAiResult::Cancelled { job_id, key };
    }
    let source = if let Some(params) = job.adjust_before_ai.as_ref() {
        Arc::new(crate::adjustment::apply_adjustments_fast(
            &job.source,
            params,
        ))
    } else {
        Arc::clone(&job.source)
    };
    if cancel.load(Ordering::Relaxed) {
        return FinalAiResult::Cancelled { job_id, key };
    }

    let bg_rgb: [u8; 3] = if key.bg == 1 {
        [255, 255, 255]
    } else {
        [0, 0, 0]
    };
    let composite_first = upscale_model.is_some();
    let mut dynimg = if composite_first {
        color_image_to_dynamic_composited(&source, bg_rgb)
    } else {
        color_image_to_dynamic(&source)
    };

    if let Some(denoise_kind) = denoise_model {
        match crate::ai::denoise::denoise(runtime, denoise_kind, &dynimg, cancel) {
            Ok(denoised) => {
                if upscale_model.is_some() {
                    dynimg = color_image_to_dynamic(&denoised);
                } else {
                    return FinalAiResult::Ready {
                        job_id,
                        key,
                        retained_key,
                        retained_epoch,
                        source_size,
                        image: denoised,
                        used_upscale: false,
                    };
                }
            }
            Err(err) => {
                if cancel.load(Ordering::Relaxed) {
                    return FinalAiResult::Cancelled { job_id, key };
                }
                if upscale_model.is_none() {
                    return FinalAiResult::Failed {
                        job_id,
                        key,
                        error: err.to_string(),
                    };
                }
                crate::logger::log(format!(
                    "[AI] Final denoise failed for idx={}: {err}",
                    key.edit_key.idx
                ));
            }
        }
    }

    if let Some(upscale_kind) = upscale_model {
        match crate::ai::upscale::upscale_to_max_dim(
            runtime,
            upscale_kind,
            &dynimg,
            cancel,
            MAX_TEXTURE_DIM as u32,
        ) {
            // 4x 全面が GPU テクスチャ上限を超える場合でも、upscaler 側で最終
            // ターゲットサイズへ直接合成する。clamp は安全網として残す。
            Ok(result) => FinalAiResult::Ready {
                job_id,
                key,
                retained_key,
                retained_epoch,
                source_size,
                image: clamp_color_image_for_gpu(result.image),
                used_upscale: result.used_upscale,
            },
            Err(err) => {
                if cancel.load(Ordering::Relaxed) {
                    FinalAiResult::Cancelled { job_id, key }
                } else {
                    FinalAiResult::Failed {
                        job_id,
                        key,
                        error: err.to_string(),
                    }
                }
            }
        }
    } else {
        // denoise だけ成功し upscale_model=None の分岐は上で return 済みなので論理的に
        // 到達しない。安全網として Failed (= 非 AI 表示へフォールバック) を返す。
        FinalAiResult::Failed {
            job_id,
            key,
            error: "no upscale model after denoise".to_string(),
        }
    }
}

/// 指定モデルがロード済みでなければロードする (worker スレッド専用)。
fn ensure_model_loaded(
    runtime: &crate::ai::runtime::AiRuntime,
    manager: &crate::ai::model_manager::ModelManager,
    kind: crate::ai::ModelKind,
) -> Result<(), String> {
    if runtime.is_loaded(kind) {
        return Ok(());
    }
    let path = manager
        .model_path(kind)
        .ok_or_else(|| format!("model path not found for {kind:?}"))?;
    runtime.load_model(kind, &path).map_err(|e| e.to_string())
}

/// egui::ColorImage → image::DynamicImage 変換ヘルパー。
/// AI 推論の入力に使う。
fn color_image_to_dynamic(ci: &egui::ColorImage) -> image::DynamicImage {
    let w = ci.size[0] as u32;
    let h = ci.size[1] as u32;
    // Color32 は premultiplied で格納されているため、unmultiply してから書き出す。
    let mut buf = image::RgbaImage::new(w, h);
    for y in 0..h {
        for x in 0..w {
            let c = ci.pixels[(y * w + x) as usize];
            buf.put_pixel(x, y, image::Rgba(c.to_srgba_unmultiplied()));
        }
    }
    image::DynamicImage::ImageRgba8(buf)
}

/// ColorImage を 1/scale に面積平均 (Triangle) 縮小する。テキスト編集中のプレビュー解像度
/// 低減 (R2 perf) 用。`scale <= 1` はそのまま clone。
pub(crate) fn downsample_color_image(ci: &egui::ColorImage, scale: u32) -> egui::ColorImage {
    if scale <= 1 {
        return ci.clone();
    }
    let [w, h] = ci.size;
    let nw = (w / scale as usize).max(1) as u32;
    let nh = (h / scale as usize).max(1) as u32;
    let dynimg = color_image_to_dynamic(ci);
    let resized = dynimg.resize_exact(nw, nh, image::imageops::FilterType::Triangle);
    dynamic_image_to_color_image(&resized)
}

/// 透明度を持つ ColorImage を単色背景に合成して RGB の DynamicImage を返す。
/// AI アップスケールの composite-first 入力作成用。完全不透明の画像なら合成は no-op になる。
pub(crate) fn color_image_to_dynamic_composited(
    ci: &egui::ColorImage,
    bg: [u8; 3],
) -> image::DynamicImage {
    let w = ci.size[0] as u32;
    let h = ci.size[1] as u32;
    let mut buf = image::RgbImage::new(w, h);
    for y in 0..h {
        for x in 0..w {
            let c = ci.pixels[(y * w + x) as usize];
            // Color32 は premultiplied 格納。 result = fg_premul + bg * (1 - a)
            let a = c.a() as u32;
            let inv = 255 - a;
            let r = ((c.r() as u32 * 255 + bg[0] as u32 * inv) / 255).min(255) as u8;
            let g = ((c.g() as u32 * 255 + bg[1] as u32 * inv) / 255).min(255) as u8;
            let b = ((c.b() as u32 * 255 + bg[2] as u32 * inv) / 255).min(255) as u8;
            buf.put_pixel(x, y, image::Rgb([r, g, b]));
        }
    }
    image::DynamicImage::ImageRgb8(buf)
}

/// 動画 open 時の resume 位置を決める (位置復元マトリクスの動画行)。
/// `from_grid` = 一覧から明示的に開いた (= `open_starts_from_beginning` で判定)、
/// それ以外 (Ctrl+↑↓ / ホイール / キー移動 / 再開) は `nav_resume` で判定。
/// 「最初から」なら `None` (= 先頭再生)、「続きから」なら保存済み位置。
fn video_resume_for_open(
    saved_resume: Option<f64>,
    from_grid: bool,
    open_starts_from_beginning: bool,
    nav_resume: crate::settings::ResumeMode,
) -> Option<f64> {
    let from_start = if from_grid {
        open_starts_from_beginning
    } else {
        matches!(nav_resume, crate::settings::ResumeMode::FromStart)
    };
    if from_start { None } else { saved_resume }
}

#[cfg(windows)]
fn native_video_presenter_config(
    owner_hwnd: u64,
    rect: windows::Win32::Foundation::RECT,
    placement: crate::video::NativeVideoPlacement,
    activate_on_show: bool,
    initially_visible: bool,
    fallback_file_name: String,
    perf_overlay_visible: bool,
    initial_tile_overlay: bool,
    vst3_available: bool,
    checked: bool,
    ui_scale: f32,
    text_contrast: crate::settings::TextContrast,
    ui_font: crate::settings::UiFontSettings,
    cursor_hide_delay_secs: f32,
    editor_hwnds_snapshot: Option<
        std::sync::Arc<std::sync::RwLock<std::collections::HashSet<u64>>>,
    >,
    main_hwnd_for_raise: u64,
    video_grade: crate::creative_lut::VideoGradeSnapshot,
    // 音声のみ native シェル (music Inc 6 ②) は true。present ループが frameless で回る
    // (§5.9 / Inc 6 ②-1)。動画経路は false。
    audio_only: bool,
) -> Option<crate::video::NativeVideoOutputConfig> {
    let in_main_window = placement.is_main_window_child();
    let sync_interval = std::env::var("MIV_NATIVE_VIDEO_SYNC_INTERVAL")
        .ok()
        .and_then(|v| v.parse::<u32>().ok())
        .unwrap_or(1)
        .min(4);
    Some(crate::video::NativeVideoOutputConfig {
        rect,
        owner_hwnd,
        fallback_file_name,
        sync_interval,
        perf_overlay_visible,
        initial_tile_overlay,
        // child / detached では VST3 GUI を対象外にする。VST editor の owner に
        // child presenter を指定すると z-order/focus が壊れるため、音声処理だけ継続する。
        vst3_available: vst3_available && placement.is_fullscreen_borderless(),
        checked,
        ui_scale: crate::settings::normalize_ui_scale_factor(ui_scale),
        text_contrast,
        ui_font,
        cursor_hide_delay_secs: crate::settings::clamp_fullscreen_cursor_hide_delay_secs(
            cursor_hide_delay_secs,
        ),
        editor_hwnds_snapshot,
        main_hwnd_for_raise,
        video_grade,
        // in-main-window / detached では topmost な HUD overlay HWND を使わず、
        // presenter の DComp tree に egui overlay を載せる。fullscreen だけ
        // 従来どおり HUD HWND を有効化 (`MIV_HUD_OVERLAY=0` で off)。
        hud_overlay_enabled: placement.is_fullscreen_borderless(),
        placement,
        activate_on_show,
        initial_visibility: if initially_visible {
            crate::video::NativeVideoInitialVisibility::Visible
        } else {
            crate::video::NativeVideoInitialVisibility::Hidden
        },
        in_main_window,
        audio_only,
    })
}

#[cfg(windows)]
fn finite_video_target_secs(target_secs: f64, duration_secs: f64) -> f64 {
    if !target_secs.is_finite() {
        return 0.0;
    }
    let upper = if duration_secs.is_finite() && duration_secs > 0.0 {
        duration_secs
    } else {
        f64::MAX
    };
    target_secs.clamp(0.0, upper)
}

